# Simple JSON Document Parser in Rust

## Project Setup

### `Cargo.toml`
```toml
[package]
name = "json_parser"
version = "0.1.0"
edition = "2021"

[dependencies]
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
```

## Source Code

### `src/main.rs`
```rust
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::fs;
use std::io::{self, Read};

// ---------- Define document structures ----------

#[derive(Debug, Serialize, Deserialize)]
struct Document {
    title: String,
    author: String,
    year: u32,
    tags: Vec<String>,
    metadata: Option<Metadata>,
}

#[derive(Debug, Serialize, Deserialize)]
struct Metadata {
    pages: u32,
    language: String,
    published: bool,
}

// ---------- Parser module ----------

/// Parses a JSON string into a strongly-typed Document
fn parse_document(json_str: &str) -> Result<Document, serde_json::Error> {
    serde_json::from_str(json_str)
}

/// Parses a JSON string into a generic serde_json::Value (untyped)
fn parse_generic(json_str: &str) -> Result<Value, serde_json::Error> {
    serde_json::from_str(json_str)
}

/// Reads a JSON file from disk and parses it into a Document
fn parse_document_from_file(path: &str) -> Result<Document, Box<dyn std::error::Error>> {
    let content = fs::read_to_string(path)?;
    let doc = serde_json::from_str(&content)?;
    Ok(doc)
}

/// Reads JSON from stdin and parses it into a Document
fn parse_document_from_stdin() -> Result<Document, Box<dyn std::error::Error>> {
    let mut buffer = String::new();
    io::stdin().read_to_string(&mut buffer)?;
    let doc = serde_json::from_str(&buffer)?;
    Ok(doc)
}

// ---------- Helper: explore generic JSON values ----------

fn explore_value(value: &Value, indent: usize) {
    let prefix = " ".repeat(indent);
    match value {
        Value::Null => println!("{prefix}null"),
        Value::Bool(b) => println!("{prefix}Bool: {b}"),
        Value::Number(n) => println!("{prefix}Number: {n}"),
        Value::String(s) => println!("{prefix}String: \"{s}\""),
        Value::Array(arr) => {
            println!("{prefix}Array[{}]:", arr.len());
            for item in arr {
                explore_value(item, indent + 2);
            }
        }
        Value::Object(map) => {
            println!("{prefix}Object {{");
            for (key, val) in map {
                println!("{prefix}  \"{key}\":");
                explore_value(val, indent + 4);
            }
            println!("{prefix}}}");
        }
    }
}

// ---------- Main ----------

fn main() {
    // --- Example 1: Parse a JSON string into a typed struct ---
    let json_input = r#"
    {
        "title": "The Rust Programming Language",
        "author": "Steve Klabnik",
        "year": 2019,
        "tags": ["rust", "programming", "systems"],
        "metadata": {
            "pages": 560,
            "language": "English",
            "published": true
        }
    }
    "#;

    println!("=== Example 1: Typed Parsing ===\n");

    match parse_document(json_input) {
        Ok(doc) => {
            println!("Title:  {}", doc.title);
            println!("Author: {}", doc.author);
            println!("Year:   {}", doc.year);
            println!("Tags:   {:?}", doc.tags);
            if let Some(meta) = &doc.metadata {
                println!("Pages:  {}", meta.pages);
                println!("Lang:   {}", meta.language);
                println!("Published: {}", meta.published);
            }
        }
        Err(e) => eprintln!("Error parsing document: {e}"),
    }

    // --- Example 2: Parse into generic Value and explore ---
    println!("\n=== Example 2: Generic (Untyped) Parsing ===\n");

    match parse_generic(json_input) {
        Ok(value) => {
            // Access fields dynamically
            if let Some(title) = value.get("title").and_then(Value::as_str) {
                println!("Title (dynamic access): {title}");
            }
            if let Some(year) = value.get("year").and_then(Value::as_u64) {
                println!("Year  (dynamic access): {year}");
            }

            println!("\nFull document tree:");
            explore_value(&value, 0);
        }
        Err(e) => eprintln!("Error parsing JSON: {e}"),
    }

    // --- Example 3: Serialize a struct back to JSON ---
    println!("\n=== Example 3: Serialize Back to JSON ===\n");

    let new_doc = Document {
        title: "Programming Rust".to_string(),
        author: "Jim Blandy".to_string(),
        year: 2021,
        tags: vec!["rust".into(), "oreilly".into()],
        metadata: None,
    };

    match serde_json::to_string_pretty(&new_doc) {
        Ok(json_out) => println!("{json_out}"),
        Err(e) => eprintln!("Serialization error: {e}"),
    }

    // --- Example 4: Handle malformed JSON gracefully ---
    println!("\n=== Example 4: Error Handling ===\n");

    let bad_json = r#"{ "title": "Missing closing brace" "#;
    match parse_document(bad_json) {
        Ok(_) => println!("Parsed successfully (unexpected)"),
        Err(e) => {
            eprintln!("Caught parse error (expected):");
            eprintln!("  Line:   {}", e.line());
            eprintln!("  Column: {}", e.column());
            eprintln!("  Msg:    {e}");
        }
    }

    // --- Example 5: Parse from file (if provided as CLI arg) ---
    let args: Vec<String> = std::env::args().collect();
    if args.len() > 1 {
        println!("\n=== Example 5: Parse from File ===\n");
        match parse_document_from_file(&args[1]) {
            Ok(doc) => println!("Parsed from file: {doc:#?}"),
            Err(e) => eprintln!("File parse error: {e}"),
        }
    }
}
```

### Sample Input File — `sample.json`
```json
{
    "title": "Rust in Action",
    "author": "Tim McNamara",
    "year": 2021,
    "tags": ["rust", "systems", "practical"],
    "metadata": {
        "pages": 456,
        "language": "English",
        "published": true
    }
}
```

## How to Run

```bash
