use std::collections::HashMap;
use std::error::Error;
use std::fmt;
use std::io::{self, BufRead, Write};

/// Represents a single record from the CSV input.
#[derive(Debug, Clone)]
struct Record {
    fields: HashMap<String, String>,
}

impl Record {
    fn new() -> Self {
        Record {
            fields: HashMap::new(),
        }
    }

    fn get(&self, key: &str) -> Option<&String> {
        self.fields.get(key)
    }

    fn set(&mut self, key: String, value: String) {
        self.fields.insert(key, value);
    }
}

impl fmt::Display for Record {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut pairs: Vec<_> = self.fields.iter().collect();
        pairs.sort_by_key(|(k, _)| k.clone());
        let formatted: Vec<String> = pairs.iter().map(|(k, v)| format!("{k}: {v}")).collect();
        write!(f, "{{{}}}", formatted.join(", "))
    }
}

/// Errors that can occur during CSV parsing.
#[derive(Debug)]
enum CsvError {
    EmptyInput,
    MismatchedColumns {
        expected: usize,
        got: usize,
        line: usize,
    },
    IoError(io::Error),
}

impl fmt::Display for CsvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CsvError::EmptyInput => write!(f, "CSV input is empty (no header row found)"),
            CsvError::MismatchedColumns {
                expected,
                got,
                line,
            } => {
                write!(
                    f,
                    "Line {line}: expected {expected} columns but found {got}"
                )
            }
            CsvError::IoError(e) => write!(f, "I/O error: {e}"),
        }
    }
}

impl Error for CsvError {}

impl From<io::Error> for CsvError {
    fn from(e: io::Error) -> Self {
        CsvError::IoError(e)
    }
}

/// Describes a transformation to apply during migration.
#[derive(Debug, Clone)]
enum Transform {
    /// Rename a column from old name to new name.
    Rename { from: String, to: String },
    /// Set a default value for a column if it's empty or missing.
    Default { column: String, value: String },
    /// Drop a column entirely.
    Drop { column: String },
    /// Add a new computed column with a static value.
    AddColumn { name: String, value: String },
    /// Convert a column's values to uppercase.
    Uppercase { column: String },
    /// Convert a column's values to lowercase.
    Lowercase { column: String },
}

impl fmt::Display for Transform {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Transform::Rename { from, to } => write!(f, "Rename '{from}' -> '{to}'"),
            Transform::Default { column, value } => {
                write!(f, "Default '{column}' = '{value}'")
            }
            Transform::Drop { column } => write!(f, "Drop '{column}'"),
            Transform::AddColumn { name, value } => {
                write!(f, "Add column '{name}' = '{value}'")
            }
            Transform::Uppercase { column } => write!(f, "Uppercase '{column}'"),
            Transform::Lowercase { column } => write!(f, "Lowercase '{column}'"),
        }
    }
}

/// Parses raw CSV text from any `BufRead` source into a vector of `Record`s.
fn parse_csv<R: BufRead>(reader: R) -> Result<(Vec<String>, Vec<Record>), CsvError> {
    let mut lines = reader.lines();

    // First line is the header row.
    let header_line = match lines.next() {
        Some(Ok(line)) => line,
        Some(Err(e)) => return Err(CsvError::IoError(e)),
        None => return Err(CsvError::EmptyInput),
    };

    let headers: Vec<String> = parse_csv_line(&header_line);

    if headers.is_empty() {
        return Err(CsvError::EmptyInput);
    }

    let mut records = Vec::new();

    for (i, line_result) in lines.enumerate() {
        let line = line_result?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue; // skip blank lines
        }

        let values = parse_csv_line(trimmed);

        if values.len() != headers.len() {
            return Err(CsvError::MismatchedColumns {
                expected: headers.len(),
                got: values.len(),
                line: i + 2, // +2 because header is line 1 and enumeration is 0-based
            });
        }

        let mut record = Record::new();
        for (header, value) in headers.iter().zip(values.iter()) {
            record.set(header.clone(), value.clone());
        }
        records.push(record);
    }

    Ok((headers, records))
}

/// Parses a single CSV line, handling quoted fields with commas and escaped quotes.
fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(ch) = chars.next() {
        match ch {
            '"' if in_quotes => {
                // Check for escaped quote ("")
                if chars.peek() == Some(&'"') {
                    current.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            }
            '"' if !in_quotes && current.is_empty() => {
                in_quotes = true;
            }
            ',' if !in_quotes => {
                fields.push(current.trim().to_string());
                current = String::new();
            }
            _ => {
                current.push(ch);
            }
        }
    }

    fields.push(current.trim().to_string());
    fields
}

/// Applies a list of transforms to parsed records and returns new headers + records.
fn apply_transforms(
    headers: &[String],
    records: &[Record],
    transforms: &[Transform],
) -> (Vec<String>, Vec<Record>) {
    let mut new_headers: Vec<String> = headers.to_vec();
    let mut new_records: Vec<Record> = records.to_vec();

    for transform in transforms {
        match transform {
            Transform::Rename { from, to } => {
                // Update headers
                for h in &mut new_headers {
                    if h == from {
                        *h = to.clone();
                    }
                }
                // Update records
                for record in &mut new_records {
                    if let Some(val) = record.fields.remove(from) {
                        record.fields.insert(to.clone(), val);
                    }
                }
            }
            Transform::Default { column, value } => {
                if !new_headers.contains(column) {
                    new_headers.push(column.clone());
                }
                for record in &mut new_records {
                    let entry = record
                        .fields
                        .entry(column.clone())
                        .or_insert_with(|| value.clone());
                    if entry.is_empty() {
                        *entry = value.clone();
                    }
                }
            }
            Transform::Drop { column } => {
                new_headers.retain(|h| h != column);
                for record in &mut new_records {
                    record.fields.remove(column);
                }
            }
            Transform::AddColumn { name, value } => {
                if !new_headers.contains(name) {
                    new_headers.push(name.clone());
                }
                for record in &mut new_records {
                    record.fields.insert(name.clone(), value.clone());
                }
            }
            Transform::Uppercase { column } => {
                for record in &mut new_records {
                    if let Some(val) = record.fields.get_mut(column) {
                        *val = val.to_uppercase();
                    }
                }
            }
            Transform::Lowercase { column } => {
                for record in &mut new_records {
                    if let Some(val) = record.fields.get_mut(column) {
                        *val = val.to_lowercase();
                    }
                }
            }
        }
    }

    (new_headers, new_records)
}

/// Writes records back out as CSV to any `Write` destination.
fn write_csv<W: Write>(
    writer: &mut W,
    headers: &[String],
    records: &[Record],
) -> Result<(), io::Error> {
    // Write header row
    writeln!(writer, "{}", headers.join(","))?;

    // Write data rows
    for record in records {
        let values: Vec<String> = headers
            .iter()
            .map(|h| {
                let val = record.fields.get(h).map(|s| s.as_str()).unwrap_or("");
                // Quote the field if it contains commas or quotes
                if val.contains(',') || val.contains('"') {
                    format!("\"{}\"", val.replace('"', "\"\""))
                } else {
                    val.to_string()
                }
            })
            .collect();
        writeln!(writer, "{}", values.join(","))?;
    }

    Ok(())
}

/// Validates records against simple rules (non-empty required fields).
fn validate_records(records: &[Record], required_fields: &[&str]) -> Vec<String> {
    let mut errors = Vec::new();

    for (i, record) in records.iter().enumerate() {
        for &field in required_fields {
            match record.get(field) {
                None => {
                    errors.push(format!("Record {}: missing required field '{field}'", i + 1));
                }
                Some(val) if val.is_empty() => {
                    errors.push(format!("Record {}: field '{field}' is empty", i + 1));
                }
                _ => {}
            }
        }
    }

    errors
}

/// Prints a summary of the migration to stdout.
fn print_migration_summary(
    original_headers: &[String],
    new_headers: &[String],
    original_count: usize,
    new_count: usize,
    transforms: &[Transform],
    validation_errors: &[String],
) {
    println!("=== Migration Summary ===");
    println!("Original columns: {}", original_headers.join(", "));
    println!("New columns:      {}", new_headers.join(", "));
    println!("Records parsed:   {original_count}");
    println!("Records output:   {new_count}");
    println!();

    if transforms.is_empty() {
        println!("No transforms applied.");
    } else {
        println!("Transforms applied:");
        for (i, t) in transforms.iter().enumerate() {
            println!("  {}. {t}", i + 1);
        }
    }
    println!();

    if validation_errors.is_empty() {
        println!("Validation: PASSED (no errors)");
    } else {
        println!("Validation: FAILED ({} error(s))", validation_errors.len());
        for err in validation_errors {
            println!("  - {err}");
        }
    }

    println!("=========================");
}

fn main() -> Result<(), Box<dyn Error>> {
    // Sample CSV data simulating a legacy system export.
    let csv_data = r#"id,name,email,department,status
1,Alice Johnson,alice@example.com,Engineering,active
2,Bob Smith,,Marketing,active
3,Carol White,carol@example.com,,inactive
4,"Dave, Jr.",dave@example.com,Engineering,active
5,Eve Brown,eve@example.com,Sales,
6,Frank "The Tank" Lee,frank@example.com,Marketing,active"#;

    println!("--- Original CSV Input ---");
    println!("{csv_data}");
    println!();

    // Parse the CSV from an in-memory string (could be stdin, file, etc.)
    let cursor = io::Cursor::new(csv_data);
    let reader = io::BufReader::new(cursor);
    let (headers, records) = parse_csv(reader)?;

    println!("--- Parsed {} record(s) ---", records.len());
    for (i, record) in records.iter().enumerate() {
        println!("  Record {}: {record}", i + 1);
    }
    println!();

    // Define migration transforms.
    let transforms = vec![
        Transform::Rename {
            from: "department".to_string(),
            to: "team".to_string(),
        },
        Transform::Default {
            column: "status".to_string(),
            value: "pending".to_string(),
        },
        Transform::Default {
            column: "team".to_string(),
            value: "Unassigned".to_string(),
        },
        Transform::AddColumn {
            name: "migrated".to_string(),
            value: "true".to_string(),
        },
        Transform::Uppercase {
            column: "status".to_string(),
        },
    ];

    // Apply all transforms.
    let (new_headers, new_records) = apply_transforms(&headers, &records, &transforms);

    println!("--- Transformed Records ---");
    for (i, record) in new_records.iter().enumerate() {
        println!("  Record {}: {record}", i + 1);
    }
    println!();

    // Validate that required fields are present and non-empty.
    let validation_errors = validate_records(&new_records, &["name", "email", "status"]);

    // Print migration summary.
    print_migration_summary(
        &headers,
        &new_headers,
        records.len(),
        new_records.len(),
        &transforms,
        &validation_errors,
    );
    println!();

    // Write the transformed CSV to stdout.
    println!("--- Output CSV ---");
    let mut output = Vec::new();
    write_csv(&mut output, &new_headers, &new_records)?;
    let output_str = String::from_utf8(output)?;
    print!("{output_str}");

    Ok(())
}

