fn tokenize(text: &str) -> Vec<String> {
    text.to_lowercase()                              // FIX #5: normalize to lowercase
        .split(|c: char| !c.is_alphanumeric())       // FIX #5: split on non-alphanum
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())                   // FIX #6: keep single-char words too
        .collect()
}

/// Extract all indexable terms from a document
fn extract_terms(doc: &Document) -> Vec<String> {
    let mut terms = tokenize(&doc.title);
    terms.extend(tokenize(&doc.body));               // FIX #9: index body terms too!
    terms.extend(doc.tags.iter().flat_map(|t| tokenize(t)));
    terms
}

/// Add a document's terms to the inverted index
fn add_to_index(index: &mut HashMap<String, HashSet<String>>, doc_id: &str, doc: &Document) {
    for term in extract_terms(doc) {
        index
            .entry(term)
            .or_insert_with(HashSet::new)            // FIX #10: HashSet deduplicates
            .insert(doc_id.to_string());
    }
}

/// Remove a document's terms from the inverted index
fn remove_from_index(index: &mut HashMap<String, HashSet<String>>, doc_id: &str, doc: &Document) {
    // FIX #16: actually clean up the inverted index on delete/update
    for term in extract_terms(doc) {
        if let Some(doc_ids) = index.get_mut(&term) {
            doc_ids.remove(doc_id);
            if doc_ids.is_empty() {
                index.remove(&term);                 // GC empty posting lists
            }
        }
    }
}

