// ─── Error Types ───────────────────────────────────────────────────────────────

#[derive(Debug)]
pub enum SyncError {
    Io(io::Error),
    MaxRetriesExceeded {
        path: PathBuf,
        attempts: u32,
        last_error: io::Error,
    },
    SourceNotFound(PathBuf),
    MetadataError {
        path: PathBuf,
        source: io::Error,
    },
}

impl fmt::Display for SyncError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SyncError::Io(e) => write!(f, "I/O error: {}", e),
            SyncError::MaxRetriesExceeded {
                path,
                attempts,
                last_error,
            } => write!(
                f,
                "Max retries ({}) exceeded for '{}': {}",
                attempts,
                path.display(),
                last_error
            ),
            SyncError::SourceNotFound(p) => {
                write!(f, "Source path not found: '{}'", p.display())
            }
            SyncError::MetadataError { path, source } => {
                write!(
                    f,
                    "Failed to read metadata for '{}': {}",
                    path.display(),
                    source
                )
            }
        }
    }
}

impl std::error::Error for SyncError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            SyncError::Io(e) => Some(e),
            SyncError::MaxRetriesExceeded { last_error, .. } => Some(last_error),
            SyncError::MetadataError { source, .. } => Some(source),
            _ => None,
        }
    }
}

impl From<io::Error> for SyncError {
    fn from(e: io::Error) -> Self {
        SyncError::Io(e)
    }
}

// ─── Retry Policy ──────────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct RetryPolicy {
    pub max_retries: u32,
    pub initial_delay: Duration,
    pub max_delay: Duration,
    pub backoff_multiplier: f64,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            max_retries: 3,
            initial_delay: Duration::from_millis(100),
            max_delay: Duration::from_secs(10),
            backoff_multiplier: 2.0,
        }
    }
}

impl RetryPolicy {
    pub fn delay_for_attempt(&self, attempt: u32) -> Duration {
        let delay_ms = self.initial_delay.as_millis() as f64
            * self.backoff_multiplier.powi(attempt as i32);
        let capped = Duration::from_millis(delay_ms as u64).min(self.max_delay);
        capped
    }
}

// ─── Sync Configuration ────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct SyncConfig {
    pub retry_policy: RetryPolicy,
    pub delete_orphaned: bool,
    pub dry_run: bool,
    pub copy_buffer_size: usize,
}

impl Default for SyncConfig {
    fn default() -> Self {
        Self {
            retry_policy: RetryPolicy::default(),
            delete_orphaned: false,
            dry_run: false,
            copy_buffer_size: 64 * 1024, // 64 KB
        }
    }
}

