// ─── File Entry Metadata ───────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct FileEntry {
    relative_path: PathBuf,
    size: u64,
    modified: SystemTime,
    is_dir: bool,
}

// ─── File Synchronizer ────────────────────────────────────────────────────────

pub struct FileSynchronizer {
    source: PathBuf,
    destination: PathBuf,
    config: SyncConfig,
}

impl FileSynchronizer {
    pub fn new<P: Into<PathBuf>>(source: P, destination: P, config: SyncConfig) -> Self {
        Self {
            source: source.into(),
            destination: destination.into(),
            config,
        }
    }

    /// Run the full synchronization process.
    pub fn sync(&self) -> Result<SyncStats, SyncError> {
        if !self.source.exists() {
            return Err(SyncError::SourceNotFound(self.source.clone()));
        }

        let mut stats = SyncStats::default();

        // 1. Scan source tree
        let source_entries = self.scan_directory(&self.source)?;
        let source_map: HashMap<PathBuf, &FileEntry> = source_entries
            .iter()
            .map(|e| (e.relative_path.clone(), e))
            .collect();

        // 2. Scan destination tree (if it exists)
        let dest_entries = if self.destination.exists() {
            self.scan_directory(&self.destination)?
        } else {
            Vec::new()
        };
        let dest_map: HashMap<PathBuf, &FileEntry> = dest_entries
            .iter()
            .map(|e| (e.relative_path.clone(), e))
            .collect();

        // 3. Create directories and copy/update files
        // Sort so directories are created before their contents
        let mut sorted_entries: Vec<&FileEntry> = source_entries.iter().collect();
        sorted_entries.sort_by(|a, b| a.relative_path.cmp(&b.relative_path));

        for entry in &sorted_entries {
            let dest_path = self.destination.join(&entry.relative_path);

            if entry.is_dir {
                if !dest_path.exists() {
                    if self.config.dry_run {
                        println!("[DRY RUN] Would create dir: {}", dest_path.display());
                    } else {
                        self.retry_operation(
                            &format!("create_dir: {}", dest_path.display()),
                            &mut stats,
                            || fs::create_dir_all(&dest_path),
                        )?;
                    }
                    stats.dirs_created += 1;
                }
            } else {
                let needs_copy = match dest_map.get(&entry.relative_path) {
                    Some(dest_entry) => self.file_needs_update(entry, dest_entry),
                    None => true,
                };

                if needs_copy {
                    let src_path = self.source.join(&entry.relative_path);

                    if self.config.dry_run {
                        println!(
                            "[DRY RUN] Would copy: {} -> {}",
                            src_path.display(),
                            dest_path.display()
                        );
                    } else {
                        // Ensure parent directory exists
                        if let Some(parent) = dest_path.parent() {
                            if !parent.exists() {
                                fs::create_dir_all(parent)?;
                            }
                        }

                        let bytes = self.copy_file_with_retry(
                            &src_path,
                            &dest_path,
                            &mut stats,
                        )?;
                        stats.bytes_copied += bytes;
                    }
                    stats.files_copied += 1;
                } else {
                    stats.files_skipped += 1;
                }
            }
        }

        // 4. Optionally delete orphaned files/directories in destination
        if self.config.delete_orphaned {
            // Delete orphaned files first, then directories (reverse sorted)
            let mut orphaned_files = Vec::new();
            let mut orphaned_dirs = Vec::new();

            for dest_entry in &dest_entries {
                if !source_map.contains_key(&dest_entry.relative_path) {
                    if dest_entry.is_dir {
                        orphaned_dirs.push(&dest_entry.relative_path);
                    } else {
                        orphaned_files.push(&dest_entry.relative_path);
                    }
                }
            }

            for rel_path in &orphaned_files {
                let full_path = self.destination.join(rel_path);
                if self.config.dry_run {
                    println!("[DRY RUN] Would delete file: {}", full_path.display());
                } else {
                    self.retry_operation(
                        &format!("delete_file: {}", full_path.display()),
                        &mut stats,
                        || fs::remove_file(&full_path),
                    )?;
                }
                stats.files_deleted += 1;
            }

            // Sort directories in reverse order so children are removed first
            orphaned_dirs.sort();
            orphaned_dirs.reverse();

            for rel_path in &orphaned_dirs {
                let full_path = self.destination.join(rel_path);
                if full_path.exists() {
                    if self.config.dry_run {
                        println!("[DRY RUN] Would delete dir: {}", full_path.display());
                    } else {
                        self.retry_operation(
                            &format!("delete_dir: {}", full_path.display()),
                            &mut stats,
                            || fs::remove_dir(&full_path),
                        )?;
                    }
                    stats.dirs_deleted += 1;
                }
            }
        }

        Ok(stats)
    }

    /// Scan a directory tree and collect all file entries with relative paths.
    fn scan_directory(&self, base: &Path) -> Result<Vec<FileEntry>, SyncError> {
        let mut entries = Vec::new();
        self.scan_directory_recursive(base, base, &mut entries)?;
        Ok(entries)
    }

    fn scan_directory_recursive(
        &self,
        base: &Path,
        current: &Path,
        entries: &mut Vec<FileEntry>,
    ) -> Result<(), SyncError> {
        let dir_entries = fs::read_dir(current).map_err(|e| SyncError::MetadataError {
            path: current.to_path_buf(),
            source: e,
        })?;

        for entry in dir_entries {
            let entry = entry?;
            let path = entry.path();
            let metadata =
                entry
                    .metadata()
                    .map_err(|e| SyncError::MetadataError {
                        path: path.clone(),
                        source: e,
                    })?;

            let relative = path
                .strip_prefix(base)
                .unwrap_or(&path)
                .to_path_buf();

            let modified = metadata
                .modified()
                .unwrap_or(SystemTime::UNIX_EPOCH);

            entries.push(FileEntry {
                relative_path: relative,
                size: metadata.len(),
                modified,
                is_dir: metadata.is_dir(),
            });

            if metadata.is_dir() {
                self.scan_directory_recursive(base, &path, entries)?;
            }
        }

        Ok(())
    }

    /// Determine if a source file is newer or different size than destination.
    fn file_needs_update(&self, src: &FileEntry, dest: &FileEntry) -> bool {
        if src.size != dest.size {
            return true;
        }
        // Compare modification times with 1-second tolerance
        match (
            src.modified.duration_since(SystemTime::UNIX_EPOCH),
            dest.modified.duration_since(SystemTime::UNIX_EPOCH),
        ) {
            (Ok(src_dur), Ok(dest_dur)) => {
                let diff = if src_dur > dest_dur {
                    src_dur - dest_dur
                } else {
                    dest_dur - src_dur
                };
                diff > Duration::from_secs(1) && src_dur > dest_dur
            }
            _ => true, // If we can't compare, copy to be safe
        }
    }

    /// Copy a single file with atomic write (write to temp, then rename).
    fn copy_file_with_retry(
        &self,
        src: &Path,
        dest: &Path,
        stats: &mut SyncStats,
    ) -> Result<u64, SyncError> {
        let temp_dest = dest.with_extension("tmp.sync");

        // Retry the copy operation
        self.retry_operation(
            &format!(
                "copy: {} -> {}",
                src.display(),
                dest.display()
            ),
            stats,
            || {
                // Copy to temp file first for atomicity
                fs::copy(src, &temp_dest)?;

                // Rename temp to final destination
                fs::rename(&temp_dest, dest)?;

                Ok(())
            },
        )?;

        // Clean up temp file in case of partial failure
        if temp_dest.exists() {
            let _ = fs::remove_file(&temp_dest);
        }

        // Return the size of the copied file
        let size = fs::metadata(dest)
            .map(|m| m.len())
            .unwrap_or(0);

        Ok(size)
    }

    /// Generic retry wrapper with exponential backoff.
    fn retry_operation<F>(
        &self,
        operation_name: &str,
        stats: &mut SyncStats,
        mut operation: F,
    ) -> Result<(), SyncError>
    where
        F: FnMut() -> io::Result<()>,
    {
        let policy = &self.config.retry_policy;
        let mut last_error: Option<io::Error> = None;

        for attempt in 0..=policy.max_retries {
            match operation() {
                Ok(()) => return Ok(()),
                Err(e) => {
                    let is_retryable = matches!(
                        e.kind(),
                        io::ErrorKind::TimedOut
                            | io::ErrorKind::Interrupted
                            | io::ErrorKind::WouldBlock
                            | io::ErrorKind::PermissionDenied
                            | io::ErrorKind::Other
                    );

                    if attempt < policy.max_retries && is_retryable {
                        let delay = policy.delay_for_attempt(attempt);
                        eprintln!(
                            "[RETRY {}/{}] {}: {} (waiting {:?})",
                            attempt + 1,
                            policy.max_retries,
                            operation_name,
                            e,
                            delay
                        );
                        stats.retries_performed += 1;
                        thread::sleep(delay);
                        last_error = Some(e);
                    } else {
                        last_error = Some(e);
                        break;
                    }
                }
            }
        }

        let err = last_error.unwrap_or_else(|| {
            io::Error::new(io::ErrorKind::Other, "Unknown error during retry")
        });

        Err(SyncError::MaxRetriesExceeded {
            path: PathBuf::from(operation_name),
            attempts: policy.max_retries,
            last_error: err,
        })
    }
}

