                            println!("  [⏰] Task {} '{}' missed deadline", t.id, t.name);
                            t.status = TaskStatus::DeadlineMissed;
                            failed.lock().unwrap().push(t);
                            continue;
                        }

                        // Track active count
                        active_count.fetch_add(1, AtomicOrdering::SeqCst);

                        let result_status = Self::execute_task(&mut t);

                        active_count.fetch_sub(1, AtomicOrdering::SeqCst);

