                                state.condvar.notify_one();
                            }
                            TaskStatus::Failed => {
                                failed.lock().unwrap().push(t);
                            }
                            _ => {}
                        }
                    }
                }

                println!("  Worker {} stopped", worker_id);
            });

            handles.push(handle);
