        let pending = self.state.tasks.lock().unwrap().len();
        let completed = self.completed.lock().unwrap().len();
        let failed = self.failed.lock().unwrap().len();
        let active = self.active_count.load(AtomicOrdering::SeqCst);

        SchedulerStats {
            pending,
            completed,
            failed,
            active,
