use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::thread;
use std::time::{Duration, SystemTime};

// ─── Configuration ───────────────────────────────────────────────

const MAX_RETRIES: u32 = 3;
const BASE_DELAY_MS: u64 = 500;

// ─── Error Types ─────────────────────────────────────────────────

#[derive(Debug)]
enum SyncError {
    Io(io::Error),
    MaxRetriesExceeded {
        path: PathBuf,
        attempts: u32,
        last_error: io::Error,
    },
}

impl std::fmt::Display for SyncError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SyncError::Io(e) => write!(f, "IO error: {e}"),
            SyncError::MaxRetriesExceeded {
                path,
                attempts,
                last_error,
            } => {
                write!(
                    f,
                    "Failed after {attempts} attempts for '{}': {last_error}",
                    path.display()
                )
            }
        }
    }
}

impl From<io::Error> for SyncError {
    fn from(e: io::Error) -> Self {
        SyncError::Io(e)
    }
}

// ─── Retry Logic ─────────────────────────────────────────────────

/// Executes a closure with exponential backoff retries.
fn retry_with_backoff<F, T>(
    max_retries: u32,
    base_delay_ms: u64,
    context_path: &Path,
    mut operation: F,
) -> Result<T, SyncError>
where
    F: FnMut() -> Result<T, io::Error>,
{
    let mut last_error = None;

    for attempt in 1..=max_retries {
        match operation() {
            Ok(value) => return Ok(value),
            Err(e) => {
                println!(
                    "  ⚠ Attempt {attempt}/{max_retries} failed for '{}': {e}",
                    context_path.display()
                );
                last_error = Some(e);

                if attempt < max_retries {
                    let delay = base_delay_ms * 2u64.pow(attempt - 1);
                    println!("    Retrying in {delay}ms...");
                    thread::sleep(Duration::from_millis(delay));
                }
            }
        }
    }

    Err(SyncError::MaxRetriesExceeded {
        path: context_path.to_path_buf(),
        attempts: max_retries,
        last_error: last_error.unwrap(),
    })
}

// ─── Sync Report ─────────────────────────────────────────────────

#[derive(Debug, Default)]
struct SyncReport {
    files_copied: u32,
    files_skipped: u32,
    files_failed: u32,
    dirs_created: u32,
    errors: Vec<SyncError>,
}

impl SyncReport {
    fn print_summary(&self) {
        println!("\n{'=':.>50}");
        println!("  Sync Summary");
        println!("{'=':.>50}");
        println!("  Copied:  {}", self.files_copied);
        println!("  Skipped: {}", self.files_skipped);
        println!("  Failed:  {}", self.files_failed);
        println!("  Dirs:    {}", self.dirs_created);

        if !self.errors.is_empty() {
            println!("\n  Errors:");
            for err in &self.errors {
                println!("    • {err}");
            }
        }
        println!();
    }
}

// ─── Core Sync Logic ─────────────────────────────────────────────

/// Checks whether the source file is newer or different size than destination.
fn needs_sync(src: &Path, dst: &Path) -> io::Result<bool> {
    if !dst.exists() {
        return Ok(true);
    }

    let src_meta = fs::metadata(src)?;
    let dst_meta = fs::metadata(dst)?;

    // Different size → needs sync
    if src_meta.len() != dst_meta.len() {
        return Ok(true);
    }

    // Source is newer → needs sync
    let src_modified = src_meta.modified().unwrap_or(SystemTime::UNIX_EPOCH);
    let dst_modified = dst_meta.modified().unwrap_or(SystemTime::UNIX_EPOCH);

    Ok(src_modified > dst_modified)
}

/// Copies a single file with retry logic.
fn sync_file(src: &Path, dst: &Path) -> Result<bool, SyncError> {
    // Check if sync is needed (no retry needed for read-only check)
    match needs_sync(src, dst) {
        Ok(false) => return Ok(false), // skipped
        Ok(true) => {}
        Err(e) => return Err(SyncError::Io(e)),
    }

    // Copy with retries
    retry_with_backoff(MAX_RETRIES, BASE_DELAY_MS, src, || {
        fs::copy(src, dst)?;
        Ok(())
    })?;

    Ok(true) // copied
}

/// Recursively synchronizes a source directory to a destination.
fn sync_directory(src: &Path, dst: &Path, report: &mut SyncReport) -> Result<(), SyncError> {
    // Create destination directory with retries
    if !dst.exists() {
        retry_with_backoff(MAX_RETRIES, BASE_DELAY_MS, dst, || {
            fs::create_dir_all(dst)?;
            Ok(())
        })?;
        report.dirs_created += 1;
        println!("  📁 Created dir: {}", dst.display());
    }

    // Read source directory entries
    let entries = fs::read_dir(src)?;

    for entry_result in entries {
        let entry = entry_result?;
        let file_type = entry.file_type()?;
        let src_path = entry.path();
        let dst_path = dst.join(entry.file_name());

        if file_type.is_dir() {
            // Recurse into subdirectory
            sync_directory(&src_path, &dst_path, report)?;
        } else if file_type.is_file() {
            match sync_file(&src_path, &dst_path) {
                Ok(true) => {
                    println!("  ✅ Copied: {}", src_path.display());
                    report.files_copied += 1;
                }
                Ok(false) => {
                    println!("  ⏭ Skipped (up to date): {}", src_path.display());
                    report.files_skipped += 1;
                }
                Err(e) => {
                    println!("  ❌ Failed: {}", src_path.display());
                    report.files_failed += 1;
                    report.errors.push(e);
                }
            }
        }
        // Symlinks and other types are ignored for simplicity
    }

    Ok(())
}

