# Background Worker for Cache Invalidation in Rust

This example demonstrates a production-style cache with a background worker that handles TTL expiration, manual invalidation, and pattern-based eviction.

```rust
use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::{mpsc, RwLock, Notify};
use tokio::time;

// ── Cache Entry ──────────────────────────────────────────────────────

#[derive(Clone, Debug)]
struct CacheEntry {
    value: String,
    created_at: Instant,
    ttl: Duration,
    access_count: u64,
}

impl CacheEntry {
    fn new(value: String, ttl: Duration) -> Self {
        Self {
            value,
            created_at: Instant::now(),
            ttl,
            access_count: 0,
        }
    }

    fn is_expired(&self) -> bool {
        self.created_at.elapsed() >= self.ttl
    }

    fn remaining_ttl(&self) -> Duration {
        self.ttl.saturating_sub(self.created_at.elapsed())
    }
}

// ── Invalidation Commands ────────────────────────────────────────────

#[derive(Debug)]
enum InvalidationCommand {
    /// Remove a specific key
    InvalidateKey(String),
    /// Remove all keys matching a prefix
    InvalidatePrefix(String),
    /// Remove all keys matching a tag
    InvalidateTag(String),
    /// Purge every entry
    PurgeAll,
    /// Shut down the background worker
    Shutdown,
}

// ── Cache Statistics ─────────────────────────────────────────────────

#[derive(Debug, Default, Clone)]
struct CacheStats {
    hits: u64,
    misses: u64,
    evictions: u64,
    expired_removals: u64,
    manual_invalidations: u64,
    total_entries: usize,
}

impl std::fmt::Display for CacheStats {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let hit_rate = if self.hits + self.misses > 0 {
            (self.hits as f64 / (self.hits + self.misses) as f64) * 100.0
        } else {
            0.0
        };
        write!(
            f,
            "entries={} hits={} misses={} hit_rate={:.1}% evictions={} \
             expired={} manual={}",
            self.total_entries,
            self.hits,
            self.misses,
            hit_rate,
            self.evictions,
            self.expired_removals,
            self.manual_invalidations,
        )
    }
}

// ── Core Cache ───────────────────────────────────────────────────────

struct CacheInner {
    entries: HashMap<String, CacheEntry>,
    tags: HashMap<String, Vec<String>>, // tag → [keys]
    stats: CacheStats,
    max_capacity: usize,
}

impl CacheInner {
    fn new(max_capacity: usize) -> Self {
        Self {
            entries: HashMap::new(),
            tags: HashMap::new(),
            stats: CacheStats::default(),
            max_capacity,
        }
    }

    /// Evict the oldest entries when over capacity.
    fn evict_if_needed(&mut self) {
        while self.entries.len() >= self.max_capacity {
            // LRU-style: remove the entry with the fewest accesses
            if let Some(key) = self
                .entries
                .iter()
                .min_by_key(|(_, e)| e.access_count)
                .map(|(k, _)| k.clone())
            {
                self.entries.remove(&key);
                self.remove_key_from_tags(&key);
                self.stats.evictions += 1;
                println!("[cache] evicted key={key:?} (capacity)");
            } else {
                break;
            }
        }
    }

    fn remove_key_from_tags(&mut self, key: &str) {
        self.tags.retain(|_tag, keys| {
            keys.retain(|k| k != key);
            !keys.is_empty()
        });
    }

    /// Remove every expired entry, returning the count removed.
    fn sweep_expired(&mut self) -> usize {
        let expired_keys: Vec<String> = self
            .entries
            .iter()
            .filter(|(_, entry)| entry.is_expired())
            .map(|(key, _)| key.clone())
            .collect();

        let count = expired_keys.len();
        for key in &expired_keys {
            self.entries.remove(key);
            self.remove_key_from_tags(key);
        }
        self.stats.expired_removals += count as u64;
        self.stats.total_entries = self.entries.len();
        count
    }
}

// ── Public Cache Handle ──────────────────────────────────────────────

#[derive(Clone)]
struct Cache {
    inner: Arc<RwLock<CacheInner>>,
    cmd_tx: mpsc::Sender<InvalidationCommand>,
    shutdown: Arc<Notify>,
}

impl Cache {
    /// Spawn a new cache with its background worker.
    fn new(
        max_capacity: usize,
        sweep_interval: Duration,
    ) -> (Self, tokio::task::JoinHandle<()>) {
        let inner = Arc::new(RwLock::new(CacheInner::new(max_capacity)));
        let (cmd_tx, cmd_rx) = mpsc::channel::<InvalidationCommand>(256);
        let shutdown = Arc::new(Notify::new());

        let worker_handle = {
            let inner = Arc::clone(&inner);
            let shutdown = Arc::clone(&shutdown);
            tokio::spawn(background_worker(
                inner,
                cmd_rx,
                sweep_interval,
                shutdown,
            ))
        };

        let cache = Self {
            inner,
            cmd_tx,
            shutdown,
        };
        (cache, worker_handle)
    }

    // ── Read / Write ────────────────────────────────────────────

    async fn get(&self, key: &str) -> Option<String> {
        let mut inner = self.inner.write().await;
        if let Some(entry) = inner.entries.get_mut(key) {
            if entry.is_expired() {
                inner.entries.remove(key);
                inner.remove_key_from_tags(key);
                inner.stats.expired_removals += 1;
                inner.stats.misses += 1;
                inner.stats.total_entries = inner.entries.len();
                None
            } else {
                entry.access_count += 1;
                inner.stats.hits += 1;
                Some(entry.value.clone())
            }
        } else {
            inner.stats.misses += 1;
            None
        }
    }

    async fn set(
        &self,
        key: impl Into<String>,
        value: impl Into<String>,
        ttl: Duration,
        tags: Vec<String>,
    ) {
        let key = key.into();
        let mut inner = self.inner.write().await;
        inner.evict_if_needed();
        inner
            .entries
            .insert(key.clone(), CacheEntry::new(value.into(), ttl));

        for tag in tags {
            inner.tags.entry(tag).or_default().push(key.clone());
        }
        inner.stats.total_entries = inner.entries.len();
    }

    // ── Invalidation helpers (send commands to the worker) ──────

    async fn invalidate_key(&self, key: impl Into<String>) {
        let _ = self
            .cmd_tx
            .send(InvalidationCommand::InvalidateKey(key.into()))
            .await;
    }

    async fn invalidate_prefix(&self, prefix: impl Into<String>) {
        let _ = self
            .cmd_tx
            .send(InvalidationCommand::InvalidatePrefix(prefix.into()))
            .await;
    }

    async fn invalidate_tag(&self, tag: impl Into<String>) {
        let _ = self
            .cmd_tx
            .send(InvalidationCommand::InvalidateTag(tag.into()))
            .await;
    }

    async fn purge_all(&self) {
        let _ = self.cmd_tx.send(InvalidationCommand::PurgeAll).await;
    }

    async fn shutdown(&self) {
        let _ = self.cmd_tx.send(InvalidationCommand::Shutdown).await;
        self.shutdown.notify_one();
    }

    async fn stats(&self) -> CacheStats {
        let inner = self.inner.read().await;
        inner.stats.clone()
    }
}

// ── Background Worker ────────────────────────────────────────────────

async fn background_worker(
    inner: Arc<RwLock<CacheInner>>,
    mut cmd_rx: mpsc::Receiver<InvalidationCommand>,
    sweep_interval: Duration,
    shutdown: Arc<Notify>,
) {
    println!("[worker] started  sweep_interval={sweep_interval:?}");
    let mut sweep_ticker = time::interval(sweep_interval);

    loop {
        tokio::select! {
            // ── Periodic TTL sweep ──────────────────────────────
            _ = sweep_ticker.tick() => {
                let removed = {
                    let mut cache = inner.write().await;
                    cache.sweep_expired()
                };
                if removed > 0 {
                    println!("[worker] sweep removed {removed} expired entries");
                }
            }

            // ── On-demand invalidation commands ─────────────────
            Some(cmd) = cmd_rx.recv() => {
                match cmd {
                    InvalidationCommand::InvalidateKey(key) => {
                        let mut cache = inner.write().await;
                        if cache.entries.remove(&key).is_some() {
                            cache.remove_key_from_tags(&key);
                            cache.stats.manual_invalidations += 1;
                            cache.stats.total_entries = cache.entries.len();
                            println!("[worker] invalidated key={key:?}");
                        }
                    }

                    InvalidationCommand::InvalidatePrefix(prefix) => {
                        let mut cache = inner.write().await;
                        let keys: Vec<String> = cache
                            .entries
                            .keys()
                            .filter(|k| k.starts_with(&prefix))
                            .cloned()
                            .collect();
                        let count = keys.len();
                        for key in &keys {
                            cache.entries.remove(key);
                            cache.remove_key_from_tags(key);
                        }
                        cache.stats.manual_invalidations += count as u64;
                        cache.stats.total_entries = cache.entries.len();
                        println!(
                            "[worker] invalidated {count} keys with \
                             prefix={prefix:?}"
                        );
                    }

                    InvalidationCommand::InvalidateTag(tag) => {
                        let mut cache = inner.write().await;
                        if let Some(keys) = cache.tags.remove(&tag) {
                            let count = keys.len();
                            for key in &keys {
                                cache.entries.remove(key);
                            }
                            cache.stats.manual_invalidations += count as u64;
                            cache.stats.total_entries = cache.entries.len();
                            println!(
                                "[worker] invalidated {count} keys with \
                                 tag={tag:?}"
                            );
                        }
                    }

                    InvalidationCommand::PurgeAll => {
                        let mut cache = inner.write().await;
                        let count = cache.entries.len();
                        cache.entries.clear();
                        cache.tags.clear();
                        cache.stats.manual_invalidations += count as u64;
                        cache.stats.total_entries = 0;
                        println!("[worker] purged all {count} entries");
                    }

                    InvalidationCommand::Shutdown => {
                        println!("[worker] shutting down");
                        break;
                    }
                }
            }

            // ── External shutdown signal ────────────────────────
            _ = shutdown.notified() => {
                println!("[worker] received shutdown notification");
                break;
            }
        }
    }

    // Final sweep before exiting
    let mut cache = inner.write().await;
    let removed = cache.sweep_expired();
    println!(
        "[worker] final sweep removed {removed} entries – goodbye"
    );
}

// ── Demo ─────────────────────────────────────────────────────────────

#[tokio::main]
async fn main() {
    println!("=== Cache Invalidation Worker Demo ===\n");

    // Create cache: 100 entries max, sweep every 2 s
    let (cache, worker) = Cache::new(100, Duration::from_secs(2));

    // ── Populate ────────────────────────────────────────────────
    cache
        .set(
            "user:1:profile",
            r#"{"name":"Alice"}"#,
            Duration::from_secs(10),
            vec!["user:1".into(), "profiles".into()],
        )
        .await;

    cache
        .set(
            "user:2:profile",
            r#"{"name":"Bob"}"#,
            Duration::from_secs(10),
            vec!["user:2".into(), "profiles".into()],
        )
        .await;

    cache
        .set(
            "user:1:settings",
            r#"{"theme":"dark"}"#,
            Duration::from_secs(10),
            vec!["user:1".into(), "settings".into()],
        )
        .await;

    // Short-lived entry that will expire quickly
    cache
        .set(
            "session:abc123",
            "session-data",
            Duration::from_secs(3),
            vec!["sessions".into()],
        )
        .await;

    cache
        .set(
            "product:42",
            r#"{"name":"Widget"}"#,
            Duration::from_secs(10),
            vec!["products".into()],
        )
        .await;

    println!("Populated 5 entries\n");

    // ── Read ────────────────────────────────────────────────────
    if let Some(val) = cache.get("user:1:profile").await {
        println!("GET user:1:profile → {val}");
    }
    let _ = cache.get("nonexistent").await; // miss
    println!("Stats: {}\n", cache.stats().await);

    // ── Invalidate a single key ─────────────────────────────────
    println!("-- invalidate key 'product:42' --");
    cache.invalidate_key("product:42").await;
    time::sleep(Duration::from_millis(50)).await;
    assert!(cache.get("product:42").await.is_none());
    println!("GET product:42 → None (invalidated)\n");

    // ── Invalidate by prefix ────────────────────────────────────
    println!("-- invalidate prefix 'user:1' --");
    cache.invalidate_prefix("user:1").await;
    time::sleep(Duration::from_millis(50)).await;
    assert!(cache.get("user:1:profile").await.is_none());
    assert!(cache.get("user:1:settings").await.is_none());
    println!("All user:1:* keys removed\n");

    // ── Wait for the short-TTL entry to expire via sweep ────────
    println!("-- waiting 4 s for session TTL to expire --");
    time::sleep(Duration::from_secs(4)).await;
    assert!(cache.get("session:abc123").await.is_none());
    println!("GET session:abc123 → None (expired)\n");

    // ── Invalidate by tag ───────────────────────────────────────
    // Re-add some entries to demonstrate tag invalidation
    cache
        .set(
            "user:3:profile",
            r#"{"name":"Charlie"}"#,
            Duration::from_secs(60),
            vec!["user:3".into(), "profiles".into()],
        )
        .await;
    cache
        .set(
            "user:4:profile",
            r#"{"name":"Diana"}"#,
            Duration::from_secs(60),
            vec!["user:4".into(), "profiles".into()],
        )
        .await;

    println!("-- invalidate tag 'profiles' --");
    cache.invalidate_tag("profiles").await;
    time::sleep(Duration::from_millis(50)).await;
    assert!(cache.get("user:3:profile").await.is_none());
    assert!(cache.get("user:4:profile").await.is_none());
    println!("All 'profiles'-tagged keys removed\n");

    // ── Final stats & shutdown ──────────────────────────────────
    println!("Final stats: {}\n", cache.stats().await);

    cache.shutdown().await;
    let _ = worker.await;

    println!("\nDone.");
}
```

