use serde::{Deserialize, Serialize};
use std::sync::Mutex;
use chrono::Utc;
use uuid::Uuid;
use log::{info, warn, error};

// ── Models ─────────────────────────────────────────────────────────

/// FIX 1: All fields derive correctly; `pub` isn't needed for serde
/// within the same crate—but Clone/Debug are essential.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct AuditLogEntry {
    pub id: String,
    pub timestamp: String,
    pub user_id: String,
    pub action: String,
    pub resource: String,
    pub details: String,
