    pub status_code: u16,
}

#[derive(Deserialize, Debug)]
pub struct CreateAuditLog {
    pub user_id: String,
    pub action: String,
    pub resource: String,
    pub details: Option<String>, // Made optional for flexibility
}

#[derive(Deserialize, Debug)]
pub struct QueryParams {
    pub user_id: Option<String>,
    pub action: Option<String>,
    pub limit: Option<usize>,
    pub offset: Option<usize>,  // Added pagination support
}

// FIX 2: Wrap the collection in a Mutex for interior mutability
pub struct AppState {
    pub logs: Mutex<Vec<AuditLogEntry>>,
}

// ── Validation ─────────────────────────────────────────────────────

/// FIX 5: Dedicated input validation
#[derive(Debug, Serialize)]
pub struct ApiError {
    pub error: String,
    pub details: Vec<String>,
}

fn validate_create_request(body: &CreateAuditLog) -> Result<(), Vec<String>> {
    let mut errors = Vec::new();

    if body.user_id.trim().is_empty() {
        errors.push("user_id cannot be empty".to_string());
    }
    if body.user_id.len() > 128 {
        errors.push("user_id exceeds 128 characters".to_string());
    }

    let valid_actions = ["CREATE", "READ", "UPDATE", "DELETE", "LOGIN", "LOGOUT"];
    if !valid_actions.contains(&body.action.to_uppercase().as_str()) {
        errors.push(format!(
            "action must be one of: {}",
            valid_actions.join(", ")
        ));
    }

    if body.resource.trim().is_empty() {
        errors.push("resource cannot be empty".to_string());
    }

    if errors.is_empty() {
        Ok(())
    } else {
        Err(errors)
    }
}

// ── Handlers ───────────────────────────────────────────────────────

/// FIX 3: `async` keyword added
/// FIX 4: AppState wrapped in Mutex via web::Data<AppState>
/// FIX 6: Proper timestamp with chrono::Utc
/// FIX 7: `.clone()` on borrowed fields from `body`
/// FIX 8: Safe extraction of peer address
/// FIX 10: Return `201 Created` on successful creation
async fn create_audit_log(
    body: web::Json<CreateAuditLog>,
    data: web::Data<AppState>,
    req: HttpRequest,
) -> HttpResponse {
    // FIX 5: Validate input before processing
    if let Err(details) = validate_create_request(&body) {
        warn!("Validation failed for audit log creation: {:?}", details);
        return HttpResponse::BadRequest().json(ApiError {
            error: "Validation failed".to_string(),
            details,
        });
    }

    // FIX 8: Safely extract the IP address
    let ip_address = req
        .peer_addr()
        .map(|addr| addr.ip().to_string())
        .or_else(|| {
            req.headers()
                .get("X-Forwarded-For")
                .and_then(|v| v.to_str().ok())
                .map(|s| s.split(',').next().unwrap_or("unknown").trim().to_string())
        })
        .unwrap_or_else(|| "unknown".to_string());

    let entry = AuditLogEntry {
        id: Uuid::new_v4().to_string(),
        timestamp: Utc::now().to_rfc3339(),   // FIX 6: real timestamp
        user_id: body.user_id.clone(),          // FIX 7: clone from ref
        action: body.action.to_uppercase(),
        resource: body.resource.clone(),
        details: body.details.clone().unwrap_or_default(),
        ip_address,
        status_code: 201,
    };

    // FIX 9: Lock the Mutex to get mutable access
    match data.logs.lock() {
        Ok(mut logs) => {
            info!("Audit log created: {} by {}", entry.id, entry.user_id);
            logs.push(entry.clone());

            // FIX 10: 201 Created with Location header
            HttpResponse::Created()
                .insert_header(("Location", format!("/audit/{}", entry.id)))
                .json(entry)
        }
        Err(poisoned) => {
            error!("Mutex poisoned: {}", poisoned);
            // Recover from poisoned mutex
            let mut logs = poisoned.into_inner();
            logs.push(entry.clone());
            HttpResponse::Created().json(entry)
        }
    }
}

/// FIX 11: Acquire Mutex lock before reading
/// FIX 12: Correct AND-based filter logic
/// FIX 13: Default limit is 100, not 0
async fn get_audit_logs(
    query: web::Query<QueryParams>,
    data: web::Data<AppState>,
) -> HttpResponse {
    let logs = match data.logs.lock() {
        Ok(logs) => logs,
        Err(poisoned) => {
            error!("Mutex poisoned on read: {}", poisoned);
            poisoned.into_inner()
        }
    };

    // FIX 12: Apply ALL filters with AND logic
    let filtered: Vec<&AuditLogEntry> = logs
        .iter()
        .filter(|log| {
            let user_match = query
                .user_id
                .as_ref()
                .map_or(true, |uid| log.user_id == *uid);

            let action_match = query
                .action
                .as_ref()
                .map_or(true, |act| log.action.eq_ignore_ascii_case(act));

            user_match && action_match  // AND logic, not early return
        })
        .skip(query.offset.unwrap_or(0))             // Pagination offset
        .take(query.limit.unwrap_or(100).min(1000))   // FIX 13: sane default + cap
        .collect();

    // Return metadata alongside results
    #[derive(Serialize)]
    struct PaginatedResponse<'a> {
        total_hint: usize,
        count: usize,
        offset: usize,
        data: Vec<&'a AuditLogEntry>,
    }

    let response = PaginatedResponse {
        total_hint: logs.len(),
        count: filtered.len(),
        offset: query.offset.unwrap_or(0),
        data: filtered,
    };

    HttpResponse::Ok().json(response)
}

/// FIX 14: Search by the actual `id`, not just `.first()`
async fn get_audit_log_by_id(
    path: web::Path<String>,
    data: web::Data<AppState>,
) -> HttpResponse {
    let id = path.into_inner();

    let logs = match data.logs.lock() {
        Ok(logs) => logs,
        Err(poisoned) => poisoned.into_inner(),
    };

    // FIX 14: Find by matching ID
    match logs.iter().find(|log| log.id == id) {
        Some(log) => HttpResponse::Ok().json(log),
        None => {
            warn!("Audit log not found: {}", id);
            HttpResponse::NotFound().json(ApiError {
                error: "Not found".to_string(),
                details: vec![format!("Audit log with id '{}' does not exist", id)],
            })
        }
    }
}

/// FIX 15: Acquire mutable lock before clearing
/// FIX 16: Return 204 No Content on successful deletion
async fn delete_audit_logs(data: web::Data<AppState>) -> HttpResponse {
    match data.logs.lock() {
        Ok(mut logs) => {
            let count = logs.len();
            logs.clear();  // FIX 15: mutable access via Mutex guard
            info!("Cleared {} audit log entries", count);
            HttpResponse::NoContent().finish()  // FIX 16: 204
        }
        Err(poisoned) => {
            let mut logs = poisoned.into_inner();
            logs.clear();
            HttpResponse::NoContent().finish()
        }
    }
}

