use std::collections::VecDeque;
use std::sync::{Arc, Mutex, Condvar};
use std::thread;
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone)]
enum ReportType {
    Sales,
    Inventory,
    UserActivity,
}

#[derive(Debug, Clone)]
struct ReportJob {
    id: u64,
    report_type: ReportType,
    requested_by: String,
    parameters: String,
}

struct JobQueue {
    queue: Mutex<VecDeque<ReportJob>>,
    condvar: Condvar,
    shutdown: Mutex<bool>,
}

impl JobQueue {
    fn new() -> Self {
        JobQueue {
            queue: Mutex::new(VecDeque::new()),
            condvar: Condvar::new(),
            shutdown: Mutex::new(false),
        }
    }

    fn push(&self, job: ReportJob) {
        let mut queue = self.queue.lock().unwrap();
        println!("[Producer] Enqueued job #{}: {:?} report for '{}'",
            job.id, job.report_type, job.requested_by);
        queue.push_back(job);
        self.condvar.notify_one();
    }

    fn pop(&self) -> Option<ReportJob> {
        let mut queue = self.queue.lock().unwrap();
        loop {
            if let Some(job) = queue.pop_front() {
                return Some(job);
            }
            if *self.shutdown.lock().unwrap() {
                return None;
            }
            queue = self.condvar.wait(queue).unwrap();
        }
    }

    fn shutdown(&self) {
        *self.shutdown.lock().unwrap() = true;
        self.condvar.notify_all();
    }
}

fn generate_report(job: &ReportJob) -> String {
    // Simulate work
    thread::sleep(std::time::Duration::from_millis(200));

    match job.report_type {
        ReportType::Sales => {
            format!(
                "=== SALES REPORT ===\nRequested by: {}\nParams: {}\nTotal Revenue: $42,350.00\nOrders: 187\nAvg Order Value: $226.47\n====================",
                job.requested_by, job.parameters
            )
        }
        ReportType::Inventory => {
            format!(
                "=== INVENTORY REPORT ===\nRequested by: {}\nParams: {}\nTotal SKUs: 1,204\nLow Stock Items: 23\nOut of Stock: 5\n========================",
                job.requested_by, job.parameters
            )
        }
        ReportType::UserActivity => {
            format!(
                "=== USER ACTIVITY REPORT ===\nRequested by: {}\nParams: {}\nActive Users (24h): 3,891\nNew Signups: 142\nChurn Rate: 2.1%\n============================",
                job.requested_by, job.parameters
            )
        }
    }
}

fn consumer_loop(id: usize, queue: Arc<JobQueue>) {
    println!("[Consumer-{}] Started", id);
    loop {
        match queue.pop() {
            Some(job) => {
                println!("[Consumer-{}] Processing job #{}: {:?}", id, job.id, job.report_type);
                let report = generate_report(&job);
                println!("[Consumer-{}] Completed job #{}:\n{}\n", id, job.id, report);
            }
            None => {
                println!("[Consumer-{}] Shutting down", id);
                break;
            }
        }
    }
}

fn main() {
    let queue = Arc::new(JobQueue::new());
    let num_consumers = 2;

    // Spawn consumer threads
    let mut handles = Vec::new();
    for i in 0..num_consumers {
        let q = Arc::clone(&queue);
        handles.push(thread::spawn(move || consumer_loop(i, q)));
    }

    // Produce some report jobs
    let jobs = vec![
        ReportJob {
            id: 1,
            report_type: ReportType::Sales,
            requested_by: "alice@example.com".into(),
            parameters: "range=2024-Q1".into(),
        },
        ReportJob {
            id: 2,
            report_type: ReportType::Inventory,
            requested_by: "bob@example.com".into(),
            parameters: "warehouse=US-EAST".into(),
        },
        ReportJob {
            id: 3,
            report_type: ReportType::UserActivity,
            requested_by: "carol@example.com".into(),
            parameters: "period=last_30d".into(),
        },
        ReportJob {
            id: 4,
            report_type: ReportType::Sales,
            requested_by: "dave@example.com".into(),
            parameters: "range=2024-Q2".into(),
        },
        ReportJob {
            id: 5,
            report_type: ReportType::Inventory,
            requested_by: "eve@example.com".into(),
            parameters: "warehouse=EU-WEST".into(),
        },
    ];

    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs();
    println!("--- Report Generation System started at {} ---\n", timestamp);

    for job in jobs {
        queue.push(job);
        thread::sleep(std::time::Duration::from_millis(50));
    }

    // Wait for queue to drain then shut down
    loop {
        let len = queue.queue.lock().unwrap().len();
        if len == 0 {
            break;
        }
        thread::sleep(std::time::Duration::from_millis(100));
    }
    // Give consumers time to finish current work
    thread::sleep(std::time::Duration::from_millis(500));

    println!("\n--- Sending shutdown signal ---");
    queue.shutdown();

    for handle in handles {
        handle.join().unwrap();
    }

    println!("--- All consumers stopped. Done. ---");
}
```

This is a basic multi-threaded queue consumer for report generation using only the standard library. Here's the breakdown:

## Key components

- **`ReportJob`** — a struct carrying the job ID, report type (enum), requester, and parameters
- **`JobQueue`** — a thread-safe wrapper around `VecDeque` using `Mutex` + `Condvar` for blocking pops (consumers sleep until work arrives instead of busy-spinning)
- **`consumer_loop`** — each consumer thread loops, pulling jobs off the queue and calling `generate_report`
- **`generate_report`** — simulates work with a sleep and returns a formatted string based on report type

## How it works

1. **2 consumer threads** spawn and block waiting for work
2. **The main thread** (producer) pushes 5 report jobs into the queue
3. Consumers wake up via `Condvar::notify_one` and process jobs concurrently
4. After the queue drains, a **shutdown signal** is sent (`notify_all` wakes all blocked consumers, which then exit)
5. Main thread joins all consumer handles

```rust
use std::collections::HashMap;
use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

/// Represents a document to be indexed
#[derive(Debug, Clone)]
struct Document {
    id: String,
    title: String,
    body: String,
}

/// Represents different types of indexing tasks
#[derive(Debug, Clone)]
enum IndexTask {
    Add(Document),
    Update(Document),
    Delete(String), // document id
}

/// Simple in-memory search index using inverted index
struct SearchIndex {
    // word -> set of document IDs
    inverted_index: HashMap<String, Vec<String>>,
    // doc_id -> document
    documents: HashMap<String, Document>,
}

impl SearchIndex {
    fn new() -> Self {
        SearchIndex {
            inverted_index: HashMap::new(),
            documents: HashMap::new(),
        }
    }

    fn add_document(&mut self, doc: &Document) {
        // Remove old entries if doc already exists
        self.remove_document(&doc.id);

        // Tokenize title and body
        let tokens = Self::tokenize(&format!("{} {}", doc.title, doc.body));

        // Add to inverted index
        for token in tokens {
            self.inverted_index
                .entry(token)
                .or_default()
                .push(doc.id.clone());
        }

        // Store the document
        self.documents.insert(doc.id.clone(), doc.clone());
        println!("  [index] Indexed document: {} - \"{}\"", doc.id, doc.title);
    }

    fn remove_document(&mut self, doc_id: &str) {
        if self.documents.remove(doc_id).is_some() {
            // Remove from inverted index
            for doc_ids in self.inverted_index.values_mut() {
                doc_ids.retain(|id| id != doc_id);
            }
            // Clean up empty entries
            self.inverted_index.retain(|_, ids| !ids.is_empty());
            println!("  [index] Removed document: {}", doc_id);
        }
    }

    fn search(&self, query: &str) -> Vec<&Document> {
        let tokens = Self::tokenize(query);
        let mut scores: HashMap<&str, usize> = HashMap::new();

        for token in &tokens {
            if let Some(doc_ids) = self.inverted_index.get(token) {
                for doc_id in doc_ids {
                    *scores.entry(doc_id.as_str()).or_insert(0) += 1;
                }
            }
        }

        // Sort by score descending
        let mut results: Vec<_> = scores.into_iter().collect();
        results.sort_by(|a, b| b.1.cmp(&a.1));

        results
            .into_iter()
            .filter_map(|(id, _)| self.documents.get(id))
            .collect()
    }

    fn tokenize(text: &str) -> Vec<String> {
        text.to_lowercase()
            .split_whitespace()
            .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()).to_string())
            .filter(|w| !w.is_empty())
            .collect()
    }

    fn doc_count(&self) -> usize {
        self.documents.len()
    }
}

/// Queue consumer that processes index tasks
struct QueueConsumer {
    queue: Arc<Mutex<VecDeque<IndexTask>>>,
    index: Arc<Mutex<SearchIndex>>,
    running: Arc<Mutex<bool>>,
}

impl QueueConsumer {
    fn new(
        queue: Arc<Mutex<VecDeque<IndexTask>>>,
        index: Arc<Mutex<SearchIndex>>,
    ) -> Self {
        QueueConsumer {
            queue,
            index,
            running: Arc::new(Mutex::new(false)),
        }
    }

    /// Start consuming tasks in a background thread
    fn start(&self) -> thread::JoinHandle<()> {
        let queue = Arc::clone(&self.queue);
        let index = Arc::clone(&self.index);
        let running = Arc::clone(&self.running);

        *running.lock().unwrap() = true;

        thread::spawn(move || {
            println!("[consumer] Started");

            while *running.lock().unwrap() {
                // Try to get a task from the queue
                let task = {
                    let mut q = queue.lock().unwrap();
                    q.pop_front()
                };

                match task {
                    Some(task) => {
                        println!("[consumer] Processing: {:?}", task);
                        let mut idx = index.lock().unwrap();

                        match &task {
                            IndexTask::Add(doc) => idx.add_document(doc),
                            IndexTask::Update(doc) => idx.add_document(doc),
                            IndexTask::Delete(id) => idx.remove_document(id),
                        }

                        println!(
                            "[consumer] Done. Index now has {} documents",
                            idx.doc_count()
                        );
                    }
                    None => {
                        // No tasks, sleep briefly before polling again
                        thread::sleep(Duration::from_millis(100));
                    }
                }
            }

            println!("[consumer] Stopped");
        })
    }

    fn stop(&self) {
        *self.running.lock().unwrap() = false;
    }
}

/// Helper to enqueue tasks
fn enqueue(queue: &Arc<Mutex<VecDeque<IndexTask>>>, task: IndexTask) {
    let mut q = queue.lock().unwrap();
    println!("[producer] Enqueuing: {:?}", task);
    q.push_back(task);
}

fn main() {
    let queue: Arc<Mutex<VecDeque<IndexTask>>> = Arc::new(Mutex::new(VecDeque::new()));
    let index = Arc::new(Mutex::new(SearchIndex::new()));

    // Create and start the consumer
    let consumer = QueueConsumer::new(Arc::clone(&queue), Arc::clone(&index));
    let handle = consumer.start();

    // Simulate a producer sending documents to index
    println!("\n=== Enqueueing documents ===\n");

    enqueue(
        &queue,
        IndexTask::Add(Document {
            id: "1".to_string(),
            title: "Rust Programming".to_string(),
            body: "Rust is a systems programming language focused on safety".to_string(),
        }),
    );

    enqueue(
        &queue,
        IndexTask::Add(Document {
            id: "2".to_string(),
            title: "Search Engines".to_string(),
            body: "Search engines use inverted indexes for fast text retrieval".to_string(),
        }),
    );

    enqueue(
        &queue,
        IndexTask::Add(Document {
            id: "3".to_string(),
            title: "Queue Systems".to_string(),
            body: "Message queues enable async processing of tasks".to_string(),
        }),
    );

    // Wait for processing
    thread::sleep(Duration::from_secs(1));

    // Update a document
    println!("\n=== Updating document 1 ===\n");
    enqueue(
        &queue,
        IndexTask::Update(Document {
            id: "1".to_string(),
            title: "Rust Programming Language".to_string(),
            body: "Rust is a blazingly fast systems programming language".to_string(),
        }),
    );

    thread::sleep(Duration::from_millis(500));

    // Delete a document
    println!("\n=== Deleting document 3 ===\n");
    enqueue(&queue, IndexTask::Delete("3".to_string()));

    // Wait for all tasks to process
    thread::sleep(Duration::from_secs(1));

    // Perform some searches
    println!("\n=== Search Results ===\n");
    {
        let idx = index.lock().unwrap();

        for query in &["rust programming", "search", "queue"] {
            let results = idx.search(query);
            println!("Query: \"{}\"", query);
            if results.is_empty() {
                println!("  No results found");
            } else {
                for doc in results {
                    println!("  -> [{}] {} - {}", doc.id, doc.title, doc.body);
                }
            }
            println!();
        }
    }

    // Shut down
    consumer.stop();
    handle.join().unwrap();
    println!("Done.");
}
```

## How it works

**Core components:**

1. **`IndexTask` enum** — three task types: `Add`, `Update`, and `Delete` documents
2. **`SearchIndex`** — a simple inverted index (word → document IDs map) with tokenization, add/remove/search operations
3. **`QueueConsumer`** — polls a shared `VecDeque` in a background thread, processes each task against the index
4. **`enqueue()`** — pushes tasks onto the shared queue from any thread

**Flow:**

```
Producer → enqueue(task) → [ VecDeque ] → Consumer thread → SearchIndex
```

- The consumer runs a poll loop (sleeps 100ms when idle)
- `Arc<Mutex<...>>` provides thread-safe shared access to the queue and index
- The consumer processes Add/Update/Delete by calling the corresponding `SearchIndex` methods
- Search uses basic TF scoring — tokens are matched against the inverted index and results are ranked by hit count

**Key design choices:**
- No external dependencies — uses only `std`
- Polling-based for simplicity (a production version would use `Condvar` or channels)
- The inverted index tokenizes on whitespace and lowercases everything

