// ── Parsing & Validation ────────────────────────────────────────────

impl AppConfig {
    /// Load config from a TOML file path.
    pub fn from_file<P: AsRef<Path>>(path: P) -> Result<Self, ConfigError> {
        let content = std::fs::read_to_string(path)?;
        Self::from_str(&content)
    }

    /// Parse config from a TOML string.
    pub fn from_str(toml_str: &str) -> Result<Self, ConfigError> {
        let config: AppConfig = toml::from_str(toml_str)?;
        config.validate()?;
        Ok(config)
    }

    /// Validate cross-references and invariants.
    fn validate(&self) -> Result<(), ConfigError> {
        if self.general.max_queue_size == 0 {
            return Err(ConfigError::Validation(
                "max_queue_size must be > 0".into(),
            ));
        }

        // Verify every action in every event references an existing handler
        for event_cfg in &self.events {
            for action in &event_cfg.actions {
                if !self.handlers.contains_key(action) {
                    return Err(ConfigError::UnknownHandler(format!(
                        "Event '{}' references unknown handler '{}'",
                        event_cfg.name, action
                    )));
                }
            }
        }

        // Check for duplicate event names
        let mut seen = std::collections::HashSet::new();
        for event_cfg in &self.events {
            if !seen.insert(&event_cfg.name) {
                return Err(ConfigError::Validation(format!(
                    "Duplicate event name: '{}'",
                    event_cfg.name
                )));
            }
        }

        Ok(())
    }

    /// Return only enabled events, sorted by priority (highest first).
    pub fn enabled_events(&self) -> Vec<&EventConfig> {
        let mut events: Vec<&EventConfig> =
            self.events.iter().filter(|e| e.enabled).collect();
        events.sort_by(|a, b| b.priority.cmp(&a.priority));
        events
    }
}
