// ── Handler trait ───────────────────────────────────────────────────

pub trait EventHandler: std::fmt::Debug {
    /// Human-readable name for logging.
    fn name(&self) -> &str;

    /// Process a single event. Returns Ok(summary) or Err.
    fn handle(&self, event: &Event) -> Result<String, ProcessingError>;
}

// ── Log handler ─────────────────────────────────────────────────────

#[derive(Debug)]
pub struct LogHandler {
    output: String,
    format: String,
    include_timestamp: bool,
}

impl LogHandler {
    pub fn from_config(cfg: &LogHandlerConfig) -> Self {
        Self {
            output: cfg.output.clone(),
            format: cfg.format.clone(),
            include_timestamp: cfg.include_timestamp.unwrap_or(true),
        }
    }
}

impl EventHandler for LogHandler {
    fn name(&self) -> &str {
        "log"
    }

    fn handle(&self, event: &Event) -> Result<String, ProcessingError> {
        let output = match self.format.as_str() {
            "json" => event.to_json_string(),
            _ => {
                if self.include_timestamp {
                    format!("{}", event)
                } else {
                    format!("{} (id: {})", event.name, &event.id.to_string()[..8])
                }
            }
        };

        println!("  [LOG → {}] {}", self.output, output);
        Ok(format!("Logged to {}", self.output))
    }
}

