// ── Factory: build handlers from config ─────────────────────────────

pub fn build_handler(name: &str, cfg: &HandlerConfig) -> Box<dyn EventHandler> {
    match cfg {
        HandlerConfig::Log(c) => Box::new(LogHandler::from_config(c)),
        HandlerConfig::Notify(c) => Box::new(NotifyHandler::from_config(c)),
        HandlerConfig::Store(c) => Box::new(StoreHandler::from_config(c)),
        HandlerConfig::Alert(c) => {
            // Fallback: if serde matched wrong variant, use name hint
            let _ = name; // could use for disambiguation
            Box::new(AlertHandler::from_config(c))
        }
    }
}
