```rust
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::io::{self, Read};

// ---------------------------------------------------------------------------
// 1. Data Models
// ---------------------------------------------------------------------------

/// Raw event coming from JSON input
#[derive(Debug, Clone, Deserialize)]
struct RawEvent {
    user_id: String,
    event: String,
    page: String,
    duration_ms: u64,
    timestamp: String,
}

/// Enriched event after the transform stage
#[derive(Debug, Clone)]
struct EnrichedEvent {
    user_id: String,
    event: String,
    page: String,
    duration_ms: u64,
    timestamp: String,
    duration_bucket: DurationBucket,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize)]
enum DurationBucket {
    Fast,   // < 500ms
    Medium, // 500ms – 2000ms
    Slow,   // > 2000ms
}

/// Final analytics report
#[derive(Debug, Serialize)]
struct AnalyticsReport {
    total_events: usize,
    unique_users: usize,
    events_by_type: HashMap<String, usize>,
    events_by_page: HashMap<String, usize>,
    avg_duration_ms: f64,
    duration_distribution: HashMap<String, usize>,
    top_users: Vec<UserSummary>,
}

#[derive(Debug, Serialize)]
struct UserSummary {
    user_id: String,
    event_count: usize,
    total_duration_ms: u64,
    avg_duration_ms: f64,
}

// ---------------------------------------------------------------------------
// 2. Pipeline Stages
// ---------------------------------------------------------------------------

/// **Stage 1 – Ingest**: Read JSON from a file or stdin
fn ingest(source: &DataSource) -> Result<Vec<RawEvent>, Box<dyn std::error::Error>> {
    let json_str = match source {
        DataSource::File(path) => fs::read_to_string(path)?,
        DataSource::Stdin => {
            let mut buf = String::new();
            io::stdin().read_to_string(&mut buf)?;
            buf
        }
        DataSource::Literal(s) => s.clone(),
    };

    let events: Vec<RawEvent> = serde_json::from_str(&json_str)?;
    println!("[ingest]  Loaded {} raw events", events.len());
    Ok(events)
}

/// **Stage 2 – Filter**: Keep only events that match a predicate
fn filter(events: Vec<RawEvent>, predicate: &dyn Fn(&RawEvent) -> bool) -> Vec<RawEvent> {
    let filtered: Vec<RawEvent> = events.into_iter().filter(|e| predicate(e)).collect();
    println!("[filter]  {} events after filtering", filtered.len());
    filtered
}

/// **Stage 3 – Transform / Enrich**: Add computed fields
fn transform(events: Vec<RawEvent>) -> Vec<EnrichedEvent> {
    let enriched: Vec<EnrichedEvent> = events
        .into_iter()
        .map(|e| {
            let bucket = match e.duration_ms {
                d if d < 500 => DurationBucket::Fast,
                d if d <= 2000 => DurationBucket::Medium,
                _ => DurationBucket::Slow,
            };
            EnrichedEvent {
                user_id: e.user_id,
                event: e.event,
                page: e.page,
                duration_ms: e.duration_ms,
                timestamp: e.timestamp,
                duration_bucket: bucket,
            }
        })
        .collect();

    println!("[transform] Enriched {} events", enriched.len());
    enriched
}

/// **Stage 4 – Aggregate**: Compute analytics from enriched events
fn aggregate(events: &[EnrichedEvent]) -> AnalyticsReport {
    let total_events = events.len();

    // Unique users
    let unique_users: HashMap<&str, ()> = events.iter().map(|e| (e.user_id.as_str(), ())).collect();

    // Counts by event type
    let mut events_by_type: HashMap<String, usize> = HashMap::new();
    for e in events {
        *events_by_type.entry(e.event.clone()).or_insert(0) += 1;
    }

    // Counts by page
    let mut events_by_page: HashMap<String, usize> = HashMap::new();
    for e in events {
        *events_by_page.entry(e.page.clone()).or_insert(0) += 1;
    }

    // Average duration
    let total_dur: u64 = events.iter().map(|e| e.duration_ms).sum();
    let avg_duration_ms = if total_events > 0 {
        total_dur as f64 / total_events as f64
    } else {
        0.0
    };

    // Duration bucket distribution
    let mut duration_distribution: HashMap<String, usize> = HashMap::new();
    for e in events {
        let label = format!("{:?}", e.duration_bucket);
        *duration_distribution.entry(label).or_insert(0) += 1;
    }

    // Per-user summary (sorted by event count descending)
    let mut user_map: HashMap<&str, (usize, u64)> = HashMap::new();
    for e in events {
        let entry = user_map.entry(&e.user_id).or_insert((0, 0));
        entry.0 += 1;
        entry.1 += e.duration_ms;
    }
    let mut top_users: Vec<UserSummary> = user_map
        .into_iter()
        .map(|(uid, (count, dur))| UserSummary {
            user_id: uid.to_string(),
            event_count: count,
            total_duration_ms: dur,
            avg_duration_ms: dur as f64 / count as f64,
        })
        .collect();
    top_users.sort_by(|a, b| b.event_count.cmp(&a.event_count));

    let report = AnalyticsReport {
        total_events,
        unique_users: unique_users.len(),
        events_by_type,
        events_by_page,
        avg_duration_ms,
        duration_distribution,
        top_users,
    };

    println!("[aggregate] Report built");
    report
}

/// **Stage 5 – Output**: Serialize report to JSON and print
fn output(report: &AnalyticsReport) -> Result<(), Box<dyn std::error::Error>> {
    let json = serde_json::to_string_pretty(report)?;
    println!("\n========== ANALYTICS REPORT ==========\n{json}");
    Ok(())
}

// ---------------------------------------------------------------------------
// 3. Pipeline Orchestrator
// ---------------------------------------------------------------------------

enum DataSource {
    File(String),
    Stdin,
    #[allow(dead_code)]
    Literal(String),
}

struct Pipeline {
    source: DataSource,
    filters: Vec<Box<dyn Fn(&RawEvent) -> bool>>,
}

impl Pipeline {
    fn new(source: DataSource) -> Self {
        Self {
            source,
            filters: Vec::new(),
        }
    }

    /// Register a filter predicate
    fn add_filter(mut self, f: impl Fn(&RawEvent) -> bool + 'static) -> Self {
        self.filters.push(Box::new(f));
        self
    }

    /// Execute the full pipeline
    fn run(self) -> Result<AnalyticsReport, Box<dyn std::error::Error>> {
        // Stage 1 – Ingest
        let mut events = ingest(&self.source)?;

        // Stage 2 – Filter (apply all registered predicates)
        for predicate in &self.filters {
            events = filter(events, predicate.as_ref());
        }

        // Stage 3 – Transform
        let enriched = transform(events);

        // Stage 4 – Aggregate
        let report = aggregate(&enriched);

        // Stage 5 – Output
        output(&report)?;

        Ok(report)
    }
}

// ---------------------------------------------------------------------------
// 4. Entry Point
// ---------------------------------------------------------------------------

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Determine data source from CLI args
    let args: Vec<String> = std::env::args().collect();
    let source = if args.len() > 1 {
        DataSource::File(args[1].clone())
    } else {
        println!("Usage: analytics_pipeline <file.json>");
        println!("       cat file.json | analytics_pipeline --stdin\n");

        if args.len() > 1 && args[1] == "--stdin" {
            DataSource::Stdin
        } else {
            // Fallback: use embedded sample for demo
            DataSource::Literal(sample_json().to_string())
        }
    };

    // Build and run the pipeline with optional filters
    Pipeline::new(source)
        // Example filters – remove any you don't need
        .add_filter(|e| e.duration_ms > 0)               // drop zero-duration events
        .add_filter(|e| e.event != "debug")               // exclude debug events
        .run()?;

    Ok(())
}

