use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::VecDeque;
use std::sync::Arc;
use std::time::Duration;
use thiserror::Error;
use tokio::sync::Mutex;
use tracing::{error, info, warn};
use uuid::Uuid;

// ---------------------------------------------------------------------------
// Error types
// ---------------------------------------------------------------------------

#[derive(Debug, Error)]
enum IngestionError {
    #[error("Network error: {0}")]
    Network(String),

    #[error("Server error (status {status}): {message}")]
    Server { status: u16, message: String },

    #[error("Serialization error: {0}")]
    Serialization(#[from] serde_json::Error),

    #[error("Max retries exceeded after {attempts} attempts")]
    MaxRetriesExceeded { attempts: u32 },

    #[error("Queue is full (capacity: {capacity})")]
    QueueFull { capacity: usize },
}

impl IngestionError {
    /// Returns true when the caller should retry the operation.
    fn is_retryable(&self) -> bool {
        matches!(
            self,
            IngestionError::Network(_)
                | IngestionError::Server { status: 500..=599, .. }
        )
    }
}

// ---------------------------------------------------------------------------
// Domain models
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Serialize, Deserialize)]
enum LogLevel {
    Debug,
    Info,
    Warn,
    Error,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct LogEntry {
    id: String,
    timestamp: DateTime<Utc>,
    level: LogLevel,
    service: String,
    message: String,
    metadata: Option<serde_json::Value>,
}

impl LogEntry {
    fn new(level: LogLevel, service: &str, message: &str) -> Self {
        Self {
            id: Uuid::new_v4().to_string(),
            timestamp: Utc::now(),
            level,
            service: service.to_string(),
            message: message.to_string(),
            metadata: None,
        }
    }

    fn with_metadata(mut self, metadata: serde_json::Value) -> Self {
        self.metadata = Some(metadata);
        self
    }
}

// ---------------------------------------------------------------------------
// Retry configuration
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
struct RetryConfig {
    max_retries: u32,
    initial_delay: Duration,
    max_delay: Duration,
    backoff_multiplier: f64,
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            max_retries: 5,
            initial_delay: Duration::from_millis(100),
            max_delay: Duration::from_secs(30),
            backoff_multiplier: 2.0,
        }
    }
}

impl RetryConfig {
    /// Calculate the delay for the given `attempt` (0-based) with
    /// exponential back-off capped at `max_delay`.
    fn delay_for_attempt(&self, attempt: u32) -> Duration {
        let delay_ms = self.initial_delay.as_millis() as f64
            * self.backoff_multiplier.powi(attempt as i32);
        let capped = delay_ms.min(self.max_delay.as_millis() as f64);
        Duration::from_millis(capped as u64)
    }
}

// ---------------------------------------------------------------------------
// Simulated HTTP backend
// ---------------------------------------------------------------------------

/// Simulates an unreliable remote log-ingestion endpoint.
struct MockHttpClient {
    /// Monotonically increasing call counter used to inject failures.
    call_count: Mutex<u32>,
}

impl MockHttpClient {
    fn new() -> Self {
        Self {
            call_count: Mutex::new(0),
        }
    }

    /// Send a batch of log entries to the "remote" endpoint.
    ///
    /// The first few calls will fail so that the retry logic is exercised.
    async fn send_logs(&self, logs: &[LogEntry]) -> Result<(), IngestionError> {
        let mut count = self.call_count.lock().await;
        *count += 1;
        let current = *count;
        drop(count);

        // Simulate network latency
        tokio::time::sleep(Duration::from_millis(50)).await;

        // ---- inject failures for demonstration ----
        match current % 5 {
            1 => Err(IngestionError::Network(
                "connection reset by peer".into(),
            )),
            2 => Err(IngestionError::Server {
                status: 503,
                message: "service unavailable".into(),
            }),
            _ => {
                info!(
                    "✅  Successfully ingested batch of {} log(s)",
                    logs.len()
                );
                Ok(())
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Log ingestion service
// ---------------------------------------------------------------------------

struct LogIngestionService {
    client: Arc<MockHttpClient>,
    retry_config: RetryConfig,
    buffer: Mutex<VecDeque<LogEntry>>,
    batch_size: usize,
    max_buffer_size: usize,
}

impl LogIngestionService {
    fn new(
        client: Arc<MockHttpClient>,
        retry_config: RetryConfig,
        batch_size: usize,
        max_buffer_size: usize,
    ) -> Self {
        Self {
            client,
            retry_config,
            buffer: Mutex::new(VecDeque::with_capacity(max_buffer_size)),
            batch_size,
            max_buffer_size,
        }
    }

    // -- public API ---------------------------------------------------------

    /// Enqueue a single log entry for later ingestion.
    async fn enqueue(&self, entry: LogEntry) -> Result<(), IngestionError> {
        let mut buf = self.buffer.lock().await;
        if buf.len() >= self.max_buffer_size {
            return Err(IngestionError::QueueFull {
                capacity: self.max_buffer_size,
            });
        }
        info!("📝  Enqueued log: [{}] {}", entry.service, entry.message);
        buf.push_back(entry);
        Ok(())
    }

    /// Drain the buffer in batches and send each batch with retries.
    async fn flush(&self) -> Result<u32, IngestionError> {
        let mut total_sent: u32 = 0;

        loop {
            let batch = self.take_batch().await;
            if batch.is_empty() {
                break;
            }

            self.send_with_retry(&batch).await?;
            total_sent += batch.len() as u32;
        }

        Ok(total_sent)
    }

    /// Convenience: enqueue *and* send a single entry immediately.
    async fn ingest(&self, entry: LogEntry) -> Result<(), IngestionError> {
        let batch = vec![entry];
        self.send_with_retry(&batch).await
    }

    // -- internal helpers ---------------------------------------------------

    /// Pop up to `batch_size` entries from the front of the buffer.
    async fn take_batch(&self) -> Vec<LogEntry> {
        let mut buf = self.buffer.lock().await;
        let n = self.batch_size.min(buf.len());
        buf.drain(..n).collect()
    }

    /// Send `batch` to the backend, retrying on transient failures.
    async fn send_with_retry(&self, batch: &[LogEntry]) -> Result<(), IngestionError> {
        let cfg = &self.retry_config;

        for attempt in 0..=cfg.max_retries {
            match self.client.send_logs(batch).await {
                Ok(()) => return Ok(()),
                Err(e) if e.is_retryable() && attempt < cfg.max_retries => {
                    let delay = cfg.delay_for_attempt(attempt);
                    warn!(
                        "⚠️  Attempt {}/{} failed: {}. Retrying in {:?}…",
                        attempt + 1,
                        cfg.max_retries,
                        e,
                        delay,
                    );
                    tokio::time::sleep(delay).await;
                }
                Err(e) if e.is_retryable() => {
                    error!(
                        "❌  All {} retries exhausted. Last error: {}",
                        cfg.max_retries, e
                    );
                    return Err(IngestionError::MaxRetriesExceeded {
                        attempts: cfg.max_retries,
                    });
                }
                Err(e) => {
                    // Non-retryable → fail fast
                    error!("❌  Non-retryable error: {}", e);
                    return Err(e);
                }
            }
        }

        // Should be unreachable, but handle defensively.
        Err(IngestionError::MaxRetriesExceeded {
            attempts: cfg.max_retries,
        })
    }
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialise tracing / logging
    tracing_subscriber::fmt()
        .with_target(false)
        .with_thread_ids(true)
        .init();

    info!("🚀  Starting log ingestion service");

    let client = Arc::new(MockHttpClient::new());
    let retry_config = RetryConfig {
        max_retries: 4,
        initial_delay: Duration::from_millis(200),
        max_delay: Duration::from_secs(5),
        backoff_multiplier: 2.0,
    };

    let service = Arc::new(LogIngestionService::new(
        client,
        retry_config,
        5,    // batch_size
        1000, // max_buffer_size
    ));

    // ── Demo 1: direct ingestion with retries ──────────────────────────────
    info!("── Demo 1: direct ingest ──");
    let entry = LogEntry::new(LogLevel::Info, "auth-service", "User login successful");
    service.ingest(entry).await?;

    // ── Demo 2: buffer → flush in batches ──────────────────────────────────
    info!("── Demo 2: buffered flush ──");
    let sample_logs = vec![
        LogEntry::new(LogLevel::Debug, "api-gateway", "Request received: GET /health"),
        LogEntry::new(LogLevel::Info, "user-service", "Profile updated for user 42"),
        LogEntry::new(LogLevel::Warn, "db-service", "Slow query detected (2.3 s)")
            .with_metadata(serde_json::json!({
                "query": "SELECT * FROM orders WHERE …",
                "duration_ms": 2300,
            })),
        LogEntry::new(LogLevel::Error, "payment-service", "Payment gateway timeout"),
        LogEntry::new(LogLevel::Info, "api-gateway", "Request received: POST /orders"),
    ];

    for log in sample_logs {
        service.enqueue(log).await?;
    }

    let sent = service.flush().await?;
    info!("📊  Flushed {sent} log(s) in total");

    // ── Demo 3: concurrent producers ───────────────────────────────────────
    info!("── Demo 3: concurrent producers ──");
    let mut handles = Vec::new();

    for i in 0..3 {
        let svc = Arc::clone(&service);
        handles.push(tokio::spawn(async move {
            let entry = LogEntry::new(
                LogLevel::Info,
                &format!("worker-{i}"),
                &format!("Concurrent log from worker {i}"),
            );
            svc.ingest(entry).await
        }));
    }

    for h in handles {
        h.await??;
    }

    info!("✅  All demos completed successfully");
    Ok(())
}
```

## How It Works

```
┌────────────┐      enqueue()      ┌───────────────┐
│  Producer   │ ──────────────────▶ │ Ring Buffer    │
│  (app code) │                     │ (VecDeque)     │
└────────────┘                     └───────┬───────┘
                                           │ flush() / ingest()
                                           ▼
                                   ┌───────────────┐
                                   │ Retry Engine   │
                                   │ (exp. backoff) │
                                   └───────┬───────┘
                                           │
                          attempt 1  ✗     │  attempt 2  ✗     attempt 3  ✓
                          ─────────────────┼───────────────────────────────▶
                           delay 200ms     │    delay 400ms
                                           ▼
                                   ┌───────────────┐
                                   │ HTTP Backend   │
                                   │ (mock / real)  │
                                   └───────────────┘
```

## Key Design Points

| Feature | Implementation |
|---|---|
| **Exponential backoff** | `delay = initial_delay × multiplier^attempt`, capped at `max_delay` |
| **Retryable vs non-retryable** | `is_retryable()` — only network & 5xx errors trigger retries |
| **Bounded buffer** | `VecDeque` with `max_buffer_size` prevents OOM |
| **Batch sending** | `flush()` drains buffer in configurable `batch_size` chunks |
| **Concurrency-safe** | Uses `Arc<Mutex<…>>` for the buffer; `Arc` for shared ownership |
| **Structured errors** | `thiserror` crate with typed variants |

