use chrono::Local;
use notify::{Config, Event, EventKind, RecommendedWatcher, RecursiveMode, Watcher};
use std::fs::OpenOptions;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::mpsc;

/// Formats a notify EventKind into a human-readable action string.
fn event_kind_to_action(kind: &EventKind) -> Option<&'static str> {
    match kind {
        EventKind::Create(_) => Some("CREATED"),
        EventKind::Modify(_) => Some("MODIFIED"),
        EventKind::Remove(_) => Some("DELETED"),
        EventKind::Access(_) => Some("ACCESSED"),
        _ => None, // ignore Other/Any events
    }
}

/// Builds a single audit log line from an event.
fn format_log_entry(action: &str, paths: &[PathBuf]) -> String {
    let timestamp = Local::now().format("%Y-%m-%d %H:%M:%S%.3f");
    let path_list: Vec<&str> = paths.iter().filter_map(|p| p.to_str()).collect();
    format!("[{}] {} :: {}", timestamp, action, path_list.join(", "))
}

/// Appends a line to the audit log file and prints to stdout.
fn write_audit_log(log_path: &Path, entry: &str) {
    println!("{}", entry);

    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_path)
        .expect("failed to open audit log file");

    writeln!(file, "{}", entry).expect("failed to write to audit log");
}

/// Processes a single notify event, logging it if relevant.
fn handle_event(event: Event, log_path: &Path) {
    if let Some(action) = event_kind_to_action(&event.kind) {
        let entry = format_log_entry(action, &event.paths);
        write_audit_log(log_path, &entry);
    }
}

fn main() {
    // --- Configuration ---------------------------------------------------
    let watch_dir = std::env::args()
        .nth(1)
        .unwrap_or_else(|| ".".to_string());
    let log_file = std::env::args()
        .nth(2)
        .unwrap_or_else(|| "audit.log".to_string());

    let watch_path = Path::new(&watch_dir);
    let log_path = Path::new(&log_file);

    if !watch_path.exists() {
        eprintln!("error: watch directory '{}' does not exist", watch_dir);
        std::process::exit(1);
    }

    // --- Channel for filesystem events -----------------------------------
    let (tx, rx) = mpsc::channel::<notify::Result<Event>>();

    // --- Create watcher --------------------------------------------------
    let mut watcher: RecommendedWatcher =
        Watcher::new(tx, Config::default()).expect("failed to create watcher");

    watcher
        .watch(watch_path, RecursiveMode::Recursive)
        .expect("failed to start watching directory");

    println!("=== File Audit Watcher ===");
    println!("Watching : {}", watch_path.canonicalize().unwrap().display());
    println!("Log file : {}", log_path.display());
    println!("Press Ctrl+C to stop.\n");

    // --- Event loop ------------------------------------------------------
    for result in rx {
        match result {
            Ok(event) => handle_event(event, log_path),
            Err(e) => eprintln!("watch error: {:?}", e),
        }
    }
}
```

