// --- Audit Log Storage (simulated sink) ---

#[derive(Debug)]
pub struct AuditLogStore {
    logs: Vec<AuditEvent>,
    write_count: u64,
    error_count: u64,
}

impl AuditLogStore {
    pub fn new() -> Self {
        Self {
            logs: Vec::new(),
            write_count: 0,
            error_count: 0,
        }
    }

    /// Persist an event. Returns Err on simulated failures.
    pub fn persist(&mut self, event: &AuditEvent) -> Result<(), String> {
        // Simulate occasional write failure (every 13th event)
        if self.write_count > 0 && self.write_count % 13 == 0 {
            self.error_count += 1;
            return Err(format!("Simulated write failure for event {}", event.id));
        }
        self.logs.push(event.clone());
        self.write_count += 1;
        Ok(())
    }

    pub fn stats(&self) -> (usize, u64) {
        (self.logs.len(), self.error_count)
    }
}

// --- Bounded Queue with Backpressure ---

struct QueueInner {
    buffer: VecDeque<AuditEvent>,
    capacity: usize,
    closed: bool,
}

pub struct AuditQueue {
    inner: Mutex<QueueInner>,
    not_empty: Condvar,
    not_full: Condvar,
}

impl AuditQueue {
    pub fn new(capacity: usize) -> Self {
        Self {
            inner: Mutex::new(QueueInner {
                buffer: VecDeque::with_capacity(capacity),
                capacity,
                closed: false,
            }),
            not_empty: Condvar::new(),
            not_full: Condvar::new(),
        }
    }

    /// Enqueue with backpressure — blocks if the queue is full.
    /// Returns false if the queue is closed.
    pub fn push(&self, event: AuditEvent) -> bool {
        let mut inner = self.inner.lock().unwrap();

        // Wait until there's space or queue closes
        while inner.buffer.len() >= inner.capacity && !inner.closed {
            inner = self.not_full.wait(inner).unwrap();
        }

        if inner.closed {
            return false;
        }

        inner.buffer.push_back(event);
        self.not_empty.notify_one();
        true
    }

    /// Dequeue — blocks until an event is available.
    /// Returns None when closed and drained.
    pub fn pop(&self) -> Option<AuditEvent> {
        let mut inner = self.inner.lock().unwrap();

        while inner.buffer.is_empty() && !inner.closed {
            inner = self.not_empty.wait(inner).unwrap();
        }

        let event = inner.buffer.pop_front();
        self.not_full.notify_one();
        event
    }

    /// Drain up to `max` events at once (batch consume).
    pub fn drain_batch(&self, max: usize) -> Vec<AuditEvent> {
        let mut inner = self.inner.lock().unwrap();

        while inner.buffer.is_empty() && !inner.closed {
            // Wait with a timeout so we can flush partial batches
            let result = self
                .not_empty
                .wait_timeout(inner, Duration::from_millis(100))
                .unwrap();
            inner = result.0;
        }

        let count = max.min(inner.buffer.len());
        let batch: Vec<_> = inner.buffer.drain(..count).collect();

        if !batch.is_empty() {
            self.not_full.notify_all();
        }

        batch
    }

    pub fn close(&self) {
        let mut inner = self.inner.lock().unwrap();
        inner.closed = true;
        self.not_empty.notify_all();
        self.not_full.notify_all();
    }

    pub fn len(&self) -> usize {
        self.inner.lock().unwrap().buffer.len()
    }
}

// --- Consumer ---

pub struct AuditConsumer {
    queue: Arc<AuditQueue>,
    store: Arc<Mutex<AuditLogStore>>,
    batch_size: usize,
    max_retries: u32,
}

impl AuditConsumer {
    pub fn new(
        queue: Arc<AuditQueue>,
        store: Arc<Mutex<AuditLogStore>>,
        batch_size: usize,
        max_retries: u32,
    ) -> Self {
        Self {
            queue,
            store,
            batch_size,
            max_retries,
        }
    }

    /// Run the consumer loop. Blocks until queue is closed and drained.
    pub fn run(&self) {
        let thread_id = thread::current().id();
        println!("[consumer {:?}] started (batch_size={})", thread_id, self.batch_size);

        loop {
            let batch = self.queue.drain_batch(self.batch_size);

            if batch.is_empty() {
                // Queue is closed and drained
                break;
            }

            println!(
                "[consumer {:?}] processing batch of {} events",
                thread_id,
                batch.len()
            );

            for event in &batch {
                self.process_with_retry(event);
            }
        }

        println!("[consumer {:?}] shutting down", thread_id);
    }

    fn process_with_retry(&self, event: &AuditEvent) {
        let mut attempts = 0;
        loop {
            let result = {
                let mut store = self.store.lock().unwrap();
                store.persist(event)
            };

            match result {
                Ok(()) => {
                    return;
                }
                Err(e) => {
                    attempts += 1;
                    eprintln!(
                        "[consumer] retry {}/{} for event {}: {}",
                        attempts, self.max_retries, event.id, e
                    );

                    if attempts >= self.max_retries {
                        // Dead-letter: log and move on so we don't block the pipeline
                        eprintln!(
                            "[consumer] DEAD LETTER event {}: {}",
                            event.id, event
                        );
                        return;
                    }

                    // Exponential backoff (capped)
                    let backoff = Duration::from_millis(50 * 2u64.pow(attempts - 1));
                    thread::sleep(backoff);
                }
            }
        }
    }
}

// --- Producer helper ---

fn now_epoch_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}

fn produce_events(queue: &AuditQueue, count: u64) {
    let actions = [
        (AuditAction::UserLogin, Severity::Info, "auth-service"),
        (AuditAction::DataAccess, Severity::Info, "api-gateway"),
        (AuditAction::DataModify, Severity::Warning, "admin-panel"),
        (AuditAction::PermissionChange, Severity::Critical, "iam-service"),
        (AuditAction::DataDelete, Severity::Critical, "cleanup-job"),
        (AuditAction::ConfigChange, Severity::Warning, "config-service"),
        (AuditAction::UserLogout, Severity::Info, "auth-service"),
        (AuditAction::SystemError, Severity::Critical, "payment-svc"),
    ];

    for i in 0..count {
        let (action, severity, resource) = &actions[(i as usize) % actions.len()];

        let event = AuditEvent {
            id: i,
            timestamp: now_epoch_ms(),
            action: action.clone(),
            severity: severity.clone(),
            user_id: format!("user-{}", i % 5),
            resource: resource.to_string(),
            detail: format!("Event #{} detail", i),
            source_ip: if i % 3 == 0 {
                Some(format!("10.0.{}.{}", i % 256, (i * 7) % 256))
            } else {
                None
            },
        };

        if !queue.push(event) {
            eprintln!("[producer] queue closed, stopping at event {}", i);
            break;
        }

        // Simulate bursty production
        if i % 10 == 0 {
            thread::sleep(Duration::from_millis(5));
        }
    }

    println!("[producer] finished producing {} events", count);
}

// --- Main: wire it all up ---

fn main() {
    const QUEUE_CAPACITY: usize = 64;
    const TOTAL_EVENTS: u64 = 200;
    const NUM_CONSUMERS: usize = 3;
    const BATCH_SIZE: usize = 10;
    const MAX_RETRIES: u32 = 3;

    let queue = Arc::new(AuditQueue::new(QUEUE_CAPACITY));
    let store = Arc::new(Mutex::new(AuditLogStore::new()));

    // Spawn consumer threads
    let mut consumer_handles = Vec::new();
    for _ in 0..NUM_CONSUMERS {
        let consumer = AuditConsumer::new(
            Arc::clone(&queue),
            Arc::clone(&store),
            BATCH_SIZE,
            MAX_RETRIES,
        );
        let handle = thread::spawn(move || consumer.run());
        consumer_handles.push(handle);
    }

    // Producer runs on the main thread (could also be a separate thread)
    let producer_queue = Arc::clone(&queue);
    let producer = thread::spawn(move || {
        produce_events(&producer_queue, TOTAL_EVENTS);
        // Signal consumers that no more events are coming
        producer_queue.close();
    });

    producer.join().expect("producer panicked");

    for h in consumer_handles {
        h.join().expect("consumer panicked");
    }

    // Print final stats
    let store = store.lock().unwrap();
    let (persisted, errors) = store.stats();
    println!("\n=== Audit Log Stats ===");
    println!("Events produced:  {}", TOTAL_EVENTS);
    println!("Events persisted: {}", persisted);
    println!("Write errors:     {}", errors);
    println!("Queue remaining:  {}", queue.len());
}
```

## What this gives you

**Bounded queue with backpressure** — producers block when the buffer is full (`QUEUE_CAPACITY = 64`), so a slow sink won't cause unbounded memory growth.

**Batch consumption** — each consumer drains up to `BATCH_SIZE` events at once via `drain_batch`, which is how you'd interact with a real database or log aggregator (bulk inserts).

**Retry with exponential backoff** — failed persists retry up to `MAX_RETRIES` times with `50ms * 2^attempt` backoff. After exhausting retries the event is logged as a dead letter so the pipeline keeps moving.

**Multiple consumers** — 3 consumer threads share the queue via `Arc<AuditQueue>`. The `Condvar`-based synchronisation means threads sleep instead of spin-waiting.

**Clean shutdown** — the producer calls `queue.close()` when done. Consumers finish draining remaining events then exit.

### To make this production-ready

| Concern | What to swap in |
|---|---|
| Queue backend | Replace `VecDeque` with Kafka/RabbitMQ/Redis Streams consumer |
| Storage | Replace `AuditLogStore` with Postgres (`sqlx`), Elasticsearch, or S3-backed parquet |
| Serialization | Add `serde::Serialize` on `AuditEvent`, write JSON/protobuf |
| Dead letter queue | Persist failed events to a DLQ topic instead of just `eprintln!` |
| Observability | Add `tracing` spans and Prometheus counters for queue depth / throughput / error rate |
| Graceful shutdown | Listen for `SIGTERM` via `tokio::signal` or `ctrlc` crate |

# File Watcher for Search Indexing in Rust

## Project Structure

```
file_watcher/
├── Cargo.toml
└── src/
    └── main.rs
```

## Cargo.toml

```toml
[package]
name = "file_watcher"
version = "0.1.0"
edition = "2021"

[dependencies]
notify = "6.1"
```

## src/main.rs

```rust
use notify::{Config, Event, EventKind, RecommendedWatcher, RecursiveMode, Watcher};
use std::collections::{HashMap, HashSet};
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};
use std::sync::mpsc;
use std::thread;

// ── Inverted Index ──────────────────────────────────────────────────

struct SearchIndex {
    /// word -> set of file paths containing that word
    index: HashMap<String, HashSet<PathBuf>>,
    /// track indexed files so we can remove stale entries
    files: HashSet<PathBuf>,
}

impl SearchIndex {
    fn new() -> Self {
        Self {
            index: HashMap::new(),
            files: HashSet::new(),
        }
    }

    /// Index a single file by reading its contents and tokenizing.
    fn add_file(&mut self, path: &Path) {
        // Remove old entries first so modified files stay clean
        self.remove_file(path);

        let contents = match fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("[index] skip {}: {e}", path.display());
                return;
            }
        };

        let path_buf = path.to_path_buf();
        self.files.insert(path_buf.clone());

        for word in tokenize(&contents) {
            self.index
                .entry(word)
                .or_default()
                .insert(path_buf.clone());
        }

        println!("[index] added  {}", path.display());
    }

    /// Remove every reference to a file from the index.
    fn remove_file(&mut self, path: &Path) {
        if !self.files.remove(path) {
            return;
        }
        // Walk every posting list and drop this path
        self.index.retain(|_, paths| {
            paths.remove(path);
            !paths.is_empty()
        });
        println!("[index] removed {}", path.display());
    }

    /// Search for a query string. Returns files that contain ALL query words.
    fn search(&self, query: &str) -> Vec<&Path> {
        let words: Vec<String> = tokenize(query);
        if words.is_empty() {
            return Vec::new();
        }

        let mut result: Option<HashSet<&PathBuf>> = None;

        for word in &words {
            let matching = match self.index.get(word) {
                Some(set) => set.iter().collect::<HashSet<_>>(),
                None => return Vec::new(), // word not found anywhere
            };

            result = Some(match result {
                Some(current) => current.intersection(&matching).copied().collect(),
                None => matching,
            });
        }

        let mut paths: Vec<&Path> = result
            .unwrap_or_default()
            .into_iter()
            .map(|p| p.as_path())
            .collect();
        paths.sort();
        paths
    }

    fn stats(&self) {
        println!(
            "[index] {} files, {} unique tokens",
            self.files.len(),
            self.index.len()
        );
    }
}

// ── Helpers ─────────────────────────────────────────────────────────

/// Lowercase and split on non-alphanumeric boundaries.
fn tokenize(text: &str) -> Vec<String> {
    text.to_lowercase()
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
        .map(String::from)
        .collect()
}

/// Walk a directory recursively, return all file paths.
fn walk_dir(dir: &Path) -> Vec<PathBuf> {
    let mut result = Vec::new();
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                result.extend(walk_dir(&path));
            } else if path.is_file() {
                result.push(path);
            }
        }
    }
    result
}

// ── Main ────────────────────────────────────────────────────────────

fn main() {
    let watch_dir = std::env::args()
        .nth(1)
        .unwrap_or_else(|| ".".to_string());
    let watch_path = PathBuf::from(&watch_dir);

    if !watch_path.is_dir() {
        eprintln!("Usage: file_watcher <directory>");
        std::process::exit(1);
    }

    println!("watching: {}", watch_path.display());

    // ── Build initial index ─────────────────────────────────────────
    let mut index = SearchIndex::new();
    for path in walk_dir(&watch_path) {
        index.add_file(&path);
    }
    index.stats();

    // ── Start file watcher on a background thread ───────────────────
    let (tx, rx) = mpsc::channel::<Event>();

    let mut watcher = RecommendedWatcher::new(
        move |res: Result<Event, notify::Error>| {
            if let Ok(event) = res {
                let _ = tx.send(event);
            }
        },
        Config::default(),
    )
    .expect("failed to create watcher");

    watcher
        .watch(&watch_path, RecursiveMode::Recursive)
        .expect("failed to watch directory");

    // Process fs events in a separate thread, send index commands back
    let (cmd_tx, cmd_rx) = mpsc::channel::<IndexCmd>();

    thread::spawn(move || {
        // keep watcher alive
        let _watcher = watcher;
        for event in rx {
            let cmds = handle_event(event);
            for cmd in cmds {
                let _ = cmd_tx.send(cmd);
            }
        }
    });

    // ── Interactive search REPL on main thread ──────────────────────
    println!("\nType a search query (or :quit / :stats):");

    let stdin = io::stdin();
    let mut stdout = io::stdout();

    loop {
        // Drain any pending index updates before prompting
        while let Ok(cmd) = cmd_rx.try_recv() {
            match cmd {
                IndexCmd::Upsert(p) => index.add_file(&p),
                IndexCmd::Remove(p) => index.remove_file(&p),
            }
        }

        print!("> ");
        stdout.flush().unwrap();

        let mut line = String::new();
        if stdin.lock().read_line(&mut line).unwrap() == 0 {
            break; // EOF
        }

        let query = line.trim();
        if query.is_empty() {
            continue;
        }

        match query {
            ":quit" | ":q" => break,
            ":stats" => index.stats(),
            _ => {
                let results = index.search(query);
                if results.is_empty() {
                    println!("  (no results)");
                } else {
                    for path in &results {
                        println!("  {}", path.display());
                    }
                    println!("  ({} result(s))", results.len());
                }
            }
        }
    }
}

// ── FS Event → Index Command mapping ────────────────────────────────

enum IndexCmd {
    Upsert(PathBuf),
    Remove(PathBuf),
}

fn handle_event(event: Event) -> Vec<IndexCmd> {
    let mut cmds = Vec::new();

    match event.kind {
        EventKind::Create(_) | EventKind::Modify(_) => {
            for path in event.paths {
                if path.is_file() {
                    cmds.push(IndexCmd::Upsert(path));
                }
            }
        }
        EventKind::Remove(_) => {
            for path in event.paths {
                cmds.push(IndexCmd::Remove(path));
            }
        }
        _ => {}
    }

    cmds
}
```

## How It Works

```
┌──────────────┐   notify events   ┌──────────────┐  IndexCmd   ┌────────────┐
│  filesystem   │ ───────────────► │ watcher thread│ ──────────► │ main thread│
│  (create/     │                  │ (maps events  │  (channel)  │ (index +   │
│   modify/     │                  │  to commands) │             │  REPL)     │
│   delete)     │                  └──────────────┘             └────────────┘
└──────────────┘
```

**Key design points:**

| Concept | Implementation |
|---|---|
| **Index structure** | Inverted index — `HashMap<word, HashSet<file>>` |
| **Tokenizer** | Lowercase + split on non-alphanumeric chars |
| **Search** | AND semantics — files must contain *all* query words |
| **File watching** | `notify` crate with recursive directory monitoring |
| **Threading** | Watcher runs in background; main thread owns the index and REPL |
| **Updates** | Drained from channel before each prompt so the index stays current |

## Usage

```bash
# Watch current directory
cargo run .

# Watch a specific directory
cargo run ~/documents

# Then search interactively
> rust watcher
  ./src/main.rs
  (1 result(s))

> :stats
[index] 2 files, 147 unique tokens

> :quit
```

Create/edit/delete files in the watched directory while the program is running and the index updates automatically.

