                    let should_run = match job.last_run {
                        Some(last) => {
                            let elapsed = last.elapsed().unwrap(); // BUG 9: unwrap on elapsed
                            elapsed.as_secs() > job.interval_secs // BUG 10: off-by-one (>= needed)
                        }
                        None => true,
                    };

                    if should_run {
                        job.status = ReportStatus::Running;
                        // BUG 11: holding lock during long operation
                        let result = generate_report(&job);

                        match result {
                            Ok(_) => {
                                job.status = ReportStatus::Completed;
                                job.last_run = Some(SystemTime::now());
                                // BUG 12: retry_count never reset
                            }
                            Err(e) => {
                                job.retry_count += 1;
                                if job.retry_count > job.max_retries { // BUG 13: >= not >
                                    job.status = ReportStatus::Failed(e);
                                }
                                // BUG 14: no status set when retrying
                            }
                        }
                    }
                }
                // BUG 15: lock held across sleep (deadlock!)
                thread::sleep(Duration::from_secs(1));
            }
        });
    }

    fn get_status(&self, id: u64) -> Option<ReportStatus> {
        let jobs = self.jobs.lock().unwrap();
        // BUG 16: returns reference into locked data
        jobs.get(&id).map(|j| j.status)    // BUG 17: ReportStatus doesn't impl Copy
    }

    fn remove_job(&self, id: u64) {
        let jobs = self.jobs.lock().unwrap();
        jobs.remove(&id);                   // BUG 18: removing from immutable ref
    }
}

fn generate_report(job: &ReportJob) -> Result<String, String> {
    println!("Generating report: {}", job.name);
    thread::sleep(Duration::from_secs(2));

    // Simulate occasional failure
    if job.name.contains("fail") {
        Err("Report generation failed".to_string())
    } else {
        Ok(format!("Report {} completed", job.name))
    }
}

fn main() {
    let mut scheduler = Scheduler::new();

    scheduler.add_job(
        "Daily Sales".to_string(),
        ReportType::Daily,
        10,
    );

    scheduler.add_job(
        "Weekly fail Report".to_string(), // will trigger simulated failure
        ReportType::Weekly,
        20,
    );

    scheduler.start();

    // BUG 19: main thread exits immediately, killing spawned threads
}
