use std::thread::{self, JoinHandle};
use std::time::{Duration, SystemTime};

// ─── Data Types ──────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq)]
enum ReportType {
    Daily,
    Weekly,
    Monthly,
}

#[derive(Debug, Clone)]
enum ReportStatus {
    Pending,   // awaiting first run or next interval
    Running,   // currently being generated
    Completed, // last run succeeded
    Failed(String),
}

#[derive(Debug, Clone)]
struct ReportJob {
    id: u64,
    name: String,
    report_type: ReportType,
    status: ReportStatus,
    interval_secs: u64,
    last_run: Option<SystemTime>,
    retry_count: u32,
    max_retries: u32,
}

// ─── Scheduler ───────────────────────────────────────────────

struct Scheduler {
    jobs: Arc<Mutex<HashMap<u64, ReportJob>>>,
    running: Arc<AtomicBool>,          // FIX 1: AtomicBool for thread-safe flag
    next_id: Arc<AtomicU64>,           // FIX 2: AtomicU64 for thread-safe ID generation
    handle: Option<JoinHandle<()>>,    // FIX 7: store join handle for clean shutdown
}

impl Scheduler {
    fn new() -> Self {
        Scheduler {
            jobs: Arc::new(Mutex::new(HashMap::new())),
            running: Arc::new(AtomicBool::new(false)),
            next_id: Arc::new(AtomicU64::new(1)),
            handle: None,
        }
    }

    /// Register a new report job and return its unique ID.
    fn add_job(
        &self, // FIX: &self is sufficient — interior mutability via atomics + mutex
        name: String,
        report_type: ReportType,
        interval_secs: u64,
    ) -> u64 {
        // FIX 2: atomic fetch_add — no race condition
        let id = self.next_id.fetch_add(1, Ordering::SeqCst);

        let job = ReportJob {
            id,
            name,
            report_type,
            status: ReportStatus::Pending, // FIX 3: correct initial status
            interval_secs,
            last_run: None,
            retry_count: 0,
            max_retries: 3,                // FIX 4: sensible default retries
        };

        // FIX 5: use match to handle poisoned mutex gracefully
        // FIX 6: lock is mutable so we can insert
        match self.jobs.lock() {
            Ok(mut jobs) => {
                jobs.insert(id, job);
            }
            Err(poisoned) => {
                eprintln!("Mutex poisoned, recovering: {}", poisoned);
                let mut jobs = poisoned.into_inner();
                jobs.insert(id, job);
            }
        }

        id
    }

    /// Start the scheduler loop on a background thread.
    fn start(&mut self) {
        // Prevent starting twice
        if self.running.load(Ordering::SeqCst) {
            eprintln!("Scheduler is already running.");
            return;
        }

        self.running.store(true, Ordering::SeqCst);

        let jobs = Arc::clone(&self.jobs);
        let running = Arc::clone(&self.running);

        // FIX 7: store the JoinHandle so we can join on shutdown
        let handle = thread::spawn(move || {
            println!("[scheduler] Started.");

            while running.load(Ordering::SeqCst) {
                // Collect IDs of jobs that are due
                let due_jobs: Vec<ReportJob> = {
                    let jobs_lock = match jobs.lock() { // FIX 5: no unwrap
                        Ok(guard) => guard,
                        Err(poisoned) => {
                            eprintln!("Mutex poisoned, recovering.");
                            poisoned.into_inner()
                        }
                    };

                    jobs_lock
                        .values()
                        .filter(|job| {
                            // FIX 10: use >= for correct interval comparison
                            match job.last_run {
                                Some(last) => {
                                    // FIX 9: handle elapsed() error
                                    match last.elapsed() {
                                        Ok(elapsed) => elapsed.as_secs() >= job.interval_secs,
                                        Err(_) => false, // clock went backwards
                                    }
                                }
                                None => true, // never run before → due now
                            }
                        })
                        .filter(|job| {
                            // skip permanently failed jobs
                            !matches!(job.status, ReportStatus::Failed(_))
                                || job.retry_count < job.max_retries
                        })
                        .cloned()
                        .collect()
                }; // FIX 15: lock is dropped here BEFORE processing

                // FIX 11: process jobs WITHOUT holding the lock
                for job in due_jobs {
                    // Mark as Running
                    if let Ok(mut jobs_lock) = jobs.lock() {
                        if let Some(j) = jobs_lock.get_mut(&job.id) {
                            j.status = ReportStatus::Running;
                        }
                    }

                    // Do the expensive work outside the lock
                    let result = generate_report(&job);

                    // Update status after completion
                    if let Ok(mut jobs_lock) = jobs.lock() {
                        if let Some(j) = jobs_lock.get_mut(&job.id) {
                            match result {
                                Ok(msg) => {
                                    println!("[scheduler] ✓ {}", msg);
                                    j.status = ReportStatus::Completed;
                                    j.last_run = Some(SystemTime::now());
                                    j.retry_count = 0; // FIX 12: reset retries on success
                                }
                                Err(e) => {
                                    j.retry_count += 1;
                                    // FIX 13: >= to include the last attempt
                                    if j.retry_count >= j.max_retries {
                                        println!(
                                            "[scheduler] ✗ {} permanently failed: {}",
                                            j.name, e
                                        );
                                        j.status = ReportStatus::Failed(e);
                                    } else {
                                        // FIX 14: set Pending so it gets retried
                                        println!(
                                            "[scheduler] ⟳ {} retry {}/{}: {}",
                                            j.name, j.retry_count, j.max_retries, e
                                        );
                                        j.status = ReportStatus::Pending;
                                        j.last_run = Some(SystemTime::now());
                                    }
                                }
                            }
                        }
                    }
                }

                // Sleep with lock released
                thread::sleep(Duration::from_secs(1));
            }

            println!("[scheduler] Stopped.");
        });

        self.handle = Some(handle);
    }

    /// Gracefully stop the scheduler and wait for the thread to finish.
    fn stop(&mut self) {
        self.running.store(false, Ordering::SeqCst);
        if let Some(handle) = self.handle.take() {
            handle.join().expect("Scheduler thread panicked");
        }
    }

    /// Get the status of a job by ID.
    fn get_status(&self, id: u64) -> Option<ReportStatus> {
        // FIX 5, 16, 17: clone the status so we don't hold a ref into the lock
        match self.jobs.lock() {
            Ok(jobs) => jobs.get(&id).map(|j| j.status.clone()),
            Err(poisoned) => poisoned.into_inner().get(&id).map(|j| j.status.clone()),
        }
    }

    /// Remove a job by ID. Returns true if found and removed.
    fn remove_job(&self, id: u64) -> bool {
        // FIX 18: get a mutable lock guard
        match self.jobs.lock() {
            Ok(mut jobs) => jobs.remove(&id).is_some(),
            Err(poisoned) => poisoned.into_inner().remove(&id).is_some(),
        }
    }

    /// List all registered jobs (snapshot).
    fn list_jobs(&self) -> Vec<ReportJob> {
        match self.jobs.lock() {
            Ok(jobs) => jobs.values().cloned().collect(),
            Err(poisoned) => poisoned.into_inner().values().cloned().collect(),
        }
    }
}

// Clean shutdown if the scheduler is dropped
impl Drop for Scheduler {
    fn drop(&mut self) {
        self.stop();
    }
}

