# Simple Document Parser in Rust

This parser handles a lightweight markup format with **headers**, **paragraphs**, **list items**, and **key: value metadata**.

```rust
// src/lib.rs

use std::fmt;

// ──────────────────────────── Data Types ────────────────────────────

/// Represents a single parsed element in a document.
#[derive(Debug, Clone, PartialEq)]
pub enum Element {
    Header { level: u8, text: String },
    Paragraph(String),
    ListItem(String),
    MetaData { key: String, value: String },
    BlankLine,
}

/// A fully parsed document — a sequence of `Element`s.
#[derive(Debug, Clone, PartialEq)]
pub struct Document {
    pub elements: Vec<Element>,
}

/// Errors that can occur during parsing.
#[derive(Debug, Clone, PartialEq)]
pub enum ParseError {
    InvalidHeader(usize),      // line number
    EmptyDocument,
    InvalidMetadata(usize),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::InvalidHeader(line) => {
                write!(f, "Invalid header at line {line}")
            }
            ParseError::EmptyDocument => {
                write!(f, "Document is empty")
            }
            ParseError::InvalidMetadata(line) => {
                write!(f, "Invalid metadata at line {line}")
            }
        }
    }
}

impl std::error::Error for ParseError {}

// ──────────────────────────── Parser ────────────────────────────────

impl Document {
    /// Parse raw text into a `Document`.
    pub fn parse(input: &str) -> Result<Self, ParseError> {
        let trimmed = input.trim();
        if trimmed.is_empty() {
            return Err(ParseError::EmptyDocument);
        }

        let mut elements = Vec::new();

        for (idx, raw_line) in input.lines().enumerate() {
            let line = raw_line.trim();
            let line_number = idx + 1;

            if line.is_empty() {
                elements.push(Element::BlankLine);
                continue;
            }

            let element = if line.starts_with('#') {
                Self::parse_header(line, line_number)?
            } else if line.starts_with('-') || line.starts_with('*') {
                Self::parse_list_item(line)
            } else if let Some(meta) = Self::try_parse_metadata(line, line_number)? {
                meta
            } else {
                Element::Paragraph(line.to_string())
            };

            elements.push(element);
        }

        Ok(Document { elements })
    }

    // ── helpers ────

    fn parse_header(line: &str, line_number: usize) -> Result<Element, ParseError> {
        let hashes = line.chars().take_while(|&c| c == '#').count();

        if !(1..=6).contains(&hashes) {
            return Err(ParseError::InvalidHeader(line_number));
        }

        let text = line[hashes..].trim().to_string();
        if text.is_empty() {
            return Err(ParseError::InvalidHeader(line_number));
        }

        Ok(Element::Header {
            level: hashes as u8,
            text,
        })
    }

    fn parse_list_item(line: &str) -> Element {
        let text = line[1..].trim().to_string();
        Element::ListItem(text)
    }

    fn try_parse_metadata(
        line: &str,
        _line_number: usize,
    ) -> Result<Option<Element>, ParseError> {
        // Only treat "word: value" at most‑one‑word keys as metadata.
        if let Some((key, value)) = line.split_once(':') {
            let key = key.trim();
            let value = value.trim();

            // Key must be a single word (no spaces) and non‑empty.
            if !key.is_empty() && !key.contains(' ') && !value.is_empty() {
                return Ok(Some(Element::MetaData {
                    key: key.to_string(),
                    value: value.to_string(),
                }));
            }
        }
        Ok(None)
    }

    // ──────────────────────── Convenience queries ───────────────────

    /// Return all headers in the document.
    pub fn headers(&self) -> Vec<&Element> {
        self.elements
            .iter()
            .filter(|e| matches!(e, Element::Header { .. }))
            .collect()
    }

    /// Return all list items.
    pub fn list_items(&self) -> Vec<&str> {
        self.elements
            .iter()
            .filter_map(|e| match e {
                Element::ListItem(text) => Some(text.as_str()),
                _ => None,
            })
            .collect()
    }

    /// Look up the first metadata value for `key`.
    pub fn meta(&self, key: &str) -> Option<&str> {
        self.elements.iter().find_map(|e| match e {
            Element::MetaData { key: k, value } if k == key => Some(value.as_str()),
            _ => None,
        })
    }

    /// Render the parsed document back to plain text.
    pub fn to_plain_text(&self) -> String {
        let mut out = String::new();
        for el in &self.elements {
            match el {
                Element::Header { level, text } => {
                    let prefix = "#".repeat(*level as usize);
                    out.push_str(&format!("{prefix} {text}\n"));
                }
                Element::Paragraph(text) => {
                    out.push_str(&format!("{text}\n"));
                }
                Element::ListItem(text) => {
                    out.push_str(&format!("- {text}\n"));
                }
                Element::MetaData { key, value } => {
                    out.push_str(&format!("{key}: {value}\n"));
                }
                Element::BlankLine => out.push('\n'),
            }
        }
        out
    }
}

// ──────────────────────────── Display ───────────────────────────────

impl fmt::Display for Document {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_plain_text())
    }
}

// ──────────────────────────── Tests ─────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    // ── Sample input used across multiple tests ──

    const SAMPLE: &str = "\
author: Alice
date: 2025-01-15

# Welcome

This is the introduction.

## Features

- Fast parsing
- Simple API
* Easy to extend

Enjoy!
";

    // ── Parsing ─────────────────────────────────

    #[test]
    fn test_parse_full_document() {
        let doc = Document::parse(SAMPLE).unwrap();
        // metadata + blank + h1 + blank + para + blank + h2 + blank + 3 list + blank + para
        assert_eq!(doc.elements.len(), 13);
    }

    #[test]
    fn test_parse_headers() {
        let doc = Document::parse(SAMPLE).unwrap();
        let headers = doc.headers();
        assert_eq!(headers.len(), 2);
        assert_eq!(
            headers[0],
            &Element::Header { level: 1, text: "Welcome".into() }
        );
        assert_eq!(
            headers[1],
            &Element::Header { level: 2, text: "Features".into() }
        );
    }

    #[test]
    fn test_parse_list_items() {
        let doc = Document::parse(SAMPLE).unwrap();
        let items = doc.list_items();
        assert_eq!(items, vec!["Fast parsing", "Simple API", "Easy to extend"]);
    }

    #[test]
    fn test_parse_metadata() {
        let doc = Document::parse(SAMPLE).unwrap();
        assert_eq!(doc.meta("author"), Some("Alice"));
        assert_eq!(doc.meta("date"), Some("2025-01-15"));
        assert_eq!(doc.meta("missing"), None);
    }

    #[test]
    fn test_paragraph() {
        let doc = Document::parse(SAMPLE).unwrap();
        let paragraphs: Vec<_> = doc
            .elements
            .iter()
            .filter(|e| matches!(e, Element::Paragraph(_)))
            .collect();
        assert_eq!(paragraphs.len(), 2);
        assert_eq!(
            paragraphs[0],
            &Element::Paragraph("This is the introduction.".into())
        );
    }

    // ── Header levels ───────────────────────────

    #[test]
    fn test_header_levels_1_through_6() {
        let input = "# H1\n## H2\n### H3\n#### H4\n##### H5\n###### H6";
        let doc = Document::parse(input).unwrap();
        for (i, el) in doc.elements.iter().enumerate() {
            let expected_level = (i + 1) as u8;
            match el {
                Element::Header { level, .. } => assert_eq!(*level, expected_level),
                other => panic!("Expected header, got {other:?}"),
            }
        }
    }

    #[test]
    fn test_header_level_too_deep() {
        let input = "####### TooDeep";
        let err = Document::parse(input).unwrap_err();
        assert_eq!(err, ParseError::InvalidHeader(1));
    }

    #[test]
    fn test_header_no_text() {
        let err = Document::parse("## ").unwrap_err();
        assert_eq!(err, ParseError::InvalidHeader(1));
    }

    // ── Edge cases ──────────────────────────────

    #[test]
    fn test_empty_document() {
        let err = Document::parse("").unwrap_err();
        assert_eq!(err, ParseError::EmptyDocument);
    }

    #[test]
    fn test_whitespace_only_is_empty() {
        let err = Document::parse("   \n  \n  ").unwrap_err();
