        assert_eq!(doc.elements.len(), 1);
        assert_eq!(
            doc.elements[0],
            Element::Paragraph("Hello, world!".into())
        );
    }

    // ── Round‑trip ──────────────────────────────

    #[test]
    fn test_round_trip_plain_text() {
        let input = "# Title\n\n- one\n- two\n\nSome text.\n";
        let doc = Document::parse(input).unwrap();
        let output = doc.to_plain_text();
        assert_eq!(output, input);
    }

