    timestamp: u64,
    value: f64,
}

#[derive(Debug, Clone)]
struct TransformedEvent {
    user_id: String,
    event_type: String,
    timestamp: u64,
    normalized_value: f64,
    category: String,
}

#[derive(Debug, Clone)]
struct AggregatedResult {
    category: String,
    event_count: usize,
    total_value: f64,
    avg_value: f64,
}

#[derive(Debug)]
struct DeliveryReport {
    results_delivered: usize,
    destination: String,
}

// ── Retry Configuration ─────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct RetryConfig {
    max_attempts: u32,
    base_delay_ms: u64,
    backoff_multiplier: u64,
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            max_attempts: 3,
            base_delay_ms: 100,
            backoff_multiplier: 2,
        }
    }
}

/// Generic retry wrapper with exponential backoff
fn retry_with_backoff<T, E: fmt::Display>(
    config: &RetryConfig,
    stage_name: &str,
    operation: impl Fn() -> Result<T, E>,
) -> Result<T, E> {
    let mut attempt = 0;
    loop {
        attempt += 1;
        match operation() {
            Ok(result) => {
                if attempt > 1 {
                    println!("  ✓ [{stage_name}] Succeeded on attempt {attempt}");
                }
                return Ok(result);
            }
            Err(e) => {
                if attempt >= config.max_attempts {
                    println!(
                        "  ✗ [{stage_name}] Failed after {attempt} attempts: {e}"
                    );
                    return Err(e);
                }
                let delay = config.base_delay_ms * config.backoff_multiplier.pow(attempt - 1);
                println!(
                    "  ⟳ [{stage_name}] Attempt {attempt} failed: {e} — retrying in {delay}ms..."
                );
                thread::sleep(Duration::from_millis(delay));
            }
        }
    }
}

// ── Pipeline Stages ─────────────────────────────────────────────────────────

/// Simulates ingestion that may fail intermittently
fn ingest_events(fail_counter: &mut u32) -> Result<Vec<RawEvent>, PipelineError> {
    // Simulate transient failure on first call
    if *fail_counter < 1 {
        *fail_counter += 1;
        return Err(PipelineError::Ingestion("Connection timeout".into()));
    }

    Ok(vec![
        RawEvent {
            user_id: "u001".into(),
            event_type: "page_view".into(),
            timestamp: 1700000000,
            value: 1.0,
        },
        RawEvent {
            user_id: "u002".into(),
            event_type: "purchase".into(),
            timestamp: 1700000010,
            value: 49.99,
        },
        RawEvent {
            user_id: "u001".into(),
            event_type: "purchase".into(),
            timestamp: 1700000020,
            value: 25.50,
        },
        RawEvent {
            user_id: "u003".into(),
            event_type: "page_view".into(),
            timestamp: 1700000030,
            value: 1.0,
        },
        RawEvent {
            user_id: "u002".into(),
            event_type: "signup".into(),
            timestamp: 1700000040,
            value: 0.0,
        },
    ])
}

/// Transforms and enriches raw events
fn transform_events(
    raw_events: &[RawEvent],
) -> Result<Vec<TransformedEvent>, PipelineError> {
    let transformed: Vec<TransformedEvent> = raw_events
        .iter()
        .map(|event| {
            let category = match event.event_type.as_str() {
                "page_view" => "engagement",
                "purchase" => "revenue",
                "signup" => "acquisition",
                _ => "other",
            };
            let max_val = if category == "revenue" { 1000.0 } else { 100.0 };
            TransformedEvent {
                user_id: event.user_id.clone(),
                event_type: event.event_type.clone(),
                timestamp: event.timestamp,
                normalized_value: event.value / max_val,
                category: category.into(),
            }
        })
        .collect();

    if transformed.is_empty() {
        return Err(PipelineError::Transform("No events to transform".into()));
    }

    Ok(transformed)
}

/// Aggregates transformed events by category
fn aggregate_events(
    events: &[TransformedEvent],
) -> Result<Vec<AggregatedResult>, PipelineError> {
    use std::collections::HashMap;

    let mut groups: HashMap<&str, Vec<&TransformedEvent>> = HashMap::new();
    for event in events {
        groups.entry(&event.category).or_default().push(event);
    }

    if groups.is_empty() {
        return Err(PipelineError::Aggregation("No data to aggregate".into()));
    }

    let results = groups
        .into_iter()
        .map(|(category, group)| {
            let total: f64 = group.iter().map(|e| e.normalized_value).sum();
            let count = group.len();
            AggregatedResult {
                category: category.into(),
                event_count: count,
                total_value: total,
                avg_value: total / count as f64,
            }
        })
        .collect();

    Ok(results)
}

/// Simulates delivery that may fail
fn deliver_results(
    results: &[AggregatedResult],
    fail_counter: &mut u32,
) -> Result<DeliveryReport, PipelineError> {
    // Simulate two transient failures before success
    if *fail_counter < 2 {
        *fail_counter += 1;
        return Err(PipelineError::Delivery("Remote service unavailable".into()));
    }

    Ok(DeliveryReport {
        results_delivered: results.len(),
        destination: "analytics-warehouse".into(),
    })
}

// ── Pipeline Orchestrator ───────────────────────────────────────────────────

struct AnalyticsPipeline {
    retry_config: RetryConfig,
}

impl AnalyticsPipeline {
    fn new(retry_config: RetryConfig) -> Self {
        Self { retry_config }
    }

    fn run(&self) -> Result<DeliveryReport, PipelineError> {
        // Stage 1: Ingest
        println!("\n🔷 Stage 1: Ingestion");
        let mut ingest_fail_counter = 0u32;
        let raw_events = retry_with_backoff(&self.retry_config, "Ingest", || {
            ingest_events(&mut ingest_fail_counter)
        })?;
        println!("  Ingested {} raw events", raw_events.len());

        // Stage 2: Transform
        println!("\n🔷 Stage 2: Transformation");
        let transformed = retry_with_backoff(&self.retry_config, "Transform", || {
            transform_events(&raw_events)
        })?;
        println!("  Transformed {} events", transformed.len());

        // Stage 3: Aggregate
        println!("\n🔷 Stage 3: Aggregation");
        let aggregated = retry_with_backoff(&self.retry_config, "Aggregate", || {
            aggregate_events(&transformed)
        })?;
        println!("  Produced {} aggregated results:", aggregated.len());
        for result in &aggregated {
            println!(
                "    • {}: count={}, total={:.4}, avg={:.4}",
                result.category, result.event_count, result.total_value, result.avg_value
            );
        }

        // Stage 4: Deliver
        println!("\n🔷 Stage 4: Delivery");
        let mut deliver_fail_counter = 0u32;
        let report = retry_with_backoff(&self.retry_config, "Deliver", || {
            deliver_results(&aggregated, &mut deliver_fail_counter)
        })?;

        Ok(report)
    }
}

// ── Main ────────────────────────────────────────────────────────────────────

fn main() {
    println!("═══════════════════════════════════════════");
    println!("  Analytics Pipeline with Retry Logic");
    println!("═══════════════════════════════════════════");

    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 50,
        backoff_multiplier: 2,
    };

    let pipeline = AnalyticsPipeline::new(config);

    match pipeline.run() {
        Ok(report) => {
            println!("\n✅ Pipeline completed successfully!");
            println!("   Delivered {} result(s) to '{}'",
                report.results_delivered, report.destination
            );
        }
        Err(e) => {
            println!("\n❌ Pipeline failed: {e}");
            std::process::exit(1);
        }
    }
}
```

## How It Works

```
┌──────────────┐     ┌───────────────┐     ┌─────────────┐     ┌──────────┐
│  Ingestion   │────▶│ Transformation│────▶│ Aggregation │────▶│ Delivery │
│  (retry ×5)  │     │  (retry ×5)   │     │  (retry ×5) │     │(retry ×5)│
└──────────────┘     └───────────────┘     └─────────────┘     └──────────┘
       │                                                              │
       ▼                                                              ▼
  Simulates 1             Categorizes &                     Simulates 2
  transient failure       normalizes values                 transient failures
```

## Key Design Points

| Concept | Implementation |
|---|---|
| **Generic retry** | `retry_with_backoff<T, E>` works with any fallible operation |
| **Exponential backoff** | Delay doubles each attempt: `base × multiplier^(attempt-1)` |
| **Typed errors** | Each stage has its own `PipelineError` variant |
| **Stage isolation** | Each stage returns a clean `Result`; failures don't leak |
| **Config-driven** | `RetryConfig` controls attempts, delay, and multiplier |

