```

## Source Code

```rust
// src/main.rs
use notify::{Config, Event, EventKind, RecommendedWatcher, RecursiveMode, Watcher};
use std::collections::HashSet;
use std::fs::File;
use std::io::{BufRead, BufReader, Seek, SeekFrom};
use std::path::Path;
use std::sync::mpsc;
use std::time::Instant;

/// Holds moderation rules and state
struct Moderator {
    banned_words: HashSet<String>,
    max_caps_ratio: f64,
    max_message_length: usize,
    spam_window_secs: u64,
    spam_max_messages: usize,
    recent_messages: Vec<(String, Instant)>,
}

/// Result of checking a single message
enum Violation {
    BannedWord(String),
    ExcessiveCaps,
    MessageTooLong,
    Spam,
}

impl std::fmt::Display for Violation {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Violation::BannedWord(word) => write!(f, "banned word: \"{}\"", word),
            Violation::ExcessiveCaps => write!(f, "excessive caps"),
            Violation::MessageTooLong => write!(f, "message too long"),
            Violation::Spam => write!(f, "spam detected"),
        }
    }
}

impl Moderator {
    fn new() -> Self {
        let banned_words: HashSet<String> = [
            "badword1", "badword2", "slur1", "toxicphrase",
        ]
        .iter()
        .map(|w| w.to_lowercase())
        .collect();

        Self {
            banned_words,
            max_caps_ratio: 0.7,
            max_message_length: 500,
            spam_window_secs: 10,
            spam_max_messages: 5,
            recent_messages: Vec::new(),
        }
    }

    /// Check a chat line for all rule violations
    fn check(&mut self, line: &str) -> Vec<Violation> {
        // Expected format: "username: message"
        let message = match line.split_once(':') {
            Some((_, msg)) => msg.trim(),
            None => line.trim(),
        };

        let mut violations = Vec::new();

        // 1. Banned words
        let lower = message.to_lowercase();
        for word in &self.banned_words {
            if lower.contains(word.as_str()) {
                violations.push(Violation::BannedWord(word.clone()));
            }
        }

        // 2. Excessive caps (only check messages with enough letters)
        let letters: Vec<char> = message.chars().filter(|c| c.is_alphabetic()).collect();
        if letters.len() > 5 {
            let upper_count = letters.iter().filter(|c| c.is_uppercase()).count();
            let ratio = upper_count as f64 / letters.len() as f64;
            if ratio > self.max_caps_ratio {
                violations.push(Violation::ExcessiveCaps);
            }
        }

        // 3. Message length
        if message.len() > self.max_message_length {
            violations.push(Violation::MessageTooLong);
        }

        // 4. Spam detection (too many messages in short window)
        let now = Instant::now();
        self.recent_messages.push((message.to_string(), now));
        self.recent_messages
            .retain(|(_, t)| now.duration_since(*t).as_secs() < self.spam_window_secs);

        if self.recent_messages.len() > self.spam_max_messages {
            violations.push(Violation::Spam);
        }

        violations
    }
}

/// Watches the file and processes only newly appended lines
struct FileWatcher {
    path: String,
    last_position: u64,
    moderator: Moderator,
}

impl FileWatcher {
    fn new(path: &str) -> Self {
        // Start at end of file so we only process new lines
        let position = std::fs::metadata(path).map(|m| m.len()).unwrap_or(0);

        Self {
            path: path.to_string(),
            last_position: position,
            moderator: Moderator::new(),
        }
    }

    /// Read and moderate any new lines appended since last check
    fn process_new_lines(&mut self) {
        let file = match File::open(&self.path) {
            Ok(f) => f,
            Err(e) => {
                eprintln!("[error] cannot open file: {}", e);
                return;
            }
        };

        let mut reader = BufReader::new(file);
        if reader.seek(SeekFrom::Start(self.last_position)).is_err() {
            return;
        }

        let mut line = String::new();
        while reader.read_line(&mut line).unwrap_or(0) > 0 {
            let trimmed = line.trim();
            if !trimmed.is_empty() {
                self.moderate_line(trimmed);
            }
            line.clear();
        }

        self.last_position = reader.stream_position().unwrap_or(self.last_position);
    }

    fn moderate_line(&mut self, line: &str) {
        let violations = self.moderator.check(line);

        if violations.is_empty() {
            println!("[  ok  ] {}", line);
        } else {
            let reasons: Vec<String> = violations.iter().map(|v| v.to_string()).collect();
            println!("[FLAGGED] {} --> [{}]", line, reasons.join(", "));
        }
    }
}

fn main() {
    let chat_file = "chat.log";

    // Create the file if it doesn't exist
    if !Path::new(chat_file).exists() {
        File::create(chat_file).expect("failed to create chat.log");
        println!("Created {}", chat_file);
    }

    let mut file_watcher = FileWatcher::new(chat_file);

    // Set up filesystem event watcher
    let (tx, rx) = mpsc::channel();

    let mut watcher = RecommendedWatcher::new(
        move |result: Result<Event, notify::Error>| {
            if let Ok(event) = result {
                let _ = tx.send(event);
            }
        },
        Config::default(),
    )
    .expect("failed to create watcher");

    watcher
        .watch(Path::new(chat_file), RecursiveMode::NonRecursive)
        .expect("failed to watch file");

    println!("Watching {} for new chat messages...", chat_file);
    println!("Append lines to the file to test moderation.");
    println!("Format: \"username: message\"");
    println!("---");

    // Event loop
    for event in rx {
        if matches!(event.kind, EventKind::Modify(_)) {
            file_watcher.process_new_lines();
        }
    }
}
```

## How It Works

```
┌──────────────┐     append      ┌────────────┐
│  Chat source │ ──────────────► │  chat.log  │
└──────────────┘                 └─────┬──────┘
                                       │ fs event (notify)
                                       ▼
                               ┌───────────────┐
                               │  FileWatcher   │
                               │  (tail mode)   │
                               └───────┬───────┘
                                       │ new lines
                                       ▼
                               ┌───────────────┐
                               │   Moderator    │
                               │                │
                               │ • banned words │
                               │ • caps check   │
                               │ • length check │
                               │ • spam detect  │
                               └───────┬───────┘
                                       │
                              ┌────────┴────────┐
                              ▼                 ▼
                          [  ok  ]         [FLAGGED]
```

## Testing

Run it in one terminal:
```bash
cargo run
```

Append messages in another terminal:
```bash
echo "alice: Hello everyone!" >> chat.log
echo "bob: THIS IS ALL CAPS AND LOUD" >> chat.log
echo "charlie: you are a badword1" >> chat.log
echo "spammer: buy now" >> chat.log
echo "spammer: buy now" >> chat.log
echo "spammer: buy now" >> chat.log
echo "spammer: buy now" >> chat.log
echo "spammer: buy now" >> chat.log
echo "spammer: buy now" >> chat.log
```

Expected output:
```
[  ok  ] alice: Hello everyone!
[FLAGGED] bob: THIS IS ALL CAPS AND LOUD --> [excessive caps]
[FLAGGED] charlie: you are a badword1 --> [banned word: "badword1"]
[  ok  ] spammer: buy now
[  ok  ] spammer: buy now
...
[FLAGGED] spammer: buy now --> [spam detected]
```

## Key Design Decisions

- **Tail mode** — seeks to end of file on startup so only new messages are checked
- **`notify` crate** — uses OS-level filesystem events (`inotify`/`kqueue`/`ReadDirectoryChanges`) instead of polling
- **Stateful spam detection** — tracks recent messages with timestamps and a sliding window
- **Multiple violations per message** — a single line can trigger more than one rule

