        write!(
            f,
            "[{}] {} | {:?} | user={} action={} resource={}{}",
            self.id[..8].to_string(),
            self.timestamp.format("%Y-%m-%d %H:%M:%S UTC"),
            self.severity,
            self.user,
            self.action,
            self.resource,
            self.details
