```rust
use crate::models::{AuditEntry, Severity};
use std::fs::{self, OpenOptions};
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};

pub struct AuditLogger {
    log_path: PathBuf,
}

#[derive(Debug)]
pub struct QueryFilter {
    pub user: Option<String>,
    pub action: Option<String>,
    pub resource: Option<String>,
    pub severity: Option<Severity>,
    pub limit: usize,
}

impl AuditLogger {
    pub fn new(log_path: &Path) -> std::io::Result<Self> {
        // Ensure parent directory exists
        if let Some(parent) = log_path.parent() {
            fs::create_dir_all(parent)?;
        }

        // Create file if it doesn't exist
        if !log_path.exists() {
            fs::File::create(log_path)?;
        }

        Ok(Self {
            log_path: log_path.to_path_buf(),
        })
    }

    /// Append a single audit entry (JSON Lines format)
    pub fn log(&self, entry: &AuditEntry) -> std::io::Result<()> {
        let mut file = OpenOptions::new()
            .append(true)
            .open(&self.log_path)?;

        let json = serde_json::to_string(entry)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;

        writeln!(file, "{}", json)?;
        Ok(())
    }

    /// Read all entries from the log file
    pub fn read_all(&self) -> std::io::Result<Vec<AuditEntry>> {
        let file = fs::File::open(&self.log_path)?;
        let reader = BufReader::new(file);
        let mut entries = Vec::new();

        for (line_num, line) in reader.lines().enumerate() {
            let line = line?;
            if line.trim().is_empty() {
                continue;
            }
            match serde_json::from_str::<AuditEntry>(&line) {
                Ok(entry) => entries.push(entry),
                Err(e) => {
                    eprintln!("Warning: skipping malformed line {}: {}", line_num + 1, e);
                }
            }
        }

        Ok(entries)
    }

    /// Query entries with filters
    pub fn query(&self, filter: &QueryFilter) -> std::io::Result<Vec<AuditEntry>> {
        let all = self.read_all()?;

        let filtered: Vec<AuditEntry> = all
            .into_iter()
            .filter(|e| {
                if let Some(ref user) = filter.user {
                    if !e.user.to_lowercase().contains(&user.to_lowercase()) {
                        return false;
                    }
                }
                if let Some(ref action) = filter.action {
                    if !e.action.to_lowercase().contains(&action.to_lowercase()) {
                        return false;
                    }
                }
                if let Some(ref resource) = filter.resource {
                    if !e.resource.to_lowercase().contains(&resource.to_lowercase()) {
                        return false;
                    }
                }
                if let Some(ref severity) = filter.severity {
                    if &e.severity != severity {
                        return false;
                    }
                }
                true
            })
            .collect();

        // Return last N entries (most recent)
        let start = filtered.len().saturating_sub(filter.limit);
        Ok(filtered[start..].to_vec())
    }

    /// Return total entry count
    pub fn count(&self) -> std::io::Result<usize> {
        Ok(self.read_all()?.len())
    }

    /// Export all entries as pretty JSON array
    pub fn export_json(&self) -> std::io::Result<String> {
        let entries = self.read_all()?;
        serde_json::to_string_pretty(&entries)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))
    }
}
