struct Cli {
    /// Path to the audit log file
    #[arg(short, long, default_value = "audit.jsonl", global = true)]
    file: PathBuf,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Record a new audit event
    Log {
        /// Who performed the action
        #[arg(short, long)]
        user: String,

        /// What action was performed
        #[arg(short, long)]
        action: String,

        /// Which resource was affected
        #[arg(short, long)]
        resource: String,

        /// Optional details or description
        #[arg(short, long)]
        details: Option<String>,

        /// Severity level: low, medium, high, critical
        #[arg(short, long, default_value = "low")]
        severity: Severity,
    },

    /// List audit log entries
    List {
        /// Filter by user (substring match)
        #[arg(short, long)]
        user: Option<String>,

        /// Filter by action (substring match)
        #[arg(short, long)]
        action: Option<String>,

        /// Filter by resource (substring match)
        #[arg(short, long)]
        resource: Option<String>,

        /// Filter by severity
        #[arg(short, long)]
        severity: Option<Severity>,

        /// Max number of entries to show
        #[arg(short, long, default_value = "50")]
        limit: usize,
    },

    /// Show summary statistics
    Stats,

    /// Export the full log as a JSON array
    Export,
}

fn main() {
    let cli = Cli::parse();

    let logger = match AuditLogger::new(&cli.file) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("Error opening log file: {}", e);
            std::process::exit(1);
        }
    };

    match cli.command {
        Commands::Log {
            user,
            action,
            resource,
            details,
            severity,
        } => handle_log(&logger, user, action, resource, details, severity),
        Commands::List {
            user,
            action,
            resource,
            severity,
            limit,
        } => handle_list(&logger, user, action, resource, severity, limit),
        Commands::Stats => handle_stats(&logger),
        Commands::Export => handle_export(&logger),
    }
}

fn handle_log(
    logger: &AuditLogger,
    user: String,
    action: String,
    resource: String,
    details: Option<String>,
    severity: Severity,
) {
    let entry = models::AuditEntry::new(user, action, resource, details, severity);

    match logger.log(&entry) {
        Ok(()) => println!("✓ Logged: {}", entry),
        Err(e) => {
            eprintln!("Error writing audit entry: {}", e);
            std::process::exit(1);
        }
    }
}

fn handle_list(
    logger: &AuditLogger,
    user: Option<String>,
    action: Option<String>,
    resource: Option<String>,
    severity: Option<Severity>,
    limit: usize,
) {
    let filter = QueryFilter {
        user,
        action,
        resource,
        severity,
        limit,
    };

    match logger.query(&filter) {
        Ok(entries) => {
            if entries.is_empty() {
                println!("No matching audit entries found.");
                return;
            }
            println!("--- Audit Log ({} entries) ---\n", entries.len());
            for entry in &entries {
                println!("{}", entry);
            }
        }
        Err(e) => {
            eprintln!("Error reading log: {}", e);
            std::process::exit(1);
        }
    }
}

fn handle_stats(logger: &AuditLogger) {
    let entries = match logger.read_all() {
        Ok(e) => e,
        Err(e) => {
            eprintln!("Error reading log: {}", e);
            std::process::exit(1);
        }
    };

    if entries.is_empty() {
        println!("Audit log is empty.");
        return;
    }

    let total = entries.len();
    let low = entries.iter().filter(|e| e.severity == Severity::Low).count();
    let medium = entries.iter().filter(|e| e.severity == Severity::Medium).count();
    let high = entries.iter().filter(|e| e.severity == Severity::High).count();
    let critical = entries.iter().filter(|e| e.severity == Severity::Critical).count();

    // Unique users
    let mut users: Vec<String> = entries.iter().map(|e| e.user.clone()).collect();
    users.sort();
    users.dedup();

    // Unique actions
    let mut actions: Vec<String> = entries.iter().map(|e| e.action.clone()).collect();
    actions.sort();
    actions.dedup();

    let oldest = entries.first().unwrap().timestamp;
    let newest = entries.last().unwrap().timestamp;

    println!("=== Audit Log Statistics ===\n");
    println!("Total entries : {}", total);
    println!("Date range    : {} → {}", oldest.format("%Y-%m-%d"), newest.format("%Y-%m-%d"));
    println!();
    println!("By severity:");
    println!("  Low      : {}", low);
    println!("  Medium   : {}", medium);
    println!("  High     : {}", high);
    println!("  Critical : {}", critical);
    println!();
    println!("Unique users  : {} ({:?})", users.len(), users);
    println!("Unique actions: {} ({:?})", actions.len(), actions);
}

fn handle_export(logger: &AuditLogger) {
    match logger.export_json() {
        Ok(json) => println!("{}", json),
        Err(e) => {
            eprintln!("Error exporting log: {}", e);
            std::process::exit(1);
        }
    }
}
```

