## `src/validator.ts` — Validate Raw Entries

```typescript
import { LogLevel, RawLogEntry } from "./types";

export class LogValidator {
  private static validLevels = new Set(Object.values(LogLevel));

  /**
   * Checks if a raw entry has all required fields and correct types.
   * Returns an error message string if invalid, or null if valid.
   */
  static validate(entry: RawLogEntry): string | null {
    // --- timestamp ---
    if (!entry.timestamp) {
      return "Missing required field: timestamp";
    }
    const parsed = new Date(entry.timestamp);
    if (isNaN(parsed.getTime())) {
      return `Invalid timestamp: "${entry.timestamp}"`;
    }

    // --- level ---
    if (!entry.level) {
      return "Missing required field: level";
    }
    const upperLevel = entry.level.toUpperCase();
    if (!this.validLevels.has(upperLevel as LogLevel)) {
      return `Invalid log level: "${entry.level}". Must be one of: ${[...this.validLevels].join(", ")}`;
    }

    // --- message ---
    if (!entry.message || entry.message.trim().length === 0) {
      return "Missing or empty required field: message";
    }

    return null; // valid
  }

  /**
   * Normalise the level string to the LogLevel enum value.
   */
  static normalizeLevel(level: string): LogLevel {
    return level.toUpperCase() as LogLevel;
  }
}
