## `src/store.ts` — In-Memory Log Store

```typescript
import { LogEntry, LogLevel } from "./types";

export class LogStore {
  private logs: LogEntry[] = [];

  /** Append a single validated log entry. */
  add(entry: LogEntry): void {
    this.logs.push(entry);
  }

  /** Return all stored logs. */
  getAll(): LogEntry[] {
    return [...this.logs];
  }

  /** Filter logs by level. */
  getByLevel(level: LogLevel): LogEntry[] {
    return this.logs.filter((log) => log.level === level);
  }

  /** Filter logs by service name. */
  getByService(service: string): LogEntry[] {
    return this.logs.filter((log) => log.service === service);
  }

  /** Filter logs within a time range. */
  getByTimeRange(start: Date, end: Date): LogEntry[] {
    return this.logs.filter(
      (log) => log.timestamp >= start && log.timestamp <= end
    );
  }

  /** How many logs are stored. */
  get count(): number {
    return this.logs.length;
  }

  /** Breakdown count per level. */
  getStats(): Record<string, number> {
    const stats: Record<string, number> = {};
    for (const log of this.logs) {
      stats[log.level] = (stats[log.level] || 0) + 1;
    }
    return stats;
  }
}
