## `src/parser.ts` — Parse & Ingest JSON Logs

```typescript
import { randomUUID } from "crypto";
import { RawLogEntry, LogEntry, IngestionResult } from "./types";
import { LogValidator } from "./validator";
import { LogStore } from "./store";

export class LogParser {
  constructor(private store: LogStore) {}

  /**
   * Accept a JSON string that is either:
   *   • a single log object   { ... }
   *   • an array of log objects [ { ... }, { ... } ]
   *
   * Returns a summary of what was accepted / rejected.
   */
  ingest(jsonString: string): IngestionResult {
    const result: IngestionResult = {
      total: 0,
      accepted: 0,
      rejected: 0,
      errors: [],
    };

    // 1. Parse the raw JSON
    let parsed: unknown;
    try {
      parsed = JSON.parse(jsonString);
    } catch (err) {
      result.errors.push(
        `JSON parse error: ${err instanceof Error ? err.message : String(err)}`
      );
      return result;
    }

    // 2. Normalise to an array
    const entries: RawLogEntry[] = Array.isArray(parsed) ? parsed : [parsed];
    result.total = entries.length;

    // 3. Validate & store each entry
    for (let i = 0; i < entries.length; i++) {
      const raw = entries[i];
      const error = LogValidator.validate(raw);

      if (error) {
        result.rejected++;
        result.errors.push(`Entry ${i}: ${error}`);
        continue;
      }

      const logEntry: LogEntry = {
        id: randomUUID(),
        timestamp: new Date(raw.timestamp!),
        level: LogValidator.normalizeLevel(raw.level!),
        message: raw.message!,
        service: raw.service || "unknown",
        metadata: raw.metadata || {},
        ingestedAt: new Date(),
      };

      this.store.add(logEntry);
      result.accepted++;
    }

    return result;
  }
}
```

