import * as fs from "fs";
import * as readline from "readline";
import { LogStore } from "./store";
import { LogParser } from "./parser";
import { LogLevel } from "./types";

// ---------- bootstrap ----------
const store = new LogStore();
const parser = new LogParser(store);

/**
 * Ingest a JSON string and print the result summary.
 */
function processJson(source: string, json: string): void {
  console.log(`\n--- Ingesting from: ${source} ---`);
  const result = parser.ingest(json);

  console.log(`  Total entries : ${result.total}`);
  console.log(`  Accepted      : ${result.accepted}`);
  console.log(`  Rejected      : ${result.rejected}`);

  if (result.errors.length > 0) {
    console.log("  Errors:");
    result.errors.forEach((e) => console.log(`    • ${e}`));
  }
}

/**
 * Print a summary of everything stored so far.
 */
function printStoreSummary(): void {
  console.log("\n========== Store Summary ==========");
  console.log(`Total stored logs: ${store.count}`);
  console.log("Breakdown by level:", store.getStats());

  // Show the first 5 entries as a preview
  const preview = store.getAll().slice(0, 5);
  if (preview.length > 0) {
    console.log("\nFirst entries (preview):");
    preview.forEach((log) => {
      console.log(
        `  [${log.level}] ${log.timestamp.toISOString()} - ${log.service}: ${log.message}`
      );
    });
  }
}

// ---------- main ----------
async function main(): Promise<void> {
  // 1. If a file path is passed as CLI arg, ingest it
  const filePath = process.argv[2];
  if (filePath) {
    try {
      const fileContent = fs.readFileSync(filePath, "utf-8");
      processJson(filePath, fileContent);
    } catch (err) {
      console.error(`Failed to read file "${filePath}":`, err);
    }
  }

  // 2. Also ingest some hard-coded sample data for demo purposes
  const sampleJson = JSON.stringify([
    {
      timestamp: "2024-01-15T10:30:00Z",
      level: "INFO",
      message: "Application started",
      service: "api-gateway",
      metadata: { port: 3000 },
    },
    {
      timestamp: "2024-01-15T10:30:05Z",
      level: "DEBUG",
      message: "Database connection pool initialised",
      service: "user-service",
      metadata: { poolSize: 10 },
    },
    {
      timestamp: "2024-01-15T10:31:00Z",
      level: "ERROR",
      message: "Failed to connect to cache",
      service: "api-gateway",
      metadata: { host: "redis.local", retries: 3 },
    },
    {
      // intentionally bad — should be rejected
      level: "INFO",
      message: "Missing timestamp",
      service: "bad-service",
    },
    {
      timestamp: "2024-01-15T10:32:00Z",
      level: "CRITICAL", // invalid level
      message: "Something happened",
    },
  ]);

  processJson("built-in sample data", sampleJson);

  // 3. Read from stdin (line-by-line, each line is a JSON log or array)
  if (!process.stdin.isTTY) {
    console.log("\nReading JSON logs from stdin …");

    const rl = readline.createInterface({
      input: process.stdin,
      crlfDelay: Infinity,
    });

    for await (const line of rl) {
      const trimmed = line.trim();
      if (trimmed.length > 0) {
        processJson("stdin", trimmed);
      }
    }
  }

  // 4. Final summary
  printStoreSummary();

  // 5. Quick query demo
  console.log("\n--- Query: ERROR logs ---");
  const errors = store.getByLevel(LogLevel.ERROR);
  errors.forEach((log) =>
    console.log(
      `  [${log.id}] ${log.timestamp.toISOString()} ${log.service}: ${log.message}`
    )
  );
}

main().catch(console.error);
