## src/main.rs

```rust
use chrono::Local;
use glob_match::glob_match;
use notify::{Config, Event, EventKind, RecommendedWatcher, RecursiveMode, Watcher};
use serde::Deserialize;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::mpsc;
use std::time::{Duration, Instant};
use std::{collections::HashMap, env, fs};

// ── Config types ──────────────────────────────────────────────

#[derive(Debug, Deserialize, Clone)]
struct TaskDef {
    name: String,
    pattern: String,
    command: String,
    args: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct TasksConfig {
    tasks: Vec<TaskDef>,
}

// ── Task scheduler ────────────────────────────────────────────

struct Scheduler {
    tasks: Vec<TaskDef>,
    /// Tracks last run per task name to debounce rapid-fire events
    last_run: HashMap<String, Instant>,
    debounce: Duration,
}

impl Scheduler {
    fn new(tasks: Vec<TaskDef>, debounce_ms: u64) -> Self {
        Self {
            tasks,
            last_run: HashMap::new(),
            debounce: Duration::from_millis(debounce_ms),
        }
    }

    /// Find every task whose glob pattern matches `path` and execute it.
    fn handle_event(&mut self, path: &Path, kind: &EventKind) {
        let file_name = match path.file_name().and_then(|n| n.to_str()) {
            Some(n) => n,
            None => return,
        };

        let rel_path = path.to_string_lossy();
        let now = Instant::now();

        for task in &self.tasks {
            // Match glob against both the bare filename and relative path
            let matched =
                glob_match(&task.pattern, file_name) || glob_match(&task.pattern, &rel_path);

            if !matched {
                continue;
            }

            // Debounce: skip if this task ran too recently
            if let Some(last) = self.last_run.get(&task.name) {
                if now.duration_since(*last) < self.debounce {
                    continue;
                }
            }

            self.run_task(task, path, kind);
            self.last_run.insert(task.name.clone(), now);
        }
    }

    fn run_task(&self, task: &TaskDef, path: &Path, kind: &EventKind) {
        let timestamp = Local::now().format("%H:%M:%S");
        let kind_label = event_label(kind);

        println!(
            "\n[{timestamp}] ⚡ {kind_label}: {}",
            path.display()
        );
        println!("       → task: \"{}\"", task.name);
        println!(
            "       → exec: {} {}",
            task.command,
            task.args.join(" ")
        );

        match Command::new(&task.command).args(&task.args).output() {
            Ok(output) => {
                let stdout = String::from_utf8_lossy(&output.stdout);
                let stderr = String::from_utf8_lossy(&output.stderr);
                if !stdout.is_empty() {
                    println!("       → stdout: {}", stdout.trim());
                }
                if !stderr.is_empty() {
                    eprintln!("       → stderr: {}", stderr.trim());
                }
                if output.status.success() {
                    println!("       ✅ done");
                } else {
                    println!("       ❌ exit code: {}", output.status);
                }
            }
            Err(e) => eprintln!("       ❌ failed to run command: {e}"),
        }
    }
}

// ── Helpers ───────────────────────────────────────────────────

fn event_label(kind: &EventKind) -> &'static str {
    match kind {
        EventKind::Create(_) => "CREATED",
        EventKind::Modify(_) => "MODIFIED",
        EventKind::Remove(_) => "REMOVED",
        EventKind::Access(_) => "ACCESSED",
        _ => "OTHER",
    }
}

fn load_config(path: &Path) -> TasksConfig {
    let data = fs::read_to_string(path).unwrap_or_else(|e| {
        eprintln!("Failed to read {}: {e}", path.display());
        std::process::exit(1);
    });
    serde_json::from_str(&data).unwrap_or_else(|e| {
        eprintln!("Invalid JSON in {}: {e}", path.display());
        std::process::exit(1);
    })
}

// ── Main ──────────────────────────────────────────────────────

fn main() {
    // Resolve paths
    let watch_dir = env::args()
        .nth(1)
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));

    let config_path = env::args()
        .nth(2)
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("tasks.json"));

    // Load tasks
    let config = load_config(&config_path);
    println!("📋 Loaded {} task(s) from {}", config.tasks.len(), config_path.display());
    for t in &config.tasks {
        println!("   • \"{}\"  [{}] → {} {}", t.name, t.pattern, t.command, t.args.join(" "));
    }

    // Set up watcher
    let (tx, rx) = mpsc::channel::<notify::Result<Event>>();

    let mut watcher = RecommendedWatcher::new(tx, Config::default()).unwrap_or_else(|e| {
        eprintln!("Failed to create watcher: {e}");
        std::process::exit(1);
    });

    watcher
        .watch(&watch_dir, RecursiveMode::Recursive)
        .unwrap_or_else(|e| {
            eprintln!("Failed to watch {}: {e}", watch_dir.display());
            std::process::exit(1);
        });

    println!(
        "\n👀 Watching \"{}\" for changes … (Ctrl+C to stop)\n",
        watch_dir.display()
    );

    // Event loop
    let mut scheduler = Scheduler::new(config.tasks, 300);

    for event in rx {
        match event {
            Ok(ev) => {
                for path in &ev.paths {
                    scheduler.handle_event(path, &ev.kind);
                }
            }
            Err(e) => eprintln!("Watch error: {e}"),
        }
    }
}
```

