```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace JsonDocumentParser
{
    // --- Models ---

    /// <summary>
    /// Represents a parsed document with metadata and content.
    /// </summary>
    public class Document
    {
        [JsonPropertyName("title")]
        public string Title { get; set; } = string.Empty;

        [JsonPropertyName("author")]
        public string Author { get; set; } = string.Empty;

        [JsonPropertyName("date")]
        public string Date { get; set; } = string.Empty;

        [JsonPropertyName("tags")]
        public List<string> Tags { get; set; } = new();

        [JsonPropertyName("sections")]
        public List<Section> Sections { get; set; } = new();

        public override string ToString()
        {
            var tagsStr = Tags.Count > 0 ? string.Join(", ", Tags) : "None";
            var result = $"Title:    {Title}\n" +
                         $"Author:   {Author}\n" +
                         $"Date:     {Date}\n" +
                         $"Tags:     {tagsStr}\n" +
                         $"Sections: {Sections.Count}\n";

            foreach (var section in Sections)
            {
                result += $"\n  [{section.Heading}]\n  {section.Body}\n";
            }

            return result;
        }
    }

    public class Section
    {
        [JsonPropertyName("heading")]
        public string Heading { get; set; } = string.Empty;

        [JsonPropertyName("body")]
        public string Body { get; set; } = string.Empty;
    }

    // --- Parser ---

    /// <summary>
    /// Handles reading and parsing JSON into Document objects.
    /// </summary>
    public class JsonDocumentParser
    {
        private readonly JsonSerializerOptions _options;

        public JsonDocumentParser()
        {
            _options = new JsonSerializerOptions
            {
                PropertyNameCaseInsensitive = true,
                ReadCommentHandling = JsonCommentHandling.Skip,
                AllowTrailingCommas = true
            };
        }

        /// <summary>
        /// Parse a JSON string into a Document.
        /// </summary>
        public Document ParseFromString(string json)
        {
            if (string.IsNullOrWhiteSpace(json))
                throw new ArgumentException("JSON input cannot be empty.");

            return JsonSerializer.Deserialize<Document>(json, _options)
                   ?? throw new JsonException("Deserialization returned null.");
        }

        /// <summary>
        /// Parse a JSON file into a Document.
        /// </summary>
        public Document ParseFromFile(string filePath)
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException($"File not found: {filePath}");

            string json = File.ReadAllText(filePath);
            return ParseFromString(json);
        }

        /// <summary>
        /// Parse JSON into a raw dictionary (for unknown/dynamic schemas).
        /// </summary>
        public Dictionary<string, JsonElement> ParseAsDynamic(string json)
        {
            if (string.IsNullOrWhiteSpace(json))
                throw new ArgumentException("JSON input cannot be empty.");

            return JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(json, _options)
                   ?? new Dictionary<string, JsonElement>();
        }

        /// <summary>
        /// Explore a JSON document using JsonDocument API (DOM-style parsing).
        /// </summary>
        public void ExploreDocument(string json)
        {
            using JsonDocument doc = JsonDocument.Parse(json);
            JsonElement root = doc.RootElement;

            Console.WriteLine("--- DOM Exploration ---");
            ExploreElement(root, indent: 0);
            Console.WriteLine("-----------------------\n");
        }

        private void ExploreElement(JsonElement element, int indent)
        {
            string pad = new string(' ', indent * 2);

            switch (element.ValueKind)
            {
                case JsonValueKind.Object:
                    foreach (JsonProperty prop in element.EnumerateObject())
                    {
                        Console.WriteLine($"{pad}{prop.Name}: ({prop.Value.ValueKind})");
                        ExploreElement(prop.Value, indent + 1);
                    }
                    break;

                case JsonValueKind.Array:
                    int i = 0;
                    foreach (JsonElement item in element.EnumerateArray())
                    {
                        Console.WriteLine($"{pad}[{i}]: ({item.ValueKind})");
                        ExploreElement(item, indent + 1);
                        i++;
                    }
                    break;

                case JsonValueKind.String:
                    Console.WriteLine($"{pad}=> \"{element.GetString()}\"");
                    break;

                case JsonValueKind.Number:
                    Console.WriteLine($"{pad}=> {element.GetDecimal()}");
                    break;

                case JsonValueKind.True:
                case JsonValueKind.False:
                    Console.WriteLine($"{pad}=> {element.GetBoolean()}");
                    break;

                case JsonValueKind.Null:
                    Console.WriteLine($"{pad}=> null");
                    break;
            }
        }
    }

    // --- Main Program ---

    class Program
    {
        static void Main(string[] args)
        {
            // Sample JSON input
            string sampleJson = @"
            {
                ""title"": ""Getting Started with C#"",
                ""author"": ""Jane Doe"",
                ""date"": ""2025-01-15"",
                ""tags"": [""csharp"", ""tutorial"", ""beginner""],
                ""sections"": [
                    {
                        ""heading"": ""Introduction"",
                        ""body"": ""C# is a modern, object-oriented language.""
                    },
                    {
                        ""heading"": ""Setup"",
                        ""body"": ""Install the .NET SDK to get started.""
                    },
                    {
                        ""heading"": ""Hello World"",
                        ""body"": ""Use Console.WriteLine to print output.""
                    }
                ]
            }";

            var parser = new JsonDocumentParser();

            // ---- Method 1: Strongly-typed parsing ----
            Console.WriteLine("=== STRONGLY-TYPED PARSING ===\n");
            try
            {
                Document doc = parser.ParseFromString(sampleJson);
                Console.WriteLine(doc);
            }
            catch (JsonException ex)
            {
                Console.WriteLine($"Parse error: {ex.Message}");
            }

            // ---- Method 2: DOM exploration ----
            Console.WriteLine("=== DOM EXPLORATION ===\n");
            parser.ExploreDocument(sampleJson);

            // ---- Method 3: Dynamic dictionary parsing ----
            Console.WriteLine("=== DYNAMIC PARSING ===\n");
            var dict = parser.ParseAsDynamic(sampleJson);
            foreach (var kvp in dict)
            {
                Console.WriteLine($"Key: {kvp.Key,-12} ValueKind: {kvp.Value.ValueKind}");
            }

            // ---- Method 4: File-based parsing ----
            Console.WriteLine("\n=== FILE PARSING ===\n");
            string tempFile = Path.GetTempFileName();
            try
            {
                File.WriteAllText(tempFile, sampleJson);
                Document fileDoc = parser.ParseFromFile(tempFile);
                Console.WriteLine($"Loaded from file: {fileDoc.Title} by {fileDoc.Author}");
                Console.WriteLine($"Sections count:   {fileDoc.Sections.Count}");
            }
            finally
            {
                File.Delete(tempFile);
            }
        }
    }
}
