```javascript
const http = require("http");
const { LogIngester } = require("./src/ingester");
const { FileStorage } = require("./src/storage");
const { validateLog } = require("./src/validator");

const PORT = process.env.PORT || 3000;
const storage = new FileStorage("./logs/ingested.log");
const ingester = new LogIngester(storage);

const server = http.createServer((req, res) => {
  // Health check
  if (req.method === "GET" && req.url === "/health") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ status: "ok", uptime: process.uptime() }));
    return;
  }

  // Single log ingestion
  if (req.method === "POST" && req.url === "/logs") {
    handleLogIngestion(req, res);
    return;
  }

  // Batch log ingestion
  if (req.method === "POST" && req.url === "/logs/batch") {
    handleBatchIngestion(req, res);
    return;
  }

  // Query logs (simple)
  if (req.method === "GET" && req.url.startsWith("/logs")) {
    handleLogQuery(req, res);
    return;
  }

  res.writeHead(404, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ error: "Not found" }));
});

// --- Route Handlers ---

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => {
      try {
        const body = JSON.parse(Buffer.concat(chunks).toString());
        resolve(body);
      } catch (err) {
        reject(new Error("Invalid JSON"));
      }
    });
    req.on("error", reject);
  });
}

async function handleLogIngestion(req, res) {
  try {
    const logEntry = await readBody(req);
    const validation = validateLog(logEntry);

    if (!validation.valid) {
      res.writeHead(400, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: validation.errors }));
      return;
    }

    const result = await ingester.ingest(logEntry);
    res.writeHead(201, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ success: true, id: result.id }));
  } catch (err) {
    res.writeHead(400, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: err.message }));
  }
}

async function handleBatchIngestion(req, res) {
  try {
    const body = await readBody(req);
    const logs = Array.isArray(body) ? body : body.logs;

    if (!Array.isArray(logs)) {
      res.writeHead(400, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Expected array of logs" }));
      return;
    }

    const results = await ingester.ingestBatch(logs);
    res.writeHead(201, { "Content-Type": "application/json" });
    res.end(JSON.stringify({
      success: true,
      total: logs.length,
      ingested: results.ingested,
      failed: results.failed,
    }));
  } catch (err) {
    res.writeHead(400, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: err.message }));
  }
}

async function handleLogQuery(req, res) {
  try {
    const url = new URL(req.url, `http://localhost:${PORT}`);
    const level = url.searchParams.get("level");
    const limit = parseInt(url.searchParams.get("limit") || "50", 10);

    const logs = await storage.query({ level, limit });
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ count: logs.length, logs }));
  } catch (err) {
    res.writeHead(500, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: err.message }));
  }
}

// --- Start Server ---

server.listen(PORT, () => {
  console.log(`Log ingestion server running on port ${PORT}`);
  console.log(`  POST /logs        - Ingest single log`);
  console.log(`  POST /logs/batch  - Ingest batch of logs`);
  console.log(`  GET  /logs        - Query logs`);
  console.log(`  GET  /health      - Health check`);
});
```

## src/validator.js — JSON Log Validation
```javascript
const VALID_LEVELS = ["debug", "info", "warn", "error", "fatal"];

/**
 * Validates a JSON log entry.
 * Expected format:
 * {
 *   "level": "info",
 *   "message": "Something happened",
 *   "timestamp": "2024-01-15T10:30:00Z",  // optional
 *   "service": "my-app",                    // optional
 *   "meta": { ... }                         // optional
 * }
 */
function validateLog(entry) {
  const errors = [];

  if (!entry || typeof entry !== "object") {
    return { valid: false, errors: ["Log entry must be a JSON object"] };
  }

  // Required: message
  if (!entry.message || typeof entry.message !== "string") {
    errors.push("'message' is required and must be a string");
  }

  // Required: level
  if (!entry.level || typeof entry.level !== "string") {
    errors.push("'level' is required and must be a string");
  } else if (!VALID_LEVELS.includes(entry.level.toLowerCase())) {
    errors.push(`'level' must be one of: ${VALID_LEVELS.join(", ")}`);
  }

  // Optional: timestamp (validate format if present)
  if (entry.timestamp) {
    const date = new Date(entry.timestamp);
    if (isNaN(date.getTime())) {
      errors.push("'timestamp' must be a valid ISO 8601 date string");
    }
  }

  // Optional: service (validate type if present)
  if (entry.service && typeof entry.service !== "string") {
    errors.push("'service' must be a string");
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

module.exports = { validateLog, VALID_LEVELS };
```

