class LogIngester {
  constructor(storage) {
    this.storage = storage;
    this.stats = { total: 0, failed: 0 };
  }

  /**
   * Ingest a single log entry.
   * Enriches with ID, timestamp, and normalized fields.
   */
  async ingest(entry) {
    const enriched = this.enrich(entry);
    await this.storage.store(enriched);
    this.stats.total++;
    console.log(`[INGESTED] ${enriched.id} | ${enriched.level} | ${enriched.message}`);
    return enriched;
  }

  /**
   * Ingest a batch of log entries.
   * Returns counts of successfully ingested and failed entries.
   */
  async ingestBatch(entries) {
    let ingested = 0;
    let failed = 0;
    const errors = [];

    for (const entry of entries) {
      const validation = validateLog(entry);

      if (!validation.valid) {
        failed++;
        errors.push({ entry, reasons: validation.errors });
        this.stats.failed++;
        continue;
      }

      try {
        await this.ingest(entry);
        ingested++;
      } catch (err) {
        failed++;
        errors.push({ entry, reasons: [err.message] });
        this.stats.failed++;
      }
    }

    return { ingested, failed, errors };
  }

  /**
   * Enrich a log entry with metadata.
   */
  enrich(entry) {
    return {
      id: crypto.randomUUID(),
      timestamp: entry.timestamp || new Date().toISOString(),
      level: entry.level.toLowerCase(),
      message: entry.message,
      service: entry.service || "unknown",
      meta: entry.meta || {},
      _ingested_at: new Date().toISOString(),
    };
  }

  getStats() {
    return { ...this.stats };
  }
}

module.exports = { LogIngester };
```

## src/storage.js — File-Based Log Storage
```javascript
const fs = require("fs");
const path = require("path");
const readline = require("readline");

class FileStorage {
  constructor(filePath) {
    this.filePath = path.resolve(filePath);
    // Ensure the directory exists
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
  }

  /**
   * Append a single log entry as a JSON line.
   */
  async store(entry) {
    const line = JSON.stringify(entry) + "\n";
    return new Promise((resolve, reject) => {
      fs.appendFile(this.filePath, line, (err) => {
        if (err) reject(err);
        else resolve();
      });
    });
  }

  /**
   * Query stored logs with optional filters.
   */
  async query({ level, limit = 50 } = {}) {
    if (!fs.existsSync(this.filePath)) return [];

    const results = [];
    const fileStream = fs.createReadStream(this.filePath);
    const rl = readline.createInterface({ input: fileStream });

    return new Promise((resolve, reject) => {
      rl.on("line", (line) => {
        if (results.length >= limit) return;

        try {
          const entry = JSON.parse(line);
          if (level && entry.level !== level.toLowerCase()) return;
          results.push(entry);
        } catch {
          // Skip malformed lines
        }
      });

      rl.on("close", () => resolve(results));
      rl.on("error", reject);
    });
  }
}

/**
 * In-memory storage (useful for testing).
 */
class MemoryStorage {
  constructor() {
    this.logs = [];
  }

  async store(entry) {
    this.logs.push(entry);
  }

  async query({ level, limit = 50 } = {}) {
    let results = this.logs;
    if (level) {
      results = results.filter((l) => l.level === level.toLowerCase());
    }
    return results.slice(0, limit);
  }
}

module.exports = { FileStorage, MemoryStorage };
```

## src/file-ingester.js — Read Logs from a JSON File via stdin
```javascript
const fs = require("fs");
const readline = require("readline");
const { LogIngester } = require("./ingester");
const { MemoryStorage } = require("./storage");
const { FileStorage } = require("./storage");

const storage = new FileStorage("./logs/ingested.log");
const ingester = new LogIngester(storage);

/**
 * Usage:
 *   echo '{"level":"info","message":"hello"}' | node src/file-ingester.js
 *   cat logs.jsonl | node src/file-ingester.js
 *   node src/file-ingester.js < sample.json
 */
async function main() {
  const rl = readline.createInterface({
    input: process.stdin,
    terminal: false,
  });

  let lineNum = 0;

  for await (const line of rl) {
    lineNum++;
    const trimmed = line.trim();
    if (!trimmed) continue;

    try {
      const entry = JSON.parse(trimmed);

      // Handle array of logs (full JSON array on one line)
      if (Array.isArray(entry)) {
        const result = await ingester.ingestBatch(entry);
        console.log(`Line ${lineNum}: Batch — ${result.ingested} ingested, ${result.failed} failed`);
        continue;
      }

      await ingester.ingest(entry);
    } catch (err) {
      console.error(`Line ${lineNum}: SKIP — ${err.message}`);
    }
  }

  console.log("\n--- Ingestion Complete ---");
  console.log(ingester.getStats());
}

main().catch(console.error);
```

