const express = require('express');
const { v4: uuidv4 } = require('uuid');
const app = express();

// ─── FIX 1: Add JSON body parser middleware ─────────────────────
app.use(express.json());

// ─── FIX 2: Async route wrapper to catch unhandled promise rejections
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// In-memory report store (simulating a database)
