// ─── Allowed values for validation ─────────────────────────────
const VALID_TYPES = ['sales', 'inventory', 'financial', 'analytics'];
const VALID_STATUSES = ['pending', 'processing', 'completed', 'failed'];

// ─── POST /reports — Generate a new report ─────────────────────
app.post('/reports', asyncHandler(async (req, res) => {
  const { title, startDate, endDate, type } = req.body;

  // FIX 4: Validate all required inputs
  const errors = [];
  if (!title || typeof title !== 'string' || title.trim() === '') {
    errors.push('title is required and must be a non-empty string');
  }
  if (!startDate || isNaN(Date.parse(startDate))) {
    errors.push('startDate is required and must be a valid date');
  }
  if (!endDate || isNaN(Date.parse(endDate))) {
    errors.push('endDate is required and must be a valid date');
  }
  if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
    errors.push('startDate must be before endDate');
  }
  if (!type || !VALID_TYPES.includes(type)) {
    errors.push(`type must be one of: ${VALID_TYPES.join(', ')}`);
  }

  if (errors.length > 0) {
    return res.status(400).json({ success: false, errors });
  }

  // FIX 5: Use UUID for a reliable unique string ID
  const reportId = uuidv4();

  const report = {
    id: reportId,
    title: title.trim(),
    startDate,
    endDate,
    type,
    status: 'pending',
    createdAt: new Date().toISOString(), // FIX 6: Human-readable ISO format
    data: null
  };

  reports[reportId] = report;

  // FIX 7: Await the async report generation
  // (fire-and-forget intentionally, but with proper error handling)
  generateReport(reportId).catch((err) => {
    console.error(`Report generation failed for ${reportId}:`, err.message);
    if (reports[reportId]) {
      reports[reportId].status = 'failed';
      reports[reportId].error = err.message;
    }
  });

  // FIX 8: Return 201 Created for resource creation
  res.status(201).json({
    success: true,
    message: 'Report generation started',
    report
  });
}));

// ─── GET /reports/:id — Fetch a report by ID ───────────────────
app.get('/reports/:id', asyncHandler(async (req, res) => {
  const report = reports[req.params.id];

  // FIX 9: Return 404 if report not found
  if (!report) {
    return res.status(404).json({
      success: false,
      error: `Report with id '${req.params.id}' not found`
    });
  }

  res.json({ success: true, report });
}));

// ─── GET /reports — List all reports with filters + pagination ──
app.get('/reports', asyncHandler(async (req, res) => {
  const { type, status, page = 1, limit = 20 } = req.query;

  // Validate filter values if provided
  if (type && !VALID_TYPES.includes(type)) {
    return res.status(400).json({
      success: false,
      error: `Invalid type. Must be one of: ${VALID_TYPES.join(', ')}`
    });
