```rust
use std::fmt;

/// All possible errors produced by the document parser.
#[derive(Debug, Clone, PartialEq)]
pub enum ParseError {
    /// Input was empty or contained only whitespace.
    EmptyInput,
    /// A syntax error at a specific line/column with a message.
    SyntaxError {
        line: usize,
        column: usize,
        message: String,
    },
    /// Unexpected end-of-input while parsing.
    UnexpectedEof {
        expected: String,
    },
    /// An unexpected token/character was encountered.
    UnexpectedToken {
        line: usize,
        column: usize,
        expected: String,
        found: String,
    },
    /// A key appeared more than once where duplicates are disallowed.
    DuplicateKey {
        key: String,
        first_line: usize,
        duplicate_line: usize,
    },
    /// The requested format is not supported.
    UnsupportedFormat {
        format: String,
    },
    /// Nesting depth exceeded the configured maximum.
    MaxDepthExceeded {
        max_depth: usize,
    },
    /// A unicode escape sequence was invalid.
    InvalidEscape {
        line: usize,
        column: usize,
        sequence: String,
    },
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::EmptyInput => write!(f, "Input is empty or contains only whitespace"),
            Self::SyntaxError { line, column, message } => {
                write!(f, "Syntax error at line {line}, column {column}: {message}")
            }
            Self::UnexpectedEof { expected } => {
                write!(f, "Unexpected end of input, expected {expected}")
            }
            Self::UnexpectedToken { line, column, expected, found } => {
                write!(
                    f,
                    "Unexpected token at line {line}, column {column}: expected {expected}, found '{found}'"
                )
            }
            Self::DuplicateKey { key, first_line, duplicate_line } => {
                write!(
                    f,
                    "Duplicate key '{key}' at line {duplicate_line} (first seen at line {first_line})"
                )
            }
            Self::UnsupportedFormat { format } => {
                write!(f, "Unsupported document format: '{format}'")
            }
            Self::MaxDepthExceeded { max_depth } => {
                write!(f, "Maximum nesting depth of {max_depth} exceeded")
            }
            Self::InvalidEscape { line, column, sequence } => {
                write!(
                    f,
                    "Invalid escape sequence '\\{sequence}' at line {line}, column {column}"
                )
            }
        }
    }
}

impl std::error::Error for ParseError {}

/// Convenience alias used throughout the crate.
pub type ParseResult<T> = Result<T, ParseError>;
```

## `src/model.rs` — Document Model

```rust
use std::collections::HashMap;
use std::fmt;

/// A single value inside a document.
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Integer(i64),
    Float(f64),
    Str(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>), // preserves insertion order
}

impl Value {
    // ── Type-checking helpers ────────────────────────────────

    pub fn is_null(&self) -> bool {
        matches!(self, Self::Null)
    }
    pub fn is_bool(&self) -> bool {
        matches!(self, Self::Bool(_))
    }
    pub fn is_integer(&self) -> bool {
        matches!(self, Self::Integer(_))
    }
    pub fn is_float(&self) -> bool {
        matches!(self, Self::Float(_))
    }
    pub fn is_string(&self) -> bool {
        matches!(self, Self::Str(_))
    }
    pub fn is_array(&self) -> bool {
        matches!(self, Self::Array(_))
    }
    pub fn is_object(&self) -> bool {
        matches!(self, Self::Object(_))
    }
    pub fn is_number(&self) -> bool {
        self.is_integer() || self.is_float()
    }

    // ── Accessor helpers ────────────────────────────────────

    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Self::Bool(b) => Some(*b),
            _ => None,
        }
    }

    pub fn as_i64(&self) -> Option<i64> {
        match self {
            Self::Integer(n) => Some(*n),
            _ => None,
        }
    }

    pub fn as_f64(&self) -> Option<f64> {
        match self {
            Self::Float(n) => Some(*n),
            Self::Integer(n) => Some(*n as f64),
            _ => None,
        }
    }

    pub fn as_str(&self) -> Option<&str> {
        match self {
            Self::Str(s) => Some(s),
            _ => None,
        }
    }

    pub fn as_array(&self) -> Option<&[Value]> {
        match self {
            Self::Array(a) => Some(a),
            _ => None,
        }
    }

    pub fn as_object(&self) -> Option<&[(String, Value)]> {
        match self {
            Self::Object(entries) => Some(entries),
            _ => None,
        }
    }

    /// Look up a key inside an [`Value::Object`].
    pub fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Self::Object(entries) => entries.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }

    /// Look up an index inside a [`Value::Array`].
    pub fn index(&self, idx: usize) -> Option<&Value> {
        match self {
            Self::Array(arr) => arr.get(idx),
            _ => None,
        }
    }
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Null => write!(f, "null"),
            Self::Bool(b) => write!(f, "{b}"),
            Self::Integer(n) => write!(f, "{n}"),
            Self::Float(n) => {
                if n.fract() == 0.0 {
                    write!(f, "{n:.1}")
                } else {
                    write!(f, "{n}")
                }
            }
            Self::Str(s) => write!(f, "\"{s}\""),
            Self::Array(items) => {
                write!(f, "[")?;
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{item}")?;
                }
                write!(f, "]")
            }
            Self::Object(entries) => {
                write!(f, "{{")?;
                for (i, (key, val)) in entries.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "\"{key}\": {val}")?;
                }
                write!(f, "}}")
