/// A parsed document with optional metadata.
#[derive(Debug, Clone, PartialEq)]
pub struct Document {
    /// Root value of the document.
    root: Value,
    /// Metadata collected during parsing (e.g. source format, line count).
    metadata: HashMap<String, String>,
}

impl Document {
    pub fn new(root: Value) -> Self {
        Self {
            root,
            metadata: HashMap::new(),
        }
    }

    pub fn with_metadata(root: Value, metadata: HashMap<String, String>) -> Self {
        Self { root, metadata }
    }

    pub fn root(&self) -> &Value {
        &self.root
    }

    pub fn root_mut(&mut self) -> &mut Value {
        &mut self.root
    }

    pub fn into_root(self) -> Value {
        self.root
    }

    pub fn metadata(&self) -> &HashMap<String, String> {
        &self.metadata
    }

    pub fn set_meta(&mut self, key: impl Into<String>, value: impl Into<String>) {
        self.metadata.insert(key.into(), value.into());
    }

    pub fn get_meta(&self, key: &str) -> Option<&str> {
        self.metadata.get(key).map(String::as_str)
    }

    /// Convenience: look up a path like `"a.b.c"` through nested objects.
    pub fn query(&self, path: &str) -> Option<&Value> {
        let mut current = &self.root;
        for segment in path.split('.') {
            match current {
                Value::Object(entries) => {
                    current = entries
                        .iter()
                        .find(|(k, _)| k == segment)
                        .map(|(_, v)| v)?;
                }
                Value::Array(arr) => {
                    let idx: usize = segment.parse().ok()?;
                    current = arr.get(idx)?;
                }
                _ => return None,
            }
        }
        Some(current)
    }
}

impl fmt::Display for Document {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.root)
    }
