struct Cursor<'a> {
    input: &'a [u8],
    pos: usize,
    line: usize,
    col: usize,
}

impl<'a> Cursor<'a> {
    fn new(input: &'a str) -> Self {
        Self {
            input: input.as_bytes(),
            pos: 0,
            line: 1,
            col: 1,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let byte = self.input.get(self.pos).copied()?;
        self.pos += 1;
        if byte == b'\n' {
            self.line += 1;
            self.col = 1;
        } else {
            self.col += 1;
        }
        Some(byte)
    }

    fn skip_whitespace(&mut self, allow_comments: bool) {
        loop {
            // plain whitespace
            while self.peek().map_or(false, |b| b.is_ascii_whitespace()) {
                self.advance();
            }

            if !allow_comments {
                break;
            }

            // line comments: // … or # …
            if self.starts_with(b"//") || self.peek() == Some(b'#') {
                while self.peek().map_or(false, |b| b != b'\n') {
                    self.advance();
                }
                continue;
            }

            // block comments: /* … */
            if self.starts_with(b"/*") {
                self.advance();
                self.advance();
                loop {
                    if self.starts_with(b"*/") {
                        self.advance();
                        self.advance();
                        break;
                    }
                    if self.advance().is_none() {
                        break;
                    }
                }
                continue;
            }

            break;
        }
    }

    fn starts_with(&self, prefix: &[u8]) -> bool {
        self.input[self.pos..].starts_with(prefix)
    }

    fn expect(&mut self, expected: u8) -> ParseResult<()> {
        match self.advance() {
            Some(b) if b == expected => Ok(()),
            Some(b) => Err(ParseError::UnexpectedToken {
                line: self.line,
                column: self.col.saturating_sub(1),
                expected: format!("'{}'", expected as char),
                found: format!("{}", b as char),
            }),
            None => Err(ParseError::UnexpectedEof {
                expected: format!("'{}'", expected as char),
            }),
        }
    }

    fn is_eof(&self) -> bool {
        self.pos >= self.input.len()
    }
}

