using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

// Represents a scheduled task
public class ScheduledTask
{
    public string Id { get; } = Guid.NewGuid().ToString("N")[..8];
    public string Name { get; set; } = string.Empty;
    public Action Work { get; set; } = () => { };
    public DateTime ScheduledTime { get; set; } = DateTime.UtcNow;
    public TaskPriority Priority { get; set; } = TaskPriority.Normal;
}

public enum TaskPriority
{
    Low = 0,
    Normal = 1,
    High = 2
}

// Queue consumer that processes scheduled tasks
public class TaskQueueConsumer : IDisposable
{
    private readonly BlockingCollection<ScheduledTask> _queue = new();
    private readonly CancellationTokenSource _cts = new();
    private readonly List<Thread> _workers = new();
    private readonly int _workerCount;
    private int _processedCount;
    private int _failedCount;

    public int ProcessedCount => _processedCount;
    public int FailedCount => _failedCount;
    public int PendingCount => _queue.Count;

    public TaskQueueConsumer(int workerCount = 2)
    {
        _workerCount = workerCount;
    }

    // Start consuming tasks
    public void Start()
    {
        for (int i = 0; i < _workerCount; i++)
        {
            var worker = new Thread(ConsumeLoop)
            {
                IsBackground = true,
                Name = $"Worker-{i + 1}"
            };
            _workers.Add(worker);
            worker.Start();
        }
        Console.WriteLine($"[Consumer] Started {_workerCount} workers.");
    }

    // Enqueue a task for processing
    public void Enqueue(ScheduledTask task)
    {
        if (_queue.IsAddingCompleted)
            throw new InvalidOperationException("Queue is shut down.");

        _queue.Add(task);
        Console.WriteLine($"[Enqueued] Task '{task.Name}' (Id: {task.Id}, Priority: {task.Priority})");
    }

    // Main consume loop for each worker thread
    private void ConsumeLoop()
    {
        string workerName = Thread.CurrentThread.Name ?? "Unknown";
        Console.WriteLine($"  [{workerName}] Ready.");

        try
        {
            foreach (var task in _queue.GetConsumingEnumerable(_cts.Token))
            {
                ProcessTask(task, workerName);
            }
        }
        catch (OperationCanceledException)
        {
            Console.WriteLine($"  [{workerName}] Cancelled.");
        }

        Console.WriteLine($"  [{workerName}] Stopped.");
    }

    // Process a single task
    private void ProcessTask(ScheduledTask task, string workerName)
    {
        Console.WriteLine($"  [{workerName}] Processing '{task.Name}' (Id: {task.Id})...");

        // Wait until scheduled time
        var delay = task.ScheduledTime - DateTime.UtcNow;
        if (delay > TimeSpan.Zero)
        {
            Console.WriteLine($"  [{workerName}] Waiting {delay.TotalMilliseconds:F0}ms for scheduled time...");
            Thread.Sleep(delay);
        }

        try
        {
            task.Work.Invoke();
            Interlocked.Increment(ref _processedCount);
            Console.WriteLine($"  [{workerName}] Completed '{task.Name}' ✓");
        }
        catch (Exception ex)
        {
            Interlocked.Increment(ref _failedCount);
            Console.WriteLine($"  [{workerName}] Failed '{task.Name}' ✗ - {ex.Message}");
        }
    }

    // Graceful shutdown: stop accepting, finish remaining
    public void Shutdown()
    {
        Console.WriteLine("[Consumer] Shutting down (finishing remaining tasks)...");
        _queue.CompleteAdding();

        foreach (var worker in _workers)
            worker.Join(timeout: TimeSpan.FromSeconds(10));

        Console.WriteLine("[Consumer] Shut down complete.");
    }

    public void Dispose()
    {
        _cts.Cancel();
        _queue.CompleteAdding();

        foreach (var worker in _workers)
            worker.Join(timeout: TimeSpan.FromSeconds(5));

        _cts.Dispose();
        _queue.Dispose();
    }
}

// --- Demo ---
public class Program
{
    public static void Main()
    {
        using var consumer = new TaskQueueConsumer(workerCount: 2);
        consumer.Start();

        // Enqueue some immediate tasks
        consumer.Enqueue(new ScheduledTask
        {
            Name = "Send Email",
            Priority = TaskPriority.High,
            Work = () =>
            {
                Thread.Sleep(500); // simulate work
                Console.WriteLine("    → Email sent!");
            }
        });

        consumer.Enqueue(new ScheduledTask
        {
            Name = "Generate Report",
            Priority = TaskPriority.Normal,
            Work = () =>
            {
                Thread.Sleep(800);
                Console.WriteLine("    → Report generated!");
            }
        });

        // Enqueue a task scheduled 2 seconds in the future
        consumer.Enqueue(new ScheduledTask
        {
            Name = "Cleanup Temp Files",
            Priority = TaskPriority.Low,
            ScheduledTime = DateTime.UtcNow.AddSeconds(2),
            Work = () => Console.WriteLine("    → Temp files cleaned!")
        });

        // Enqueue a task that will fail
        consumer.Enqueue(new ScheduledTask
        {
            Name = "Faulty Task",
            Work = () => throw new InvalidOperationException("Something broke!")
        });

        // Let tasks process, then shut down gracefully
        Thread.Sleep(5000);
        consumer.Shutdown();

        Console.WriteLine($"\nProcessed: {consumer.ProcessedCount}, Failed: {consumer.FailedCount}, Pending: {consumer.PendingCount}");
    }
}
