// worker.js
const { parentPort, workerData } = require('worker_threads');

// Listen for cancellation message from the main thread
let cancelled = false;
parentPort.on('message', (msg) => {
  if (msg.type === 'cancel') {
    cancelled = true;
  }
});

/**
 * Check cancellation status — call this periodically in long-running tasks.
 * Throws if the worker has been cancelled.
 */
function checkCancellation() {
  if (cancelled) {
    throw new CancellationError('Worker was cancelled');
  }
}

class CancellationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CancellationError';
    this.code = 'ERR_CANCELLED';
  }
}

// ─── Task Registry ──────────────────────────────────────────
const tasks = {
  /**
   * Example: compute Fibonacci numbers iteratively,
   * checking for cancellation every 1000 iterations.
   */
  fibonacci(n) {
    if (n <= 1) return BigInt(n);
    let a = 0n, b = 1n;

    for (let i = 2; i <= n; i++) {
      if (i % 1000 === 0) {
        checkCancellation();
        // Report progress back to the main thread
        parentPort.postMessage({
          type: 'progress',
          value: Math.round((i / n) * 100),
        });
      }
      [a, b] = [b, a + b];
    }

    return b.toString(); // BigInt isn't cloneable, send as string
  },

  /**
   * Example: process a large array in chunks,
   * checking for cancellation between chunks.
   */
  processArray({ data, chunkSize = 1000 }) {
    const results = [];

    for (let i = 0; i < data.length; i += chunkSize) {
      checkCancellation();

      const chunk = data.slice(i, i + chunkSize);
      const processed = chunk.map((val) => val * val); // example work
      results.push(...processed);

      parentPort.postMessage({
        type: 'progress',
        value: Math.round(((i + chunkSize) / data.length) * 100),
      });
    }

    return results;
  },

  /**
   * Example: simulate a long-running async task
   */
  async longRunningTask({ durationMs, steps }) {
    const stepDuration = durationMs / steps;
    const results = [];

    for (let i = 0; i < steps; i++) {
      checkCancellation();

      // Simulate async work
      await new Promise((resolve) => setTimeout(resolve, stepDuration));
      results.push(`Step ${i + 1} completed`);

      parentPort.postMessage({
        type: 'progress',
        value: Math.round(((i + 1) / steps) * 100),
      });
    }

    return results;
  },
};

// ─── Execute the requested task ─────────────────────────────
(async () => {
  const { taskName, args } = workerData;
  const taskFn = tasks[taskName];

  if (!taskFn) {
    parentPort.postMessage({
      type: 'error',
      error: `Unknown task: ${taskName}`,
    });
    process.exit(1);
  }

  try {
    const result = await taskFn(args);
    parentPort.postMessage({ type: 'result', value: result });
  } catch (err) {
    if (err.code === 'ERR_CANCELLED') {
      parentPort.postMessage({ type: 'cancelled' });
    } else {
      parentPort.postMessage({
        type: 'error',
        error: err.message,
        stack: err.stack,
      });
    }
  }
})();
