// worker-manager.js
const { Worker } = require('worker_threads');
const path = require('path');
const { EventEmitter } = require('events');

/**
 * Represents a handle to a running background job.
 * Supports cancellation, progress events, and promise-based results.
 */
class WorkerJob extends EventEmitter {
  #worker;
  #abortController;
  #promise;
  #state; // 'pending' | 'running' | 'completed' | 'cancelled' | 'error'

  constructor(worker, abortController) {
    super();
    this.#worker = worker;
    this.#abortController = abortController;
    this.#state = 'running';

    this.#promise = new Promise((resolve, reject) => {
      // Listen for abort signal
      abortController.signal.addEventListener('abort', () => {
        this.#worker.postMessage({ type: 'cancel' });

        // Force-kill after a grace period
        setTimeout(() => {
          if (this.#state === 'running') {
            this.#worker.terminate();
            this.#state = 'cancelled';
            reject(new DOMException('Worker forcefully terminated', 'AbortError'));
          }
        }, 5000);
      });

      // Handle messages from the worker
      worker.on('message', (msg) => {
        switch (msg.type) {
          case 'result':
            this.#state = 'completed';
            this.emit('completed', msg.value);
            resolve(msg.value);
            break;

          case 'progress':
            this.emit('progress', msg.value);
            break;

          case 'cancelled':
            this.#state = 'cancelled';
            this.emit('cancelled');
            reject(new DOMException('Worker cancelled', 'AbortError'));
            break;

          case 'error':
            this.#state = 'error';
            const error = new Error(msg.error);
            error.stack = msg.stack;
            this.emit('error', error);
            reject(error);
            break;
        }
      });

      // Handle unexpected worker exit
      worker.on('error', (err) => {
        this.#state = 'error';
        reject(err);
      });

      worker.on('exit', (code) => {
        if (this.#state === 'running') {
          this.#state = 'error';
          reject(new Error(`Worker exited unexpectedly with code ${code}`));
        }
      });
    });
  }

  /** Cancel the running job */
  cancel() {
    if (this.#state !== 'running') return;
    this.#abortController.abort();
  }

  /** @returns {Promise} resolves with the task result */
  get result() {
    return this.#promise;
  }

  get state() {
    return this.#state;
  }

  get signal() {
    return this.#abortController.signal;
  }
}

/**
 * Manages a pool of background workers with concurrency control.
 */
class WorkerManager {
  #workerScript;
  #maxConcurrency;
  #activeJobs = new Map();
  #queue = [];

  constructor(options = {}) {
    this.#workerScript = options.workerScript || path.join(__dirname, 'worker.js');
    this.#maxConcurrency = options.maxConcurrency || 4;
  }

  /**
   * Submit a task for background execution.
   *
   * @param {string} taskName  - name registered in worker.js
   * @param {*} args           - serializable arguments
   * @param {object} [options]
   * @param {AbortSignal} [options.signal] - external abort signal
   * @returns {WorkerJob}
   */
  run(taskName, args, options = {}) {
    const abortController = new AbortController();

    // Link an external signal if provided
    if (options.signal) {
      if (options.signal.aborted) {
        abortController.abort();
      } else {
        options.signal.addEventListener('abort', () => abortController.abort(), { once: true });
      }
    }

    const worker = new Worker(this.#workerScript, {
      workerData: { taskName, args },
    });

    const job = new WorkerJob(worker, abortController);
    const jobId = worker.threadId;

    this.#activeJobs.set(jobId, job);

    // Clean up when finished
    job.result
      .catch(() => {})
      .finally(() => {
        this.#activeJobs.delete(jobId);
      });

    return job;
  }

  /** Cancel all active jobs */
  cancelAll() {
    for (const job of this.#activeJobs.values()) {
      job.cancel();
    }
  }

  get activeCount() {
    return this.#activeJobs.size;
  }
}

module.exports = { WorkerManager, WorkerJob };
```

