// main.js
const { WorkerManager } = require('./worker-manager');

async function demo() {
  const manager = new WorkerManager({ maxConcurrency: 4 });

  // ─── Example 1: Run to completion ──────────────────────────
  console.log('=== Example 1: Fibonacci (run to completion) ===');
  const job1 = manager.run('fibonacci', 500_000);

  job1.on('progress', (pct) => {
    process.stdout.write(`\r  Fibonacci progress: ${pct}%`);
  });

  const result1 = await job1.result;
  console.log(`\n  Result length: ${result1.length} digits\n`);

  // ─── Example 2: Cancel after a timeout ─────────────────────
  console.log('=== Example 2: Long task (cancelled after 2s) ===');
  const job2 = manager.run('longRunningTask', { durationMs: 10000, steps: 20 });

  job2.on('progress', (pct) => {
    console.log(`  Long task progress: ${pct}%`);
  });

  job2.on('cancelled', () => {
    console.log('  ✓ Job was cancelled gracefully');
  });

  // Cancel after 2 seconds
  setTimeout(() => {
    console.log('  → Requesting cancellation...');
    job2.cancel();
  }, 2000);

  try {
    await job2.result;
  } catch (err) {
    console.log(`  Caught: ${err.name}: ${err.message}\n`);
  }

  // ─── Example 3: Cancel via AbortController ────────────────
  console.log('=== Example 3: External AbortController ===');
  const controller = new AbortController();

  const job3 = manager.run(
    'fibonacci',
    10_000_000,
    { signal: controller.signal }
  );

  job3.on('progress', (pct) => {
    process.stdout.write(`\r  Fibonacci progress: ${pct}%`);
  });

  // Abort from the external controller
  setTimeout(() => {
    console.log('\n  → External abort signal fired');
    controller.abort();
  }, 1500);

  try {
    await job3.result;
  } catch (err) {
    console.log(`  Caught: ${err.name}: ${err.message}\n`);
  }

  // ─── Example 4: Cancel all ────────────────────────────────
  console.log('=== Example 4: Cancel all active jobs ===');
  const jobs = [
    manager.run('longRunningTask', { durationMs: 10000, steps: 50 }),
    manager.run('longRunningTask', { durationMs: 10000, steps: 50 }),
    manager.run('longRunningTask', { durationMs: 10000, steps: 50 }),
  ];

  console.log(`  Active jobs: ${manager.activeCount}`);

  setTimeout(() => {
    manager.cancelAll();
    console.log('  → Cancelled all jobs');
  }, 1000);

  const settled = await Promise.allSettled(jobs.map((j) => j.result));
  settled.forEach((s, i) => {
    console.log(`  Job ${i}: ${s.status}${s.reason ? ' — ' + s.reason.message : ''}`);
  });
}

demo().catch(console.error);
