import { readFileSync, existsSync } from "fs";
import { resolve } from "path";

// --- 1. Read & Parse JSON from a File ---
function parseJSONFile(filePath) {
  const absolutePath = resolve(filePath);

  if (!existsSync(absolutePath)) {
    throw new Error(`File not found: ${absolutePath}`);
  }

  const rawData = readFileSync(absolutePath, "utf-8");

  try {
    return JSON.parse(rawData);
  } catch (err) {
    throw new Error(`Invalid JSON in ${filePath}: ${err.message}`);
  }
}

// --- 2. Parse JSON from a String ---
function parseJSONString(jsonString) {
  try {
    return JSON.parse(jsonString);
  } catch (err) {
    throw new Error(`Invalid JSON string: ${err.message}`);
  }
}

// --- 3. Extract Nested Values Safely ---
function getNestedValue(obj, path) {
  // path example: "metadata.createdAt" or "employees.0.name"
  return path.split(".").reduce((current, key) => {
    if (current === undefined || current === null) return undefined;
    return current[key];
  }, obj);
}

// --- 4. Summarize Document Structure ---
function summarize(obj, indent = 0) {
  const prefix = "  ".repeat(indent);
  const lines = [];

  for (const [key, value] of Object.entries(obj)) {
    if (Array.isArray(value)) {
      lines.push(`${prefix}${key}: Array[${value.length}]`);
    } else if (typeof value === "object" && value !== null) {
      lines.push(`${prefix}${key}: Object`);
      lines.push(summarize(value, indent + 1));
    } else {
      lines.push(`${prefix}${key}: ${typeof value} = ${JSON.stringify(value)}`);
    }
  }

  return lines.join("\n");
}

// --- 5. Search for a Key Recursively ---
function findKey(obj, targetKey) {
  const results = [];

  function search(current, path) {
    if (typeof current !== "object" || current === null) return;

    for (const [key, value] of Object.entries(current)) {
      const currentPath = path ? `${path}.${key}` : key;

      if (key === targetKey) {
        results.push({ path: currentPath, value });
      }

      if (typeof value === "object" && value !== null) {
        search(value, currentPath);
      }
    }
  }

  search(obj, "");
  return results;
}

// ========== MAIN ==========
function main() {
  console.log("=== JSON Document Parser ===\n");

  // Parse from file
  const doc = parseJSONFile("sample.json");
  console.log("✅ File parsed successfully\n");

  // Display top-level keys
  console.log("--- Top-Level Keys ---");
  console.log(Object.keys(doc).join(", "));

  // Display document summary
  console.log("\n--- Document Structure ---");
  console.log(summarize(doc));

  // Access nested values
  console.log("\n--- Nested Value Access ---");
  const paths = [
    "title",
    "metadata.createdAt",
    "employees.0.name",
    "employees.1.skills",
  ];
  for (const path of paths) {
    console.log(`  ${path} → ${JSON.stringify(getNestedValue(doc, path))}`);
  }

  // Search for a key
  console.log('\n--- Search for key: "name" ---');
  const matches = findKey(doc, "name");
  for (const match of matches) {
    console.log(`  ${match.path} → ${JSON.stringify(match.value)}`);
  }

  // Parse from string
  console.log("\n--- Parse JSON String ---");
  const jsonStr = '{"status": "ok", "count": 42}';
  const parsed = parseJSONString(jsonStr);
  console.log("  Parsed:", parsed);
}

main();
```

