## Key Concepts Covered

| Feature | Method Used |
|---|---|
| **Read file** | `readFileSync` from `fs` |
| **Parse JSON** | `JSON.parse()` with error handling |
| **Nested access** | Dot-path traversal via `reduce` |
| **Structure summary** | Recursive type inspection |
| **Key search** | Recursive depth-first search |
| **String parsing** | Direct `JSON.parse()` on raw strings |

> **Notes:**
> - Uses **ES modules** (`import`) — set `"type": "module"` in `package.json` or rename to `.mjs`.
> - All parsing is wrapped in **try/catch** for safe error handling.
> - For large files, consider `fs.createReadStream` with a streaming JSON parser like `JSONStream`.

```rust
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::path::Path;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct DatabaseConfig {
    pub host: String,
    pub port: u16,
    pub name: String,
    pub username: String,
    pub password: String,
    pub max_connections: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ServerConfig {
    pub host: String,
    pub port: u16,
    pub workers: usize,
    pub debug: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct LoggingConfig {
    pub level: String,
    pub file: Option<String>,
    pub format: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct AppConfig {
    pub app_name: String,
    pub version: String,
    pub server: ServerConfig,
    pub database: DatabaseConfig,
    pub logging: LoggingConfig,
    #[serde(default)]
    pub extra: HashMap<String, String>,
}

#[derive(Debug)]
pub enum ConfigError {
    FileNotFound(String),
    ReadError(String),
    ParseError(String),
    ValidationError(String),
    SerializeError(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::FileNotFound(path) => write!(f, "Config file not found: {}", path),
            ConfigError::ReadError(msg) => write!(f, "Failed to read config: {}", msg),
            ConfigError::ParseError(msg) => write!(f, "Failed to parse config: {}", msg),
            ConfigError::ValidationError(msg) => write!(f, "Config validation failed: {}", msg),
            ConfigError::SerializeError(msg) => write!(f, "Failed to serialize config: {}", msg),
        }
    }
}

impl std::error::Error for ConfigError {}

impl Default for DatabaseConfig {
    fn default() -> Self {
        Self {
            host: "localhost".to_string(),
            port: 5432,
            name: "myapp".to_string(),
            username: "admin".to_string(),
            password: String::new(),
            max_connections: 10,
        }
    }
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            host: "0.0.0.0".to_string(),
            port: 8080,
            workers: 4,
            debug: false,
        }
    }
}

impl Default for LoggingConfig {
    fn default() -> Self {
        Self {
            level: "info".to_string(),
            file: None,
            format: "text".to_string(),
        }
    }
}

impl Default for AppConfig {
    fn default() -> Self {
        Self {
            app_name: "myapp".to_string(),
            version: "0.1.0".to_string(),
            server: ServerConfig::default(),
            database: DatabaseConfig::default(),
            logging: LoggingConfig::default(),
            extra: HashMap::new(),
        }
    }
}

impl AppConfig {
    /// Load configuration from a JSON file
    pub fn from_json_file<P: AsRef<Path>>(path: P) -> Result<Self, ConfigError> {
        let path = path.as_ref();

        if !path.exists() {
            return Err(ConfigError::FileNotFound(
                path.display().to_string(),
            ));
        }

        let content = fs::read_to_string(path)
            .map_err(|e| ConfigError::ReadError(e.to_string()))?;

        Self::from_json_str(&content)
    }

    /// Parse configuration from a JSON string
    pub fn from_json_str(json: &str) -> Result<Self, ConfigError> {
        let config: Self = serde_json::from_str(json)
            .map_err(|e| ConfigError::ParseError(e.to_string()))?;

        config.validate()?;
        Ok(config)
    }

    /// Load configuration from a TOML file
    pub fn from_toml_file<P: AsRef<Path>>(path: P) -> Result<Self, ConfigError> {
        let path = path.as_ref();

        if !path.exists() {
            return Err(ConfigError::FileNotFound(
                path.display().to_string(),
            ));
        }

        let content = fs::read_to_string(path)
            .map_err(|e| ConfigError::ReadError(e.to_string()))?;

        Self::from_toml_str(&content)
    }

    /// Parse configuration from a TOML string
    pub fn from_toml_str(toml: &str) -> Result<Self, ConfigError> {
        let config: Self = toml::from_str(toml)
            .map_err(|e| ConfigError::ParseError(e.to_string()))?;

        config.validate()?;
        Ok(config)
    }

    /// Serialize configuration to a JSON string
    pub fn to_json_string(&self) -> Result<String, ConfigError> {
        serde_json::to_string_pretty(self)
            .map_err(|e| ConfigError::SerializeError(e.to_string()))
    }

    /// Serialize configuration to a TOML string
    pub fn to_toml_string(&self) -> Result<String, ConfigError> {
        toml::to_string_pretty(self)
            .map_err(|e| ConfigError::SerializeError(e.to_string()))
    }

    /// Save configuration to a JSON file
    pub fn save_json<P: AsRef<Path>>(&self, path: P) -> Result<(), ConfigError> {
        let json = self.to_json_string()?;
        fs::write(path, json).map_err(|e| ConfigError::ReadError(e.to_string()))
    }

    /// Save configuration to a TOML file
    pub fn save_toml<P: AsRef<Path>>(&self, path: P) -> Result<(), ConfigError> {
        let toml_str = self.to_toml_string()?;
        fs::write(path, toml_str).map_err(|e| ConfigError::ReadError(e.to_string()))
    }

    /// Override configuration with environment variables
    /// Format: APP_SERVER__HOST, APP_SERVER__PORT, APP_DATABASE__HOST, etc.
    pub fn override_with_env(&mut self, prefix: &str) {
        if let Ok(val) = std::env::var(format!("{}_SERVER__HOST", prefix)) {
            self.server.host = val;
        }
        if let Ok(val) = std::env::var(format!("{}_SERVER__PORT", prefix)) {
            if let Ok(port) = val.parse::<u16>() {
                self.server.port = port;
            }
        }
        if let Ok(val) = std::env::var(format!("{}_SERVER__DEBUG", prefix)) {
            if let Ok(debug) = val.parse::<bool>() {
                self.server.debug = debug;
            }
        }
        if let Ok(val) = std::env::var(format!("{}_DATABASE__HOST", prefix)) {
            self.database.host = val;
        }
        if let Ok(val) = std::env::var(format!("{}_DATABASE__PORT", prefix)) {
            if let Ok(port) = val.parse::<u16>() {
                self.database.port = port;
            }
        }
        if let Ok(val) = std::env::var(format!("{}_DATABASE__NAME", prefix)) {
            self.database.name = val;
        }
        if let Ok(val) = std::env::var(format!("{}_LOGGING__LEVEL", prefix)) {
            self.logging.level = val;
        }
    }

    /// Validate the configuration
    pub fn validate(&self) -> Result<(), ConfigError> {
        if self.app_name.is_empty() {
            return Err(ConfigError::ValidationError(
                "app_name cannot be empty".to_string(),
            ));
        }

        if self.server.port == 0 {
            return Err(ConfigError::ValidationError(
                "server port cannot be 0".to_string(),
            ));
        }

        if self.server.workers == 0 {
            return Err(ConfigError::ValidationError(
                "server workers must be > 0".to_string(),
            ));
        }

        if self.database.host.is_empty() {
            return Err(ConfigError::ValidationError(
                "database host cannot be empty".to_string(),
            ));
        }

        if self.database.port == 0 {
            return Err(ConfigError::ValidationError(
                "database port cannot be 0".to_string(),
            ));
        }

        let valid_levels = ["trace", "debug", "info", "warn", "error"];
        if !valid_levels.contains(&self.logging.level.to_lowercase().as_str()) {
            return Err(ConfigError::ValidationError(format!(
                "invalid logging level: '{}'. Must be one of: {:?}",
                self.logging.level, valid_levels
            )));
        }

        Ok(())
    }

    /// Merge with another config, preferring values from `other`
    pub fn merge(&mut self, other: &AppConfig) {
        if other.app_name != AppConfig::default().app_name {
            self.app_name = other.app_name.clone();
        }
        if other.version != AppConfig::default().version {
            self.version = other.version.clone();
        }
        self.server = other.server.clone();
        self.database = other.database.clone();
        self.logging = other.logging.clone();
        for (key, value) in &other.extra {
            self.extra.insert(key.clone(), value.clone());
        }
    }

    /// Get the database connection string
    pub fn database_url(&self) -> String {
        format!(
            "postgres://{}:{}@{}:{}/{}",
            self.database.username,
            self.database.password,
            self.database.host,
            self.database.port,
            self.database.name
        )
    }

    /// Get the server bind address
    pub fn server_addr(&self) -> String {
        format!("{}:{}", self.server.host, self.server.port)
    }
}

fn main() {
    // Create a default config and customize it
    let mut config = AppConfig::default();
    config.app_name = "demo-app".to_string();
    config.server.port = 3000;
    config.database.name = "demo_db".to_string();
    config.extra.insert("feature_flag".to_string(), "true".to_string());

    println!("=== App Configuration ===");
    println!("App: {} v{}", config.app_name, config.version);
    println!("Server: {}", config.server_addr());
    println!("Database: {}", config.database_url());
    println!("Log Level: {}", config.logging.level);
    println!("Debug: {}", config.server.debug);

    // Serialize to JSON
    let json = config.to_json_string().unwrap();
    println!("\n=== JSON Output ===\n{}", json);

    // Serialize to TOML
    let toml_str = config.to_toml_string().unwrap();
    println!("\n=== TOML Output ===\n{}", toml_str);

    // Round-trip: parse back from JSON
    let parsed = AppConfig::from_json_str(&json).unwrap();
    assert_eq!(config, parsed);
    println!("\n✓ JSON round-trip successful");

    // Round-trip: parse back from TOML
    let parsed = AppConfig::from_toml_str(&toml_str).unwrap();
    assert_eq!(config, parsed);
    println!("✓ TOML round-trip successful");
}

