# Debugging a JavaScript Audit Logging Scheduler

Below is a **buggy** scheduler followed by the **fully debugged** version with detailed explanations.

## Buggy Code (Before)

```javascript
// ❌ BUGGY VERSION — multiple issues annotated below
class AuditLogScheduler {
  constructor(config) {
    this.buffer = [];
    this.interval = config.interval;
    this.maxBufferSize = config.maxBufferSize;
    this.apiEndpoint = config.apiEndpoint;
    this.timer = null;
    // BUG 1: no default config — crashes if config is partial
    // BUG 2: no running state flag — can start multiple times
  }

  start() {
    // BUG 3: doesn't check if already running → duplicate intervals
    this.timer = setInterval(() => {
      this.flush();             // BUG 4: not awaiting async flush
    }, this.interval);
  }

  stop() {
    clearInterval(this.timer);
    // BUG 5: doesn't flush remaining buffer on shutdown
    // BUG 6: doesn't reset timer to null
  }

  log(entry) {
    // BUG 7: no input validation
    // BUG 8: no timestamp added to entry
    this.buffer.push(entry);

    if (this.buffer.length >= this.maxBufferSize) {
      this.flush();             // BUG 9: not awaiting async call
    }
    // BUG 10: no return value / confirmation
  }

  async flush() {
    if (this.buffer.length === 0) return;

    const entries = this.buffer;
    this.buffer = [];           // BUG 11: if fetch fails, entries are LOST

    // BUG 12: no timeout on fetch
    // BUG 13: no retry logic
    const response = await fetch(this.apiEndpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(entries),   // BUG 14: can throw on circular refs
    });

    if (!response.ok) {
      console.log("Flush failed");    // BUG 15: entries lost on failure
      // BUG 16: no structured error logging
    }
    // BUG 17: no success confirmation / metrics
  }

  getBufferSize() {
    return this.buffer.length;         // Only minor — works but no stats
  }
}
```

---

## Debugged Code (After)

```javascript
/**
 * AuditLogScheduler — resilient, non-lossy audit log batcher
 *
 * Fixed bugs:
 *  1. Safe defaults for partial config
 *  2. Running-state guard prevents duplicate intervals
 *  3. Graceful shutdown flushes remaining entries
 *  4. Entries restored to buffer on flush failure (no data loss)
 *  5. Retry with exponential backoff
 *  6. Fetch timeout via AbortController
 *  7. Input validation + auto-timestamping
 *  8. Structured error logging
 *  9. Proper async handling in setInterval
 * 10. Metrics / observability hooks
 */
class AuditLogScheduler {
  // ── FIX 1: safe defaults ────────────────────────────────
  static DEFAULTS = {
    interval: 5_000,          // flush every 5 s
    maxBufferSize: 100,       // flush when buffer hits 100
    maxRetries: 3,
    retryBaseDelay: 1_000,    // 1 s → 2 s → 4 s
    fetchTimeout: 10_000,     // 10 s abort
    apiEndpoint: "/api/audit-logs",
  };

  constructor(config = {}) {
    const cfg = { ...AuditLogScheduler.DEFAULTS, ...config };

    this.buffer = [];
    this.interval = cfg.interval;
    this.maxBufferSize = cfg.maxBufferSize;
    this.maxRetries = cfg.maxRetries;
    this.retryBaseDelay = cfg.retryBaseDelay;
    this.fetchTimeout = cfg.fetchTimeout;
    this.apiEndpoint = cfg.apiEndpoint;

    // FIX 2: state flags
    this.timer = null;
    this.isRunning = false;
    this.isFlushing = false;

    // FIX 10: basic metrics
    this.metrics = {
      totalLogged: 0,
      totalFlushed: 0,
      totalFailed: 0,
      flushCount: 0,
    };
  }

  // ── FIX 3: guard against double-start ───────────────────
  start() {
    if (this.isRunning) {
      console.warn("[AuditScheduler] Already running — ignoring start()");
      return;
    }

    this.isRunning = true;

    // FIX 4: wrap async flush properly inside setInterval
    this.timer = setInterval(async () => {
      try {
        await this.flush();
      } catch (err) {
        console.error("[AuditScheduler] Scheduled flush error:", err);
      }
    }, this.interval);

    // Don't let the timer block Node.js shutdown
    if (this.timer.unref) this.timer.unref();

    console.info(`[AuditScheduler] Started — interval=${this.interval}ms`);
  }

  // ── FIX 5 & 6: flush remaining + reset state ───────────
  async stop() {
    if (!this.isRunning) return;

    clearInterval(this.timer);
    this.timer = null;
    this.isRunning = false;

    // Flush anything still in the buffer before shutting down
    if (this.buffer.length > 0) {
      console.info("[AuditScheduler] Flushing remaining entries on stop…");
      try {
        await this.flush();
      } catch (err) {
        console.error("[AuditScheduler] Final flush failed:", err);
      }
    }

    console.info("[AuditScheduler] Stopped");
  }

  // ── FIX 7 & 8: validate + timestamp ────────────────────
  log(entry) {
    if (!entry || typeof entry !== "object") {
      throw new TypeError("Audit entry must be a non-null object");
    }

    const enrichedEntry = {
      ...entry,
      timestamp: entry.timestamp || new Date().toISOString(),
      id: entry.id || crypto.randomUUID?.() || this._uuid(),
    };

    this.buffer.push(enrichedEntry);
    this.metrics.totalLogged++;

    // FIX 9: await the auto-flush when buffer is full
    if (this.buffer.length >= this.maxBufferSize) {
      // Fire-and-forget but catch errors
      this.flush().catch((err) =>
        console.error("[AuditScheduler] Auto-flush error:", err)
      );
    }

    return enrichedEntry.id;    // FIX: return confirmation
  }

  // ── FIX 4, 11-17: resilient flush ──────────────────────
  async flush() {
    if (this.isFlushing || this.buffer.length === 0) return;
    this.isFlushing = true;

    // Snapshot the current buffer, keep reference for rollback
    const entries = [...this.buffer];       // shallow copy
    this.buffer = [];

    try {
      await this._sendWithRetry(entries);

      // ✅ Success path
      this.metrics.totalFlushed += entries.length;
      this.metrics.flushCount++;
    } catch (err) {
      // ── FIX 11 & 15: restore entries on total failure ──
      console.error(
        `[AuditScheduler] Flush failed after ${this.maxRetries} retries — ` +
        `restoring ${entries.length} entries to buffer`,
        err
      );
      this.buffer = [...entries, ...this.buffer];   // prepend old entries
      this.metrics.totalFailed += entries.length;

      // Prevent unbounded growth (circuit breaker)
      if (this.buffer.length > this.maxBufferSize * 3) {
        const dropped = this.buffer.length - this.maxBufferSize * 3;
        this.buffer = this.buffer.slice(-this.maxBufferSize * 3);
        console.warn(`[AuditScheduler] Dropped ${dropped} oldest entries (overflow)`);
      }
    } finally {
      this.isFlushing = false;
    }
  }

  // ── FIX 12 & 13: timeout + exponential backoff ─────────
  async _sendWithRetry(entries, attempt = 0) {
    const controller = new AbortController();
    const timeout = setTimeout(
      () => controller.abort(),
      this.fetchTimeout
    );

    try {
      // FIX 14: safe serialisation
      let body;
      try {
        body = JSON.stringify(entries);
      } catch (serErr) {
        throw new Error(`Serialisation failed: ${serErr.message}`);
      }

      const response = await fetch(this.apiEndpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Batch-Size": String(entries.length),
        },
        body,
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      return await response.json().catch(() => ({})); // tolerate empty body
    } catch (err) {
      // ── Retry logic ───────────────────────────────────
      if (attempt < this.maxRetries - 1) {
        const delay = this.retryBaseDelay * 2 ** attempt;
        console.warn(
          `[AuditScheduler] Attempt ${attempt + 1} failed — ` +
          `retrying in ${delay}ms…`,
          err.message
        );
        await this._sleep(delay);
        return this._sendWithRetry(entries, attempt + 1);
      }
      throw err;    // exhausted retries
    } finally {
      clearTimeout(timeout);
    }
  }

  // ── Helpers ─────────────────────────────────────────────
  _sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  _uuid() {
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
      const r = (Math.random() * 16) | 0;
      return (c === "x" ? r : (r & 0x3) | 0x8).toString(16);
    });
  }

  getMetrics() {
    return {
      ...this.metrics,
      currentBufferSize: this.buffer.length,
      isRunning: this.isRunning,
      isFlushing: this.isFlushing,
    };
  }
}
```

