```rust
use std::path::PathBuf;
use thiserror::Error;

/// Top-level error type for the document parser.
#[derive(Debug, Error)]
pub enum DocumentError {
    #[error("I/O error reading '{path}': {source}")]
    Io {
        path: PathBuf,
        source: std::io::Error,
    },

    #[error("JSON parse error at line {line}, column {column}: {message}")]
    JsonParse {
        line: usize,
        column: usize,
        message: String,
    },

    #[error("Validation error: {0}")]
    Validation(#[from] ValidationError),

    #[error("Unsupported document version: {0}")]
    UnsupportedVersion(String),

    #[error("Missing required field: '{field}' in section '{section}'")]
    MissingField { section: String, field: String },
}

/// Specific validation errors with structured context.
#[derive(Debug, Error)]
pub enum ValidationError {
    #[error("Field '{field}' is empty but required")]
    EmptyField { field: String },

    #[error("Field '{field}' exceeds max length {max} (got {actual})")]
    FieldTooLong {
        field: String,
        max: usize,
        actual: usize,
    },

    #[error("Invalid email format: '{value}'")]
    InvalidEmail { value: String },

    #[error("Invalid date range: start '{start}' is after end '{end}'")]
    InvalidDateRange { start: String, end: String },

    #[error("{count} validation error(s) found")]
    Multiple {
        count: usize,
        errors: Vec<ValidationError>,
    },
}

/// Convenient Result alias used throughout the crate.
pub type Result<T> = std::result::Result<T, DocumentError>;

impl DocumentError {
    /// Construct an `Io` variant from a path and raw `io::Error`.
    pub fn io(path: impl Into<PathBuf>, source: std::io::Error) -> Self {
        Self::Io {
            path: path.into(),
            source,
        }
    }

    /// Construct a `JsonParse` variant from a `serde_json::Error`.
    pub fn from_serde(err: serde_json::Error) -> Self {
        Self::JsonParse {
            line: err.line(),
            column: err.column(),
            message: err.to_string(),
        }
    }
}
