#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct InvoiceContent {
    pub invoice_number: String,
    pub vendor: String,
    pub client: String,
    pub line_items: Vec<LineItem>,

    #[serde(default)]
    pub tax_rate: Option<f64>,

    #[serde(default)]
    pub notes: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct LineItem {
    pub description: String,
    pub quantity: u32,
    pub unit_price: f64,

    #[serde(default)]
    pub discount: Option<f64>,
}

impl LineItem {
    /// Net amount after optional discount.
    pub fn total(&self) -> f64 {
        let gross = f64::from(self.quantity) * self.unit_price;
        match self.discount {
            Some(d) => gross * (1.0 - d / 100.0),
            None => gross,
        }
    }
}

impl InvoiceContent {
    /// Sum of all line-item totals.
    pub fn subtotal(&self) -> f64 {
        self.line_items.iter().map(LineItem::total).sum()
    }

    /// Grand total including optional tax.
    pub fn grand_total(&self) -> f64 {
        let sub = self.subtotal();
        match self.tax_rate {
            Some(rate) => sub * (1.0 + rate / 100.0),
            None => sub,
        }
    }
}

// ── Correspondence ───────────────────────────────────────

