## `src/validator/rules.rs` — Validation Rules

```rust
use crate::error::ValidationError;
use crate::models::*;

/// Accumulator that collects every validation failure.
pub struct ValidationContext {
    errors: Vec<ValidationError>,
}

impl ValidationContext {
    pub fn new() -> Self {
        Self { errors: Vec::new() }
    }

    /// Record a single error.
    pub fn add_error(&mut self, error: ValidationError) {
        self.errors.push(error);
    }

    /// Consume the context and return `Ok(())` or a combined error.
    pub fn finish(self) -> Result<(), ValidationError> {
        if self.errors.is_empty() {
            Ok(())
        } else {
            let count = self.errors.len();
            Err(ValidationError::Multiple {
                count,
                errors: self.errors,
            })
        }
    }

    // ── Primitive checks ─────────────────────────────────

    fn check_non_empty(&mut self, field: &str, value: &str) {
        if value.trim().is_empty() {
            self.add_error(ValidationError::EmptyField {
                field: field.to_owned(),
            });
        }
    }

    fn check_max_length(&mut self, field: &str, value: &str, max: usize) {
        if value.len() > max {
            self.add_error(ValidationError::FieldTooLong {
                field: field.to_owned(),
                max,
                actual: value.len(),
            });
        }
    }

    fn check_email(&mut self, field: &str, value: &str) {
        // Lightweight check — swap in a real crate for production.
        if !value.contains('@') || !value.contains('.') {
            self.add_error(ValidationError::InvalidEmail {
                value: value.to_owned(),
            });
        }
    }

    // ── Composite validators ─────────────────────────────

    pub fn validate_metadata(&mut self, meta: &Metadata) {
        self.check_non_empty("metadata.version", &meta.version);
        self.check_max_length("metadata.version", &meta.version, 20);

        if let Some(author) = &meta.author {
            self.check_non_empty("metadata.author.name", &author.name);
            self.check_max_length("metadata.author.name", &author.name, 200);

            if let Some(email) = &author.email {
                self.check_email("metadata.author.email", email);
            }
        }

        for (i, tag) in meta.tags.iter().enumerate() {
            self.check_non_empty(&format!("metadata.tags[{i}]"), tag);
            self.check_max_length(&format!("metadata.tags[{i}]"), tag, 50);
        }
    }

    pub fn validate_report(&mut self, report: &ReportContent) {
        self.check_non_empty("report.title", &report.title);
        self.check_max_length("report.title", &report.title, 500);

        if report.sections.is_empty() {
            self.add_error(ValidationError::EmptyField {
                field: "report.sections".to_owned(),
            });
        }

        for (i, section) in report.sections.iter().enumerate() {
            self.validate_section(section, &format!("report.sections[{i}]"));
        }
    }

    fn validate_section(&mut self, section: &Section, path: &str) {
        self.check_non_empty(&format!("{path}.heading"), &section.heading);
        self.check_non_empty(&format!("{path}.body"), &section.body);
        self.check_max_length(&format!("{path}.body"), &section.body, 50_000);

        for (i, sub) in section.subsections.iter().enumerate() {
            self.validate_section(sub, &format!("{path}.subsections[{i}]"));
        }
    }

    pub fn validate_invoice(&mut self, invoice: &InvoiceContent) {
        self.check_non_empty("invoice.invoice_number", &invoice.invoice_number);
        self.check_non_empty("invoice.vendor", &invoice.vendor);
        self.check_non_empty("invoice.client", &invoice.client);

        if invoice.line_items.is_empty() {
            self.add_error(ValidationError::EmptyField {
                field: "invoice.line_items".to_owned(),
            });
        }

        for (i, item) in invoice.line_items.iter().enumerate() {
            self.check_non_empty(&format!("invoice.line_items[{i}].description"), &item.description);

            if item.unit_price < 0.0 {
                self.add_error(ValidationError::EmptyField {
                    field: format!("invoice.line_items[{i}].unit_price (negative)"),
                });
            }
        }

        if let Some(rate) = invoice.tax_rate {
            if !(0.0..=100.0).contains(&rate) {
                self.add_error(ValidationError::EmptyField {
                    field: "invoice.tax_rate (must be 0–100)".to_owned(),
                });
            }
        }
    }

    pub fn validate_correspondence(&mut self, corr: &CorrespondenceContent) {
        self.check_non_empty("correspondence.from", &corr.from);
        self.check_non_empty("correspondence.subject", &corr.subject);
        self.check_non_empty("correspondence.body", &corr.body);

        if corr.to.is_empty() {
            self.add_error(ValidationError::EmptyField {
                field: "correspondence.to".to_owned(),
            });
        }
    }
}
