pub mod rules;

use crate::error::{DocumentError, Result};
use crate::models::{Document, DocumentContent};
use rules::ValidationContext;

/// Validate the full document (metadata + content).
pub fn validate_document(doc: &Document) -> Result<()> {
    let mut ctx = ValidationContext::new();

    // Version gate
    if !doc.metadata.is_version_supported() {
        return Err(DocumentError::UnsupportedVersion(
            doc.metadata.version.clone(),
        ));
    }

    ctx.validate_metadata(&doc.metadata);

    match &doc.content {
        DocumentContent::Report(r) => ctx.validate_report(r),
        DocumentContent::Invoice(i) => ctx.validate_invoice(i),
        DocumentContent::Correspondence(c) => ctx.validate_correspondence(c),
    }

    ctx.finish().map_err(DocumentError::Validation)
}
