# Background Worker with Cancellation in C#

## Modern Approach: `Task` + `CancellationToken` (Recommended)

```csharp
using System;
using System.Threading;
using System.Threading.Tasks;

public class BackgroundWorkerService
{
    private CancellationTokenSource? _cts;
    private Task? _workerTask;

    // Event to report progress
    public event Action<int, string>? ProgressChanged;
    // Event to report completion
    public event Action<bool, Exception?>? WorkCompleted;

    public bool IsRunning => _workerTask != null
                          && !_workerTask.IsCompleted;

    // --- Start the background work ---
    public void Start()
    {
        if (IsRunning)
            throw new InvalidOperationException("Worker is already running.");

        _cts = new CancellationTokenSource();
        CancellationToken token = _cts.Token;

        _workerTask = Task.Run(() => DoWork(token), token);

        // Handle completion/errors without blocking
        _workerTask.ContinueWith(t =>
        {
            bool cancelled = t.IsCanceled;
            Exception? error = t.Exception?.InnerException;

            WorkCompleted?.Invoke(cancelled, error);
        });
    }

    // --- Request cancellation ---
    public void Cancel()
    {
        _cts?.Cancel();
    }

    // --- Cancel with a timeout, then force ---
    public async Task CancelAsync(TimeSpan timeout)
    {
        _cts?.Cancel();

        if (_workerTask != null)
        {
            Task completedTask = await Task.WhenAny(
                _workerTask,
                Task.Delay(timeout)
            );

            if (completedTask != _workerTask)
                Console.WriteLine("⚠ Worker did not stop within timeout.");
        }
    }

    // --- The actual work ---
    private void DoWork(CancellationToken token)
    {
        const int totalSteps = 10;

        for (int i = 1; i <= totalSteps; i++)
        {
            // ✅ Check for cancellation (throws OperationCanceledException)
            token.ThrowIfCancellationRequested();

            // Simulate work
            Thread.Sleep(1000);

            // Report progress
            int percent = (int)((double)i / totalSteps * 100);
            ProgressChanged?.Invoke(percent, $"Step {i}/{totalSteps} complete");
        }
    }

    // --- Cleanup ---
    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}
```

## Console App Demo

```csharp
class Program
{
    static async Task Main()
    {
        var worker = new BackgroundWorkerService();

        // Subscribe to events
        worker.ProgressChanged += (percent, message) =>
            Console.WriteLine($"  [{percent,3}%] {message}");

        worker.WorkCompleted += (cancelled, error) =>
        {
            if (cancelled)
                Console.WriteLine("\n🛑 Work was cancelled.");
            else if (error != null)
                Console.WriteLine($"\n❌ Error: {error.Message}");
            else
                Console.WriteLine("\n✅ Work completed successfully!");
        };

        // Start worker
        Console.WriteLine("Starting background work...");
        Console.WriteLine("Press 'C' to cancel.\n");
        worker.Start();

        // Monitor for cancel input
        while (worker.IsRunning)
        {
            if (Console.KeyAvailable && Console.ReadKey(true).Key == ConsoleKey.C)
            {
                Console.WriteLine("\nCancellation requested...");
                worker.Cancel();
                break;
            }
            await Task.Delay(100);
        }

        // Wait a moment for completion event to fire
        await Task.Delay(500);
        worker.Dispose();
    }
}
