## Legacy Approach: `BackgroundWorker` Class

```csharp
using System.ComponentModel;

// Simpler but older — use Task-based approach for new code
var bgw = new BackgroundWorker
{
    WorkerReportsProgress = true,
    WorkerSupportsCancellation = true   // ← enables cancellation
};

bgw.DoWork += (sender, e) =>
{
    var worker = (BackgroundWorker)sender!;
    for (int i = 1; i <= 10; i++)
    {
        if (worker.CancellationPending)     // ← check flag
        {
            e.Cancel = true;                // ← signal cancelled
            return;
        }
        Thread.Sleep(1000);
        worker.ReportProgress(i * 10);
    }
};

bgw.ProgressChanged += (s, e) =>
    Console.WriteLine($"Progress: {e.ProgressPercentage}%");

bgw.RunWorkerCompleted += (s, e) =>
    Console.WriteLine(e.Cancelled ? "Cancelled" : "Done");

