## Elasticsearch Indexer (with Batching)

```js
// src/indexer.js
import { Client } from '@elastic/elasticsearch';
import { config } from './config.js';
import { getSchema, getAllSchemas } from './schema.js';
import pino from 'pino';

const log = pino({ name: 'indexer' });

export class SearchIndexer {
  constructor() {
    this.client = new Client(config.elasticsearch);
    this.buffers = new Map();  // entityType -> pending docs
    this.flushTimer = null;
  }

  // Create indices with mappings on startup
  async initialize() {
    const schemas = getAllSchemas();

    for (const [type, schema] of Object.entries(schemas)) {
      const exists = await this.client.indices.exists({ index: schema.index });

      if (!exists) {
        await this.client.indices.create({
          index: schema.index,
          body: {
            mappings: schema.mappings,
            settings: schema.settings,
          },
        });
        log.info({ index: schema.index }, 'Created index');
      }
    }

    // Start periodic flush
    this.flushTimer = setInterval(
      () => this.flushAll(),
      config.batch.flushIntervalMs,
    );

    log.info('Indexer initialized');
  }

  // Handle a single job — buffers internally, flushes when batch is full
  async process(job) {
    const { action, entityType, id, document } = job.data;

    switch (action) {
      case 'upsert':
        return this.bufferUpsert(entityType, id, document);

      case 'delete':
        // Deletes happen immediately (usually low volume)
        return this.deleteDoc(entityType, id);

      case 'reindex':
        // Bulk reindex: document is an array
        return this.bulkUpsert(entityType, document);

      default:
        throw new Error(`Unknown action: ${action}`);
    }
  }

  bufferUpsert(entityType, id, document) {
    if (!this.buffers.has(entityType)) {
      this.buffers.set(entityType, []);
    }

    const buffer = this.buffers.get(entityType);
    buffer.push({ id, document: { ...document, updated_at: new Date().toISOString() } });

    if (buffer.length >= config.batch.size) {
      return this.flush(entityType);
    }
  }

  async flush(entityType) {
    const buffer = this.buffers.get(entityType);
    if (!buffer || buffer.length === 0) return;

    // Drain the buffer
    const docs = buffer.splice(0, buffer.length);
    await this.bulkUpsert(entityType, docs);
  }

  async flushAll() {
    const types = [...this.buffers.keys()];
    await Promise.allSettled(types.map((t) => this.flush(t)));
  }

  async bulkUpsert(entityType, docs) {
    if (!docs || docs.length === 0) return;

    const schema = getSchema(entityType);
    const operations = docs.flatMap(({ id, document }) => [
      { index: { _index: schema.index, _id: id } },
      document,
    ]);

    const { errors, items } = await this.client.bulk({
      refresh: false,
      operations,
    });

    if (errors) {
      const failed = items.filter((item) => item.index?.error);
      log.error(
        { count: failed.length, sample: failed[0]?.index?.error },
        'Partial bulk indexing failure',
      );
      // Throw so BullMQ retries the job
      throw new Error(`Bulk index: ${failed.length}/${items.length} failed`);
    }

    log.info({ entityType, count: docs.length }, 'Indexed batch');
  }

  async deleteDoc(entityType, id) {
    const schema = getSchema(entityType);

    try {
      await this.client.delete({ index: schema.index, id, refresh: false });
      log.info({ entityType, id }, 'Deleted document');
    } catch (err) {
      if (err.meta?.statusCode === 404) {
        log.warn({ entityType, id }, 'Document not found for deletion');
        return; // Don't retry on 404
      }
      throw err;
    }
  }

  async shutdown() {
    clearInterval(this.flushTimer);
    await this.flushAll();
    await this.client.close();
    log.info('Indexer shut down');
  }

  // Useful for health checks
  async ping() {
    return this.client.ping();
  }
}
```

## Worker

```js
// src/worker.js
import { Worker, QueueEvents } from 'bullmq';
import { config } from './config.js';
import { SearchIndexer } from './indexer.js';
import pino from 'pino';

const log = pino({ name: 'worker' });

export async function startWorker() {
  const indexer = new SearchIndexer();
  await indexer.initialize();

  const worker = new Worker(
    config.queue.name,
    async (job) => {
      log.debug({ jobId: job.id, action: job.data.action }, 'Processing job');
      await indexer.process(job);
    },
    {
      connection: config.redis,
      concurrency: config.queue.concurrency,

      // Stalled job detection
      lockDuration: 30_000,
      stalledInterval: 15_000,
      maxStalledCount: 2,
    },
  );

  // ------- Event logging -------
  worker.on('completed', (job) => {
    log.debug({ jobId: job.id }, 'Job completed');
  });

  worker.on('failed', (job, err) => {
    log.error(
      { jobId: job?.id, attempt: job?.attemptsMade, err: err.message },
      'Job failed',
    );
  });

  worker.on('error', (err) => {
    log.error({ err: err.message }, 'Worker error');
  });

  // ------- Track dead-letter jobs -------
  const events = new QueueEvents(config.queue.name, {
    connection: config.redis,
  });

  events.on('failed', ({ jobId, failedReason }) => {
    // After all retries exhausted — alert, write to DLQ table, etc.
    log.error({ jobId, failedReason }, 'Job permanently failed (DLQ)');
  });

  return { worker, indexer, events };
}
