## Entry Point with Graceful Shutdown

```js
// src/index.js
import { startWorker } from './worker.js';
import pino from 'pino';

const log = pino({ name: 'main' });

async function main() {
  log.info('Starting search index worker...');

  const { worker, indexer, events } = await startWorker();

  // ---------- Graceful shutdown ----------
  const shutdown = async (signal) => {
    log.info({ signal }, 'Shutting down...');

    // Stop accepting new jobs, finish current ones
    await worker.close();
    await events.close();
    await indexer.shutdown();

    log.info('Clean shutdown complete');
    process.exit(0);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));

  process.on('unhandledRejection', (err) => {
    log.fatal({ err }, 'Unhandled rejection');
    process.exit(1);
  });

  log.info('Worker is running. Waiting for jobs...');
}

main().catch((err) => {
  log.fatal({ err }, 'Failed to start');
  process.exit(1);
});
```

