```js
// src/producer.js
import { Queue } from 'bullmq';
import { config } from './config.js';

const queue = new Queue(config.queue.name, {
  connection: config.redis,
  defaultJobOptions: config.job,
});

// ---- Public API for your services ----

export async function indexDocument(entityType, id, document) {
  return queue.add(`upsert:${entityType}:${id}`, {
    action: 'upsert',
    entityType,
    id: String(id),
    document,
  });
}

export async function removeDocument(entityType, id) {
  return queue.add(`delete:${entityType}:${id}`, {
    action: 'delete',
    entityType,
    id: String(id),
  });
}

export async function reindexBatch(entityType, docs) {
  return queue.add(`reindex:${entityType}`, {
    action: 'reindex',
    entityType,
    document: docs, // [{ id, document }, ...]
  }, {
    // Larger jobs get longer timeout
    attempts: 3,
    timeout: 120_000,
  });
}

// ---- Test it directly ----
if (process.argv[1].includes('producer')) {
  const products = [
    { id: '1', name: 'Mechanical Keyboard', category: 'electronics', price: 149.99, tags: ['typing', 'gaming'], in_stock: true },
    { id: '2', name: 'Standing Desk', category: 'furniture', price: 599.00, tags: ['ergonomic', 'office'], in_stock: true },
    { id: '3', name: 'Noise Cancelling Headphones', category: 'electronics', price: 349.99, tags: ['audio', 'wireless'], in_stock: false },
  ];

  for (const p of products) {
    await indexDocument('product', p.id, p);
    console.log(`Enqueued: ${p.name}`);
  }

  await removeDocument('product', '999');
  console.log('Enqueued delete for id=999');

  await queue.close();
  console.log('Done. Run `npm start` to process.');
}
