// types.ts

/** Supported backup strategies */
export enum BackupStrategy {
  Full = "full",
  Incremental = "incremental",
  Differential = "differential",
}

/** Compression algorithms */
export enum CompressionType {
  None = "none",
  Gzip = "gzip",
  Zstd = "zstd",
  Lz4 = "lz4",
}

/** Schedule frequency */
export enum ScheduleFrequency {
  Hourly = "hourly",
  Daily = "daily",
  Weekly = "weekly",
  Monthly = "monthly",
  Cron = "cron",
}

/** A single source path configuration */
export interface SourceConfig {
  path: string;
  recursive: boolean;
  excludePatterns: string[];
  includePatterns: string[];
}

/** Destination / storage target */
export interface DestinationConfig {
  type: "local" | "s3" | "sftp";
  path: string;
  bucket?: string;
  region?: string;
  host?: string;
  port?: number;
  credentials?: {
    accessKey?: string;
    secretKey?: string;
    username?: string;
    keyFile?: string;
  };
}

/** How long to keep backups */
export interface RetentionPolicy {
  keepLast: number;           // Number of recent backups to retain
  keepDaily: number;          // Days of daily backups
  keepWeekly: number;         // Weeks of weekly backups
  keepMonthly: number;        // Months of monthly backups
  maxAgeDays: number;         // Hard max age limit
  forceFullEvery: number;     // Force a full backup every N incremental runs
}

/** Schedule definition */
export interface ScheduleConfig {
  frequency: ScheduleFrequency;
  cronExpression?: string;    // Used when frequency = "cron"
  timeOfDay?: string;         // HH:MM format
  dayOfWeek?: number;         // 0-6 for weekly
  dayOfMonth?: number;        // 1-31 for monthly
  timezone: string;
}

/** Incremental-specific tracking */
export interface IncrementalConfig {
  strategy: BackupStrategy;
  checksumAlgorithm: "sha256" | "xxhash" | "md5";
  blockSizeKb: number;
  detectMoves: boolean;       // Track file renames/moves
  useFileTimestamps: boolean; // Use mtime for change detection
  useFileChecksums: boolean;  // Use content hashing for change detection
}

/** Top-level backup job configuration */
export interface BackupConfig {
  version: string;
  name: string;
  description: string;
  sources: SourceConfig[];
  destination: DestinationConfig;
  retention: RetentionPolicy;
  schedule: ScheduleConfig;
  incremental: IncrementalConfig;
  compression: CompressionType;
  encryption: {
    enabled: boolean;
    algorithm: "aes-256-gcm" | "chacha20-poly1305";
    keySource: "env" | "file" | "kms";
    keyReference: string;
  };
  notifications: {
    onSuccess: boolean;
    onFailure: boolean;
    webhookUrl?: string;
    emailTo?: string[];
  };
  logging: {
    level: "debug" | "info" | "warn" | "error";
    filePath?: string;
  };
}

/** Tracks a single file's state in the manifest */
export interface FileEntry {
  relativePath: string;
  absolutePath: string;
  sizeBytes: number;
  modifiedAt: Date;
  checksum: string;
  isDirectory: boolean;
}

/** Change types between snapshots */
export enum ChangeType {
  Added = "added",
  Modified = "modified",
  Deleted = "deleted",
  Moved = "moved",
  Unchanged = "unchanged",
}

/** A detected change between two manifest snapshots */
export interface FileChange {
  type: ChangeType;
  entry: FileEntry;
  previousEntry?: FileEntry;  // For modified/moved files
  previousPath?: string;      // For moved files
}

/** Backup manifest — snapshot of state at a point in time */
export interface BackupManifest {
  id: string;
  configName: string;
  strategy: BackupStrategy;
  parentId: string | null;       // null = full backup
  createdAt: Date;
  completedAt: Date | null;
  totalFiles: number;
  totalSizeBytes: number;
  changedFiles: number;
  changedSizeBytes: number;
  entries: Map<string, FileEntry>;
  status: "pending" | "running" | "completed" | "failed";
}
