## Config Parser

```typescript
// parser.ts

import {
  BackupConfig,
  BackupStrategy,
  CompressionType,
  ScheduleFrequency,
  SourceConfig,
  DestinationConfig,
  RetentionPolicy,
  ScheduleConfig,
  IncrementalConfig,
} from "./types";
import { ParseError } from "./errors";

/** Default values applied when optional fields are missing */
const DEFAULTS: Partial<BackupConfig> = {
  version: "1.0",
  compression: CompressionType.Gzip,
  logging: { level: "info" },
  notifications: { onSuccess: false, onFailure: true },
};

const DEFAULT_RETENTION: RetentionPolicy = {
  keepLast: 10,
  keepDaily: 7,
  keepWeekly: 4,
  keepMonthly: 6,
  maxAgeDays: 365,
  forceFullEvery: 7,
};

const DEFAULT_INCREMENTAL: IncrementalConfig = {
  strategy: BackupStrategy.Incremental,
  checksumAlgorithm: "sha256",
  blockSizeKb: 64,
  detectMoves: true,
  useFileTimestamps: true,
  useFileChecksums: true,
};

/**
 * Parses a raw config object (from JSON/YAML) into a typed BackupConfig.
 * Applies defaults for missing optional fields.
 */
export function parseConfig(raw: Record<string, unknown>): BackupConfig {
  return {
    version: parseString(raw, "version", DEFAULTS.version!),
    name: parseRequiredString(raw, "name"),
    description: parseString(raw, "description", ""),
    sources: parseSources(raw),
    destination: parseDestination(raw),
    retention: parseRetention(raw),
    schedule: parseSchedule(raw),
    incremental: parseIncremental(raw),
    compression: parseEnum(
      raw,
      "compression",
      CompressionType,
      DEFAULTS.compression!
    ),
    encryption: parseEncryption(raw),
    notifications: parseNotifications(raw),
    logging: parseLogging(raw),
  };
}

/**
 * Reads and parses a config from a JSON string.
 * Handles syntax errors with line/column info.
 */
export function parseConfigFromJson(jsonString: string): BackupConfig {
  let rawObj: Record<string, unknown>;

  try {
    rawObj = JSON.parse(jsonString);
  } catch (err) {
    // Attempt to extract line info from JSON parse errors
    const match = (err as Error).message.match(/position (\d+)/);
    if (match) {
      const pos = parseInt(match[1], 10);
      const { line, column } = getLineColumn(jsonString, pos);
      throw new ParseError(`Invalid JSON syntax`, line, column);
    }
    throw new ParseError(`Invalid JSON: ${(err as Error).message}`);
  }

  if (typeof rawObj !== "object" || rawObj === null || Array.isArray(rawObj)) {
    throw new ParseError("Config root must be a JSON object");
  }

  return parseConfig(rawObj);
}

// ─── Field Parsers ─────────────────────────────────────────────────

function parseRequiredString(
  obj: Record<string, unknown>,
  field: string
): string {
  const val = obj[field];
  if (typeof val !== "string" || val.trim().length === 0) {
    throw new ParseError(`'${field}' is required and must be a non-empty string`);
  }
  return val.trim();
}

function parseString(
  obj: Record<string, unknown>,
  field: string,
  fallback: string
): string {
  const val = obj[field];
  if (val === undefined || val === null) return fallback;
  if (typeof val !== "string") {
    throw new ParseError(`'${field}' must be a string`);
  }
  return val.trim();
}

function parseNumber(
  obj: Record<string, unknown>,
  field: string,
  fallback: number
): number {
  const val = obj[field];
  if (val === undefined || val === null) return fallback;
  if (typeof val !== "number" || isNaN(val)) {
    throw new ParseError(`'${field}' must be a number`);
  }
  return val;
}

function parseBool(
  obj: Record<string, unknown>,
  field: string,
  fallback: boolean
): boolean {
  const val = obj[field];
  if (val === undefined || val === null) return fallback;
  if (typeof val !== "boolean") {
    throw new ParseError(`'${field}' must be a boolean`);
  }
  return val;
}

function parseEnum<T extends Record<string, string>>(
  obj: Record<string, unknown>,
  field: string,
  enumObj: T,
  fallback: T[keyof T]
): T[keyof T] {
  const val = obj[field];
  if (val === undefined || val === null) return fallback;
  if (typeof val !== "string") {
    throw new ParseError(`'${field}' must be a string`);
  }
  const allowed = Object.values(enumObj);
  if (!allowed.includes(val as T[keyof T])) {
    throw new ParseError(
      `'${field}' must be one of: ${allowed.join(", ")}. Got '${val}'`
    );
  }
  return val as T[keyof T];
}

function asRecord(
  obj: Record<string, unknown>,
  field: string,
  required = true
): Record<string, unknown> {
  const val = obj[field];
  if (val === undefined || val === null) {
    if (required) throw new ParseError(`'${field}' section is required`);
    return {};
  }
  if (typeof val !== "object" || Array.isArray(val)) {
    throw new ParseError(`'${field}' must be an object`);
  }
  return val as Record<string, unknown>;
}

// ─── Section Parsers ───────────────────────────────────────────────

function parseSources(raw: Record<string, unknown>): SourceConfig[] {
  const arr = raw["sources"];
  if (!Array.isArray(arr) || arr.length === 0) {
    throw new ParseError("'sources' must be a non-empty array");
  }

  return arr.map((item, idx) => {
    if (typeof item === "string") {
      // Shorthand: just a path string
      return {
        path: item,
        recursive: true,
        excludePatterns: [],
        includePatterns: [],
      };
    }

    if (typeof item !== "object" || item === null) {
      throw new ParseError(`sources[${idx}] must be a string or object`);
    }

    const src = item as Record<string, unknown>;
    return {
      path: parseRequiredString(src, "path"),
      recursive: parseBool(src, "recursive", true),
      excludePatterns: parseStringArray(src, "exclude", []),
      includePatterns: parseStringArray(src, "include", []),
    };
  });
}

function parseDestination(raw: Record<string, unknown>): DestinationConfig {
  const dest = asRecord(raw, "destination");
  const destType = parseRequiredString(dest, "type");

  if (!["local", "s3", "sftp"].includes(destType)) {
    throw new ParseError(
      `destination.type must be 'local', 's3', or 'sftp'. Got '${destType}'`
    );
  }

  const creds = dest["credentials"]
    ? (asRecord(dest, "credentials", false) as DestinationConfig["credentials"])
    : undefined;

  return {
    type: destType as DestinationConfig["type"],
    path: parseRequiredString(dest, "path"),
    bucket: parseString(dest, "bucket", ""),  || undefined,
    region: parseString(dest, "region", "") || undefined,
    host: parseString(dest, "host", "") || undefined,
    port: dest["port"] != null ? parseNumber(dest, "port", 22) : undefined,
    credentials: creds,
  };
}

function parseRetention(raw: Record<string, unknown>): RetentionPolicy {
  const section = asRecord(raw, "retention", false);
  if (Object.keys(section).length === 0) return DEFAULT_RETENTION;

  return {
    keepLast: parseNumber(section, "keepLast", DEFAULT_RETENTION.keepLast),
    keepDaily: parseNumber(section, "keepDaily", DEFAULT_RETENTION.keepDaily),
    keepWeekly: parseNumber(section, "keepWeekly", DEFAULT_RETENTION.keepWeekly),
    keepMonthly: parseNumber(section, "keepMonthly", DEFAULT_RETENTION.keepMonthly),
    maxAgeDays: parseNumber(section, "maxAgeDays", DEFAULT_RETENTION.maxAgeDays),
    forceFullEvery: parseNumber(
      section,
      "forceFullEvery",
      DEFAULT_RETENTION.forceFullEvery
    ),
  };
}

function parseSchedule(raw: Record<string, unknown>): ScheduleConfig {
  const section = asRecord(raw, "schedule");

  return {
    frequency: parseEnum(
      section,
      "frequency",
      ScheduleFrequency,
      ScheduleFrequency.Daily
    ),
    cronExpression: parseString(section, "cron", "") || undefined,
    timeOfDay: parseString(section, "timeOfDay", "02:00"),
    dayOfWeek: section["dayOfWeek"] != null
      ? parseNumber(section, "dayOfWeek", 0)
      : undefined,
    dayOfMonth: section["dayOfMonth"] != null
      ? parseNumber(section, "dayOfMonth", 1)
      : undefined,
    timezone: parseString(section, "timezone", "UTC"),
  };
}

function parseIncremental(raw: Record<string, unknown>): IncrementalConfig {
  const section = asRecord(raw, "incremental", false);
  if (Object.keys(section).length === 0) return DEFAULT_INCREMENTAL;

  return {
    strategy: parseEnum(
      section,
      "strategy",
      BackupStrategy,
      DEFAULT_INCREMENTAL.strategy
    ),
    checksumAlgorithm: parseString(
      section,
      "checksumAlgorithm",
      DEFAULT_INCREMENTAL.checksumAlgorithm
    ) as IncrementalConfig["checksumAlgorithm"],
    blockSizeKb: parseNumber(
      section,
      "blockSizeKb",
      DEFAULT_INCREMENTAL.blockSizeKb
    ),
    detectMoves: parseBool(section, "detectMoves", DEFAULT_INCREMENTAL.detectMoves),
    useFileTimestamps: parseBool(
      section,
      "useFileTimestamps",
      DEFAULT_INCREMENTAL.useFileTimestamps
    ),
    useFileChecksums: parseBool(
      section,
      "useFileChecksums",
      DEFAULT_INCREMENTAL.useFileChecksums
    ),
  };
}

function parseEncryption(raw: Record<string, unknown>) {
  const section = asRecord(raw, "encryption", false);
  const enabled = parseBool(section, "enabled", false);

  return {
    enabled,
    algorithm: parseString(section, "algorithm", "aes-256-gcm") as
      | "aes-256-gcm"
      | "chacha20-poly1305",
    keySource: parseString(section, "keySource", "env") as
      | "env"
      | "file"
      | "kms",
    keyReference: parseString(
      section,
      "keyReference",
      "BACKUP_ENCRYPTION_KEY"
    ),
  };
}

function parseNotifications(raw: Record<string, unknown>) {
  const section = asRecord(raw, "notifications", false);
  return {
    onSuccess: parseBool(section, "onSuccess", false),
    onFailure: parseBool(section, "onFailure", true),
    webhookUrl: parseString(section, "webhookUrl", "") || undefined,
    emailTo: parseStringArray(section, "emailTo", []),
  };
}

function parseLogging(raw: Record<string, unknown>) {
  const section = asRecord(raw, "logging", false);
  return {
    level: parseString(section, "level", "info") as BackupConfig["logging"]["level"],
    filePath: parseString(section, "filePath", "") || undefined,
  };
}

// ─── Utilities ─────────────────────────────────────────────────────

function parseStringArray(
  obj: Record<string, unknown>,
  field: string,
  fallback: string[]
): string[] {
  const val = obj[field];
  if (val === undefined || val === null) return fallback;
  if (!Array.isArray(val)) {
    throw new ParseError(`'${field}' must be an array of strings`);
  }
  return val.map((item, i) => {
    if (typeof item !== "string") {
      throw new ParseError(`'${field}[${i}]' must be a string`);
    }
    return item;
  });
}

function getLineColumn(
  text: string,
  position: number
): { line: number; column: number } {
  let line = 1;
  let column = 1;
  for (let i = 0; i < position && i < text.length; i++) {
    if (text[i] === "\n") {
      line++;
      column = 1;
    } else {
      column++;
    }
  }
  return { line, column };
}
