## `indexer.js` — In-Memory Inverted Index

```javascript
const fs = require("fs");
const path = require("path");

class SearchIndex {
  constructor() {
    // word -> Set of { filePath, positions[] }
    this.invertedIndex = new Map();
    // filePath -> { title, snippet, modifiedAt }
    this.documents = new Map();
  }

  /** Tokenize text into searchable terms */
  tokenize(text) {
    return text
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .split(/\s+/)
      .filter((word) => word.length > 1);
  }

  /** Add or update a file in the index */
  addDocument(filePath) {
    // Remove old entries first if updating
    this.removeDocument(filePath);

    let content;
    try {
      content = fs.readFileSync(filePath, "utf-8");
    } catch {
      console.error(`  Could not read: ${filePath}`);
      return;
    }

    const tokens = this.tokenize(content);
    const fileName = path.basename(filePath);
    const snippet = content.slice(0, 150).replace(/\n/g, " ");

    this.documents.set(filePath, {
      title: fileName,
      snippet,
      modifiedAt: new Date(),
      wordCount: tokens.length,
    });

    // Build inverted index with positions
    tokens.forEach((token, position) => {
      if (!this.invertedIndex.has(token)) {
        this.invertedIndex.set(token, new Map());
      }

      const tokenEntry = this.invertedIndex.get(token);

      if (!tokenEntry.has(filePath)) {
        tokenEntry.set(filePath, []);
      }

      tokenEntry.get(filePath).push(position);
    });

    console.log(`  Indexed: ${fileName} (${tokens.length} tokens)`);
  }

  /** Remove a file from the index */
  removeDocument(filePath) {
    if (!this.documents.has(filePath)) return;

    this.documents.delete(filePath);

    // Clean up inverted index entries
    for (const [token, fileMap] of this.invertedIndex) {
      fileMap.delete(filePath);
      if (fileMap.size === 0) {
        this.invertedIndex.delete(token);
      }
    }

    console.log(`  Removed from index: ${path.basename(filePath)}`);
  }

  /** Get index stats */
  getStats() {
    return {
      documents: this.documents.size,
      uniqueTerms: this.invertedIndex.size,
    };
  }
}

module.exports = SearchIndex;
```

## `searcher.js` — Query Engine

```javascript
class Searcher {
  constructor(index) {
    this.index = index;
  }

  /** Search the index, return ranked results */
  search(query) {
    const tokens = this.index.tokenize(query);

    if (tokens.length === 0) return [];

    // Score each document by term frequency
    const scores = new Map();

    for (const token of tokens) {
      const fileMap = this.index.invertedIndex.get(token);
      if (!fileMap) continue;

      for (const [filePath, positions] of fileMap) {
        const doc = this.index.documents.get(filePath);
        if (!doc) continue;

        const current = scores.get(filePath) || {
          filePath,
          title: doc.title,
          snippet: doc.snippet,
          score: 0,
          matches: [],
        };

        // TF score: occurrences / total words
        const tf = positions.length / doc.wordCount;
        // IDF-like boost: rarer terms score higher
        const docFreq = fileMap.size;
        const totalDocs = this.index.documents.size || 1;
        const idf = Math.log(totalDocs / docFreq) + 1;

        current.score += tf * idf;
        current.matches.push({ term: token, count: positions.length });

        scores.set(filePath, current);
      }
    }

    return Array.from(scores.values())
      .sort((a, b) => b.score - a.score)
      .map((result) => ({
        ...result,
        score: Math.round(result.score * 1000) / 1000,
      }));
  }
}

module.exports = Searcher;
```

