```javascript
const fs = require("fs");
const path = require("path");

const SUPPORTED_EXTENSIONS = new Set([".txt", ".md", ".json", ".js", ".html", ".css"]);
const DEBOUNCE_MS = 300;

class FileWatcher {
  constructor(directory, index) {
    this.directory = path.resolve(directory);
    this.index = index;
    this.debounceTimers = new Map();
    this.watcher = null;
  }

  /** Initial scan of directory */
  buildInitialIndex() {
    console.log(`\nScanning: ${this.directory}`);

    if (!fs.existsSync(this.directory)) {
      fs.mkdirSync(this.directory, { recursive: true });
      console.log("  Created watched directory");
      return;
    }

    const files = fs.readdirSync(this.directory);

    for (const file of files) {
      const filePath = path.join(this.directory, file);
      const stat = fs.statSync(filePath);

      if (stat.isFile() && this.isSupported(file)) {
        this.index.addDocument(filePath);
      }
    }

    const stats = this.index.getStats();
    console.log(`  Done: ${stats.documents} docs, ${stats.uniqueTerms} terms\n`);
  }

  /** Start watching for changes */
  start() {
    this.buildInitialIndex();

    this.watcher = fs.watch(this.directory, (eventType, filename) => {
      if (!filename || !this.isSupported(filename)) return;

      // Debounce rapid changes (editors often save multiple times)
      const key = `${eventType}-${filename}`;
      clearTimeout(this.debounceTimers.get(key));

      this.debounceTimers.set(
        key,
        setTimeout(() => {
          this.handleChange(eventType, filename);
          this.debounceTimers.delete(key);
        }, DEBOUNCE_MS)
      );
    });

    console.log("Watching for changes... (Ctrl+C to stop)\n");
  }

  /** Handle a file change event */
  handleChange(eventType, filename) {
    const filePath = path.join(this.directory, filename);
    const exists = fs.existsSync(filePath);
    const timestamp = new Date().toLocaleTimeString();

    if (exists) {
      console.log(`[${timestamp}] Changed: ${filename}`);
      this.index.addDocument(filePath);
    } else {
      console.log(`[${timestamp}] Deleted: ${filename}`);
      this.index.removeDocument(filePath);
    }

    const stats = this.index.getStats();
    console.log(`  Index: ${stats.documents} docs, ${stats.uniqueTerms} terms\n`);
  }

  isSupported(filename) {
    return SUPPORTED_EXTENSIONS.has(path.extname(filename).toLowerCase());
  }

  stop() {
    if (this.watcher) {
      this.watcher.close();
      console.log("\nWatcher stopped.");
    }
  }
}

module.exports = FileWatcher;
```

## `index.js` — Entry Point with REPL

```javascript
const readline = require("readline");
const SearchIndex = require("./indexer");
const FileWatcher = require("./watcher");
const Searcher = require("./searcher");

const WATCH_DIR = process.argv[2] || "./content";

// --- Setup ---
const index = new SearchIndex();
const watcher = new FileWatcher(WATCH_DIR, index);
const searcher = new Searcher(index);

watcher.start();

// --- Interactive Search REPL ---
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  prompt: "search> ",
});

rl.prompt();

rl.on("line", (line) => {
  const input = line.trim();

  if (!input) {
    rl.prompt();
    return;
  }

  if (input === ":quit") {
    watcher.stop();
    process.exit(0);
  }

  if (input === ":stats") {
    console.log(index.getStats());
    rl.prompt();
    return;
  }

  // Search
  const results = searcher.search(input);

  if (results.length === 0) {
    console.log("  No results.\n");
  } else {
    console.log(`  ${results.length} result(s):\n`);
    results.forEach((r, i) => {
      console.log(`  ${i + 1}. ${r.title}  (score: ${r.score})`);
      console.log(`     Matches: ${r.matches.map((m) => `${m.term}(${m.count})`).join(", ")}`);
      console.log(`     ${r.snippet}...`);
      console.log();
    });
  }

  rl.prompt();
});

// --- Cleanup ---
process.on("SIGINT", () => {
  watcher.stop();
  process.exit(0);
});
```

