## Key Design Decisions

| Aspect | Choice | Why |
|---|---|---|
| **Index type** | Inverted index (term → docs) | Standard for full-text search |
| **Ranking** | TF-IDF scoring | Balances frequency vs. rarity |
| **Debouncing** | 300ms timer per event | Editors trigger multiple saves |
| **Tokenization** | Lowercase + alphanumeric split | Simple but effective baseline |
| **Storage** | In-memory `Map` | Fast; rebuilds on restart |

# Debugging a Chat Moderation Linter in Node.js

Below is a buggy chat moderation linter, followed by the debugged version with detailed explanations.

## Buggy Code (Before)

```javascript
// ❌ BUGGY VERSION — chatModLinter.js

class ChatModerationLinter {
  constructor(config) {
    // BUG 1: No default config — crashes if config is undefined
    this.bannedWords = config.bannedWords;
    this.maxMessageLength = config.maxMessageLength;
    this.maxCapsPercent = config.maxCapsPercent;
    this.maxRepeatedChars = config.maxRepeatedChars;
    this.linkWhitelist = config.linkWhitelist;
    this.rateLimit = config.rateLimit;
    this.userMessageTimestamps = {};
  }

  // BUG 2: Doesn't handle null/undefined/non-string messages
  lint(message, userId) {
    const violations = [];

    violations.push(this.checkBannedWords(message));       // BUG 3: pushes arrays into array
    violations.push(this.checkMessageLength(message));
    violations.push(this.checkExcessiveCaps(message));
    violations.push(this.checkRepeatedChars(message));
    violations.push(this.checkLinks(message));
    violations.push(this.checkRateLimit(userId));

    return {
      passed: violations.length == 0,  // BUG 4: loose equality + always has items
      violations: violations,
      sanitized: this.sanitize(message),
    };
  }

  checkBannedWords(message) {
    const found = [];
    // BUG 5: Case-sensitive comparison — "BadWord" bypasses "badword"
    for (const word of this.bannedWords) {
      // BUG 6: Simple `includes` matches partial words ("hello" matches "shell")
      if (message.includes(word)) {
        found.push({
          rule: "banned_word",
          severity: "high",
          detail: `Banned word detected: "${word}"`,
        });
      }
    }
    return found;
  }

  checkMessageLength(message) {
    if (message.length > this.maxMessageLength) {
      return {
        rule: "max_length",
        severity: "medium",
        detail: `Message exceeds ${this.maxMessageLength} characters`,
      };
    }
    // BUG 7: Returns undefined instead of empty array on pass
  }

  checkExcessiveCaps(message) {
    // BUG 8: Counts non-alpha chars as total, skewing percentage
    const upperCount = message.replace(/[^A-Z]/g, "").length;
    const totalCount = message.length;

    if (totalCount > 0 && (upperCount / totalCount) > this.maxCapsPercent) {
      return {
        rule: "excessive_caps",
        severity: "low",
        detail: `Message is ${((upperCount / totalCount) * 100).toFixed(1)}% caps`,
      };
    }
    return [];
  }

  checkRepeatedChars(message) {
    // BUG 9: Regex not constructed correctly — doesn't use dynamic value
    const regex = new RegExp("(.)\\1{maxRepeatedChars,}", "g");
    const matches = message.match(regex);

    if (matches) {
      return matches.map((m) => ({
        rule: "repeated_chars",
        severity: "low",
        detail: `Repeated characters: "${m}"`,
      }));
    }
    return [];
  }

  checkLinks(message) {
    const urlRegex = /https?:\/\/[^\s]+/g;  // BUG 10: Misses protocol-less URLs
    const urls = message.match(urlRegex) || [];
    const violations = [];

    for (const url of urls) {
      // BUG 11: Whitelist check uses exact match (fails with paths/params)
      if (!this.linkWhitelist.includes(url)) {
        violations.push({
          rule: "unapproved_link",
          severity: "high",
          detail: `Unapproved link: "${url}"`,
        });
      }
    }
    return violations;
  }

  checkRateLimit(userId) {
    const now = Date.now();
    // BUG 12: Never initializes user's timestamp array
    this.userMessageTimestamps[userId].push(now);

    // BUG 13: Never cleans up old timestamps — memory leak
    const recentCount = this.userMessageTimestamps[userId].length;

    if (recentCount > this.rateLimit.maxMessages) {
      return {
        rule: "rate_limit",
        severity: "high",
        detail: `Rate limit exceeded: ${recentCount}/${this.rateLimit.maxMessages} messages`,
      };
    }
    return [];
  }

  sanitize(message) {
    let sanitized = message;
    for (const word of this.bannedWords) {
      // BUG 14: Only replaces first occurrence
      sanitized = sanitized.replace(word, "*".repeat(word.length));
    }
    return sanitized;
  }
}

module.exports = ChatModerationLinter;
