## Fixed & Debugged Code (After)

```javascript
// ✅ FIXED VERSION — chatModLinter.js

class ChatModerationLinter {
  /**
   * @param {Object} config - Moderation rule configuration
   */
  constructor(config = {}) {
    // FIX 1: Provide sensible defaults for every config property
    const defaults = {
      bannedWords: [],
      maxMessageLength: 500,
      maxCapsPercent: 0.7,
      maxRepeatedChars: 4,
      linkWhitelist: [],
      rateLimit: { maxMessages: 5, windowMs: 10_000 },
    };

    const merged = { ...defaults, ...config };

    this.bannedWords = merged.bannedWords.map((w) => w.toLowerCase());
    this.maxMessageLength = merged.maxMessageLength;
    this.maxCapsPercent = merged.maxCapsPercent;
    this.maxRepeatedChars = merged.maxRepeatedChars;
    this.linkWhitelist = merged.linkWhitelist.map((d) => d.toLowerCase());
    this.rateLimit = merged.rateLimit;

    /** @type {Record<string, number[]>} */
    this.userMessageTimestamps = {};

    // Pre-compile banned-word regexes for word-boundary matching
    // FIX 6: Use word boundaries so "hell" doesn't match "shell"
    this.bannedWordPatterns = this.bannedWords.map((word) => ({
      word,
      regex: new RegExp(`\\b${this._escapeRegex(word)}\\b`, "gi"),
    }));
  }

  // ──────────────────────────────────────────────
  //  Main lint entry point
  // ──────────────────────────────────────────────

  /**
   * Lint a chat message and return violations.
   * @param {*} message - The chat message
   * @param {string} userId - Unique user identifier
   * @returns {{ passed: boolean, violations: object[], sanitized: string }}
   */
  lint(message, userId) {
    // FIX 2: Validate input — handle null, undefined, non-string
    if (message == null || typeof message !== "string") {
      return {
        passed: false,
        violations: [
          {
            rule: "invalid_input",
            severity: "high",
            detail: "Message must be a non-null string",
          },
        ],
        sanitized: "",
      };
    }

    const trimmed = message.trim();

    // FIX 3: Use .flat() or spread to flatten sub-arrays into one list
    const checks = [
      this.checkBannedWords(trimmed),
      this.checkMessageLength(trimmed),
      this.checkExcessiveCaps(trimmed),
      this.checkRepeatedChars(trimmed),
      this.checkLinks(trimmed),
      this.checkRateLimit(userId),
    ];

    // Flatten & filter: each check returns an array of violations
    const violations = checks.flat().filter(Boolean);

    return {
      passed: violations.length === 0, // FIX 4: Strict equality + correct logic
      violations,
      sanitized: this.sanitize(trimmed),
    };
  }

  // ──────────────────────────────────────────────
  //  Individual rule checks (each returns an array)
  // ──────────────────────────────────────────────

  /** FIX 5 & 6: Case-insensitive, word-boundary matching */
  checkBannedWords(message) {
    const found = [];

    for (const { word, regex } of this.bannedWordPatterns) {
      regex.lastIndex = 0; // reset stateful regex
      if (regex.test(message)) {
        found.push({
          rule: "banned_word",
          severity: "high",
          detail: `Banned word detected: "${word}"`,
        });
      }
    }
    return found;
  }

  /** FIX 7: Always return an array (empty on pass) */
  checkMessageLength(message) {
    if (message.length > this.maxMessageLength) {
      return [
        {
          rule: "max_length",
          severity: "medium",
          detail: `Message exceeds ${this.maxMessageLength} chars (got ${message.length})`,
        },
      ];
    }
    return []; // Consistent return type
  }

  /** FIX 8: Count only alphabetic characters for caps percentage */
  checkExcessiveCaps(message) {
    const alphaOnly = message.replace(/[^a-zA-Z]/g, "");
    const upperCount = alphaOnly.replace(/[^A-Z]/g, "").length;
    const totalAlpha = alphaOnly.length;

    if (totalAlpha > 5 && upperCount / totalAlpha > this.maxCapsPercent) {
      return [
        {
          rule: "excessive_caps",
          severity: "low",
          detail: `Message is ${((upperCount / totalAlpha) * 100).toFixed(1)}% caps`,
        },
      ];
    }
    return [];
  }

  /** FIX 9: Interpolate `maxRepeatedChars` into the RegExp string */
  checkRepeatedChars(message) {
    const regex = new RegExp(`(.)\\1{${this.maxRepeatedChars},}`, "gi");
    const matches = message.match(regex);

    if (matches) {
      return matches.map((m) => ({
        rule: "repeated_chars",
        severity: "low",
        detail: `Repeated characters: "${m}"`,
      }));
    }
    return [];
  }

  /** FIX 10 & 11: Catch protocol-less URLs; whitelist by domain */
  checkLinks(message) {
    // Matches URLs with or without protocol
    const urlRegex =
      /(?:https?:\/\/)?(?:www\.)?([a-zA-Z0-9-]+(?:\.[a-zA-Z]{2,})+)(\/[^\s]*)?/gi;

    const violations = [];
    let match;

    while ((match = urlRegex.exec(message)) !== null) {
      const domain = match[1].toLowerCase();

      // FIX 11: Check if the *domain* is whitelisted (not full URL)
      const isWhitelisted = this.linkWhitelist.some(
        (allowed) => domain === allowed || domain.endsWith(`.${allowed}`)
      );

      if (!isWhitelisted) {
        violations.push({
          rule: "unapproved_link",
          severity: "high",
          detail: `Unapproved link domain: "${domain}"`,
        });
      }
    }
    return violations;
  }

  /** FIX 12 & 13: Initialize user bucket; prune old timestamps */
  checkRateLimit(userId) {
    if (!userId) return [];

    const now = Date.now();
    const windowMs = this.rateLimit.windowMs;

    // FIX 12: Lazily initialize the timestamps array
    if (!this.userMessageTimestamps[userId]) {
      this.userMessageTimestamps[userId] = [];
    }

    const timestamps = this.userMessageTimestamps[userId];
    timestamps.push(now);

    // FIX 13: Prune timestamps outside the sliding window (prevent leak)
    this.userMessageTimestamps[userId] = timestamps.filter(
      (ts) => now - ts <= windowMs
    );

    const recentCount = this.userMessageTimestamps[userId].length;

    if (recentCount > this.rateLimit.maxMessages) {
      return [
        {
          rule: "rate_limit",
          severity: "high",
          detail: `Rate limit exceeded: ${recentCount}/${this.rateLimit.maxMessages} in ${windowMs / 1000}s`,
        },
      ];
    }
    return [];
  }

  // ──────────────────────────────────────────────
  //  Sanitizer
  // ──────────────────────────────────────────────

  /** FIX 14: Replace ALL occurrences using the pre-compiled global regex */
  sanitize(message) {
    let sanitized = message;

    for (const { word, regex } of this.bannedWordPatterns) {
      regex.lastIndex = 0;
      sanitized = sanitized.replace(regex, "*".repeat(word.length));
    }
    return sanitized;
  }

  // ──────────────────────────────────────────────
  //  Helpers
  // ──────────────────────────────────────────────

  /** Escape special regex characters in a string */
  _escapeRegex(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
}

module.exports = ChatModerationLinter;
```

