## Unit Tests

```javascript
// chatModLinter.test.js
const ChatModerationLinter = require("./chatModLinter");

describe("ChatModerationLinter", () => {
  let linter;

  beforeEach(() => {
    linter = new ChatModerationLinter({
      bannedWords: ["badword", "evil"],
      maxMessageLength: 100,
      maxCapsPercent: 0.7,
      maxRepeatedChars: 4,
      linkWhitelist: ["example.com", "trusted.org"],
      rateLimit: { maxMessages: 3, windowMs: 5000 },
    });
  });

  // ── Input validation ──────────────────────────
  test("rejects null/undefined messages", () => {
    const result = linter.lint(null, "user1");
    expect(result.passed).toBe(false);
    expect(result.violations[0].rule).toBe("invalid_input");
  });

  // ── Banned words ──────────────────────────────
  test("detects banned words (case-insensitive)", () => {
    const result = linter.lint("This is a BADWORD test", "user1");
    expect(result.passed).toBe(false);
    expect(result.violations).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ rule: "banned_word" }),
      ])
    );
  });

  test("does NOT flag partial word matches", () => {
    // "evil" should not match inside "medieval"
    const result = linter.lint("I love medieval history", "user1");
    const bannedHits = result.violations.filter((v) => v.rule === "banned_word");
    expect(bannedHits).toHaveLength(0);
  });

  // ── Message length ────────────────────────────
  test("flags messages exceeding max length", () => {
    const longMsg = "a".repeat(101);
    const result = linter.lint(longMsg, "user1");
    expect(result.violations).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ rule: "max_length" }),
      ])
    );
  });

  // ── Excessive caps ────────────────────────────
  test("flags excessive caps (alpha-only percentage)", () => {
    const result = linter.lint("THIS IS SHOUTING!!!", "user1");
    expect(result.violations).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ rule: "excessive_caps" }),
      ])
    );
  });

  test("ignores short messages for caps check", () => {
    const result = linter.lint("OK", "user1");
    const capsHits = result.violations.filter(
      (v) => v.rule === "excessive_caps"
    );
    expect(capsHits).toHaveLength(0);
  });

  // ── Repeated characters ───────────────────────
  test("detects repeated characters", () => {
    const result = linter.lint("Hellooooooo there", "user1");
    expect(result.violations).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ rule: "repeated_chars" }),
      ])
    );
  });

  // ── Link checking ─────────────────────────────
  test("allows whitelisted domains", () => {
    const result = linter.lint("Visit https://example.com/page", "user1");
    const linkHits = result.violations.filter(
      (v) => v.rule === "unapproved_link"
    );
    expect(linkHits).toHaveLength(0);
  });

  test("flags non-whitelisted domains", () => {
    const result = linter.lint("Go to malicious-site.com", "user1");
    expect(result.violations).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ rule: "unapproved_link" }),
      ])
    );
  });

  // ── Rate limiting ─────────────────────────────
  test("enforces rate limit with sliding window", () => {
    linter.lint("msg1", "user1");
    linter.lint("msg2", "user1");
    linter.lint("msg3", "user1");
    const result = linter.lint("msg4", "user1"); // exceeds limit of 3
    expect(result.violations).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ rule: "rate_limit" }),
      ])
    );
  });

  // ── Sanitizer ─────────────────────────────────
  test("sanitizes ALL occurrences of banned words", () => {
    const result = linter.lint("badword and badword again", "user1");
    expect(result.sanitized).toBe("******* and ******* again");
  });

  // ── Default config ────────────────────────────
  test("works with no config (uses defaults)", () => {
    const defaultLinter = new ChatModerationLinter();
    const result = defaultLinter.lint("Hello world", "user1");
    expect(result.passed).toBe(true);
  });
});
