## src/taskQueue.js — Priority Queue with Concurrency

```javascript
import { EventEmitter } from "node:events";
import { logger } from "./logger.js";

export class TaskQueue extends EventEmitter {
  #queue = [];
  #running = new Map();          // taskId -> AbortController
  #maxConcurrent;
  #retryAttempts;
  #retryDelayMs;
  #processed = 0;
  #failed = 0;

  constructor({ maxConcurrent = 3, retryAttempts = 2, retryDelayMs = 1000 } = {}) {
    super();
    this.#maxConcurrent = maxConcurrent;
    this.#retryAttempts = retryAttempts;
    this.#retryDelayMs = retryDelayMs;
  }

  /**
   * Add a task to the queue.
   * Deduplicates by taskId — if a task with the same ID is already
   * queued (not yet running), the newer one replaces it.
   */
  enqueue(task) {
    // task shape: { id, name, priority, execute(signal), filePath, event }
    const existing = this.#queue.findIndex((t) => t.id === task.id);

    if (existing !== -1) {
      this.#queue[existing] = task;               // replace stale entry
      logger.debug(`Deduped queued task: ${task.id}`);
    } else {
      this.#queue.push(task);
    }

    // Sort: lower priority number = higher urgency
    this.#queue.sort((a, b) => a.priority - b.priority);

    logger.info(`Enqueued task: ${task.name}`, {
      id: task.id,
      priority: task.priority,
      queueSize: this.#queue.length,
    });

    this.#drain();
  }

  async #drain() {
    while (this.#running.size < this.#maxConcurrent && this.#queue.length > 0) {
      const task = this.#queue.shift();
      this.#runTask(task);          // fire-and-forget; errors handled inside
    }
  }

  async #runTask(task, attempt = 1) {
    const ac = new AbortController();
    this.#running.set(task.id, ac);

    const startTime = performance.now();
    logger.info(`Running task: ${task.name} (attempt ${attempt})`, { id: task.id });

    try {
      await task.execute(ac.signal);

      const duration = (performance.now() - startTime).toFixed(1);
      this.#processed++;
      logger.info(`Task completed: ${task.name} in ${duration}ms`);
      this.emit("completed", task);
    } catch (err) {
      if (ac.signal.aborted) {
        logger.warn(`Task aborted: ${task.name}`);
        this.emit("aborted", task);
      } else if (attempt < this.#retryAttempts) {
        logger.warn(`Task failed, retrying: ${task.name}`, { error: err.message });
        await this.#delay(this.#retryDelayMs * attempt);
        this.#running.delete(task.id);
        return this.#runTask(task, attempt + 1);
      } else {
        this.#failed++;
        logger.error(`Task failed permanently: ${task.name}`, { error: err.message });
        this.emit("failed", task, err);
      }
    } finally {
      this.#running.delete(task.id);
      this.#drain();                // pick up next queued task
    }
  }

  /** Cancel a running task by ID. */
  cancel(taskId) {
    const ac = this.#running.get(taskId);
    if (ac) {
      ac.abort();
      logger.info(`Cancelled task: ${taskId}`);
    }
  }

  /** Cancel everything. */
  cancelAll() {
    for (const [id, ac] of this.#running) {
      ac.abort();
    }
    this.#queue.length = 0;
    logger.info("All tasks cancelled");
  }

  get stats() {
    return {
      queued: this.#queue.length,
      running: this.#running.size,
      processed: this.#processed,
      failed: this.#failed,
    };
  }

  #delay(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}
