## src/taskRunner.js — Loads & Builds Executable Tasks

```javascript
import { readFile } from "node:fs/promises";
import { resolve, relative, extname } from "node:path";
import { minimatch } from "minimatch";
import { logger } from "./logger.js";

/**
 * Registry of task handlers.
 * Each handler is an async function: (filePath, event, signal) => void
 */
const handlers = new Map();

export function registerHandler(name, fn) {
  handlers.set(name, fn);
  logger.info(`Registered task handler: ${name}`);
}

/**
 * Holds cooldown timestamps per rule so we don't
 * fire the same rule too rapidly.
 */
const cooldowns = new Map();

/**
 * Given a file event, return an array of runnable task objects
 * that match the config rules.
 */
export function matchTasks(filePath, event, rules) {
  const relPath = relative(process.cwd(), resolve(filePath));

  return rules
    .filter((rule) => {
      // Event must match
      if (!rule.events.includes(event)) return false;

      // Glob must match
      if (!minimatch(relPath, rule.pattern)) return false;

      // Cooldown check
      if (rule.cooldownMs) {
        const lastRun = cooldowns.get(rule.name) ?? 0;
        if (Date.now() - lastRun < rule.cooldownMs) {
          logger.debug(`Skipping rule "${rule.name}" — cooldown active`);
          return false;
        }
      }

      return true;
    })
    .map((rule) => {
      // Mark cooldown
      if (rule.cooldownMs) cooldowns.set(rule.name, Date.now());

      const handler = handlers.get(rule.task);
      if (!handler) {
        logger.warn(`No handler registered for task: ${rule.task}`);
        return null;
      }

      return {
        id: `${rule.name}::${relPath}`,
        name: `${rule.name} → ${relPath}`,
        priority: rule.priority ?? 5,
        filePath: relPath,
        event,
        execute: (signal) => handler(relPath, event, signal),
      };
    })
    .filter(Boolean);
}
