## src/watcher.js — Chokidar Wrapper with Debouncing

```javascript
import chokidar from "chokidar";
import { logger } from "./logger.js";

export class FileWatcher {
  #watcher = null;
  #debounceTimers = new Map();
  #debounceMs;
  #callback;

  /**
   * @param {object} opts
   * @param {string[]}  opts.paths       - Directories / globs to watch
   * @param {string[]}  opts.ignored     - Globs to ignore
   * @param {number}    opts.debounceMs  - Debounce window per file
   * @param {function}  opts.onChange     - (filePath, event) => void
   */
  constructor({ paths, ignored = [], debounceMs = 300, onChange }) {
    this.#debounceMs = debounceMs;
    this.#callback = onChange;

    this.#watcher = chokidar.watch(paths, {
      ignored,
      persistent: true,
      ignoreInitial: true,          // don't fire on startup scan
      awaitWriteFinish: {           // wait for large file writes to complete
        stabilityThreshold: 200,
        pollInterval: 50,
      },
    });

    // Bind the events we care about
    for (const event of ["add", "change", "unlink"]) {
      this.#watcher.on(event, (filePath) => this.#debounce(filePath, event));
    }

    this.#watcher.on("ready", () => {
      const watched = this.#watcher.getWatched();
      const dirCount = Object.keys(watched).length;
      logger.info(`Watcher ready — monitoring ${dirCount} directories`);
    });

    this.#watcher.on("error", (err) => {
      logger.error("Watcher error", { error: err.message });
    });
  }

  /**
   * Debounce per-file so rapid saves don't trigger
   * the same task ten times.
   */
  #debounce(filePath, event) {
    const key = `${event}::${filePath}`;

    if (this.#debounceTimers.has(key)) {
      clearTimeout(this.#debounceTimers.get(key));
    }

    const timer = setTimeout(() => {
      this.#debounceTimers.delete(key);
      logger.debug(`File ${event}: ${filePath}`);
      this.#callback(filePath, event);
    }, this.#debounceMs);

    this.#debounceTimers.set(key, timer);
  }

  async close() {
    // Clear pending debounce timers
    for (const timer of this.#debounceTimers.values()) {
      clearTimeout(timer);
    }
    this.#debounceTimers.clear();

    if (this.#watcher) {
      await this.#watcher.close();
      logger.info("Watcher closed");
    }
  }
}
