## tasks/lintTask.js

```javascript
import { readFile } from "node:fs/promises";
import { extname } from "node:path";
import { logger } from "../src/logger.js";

/**
 * Lightweight lint checks — no external dependency needed.
 * Swap in ESLint for real usage.
 */
export async function lintTask(filePath, event, signal) {
  // Respect cancellation
  signal?.throwIfAborted();

  const content = await readFile(filePath, "utf-8");
  const lines = content.split("\n");
  const issues = [];

  lines.forEach((line, i) => {
    if (line.length > 120) {
      issues.push({ line: i + 1, rule: "max-line-length", message: `Line exceeds 120 chars (${line.length})` });
    }
    if (line.includes("console.log")) {
      issues.push({ line: i + 1, rule: "no-console", message: "Unexpected console.log" });
    }
    if (/\t/.test(line)) {
      issues.push({ line: i + 1, rule: "no-tabs", message: "Tab character found" });
    }
  });

  if (issues.length > 0) {
    logger.warn(`Lint: ${issues.length} issue(s) in ${filePath}`);
    issues.forEach((issue) => {
      logger.warn(`  L${issue.line} [${issue.rule}] ${issue.message}`);
    });
  } else {
    logger.info(`Lint: ${filePath} — clean`);
  }
}
