## src/index.js — Entry Point (Wires Everything Together)

```javascript
import { readFile, mkdir } from "node:fs/promises";
import { existsSync } from "node:fs";

import { FileWatcher } from "./watcher.js";
import { TaskQueue } from "./taskQueue.js";
import { registerHandler, matchTasks } from "./taskRunner.js";
import { logger } from "./logger.js";

// --- Load task handlers -------------------------------------------
import { compileTask } from "../tasks/compileTask.js";
import { lintTask } from "../tasks/lintTask.js";
import { deployTask } from "../tasks/deployTask.js";

registerHandler("compile", compileTask);
registerHandler("lint", lintTask);
registerHandler("deploy", deployTask);

// --- Load config --------------------------------------------------
const config = JSON.parse(await readFile("./config.json", "utf-8"));

// Ensure watched directories exist
for (const dir of config.watchPaths) {
  if (!existsSync(dir)) {
    await mkdir(dir, { recursive: true });
    logger.info(`Created watch directory: ${dir}`);
  }
}

// --- Initialize queue ---------------------------------------------
const queue = new TaskQueue({
  maxConcurrent: config.maxConcurrent,
  retryAttempts: config.retryAttempts,
  retryDelayMs: config.retryDelayMs,
});

queue.on("completed", (task) => {
  logger.debug("Queue stats", queue.stats);
});

queue.on("failed", (task, err) => {
  logger.error(`Permanent failure: ${task.name}`, { error: err.message });
});

// --- Initialize watcher -------------------------------------------
const watcher = new FileWatcher({
  paths: config.watchPaths,
  ignored: config.ignored,
  debounceMs: config.debounceMs,
  onChange(filePath, event) {
    const tasks = matchTasks(filePath, event, config.rules);
    for (const task of tasks) {
      queue.enqueue(task);
    }
  },
});

// --- Status report on interval ------------------------------------
const statusInterval = setInterval(() => {
  const s = queue.stats;
  if (s.queued || s.running) {
    logger.info("Queue status", s);
  }
}, 10_000);

// --- Graceful shutdown --------------------------------------------
async function shutdown(signal) {
  logger.info(`Received ${signal} — shutting down`);
  clearInterval(statusInterval);
  queue.cancelAll();
  await watcher.close();
  logger.info("Goodbye", queue.stats);
  process.exit(0);
}

process.on("SIGINT", () => shutdown("SIGINT"));
process.on("SIGTERM", () => shutdown("SIGTERM"));

logger.info("File watcher scheduler started", {
  watchPaths: config.watchPaths,
  rules: config.rules.length,
});
