```javascript
const { EventEmitter } = require("events");

class PipelineError extends Error {
  constructor(stageName, originalError) {
    super(`Pipeline failed at stage "${stageName}": ${originalError.message}`);
    this.stageName = stageName;
    this.originalError = originalError;
  }
}

class Pipeline extends EventEmitter {
  constructor(name = "unnamed") {
    super();
    this.name = name;
    this.stages = [];
    this.metrics = {
      inputCount: 0,
      outputCount: 0,
      stageMetrics: {},
      startTime: null,
      endTime: null,
    };
  }

  /** Register a named stage (function: data[] => data[]) */
  addStage(name, fn) {
    if (typeof fn !== "function") {
      throw new TypeError(`Stage "${name}" must be a function`);
    }
    this.stages.push({ name, fn });
    this.metrics.stageMetrics[name] = { inputCount: 0, outputCount: 0, durationMs: 0 };
    return this; // allow chaining
  }

  /** Run all stages sequentially on the input data */
  async run(data) {
    if (!Array.isArray(data)) {
      throw new TypeError("Pipeline input must be an array");
    }

    this.metrics.startTime = Date.now();
    this.metrics.inputCount = data.length;
    this.emit("start", { pipeline: this.name, recordCount: data.length });

    let current = [...data]; // shallow copy to avoid mutation

    for (const stage of this.stages) {
      const stageStart = Date.now();
      const inputCount = current.length;

      this.emit("stage:start", { stage: stage.name, recordCount: inputCount });

      try {
        current = await stage.fn(current);
      } catch (err) {
        const pipelineErr = new PipelineError(stage.name, err);
        this.emit("error", pipelineErr);
        throw pipelineErr;
      }

      if (!Array.isArray(current)) {
        // Stages that produce a single summary wrap it in an array
        current = [current];
      }

      const durationMs = Date.now() - stageStart;
      this.metrics.stageMetrics[stage.name] = {
        inputCount,
        outputCount: current.length,
        durationMs,
      };

      this.emit("stage:end", {
        stage: stage.name,
        inputCount,
        outputCount: current.length,
        durationMs,
      });
    }

    this.metrics.outputCount = current.length;
    this.metrics.endTime = Date.now();
    this.emit("end", {
      pipeline: this.name,
      totalDurationMs: this.metrics.endTime - this.metrics.startTime,
      outputCount: current.length,
    });

    return current;
  }

  /** Return a copy of collected metrics */
  getMetrics() {
    return { ...this.metrics };
  }

  /** Remove all stages and reset metrics */
  reset() {
    this.stages = [];
    this.metrics = {
      inputCount: 0,
      outputCount: 0,
      stageMetrics: {},
      startTime: null,
      endTime: null,
    };
    return this;
  }
}

module.exports = { Pipeline, PipelineError };
```

## src/stages.js — Reusable Stage Factories

```javascript
/**
 * Reusable, composable stage factories.
 * Each factory returns a function: data[] => data[]
 */

/** Keep only records matching the predicate */
function filter(predicate) {
  return (data) => data.filter(predicate);
}

/** Transform every record */
function map(transformFn) {
  return (data) => data.map(transformFn);
}

/** Group records by a key-extractor and run a reducer per group */
function groupBy(keyFn, reducerFn, initialValueFn = () => ({})) {
  return (data) => {
    const groups = {};

    for (const record of data) {
      const key = keyFn(record);
      if (!groups[key]) {
        groups[key] = { key, records: [], accumulator: initialValueFn() };
      }
      groups[key].records.push(record);
      groups[key].accumulator = reducerFn(groups[key].accumulator, record);
    }

    return Object.values(groups).map(({ key, accumulator, records }) => ({
      groupKey: key,
      count: records.length,
      ...accumulator,
    }));
  };
}

/** Sort records by a comparator or key function */
function sort(compareFnOrKey, direction = "asc") {
  return (data) => {
    const sorted = [...data];

    if (typeof compareFnOrKey === "function" && compareFnOrKey.length === 2) {
      // it's a full comparator (a, b) => number
      sorted.sort(compareFnOrKey);
    } else {
      // it's a key extractor
      const keyFn =
        typeof compareFnOrKey === "function"
          ? compareFnOrKey
          : (r) => r[compareFnOrKey];
      const mult = direction === "desc" ? -1 : 1;
      sorted.sort((a, b) => {
        const ka = keyFn(a);
        const kb = keyFn(b);
        if (ka < kb) return -1 * mult;
        if (ka > kb) return 1 * mult;
        return 0;
      });
    }

    return sorted;
  };
}

/** Take only the first N records */
function limit(n) {
  return (data) => data.slice(0, n);
}

/** Remove duplicate records based on a key function */
function deduplicate(keyFn) {
  return (data) => {
    const seen = new Set();
    return data.filter((record) => {
      const key = keyFn(record);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  };
}

/** Add / derive new fields on each record */
function enrich(enrichFn) {
  return (data) =>
    data.map((record) => ({
      ...record,
      ...enrichFn(record),
    }));
}

/** Generic aggregation that collapses the whole dataset into one summary */
function aggregate(aggregatorFn) {
  return (data) => [aggregatorFn(data)];
}

module.exports = {
  filter,
  map,
  groupBy,
  sort,
  limit,
  deduplicate,
  enrich,
  aggregate,
};
```

## src/analytics.js — Domain-Specific Analytics Helpers

```javascript
const { Pipeline } = require("./pipeline");
const stages = require("./stages");

/** ---- Metric calculators ---- */

function sum(arr, keyFn) {
  return arr.reduce((total, item) => total + (keyFn(item) || 0), 0);
}

function average(arr, keyFn) {
  if (arr.length === 0) return 0;
  return sum(arr, keyFn) / arr.length;
}

function min(arr, keyFn) {
  return arr.reduce(
    (m, item) => Math.min(m, keyFn(item)),
    Number.POSITIVE_INFINITY
  );
}

function max(arr, keyFn) {
  return arr.reduce(
    (m, item) => Math.max(m, keyFn(item)),
    Number.NEGATIVE_INFINITY
  );
}

function percentile(arr, keyFn, p) {
  const sorted = arr.map(keyFn).sort((a, b) => a - b);
  const idx = Math.ceil((p / 100) * sorted.length) - 1;
  return sorted[Math.max(0, idx)];
}

/** ---- Pre-built analytics pipelines ---- */

/** Page-view analytics: groups by page, counts views, averages duration */
function createPageViewPipeline() {
  return new Pipeline("page-views")
    .addStage(
      "filter-pageviews",
      stages.filter((e) => e.event === "pageview")
    )
    .addStage(
      "group-by-page",
      stages.groupBy(
        (e) => e.page,
        (acc, e) => ({
          totalDuration: (acc.totalDuration || 0) + (e.duration || 0),
        }),
        () => ({ totalDuration: 0 })
      )
    )
    .addStage(
      "enrich-avg-duration",
      stages.enrich((r) => ({
        avgDuration: r.count > 0 ? Math.round(r.totalDuration / r.count) : 0,
      }))
    )
    .addStage("sort-by-views", stages.sort("count", "desc"));
}

/** User session analytics: groups by userId and computes session stats */
function createSessionPipeline() {
  return new Pipeline("sessions")
    .addStage(
      "dedupe-events",
      stages.deduplicate((e) => e.eventId)
    )
    .addStage(
      "group-by-user",
      stages.groupBy(
        (e) => e.userId,
        (acc, e) => ({
          events: (acc.events || 0) + 1,
          revenue: (acc.revenue || 0) + (e.revenue || 0),
          firstSeen: !acc.firstSeen || e.timestamp < acc.firstSeen
            ? e.timestamp
            : acc.firstSeen,
          lastSeen: !acc.lastSeen || e.timestamp > acc.lastSeen
            ? e.timestamp
            : acc.lastSeen,
        }),
        () => ({ events: 0, revenue: 0, firstSeen: null, lastSeen: null })
      )
    )
    .addStage(
      "enrich-session-duration",
      stages.enrich((r) => ({
        sessionDurationMs:
          r.lastSeen && r.firstSeen
            ? new Date(r.lastSeen) - new Date(r.firstSeen)
            : 0,
      }))
    )
    .addStage("sort-by-revenue", stages.sort("revenue", "desc"));
}

/** Simple funnel analysis: counts events at each funnel step */
function createFunnelPipeline(funnelSteps) {
  return new Pipeline("funnel").addStage("compute-funnel", (data) => {
    const userEvents = {};
    for (const record of data) {
      if (!userEvents[record.userId]) userEvents[record.userId] = new Set();
      userEvents[record.userId].add(record.event);
    }

    let previousCount = null;
    return funnelSteps.map((step) => {
      const usersAtStep = Object.values(userEvents).filter((evts) =>
        evts.has(step)
      ).length;
      const conversionRate =
        previousCount !== null && previousCount > 0
          ? Math.round((usersAtStep / previousCount) * 10000) / 100
          : 100;
      previousCount = usersAtStep;
      return { step, users: usersAtStep, conversionRate };
    });
  });
}

