import Anthropic from "@anthropic-ai/sdk";
import fs from "fs";
import path from "path";

const client = new Anthropic();

const WATCH_DIR = "./watch";
const OUTPUT_DIR = "./reports";

// Ensure directories exist
if (!fs.existsSync(WATCH_DIR)) fs.mkdirSync(WATCH_DIR, { recursive: true });
if (!fs.existsSync(OUTPUT_DIR)) fs.mkdirSync(OUTPUT_DIR, { recursive: true });

async function generateReport(filePath) {
  const fileName = path.basename(filePath);
  const content = fs.readFileSync(filePath, "utf-8");

  console.log(`\n📄 Processing: ${fileName}`);
  console.log("⏳ Generating report via Claude...\n");

  const reportPath = path.join(
    OUTPUT_DIR,
    `report_${fileName.replace(path.extname(fileName), "")}.md`
  );
  const writeStream = fs.createWriteStream(reportPath);

  writeStream.write(`# Report: ${fileName}\n\n`);
  writeStream.write(`*Generated: ${new Date().toISOString()}*\n\n---\n\n`);

  const stream = await client.messages.stream({
    model: "claude-sonnet-4-20250514",
    max_tokens: 1024,
    messages: [
      {
        role: "user",
        content: `Analyze the following data and generate a concise report with key findings, summary statistics (if applicable), and recommendations. Format in markdown.\n\nFile: ${fileName}\n\nContent:\n${content}`,
      },
    ],
  });

  for await (const event of stream) {
    if (
      event.type === "content_block_delta" &&
      event.delta.type === "text_delta"
    ) {
      process.stdout.write(event.delta.text);
      writeStream.write(event.delta.text);
    }
  }

  writeStream.end();
  console.log(`\n\n✅ Report saved: ${reportPath}`);
}

const processedFiles = new Set();

// Scan for existing files on startup
fs.readdirSync(WATCH_DIR).forEach((file) => {
  processedFiles.add(file);
});

console.log("👀 File watcher started");
console.log(`   Watching: ${path.resolve(WATCH_DIR)}`);
console.log(`   Output:   ${path.resolve(OUTPUT_DIR)}`);
console.log(
  `   ${processedFiles.size} existing file(s) skipped. Drop new files to generate reports.\n`
);

fs.watch(WATCH_DIR, async (eventType, filename) => {
  if (!filename || processedFiles.has(filename)) return;

  const filePath = path.join(WATCH_DIR, filename);

  // Debounce: wait for file write to complete
  await new Promise((resolve) => setTimeout(resolve, 500));

  if (!fs.existsSync(filePath)) return;

  processedFiles.add(filename);

  try {
    await generateReport(filePath);
  } catch (err) {
    console.error(`❌ Error processing ${filename}:`, err.message);
  }
});
```

**How it works:**

1. **Watches** the `./watch` directory for new files
2. **Reads** the file content when a new file appears
3. **Streams** the content to Claude asking for a report with findings, stats, and recommendations
4. **Writes** the streamed response to a markdown file in `./reports`

**To test it:**

```bash
# Start the watcher
node solution.js

# In another terminal, drop a data file into the watch directory
echo "Q1 Sales: $45,000
Q2 Sales: $52,000
Q3 Sales: $38,000
Q4 Sales: $61,000" > watch/sales_data.txt
```

The watcher will pick up the file, stream Claude's analysis to the terminal, and save the full report as `reports/report_sales_data.md`.

**Key details:**
- Skips files that existed before startup
- Tracks processed files to avoid duplicates from repeated `fs.watch` events
- Uses a 500ms debounce to let file writes finish
- Streams output to both the terminal and the report file simultaneously

