```rust
use std::path::PathBuf;
use thiserror::Error;

/// Unified error type for the analytics pipeline.
#[derive(Error, Debug)]
pub enum PipelineError {
    #[error("IO error reading '{path}': {source}")]
    Io {
        path: PathBuf,
        source: std::io::Error,
    },

    #[error("JSON parse error at record {record_index}: {source}")]
    JsonParse {
        record_index: usize,
        source: serde_json::Error,
    },

    #[error("JSON serialization error: {0}")]
    JsonSerialize(#[from] serde_json::Error),

    #[error("Validation failed for field '{field}': {reason}")]
    Validation { field: String, reason: String },

    #[error("Stage '{stage_name}' failed: {reason}")]
    StageExecution { stage_name: String, reason: String },

    #[error("Configuration error: {0}")]
    Config(String),

    #[error("Pipeline '{pipeline_id}' was cancelled")]
    Cancelled { pipeline_id: String },

    #[error("Schema mismatch: expected {expected}, got {actual}")]
    SchemaMismatch { expected: String, actual: String },

    #[error("Aggregation error: {0}")]
    Aggregation(String),

    #[error("Output sink error: {0}")]
    Sink(String),
}

impl PipelineError {
    pub fn io(path: impl Into<PathBuf>, source: std::io::Error) -> Self {
        Self::Io {
            path: path.into(),
            source,
        }
    }

    pub fn validation(field: impl Into<String>, reason: impl Into<String>) -> Self {
        Self::Validation {
            field: field.into(),
            reason: reason.into(),
        }
    }

    pub fn stage(name: impl Into<String>, reason: impl Into<String>) -> Self {
        Self::StageExecution {
            stage_name: name.into(),
            reason: reason.into(),
        }
    }

    /// Returns true if this error is recoverable (record can be skipped).
    pub fn is_recoverable(&self) -> bool {
        matches!(
            self,
            Self::Validation { .. } | Self::JsonParse { .. } | Self::SchemaMismatch { .. }
        )
    }
}

pub type Result<T> = std::result::Result<T, PipelineError>;
