```rust
use serde_json::Value;
use std::collections::HashMap;
use std::io::{BufRead, BufReader, Read};
use std::path::{Path, PathBuf};
use tracing::{debug, warn};

use crate::config::InputConfig;
use crate::error::{PipelineError, Result};

/// A single data record represented as a JSON object.
pub type Record = HashMap<String, Value>;

/// Abstraction over JSON data sources.
pub enum JsonSource {
    File(PathBuf),
    Stdin,
    Memory(String),
    Directory(PathBuf, String),
}

/// Reads JSON records from various sources with error recovery.
pub struct JsonReader {
    source: JsonSource,
    max_record_errors: usize,
}

impl JsonReader {
    pub fn new(source: JsonSource) -> Self {
        Self {
            source,
            max_record_errors: 100,
        }
    }

    pub fn from_config(config: &InputConfig) -> Self {
        let source = match config {
            InputConfig::File { path } => JsonSource::File(path.clone()),
            InputConfig::Stdin => JsonSource::Stdin,
            InputConfig::Directory { path, pattern } => {
                JsonSource::Directory(path.clone(), pattern.clone())
            }
        };
        Self::new(source)
    }

    pub fn with_max_errors(mut self, max: usize) -> Self {
        self.max_record_errors = max;
        self
    }

    /// Read all records, returning successfully parsed records and a list of errors.
    pub fn read_all(&self) -> Result<ReadResult> {
        match &self.source {
            JsonSource::File(path) => self.read_file(path),
            JsonSource::Stdin => self.read_stdin(),
            JsonSource::Memory(data) => self.parse_json_input(data.as_bytes(), "<memory>"),
            JsonSource::Directory(path, pattern) => self.read_directory(path, pattern),
        }
    }

    fn read_file(&self, path: &Path) -> Result<ReadResult> {
        let file = std::fs::File::open(path)
            .map_err(|e| PipelineError::io(path, e))?;
        let reader = BufReader::new(file);
        let path_str = path.display().to_string();
        self.parse_from_reader(reader, &path_str)
    }

    fn read_stdin(&self) -> Result<ReadResult> {
        let stdin = std::io::stdin();
        let reader = BufReader::new(stdin.lock());
        self.parse_from_reader(reader, "<stdin>")
    }

    fn read_directory(&self, dir: &Path, pattern: &str) -> Result<ReadResult> {
        let mut combined = ReadResult::default();
        let entries = std::fs::read_dir(dir)
            .map_err(|e| PipelineError::io(dir, e))?;

        for entry in entries {
            let entry = entry.map_err(|e| PipelineError::io(dir, e))?;
            let path = entry.path();

            if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                if Self::matches_pattern(name, pattern) {
                    debug!(file = %path.display(), "Reading file from directory");
                    match self.read_file(&path) {
                        Ok(result) => combined.merge(result),
                        Err(e) => {
                            warn!(error = %e, file = %path.display(), "Failed to read file");
                            combined.errors.push(e);
                        }
                    }
                }
            }
        }

        Ok(combined)
    }

    fn parse_from_reader<R: Read>(&self, reader: BufReader<R>, source: &str) -> Result<ReadResult> {
        let mut buf = String::new();
        let mut reader = reader;
        reader
            .read_to_string(&mut buf)
            .map_err(|e| PipelineError::Io {
                path: source.into(),
                source: e,
            })?;
        self.parse_json_input(buf.as_bytes(), source)
    }

    fn parse_json_input(&self, data: &[u8], source: &str) -> Result<ReadResult> {
        let text = std::str::from_utf8(data).map_err(|_| {
            PipelineError::Config(format!("Invalid UTF-8 in source: {source}"))
        })?;

        let trimmed = text.trim();
        if trimmed.is_empty() {
            return Ok(ReadResult::default());
        }

        // Try parsing as a JSON array first
        if trimmed.starts_with('[') {
            return self.parse_json_array(trimmed, source);
        }

        // Try parsing as newline-delimited JSON (NDJSON / JSON Lines)
        self.parse_ndjson(trimmed, source)
    }

    fn parse_json_array(&self, text: &str, source: &str) -> Result<ReadResult> {
        let parsed: Value = serde_json::from_str(text).map_err(|e| PipelineError::JsonParse {
            record_index: 0,
            source: e,
        })?;

        let mut result = ReadResult::default();

        match parsed {
            Value::Array(items) => {
                for (i, item) in items.into_iter().enumerate() {
                    match self.value_to_record(item, i) {
                        Ok(record) => result.records.push(record),
                        Err(e) => {
                            if result.errors.len() >= self.max_record_errors {
                                return Err(PipelineError::stage(
                                    "json_reader",
                                    format!(
                                        "Max errors ({}) exceeded reading '{source}'",
                                        self.max_record_errors
                                    ),
                                ));
                            }
                            warn!(record_index = i, error = %e, "Skipping invalid record");
                            result.errors.push(e);
                        }
                    }
                }
            }
            _ => {
                return Err(PipelineError::SchemaMismatch {
                    expected: "JSON array".into(),
                    actual: "non-array value".into(),
                });
            }
        }

        debug!(
            source = source,
            records = result.records.len(),
            errors = result.errors.len(),
            "Parsed JSON array"
        );

        Ok(result)
    }

    fn parse_ndjson(&self, text: &str, source: &str) -> Result<ReadResult> {
        let mut result = ReadResult::default();

        for (i, line) in text.lines().enumerate() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            match serde_json::from_str::<Value>(line) {
                Ok(value) => match self.value_to_record(value, i) {
                    Ok(record) => result.records.push(record),
                    Err(e) => {
                        if result.errors.len() >= self.max_record_errors {
                            return Err(PipelineError::stage(
                                "json_reader",
                                format!(
                                    "Max errors ({}) exceeded reading '{source}'",
                                    self.max_record_errors
                                ),
                            ));
                        }
                        result.errors.push(e);
                    }
                },
                Err(e) => {
                    let err = PipelineError::JsonParse {
                        record_index: i,
                        source: e,
                    };
                    if result.errors.len() >= self.max_record_errors {
                        return Err(PipelineError::stage(
                            "json_reader",
                            format!(
                                "Max errors ({}) exceeded reading '{source}'",
                                self.max_record_errors
                            ),
                        ));
                    }
                    warn!(line = i, "Skipping malformed JSON line");
                    result.errors.push(err);
                }
            }
        }

        debug!(
            source = source,
            records = result.records.len(),
            errors = result.errors.len(),
            "Parsed NDJSON"
        );

        Ok(result)
