# Basic Queue Consumer for Report Generation

## Queue and Consumer Implementation

```javascript
// queue.js
const EventEmitter = require("events");

class ReportQueue extends EventEmitter {
  constructor() {
    super();
    this.jobs = [];
    this.processing = false;
  }

  enqueue(job) {
    this.jobs.push({
      id: crypto.randomUUID(),
      status: "pending",
      createdAt: new Date(),
      ...job,
    });
    this.emit("job:added");
  }

  dequeue() {
    return this.jobs.find((j) => j.status === "pending") || null;
  }

  size() {
    return this.jobs.filter((j) => j.status === "pending").length;
  }
}

module.exports = { ReportQueue };
```

## Consumer

```javascript
// consumer.js
class ReportConsumer {
  constructor(queue, options = {}) {
    this.queue = queue;
    this.pollInterval = options.pollInterval || 2000;
    this.maxRetries = options.maxRetries || 3;
    this.running = false;
    this.timer = null;

    // Process immediately when a job is added
    this.queue.on("job:added", () => {
      if (this.running && !this.queue.processing) {
        this.processNext();
      }
    });
  }

  start() {
    console.log("🚀 Consumer started. Waiting for jobs...");
    this.running = true;
    this.poll();
  }

  stop() {
    console.log("🛑 Consumer stopped.");
    this.running = false;
    clearTimeout(this.timer);
  }

  poll() {
    if (!this.running) return;

    this.processNext();
    this.timer = setTimeout(() => this.poll(), this.pollInterval);
  }

  async processNext() {
    const job = this.queue.dequeue();
    if (!job) return;

    this.queue.processing = true;
    job.status = "processing";
    job.attempts = (job.attempts || 0) + 1;

    console.log(`📝 Processing job ${job.id} | Type: ${job.type}`);

    try {
      const result = await this.generateReport(job);
      job.status = "completed";
      job.completedAt = new Date();
      console.log(`✅ Job ${job.id} completed.`, result);
    } catch (err) {
      if (job.attempts < this.maxRetries) {
        job.status = "pending"; // re-queue
        console.log(`🔁 Retrying job ${job.id} (${job.attempts}/${this.maxRetries})`);
      } else {
        job.status = "failed";
        job.error = err.message;
        console.error(`❌ Job ${job.id} failed: ${err.message}`);
      }
    } finally {
      this.queue.processing = false;
    }
  }

  // --- Report generation logic ---
  async generateReport(job) {
    switch (job.type) {
      case "sales":
        return await this.buildSalesReport(job.params);
      case "inventory":
        return await this.buildInventoryReport(job.params);
      case "users":
        return await this.buildUsersReport(job.params);
      default:
        throw new Error(`Unknown report type: ${job.type}`);
    }
  }

  async buildSalesReport({ startDate, endDate }) {
    await this.simulateWork(1500);
    return { file: `sales_${startDate}_${endDate}.csv`, rows: 1240 };
  }

  async buildInventoryReport({ warehouse }) {
    await this.simulateWork(1000);
    return { file: `inventory_${warehouse}.csv`, rows: 530 };
  }

  async buildUsersReport({ role }) {
    await this.simulateWork(800);
    return { file: `users_${role}.csv`, rows: 87 };
  }

  simulateWork(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

module.exports = { ReportConsumer };
```

## Usage

```javascript
// main.js
const { ReportQueue } = require("./queue");
const { ReportConsumer } = require("./consumer");

const queue = new ReportQueue();
const consumer = new ReportConsumer(queue, {
  pollInterval: 3000,
  maxRetries: 3,
});

// Start consuming
consumer.start();

// Simulate incoming requests
queue.enqueue({
  type: "sales",
  params: { startDate: "2024-01-01", endDate: "2024-06-30" },
});

queue.enqueue({
  type: "inventory",
  params: { warehouse: "east" },
});

queue.enqueue({
  type: "users",
  params: { role: "admin" },
});

// Add one later
setTimeout(() => {
  queue.enqueue({
    type: "sales",
    params: { startDate: "2024-07-01", endDate: "2024-12-31" },
  });
}, 8000);

// Graceful shutdown
process.on("SIGINT", () => {
  consumer.stop();
  console.log(`\n📊 Queue status: ${queue.size()} pending jobs remaining.`);
  process.exit();
});
```

