        .iter()
        .enumerate()
        .map(|(i, s)| {
            let stock = 100u32.saturating_sub(s.quantity * 3);
            let reorder = 20;
            InventoryRecord {
                id: (i + 1) as u32,
                product: s.product.clone(),
                category: s.category.clone(),
                stock,
                reorder_level: reorder,
                status: if stock <= reorder {
                    "LOW".to_string()
                } else {
                    "OK".to_string()
                },
            }
        })
        .collect()
}

pub fn build_summary(sales: &[SalesRecord]) -> Vec<SummaryRecord> {
    use std::collections::BTreeMap;

    let mut map: BTreeMap<String, (f64, u32, Vec<f64>)> = BTreeMap::new();

    for s in sales {
        let entry = map.entry(s.category.clone()).or_insert((0.0, 0, vec![]));
        entry.0 += s.total;
        entry.1 += s.quantity;
        entry.2.push(s.unit_price);
    }

    map.into_iter()
        .map(|(category, (total_sales, total_quantity, prices))| {
            let avg_price = prices.iter().sum::<f64>() / prices.len() as f64;
            SummaryRecord {
                category,
                total_sales,
                total_quantity,
                avg_price,
            }
        })
        .collect()
}
