use crate::data::{SalesRecord, InventoryRecord, SummaryRecord};

pub struct Filters {
    pub min_amount: Option<f64>,
    pub category: Option<String>,
    pub limit: usize,
}

impl Filters {
    fn apply_limit<T>(&self, data: Vec<T>) -> Vec<T> {
        if self.limit > 0 {
            data.into_iter().take(self.limit).collect()
        } else {
            data
        }
    }
}

pub fn filter_sales(records: Vec<SalesRecord>, f: &Filters) -> Vec<SalesRecord> {
    let filtered: Vec<_> = records
        .into_iter()
        .filter(|r| {
            if let Some(min) = f.min_amount {
                if r.total < min {
                    return false;
                }
            }
            if let Some(ref cat) = f.category {
                if !r.category.eq_ignore_ascii_case(cat) {
                    return false;
                }
            }
            true
        })
        .collect();

    f.apply_limit(filtered)
}

pub fn filter_inventory(records: Vec<InventoryRecord>, f: &Filters) -> Vec<InventoryRecord> {
    let filtered: Vec<_> = records
        .into_iter()
        .filter(|r| {
            if let Some(ref cat) = f.category {
                if !r.category.eq_ignore_ascii_case(cat) {
                    return false;
                }
            }
            true
        })
        .collect();

    f.apply_limit(filtered)
}

pub fn filter_summary(records: Vec<SummaryRecord>, f: &Filters) -> Vec<SummaryRecord> {
    let filtered: Vec<_> = records
        .into_iter()
        .filter(|r| {
            if let Some(min) = f.min_amount {
                if r.total_sales < min {
                    return false;
                }
            }
            if let Some(ref cat) = f.category {
                if !r.category.eq_ignore_ascii_case(cat) {
                    return false;
                }
            }
            true
        })
        .collect();

    f.apply_limit(filtered)
}
