fn write_json<W: Write, T: Serialize>(w: &mut W, data: &[T]) -> io::Result<()> {
    let json = serde_json::to_string_pretty(data)
        .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
    writeln!(w, "{json}")
}

fn write_csv<W: Write, T: Serialize>(w: &mut W, data: &[T]) -> io::Result<()> {
    let mut wtr = csv::Writer::from_writer(vec![]);
    for record in data {
        wtr.serialize(record)
            .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
    }
    let bytes = wtr
        .into_inner()
        .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
    w.write_all(&bytes)
}

