## `src/main.rs` — Entry Point

```rust
mod cli;
mod data;
mod format;
mod report;

use clap::Parser;
use cli::{Cli, OutputFormat, ReportType};
use report::Filters;
use std::fs::File;
use std::io::{self, BufWriter, Write};

fn get_writer(cli: &Cli) -> io::Result<Box<dyn Write>> {
    match &cli.output {
        Some(path) => {
            let file = File::create(path)?;
            Ok(Box::new(BufWriter::new(file)))
        }
        None => Ok(Box::new(BufWriter::new(io::stdout().lock()))),
    }
}

fn fmt_key(f: &OutputFormat) -> &str {
    match f {
        OutputFormat::Text => "text",
        OutputFormat::Csv => "csv",
        OutputFormat::Json => "json",
    }
}

fn run(cli: Cli) -> io::Result<()> {
    let sales = data::load_sales_data();
    let filters = Filters {
        min_amount: cli.min_amount,
        category: cli.category.clone(),
        limit: cli.limit,
    };
    let fmt = fmt_key(&cli.format);
    let mut w = get_writer(&cli)?;

    match cli.report_type {
        ReportType::Sales => {
            let filtered = report::filter_sales(sales, &filters);
            format::format_sales(&mut w, &filtered, fmt)?;
        }
        ReportType::Inventory => {
            let inventory = data::build_inventory(&sales);
            let filtered = report::filter_inventory(inventory, &filters);
            format::format_inventory(&mut w, &filtered, fmt)?;
        }
        ReportType::Summary => {
            let summary = data::build_summary(&sales);
            let filtered = report::filter_summary(summary, &filters);
            format::format_summary(&mut w, &filtered, fmt)?;
        }
    }

    w.flush()?;

    if let Some(path) = &cli.output {
        eprintln!("✓ Report written to {}", path.display());
    }

    Ok(())
}

fn main() {
    let cli = Cli::parse();

    if let Err(e) = run(cli) {
        eprintln!("Error: {e}");
        std::process::exit(1);
    }
}
