```javascript
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

class FileSync {
  /**
   * @param {object} options
   * @param {boolean} options.deleteOrphans - Remove dest files not in source
   * @param {string[]} options.ignore       - Glob patterns / names to skip
   * @param {boolean} options.dryRun        - Log actions without executing
   */
  constructor(options = {}) {
    this.deleteOrphans = options.deleteOrphans ?? false;
    this.ignore = new Set(options.ignore ?? []);
    this.dryRun = options.dryRun ?? false;
    this.log = [];
  }

  // ─── Public API ──────────────────────────────────────────

  /**
   * Synchronize source directory → destination directory.
   * Returns an array of action logs.
   */
  sync(source, destination) {
    this.log = [];
    this._validateDirectory(source, "Source");
    this._ensureDirectory(destination);
    this._syncDirectory(source, destination);
    return [...this.log];
  }

  /**
   * Build a manifest (relative path → md5 hash) for a directory tree.
   */
  buildManifest(dirPath) {
    const manifest = {};
    this._walkDirectory(dirPath, dirPath, manifest);
    return manifest;
  }

  /**
   * Compute the MD5 checksum of a single file.
   */
  static computeChecksum(filePath) {
    const content = fs.readFileSync(filePath);
    return crypto.createHash("md5").update(content).digest("hex");
  }

  /**
   * Compare two directories and return a diff object.
   */
  compare(source, destination) {
    const srcManifest = this.buildManifest(source);
    const destManifest = this.buildManifest(destination);

    const added = [];    // in source, not in dest
    const modified = []; // in both, different checksum
    const removed = [];  // in dest, not in source
    const unchanged = [];

    for (const [relPath, srcHash] of Object.entries(srcManifest)) {
      if (!(relPath in destManifest)) {
        added.push(relPath);
      } else if (destManifest[relPath] !== srcHash) {
        modified.push(relPath);
      } else {
        unchanged.push(relPath);
      }
    }

    for (const relPath of Object.keys(destManifest)) {
      if (!(relPath in srcManifest)) {
        removed.push(relPath);
      }
    }

    return { added, modified, removed, unchanged };
  }

  // ─── Private helpers ─────────────────────────────────────

  _validateDirectory(dirPath, label) {
    if (!fs.existsSync(dirPath)) {
      throw new Error(`${label} directory does not exist: ${dirPath}`);
    }
    if (!fs.statSync(dirPath).isDirectory()) {
      throw new Error(`${label} path is not a directory: ${dirPath}`);
    }
  }

  _ensureDirectory(dirPath) {
    if (!this.dryRun) {
      fs.mkdirSync(dirPath, { recursive: true });
    }
  }

  _shouldIgnore(name) {
    return this.ignore.has(name);
  }

  _record(action, filePath) {
    this.log.push({ action, path: filePath, timestamp: new Date() });
  }

  _walkDirectory(baseDir, currentDir, manifest) {
    const entries = fs.readdirSync(currentDir, { withFileTypes: true });

    for (const entry of entries) {
      if (this._shouldIgnore(entry.name)) continue;

      const fullPath = path.join(currentDir, entry.name);
      const relativePath = path.relative(baseDir, fullPath);

      if (entry.isDirectory()) {
        this._walkDirectory(baseDir, fullPath, manifest);
      } else if (entry.isFile()) {
        manifest[relativePath] = FileSync.computeChecksum(fullPath);
      }
    }
  }

  _syncDirectory(source, destination) {
    const entries = fs.readdirSync(source, { withFileTypes: true });
    const sourceNames = new Set();

    // --- copy / update from source → destination ---
    for (const entry of entries) {
      if (this._shouldIgnore(entry.name)) continue;

      sourceNames.add(entry.name);
      const srcPath = path.join(source, entry.name);
      const destPath = path.join(destination, entry.name);

      if (entry.isDirectory()) {
        this._ensureDirectory(destPath);
        this._record("sync-dir", destPath);
        this._syncDirectory(srcPath, destPath);
      } else if (entry.isFile()) {
        this._syncFile(srcPath, destPath);
      }
    }

    // --- remove orphans in destination ---
    if (this.deleteOrphans && fs.existsSync(destination)) {
      const destEntries = fs.readdirSync(destination, { withFileTypes: true });

      for (const entry of destEntries) {
        if (sourceNames.has(entry.name)) continue;

        const orphanPath = path.join(destination, entry.name);

        if (entry.isDirectory()) {
          this._record("delete-dir", orphanPath);
          if (!this.dryRun) fs.rmSync(orphanPath, { recursive: true });
        } else {
          this._record("delete", orphanPath);
          if (!this.dryRun) fs.unlinkSync(orphanPath);
        }
      }
    }
  }

  _syncFile(srcPath, destPath) {
    const needsCopy = this._needsCopy(srcPath, destPath);

    if (!needsCopy) {
      this._record("skip", destPath);
      return;
    }

    const action = fs.existsSync(destPath) ? "update" : "copy";
    this._record(action, destPath);

    if (!this.dryRun) {
      fs.copyFileSync(srcPath, destPath);
      // Preserve modified time
      const stat = fs.statSync(srcPath);
      fs.utimesSync(destPath, stat.atime, stat.mtime);
    }
  }

  _needsCopy(srcPath, destPath) {
    if (!fs.existsSync(destPath)) return true;

    const srcStat = fs.statSync(srcPath);
    const destStat = fs.statSync(destPath);

    // Quick check: different size → needs copy
    if (srcStat.size !== destStat.size) return true;

    // Deeper check: compare checksums
    return (
      FileSync.computeChecksum(srcPath) !==
      FileSync.computeChecksum(destPath)
    );
  }
}

module.exports = FileSync;
```

