const fs = require("fs");
const path = require("path");
const os = require("os");
const FileSync = require("../src/file-sync");

// ─── Test helpers ─────────────────────────────────────────

function createTempDir(prefix = "filesync-test-") {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

function writeFile(dir, relativePath, content) {
  const fullPath = path.join(dir, relativePath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, content, "utf-8");
  return fullPath;
}

function readFile(dir, relativePath) {
  return fs.readFileSync(path.join(dir, relativePath), "utf-8");
}

function fileExists(dir, relativePath) {
  return fs.existsSync(path.join(dir, relativePath));
}

function listAllFiles(dir, base = dir) {
  let results = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results = results.concat(listAllFiles(full, base));
    } else {
      results.push(path.relative(base, full));
    }
  }
  return results.sort();
}

// ─── Test suite ───────────────────────────────────────────

describe("FileSync", () => {
  let srcDir, destDir, syncer;

  beforeEach(() => {
    srcDir = createTempDir("src-");
    destDir = createTempDir("dest-");
    syncer = new FileSync();
  });

  afterEach(() => {
    fs.rmSync(srcDir, { recursive: true, force: true });
    fs.rmSync(destDir, { recursive: true, force: true });
  });

  // ── Constructor & options ─────────────────────────────

  test("creates instance with default options", () => {
    const s = new FileSync();
    expect(s.deleteOrphans).toBe(false);
    expect(s.dryRun).toBe(false);
    expect(s.ignore.size).toBe(0);
  });

  test("accepts custom options", () => {
    const s = new FileSync({
      deleteOrphans: true,
      dryRun: true,
      ignore: [".git", "node_modules"],
    });
    expect(s.deleteOrphans).toBe(true);
    expect(s.dryRun).toBe(true);
    expect(s.ignore.has(".git")).toBe(true);
    expect(s.ignore.has("node_modules")).toBe(true);
  });

  // ── Validation ────────────────────────────────────────

  test("throws when source does not exist", () => {
    expect(() => syncer.sync("/nonexistent/path", destDir)).toThrow(
      "Source directory does not exist"
    );
  });

  test("throws when source is a file, not a directory", () => {
    const filePath = writeFile(srcDir, "file.txt", "data");
    expect(() => syncer.sync(filePath, destDir)).toThrow(
      "not a directory"
    );
  });

  test("creates destination if it does not exist", () => {
    writeFile(srcDir, "a.txt", "hello");
    const newDest = path.join(destDir, "nested", "subdir");

    syncer.sync(srcDir, newDest);

    expect(fs.existsSync(newDest)).toBe(true);
    expect(readFile(newDest, "a.txt")).toBe("hello");
  });

  // ── Basic sync (copy new files) ──────────────────────

  test("copies new files from source to destination", () => {
    writeFile(srcDir, "file1.txt", "content1");
    writeFile(srcDir, "file2.txt", "content2");

    const log = syncer.sync(srcDir, destDir);

    expect(readFile(destDir, "file1.txt")).toBe("content1");
    expect(readFile(destDir, "file2.txt")).toBe("content2");

    const copyActions = log.filter((l) => l.action === "copy");
    expect(copyActions).toHaveLength(2);
  });

  test("copies nested directory structures", () => {
    writeFile(srcDir, "a/b/c.txt", "deep");
    writeFile(srcDir, "a/d.txt", "shallow");
    writeFile(srcDir, "root.txt", "top");

    syncer.sync(srcDir, destDir);

    expect(readFile(destDir, "a/b/c.txt")).toBe("deep");
    expect(readFile(destDir, "a/d.txt")).toBe("shallow");
    expect(readFile(destDir, "root.txt")).toBe("top");
  });

  // ── Update modified files ─────────────────────────────

  test("updates files that have changed content", () => {
    writeFile(srcDir, "file.txt", "version1");
    syncer.sync(srcDir, destDir);
    expect(readFile(destDir, "file.txt")).toBe("version1");

    // Modify source
    writeFile(srcDir, "file.txt", "version2");
    const log = syncer.sync(srcDir, destDir);

    expect(readFile(destDir, "file.txt")).toBe("version2");
    const updates = log.filter((l) => l.action === "update");
    expect(updates).toHaveLength(1);
  });

