    syncer.sync(srcDir, destDir);

    const log = syncer.sync(srcDir, destDir);

    const skipped = log.filter((l) => l.action === "skip");
    expect(skipped).toHaveLength(1);

    const copies = log.filter((l) => l.action === "copy");
    expect(copies).toHaveLength(0);
  });

  // ── Delete orphans ───────────────────────────────────

  test("does NOT delete orphans by default", () => {
    writeFile(srcDir, "keep.txt", "keep");
