    writeFile(destDir, "orphan.txt", "remove me");
    writeFile(destDir, "keep.txt", "old");

    const log = s.sync(srcDir, destDir);

    expect(fileExists(destDir, "keep.txt")).toBe(true);
    expect(fileExists(destDir, "orphan.txt")).toBe(false);

    const deletions = log.filter((l) => l.action === "delete");
    expect(deletions).toHaveLength(1);
  });

  test("deletes orphan directories recursively", () => {
    const s = new FileSync({ deleteOrphans: true });

    writeFile(srcDir, "a.txt", "data");
