  test("ignores specified file/directory names", () => {
    const s = new FileSync({ ignore: [".git", ".DS_Store"] });

    writeFile(srcDir, ".git/config", "git stuff");
    writeFile(srcDir, ".DS_Store", "mac stuff");
    writeFile(srcDir, "real.txt", "real content");

    s.sync(srcDir, destDir);

    expect(fileExists(destDir, "real.txt")).toBe(true);
    expect(fileExists(destDir, ".git")).toBe(false);
    expect(fileExists(destDir, ".DS_Store")).toBe(false);
  });

  // ── Dry run ──────────────────────────────────────────

  test("dry run logs actions but does not modify filesystem", () => {
    const s = new FileSync({ dryRun: true, deleteOrphans: true });

    writeFile(srcDir, "new.txt", "new content");
    writeFile(destDir, "orphan.txt", "old content");

    const log = s.sync(srcDir, destDir);

    // Actions were logged
    expect(log.length).toBeGreaterThan(0);

    // But files were NOT actually touched
    expect(fileExists(destDir, "new.txt")).toBe(false);
    expect(fileExists(destDir, "orphan.txt")).toBe(true);
  });

  // ── Checksum ─────────────────────────────────────────

  test("computeChecksum returns consistent MD5 hash", () => {
    const fp = writeFile(srcDir, "hash.txt", "hello world");

    const hash1 = FileSync.computeChecksum(fp);
