  });

  test("different content produces different checksums", () => {
    const f1 = writeFile(srcDir, "a.txt", "aaa");
    const f2 = writeFile(srcDir, "b.txt", "bbb");

    expect(FileSync.computeChecksum(f1)).not.toBe(
      FileSync.computeChecksum(f2)
    );
  });

  // ── Manifest ─────────────────────────────────────────

  test("buildManifest returns relative-path → hash map", () => {
    writeFile(srcDir, "a.txt", "alpha");
    writeFile(srcDir, "sub/b.txt", "beta");

    const manifest = syncer.buildManifest(srcDir);

    expect(Object.keys(manifest).sort()).toEqual(["a.txt", "sub/b.txt"].sort());
    expect(manifest["a.txt"]).toMatch(/^[a-f0-9]{32}$/);
  });

  test("buildManifest respects ignore list", () => {
    const s = new FileSync({ ignore: ["secret"] });

    writeFile(srcDir, "public.txt", "visible");
    writeFile(srcDir, "secret/key.pem", "hidden");

