## Core Module — `src/ConfigLoader.js`

```javascript
"use strict";

const fs = require("fs");
const path = require("path");
const { EventEmitter } = require("events");
const { ConfigValidator } = require("./ConfigValidator");
const { ConfigMerger } = require("./ConfigMerger");

/**
 * Production-ready configuration loader that reads JSON input.
 * Supports file-based configs, environment overrides, defaults,
 * schema validation, hot-reloading, and hierarchical merging.
 */
class ConfigLoader extends EventEmitter {
  /** @type {Map<string, ConfigLoader>} */
  static #instances = new Map();

  /** @type {Object} Frozen resolved configuration */
  #config = null;

  /** @type {Object} Raw merged configuration before freeze */
  #rawConfig = null;

  /** @type {Object|null} Validation schema */
  #schema = null;

  /** @type {string[]} Ordered list of loaded source descriptions */
  #loadedSources = [];

  /** @type {fs.FSWatcher[]} Active file watchers for hot-reload */
  #watchers = [];

  /** @type {boolean} Whether the loader has been disposed */
  #disposed = false;

  /** @type {Object} Loader options */
  #options;

  /**
   * @param {Object} [options]
   * @param {string}   [options.configDir]          - Directory containing config JSON files
   * @param {string}   [options.env]                - Environment name (default: NODE_ENV || 'development')
   * @param {Object}   [options.defaults]           - Default configuration values
   * @param {Object}   [options.overrides]          - Values that override everything
   * @param {Object}   [options.schema]             - Validation schema
   * @param {string}   [options.envPrefix]          - Prefix for environment variable overrides (e.g., 'APP_')
   * @param {string}   [options.envSeparator]       - Nested key separator in env vars (default: '__')
   * @param {boolean}  [options.watchFiles]         - Enable hot-reload on file changes
   * @param {number}   [options.watchDebounceMs]    - Debounce interval for file watch (default: 500)
   * @param {boolean}  [options.freezeConfig]       - Deep-freeze the resulting config (default: true)
   * @param {boolean}  [options.allowEmptyConfig]   - Allow empty configuration (default: false)
   * @param {boolean}  [options.silent]             - Suppress warning logs (default: false)
   * @param {Function} [options.logger]             - Custom logger (default: console)
   */
  constructor(options = {}) {
    super();

    this.#options = {
      configDir: options.configDir || path.join(process.cwd(), "config"),
      env: options.env || process.env.NODE_ENV || "development",
      defaults: options.defaults || {},
      overrides: options.overrides || {},
      schema: options.schema || null,
      envPrefix: options.envPrefix || "",
      envSeparator: options.envSeparator || "__",
      watchFiles: options.watchFiles || false,
      watchDebounceMs: options.watchDebounceMs || 500,
      freezeConfig: options.freezeConfig !== false,
      allowEmptyConfig: options.allowEmptyConfig || false,
      silent: options.silent || false,
      logger: options.logger || console,
    };

    if (options.schema) {
      this.#schema = options.schema;
    }
  }

  // ─── Factory / Singleton ────────────────────────────────────────

  /**
   * Returns a named singleton instance.
   * @param {string} [name='default']
   * @param {Object} [options]
   * @returns {ConfigLoader}
   */
  static getInstance(name = "default", options = {}) {
    if (!ConfigLoader.#instances.has(name)) {
      ConfigLoader.#instances.set(name, new ConfigLoader(options));
    }
    return ConfigLoader.#instances.get(name);
  }

  /**
   * Removes a named singleton instance and disposes it.
   * @param {string} [name='default']
   */
  static removeInstance(name = "default") {
    const instance = ConfigLoader.#instances.get(name);
    if (instance) {
      instance.dispose();
      ConfigLoader.#instances.delete(name);
    }
  }

  /** Clears all singleton instances. */
  static clearInstances() {
    for (const [name] of ConfigLoader.#instances) {
      ConfigLoader.removeInstance(name);
    }
  }

  // ─── Public API ─────────────────────────────────────────────────

  /**
   * Loads configuration from all sources and returns the frozen config.
   * Loading order (later wins):
   *   1. defaults
   *   2. default.json
   *   3. {env}.json
   *   4. local.json (gitignored overrides)
   *   5. environment variables
   *   6. programmatic overrides
   *
   * @returns {Promise<Object>} Resolved configuration
   * @throws {ConfigLoadError} On read, parse, or validation failure
   */
  async load() {
    this.#assertNotDisposed();
    this.#loadedSources = [];

    try {
      const layers = [];

      // 1 — Defaults
      if (Object.keys(this.#options.defaults).length > 0) {
        layers.push(this.#options.defaults);
        this.#loadedSources.push("programmatic-defaults");
      }

      // 2 — default.json
      const defaultFile = await this.#readJsonFile("default.json");
      if (defaultFile !== null) {
        layers.push(defaultFile);
        this.#loadedSources.push("default.json");
      }

      // 3 — {env}.json
      const envFileName = `${this.#options.env}.json`;
      const envFile = await this.#readJsonFile(envFileName);
      if (envFile !== null) {
        layers.push(envFile);
        this.#loadedSources.push(envFileName);
      }

      // 4 — local.json
      const localFile = await this.#readJsonFile("local.json");
      if (localFile !== null) {
        layers.push(localFile);
        this.#loadedSources.push("local.json");
      }

      // 5 — Environment variable overrides
      const envOverrides = this.#parseEnvOverrides();
      if (Object.keys(envOverrides).length > 0) {
        layers.push(envOverrides);
        this.#loadedSources.push("environment-variables");
      }

      // 6 — Programmatic overrides
      if (Object.keys(this.#options.overrides).length > 0) {
        layers.push(this.#options.overrides);
        this.#loadedSources.push("programmatic-overrides");
      }

      // Merge all layers
      this.#rawConfig = ConfigMerger.deepMerge({}, ...layers);

      // Guard against empty config
      if (
        !this.#options.allowEmptyConfig &&
        Object.keys(this.#rawConfig).length === 0
      ) {
        throw new ConfigLoadError(
          "Configuration is empty after merging all sources. " +
            "Set allowEmptyConfig: true to suppress this error."
        );
      }

      // Validate against schema
      if (this.#schema) {
        const validator = new ConfigValidator(this.#schema);
        const result = validator.validate(this.#rawConfig);
        if (!result.valid) {
          throw new ConfigValidationError(
            "Configuration validation failed",
            result.errors
          );
        }
      }

      // Freeze
      this.#config = this.#options.freezeConfig
        ? ConfigLoader.#deepFreeze({ ...this.#rawConfig })
        : { ...this.#rawConfig };

      // Optionally start watching files
      if (this.#options.watchFiles) {
        this.#startWatching();
      }

      this.#log("info", `Configuration loaded from: ${this.#loadedSources.join(", ")}`);
      this.emit("loaded", this.#config);

      return this.#config;
    } catch (error) {
      if (
        error instanceof ConfigLoadError ||
        error instanceof ConfigValidationError
      ) {
        throw error;
      }
      throw new ConfigLoadError(`Failed to load configuration: ${error.message}`, error);
    }
  }

  /**
   * Synchronous variant of load().
   * @returns {Object}
   */
  loadSync() {
    this.#assertNotDisposed();
    this.#loadedSources = [];

    const layers = [];

    if (Object.keys(this.#options.defaults).length > 0) {
      layers.push(this.#options.defaults);
      this.#loadedSources.push("programmatic-defaults");
    }

    for (const fileName of ["default.json", `${this.#options.env}.json`, "local.json"]) {
      const data = this.#readJsonFileSync(fileName);
      if (data !== null) {
        layers.push(data);
        this.#loadedSources.push(fileName);
      }
    }

    const envOverrides = this.#parseEnvOverrides();
    if (Object.keys(envOverrides).length > 0) {
      layers.push(envOverrides);
      this.#loadedSources.push("environment-variables");
    }

    if (Object.keys(this.#options.overrides).length > 0) {
      layers.push(this.#options.overrides);
      this.#loadedSources.push("programmatic-overrides");
    }

    this.#rawConfig = ConfigMerger.deepMerge({}, ...layers);

    if (
      !this.#options.allowEmptyConfig &&
      Object.keys(this.#rawConfig).length === 0
    ) {
      throw new ConfigLoadError(
        "Configuration is empty after merging all sources."
      );
    }

    if (this.#schema) {
      const validator = new ConfigValidator(this.#schema);
      const result = validator.validate(this.#rawConfig);
      if (!result.valid) {
        throw new ConfigValidationError(
          "Configuration validation failed",
          result.errors
        );
      }
    }

    this.#config = this.#options.freezeConfig
      ? ConfigLoader.#deepFreeze({ ...this.#rawConfig })
      : { ...this.#rawConfig };

    this.#log("info", `Configuration loaded (sync) from: ${this.#loadedSources.join(", ")}`);
    this.emit("loaded", this.#config);

    return this.#config;
  }

  /**
   * Loads configuration directly from a JSON string.
   * @param {string} jsonString
   * @param {Object} [mergeWith] - Optional base config to merge onto
   * @returns {Object}
   */
  loadFromString(jsonString, mergeWith = {}) {
    this.#assertNotDisposed();

    if (typeof jsonString !== "string") {
      throw new ConfigLoadError("loadFromString expects a string argument");
    }

    let parsed;
    try {
      parsed = JSON.parse(jsonString);
    } catch (err) {
      throw new ConfigLoadError(`Invalid JSON string: ${err.message}`, err);
    }

    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
      throw new ConfigLoadError("JSON input must be a plain object at the root level");
    }

    this.#rawConfig = ConfigMerger.deepMerge(
      {},
      this.#options.defaults,
      mergeWith,
      parsed,
      this.#options.overrides
    );

    if (this.#schema) {
      const validator = new ConfigValidator(this.#schema);
      const result = validator.validate(this.#rawConfig);
      if (!result.valid) {
        throw new ConfigValidationError(
          "Configuration validation failed",
          result.errors
        );
      }
    }

    this.#config = this.#options.freezeConfig
      ? ConfigLoader.#deepFreeze({ ...this.#rawConfig })
      : { ...this.#rawConfig };

    this.emit("loaded", this.#config);
    return this.#config;
  }

  /**
   * Reads a single JSON file and returns the parsed object.
   * Useful for loading supplemental configuration.
   * @param {string} filePath - Absolute or relative to configDir
   * @returns {Promise<Object>}
   */
  async loadFile(filePath) {
    this.#assertNotDisposed();
    const resolved = path.isAbsolute(filePath)
      ? filePath
      : path.join(this.#options.configDir, filePath);

    const content = await this.#readFile(resolved);
    return this.#parseJson(content, resolved);
  }

  /**
   * Retrieves a value using a dot-notation path.
   * @param {string} keyPath - e.g., 'database.host'
   * @param {*} [defaultValue] - Returned when the key is not found
   * @returns {*}
   */
  get(keyPath, defaultValue = undefined) {
    this.#assertLoaded();

    if (typeof keyPath !== "string" || keyPath.length === 0) {
      throw new TypeError("keyPath must be a non-empty string");
    }

    const segments = keyPath.split(".");
    let current = this.#config;

    for (const segment of segments) {
      if (
        current === null ||
        current === undefined ||
        typeof current !== "object"
      ) {
        return defaultValue;
      }
      if (!Object.prototype.hasOwnProperty.call(current, segment)) {
        return defaultValue;
      }
      current = current[segment];
    }

    return current;
  }

  /**
   * Checks whether a dot-notation path exists.
   * @param {string} keyPath
   * @returns {boolean}
   */
  has(keyPath) {
    this.#assertLoaded();

    const segments = keyPath.split(".");
    let current = this.#config;

    for (const segment of segments) {
      if (
        current === null ||
        current === undefined ||
        typeof current !== "object" ||
        !Object.prototype.hasOwnProperty.call(current, segment)
      ) {
        return false;
      }
      current = current[segment];
    }

    return true;
  }

