## index.js

```javascript
#!/usr/bin/env node

import { readFileSync, writeFileSync, existsSync } from "fs";
import { resolve } from "path";

// --- Storage ---

const INDEX_PATH = resolve(process.cwd(), ".search-index.json");

function loadIndex() {
  if (!existsSync(INDEX_PATH)) {
    return { documents: {}, invertedIndex: {}, docCount: 0 };
  }
  return JSON.parse(readFileSync(INDEX_PATH, "utf-8"));
}

function saveIndex(index) {
  writeFileSync(INDEX_PATH, JSON.stringify(index, null, 2));
}

// --- Tokenizer & Normalization ---

const STOP_WORDS = new Set([
  "the", "a", "an", "is", "are", "was", "were", "be", "been",
  "being", "have", "has", "had", "do", "does", "did", "will",
  "would", "could", "should", "may", "might", "and", "but", "or",
  "nor", "not", "so", "yet", "both", "either", "neither", "each",
  "of", "in", "to", "for", "with", "on", "at", "from", "by",
  "about", "as", "into", "through", "during", "before", "after",
  "it", "its", "this", "that", "these", "those",
]);

function tokenize(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")       // strip punctuation
    .split(/\s+/)                         // split on whitespace
    .filter(t => t.length > 1 && !STOP_WORDS.has(t));
}

function computeTermFrequency(tokens) {
  const tf = {};
  for (const token of tokens) {
    tf[token] = (tf[token] || 0) + 1;
  }
  // normalize by total token count
  const len = tokens.length || 1;
  for (const term in tf) {
    tf[term] /= len;
  }
  return tf;
}

// --- Indexing Operations ---

function addDocument(index, id, text) {
  // if the doc already exists, remove its old terms first
  if (index.documents[id]) {
    removeDocument(index, id);
  }

  const tokens = tokenize(text);
  const tf = computeTermFrequency(tokens);

  // store the original document
  index.documents[id] = { text, tf, tokenCount: tokens.length };
  index.docCount += 1;

  // update the inverted index: term -> Set of doc IDs
  for (const term of Object.keys(tf)) {
    if (!index.invertedIndex[term]) {
      index.invertedIndex[term] = [];
    }
    if (!index.invertedIndex[term].includes(id)) {
      index.invertedIndex[term].push(id);
    }
  }
}

function removeDocument(index, id) {
  const doc = index.documents[id];
  if (!doc) return false;

  // remove doc ID from every term posting list
  for (const term of Object.keys(doc.tf)) {
    const postings = index.invertedIndex[term];
    if (postings) {
      index.invertedIndex[term] = postings.filter(d => d !== id);
      if (index.invertedIndex[term].length === 0) {
        delete index.invertedIndex[term];
      }
    }
  }

  delete index.documents[id];
  index.docCount -= 1;
  return true;
}

// --- Search with TF-IDF Scoring ---

function search(index, query, limit = 10) {
  const queryTokens = tokenize(query);
  if (queryTokens.length === 0) return [];

  const scores = {};  // docId -> score

  for (const term of queryTokens) {
    const postings = index.invertedIndex[term];
    if (!postings) continue;

    // IDF = log(totalDocs / docsContainingTerm)
    const idf = Math.log((index.docCount + 1) / (postings.length + 1)) + 1;

    for (const docId of postings) {
      const tf = index.documents[docId].tf[term] || 0;
      scores[docId] = (scores[docId] || 0) + tf * idf;
    }
  }

  // sort by score descending, return top N
  return Object.entries(scores)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([id, score]) => ({
      id,
      score: Math.round(score * 1000) / 1000,
      text: index.documents[id].text,
    }));
}

// --- CLI Interface ---

function printUsage() {
  console.log(`
  search-index-cli — a basic TF-IDF search index

  USAGE
    searchidx <command> [arguments]

  COMMANDS
    add    <id> <text>      Add or update a document
    remove <id>             Remove a document by ID
    search <query>          Search the index
    list                    List all indexed documents
    stats                   Show index statistics
    clear                   Delete the entire index

  EXAMPLES
    searchidx add doc1 "Node.js is a JavaScript runtime"
    searchidx add doc2 "Deno is a modern runtime for JavaScript"
    searchidx search "javascript runtime"
    searchidx remove doc1
  `);
}

function printTable(rows, columns) {
  // simple column-aligned printer
  const widths = columns.map(col =>
    Math.max(col.label.length, ...rows.map(r => String(r[col.key]).length))
  );

  const header = columns.map((c, i) => c.label.padEnd(widths[i])).join("  ");
  const sep = columns.map((_, i) => "─".repeat(widths[i])).join("──");

  console.log(`  ${header}`);
  console.log(`  ${sep}`);
  for (const row of rows) {
    const line = columns.map((c, i) => String(row[c.key]).padEnd(widths[i])).join("  ");
    console.log(`  ${line}`);
  }
}

// --- Main ---

function main() {
  const [,, command, ...args] = process.argv;

  if (!command || command === "--help" || command === "-h") {
    printUsage();
    process.exit(0);
  }

  const index = loadIndex();

  switch (command) {

    case "add": {
      const id = args[0];
      const text = args.slice(1).join(" ");
      if (!id || !text) {
        console.error("  Error: provide an ID and text.\n  Usage: searchidx add <id> <text>");
        process.exit(1);
      }
      addDocument(index, id, text);
      saveIndex(index);
      console.log(`  ✓ Indexed "${id}" (${tokenize(text).length} tokens)`);
      break;
    }

    case "remove": {
      const id = args[0];
      if (!id) {
        console.error("  Error: provide a document ID.\n  Usage: searchidx remove <id>");
        process.exit(1);
      }
      if (removeDocument(index, id)) {
        saveIndex(index);
        console.log(`  ✓ Removed "${id}"`);
      } else {
        console.log(`  ✗ Document "${id}" not found`);
      }
      break;
    }

    case "search": {
      const query = args.join(" ");
      if (!query) {
        console.error("  Error: provide a search query.\n  Usage: searchidx search <query>");
        process.exit(1);
      }
      const results = search(index, query);
      if (results.length === 0) {
        console.log("  No results found.");
      } else {
        console.log(`\n  Results for "${query}":\n`);
        printTable(results, [
          { key: "id",    label: "ID" },
          { key: "score", label: "Score" },
          { key: "text",  label: "Text" },
        ]);
        console.log(`\n  ${results.length} result(s)\n`);
      }
      break;
    }

    case "list": {
      const docs = Object.entries(index.documents);
      if (docs.length === 0) {
        console.log("  Index is empty.");
      } else {
        const rows = docs.map(([id, doc]) => ({
          id,
          tokens: doc.tokenCount,
          text: doc.text.length > 60 ? doc.text.slice(0, 57) + "..." : doc.text,
        }));
        console.log();
        printTable(rows, [
          { key: "id",     label: "ID" },
          { key: "tokens", label: "Tokens" },
          { key: "text",   label: "Text" },
        ]);
        console.log(`\n  ${docs.length} document(s)\n`);
      }
      break;
    }

    case "stats": {
      const termCount = Object.keys(index.invertedIndex).length;
      console.log(`
  Index Statistics
  ────────────────
  Documents :  ${index.docCount}
  Terms     :  ${termCount}
  Index file:  ${INDEX_PATH}
  File size :  ${existsSync(INDEX_PATH)
        ? (readFileSync(INDEX_PATH).length / 1024).toFixed(1) + " KB"
        : "N/A"}
      `);
      break;
    }

    case "clear": {
      saveIndex({ documents: {}, invertedIndex: {}, docCount: 0 });
      console.log("  ✓ Index cleared.");
      break;
    }

    default:
      console.error(`  Unknown command: "${command}"`);
      printUsage();
      process.exit(1);
  }
}

main();
```

## How It Works

```
┌──────────────┐     tokenize      ┌──────────────┐
│  "Node.js    │ ───────────────▶  │ [node, js,   │
│   is great"  │   lowercase +     │  great]      │
└──────────────┘   stop-word removal└──────┬───────┘
                                          │
                    ┌─────────────────────┘
                    ▼
          ┌─────────────────┐
          │  Inverted Index  │     TF-IDF Scoring
          │                  │     ────────────────
          │  node  → [doc1]  │     TF  = term freq / total tokens
          │  js    → [doc1,  │     IDF = log(N / df) + 1
          │          doc2]   │     score = Σ (TF × IDF)
          │  great → [doc1]  │
          └─────────────────┘
```

## Usage

```bash
