import { readFileSync } from 'fs';
import { resolve } from 'path';
import { loadData } from './datasources/loader.js';
import { generateReport } from './reportGenerator.js';
import { formatReport } from './formatters/index.js';

// ── Help Text ────────────────────────────────────────────
const HELP = `
  report-cli — Basic Report Generator

  USAGE
    report <datafile> [options]

  OPTIONS
    -f, --format <type>    Output format: text | csv | json   (default: text)
    -t, --title  <title>   Report title                       (default: "Report")
    -s, --sort   <field>   Sort rows by field name
    -g, --group  <field>   Group & summarize by field
    -o, --output <file>    Write to file instead of stdout
    -h, --help             Show this help message

  EXAMPLES
    report sales.json
    report sales.json -f csv -s revenue
    report sales.json -g region -f text -o report.txt
`;

// ── Argument Parser ──────────────────────────────────────
function parseArgs(argv) {
  const args = {
    dataFile: null,
    format: 'text',
    title: 'Report',
    sort: null,
    group: null,
    output: null,
  };

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    switch (token) {
      case '-h':
      case '--help':
        console.log(HELP);
        process.exit(0);

      case '-f':
      case '--format':
        args.format = argv[++i];
        break;

      case '-t':
      case '--title':
        args.title = argv[++i];
        break;

      case '-s':
      case '--sort':
        args.sort = argv[++i];
        break;

      case '-g':
      case '--group':
        args.group = argv[++i];
        break;

      case '-o':
      case '--output':
        args.output = argv[++i];
        break;

      default:
        if (token.startsWith('-')) {
          console.error(`Unknown option: ${token}`);
          process.exit(1);
        }
        args.dataFile = token;
    }
    i++;
  }

  return args;
}

// ── Validate ─────────────────────────────────────────────
function validate(args) {
  if (!args.dataFile) {
    console.error('Error: No data file provided.\n');
    console.log(HELP);
    process.exit(1);
  }

  const validFormats = ['text', 'csv', 'json'];
  if (!validFormats.includes(args.format)) {
    console.error(`Error: Invalid format "${args.format}". Use: ${validFormats.join(', ')}`);
    process.exit(1);
  }
}

// ── Main ─────────────────────────────────────────────────
export function runCLI(argv) {
  const args = parseArgs(argv);
  validate(args);

  try {
    // 1. Load raw data
    const data = loadData(resolve(args.dataFile));

    // 2. Generate report (sort, group, summarize)
    const report = generateReport(data, {
      title: args.title,
      sortBy: args.sort,
      groupBy: args.group,
    });

    // 3. Format for output
    const output = formatReport(report, args.format);

    // 4. Write or print
    if (args.output) {
      const { writeFileSync } = await import('fs');
      writeFileSync(resolve(args.output), output, 'utf-8');
      console.log(`✔ Report written to ${args.output}`);
    } else {
      console.log(output);
    }
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }
}
