import { readFileSync, existsSync } from 'fs';
import { extname } from 'path';

/**
 * Loads an array of objects from a JSON or CSV file.
 */
export function loadData(filePath) {
  if (!existsSync(filePath)) {
    throw new Error(`File not found: ${filePath}`);
  }

  const raw = readFileSync(filePath, 'utf-8');
  const ext = extname(filePath).toLowerCase();

  switch (ext) {
    case '.json':
      return parseJSON(raw);
    case '.csv':
      return parseCSV(raw);
    default:
      throw new Error(`Unsupported file type: ${ext}. Use .json or .csv`);
  }
}

function parseJSON(raw) {
  const data = JSON.parse(raw);
  if (!Array.isArray(data)) {
    throw new Error('JSON file must contain an array of objects');
  }
  return data;
}

/**
 * Minimal CSV parser — handles simple comma-separated files.
 * Not meant for production edge-cases (quoted commas, etc.)
 */
function parseCSV(raw) {
  const lines = raw.trim().split('\n');
  if (lines.length < 2) throw new Error('CSV must have a header row + data');

  const headers = lines[0].split(',').map((h) => h.trim());

  return lines.slice(1).map((line) => {
    const values = line.split(',').map((v) => v.trim());
    const obj = {};
    headers.forEach((h, i) => {
      const num = Number(values[i]);
      obj[h] = isNaN(num) ? values[i] : num;
    });
    return obj;
  });
}
