## src/reportGenerator.js — Core Logic

```javascript
/**
 * Takes raw row data and returns a structured report object.
 *
 * report = {
 *   title, generatedAt, columns, rows,
 *   summary: { totalRows, numericSummaries },
 *   groups?: [{ key, rows, summary }]
 * }
 */
export function generateReport(data, options = {}) {
  const { title = 'Report', sortBy = null, groupBy = null } = options;

  if (!data.length) {
    throw new Error('No data rows to report');
  }

  const columns = Object.keys(data[0]);
  let rows = [...data];

  // ── Sort ───────────────────────────────────────────────
  if (sortBy) {
    if (!columns.includes(sortBy)) {
      throw new Error(`Sort field "${sortBy}" not found. Available: ${columns.join(', ')}`);
    }
    rows.sort((a, b) => {
      if (typeof a[sortBy] === 'number') return a[sortBy] - b[sortBy];
      return String(a[sortBy]).localeCompare(String(b[sortBy]));
    });
  }

  // ── Build report ───────────────────────────────────────
  const report = {
    title,
    generatedAt: new Date().toISOString(),
    columns,
    rows,
    summary: buildSummary(rows, columns),
  };

  // ── Group ──────────────────────────────────────────────
  if (groupBy) {
    if (!columns.includes(groupBy)) {
      throw new Error(`Group field "${groupBy}" not found. Available: ${columns.join(', ')}`);
    }
    report.groups = buildGroups(rows, columns, groupBy);
  }

  return report;
}

// ── Helpers ──────────────────────────────────────────────

function buildSummary(rows, columns) {
  const numericCols = columns.filter((c) => typeof rows[0][c] === 'number');

  const summaries = {};
  for (const col of numericCols) {
    const values = rows.map((r) => r[col]);
    summaries[col] = {
      sum: round(values.reduce((a, b) => a + b, 0)),
      avg: round(values.reduce((a, b) => a + b, 0) / values.length),
      min: Math.min(...values),
      max: Math.max(...values),
    };
  }

  return { totalRows: rows.length, numericSummaries: summaries };
}

function buildGroups(rows, columns, groupBy) {
  const map = new Map();
  for (const row of rows) {
    const key = row[groupBy];
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(row);
  }

  return Array.from(map.entries()).map(([key, groupRows]) => ({
    key,
    rows: groupRows,
    summary: buildSummary(groupRows, columns),
  }));
}

function round(n) {
  return Math.round(n * 100) / 100;
}
