## src/formatters/text.js — Plain Text Table

```javascript
/**
 * Renders a nice human-readable text report.
 */
export function formatText(report) {
  const lines = [];
  const sep = '═'.repeat(60);

  // ── Header ─────────────────────────────────────────────
  lines.push(sep);
  lines.push(centerPad(report.title, 60));
  lines.push(`  Generated: ${report.generatedAt}`);
  lines.push(sep);

  // ── Data Table ─────────────────────────────────────────
  lines.push('');
  lines.push(renderTable(report.columns, report.rows));

  // ── Summary ────────────────────────────────────────────
  lines.push('');
  lines.push(`Total Rows: ${report.summary.totalRows}`);
  lines.push(renderSummary(report.summary.numericSummaries));

  // ── Groups ─────────────────────────────────────────────
  if (report.groups) {
    for (const group of report.groups) {
      lines.push('');
      lines.push('─'.repeat(60));
      lines.push(`Group: ${group.key}  (${group.summary.totalRows} rows)`);
      lines.push(renderSummary(group.summary.numericSummaries));
    }
  }

  lines.push(sep);
  return lines.join('\n');
}

// ── Helpers ──────────────────────────────────────────────

function renderTable(columns, rows) {
  // Calculate column widths
  const widths = columns.map((col) =>
    Math.max(col.length, ...rows.map((r) => String(r[col]).length))
  );

  const headerLine = columns.map((c, i) => c.padEnd(widths[i])).join(' │ ');
  const divider = widths.map((w) => '─'.repeat(w)).join('─┼─');

  const dataLines = rows.map((row) =>
    columns.map((c, i) => String(row[c]).padEnd(widths[i])).join(' │ ')
  );

  return [headerLine, divider, ...dataLines].join('\n');
}

function renderSummary(summaries) {
  const parts = [];
  for (const [col, stats] of Object.entries(summaries)) {
    parts.push(
      `  ${col}: sum=${stats.sum}  avg=${stats.avg}  min=${stats.min}  max=${stats.max}`
    );
  }
  return parts.join('\n');
}

function centerPad(str, width) {
  const pad = Math.max(0, Math.floor((width - str.length) / 2));
  return ' '.repeat(pad) + str;
}
