```javascript
export function formatCSV(report) {
  const lines = [];

  // Header row
  lines.push(report.columns.join(','));

  // Data rows
  for (const row of report.rows) {
    const values = report.columns.map((c) => {
      const val = row[c];
      // Wrap strings that contain commas in quotes
      return typeof val === 'string' && val.includes(',') ? `"${val}"` : val;
    });
    lines.push(values.join(','));
  }

  // Append summary as comment rows
  lines.push('');
  lines.push(`# Total Rows: ${report.summary.totalRows}`);
  for (const [col, stats] of Object.entries(report.summary.numericSummaries)) {
    lines.push(`# ${col}: sum=${stats.sum} avg=${stats.avg} min=${stats.min} max=${stats.max}`);
  }

  return lines.join('\n');
}
