### `src/cache/keys.js` — Cache Key Registry
```javascript
// Defines cache key patterns and their dependency graphs.
// This makes invalidation predictable and auditable.

class CacheKeyRegistry {
  constructor() {
    // Map of entity type -> key pattern templates
    this.patterns = new Map();

    // Dependency graph: when entity X changes, invalidate keys for Y
    this.dependencies = new Map();

    this.registerDefaults();
  }

  registerDefaults() {
    // Register key patterns with their metadata
    this.register("user", {
      single: (id) => `user:${id}`,
      list: () => "users:list",
      profile: (id) => `user:${id}:profile`,
      settings: (id) => `user:${id}:settings`,
    });

    this.register("product", {
      single: (id) => `product:${id}`,
      list: () => "products:list",
      category: (catId) => `products:category:${catId}`,
      search: (query) => `products:search:${Buffer.from(query).toString("base64")}`,
    });

    this.register("order", {
      single: (id) => `order:${id}`,
      userOrders: (userId) => `user:${userId}:orders`,
      recent: () => "orders:recent",
    });

    // Dependency graph: changing a user invalidates related caches
    this.addDependency("user", ["user", "order"]);
    this.addDependency("product", ["product"]);
    this.addDependency("order", ["order", "product"]); // order changes may affect product stock
  }

  register(entity, patterns) {
    this.patterns.set(entity, patterns);
  }

  addDependency(source, targets) {
    this.dependencies.set(source, targets);
  }

  // Get all key generators for an entity type
  getPatterns(entity) {
    return this.patterns.get(entity);
  }

  // Get all entity types that should be invalidated when source changes
  getDependencies(entity) {
    return this.dependencies.get(entity) || [entity];
  }

  // Generate a glob pattern for SCAN-based invalidation
  getGlobPattern(entity) {
    return `${entity}:*`;
  }
}

module.exports = new CacheKeyRegistry();
```

### `src/cache/CacheManager.js` — Core Cache Layer
```javascript
const Redis = require("ioredis");
const { v4: uuidv4 } = require("uuid");
const config = require("../../config");
const logger = require("../utils/logger");

class CacheManager {
  constructor() {
    this.client = new Redis(config.redis);
    this.metaPrefix = "_meta:";

    this.client.on("error", (err) => logger.error("Redis error", err));
    this.client.on("connect", () => logger.info("Redis connected"));
  }

  // ── Core Operations ──────────────────────────────────────

  async get(key) {
    const value = await this.client.get(key);
    if (!value) return null;

    // Track access for LRU-style metrics
    await this.client.hset(`${this.metaPrefix}${key}`, "lastAccess", Date.now());

    try {
      return JSON.parse(value);
    } catch {
      return value;
    }
  }

  async set(key, value, options = {}) {
    const {
      ttl = config.cache.defaultTTL,
      tags = [],       // tags for group invalidation
      version = null,  // optimistic locking
    } = options;

    const serialized = JSON.stringify(value);
    const pipeline = this.client.pipeline();

    // Set the value with TTL
    if (ttl > 0) {
      pipeline.setex(key, Math.min(ttl, config.cache.maxTTL), serialized);
    } else {
      pipeline.set(key, serialized);
    }

    // Store metadata for the cached entry
    const meta = {
      createdAt: Date.now(),
      ttl,
      version: version || uuidv4(),
      tags: JSON.stringify(tags),
      lastAccess: Date.now(),
    };
    pipeline.hset(`${this.metaPrefix}${key}`, meta);
    if (ttl > 0) {
      pipeline.expire(`${this.metaPrefix}${key}`, ttl + config.cache.staleThreshold);
    }

    // Add key to each tag set (for tag-based invalidation)
    for (const tag of tags) {
      pipeline.sadd(`_tag:${tag}`, key);
    }

    await pipeline.exec();
    logger.debug(`Cache SET: ${key}`, { ttl, tags });

    return meta.version;
  }

  async del(key) {
    const pipeline = this.client.pipeline();
    pipeline.del(key);
    pipeline.del(`${this.metaPrefix}${key}`);
    await pipeline.exec();
    logger.debug(`Cache DEL: ${key}`);
  }

  // ── Batch Operations ─────────────────────────────────────

  async mget(keys) {
    if (!keys.length) return {};

    const values = await this.client.mget(keys);
    const result = {};

    keys.forEach((key, i) => {
      if (values[i] !== null) {
        try {
          result[key] = JSON.parse(values[i]);
        } catch {
          result[key] = values[i];
        }
      }
    });

    return result;
  }

  async mdel(keys) {
    if (!keys.length) return 0;

    const pipeline = this.client.pipeline();
    for (const key of keys) {
      pipeline.del(key);
      pipeline.del(`${this.metaPrefix}${key}`);
    }
    const results = await pipeline.exec();
    const deleted = results.filter(([err, val]) => !err && val === 1).length / 2;

    logger.info(`Cache MDEL: ${deleted}/${keys.length} keys removed`);
    return deleted;
  }

  // ── Invalidation Methods ─────────────────────────────────

  // Invalidate by exact key
  async invalidateKey(key) {
    await this.del(key);
    return 1;
  }

  // Invalidate all keys matching a glob pattern using SCAN
  async invalidatePattern(pattern) {
    let cursor = "0";
    let totalDeleted = 0;

    do {
      const [nextCursor, keys] = await this.client.scan(
        cursor,
        "MATCH", pattern,
        "COUNT", config.cache.scanBatchSize
      );
      cursor = nextCursor;

      if (keys.length > 0) {
        totalDeleted += await this.mdel(keys);
      }
    } while (cursor !== "0");

    logger.info(`Pattern invalidation "${pattern}": ${totalDeleted} keys`);
    return totalDeleted;
  }

  // Invalidate all keys tagged with a specific tag
  async invalidateTag(tag) {
    const tagKey = `_tag:${tag}`;
    const keys = await this.client.smembers(tagKey);

    if (keys.length === 0) return 0;

    const deleted = await this.mdel(keys);
    await this.client.del(tagKey);

    logger.info(`Tag invalidation "${tag}": ${deleted} keys`);
    return deleted;
  }

  // Invalidate with version check (optimistic concurrency)
  async invalidateIfVersion(key, expectedVersion) {
    const meta = await this.client.hgetall(`${this.metaPrefix}${key}`);

    if (!meta || !meta.version) {
      return false; // key doesn't exist
    }
    if (meta.version !== expectedVersion) {
      logger.warn(`Version mismatch for ${key}: expected ${expectedVersion}, got ${meta.version}`);
      return false; // someone else already updated it
    }

    await this.del(key);
    return true;
  }

  // ── Metadata & Diagnostics ───────────────────────────────

  async getMeta(key) {
    const meta = await this.client.hgetall(`${this.metaPrefix}${key}`);
    if (!meta || !meta.createdAt) return null;

    return {
      ...meta,
      createdAt: parseInt(meta.createdAt, 10),
      ttl: parseInt(meta.ttl, 10),
      lastAccess: parseInt(meta.lastAccess, 10),
      tags: JSON.parse(meta.tags || "[]"),
      age: Date.now() - parseInt(meta.createdAt, 10),
    };
  }

  async getStats() {
    const info = await this.client.info("keyspace");
    const dbSize = await this.client.dbsize();
    return { dbSize, info };
  }

  async disconnect() {
    await this.client.quit();
  }
}

module.exports = CacheManager;
```

### `src/cache/InvalidationStrategy.js` — Strategy Definitions
```javascript
// Encapsulates different reasons and methods for cache invalidation.

class InvalidationStrategy {
  // Entity was directly modified (CRUD operation)
  static entityMutation(entityType, entityId, operation) {
    return {
      type: "ENTITY_MUTATION",
      entityType,
      entityId,
      operation, // 'create' | 'update' | 'delete'
      timestamp: Date.now(),
    };
  }

  // Invalidate all caches for an entity type (e.g., after bulk import)
  static bulkInvalidation(entityType, reason) {
    return {
      type: "BULK_INVALIDATION",
      entityType,
      reason,
      timestamp: Date.now(),
    };
  }

  // Invalidate by tag (e.g., "homepage", "featured")
  static tagInvalidation(tags, reason) {
    return {
      type: "TAG_INVALIDATION",
      tags: Array.isArray(tags) ? tags : [tags],
      reason,
      timestamp: Date.now(),
    };
  }

  // Time-based stale data cleanup
  static staleSweep(maxAge) {
    return {
      type: "STALE_SWEEP",
      maxAge,
      timestamp: Date.now(),
    };
  }

  // Custom pattern match
  static patternInvalidation(pattern, reason) {
    return {
      type: "PATTERN_INVALIDATION",
      pattern,
      reason,
      timestamp: Date.now(),
    };
  }
}

module.exports = InvalidationStrategy;
```

### `src/events/EventBus.js` — Redis Pub/Sub Event Bus
```javascript
const Redis = require("ioredis");
const config = require("../../config");
const logger = require("../utils/logger");

class EventBus {
  constructor() {
    // Separate connections: one for publishing, one for subscribing
    this.publisher = new Redis(config.redis);
    this.subscriber = new Redis(config.redis);
    this.handlers = new Map();

    this.subscriber.on("message", (channel, message) => {
      this._dispatch(channel, JSON.parse(message));
    });
  }

  // Publish a cache invalidation event
  async publish(channel, event) {
    const envelope = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
      channel,
      payload: event,
      publishedAt: Date.now(),
    };

    await this.publisher.publish(channel, JSON.stringify(envelope));
    logger.debug(`Event published: ${channel}`, { eventId: envelope.id });
  }

  // Subscribe to a channel with a handler
  subscribe(channel, handler) {
    if (!this.handlers.has(channel)) {
      this.handlers.set(channel, []);
      this.subscriber.subscribe(channel);
    }
    this.handlers.get(channel).push(handler);
    logger.info(`Subscribed to channel: ${channel}`);
  }

  _dispatch(channel, envelope) {
    const handlers = this.handlers.get(channel) || [];
    for (const handler of handlers) {
      try {
        handler(envelope.payload, envelope);
      } catch (err) {
        logger.error(`Handler error on ${channel}`, err);
      }
    }
  }

  async disconnect() {
    await this.publisher.quit();
    await this.subscriber.quit();
  }
}

module.exports = EventBus;
