const logger = require("../utils/logger");

class BackgroundWorker {
  constructor(name, options = {}) {
    this.name = name;
    this.running = false;
    this.tasks = [];
    this.intervals = [];
    this.options = {
      shutdownTimeout: 10000,
      ...options,
    };

    // Graceful shutdown
    process.on("SIGTERM", () => this.stop());
    process.on("SIGINT", () => this.stop());
  }

  // Register a recurring task
  addTask(task) {
    this.tasks.push(task);
    return this;
  }

  async start() {
    logger.info(`Worker [${this.name}] starting with ${this.tasks.length} tasks`);
    this.running = true;

    // Initialize all tasks
    for (const task of this.tasks) {
      await task.initialize();
    }

    // Start recurring tasks
    for (const task of this.tasks) {
      if (task.interval) {
        const id = setInterval(async () => {
          if (!this.running) return;

          try {
            const started = Date.now();
            await task.execute();
            const elapsed = Date.now() - started;
            logger.debug(`Task [${task.name}] completed in ${elapsed}ms`);
          } catch (err) {
            logger.error(`Task [${task.name}] failed`, err);
            await task.onError(err);
          }
        }, task.interval);

        this.intervals.push(id);
      }

      // Run event-driven tasks immediately (they set up listeners)
      if (task.isEventDriven) {
        await task.execute();
      }
    }

    logger.info(`Worker [${this.name}] is running`);
  }

  async stop() {
    if (!this.running) return;
    logger.info(`Worker [${this.name}] shutting down...`);
    this.running = false;

    // Clear all intervals
    for (const id of this.intervals) {
      clearInterval(id);
    }

    // Clean up all tasks
    const cleanup = this.tasks.map((task) =>
      Promise.race([
        task.cleanup(),
        new Promise((resolve) => setTimeout(resolve, this.options.shutdownTimeout)),
      ])
    );

    await Promise.allSettled(cleanup);
    logger.info(`Worker [${this.name}] stopped`);
  }
}

module.exports = BackgroundWorker;
