#[derive(Error, Debug)]
pub enum MigrationError {
    #[error("Migration version {0} not found")]
    VersionNotFound(u64),

    #[error("Backup not found: {0}")]
    BackupNotFound(String),

    #[error("Checksum mismatch for key '{key}': expected {expected}, got {actual}")]
    ChecksumMismatch {
        key: String,
        expected: String,
        actual: String,
    },

    #[error("Migration {version} already applied")]
    AlreadyApplied { version: u64 },

    #[error("Cannot rollback — no migrations applied")]
