```rust
use crate::error::{MigrationError, Result};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, HashMap};

/// Represents a single record in the data store.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Record {
    pub value: String,
    pub schema_version: u64,
}

/// In-memory key-value store simulating a database.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DataStore {
    records: BTreeMap<String, Record>,
    current_version: u64,
}

impl DataStore {
    pub fn new() -> Self {
        Self {
            records: BTreeMap::new(),
            current_version: 0,
        }
    }

    pub fn version(&self) -> u64 {
        self.current_version
    }

    pub fn set_version(&mut self, v: u64) {
        self.current_version = v;
    }

    pub fn get(&self, key: &str) -> Option<&Record> {
        self.records.get(key)
    }

    pub fn insert(&mut self, key: String, value: String) {
        self.records.insert(
            key,
            Record {
                value,
                schema_version: self.current_version,
            },
        );
    }

    pub fn remove(&mut self, key: &str) -> Option<Record> {
        self.records.remove(key)
    }

    pub fn keys(&self) -> Vec<String> {
        self.records.keys().cloned().collect()
    }

    pub fn records(&self) -> &BTreeMap<String, Record> {
        &self.records
    }

    /// Compute a SHA-256 checksum over all records (deterministic via BTreeMap).
    pub fn checksum(&self) -> String {
        let serialized = serde_json::to_string(&self.records).unwrap_or_default();
        let hash = Sha256::digest(serialized.as_bytes());
        format!("{:x}", hash)
    }

    /// Compute the diff between this store and a previous snapshot.
    /// Returns only keys that were added, modified, or removed.
    pub fn diff_from(&self, previous: &DataStore) -> StoreDiff {
        let mut added = HashMap::new();
        let mut modified = HashMap::new();
        let mut removed = HashMap::new();

        // Find additions and modifications
        for (key, record) in &self.records {
            match previous.records.get(key) {
                None => {
                    added.insert(key.clone(), record.clone());
                }
                Some(old_record) if old_record != record => {
                    modified.insert(
                        key.clone(),
                        DiffEntry {
                            old: old_record.clone(),
                            new: record.clone(),
                        },
                    );
                }
                _ => {} // unchanged
            }
        }

        // Find removals
        for key in previous.records.keys() {
            if !self.records.contains_key(key) {
                removed.insert(key.clone(), previous.records[key].clone());
            }
        }

        StoreDiff {
            added,
            modified,
            removed,
        }
    }

    /// Apply a diff to reconstruct a newer state from a base.
    pub fn apply_diff(&mut self, diff: &StoreDiff) {
        for (key, record) in &diff.added {
            self.records.insert(key.clone(), record.clone());
        }
        for (key, entry) in &diff.modified {
            self.records.insert(key.clone(), entry.new.clone());
        }
        for key in diff.removed.keys() {
            self.records.remove(key);
        }
    }

    /// Reverse-apply a diff to roll back changes.
    pub fn reverse_diff(&mut self, diff: &StoreDiff) {
        // Undo additions → remove them
        for key in diff.added.keys() {
            self.records.remove(key);
        }
        // Undo modifications → restore old value
        for (key, entry) in &diff.modified {
            self.records.insert(key.clone(), entry.old.clone());
        }
        // Undo removals → re-insert them
        for (key, record) in &diff.removed {
            self.records.insert(key.clone(), record.clone());
        }
    }
}

/// The delta between two store snapshots.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StoreDiff {
    pub added: HashMap<String, Record>,
    pub modified: HashMap<String, DiffEntry>,
    pub removed: HashMap<String, Record>,
}

impl StoreDiff {
    pub fn is_empty(&self) -> bool {
        self.added.is_empty() && self.modified.is_empty() && self.removed.is_empty()
    }

    pub fn change_count(&self) -> usize {
        self.added.len() + self.modified.len() + self.removed.len()
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DiffEntry {
    pub old: Record,
    pub new: Record,
}

/// Verify that a store matches an expected checksum.
pub fn verify_checksum(store: &DataStore, expected: &str) -> Result<()> {
    let actual = store.checksum();
    if actual != expected {
        return Err(MigrationError::ChecksumMismatch {
            key: format!("store@v{}", store.version()),
            expected: expected.to_string(),
            actual,
        });
    }
    Ok(())
}
