```rust
use crate::error::{MigrationError, Result};
use crate::storage::{DataStore, StoreDiff};
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use uuid::Uuid;

/// Metadata for a single backup snapshot.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackupMeta {
    pub id: String,
    pub version: u64,
    pub parent_id: Option<String>,
    pub created_at: DateTime<Utc>,
    pub checksum: String,
    pub change_count: usize,
    pub backup_type: BackupType,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub enum BackupType {
    Full,
    Incremental,
}

/// A single incremental backup entry — stores only the diff.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IncrementalBackup {
    pub meta: BackupMeta,
    pub diff: StoreDiff,
}

/// A full backup entry — stores the entire snapshot.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FullBackup {
    pub meta: BackupMeta,
    pub snapshot: DataStore,
}

/// Manages the chain of backups (full + incremental).
#[derive(Debug)]
pub struct BackupChain {
    /// Full backups keyed by their ID.
    full_backups: BTreeMap<String, FullBackup>,

    /// Incremental backups keyed by their ID.
    incremental_backups: BTreeMap<String, IncrementalBackup>,

    /// Ordered list of backup IDs (oldest first).
    chain: Vec<String>,

    /// How many incremental backups before forcing a full backup.
    full_backup_interval: usize,

    /// Counter since last full backup.
    since_last_full: usize,
}

impl BackupChain {
    pub fn new(full_backup_interval: usize) -> Self {
        Self {
            full_backups: BTreeMap::new(),
            incremental_backups: BTreeMap::new(),
            chain: Vec::new(),
            full_backup_interval,
            since_last_full: 0,
        }
    }

    /// Create a backup of the current store state.
    /// Automatically decides between full and incremental.
    pub fn create_backup(&mut self, store: &DataStore) -> Result<BackupMeta> {
        let needs_full = self.chain.is_empty()
            || self.since_last_full >= self.full_backup_interval;

        if needs_full {
            self.create_full_backup(store)
        } else {
            self.create_incremental_backup(store)
        }
    }

    /// Force a full backup regardless of the interval.
    pub fn create_full_backup(&mut self, store: &DataStore) -> Result<BackupMeta> {
        let id = Uuid::new_v4().to_string();
        let meta = BackupMeta {
            id: id.clone(),
            version: store.version(),
            parent_id: self.chain.last().cloned(),
            created_at: Utc::now(),
            checksum: store.checksum(),
            change_count: store.records().len(),
            backup_type: BackupType::Full,
        };

        let backup = FullBackup {
            meta: meta.clone(),
            snapshot: store.clone(),
        };

        self.full_backups.insert(id.clone(), backup);
        self.chain.push(id);
        self.since_last_full = 0;

        println!(
            "  ✔ Full backup created: version={}, records={}, id={}…",
            meta.version,
            meta.change_count,
            &meta.id[..8]
        );

        Ok(meta)
    }

    /// Create an incremental backup (diff from last known state).
    fn create_incremental_backup(&mut self, store: &DataStore) -> Result<BackupMeta> {
        let previous_state = self.restore_latest()?;
        let diff = store.diff_from(&previous_state);

        let id = Uuid::new_v4().to_string();
        let meta = BackupMeta {
            id: id.clone(),
            version: store.version(),
            parent_id: self.chain.last().cloned(),
            created_at: Utc::now(),
            checksum: store.checksum(),
            change_count: diff.change_count(),
            backup_type: BackupType::Incremental,
        };

        let backup = IncrementalBackup {
            meta: meta.clone(),
            diff,
        };

        self.incremental_backups.insert(id.clone(), backup);
        self.chain.push(id);
        self.since_last_full += 1;

        println!(
            "  ✔ Incremental backup: version={}, changes={}, id={}…",
            meta.version,
            meta.change_count,
            &meta.id[..8]
        );

        Ok(meta)
    }

    /// Restore the store to the state at a specific backup ID.
    pub fn restore_to(&self, target_id: &str) -> Result<DataStore> {
        // Find the position of the target in the chain
        let target_pos = self
            .chain
            .iter()
            .position(|id| id == target_id)
            .ok_or_else(|| MigrationError::BackupNotFound(target_id.to_string()))?;

        // Walk backwards to find the nearest full backup
        let mut full_pos = None;
        for i in (0..=target_pos).rev() {
            let id = &self.chain[i];
            if self.full_backups.contains_key(id) {
                full_pos = Some(i);
                break;
            }
        }

        let full_pos =
            full_pos.ok_or_else(|| MigrationError::BrokenChain(0))?;

        // Start from the full backup
        let full_id = &self.chain[full_pos];
        let mut store = self.full_backups[full_id].snapshot.clone();

        // Apply each incremental diff up to (and including) the target
        for i in (full_pos + 1)..=target_pos {
            let id = &self.chain[i];
            if let Some(inc) = self.incremental_backups.get(id) {
                store.apply_diff(&inc.diff);
                store.set_version(inc.meta.version);
            }
            // Full backups in the middle just replace the store
            else if let Some(full) = self.full_backups.get(id) {
                store = full.snapshot.clone();
            }
        }

        Ok(store)
    }

    /// Restore to the most recent backup.
    pub fn restore_latest(&self) -> Result<DataStore> {
        let latest_id = self
            .chain
            .last()
            .ok_or(MigrationError::NothingToRollback)?
            .clone();
        self.restore_to(&latest_id)
    }

    /// List all backups in chronological order.
    pub fn list_backups(&self) -> Vec<&BackupMeta> {
        self.chain
            .iter()
            .filter_map(|id| {
                self.full_backups
                    .get(id)
                    .map(|b| &b.meta)
                    .or_else(|| self.incremental_backups.get(id).map(|b| &b.meta))
            })
            .collect()
    }

    /// Get the total number of backups.
    pub fn len(&self) -> usize {
        self.chain.len()
    }

    /// Export the full chain metadata as JSON (for persistence).
    pub fn export_manifest(&self) -> Result<String> {
        let manifest: Vec<&BackupMeta> = self.list_backups();
        Ok(serde_json::to_string_pretty(&manifest)?)
    }
}
