use crate::backup::BackupChain;
use crate::error::{MigrationError, Result};
use crate::storage::{self, DataStore};
use std::collections::BTreeMap;

/// Defines what a single migration step does.
pub trait MigrationStep: std::fmt::Debug {
    fn version(&self) -> u64;
    fn description(&self) -> &str;

    /// Apply the migration (upgrade).
    fn up(&self, store: &mut DataStore) -> Result<()>;

    /// Reverse the migration (downgrade).
    fn down(&self, store: &mut DataStore) -> Result<()>;
}

/// Orchestrates running migrations with automatic incremental backups.
pub struct MigrationRunner {
    store: DataStore,
    backups: BackupChain,
    migrations: BTreeMap<u64, Box<dyn MigrationStep>>,
    applied: Vec<u64>,
}

impl MigrationRunner {
    pub fn new(full_backup_interval: usize) -> Self {
        Self {
            store: DataStore::new(),
            backups: BackupChain::new(full_backup_interval),
            migrations: BTreeMap::new(),
            applied: Vec::new(),
        }
    }

    /// Register a migration step.
    pub fn register(&mut self, step: Box<dyn MigrationStep>) {
        let v = step.version();
        self.migrations.insert(v, step);
    }

    /// Apply all pending migrations in order, creating backups before each.
    pub fn migrate_up_all(&mut self) -> Result<Vec<u64>> {
        let pending: Vec<u64> = self
            .migrations
            .keys()
            .filter(|v| !self.applied.contains(v))
            .cloned()
            .collect();

        if pending.is_empty() {
            println!("  ℹ No pending migrations.");
            return Ok(vec![]);
        }

        let mut newly_applied = Vec::new();

        for version in &pending {
            self.migrate_up(*version)?;
            newly_applied.push(*version);
        }

        Ok(newly_applied)
    }

    /// Apply a single migration by version, with a pre-migration backup.
    pub fn migrate_up(&mut self, version: u64) -> Result<()> {
        if self.applied.contains(&version) {
            return Err(MigrationError::AlreadyApplied { version });
        }

        let step = self
            .migrations
            .get(&version)
            .ok_or(MigrationError::VersionNotFound(version))?;

        println!(
            "\n▶ Applying migration v{}: {}",
            version,
            step.description()
        );

        // --- Backup BEFORE applying ---
        println!("  Creating pre-migration backup…");
        self.backups.create_backup(&self.store)?;

        // --- Apply ---
        // We need to work around the borrow checker here
        let step = self.migrations.get(&version).unwrap();
        step.up(&mut self.store)?;
        self.store.set_version(version);

