// utils/reader.js
import { readFile } from "fs/promises";
import { existsSync } from "fs";

/**
 * Reads JSON from a file path or stdin
 */
export async function readJSON(source) {
  // Read from file
  if (source && source !== "--stdin") {
    if (!existsSync(source)) {
      throw new Error(`File not found: ${source}`);
    }
    const raw = await readFile(source, "utf-8");
    return JSON.parse(raw);
  }

  // Read from stdin
  return readFromStdin();
}

function readFromStdin() {
  return new Promise((resolve, reject) => {
    let data = "";

    process.stdin.setEncoding("utf-8");
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => {
      try {
        resolve(JSON.parse(data));
      } catch (err) {
        reject(new Error(`Invalid JSON from stdin: ${err.message}`));
      }
    });
    process.stdin.on("error", reject);

    // Timeout after 5s if no input
    setTimeout(() => reject(new Error("Stdin read timeout")), 5000);
  });
}
