    const totalMs = (new Date() - this.#context.startedAt).toFixed(0);
    console.log(`\n✅ Pipeline complete in ${totalMs}ms\n`);

    return { data, context: this.#context };
  }
}
```

## Pipeline Stages

### Filter Stage

```javascript
// stages/filter.js

/**
 * Creates a filter stage from a predicate function
 */
export function filterBy(predicate, description = "filter") {
  return function filterStage(data) {
    if (!Array.isArray(data)) {
      throw new Error("Filter expects an array");
    }
    return data.filter(predicate);
  };
}

/** Remove events of a specific type */
export function excludeEvents(...eventTypes) {
  const excluded = new Set(eventTypes);
  return filterBy(
    (record) => !excluded.has(record.event),
    `exclude: ${eventTypes.join(", ")}`
  );
}

/** Keep only events of specific types */
export function includeEvents(...eventTypes) {
  const included = new Set(eventTypes);
  return filterBy(
    (record) => included.has(record.event),
    `include: ${eventTypes.join(", ")}`
  );
}

/** Filter by time range */
export function timeRange(start, end) {
  const startMs = new Date(start).getTime();
  const endMs = new Date(end).getTime();

  return filterBy(
    (record) => {
      const ts = new Date(record.timestamp).getTime();
      return ts >= startMs && ts <= endMs;
    },
    `time: ${start} → ${end}`
  );
}
```

### Transform Stage

```javascript
// stages/transform.js

/**
 * Enrich each record with computed fields
 */
export function enrich(enrichFn) {
  return function enrichStage(data) {
    return data.map((record) => ({
      ...record,
      ...enrichFn(record),
    }));
  };
}

/** Parse timestamp and add hour/date fields */
export function addTimeParts() {
  return enrich((record) => {
    const date = new Date(record.timestamp);
    return {
      _hour: date.getUTCHours(),
      _date: date.toISOString().split("T")[0],
      _dayOfWeek: date.toLocaleDateString("en-US", { weekday: "short", timeZone: "UTC" }),
    };
  });
}

/** Categorize pages into sections */
export function categorizePages(mapping = {}) {
  const defaultMapping = {
    "/home": "landing",
    "/pricing": "conversion",
    "/checkout": "conversion",
    "/dashboard": "product",
    "/settings": "product",
  };

  const finalMapping = { ...defaultMapping, ...mapping };

  return enrich((record) => ({
    _section: finalMapping[record.page] || "other",
  }));
}

/** Rename or reshape fields */
export function mapFields(fieldMap) {
  return function mapStage(data) {
    return data.map((record) => {
      const mapped = {};
      for (const [newKey, sourceFn] of Object.entries(fieldMap)) {
        mapped[newKey] =
          typeof sourceFn === "function" ? sourceFn(record) : record[sourceFn];
      }
      return mapped;
    });
  };
}
```

### Aggregate Stage

```javascript
// stages/aggregate.js

/**
 * Group records by a key and compute aggregations
 */
export function groupBy(keyFn, aggregations) {
  return function groupStage(data) {
    // Build groups
    const groups = new Map();

    for (const record of data) {
      const key = typeof keyFn === "string" ? record[keyFn] : keyFn(record);
      if (!groups.has(key)) {
        groups.set(key, []);
      }
      groups.get(key).push(record);
    }

    // Apply aggregations to each group
    const results = [];

    for (const [key, records] of groups) {
      const row = { _key: key, _count: records.length };

      for (const [name, aggFn] of Object.entries(aggregations)) {
        row[name] = aggFn(records);
      }

      results.push(row);
    }

    return results;
  };
}

/** Common aggregation helpers */
export const agg = {
  count: () => (records) => records.length,

  sum: (field) => (records) =>
    records.reduce((acc, r) => acc + (Number(r[field]) || 0), 0),

  avg: (field) => (records) => {
    const vals = records.map((r) => r[field]).filter((v) => v != null);
    return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
  },

  min: (field) => (records) =>
    Math.min(...records.map((r) => r[field]).filter((v) => v != null)),

  max: (field) => (records) =>
    Math.max(...records.map((r) => r[field]).filter((v) => v != null)),

  countDistinct: (field) => (records) =>
    new Set(records.map((r) => r[field])).size,

  collect: (field) => (records) =>
    [...new Set(records.map((r) => r[field]))],

  first: (field) => (records) =>
    records[0]?.[field],

  last: (field) => (records) =>
    records[records.length - 1]?.[field],
};

/**
 * Sort results by a field
 */
export function sortBy(field, order = "desc") {
  return function sortStage(data) {
    return [...data].sort((a, b) => {
      const valA = a[field] ?? 0;
      const valB = b[field] ?? 0;
      return order === "desc" ? valB - valA : valA - valB;
    });
  };
}

/**
 * Limit results to top N
 */
export function limit(n) {
  return function limitStage(data) {
    return data.slice(0, n);
  };
}
```

### Output Stage

```javascript
// stages/output.js
import { writeFile } from "fs/promises";

/**
 * Print results as a formatted table
 */
export function printTable(title = "Results") {
  return function printStage(data, context) {
    console.log(`\n📊 ${title}`);
    console.log("─".repeat(60));

    if (data.length === 0) {
      console.log("   (no data)");
    } else {
      console.table(data);
    }

    // Store in context for later use
    context.metrics[title] = data;

    return data; // pass through
  };
}

/**
 * Write results to a JSON file
 */
export function writeJSON(filepath) {
  return async function writeStage(data) {
    const output = JSON.stringify(data, null, 2);
    await writeFile(filepath, output, "utf-8");
    console.log(`   💾 Wrote ${filepath}`);
    return data;
  };
}

/**
 * Write a summary report
 */
export function printSummary() {
  return function summaryStage(data, context) {
    console.log("\n📈 Summary");
    console.log("─".repeat(60));
    console.log(`   Total input records : ${context.inputCount}`);
    console.log(`   Output records      : ${data.length}`);
    console.log(`   Pipeline            : ${context.pipelineName}`);
    console.log(`   Started at          : ${context.startedAt.toISOString()}`);
    return data;
  };
}
```

## Main Entry Point

```javascript
// index.js
import { readJSON } from "./utils/reader.js";
import { Pipeline } from "./pipeline.js";
import { excludeEvents, includeEvents } from "./stages/filter.js";
import { addTimeParts, categorizePages } from "./stages/transform.js";
import { groupBy, agg, sortBy, limit } from "./stages/aggregate.js";
import { printTable, printSummary } from "./stages/output.js";

async function main() {
  // --- Read Input ---
  const source = process.argv[2] || "--stdin";
  const events = await readJSON(source);

  console.log("═".repeat(60));
  console.log(" ANALYTICS PIPELINE");
  console.log("═".repeat(60));

  // --- Pipeline 1: Page View Analytics ---
  const pageAnalytics = new Pipeline("Page View Analytics")
    .addStage("Remove errors", excludeEvents("error"))
    .addStage("Keep page views", includeEvents("page_view"))
    .addStage("Add time parts", addTimeParts())
    .addStage("Categorize pages", categorizePages())
    .addStage(
      "Group by page",
      groupBy("page", {
        views: agg.count(),
        uniqueUsers: agg.countDistinct("userId"),
        avgDuration: agg.avg("duration"),
        totalDuration: agg.sum("duration"),
        section: agg.first("_section"),
      })
    )
    .addStage("Sort by views", sortBy("views"))
    .addStage("Print", printTable("Page Views Report"));

  await pageAnalytics.run(events);

  // --- Pipeline 2: User Activity ---
  const userActivity = new Pipeline("User Activity")
    .addStage("Remove errors", excludeEvents("error"))
    .addStage("Add time parts", addTimeParts())
    .addStage(
      "Group by user",
      groupBy("userId", {
        totalEvents: agg.count(),
        eventTypes: agg.collect("event"),
        pagesVisited: agg.countDistinct("page"),
        firstSeen: agg.first("timestamp"),
        lastSeen: agg.last("timestamp"),
      })
    )
    .addStage("Sort by events", sortBy("totalEvents"))
    .addStage("Print", printTable("User Activity Report"))
    .addStage("Summary", printSummary());

  await userActivity.run(events);

  // --- Pipeline 3: Hourly Traffic ---
  const hourlyTraffic = new Pipeline("Hourly Traffic")
    .addStage("Add time parts", addTimeParts())
    .addStage(
      "Group by hour",
      groupBy("_hour", {
        events: agg.count(),
        uniqueUsers: agg.countDistinct("userId"),
        types: agg.collect("event"),
      })
    )
    .addStage("Sort by hour", sortBy("_key", "asc"))
    .addStage("Print", printTable("Hourly Traffic Report"));

  await hourlyTraffic.run(events);
}

main().catch((err) => {
  console.error(`\n💥 Fatal: ${err.message}`);
  process.exit(1);
});
```

