### `src/processors/csv-processor.js`

```javascript
import { readFile } from "fs/promises";

/**
 * Parses a CSV file into structured data.
 * Handles quoted fields, different line endings, and type coercion.
 */
export async function process(filePath) {
  const raw = await readFile(filePath, "utf-8");
  const lines = raw.split(/\r?\n/).filter((line) => line.trim());

  if (lines.length < 2) {
    throw new Error("CSV must have a header row and at least one data row");
  }

  const headers = parseCsvLine(lines[0]);
  const rows = [];

  for (let i = 1; i < lines.length; i++) {
    const values = parseCsvLine(lines[i]);
    if (values.length !== headers.length) {
      throw new Error(`Row ${i + 1}: expected ${headers.length} columns, got ${values.length}`);
    }

    const row = {};
    headers.forEach((header, idx) => {
      row[header] = coerceType(values[idx]);
    });
    rows.push(row);
  }

  return {
    headers,
    rows,
    rowCount: rows.length,
  };
}

function parseCsvLine(line) {
  const fields = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (inQuotes) {
      if (char === '"' && line[i + 1] === '"') {
        current += '"';
        i++; // skip escaped quote
      } else if (char === '"') {
        inQuotes = false;
      } else {
        current += char;
      }
    } else if (char === '"') {
      inQuotes = true;
    } else if (char === ",") {
      fields.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }

  fields.push(current.trim());
  return fields;
}

function coerceType(value) {
  if (value === "") return null;
  const num = Number(value);
  if (!isNaN(num) && value !== "") return num;
  if (value.toLowerCase() === "true") return true;
  if (value.toLowerCase() === "false") return false;
  return value;
}
```

