```javascript
import { readFile } from "fs/promises";

/**
 * Parses a JSON file. Accepts arrays of objects or single objects.
 */
export async function process(filePath) {
  const raw = await readFile(filePath, "utf-8");

  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new Error("Invalid JSON format");
  }

  // Normalize to array
  const rows = Array.isArray(data) ? data : [data];

  if (rows.length === 0) {
    throw new Error("JSON file contains no records");
  }

  // Extract headers from all objects (union of all keys)
  const headerSet = new Set();
  rows.forEach((row) => {
    if (typeof row !== "object" || row === null) {
      throw new Error("Each record must be an object");
    }
    Object.keys(row).forEach((key) => headerSet.add(key));
  });

  return {
    headers: [...headerSet],
    rows,
    rowCount: rows.length,
  };
}
