```javascript
import { writeFile } from "fs/promises";
import { resolve, basename } from "path";
import config from "../config.js";
import logger from "./logger.js";

/**
 * Generates a summary report from processed data.
 * Outputs a JSON report with statistics and data preview.
 */
export async function generate(sourceFileName, processedData) {
  const { headers, rows, rowCount } = processedData;

  const report = {
    meta: {
      sourceFile: sourceFileName,
      generatedAt: new Date().toISOString(),
      totalRows: rowCount,
      columns: headers,
    },
    statistics: computeStatistics(headers, rows),
    preview: rows.slice(0, 5), // first 5 rows
  };

  // Write report
  const timestamp = Date.now();
  const baseName = basename(sourceFileName, /\.[^.]+$/.exec(sourceFileName)?.[0]);
  const reportName = `${baseName}_report_${timestamp}.json`;
  const reportPath = resolve(config.dirs.reports, reportName);

  await writeFile(reportPath, JSON.stringify(report, null, 2), "utf-8");

  logger.info("Report written", { reportPath, rows: rowCount });
  return { reportPath, reportName, report };
}

/**
 * Computes per-column statistics for numeric and categorical fields.
 */
function computeStatistics(headers, rows) {
  const stats = {};

  for (const header of headers) {
    const values = rows.map((r) => r[header]).filter((v) => v !== null && v !== undefined);
    const numericValues = values.filter((v) => typeof v === "number");

    if (numericValues.length > 0 && numericValues.length >= values.length * 0.5) {
      // Treat as numeric column
      const sorted = [...numericValues].sort((a, b) => a - b);
      stats[header] = {
        type: "numeric",
        count: numericValues.length,
        nullCount: rows.length - values.length,
        min: sorted[0],
        max: sorted[sorted.length - 1],
        mean: round(numericValues.reduce((a, b) => a + b, 0) / numericValues.length),
        median: round(
          sorted.length % 2 === 0
            ? (sorted[sorted.length / 2 - 1] + sorted[sorted.length / 2]) / 2
            : sorted[Math.floor(sorted.length / 2)]
        ),
      };
    } else {
      // Treat as categorical
      const freq = {};
      values.forEach((v) => {
        const key = String(v);
        freq[key] = (freq[key] || 0) + 1;
      });

      const sorted = Object.entries(freq).sort((a, b) => b[1] - a[1]);

      stats[header] = {
        type: "categorical",
        count: values.length,
        nullCount: rows.length - values.length,
        uniqueValues: Object.keys(freq).length,
        topValues: Object.fromEntries(sorted.slice(0, 5)),
      };
    }
  }

  return stats;
}

function round(num) {
  return Math.round(num * 100) / 100;
}
