### `src/watcher.js` — The Main Engine

```javascript
import chokidar from "chokidar";
import { rename, mkdir } from "fs/promises";
import { resolve, extname, basename } from "path";
import { EventEmitter } from "events";
import config from "../config.js";
import logger from "./logger.js";
import { getProcessor, isSupported } from "./processors/index.js";
import { generate } from "./report-generator.js";

export class ReportWatcher extends EventEmitter {
  #watcher = null;
  #activeJobs = 0;
  #queue = [];
  #isShuttingDown = false;

  async start() {
    await this.#ensureDirectories();

    this.#watcher = chokidar.watch(config.dirs.inbox, {
      ...config.watcher,
      // Only watch supported file types
      ignored: (filePath, stats) => {
        if (stats?.isFile()) {
          return !isSupported(extname(filePath));
        }
        return false;
      },
    });

    this.#watcher
      .on("add", (filePath) => this.#enqueue(filePath))
      .on("error", (err) => {
        logger.error("Watcher error", { error: err.message });
        this.emit("error", err);
      })
      .on("ready", () => {
        logger.info("Watcher ready", { directory: config.dirs.inbox });
        this.emit("ready");
      });

    return this;
  }

  async stop() {
    this.#isShuttingDown = true;
    logger.info("Shutting down watcher...");

    if (this.#watcher) {
      await this.#watcher.close();
    }

    // Wait for active jobs to complete (with timeout)
    if (this.#activeJobs > 0) {
      logger.info("Waiting for active jobs to finish", { count: this.#activeJobs });
      await this.#waitForDrain(10_000);
    }

    this.emit("stopped");
    logger.info("Watcher stopped");
  }

  // ── Private Methods ───────────────────────────────────────

  #enqueue(filePath) {
    this.#queue.push(filePath);
    this.#processNext();
  }

  #processNext() {
    if (this.#isShuttingDown) return;
    if (this.#activeJobs >= config.processing.maxConcurrent) return;

    const filePath = this.#queue.shift();
    if (!filePath) return;

    this.#activeJobs++;
    this.#processFile(filePath)
      .catch(() => {}) // errors handled inside
      .finally(() => {
        this.#activeJobs--;
        this.#processNext(); // pick up next queued item
      });
  }

  async #processFile(filePath, attempt = 1) {
    const fileName = basename(filePath);
    const ext = extname(filePath);
    const maxAttempts = config.processing.retryAttempts;

    logger.info("Processing file", { fileName, attempt });

    try {
      // 1. Move to processing directory (prevents double-processing)
      const processingPath = resolve(config.dirs.processing, fileName);
      await rename(filePath, processingPath);

      // 2. Get the right processor and parse the file
      const processor = getProcessor(ext);
      if (!processor) {
        throw new Error(`No processor for extension: ${ext}`);
      }

      const data = await processor.process(processingPath);

      // 3. Generate the report
      const result = await generate(fileName, data);

      // 4. Clean up — remove the processed source file
      const donePath = resolve(config.dirs.reports, `source_${fileName}`);
      await rename(processingPath, donePath);

      this.emit("report", { fileName, reportPath: result.reportPath });
      logger.info("File processed successfully", { fileName });
    } catch (err) {
      logger.error("Processing failed", {
        fileName,
        attempt,
        error: err.message,
      });

      if (attempt < maxAttempts) {
        // Retry with backoff
        const delay = config.processing.retryDelayMs * attempt;
        logger.info("Retrying", { fileName, nextAttempt: attempt + 1, delayMs: delay });
        await new Promise((r) => setTimeout(r, delay));
        return this.#processFile(filePath, attempt + 1);
      }

      // Move to failed directory after exhausting retries
      await this.#moveToFailed(fileName).catch((moveErr) => {
        logger.error("Failed to move to failed dir", { error: moveErr.message });
      });

      this.emit("failed", { fileName, error: err });
    }
  }

  async #moveToFailed(fileName) {
    const sources = [
      resolve(config.dirs.processing, fileName),
      resolve(config.dirs.inbox, fileName),
    ];

    for (const src of sources) {
      try {
        await rename(src, resolve(config.dirs.failed, fileName));
        logger.warn("Moved to failed", { fileName });
        return;
      } catch {
        // file not at this location, try next
      }
    }
  }

  async #ensureDirectories() {
    const dirs = Object.values(config.dirs);
    await Promise.all(dirs.map((dir) => mkdir(dir, { recursive: true })));
    logger.debug("Directories ensured", { dirs });
  }

  #waitForDrain(timeoutMs) {
    return new Promise((resolve) => {
      const check = setInterval(() => {
        if (this.#activeJobs === 0) {
          clearInterval(check);
          resolve();
        }
      }, 200);

      setTimeout(() => {
        clearInterval(check);
        logger.warn("Drain timeout — forcing stop", { remainingJobs: this.#activeJobs });
        resolve();
      }, timeoutMs);
    });
  }
}
```

