## `src/main.rs`

```rust
use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::{mpsc, RwLock, Notify};
use tokio::task::JoinHandle;

// ─── Metric Types ──────────────────────────────────────────────

/// Represents a single metric data point submitted by application code.
#[derive(Debug, Clone)]
enum MetricValue {
    Counter(f64),
    Gauge(f64),
    Histogram(f64),
}

#[derive(Debug, Clone)]
struct MetricSample {
    name: String,
    value: MetricValue,
    tags: Vec<(String, String)>,
    timestamp: Instant,
}

// ─── Aggregated Snapshots ──────────────────────────────────────

/// The result of aggregating many samples over a flush interval.
#[derive(Debug, Clone, Default)]
struct AggregatedCounter {
    sum: f64,
    count: u64,
}

#[derive(Debug, Clone)]
struct AggregatedGauge {
    last: f64,
    min: f64,
    max: f64,
}

#[derive(Debug, Clone, Default)]
struct AggregatedHistogram {
    values: Vec<f64>,
    sum: f64,
    count: u64,
    min: f64,
    max: f64,
}

#[derive(Debug, Clone)]
enum AggregatedMetric {
    Counter(AggregatedCounter),
    Gauge(AggregatedGauge),
    Histogram(AggregatedHistogram),
}

/// A full snapshot emitted every flush interval.
#[derive(Debug)]
struct MetricsSnapshot {
    metrics: HashMap<String, AggregatedMetric>,
    flush_duration: Duration,
    total_samples: u64,
}

// ─── Internal Bucket ───────────────────────────────────────────

/// Accumulates samples between flushes.
#[derive(Default)]
struct MetricsBucket {
    counters: HashMap<String, AggregatedCounter>,
    gauges: HashMap<String, AggregatedGauge>,
    histograms: HashMap<String, AggregatedHistogram>,
    total_samples: u64,
}

impl MetricsBucket {
    fn record(&mut self, sample: MetricSample) {
        self.total_samples += 1;

        // Build a key from name + sorted tags for uniqueness
        let key = Self::make_key(&sample.name, &sample.tags);

        match sample.value {
            MetricValue::Counter(v) => {
                let entry = self.counters.entry(key).or_default();
                entry.sum += v;
                entry.count += 1;
            }
            MetricValue::Gauge(v) => {
                self.gauges
                    .entry(key)
                    .and_modify(|g| {
                        g.last = v;
                        g.min = g.min.min(v);
                        g.max = g.max.max(v);
                    })
                    .or_insert(AggregatedGauge {
                        last: v,
                        min: v,
                        max: v,
                    });
            }
            MetricValue::Histogram(v) => {
                let entry = self.histograms.entry(key).or_default();
                if entry.count == 0 {
                    entry.min = v;
                    entry.max = v;
                } else {
                    entry.min = entry.min.min(v);
                    entry.max = entry.max.max(v);
                }
                entry.values.push(v);
                entry.sum += v;
                entry.count += 1;
            }
        }
    }

    /// Drain the bucket into a snapshot and reset.
    fn flush(&mut self, flush_duration: Duration) -> MetricsSnapshot {
        let mut metrics = HashMap::new();

        for (k, v) in self.counters.drain() {
            metrics.insert(k, AggregatedMetric::Counter(v));
        }
        for (k, v) in self.gauges.drain() {
            metrics.insert(k, AggregatedMetric::Gauge(v));
        }
        for (k, mut v) in self.histograms.drain() {
            // Sort values so percentile calculation is easy downstream
            v.values.sort_by(|a, b| a.partial_cmp(b).unwrap());
            metrics.insert(k, AggregatedMetric::Histogram(v));
        }

        let total_samples = self.total_samples;
        self.total_samples = 0;

        MetricsSnapshot {
            metrics,
            flush_duration,
            total_samples,
        }
    }

    fn make_key(name: &str, tags: &[(String, String)]) -> String {
        if tags.is_empty() {
            return name.to_string();
        }
        let mut sorted_tags = tags.to_vec();
        sorted_tags.sort();
        let tag_str: Vec<String> = sorted_tags
            .iter()
            .map(|(k, v)| format!("{k}:{v}"))
            .collect();
        format!("{name}|{}", tag_str.join(","))
    }
}

// ─── Metrics Client (the handle callers use) ──────────────────

/// Cheaply cloneable handle for submitting metrics from anywhere.
#[derive(Clone)]
struct MetricsClient {
    tx: mpsc::Sender<MetricSample>,
}

impl MetricsClient {
    /// Increment a counter.
    pub async fn counter(&self, name: &str, value: f64, tags: &[(&str, &str)]) {
        let _ = self.tx.send(MetricSample {
            name: name.to_string(),
            value: MetricValue::Counter(value),
            tags: tags.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect(),
            timestamp: Instant::now(),
        }).await;
    }

    /// Set a gauge value.
    pub async fn gauge(&self, name: &str, value: f64, tags: &[(&str, &str)]) {
        let _ = self.tx.send(MetricSample {
            name: name.to_string(),
            value: MetricValue::Gauge(value),
            tags: tags.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect(),
            timestamp: Instant::now(),
        }).await;
    }

    /// Record a histogram observation (e.g. latency).
    pub async fn histogram(&self, name: &str, value: f64, tags: &[(&str, &str)]) {
        let _ = self.tx.send(MetricSample {
            name: name.to_string(),
            value: MetricValue::Histogram(value),
            tags: tags.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect(),
            timestamp: Instant::now(),
        }).await;
    }
}

// ─── Background Aggregation Worker ────────────────────────────

struct AggregationWorker {
    rx: mpsc::Receiver<MetricSample>,
    bucket: MetricsBucket,
    flush_interval: Duration,
    shutdown: Arc<Notify>,
    // Shared latest snapshot so other components can read it
    latest_snapshot: Arc<RwLock<Option<MetricsSnapshot>>>,
}

impl AggregationWorker {
    /// Main run-loop: receive samples, periodically flush.
    async fn run(mut self) {
        let mut flush_timer = tokio::time::interval(self.flush_interval);
        flush_timer.tick().await; // first tick is immediate — skip it

        let mut last_flush = Instant::now();

        loop {
            tokio::select! {
                // ── Receive samples ─────────────────────────
                Some(sample) = self.rx.recv() => {
                    self.bucket.record(sample);
                }

                // ── Periodic flush ──────────────────────────
                _ = flush_timer.tick() => {
                    let now = Instant::now();
                    let snapshot = self.bucket.flush(now - last_flush);
                    last_flush = now;

                    Self::emit_snapshot(&snapshot);

                    // Store for external readers
                    *self.latest_snapshot.write().await = Some(snapshot);
                }

                // ── Graceful shutdown ───────────────────────
                _ = self.shutdown.notified() => {
                    println!("[worker] shutdown signal received, draining channel…");

                    // Drain remaining samples from the channel
                    while let Ok(sample) = self.rx.try_recv() {
                        self.bucket.record(sample);
                    }

                    // Final flush
                    let snapshot = self.bucket.flush(Instant::now() - last_flush);
                    Self::emit_snapshot(&snapshot);
                    *self.latest_snapshot.write().await = Some(snapshot);

                    println!("[worker] final flush complete, exiting.");
                    return;
                }
            }
        }
    }

    /// Simulate sending the snapshot somewhere (stdout, remote API, etc.)
    fn emit_snapshot(snapshot: &MetricsSnapshot) {
        println!("\n╔══════════════════════════════════════════════════╗");
        println!("║           METRICS FLUSH                          ║");
        println!("╠══════════════════════════════════════════════════╣");
        println!(
            "║  Total samples : {:<10}  Interval: {:>6.1}s  ║",
            snapshot.total_samples,
            snapshot.flush_duration.as_secs_f64()
        );
        println!("╠══════════════════════════════════════════════════╣");

        for (key, metric) in &snapshot.metrics {
            match metric {
                AggregatedMetric::Counter(c) => {
                    println!("║ COUNTER  {key:<20} sum={:<8.1} cnt={}", c.sum, c.count);
                }
                AggregatedMetric::Gauge(g) => {
                    println!(
                        "║ GAUGE    {key:<20} last={:<8.2} min={:<8.2} max={:<8.2}",
                        g.last, g.min, g.max
                    );
                }
                AggregatedMetric::Histogram(h) => {
                    let p50 = percentile(&h.values, 50.0);
                    let p95 = percentile(&h.values, 95.0);
                    let p99 = percentile(&h.values, 99.0);
                    let avg = if h.count > 0 { h.sum / h.count as f64 } else { 0.0 };
                    println!(
                        "║ HISTO    {key:<20} cnt={:<6} avg={:<8.2} p50={:<8.2} p95={:<8.2} p99={:<8.2}",
                        h.count, avg, p50, p95, p99
                    );
                }
            }
        }
        println!("╚══════════════════════════════════════════════════╝");
    }
}

/// Nearest-rank percentile on a sorted slice.
fn percentile(sorted: &[f64], pct: f64) -> f64 {
    if sorted.is_empty() {
        return 0.0;
    }
    let rank = (pct / 100.0 * sorted.len() as f64).ceil() as usize;
    sorted[rank.saturating_sub(1).min(sorted.len() - 1)]
}

// ─── Builder / Orchestrator ───────────────────────────────────

struct MetricsSystem {
    client: MetricsClient,
    shutdown: Arc<Notify>,
    worker_handle: JoinHandle<()>,
    latest_snapshot: Arc<RwLock<Option<MetricsSnapshot>>>,
}

impl MetricsSystem {
    /// Spawn the background worker and return a system handle.
    fn new(channel_capacity: usize, flush_interval: Duration) -> Self {
        let (tx, rx) = mpsc::channel(channel_capacity);
        let shutdown = Arc::new(Notify::new());
        let latest_snapshot = Arc::new(RwLock::new(None));

        let worker = AggregationWorker {
            rx,
            bucket: MetricsBucket::default(),
            flush_interval,
            shutdown: shutdown.clone(),
            latest_snapshot: latest_snapshot.clone(),
        };

        let worker_handle = tokio::spawn(worker.run());

        MetricsSystem {
            client: MetricsClient { tx },
            shutdown,
            worker_handle,
            latest_snapshot,
        }
    }

    /// Get a cloneable client for submitting metrics.
    fn client(&self) -> MetricsClient {
        self.client.clone()
    }

    /// Trigger graceful shutdown and wait for the worker to finish.
    async fn shutdown(self) {
        self.shutdown.notify_one();
        let _ = self.worker_handle.await;
    }
}

// ─── Example Application ──────────────────────────────────────

#[tokio::main]
async fn main() {
    println!("Starting metrics aggregation system…\n");

    // Flush every 3 seconds, buffer up to 10_000 samples
    let system = MetricsSystem::new(10_000, Duration::from_secs(3));
    let client = system.client();

    // Simulate several concurrent producers
    let mut producer_handles = Vec::new();

    // ── Producer 1: HTTP request counter ──────────────────
    {
        let c = client.clone();
        producer_handles.push(tokio::spawn(async move {
            for i in 0..50 {
                c.counter(
                    "http.requests",
                    1.0,
                    &[("method", "GET"), ("path", "/api/v1/users")],
                ).await;
                if i % 3 == 0 {
                    c.counter(
                        "http.requests",
                        1.0,
                        &[("method", "POST"), ("path", "/api/v1/orders")],
                    ).await;
                }
                tokio::time::sleep(Duration::from_millis(100)).await;
            }
        }));
    }

    // ── Producer 2: Response latency histogram ────────────
    {
        let c = client.clone();
        producer_handles.push(tokio::spawn(async move {
            use std::f64::consts::PI;
            for i in 0..80 {
                // Simulate variable latency
                let latency = 20.0 + 15.0 * (i as f64 * PI / 20.0).sin() + (i as f64 * 0.3);
                c.histogram(
                    "http.latency_ms",
                    latency,
                    &[("service", "api")],
                ).await;
                tokio::time::sleep(Duration::from_millis(70)).await;
            }
        }));
    }

    // ── Producer 3: System gauges ─────────────────────────
    {
        let c = client.clone();
        producer_handles.push(tokio::spawn(async move {
            for i in 0..20 {
                let cpu = 30.0 + (i as f64) * 1.5;
                let mem = 1024.0 + (i as f64) * 50.0;
                c.gauge("system.cpu_percent", cpu, &[("host", "web-01")]).await;
                c.gauge("system.memory_mb", mem, &[("host", "web-01")]).await;
                tokio::time::sleep(Duration::from_millis(300)).await;
            }
        }));
    }

    // Wait for all producers to finish
    for h in producer_handles {
        let _ = h.await;
    }

    // Read the latest snapshot from the shared state
    if let Some(snap) = system.latest_snapshot.read().await.as_ref() {
        println!("\n[main] Latest snapshot has {} metric keys", snap.metrics.len());
    }

    // Graceful shutdown (drains remaining samples and does a final flush)
    system.shutdown().await;

    println!("\nMetrics system shut down cleanly.");
}
