use std::collections::HashMap;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::time::SystemTime;
use thiserror::Error;
use walkdir::WalkDir;

// ---------------------------------------------------------------------------
// Error types
// ---------------------------------------------------------------------------

#[derive(Error, Debug)]
pub enum SyncError {
    #[error("IO error: {0}")]
    Io(#[from] io::Error),

    #[error("Source directory does not exist: {0}")]
    SourceNotFound(PathBuf),

    #[error("Walk error: {0}")]
    Walk(#[from] walkdir::Error),

    #[error("Failed to get relative path for {0}")]
    RelativePath(PathBuf),
}

pub type SyncResult<T> = Result<T, SyncError>;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub struct SyncConfig {
    /// Delete files in dest that are not in source
    pub delete_orphans: bool,
    /// Only sync files matching these extensions (empty = all)
    pub extensions: Vec<String>,
    /// Skip hidden files/directories (starting with '.')
    pub skip_hidden: bool,
    /// Perform a dry run – don't actually write anything
    pub dry_run: bool,
}

impl Default for SyncConfig {
    fn default() -> Self {
        Self {
            delete_orphans: false,
            extensions: Vec::new(),
            skip_hidden: true,
            dry_run: false,
        }
    }
}

// ---------------------------------------------------------------------------
// Sync action / report
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SyncAction {
    /// File exists only in source → copy to dest
    CopyNew(PathBuf),
    /// File exists in both but source is newer → overwrite in dest
    UpdateModified(PathBuf),
    /// File exists only in dest → delete from dest
    DeleteOrphan(PathBuf),
    /// File is the same in both → nothing to do
    Unchanged(PathBuf),
}

#[derive(Debug, Clone, Default)]
pub struct SyncReport {
    pub actions: Vec<SyncAction>,
}

impl SyncReport {
    pub fn copied(&self) -> Vec<&PathBuf> {
        self.actions
            .iter()
            .filter_map(|a| match a {
                SyncAction::CopyNew(p) => Some(p),
                _ => None,
            })
            .collect()
    }

    pub fn updated(&self) -> Vec<&PathBuf> {
        self.actions
            .iter()
            .filter_map(|a| match a {
                SyncAction::UpdateModified(p) => Some(p),
                _ => None,
            })
            .collect()
    }

    pub fn deleted(&self) -> Vec<&PathBuf> {
        self.actions
            .iter()
            .filter_map(|a| match a {
                SyncAction::DeleteOrphan(p) => Some(p),
                _ => None,
            })
            .collect()
    }

    pub fn unchanged(&self) -> Vec<&PathBuf> {
        self.actions
            .iter()
            .filter_map(|a| match a {
                SyncAction::Unchanged(p) => Some(p),
                _ => None,
            })
            .collect()
    }
}

// ---------------------------------------------------------------------------
// File metadata helper
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
struct FileMeta {
    size: u64,
    modified: SystemTime,
}

impl FileMeta {
    fn from_path(path: &Path) -> SyncResult<Self> {
        let meta = fs::metadata(path)?;
        Ok(Self {
            size: meta.len(),
            modified: meta.modified()?,
        })
    }

    /// Returns true when the *other* file is considered outdated compared to self.
    fn is_newer_than(&self, other: &FileMeta) -> bool {
        self.modified > other.modified || self.size != other.size
    }
}

// ---------------------------------------------------------------------------
// FileSync – the main synchronizer
// ---------------------------------------------------------------------------

pub struct FileSync {
    source: PathBuf,
    dest: PathBuf,
    config: SyncConfig,
}

impl FileSync {
    /// Create a new synchronizer.
    pub fn new(
        source: impl Into<PathBuf>,
        dest: impl Into<PathBuf>,
        config: SyncConfig,
    ) -> Self {
        Self {
            source: source.into(),
            dest: dest.into(),
            config,
        }
    }

    // -- public API ---------------------------------------------------------

    /// Plan what needs to happen (without touching the filesystem).
    pub fn plan(&self) -> SyncResult<SyncReport> {
        self.validate_source()?;

        let src_files = self.scan_dir(&self.source)?;
        let dst_files = self.scan_dir(&self.dest).unwrap_or_default();

        let mut report = SyncReport::default();

        // Check every source file against dest
        for (rel, _src_meta) in &src_files {
            let src_full = self.source.join(rel);
            let dst_full = self.dest.join(rel);

            if let Some(_dst_meta) = dst_files.get(rel) {
                let sm = FileMeta::from_path(&src_full)?;
                let dm = FileMeta::from_path(&dst_full)?;
                if sm.is_newer_than(&dm) {
                    report.actions.push(SyncAction::UpdateModified(rel.clone()));
                } else {
                    report.actions.push(SyncAction::Unchanged(rel.clone()));
                }
            } else {
                report.actions.push(SyncAction::CopyNew(rel.clone()));
            }
        }

        // Check for orphans in dest
        if self.config.delete_orphans {
            for (rel, _) in &dst_files {
                if !src_files.contains_key(rel) {
                    report.actions.push(SyncAction::DeleteOrphan(rel.clone()));
                }
            }
        }

        Ok(report)
    }

    /// Execute the sync – returns a report of everything that was done.
    pub fn sync(&self) -> SyncResult<SyncReport> {
        let report = self.plan()?;

        if self.config.dry_run {
            log::info!("[dry-run] Would perform {} actions", report.actions.len());
            return Ok(report);
        }

        for action in &report.actions {
            match action {
                SyncAction::CopyNew(rel) | SyncAction::UpdateModified(rel) => {
                    let src = self.source.join(rel);
                    let dst = self.dest.join(rel);
                    if let Some(parent) = dst.parent() {
                        fs::create_dir_all(parent)?;
                    }
                    fs::copy(&src, &dst)?;
                    log::info!("Copied: {}", rel.display());
                }
                SyncAction::DeleteOrphan(rel) => {
                    let dst = self.dest.join(rel);
                    if dst.is_file() {
                        fs::remove_file(&dst)?;
                        log::info!("Deleted orphan: {}", rel.display());
                    }
                }
                SyncAction::Unchanged(rel) => {
                    log::debug!("Unchanged: {}", rel.display());
                }
            }
        }

        Ok(report)
    }

    // -- helpers ------------------------------------------------------------

    fn validate_source(&self) -> SyncResult<()> {
        if !self.source.exists() {
            return Err(SyncError::SourceNotFound(self.source.clone()));
        }
        Ok(())
    }

    /// Recursively scan a directory and return map: relative_path → FileMeta.
    fn scan_dir(&self, base: &Path) -> SyncResult<HashMap<PathBuf, FileMeta>> {
        let mut map = HashMap::new();

        if !base.exists() {
            return Ok(map);
        }

        for entry in WalkDir::new(base).into_iter().filter_map(|e| e.ok()) {
            if !entry.file_type().is_file() {
                continue;
            }

            let path = entry.path();

            // Skip hidden
            if self.config.skip_hidden && self.is_hidden(path, base) {
                continue;
            }

            // Extension filter
            if !self.config.extensions.is_empty() {
                let ext = path
                    .extension()
                    .and_then(|e| e.to_str())
                    .unwrap_or("")
                    .to_lowercase();
                if !self.config.extensions.iter().any(|e| e.to_lowercase() == ext) {
                    continue;
                }
            }

            let rel = path
                .strip_prefix(base)
                .map_err(|_| SyncError::RelativePath(path.to_path_buf()))?
                .to_path_buf();

            let meta = FileMeta::from_path(path)?;
            map.insert(rel, meta);
        }

        Ok(map)
    }

    fn is_hidden(&self, path: &Path, base: &Path) -> bool {
        path.strip_prefix(base)
            .ok()
            .map(|rel| {
                rel.components().any(|c| {
                    c.as_os_str()
                        .to_str()
                        .map(|s| s.starts_with('.'))
                        .unwrap_or(false)
                })
            })
            .unwrap_or(false)
    }
}

