#[cfg(test)]
mod tests {
    use super::*;
    use std::thread;
    use std::time::Duration;
    use tempfile::TempDir;

    // -- helpers for tests --------------------------------------------------

    /// Create a file with given content inside `base/relative_path`.
    fn create_file(base: &Path, relative: &str, content: &str) {
        let full = base.join(relative);
        if let Some(parent) = full.parent() {
            fs::create_dir_all(parent).unwrap();
        }
        fs::write(&full, content).unwrap();
    }

    /// Read a file to string.
    fn read_file(base: &Path, relative: &str) -> String {
        fs::read_to_string(base.join(relative)).unwrap()
    }

    fn file_exists(base: &Path, relative: &str) -> bool {
        base.join(relative).exists()
    }

    fn default_syncer(src: &Path, dst: &Path) -> FileSync {
        FileSync::new(src, dst, SyncConfig::default())
    }

    // -- tests --------------------------------------------------------------

    #[test]
    fn test_copy_new_files() {
        let src_dir = TempDir::new().unwrap();
        let dst_dir = TempDir::new().unwrap();

        create_file(src_dir.path(), "hello.txt", "Hello World");
        create_file(src_dir.path(), "sub/nested.txt", "Nested!");

        let syncer = default_syncer(src_dir.path(), dst_dir.path());
        let report = syncer.sync().unwrap();

        // Both files should be copied
        assert_eq!(report.copied().len(), 2);
        assert_eq!(read_file(dst_dir.path(), "hello.txt"), "Hello World");
        assert_eq!(read_file(dst_dir.path(), "sub/nested.txt"), "Nested!");
    }

    #[test]
    fn test_update_modified_file() {
        let src_dir = TempDir::new().unwrap();
        let dst_dir = TempDir::new().unwrap();

        // Initial sync
        create_file(src_dir.path(), "data.txt", "version 1");
        let syncer = default_syncer(src_dir.path(), dst_dir.path());
        syncer.sync().unwrap();
        assert_eq!(read_file(dst_dir.path(), "data.txt"), "version 1");

        // Modify source (small sleep so mtime differs)
        thread::sleep(Duration::from_millis(50));
        create_file(src_dir.path(), "data.txt", "version 2 – updated");

        let report = syncer.sync().unwrap();
        assert_eq!(report.updated().len(), 1);
        assert_eq!(
            read_file(dst_dir.path(), "data.txt"),
            "version 2 – updated"
        );
    }

    #[test]
    fn test_unchanged_files_skipped() {
        let src_dir = TempDir::new().unwrap();
        let dst_dir = TempDir::new().unwrap();

        create_file(src_dir.path(), "keep.txt", "same");
        let syncer = default_syncer(src_dir.path(), dst_dir.path());

        // First sync: copy
        let r1 = syncer.sync().unwrap();
        assert_eq!(r1.copied().len(), 1);

        // Second sync: unchanged
        let r2 = syncer.sync().unwrap();
        assert_eq!(r2.unchanged().len(), 1);
        assert_eq!(r2.copied().len(), 0);
    }

    #[test]
    fn test_delete_orphans() {
        let src_dir = TempDir::new().unwrap();
        let dst_dir = TempDir::new().unwrap();

        create_file(src_dir.path(), "a.txt", "a");
        create_file(dst_dir.path(), "a.txt", "a");
        create_file(dst_dir.path(), "orphan.txt", "should be deleted");

        let config = SyncConfig {
            delete_orphans: true,
            ..SyncConfig::default()
        };
        let syncer = FileSync::new(src_dir.path(), dst_dir.path(), config);
        let report = syncer.sync().unwrap();

        assert_eq!(report.deleted().len(), 1);
        assert!(!file_exists(dst_dir.path(), "orphan.txt"));
        assert!(file_exists(dst_dir.path(), "a.txt"));
    }

    #[test]
    fn test_no_delete_without_flag() {
        let src_dir = TempDir::new().unwrap();
        let dst_dir = TempDir::new().unwrap();

        create_file(src_dir.path(), "a.txt", "a");
        create_file(dst_dir.path(), "a.txt", "a");
        create_file(dst_dir.path(), "extra.txt", "extra");

        let syncer = default_syncer(src_dir.path(), dst_dir.path());
        let report = syncer.sync().unwrap();

