```javascript
// ✅ FIXED VERSION - Chat Moderation Scheduler
class ModerationScheduler {
  constructor(config) {
    this.queue = [];
    this.moderators = config.moderators || [];
    this.maxRetries = config.maxRetries || 3;
    this.interval = config.interval || 5000;
    this.batchSize = config.batchSize || 10;           // FIX 6: Batch limit
    this.apiTimeout = config.apiTimeout || 10000;       // FIX 11: Configurable timeout
    this.running = false;
    this.processedMessages = new Map();                 // FIX 1: Use Map for easier cleanup
    this.maxCacheSize = config.maxCacheSize || 10000;
    this.timer = null;
    this.processing = false;                            // Guard against overlapping runs
  }

  // ─── Start the scheduler ────────────────────────────────
  start() {
    if (this.running) {
      console.warn("Scheduler is already running");
      return;
    }

    this.running = true;
    this.timer = setInterval(() => {          // FIX 2: Arrow function preserves `this`
      this.processQueue();
    }, this.interval);
    console.log("Scheduler started");
  }

  // ─── Stop the scheduler ────────────────────────────────
  stop() {
    this.running = false;
    if (this.timer) {
      clearInterval(this.timer);              // FIX 3: Clear the interval timer
      this.timer = null;
    }
    console.log("Scheduler stopped");
  }

  // ─── Add message to moderation queue ───────────────────
  addMessage(message) {
    // FIX 4: Validate message structure before adding
    if (!message || !message.id || !message.content || !message.userId) {
      console.error("Invalid message structure:", message);
      throw new Error("Message must have id, content, and userId");
    }

    // Prevent duplicates
    if (this.queue.some(m => m.id === message.id) ||
        this.processedMessages.has(message.id)) {
      console.warn(`Message ${message.id} already queued or processed`);
      return;
    }

    this.queue.push({
      id: message.id,
      content: message.content,
      userId: message.userId,
      timestamp: message.timestamp || Date.now(),
      retries: 0,
      status: "pending",
    });
  }

  // ─── Process the moderation queue ──────────────────────
  async processQueue() {
    // FIX 5: Strict equality + guard against overlapping runs
    if (!this.running || this.queue.length === 0 || this.processing) {
      return;
    }

    this.processing = true;

    try {
      // FIX 6: Process in controlled batches
      const pendingMessages = this.queue
        .filter(m => m.status === "pending")
        .slice(0, this.batchSize);

      // FIX 7: Process sequentially with proper await & error handling
      for (const message of pendingMessages) {
        try {
          await this.moderateMessage(message);
        } catch (error) {
          console.error(`Failed to moderate message ${message.id}:`, error);
          this.handleModerationError(message, error);
        }
      }

      // Clean completed messages from the queue
      this.cleanupQueue();
    } finally {
      this.processing = false;
    }
  }

  // ─── Moderate a single message ─────────────────────────
  async moderateMessage(message) {
    message.status = "processing";

    // FIX 8: Wrap API call in try-catch
    try {
      const result = await this.callModerationAPI(message);

      if (result.flagged) {
        this.handleFlaggedMessage(message, result);
      }

      // FIX 9: Mark completed, move to cache, remove from queue
      message.status = "completed";
      message.completedAt = Date.now();
      this.processedMessages.set(message.id, { ...message, result });

      // FIX 1: Prune old entries to prevent memory leak
      this.pruneProcessedCache();

    } catch (error) {
      message.status = "failed";
      throw error;                  // Re-throw for processQueue to handle
    }
  }

  // ─── API call with timeout and headers ─────────────────
  async callModerationAPI(message) {
    // FIX 11: AbortController for request timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.apiTimeout);

    try {
      const response = await fetch("/api/moderate", {
        method: "POST",
        // FIX 10: Include proper headers
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json",
        },
        body: JSON.stringify({ content: message.content }),
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`API error: ${response.status} ${response.statusText}`);
      }

      return await response.json();

    } catch (error) {
      if (error.name === "AbortError") {
        throw new Error(`Moderation API timed out after ${this.apiTimeout}ms`);
      }
      throw error;
    } finally {
      clearTimeout(timeoutId);
    }
  }

  // ─── Handle flagged messages ───────────────────────────
  handleFlaggedMessage(message, result) {
    const notification = {
      type: "moderation_alert",
      messageId: message.id,
      reason: result.reason,
      severity: result.severity,
      // FIX 12: Use current time for the alert timestamp
      timestamp: Date.now(),
      originalTimestamp: message.timestamp,
    };

    // FIX 13: Route to moderators by severity level
    const targetModerators = this.getModeratorsBySeverity(result.severity);
    targetModerators.forEach(mod => this.notifyModerator(mod, notification));
  }

  // ─── Route alerts by severity ──────────────────────────
  getModeratorsBySeverity(severity) {
    switch (severity) {
      case "critical":
        return this.moderators.filter(m => m.role === "senior" || m.role === "admin");
      case "high":
        return this.moderators.filter(m => m.role !== "junior");
      default:
        return this.moderators.length > 0 ? [this.moderators[0]] : [];
    }
  }

  // ─── Retry failed messages with backoff ────────────────
  handleModerationError(message, error) {
    // FIX 14: Respect maxRetries to prevent infinite loops
    if (message.retries < this.maxRetries) {
      message.retries++;
      message.status = "pending";
      message.lastError = error.message;
      message.nextRetryAt = Date.now() + (1000 * Math.pow(2, message.retries)); // Exponential backoff
      console.warn(
        `Retrying message ${message.id} (${message.retries}/${this.maxRetries})`
      );
    } else {
      message.status = "failed_permanent";
      console.error(
        `Message ${message.id} permanently failed after ${this.maxRetries} retries`
      );
      // Notify admins of permanent failure
      this.moderators
        .filter(m => m.role === "admin")
        .forEach(admin => this.notifyModerator(admin, {
          type: "moderation_failure",
          messageId: message.id,
          error: error.message,
          timestamp: Date.now(),
        }));
    }
  }

  // ─── Queue cleanup ─────────────────────────────────────
  cleanupQueue() {
    this.queue = this.queue.filter(
      m => m.status !== "completed" && m.status !== "failed_permanent"
    );
  }

  // ─── Prevent memory leak in processed cache ────────────
  pruneProcessedCache() {
    if (this.processedMessages.size > this.maxCacheSize) {
      const entriesToDelete = this.processedMessages.size - this.maxCacheSize;
      const iterator = this.processedMessages.keys();
      for (let i = 0; i < entriesToDelete; i++) {
        this.processedMessages.delete(iterator.next().value);
      }
    }
  }

  notifyModerator(moderator, notification) {
    console.log(`Notifying ${moderator.name}:`, notification);
  }

  // ─── Get accurate scheduler stats ──────────────────────
  getStats() {
    // FIX 15: Count by actual status
    const statusCounts = this.queue.reduce((acc, m) => {
      acc[m.status] = (acc[m.status] || 0) + 1;
      return acc;
    }, {});

    return {
      queueLength: this.queue.length,
      pending: statusCounts["pending"] || 0,
      processing: statusCounts["processing"] || 0,
      failed: statusCounts["failed"] || 0,
      failedPermanent: statusCounts["failed_permanent"] || 0,
      processed: this.processedMessages.size,
      isRunning: this.running,
    };
  }

  // ─── Graceful shutdown ────────────────────────────────
  async shutdown() {
    console.log("Gracefully shutting down...");
    this.stop();

    // Wait for current processing to finish
    while (this.processing) {
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    console.log("Scheduler shut down. Final stats:", this.getStats());
  }
}
