use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fmt;
use uuid::Uuid;

/// Log severity levels following syslog conventions.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "UPPERCASE")]
pub enum LogLevel {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
    Fatal,
}

impl LogLevel {
    pub fn from_str_loose(s: &str) -> Option<Self> {
        match s.to_uppercase().as_str() {
            "TRACE" | "TRC" => Some(Self::Trace),
            "DEBUG" | "DBG" => Some(Self::Debug),
            "INFO" | "INF" => Some(Self::Info),
            "WARN" | "WARNING" | "WRN" => Some(Self::Warn),
            "ERROR" | "ERR" => Some(Self::Error),
            "FATAL" | "CRITICAL" | "CRIT" | "FTL" => Some(Self::Fatal),
            _ => None,
        }
    }
}

impl fmt::Display for LogLevel {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Trace => write!(f, "TRACE"),
            Self::Debug => write!(f, "DEBUG"),
            Self::Info => write!(f, "INFO"),
            Self::Warn => write!(f, "WARN"),
            Self::Error => write!(f, "ERROR"),
            Self::Fatal => write!(f, "FATAL"),
        }
    }
}

/// A structured log entry with metadata and key-value fields.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LogEntry {
    pub id: String,
    pub timestamp: DateTime<Utc>,
    pub level: LogLevel,
    pub message: String,
    pub source: String,
    pub fields: HashMap<String, String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub raw: Option<String>,
    pub ingested_at: DateTime<Utc>,
}

impl LogEntry {
    pub fn new(level: LogLevel, message: impl Into<String>, source: impl Into<String>) -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4().to_string(),
            timestamp: now,
            level,
            message: message.into(),
            source: source.into(),
            fields: HashMap::new(),
            raw: None,
            ingested_at: now,
        }
    }

    pub fn with_timestamp(mut self, ts: DateTime<Utc>) -> Self {
        self.timestamp = ts;
        self
    }

    pub fn with_field(mut self, key: impl Into<String>, value: impl Into<String>) -> Self {
        self.fields.insert(key.into(), value.into());
        self
    }

    pub fn with_fields(mut self, fields: HashMap<String, String>) -> Self {
        self.fields.extend(fields);
        self
    }

    pub fn with_raw(mut self, raw: impl Into<String>) -> Self {
        self.raw = Some(raw.into());
        self
    }

    /// Byte size estimate for memory accounting.
    pub fn estimated_size(&self) -> usize {
        self.id.len()
            + self.message.len()
            + self.source.len()
            + self.raw.as_ref().map_or(0, |r| r.len())
            + self
                .fields
                .iter()
                .map(|(k, v)| k.len() + v.len())
                .sum::<usize>()
            + 64 // fixed overhead for timestamps, enum, etc.
    }
}

impl fmt::Display for LogEntry {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "[{}] {} [{}] {}",
            self.timestamp.format("%Y-%m-%dT%H:%M:%S%.3fZ"),
            self.level,
            self.source,
            self.message
        )
    }
}

/// Builder for constructing LogEntry instances with validation.
pub struct LogEntryBuilder {
    level: Option<LogLevel>,
    message: Option<String>,
    source: Option<String>,
    timestamp: Option<DateTime<Utc>>,
    fields: HashMap<String, String>,
    raw: Option<String>,
}

impl LogEntryBuilder {
    pub fn new() -> Self {
        Self {
            level: None,
            message: None,
            source: None,
            timestamp: None,
            fields: HashMap::new(),
            raw: None,
        }
    }

    pub fn level(mut self, level: LogLevel) -> Self {
        self.level = Some(level);
        self
    }

    pub fn message(mut self, msg: impl Into<String>) -> Self {
        self.message = Some(msg.into());
        self
    }

    pub fn source(mut self, src: impl Into<String>) -> Self {
        self.source = Some(src.into());
        self
    }

    pub fn timestamp(mut self, ts: DateTime<Utc>) -> Self {
        self.timestamp = Some(ts);
        self
    }

    pub fn field(mut self, key: impl Into<String>, value: impl Into<String>) -> Self {
        self.fields.insert(key.into(), value.into());
        self
    }

    pub fn raw(mut self, raw: impl Into<String>) -> Self {
        self.raw = Some(raw.into());
        self
    }

    pub fn build(self) -> crate::error::Result<LogEntry> {
        let level = self
            .level
            .ok_or_else(|| crate::error::IngestionError::ParseError("missing level".into()))?;
        let message = self
            .message
            .ok_or_else(|| crate::error::IngestionError::ParseError("missing message".into()))?;
        let source = self.source.unwrap_or_else(|| "unknown".into());

        let mut entry = LogEntry::new(level, message, source);
        if let Some(ts) = self.timestamp {
            entry = entry.with_timestamp(ts);
        }
        if !self.fields.is_empty() {
            entry = entry.with_fields(self.fields);
        }
        if let Some(raw) = self.raw {
            entry = entry.with_raw(raw);
        }
        Ok(entry)
    }
}

impl Default for LogEntryBuilder {
    fn default() -> Self {
        Self::new()
    }
}
