# Background Worker for Event Processing in JavaScript

Here's a comprehensive example of a background event processing system using a worker pattern with queue management, retries, and concurrency control.

## Project Structure

```
event-worker/
├── EventQueue.js
├── EventWorker.js
├── EventProcessor.js
├── handlers/
│   └── eventHandlers.js
└── index.js
```

## Core Components

### EventQueue.js — Priority Queue for Events

```javascript
class EventQueue {
  constructor(maxSize = 1000) {
    this.queues = {
      high: [],
      normal: [],
      low: [],
    };
    this.maxSize = maxSize;
    this.totalSize = 0;
    this.waiters = []; // Promises waiting for new events
  }

  /**
   * Add an event to the queue with a given priority.
   * Resolves any workers waiting for events.
   */
  enqueue(event, priority = "normal") {
    if (this.totalSize >= this.maxSize) {
      throw new Error(`Queue is full (max: ${this.maxSize})`);
    }

    const entry = {
      id: crypto.randomUUID?.() ?? `${Date.now()}-${Math.random()}`,
      event,
      priority,
      attempts: 0,
      createdAt: Date.now(),
    };

    this.queues[priority].push(entry);
    this.totalSize++;

    // Wake up any worker waiting for events
    if (this.waiters.length > 0) {
      const resolve = this.waiters.shift();
      resolve();
    }

    return entry.id;
  }

  /**
   * Dequeue the next highest-priority event.
   */
  dequeue() {
    for (const priority of ["high", "normal", "low"]) {
      if (this.queues[priority].length > 0) {
        this.totalSize--;
        return this.queues[priority].shift();
      }
    }
    return null;
  }

  /**
   * Re-enqueue a failed event for retry.
   */
  requeue(entry) {
    entry.attempts++;
    entry.lastAttempt = Date.now();
    this.queues[entry.priority].unshift(entry);
    this.totalSize++;
  }

  /**
   * Returns a promise that resolves when a new event arrives.
   */
  waitForEvent() {
    return new Promise((resolve) => {
      this.waiters.push(resolve);
    });
  }

  get size() {
    return this.totalSize;
  }

  get isEmpty() {
    return this.totalSize === 0;
  }

  getStats() {
    return {
      total: this.totalSize,
      high: this.queues.high.length,
      normal: this.queues.normal.length,
      low: this.queues.low.length,
      waitingWorkers: this.waiters.length,
    };
  }
}

module.exports = EventQueue;
```

### EventWorker.js — Worker with Retry & Backoff

```javascript
const { EventEmitter } = require("events");

class EventWorker extends EventEmitter {
  constructor(id, processor, options = {}) {
    super();
    this.id = id;
    this.processor = processor;
    this.maxRetries = options.maxRetries ?? 3;
    this.retryDelayMs = options.retryDelayMs ?? 1000;
    this.backoffMultiplier = options.backoffMultiplier ?? 2;
    this.processingTimeoutMs = options.processingTimeoutMs ?? 30000;

    this.running = false;
    this.currentEntry = null;
    this.stats = { processed: 0, failed: 0, retried: 0 };
  }

  /**
   * Main worker loop — continuously pulls from the queue.
   */
  async start(queue) {
    this.running = true;
    this.emit("started", { workerId: this.id });

    while (this.running) {
      const entry = queue.dequeue();

      if (!entry) {
        // No events — wait until one arrives or shutdown
        await Promise.race([
          queue.waitForEvent(),
          this._sleepUntilStopped(500),
        ]);
        continue;
      }

      await this._processEntry(entry, queue);
    }

    this.emit("stopped", { workerId: this.id, stats: this.stats });
  }

  /**
   * Process a single event entry with timeout and retry logic.
   */
  async _processEntry(entry, queue) {
    this.currentEntry = entry;

    const startTime = Date.now();
    this.emit("processing", {
      workerId: this.id,
      eventId: entry.id,
      eventType: entry.event.type,
      attempt: entry.attempts + 1,
    });

    try {
      // Wrap processing in a timeout
      await this._withTimeout(
        this.processor.process(entry.event),
        this.processingTimeoutMs
      );

      const duration = Date.now() - startTime;
      this.stats.processed++;

      this.emit("completed", {
        workerId: this.id,
        eventId: entry.id,
        eventType: entry.event.type,
        duration,
      });
    } catch (error) {
      const duration = Date.now() - startTime;

      if (entry.attempts < this.maxRetries) {
        // Retry with exponential backoff
        this.stats.retried++;
        const delay =
          this.retryDelayMs *
          Math.pow(this.backoffMultiplier, entry.attempts);

        this.emit("retrying", {
          workerId: this.id,
          eventId: entry.id,
          attempt: entry.attempts + 1,
          maxRetries: this.maxRetries,
          nextRetryIn: delay,
          error: error.message,
        });

        await this._sleep(delay);
        queue.requeue(entry);
      } else {
        // Exhausted retries — move to dead letter
        this.stats.failed++;
        this.emit("failed", {
          workerId: this.id,
          eventId: entry.id,
          eventType: entry.event.type,
          attempts: entry.attempts + 1,
          duration,
          error: error.message,
        });
      }
    } finally {
      this.currentEntry = null;
    }
  }

  stop() {
    this.running = false;
  }

  _withTimeout(promise, ms) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(
        () => reject(new Error(`Processing timed out after ${ms}ms`)),
        ms
      );
      promise
        .then(resolve)
        .catch(reject)
        .finally(() => clearTimeout(timer));
    });
  }

  _sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  _sleepUntilStopped(ms) {
    return new Promise((resolve) => {
      const timer = setTimeout(resolve, ms);
      // Allow early exit if stopped
      const check = setInterval(() => {
        if (!this.running) {
          clearTimeout(timer);
          clearInterval(check);
          resolve();
        }
      }, 50);
    });
  }
}

module.exports = EventWorker;
```

