### EventProcessor.js — Orchestrator

```javascript
const { EventEmitter } = require("events");
const EventQueue = require("./EventQueue");
const EventWorker = require("./EventWorker");
const handlers = require("./handlers/eventHandlers");

class EventProcessor extends EventEmitter {
  constructor(options = {}) {
    super();
    this.concurrency = options.concurrency ?? 3;
    this.queue = new EventQueue(options.maxQueueSize);
    this.workers = [];
    this.deadLetterQueue = [];

    this.workerOptions = {
      maxRetries: options.maxRetries ?? 3,
      retryDelayMs: options.retryDelayMs ?? 500,
      backoffMultiplier: options.backoffMultiplier ?? 2,
      processingTimeoutMs: options.processingTimeoutMs ?? 10000,
    };
  }

  /**
   * Spin up worker pool and begin processing.
   */
  start() {
    console.log(
      `Starting ${this.concurrency} worker(s)...\n`
    );

    for (let i = 0; i < this.concurrency; i++) {
      const worker = new EventWorker(
        `worker-${i + 1}`,
        this,               // processor with .process() method
        this.workerOptions
      );

      this._attachWorkerListeners(worker);
      worker.start(this.queue);
      this.workers.push(worker);
    }
  }

  /**
   * Gracefully shut down all workers.
   */
  async shutdown() {
    console.log("\nShutting down workers...");
    this.workers.forEach((w) => w.stop());

    // Wait until current items finish (with a hard timeout)
    await new Promise((resolve) => setTimeout(resolve, 2000));

    console.log("\n=== Final Report ===");
    this.workers.forEach((w) => {
      console.log(`  ${w.id}: ${JSON.stringify(w.stats)}`);
    });
    console.log(`  Dead letters: ${this.deadLetterQueue.length}`);
    console.log(`  Remaining in queue: ${this.queue.size}`);
  }

  /**
   * Dispatch an event into the processing pipeline.
   */
  dispatch(type, payload, priority = "normal") {
    const event = { type, payload, timestamp: Date.now() };
    const id = this.queue.enqueue(event, priority);
    this.emit("dispatched", { id, type, priority });
    return id;
  }

  /**
   * Called by workers — routes to the correct handler.
   */
  async process(event) {
    const handler = handlers[event.type];

    if (!handler) {
      throw new Error(`No handler registered for "${event.type}"`);
    }

    return handler(event.payload);
  }

  /**
   * Forward worker lifecycle events to the processor.
   */
  _attachWorkerListeners(worker) {
    worker.on("processing", ({ workerId, eventType, attempt }) => {
      console.log(
        `[${workerId}] Processing "${eventType}" (attempt ${attempt})`
      );
    });

    worker.on("completed", ({ workerId, eventId, duration }) => {
      console.log(
        `[${workerId}] ✓ Completed ${eventId} in ${duration}ms`
      );
    });

    worker.on("retrying", ({ workerId, eventId, attempt, maxRetries, error }) => {
      console.log(
        `[${workerId}] ⟳ Retry ${attempt}/${maxRetries} for ${eventId}: ${error}`
      );
    });

    worker.on("failed", ({ workerId, eventId, eventType, error }) => {
      console.log(
        `[${workerId}] ✗ Failed ${eventId} (${eventType}): ${error}`
      );
      this.deadLetterQueue.push({ eventId, eventType, error });
    });
  }
}

module.exports = EventProcessor;
```

