package main

import (
	"database/sql"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

type Store struct {
	db *sql.DB
}

func NewStore(dbPath string) (*Store, error) {
	dir := filepath.Dir(dbPath)
	if err := os.MkdirAll(dir, 0700); err != nil {
		return nil, fmt.Errorf("creating db directory: %w", err)
	}

	db, err := sql.Open("sqlite3", dbPath+"?_journal_mode=WAL&_busy_timeout=5000")
	if err != nil {
		return nil, fmt.Errorf("opening database: %w", err)
	}

	s := &Store{db: db}
	if err := s.migrate(); err != nil {
		db.Close()
		return nil, fmt.Errorf("running migrations: %w", err)
	}
	return s, nil
}

func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) migrate() error {
	schema := `
	CREATE TABLE IF NOT EXISTS audit_events (
		id             INTEGER PRIMARY KEY AUTOINCREMENT,
		timestamp      TEXT    NOT NULL,
		actor          TEXT    NOT NULL,
		action         TEXT    NOT NULL,
		resource       TEXT    NOT NULL DEFAULT '',
		resource_id    TEXT    NOT NULL DEFAULT '',
		outcome        TEXT    NOT NULL DEFAULT 'success',
		severity       TEXT    NOT NULL DEFAULT 'info',
		source_ip      TEXT    NOT NULL DEFAULT '',
		session_id     TEXT    NOT NULL DEFAULT '',
		correlation_id TEXT    NOT NULL DEFAULT '',
		metadata       TEXT    NOT NULL DEFAULT '{}',
		hash           TEXT    NOT NULL,
		prev_hash      TEXT    NOT NULL
	);

	CREATE INDEX IF NOT EXISTS idx_events_timestamp ON audit_events(timestamp);
	CREATE INDEX IF NOT EXISTS idx_events_actor     ON audit_events(actor);
	CREATE INDEX IF NOT EXISTS idx_events_action    ON audit_events(action);
	CREATE INDEX IF NOT EXISTS idx_events_outcome   ON audit_events(outcome);
	CREATE INDEX IF NOT EXISTS idx_events_severity  ON audit_events(severity);
	CREATE INDEX IF NOT EXISTS idx_events_session   ON audit_events(session_id);
	CREATE INDEX IF NOT EXISTS idx_events_corr      ON audit_events(correlation_id);
	`
	_, err := s.db.Exec(schema)
	return err
}

// LastHash returns the hash of the most recent event, or the genesis hash.
func (s *Store) LastHash() (string, error) {
	var hash string
	err := s.db.QueryRow(
		`SELECT hash FROM audit_events ORDER BY id DESC LIMIT 1`,
	).Scan(&hash)

	if err == sql.ErrNoRows {
		return genesisHash, nil
	}
	return hash, err
}

// Insert adds an event, computing its hash and chaining to the previous one.
func (s *Store) Insert(e *AuditEvent) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// Get previous hash inside the transaction for consistency.
	var prevHash string
	err = tx.QueryRow(`SELECT hash FROM audit_events ORDER BY id DESC LIMIT 1`).Scan(&prevHash)
	if err == sql.ErrNoRows {
		prevHash = genesisHash
	} else if err != nil {
		return err
	}

	e.PrevHash = prevHash
	e.Hash = ComputeHash(e, prevHash)

	_, err = tx.Exec(`
		INSERT INTO audit_events
			(timestamp, actor, action, resource, resource_id, outcome, severity,
			 source_ip, session_id, correlation_id, metadata, hash, prev_hash)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		e.Timestamp.UTC().Format(time.RFC3339Nano),
		e.Actor, e.Action, e.Resource, e.ResourceID,
		string(e.Outcome), string(e.Severity),
		e.SourceIP, e.SessionID, e.CorrelationID,
		e.MetadataJSON(), e.Hash, e.PrevHash,
	)
	if err != nil {
		return err
	}

	return tx.Commit()
}

// Search returns events matching the filter.
func (s *Store) Search(f SearchFilter) ([]AuditEvent, error) {
	var conditions []string
	var args []interface{}

	if f.Actor != "" {
		conditions = append(conditions, "actor LIKE ?")
		args = append(args, wildcardToSQL(f.Actor))
	}
	if f.Action != "" {
		conditions = append(conditions, "action LIKE ?")
		args = append(args, wildcardToSQL(f.Action))
	}
	if f.Resource != "" {
		conditions = append(conditions, "resource LIKE ?")
		args = append(args, wildcardToSQL(f.Resource))
	}
	if f.Outcome != "" {
		conditions = append(conditions, "outcome = ?")
		args = append(args, f.Outcome)
	}
	if f.Severity != "" {
		conditions = append(conditions, "severity = ?")
		args = append(args, f.Severity)
	}
	if f.SourceIP != "" {
		conditions = append(conditions, "source_ip = ?")
		args = append(args, f.SourceIP)
	}
	if f.SessionID != "" {
		conditions = append(conditions, "session_id = ?")
		args = append(args, f.SessionID)
	}
	if f.CorrelationID != "" {
		conditions = append(conditions, "correlation_id = ?")
		args = append(args, f.CorrelationID)
	}
	if !f.From.IsZero() {
		conditions = append(conditions, "timestamp >= ?")
		args = append(args, f.From.UTC().Format(time.RFC3339Nano))
	}
	if !f.To.IsZero() {
		conditions = append(conditions, "timestamp <= ?")
		args = append(args, f.To.UTC().Format(time.RFC3339Nano))
	}

	query := `SELECT id, timestamp, actor, action, resource, resource_id,
	                 outcome, severity, source_ip, session_id, correlation_id,
	                 metadata, hash, prev_hash
	          FROM audit_events`

	if len(conditions) > 0 {
		query += " WHERE " + strings.Join(conditions, " AND ")
	}
	query += " ORDER BY id ASC"

	if f.Limit > 0 {
		query += fmt.Sprintf(" LIMIT %d", f.Limit)
	}
	if f.Offset > 0 {
		query += fmt.Sprintf(" OFFSET %d", f.Offset)
	}

	return s.queryEvents(query, args...)
}

// AllEventsOrdered returns every event in insertion order (for verification).
func (s *Store) AllEventsOrdered() ([]AuditEvent, error) {
	return s.queryEvents(`
		SELECT id, timestamp, actor, action, resource, resource_id,
		       outcome, severity, source_ip, session_id, correlation_id,
		       metadata, hash, prev_hash
		FROM audit_events ORDER BY id ASC`)
}

// EventsSinceID returns events with id > afterID (for tail).
func (s *Store) EventsSinceID(afterID int64) ([]AuditEvent, error) {
	return s.queryEvents(`
		SELECT id, timestamp, actor, action, resource, resource_id,
		       outcome, severity, source_ip, session_id, correlation_id,
		       metadata, hash, prev_hash
		FROM audit_events WHERE id > ? ORDER BY id ASC`, afterID)
}

// PurgeOlderThan deletes events before the given time. Returns count deleted.
func (s *Store) PurgeOlderThan(before time.Time) (int64, error) {
	res, err := s.db.Exec(
		`DELETE FROM audit_events WHERE timestamp < ?`,
		before.UTC().Format(time.RFC3339Nano),
	)
	if err != nil {
		return 0, err
	}
	return res.RowsAffected()
}

// CountOlderThan returns how many events exist before the given time.
func (s *Store) CountOlderThan(before time.Time) (int64, error) {
	var n int64
	err := s.db.QueryRow(
		`SELECT COUNT(*) FROM audit_events WHERE timestamp < ?`,
		before.UTC().Format(time.RFC3339Nano),
	).Scan(&n)
	return n, err
}

// Stats returns aggregate statistics.
func (s *Store) Stats(from, to time.Time) (*AuditStats, error) {
	st := &AuditStats{
		ByOutcome:  make(map[string]int64),
		BySeverity: make(map[string]int64),
	}

	where, args := timeRangeClause(from, to)

	// Total + time range
	var firstTS, lastTS sql.NullString
	err := s.db.QueryRow(
		`SELECT COUNT(*), MIN(timestamp), MAX(timestamp) FROM audit_events`+where, args...,
	).Scan(&st.TotalEvents, &firstTS, &lastTS)
	if err != nil {
		return nil, err
	}
	if firstTS.Valid {
		st.FirstEvent, _ = time.Parse(time.RFC3339Nano, firstTS.String)
	}
	if lastTS.Valid {
		st.LastEvent, _ = time.Parse(time.RFC3339Nano, lastTS.String)
	}

	// By outcome
	rows, err := s.db.Query(`SELECT outcome, COUNT(*) FROM audit_events`+where+` GROUP BY outcome`, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var k string
		var v int64
		if err := rows.Scan(&k, &v); err != nil {
			return nil, err
		}
		st.ByOutcome[k] = v
	}

	// By severity
	rows, err = s.db.Query(`SELECT severity, COUNT(*) FROM audit_events`+where+` GROUP BY severity`, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var k string
		var v int64
		if err := rows.Scan(&k, &v); err != nil {
			return nil, err
		}
		st.BySeverity[k] = v
	}

	// Top actors
	rows, err = s.db.Query(
		`SELECT actor, COUNT(*) as c FROM audit_events`+where+` GROUP BY actor ORDER BY c DESC LIMIT 10`, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var kv KV
		if err := rows.Scan(&kv.Key, &kv.Count); err != nil {
			return nil, err
		}
		st.TopActors = append(st.TopActors, kv)
	}

	// Top actions
	rows, err = s.db.Query(
		`SELECT action, COUNT(*) as c FROM audit_events`+where+` GROUP BY action ORDER BY c DESC LIMIT 10`, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var kv KV
		if err := rows.Scan(&kv.Key, &kv.Count); err != nil {
			return nil, err
		}
		st.TopActions = append(st.TopActions, kv)
	}

	return st, nil
}

// --- helpers ---

func (s *Store) queryEvents(query string, args ...interface{}) ([]AuditEvent, error) {
	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var events []AuditEvent
	for rows.Next() {
		var e AuditEvent
		var ts, metaRaw string
		err := rows.Scan(
			&e.ID, &ts, &e.Actor, &e.Action, &e.Resource, &e.ResourceID,
			&e.Outcome, &e.Severity, &e.SourceIP, &e.SessionID,
			&e.CorrelationID, &metaRaw, &e.Hash, &e.PrevHash,
		)
		if err != nil {
			return nil, err
		}
		e.Timestamp, _ = time.Parse(time.RFC3339Nano, ts)
		e.Metadata = ParseMetadata(metaRaw)
		events = append(events, e)
	}
	return events, rows.Err()
}

func wildcardToSQL(pattern string) string {
	// Convert user wildcards (* and ?) to SQL LIKE (% and _).
	r := strings.NewReplacer("*", "%", "?", "_")
	return r.Replace(pattern)
}

func timeRangeClause(from, to time.Time) (string, []interface{}) {
	var parts []string
	var args []interface{}
	if !from.IsZero() {
		parts = append(parts, "timestamp >= ?")
		args = append(args, from.UTC().Format(time.RFC3339Nano))
	}
	if !to.IsZero() {
		parts = append(parts, "timestamp <= ?")
		args = append(args, to.UTC().Format(time.RFC3339Nano))
	}
	if len(parts) == 0 {
		return "", nil
	}
	return " WHERE " + strings.Join(parts, " AND "), args
}
