type OutputFormat string

const (
	FormatTable OutputFormat = "table"
	FormatJSON  OutputFormat = "json"
	FormatCSV   OutputFormat = "csv"
)

func PrintEvents(w io.Writer, events []AuditEvent, format OutputFormat) error {
	switch format {
	case FormatJSON:
		return printJSON(w, events)
	case FormatCSV:
		return printCSV(w, events)
	default:
		return printTable(w, events)
	}
}

func printTable(w io.Writer, events []AuditEvent) error {
	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	fmt.Fprintf(tw, "ID\tTIMESTAMP\tACTOR\tACTION\tRESOURCE\tOUTCOME\tSEVERITY\tSOURCE IP\n")
	fmt.Fprintf(tw, "--\t---------\t-----\t------\t--------\t-------\t--------\t---------\n")
	for _, e := range events {
		resource := e.Resource
		if e.ResourceID != "" {
			resource += "/" + e.ResourceID
		}
		fmt.Fprintf(tw, "%d\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n",
			e.ID,
			e.Timestamp.Format("2006-01-02 15:04:05"),
			e.Actor,
			e.Action,
			resource,
			e.Outcome,
			e.Severity,
			e.SourceIP,
		)
	}
	return tw.Flush()
}

func printJSON(w io.Writer, events []AuditEvent) error {
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	for _, e := range events {
