```javascript
// src/ConfigError.js

class ConfigError extends Error {
  constructor(message, line = null, column = null) {
    super(message);
    this.name = 'ConfigError';
    this.line = line;
    this.column = column;
  }

  toString() {
    let location = '';
    if (this.line !== null) {
      location = ` (line ${this.line}`;
      if (this.column !== null) {
        location += `, col ${this.column}`;
      }
      location += ')';
    }
    return `${this.name}${location}: ${this.message}`;
  }
}

class ParseError extends ConfigError {
  constructor(message, line, column) {
    super(message, line, column);
    this.name = 'ParseError';
  }
}

class ValidationError extends ConfigError {
  constructor(message, key, line) {
    super(message, line);
    this.name = 'ValidationError';
    this.key = key;
  }
}

class InterpolationError extends ConfigError {
  constructor(message, key, line) {
    super(message, line);
    this.name = 'InterpolationError';
    this.key = key;
  }
}

module.exports = { ConfigError, ParseError, ValidationError, InterpolationError };
