## Step 2: Type Coercion Utilities

```javascript
// src/typeCoercion.js

const TypeCoercion = {
  /**
   * Automatically detect and convert a string value to its proper type.
   */
  auto(value) {
    if (value === null || value === undefined) return null;

    const trimmed = value.trim();

    // Null
    if (trimmed.toLowerCase() === 'null' || trimmed.toLowerCase() === 'none') {
      return null;
    }

    // Boolean
    if (['true', 'yes', 'on', '1'].includes(trimmed.toLowerCase())) {
      return true;
    }
    if (['false', 'no', 'off', '0'].includes(trimmed.toLowerCase())) {
      return false;
    }

    // Integer
    if (/^-?\d+$/.test(trimmed)) {
      const num = parseInt(trimmed, 10);
      if (Number.isSafeInteger(num)) return num;
    }

    // Float
    if (/^-?\d+\.\d+$/.test(trimmed)) {
      return parseFloat(trimmed);
    }

    // Array (comma-separated values in brackets)
    if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
      return trimmed
        .slice(1, -1)
        .split(',')
        .map(item => TypeCoercion.auto(item.trim()))
        .filter(item => item !== null && item !== '');
    }

    // Quoted string — strip quotes
    if (
      (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
      (trimmed.startsWith("'") && trimmed.endsWith("'"))
    ) {
      return trimmed.slice(1, -1);
    }

    // Plain string
    return trimmed;
  },

  toString(value) {
    return String(value);
  },

  toInt(value) {
    const num = parseInt(value, 10);
    if (isNaN(num)) throw new Error(`Cannot convert "${value}" to integer`);
    return num;
  },

  toFloat(value) {
    const num = parseFloat(value);
    if (isNaN(num)) throw new Error(`Cannot convert "${value}" to float`);
    return num;
  },

  toBool(value) {
    if (typeof value === 'boolean') return value;
    const str = String(value).toLowerCase().trim();
    if (['true', 'yes', 'on', '1'].includes(str)) return true;
    if (['false', 'no', 'off', '0'].includes(str)) return false;
    throw new Error(`Cannot convert "${value}" to boolean`);
  }
};

module.exports = TypeCoercion;
