// src/validators.js

const { ValidationError } = require('./ConfigError');

/**
 * Schema-based validation for parsed config values.
 *
 * Schema format:
 * {
 *   "section.key": {
 *     type: "string" | "number" | "boolean" | "array",
 *     required: true/false,
 *     default: <value>,
 *     enum: [allowed, values],
 *     min: <number>,       // for numbers
 *     max: <number>,       // for numbers
 *     pattern: /regex/,    // for strings
 *     validator: (val) => true/false  // custom
 *   }
 * }
 */
function validateConfig(config, schema) {
  const errors = [];

  for (const [key, rules] of Object.entries(schema)) {
    const value = getNestedValue(config, key);

    // --- Required check ---
    if (value === undefined || value === null) {
      if (rules.required) {
        errors.push(new ValidationError(`Missing required key "${key}"`, key));
      }
      continue; // skip further checks if value is absent
    }

    // --- Type check ---
    if (rules.type) {
      const actualType = Array.isArray(value) ? 'array' : typeof value;
      if (actualType !== rules.type) {
        errors.push(
          new ValidationError(
            `Key "${key}" expected type "${rules.type}", got "${actualType}"`,
            key
          )
        );
        continue;
      }
    }

    // --- Enum check ---
    if (rules.enum && !rules.enum.includes(value)) {
      errors.push(
        new ValidationError(
          `Key "${key}" must be one of [${rules.enum.join(', ')}], got "${value}"`,
          key
        )
      );
    }

    // --- Range check (numbers) ---
    if (typeof value === 'number') {
      if (rules.min !== undefined && value < rules.min) {
        errors.push(
          new ValidationError(`Key "${key}" must be >= ${rules.min}, got ${value}`, key)
        );
      }
      if (rules.max !== undefined && value > rules.max) {
        errors.push(
          new ValidationError(`Key "${key}" must be <= ${rules.max}, got ${value}`, key)
        );
      }
    }

    // --- Pattern check (strings) ---
    if (rules.pattern && typeof value === 'string') {
      if (!rules.pattern.test(value)) {
        errors.push(
          new ValidationError(
            `Key "${key}" does not match pattern ${rules.pattern}`,
            key
          )
        );
      }
    }

    // --- Custom validator ---
    if (rules.validator && typeof rules.validator === 'function') {
      if (!rules.validator(value)) {
        errors.push(
          new ValidationError(
            `Key "${key}" failed custom validation`,
            key
          )
        );
      }
    }
  }

  return errors;
}

/**
 * Apply default values from schema to config.
 */
function applyDefaults(config, schema) {
  const result = JSON.parse(JSON.stringify(config)); // deep clone

  for (const [key, rules] of Object.entries(schema)) {
    if (rules.default !== undefined) {
      const value = getNestedValue(result, key);
      if (value === undefined || value === null) {
        setNestedValue(result, key, rules.default);
      }
    }
  }

  return result;
}

// --- Helpers for nested access via "section.key" strings ---

function getNestedValue(obj, path) {
  return path.split('.').reduce((current, segment) => {
    return current && current[segment] !== undefined ? current[segment] : undefined;
  }, obj);
}

function setNestedValue(obj, path, value) {
  const parts = path.split('.');
  let current = obj;

  for (let i = 0; i < parts.length - 1; i++) {
    if (current[parts[i]] === undefined) {
      current[parts[i]] = {};
    }
    current = current[parts[i]];
  }

  current[parts[parts.length - 1]] = value;
}

module.exports = { validateConfig, applyDefaults };
