```javascript
// src/ConfigParser.js

const fs = require('fs');
const { ParseError, InterpolationError } = require('./ConfigError');
const TypeCoercion = require('./typeCoercion');
const { validateConfig, applyDefaults } = require('./validators');

class ConfigParser {
  /**
   * @param {Object} options
   * @param {string}  options.commentChars       - Characters that start a comment (default: '#;')
   * @param {string}  options.delimiter           - Key/value delimiter (default: '=')
   * @param {boolean} options.autoCoerce          - Auto-detect types (default: true)
   * @param {boolean} options.interpolateEnv      - Replace ${ENV_VAR} references (default: true)
   * @param {boolean} options.interpolateRefs     - Replace ${section.key} references (default: true)
   * @param {boolean} options.allowMultiline      - Support backslash line continuation (default: true)
   * @param {Object}  options.schema              - Validation schema (default: null)
   */
  constructor(options = {}) {
    this.commentChars = options.commentChars || '#;';
    this.delimiter = options.delimiter || '=';
    this.autoCoerce = options.autoCoerce !== false;
    this.interpolateEnv = options.interpolateEnv !== false;
    this.interpolateRefs = options.interpolateRefs !== false;
    this.allowMultiline = options.allowMultiline !== false;
    this.schema = options.schema || null;

    this.data = {};
    this.errors = [];
    this.warnings = [];
  }

  // ─── Public API ──────────────────────────────────

  /**
   * Parse a config file from disk.
   */
  parseFile(filePath) {
    try {
      if (!fs.existsSync(filePath)) {
        throw new ParseError(`Config file not found: ${filePath}`);
      }

      const content = fs.readFileSync(filePath, 'utf-8');
      return this.parseString(content);
    } catch (err) {
      if (err instanceof ParseError) throw err;
      throw new ParseError(`Failed to read config file: ${err.message}`);
    }
  }

  /**
   * Parse a config string directly.
   */
  parseString(content) {
    this.data = {};
    this.errors = [];
    this.warnings = [];

    const lines = this._preprocessLines(content);
    let currentSection = 'default';
    this.data[currentSection] = {};

    for (const { text, lineNumber } of lines) {
      try {
        // Skip empty lines and comments
        if (this._isEmptyOrComment(text)) continue;

        // Section header: [section_name]
        const sectionMatch = text.match(/^\[([^\]]+)\]$/);
        if (sectionMatch) {
          currentSection = sectionMatch[1].trim();
          if (!this.data[currentSection]) {
            this.data[currentSection] = {};
          }
          continue;
        }

        // Key-value pair
        this._parseKeyValue(text, currentSection, lineNumber);
      } catch (err) {
        this.errors.push(
          err instanceof ParseError
            ? err
            : new ParseError(err.message, lineNumber)
        );
      }
    }

    // Interpolation pass
    if (this.interpolateEnv || this.interpolateRefs) {
      this._interpolateAll();
    }

    // Type coercion pass
    if (this.autoCoerce) {
      this._coerceAll();
    }

    // Schema validation pass
    if (this.schema) {
      this.data = applyDefaults(this.data, this.schema);
      const validationErrors = validateConfig(this.data, this.schema);
      this.errors.push(...validationErrors);
    }

    // If any errors accumulated, throw a summary
    if (this.errors.length > 0) {
      const summary = this.errors.map(e => e.toString()).join('\n  ');
      const err = new ParseError(
        `Config parsing completed with ${this.errors.length} error(s):\n  ${summary}`
      );
      err.details = this.errors;
      throw err;
    }

    return this.data;
  }

  /**
   * Get a value by "section.key" path with an optional default.
   */
  get(path, defaultValue = undefined) {
    const parts = path.split('.');
    let current = this.data;

    for (const part of parts) {
      if (current === undefined || current === null) return defaultValue;
      current = current[part];
    }

    return current !== undefined ? current : defaultValue;
  }

  /**
   * Get an entire section as an object.
   */
  getSection(section) {
    return this.data[section] ? { ...this.data[section] } : null;
  }

  /**
   * List all section names.
   */
  getSections() {
    return Object.keys(this.data);
  }

  /**
   * Check if a key exists at the given path.
   */
  has(path) {
    return this.get(path) !== undefined;
  }

  /**
   * Serialize the current config back to a string.
   */
  serialize() {
    const lines = [];

    for (const [section, entries] of Object.entries(this.data)) {
      if (section !== 'default') {
        lines.push(`\n[${section}]`);
      }
      for (const [key, value] of Object.entries(entries)) {
        const serialized = Array.isArray(value)
          ? `[${value.join(', ')}]`
          : String(value);
        lines.push(`${key} = ${serialized}`);
      }
    }

    return lines.join('\n').trim() + '\n';
  }

  // ─── Internal Parsing Methods ────────────────────

  /**
   * Join backslash-continued lines and track original line numbers.
   */
  _preprocessLines(content) {
    const rawLines = content.split(/\r?\n/);
    const processed = [];
    let buffer = '';
    let startLine = 1;

    for (let i = 0; i < rawLines.length; i++) {
      const line = rawLines[i];
      const lineNum = i + 1;

      if (this.allowMultiline && line.endsWith('\\')) {
        if (!buffer) startLine = lineNum;
        buffer += line.slice(0, -1).trim() + ' ';
      } else if (buffer) {
        buffer += line.trim();
        processed.push({ text: buffer, lineNumber: startLine });
        buffer = '';
      } else {
        processed.push({ text: line.trim(), lineNumber: lineNum });
      }
    }

    // Unterminated continuation
    if (buffer) {
      this.warnings.push(`Unterminated line continuation at line ${startLine}`);
      processed.push({ text: buffer, lineNumber: startLine });
    }

    return processed;
  }

  _isEmptyOrComment(line) {
    if (!line) return true;
    return this.commentChars.includes(line[0]);
  }

  _parseKeyValue(line, section, lineNumber) {
    const delimIndex = line.indexOf(this.delimiter);

    if (delimIndex === -1) {
      throw new ParseError(
        `Expected "${this.delimiter}" delimiter in: "${line}"`,
        lineNumber
      );
    }

    const key = line.substring(0, delimIndex).trim();
    const value = line.substring(delimIndex + 1).trim();

    // Strip inline comments (but not inside quotes)
    const cleanValue = this._stripInlineComment(value);

    // Validate key format
    if (!key) {
      throw new ParseError('Empty key name', lineNumber);
    }
    if (!/^[a-zA-Z_][a-zA-Z0-9_.-]*$/.test(key)) {
      throw new ParseError(
        `Invalid key name "${key}" — use alphanumerics, underscores, dots, hyphens`,
        lineNumber
      );
    }

    // Warn on duplicate keys
    if (this.data[section] && this.data[section][key] !== undefined) {
      this.warnings.push(
        `Duplicate key "${key}" in [${section}] at line ${lineNumber} (overwriting)`
      );
    }

    this.data[section][key] = cleanValue;
  }

  _stripInlineComment(value) {
    let inQuote = false;
    let quoteChar = '';

    for (let i = 0; i < value.length; i++) {
      const ch = value[i];

      if (inQuote) {
        if (ch === quoteChar) inQuote = false;
      } else if (ch === '"' || ch === "'") {
        inQuote = true;
        quoteChar = ch;
      } else if (this.commentChars.includes(ch)) {
        return value.substring(0, i).trim();
      }
    }

    return value;
  }

  // ─── Interpolation ──────────────────────────────

  _interpolateAll() {
    const maxDepth = 10;

    for (const section of Object.keys(this.data)) {
      for (const key of Object.keys(this.data[section])) {
        const value = this.data[section][key];
        if (typeof value !== 'string') continue;

        try {
          this.data[section][key] = this._interpolateValue(
            value,
            `${section}.${key}`,
            0,
            maxDepth
          );
        } catch (err) {
          this.errors.push(err);
        }
      }
    }
  }

  _interpolateValue(value, keyPath, depth, maxDepth) {
    if (depth > maxDepth) {
      throw new InterpolationError(
        `Max interpolation depth exceeded for "${keyPath}" — possible circular reference`,
        keyPath
      );
    }

    return value.replace(/\$\{([^}]+)\}/g, (match, ref) => {
      const trimmedRef = ref.trim();

      // Try environment variable first
      if (this.interpolateEnv && process.env[trimmedRef] !== undefined) {
        return process.env[trimmedRef];
      }

      // Try config reference (section.key)
      if (this.interpolateRefs) {
        const resolved = this._resolveRef(trimmedRef);
        if (resolved !== undefined) {
          // Recursively interpolate the resolved value
          if (typeof resolved === 'string' && resolved.includes('${')) {
            return this._interpolateValue(resolved, keyPath, depth + 1, maxDepth);
          }

# Background Worker for Cache Invalidation in JavaScript

## Architecture Overview

```
┌──────────────┐     ┌──────────────────┐     ┌─────────────┐
│  Application  │────▶│   Cache Manager   │────▶│  In-Memory  │
│    Code       │◀────│   (get/set/del)   │◀────│    Store    │
└──────────────┘     └────────┬─────────┘     └─────────────┘
                              │
                    ┌─────────▼──────────┐
                    │  Background Worker  │
                    │  ─ TTL sweep        │
                    │  ─ Dependency check │
                    │  ─ Event listener   │
