```javascript
// ─────────────────────────────────────────────
// cacheEntry.js — Represents a single cache item
// ─────────────────────────────────────────────
class CacheEntry {
  constructor(key, value, options = {}) {
    this.key = key;
    this.value = value;
    this.createdAt = Date.now();
    this.lastAccessed = Date.now();
    this.ttl = options.ttl ?? null;              // milliseconds, null = no expiry
    this.tags = new Set(options.tags ?? []);      // for group invalidation
    this.dependencies = options.dependencies ?? []; // keys this entry depends on
    this.version = options.version ?? 1;
    this.hitCount = 0;
  }

  isExpired() {
    if (this.ttl === null) return false;
    return Date.now() - this.createdAt > this.ttl;
  }

  touch() {
    this.lastAccessed = Date.now();
    this.hitCount++;
  }

  toJSON() {
    return {
      key: this.key,
      createdAt: this.createdAt,
      ttl: this.ttl,
      tags: [...this.tags],
      hitCount: this.hitCount,
      expired: this.isExpired(),
    };
  }
}

// ─────────────────────────────────────────────
// eventBus.js — Simple pub/sub for cache events
// ─────────────────────────────────────────────
class EventBus {
  constructor() {
    this.listeners = new Map();
  }

  on(event, callback) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event).add(callback);
    // Return unsubscribe function
    return () => this.listeners.get(event)?.delete(callback);
  }

  emit(event, data) {
    const callbacks = this.listeners.get(event);
    if (callbacks) {
      for (const cb of callbacks) {
        try {
          cb(data);
        } catch (err) {
          console.error(`Event handler error [${event}]:`, err);
        }
      }
    }
  }
}

// ─────────────────────────────────────────────
// cacheManager.js — Core cache with CRUD ops
// ─────────────────────────────────────────────
class CacheManager {
  constructor(options = {}) {
    this.store = new Map();
    this.maxSize = options.maxSize ?? 1000;
    this.events = new EventBus();
    this.stats = { hits: 0, misses: 0, evictions: 0, invalidations: 0 };
  }

  get(key) {
    const entry = this.store.get(key);

    if (!entry) {
      this.stats.misses++;
      this.events.emit("cache:miss", { key });
      return undefined;
    }

    // Check expiration on read (lazy invalidation)
    if (entry.isExpired()) {
      this.delete(key, "expired-on-read");
      this.stats.misses++;
      return undefined;
    }

    entry.touch();
    this.stats.hits++;
    this.events.emit("cache:hit", { key, hitCount: entry.hitCount });
    return entry.value;
  }

  set(key, value, options = {}) {
    // Evict LRU if at capacity
    if (!this.store.has(key) && this.store.size >= this.maxSize) {
      this.evictLRU();
    }

    const entry = new CacheEntry(key, value, options);
    this.store.set(key, entry);

    this.events.emit("cache:set", { key, tags: [...entry.tags], ttl: entry.ttl });
    return entry;
  }

  delete(key, reason = "manual") {
    const entry = this.store.get(key);
    if (!entry) return false;

    this.store.delete(key);
    this.stats.invalidations++;
    this.events.emit("cache:invalidated", { key, reason, entry: entry.toJSON() });
    return true;
  }

  has(key) {
    const entry = this.store.get(key);
    return entry ? !entry.isExpired() : false;
  }

  // Invalidate all entries matching specific tags
  invalidateByTag(tag) {
    const invalidated = [];
    for (const [key, entry] of this.store) {
      if (entry.tags.has(tag)) {
        invalidated.push(key);
        this.delete(key, `tag:${tag}`);
      }
    }
    this.events.emit("cache:tag-invalidated", { tag, keys: invalidated });
    return invalidated;
  }

  // Invalidate entries matching a key pattern (glob-like)
  invalidateByPattern(pattern) {
    const regex = new RegExp("^" + pattern.replace(/\*/g, ".*") + "$");
    const invalidated = [];
    for (const [key] of this.store) {
      if (regex.test(key)) {
        invalidated.push(key);
        this.delete(key, `pattern:${pattern}`);
      }
    }
    return invalidated;
  }

  // Remove the least recently used entry
  evictLRU() {
    let oldest = null;
    for (const [key, entry] of this.store) {
      if (!oldest || entry.lastAccessed < oldest.lastAccessed) {
        oldest = entry;
      }
    }
    if (oldest) {
      this.delete(oldest.key, "lru-eviction");
      this.stats.evictions++;
    }
  }

  getStats() {
    const totalEntries = this.store.size;
    const expiredEntries = [...this.store.values()].filter((e) => e.isExpired()).length;
    return { ...this.stats, totalEntries, expiredEntries };
  }

  clear() {
    const count = this.store.size;
    this.store.clear();
    this.events.emit("cache:cleared", { count });
  }
}

// ─────────────────────────────────────────────
// invalidationWorker.js — Background worker
// ─────────────────────────────────────────────
class CacheInvalidationWorker {
  constructor(cacheManager, options = {}) {
    this.cache = cacheManager;
    this.running = false;
    this.timers = new Map();

    // Worker configuration
    this.config = {
      ttlSweepInterval: options.ttlSweepInterval ?? 30_000,      // 30s
      dependencyCheckInterval: options.dependencyCheckInterval ?? 60_000, // 60s
      statsReportInterval: options.statsReportInterval ?? 120_000,       // 2min
      batchSize: options.batchSize ?? 100,  // max keys per sweep cycle
      enableDependencyCheck: options.enableDependencyCheck ?? true,
      onInvalidation: options.onInvalidation ?? null, // external callback
    };

    // Track dependency versions for change detection
    this.dependencyVersions = new Map();

    this._bindEvents();
  }

  // ── Lifecycle ──────────────────────────────

  start() {
    if (this.running) {
      console.warn("[Worker] Already running");
      return;
    }

    this.running = true;
    console.log("[Worker] Starting cache invalidation worker...");

    // Schedule recurring tasks
    this._schedule("ttl-sweep", this.config.ttlSweepInterval, () => this.sweepExpired());
    this._schedule("stats-report", this.config.statsReportInterval, () => this.reportStats());

    if (this.config.enableDependencyCheck) {
      this._schedule("dep-check", this.config.dependencyCheckInterval, () =>
        this.checkDependencies()
      );
    }

    // Run an initial sweep immediately
    this.sweepExpired();

    console.log("[Worker] Worker started with intervals:", {
      ttlSweep: `${this.config.ttlSweepInterval}ms`,
      depCheck: `${this.config.dependencyCheckInterval}ms`,
      statsReport: `${this.config.statsReportInterval}ms`,
    });
  }

  stop() {
    if (!this.running) return;

    this.running = false;
    for (const [name, timerId] of this.timers) {
      clearInterval(timerId);
      console.log(`[Worker] Stopped task: ${name}`);
    }
    this.timers.clear();
    console.log("[Worker] Cache invalidation worker stopped");
  }

  // ── Core Strategies ────────────────────────

  /**
   * Strategy 1: TTL-Based Sweep
   * Scans the cache in batches and removes expired entries.
   */
  sweepExpired() {
    const startTime = performance.now();
    const expiredKeys = [];
    let scanned = 0;

    for (const [key, entry] of this.cache.store) {
      if (scanned >= this.config.batchSize) break;

      if (entry.isExpired()) {
        expiredKeys.push(key);
      }
      scanned++;
    }

    // Perform the actual deletions
    for (const key of expiredKeys) {
      this.cache.delete(key, "ttl-sweep");
      this.config.onInvalidation?.({ key, reason: "ttl-sweep" });
    }

    const elapsed = (performance.now() - startTime).toFixed(2);

    if (expiredKeys.length > 0) {
      console.log(
        `[Worker] TTL sweep: removed ${expiredKeys.length}/${scanned} scanned in ${elapsed}ms`
      );
    }

    return { removed: expiredKeys.length, scanned, elapsedMs: parseFloat(elapsed) };
  }

  /**
   * Strategy 2: Dependency-Based Invalidation
   * If entry A depends on entry B, and B is gone or updated → invalidate A.
   */
  checkDependencies() {
    const startTime = performance.now();
    const invalidated = [];

    for (const [key, entry] of this.cache.store) {
      if (entry.dependencies.length === 0) continue;

      for (const depKey of entry.dependencies) {
        const depEntry = this.cache.store.get(depKey);

        // Dependency missing → invalidate
        if (!depEntry) {
          invalidated.push(key);
          this.cache.delete(key, `dependency-missing:${depKey}`);
          break;
        }

        // Dependency version changed → invalidate
        const trackedVersion = this.dependencyVersions.get(depKey);
        if (trackedVersion !== undefined && depEntry.version !== trackedVersion) {
          invalidated.push(key);
          this.cache.delete(key, `dependency-changed:${depKey}`);
          break;
        }
      }
    }

    // Snapshot current versions for next comparison
    for (const [key, entry] of this.cache.store) {
      this.dependencyVersions.set(key, entry.version);
    }

    const elapsed = (performance.now() - startTime).toFixed(2);
    if (invalidated.length > 0) {
      console.log(`[Worker] Dependency check: invalidated ${invalidated.length} in ${elapsed}ms`);
    }

    return { invalidated, elapsedMs: parseFloat(elapsed) };
  }

  /**
   * Strategy 3: Event-Driven Invalidation
   * External systems notify about data changes.
   */
  handleExternalEvent(event) {
    const { type, entity, id, tags } = event;

    console.log(`[Worker] External event: ${type} → ${entity}:${id}`);

    switch (type) {
      case "update":
      case "delete": {
        // Invalidate specific key
        const key = `${entity}:${id}`;
        this.cache.delete(key, `event:${type}`);

        // Also invalidate related list caches
        this.cache.invalidateByPattern(`${entity}:list:*`);

        // Invalidate by tags if provided
        if (tags) {
          tags.forEach((tag) => this.cache.invalidateByTag(tag));
        }
        break;
      }
      case "bulk-update": {
        this.cache.invalidateByTag(entity);
        break;
      }
      default:
        console.warn(`[Worker] Unknown event type: ${type}`);
    }
  }

  // ── Reporting ──────────────────────────────

  reportStats() {
    const stats = this.cache.getStats();
    const hitRate =
      stats.hits + stats.misses > 0
        ? ((stats.hits / (stats.hits + stats.misses)) * 100).toFixed(1)
        : "0.0";

    console.log("[Worker] Cache Statistics:", {
      ...stats,
      hitRate: `${hitRate}%`,
      memoryEntries: this.cache.store.size,
    });

    return stats;
  }

  // ── Internal Helpers ───────────────────────

  _schedule(name, intervalMs, task) {
    const timerId = setInterval(() => {
      if (!this.running) return;
      try {
        task();
      } catch (err) {
        console.error(`[Worker] Task "${name}" failed:`, err);
      }
    }, intervalMs);

    this.timers.set(name, timerId);
  }

  _bindEvents() {
    // Cascade: when an entry is invalidated, check if other entries depended on it
    this.cache.events.on("cache:invalidated", ({ key }) => {
      if (!this.running) return;

      // Find entries that list this key as a dependency
      for (const [otherKey, entry] of this.cache.store) {
        if (entry.dependencies.includes(key)) {
          console.log(`[Worker] Cascade invalidation: ${otherKey} (depends on ${key})`);
          this.cache.delete(otherKey, `cascade:${key}`);
        }
      }
    });
  }
}

