            TaskError::ExecutionFailed(msg) => write!(f, "Execution failed: {msg}"),
            TaskError::LockError(msg) => write!(f, "Lock error: {msg}"),
            TaskError::SchedulerShutdown => write!(f, "Scheduler is shutting down"),
        }
    }
