## `src/main.rs`

```rust
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::{mpsc, Mutex};
use tokio::time::{self, Duration};

// ---------- Models ----------

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ChatMessage {
    id: u64,
    user_id: String,
    channel: String,
    content: String,
    timestamp: DateTime<Utc>,
}

#[derive(Debug, Clone)]
enum ModerationAction {
    Allow,
    Delete { reason: String },
    Warn { reason: String },
    Ban { reason: String, duration_secs: u64 },
}

#[derive(Debug, Clone)]
struct ModerationResult {
    message: ChatMessage,
    action: ModerationAction,
    flags: Vec<String>,
}

// ---------- Moderator ----------

struct Moderator {
    banned_words: Vec<String>,
    link_patterns: Vec<String>,
    spam_tracker: Arc<Mutex<HashMap<String, Vec<DateTime<Utc>>>>>,
    max_messages_per_window: usize,
    window_secs: i64,
    caps_threshold: f64,
}

impl Moderator {
    fn new() -> Self {
        Self {
            banned_words: vec![
                "slur1", "slur2", "badword", "hate", "harassment",
            ]
            .into_iter()
            .map(String::from)
            .collect(),

            link_patterns: vec![
                "http://", "https://", "www.", ".com", ".gg/",
            ]
            .into_iter()
            .map(String::from)
            .collect(),

            spam_tracker: Arc::new(Mutex::new(HashMap::new())),
            max_messages_per_window: 5,
            window_secs: 10,
            caps_threshold: 0.7,
        }
    }

    /// Run all moderation checks on a message
    async fn moderate(&self, message: ChatMessage) -> ModerationResult {
        let mut flags: Vec<String> = Vec::new();

        // Check 1: Banned words
        if let Some(word) = self.check_banned_words(&message.content) {
            flags.push(format!("banned_word:{word}"));
        }

        // Check 2: Excessive caps
        if self.check_excessive_caps(&message.content) {
            flags.push("excessive_caps".into());
        }

        // Check 3: Spam (rate limiting)
        if self.check_spam(&message.user_id, message.timestamp).await {
            flags.push("spam".into());
        }

        // Check 4: Unsolicited links
        if self.check_links(&message.content) {
            flags.push("contains_link".into());
        }

        // Decide action based on flags
        let action = self.decide_action(&flags);

        ModerationResult {
            message,
            action,
            flags,
        }
    }

    fn check_banned_words(&self, content: &str) -> Option<String> {
        let lower = content.to_lowercase();
        self.banned_words
            .iter()
            .find(|word| lower.contains(word.as_str()))
            .cloned()
    }

    fn check_excessive_caps(&self, content: &str) -> bool {
        if content.len() < 8 {
            return false;
        }
        let alpha_chars: Vec<char> = content.chars().filter(|c| c.is_alphabetic()).collect();
        if alpha_chars.is_empty() {
            return false;
        }
        let upper_count = alpha_chars.iter().filter(|c| c.is_uppercase()).count();
        (upper_count as f64 / alpha_chars.len() as f64) > self.caps_threshold
    }

    async fn check_spam(&self, user_id: &str, timestamp: DateTime<Utc>) -> bool {
        let mut tracker = self.spam_tracker.lock().await;
        let entries = tracker.entry(user_id.to_string()).or_default();

        // Purge old entries outside the window
        let cutoff = timestamp - chrono::Duration::seconds(self.window_secs);
        entries.retain(|t| *t > cutoff);

        entries.push(timestamp);

        entries.len() > self.max_messages_per_window
    }

    fn check_links(&self, content: &str) -> bool {
        let lower = content.to_lowercase();
        self.link_patterns.iter().any(|p| lower.contains(p))
    }

    fn decide_action(&self, flags: &[String]) -> ModerationAction {
        if flags.is_empty() {
            return ModerationAction::Allow;
        }

        // Banned words -> immediate delete + ban
        if flags.iter().any(|f| f.starts_with("banned_word")) {
            let reason = flags
                .iter()
                .filter(|f| f.starts_with("banned_word"))
                .cloned()
                .collect::<Vec<_>>()
                .join(", ");
            return ModerationAction::Ban {
                reason,
                duration_secs: 3600,
            };
        }

        // Spam -> delete + warn
        if flags.contains(&"spam".into()) {
            return ModerationAction::Delete {
                reason: "Rate limit exceeded".into(),
            };
        }

        // Caps or links -> warn
        let reason = flags.join(", ");
        ModerationAction::Warn { reason }
    }
}

// ---------- Consumer ----------

async fn consume(mut rx: mpsc::Receiver<ChatMessage>, moderator: Arc<Moderator>) {
    println!("[consumer] Listening for messages...\n");

    while let Some(msg) = rx.recv().await {
        let moderator = Arc::clone(&moderator);

        // Spawn a task per message for concurrent processing
        tokio::spawn(async move {
            let result = moderator.moderate(msg).await;
            handle_result(&result);
        });
    }

    println!("[consumer] Channel closed. Shutting down.");
}

fn handle_result(result: &ModerationResult) {
    let msg = &result.message;
    let tag = format!("[{}] #{} @{}", msg.id, msg.channel, msg.user_id);

    match &result.action {
        ModerationAction::Allow => {
            println!("{tag} ✅ ALLOWED  \"{}\"", msg.content);
        }
        ModerationAction::Delete { reason } => {
            println!("{tag} 🗑️  DELETED  \"{}\" reason={reason}", msg.content);
        }
        ModerationAction::Warn { reason } => {
            println!("{tag} ⚠️  WARNED   \"{}\" reason={reason}", msg.content);
        }
        ModerationAction::Ban {
            reason,
            duration_secs,
        } => {
            println!(
                "{tag} 🚫 BANNED   \"{}\" reason={reason} duration={duration_secs}s",
                msg.content
            );
        }
    }

    if !result.flags.is_empty() {
        println!("   flags: {:?}\n", result.flags);
    }
}

// ---------- Producer (simulated) ----------

async fn produce(tx: mpsc::Sender<ChatMessage>) {
    let test_messages = vec![
        ("alice", "general", "Hey everyone! How's it going?"),
        ("bob", "general", "Check out https://scam.com free stuff!"),
        ("charlie", "gaming", "THIS GAME IS ABSOLUTELY TERRIBLE AHHH"),
        ("dave", "general", "You are full of hate and harassment"),
        ("alice", "general", "Anyone want to play later?"),
        ("eve", "general", "msg1"),
        ("eve", "general", "msg2"),
        ("eve", "general", "msg3"),
        ("eve", "general", "msg4"),
        ("eve", "general", "msg5"),
        ("eve", "general", "msg6 - this should trigger spam"),
        ("frank", "general", "Normal message, nothing wrong here."),
    ];

    for (i, (user, channel, content)) in test_messages.into_iter().enumerate() {
        let msg = ChatMessage {
            id: i as u64 + 1,
            user_id: user.into(),
            channel: channel.into(),
            content: content.into(),
            timestamp: Utc::now(),
        };

        if tx.send(msg).await.is_err() {
            eprintln!("[producer] Consumer dropped. Stopping.");
            break;
        }

        // Simulate real-time message flow
        time::sleep(Duration::from_millis(100)).await;
    }

    println!("\n[producer] All test messages sent.");
}

// ---------- Main ----------

#[tokio::main]
async fn main() {
    let (tx, rx) = mpsc::channel::<ChatMessage>(100);
    let moderator = Arc::new(Moderator::new());

    let consumer_handle = tokio::spawn(consume(rx, moderator));
    let producer_handle = tokio::spawn(produce(tx));

    // Wait for producer to finish, then consumer drains and exits
    let _ = producer_handle.await;
    let _ = consumer_handle.await;
}
```

## How It Works

```
┌──────────┐    mpsc::channel    ┌──────────┐    moderate()    ┌──────────────┐
│ Producer  │ ──────────────────▶ │ Consumer │ ──────────────▶ │  Moderator   │
│ (ingress) │   ChatMessage       │ (loop)   │                 │              │
└──────────┘                     └──────────┘                 │ • banned words│
                                       │                      │ • caps check  │
                                       ▼                      │ • spam detect │
                                 handle_result()              │ • link filter │
                                 (log / persist)              └──────────────┘
```

## Moderation Rules

| Check | Trigger | Action |
|---|---|---|
| **Banned words** | Message contains a blocklisted word | `Ban` (1 hour) |
| **Spam** | >5 messages in 10 seconds from same user | `Delete` |
| **Excessive caps** | >70% uppercase (min 8 chars) | `Warn` |
| **Links** | Contains URL patterns | `Warn` |
| **Clean** | No flags | `Allow` |

