# Rust Config Parser with Cache Invalidation

This example implements a thread-safe config parser that caches parsed configurations and supports multiple invalidation strategies (TTL, file-modification, version-based, and manual).

```rust
use std::collections::HashMap;
use std::fmt;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant, SystemTime};

// ──────────────────────────── Error Types ────────────────────────────

#[derive(Debug)]
enum ConfigError {
    Io(io::Error),
    Parse { line: usize, message: String },
    NotFound(String),
    CachePoisoned,
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(e) => write!(f, "IO error: {e}"),
            Self::Parse { line, message } => write!(f, "Parse error at line {line}: {message}"),
            Self::NotFound(key) => write!(f, "Config key not found: {key}"),
            Self::CachePoisoned => write!(f, "Cache lock poisoned"),
        }
    }
}

impl std::error::Error for ConfigError {}

impl From<io::Error> for ConfigError {
    fn from(e: io::Error) -> Self {
        Self::Io(e)
    }
}

type Result<T> = std::result::Result<T, ConfigError>;

// ──────────────────────────── Config Values ──────────────────────────

#[derive(Debug, Clone, PartialEq)]
enum ConfigValue {
    String(String),
    Integer(i64),
    Float(f64),
    Boolean(bool),
    List(Vec<ConfigValue>),
}

impl ConfigValue {
    fn as_str(&self) -> Option<&str> {
        match self {
            Self::String(s) => Some(s),
            _ => None,
        }
    }

    fn as_i64(&self) -> Option<i64> {
        match self {
            Self::Integer(n) => Some(*n),
            _ => None,
        }
    }

    fn as_bool(&self) -> Option<bool> {
        match self {
            Self::Boolean(b) => Some(*b),
            _ => None,
        }
    }
}

impl fmt::Display for ConfigValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::String(s) => write!(f, "{s}"),
            Self::Integer(n) => write!(f, "{n}"),
            Self::Float(n) => write!(f, "{n}"),
            Self::Boolean(b) => write!(f, "{b}"),
            Self::List(items) => {
                let strs: Vec<String> = items.iter().map(|v| v.to_string()).collect();
                write!(f, "[{}]", strs.join(", "))
            }
        }
    }
}

// ──────────────────────── Parsed Config ──────────────────────────────

#[derive(Debug, Clone)]
struct ParsedConfig {
    /// section -> key -> value
    sections: HashMap<String, HashMap<String, ConfigValue>>,
}

impl ParsedConfig {
    fn new() -> Self {
        Self {
            sections: HashMap::new(),
        }
    }

    /// Get a value by "section.key" dotted path
    fn get(&self, path: &str) -> Option<&ConfigValue> {
        let (section, key) = path.split_once('.')?;
        self.sections.get(section)?.get(key)
    }

    /// Get with a fallback default
    fn get_or<'a>(&'a self, path: &str, default: &'a ConfigValue) -> &'a ConfigValue {
        self.get(path).unwrap_or(default)
    }
}

// ──────────────────────── Parser ─────────────────────────────────────

struct ConfigParser;

impl ConfigParser {
    /// Parse an INI-like config string:
    ///
    /// ```text
    /// [section]
    /// key = value
    /// number = 42
    /// flag = true
    /// list = one, two, three
    /// ```
    fn parse(input: &str) -> Result<ParsedConfig> {
        let mut config = ParsedConfig::new();
        let mut current_section = String::from("default");

        for (line_num, raw_line) in input.lines().enumerate() {
            let line = raw_line.trim();

            // Skip empty lines and comments
            if line.is_empty() || line.starts_with('#') || line.starts_with(';') {
                continue;
            }

            // Section header: [section_name]
            if line.starts_with('[') && line.ends_with(']') {
                current_section = line[1..line.len() - 1].trim().to_string();
                if current_section.is_empty() {
                    return Err(ConfigError::Parse {
                        line: line_num + 1,
                        message: "Empty section name".into(),
                    });
                }
                continue;
            }

            // Key-value pair: key = value
            let (key, raw_value) = line.split_once('=').ok_or(ConfigError::Parse {
                line: line_num + 1,
                message: format!("Expected 'key = value', got: {line}"),
            })?;

            let key = key.trim().to_string();
            let raw_value = raw_value.trim();

            if key.is_empty() {
                return Err(ConfigError::Parse {
                    line: line_num + 1,
                    message: "Empty key".into(),
                });
            }

            let value = Self::parse_value(raw_value);

            config
                .sections
                .entry(current_section.clone())
                .or_default()
                .insert(key, value);
        }

        Ok(config)
    }

    fn parse_value(raw: &str) -> ConfigValue {
        // Boolean
        match raw.to_lowercase().as_str() {
            "true" | "yes" | "on" => return ConfigValue::Boolean(true),
            "false" | "no" | "off" => return ConfigValue::Boolean(false),
            _ => {}
        }

        // Integer
        if let Ok(n) = raw.parse::<i64>() {
            return ConfigValue::Integer(n);
        }

        // Float
        if let Ok(n) = raw.parse::<f64>() {
            return ConfigValue::Float(n);
        }

        // Comma-separated list
        if raw.contains(',') {
            let items: Vec<ConfigValue> = raw
                .split(',')
                .map(|s| Self::parse_value(s.trim()))
                .collect();
            return ConfigValue::List(items);
        }

        // Quoted string → strip quotes
        if (raw.starts_with('"') && raw.ends_with('"'))
            || (raw.starts_with('\'') && raw.ends_with('\''))
        {
            return ConfigValue::String(raw[1..raw.len() - 1].to_string());
        }

        ConfigValue::String(raw.to_string())
    }

    fn parse_file(path: &Path) -> Result<ParsedConfig> {
        let content = fs::read_to_string(path)?;
        Self::parse(&content)
    }
}

// ──────────────────── Invalidation Strategy ──────────────────────────

#[derive(Debug, Clone)]
enum InvalidationStrategy {
    /// Invalidate after a fixed duration
    Ttl(Duration),
    /// Invalidate when the file's modification time changes
    FileModified,
    /// Invalidate only by manual / version bump
    Manual,
    /// Combine TTL *and* file-modification checks
    TtlAndFileModified(Duration),
}

// ──────────────────── Cache Entry ────────────────────────────────────

#[derive(Debug, Clone)]
struct CacheEntry {
    config: ParsedConfig,
    loaded_at: Instant,
    file_modified: Option<SystemTime>,
    version: u64,
    hit_count: u64,
}

impl CacheEntry {
    fn is_ttl_expired(&self, ttl: Duration) -> bool {
        self.loaded_at.elapsed() > ttl
    }

    fn is_file_stale(&self, path: &Path) -> bool {
        let current_mtime = fs::metadata(path)
            .and_then(|m| m.modified())
            .ok();

        match (self.file_modified, current_mtime) {
            (Some(cached), Some(current)) => cached != current,
            (None, Some(_)) => true,   // file appeared
            (Some(_), None) => true,   // file disappeared
            (None, None) => false,
        }
    }
}

// ──────────────── Cache Statistics ───────────────────────────────────

#[derive(Debug, Default, Clone)]
struct CacheStats {
    hits: u64,
    misses: u64,
    invalidations: u64,
    reloads: u64,
}

impl fmt::Display for CacheStats {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let total = self.hits + self.misses;
        let ratio = if total > 0 {
            self.hits as f64 / total as f64 * 100.0
        } else {
            0.0
        };
        write!(
            f,
            "Cache stats — hits: {}, misses: {}, hit-rate: {:.1}%, \
             invalidations: {}, reloads: {}",
            self.hits, self.misses, ratio, self.invalidations, self.reloads
        )
    }
}

// ──────────── Cached Config Manager (thread-safe) ────────────────────

struct CachedConfigManager {
    cache: Arc<RwLock<HashMap<PathBuf, CacheEntry>>>,
    strategy: InvalidationStrategy,
    stats: Arc<RwLock<CacheStats>>,
    global_version: Arc<RwLock<u64>>,
}

impl CachedConfigManager {
    fn new(strategy: InvalidationStrategy) -> Self {
        Self {
            cache: Arc::new(RwLock::new(HashMap::new())),
            strategy,
            stats: Arc::new(RwLock::new(CacheStats::default())),
            global_version: Arc::new(RwLock::new(0)),
        }
    }

    // ── public API ───────────────────────────────────────────────────

    /// Load (or return cached) config for `path`.
    fn get_config(&self, path: &Path) -> Result<ParsedConfig> {
        // Fast path — read lock only
        if let Some(config) = self.try_cached(path)? {
            return Ok(config);
        }
        // Slow path — parse, then write lock
        self.load_and_cache(path)
    }

    /// Force-invalidate a single file's cache.
    fn invalidate(&self, path: &Path) -> Result<bool> {
        let canonical = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
        let mut cache = self.cache.write().map_err(|_| ConfigError::CachePoisoned)?;
        let removed = cache.remove(&canonical).is_some();
        if removed {
            self.bump_stat(|s| s.invalidations += 1)?;
        }
        Ok(removed)
    }

    /// Invalidate *all* cached configs.
    fn invalidate_all(&self) -> Result<usize> {
        let mut cache = self.cache.write().map_err(|_| ConfigError::CachePoisoned)?;
        let count = cache.len();
        cache.clear();
        self.bump_stat(|s| s.invalidations += count as u64)?;
        Ok(count)
    }

    /// Bump the global version — makes every entry stale under `Manual` strategy.
    fn bump_version(&self) -> Result<u64> {
        let mut v = self.global_version.write().map_err(|_| ConfigError::CachePoisoned)?;
        *v += 1;
        Ok(*v)
    }

    /// Snapshot of current stats.
    fn stats(&self) -> Result<CacheStats> {
        self.stats.read().map(|s| s.clone()).map_err(|_| ConfigError::CachePoisoned)
    }

    // ── internals ────────────────────────────────────────────────────

    fn try_cached(&self, path: &Path) -> Result<Option<ParsedConfig>> {
        let canonical = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
        let cache = self.cache.read().map_err(|_| ConfigError::CachePoisoned)?;

        let entry = match cache.get(&canonical) {
            Some(e) => e,
            None => return Ok(None),
        };

        if self.is_stale(entry, &canonical)? {
            return Ok(None); // will reload on slow path
        }

        // Cache hit
        drop(cache);
        // bump hit_count under write lock
        if let Ok(mut cache) = self.cache.write() {
            if let Some(e) = cache.get_mut(&canonical) {
                e.hit_count += 1;
            }
        }
        self.bump_stat(|s| s.hits += 1)?;

        let cache = self.cache.read().map_err(|_| ConfigError::CachePoisoned)?;
        Ok(cache.get(&canonical).map(|e| e.config.clone()))
    }

    fn load_and_cache(&self, path: &Path) -> Result<ParsedConfig> {
        let canonical = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());

        let config = ConfigParser::parse_file(&canonical)?;
        let mtime = fs::metadata(&canonical)
            .and_then(|m| m.modified())
            .ok();
        let version = *self.global_version.read().map_err(|_| ConfigError::CachePoisoned)?;

        let entry = CacheEntry {
            config: config.clone(),
            loaded_at: Instant::now(),
            file_modified: mtime,
            version,
            hit_count: 0,
        };

        self.cache
            .write()
            .map_err(|_| ConfigError::CachePoisoned)?
            .insert(canonical, entry);

        self.bump_stat(|s| {
            s.misses += 1;
            s.reloads += 1;
        })?;

        Ok(config)
    }

    fn is_stale(&self, entry: &CacheEntry, path: &Path) -> Result<bool> {
        match &self.strategy {
            InvalidationStrategy::Ttl(ttl) => Ok(entry.is_ttl_expired(*ttl)),

            InvalidationStrategy::FileModified => Ok(entry.is_file_stale(path)),

            InvalidationStrategy::Manual => {
                let current = *self.global_version.read().map_err(|_| ConfigError::CachePoisoned)?;
                Ok(entry.version != current)
            }

            InvalidationStrategy::TtlAndFileModified(ttl) => {
                Ok(entry.is_ttl_expired(*ttl) || entry.is_file_stale(path))
            }
        }
    }

    fn bump_stat<F: FnOnce(&mut CacheStats)>(&self, f: F) -> Result<()> {
        let mut stats = self.stats.write().map_err(|_| ConfigError::CachePoisoned)?;
        f(&mut stats);
        Ok(())
    }
}

// ──────────────────────── Demo ───────────────────────────────────────

fn main() -> Result<()> {
    // ── 1. Write a sample config file ────────────────────────────────
    let config_path = Path::new("/tmp/app_config.ini");
    fs::write(
        config_path,
        r#"
# Application configuration

[server]
host = 127.0.0.1
port = 8080
workers = 4
debug = true
allowed_origins = localhost, example.com, api.example.com

[database]
url = "postgres://localhost:5432/mydb"
max_connections = 25
timeout_seconds = 30
ssl = true

[cache]
enabled = true
ttl_seconds = 300
max_entries = 10000
backend = redis
"#,
    )?;

    // ── 2. Create manager with a 5-second TTL ───────────────────────
    let manager = CachedConfigManager::new(InvalidationStrategy::Ttl(Duration::from_secs(5)));

    // ── 3. First load — cache miss, file is parsed ──────────────────
    println!("━━━ First load (cold cache) ━━━");
    let config = manager.get_config(config_path)?;
    print_config_summary(&config);
    println!("{}\n", manager.stats()?);

    // ── 4. Second load — cache hit ──────────────────────────────────
