    assert_eq!(
        config.get("server.port").and_then(|v| v.as_i64()),
        Some(8080)
    );
    println!("{}\n", manager.stats()?);

    // ── 5. Manual invalidation, then reload ─────────────────────────
    println!("━━━ After manual invalidation ━━━");
    manager.invalidate(config_path)?;

    // Rewrite file with different values
    fs::write(
        config_path,
        r#"
