    // ── 6. Demonstrate version-based invalidation ───────────────────
    println!("━━━ Version-based strategy demo ━━━");
    let versioned = CachedConfigManager::new(InvalidationStrategy::Manual);

    let c1 = versioned.get_config(config_path)?;
    println!("Before version bump → port = {:?}", c1.get("server.port"));

