```js
#!/usr/bin/env node

import { parseArgs } from 'node:util';
import { resolve } from 'node:path';
import { AuditLogger } from '../src/logger.js';
import { AuditQuery } from '../src/query.js';
import { IntegrityChecker } from '../src/integrity.js';
import { Formatter } from '../src/formatter.js';

const HELP = `
audit-logger — tamper-evident audit logging

USAGE
  audit <command> [options]

COMMANDS
  log         Record an audit event
  search      Query audit logs
  tail        Show recent entries
  verify      Check log integrity (hash chain)
  export      Export logs to JSON or CSV
  stats       Show summary statistics
  purge       Delete entries older than N days

GLOBAL OPTIONS
  --db <path>       Database file path (default: ./audit.db)
  --help            Show this help

EXAMPLES
  audit log --actor admin --action user.create --target user:42 --detail '{"email":"a@b.com"}'
  audit search --actor admin --from 2024-01-01 --to 2024-12-31
  audit tail --limit 20
  audit verify
  audit export --format csv --output report.csv --from 2024-06-01
  audit stats --from 2024-01-01
  audit purge --days 90 --confirm
`;

// ---------------------------------------------------------------------------
// Argument parsing
// ---------------------------------------------------------------------------

function parseCliArgs() {
  const command = process.argv[2];
  const raw = process.argv.slice(3);

  // Define all possible flags across commands
  const options = {
    db:      { type: 'string', default: './audit.db' },
    help:    { type: 'boolean', default: false },

    // log command
    actor:   { type: 'string' },
    action:  { type: 'string' },
    target:  { type: 'string', default: '' },
    detail:  { type: 'string', default: '{}' },
    source:  { type: 'string', default: '' },
    severity:{ type: 'string', default: 'info' },

    // search / export / stats / tail
    from:    { type: 'string', default: '' },
    to:      { type: 'string', default: '' },
    limit:   { type: 'string', default: '50' },
    offset:  { type: 'string', default: '0' },
    format:  { type: 'string', default: 'table' },
    output:  { type: 'string', default: '' },

    // purge
    days:    { type: 'string', default: '0' },
    confirm: { type: 'boolean', default: false },
  };

  const { values } = parseArgs({ args: raw, options, strict: false });
  return { command, flags: values };
}

// ---------------------------------------------------------------------------
// Command handlers
// ---------------------------------------------------------------------------

async function cmdLog(logger, flags) {
  if (!flags.actor || !flags.action) {
    console.error('Error: --actor and --action are required');
    process.exit(1);
  }

  let detail;
  try {
    detail = JSON.parse(flags.detail);
  } catch {
    detail = { raw: flags.detail };
  }

  const entry = logger.log({
    actor:    flags.actor,
    action:   flags.action,
    target:   flags.target || null,
    detail,
    source:   flags.source || null,
    severity: flags.severity || 'info',
  });

  console.log(`✓ Logged event #${entry.id} [${entry.hash.slice(0, 12)}…]`);
}

function cmdSearch(logger, flags) {
  const query = new AuditQuery(logger.store);
  const results = query.search({
    actor:  flags.actor || null,
    action: flags.action || null,
    target: flags.target || null,
    from:   flags.from || null,
    to:     flags.to || null,
    severity: flags.severity !== 'info' ? flags.severity : null,
    limit:  parseInt(flags.limit, 10),
    offset: parseInt(flags.offset, 10),
  });

  Formatter.output(results, flags.format);
}

function cmdTail(logger, flags) {
  const query = new AuditQuery(logger.store);
  const limit = parseInt(flags.limit, 10) || 20;
  const results = query.tail(limit);
  Formatter.output(results, flags.format === 'table' ? 'table' : flags.format);
}

function cmdVerify(logger, flags) {
  const checker = new IntegrityChecker(logger.store);
  const result = checker.verifyAll();

  if (result.valid) {
    console.log(`✓ All ${result.checked} entries verified — hash chain intact`);
  } else {
    console.error(`✗ Integrity failure at entry #${result.brokenAt}`);
    console.error(`  Expected: ${result.expected}`);
    console.error(`  Found:    ${result.found}`);
    process.exit(1);
  }
}

function cmdExport(logger, flags) {
  const query = new AuditQuery(logger.store);
  const results = query.search({
    from:  flags.from || null,
    to:    flags.to || null,
    limit: 100_000,
    offset: 0,
  });

  const format = flags.format || 'json';
  const content = Formatter.serialize(results, format);

  if (flags.output) {
    const { writeFileSync } = await import('node:fs');
    writeFileSync(resolve(flags.output), content, 'utf-8');
    console.log(`✓ Exported ${results.length} entries to ${flags.output}`);
  } else {
    process.stdout.write(content + '\n');
  }
}

function cmdStats(logger, flags) {
  const query = new AuditQuery(logger.store);
  const stats = query.stats({
    from: flags.from || null,
    to:   flags.to || null,
  });

  console.log('\n  Audit Log Statistics');
  console.log('  ────────────────────────────────────');
  console.log(`  Total entries:    ${stats.total}`);
  console.log(`  Unique actors:    ${stats.uniqueActors}`);
  console.log(`  Unique actions:   ${stats.uniqueActions}`);
  console.log(`  Date range:       ${stats.earliest || 'N/A'} → ${stats.latest || 'N/A'}`);
  console.log('\n  By severity:');
  for (const [sev, count] of Object.entries(stats.bySeverity)) {
    console.log(`    ${sev.padEnd(10)} ${count}`);
  }
  console.log('\n  Top actors:');
  for (const { actor, count } of stats.topActors) {
    console.log(`    ${actor.padEnd(20)} ${count}`);
  }
  console.log('\n  Top actions:');
  for (const { action, count } of stats.topActions) {
    console.log(`    ${action.padEnd(25)} ${count}`);
  }
  console.log('');
}

function cmdPurge(logger, flags) {
  const days = parseInt(flags.days, 10);
  if (!days || days <= 0) {
    console.error('Error: --days must be a positive integer');
    process.exit(1);
  }

  const query = new AuditQuery(logger.store);
  const cutoff = new Date(Date.now() - days * 86_400_000).toISOString();
  const count = query.countBefore(cutoff);

  if (count === 0) {
    console.log('Nothing to purge.');
    return;
  }

  if (!flags.confirm) {
    console.log(`This would delete ${count} entries before ${cutoff}`);
    console.log('Run again with --confirm to proceed.');
    return;
  }

  const deleted = logger.store.purgeBefore(cutoff);
  console.log(`✓ Purged ${deleted} entries`);
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

const { command, flags } = parseCliArgs();

if (!command || flags.help) {
  console.log(HELP);
  process.exit(0);
}

const dbPath = resolve(flags.db);
const logger = new AuditLogger(dbPath);

const commands = {
  log:    () => cmdLog(logger, flags),
  search: () => cmdSearch(logger, flags),
  tail:   () => cmdTail(logger, flags),
  verify: () => cmdVerify(logger, flags),
  export: () => cmdExport(logger, flags),
  stats:  () => cmdStats(logger, flags),
  purge:  () => cmdPurge(logger, flags),
};

if (!commands[command]) {
  console.error(`Unknown command: ${command}`);
  console.log(HELP);
  process.exit(1);
}

try {
  await commands[command]();
} catch (err) {
  console.error(`Error: ${err.message}`);
  process.exit(1);
} finally {
  logger.close();
}
