## src/store.js — SQLite Storage Layer

```js
import Database from 'better-sqlite3';

/**
 * Thin wrapper over SQLite. Handles schema, inserts, and raw queries.
 * All timestamps are ISO-8601 UTC strings.
 */
export class AuditStore {
  #db;

  constructor(dbPath) {
    this.#db = new Database(dbPath);
    this.#db.pragma('journal_mode = WAL');       // safe concurrent reads
    this.#db.pragma('foreign_keys = ON');
    this.#migrate();
  }

  // ── Schema ──────────────────────────────────────────────────────────────

  #migrate() {
    this.#db.exec(`
      CREATE TABLE IF NOT EXISTS audit_log (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp   TEXT    NOT NULL,
        actor       TEXT    NOT NULL,
        action      TEXT    NOT NULL,
        target      TEXT,
        detail      TEXT    NOT NULL DEFAULT '{}',
        source      TEXT,
        severity    TEXT    NOT NULL DEFAULT 'info',
        prev_hash   TEXT,
        hash        TEXT    NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_audit_actor     ON audit_log(actor);
      CREATE INDEX IF NOT EXISTS idx_audit_action    ON audit_log(action);
      CREATE INDEX IF NOT EXISTS idx_audit_timestamp ON audit_log(timestamp);
      CREATE INDEX IF NOT EXISTS idx_audit_severity  ON audit_log(severity);
    `);
  }

  // ── Write ───────────────────────────────────────────────────────────────

  insert(entry) {
    const stmt = this.#db.prepare(`
      INSERT INTO audit_log (timestamp, actor, action, target, detail, source, severity, prev_hash, hash)
      VALUES (@timestamp, @actor, @action, @target, @detail, @source, @severity, @prevHash, @hash)
    `);
    const info = stmt.run(entry);
    return info.lastInsertRowid;
  }

  // ── Read ────────────────────────────────────────────────────────────────

  getLastEntry() {
    return this.#db.prepare('SELECT * FROM audit_log ORDER BY id DESC LIMIT 1').get() || null;
  }

  getById(id) {
    return this.#db.prepare('SELECT * FROM audit_log WHERE id = ?').get(id);
  }

  /**
   * Dynamic filtered query. Only non-null filters are applied.
   */
  search({ actor, action, target, from, to, severity, limit, offset }) {
    const conditions = [];
    const params = {};

    if (actor)    { conditions.push('actor = @actor');           params.actor = actor; }
    if (action)   { conditions.push('action LIKE @action');      params.action = `%${action}%`; }
    if (target)   { conditions.push('target LIKE @target');      params.target = `%${target}%`; }
    if (severity) { conditions.push('severity = @severity');     params.severity = severity; }
    if (from)     { conditions.push('timestamp >= @from');       params.from = new Date(from).toISOString(); }
    if (to)       { conditions.push('timestamp <= @to');         params.to = new Date(to).toISOString(); }

    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
    const sql = `SELECT * FROM audit_log ${where} ORDER BY id DESC LIMIT @limit OFFSET @offset`;

    params.limit = limit || 50;
    params.offset = offset || 0;

    return this.#db.prepare(sql).all(params);
  }

  tail(limit) {
    return this.#db.prepare('SELECT * FROM audit_log ORDER BY id DESC LIMIT ?').all(limit);
  }

  /**
   * Iterate every row in insertion order — used for integrity verification.
   */
  *iterateAll() {
    const stmt = this.#db.prepare('SELECT * FROM audit_log ORDER BY id ASC');
    for (const row of stmt.iterate()) {
      yield row;
    }
  }

  count() {
    return this.#db.prepare('SELECT COUNT(*) AS n FROM audit_log').get().n;
  }

  countBefore(isoDate) {
    return this.#db.prepare('SELECT COUNT(*) AS n FROM audit_log WHERE timestamp < ?').get(isoDate).n;
  }

  purgeBefore(isoDate) {
    return this.#db.prepare('DELETE FROM audit_log WHERE timestamp < ?').run(isoDate).changes;
  }

  // ── Stats ───────────────────────────────────────────────────────────────

  stats({ from, to }) {
    const conditions = [];
    const params = {};
    if (from) { conditions.push('timestamp >= @from'); params.from = new Date(from).toISOString(); }
    if (to)   { conditions.push('timestamp <= @to');   params.to = new Date(to).toISOString(); }
    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

    const total = this.#db
      .prepare(`SELECT COUNT(*) AS n FROM audit_log ${where}`)
      .get(params).n;

    const uniqueActors = this.#db
      .prepare(`SELECT COUNT(DISTINCT actor) AS n FROM audit_log ${where}`)
      .get(params).n;

    const uniqueActions = this.#db
      .prepare(`SELECT COUNT(DISTINCT action) AS n FROM audit_log ${where}`)
      .get(params).n;

    const range = this.#db
      .prepare(`SELECT MIN(timestamp) AS earliest, MAX(timestamp) AS latest FROM audit_log ${where}`)
      .get(params);

    const bySeverityRows = this.#db
      .prepare(`SELECT severity, COUNT(*) AS n FROM audit_log ${where} GROUP BY severity ORDER BY n DESC`)
      .all(params);

    const topActors = this.#db
      .prepare(`SELECT actor, COUNT(*) AS count FROM audit_log ${where} GROUP BY actor ORDER BY count DESC LIMIT 10`)
      .all(params);

    const topActions = this.#db
      .prepare(`SELECT action, COUNT(*) AS count FROM audit_log ${where} GROUP BY action ORDER BY count DESC LIMIT 10`)
      .all(params);

    const bySeverity = {};
    for (const row of bySeverityRows) bySeverity[row.severity] = row.n;

    return {
      total,
      uniqueActors,
      uniqueActions,
      earliest: range.earliest,
      latest: range.latest,
      bySeverity,
      topActors,
      topActions,
    };
  }

  // ── Lifecycle ───────────────────────────────────────────────────────────

  close() {
    this.#db.close();
  }
}
