## src/logger.js — Core Audit Logger (Hash-Chained)

```js
import { createHash } from 'node:crypto';
import { AuditStore } from './store.js';

/**
 * Each entry's SHA-256 hash covers (prevHash + timestamp + actor + action + detail).
 * This creates a tamper-evident chain — changing any row breaks all subsequent hashes.
 */
export class AuditLogger {
  store;

  constructor(dbPath) {
    this.store = new AuditStore(dbPath);
  }

  /**
   * Write one audit event. Returns the stored entry with id & hash.
   */
  log({ actor, action, target = null, detail = {}, source = null, severity = 'info' }) {
    const VALID_SEVERITY = ['debug', 'info', 'warn', 'error', 'critical'];
    if (!VALID_SEVERITY.includes(severity)) {
      throw new Error(`Invalid severity "${severity}". Use: ${VALID_SEVERITY.join(', ')}`);
    }

    const timestamp = new Date().toISOString();
    const detailStr = typeof detail === 'string' ? detail : JSON.stringify(detail);

    // Chain: grab previous hash
    const last = this.store.getLastEntry();
    const prevHash = last?.hash ?? '0'.repeat(64);

    // Compute hash over the immutable fields
    const hash = AuditLogger.computeHash({ prevHash, timestamp, actor, action, detail: detailStr });

    const id = this.store.insert({
      timestamp,
      actor,
      action,
      target,
      detail: detailStr,
      source,
      severity,
      prevHash,
      hash,
    });

    return { id, timestamp, actor, action, target, detail: detailStr, source, severity, hash };
  }

  /**
   * Deterministic SHA-256 over canonical fields.
   */
  static computeHash({ prevHash, timestamp, actor, action, detail }) {
    const payload = [prevHash, timestamp, actor, action, detail].join('|');
    return createHash('sha256').update(payload).digest('hex');
  }

  close() {
    this.store.close();
  }
}
