## watcher.js — Core File Watcher

```javascript
const fs = require("fs");
const path = require("path");
const { EventEmitter } = require("events");

class FileWatcher extends EventEmitter {
  #watchDir;
  #debounceMs;
  #timers;      // debounce timers per file
  #snapshot;    // last known state of the directory
  #watcher;     // fs.watch instance

  constructor(watchDir, debounceMs = 300) {
    super();
    this.#watchDir = path.resolve(watchDir);
    this.#debounceMs = debounceMs;
    this.#timers = new Map();
    this.#snapshot = new Map();
    this.#watcher = null;
  }

  // Take a snapshot of current directory contents
  #takeSnapshot() {
    const snapshot = new Map();
    try {
      const files = fs.readdirSync(this.#watchDir);
      for (const file of files) {
        const fullPath = path.join(this.#watchDir, file);
        const stat = fs.statSync(fullPath);
        if (stat.isFile()) {
          snapshot.set(file, { size: stat.size, mtime: stat.mtimeMs });
        }
      }
    } catch (err) {
      this.emit("error", err);
    }
    return snapshot;
  }

  // Determine what changed by comparing snapshots
  #detectChange(filename) {
    const fullPath = path.join(this.#watchDir, filename);
    const existed = this.#snapshot.has(filename);

    try {
      const stat = fs.statSync(fullPath);
      const meta = { size: stat.size, mtime: stat.mtimeMs };

      if (!existed) {
        this.#snapshot.set(filename, meta);
        return "add";
      }

      const prev = this.#snapshot.get(filename);
      if (prev.mtime !== meta.mtime || prev.size !== meta.size) {
        this.#snapshot.set(filename, meta);
        return "change";
      }

      return null; // no real change
    } catch {
      // File no longer exists
      if (existed) {
        this.#snapshot.delete(filename);
        return "delete";
      }
      return null;
    }
  }

  // Debounced handler for raw fs.watch events
  #handleEvent(filename) {
    if (!filename) return;

    // Clear previous timer for this file
    if (this.#timers.has(filename)) {
      clearTimeout(this.#timers.get(filename));
    }

    // Set debounced handler
    const timer = setTimeout(() => {
      this.#timers.delete(filename);

      const eventType = this.#detectChange(filename);
      if (eventType) {
        const fullPath = path.join(this.#watchDir, filename);
        const ext = path.extname(filename).toLowerCase();

        this.emit(eventType, {
          filename,
          fullPath,
          ext,
          timestamp: Date.now(),
        });

        // Also emit a generic "file" event for all changes
        this.emit("file", {
          type: eventType,
          filename,
          fullPath,
          ext,
          timestamp: Date.now(),
        });
      }
    }, this.#debounceMs);

    this.#timers.set(filename, timer);
  }

  start() {
    // Ensure directory exists
    if (!fs.existsSync(this.#watchDir)) {
      fs.mkdirSync(this.#watchDir, { recursive: true });
    }

    // Initial snapshot
    this.#snapshot = this.#takeSnapshot();

    // Start native watcher
    this.#watcher = fs.watch(this.#watchDir, (eventType, filename) => {
      this.#handleEvent(filename);
    });

    this.#watcher.on("error", (err) => this.emit("error", err));

    this.emit("ready", {
      dir: this.#watchDir,
      files: this.#snapshot.size,
    });

    return this;
  }

  stop() {
    if (this.#watcher) {
      this.#watcher.close();
      this.#watcher = null;
    }

    // Clear all pending debounce timers
    for (const timer of this.#timers.values()) {
      clearTimeout(timer);
    }
    this.#timers.clear();

    this.emit("stop");
    return this;
  }

  // List currently tracked files
  listFiles() {
    return [...this.#snapshot.keys()];
  }
}

module.exports = FileWatcher;
```

## scheduler.js — Task Scheduler

```javascript
class TaskScheduler {
  #tasks;       // registered task handlers
  #queue;       // pending task queue
  #running;     // is a task currently executing
  #history;     // completed task log

  constructor() {
    this.#tasks = new Map();
    this.#queue = [];
    this.#running = false;
    this.#history = [];
  }

  // Register a named task handler
  register(name, handler) {
    if (typeof handler !== "function") {
      throw new TypeError(`Handler for "${name}" must be a function`);
    }
    this.#tasks.set(name, handler);
    return this;
  }

  // Add a task to the queue
  schedule(taskName, fileInfo) {
    if (!this.#tasks.has(taskName)) {
      console.warn(`⚠  No handler registered for task: ${taskName}`);
      return this;
    }

    this.#queue.push({
      taskName,
      fileInfo,
      scheduledAt: Date.now(),
    });

    // Process queue if idle
    this.#processQueue();
    return this;
  }

  // Process queued tasks sequentially
  async #processQueue() {
    if (this.#running || this.#queue.length === 0) return;

    this.#running = true;

    while (this.#queue.length > 0) {
      const job = this.#queue.shift();
      const handler = this.#tasks.get(job.taskName);

      const record = {
        taskName: job.taskName,
        filename: job.fileInfo.filename,
        scheduledAt: job.scheduledAt,
        startedAt: Date.now(),
        status: "running",
      };

      try {
        console.log(`▶  Running "${job.taskName}" on ${job.fileInfo.filename}`);
        await handler(job.fileInfo);
        record.status = "done";
      } catch (err) {
        record.status = "failed";
        record.error = err.message;
        console.error(`✖  Task "${job.taskName}" failed: ${err.message}`);
      } finally {
        record.finishedAt = Date.now();
        record.duration = record.finishedAt - record.startedAt;
        this.#history.push(record);
      }
    }

    this.#running = false;
  }

  // Get task execution history
  getHistory(limit = 10) {
    return this.#history.slice(-limit);
  }

  // Get pending queue size
  get pending() {
    return this.#queue.length;
  }
}

module.exports = TaskScheduler;
```

## index.js — Entry Point

```javascript
const fs = require("fs");
const FileWatcher = require("./watcher");
const TaskScheduler = require("./scheduler");
const config = require("./config.json");

// --- Initialize ---
const watcher = new FileWatcher(config.watchDir, config.debounceMs);
const scheduler = new TaskScheduler();

// --- Register task handlers ---

scheduler.register("processText", async (fileInfo) => {
  const content = fs.readFileSync(fileInfo.fullPath, "utf-8");
  const lines = content.split("\n").length;
  const words = content.split(/\s+/).filter(Boolean).length;
  console.log(`   📄 Text: ${lines} lines, ${words} words`);
});

scheduler.register("processJSON", async (fileInfo) => {
  const raw = fs.readFileSync(fileInfo.fullPath, "utf-8");
  const data = JSON.parse(raw);
  const keys = Object.keys(data).length;
  console.log(`   📋 JSON: ${keys} top-level keys`);
});

scheduler.register("processCSV", async (fileInfo) => {
  const content = fs.readFileSync(fileInfo.fullPath, "utf-8");
  const rows = content.trim().split("\n");
  const cols = rows[0] ? rows[0].split(",").length : 0;
  console.log(`   📊 CSV: ${rows.length} rows, ${cols} columns`);
});

scheduler.register("processLog", async (fileInfo) => {
  const content = fs.readFileSync(fileInfo.fullPath, "utf-8");
  const errors = (content.match(/error/gi) || []).length;
  const warnings = (content.match(/warn/gi) || []).length;
  console.log(`   📝 Log: ${errors} errors, ${warnings} warnings`);
});

// --- Wire watcher events to scheduler ---

watcher.on("ready", (info) => {
  console.log(`\n👁  Watching: ${info.dir}`);
  console.log(`   Found ${info.files} existing file(s)\n`);
  console.log("   Drop files into ./watched to trigger tasks");
  console.log("   Press Ctrl+C to stop\n");
});

watcher.on("add", (fileInfo) => {
  console.log(`\n✚  Added: ${fileInfo.filename}`);
  const taskName = config.tasks[fileInfo.ext];
  if (taskName) {
    scheduler.schedule(taskName, fileInfo);
  } else {
    console.log(`   (no task mapped for ${fileInfo.ext || "no extension"})`);
  }
});

watcher.on("change", (fileInfo) => {
  console.log(`\n✎  Changed: ${fileInfo.filename}`);
  const taskName = config.tasks[fileInfo.ext];
  if (taskName) {
    scheduler.schedule(taskName, fileInfo);
  }
});

watcher.on("delete", (fileInfo) => {
  console.log(`\n✖  Deleted: ${fileInfo.filename}`);
});

watcher.on("error", (err) => {
  console.error(`\n⚠  Watcher error: ${err.message}`);
});

// --- Graceful shutdown ---

process.on("SIGINT", () => {
  console.log("\n\n🛑 Shutting down...");

  const history = scheduler.getHistory(20);
  if (history.length > 0) {
    console.log("\n── Task History ──");
    for (const h of history) {
      const symbol = h.status === "done" ? "✔" : "✖";
      console.log(`  ${symbol} ${h.taskName} → ${h.filename} (${h.duration}ms)`);
    }
  }

  watcher.stop();
  process.exit(0);
});

// --- Start ---
watcher.start();
```

## How It Works

```
fs.watch (OS events)
    │
    ▼
FileWatcher (debounce + snapshot diffing)
    │
    ├── emit("add",    fileInfo)
    ├── emit("change", fileInfo)
    └── emit("delete", fileInfo)
            │
            ▼
    config.json maps extension → task name
            │
            ▼
TaskScheduler (sequential async queue)
    │
    ├── processText()
    ├── processJSON()
    ├── processCSV()
    └── processLog()
```

