```

## Key Design Decisions

| Concern | Approach |
|---|---|
| **Debouncing** | Per-file timers prevent duplicate events from rapid saves |
| **Event accuracy** | Snapshot diffing distinguishes add/change/delete (fs.watch is unreliable alone) |
| **Task ordering** | Sequential queue prevents race conditions on shared resources |
| **Extension mapping** | `config.json` maps file types to handler names — no code changes needed |
| **Cleanup** | `SIGINT` handler closes the watcher and prints execution history |

# Chat Moderation File Watcher

## `moderator.js`

```javascript
const fs = require("fs");
const path = require("path");

// --- Configuration ---
const WATCH_FILE = path.join(__dirname, "chat.log");
const FLAGGED_FILE = path.join(__dirname, "flagged.log");

const BANNED_WORDS = ["spam", "scam", "hack", "cheat"];
const MAX_CAPS_RATIO = 0.7;
const MAX_MESSAGE_LENGTH = 500;
const SPAM_INTERVAL_MS = 2000;

// --- State ---
let lastSize = 0;
const userTimestamps = new Map();

// Ensure files exist
if (!fs.existsSync(WATCH_FILE)) {
  fs.writeFileSync(WATCH_FILE, "");
}

// --- Moderation Checks ---
function checkBannedWords(message) {
  const lower = message.toLowerCase();
  const found = BANNED_WORDS.filter((word) => lower.includes(word));
  return found.length > 0 ? `Banned words: [${found.join(", ")}]` : null;
}

function checkExcessiveCaps(message) {
  const letters = message.replace(/[^a-zA-Z]/g, "");
  if (letters.length < 5) return null;

  const upperCount = (message.match(/[A-Z]/g) || []).length;
  const ratio = upperCount / letters.length;

  return ratio > MAX_CAPS_RATIO ? `Excessive caps (${(ratio * 100).toFixed(0)}%)` : null;
}

function checkMessageLength(message) {
  return message.length > MAX_MESSAGE_LENGTH
    ? `Message too long (${message.length}/${MAX_MESSAGE_LENGTH})`
    : null;
}

function checkSpam(username) {
  const now = Date.now();
  const lastTime = userTimestamps.get(username);
  userTimestamps.set(username, now);

  if (lastTime && now - lastTime < SPAM_INTERVAL_MS) {
    return `Spam detected (${now - lastTime}ms since last message)`;
  }
  return null;
}

function moderateMessage(line) {
  // Expected format: "[timestamp] username: message"
  const match = line.match(/^\[(.+?)\]\s+(\w+):\s+(.+)$/);
  if (!match) return null;

  const [, timestamp, username, message] = match;
  const violations = [];

  const checks = [
    checkBannedWords(message),
    checkExcessiveCaps(message),
    checkMessageLength(message),
    checkSpam(username),
  ];

  checks.forEach((result) => {
    if (result) violations.push(result);
  });

  if (violations.length > 0) {
    return {
      timestamp,
      username,
      message,
      violations,
    };
  }

  return null;
}

// --- Flag Logging ---
function logFlagged(entry) {
  const logLine =
    `[FLAGGED ${new Date().toISOString()}] ` +
    `User: ${entry.username} | ` +
    `Violations: ${entry.violations.join("; ")} | ` +
    `Message: "${entry.message}"\n`;

  fs.appendFileSync(FLAGGED_FILE, logLine);
}

// --- File Watching ---
function processNewContent() {
  const stats = fs.statSync(WATCH_FILE);

  if (stats.size < lastSize) {
    // File was truncated/reset
    lastSize = 0;
  }

  if (stats.size === lastSize) return;

  // Read only the new bytes
  const buffer = Buffer.alloc(stats.size - lastSize);
  const fd = fs.openSync(WATCH_FILE, "r");
  fs.readSync(fd, buffer, 0, buffer.length, lastSize);
  fs.closeSync(fd);

  lastSize = stats.size;

  const newContent = buffer.toString("utf-8");
  const lines = newContent.split("\n").filter((line) => line.trim() !== "");

  lines.forEach((line) => {
    const result = moderateMessage(line);
    if (result) {
      console.log(`⚠️  FLAGGED — ${result.username}: "${result.message}"`);
      result.violations.forEach((v) => console.log(`   → ${v}`));
      console.log();
      logFlagged(result);
    } else if (line.match(/^\[.+?\]\s+\w+:\s+.+$/)) {
      console.log(`✅ OK — ${line}`);
    }
  });
}

// --- Start Watcher ---
console.log(`👁️  Watching: ${WATCH_FILE}`);
console.log(`📋 Flagged messages logged to: ${FLAGGED_FILE}`);
console.log(`   Banned words: ${BANNED_WORDS.join(", ")}`);
console.log(`   Max caps ratio: ${MAX_CAPS_RATIO * 100}%`);
console.log(`   Max message length: ${MAX_MESSAGE_LENGTH}`);
console.log(`   Spam interval: ${SPAM_INTERVAL_MS}ms`);
console.log("-------------------------------------------\n");

// Get initial size so we only process new content
lastSize = fs.existsSync(WATCH_FILE) ? fs.statSync(WATCH_FILE).size : 0;

fs.watch(WATCH_FILE, (eventType) => {
  if (eventType === "change") {
    processNewContent();
  }
});
```

