## Core Implementation

### `src/cache/CacheClient.js` — Unified Cache Interface

```javascript
/**
 * Abstract cache client supporting multiple backends.
 * Provides pattern-based key scanning and batch operations.
 */
class CacheClient {
  constructor(adapter, options = {}) {
    this.adapter = adapter;
    this.namespace = options.namespace || '';
    this.logger = options.logger || console;
    this.stats = { hits: 0, misses: 0, invalidations: 0 };
  }

  /** Prefix a key with the configured namespace */
  _prefixKey(key) {
    return this.namespace ? `${this.namespace}:${key}` : key;
  }

  async get(key) {
    const value = await this.adapter.get(this._prefixKey(key));
    value !== null ? this.stats.hits++ : this.stats.misses++;
    return value;
  }

  async set(key, value, ttlSeconds) {
    return this.adapter.set(this._prefixKey(key), value, ttlSeconds);
  }

  async del(key) {
    this.stats.invalidations++;
    return this.adapter.del(this._prefixKey(key));
  }

  /**
   * Delete all keys matching a glob pattern (e.g., "user:*")
   * Returns the count of deleted keys.
   */
  async deleteByPattern(pattern) {
    const prefixedPattern = this._prefixKey(pattern);
    const keys = await this.adapter.scan(prefixedPattern);

    if (keys.length === 0) return 0;

    this.logger.info(
      `[CacheClient] Deleting ${keys.length} keys matching "${prefixedPattern}"`
    );

    // Delete in batches to avoid overwhelming the cache backend
    const BATCH_SIZE = 500;
    let deleted = 0;

    for (let i = 0; i < keys.length; i += BATCH_SIZE) {
      const batch = keys.slice(i, i + BATCH_SIZE);
      await this.adapter.delMulti(batch);
      deleted += batch.length;
    }

    this.stats.invalidations += deleted;
    return deleted;
  }

  /**
   * Delete multiple explicit keys at once.
   */
  async deleteMany(keys) {
    if (keys.length === 0) return 0;

    const prefixed = keys.map((k) => this._prefixKey(k));
    await this.adapter.delMulti(prefixed);
    this.stats.invalidations += prefixed.length;
    return prefixed.length;
  }

  /** Flush the entire namespace (nuclear option) */
  async flushNamespace() {
    return this.deleteByPattern('*');
  }

  getStats() {
    return { ...this.stats };
  }

  async disconnect() {
    return this.adapter.disconnect();
  }
}

module.exports = CacheClient;
```

### `src/cache/RedisAdapter.js` — Redis Backend

```javascript
const Redis = require('ioredis');

/**
 * Redis adapter implementing the interface expected by CacheClient.
 * Uses SCAN (not KEYS) for production-safe pattern matching.
 */
class RedisAdapter {
  constructor(redisOptions = {}) {
    this.client = new Redis({
      host: redisOptions.host || '127.0.0.1',
      port: redisOptions.port || 6379,
      password: redisOptions.password,
      db: redisOptions.db || 0,
      keyPrefix: redisOptions.keyPrefix || '',
      retryStrategy: (times) => Math.min(times * 200, 5000),
      ...redisOptions,
    });
  }

  async get(key) {
    const raw = await this.client.get(key);
    if (raw === null) return null;
    try {
      return JSON.parse(raw);
    } catch {
      return raw;
    }
  }

  async set(key, value, ttlSeconds) {
    const serialized = JSON.stringify(value);
    if (ttlSeconds) {
      return this.client.setex(key, ttlSeconds, serialized);
    }
    return this.client.set(key, serialized);
  }

  async del(key) {
    return this.client.del(key);
  }

  async delMulti(keys) {
    if (keys.length === 0) return 0;
    // Use pipeline for efficient batch deletion
    const pipeline = this.client.pipeline();
    keys.forEach((key) => pipeline.del(key));
    const results = await pipeline.exec();
    return results.length;
  }

  /**
   * Production-safe key scanning using SCAN (non-blocking).
   * Never use KEYS in production — it blocks the Redis event loop.
   */
  async scan(pattern, batchSize = 200) {
    const keys = [];
    let cursor = '0';

    do {
      const [nextCursor, batch] = await this.client.scan(
        cursor,
        'MATCH',
        pattern,
        'COUNT',
        batchSize
      );
      cursor = nextCursor;
      keys.push(...batch);
    } while (cursor !== '0');

    return keys;
  }

  async disconnect() {
    await this.client.quit();
  }
}

module.exports = RedisAdapter;
```

### `src/invalidation/InvalidationStrategy.js` — Strategy Definitions

```javascript
/**
 * Each strategy describes HOW to invalidate cache entries
 * affected by a specific type of data change.
 */

/** Delete all keys matching one or more glob patterns */
class PatternStrategy {
  constructor(patterns) {
    this.type = 'pattern';
    this.patterns = Array.isArray(patterns) ? patterns : [patterns];
  }
}

/** Delete an explicit list of known keys */
class ExplicitKeyStrategy {
  constructor(keys) {
    this.type = 'explicit';
    this.keys = Array.isArray(keys) ? keys : [keys];
  }
}

/** Delete keys generated by a function (for dynamic/computed keys) */
class ComputedStrategy {
  constructor(computeFn) {
    if (typeof computeFn !== 'function') {
      throw new TypeError('ComputedStrategy requires a function');
    }
    this.type = 'computed';
    this.computeFn = computeFn;
  }
}

/** Tag-based: delete every key associated with one or more tags */
class TagStrategy {
  constructor(tags) {
    this.type = 'tag';
    this.tags = Array.isArray(tags) ? tags : [tags];
  }
}

/** Delete everything — use only when a migration is too broad to target */
class FlushAllStrategy {
  constructor() {
    this.type = 'flush';
  }
}

module.exports = {
  PatternStrategy,
  ExplicitKeyStrategy,
  ComputedStrategy,
  TagStrategy,
  FlushAllStrategy,
};
```

### `src/invalidation/InvalidationPlanner.js` — Executes Strategies

```javascript
/**
 * Executes a list of invalidation strategies against a CacheClient.
 * Collects metrics and produces an audit report.
 */
class InvalidationPlanner {
  constructor(cacheClient, options = {}) {
    this.cache = cacheClient;
    this.logger = options.logger || console;
    this.tagIndex = options.tagIndex || null; // optional tag→keys map
    this.dryRun = options.dryRun || false;
  }

  /**
   * Execute all strategies and return a summary report.
   * @param {Array} strategies - InvalidationStrategy instances
   * @param {object} context   - Migration context (passed to computed fns)
   */
  async execute(strategies, context = {}) {
    const report = {
      totalDeleted: 0,
      details: [],
      errors: [],
      startedAt: new Date().toISOString(),
      dryRun: this.dryRun,
    };

    for (const strategy of strategies) {
      try {
        const result = await this._executeOne(strategy, context);
        report.details.push(result);
        report.totalDeleted += result.deletedCount;
      } catch (err) {
        const errorDetail = {
          strategy: strategy.type,
          error: err.message,
          stack: err.stack,
        };
        report.errors.push(errorDetail);
        this.logger.error('[InvalidationPlanner] Strategy failed:', errorDetail);
      }
    }

    report.completedAt = new Date().toISOString();
    return report;
  }

  async _executeOne(strategy, context) {
    const result = {
      strategy: strategy.type,
      deletedCount: 0,
      keysAffected: [],
    };

    switch (strategy.type) {
      case 'pattern': {
        for (const pattern of strategy.patterns) {
          this.logger.info(`[Planner] Invalidating pattern: ${pattern}`);
          if (!this.dryRun) {
            const count = await this.cache.deleteByPattern(pattern);
            result.deletedCount += count;
          }
          result.keysAffected.push(`pattern:${pattern}`);
        }
        break;
      }

      case 'explicit': {
        this.logger.info(
          `[Planner] Invalidating ${strategy.keys.length} explicit keys`
        );
        if (!this.dryRun) {
          result.deletedCount = await this.cache.deleteMany(strategy.keys);
        }
        result.keysAffected = strategy.keys;
        break;
      }

      case 'computed': {
        const keys = await strategy.computeFn(context);
        this.logger.info(
          `[Planner] Computed ${keys.length} keys to invalidate`
        );
        if (!this.dryRun) {
          result.deletedCount = await this.cache.deleteMany(keys);
        }
        result.keysAffected = keys;
        break;
      }

      case 'tag': {
        if (!this.tagIndex) {
          throw new Error('Tag-based invalidation requires a tagIndex');
        }
        for (const tag of strategy.tags) {
          const keys = await this.tagIndex.getKeysByTag(tag);
          this.logger.info(
            `[Planner] Tag "${tag}" maps to ${keys.length} keys`
          );
          if (!this.dryRun) {
            const count = await this.cache.deleteMany(keys);
            result.deletedCount += count;
          }
          result.keysAffected.push(...keys);
        }
        break;
      }

      case 'flush': {
        this.logger.warn('[Planner] Flushing entire cache namespace!');
        if (!this.dryRun) {
          result.deletedCount = await this.cache.flushNamespace();
        }
        result.keysAffected = ['*'];
        break;
      }

      default:
        throw new Error(`Unknown strategy type: ${strategy.type}`);
    }

    return result;
  }
}

module.exports = InvalidationPlanner;
```

### `src/migrations/BaseMigration.js` — Migration Contract

```javascript
/**
 * Every migration must extend this base class and implement:
 *   - up(context)                     — apply the migration
 *   - down(context)                   — revert the migration
 *   - getCacheInvalidationStrategies() — declare what to invalidate
 */
class BaseMigration {
  constructor() {
    if (new.target === BaseMigration) {
      throw new Error('BaseMigration is abstract — extend it');
    }
  }

  /** Unique, sortable identifier (e.g., "001_rename_user_fields") */
  get id() {
    throw new Error('Migration must define an `id` getter');
  }

  /** Human-readable description */
  get description() {
    return '';
  }

  /** Apply the migration */
  async up(/* context */) {
    throw new Error('Migration must implement up()');
  }

  /** Revert the migration */
  async down(/* context */) {
    throw new Error('Migration must implement down()');
  }

  /**
   * Return an array of InvalidationStrategy instances.
   * Called AFTER up() succeeds (or AFTER down() on rollback).
   */
  getCacheInvalidationStrategies() {
    return [];
  }

  /**
   * Optional: separate strategies when rolling back,
   * defaults to the same strategies as up().
   */
  getRollbackInvalidationStrategies() {
    return this.getCacheInvalidationStrategies();
  }
}

module.exports = BaseMigration;
```

### `src/migrations/MigrationRegistry.js` — Tracks Applied Migrations

```javascript
/**
 * Persists which migrations have been applied.
 * This example uses a simple JSON table via a db adapter,
 * but you could back it with Postgres, SQLite, etc.
 */
class MigrationRegistry {
  constructor(db, tableName = '_migrations') {
    this.db = db;
    this.tableName = tableName;
  }

  async initialize() {
    await this.db.query(`
      CREATE TABLE IF NOT EXISTS ${this.tableName} (
        id          VARCHAR(255) PRIMARY KEY,
        description TEXT,
        applied_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        checksum    VARCHAR(64),
        status      VARCHAR(20) DEFAULT 'applied'
      )
    `);
  }

  async isApplied(migrationId) {
    const rows = await this.db.query(
      `SELECT id FROM ${this.tableName} WHERE id = $1 AND status = 'applied'`,
      [migrationId]
    );
    return rows.length > 0;
  }

  async markApplied(migrationId, description, checksum) {
    await this.db.query(
      `INSERT INTO ${this.tableName} (id, description, checksum, status)
       VALUES ($1, $2, $3, 'applied')
       ON CONFLICT (id) DO UPDATE SET status = 'applied', applied_at = CURRENT_TIMESTAMP`,
      [migrationId, description, checksum]
    );
  }

  async markRolledBack(migrationId) {
    await this.db.query(
      `UPDATE ${this.tableName} SET status = 'rolled_back' WHERE id = $1`,
      [migrationId]
    );
  }

  async getApplied() {
    return this.db.query(
      `SELECT * FROM ${this.tableName} WHERE status = 'applied' ORDER BY id`
    );
  }
}

module.exports = MigrationRegistry;
```

