    const results = [];

    for (const migration of migrations) {
      const already = await this.registry.isApplied(migration.id);
      if (already) {
        this.logger.info(`[Runner] Skipping "${migration.id}" (already applied)`);
        continue;
      }

      const result = await this._executeMigration(migration, 'up', context);
      results.push(result);

      if (result.status === 'failed') {
        this.logger.error(`[Runner] Stopping — "${migration.id}" failed`);
        break; // halt on first failure
      }
