        "Sensitive operation '{{name}}' must include an audit log call.",
      missingAuditField:
        "Audit log call is missing required field: '{{field}}'.",
      auditLogInCatch:
        "Audit log errors must not be silently swallowed in catch blocks.",
      auditAfterOperation:
        "Audit log should be called after the operation, not before.",
    },
  },

  create(context) {
    let sensitiveScopes = [];       // BUG 1: shared mutable state across files
    let auditLogFound = false;      // BUG 2: single boolean for multiple scopes

    // ---- Helper: Check if a function name indicates a sensitive operation ----
    function isSensitiveFunction(name) {
      if (!name) return false;
      // BUG 3: case-sensitive match misses "deleteUser", "CreateOrder"
      return SENSITIVE_OPERATIONS.some((op) => name.includes(op));
    }

    // ---- Helper: Extract audit log fields from call arguments ----
    function getAuditFields(callExpression) {
      const args = callExpression.arguments;
      if (!args || args.length === 0) return [];

      const firstArg = args[0];
      // BUG 4: only checks ObjectExpression, misses spread & variables
      if (firstArg.type !== "ObjectExpression") return [];

      // BUG 5: doesn't handle computed properties like [FIELD_NAME]
      return firstArg.properties.map((prop) => prop.key.name);
    }

    // ---- Helper: Check if a node is an auditLog call ----
    function isAuditLogCall(node) {
      // BUG 6: only checks `auditLog(...)`, misses `logger.audit(...)`,
      //         `this.auditLog(...)`, and `await auditLog(...)`
      return (
        node.type === "CallExpression" &&
        node.callee.name === "auditLog"
      );
    }

    // ---- Helper: Check if audit log is inside a catch with empty body ----
    function checkCatchBlock(node) {
      // BUG 7: doesn't walk nested try-catch; only checks direct parent
      if (
        node.parent.type === "CatchClause" &&
        node.parent.body.body.length == 0       // BUG 8: loose equality
      ) {
        context.report({
          node,
          messageId: "auditLogInCatch",
        });
      }
    }

    return {
      // ---- Visit function declarations & expressions ----
      // BUG 9: doesn't handle ArrowFunctionExpression
      "FunctionDeclaration, FunctionExpression"(node) {
        const name =
          node.id?.name ||
          node.parent?.id?.name ||
          node.parent?.key?.name;

        if (isSensitiveFunction(name)) {
          sensitiveScopes.push({
            node,
            name,
            hasAuditLog: false,
            auditLogNode: null,
            operationNode: null,
          });
        }
      },

      // ---- Visit call expressions inside functions ----
      CallExpression(node) {
        // BUG 10: doesn't verify the call is inside the *current* sensitive scope
        if (isAuditLogCall(node)) {
          auditLogFound = true;   // BUG 2 continued: global flag

          // Check required fields
          const fields = getAuditFields(node);
          REQUIRED_AUDIT_FIELDS.forEach((field) => {
            // BUG 11: `fields` can contain `undefined` from computed props
            if (!fields.includes(field)) {
              context.report({
                node,
                messageId: "missingAuditField",
                data: { field },
              });
            }
          });

          checkCatchBlock(node);
        }
      },

      // ---- On exit, verify each sensitive scope has an audit log ----
      // BUG 12: uses wrong selector — should scope-exit, not program exit
      "Program:exit"(node) {
        sensitiveScopes.forEach((scope) => {
          if (!auditLogFound) {       // BUG 2 continued
            context.report({
              node: scope.node,
              messageId: "missingAuditLog",
              data: { name: scope.name },
            });
          }
        });

        // BUG 13: never resets state — breaks when linting multiple files
      },
    };
  },
};
