// ✅ FIXED: rules/require-audit-logging.js
"use strict";

const SENSITIVE_OPERATIONS = ["delete", "update", "create", "patch"];
const REQUIRED_AUDIT_FIELDS = ["userId", "action", "resource", "timestamp"];
const AUDIT_CALL_PATTERNS = ["auditLog", "audit"]; // configurable names

module.exports = {
  meta: {
    type: "problem",
    docs: {
      description: "Enforce audit logging on sensitive operations",
      category: "Security",
      recommended: true,
    },
    // FIX 14: Allow users to configure audit function names & required fields
    schema: [
      {
        type: "object",
        properties: {
          auditFunctionNames: {
            type: "array",
            items: { type: "string" },
          },
          requiredFields: {
            type: "array",
            items: { type: "string" },
          },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      missingAuditLog:
        "Sensitive operation '{{name}}' must include an audit log call.",
      missingAuditField:
        "Audit log call is missing required field: '{{field}}'.",
      auditLogInCatch:
        "Audit log errors must not be silently swallowed in catch blocks.",
    },
  },

  create(context) {
    // FIX 14: Merge user options with defaults
    const options = context.options[0] || {};
    const auditFunctionNames =
      options.auditFunctionNames || AUDIT_CALL_PATTERNS;
    const requiredFields = options.requiredFields || REQUIRED_AUDIT_FIELDS;

    // FIX 1 & 13: Use a stack scoped to this `create()` invocation
    // Each entry tracks one sensitive function scope
    const scopeStack = [];

    // =========================================================================
    //  Helpers
    // =========================================================================

    /**
     * FIX 3: Case-insensitive check for sensitive operation names
     */
    function isSensitiveFunction(name) {
      if (!name) return false;
      const lower = name.toLowerCase();
      return SENSITIVE_OPERATIONS.some((op) => lower.includes(op));
    }

    /**
     * FIX 6: Resolve the callee name from multiple patterns:
     *   - auditLog(...)              → "auditLog"
     *   - logger.audit(...)          → "audit"
     *   - this.auditLog(...)         → "auditLog"
     *   - await auditLog(...)        → handled by unwrapping AwaitExpression
     */
    function getCalleeName(callee) {
      switch (callee.type) {
        case "Identifier":
          return callee.name;
        case "MemberExpression":
          // e.g. logger.audit or this.auditLog
          return callee.property?.type === "Identifier"
            ? callee.property.name
            : null;
        default:
          return null;
      }
    }

    /**
     * FIX 6 continued: Determine if a CallExpression is an audit log call
     */
    function isAuditLogCall(node) {
      if (node.type !== "CallExpression") return false;

      const calleeName = getCalleeName(node.callee);
      return calleeName !== null && auditFunctionNames.includes(calleeName);
    }

    /**
     * FIX 4 & 5: Safely extract property names from the first argument.
     * Returns `null` when the argument is not statically analyzable,
     * meaning we should skip field validation (not give false positives).
     */
    function getAuditFields(callExpression) {
      const args = callExpression.arguments;
      if (!args || args.length === 0) return null;

      const firstArg = args[0];

      // If the argument is a variable or function call, we can't statically check
      if (firstArg.type !== "ObjectExpression") {
        return null; // FIX 4: return null so caller knows to skip field check
      }

      const fields = [];
      for (const prop of firstArg.properties) {
        if (prop.type === "SpreadElement") {
          // Can't statically analyze spread — skip field validation entirely
          return null;
        }
        // FIX 5: Handle Identifier keys and Literal keys (e.g., "userId")
        if (prop.key) {
          if (prop.key.type === "Identifier" && !prop.computed) {
            fields.push(prop.key.name);
          } else if (prop.key.type === "Literal") {
            fields.push(String(prop.key.value));
          }
          // computed dynamic keys → skip (we can't resolve at lint time)
        }
      }
      return fields;
    }

    /**
     * FIX 7: Walk up the AST to find if the node is inside a catch block
     * whose body only contains the audit call (swallowed error).
     */
    function isInsideSilentCatch(node) {
      let current = node.parent;
      while (current) {
        if (current.type === "CatchClause") {
          const bodyStatements = current.body.body;
          // FIX 8: strict equality
          // A "silent" catch has 0 or 1 statements (only the audit call itself)
          if (bodyStatements.length === 0) return true;
          if (
            bodyStatements.length === 1 &&
            isNodeOrParentOf(bodyStatements[0], node)
          ) {
            return true;
          }
          break; // stop at the nearest catch
        }
        current = current.parent;
      }
      return false;
    }

    /**
     * Check if `ancestor` is or contains `target`
     */
    function isNodeOrParentOf(ancestor, target) {
      if (ancestor === target) return true;
      if (
        ancestor.type === "ExpressionStatement" &&
        ancestor.expression === target
      ) {
        return true;
      }
      return false;
    }

    /**
     * Get the function name from a node (handles multiple patterns)
     */
    function getFunctionName(node) {
      // Named function declaration: function deleteUser() {}
      if (node.id?.name) return node.id.name;

      const parent = node.parent;
      if (!parent) return null;

      // Variable declarator: const deleteUser = function() {} | () => {}
      if (parent.type === "VariableDeclarator" && parent.id?.name) {
        return parent.id.name;
      }

      // Object/class method: { deleteUser() {} } or class { deleteUser() {} }
      if (
        (parent.type === "Property" || parent.type === "MethodDefinition") &&
        parent.key?.type === "Identifier"
      ) {
        return parent.key.name;
      }

      // Assignment: module.exports.deleteUser = () => {}
      if (
        parent.type === "AssignmentExpression" &&
        parent.left?.type === "MemberExpression" &&
        parent.left.property?.type === "Identifier"
      ) {
        return parent.left.property.name;
      }

      return null;
    }

    /**
     * FIX 10: Check if a node is inside the given function scope node
     */
    function isInsideFunction(node, fnNode) {
      let current = node.parent;
      while (current) {
        if (current === fnNode) return true;
        // Stop at the nearest enclosing function boundary
        if (
          current.type === "FunctionDeclaration" ||
          current.type === "FunctionExpression" ||
          current.type === "ArrowFunctionExpression"
        ) {
          return current === fnNode;
        }
        current = current.parent;
      }
      return false;
    }

    // =========================================================================
    //  Visitor
    // =========================================================================

    // FIX 9: Include ArrowFunctionExpression in the selector
    const FUNCTION_SELECTOR = [
      "FunctionDeclaration",
      "FunctionExpression",
      "ArrowFunctionExpression",
    ].join(",");

    return {
      // ---- Enter a function scope ----
      [FUNCTION_SELECTOR](node) {
        const name = getFunctionName(node);

        if (isSensitiveFunction(name)) {
          // FIX 1 & 2: push per-scope tracking onto a stack
          scopeStack.push({
            node,
            name,
            hasAuditLog: false,
          });
        }
      },

      // ---- Check every call expression ----
      CallExpression(node) {
        if (!isAuditLogCall(node)) return;

        // FIX 10: Find which sensitive scope (if any) this call belongs to
        for (let i = scopeStack.length - 1; i >= 0; i--) {
          const scope = scopeStack[i];
          if (isInsideFunction(node, scope.node)) {
            scope.hasAuditLog = true;
            break;
          }
        }

        // ---- Validate required fields ----
        const fields = getAuditFields(node);
        // FIX 4: only report missing fields when we can statically analyze
        if (fields !== null) {
          for (const field of requiredFields) {
            if (!fields.includes(field)) {
              context.report({
                node,
                messageId: "missingAuditField",
                data: { field },
              });
            }
          }
        }

        // FIX 7 & 8: check for swallowed errors in catch blocks
        if (isInsideSilentCatch(node)) {
          context.report({
            node,
            messageId: "auditLogInCatch",
          });
        }
      },

      // FIX 12: Report at function exit, not program exit
      [`${FUNCTION_SELECTOR}:exit`](node) {
        if (scopeStack.length === 0) return;

        const currentScope = scopeStack[scopeStack.length - 1];
        if (currentScope.node !== node) return;

        // Pop the scope and check
        const scope = scopeStack.pop();
        if (!scope.hasAuditLog) {
          context.report({
            node: scope.node,
            messageId: "missingAuditLog",
            data: { name: scope.name },
          });
        }
      },

      // FIX 13: Clean up (safety net — stack should be empty by now)
      "Program:exit"() {
        scopeStack.length = 0;
      },
    };
  },
};
