```javascript
// src/ConfigParser.js
import { readFile } from "fs/promises";
import { existsSync } from "fs";
import { resolve } from "path";

// ─── Schema Definition for Validation ────────────────────────────
const SCHEMA = {
  version: { type: "string", required: true },
  settings: {
    type: "object",
    required: true,
    properties: {
      maxRetries:   { type: "number", min: 0, max: 10 },
      retryDelayMs: { type: "number", min: 100, max: 60000 },
      logLevel:     { type: "string", enum: ["debug", "info", "warn", "error"] },
      batchSize:    { type: "number", min: 1, max: 1000 },
      timeoutMs:    { type: "number", min: 1000, max: 30000 },
    },
  },
  events: {
    type: "object",
    required: true,
    valueSchema: {
      enabled:  { type: "boolean", required: true },
      priority: { type: "string", required: true, enum: ["critical", "high", "medium", "low"] },
      handlers: { type: "array", required: true, minLength: 1 },
    },
  },
};

const VALID_OPERATORS = new Set(["eq", "neq", "gt", "gte", "lt", "lte", "in", "nin", "exists"]);

// ─── Validation Error ────────────────────────────────────────────
class ConfigValidationError extends Error {
  constructor(errors) {
    const message = `Config validation failed:\n  • ${errors.join("\n  • ")}`;
    super(message);
    this.name = "ConfigValidationError";
    this.errors = errors;
  }
}

// ─── Main Parser Class ──────────────────────────────────────────
class ConfigParser {
  #config = null;        // parsed config (private)
  #eventMap = new Map(); // quick lookup for event definitions
  #filePath;
  #env;

  constructor(filePath, options = {}) {
    this.#filePath = resolve(filePath);
    this.#env = options.env || process.env.NODE_ENV || "development";
  }

  // ── Public API ───────────────────────────────────────────────

  /** Load, parse, validate, and resolve the config file. */
  async load() {
    const raw = await this.#readFile();
    const parsed = this.#parse(raw);
    const resolved = this.#resolveEnvVariables(parsed);

    this.#validate(resolved);

    this.#config = Object.freeze(resolved);
    this.#buildEventMap();

    return this;
  }

  /** Return a defensive copy of the entire config. */
  getConfig() {
    this.#ensureLoaded();
    return structuredClone(this.#config);
  }

  /** Return the settings block. */
  getSettings() {
    this.#ensureLoaded();
    return { ...this.#config.settings };
  }

  /** Return config for one event type, or null if not found. */
  getEventConfig(eventType) {
    this.#ensureLoaded();
    return this.#eventMap.get(eventType) ?? null;
  }

  /** Return only events that are enabled. */
  getEnabledEvents() {
    this.#ensureLoaded();
    const result = {};
    for (const [key, cfg] of this.#eventMap) {
      if (cfg.enabled) result[key] = { ...cfg };
    }
    return result;
  }

  /** Return events filtered by priority. */
  getEventsByPriority(priority) {
    this.#ensureLoaded();
    const result = {};
    for (const [key, cfg] of this.#eventMap) {
      if (cfg.priority === priority && cfg.enabled) result[key] = { ...cfg };
    }
    return result;
  }

  /** Return transform rules for a given event type. */
  getTransforms(eventType) {
    this.#ensureLoaded();
    return this.#config.transforms?.[eventType] ?? null;
  }

  /** Return the routing block. */
  getRouting() {
    this.#ensureLoaded();
    return { ...this.#config.routing };
  }

  /** Return the target queue name for a given priority level. */
  getQueueForPriority(priority) {
    this.#ensureLoaded();
    return this.#config.routing?.priorityQueues?.[priority] ?? this.#config.routing?.deadLetterQueue;
  }

  /** Merge an override object into the current config (returns new parser). */
  withOverrides(overrides) {
    this.#ensureLoaded();
    const merged = this.#deepMerge(structuredClone(this.#config), overrides);
    this.#validate(merged);
    const parser = Object.create(ConfigParser.prototype);
    parser.#config = Object.freeze(merged);
    parser.#buildEventMap.call(parser);
    return parser;
  }

  // ── Private helpers ──────────────────────────────────────────

  async #readFile() {
    if (!existsSync(this.#filePath)) {
      throw new Error(`Config file not found: ${this.#filePath}`);
    }
    return readFile(this.#filePath, "utf-8");
  }

  #parse(raw) {
    try {
      return JSON.parse(raw);
    } catch (err) {
      throw new Error(`Failed to parse config JSON: ${err.message}`);
    }
  }

  /** Replace ${ENV_VAR} tokens with process.env values. */
  #resolveEnvVariables(obj) {
    if (typeof obj === "string") {
      return obj.replace(/\$\{(\w+)\}/g, (_, key) => process.env[key] ?? "");
    }
    if (Array.isArray(obj)) return obj.map((v) => this.#resolveEnvVariables(v));
    if (obj !== null && typeof obj === "object") {
      return Object.fromEntries(
        Object.entries(obj).map(([k, v]) => [k, this.#resolveEnvVariables(v)])
      );
    }
    return obj;
  }

  #validate(config) {
    const errors = [];

    // Top-level keys
    if (!config.version) errors.push("Missing required field: version");
    if (!config.settings || typeof config.settings !== "object")
      errors.push("Missing or invalid: settings");
    if (!config.events || typeof config.events !== "object")
      errors.push("Missing or invalid: events");

    // Settings ranges
    if (config.settings) {
      const s = config.settings;
      const props = SCHEMA.settings.properties;
      for (const [key, rule] of Object.entries(props)) {
        if (s[key] === undefined) continue;
        if (rule.type === "number") {
          if (typeof s[key] !== "number") errors.push(`settings.${key} must be a number`);
          if (rule.min !== undefined && s[key] < rule.min)
            errors.push(`settings.${key} must be >= ${rule.min}`);
          if (rule.max !== undefined && s[key] > rule.max)
            errors.push(`settings.${key} must be <= ${rule.max}`);
        }
        if (rule.enum && !rule.enum.includes(s[key]))
          errors.push(`settings.${key} must be one of: ${rule.enum.join(", ")}`);
      }
    }

    // Per-event validation
    if (config.events) {
      for (const [eventName, eventCfg] of Object.entries(config.events)) {
        const prefix = `events.${eventName}`;
        if (typeof eventCfg.enabled !== "boolean")
          errors.push(`${prefix}.enabled must be a boolean`);
        if (!["critical", "high", "medium", "low"].includes(eventCfg.priority))
          errors.push(`${prefix}.priority is invalid`);
        if (!Array.isArray(eventCfg.handlers) || eventCfg.handlers.length === 0)
          errors.push(`${prefix}.handlers must be a non-empty array`);

        // Validate filter conditions operators
        const conditions = eventCfg.filters?.conditions ?? [];
        conditions.forEach((cond, i) => {
          if (!VALID_OPERATORS.has(cond.operator))
            errors.push(`${prefix}.filters.conditions[${i}].operator "${cond.operator}" is invalid`);
        });
      }
    }

    if (errors.length > 0) throw new ConfigValidationError(errors);
  }

  #buildEventMap() {
    this.#eventMap = new Map();
    if (!this.#config?.events) return;
    for (const [key, cfg] of Object.entries(this.#config.events)) {
      this.#eventMap.set(key, { ...cfg });
    }
  }

  #ensureLoaded() {
    if (!this.#config) throw new Error("Config not loaded – call load() first");
  }

  #deepMerge(target, source) {
    for (const key of Object.keys(source)) {
      if (
        source[key] &&
        typeof source[key] === "object" &&
        !Array.isArray(source[key]) &&
        target[key] &&
        typeof target[key] === "object"
      ) {
        target[key] = this.#deepMerge({ ...target[key] }, source[key]);
      } else {
        target[key] = source[key];
      }
    }
    return target;
  }
}

export { ConfigParser, ConfigValidationError };
