### Event Bus (Pub/Sub backbone)

```javascript
// src/EventBus.js

class EventBus {
  #listeners = new Map();   // eventType → Set<callback>
  #middlewares = [];         // global middleware pipeline
  #history = [];            // recent events for debugging
  #maxHistory;

  constructor(options = {}) {
    this.#maxHistory = options.maxHistory ?? 100;
  }

  // ── Subscribe / Unsubscribe ──────────────────────────────────

  /** Register a listener for a specific event type. Returns an unsubscribe fn. */
  on(eventType, callback) {
    if (typeof callback !== "function") {
      throw new TypeError("Listener must be a function");
    }
    if (!this.#listeners.has(eventType)) {
      this.#listeners.set(eventType, new Set());
    }
    this.#listeners.get(eventType).add(callback);

    // Return disposer
    return () => this.off(eventType, callback);
  }

  /** Register a one-shot listener. */
  once(eventType, callback) {
    const wrapper = async (event) => {
      this.off(eventType, wrapper);
      return callback(event);
    };
    return this.on(eventType, wrapper);
  }

  /** Remove a specific listener. */
  off(eventType, callback) {
    this.#listeners.get(eventType)?.delete(callback);
  }

  /** Remove all listeners (optionally for one event type). */
  removeAll(eventType) {
    if (eventType) {
      this.#listeners.delete(eventType);
    } else {
      this.#listeners.clear();
    }
  }

  // ── Middleware ────────────────────────────────────────────────

  /** Add a global middleware: (event, next) => ... */
  use(middleware) {
    if (typeof middleware !== "function") {
      throw new TypeError("Middleware must be a function");
    }
    this.#middlewares.push(middleware);
    return this;
  }

  // ── Emit ─────────────────────────────────────────────────────

  /** Emit an event through middleware, then to all listeners. */
  async emit(eventType, payload) {
    const event = {
      type: eventType,
      payload,
      timestamp: Date.now(),
      id: crypto.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`,
      metadata: {},
    };

    // Record history
    this.#history.push(event);
    if (this.#history.length > this.#maxHistory) this.#history.shift();

    // Run global middleware pipeline
    const processedEvent = await this.#runMiddleware(event);
    if (!processedEvent) return []; // middleware aborted the event

    // Invoke listeners
    const listeners = this.#listeners.get(eventType);
    if (!listeners || listeners.size === 0) return [];

    const results = [];
    for (const listener of listeners) {
      try {
        results.push(await listener(processedEvent));
      } catch (err) {
        results.push({ error: err.message });
        // Also emit on an internal error channel
        if (eventType !== "__error__") {
          this.emit("__error__", { originalEvent: event, error: err });
        }
      }
    }
    return results;
  }

  // ── Introspection ────────────────────────────────────────────

  listenerCount(eventType) {
    return this.#listeners.get(eventType)?.size ?? 0;
  }

  getHistory(limit = 10) {
    return this.#history.slice(-limit);
  }

  // ── Private ──────────────────────────────────────────────────

  async #runMiddleware(event) {
    let current = event;
    for (const mw of this.#middlewares) {
      let called = false;
      const next = (modified) => {
        called = true;
        current = modified ?? current;
      };
      await mw(current, next);
      if (!called) return null; // middleware didn't call next → abort
    }
    return current;
  }
}

export { EventBus };
