### `src/RateLimiter.js` — Token Bucket Rate Limiter

```javascript
const { EventEmitter } = require("events");

class RateLimiter extends EventEmitter {
  /**
   * Token-bucket rate limiter.
   * @param {object} opts
   * @param {number} opts.maxTokens      – bucket capacity
   * @param {number} opts.refillRate     – tokens added per interval
   * @param {number} opts.refillIntervalMs – ms between refills
   * @param {number} [opts.maxQueueSize] – max waiting callers (0 = unlimited)
   */
  constructor({
    maxTokens = 10,
    refillRate = 10,
    refillIntervalMs = 1000,
    maxQueueSize = 0,
  } = {}) {
    super();
    this.maxTokens = maxTokens;
    this.tokens = maxTokens;
    this.refillRate = refillRate;
    this.refillIntervalMs = refillIntervalMs;
    this.maxQueueSize = maxQueueSize;

    this._queue = [];          // waiters: { resolve, reject, cost }
    this._refillTimer = null;
    this._paused = false;
    this._pauseUntil = 0;

    this._startRefill();
  }

  /* ── public API ─────────────────────────────────── */

  /** Wait until `cost` tokens are available, then consume them. */
  async acquire(cost = 1) {
    if (cost > this.maxTokens) {
      throw new RangeError(
        `Requested ${cost} tokens but bucket capacity is ${this.maxTokens}`
      );
    }

    // Fast path: tokens available right now
    if (!this._paused && this.tokens >= cost) {
      this.tokens -= cost;
      this.emit("acquire", { tokens: this.tokens, cost });
      return;
    }

    // Slow path: queue and wait
    if (this.maxQueueSize > 0 && this._queue.length >= this.maxQueueSize) {
      throw new Error("Rate limiter queue is full");
    }

    return new Promise((resolve, reject) => {
      this._queue.push({ resolve, reject, cost });
      this.emit("queued", { queueLength: this._queue.length });
    });
  }

  /** Externally pause (e.g. after a 429 Retry-After header). */
  pauseFor(ms) {
    const until = Date.now() + ms;
    if (until > this._pauseUntil) {
      this._pauseUntil = until;
      this._paused = true;
      this.emit("paused", { ms, until });
    }
  }

  /** Snapshot for logging / monitoring. */
  getStatus() {
    return {
      tokens: this.tokens,
      maxTokens: this.maxTokens,
      queueLength: this._queue.length,
      paused: this._paused,
      pauseRemainingMs: Math.max(0, this._pauseUntil - Date.now()),
    };
  }

  /** Clean up the refill timer. */
  destroy() {
    if (this._refillTimer) {
      clearInterval(this._refillTimer);
      this._refillTimer = null;
    }
    // Reject anything still waiting
    for (const waiter of this._queue) {
      waiter.reject(new Error("RateLimiter destroyed"));
    }
    this._queue = [];
  }

  /* ── internals ──────────────────────────────────── */

  _startRefill() {
    this._refillTimer = setInterval(() => {
      // Honour external pauses
      if (this._paused) {
        if (Date.now() >= this._pauseUntil) {
          this._paused = false;
          this.emit("resumed");
        } else {
          return; // still paused
        }
      }

      // Refill tokens
      const prev = this.tokens;
      this.tokens = Math.min(this.maxTokens, this.tokens + this.refillRate);

      if (this.tokens !== prev) {
        this.emit("refill", { tokens: this.tokens });
      }

      // Drain waiters that can now be satisfied
      this._drainQueue();
    }, this.refillIntervalMs);

    // Allow the process to exit even if the timer is running
    if (this._refillTimer.unref) {
      this._refillTimer.unref();
    }
  }

  _drainQueue() {
    while (this._queue.length > 0) {
      const next = this._queue[0];
      if (this.tokens >= next.cost) {
        this.tokens -= next.cost;
        this._queue.shift();
        next.resolve();
        this.emit("acquire", { tokens: this.tokens, cost: next.cost });
      } else {
        break; // not enough tokens for the next waiter
      }
    }
  }
}

module.exports = RateLimiter;
