### `src/ProgressTracker.js` — Migration Progress Tracking

```javascript
const { EventEmitter } = require("events");
const fs = require("fs");
const path = require("path");

class ProgressTracker extends EventEmitter {
  /**
   * Tracks migration progress and supports resume from checkpoint.
   * @param {object} opts
   * @param {string}  opts.migrationId   – unique name for this migration
   * @param {number}  opts.totalItems    – total items to migrate
   * @param {string} [opts.checkpointDir] – where to persist checkpoint files
   * @param {number} [opts.checkpointEvery] – persist every N items
   */
  constructor({
    migrationId,
    totalItems,
    checkpointDir = "./.migration-checkpoints",
    checkpointEvery = 50,
  }) {
    super();
    this.migrationId = migrationId;
    this.totalItems = totalItems;
    this.checkpointDir = checkpointDir;
    this.checkpointEvery = checkpointEvery;

    this.processed = 0;
    this.succeeded = 0;
    this.failed = 0;
    this.skipped = 0;
    this.errors = [];        // { item, error, timestamp }
    this.startTime = null;
    this.completedIds = new Set();

    this._checkpointPath = path.join(
      checkpointDir,
      `${migrationId}.checkpoint.json`
    );
  }

  /* ── lifecycle ──────────────────────────────────── */

  start() {
    this.startTime = Date.now();
    this.emit("start", { migrationId: this.migrationId, totalItems: this.totalItems });
  }

  /** Load a previous checkpoint so already-done items can be skipped. */
  loadCheckpoint() {
    try {
      if (!fs.existsSync(this._checkpointPath)) return null;

      const raw = fs.readFileSync(this._checkpointPath, "utf-8");
      const cp = JSON.parse(raw);

      this.processed = cp.processed || 0;
      this.succeeded = cp.succeeded || 0;
      this.failed = cp.failed || 0;
      this.skipped = cp.skipped || 0;
      this.completedIds = new Set(cp.completedIds || []);

      this.emit("checkpoint-loaded", {
        processed: this.processed,
        completedIds: this.completedIds.size,
      });

      return cp;
    } catch {
      return null;
    }
  }

  /* ── recording ──────────────────────────────────── */

  recordSuccess(itemId) {
    this.processed++;
    this.succeeded++;
    this.completedIds.add(itemId);

    const progress = this._buildProgress();
    this.emit("progress", progress);

    if (this.processed % this.checkpointEvery === 0) {
      this.saveCheckpoint();
    }
  }

  recordFailure(itemId, error) {
    this.processed++;
    this.failed++;

    this.errors.push({
      itemId,
      error: error.message,
      stack: error.stack,
      timestamp: new Date().toISOString(),
    });

    this.emit("failure", { itemId, error: error.message });

    if (this.processed % this.checkpointEvery === 0) {
      this.saveCheckpoint();
    }
  }

  recordSkip(itemId, reason = "already processed") {
    this.processed++;
    this.skipped++;
    this.emit("skip", { itemId, reason });
  }

  isAlreadyProcessed(itemId) {
    return this.completedIds.has(itemId);
  }

  /* ── checkpoint persistence ─────────────────────── */

  saveCheckpoint() {
    try {
      fs.mkdirSync(this.checkpointDir, { recursive: true });

      const data = {
        migrationId: this.migrationId,
        timestamp: new Date().toISOString(),
        processed: this.processed,
        succeeded: this.succeeded,
        failed: this.failed,
        skipped: this.skipped,
        completedIds: [...this.completedIds],
      };

      fs.writeFileSync(this._checkpointPath, JSON.stringify(data, null, 2));
      this.emit("checkpoint-saved", { processed: this.processed });
    } catch (err) {
      this.emit("checkpoint-error", err);
    }
  }

  /* ── reporting ──────────────────────────────────── */

  _buildProgress() {
    const elapsed = Date.now() - (this.startTime || Date.now());
    const rate = this.processed / (elapsed / 1000) || 0;
    const remaining = this.totalItems - this.processed;
    const etaSeconds = rate > 0 ? remaining / rate : Infinity;

    return {
      processed: this.processed,
      total: this.totalItems,
      succeeded: this.succeeded,
      failed: this.failed,
      skipped: this.skipped,
      percent: ((this.processed / this.totalItems) * 100).toFixed(1),
      ratePerSec: rate.toFixed(2),
      etaSeconds: Math.ceil(etaSeconds),
      elapsedMs: elapsed,
    };
  }

  getSummary() {
    return {
      ...this._buildProgress(),
      errors: this.errors,
    };
  }
}

module.exports = ProgressTracker;
