### `src/BatchProcessor.js` — Concurrent Batch Execution

```javascript
const { EventEmitter } = require("events");
const { MaxRetriesError } = require("./errors");

class BatchProcessor extends EventEmitter {
  /**
   * Processes items with concurrency control and retries.
   * @param {object} opts
   * @param {number}  opts.concurrency  – parallel in-flight items
   * @param {number}  opts.maxRetries   – per-item retry limit
   * @param {number}  opts.retryBaseMs  – base delay for exponential back-off
   * @param {number}  opts.retryMaxMs   – ceiling for back-off delay
   * @param {boolean} opts.jitter       – add randomised jitter to back-off
   */
  constructor({
    concurrency = 5,
    maxRetries = 3,
    retryBaseMs = 1000,
    retryMaxMs = 30000,
    jitter = true,
  } = {}) {
    super();
    this.concurrency = concurrency;
    this.maxRetries = maxRetries;
    this.retryBaseMs = retryBaseMs;
    this.retryMaxMs = retryMaxMs;
    this.jitter = jitter;
  }

  /**
   * Process a batch of items through `handler`.
   * @param {Array}    items   – items to migrate
   * @param {Function} handler – async (item) => result
   * @returns {{ results: Array, errors: Array }}
   */
  async processBatch(items, handler) {
    const results = [];
    const errors = [];

    // Concurrency pool
    const pool = new Set();
    let idx = 0;

    const enqueue = () => {
      while (pool.size < this.concurrency && idx < items.length) {
        const item = items[idx++];
        const p = this._processOne(item, handler)
          .then((result) => {
            results.push({ item, result, status: "success" });
          })
          .catch((err) => {
            errors.push({ item, error: err, status: "failed" });
          })
          .finally(() => {
            pool.delete(p);
            enqueue(); // backfill the pool
          });

        pool.add(p);
      }
    };

    enqueue();

    // Wait until every item is done
    while (pool.size > 0) {
      await Promise.race(pool);
    }

    return { results, errors };
  }

  /* ── internals ──────────────────────────────────── */

  async _processOne(item, handler) {
    let lastError;

    for (let attempt = 1; attempt <= this.maxRetries + 1; attempt++) {
      try {
        const result = await handler(item);
        if (attempt > 1) {
          this.emit("retry-success", { item, attempt });
        }
        return result;
      } catch (err) {
        lastError = err;
        this.emit("retry", { item, attempt, error: err.message });

        // If it's explicitly a rate-limit error, honour the server's delay
        const isRateLimit =
          err.name === "RateLimitError" ||
          err.statusCode === 429 ||
          err.status === 429;

        if (attempt <= this.maxRetries) {
          const delay = isRateLimit
            ? err.retryAfterMs || this._backoff(attempt)
            : this._backoff(attempt);

          await this._sleep(delay);
        }
      }
    }

    throw new MaxRetriesError(item, this.maxRetries + 1);
  }

  _backoff(attempt) {
    const exp = Math.min(
      this.retryMaxMs,
      this.retryBaseMs * Math.pow(2, attempt - 1)
    );
    return this.jitter ? exp * (0.5 + Math.random() * 0.5) : exp;
  }

  _sleep(ms) {
    return new Promise((r) => setTimeout(r, ms));
  }
}

module.exports = BatchProcessor;
```

