const RateLimiter = require("./RateLimiter");
const BatchProcessor = require("./BatchProcessor");
const ProgressTracker = require("./ProgressTracker");

class MigrationHelper extends EventEmitter {
  /**
   * @param {object}   opts
   * @param {string}   opts.migrationId        – unique identifier
   * @param {object}  [opts.rateLimit]          – RateLimiter options
   * @param {object}  [opts.batch]              – BatchProcessor options
   * @param {object}  [opts.progress]           – ProgressTracker overrides
   * @param {boolean} [opts.resumable]          – load checkpoint on start
   * @param {boolean} [opts.stopOnError]        – abort entire migration on first error
   * @param {Function} opts.fetchItems          – async () => Item[]
   * @param {Function} opts.migrateItem         – async (item) => result
   * @param {Function} [opts.getItemId]         – (item) => string  (default: item.id)
   * @param {Function} [opts.onItemComplete]    – optional hook
   */
  constructor(opts) {
    super();

    this.migrationId = opts.migrationId;
    this.resumable = opts.resumable ?? true;
    this.stopOnError = opts.stopOnError ?? false;
    this.fetchItems = opts.fetchItems;
    this.migrateItem = opts.migrateItem;
    this.getItemId = opts.getItemId || ((item) => item.id);
    this.onItemComplete = opts.onItemComplete || (() => {});

    // Sub-components
    this.rateLimiter = new RateLimiter({
      maxTokens: 10,
      refillRate: 10,
      refillIntervalMs: 1000,
      ...opts.rateLimit,
    });

    this.batchProcessor = new BatchProcessor({
      concurrency: 5,
      maxRetries: 3,
      retryBaseMs: 1000,
      ...opts.batch,
    });

    // Tracker is created once we know totalItems (see run())
    this._trackerOpts = opts.progress || {};
    this.tracker = null;

    // Wire sub-component events upward
    this._wireEvents();
  }

  /* ── main entry point ───────────────────────────── */

  async run() {
    this.emit("migration-start", { migrationId: this.migrationId });

    // 1. Fetch all items
    this.emit("phase", "fetching items");
    const allItems = await this.fetchItems();

    // 2. Create progress tracker
    this.tracker = new ProgressTracker({
      migrationId: this.migrationId,
      totalItems: allItems.length,
      ...this._trackerOpts,
    });
    this._wireTrackerEvents();

    if (this.resumable) {
      this.tracker.loadCheckpoint();
    }
    this.tracker.start();

    // 3. Filter already-processed items
    const pending = allItems.filter((item) => {
      const id = this.getItemId(item);
      if (this.tracker.isAlreadyProcessed(id)) {
        this.tracker.recordSkip(id);
        return false;
      }
      return true;
    });

    this.emit("phase", `processing ${pending.length} items (${allItems.length - pending.length} skipped)`);

    // 4. Build rate-limited handler
