      await this.rateLimiter.acquire(); // wait for a token
      return this.migrateItem(item);
    };

    // 5. Process in batches
    const batchSize = this.batchProcessor.concurrency * 2; // 2× concurrency
    const batches = this._chunk(pending, batchSize);

