      await this.#writeWithRetry(filePath, content, batch);

      this.#stats.totalLogsFlushed += batch.length;
      this.#stats.lastFlushTime = new Date().toISOString();

      this.emit('flushed', {
        count: batch.length,
        file: filePath,
        timestamp: this.#stats.lastFlushTime,
      });
    } finally {
      // Always release the mutex, even on error
      this.#flushMutex.release();
    }
