        return this.#writeWithRetry(filePath, content, batch, attempt + 1);
      }

      // All retries exhausted — push batch back to buffer head
      console.error(
        `[AuditScheduler] ❌ Write failed after ${this.#config.maxRetries} attempts. ` +
        `Re-buffering ${batch.length} logs.`
      );
      this.#logBuffer.unshift(...batch);

      throw new AuditLogError(
        `Write failed after ${this.#config.maxRetries} retries`,
        'WRITE_EXHAUSTED',
        { filePath, attempts: attempt }
      );
    }
