        }
      }

      this.#stats.lastRotationTime = new Date().toISOString();

      if (deletedCount > 0) {
        this.emit('rotated', {
          deletedCount,
          timestamp: this.#stats.lastRotationTime,
        });
        console.log(`[AuditScheduler] 🗑️  Rotated ${deletedCount} old log files`);
      }
    } finally {
      this.#rotateMutex.release();
    }
  }

  // ── Private: Shutdown Hooks ────────────────────────────

  /**
   * FIX 16: Graceful shutdown on process signals
   */
  #registerShutdownHooks() {
    const gracefulShutdown = async (signal) => {
      console.log(`\n[AuditScheduler] Received ${signal}, shutting down...`);
      await this.stop();
      process.exit(0);
    };

    // Handle common shutdown signals
    process.once('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.once('SIGINT', () => gracefulShutdown('SIGINT'));

    // Handle uncaught errors — flush before crashing
    process.once('uncaughtException', async (error) => {
      console.error('[AuditScheduler] Uncaught exception, emergency flush...');
      try {
        await this.stop();
      } catch { /* best-effort */ }
      process.exit(1);
    });
  }
}

