    handleRecurrence(task);
}

function handleRecurrence(task) {
    if (!task.recurrence || task.recurrence === 'none') return;

    const currentTime = new Date(task.scheduledTime);
    let nextTime;

    switch (task.recurrence) {
        case 'daily':
            nextTime = new Date(currentTime.getTime() + 24 * 60 * 60 * 1000);
            break;
        case 'weekly':
            nextTime = new Date(currentTime.getTime() + 7 * 24 * 60 * 60 * 1000);
            break;
        default:
            console.warn(`Unknown recurrence: ${task.recurrence}`);
            return;
    }

    task.scheduledTime = nextTime.toISOString();
    task.status = 'pending';
    task.updatedAt = new Date().toISOString();

    console.log(`🔁 Rescheduled '${task.title}' → ${task.scheduledTime}`);
    scheduleTask(task);
}

function cancelScheduledTimer(taskId) {
    if (scheduledTimers[taskId]) {
        clearTimeout(scheduledTimers[taskId]);
        delete scheduledTimers[taskId];
        console.log(`⏹ Cancelled timer for task '${taskId}'`);
    }
}

// ===================== GLOBAL ERROR HANDLER =====================
// FIX 16: Global error handling middleware
app.use((err, req, res, next) => {
    console.error('Unhandled error:', err.stack);
    res.status(500).json({
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? err.message : undefined
    });
});

// Handle 404 for undefined routes
app.use((req, res) => {
    res.status(404).json({ error: `Route ${req.method} ${req.originalUrl} not found` });
});

// ===================== GRACEFUL SHUTDOWN =====================
function gracefulShutdown() {
    console.log('\nShutting down... cancelling all timers.');
    Object.keys(scheduledTimers).forEach(cancelScheduledTimer);
    process.exit(0);
}
process.on('SIGINT', gracefulShutdown);
process.on('SIGTERM', gracefulShutdown);

// ===================== START SERVER =====================
app.listen(PORT, () => {  // FIX 17: Use configurable PORT
    console.log(`🚀 Task Scheduler API running on http://localhost:${PORT}`);
});
