## The Debugged Code (After)

```javascript
// lib/rules/require-audit-logging.js — FIXED VERSION

"use strict";

module.exports = {
  meta: {
    type: "suggestion",  // ✅ FIX 2: Correct meta type
    docs: {
      description: "Enforce audit logging on sensitive operations",
      category: "Best Practices",
      recommended: true,
    },
    fixable: "code",
    messages: {
      missingAuditLog:
        "Sensitive operation '{{name}}' must include an audit log call.",
      missingRequiredFields:
        "Audit log call is missing required fields: {{fields}}.",
      missingErrorAudit:
        "Catch block for sensitive operation must include audit logging.",
    },
    // ✅ FIX 1: Provide full JSON schema so ESLint can validate options
    schema: [
      {
        type: "object",
        properties: {
          sensitiveFunctions: {
            type: "array",
            items: { type: "string" },
          },
          auditLogFunctions: {
            type: "array",
            items: { type: "string" },
          },
          requiredFields: {
            type: "array",
            items: { type: "string" },
          },
        },
        additionalProperties: false,
      },
    ],
  },

  create(context) {
    const options = context.options[0] || {};

    const sensitiveFunctions = options.sensitiveFunctions || [
      "deleteUser",
      "updatePermissions",
      "transferFunds",
      "resetPassword",
      "modifyRole",
    ];

    const auditLogFunctions = options.auditLogFunctions || [
      "auditLog",
      "logger.audit",
      "AuditService.log",
    ];

    const requiredFields = options.requiredFields || [
      "userId",
      "action",
      "timestamp",
      "resource",
    ];

    // ---------------------------------------------------------------
    // ✅ FIX 3: Recursively resolve member expressions of any depth
    //    e.g. "AuditService.logger.audit" now works correctly
    // ---------------------------------------------------------------
    function getCalleeName(node) {
      if (!node) return null;

      if (node.type === "Identifier") {
        return node.name;
      }

      if (node.type === "MemberExpression") {
        const objectName = getCalleeName(node.object);  // recurse
        const propertyName = node.computed
          ? null                       // skip dynamic access like obj[expr]
          : node.property.name;

        if (objectName && propertyName) {
          return `${objectName}.${propertyName}`;
        }
        return propertyName || objectName || null;
      }

      return null;
    }

    // ---------------------------------------------------------------
    // ✅ FIX 4 / 5 / 6: Deep-search for audit log calls in a subtree
    //    — handles nested blocks, if/else, loops, etc.
    //    — uses strict equality
    //    — eliminates off-by-one
    // ---------------------------------------------------------------
    function containsAuditLogCall(node) {
      if (!node) return false;

      // Handle BlockStatement / Program body
      if (node.type === "BlockStatement" || node.type === "Program") {
        // ✅ FIX 4: body is accessed safely
        const statements = Array.isArray(node.body) ? node.body : [];

        // ✅ FIX 6: '<' instead of '<=' — no off-by-one
        for (let i = 0; i < statements.length; i++) {
          if (containsAuditLogCall(statements[i])) return true;
        }
        return false;
      }

      // Direct call expression
      // ✅ FIX 5: Strict '===' comparison
      if (
        node.type === "ExpressionStatement" &&
        node.expression &&
        node.expression.type === "CallExpression"
      ) {
        const callee = getCalleeName(node.expression.callee);
        if (auditLogFunctions.includes(callee)) return true;
      }

      // Await expression wrapping a call:  await auditLog(...)
      if (
        node.type === "ExpressionStatement" &&
        node.expression &&
        node.expression.type === "AwaitExpression" &&
        node.expression.argument &&
        node.expression.argument.type === "CallExpression"
      ) {
        const callee = getCalleeName(node.expression.argument.callee);
        if (auditLogFunctions.includes(callee)) return true;
      }

      // ✅ FIX 4 (cont.): Recurse into nested control-flow structures
      if (node.type === "IfStatement") {
        return (
          containsAuditLogCall(node.consequent) ||
          containsAuditLogCall(node.alternate)
        );
      }
      if (node.type === "TryStatement") {
        return (
          containsAuditLogCall(node.block) ||
          containsAuditLogCall(node.handler && node.handler.body)
        );
      }

      return false;
    }

    // ---------------------------------------------------------------
    // ✅ FIX 7: Null-safe argument field extraction
    // ---------------------------------------------------------------
    function getAuditLogFieldNames(callExpression) {
      const args = callExpression.arguments;
      if (!args || args.length === 0) return [];

      const firstArg = args[0];
      if (firstArg.type !== "ObjectExpression") return [];

      return firstArg.properties
        .filter((p) => p.key)                           // guard against spreads
        .map((p) => {
          if (p.key.type === "Identifier") return p.key.name;
          if (p.key.type === "Literal") return String(p.key.value);
          return null;
        })
        .filter(Boolean);
    }

    // ---------------------------------------------------------------
    // ✅ FIX 8: Fixer inserts **inside** the enclosing block,
    //    after the sensitive call, with proper formatting
    // ---------------------------------------------------------------
    function buildAuditLogFix(fixer, callNode, enclosingBlock, functionName) {
      // Find the ExpressionStatement that wraps the sensitive call
      const sourceCode = context.getSourceCode();
      const parentStmt =
        callNode.parent.type === "ExpressionStatement"
          ? callNode.parent
          : callNode.parent.type === "AwaitExpression" &&
            callNode.parent.parent.type === "ExpressionStatement"
          ? callNode.parent.parent
          : null;

      if (!parentStmt) return null;

      const indent = " ".repeat(parentStmt.loc.start.column);
      const auditCall = [
        "",
        `${indent}auditLog({`,
        `${indent}  userId: ctx.userId,`,
        `${indent}  action: "${functionName}",`,
        `${indent}  timestamp: Date.now(),`,
        `${indent}  resource: "${functionName}",`,
        `${indent}});`,
      ].join("\n");

      return fixer.insertTextAfter(parentStmt, auditCall);
    }

    // ---------------------------------------------------------------
    // Helper: find the nearest enclosing function / block
    // ✅ FIX 10: Also matches ArrowFunctionExpression & FunctionExpression
    // ---------------------------------------------------------------
    function findEnclosingBlock(node) {
      // ✅ FIX: Use context.getAncestors() → sourceCode.getAncestors(node)
      //    for ESLint v9 compatibility (falls back gracefully)
      const sourceCode = context.getSourceCode();
      const ancestors =
        typeof sourceCode.getAncestors === "function"
          ? sourceCode.getAncestors(node)
          : context.getAncestors();

      return ancestors.reverse().find(
        (a) =>
          a.type === "BlockStatement" ||
          a.type === "FunctionDeclaration" ||
          a.type === "FunctionExpression" ||            // ✅ added
          a.type === "ArrowFunctionExpression"          // ✅ FIX 10
      );
    }

    // ===============================================================
    // Visitor
    // ===============================================================
    return {
      // ✅ FIX 9: Single handler that covers both plain calls and
      //    `await` calls by inspecting 'CallExpression' universally
      CallExpression(node) {
        const calleeName = getCalleeName(node.callee);
        if (!calleeName) return;

        // ------------------------------------------------
        // A) Check: sensitive operation has an audit log
        // ------------------------------------------------
        if (sensitiveFunctions.includes(calleeName)) {
          const block = findEnclosingBlock(node);

          // Resolve the actual block body
          const blockBody =
            block &&
            (block.type === "BlockStatement"
              ? block
              : block.body && block.body.type === "BlockStatement"
              ? block.body
              : null);

          if (!blockBody || !containsAuditLogCall(blockBody)) {
            context.report({
              node,
              messageId: "missingAuditLog",
              data: { name: calleeName },
              fix(fixer) {
                return buildAuditLogFix(fixer, node, blockBody, calleeName);
              },
            });
          }
        }

        // ------------------------------------------------
        // ✅ FIX 11: B) Check: audit log call has required fields
        // ------------------------------------------------
        if (auditLogFunctions.includes(calleeName)) {
          const presentFields = getAuditLogFieldNames(node);
          const missingFields = requiredFields.filter(
            (f) => !presentFields.includes(f)
          );

          if (missingFields.length > 0) {
            context.report({
              node,
              messageId: "missingRequiredFields",
              data: { fields: missingFields.join(", ") },
            });
          }
        }
      },

      // ------------------------------------------------
      // ✅ FIX 12: C) Check: catch blocks audit the error
      // ------------------------------------------------
      CatchClause(node) {
        // Walk ancestors to see if this try/catch wraps a sensitive call
        const tryBlock = node.parent && node.parent.block;
        if (!tryBlock) return;

        const hasSensitiveCall = sensitiveFunctions.some((fn) => {
          const source = context.getSourceCode().getText(tryBlock);
          return source.includes(fn);         // quick heuristic
        });

        if (hasSensitiveCall && !containsAuditLogCall(node.body)) {
          context.report({
            node,
            messageId: "missingErrorAudit",
          });
        }
      },
    };
  },
};
