# Rust Migration Helper with Event Processing

This example demonstrates a migration system that processes steps sequentially, emits events at each phase, and supports event handler subscriptions, rollback, and retry logic.

```rust
use std::collections::HashMap;
use std::fmt;
use std::time::{Duration, Instant};

// ─── Error Types ────────────────────────────────────────────────

#[derive(Debug, Clone)]
pub enum MigrationError {
    StepFailed { step: String, reason: String },
    RollbackFailed { step: String, reason: String },
    InvalidState { expected: MigrationState, actual: MigrationState },
    MaxRetriesExceeded { step: String, attempts: u32 },
    HandlerError(String),
}

impl fmt::Display for MigrationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::StepFailed { step, reason } =>
                write!(f, "Step '{step}' failed: {reason}"),
            Self::RollbackFailed { step, reason } =>
                write!(f, "Rollback of '{step}' failed: {reason}"),
            Self::InvalidState { expected, actual } =>
                write!(f, "Invalid state: expected {expected:?}, got {actual:?}"),
            Self::MaxRetriesExceeded { step, attempts } =>
                write!(f, "Step '{step}' exceeded max retries ({attempts})"),
            Self::HandlerError(msg) =>
                write!(f, "Handler error: {msg}"),
        }
    }
}

impl std::error::Error for MigrationError {}

// ─── Core Types ─────────────────────────────────────────────────

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum MigrationState {
    Pending,
    InProgress,
    Completed,
    Failed,
    RolledBack,
}

/// Events emitted during migration processing.
#[derive(Debug, Clone)]
pub enum MigrationEvent {
    MigrationStarted {
        total_steps: usize,
    },
    StepStarted {
        step_index: usize,
        step_name: String,
    },
    StepCompleted {
        step_index: usize,
        step_name: String,
        duration: Duration,
    },
    StepRetried {
        step_index: usize,
        step_name: String,
        attempt: u32,
        error: String,
    },
    StepFailed {
        step_index: usize,
        step_name: String,
        error: String,
    },
    RollbackStarted {
        from_step: usize,
    },
    RollbackStepCompleted {
        step_name: String,
    },
    MigrationCompleted {
        total_duration: Duration,
    },
    MigrationFailed {
        error: String,
    },
}

/// Trait for a single migration step (forward + rollback).
pub trait MigrationStep {
    fn name(&self) -> &str;
    fn apply(&self, ctx: &mut MigrationContext) -> Result<(), MigrationError>;
    fn rollback(&self, ctx: &mut MigrationContext) -> Result<(), MigrationError>;
}

/// Shared context passed through every step.
#[derive(Debug, Default)]
pub struct MigrationContext {
    pub data: HashMap<String, String>,
}

impl MigrationContext {
    pub fn set(&mut self, key: impl Into<String>, value: impl Into<String>) {
        self.data.insert(key.into(), value.into());
    }

    pub fn get(&self, key: &str) -> Option<&str> {
        self.data.get(key).map(|s| s.as_str())
    }
}

// ─── Event Handler ──────────────────────────────────────────────

/// Anything that can react to migration events.
pub trait EventHandler {
    fn handle(&self, event: &MigrationEvent);
}

/// A simple handler that logs to stdout.
pub struct LoggingHandler {
    pub prefix: String,
}

impl EventHandler for LoggingHandler {
    fn handle(&self, event: &MigrationEvent) {
        match event {
            MigrationEvent::MigrationStarted { total_steps } =>
                println!("[{}] Migration started ({total_steps} steps)", self.prefix),

            MigrationEvent::StepStarted { step_index, step_name } =>
                println!("[{}]   ▶ Step {step_index}: '{step_name}'", self.prefix),

            MigrationEvent::StepCompleted { step_name, duration, .. } =>
                println!("[{}]   ✔ '{step_name}' completed in {duration:?}", self.prefix),

            MigrationEvent::StepRetried { step_name, attempt, error, .. } =>
                println!("[{}]   ⟳ Retrying '{step_name}' (attempt {attempt}): {error}", self.prefix),

            MigrationEvent::StepFailed { step_name, error, .. } =>
                println!("[{}]   ✘ '{step_name}' FAILED: {error}", self.prefix),

            MigrationEvent::RollbackStarted { from_step } =>
                println!("[{}]   ↺ Rolling back from step {from_step}", self.prefix),

            MigrationEvent::RollbackStepCompleted { step_name } =>
                println!("[{}]   ↺ Rolled back '{step_name}'", self.prefix),

            MigrationEvent::MigrationCompleted { total_duration } =>
                println!("[{}] Migration completed in {total_duration:?}", self.prefix),

            MigrationEvent::MigrationFailed { error } =>
                println!("[{}] Migration FAILED: {error}", self.prefix),
        }
    }
}

/// A handler that collects all events for later inspection (e.g. testing).
pub struct CollectingHandler {
    events: std::cell::RefCell<Vec<MigrationEvent>>,
}

impl CollectingHandler {
    pub fn new() -> Self {
        Self { events: std::cell::RefCell::new(Vec::new()) }
    }

    pub fn events(&self) -> Vec<MigrationEvent> {
        self.events.borrow().clone()
    }

    pub fn event_count(&self) -> usize {
        self.events.borrow().len()
    }
}

impl EventHandler for CollectingHandler {
    fn handle(&self, event: &MigrationEvent) {
        self.events.borrow_mut().push(event.clone());
    }
}

// ─── Migration Engine ───────────────────────────────────────────

pub struct MigrationConfig {
    pub max_retries: u32,
    pub rollback_on_failure: bool,
}

impl Default for MigrationConfig {
    fn default() -> Self {
        Self {
            max_retries: 3,
            rollback_on_failure: true,
        }
    }
}

pub struct MigrationEngine<'a> {
    steps: Vec<Box<dyn MigrationStep>>,
    handlers: Vec<&'a dyn EventHandler>,
    config: MigrationConfig,
    state: MigrationState,
}

impl<'a> MigrationEngine<'a> {
    pub fn new(config: MigrationConfig) -> Self {
        Self {
            steps: Vec::new(),
            handlers: Vec::new(),
            config,
            state: MigrationState::Pending,
        }
    }

    /// Register a migration step.
    pub fn add_step(&mut self, step: impl MigrationStep + 'static) -> &mut Self {
        self.steps.push(Box::new(step));
        self
    }

    /// Subscribe an event handler.
    pub fn add_handler(&mut self, handler: &'a dyn EventHandler) -> &mut Self {
        self.handlers.push(handler);
        self
    }

    pub fn state(&self) -> MigrationState {
        self.state
    }

    /// Broadcast an event to every registered handler.
    fn emit(&self, event: MigrationEvent) {
        for handler in &self.handlers {
            handler.handle(&event);
        }
    }

    /// Execute all steps in order, with retry and optional rollback.
    pub fn run(&mut self, ctx: &mut MigrationContext) -> Result<(), MigrationError> {
        if self.state != MigrationState::Pending {
            return Err(MigrationError::InvalidState {
                expected: MigrationState::Pending,
                actual: self.state,
            });
        }

        self.state = MigrationState::InProgress;
        let start = Instant::now();

        self.emit(MigrationEvent::MigrationStarted {
            total_steps: self.steps.len(),
        });

        for (idx, step) in self.steps.iter().enumerate() {
            self.emit(MigrationEvent::StepStarted {
                step_index: idx,
                step_name: step.name().to_string(),
            });

            let step_start = Instant::now();

            match self.execute_with_retry(step.as_ref(), ctx, idx) {
                Ok(()) => {
                    self.emit(MigrationEvent::StepCompleted {
                        step_index: idx,
                        step_name: step.name().to_string(),
                        duration: step_start.elapsed(),
                    });
                }
                Err(err) => {
                    self.emit(MigrationEvent::StepFailed {
                        step_index: idx,
                        step_name: step.name().to_string(),
                        error: err.to_string(),
                    });

                    if self.config.rollback_on_failure {
                        self.rollback(ctx, idx)?;
                    }

                    self.state = MigrationState::Failed;
                    self.emit(MigrationEvent::MigrationFailed {
                        error: err.to_string(),
                    });
                    return Err(err);
                }
            }
        }

        self.state = MigrationState::Completed;
        self.emit(MigrationEvent::MigrationCompleted {
            total_duration: start.elapsed(),
        });
        Ok(())
    }

    /// Try a step up to `max_retries` times.
    fn execute_with_retry(
        &self,
        step: &dyn MigrationStep,
        ctx: &mut MigrationContext,
        step_index: usize,
    ) -> Result<(), MigrationError> {
        let mut last_err = None;

        for attempt in 1..=self.config.max_retries {
            match step.apply(ctx) {
                Ok(()) => return Ok(()),
                Err(err) => {
                    if attempt < self.config.max_retries {
                        self.emit(MigrationEvent::StepRetried {
                            step_index,
                            step_name: step.name().to_string(),
                            attempt,
                            error: err.to_string(),
                        });
                    }
                    last_err = Some(err);
                }
            }
        }

        Err(MigrationError::MaxRetriesExceeded {
            step: step.name().to_string(),
            attempts: self.config.max_retries,
        })
    }

    /// Roll back completed steps in reverse order.
    fn rollback(
        &self,
        ctx: &mut MigrationContext,
        failed_step_index: usize,
    ) -> Result<(), MigrationError> {
        self.emit(MigrationEvent::RollbackStarted {
            from_step: failed_step_index,
        });

        // Roll back every step that completed *before* the failure.
        for idx in (0..failed_step_index).rev() {
            let step = &self.steps[idx];
            step.rollback(ctx).map_err(|_| MigrationError::RollbackFailed {
                step: step.name().to_string(),
                reason: "rollback returned an error".into(),
            })?;
            self.emit(MigrationEvent::RollbackStepCompleted {
                step_name: step.name().to_string(),
            });
        }

        Ok(())
    }
}

// ─── Example Migration Steps ────────────────────────────────────

/// Simulates creating a new schema table.
struct CreateUsersTable;

impl MigrationStep for CreateUsersTable {
    fn name(&self) -> &str { "create_users_table" }

    fn apply(&self, ctx: &mut MigrationContext) -> Result<(), MigrationError> {
        // Simulate DDL
        ctx.set("users_table", "created");
        Ok(())
    }

    fn rollback(&self, ctx: &mut MigrationContext) -> Result<(), MigrationError> {
        ctx.data.remove("users_table");
        Ok(())
    }
}

/// Simulates back-filling data into the new table.
struct BackfillUserEmails;

impl MigrationStep for BackfillUserEmails {
    fn name(&self) -> &str { "backfill_user_emails" }

    fn apply(&self, ctx: &mut MigrationContext) -> Result<(), MigrationError> {
        if ctx.get("users_table") != Some("created") {
            return Err(MigrationError::StepFailed {
                step: self.name().into(),
                reason: "users table does not exist".into(),
            });
        }
        ctx.set("emails_backfilled", "true");
        Ok(())
    }

    fn rollback(&self, ctx: &mut MigrationContext) -> Result<(), MigrationError> {
        ctx.data.remove("emails_backfilled");
        Ok(())
    }
}

/// Simulates adding an index — intentionally fails to demo rollback.
struct AddEmailIndex {
    should_fail: bool,
}

impl MigrationStep for AddEmailIndex {
    fn name(&self) -> &str { "add_email_index" }

    fn apply(&self, ctx: &mut MigrationContext) -> Result<(), MigrationError> {
        if self.should_fail {
            return Err(MigrationError::StepFailed {
                step: self.name().into(),
                reason: "simulated index creation failure".into(),
            });
        }
        ctx.set("email_index", "created");
        Ok(())
    }

    fn rollback(&self, ctx: &mut MigrationContext) -> Result<(), MigrationError> {
        ctx.data.remove("email_index");
        Ok(())
    }
}

// ─── Main ───────────────────────────────────────────────────────

fn main() {
    println!("===== Successful Migration =====\n");
    run_migration(false);

    println!("\n===== Failing Migration (with rollback) =====\n");
    run_migration(true);
}

fn run_migration(simulate_failure: bool) {
    let logger = LoggingHandler { prefix: "MIG".into() };
    let collector = CollectingHandler::new();

    let config = MigrationConfig {
        max_retries: 2,
        rollback_on_failure: true,
    };

    let mut engine = MigrationEngine::new(config);

    // Register steps
    engine.add_step(CreateUsersTable);
    engine.add_step(BackfillUserEmails);
    engine.add_step(AddEmailIndex { should_fail: simulate_failure });

    // Subscribe event handlers
    engine.add_handler(&logger);
    engine.add_handler(&collector);

    let mut ctx = MigrationContext::default();

    match engine.run(&mut ctx) {
        Ok(()) => {
            println!("\nFinal state: {:?}", engine.state());
            println!("Context: {:?}", ctx.data);
        }
        Err(err) => {
            println!("\nFinal state: {:?}", engine.state());
            println!("Error: {err}");
            println!("Context after rollback: {:?}", ctx.data);
        }
    }

    println!("Total events captured: {}", collector.event_count());
}
