## bin/report.js — Entry Point

```js
#!/usr/bin/env node

const { parseArgs, printUsage } = require('../lib/cli');
const { loadData } = require('../lib/loader');
const { processReport } = require('../lib/engine');
const { format } = require('../lib/formatters');

async function main() {
  // 1. Parse CLI arguments
  const args = parseArgs(process.argv.slice(2));

  if (args.help) {
    printUsage();
    process.exit(0);
  }

  try {
    // 2. Load raw data
    const rawData = await loadData(args.input);

    if (!rawData.length) {
      console.error('Error: No data found in input.');
      process.exit(1);
    }

    // 3. Process (filter, sort, aggregate)
    const processed = processReport(rawData, {
      filterBy: args.filter,
      sortBy: args.sort,
      sortOrder: args.order,
      groupBy: args.group,
      columns: args.columns,
      limit: args.limit,
    });

    // 4. Format output
    const output = format(processed, {
      format: args.format,
      title: args.title,
    });

    // 5. Write result
    if (args.output) {
      const fs = require('fs');
      fs.writeFileSync(args.output, output, 'utf-8');
      console.log(`Report written to ${args.output}`);
    } else {
      console.log(output);
    }
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }
}

main();
