## lib/cli.js — Argument Parsing

```js
function parseArgs(argv) {
  const args = {
    input: null,
    output: null,
    format: 'table',    // table | csv | json | html
    filter: null,        // "field=value"
    sort: null,          // field name
    order: 'asc',        // asc | desc
    group: null,         // field to group by
    columns: null,       // comma-separated column names
    limit: null,         // max rows
    title: 'Report',
    help: false,
  };

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    const next = argv[i + 1];

    switch (arg) {
      case '-i':
      case '--input':
        args.input = next; i++; break;
      case '-o':
      case '--output':
        args.output = next; i++; break;
      case '-f':
      case '--format':
        args.format = next; i++; break;
      case '--filter':
        args.filter = next; i++; break;
      case '-s':
      case '--sort':
        args.sort = next; i++; break;
      case '--order':
        args.order = next; i++; break;
      case '-g':
      case '--group':
        args.group = next; i++; break;
      case '-c':
      case '--columns':
        args.columns = next ? next.split(',').map(c => c.trim()) : null;
        i++; break;
      case '-l':
      case '--limit':
        args.limit = parseInt(next, 10); i++; break;
      case '-t':
      case '--title':
        args.title = next; i++; break;
      case '-h':
      case '--help':
        args.help = true; break;
      default:
        // Treat first positional arg as input
        if (!arg.startsWith('-') && !args.input) {
          args.input = arg;
        }
    }
  }

  return args;
}

function printUsage() {
  const usage = `
  report-cli — Basic Report Generator

  USAGE
    report [options] [input-file]

  OPTIONS
    -i, --input  <file>     Input JSON file (required)
    -o, --output <file>     Output file (default: stdout)
    -f, --format <type>     Output format: table, csv, json, html (default: table)
    -c, --columns <cols>    Comma-separated column names to include
    -s, --sort <field>      Sort by field name
        --order <dir>       Sort order: asc or desc (default: asc)
        --filter <expr>     Filter rows: "field=value"
    -g, --group <field>     Group rows by field
    -l, --limit <n>         Limit output to n rows
    -t, --title <text>      Report title (default: "Report")
    -h, --help              Show this help message

  EXAMPLES
    report -i data.json -f table
    report -i data.json -f csv -s revenue --order desc -o out.csv
    report -i data.json --filter "status=active" -c "name,email,status"
    report data.json -g department -f html -o report.html
  `;
  console.log(usage);
}

module.exports = { parseArgs, printUsage };
