## lib/loader.js — Data Loading

```js
const fs = require('fs');
const path = require('path');

async function loadData(inputPath) {
  if (!inputPath) {
    // Try reading from stdin if piped
    return readStdin();
  }

  const resolved = path.resolve(inputPath);

  if (!fs.existsSync(resolved)) {
    throw new Error(`File not found: ${resolved}`);
  }

  const ext = path.extname(resolved).toLowerCase();
  const raw = fs.readFileSync(resolved, 'utf-8');

  switch (ext) {
    case '.json':
      return parseJSON(raw);
    case '.csv':
      return parseCSV(raw);
    default:
      throw new Error(`Unsupported file type: ${ext}. Use .json or .csv`);
  }
}

function parseJSON(raw) {
  const data = JSON.parse(raw);
  // Support both arrays and { data: [...] } wrappers
  if (Array.isArray(data)) return data;
  if (data.data && Array.isArray(data.data)) return data.data;
  // Single object → wrap in array
  return [data];
}

function parseCSV(raw) {
  const lines = raw.trim().split('\n');
  if (lines.length < 2) return [];

  const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));

  return lines.slice(1).map(line => {
    const values = splitCSVLine(line);
    const row = {};
    headers.forEach((header, i) => {
      let val = (values[i] || '').trim().replace(/^"|"$/g, '');
      // Auto-convert numbers
      if (val !== '' && !isNaN(val)) val = Number(val);
      row[header] = val;
    });
    return row;
  });
}

function splitCSVLine(line) {
  const result = [];
  let current = '';
  let inQuotes = false;

  for (const char of line) {
    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      result.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  result.push(current);
  return result;
}

function readStdin() {
  return new Promise((resolve, reject) => {
    if (process.stdin.isTTY) {
      reject(new Error('No input file specified. Use --input or pipe data via stdin.'));
      return;
    }

    let data = '';
    process.stdin.setEncoding('utf-8');
    process.stdin.on('data', chunk => { data += chunk; });
    process.stdin.on('end', () => {
      try {
        resolve(parseJSON(data));
      } catch {
        reject(new Error('Failed to parse stdin as JSON.'));
      }
    });
    process.stdin.on('error', reject);
  });
}

module.exports = { loadData };
