### `src/configLoader.js`
```javascript
const fs = require("fs");
const path = require("path");

class ConfigLoader {
  constructor(configDir = path.join(process.cwd(), "config")) {
    this.configDir = configDir;
    this.config = {};
    this.loaded = false;
  }

  // ── Read & Parse a JSON File ──────────────────────────────
  readJsonFile(filePath) {
    try {
      const absolutePath = path.resolve(filePath);

      if (!fs.existsSync(absolutePath)) {
        return null;
      }

      const rawData = fs.readFileSync(absolutePath, "utf-8");
      return JSON.parse(rawData);
    } catch (error) {
      if (error instanceof SyntaxError) {
        throw new Error(`Invalid JSON in ${filePath}: ${error.message}`);
      }
      throw new Error(`Failed to read config file ${filePath}: ${error.message}`);
    }
  }

  // ── Deep Merge Two Objects ────────────────────────────────
  deepMerge(target, source) {
    const result = { ...target };

    for (const key of Object.keys(source)) {
      if (
        source[key] &&
        typeof source[key] === "object" &&
        !Array.isArray(source[key]) &&
        target[key] &&
        typeof target[key] === "object" &&
        !Array.isArray(target[key])
      ) {
        // Recursively merge nested objects
        result[key] = this.deepMerge(target[key], source[key]);
      } else {
        // Overwrite primitive values and arrays
        result[key] = source[key];
      }
    }

    return result;
  }

  // ── Load Configuration (default + environment) ────────────
  load(environment = null) {
    const env = environment || process.env.NODE_ENV || "development";

    // Step 1: Load default config (required)
    const defaultPath = path.join(this.configDir, "default.json");
    const defaultConfig = this.readJsonFile(defaultPath);

    if (!defaultConfig) {
      throw new Error(`Default config not found: ${defaultPath}`);
    }

    // Step 2: Load environment-specific config (optional)
    const envPath = path.join(this.configDir, `${env}.json`);
    const envConfig = this.readJsonFile(envPath);

    // Step 3: Merge defaults with environment overrides
    this.config = envConfig
      ? this.deepMerge(defaultConfig, envConfig)
      : { ...defaultConfig };

    // Step 4: Apply environment variable overrides
    this.applyEnvOverrides();

    this.loaded = true;
    console.log(`Configuration loaded for environment: ${env}`);

    return this.config;
  }

  // ── Override Config Values with Environment Variables ──────
  // Format: APP__DATABASE__HOST → config.database.host
  applyEnvOverrides() {
    const prefix = "APP__";

    for (const [key, value] of Object.entries(process.env)) {
      if (!key.startsWith(prefix)) continue;

      const configPath = key
        .slice(prefix.length)       // remove prefix
        .toLowerCase()
        .split("__");               // split into nested keys

      this.setNestedValue(this.config, configPath, this.parseValue(value));
    }
  }

  // ── Auto-Parse Strings to Proper Types ────────────────────
  parseValue(value) {
    if (value === "true") return true;
    if (value === "false") return false;
    if (value === "null") return null;
    if (!isNaN(value) && value.trim() !== "") return Number(value);
    return value;
  }

  // ── Set a Value in a Nested Object via Key Path ───────────
  setNestedValue(obj, keys, value) {
    let current = obj;

    for (let i = 0; i < keys.length - 1; i++) {
      if (!(keys[i] in current) || typeof current[keys[i]] !== "object") {
        current[keys[i]] = {};
      }
      current = current[keys[i]];
    }

    current[keys[keys.length - 1]] = value;
  }

  // ── Get a Config Value by Dot-Notation Path ───────────────
  // Example: get("database.host") → "localhost"
  get(keyPath, defaultValue = undefined) {
    if (!this.loaded) {
      throw new Error("Configuration not loaded. Call load() first.");
    }

    const keys = keyPath.split(".");
    let current = this.config;

    for (const key of keys) {
      if (current === null || current === undefined || !(key in current)) {
        return defaultValue;
      }
      current = current[key];
    }

    return current;
  }

  // ── Get a Required Config Value (throws if missing) ───────
  getRequired(keyPath) {
    const value = this.get(keyPath);

    if (value === undefined || value === null || value === "") {
      throw new Error(`Required configuration missing: ${keyPath}`);
    }

    return value;
  }

  // ── Validate Required Fields Exist ────────────────────────
  validate(requiredKeys) {
    const missing = [];

    for (const key of requiredKeys) {
      const value = this.get(key);
      if (value === undefined || value === null || value === "") {
        missing.push(key);
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Missing required configuration keys:\n  - ${missing.join("\n  - ")}`
      );
    }

    return true;
  }

  // ── Return the Full Config Object ─────────────────────────
  getAll() {
    if (!this.loaded) {
      throw new Error("Configuration not loaded. Call load() first.");
    }
    return { ...this.config };
  }

  // ── Print Config (mask sensitive fields) ──────────────────
  print(sensitiveKeys = ["password", "secret", "token", "key"]) {
    const masked = JSON.parse(JSON.stringify(this.config));
    this.maskSensitive(masked, sensitiveKeys);
    console.log("Current configuration:");
    console.log(JSON.stringify(masked, null, 2));
  }

  maskSensitive(obj, sensitiveKeys) {
    for (const key of Object.keys(obj)) {
      if (typeof obj[key] === "object" && obj[key] !== null) {
        this.maskSensitive(obj[key], sensitiveKeys);
      } else if (sensitiveKeys.some((s) => key.toLowerCase().includes(s))) {
        obj[key] = "****";
      }
    }
  }
}

module.exports = ConfigLoader;
```

