## Simple Config Loader

```javascript
const fs = require('fs');
const path = require('path');

class ConfigLoader {
  constructor(defaults = {}) {
    this.config = { ...defaults };
  }

  /**
   * Load configuration from a JSON file
   * @param {string} filePath - Path to the JSON config file
   * @returns {object} Merged configuration object
   */
  loadFromFile(filePath) {
    try {
      const absolutePath = path.resolve(filePath);
      const rawData = fs.readFileSync(absolutePath, 'utf-8');
      const parsed = JSON.parse(rawData);

      this.config = { ...this.config, ...parsed };
      console.log(`✅ Config loaded from: ${absolutePath}`);
      return this.config;
    } catch (error) {
      if (error.code === 'ENOENT') {
        throw new Error(`Config file not found: ${filePath}`);
      }
      if (error instanceof SyntaxError) {
        throw new Error(`Invalid JSON in config file: ${error.message}`);
      }
      throw error;
    }
  }

  /**
   * Load configuration from a JSON string
   * @param {string} jsonString - JSON string to parse
   * @returns {object} Merged configuration object
   */
  loadFromString(jsonString) {
    try {
      const parsed = JSON.parse(jsonString);
      this.config = { ...this.config, ...parsed };
      return this.config;
    } catch (error) {
      throw new Error(`Invalid JSON string: ${error.message}`);
    }
  }

  /**
   * Get a config value by dot-notation key
   * @param {string} key - Dot-notation key (e.g., "database.host")
   * @param {*} fallback - Fallback value if key not found
   * @returns {*} Config value
   */
  get(key, fallback = undefined) {
    const keys = key.split('.');
    let value = this.config;

    for (const k of keys) {
      if (value === undefined || value === null || typeof value !== 'object') {
        return fallback;
      }
      value = value[k];
    }

    return value !== undefined ? value : fallback;
  }

  /**
   * Set a config value by dot-notation key
   * @param {string} key - Dot-notation key
   * @param {*} value - Value to set
   */
  set(key, value) {
    const keys = key.split('.');
    let current = this.config;

    for (let i = 0; i < keys.length - 1; i++) {
      if (!(keys[i] in current) || typeof current[keys[i]] !== 'object') {
        current[keys[i]] = {};
      }
      current = current[keys[i]];
    }

    current[keys[keys.length - 1]] = value;
  }

  /**
   * Get all configuration
   * @returns {object} Full config object
   */
  getAll() {
    return { ...this.config };
  }

  /**
   * Validate required keys exist
   * @param {string[]} requiredKeys - Array of required dot-notation keys
   * @throws {Error} If any required key is missing
   */
  validate(requiredKeys) {
    const missing = requiredKeys.filter(
      (key) => this.get(key) === undefined
    );

    if (missing.length > 0) {
      throw new Error(`Missing required config keys: ${missing.join(', ')}`);
    }
  }
}

module.exports = ConfigLoader;
```

