### `src/logStore.js` — In-Memory Storage Engine

```javascript
class LogStore {
  constructor({ maxSize = 10000 } = {}) {
    this.logs = [];
    this.maxSize = maxSize;
  }

  /** Add a single log entry */
  add(entry) {
    if (!entry || typeof entry !== "object") {
      throw new Error("Log entry must be a non-null object");
    }

    // Evict oldest entries when capacity is reached
    if (this.logs.length >= this.maxSize) {
      this.logs.shift();
    }

    this.logs.push(entry);
    return entry;
  }

  /** Add multiple entries at once */
  addBatch(entries) {
    if (!Array.isArray(entries)) {
      throw new Error("Batch must be an array");
    }
    return entries.map((e) => this.add(e));
  }

  /** Return all stored logs */
  getAll() {
    return [...this.logs];
  }

  /** Find a single log by its id */
  findById(id) {
    return this.logs.find((log) => log.id === id) || null;
  }

  /**
   * Query logs with optional filters
   *  - level   : "info" | "warn" | "error" | "debug"
   *  - source  : string
   *  - from    : ISO date string  (inclusive)
   *  - to      : ISO date string  (inclusive)
   *  - search  : substring to match in `message`
   *  - limit   : max results (default 100)
   *  - offset  : pagination offset (default 0)
   */
  query({ level, source, from, to, search, limit = 100, offset = 0 } = {}) {
    let results = this.logs;

    if (level) {
      results = results.filter((l) => l.level === level);
    }
    if (source) {
      results = results.filter((l) => l.source === source);
    }
    if (from) {
      const fromDate = new Date(from);
      results = results.filter((l) => new Date(l.timestamp) >= fromDate);
    }
    if (to) {
      const toDate = new Date(to);
      results = results.filter((l) => new Date(l.timestamp) <= toDate);
    }
    if (search) {
      const lower = search.toLowerCase();
      results = results.filter(
        (l) => l.message && l.message.toLowerCase().includes(lower)
      );
    }

    const total = results.length;
    const paged = results.slice(offset, offset + limit);

    return { total, logs: paged };
  }

  /** Count logs grouped by level */
  stats() {
    const counts = { info: 0, warn: 0, error: 0, debug: 0 };
    for (const log of this.logs) {
      if (counts[log.level] !== undefined) {
        counts[log.level]++;
      }
    }
    return { total: this.logs.length, counts };
  }

  /** Remove all stored logs */
  clear() {
    this.logs = [];
  }
}

module.exports = LogStore;
```

