```javascript
const { v4: uuidv4 } = require("uuid");

const VALID_LEVELS = ["info", "warn", "error", "debug"];

class LogIngester {
  constructor(store) {
    if (!store) throw new Error("A LogStore instance is required");
    this.store = store;
  }

  /**
   * Validate, enrich, and persist a raw log payload.
   *
   * Required fields: message
   * Optional fields: level, source, metadata
   */
  ingest(payload) {
    const errors = this._validate(payload);
    if (errors.length > 0) {
      return { success: false, errors };
    }

    const entry = this._enrich(payload);
    this.store.add(entry);
    return { success: true, entry };
  }

  /** Ingest an array of payloads; returns per-item results */
  ingestBatch(payloads) {
    if (!Array.isArray(payloads)) {
      return { success: false, errors: ["Payload must be an array"] };
    }
    if (payloads.length === 0) {
      return { success: false, errors: ["Batch must not be empty"] };
    }

    const results = payloads.map((p, idx) => {
      const res = this.ingest(p);
      return { index: idx, ...res };
    });

    const successCount = results.filter((r) => r.success).length;
    return { success: successCount > 0, total: payloads.length, successCount, results };
  }

  // ---- private helpers ------------------------------------------------

  _validate(payload) {
    const errors = [];

    if (!payload || typeof payload !== "object") {
      return ["Payload must be a non-null object"];
    }
    if (!payload.message || typeof payload.message !== "string") {
      errors.push("Field 'message' is required and must be a string");
    }
    if (payload.level && !VALID_LEVELS.includes(payload.level)) {
      errors.push(`Field 'level' must be one of: ${VALID_LEVELS.join(", ")}`);
    }
    if (payload.source && typeof payload.source !== "string") {
      errors.push("Field 'source' must be a string");
    }
    return errors;
  }

  _enrich(payload) {
    return {
      id: uuidv4(),
      timestamp: new Date().toISOString(),
      level: payload.level || "info",
      message: payload.message,
      source: payload.source || "unknown",
      metadata: payload.metadata || {},
    };
  }
}

module.exports = LogIngester;
```

### `src/routes.js` — Express Router

```javascript
const express = require("express");

function createRouter(ingester, store) {
  const router = express.Router();

  // Health check
  router.get("/health", (_req, res) => {
    res.json({ status: "ok" });
  });

  // POST /logs — ingest a single log
  router.post("/logs", (req, res) => {
    const result = ingester.ingest(req.body);
    if (!result.success) {
      return res.status(400).json(result);
    }
    return res.status(201).json(result);
  });

  // POST /logs/batch — ingest multiple logs
  router.post("/logs/batch", (req, res) => {
    const result = ingester.ingestBatch(req.body);
    if (!result.success) {
      return res.status(400).json(result);
    }
    const status = result.successCount === result.total ? 201 : 207;
    return res.status(status).json(result);
  });

  // GET /logs — query logs with optional filters
  router.get("/logs", (req, res) => {
    const { level, source, from, to, search, limit, offset } = req.query;
    const result = store.query({
      level,
      source,
      from,
      to,
      search,
      limit: limit ? parseInt(limit, 10) : undefined,
      offset: offset ? parseInt(offset, 10) : undefined,
    });
    return res.json(result);
  });

  // GET /logs/stats — aggregate counts
  router.get("/logs/stats", (_req, res) => {
    return res.json(store.stats());
  });

  // GET /logs/:id — fetch single log by id
  router.get("/logs/:id", (req, res) => {
    const entry = store.findById(req.params.id);
    if (!entry) {
      return res.status(404).json({ error: "Log not found" });
    }
    return res.json(entry);
  });

  return router;
}

module.exports = createRouter;
