const express = require("express");
const LogStore = require("./logStore");
const LogIngester = require("./logIngester");
const createRouter = require("./routes");

const PORT = process.env.PORT || 3000;

const store = new LogStore({ maxSize: 50000 });
const ingester = new LogIngester(store);

const app = express();
app.use(express.json());
app.use("/api", createRouter(ingester, store));

app.listen(PORT, () => {
  console.log(`Log ingestion service running on port ${PORT}`);
});

module.exports = app; // for testing
