```javascript
// src/errors.js

class ConfigError extends Error {
  constructor(message, options = {}) {
    super(message);
    this.name = 'ConfigError';
    this.filePath = options.filePath || null;
    this.line = options.line || null;
    this.column = options.column || null;
  }

  toString() {
    let location = '';
    if (this.filePath) location += ` in ${this.filePath}`;
    if (this.line) location += ` at line ${this.line}`;
    if (this.column) location += `, column ${this.column}`;
    return `${this.name}: ${this.message}${location}`;
  }
}

class ParseError extends ConfigError {
  constructor(message, options = {}) {
    super(message, options);
    this.name = 'ParseError';
    this.rawContent = options.rawContent || null;
  }
}

class ValidationError extends ConfigError {
  constructor(message, options = {}) {
    super(message, options);
    this.name = 'ValidationError';
    this.key = options.key || null;
    this.expectedType = options.expectedType || null;
    this.receivedType = options.receivedType || null;
    this.receivedValue = options.receivedValue;
  }
}

class FileError extends ConfigError {
  constructor(message, options = {}) {
    super(message, options);
    this.name = 'FileError';
    this.code = options.code || null;
  }
}

class MissingKeyError extends ConfigError {
  constructor(key, options = {}) {
    super(`Required config key "${key}" is missing`, options);
    this.name = 'MissingKeyError';
    this.key = key;
  }
}

module.exports = {
  ConfigError,
  ParseError,
  ValidationError,
  FileError,
  MissingKeyError
};
