// src/parsers/JsonParser.js

const { ParseError } = require('../errors');

class JsonParser {
  static get extensions() {
    return ['.json'];
  }

  static get name() {
    return 'JSON';
  }

  /**
   * Parse JSON content with detailed error reporting
   */
  parse(content, filePath = null) {
    try {
      return JSON.parse(content);
    } catch (err) {
      // Extract line/column from JSON parse error
      const position = this._extractPosition(err.message, content);

      throw new ParseError(
        `Invalid JSON: ${err.message}`,
        {
          filePath,
          line: position.line,
          column: position.column,
          rawContent: content
        }
      );
    }
  }

  /**
   * Serialize config object to JSON
   */
  serialize(data) {
    return JSON.stringify(data, null, 2);
  }

  /**
   * Extract line and column from JSON error message
   */
  _extractPosition(errorMessage, content) {
    // JSON.parse errors often include "at position N"
    const posMatch = errorMessage.match(/position\s+(\d+)/);
    if (!posMatch) return { line: null, column: null };

    const position = parseInt(posMatch[1], 10);
    const lines = content.substring(0, position).split('\n');

    return {
      line: lines.length,
      column: lines[lines.length - 1].length + 1
    };
  }
}

module.exports = JsonParser;
