// src/parsers/IniParser.js

const { ParseError } = require('../errors');

class IniParser {
  static get extensions() {
    return ['.ini', '.cfg', '.conf'];
  }

  static get name() {
    return 'INI';
  }

  /**
   * Parse INI content into nested object
   * Supports: sections, key=value, comments (# and ;)
   */
  parse(content, filePath = null) {
    const result = {};
    let currentSection = null;
    const lines = content.split(/\r?\n/);

    for (let i = 0; i < lines.length; i++) {
      const lineNum = i + 1;
      const rawLine = lines[i];
      const line = rawLine.trim();

      // Skip empty lines and comments
      if (!line || line.startsWith('#') || line.startsWith(';')) {
        continue;
      }

      // Section header: [section]
      if (line.startsWith('[')) {
        const sectionMatch = line.match(/^\[([^\]]+)\]$/);
        if (!sectionMatch) {
          throw new ParseError(
            `Malformed section header: "${line}"`,
            { filePath, line: lineNum, rawContent: content }
          );
        }
        currentSection = sectionMatch[1].trim();
        if (!result[currentSection]) {
          result[currentSection] = {};
        }
        continue;
      }

      // Key-value pair: key = value
      const kvMatch = line.match(/^([^=]+?)(?:\s*=\s*)(.*)$/);
      if (!kvMatch) {
        throw new ParseError(
          `Invalid syntax: "${line}" (expected key=value)`,
          { filePath, line: lineNum, rawContent: content }
        );
      }

      const key = kvMatch[1].trim();
      let value = kvMatch[2].trim();

      // Validate key
      if (!key) {
        throw new ParseError(
          `Empty key found`,
          { filePath, line: lineNum, rawContent: content }
        );
      }

      // Parse value types
      value = this._parseValue(value);

      // Assign to section or root
      if (currentSection) {
        result[currentSection][key] = value;
      } else {
        result[key] = value;
      }
    }

    return result;
  }

  /**
   * Convert string values to appropriate types
   */
  _parseValue(value) {
    // Remove inline comments
    const commentIndex = value.search(/\s+[#;]/);
    if (commentIndex > -1) {
      value = value.substring(0, commentIndex).trim();
    }

    // Remove surrounding quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      return value.slice(1, -1);
    }

    // Boolean
    if (value.toLowerCase() === 'true') return true;
    if (value.toLowerCase() === 'false') return false;

    // Null
    if (value.toLowerCase() === 'null' || value === '') return null;

    // Number
    if (/^-?\d+(\.\d+)?$/.test(value)) {
      return Number(value);
    }

    return value;
  }

  /**
   * Serialize config object to INI format
   */
  serialize(data) {
    const lines = [];

    // Root-level keys first
    for (const [key, value] of Object.entries(data)) {
      if (typeof value !== 'object' || value === null) {
        lines.push(`${key} = ${this._serializeValue(value)}`);
      }
    }

    if (lines.length > 0) lines.push('');

    // Sections
    for (const [section, values] of Object.entries(data)) {
      if (typeof values === 'object' && values !== null) {
        lines.push(`[${section}]`);
        for (const [key, value] of Object.entries(values)) {
          lines.push(`${key} = ${this._serializeValue(value)}`);
        }
        lines.push('');
      }
    }

    return lines.join('\n');
  }

  _serializeValue(value) {
    if (value === null) return '';
    if (typeof value === 'string' && value.includes(' ')) return `"${value}"`;
    return String(value);
  }
}

module.exports = IniParser;
