// src/parsers/EnvParser.js

const { ParseError } = require('../errors');

class EnvParser {
  static get extensions() {
    return ['.env'];
  }

  static get name() {
    return 'ENV';
  }

  /**
   * Parse .env format content
   * Supports: KEY=VALUE, quoted values, multiline, variable expansion
   */
  parse(content, filePath = null) {
    const result = {};
    const lines = content.split(/\r?\n/);
    let i = 0;

    while (i < lines.length) {
      const lineNum = i + 1;
      const rawLine = lines[i];
      const line = rawLine.trim();

      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        i++;
        continue;
      }

      // Optional 'export' prefix
      const exportMatch = line.match(/^export\s+(.*)$/);
      const effectiveLine = exportMatch ? exportMatch[1] : line;

      // Key=Value pattern
      const kvMatch = effectiveLine.match(/^([A-Za-z_][A-Za-z0-9_]*)(?:\s*=\s*)([\s\S]*)$/);
      if (!kvMatch) {
        throw new ParseError(
          `Invalid env syntax: "${line}"`,
          { filePath, line: lineNum, rawContent: content }
        );
      }

      const key = kvMatch[1];
      let value = kvMatch[2].trim();

      // Handle quoted values (including multiline)
      if (value.startsWith('"') || value.startsWith("'")) {
        const quote = value[0];
        const parsed = this._parseQuotedValue(value, quote, lines, i, filePath);
        value = parsed.value;
        i = parsed.nextLine;
      } else {
        // Unquoted: strip inline comments
        const commentIdx = value.indexOf(' #');
        if (commentIdx > -1) {
          value = value.substring(0, commentIdx).trim();
        }
        i++;
      }

      // Variable expansion: ${VAR} or $VAR
      value = this._expandVariables(value, result);

      result[key] = value;
    }

    return result;
  }

  /**
   * Handle quoted (possibly multiline) values
   */
  _parseQuotedValue(startValue, quote, lines, lineIndex, filePath) {
    let value = startValue.substring(1); // Remove opening quote
    let currentLine = lineIndex;

    // Check if closing quote is on the same line
    const closeIdx = value.indexOf(quote);
    if (closeIdx > -1) {
      return {
        value: value.substring(0, closeIdx),
        nextLine: currentLine + 1
      };
    }

    // Multiline value
    const parts = [value];
    currentLine++;

    while (currentLine < lines.length) {
      const line = lines[currentLine];
      const endIdx = line.indexOf(quote);

      if (endIdx > -1) {
        parts.push(line.substring(0, endIdx));
        return {
          value: parts.join('\n'),
          nextLine: currentLine + 1
        };
      }

      parts.push(line);
      currentLine++;
    }

    throw new ParseError(
      `Unterminated ${quote === '"' ? 'double' : 'single'}-quoted string`,
      { filePath, line: lineIndex + 1 }
    );
  }

  /**
   * Expand ${VAR} references in values
   */
  _expandVariables(value, context) {
    return value.replace(/\$\{([A-Za-z_][A-Za-z0-9_]*)\}/g, (_, varName) => {
      // Check context first, then process.env
      if (varName in context) return context[varName];
      if (varName in process.env) return process.env[varName];
      return '';
    });
  }

  serialize(data) {
    return Object.entries(data)
      .map(([key, value]) => {
        const strValue = String(value);
        // Quote if contains spaces or special chars
        if (strValue.includes(' ') || strValue.includes('\n') || strValue.includes('#')) {
          return `${key}="${strValue.replace(/"/g, '\\"')}"`;
        }
        return `${key}=${strValue}`;
      })
      .join('\n');
  }
}

module.exports = EnvParser;
