// src/parsers/index.js

const JsonParser = require('./JsonParser');
const IniParser = require('./IniParser');
const EnvParser = require('./EnvParser');

const parsers = [JsonParser, IniParser, EnvParser];

/**
 * Build a map of file extension → parser instance
 */
function createParserRegistry() {
  const registry = new Map();

  for (const ParserClass of parsers) {
    const instance = new ParserClass();
    for (const ext of ParserClass.extensions) {
      registry.set(ext, instance);
    }
  }

  return registry;
}

module.exports = {
  createParserRegistry,
