# JavaScript Migration Helper with Rate Limiting

This example demonstrates a migration helper class that processes records in batches, respects API rate limits, handles retries with backoff, and tracks progress.

## Core Implementation

```javascript
// migrationHelper.js

/**
 * Token Bucket rate limiter
 * Controls the flow of requests to stay within API limits.
 */
class TokenBucket {
  #tokens;
  #maxTokens;
  #refillRate; // tokens per ms
  #lastRefill;

  constructor(maxTokens, refillPerSecond) {
    this.#maxTokens = maxTokens;
    this.#tokens = maxTokens;
    this.#refillRate = refillPerSecond / 1000;
    this.#lastRefill = Date.now();
  }

  /**
   * Refills tokens based on elapsed time since last refill.
   */
  #refill() {
    const now = Date.now();
    const elapsed = now - this.#lastRefill;
    this.#tokens = Math.min(
      this.#maxTokens,
      this.#tokens + elapsed * this.#refillRate
    );
    this.#lastRefill = now;
  }

  /**
   * Waits until a token is available, then consumes it.
   * @param {number} cost - Number of tokens this operation costs (default: 1)
   * @returns {Promise<void>}
   */
  async acquire(cost = 1) {
    this.#refill();

    if (this.#tokens >= cost) {
      this.#tokens -= cost;
      return;
    }

    // Calculate wait time until enough tokens are available
    const deficit = cost - this.#tokens;
    const waitMs = Math.ceil(deficit / this.#refillRate);

    await new Promise((resolve) => setTimeout(resolve, waitMs));

    this.#refill();
    this.#tokens -= cost;
  }

  get availableTokens() {
    this.#refill();
    return Math.floor(this.#tokens);
  }
}

/**
 * Tracks and reports migration progress.
 */
class ProgressTracker {
  #total;
  #processed;
  #succeeded;
  #failed;
  #skipped;
  #startTime;
  #listeners;

  constructor(total) {
    this.#total = total;
    this.#processed = 0;
    this.#succeeded = 0;
    this.#failed = 0;
    this.#skipped = 0;
    this.#startTime = Date.now();
    this.#listeners = [];
  }

  onProgress(listener) {
    this.#listeners.push(listener);
  }

  recordSuccess(count = 1) {
    this.#succeeded += count;
    this.#processed += count;
    this.#notify();
  }

  recordFailure(count = 1) {
    this.#failed += count;
    this.#processed += count;
    this.#notify();
  }

  recordSkip(count = 1) {
    this.#skipped += count;
    this.#processed += count;
    this.#notify();
  }

  #notify() {
    const snapshot = this.snapshot();
    for (const listener of this.#listeners) {
      listener(snapshot);
    }
  }

  snapshot() {
    const elapsed = Date.now() - this.#startTime;
    const rate = this.#processed / (elapsed / 1000) || 0;
    const remaining = this.#total - this.#processed;
    const eta = rate > 0 ? remaining / rate : Infinity;

    return {
      total: this.#total,
      processed: this.#processed,
      succeeded: this.#succeeded,
      failed: this.#failed,
      skipped: this.#skipped,
      remaining,
      percent: this.#total > 0
        ? ((this.#processed / this.#total) * 100).toFixed(1)
        : 0,
      elapsedMs: elapsed,
      ratePerSecond: rate.toFixed(2),
      etaSeconds: eta === Infinity ? null : Math.ceil(eta),
    };
  }
}

/**
 * Main migration helper class.
 * Orchestrates batched data migration with rate limiting and retries.
 */
class MigrationHelper {
  #config;
  #rateLimiter;
  #progress;
  #errors;
  #abortController;
  #state; // 'idle' | 'running' | 'paused' | 'aborted' | 'completed'
  #pausePromise;
  #pauseResolve;
  #checkpoint;

  /**
   * @param {Object} config
   * @param {number} config.rateLimit         - Max requests per second
   * @param {number} config.burstLimit        - Max burst size (default: rateLimit)
   * @param {number} config.batchSize         - Records per batch (default: 50)
   * @param {number} config.maxRetries        - Max retry attempts (default: 3)
   * @param {number} config.baseDelayMs       - Base retry delay in ms (default: 1000)
   * @param {number} config.maxDelayMs        - Max retry delay cap (default: 30000)
   * @param {number} config.concurrency       - Parallel batches (default: 1)
   * @param {boolean} config.continueOnError  - Skip failed records (default: true)
   * @param {Function} config.onProgress      - Progress callback
   * @param {Function} config.onError         - Error callback
   * @param {Function} config.shouldRetry     - Custom retry predicate
   */
  constructor(config) {
    this.#config = {
      rateLimit: 10,
      burstLimit: config.rateLimit || 10,
      batchSize: 50,
      maxRetries: 3,
      baseDelayMs: 1000,
      maxDelayMs: 30000,
      concurrency: 1,
      continueOnError: true,
      onProgress: null,
      onError: null,
      shouldRetry: null,
      ...config,
    };

    this.#rateLimiter = new TokenBucket(
      this.#config.burstLimit,
      this.#config.rateLimit
    );
    this.#errors = [];
    this.#state = "idle";
    this.#checkpoint = null;
  }

  /**
   * Primary entry point. Fetches records, processes them in batches.
   *
   * @param {Object} params
   * @param {Function} params.fetchRecords    - async () => Record[]
   * @param {Function} params.transformRecord - (record) => transformedRecord
   * @param {Function} params.migrateRecord   - async (transformed) => result
   * @param {Function} [params.validate]      - (record) => { valid, reason? }
   * @returns {Promise<MigrationResult>}
   */
  async run({ fetchRecords, transformRecord, migrateRecord, validate }) {
    this.#state = "running";
    this.#abortController = new AbortController();

    try {
      // --- Step 1: Fetch all source records ---
      console.log("[Migration] Fetching source records...");
      const records = await fetchRecords();
      console.log(`[Migration] Found ${records.length} records to migrate.`);

      // --- Step 2: Initialize progress tracking ---
      this.#progress = new ProgressTracker(records.length);
      if (this.#config.onProgress) {
        this.#progress.onProgress(this.#config.onProgress);
      }

      // --- Step 3: Split into batches ---
      const batches = this.#createBatches(records, this.#config.batchSize);
      console.log(
        `[Migration] Split into ${batches.length} batches ` +
          `(size: ${this.#config.batchSize}, concurrency: ${this.#config.concurrency})`
      );

      // --- Step 4: Resume from checkpoint if available ---
      let startBatch = 0;
      if (this.#checkpoint !== null) {
        startBatch = this.#checkpoint;
        console.log(`[Migration] Resuming from batch ${startBatch}`);
      }

      // --- Step 5: Process batches with concurrency control ---
      const batchQueue = batches.slice(startBatch);
      await this.#processWithConcurrency(batchQueue, async (batch, index) => {
        const batchIndex = startBatch + index;
        await this.#processBatch(
          batch,
          batchIndex,
          { transformRecord, migrateRecord, validate }
        );
        this.#checkpoint = batchIndex + 1;
      });

      this.#state = "completed";
      return this.#buildResult();
    } catch (error) {
      if (this.#state === "aborted") {
        console.log("[Migration] Aborted by user.");
      } else {
        this.#state = "aborted";
        console.error("[Migration] Fatal error:", error.message);
      }
      return this.#buildResult(error);
    }
  }

  /**
   * Processes async tasks with bounded concurrency.
   */
  async #processWithConcurrency(items, handler) {
    const concurrency = this.#config.concurrency;
    let index = 0;

    const workers = Array.from({ length: concurrency }, async () => {
      while (index < items.length) {
        this.#checkAborted();
        await this.#checkPaused();

        const currentIndex = index++;
        if (currentIndex >= items.length) break;

        await handler(items[currentIndex], currentIndex);
      }
    });

    await Promise.all(workers);
  }

  /**
   * Processes a single batch of records.
   */
  async #processBatch(batch, batchIndex, { transformRecord, migrateRecord, validate }) {
    console.log(
      `[Batch ${batchIndex}] Processing ${batch.length} records...`
    );

    for (const record of batch) {
      this.#checkAborted();
      await this.#checkPaused();

      try {
        // Validate
        if (validate) {
          const { valid, reason } = validate(record);
          if (!valid) {
            console.warn(
              `[Batch ${batchIndex}] Skipping record ${record.id}: ${reason}`
            );
            this.#progress.recordSkip();
            continue;
          }
        }

        // Transform
        const transformed = transformRecord(record);

        // Rate-limit, then migrate with retries
        await this.#rateLimiter.acquire();
        await this.#executeWithRetry(
          () => migrateRecord(transformed),
          record
        );

        this.#progress.recordSuccess();
      } catch (error) {
        this.#handleRecordError(record, error, batchIndex);
      }
    }
  }

  /**
   * Retries an async operation with exponential backoff.
   * Respects Retry-After headers from 429 responses.
   */
  async #executeWithRetry(operation, record) {
    const { maxRetries, baseDelayMs, maxDelayMs, shouldRetry } = this.#config;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        return await operation();
      } catch (error) {
        const isLast = attempt === maxRetries;
        const retryable = this.#isRetryable(error, shouldRetry);

        if (isLast || !retryable) {
          throw error;
        }

        // Use Retry-After header if present (429 responses)
        const retryAfter = this.#parseRetryAfter(error);
        const delay = retryAfter
          ?? Math.min(baseDelayMs * 2 ** attempt + this.#jitter(), maxDelayMs);

        console.warn(
          `[Retry] Record ${record.id} – attempt ${attempt + 1}/${maxRetries}, ` +
            `waiting ${delay}ms (${error.message})`
        );

        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }

  /**
   * Determines whether an error is retryable.
   */
  #isRetryable(error, customPredicate) {
    if (customPredicate) return customPredicate(error);

    // Retry on rate limits
    if (error.status === 429) return true;

    // Retry on server errors
    if (error.status >= 500) return true;

    // Retry on network errors
    if (error.code === "ECONNRESET" || error.code === "ETIMEDOUT") return true;
    if (error.message?.includes("fetch failed")) return true;

    return false;
  }

  /**
   * Extracts Retry-After value from an error/response (in ms).
   */
  #parseRetryAfter(error) {
    const header = error.headers?.get?.("retry-after")
      ?? error.retryAfter;
    if (!header) return null;

    const seconds = Number(header);
    if (!Number.isNaN(seconds)) return seconds * 1000;

    // Could also be an HTTP-date
    const date = Date.parse(header);
    if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

    return null;
  }

  /**
   * Adds random jitter to prevent thundering herd.
   */
  #jitter() {
    return Math.floor(Math.random() * 500);
  }

  /**
   * Handles a record-level error based on continueOnError config.
   */
  #handleRecordError(record, error, batchIndex) {
    const entry = {
      recordId: record.id,
      batchIndex,
      error: error.message,
      timestamp: new Date().toISOString(),
    };

    this.#errors.push(entry);
    this.#progress.recordFailure();

    if (this.#config.onError) {
      this.#config.onError(entry);
    }

    if (!this.#config.continueOnError) {
      throw new Error(
        `Migration stopped at record ${record.id}: ${error.message}`
      );
    }

    console.error(
      `[Batch ${batchIndex}] Failed record ${record.id}: ${error.message}`
    );
  }

  /**
   * Splits an array into fixed-size chunks.
   */
  #createBatches(items, size) {
    const batches = [];
    for (let i = 0; i < items.length; i += size) {
      batches.push(items.slice(i, i + size));
    }
    return batches;
  }

  // --- Pause / Resume / Abort controls ---

  #checkAborted() {
    if (this.#abortController.signal.aborted) {
      throw new Error("Migration aborted");
    }
  }

  async #checkPaused() {
    if (this.#state === "paused" && this.#pausePromise) {
      console.log("[Migration] Paused. Waiting for resume...");
      await this.#pausePromise;
    }
  }

  pause() {
    if (this.#state !== "running") return;
    this.#state = "paused";
    this.#pausePromise = new Promise((resolve) => {
      this.#pauseResolve = resolve;
    });
    console.log("[Migration] Pause requested.");
  }

  resume() {
    if (this.#state !== "paused") return;
    this.#state = "running";
    this.#pauseResolve?.();
    this.#pausePromise = null;
    console.log("[Migration] Resumed.");
  }

  abort() {
    this.#state = "aborted";
    this.#abortController?.abort();
    this.#pauseResolve?.(); // unblock if paused
    console.log("[Migration] Abort requested.");
  }

  // --- Result builder ---

  #buildResult(fatalError = null) {
    const progress = this.#progress?.snapshot() ?? {};
    return {
      status: this.#state,
      ...progress,
      errors: [...this.#errors],
      checkpoint: this.#checkpoint,
      fatalError: fatalError?.message ?? null,
    };
  }

  get state() {
    return this.#state;
  }

  get errors() {
    return [...this.#errors];
  }
}

