```javascript
// src/worker.js
import { Worker } from "bullmq";
import { connection } from "./queue.js";
import { reportRegistry } from "./reports/registry.js";
import { storage } from "./storage.js";
import { notifier } from "./notifier.js";

export function createWorker(concurrency = 3) {
  const worker = new Worker(
    "report-generation",
    async (job) => {
      const { reportType, params, requestedBy } = job.data;

      // 1. Validate report type exists
      const generator = reportRegistry.get(reportType);
      if (!generator) {
        throw new Error(`Unknown report type: ${reportType}`);
      }

      // 2. Progress: starting
      await job.updateProgress({ stage: "querying", percent: 0 });
      job.log(`Starting ${reportType} report for user ${requestedBy}`);

      // 3. Fetch data
      const data = await generator.fetchData(params);
      await job.updateProgress({ stage: "generating", percent: 40 });
      job.log(`Fetched ${data.length} rows`);

      // 4. Generate the file
      const file = await generator.render(data, params);
      await job.updateProgress({ stage: "uploading", percent: 80 });
      job.log(`Rendered ${file.format} (${file.buffer.length} bytes)`);

      // 5. Upload to storage
      const fileKey = buildFileKey(reportType, job.id, file.format);
      const downloadUrl = await storage.upload(fileKey, file.buffer, {
        contentType: file.mimeType,
        metadata: { reportType, jobId: job.id, requestedBy },
      });

      await job.updateProgress({ stage: "complete", percent: 100 });

      // 6. Return result (stored with the job)
      return {
        downloadUrl,
        fileKey,
        rowCount: data.length,
        format: file.format,
        generatedAt: new Date().toISOString(),
      };
    },
    {
      connection,
      concurrency,
      limiter: {
        max: 10,       // max 10 jobs
        duration: 60_000, // per minute — protects your DB
      },
    }
  );

  // --- Event handlers ---

  worker.on("completed", async (job, result) => {
    console.log(`✓ Job ${job.id} completed: ${result.downloadUrl}`);
    await notifier.send(job.data.requestedBy, {
      type: "report_ready",
      reportType: job.data.reportType,
      downloadUrl: result.downloadUrl,
    });
  });

  worker.on("failed", async (job, error) => {
    console.error(`✗ Job ${job?.id} failed (attempt ${job?.attemptsMade}): ${error.message}`);

    // Only notify on final failure (all retries exhausted)
    if (job && job.attemptsMade >= job.opts.attempts) {
      await notifier.send(job.data.requestedBy, {
        type: "report_failed",
        reportType: job.data.reportType,
        error: error.message,
      });
    }
  });

  worker.on("error", (err) => {
    console.error("Worker error:", err);
  });

  return worker;
}

function buildFileKey(reportType, jobId, format) {
  const date = new Date().toISOString().slice(0, 10);
  return `reports/${date}/${reportType}-${jobId}.${format}`;
}
