// src/reports/sales.js
import { db } from "../db.js"; // your database client

export const salesReport = {
  async fetchData({ startDate, endDate, storeIds }) {
    // Real query — adjust to your ORM/driver
    const rows = await db.query(
      `SELECT
         date, store_id, product_id,
         SUM(quantity) as units_sold,
         SUM(revenue)  as revenue
       FROM sales
       WHERE date BETWEEN $1 AND $2
         AND ($3::int[] IS NULL OR store_id = ANY($3))
       GROUP BY date, store_id, product_id
       ORDER BY date`,
      [startDate, endDate, storeIds?.length ? storeIds : null]
    );
    return rows;
  },

  async render(data, params) {
    const format = params.format || "csv";

    if (format === "csv") {
      return renderCsv(data);
    }
    if (format === "xlsx") {
      return renderXlsx(data);
    }
    throw new Error(`Unsupported format: ${format}`);
  },
};

function renderCsv(rows) {
  if (rows.length === 0) {
    return { buffer: Buffer.from(""), format: "csv", mimeType: "text/csv" };
  }

  const headers = Object.keys(rows[0]);
  const lines = [
    headers.join(","),
    ...rows.map((row) =>
      headers.map((h) => escapeCsvField(row[h])).join(",")
    ),
  ];

  return {
    buffer: Buffer.from(lines.join("\n"), "utf-8"),
    format: "csv",
    mimeType: "text/csv",
  };
}

async function renderXlsx(rows) {
  // exceljs is heavy — only import when needed
  const ExcelJS = await import("exceljs");
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet("Sales");

  if (rows.length > 0) {
    sheet.columns = Object.keys(rows[0]).map((key) => ({
      header: key,
      key,
      width: 18,
    }));
    sheet.addRows(rows);
  }

  const buffer = await workbook.xlsx.writeBuffer();
  return {
    buffer: Buffer.from(buffer),
    format: "xlsx",
    mimeType: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  };
}

function escapeCsvField(value) {
  if (value == null) return "";
  const str = String(value);
  return str.includes(",") || str.includes('"') || str.includes("\n")
    ? `"${str.replace(/"/g, '""')}"`
    : str;
}
