```rust
mod backup;
mod manifest;
mod worker;

use std::path::PathBuf;
use std::time::Duration;
use tracing::{info, error};
use worker::{BackupWorker, WorkerCommand};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    // Initialize structured logging
    tracing_subscriber::fmt()
        .with_target(false)
        .with_timer(tracing_subscriber::fmt::time::uptime())
        .init();

    // ── Configuration ──────────────────────────────────────────────
    let source_dir = PathBuf::from("./test_source");
    let backup_dir = PathBuf::from("./test_backups");
    let interval = Duration::from_secs(30);

    // Create test directories
    std::fs::create_dir_all(&source_dir)?;
    std::fs::create_dir_all(&backup_dir)?;

    // Create some sample files to back up
    create_sample_files(&source_dir)?;

    // ── Launch the background worker ───────────────────────────────
    let (worker, cmd_tx) = BackupWorker::new(source_dir, backup_dir, interval);
    let worker_handle = tokio::spawn(worker.run());

    // ── Simulate application lifecycle ─────────────────────────────

    // Trigger an immediate backup
    info!("Requesting immediate backup...");
    let (resp_tx, resp_rx) = tokio::sync::oneshot::channel();
    cmd_tx.send(WorkerCommand::RunNow { respond_to: resp_tx }).await?;
    match resp_rx.await? {
        Ok(summary) => info!("Backup complete: {summary}"),
        Err(e) => error!("Backup failed: {e}"),
    }

    // Request status
    let (resp_tx, resp_rx) = tokio::sync::oneshot::channel();
    cmd_tx.send(WorkerCommand::GetStatus { respond_to: resp_tx }).await?;
    let status = resp_rx.await?;
    info!("Worker status: {status:#?}");

    // Let scheduled backups run for a while
    info!("Letting scheduled backups run for 65 seconds (modify files to see incremental)...");
    tokio::time::sleep(Duration::from_secs(65)).await;

    // Graceful shutdown
    info!("Sending shutdown signal...");
    cmd_tx.send(WorkerCommand::Shutdown).await?;
    worker_handle.await??;
    info!("Worker shut down cleanly.");

    Ok(())
}

fn create_sample_files(dir: &std::path::Path) -> std::io::Result<()> {
    std::fs::write(dir.join("readme.txt"), "Hello, incremental backups!")?;
    std::fs::write(dir.join("data.csv"), "id,name,value\n1,alpha,100\n2,beta,200\n")?;
    let sub = dir.join("subdir");
    std::fs::create_dir_all(&sub)?;
    std::fs::write(sub.join("nested.log"), "log entry 1\nlog entry 2\n")?;
    Ok(())
}
