## `src/manifest.rs` — Tracks file states between backups

```rust
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::{Path, PathBuf};

/// Persisted manifest that records the state of every backed-up file.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackupManifest {
    /// Monotonically increasing backup generation number.
    pub generation: u64,
    /// When this manifest was written.
    pub created_at: DateTime<Utc>,
    /// Map of *relative* file path → entry metadata.
    pub entries: HashMap<PathBuf, FileEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct FileEntry {
    /// SHA-256 hex digest of the file contents.
    pub content_hash: String,
    /// File size in bytes.
    pub size: u64,
    /// Last-modified time reported by the OS.
    pub modified: DateTime<Utc>,
}

/// What changed between two manifests.
#[derive(Debug, Default)]
pub struct ChangeSet {
    pub added: Vec<PathBuf>,
    pub modified: Vec<PathBuf>,
    pub deleted: Vec<PathBuf>,
}

impl ChangeSet {
    pub fn total_changes(&self) -> usize {
        self.added.len() + self.modified.len() + self.deleted.len()
    }

    pub fn is_empty(&self) -> bool {
        self.total_changes() == 0
    }
}

impl BackupManifest {
    /// Start a fresh manifest (generation 0).
    pub fn empty() -> Self {
        Self {
            generation: 0,
            created_at: Utc::now(),
            entries: HashMap::new(),
        }
    }

    /// Load from a JSON file, or return an empty manifest.
    pub fn load_or_default(path: &Path) -> Self {
        std::fs::read_to_string(path)
            .ok()
            .and_then(|s| serde_json::from_str(&s).ok())
            .unwrap_or_else(Self::empty)
    }

    /// Persist to a JSON file.
    pub fn save(&self, path: &Path) -> std::io::Result<()> {
        let json = serde_json::to_string_pretty(self)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
        // Atomic write: write to temp file, then rename
        let tmp = path.with_extension("tmp");
        std::fs::write(&tmp, json)?;
        std::fs::rename(tmp, path)?;
        Ok(())
    }

    /// Diff `self` (old) against a set of current entries to produce a change set.
    pub fn diff(&self, current: &HashMap<PathBuf, FileEntry>) -> ChangeSet {
        let mut cs = ChangeSet::default();

        // Find added and modified files
        for (path, entry) in current {
            match self.entries.get(path) {
                None => cs.added.push(path.clone()),
                Some(old) if old != entry => cs.modified.push(path.clone()),
                _ => {} // unchanged
            }
        }

        // Find deleted files
        for path in self.entries.keys() {
            if !current.contains_key(path) {
                cs.deleted.push(path.clone());
            }
        }

        // Sort for deterministic output
        cs.added.sort();
        cs.modified.sort();
        cs.deleted.sort();
        cs
    }
}
```

## `src/backup.rs` — Core incremental backup logic

```rust
use crate::manifest::{BackupManifest, ChangeSet, FileEntry};
use chrono::{DateTime, Utc};
use sha2::{Digest, Sha256};
use std::collections::HashMap;
use std::fmt;
use std::path::{Path, PathBuf};
use std::time::SystemTime;
use tracing::{debug, info, warn};

/// Result summary returned after a backup run.
#[derive(Debug, Clone)]
pub struct BackupSummary {
    pub generation: u64,
    pub files_added: usize,
    pub files_modified: usize,
    pub files_deleted: usize,
    pub bytes_copied: u64,
    pub duration: std::time::Duration,
    pub skipped_no_changes: bool,
}

impl fmt::Display for BackupSummary {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.skipped_no_changes {
            write!(f, "gen {} — no changes detected, skipped", self.generation)
        } else {
            write!(
                f,
                "gen {} — +{} ~{} -{} | {:.1} KB copied in {:.2?}",
                self.generation,
                self.files_added,
                self.files_modified,
                self.files_deleted,
                self.bytes_copied as f64 / 1024.0,
                self.duration,
            )
        }
    }
}

/// The incremental backup engine. Not async — runs blocking I/O,
/// intended to be called via `tokio::task::spawn_blocking`.
pub struct IncrementalBackup {
    source_root: PathBuf,
    backup_root: PathBuf,
    manifest_path: PathBuf,
}

impl IncrementalBackup {
    pub fn new(source_root: PathBuf, backup_root: PathBuf) -> Self {
        let manifest_path = backup_root.join("backup_manifest.json");
        Self {
            source_root,
            backup_root,
            manifest_path,
        }
    }

    /// Run a single incremental backup pass (blocking I/O).
    pub fn run_backup(&self) -> Result<BackupSummary, BackupError> {
        let start = std::time::Instant::now();

        // 1. Load (or create) the previous manifest
        let old_manifest = BackupManifest::load_or_default(&self.manifest_path);
        let new_generation = old_manifest.generation + 1;

        info!(
            gen = new_generation,
            source = %self.source_root.display(),
            "Starting incremental backup scan"
        );

        // 2. Scan the source tree and compute current file entries
        let current_entries = self.scan_source_tree()?;
        debug!("Scanned {} files in source", current_entries.len());

        // 3. Diff against old manifest
        let changes = old_manifest.diff(&current_entries);

        if changes.is_empty() {
            info!(gen = new_generation, "No changes detected — skipping copy");
            return Ok(BackupSummary {
                generation: new_generation,
                files_added: 0,
                files_modified: 0,
                files_deleted: 0,
                bytes_copied: 0,
                duration: start.elapsed(),
                skipped_no_changes: true,
            });
        }

        log_changes(&changes);

        // 4. Create a generation-specific backup directory
        let gen_dir = self.backup_root.join(format!("gen_{new_generation:05}"));
        std::fs::create_dir_all(&gen_dir)?;

        // 5. Copy added and modified files
        let bytes_copied = self.copy_changed_files(&changes, &current_entries, &gen_dir)?;

        // 6. Record deletions in a sidecar file
        if !changes.deleted.is_empty() {
            self.write_deletion_log(&changes.deleted, &gen_dir)?;
        }

        // 7. Build and persist the new manifest
        let new_manifest = BackupManifest {
            generation: new_generation,
            created_at: Utc::now(),
            entries: current_entries,
        };
        new_manifest.save(&self.manifest_path)?;

        let summary = BackupSummary {
            generation: new_generation,
            files_added: changes.added.len(),
            files_modified: changes.modified.len(),
            files_deleted: changes.deleted.len(),
            bytes_copied,
            duration: start.elapsed(),
            skipped_no_changes: false,
        };

        info!(%summary, "Backup generation complete");
        Ok(summary)
    }

    /// Recursively walk the source tree and build a map of relative paths → FileEntry.
    fn scan_source_tree(&self) -> Result<HashMap<PathBuf, FileEntry>, BackupError> {
        let mut entries = HashMap::new();
        self.walk_dir(&self.source_root, &mut entries)?;
        Ok(entries)
    }

    fn walk_dir(
        &self,
        dir: &Path,
        entries: &mut HashMap<PathBuf, FileEntry>,
    ) -> Result<(), BackupError> {
        let read_dir = std::fs::read_dir(dir).map_err(|e| BackupError::Io {
            context: format!("reading directory {}", dir.display()),
            source: e,
        })?;

        for item in read_dir {
            let item = item?;
            let path = item.path();
            let file_type = item.file_type()?;

            if file_type.is_dir() {
                self.walk_dir(&path, entries)?;
            } else if file_type.is_file() {
                let rel_path = path
                    .strip_prefix(&self.source_root)
                    .unwrap_or(&path)
                    .to_path_buf();

                match self.compute_file_entry(&path) {
                    Ok(entry) => {
                        entries.insert(rel_path, entry);
                    }
                    Err(e) => {
                        warn!(path = %path.display(), error = %e, "Skipping file");
                    }
                }
            }
            // Symlinks are intentionally skipped
        }
        Ok(())
    }

    /// Hash and stat a single file.
    fn compute_file_entry(&self, path: &Path) -> Result<FileEntry, BackupError> {
        let metadata = std::fs::metadata(path)?;
        let modified = system_time_to_chrono(metadata.modified()?);
        let size = metadata.len();

        // Stream-hash so we don't load huge files into memory
        let content_hash = hash_file(path)?;

        Ok(FileEntry {
            content_hash,
            size,
            modified,
        })
    }

    /// Copy only the files listed in `changes.added` and `changes.modified`.
    fn copy_changed_files(
        &self,
        changes: &ChangeSet,
        current_entries: &HashMap<PathBuf, FileEntry>,
        gen_dir: &Path,
    ) -> Result<u64, BackupError> {
        let mut total_bytes: u64 = 0;

        let files_to_copy = changes.added.iter().chain(changes.modified.iter());

        for rel_path in files_to_copy {
            let src = self.source_root.join(rel_path);
            let dst = gen_dir.join(rel_path);

            // Ensure parent directories exist in backup
            if let Some(parent) = dst.parent() {
                std::fs::create_dir_all(parent)?;
            }

            std::fs::copy(&src, &dst).map_err(|e| BackupError::Io {
                context: format!(
                    "copying {} → {}",
                    src.display(),
                    dst.display()
                ),
                source: e,
            })?;

            if let Some(entry) = current_entries.get(rel_path) {
                total_bytes += entry.size;
            }

            debug!(file = %rel_path.display(), "Copied");
        }

        Ok(total_bytes)
    }

    /// Write a list of deleted paths so a restore process knows what was removed.
    fn write_deletion_log(
        &self,
        deleted: &[PathBuf],
        gen_dir: &Path,
    ) -> Result<(), BackupError> {
        let log_path = gen_dir.join("_deletions.json");
        let json = serde_json::to_string_pretty(deleted)
            .map_err(|e| BackupError::Io {
                context: "serializing deletion log".into(),
                source: std::io::Error::new(std::io::ErrorKind::Other, e),
            })?;
        std::fs::write(log_path, json)?;
        Ok(())
    }
}

// ── Helpers ────────────────────────────────────────────────────────

fn hash_file(path: &Path) -> Result<String, BackupError> {
    use std::io::Read;
    let mut file = std::fs::File::open(path)?;
    let mut hasher = Sha256::new();
    let mut buf = [0u8; 8192];
    loop {
        let n = file.read(&mut buf)?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    Ok(format!("{:x}", hasher.finalize()))
}

fn system_time_to_chrono(t: SystemTime) -> DateTime<Utc> {
    let duration = t
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default();
    DateTime::from_timestamp(duration.as_secs() as i64, duration.subsec_nanos())
        .unwrap_or_default()
}

fn log_changes(cs: &ChangeSet) {
    for p in &cs.added {
        info!(file = %p.display(), "  + added");
    }
    for p in &cs.modified {
        info!(file = %p.display(), "  ~ modified");
    }
    for p in &cs.deleted {
        info!(file = %p.display(), "  - deleted");
    }
}

// ── Error type ─────────────────────────────────────────────────────

#[derive(Debug)]
pub enum BackupError {
    Io {
        context: String,
        source: std::io::Error,
    },
}

impl fmt::Display for BackupError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            BackupError::Io { context, source } => {
                write!(f, "{context}: {source}")
            }
        }
    }
}

impl std::error::Error for BackupError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            BackupError::Io { source, .. } => Some(source),
        }
    }
}

impl From<std::io::Error> for BackupError {
    fn from(e: std::io::Error) -> Self {
        BackupError::Io {
            context: String::new(),
            source: e,
        }
    }
}

use std::fmt;
