## Config Parser

```javascript
// src/ConfigParser.js

import { readFileSync, watchFile } from "fs";
import { resolve } from "path";
import { EventEmitter } from "events";

/**
 * Schema definition for validation.
 * Each field defines its type, default, constraints, and description.
 */
const RATE_LIMIT_SCHEMA = {
  algorithm: {
    type: "string",
    enum: ["token-bucket", "sliding-window", "fixed-window"],
    default: "token-bucket",
    description: "Rate limiting algorithm to use",
  },
  maxRequests: {
    type: "number",
    min: 1,
    max: 1_000_000,
    default: 100,
    description: "Maximum requests allowed in the time window",
  },
  windowMs: {
    type: "number",
    min: 1000,
    max: 86_400_000,
    default: 60_000,
    description: "Time window in milliseconds",
  },
  burstLimit: {
    type: "number",
    min: 1,
    max: 10_000,
    default: 20,
    description: "Maximum burst of requests allowed",
  },
  retryAfterMs: {
    type: "number",
    min: 100,
    max: 3_600_000,
    default: 1000,
    description: "Suggested retry delay sent in response headers",
  },
  blockDurationMs: {
    type: "number",
    min: 0,
    max: 86_400_000,
    default: 0,
    description: "Duration to block after limit exceeded (0 = no block)",
  },
  costPerRequest: {
    type: "number",
    min: 1,
    max: 100,
    default: 1,
    description: "Token cost per request (for weighted limiting)",
  },
  headers: {
    type: "boolean",
    default: true,
    description: "Whether to include rate limit headers in responses",
  },
};

class ConfigParser extends EventEmitter {
  #config = null;
  #filePath = null;
  #envPrefix;
  #watchHandle = null;

  /**
   * @param {object} options
   * @param {string} [options.envPrefix='RATE_LIMIT'] - Prefix for env variable overrides
   */
  constructor(options = {}) {
    super();
    this.#envPrefix = options.envPrefix ?? "RATE_LIMIT";
  }

  // ── Public API ──────────────────────────────────────────────

  /**
   * Load config from a JSON file, merge env overrides, validate.
   * @param {string} filePath - Absolute or relative path to JSON config
   * @returns {Readonly<object>} Frozen, validated config
   */
  loadFromFile(filePath) {
    this.#filePath = resolve(filePath);

    try {
      const raw = readFileSync(this.#filePath, "utf-8");
      const parsed = this.#parseJSON(raw);
      return this.#processConfig(parsed);
    } catch (err) {
      if (err.code === "ENOENT") {
        console.warn(`Config file not found: ${this.#filePath} — using defaults`);
        return this.#processConfig({});
      }
      throw new ConfigError(`Failed to load config: ${err.message}`, err);
    }
  }

  /**
   * Load config from a plain object (useful for testing / programmatic use).
   * @param {object} obj
   * @returns {Readonly<object>}
   */
  loadFromObject(obj) {
    return this.#processConfig(structuredClone(obj));
  }

  /**
   * Build a config entirely from environment variables.
   * @returns {Readonly<object>}
   */
  loadFromEnv() {
    return this.#processConfig(this.#readEnvOverrides());
  }

  /**
   * Watch the config file for changes and emit 'reload' events.
   * @param {number} [intervalMs=5000]
   */
  watch(intervalMs = 5000) {
    if (!this.#filePath) {
      throw new ConfigError("No file loaded — call loadFromFile first");
    }

    this.#watchHandle = watchFile(
      this.#filePath,
      { interval: intervalMs },
      () => {
        try {
          const updated = this.loadFromFile(this.#filePath);
          this.emit("reload", updated);
        } catch (err) {
          this.emit("error", err);
        }
      }
    );
  }

  /** Stop watching. */
  unwatch() {
    if (this.#watchHandle) {
      this.#watchHandle = null;
    }
  }

  /** Return the resolved config for a specific route + optional tier. */
  getRouteConfig(route, tier = null) {
    if (!this.#config) {
      throw new ConfigError("No config loaded");
    }

    // Start with global defaults
    let resolved = { ...this.#config.global };

    // Layer on the most-specific matching route
    const routeOverride = this.#matchRoute(route);
    if (routeOverride) {
      resolved = { ...resolved, ...routeOverride };
    }

    // Layer on tier limits
    if (tier && this.#config.tiers?.[tier]) {
      resolved = { ...resolved, ...this.#config.tiers[tier] };
    }

    return Object.freeze(resolved);
  }

  /** Check whether an IP is whitelisted. */
  isWhitelisted(ip) {
    return this.#matchIpList(this.#config?.whitelist ?? [], ip);
  }

  /** Check whether an IP is blacklisted. */
  isBlacklisted(ip) {
    return this.#matchIpList(this.#config?.blacklist ?? [], ip);
  }

  get config() {
    return this.#config;
  }

  // ── Internal helpers ────────────────────────────────────────

  #processConfig(raw) {
    // 1. Apply env-var overrides to the global section
    const envOverrides = this.#readEnvOverrides();
    if (raw.global || Object.keys(envOverrides).length) {
      raw.global = { ...raw.global, ...envOverrides };
    }

    // 2. Validate & apply defaults
    raw.global = this.#validateSection(raw.global ?? {}, "global");

    if (raw.routes) {
      for (const [route, section] of Object.entries(raw.routes)) {
        raw.routes[route] = this.#validateSection(section, `routes.${route}`);
      }
    }

    if (raw.tiers) {
      for (const [tier, section] of Object.entries(raw.tiers)) {
        raw.tiers[tier] = this.#validateSection(section, `tiers.${tier}`);
      }
    }

    this.#validateIpList(raw.whitelist, "whitelist");
    this.#validateIpList(raw.blacklist, "blacklist");
    this.#validateStorage(raw.storage);

    // 3. Freeze and cache
    this.#config = this.#deepFreeze(raw);
    return this.#config;
  }

  /** Validate one section against the schema, returning a merged copy. */
  #validateSection(section, label) {
    const errors = [];
    const result = {};

    for (const [key, rule] of Object.entries(RATE_LIMIT_SCHEMA)) {
      const value = section[key] ?? rule.default;

      // Type check
      if (typeof value !== rule.type) {
        errors.push(
          `${label}.${key}: expected ${rule.type}, got ${typeof value}`
        );
        result[key] = rule.default;
        continue;
      }

      // Enum check
      if (rule.enum && !rule.enum.includes(value)) {
        errors.push(
          `${label}.${key}: must be one of [${rule.enum}], got "${value}"`
        );
        result[key] = rule.default;
        continue;
      }

      // Range check
      if (rule.type === "number") {
        if (value < rule.min || value > rule.max) {
          errors.push(
            `${label}.${key}: ${value} outside range [${rule.min}–${rule.max}]`
          );
          result[key] = Math.min(Math.max(value, rule.min), rule.max);
          continue;
        }
      }

      result[key] = value;
    }

    // Logical cross-field check
    if (result.burstLimit > result.maxRequests) {
      errors.push(
        `${label}: burstLimit (${result.burstLimit}) > maxRequests (${result.maxRequests})`
      );
      result.burstLimit = result.maxRequests;
    }

    if (errors.length) {
      console.warn(`Config warnings in [${label}]:\n  • ${errors.join("\n  • ")}`);
    }

    return result;
  }

  /** Read RATE_LIMIT_* env vars and coerce types. */
  #readEnvOverrides() {
    const overrides = {};
    const prefix = `${this.#envPrefix}_`;

    for (const [envKey, envVal] of Object.entries(process.env)) {
      if (!envKey.startsWith(prefix)) continue;

      const configKey = this.#envKeyToConfigKey(envKey.slice(prefix.length));
      if (!(configKey in RATE_LIMIT_SCHEMA)) continue;

      overrides[configKey] = this.#coerceType(
        envVal,
        RATE_LIMIT_SCHEMA[configKey].type
      );
    }

    return overrides;
  }

  /** RATE_LIMIT_MAX_REQUESTS → maxRequests */
  #envKeyToConfigKey(envSuffix) {
    return envSuffix
      .toLowerCase()
      .replace(/_([a-z])/g, (_, ch) => ch.toUpperCase());
  }

  #coerceType(value, type) {
    switch (type) {
      case "number": {
        const n = Number(value);
        return Number.isNaN(n) ? undefined : n;
      }
      case "boolean":
        return value === "true" || value === "1";
      default:
        return value;
    }
  }

  /** Match a request path against configured route patterns. */
  #matchRoute(path) {
    if (!this.#config.routes) return null;

    // Exact match first
    if (this.#config.routes[path]) return this.#config.routes[path];

    // Wildcard / prefix match (longest wins)
    let bestMatch = null;
    let bestLen = 0;

    for (const [pattern, cfg] of Object.entries(this.#config.routes)) {
      if (!pattern.endsWith("*")) continue;
      const prefix = pattern.slice(0, -1);
      if (path.startsWith(prefix) && prefix.length > bestLen) {
        bestMatch = cfg;
        bestLen = prefix.length;
      }
    }

    return bestMatch;
  }

  #matchIpList(list = [], ip) {
    return list.some((pattern) => {
      if (pattern === ip) return true;
      if (pattern.endsWith("*")) {
        return ip.startsWith(pattern.slice(0, -1));
      }
      return false;
    });
  }

  #validateIpList(list, label) {
    if (list && !Array.isArray(list)) {
      throw new ConfigError(`${label} must be an array`);
    }
  }

  #validateStorage(storage) {
    if (!storage) return;
    const validTypes = ["memory", "redis", "memcached"];
    if (storage.type && !validTypes.includes(storage.type)) {
      throw new ConfigError(
        `storage.type must be one of [${validTypes}], got "${storage.type}"`
      );
    }
  }

  #parseJSON(raw) {
    try {
      return JSON.parse(raw);
    } catch {
      throw new ConfigError("Invalid JSON in config file");
    }
  }

  #deepFreeze(obj) {
    if (obj === null || typeof obj !== "object") return obj;
    Object.freeze(obj);
    for (const val of Object.values(obj)) this.#deepFreeze(val);
    return obj;
  }
}

class ConfigError extends Error {
  constructor(message, cause) {
    super(message);
    this.name = "ConfigError";
    this.cause = cause;
  }
}

export { ConfigParser, ConfigError, RATE_LIMIT_SCHEMA };
