## Token-Bucket Rate Limiter

```javascript
// src/RateLimiter.js

/**
 * Token-bucket rate limiter driven by a parsed config.
 *
 * Each "bucket" refills at a constant rate:
 *   refillRate = maxRequests / windowMs   (tokens per ms)
 *
 * Bursts up to `burstLimit` tokens are allowed.
 */
class RateLimiter {
  #buckets = new Map();   // key → { tokens, lastRefill, blockedUntil }
  #config;
  #cleanupTimer;

  /**
   * @param {object} config - A validated rate-limit section
   *   (e.g. from ConfigParser.getRouteConfig)
   */
  constructor(config) {
    this.#config = config;
    this.#startCleanup();
  }

  /**
   * Try to consume one request for `key`.
   * @param {string} key   - Unique client identifier (IP, userId, …)
   * @param {number} [cost] - Optional token cost override
   * @returns {{ allowed: boolean, remaining: number, retryAfterMs: number,
   *             limit: number, resetMs: number }}
   */
  consume(key, cost) {
    const now = Date.now();
    const bucket = this.#getOrCreateBucket(key, now);
    const tokenCost = cost ?? this.#config.costPerRequest;

    // Check if client is temporarily blocked
    if (bucket.blockedUntil && now < bucket.blockedUntil) {
      return this.#denied(bucket, now);
    }

    // Refill tokens based on elapsed time
    this.#refill(bucket, now);

    // Attempt to consume
    if (bucket.tokens >= tokenCost) {
      bucket.tokens -= tokenCost;
      return {
        allowed: true,
        remaining: Math.floor(bucket.tokens),
        retryAfterMs: 0,
        limit: this.#config.maxRequests,
        resetMs: this.#msUntilFull(bucket, now),
      };
    }

    // Limit exceeded — optionally block
    if (this.#config.blockDurationMs > 0) {
      bucket.blockedUntil = now + this.#config.blockDurationMs;
    }

    return this.#denied(bucket, now);
  }

  /** Manually reset a key (e.g. after successful captcha). */
  reset(key) {
    this.#buckets.delete(key);
  }

  /** Return current state without consuming. */
  peek(key) {
    const now = Date.now();
    const bucket = this.#buckets.get(key);
    if (!bucket) {
      return {
        remaining: this.#config.burstLimit,
        limit: this.#config.maxRequests,
        resetMs: 0,
      };
    }
    this.#refill(bucket, now);
    return {
      remaining: Math.floor(bucket.tokens),
      limit: this.#config.maxRequests,
      resetMs: this.#msUntilFull(bucket, now),
    };
  }

  /** Number of tracked clients. */
  get size() {
    return this.#buckets.size;
  }

  destroy() {
    clearInterval(this.#cleanupTimer);
    this.#buckets.clear();
  }

  // ── Internals ───────────────────────────────────────────────

  #getOrCreateBucket(key, now) {
    let bucket = this.#buckets.get(key);
    if (!bucket) {
      bucket = {
        tokens: this.#config.burstLimit,
        lastRefill: now,
        blockedUntil: 0,
      };
      this.#buckets.set(key, bucket);
    }
    return bucket;
  }

  #refill(bucket, now) {
    const elapsed = now - bucket.lastRefill;
    const rate = this.#config.maxRequests / this.#config.windowMs;
    const newTokens = elapsed * rate;

    bucket.tokens = Math.min(
      bucket.tokens + newTokens,
      this.#config.burstLimit
    );
    bucket.lastRefill = now;
  }

  #msUntilFull(bucket, now) {
    const deficit = this.#config.burstLimit - bucket.tokens;
    if (deficit <= 0) return 0;
    const rate = this.#config.maxRequests / this.#config.windowMs;
    return Math.ceil(deficit / rate);
  }

  #denied(bucket, now) {
    const retryAfterMs =
      bucket.blockedUntil && now < bucket.blockedUntil
        ? bucket.blockedUntil - now
        : this.#config.retryAfterMs;

    return {
      allowed: false,
      remaining: 0,
      retryAfterMs,
      limit: this.#config.maxRequests,
      resetMs: retryAfterMs,
    };
  }

  /** Evict stale buckets periodically to prevent memory leaks. */
  #startCleanup() {
    const interval = this.#config.windowMs * 2;
    this.#cleanupTimer = setInterval(() => {
      const now = Date.now();
      for (const [key, bucket] of this.#buckets) {
        const idle = now - bucket.lastRefill;
        if (idle > this.#config.windowMs && bucket.tokens >= this.#config.burstLimit) {
          this.#buckets.delete(key);
        }
      }
    }, interval);

    // Allow Node to exit even if the timer is running
    if (this.#cleanupTimer.unref) {
      this.#cleanupTimer.unref();
    }
  }
}

export { RateLimiter };
