## Core Queue Consumer

```javascript
// src/consumer.js
import amqplib from 'amqplib';
import config from './config.js';
import { EventEmitter } from 'events';

export default class QueueConsumer extends EventEmitter {
  #connection = null;
  #channel = null;
  #closing = false;

  async start() {
    await this.#connect();
    await this.#setupTopology();
    await this.#consume();
    console.log(`[Consumer] Listening on queue: ${config.rabbit.queue}`);
  }

  async #connect() {
    const { url, reconnectDelay } = config.rabbit;

    this.#connection = await amqplib.connect(url);
    this.#channel = await this.#connection.createChannel();
    this.#channel.prefetch(config.rabbit.prefetch);

    // auto-reconnect on unexpected close
    this.#connection.on('close', () => {
      if (this.#closing) return;
      console.error('[Consumer] Connection lost. Reconnecting...');
      setTimeout(() => this.start(), reconnectDelay);
    });

    this.#connection.on('error', (err) => {
      console.error('[Consumer] Connection error:', err.message);
    });
  }

  async #setupTopology() {
    const { exchange, queue, deadLetterQueue, routingKey } = config.rabbit;

    // dead letter exchange + queue
    await this.#channel.assertExchange(`${exchange}.dlx`, 'topic', { durable: true });
    await this.#channel.assertQueue(deadLetterQueue, { durable: true });
    await this.#channel.bindQueue(deadLetterQueue, `${exchange}.dlx`, '#');

    // main exchange + queue (with DLX configured)
    await this.#channel.assertExchange(exchange, 'topic', { durable: true });
    await this.#channel.assertQueue(queue, {
      durable: true,
      arguments: {
        'x-dead-letter-exchange': `${exchange}.dlx`,
        'x-message-ttl': 86400000, // 24h max time in queue
      },
    });
    await this.#channel.bindQueue(queue, exchange, routingKey);
  }

  async #consume() {
    await this.#channel.consume(config.rabbit.queue, (msg) => {
      if (!msg) return;
      this.emit('message', msg, {
        ack: () => this.#channel.ack(msg),
        nack: (requeue = false) => this.#channel.nack(msg, false, requeue),
      });
    });
  }

  async shutdown() {
    this.#closing = true;
    console.log('[Consumer] Shutting down...');
    try {
      await this.#channel?.close();
      await this.#connection?.close();
    } catch { /* already closed */ }
  }
}
