## Audit Log Processor (Batched Writes)

```javascript
// src/auditProcessor.js
import config from './config.js';
import { insertAuditBatch } from './db.js';

export default class AuditProcessor {
  #buffer = [];
  #pending = new Map();   // messageId → ack/nack controls
  #flushTimer = null;

  constructor() {
    this.#startFlushTimer();
  }

  /**
   * Accepts a raw AMQP message, parses it, buffers it for batch insert.
   */
  handle(msg, controls) {
    const parsed = this.#parse(msg);

    if (!parsed) {
      console.warn('[Processor] Malformed message dropped', msg.properties.messageId);
      controls.nack(false); // send to DLQ
      return;
    }

    this.#buffer.push(parsed);
    this.#pending.set(parsed._deliveryTag, controls);

    if (this.#buffer.length >= config.processing.batchSize) {
      this.flush();
    }
  }

  #parse(msg) {
    try {
      const body = JSON.parse(msg.content.toString());
      const retryCount = (msg.properties.headers?.['x-retry-count']) || 0;

      return {
        _deliveryTag: msg.fields.deliveryTag,
        _retryCount: retryCount,
        eventId: body.eventId || msg.properties.messageId,
        actor: body.actor,             // { id, type, ip }
        action: body.action,           // e.g. "user.updated"
        resource: body.resource,       // { type, id }
        changes: body.changes || null, // { before, after }
        metadata: body.metadata || {},
        timestamp: body.timestamp ? new Date(body.timestamp) : new Date(),
      };
    } catch {
      return null;
    }
  }

  async flush() {
    if (this.#buffer.length === 0) return;

    const batch = this.#buffer.splice(0);
    const batchControls = new Map();
    for (const record of batch) {
      batchControls.set(record._deliveryTag, this.#pending.get(record._deliveryTag));
      this.#pending.delete(record._deliveryTag);
    }

    try {
      await insertAuditBatch(batch);
      // ack all on success
      for (const controls of batchControls.values()) {
        controls.ack();
      }
      console.log(`[Processor] Flushed ${batch.length} audit records`);
    } catch (err) {
      console.error('[Processor] Batch insert failed:', err.message);
      this.#handleBatchFailure(batch, batchControls);
    }
  }

  #handleBatchFailure(batch, batchControls) {
    for (const record of batch) {
      const controls = batchControls.get(record._deliveryTag);
      if (record._retryCount < config.processing.maxRetries) {
        controls.nack(true);  // requeue for retry
      } else {
        controls.nack(false); // send to DLQ after max retries
        console.error(`[Processor] Event ${record.eventId} sent to DLQ after ${record._retryCount} retries`);
      }
    }
  }

  #startFlushTimer() {
    this.#flushTimer = setInterval(() => {
      this.flush();
    }, config.processing.flushIntervalMs);
  }

  async shutdown() {
    clearInterval(this.#flushTimer);
    await this.flush(); // drain remaining
  }
}
