// src/db.js
import pg from 'pg';
const { Pool } = pg;
import config from './config.js';

const pool = new Pool({ connectionString: config.db.connectionString });

/**
 * Batch insert audit records using a single multi-row INSERT.
 */
export async function insertAuditBatch(records) {
  if (records.length === 0) return;

  const columns = '(event_id, actor_id, actor_type, actor_ip, action, resource_type, resource_id, changes, metadata, created_at)';
  const params = [];
  const placeholders = [];

  for (let i = 0; i < records.length; i++) {
    const r = records[i];
    const offset = i * 10;
    placeholders.push(
      `($${offset+1},$${offset+2},$${offset+3},$${offset+4},$${offset+5},$${offset+6},$${offset+7},$${offset+8},$${offset+9},$${offset+10})`
    );
    params.push(
      r.eventId,
      r.actor?.id,
      r.actor?.type,
      r.actor?.ip,
      r.action,
      r.resource?.type,
      r.resource?.id,
      JSON.stringify(r.changes),
      JSON.stringify(r.metadata),
      r.timestamp,
    );
  }

  const query = `
    INSERT INTO audit_log ${columns}
    VALUES ${placeholders.join(',')}
    ON CONFLICT (event_id) DO NOTHING
  `;

  await pool.query(query, params);
}

// -- Table creation (run once) --
export async function migrate() {
