## Dead Letter Queue Handler

```javascript
// src/deadLetterHandler.js
import amqplib from 'amqplib';
import config from './config.js';
import fs from 'fs/promises';
import path from 'path';

/**
 * Separate process/utility to drain the DLQ.
 * In production, you'd alert on DLQ depth and replay or archive.
 */
export async function drainDLQ(outputDir = './dlq-dump') {
  const conn = await amqplib.connect(config.rabbit.url);
  const ch = await conn.createChannel();

  await fs.mkdir(outputDir, { recursive: true });

  let count = 0;
  let msg;

  while ((msg = await ch.get(config.rabbit.deadLetterQueue, { noAck: false }))) {
    const filename = path.join(outputDir, `${msg.properties.messageId || count}.json`);
    const record = {
      body: JSON.parse(msg.content.toString()),
      properties: msg.properties,
      headers: msg.properties.headers,
      drainedAt: new Date().toISOString(),
    };

    await fs.writeFile(filename, JSON.stringify(record, null, 2));
    ch.ack(msg);
    count++;
  }

  console.log(`[DLQ] Drained ${count} messages to ${outputDir}`);
  await ch.close();
  await conn.close();
}
```

## Entry Point

```javascript
// index.js
import QueueConsumer from './src/consumer.js';
import AuditProcessor from './src/auditProcessor.js';
import { migrate, shutdown as dbShutdown } from './src/db.js';

async function main() {
  await migrate();

  const consumer = new QueueConsumer();
  const processor = new AuditProcessor();

  // wire consumer messages to the processor
  consumer.on('message', (msg, controls) => {
    processor.handle(msg, controls);
  });

  await consumer.start();

  // --- graceful shutdown ---
  const shutdown = async (signal) => {
    console.log(`\nReceived ${signal}`);
    await consumer.shutdown();   // stop receiving
    await processor.shutdown();  // flush remaining buffer
    await dbShutdown();          // close DB pool
    process.exit(0);
  };

  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));
}

main().catch((err) => {
  console.error('[Fatal]', err);
  process.exit(1);
});
