## Main Sync Script (`fileSync.js`)

```javascript
const fs = require("fs");
const path = require("path");

// ─── Configuration Loader ────────────────────────────────────
function loadConfig(configPath) {
  try {
    const raw = fs.readFileSync(configPath, "utf-8");
    const config = JSON.parse(raw);
    validateConfig(config);
    return config;
  } catch (err) {
    if (err instanceof SyntaxError) {
      throw new Error(`Invalid JSON in config file: ${err.message}`);
    }
    throw err;
  }
}

function validateConfig(config) {
  if (!config.syncTasks || !Array.isArray(config.syncTasks)) {
    throw new Error('Config must contain a "syncTasks" array.');
  }
  config.syncTasks.forEach((task, i) => {
    if (!task.source) throw new Error(`Task ${i} missing "source".`);
    if (!task.destination) throw new Error(`Task ${i} missing "destination".`);
  });
}

// ─── File Utilities ──────────────────────────────────────────
function ensureDir(dirPath) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function getFileStats(filePath) {
  try {
    return fs.statSync(filePath);
  } catch {
    return null;
  }
}

/**
 * Check if a filename matches a glob-like pattern
 * Supports: *.ext, exact names
 */
function matchesPattern(filename, pattern) {
  if (pattern.startsWith("*.")) {
    return filename.endsWith(pattern.slice(1));
  }
  return filename === pattern;
}

function shouldInclude(filename, options) {
  const { include = [], exclude = [] } = options;

  // Check exclusions first
  if (exclude.some((pat) => matchesPattern(filename, pat))) {
    return false;
  }

  // If no include filters, include everything
  if (include.length === 0) return true;

  // Check inclusions
  return include.some((pat) => matchesPattern(filename, pat));
}

// ─── Sync Engine ─────────────────────────────────────────────
class FileSyncer {
  constructor() {
    this.results = { copied: [], updated: [], deleted: [], skipped: [], errors: [] };
  }

  /**
   * Recursively collect all files from a directory
   */
  collectFiles(dirPath, basePath = dirPath, options = {}) {
    const files = [];

    if (!fs.existsSync(dirPath)) return files;

    const entries = fs.readdirSync(dirPath, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dirPath, entry.name);
      const relativePath = path.relative(basePath, fullPath);

      if (!shouldInclude(entry.name, options)) {
        continue;
      }

      if (entry.isDirectory()) {
        files.push(...this.collectFiles(fullPath, basePath, options));
      } else if (entry.isFile()) {
        files.push({
          relativePath,
          fullPath,
          stats: fs.statSync(fullPath),
        });
      }
    }

    return files;
  }

  /**
   * Copy a single file from source to destination
   */
  copyFile(srcPath, destPath) {
    ensureDir(path.dirname(destPath));
    fs.copyFileSync(srcPath, destPath);
  }

  /**
   * Determine if source file is newer than destination
   */
  isNewer(srcStats, destStats) {
    return srcStats.mtimeMs > destStats.mtimeMs;
  }

  /**
   * Run a single sync task
   */
  syncTask(task) {
    const { source, destination, options = {}, name = "Unnamed" } = task;
    const { deleteOrphaned = false, overwriteNewer = true } = options;

    console.log(`\n▶ Running task: "${name}"`);
    console.log(`  Source:      ${path.resolve(source)}`);
    console.log(`  Destination: ${path.resolve(destination)}`);

    // 1) Validate source exists
    if (!fs.existsSync(source)) {
      const msg = `Source directory not found: ${source}`;
      this.results.errors.push({ task: name, message: msg });
      console.error(`  ✖ ${msg}`);
      return;
    }

    ensureDir(destination);

    // 2) Collect files from both sides
    const sourceFiles = this.collectFiles(source, source, options);
    const destFiles = this.collectFiles(destination, destination, options);

    const destMap = new Map();
    destFiles.forEach((f) => destMap.set(f.relativePath, f));

    // 3) Copy new & updated files → source to destination
    for (const srcFile of sourceFiles) {
      const destPath = path.join(destination, srcFile.relativePath);
      const destFile = destMap.get(srcFile.relativePath);

      try {
        if (!destFile) {
          // New file — copy it
          this.copyFile(srcFile.fullPath, destPath);
          this.results.copied.push(srcFile.relativePath);
          console.log(`  ✚ Copied:  ${srcFile.relativePath}`);
        } else if (overwriteNewer && this.isNewer(srcFile.stats, destFile.stats)) {
          // Updated file — overwrite
          this.copyFile(srcFile.fullPath, destPath);
          this.results.updated.push(srcFile.relativePath);
          console.log(`  ✎ Updated: ${srcFile.relativePath}`);
        } else {
          this.results.skipped.push(srcFile.relativePath);
        }
      } catch (err) {
        this.results.errors.push({
          task: name,
          file: srcFile.relativePath,
          message: err.message,
        });
        console.error(`  ✖ Error:   ${srcFile.relativePath} — ${err.message}`);
      }

      // Remove from map so we know what's left (orphaned)
      destMap.delete(srcFile.relativePath);
    }

    // 4) Handle orphaned files in destination
    if (deleteOrphaned) {
      for (const [relPath, destFile] of destMap) {
        try {
          fs.unlinkSync(destFile.fullPath);
          this.results.deleted.push(relPath);
          console.log(`  ✖ Deleted: ${relPath}`);
        } catch (err) {
          this.results.errors.push({
            task: name,
            file: relPath,
            message: err.message,
          });
        }
      }
    }
  }

  /**
   * Run all sync tasks from config
   */
  run(config) {
    console.log("═══════════════════════════════════════════");
    console.log("  File Synchronization Started");
    console.log(`  Time: ${new Date().toISOString()}`);
    console.log("═══════════════════════════════════════════");

    const startTime = Date.now();

    for (const task of config.syncTasks) {
      this.syncTask(task);
    }

    const elapsed = ((Date.now() - startTime) / 1000).toFixed(2);

    // Print summary
    console.log("\n───────────────────────────────────────────");
    console.log("  Summary:");
    console.log(`    Copied:  ${this.results.copied.length}`);
    console.log(`    Updated: ${this.results.updated.length}`);
    console.log(`    Deleted: ${this.results.deleted.length}`);
    console.log(`    Skipped: ${this.results.skipped.length}`);
    console.log(`    Errors:  ${this.results.errors.length}`);
    console.log(`    Time:    ${elapsed}s`);
    console.log("═══════════════════════════════════════════\n");

    // Save log if configured
    if (config.logFile) {
      this.saveLog(config.logFile, elapsed);
    }

    return this.results;
  }

  /**
   * Save sync results to a JSON log file
   */
  saveLog(logPath, elapsed) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      duration: `${elapsed}s`,
      results: this.results,
    };

    // Append to existing log or create new
    let logData = [];
    if (fs.existsSync(logPath)) {
      try {
        logData = JSON.parse(fs.readFileSync(logPath, "utf-8"));
      } catch {
        logData = [];
      }
    }

    logData.push(logEntry);
    fs.writeFileSync(logPath, JSON.stringify(logData, null, 2));
    console.log(`📄 Log saved to: ${logPath}`);
  }
}

// ─── Main Entry Point ────────────────────────────────────────
function main() {
  const configPath = process.argv[2] || "sync-config.json";

  try {
    const config = loadConfig(configPath);
    const syncer = new FileSyncer();
    syncer.run(config);
  } catch (err) {
    console.error(`\n❌ Fatal Error: ${err.message}\n`);
    process.exit(1);
  }
}

main();
```

