## Core Retry Utility

```javascript
// retry.js

class RetryError extends Error {
  constructor(message, attempts, lastError) {
    super(message);
    this.name = "RetryError";
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

/**
 * Executes an async function with retry logic and exponential backoff.
 */
async function withRetry(fn, options = {}) {
  const {
    maxRetries = 3,
    baseDelay = 1000,
    maxDelay = 10000,
    backoffFactor = 2,
    retryableErrors = [],       // specific error types to retry
    onRetry = null,              // callback before each retry
  } = options;

  let lastError;

  for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
    try {
      const result = await fn(attempt);
      return result;
    } catch (error) {
      lastError = error;

      // Check if we've exhausted retries
      if (attempt > maxRetries) {
        break;
      }

      // Check if the error is retryable
      if (retryableErrors.length > 0) {
        const isRetryable = retryableErrors.some(
          (errType) => error instanceof errType || error.code === errType
        );
        if (!isRetryable) {
          throw error; // non-retryable — fail immediately
        }
      }

      // Calculate delay with exponential backoff + jitter
      const exponentialDelay = baseDelay * Math.pow(backoffFactor, attempt - 1);
      const jitter = Math.random() * baseDelay * 0.5;
      const delay = Math.min(exponentialDelay + jitter, maxDelay);

      if (onRetry) {
        onRetry({ attempt, maxRetries, delay, error });
      }

      await sleep(delay);
    }
  }

  throw new RetryError(
    `Failed after ${maxRetries + 1} attempts: ${lastError.message}`,
    maxRetries + 1,
    lastError
  );
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

module.exports = { withRetry, RetryError };
```

## Document Parser Module

```javascript
// parser.js

const fs = require("fs/promises");
const path = require("path");
const { withRetry } = require("./retry");

// --- Custom Errors ---

class ParseError extends Error {
  constructor(message, filePath, line = null) {
    super(message);
    this.name = "ParseError";
    this.filePath = filePath;
    this.line = line;
  }
}

class FileAccessError extends Error {
  constructor(message, filePath) {
    super(message);
    this.name = "FileAccessError";
    this.filePath = filePath;
  }
}

// --- Individual Parsers ---

function parseJSON(content, filePath) {
  try {
    return JSON.parse(content);
  } catch (err) {
    throw new ParseError(
      `Invalid JSON: ${err.message}`,
      filePath
    );
  }
}

function parseCSV(content, filePath) {
  const lines = content.trim().split("\n");

  if (lines.length === 0) {
    throw new ParseError("CSV file is empty", filePath);
  }

  const headers = lines[0].split(",").map((h) => h.trim().replace(/^"|"$/g, ""));

  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(",").map((v) => v.trim().replace(/^"|"$/g, ""));

    if (values.length !== headers.length) {
      throw new ParseError(
        `Column count mismatch: expected ${headers.length}, got ${values.length}`,
        filePath,
        i + 1
      );
    }

    const row = {};
    headers.forEach((header, idx) => {
      row[header] = values[idx];
    });
    rows.push(row);
  }

  return { headers, rows, rowCount: rows.length };
}

function parseKeyValue(content, filePath) {
  const result = {};
  const lines = content.trim().split("\n");

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    // Skip empty lines and comments
    if (!line || line.startsWith("#")) continue;

    const separatorIdx = line.indexOf("=");
    if (separatorIdx === -1) {
      throw new ParseError(
        `Invalid key-value pair: "${line}"`,
        filePath,
        i + 1
      );
    }

    const key = line.substring(0, separatorIdx).trim();
    const value = line.substring(separatorIdx + 1).trim();
    result[key] = value;
  }

  return result;
}

// --- Parser Registry ---

const PARSERS = {
  ".json": parseJSON,
  ".csv": parseCSV,
  ".env": parseKeyValue,
  ".conf": parseKeyValue,
  ".txt": (content) => ({ text: content, lines: content.split("\n").length }),
};

// --- Main Parse Function with Retries ---

/**
 * Reads and parses a document file with automatic retry on transient failures.
 *
 * @param {string} filePath - Path to the document
 * @param {object} options  - Retry and parsing options
 * @returns {object} Parsed document content
 */
async function parseDocument(filePath, options = {}) {
  const {
    maxRetries = 3,
    encoding = "utf-8",
    parser = null,          // override auto-detected parser
    onRetry = defaultRetryLogger,
  } = options;

  const ext = path.extname(filePath).toLowerCase();
  const parserFn = parser || PARSERS[ext];

  if (!parserFn) {
    throw new ParseError(
      `Unsupported file type: "${ext}". Supported: ${Object.keys(PARSERS).join(", ")}`,
      filePath
    );
  }

  const result = await withRetry(
    async (attempt) => {
      // Step 1: Read the file
      let content;
      try {
        content = await fs.readFile(filePath, { encoding });
      } catch (err) {
        if (err.code === "ENOENT") {
          // File not found — not retryable
          throw new ParseError(`File not found: ${filePath}`, filePath);
        }
        // EBUSY, EMFILE, EAGAIN — transient, worth retrying
        throw new FileAccessError(
          `Cannot read file (attempt ${attempt}): ${err.message}`,
          filePath
        );
      }

      // Step 2: Parse the content
      const parsed = parserFn(content, filePath);

      return {
        filePath: path.resolve(filePath),
        fileType: ext,
        parsedAt: new Date().toISOString(),
        data: parsed,
      };
    },
    {
      maxRetries,
      baseDelay: 500,
      maxDelay: 5000,
      retryableErrors: [FileAccessError],
      onRetry,
    }
  );

  return result;
}

/**
 * Parses multiple documents concurrently, collecting successes and failures.
 */
async function parseDocuments(filePaths, options = {}) {
  const { concurrency = 5, ...parseOptions } = options;

  const results = { succeeded: [], failed: [] };
  const queue = [...filePaths];

  async function worker() {
    while (queue.length > 0) {
      const filePath = queue.shift();
      try {
        const result = await parseDocument(filePath, parseOptions);
        results.succeeded.push(result);
      } catch (error) {
        results.failed.push({
          filePath,
          error: error.message,
          errorType: error.name,
        });
      }
    }
  }

  // Launch limited concurrent workers
  const workers = Array.from(
    { length: Math.min(concurrency, filePaths.length) },
    () => worker()
  );
  await Promise.all(workers);

  return results;
}

function defaultRetryLogger({ attempt, maxRetries, delay, error }) {
  console.warn(
    `[Retry ${attempt}/${maxRetries}] ${error.message} — retrying in ${Math.round(delay)}ms`
  );
}

module.exports = {
  parseDocument,
  parseDocuments,
  ParseError,
  FileAccessError,
  PARSERS,
};
```

