    console.error(`Failed: [${err.name}] ${err.message}`);
  }

  // --- Example 2: Parse a CSV file ---
  console.log("\n=== CSV File ===");
  try {
    const result = await parseDocument("./data/users.csv");
    console.log(`Parsed ${result.data.rowCount} rows`);
    console.log("Headers:", result.data.headers);
    console.log("First row:", result.data.rows[0]);
  } catch (err) {
    console.error(`Failed: [${err.name}] ${err.message}`);
  }

  // --- Example 3: Parse multiple files with concurrency ---
  console.log("\n=== Batch Parsing ===");
  const files = [
    "./data/config.json",
    "./data/users.csv",
    "./data/settings.env",
    "./data/missing.json",   // will fail gracefully
  ];

  const batch = await parseDocuments(files, {
    concurrency: 3,
    maxRetries: 2,
  });

  console.log(`Succeeded: ${batch.succeeded.length}`);
  console.log(`Failed:    ${batch.failed.length}`);
  batch.failed.forEach((f) =>
    console.log(`  ✗ ${f.filePath}: ${f.error}`)
  );
}

main();
```

