use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use uuid::Uuid;

// ---------- Data Models ----------

/// Represents a single raw log entry from JSON input
#[derive(Debug, Deserialize, Clone)]
struct RawLogEntry {
    #[serde(default = "default_level")]
    level: String,
    message: String,
    #[serde(default)]
    timestamp: Option<String>,
    #[serde(default)]
    source: Option<String>,
    /// Catch-all for extra fields
    #[serde(flatten)]
    extra: HashMap<String, serde_json::Value>,
}

fn default_level() -> String {
    "INFO".to_string()
}

/// Normalized log entry after ingestion
#[derive(Debug, Serialize, Clone)]
struct LogEntry {
    id: String,
    level: LogLevel,
    message: String,
    timestamp: DateTime<Utc>,
    source: String,
    extra: HashMap<String, serde_json::Value>,
}

/// Supported log levels
#[derive(Debug, Serialize, Clone, PartialEq, Eq)]
#[serde(rename_all = "UPPERCASE")]
enum LogLevel {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
    Fatal,
}

impl LogLevel {
    fn from_str(s: &str) -> Self {
        match s.to_uppercase().as_str() {
            "TRACE" => LogLevel::Trace,
            "DEBUG" => LogLevel::Debug,
            "INFO" => LogLevel::Info,
            "WARN" | "WARNING" => LogLevel::Warn,
            "ERROR" | "ERR" => LogLevel::Error,
            "FATAL" | "CRITICAL" => LogLevel::Fatal,
            _ => LogLevel::Info,
        }
    }

    fn severity(&self) -> u8 {
        match self {
            LogLevel::Trace => 0,
            LogLevel::Debug => 1,
            LogLevel::Info => 2,
            LogLevel::Warn => 3,
            LogLevel::Error => 4,
            LogLevel::Fatal => 5,
        }
    }
}

// ---------- Log Store ----------

/// In-memory log storage with basic querying
struct LogStore {
    entries: Vec<LogEntry>,
    stats: IngestionStats,
}

#[derive(Debug, Default)]
struct IngestionStats {
    total_received: usize,
    total_ingested: usize,
    total_failed: usize,
    by_level: HashMap<String, usize>,
}

impl LogStore {
    fn new() -> Self {
        LogStore {
            entries: Vec::new(),
            stats: IngestionStats::default(),
        }
    }

    /// Ingest a single raw log entry, normalize it, and store it
    fn ingest(&mut self, raw: RawLogEntry) -> Result<&LogEntry, String> {
        self.stats.total_received += 1;

        // Validate required fields
        if raw.message.trim().is_empty() {
            self.stats.total_failed += 1;
            return Err("Empty message field".to_string());
        }

        // Parse timestamp or default to now
        let timestamp = match &raw.timestamp {
            Some(ts) => DateTime::parse_from_rfc3339(ts)
                .map(|dt| dt.with_timezone(&Utc))
                .or_else(|_| {
                    DateTime::parse_from_str(ts, "%Y-%m-%d %H:%M:%S")
                        .map(|dt| dt.with_timezone(&Utc))
                })
                .unwrap_or_else(|_| Utc::now()),
            None => Utc::now(),
        };

        let level = LogLevel::from_str(&raw.level);

        // Build normalized entry
        let entry = LogEntry {
            id: Uuid::new_v4().to_string(),
            level,
            message: raw.message,
            timestamp,
            source: raw.source.unwrap_or_else(|| "unknown".to_string()),
            extra: raw.extra,
        };

        // Update stats
        let level_str = format!("{:?}", entry.level);
        *self.stats.by_level.entry(level_str).or_insert(0) += 1;
        self.stats.total_ingested += 1;

        self.entries.push(entry);
        Ok(self.entries.last().unwrap())
    }

    /// Ingest a batch of raw entries
    fn ingest_batch(&mut self, raws: Vec<RawLogEntry>) -> BatchResult {
        let mut successes = 0;
        let mut failures = Vec::new();

        for (i, raw) in raws.into_iter().enumerate() {
            match self.ingest(raw) {
                Ok(_) => successes += 1,
                Err(e) => failures.push(format!("Entry {}: {}", i, e)),
            }
        }

        BatchResult {
            successes,
            failures,
        }
    }

    /// Query logs by minimum severity level
    fn query_by_level(&self, min_level: LogLevel) -> Vec<&LogEntry> {
        let min_severity = min_level.severity();
        self.entries
            .iter()
            .filter(|e| e.level.severity() >= min_severity)
            .collect()
    }

    /// Query logs by source
    fn query_by_source(&self, source: &str) -> Vec<&LogEntry> {
        self.entries
            .iter()
            .filter(|e| e.source.eq_ignore_ascii_case(source))
            .collect()
    }

    /// Search logs by keyword in message
    fn search(&self, keyword: &str) -> Vec<&LogEntry> {
        let kw = keyword.to_lowercase();
        self.entries
            .iter()
            .filter(|e| e.message.to_lowercase().contains(&kw))
            .collect()
    }

    fn print_stats(&self) {
        println!("\n===== Ingestion Stats =====");
        println!("  Received:  {}", self.stats.total_received);
        println!("  Ingested:  {}", self.stats.total_ingested);
        println!("  Failed:    {}", self.stats.total_failed);
        println!("  By Level:");
        for (level, count) in &self.stats.by_level {
            println!("    {:<8} {}", level, count);
        }
        println!("===========================\n");
    }
}

#[derive(Debug)]
struct BatchResult {
    successes: usize,
    failures: Vec<String>,
}

// ---------- Input Reading ----------

/// Read JSON from a file — supports JSON array or newline-delimited JSON (NDJSON)
fn read_from_file(path: &str) -> Result<Vec<RawLogEntry>, Box<dyn std::error::Error>> {
    let mut file = File::open(path)?;
    let mut content = String::new();
    file.read_to_string(&mut content)?;

    // Try parsing as a JSON array first
    if let Ok(entries) = serde_json::from_str::<Vec<RawLogEntry>>(&content) {
        return Ok(entries);
    }

    // Fall back to newline-delimited JSON (NDJSON)
    let entries: Vec<RawLogEntry> = content
        .lines()
        .filter(|line| !line.trim().is_empty())
        .filter_map(|line| {
            serde_json::from_str(line)
                .map_err(|e| eprintln!("Skipping invalid line: {} — {}", line, e))
                .ok()
        })
        .collect();

    Ok(entries)
}

/// Read NDJSON from stdin (one JSON object per line)
fn read_from_stdin() -> Vec<RawLogEntry> {
    let reader = BufReader::new(io::stdin());
    let mut entries = Vec::new();

    println!("Reading JSON logs from stdin (one per line, empty line to stop):");

    for line in reader.lines() {
        match line {
            Ok(l) if l.trim().is_empty() => break,
            Ok(l) => match serde_json::from_str::<RawLogEntry>(&l) {
                Ok(entry) => entries.push(entry),
                Err(e) => eprintln!("  [SKIP] Invalid JSON: {}", e),
            },
            Err(e) => {
                eprintln!("  [ERROR] Read error: {}", e);
                break;
            }
        }
    }

    entries
}

// ---------- Pretty Printing ----------

fn print_entries(entries: &[&LogEntry]) {
    if entries.is_empty() {
        println!("  (no matching entries)");
        return;
    }
    for entry in entries {
        println!(
            "  [{}] {:>5?} | {} | {} {}",
            &entry.id[..8],
            entry.level,
            entry.timestamp.format("%Y-%m-%d %H:%M:%S"),
            entry.source,
            entry.message,
        );
        if !entry.extra.is_empty() {
            println!("         extra: {:?}", entry.extra);
        }
    }
}

// ---------- Main ----------

fn main() {
    let mut store = LogStore::new();
    let args: Vec<String> = std::env::args().collect();

    // --- 1. Ingest from file or stdin ---
    let raw_entries = if args.len() > 1 {
        let path = &args[1];
        println!("Reading logs from file: {}", path);
        match read_from_file(path) {
            Ok(entries) => entries,
            Err(e) => {
                eprintln!("Error reading file: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        read_from_stdin()
    };

    // --- 2. Batch ingest ---
    println!("\nIngesting {} log entries...", raw_entries.len());
    let result = store.ingest_batch(raw_entries);
    println!(
        "  OK: {} | Failed: {}",
        result.successes,
        result.failures.len()
    );
    for f in &result.failures {
        eprintln!("  [FAIL] {}", f);
    }

    // --- 3. Print stats ---
    store.print_stats();

    // --- 4. Demo queries ---
    println!("----- All Entries -----");
    let all: Vec<&LogEntry> = store.entries.iter().collect();
    print_entries(&all);

    println!("\n----- Errors and above -----");
    let errors = store.query_by_level(LogLevel::Error);
    print_entries(&errors);

    println!("\n----- Source: 'auth-service' -----");
    let auth = store.query_by_source("auth-service");
    print_entries(&auth);

    println!("\n----- Search: 'timeout' -----");
    let timeouts = store.search("timeout");
    print_entries(&timeouts);

    // --- 5. Serialize stored logs back to JSON ---
    println!("\n----- JSON Output -----");
    match serde_json::to_string_pretty(&store.entries) {
        Ok(json) => println!("{}", json),
        Err(e) => eprintln!("Serialization error: {}", e),
    }
}
