## Backoff Utility

```typescript
// src/utils/backoff.ts

import { RetryPolicy } from "../types";

/**
 * Calculates delay using exponential backoff with optional jitter.
 *
 * Formula: min(maxDelay, baseDelay * multiplier^attempt) + jitter
 * Jitter adds ±25% randomness to prevent thundering herd.
 */
export function calculateBackoffDelay(
  attempt: number,
  policy: RetryPolicy
): number {
  const exponentialDelay =
    policy.baseDelayMs * Math.pow(policy.backoffMultiplier, attempt);
  const clampedDelay = Math.min(exponentialDelay, policy.maxDelayMs);

  if (!policy.jitterEnabled) {
    return clampedDelay;
  }

  // Add ±25% jitter
  const jitterRange = clampedDelay * 0.25;
  const jitter = Math.random() * 2 * jitterRange - jitterRange;

  return Math.max(0, Math.round(clampedDelay + jitter));
}

export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function isRetryableStatusCode(statusCode: number): boolean {
  return (
    statusCode === 429 || // Too Many Requests
    statusCode === 502 || // Bad Gateway
    statusCode === 503 || // Service Unavailable
    statusCode === 504 // Gateway Timeout
  );
}
