// src/utils/logger.ts

export enum InternalLogLevel {
  DEBUG = 0,
  INFO = 1,
  WARN = 2,
  ERROR = 3,
}

export class InternalLogger {
  constructor(
    private readonly context: string,
    private readonly level: InternalLogLevel = InternalLogLevel.INFO
  ) {}

  debug(message: string, data?: Record<string, unknown>): void {
    if (this.level <= InternalLogLevel.DEBUG) {
      this.log("DEBUG", message, data);
    }
  }

  info(message: string, data?: Record<string, unknown>): void {
    if (this.level <= InternalLogLevel.INFO) {
      this.log("INFO", message, data);
    }
  }

  warn(message: string, data?: Record<string, unknown>): void {
    if (this.level <= InternalLogLevel.WARN) {
      this.log("WARN", message, data);
    }
  }

  error(message: string, data?: Record<string, unknown>): void {
    if (this.level <= InternalLogLevel.ERROR) {
      this.log("ERROR", message, data);
    }
  }

  private log(
    level: string,
    message: string,
    data?: Record<string, unknown>
  ): void {
    const entry = {
      timestamp: new Date().toISOString(),
      level,
      context: this.context,
      message,
      ...data,
    };
    console.log(JSON.stringify(entry));
  }
}
