  private abortController: AbortController | null = null;

  constructor(private readonly options: HttpTransportOptions) {}

  async send(batch: LogBatch): Promise<IngestionResult> {
    const startTime = Date.now();
    this.abortController = new AbortController();

    const timeoutId = setTimeout(
      () => this.abortController?.abort(),
      this.options.timeoutMs
    );

    try {
      const response = await fetch(this.options.endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${this.options.apiKey}`,
          "X-Batch-Id": batch.batchId,
          ...this.options.headers,
        },
        body: JSON.stringify({
          batchId: batch.batchId,
          logs: batch.entries,
          sentAt: new Date().toISOString(),
        }),
        signal: this.abortController.signal,
      });

      clearTimeout(timeoutId);

      if (response.ok) {
        return {
          batchId: batch.batchId,
          status: IngestionStatus.SUCCESS,
          entriesProcessed: batch.entries.length,
          attemptCount: batch.attemptCount,
          duration: Date.now() - startTime,
        };
      }

      const errorBody = await response.text().catch(() => "Unknown error");

      if (isRetryableStatusCode(response.status)) {
        throw new RetryableError(
          `HTTP ${response.status}: ${errorBody}`,
          response.status
        );
      }

      throw new NonRetryableError(
        `HTTP ${response.status}: ${errorBody}`,
        response.status
      );
    } catch (error) {
      clearTimeout(timeoutId);

      if (error instanceof RetryableError || error instanceof NonRetryableError) {
        throw error;
      }

      // Network errors are retryable
      const err = error as Error;
      if (err.name === "AbortError") {
        throw new RetryableError(`Request timed out after ${this.options.timeoutMs}ms`);
      }

      throw new RetryableError(err.message);
    }
  }

  async healthCheck(): Promise<boolean> {
    try {
      const response = await fetch(
        `${this.options.endpoint}/health`,
        {
          method: "GET",
          headers: { Authorization: `Bearer ${this.options.apiKey}` },
          signal: AbortSignal.timeout(5000),
        }
      );
      return response.ok;
    } catch {
      return false;
    }
  }

  async close(): Promise<void> {
    this.abortController?.abort();
    this.logger.info("Transport closed");
  }
}
