```typescript
// src/services/CircuitBreaker.ts

import { CircuitBreakerConfig } from "../types";
import { InternalLogger } from "../utils/logger";
import { EventEmitter } from "events";

export enum CircuitState {
  CLOSED = "closed",     // Normal operation
  OPEN = "open",         // Failing — reject calls
  HALF_OPEN = "half_open", // Testing recovery
}

export interface CircuitBreakerMetrics {
  state: CircuitState;
  failures: number;
  successes: number;
  lastFailureTime: number | null;
  lastSuccessTime: number | null;
  totalRequests: number;
  totalFailures: number;
}

export class CircuitBreaker extends EventEmitter {
  private state: CircuitState = CircuitState.CLOSED;
  private failures = 0;
  private successes = 0;
  private halfOpenAttempts = 0;
  private lastFailureTime: number | null = null;
  private lastSuccessTime: number | null = null;
  private totalRequests = 0;
  private totalFailures = 0;
  private recoveryTimer: ReturnType<typeof setTimeout> | null = null;

  private readonly logger = new InternalLogger("CircuitBreaker");

  constructor(private readonly config: CircuitBreakerConfig) {
    super();
  }

  /**
   * Execute a function through the circuit breaker.
   * Throws immediately if the circuit is open.
   */
  async execute<T>(fn: () => Promise<T>): Promise<T> {
    if (!this.canExecute()) {
      const error = new Error(
        `Circuit breaker is OPEN. Recovery in ${this.timeUntilRecovery()}ms`
      );
      error.name = "CircuitBreakerOpenError";
      throw error;
    }

    this.totalRequests++;

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure(error as Error);
      throw error;
    }
  }

  getState(): CircuitState {
    return this.state;
  }

  getMetrics(): CircuitBreakerMetrics {
    return {
      state: this.state,
      failures: this.failures,
      successes: this.successes,
      lastFailureTime: this.lastFailureTime,
      lastSuccessTime: this.lastSuccessTime,
      totalRequests: this.totalRequests,
      totalFailures: this.totalFailures,
    };
  }

  reset(): void {
    this.state = CircuitState.CLOSED;
    this.failures = 0;
    this.successes = 0;
    this.halfOpenAttempts = 0;
    this.clearRecoveryTimer();
    this.emit("stateChange", CircuitState.CLOSED);
    this.logger.info("Circuit breaker reset");
  }

  destroy(): void {
    this.clearRecoveryTimer();
    this.removeAllListeners();
  }

  private canExecute(): boolean {
    switch (this.state) {
      case CircuitState.CLOSED:
        return true;

      case CircuitState.OPEN:
        if (this.shouldAttemptRecovery()) {
          this.transitionTo(CircuitState.HALF_OPEN);
          return true;
        }
        return false;

      case CircuitState.HALF_OPEN:
        return this.halfOpenAttempts < this.config.halfOpenMaxAttempts;

      default:
        return false;
    }
  }

  private onSuccess(): void {
    this.lastSuccessTime = Date.now();
    this.successes++;

    switch (this.state) {
      case CircuitState.HALF_OPEN:
        this.halfOpenAttempts++;
        if (this.halfOpenAttempts >= this.config.halfOpenMaxAttempts) {
          this.transitionTo(CircuitState.CLOSED);
          this.failures = 0;
          this.halfOpenAttempts = 0;
        }
        break;

      case CircuitState.CLOSED:
        // Decay failures on success
        this.failures = Math.max(0, this.failures - 1);
        break;
    }
  }

  private onFailure(error: Error): void {
    this.lastFailureTime = Date.now();
    this.failures++;
    this.totalFailures++;

    this.logger.warn("Operation failed", {
      error: error.message,
      failures: this.failures,
      state: this.state,
    });

    switch (this.state) {
      case CircuitState.HALF_OPEN:
        // Any failure in half-open goes back to open
        this.transitionTo(CircuitState.OPEN);
        this.halfOpenAttempts = 0;
        break;

      case CircuitState.CLOSED:
        if (this.failures >= this.config.failureThreshold) {
          this.transitionTo(CircuitState.OPEN);
        }
        break;
    }
  }

  private transitionTo(newState: CircuitState): void {
    const oldState = this.state;
    this.state = newState;

    this.logger.info("State transition", {
      from: oldState,
      to: newState,
    });

    if (newState === CircuitState.OPEN) {
      this.scheduleRecoveryAttempt();
    }

    this.emit("stateChange", newState, oldState);
  }

  private shouldAttemptRecovery(): boolean {
    if (!this.lastFailureTime) return true;
    return Date.now() - this.lastFailureTime >= this.config.recoveryTimeMs;
  }

  private timeUntilRecovery(): number {
    if (!this.lastFailureTime) return 0;
    const elapsed = Date.now() - this.lastFailureTime;
    return Math.max(0, this.config.recoveryTimeMs - elapsed);
  }

  private scheduleRecoveryAttempt(): void {
    this.clearRecoveryTimer();
    this.recoveryTimer = setTimeout(() => {
      if (this.state === CircuitState.OPEN) {
        this.logger.info("Recovery timer fired, transitioning to half-open");
        this.transitionTo(CircuitState.HALF_OPEN);
      }
    }, this.config.recoveryTimeMs);
  }

  private clearRecoveryTimer(): void {
    if (this.recoveryTimer) {
      clearTimeout(this.recoveryTimer);
      this.recoveryTimer = null;
    }
  }
}
