## scheduler.js

```js
#!/usr/bin/env node

const fs = require("fs");
const path = require("path");
const { exec } = require("child_process");

// ─── Storage ────────────────────────────────────────────
const DATA_FILE = path.join(__dirname, "tasks.json");

function loadTasks() {
  if (!fs.existsSync(DATA_FILE)) return [];
  try {
    return JSON.parse(fs.readFileSync(DATA_FILE, "utf8"));
  } catch {
    return [];
  }
}

function saveTasks(tasks) {
  fs.writeFileSync(DATA_FILE, JSON.stringify(tasks, null, 2));
}

function nextId(tasks) {
  if (tasks.length === 0) return 1;
  return Math.max(...tasks.map((t) => t.id)) + 1;
}

// ─── Formatting helpers ─────────────────────────────────
const COLORS = {
  reset: "\x1b[0m",
  bold: "\x1b[1m",
  dim: "\x1b[2m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  cyan: "\x1b[36m",
  red: "\x1b[31m",
  magenta: "\x1b[35m",
};

function c(color, text) {
  return `${COLORS[color]}${text}${COLORS.reset}`;
}

function padRight(str, len) {
  return String(str).padEnd(len);
}

// ─── Commands ───────────────────────────────────────────

function addTask(name, datetime, command, repeat = "none") {
  const scheduledAt = new Date(datetime);

  if (isNaN(scheduledAt.getTime())) {
    console.error(c("red", `✗ Invalid date: "${datetime}"`));
    console.log(`  Use format: "YYYY-MM-DD HH:MM"`);
    process.exit(1);
  }

  const validRepeats = ["none", "hourly", "daily", "weekly"];
  if (!validRepeats.includes(repeat)) {
    console.error(c("red", `✗ Invalid repeat: "${repeat}"`));
    console.log(`  Options: ${validRepeats.join(", ")}`);
    process.exit(1);
  }

  const tasks = loadTasks();
  const task = {
    id: nextId(tasks),
    name,
    command,
    scheduledAt: scheduledAt.toISOString(),
    repeat,
    status: "pending",
    createdAt: new Date().toISOString(),
    lastRun: null,
  };

  tasks.push(task);
  saveTasks(tasks);

  console.log(c("green", `✓ Task #${task.id} added`));
  console.log(`  Name:      ${task.name}`);
  console.log(`  Command:   ${task.command}`);
  console.log(`  Scheduled: ${scheduledAt.toLocaleString()}`);
  console.log(`  Repeat:    ${task.repeat}`);
}

function listTasks() {
  const tasks = loadTasks();

  if (tasks.length === 0) {
    console.log(c("dim", "No tasks scheduled."));
    return;
  }

  console.log();
  console.log(
    c("bold", `  ${padRight("ID", 5)}${padRight("STATUS", 10)}` +
      `${padRight("NAME", 20)}${padRight("SCHEDULED", 22)}` +
      `${padRight("REPEAT", 10)}COMMAND`)
  );
  console.log(c("dim", "  " + "─".repeat(90)));

  for (const task of tasks) {
    const date = new Date(task.scheduledAt).toLocaleString();
    const statusColors = {
      pending: "yellow",
      done: "green",
      failed: "red",
    };
    const statusColor = statusColors[task.status] || "dim";

    console.log(
      `  ${c("cyan", padRight(task.id, 5))}` +
        `${c(statusColor, padRight(task.status, 10))}` +
        `${padRight(task.name, 20)}` +
        `${padRight(date, 22)}` +
        `${c("magenta", padRight(task.repeat, 10))}` +
        `${c("dim", task.command)}`
    );
  }
  console.log();
}

function removeTask(id) {
  const tasks = loadTasks();
  const index = tasks.findIndex((t) => t.id === id);

  if (index === -1) {
    console.error(c("red", `✗ Task #${id} not found`));
    process.exit(1);
  }

  const [removed] = tasks.splice(index, 1);
  saveTasks(tasks);
  console.log(c("green", `✓ Removed task #${id}: "${removed.name}"`));
}

function clearDone() {
  const tasks = loadTasks();
  const remaining = tasks.filter((t) => t.status !== "done");
  const cleared = tasks.length - remaining.length;
  saveTasks(remaining);
  console.log(c("green", `✓ Cleared ${cleared} completed task(s)`));
}

// ─── Scheduler engine ───────────────────────────────────

function getNextRun(task) {
  const last = new Date(task.lastRun || task.scheduledAt);
  const intervals = {
    hourly: 60 * 60 * 1000,
    daily: 24 * 60 * 60 * 1000,
    weekly: 7 * 24 * 60 * 60 * 1000,
  };

  if (!intervals[task.repeat]) return null;

  let next = new Date(last.getTime() + intervals[task.repeat]);
  // if next is in the past, fast-forward to the future
  const now = Date.now();
  while (next.getTime() < now) {
    next = new Date(next.getTime() + intervals[task.repeat]);
  }
  return next;
}

function runTask(task) {
  return new Promise((resolve) => {
    const timestamp = new Date().toLocaleTimeString();
    console.log(c("cyan", `[${timestamp}] Running #${task.id}: "${task.name}"`));
    console.log(c("dim", `  → ${task.command}`));

    exec(task.command, (error, stdout, stderr) => {
      if (error) {
        console.log(c("red", `  ✗ Failed: ${error.message}`));
        resolve("failed");
      } else {
        if (stdout.trim()) console.log(`  ${stdout.trim()}`);
        if (stderr.trim()) console.log(c("yellow", `  ${stderr.trim()}`));
        console.log(c("green", `  ✓ Done`));
        resolve("done");
      }
    });
  });
}

async function tick() {
  const tasks = loadTasks();
  const now = Date.now();
  let changed = false;

  for (const task of tasks) {
    if (task.status === "done" && task.repeat === "none") continue;

    const scheduledTime = new Date(task.scheduledAt).getTime();
    let isDue = false;

    if (task.repeat !== "none" && task.lastRun) {
      const nextRun = getNextRun(task);
      isDue = nextRun && nextRun.getTime() <= now;
    } else {
      isDue = scheduledTime <= now && task.status === "pending";
    }

    if (isDue) {
      const result = await runTask(task);
      task.lastRun = new Date().toISOString();

      if (task.repeat === "none") {
        task.status = result;
      } else {
        // recurring tasks stay pending, update scheduledAt to next run
        task.status = "pending";
        const nextRun = getNextRun(task);
        if (nextRun) task.scheduledAt = nextRun.toISOString();
      }
      changed = true;
    }
  }

  if (changed) saveTasks(tasks);
}

function startScheduler() {
  console.log(c("bold", "⏰ Task scheduler started"));
  console.log(c("dim", "   Checking every 30 seconds. Press Ctrl+C to stop.\n"));

  // run immediately, then every 30s
  tick();
  setInterval(tick, 30 * 1000);
}

// ─── CLI routing ────────────────────────────────────────

function showHelp() {
  console.log(`
${c("bold", "Task Scheduler")} — a basic CLI task scheduler

${c("bold", "Usage:")}
  node scheduler.js ${c("cyan", "<command>")} [options]

${c("bold", "Commands:")}
  ${c("cyan", "add")} <name> <datetime> <command> [repeat]
      Schedule a new task
      datetime format: "YYYY-MM-DD HH:MM"
      repeat options:  none (default), hourly, daily, weekly

  ${c("cyan", "list")}
      Show all scheduled tasks

  ${c("cyan", "remove")} <id>
      Remove a task by ID

  ${c("cyan", "clear")}
      Remove all completed (non-recurring) tasks

  ${c("cyan", "start")}
      Start the scheduler (runs in foreground)

${c("bold", "Examples:")}
  node scheduler.js add "Backup logs" "2025-01-20 09:00" "tar -czf backup.tar.gz /var/log"
  node scheduler.js add "Health check" "2025-01-20 12:00" "curl localhost:3000/health" daily
  node scheduler.js list
  node scheduler.js remove 2
  node scheduler.js start
`);
}

// Parse arguments
const [, , command, ...args] = process.argv;

switch (command) {
  case "add": {
    const [name, datetime, cmd, repeat] = args;
    if (!name || !datetime || !cmd) {
      console.error(c("red", "✗ Missing arguments"));
      console.log('  Usage: add <name> <datetime> <command> [repeat]');
      process.exit(1);
    }
    addTask(name, datetime, cmd, repeat || "none");
    break;
  }

  case "list":
    listTasks();
    break;

  case "remove": {
    const id = parseInt(args[0], 10);
    if (isNaN(id)) {
      console.error(c("red", "✗ Provide a valid task ID"));
      process.exit(1);
    }
    removeTask(id);
    break;
  }

  case "clear":
    clearDone();
    break;

  case "start":
    startScheduler();
    break;

  default:
    showHelp();
}
