## Core Configuration Loader

```javascript
// configLoader.js
const fs = require("fs/promises");
const path = require("path");

class ConfigLoader {
  /**
   * @param {object} options
   * @param {number} options.maxRetries    - Max retry attempts (default: 3)
   * @param {number} options.retryDelayMs  - Base delay between retries in ms (default: 1000)
   * @param {boolean} options.useBackoff   - Use exponential backoff (default: true)
   */
  constructor(options = {}) {
    this.maxRetries = options.maxRetries ?? 3;
    this.retryDelayMs = options.retryDelayMs ?? 1000;
    this.useBackoff = options.useBackoff ?? true;
    this.config = null;
  }

  // --- Public API ---

  /** Load config from a JSON file with retries */
  async loadFromFile(filePath) {
    const absolutePath = path.resolve(filePath);

    return this._withRetry(async (attempt) => {
      console.log(`[Attempt ${attempt}] Loading config from: ${absolutePath}`);
      const raw = await fs.readFile(absolutePath, "utf-8");
      const parsed = JSON.parse(raw);
      this.config = parsed;
      return parsed;
    });
  }

  /** Load config from a remote URL with retries */
  async loadFromUrl(url) {
    return this._withRetry(async (attempt) => {
      console.log(`[Attempt ${attempt}] Fetching config from: ${url}`);
      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const parsed = await response.json();
      this.config = parsed;
      return parsed;
    });
  }

  /** Load from file with a URL fallback */
  async loadWithFallback(filePath, fallbackUrl) {
    try {
      return await this.loadFromFile(filePath);
    } catch (fileError) {
      console.warn(`File load failed: ${fileError.message}`);
      console.warn("Trying remote fallback...");
      return this.loadFromUrl(fallbackUrl);
    }
  }

  /** Get a nested config value by dot-notation key */
  get(key, defaultValue = undefined) {
    if (!this.config) {
      throw new Error("Config not loaded. Call a load method first.");
    }

    const value = key
      .split(".")
      .reduce((obj, k) => (obj && obj[k] !== undefined ? obj[k] : undefined), this.config);

    return value !== undefined ? value : defaultValue;
  }

  // --- Private helpers ---

  /** Execute an async function with retry logic */
  async _withRetry(fn) {
    let lastError;

    for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
      try {
        return await fn(attempt);
      } catch (error) {
        lastError = error;
        console.error(`[Attempt ${attempt}] Failed: ${error.message}`);

        if (attempt < this.maxRetries) {
          const delay = this._calculateDelay(attempt);
          console.log(`  Retrying in ${delay}ms...`);
          await this._sleep(delay);
        }
      }
    }

    throw new Error(
      `All ${this.maxRetries} attempts failed. Last error: ${lastError.message}`
    );
  }

  /** Calculate delay: flat or exponential backoff with jitter */
  _calculateDelay(attempt) {
    if (!this.useBackoff) {
      return this.retryDelayMs;
    }

    const exponential = this.retryDelayMs * Math.pow(2, attempt - 1);
    const jitter = Math.random() * this.retryDelayMs * 0.5;
    return Math.floor(exponential + jitter);
  }

  _sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

module.exports = ConfigLoader;
```

