    console.log("  App name :", loader.get("app.name"));
    console.log("  DB host  :", loader.get("database.host"));
    console.log("  Pool max :", loader.get("database.pool.max"));
    console.log("  Missing  :", loader.get("nonexistent.key", "default_val"));
  } catch (err) {
    console.error("\n❌ Failed to load config:", err.message);
  }

  // --- Example 2: Load from a file that doesn't exist (shows retries) ---
  console.log("\n--- Retry demo with missing file ---");
  const loader2 = new ConfigLoader({ maxRetries: 3, retryDelayMs: 300 });

  try {
    await loader2.loadFromFile("./missing-config.json");
  } catch (err) {
    console.error("\n❌ Expected failure:", err.message);
  }

  // --- Example 3: Fallback from file → remote URL ---
  console.log("\n--- Fallback demo ---");
  const loader3 = new ConfigLoader({ maxRetries: 2, retryDelayMs: 200 });

  try {
    await loader3.loadWithFallback(
      "./missing-config.json",
      "https://jsonplaceholder.typicode.com/posts/1" // sample endpoint
    );
    console.log("\n✅ Fallback config loaded:", loader3.config);
  } catch (err) {
    console.error("\n❌ All sources failed:", err.message);
  }
}

main();
