### Debugged & Fixed Code

```javascript
// ✅ FIXED VERSION - reportScheduler.js
const cron = require('node-cron');
const fs = require('fs').promises;        // FIX 7: Use async fs
const path = require('path');
const { Pool } = require('pg');
const { EventEmitter } = require('events');

// ─── Configuration ──────────────────────────────────────────
const CONFIG = {
  reportDir: process.env.REPORT_DIR || './reports',
  timezone: process.env.TZ || 'America/New_York',    // FIX 4: Explicit timezone
  maxRetries: 3,
  retryDelayMs: 2000,
  queryTimeoutMs: 30000,                              // FIX 10: Query timeout
  maxReportHistory: 100,                              // FIX 8: Bounded history
  concurrency: {
    daily: false,
    weekly: false,
  },
};

// ─── Database Pool with Proper Config ───────────────────────
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 5000,
  statement_timeout: CONFIG.queryTimeoutMs,           // FIX 10: DB-level timeout
});

pool.on('error', (err) => {
  console.error('[DB Pool] Unexpected error on idle client:', err.message);
});

// ─── Scheduler Class ────────────────────────────────────────
class ReportScheduler extends EventEmitter {
  constructor() {
    super();
    this.scheduledTasks = [];
    this.reportHistory = [];       // FIX 1: Managed within class
    this.isShuttingDown = false;
  }

  /**
   * FIX 2: Valid cron expression ('0' instead of '60')
   * FIX 3: Properly awaits async handler
   * FIX 4: Timezone-aware scheduling
   */
  start() {
    // Every hour at minute 0 (was invalid '60')
    const dailyTask = cron.schedule(
      '0 * * * *',                                    // FIX 2: Valid cron
      async () => {
        await this.#safeExecute('daily', () => this.generateDailyReport());
      },
      {
        timezone: CONFIG.timezone,                     // FIX 4: Timezone config
        scheduled: true,
      }
    );

    // Weekly at 9 AM Monday in configured timezone
    const weeklyTask = cron.schedule(
      '0 9 * * 1',
      async () => {
        await this.#safeExecute('weekly', () => this.generateWeeklyReport());
      },
      {
        timezone: CONFIG.timezone,
        scheduled: true,
      }
    );

    this.scheduledTasks.push(dailyTask, weeklyTask);

    // FIX 15: Health-check heartbeat every 5 minutes
    const healthCheck = cron.schedule('*/5 * * * *', () => {
      this.emit('healthcheck', {
        uptime: process.uptime(),
        pendingReports: Object.entries(CONFIG.concurrency)
          .filter(([, running]) => running)
          .map(([name]) => name),
        historySize: this.reportHistory.length,
      });
    });
    this.scheduledTasks.push(healthCheck);

    console.log(`[Scheduler] Started with timezone: ${CONFIG.timezone}`);
  }

  /**
   * FIX 9: Prevent overlapping executions with a lock
   * FIX 3: Wraps execution with full error handling
   */
  async #safeExecute(taskName, taskFn) {
    // Guard: skip if shutting down
    if (this.isShuttingDown) {
      console.warn(`[Scheduler] Skipping "${taskName}" — shutting down`);
      return;
    }

    // FIX 9: Concurrency lock per task type
    if (CONFIG.concurrency[taskName]) {
      console.warn(`[Scheduler] "${taskName}" already running — skipping`);
      return;
    }

    CONFIG.concurrency[taskName] = true;
    const startTime = Date.now();

    try {
      console.log(`[Scheduler] Starting "${taskName}" report...`);
      const result = await taskFn();

      const duration = Date.now() - startTime;
      this.#addToHistory(taskName, 'success', duration);
      this.emit('report:complete', { taskName, duration, result });

      console.log(`[Scheduler] "${taskName}" completed in ${duration}ms`);
    } catch (error) {
      const duration = Date.now() - startTime;
      this.#addToHistory(taskName, 'failure', duration, error.message);
      this.emit('report:error', { taskName, error, duration });

      console.error(`[Scheduler] "${taskName}" failed:`, error.message);
    } finally {
      CONFIG.concurrency[taskName] = false;           // Always release lock
    }
  }

  /**
   * FIX 5 & 6: Proper try/finally for DB connection release
   * FIX 7: Async file write
   */
  async generateDailyReport() {
    let client;
    try {
      client = await pool.connect();                   // FIX 5: Wrapped in try

      // Use date range for proper daily filtering
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const tomorrow = new Date(today);
      tomorrow.setDate(tomorrow.getDate() + 1);

      const result = await client.query(
        'SELECT * FROM sales WHERE date >= $1 AND date < $2',
        [today, tomorrow]
      );

      // FIX 7: Async file write — non-blocking
      const reportPath = path.join(
        CONFIG.reportDir,
        `daily-${today.toISOString().split('T')[0]}.json`
      );

      await fs.mkdir(CONFIG.reportDir, { recursive: true });
      await fs.writeFile(reportPath, JSON.stringify(result.rows, null, 2));

      return { rowCount: result.rowCount, path: reportPath };
    } finally {
      if (client) client.release();                    // FIX 6: Always release
    }
  }

  /**
   * FIX 11 & 12: Null-safe data processing with retry
   */
  async generateWeeklyReport() {
    const data = await this.#fetchWithRetry(           // FIX 13: Retry wrapper
      () => this.#fetchWeeklyData()
    );

    // FIX 11: Guard against null/empty data
    if (!data || data.length === 0) {
      console.warn('[Weekly Report] No data found for the past 7 days');
      return { rowCount: 0, totals: {} };
    }

    const report = this.#processReport(data);

    await this.#fetchWithRetry(
      () => this.#saveReport('weekly', report)
    );

    return { rowCount: data.length, totals: report };
  }

  async #fetchWeeklyData() {
    // Uses pool.query (auto-releases) for simple queries
    const result = await pool.query(
      `SELECT category, amount, date
       FROM sales
       WHERE date >= NOW() - INTERVAL '7 days'
       ORDER BY date`
    );
    return result.rows;
  }

  /**
   * FIX 12: Safe accumulator initialization
   */
  #processReport(data) {
    const totals = data.reduce((acc, row) => {
      const category = row.category || 'uncategorized';
      acc[category] = (acc[category] || 0) + (Number(row.amount) || 0);  // FIX 12
      return acc;
    }, {});

    return {
      totals,
      recordCount: data.length,
      generatedAt: new Date().toISOString(),
    };
  }

  async #saveReport(type, report) {
    await pool.query(
      'INSERT INTO reports (type, data, created_at) VALUES ($1, $2, NOW())',
      [type, JSON.stringify(report)]
    );
  }

  /**
   * FIX 13: Retry logic with exponential backoff
   */
  async #fetchWithRetry(fn, retries = CONFIG.maxRetries) {
    for (let attempt = 1; attempt <= retries; attempt++) {
      try {
        return await fn();
      } catch (error) {
        const isLast = attempt === retries;
        const delay = CONFIG.retryDelayMs * Math.pow(2, attempt - 1);

        console.warn(
          `[Retry] Attempt ${attempt}/${retries} failed: ${error.message}` +
          (isLast ? ' — giving up' : ` — retrying in ${delay}ms`)
        );

        if (isLast) throw error;
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }

  /**
   * FIX 8: Bounded report history to prevent memory leak
   */
  #addToHistory(taskName, status, durationMs, error = null) {
    this.reportHistory.push({
      taskName,
      status,
      durationMs,
      error,
      timestamp: new Date().toISOString(),
    });

    // Keep only the last N entries
    if (this.reportHistory.length > CONFIG.maxReportHistory) {
      this.reportHistory = this.reportHistory.slice(-CONFIG.maxReportHistory);
    }
  }

  /**
   * FIX 14: Graceful shutdown
   */
  async stop() {
    console.log('[Scheduler] Initiating graceful shutdown...');
    this.isShuttingDown = true;

    // Stop all cron tasks from firing
    for (const task of this.scheduledTasks) {
      task.stop();
    }

    // Wait for any running tasks to finish (with a timeout)
    const maxWaitMs = 30000;
    const start = Date.now();

    while (
      Object.values(CONFIG.concurrency).some(Boolean) &&
      Date.now() - start < maxWaitMs
    ) {
      console.log('[Scheduler] Waiting for running tasks to complete...');
      await new Promise((resolve) => setTimeout(resolve, 1000));
    }

    // Close database pool
    await pool.end();
    console.log('[Scheduler] Shutdown complete');
  }

  getStatus() {
    return {
      isRunning: !this.isShuttingDown,
      activeTasks: Object.entries(CONFIG.concurrency)
        .filter(([, running]) => running)
        .map(([name]) => name),
      history: this.reportHistory.slice(-10),
    };
  }
}

module.exports = ReportScheduler;
```

