    this.rules = [];
    this.report = new LintReport();
    this.config = config || {};
    this.filePatterns = config.filePatterns || ['.js'];
  }

  addRule(name, severity, checkFn) {
    // BUG 3: No validation — duplicate rules silently added
    const rule = new LinterRule(name, severity, checkFn);
    this.rules.push(rule);
  }

