    let content;
    try {
      content = fs.readFileSync(filePath, 'utf-8');
    } catch (err) {
      // BUG 5: Swallowing the error entirely — no logging or reporting
      return;
    }

    const lines = content.split('\n');
    this.report.fileCount++;

    // BUG 6: Off-by-one error — line numbers should be 1-based
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];

      for (const rule of this.rules) {
        // BUG 7: Not checking if rule is enabled
        try {
          const result = rule.check(line, i, lines, filePath);
          if (result) {
            if (rule.severity === 'error') {
              this.report.addError(filePath, i, result.message, rule.name);
            } else {
              this.report.addWarning(filePath, i, result.message, rule.name);
            }
          }
        } catch (err) {
          // BUG 8: Rule execution error is silently ignored
        }
      }
    }
  }

  // BUG 9: Not filtering by file extensions properly
  lintDirectory(dirPath) {
    const files = fs.readdirSync(dirPath);

    for (const file of files) {
      const fullPath = path.join(dirPath, file);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory()) {
        // BUG 10: No check for node_modules or hidden directories
        this.lintDirectory(fullPath);
      } else {
        this.lintFile(fullPath);
      }
    }
  }

  // BUG 11: generateReport doesn't sort or group issues logically
  generateReport(format) {
    const report = this.report;

    // BUG 12: Only handles 'json' — 'text' format throws
    if (format === 'json') {
      return JSON.stringify(report);
    } else if (format === 'text') {
      let output = '';
      // BUG 13: Iterating over wrong variable name (allIssues undefined)
      const allIssues = report.errors.concat(report.warnings);
      for (const issue of allIssue) {
        output += `${issue.file}:${issue.line} [${issue.severity}] ${issue.message} (${issue.rule})\n`;
      }
