```rust
use crossbeam_channel::Receiver;
use notify_debouncer_mini::{new_debouncer, DebouncedEventKind};
use std::collections::{HashMap, HashSet};
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};
use std::sync::{Arc, RwLock};
use std::time::Duration;

// --- Inverted Index ---

/// Document stored in the index.
#[derive(Debug, Clone)]
struct Document {
    path: PathBuf,
    content: String,
    modified: std::time::SystemTime,
}

/// Simple inverted index: token → set of file paths.
struct SearchIndex {
    /// token → set of document paths containing that token
    inverted: HashMap<String, HashSet<PathBuf>>,
    /// path → stored document
    documents: HashMap<PathBuf, Document>,
    /// file extensions to index (empty = index everything)
    extensions: HashSet<String>,
}

impl SearchIndex {
    fn new(extensions: &[&str]) -> Self {
        Self {
            inverted: HashMap::new(),
            documents: HashMap::new(),
            extensions: extensions.iter().map(|e| e.to_lowercase()).collect(),
        }
    }

    /// Check if a path should be indexed based on extension filter.
    fn should_index(&self, path: &Path) -> bool {
        if self.extensions.is_empty() {
            return true;
        }
        path.extension()
            .and_then(|e| e.to_str())
            .map(|e| self.extensions.contains(&e.to_lowercase()))
            .unwrap_or(false)
    }

    /// Tokenize text into lowercase alphanumeric tokens.
    fn tokenize(text: &str) -> Vec<String> {
        text.split(|c: char| !c.is_alphanumeric() && c != '_')
            .filter(|s| s.len() >= 2) // skip single chars
            .map(|s| s.to_lowercase())
            .collect()
    }

    /// Add or update a file in the index.
    fn upsert(&mut self, path: &Path) {
        if !self.should_index(path) {
            return;
        }

        // Remove old entry first (handles updates)
        self.remove(path);

        let content = match fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("  [skip] cannot read {}: {}", path.display(), e);
                return;
            }
        };

        let modified = fs::metadata(path)
            .and_then(|m| m.modified())
            .unwrap_or(std::time::SystemTime::now());

        let tokens = Self::tokenize(&content);

        // Build inverted index entries
        for token in &tokens {
            self.inverted
                .entry(token.clone())
                .or_default()
                .insert(path.to_path_buf());
        }

        let doc = Document {
            path: path.to_path_buf(),
            content,
            modified,
        };
        self.documents.insert(path.to_path_buf(), doc);

        println!(
            "  [indexed] {} ({} tokens)",
            path.display(),
            tokens.len()
        );
    }

    /// Remove a file from the index.
    fn remove(&mut self, path: &Path) {
        if self.documents.remove(path).is_none() {
            return; // wasn't indexed
        }

        // Clean up inverted index — remove path from all token sets
        self.inverted.retain(|_token, paths| {
            paths.remove(path);
            !paths.is_empty()
        });

        println!("  [removed] {}", path.display());
    }

    /// Search the index. Returns paths ranked by token match count.
    fn search(&self, query: &str) -> Vec<SearchResult> {
        let query_tokens = Self::tokenize(query);
        if query_tokens.is_empty() {
            return vec![];
        }

        // Count how many query tokens each document matches
        let mut scores: HashMap<&PathBuf, usize> = HashMap::new();

        for token in &query_tokens {
            if let Some(paths) = self.inverted.get(token) {
                for path in paths {
                    *scores.entry(path).or_insert(0) += 1;
                }
            }
        }

        let mut results: Vec<SearchResult> = scores
            .into_iter()
            .map(|(path, score)| {
                let snippet = self
                    .documents
                    .get(path)
                    .map(|doc| make_snippet(&doc.content, &query_tokens, 120))
                    .unwrap_or_default();

                SearchResult {
                    path: path.clone(),
                    score,
                    snippet,
                }
            })
            .collect();

        results.sort_by(|a, b| b.score.cmp(&a.score));
        results
    }

    /// Recursively index all matching files in a directory.
    fn index_directory(&mut self, dir: &Path) {
        let entries = match fs::read_dir(dir) {
            Ok(e) => e,
            Err(e) => {
                eprintln!("Cannot read directory {}: {}", dir.display(), e);
                return;
            }
        };

        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                self.index_directory(&path);
            } else if path.is_file() {
                self.upsert(&path);
            }
        }
    }

    fn stats(&self) -> (usize, usize) {
        (self.documents.len(), self.inverted.len())
    }
}

#[derive(Debug)]
struct SearchResult {
    path: PathBuf,
    score: usize,
    snippet: String,
}

/// Extract a short snippet around the first query token match.
fn make_snippet(content: &str, query_tokens: &[String], max_len: usize) -> String {
    let lower = content.to_lowercase();

    // Find earliest match position
    let pos = query_tokens
        .iter()
        .filter_map(|t| lower.find(t.as_str()))
        .min()
        .unwrap_or(0);

    let start = pos.saturating_sub(30);
    let end = (start + max_len).min(content.len());

    // Align to char boundaries
    let start = content[..start]
        .rfind(char::is_whitespace)
        .map(|p| p + 1)
        .unwrap_or(start);

    let snippet = &content[start..end];
    let snippet = snippet.replace('\n', " ");

    if start > 0 {
        format!("...{}", snippet.trim())
    } else {
        snippet.trim().to_string()
    }
}

// --- File Watcher ---

fn start_watcher(
    watch_path: &Path,
) -> Result<
    (
        notify_debouncer_mini::Debouncer<notify::RecommendedWatcher>,
        Receiver<Result<Vec<notify_debouncer_mini::DebouncedEvent>, notify::Error>>,
    ),
    notify::Error,
> {
    let (tx, rx) = crossbeam_channel::unbounded();

    let mut debouncer = new_debouncer(Duration::from_millis(500), tx)?;

    debouncer
        .watcher()
        .watch(watch_path, notify::RecursiveMode::Recursive)?;

    println!("Watching: {}", watch_path.display());
    Ok((debouncer, rx))
}

/// Process debounced filesystem events and update the index.
fn process_events(
    rx: &Receiver<Result<Vec<notify_debouncer_mini::DebouncedEvent>, notify::Error>>,
    index: &Arc<RwLock<SearchIndex>>,
) {
    // Non-blocking drain of all pending events
    while let Ok(result) = rx.try_recv() {
        match result {
            Ok(events) => {
                let mut idx = index.write().unwrap();
                for event in events {
                    let path = &event.path;
                    match event.kind {
                        DebouncedEventKind::Any => {
                            if path.is_file() {
                                idx.upsert(path);
                            } else if !path.exists() {
                                // File was deleted
                                idx.remove(path);
                            }
                        }
                        DebouncedEventKind::AnyContinuous => {
                            // Still changing, skip until stable
                        }
                    }
                }
            }
            Err(e) => eprintln!("Watch error: {:?}", e),
        }
    }
}

// --- CLI ---

fn print_help() {
    println!("Commands:");
    println!("  search <query>   Search indexed files");
    println!("  stats            Show index statistics");
    println!("  reindex          Force full re-index");
    println!("  help             Show this message");
    println!("  quit             Exit");
    println!();
}

fn main() {
    let watch_dir = std::env::args()
        .nth(1)
        .unwrap_or_else(|| ".".to_string());

    let watch_path = PathBuf::from(&watch_dir)
        .canonicalize()
        .expect("Invalid watch directory");

    // Index text-like files
    let index = Arc::new(RwLock::new(SearchIndex::new(&[
        "txt", "md", "rs", "toml", "json", "yaml", "yml", "py", "js", "ts",
        "html", "css", "csv", "log", "sh", "go", "java", "c", "h", "cpp",
    ])));

    // Initial indexing
    println!("Building initial index...");
    {
        let mut idx = index.write().unwrap();
        idx.index_directory(&watch_path);
        let (docs, tokens) = idx.stats();
        println!("Indexed {} files, {} unique tokens\n", docs, tokens);
    }

    // Start file watcher
    let (_debouncer, rx) = start_watcher(&watch_path).expect("Failed to start file watcher");

    print_help();

    // Main loop: process events + handle user input
    let stdin = io::stdin();
    let mut stdout = io::stdout();

    loop {
        // Process any pending file events
        process_events(&rx, &index);

        // Non-blocking-ish prompt
        print!("> ");
        stdout.flush().unwrap();

        let mut line = String::new();
        if stdin.lock().read_line(&mut line).is_err() {
            break;
        }
        let line = line.trim();

        if line.is_empty() {
            continue;
        }

        // Process file events that may have come in while waiting
        process_events(&rx, &index);

        if line == "quit" || line == "exit" {
            break;
        } else if line == "help" {
            print_help();
        } else if line == "stats" {
            let idx = index.read().unwrap();
            let (docs, tokens) = idx.stats();
            println!("Documents: {}, Unique tokens: {}", docs, tokens);
        } else if line == "reindex" {
            println!("Re-indexing...");
            let mut idx = index.write().unwrap();
            idx.inverted.clear();
            idx.documents.clear();
            idx.index_directory(&watch_path);
            let (docs, tokens) = idx.stats();
            println!("Indexed {} files, {} unique tokens", docs, tokens);
        } else if let Some(query) = line.strip_prefix("search ") {
            let query = query.trim();
            if query.is_empty() {
                println!("Usage: search <query>");
                continue;
            }

            let idx = index.read().unwrap();
            let results = idx.search(query);

            if results.is_empty() {
                println!("No results for '{}'", query);
            } else {
                println!("Found {} result(s):\n", results.len());
                for (i, r) in results.iter().take(10).enumerate() {
                    println!(
                        "  {}. [score:{}] {}",
                        i + 1,
                        r.score,
                        r.path.display()
                    );
                    if !r.snippet.is_empty() {
                        println!("     {}", r.snippet);
                    }
                }
            }
        } else {
            println!("Unknown command. Type 'help' for usage.");
        }

        println!();
    }

    println!("Bye.");
}
```

## How It Works

**Index structure** — a straightforward inverted index mapping each lowercase token to the set of file paths containing it. No external search library needed.

```
"rust"  → {src/main.rs, README.md}
"tokio" → {src/main.rs, Cargo.toml}
```

**Debouncing** — uses `notify-debouncer-mini` to collapse rapid filesystem events (editors often write temp files, rename, etc.) into single events with a 500ms window.

**Event processing flow:**

```
filesystem change
    → notify detects raw event
    → debouncer collapses duplicates (500ms)
    → channel delivers batched events
    → process_events() drains channel
    → upsert/remove updates index in-place
```

**What gets indexed** — only files matching a whitelist of extensions. Reads file as UTF-8 text, splits on non-alphanumeric boundaries, drops single-character tokens, lowercases everything.

## Usage

```bash
# Watch current directory
cargo run

# Watch a specific directory
cargo run -- /path/to/project
```

```
Building initial index...
  [indexed] ./src/main.rs (342 tokens)
  [indexed] ./Cargo.toml (28 tokens)
  [indexed] ./README.md (156 tokens)
Indexed 3 files, 401 unique tokens

> search inverted index
Found 2 result(s):

  1. [score:2] ./src/main.rs
     ...Simple inverted index: token → set of file paths...
  2. [score:1] ./README.md
     ...builds an inverted index for fast lookups...

> stats
Documents: 3, Unique tokens: 401

> reindex
Re-indexing...
Indexed 3 files, 401 unique tokens
```

Edit any file in the watched directory and the index updates automatically:

```
  [removed] ./src/main.rs
  [indexed] ./src/main.rs (350 tokens)
```

## Key Design Decisions

| Decision | Reasoning |
|---|---|
| `RwLock` not `Mutex` | Searches read-lock only; writes are infrequent |
| Debounce at 500ms | Catches editor save patterns (write→rename→delete temp) |
| Remove-then-insert on update | Simpler than diffing token sets; fast enough for <10k files |
| Extension whitelist | Avoids indexing binaries, images, `.git` objects |
| Score = token overlap count | Good enough for a local tool; swap in TF-IDF if needed |

For production use, you'd add persistent storage (serde + bincode to disk), ignore patterns (`.gitignore` parsing), and move the watcher event loop to a separate thread so searches never block on I/O.

