```javascript
// src/CacheStore.js
const { EventEmitter } = require('events');

class CacheEntry {
  constructor(key, value, metadata = {}) {
    this.key = key;
    this.value = value;
    this.metadata = metadata;
    this.createdAt = Date.now();
    this.lastAccessedAt = Date.now();
    this.accessCount = 0;
    this.version = metadata.version || 1;
    this.hash = metadata.hash || null;
    this.ttl = metadata.ttl || null; // null = no expiry
  }

  get isExpired() {
    if (this.ttl === null) return false;
    return Date.now() - this.createdAt > this.ttl;
  }

  touch() {
    this.lastAccessedAt = Date.now();
    this.accessCount++;
  }

  updateValue(value, metadata = {}) {
    this.value = value;
    this.version++;
    this.createdAt = Date.now();
    this.lastAccessedAt = Date.now();
    if (metadata.hash) this.hash = metadata.hash;
    if (metadata.ttl !== undefined) this.ttl = metadata.ttl;
  }
}

class CacheStore extends EventEmitter {
  constructor(options = {}) {
    super();
    this.store = new Map();
    this.maxSize = options.maxSize || 100;
    this.defaultTTL = options.defaultTTL || null;
    this.cleanupInterval = options.cleanupInterval || 30_000;

    // Periodic cleanup of expired entries
    this._cleanupTimer = setInterval(() => this._cleanup(), this.cleanupInterval);
    this._cleanupTimer.unref(); // Don't prevent process exit
  }

  get(key) {
    const entry = this.store.get(key);

    if (!entry) {
      this.emit('miss', { key });
      return null;
    }

    if (entry.isExpired) {
      this.emit('expired', { key, entry });
      this.store.delete(key);
      return null;
    }

    entry.touch();
    this.emit('hit', { key, entry });
    return entry;
  }

  set(key, value, metadata = {}) {
    // Enforce max size with LRU eviction
    if (!this.store.has(key) && this.store.size >= this.maxSize) {
      this._evictLRU();
    }

    const finalMetadata = {
      ...metadata,
      ttl: metadata.ttl !== undefined ? metadata.ttl : this.defaultTTL,
    };

    const existing = this.store.get(key);

    if (existing) {
      const oldValue = existing.value;
      existing.updateValue(value, finalMetadata);
      this.emit('update', { key, oldValue, newValue: value, entry: existing });
    } else {
      const entry = new CacheEntry(key, value, finalMetadata);
      this.store.set(key, entry);
      this.emit('set', { key, entry });
    }

    return this.store.get(key);
  }

  invalidate(key, reason = 'manual') {
    const entry = this.store.get(key);
    if (entry) {
      this.store.delete(key);
      this.emit('invalidated', { key, reason, entry });
      return true;
    }
    return false;
  }

  invalidatePattern(pattern) {
    const regex = typeof pattern === 'string' ? new RegExp(pattern) : pattern;
    const invalidated = [];

    for (const key of this.store.keys()) {
      if (regex.test(key)) {
        const entry = this.store.get(key);
        this.store.delete(key);
        invalidated.push(key);
        this.emit('invalidated', { key, reason: 'pattern', entry });
      }
    }

    return invalidated;
  }

  invalidateAll(reason = 'flush') {
    const keys = [...this.store.keys()];
    this.store.clear();
    this.emit('flushed', { keys, reason });
    return keys;
  }

  has(key) {
    const entry = this.store.get(key);
    return entry !== undefined && !entry.isExpired;
  }

  stats() {
    let expired = 0;
    let active = 0;

    for (const entry of this.store.values()) {
      if (entry.isExpired) expired++;
      else active++;
    }

    return { total: this.store.size, active, expired, maxSize: this.maxSize };
  }

  _cleanup() {
    let cleaned = 0;
    for (const [key, entry] of this.store) {
      if (entry.isExpired) {
        this.store.delete(key);
        this.emit('expired', { key, entry });
        cleaned++;
      }
    }
    if (cleaned > 0) {
      this.emit('cleanup', { removed: cleaned });
    }
  }

  _evictLRU() {
    let oldestKey = null;
    let oldestTime = Infinity;

    for (const [key, entry] of this.store) {
      if (entry.lastAccessedAt < oldestTime) {
        oldestTime = entry.lastAccessedAt;
        oldestKey = key;
      }
    }

    if (oldestKey) {
      this.invalidate(oldestKey, 'lru-eviction');
    }
  }

  destroy() {
    clearInterval(this._cleanupTimer);
    this.store.clear();
    this.removeAllListeners();
  }
}

module.exports = { CacheStore, CacheEntry };
