## Invalidation Strategies

```javascript
// src/strategies/TTLStrategy.js
class TTLStrategy {
  constructor(options = {}) {
    this.defaultTTL = options.defaultTTL || 60_000;       // 1 minute
    this.ttlOverrides = new Map();                         // Per-key TTL
    this.refreshOnAccess = options.refreshOnAccess || false; // Sliding window
  }

  /**
   * Set a custom TTL for a specific config key.
   */
  setTTL(key, ttl) {
    this.ttlOverrides.set(key, ttl);
  }

  getTTL(key) {
    return this.ttlOverrides.get(key) ?? this.defaultTTL;
  }

  /**
   * Returns true if the entry should be invalidated.
   */
  shouldInvalidate(entry) {
    if (!entry) return true;

    const ttl = this.getTTL(entry.key);
    if (ttl === null || ttl === Infinity) return false;

    const referenceTime = this.refreshOnAccess
      ? entry.lastAccessedAt
      : entry.createdAt;

    return Date.now() - referenceTime > ttl;
  }
}

module.exports = { TTLStrategy };
