```javascript
// src/strategies/HashStrategy.js
const crypto = require('crypto');
const fs = require('fs');

class HashStrategy {
  constructor(options = {}) {
    this.algorithm = options.algorithm || 'sha256';
    this.hashes = new Map(); // key -> last known hash
  }

  /**
   * Compute a content hash from a string or buffer.
   */
  computeHash(content) {
    return crypto
      .createHash(this.algorithm)
      .update(typeof content === 'string' ? content : JSON.stringify(content))
      .digest('hex');
  }

  /**
   * Compute hash directly from a file path.
   */
  computeFileHash(filePath) {
    const content = fs.readFileSync(filePath);
    return this.computeHash(content);
  }

  /**
   * Store the hash for a key and return it.
   */
  recordHash(key, content) {
    const hash = this.computeHash(content);
    this.hashes.set(key, hash);
    return hash;
  }

  /**
   * Returns true if the content has changed since last recorded hash.
   */
  shouldInvalidate(key, currentContent) {
    const previousHash = this.hashes.get(key);
    if (!previousHash) return true; // Never seen → treat as new

    const currentHash = this.computeHash(currentContent);
    return previousHash !== currentHash;
  }

  /**
   * Check a file path against its previously recorded hash.
   */
  shouldInvalidateFile(key, filePath) {
    try {
      const content = fs.readFileSync(filePath);
      return this.shouldInvalidate(key, content);
    } catch {
      return true; // File unreadable → invalidate
    }
  }
}

module.exports = { HashStrategy };
