```javascript
// src/strategies/VersionStrategy.js
class VersionStrategy {
  constructor() {
    this.versions = new Map(); // key -> expected version
  }

  /**
   * Bump the expected version for a key, forcing next access to re-parse.
   */
  bump(key) {
    const current = this.versions.get(key) || 0;
    this.versions.set(key, current + 1);
    return current + 1;
  }

  /**
   * Set an explicit version for a key.
   */
  setVersion(key, version) {
    this.versions.set(key, version);
  }

  /**
   * Returns true if the cached entry is behind the expected version.
   */
  shouldInvalidate(entry) {
    if (!entry) return true;

    const expected = this.versions.get(entry.key);
    if (expected === undefined) return false; // No version tracking → keep

    return entry.version < expected;
  }
}

module.exports = { VersionStrategy };
