## File Watcher (FS-based Invalidation)

```javascript
// src/FileWatcher.js
const fs = require('fs');
const path = require('path');
const { EventEmitter } = require('events');

class FileWatcher extends EventEmitter {
  constructor(options = {}) {
    super();
    this.watchers = new Map();          // filePath -> fs.FSWatcher
    this.debounceMs = options.debounceMs || 200;
    this._debounceTimers = new Map();
  }

  watch(filePath) {
    const resolved = path.resolve(filePath);

    if (this.watchers.has(resolved)) return; // Already watching

    try {
      const watcher = fs.watch(resolved, (eventType) => {
        this._debounce(resolved, () => {
          this.emit('change', { filePath: resolved, eventType });
        });
      });

      watcher.on('error', (err) => {
        this.emit('error', { filePath: resolved, error: err });
        this.unwatch(resolved);
      });

      this.watchers.set(resolved, watcher);
      this.emit('watching', { filePath: resolved });
    } catch (err) {
      this.emit('error', { filePath: resolved, error: err });
    }
  }

  unwatch(filePath) {
    const resolved = path.resolve(filePath);
    const watcher = this.watchers.get(resolved);

    if (watcher) {
      watcher.close();
      this.watchers.delete(resolved);
      this.emit('unwatched', { filePath: resolved });
    }

    // Clear any pending debounce
    const timer = this._debounceTimers.get(resolved);
    if (timer) {
      clearTimeout(timer);
      this._debounceTimers.delete(resolved);
    }
  }

  unwatchAll() {
    for (const filePath of this.watchers.keys()) {
      this.unwatch(filePath);
    }
  }

  _debounce(key, fn) {
    const existing = this._debounceTimers.get(key);
    if (existing) clearTimeout(existing);

    const timer = setTimeout(() => {
      this._debounceTimers.delete(key);
      fn();
    }, this.debounceMs);

    this._debounceTimers.set(key, timer);
  }

  destroy() {
    this.unwatchAll();
    this.removeAllListeners();
  }
}

module.exports = { FileWatcher };
