// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// POST /api/mute/:userId — Mute a user
// FIX 10: Use POST (state-changing operation)
// FIX 11: Accept duration in the request body
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
app.post('/api/mute/:userId', requireModRole, (req, res) => {
  const { userId } = req.params;
  const { durationMs } = req.body;

  const duration = Number(durationMs) || DEFAULT_MUTE_MS;

  if (duration <= 0 || duration > 86_400_000) {
    return res.status(400).json({
      error: 'Duration must be between 1ms and 24 hours'
    });
  }

  mutedUsers[userId] = Date.now() + duration;

  res.status(200).json({
    userId,
    mutedUntil: new Date(mutedUsers[userId]).toISOString(),
    durationMs: duration
  });
});

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// DELETE /api/mute/:userId — Unmute a user
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
app.delete('/api/mute/:userId', requireModRole, (req, res) => {
  const { userId } = req.params;

  if (!mutedUsers[userId]) {
    return res.status(404).json({ error: 'User is not muted' });
  }

  delete mutedUsers[userId];
  res.json({ message: `User ${userId} has been unmuted` });
});

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// DELETE /api/messages/:id — Delete a message
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
app.delete('/api/messages/:id', requireModRole, (req, res) => {
  const { id } = req.params;

  // FIX 13: Compare same types (both strings since we now use UUID)
  const index = messages.findIndex(m => m.id === id);

  // FIX 14 & 15: Early return prevents double response
  if (index === -1) {
    return res.status(404).json({ error: 'Message not found' });
  }

  const [deleted] = messages.splice(index, 1);
  res.json({ success: true, deletedMessage: deleted });
});

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// Content moderation function
// FIX 16 & 17: Use regex with global + case-insensitive flags
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
function moderateContent(text) {
  let result = text;

  for (const word of BANNED_WORDS) {
    // 'gi' → global (all occurrences) + case-insensitive
    const regex = new RegExp(`\\b${escapeRegex(word)}\\b`, 'gi');
    result = result.replace(regex, '***');
  }

  return result;
}

// Helper: escape special regex characters in banned words
function escapeRegex(string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// FIX 18: Global error handler
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
app.use((err, req, res, _next) => {
  console.error(`[ERROR] ${req.method} ${req.path}:`, err.message);
  res.status(500).json({ error: 'Internal server error' });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: `Route ${req.method} ${req.path} not found` });
});

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// FIX 19: Configurable port with fallback
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
