```javascript
// src/queue/PriorityQueue.js

class PriorityQueue {
  #heap = [];

  get size() {
    return this.#heap.length;
  }

  get isEmpty() {
    return this.#heap.length === 0;
  }

  // Insert with priority (lower number = higher priority)
  enqueue(item, priority = 5) {
    const node = { item, priority, insertedAt: Date.now() };
    this.#heap.push(node);
    this.#bubbleUp(this.#heap.length - 1);
  }

  // Extract highest priority item
  dequeue() {
    if (this.isEmpty) return null;

    const top = this.#heap[0];
    const last = this.#heap.pop();

    if (!this.isEmpty) {
      this.#heap[0] = last;
      this.#sinkDown(0);
    }

    return top.item;
  }

  peek() {
    return this.isEmpty ? null : this.#heap[0].item;
  }

  toArray() {
    return [...this.#heap]
      .sort((a, b) => a.priority - b.priority)
      .map(n => n.item);
  }

  #bubbleUp(index) {
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      if (this.#heap[parentIndex].priority <= this.#heap[index].priority) break;
      [this.#heap[parentIndex], this.#heap[index]] =
        [this.#heap[index], this.#heap[parentIndex]];
      index = parentIndex;
    }
  }

  #sinkDown(index) {
    const length = this.#heap.length;
    while (true) {
      let smallest = index;
      const left = 2 * index + 1;
      const right = 2 * index + 2;

      if (left < length && this.#heap[left].priority < this.#heap[smallest].priority) {
        smallest = left;
      }
      if (right < length && this.#heap[right].priority < this.#heap[smallest].priority) {
        smallest = right;
      }
      if (smallest === index) break;

      [this.#heap[smallest], this.#heap[index]] =
        [this.#heap[index], this.#heap[smallest]];
      index = smallest;
    }
  }
}

module.exports = PriorityQueue;
