// src/queue/EventQueue.js

const { EventEmitter } = require("node:events");
const PriorityQueue = require("./PriorityQueue");

class EventQueue extends EventEmitter {
  #queues = new Map();        // topic -> PriorityQueue
  #deadLetterQueue = [];
  #maxRetries;
  #maxDeadLetterSize;

  constructor(options = {}) {
    super();
    this.#maxRetries = options.maxRetries ?? 3;
    this.#maxDeadLetterSize = options.maxDeadLetterSize ?? 1000;
  }

  // Publish an event to a topic
  publish(topic, event) {
    const envelope = {
      id: crypto.randomUUID(),
      topic,
      payload: event.payload,
      metadata: {
        priority: event.priority ?? 5,
        createdAt: new Date().toISOString(),
        attempts: 0,
        maxRetries: event.maxRetries ?? this.#maxRetries,
        correlationId: event.correlationId ?? crypto.randomUUID(),
        source: event.source ?? "unknown",
      },
    };

    if (!this.#queues.has(topic)) {
      this.#queues.set(topic, new PriorityQueue());
    }

    this.#queues.get(topic).enqueue(envelope, envelope.metadata.priority);
    this.emit("event:published", envelope);
    this.emit(`topic:${topic}`, envelope);

    return envelope.id;
  }

  // Consume next event from a topic
  consume(topic) {
    const queue = this.#queues.get(topic);
    if (!queue || queue.isEmpty) return null;

    const envelope = queue.dequeue();
    envelope.metadata.attempts += 1;
    envelope.metadata.lastAttemptAt = new Date().toISOString();

    this.emit("event:consumed", envelope);
    return envelope;
  }

  // Re-queue a failed event or send to dead letter queue
  nack(envelope, error) {
    envelope.metadata.lastError = {
      message: error.message,
      stack: error.stack,
      timestamp: new Date().toISOString(),
    };

    if (envelope.metadata.attempts < envelope.metadata.maxRetries) {
      // Re-queue with lower priority (backoff)
      const backoffPriority = envelope.metadata.priority + envelope.metadata.attempts;
      const queue = this.#queues.get(envelope.topic);
      queue.enqueue(envelope, backoffPriority);
      this.emit("event:requeued", envelope);
    } else {
      this.#sendToDeadLetter(envelope);
    }
  }

  // Acknowledge successful processing
  ack(envelope) {
    envelope.metadata.completedAt = new Date().toISOString();
    this.emit("event:completed", envelope);
  }

  #sendToDeadLetter(envelope) {
    envelope.metadata.deadLetteredAt = new Date().toISOString();
    this.#deadLetterQueue.push(envelope);

    // Trim if over max size
    if (this.#deadLetterQueue.length > this.#maxDeadLetterSize) {
      this.#deadLetterQueue.shift();
    }

    this.emit("event:dead-lettered", envelope);
  }

  // Inspect queue state
  getTopicSize(topic) {
    return this.#queues.get(topic)?.size ?? 0;
  }

  getDeadLetterQueue() {
    return [...this.#deadLetterQueue];
  }

  getTopics() {
    return [...this.#queues.keys()];
  }

  getStats() {
    const stats = {};
    for (const [topic, queue] of this.#queues) {
      stats[topic] = { pending: queue.size };
    }
    stats.deadLetterCount = this.#deadLetterQueue.length;
    return stats;
  }
}

module.exports = EventQueue;
