```javascript
// src/workers/Worker.js

const { EventEmitter } = require("node:events");

// Possible states for a worker
const WorkerState = {
  IDLE: "idle",
  BUSY: "busy",
  STOPPED: "stopped",
  ERROR: "error",
};

class Worker extends EventEmitter {
  #id;
  #state;
  #handler;
  #currentEvent = null;
  #processedCount = 0;
  #errorCount = 0;
  #totalProcessingTime = 0;

  constructor(id, handler) {
    super();
    this.#id = id;
    this.#handler = handler;
    this.#state = WorkerState.IDLE;
  }

  get id() { return this.#id; }
  get state() { return this.#state; }
  get isIdle() { return this.#state === WorkerState.IDLE; }
  get stats() {
    return {
      id: this.#id,
      state: this.#state,
      processedCount: this.#processedCount,
      errorCount: this.#errorCount,
      avgProcessingTime: this.#processedCount > 0
        ? Math.round(this.#totalProcessingTime / this.#processedCount)
        : 0,
    };
  }

  async process(envelope) {
    if (this.#state === WorkerState.STOPPED) {
      throw new Error(`Worker ${this.#id} is stopped`);
    }

    this.#state = WorkerState.BUSY;
    this.#currentEvent = envelope;
    const startTime = Date.now();

    this.emit("worker:busy", { workerId: this.#id, eventId: envelope.id });

    try {
      const result = await this.#handler(envelope);
      const duration = Date.now() - startTime;

      this.#processedCount++;
      this.#totalProcessingTime += duration;
      this.#state = WorkerState.IDLE;
      this.#currentEvent = null;

      this.emit("worker:idle", { workerId: this.#id });
      return { success: true, result, duration };
    } catch (error) {
      const duration = Date.now() - startTime;
      this.#errorCount++;
      this.#totalProcessingTime += duration;
      this.#state = WorkerState.IDLE;
      this.#currentEvent = null;

      this.emit("worker:error", { workerId: this.#id, error });
      return { success: false, error, duration };
    }
  }

  stop() {
    this.#state = WorkerState.STOPPED;
    this.emit("worker:stopped", { workerId: this.#id });
  }

  resume() {
    if (this.#state === WorkerState.STOPPED) {
      this.#state = WorkerState.IDLE;
      this.emit("worker:idle", { workerId: this.#id });
    }
  }
}

module.exports = { Worker, WorkerState };
