```javascript
// src/workers/WorkerPool.js

const { EventEmitter } = require("node:events");
const { Worker } = require("./Worker");

class WorkerPool extends EventEmitter {
  #workers = new Map();
  #taskQueue = [];     // overflow tasks when all workers are busy
  #handler;
  #poolSize;
  #isRunning = false;

  constructor(poolSize, handler) {
    super();
    this.#poolSize = poolSize;
    this.#handler = handler;

    for (let i = 0; i < poolSize; i++) {
      this.#createWorker(i);
    }
  }

  #createWorker(id) {
    const worker = new Worker(`worker-${id}`, this.#handler);

    worker.on("worker:idle", () => {
      // When a worker becomes idle, check overflow queue
      if (this.#taskQueue.length > 0) {
        const { envelope, resolve } = this.#taskQueue.shift();
        this.#dispatch(worker, envelope).then(resolve);
      }
    });

    worker.on("worker:error", ({ error }) => {
      this.emit("pool:worker-error", { workerId: worker.id, error });
    });

    this.#workers.set(worker.id, worker);
  }

  // Submit an event for processing
  async submit(envelope) {
    const idleWorker = this.#getIdleWorker();

    if (idleWorker) {
      return this.#dispatch(idleWorker, envelope);
    }

    // All workers busy — queue the task
    return new Promise(resolve => {
      this.#taskQueue.push({ envelope, resolve });
      this.emit("pool:queued", {
        eventId: envelope.id,
        queuePosition: this.#taskQueue.length,
      });
    });
  }

  async #dispatch(worker, envelope) {
    this.emit("pool:dispatched", {
      workerId: worker.id,
      eventId: envelope.id,
    });
    return worker.process(envelope);
  }

  #getIdleWorker() {
    for (const worker of this.#workers.values()) {
      if (worker.isIdle) return worker;
    }
    return null;
  }

  getStats() {
    const workerStats = [];
    for (const worker of this.#workers.values()) {
      workerStats.push(worker.stats);
    }
    return {
      poolSize: this.#poolSize,
      overflowQueueSize: this.#taskQueue.length,
      workers: workerStats,
      idleCount: workerStats.filter(w => w.state === "idle").length,
      busyCount: workerStats.filter(w => w.state === "busy").length,
    };
  }

  async shutdown() {
    for (const worker of this.#workers.values()) {
      worker.stop();
    }
    this.#taskQueue = [];
    this.emit("pool:shutdown");
  }
}

module.exports = WorkerPool;
