## Retry Middleware

```javascript
// src/middleware/RetryMiddleware.js

class RetryMiddleware {
  #baseDelay;
  #maxDelay;
  #backoffMultiplier;

  constructor(options = {}) {
    this.#baseDelay = options.baseDelay ?? 1000;
    this.#maxDelay = options.maxDelay ?? 30000;
    this.#backoffMultiplier = options.backoffMultiplier ?? 2;
  }

  // Wrap a handler with retry + exponential backoff logic
  wrap(handler) {
    return async (envelope) => {
      const attempt = envelope.metadata.attempts;

      // Apply backoff delay on retries
      if (attempt > 1) {
        const delay = this.#calculateDelay(attempt);
        console.log(
          `⏳ Retry #${attempt} for event ${envelope.id} — waiting ${delay}ms`
        );
        await this.#sleep(delay);
      }

      return handler(envelope);
    };
  }

  #calculateDelay(attempt) {
    const delay = this.#baseDelay * Math.pow(this.#backoffMultiplier, attempt - 1);
    // Add jitter ±25%
    const jitter = delay * 0.25 * (Math.random() * 2 - 1);
    return Math.min(Math.round(delay + jitter), this.#maxDelay);
  }

  #sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

module.exports = RetryMiddleware;
