```javascript
// src/storage/EventStore.js

const { EventEmitter } = require("node:events");

class EventStore extends EventEmitter {
  #events = new Map();
  #indexByTopic = new Map();   // topic -> Set<eventId>
  #indexByStatus = new Map();  // status -> Set<eventId>

  save(envelope, status = "pending") {
    const record = {
      ...envelope,
      status,
      updatedAt: new Date().toISOString(),
    };

    this.#events.set(envelope.id, record);
    this.#addToIndex(this.#indexByTopic, envelope.topic, envelope.id);
    this.#addToIndex(this.#indexByStatus, status, envelope.id);

    this.emit("store:saved", record);
    return record;
  }

  updateStatus(eventId, status, metadata = {}) {
    const record = this.#events.get(eventId);
    if (!record) return null;

    // Remove from old status index
    this.#indexByStatus.get(record.status)?.delete(eventId);

    // Update record
    record.status = status;
    record.updatedAt = new Date().toISOString();
    Object.assign(record.metadata, metadata);

    // Add to new status index
    this.#addToIndex(this.#indexByStatus, status, eventId);

    this.emit("store:updated", record);
    return record;
  }

  getById(eventId) {
    return this.#events.get(eventId) ?? null;
  }

  getByTopic(topic) {
    const ids = this.#indexByTopic.get(topic);
    if (!ids) return [];
    return [...ids].map(id => this.#events.get(id));
  }

  getByStatus(status) {
    const ids = this.#indexByStatus.get(status);
    if (!ids) return [];
    return [...ids].map(id => this.#events.get(id));
  }

  getSummary() {
    const summary = {};
    for (const [status, ids] of this.#indexByStatus) {
      summary[status] = ids.size;
    }
    return { total: this.#events.size, byStatus: summary };
  }

  #addToIndex(index, key, value) {
    if (!index.has(key)) index.set(key, new Set());
    index.get(key).add(value);
  }
}

module.exports = EventStore;
