### `src/ManifestStore.js` — Tracks Backup Metadata

```javascript
import fs from "node:fs/promises";
import path from "node:path";

/**
 * Manages backup manifests that record:
 * - Which files were included in each backup
 * - Their checksums at backup time
 * - Backup type (full vs incremental)
 * - Timestamps and lineage (which full backup an incremental belongs to)
 */
export class ManifestStore {
  #manifestDir;

  constructor(manifestDir) {
    this.#manifestDir = manifestDir;
  }

  /** Ensure manifest directory exists */
  async init() {
    await fs.mkdir(this.#manifestDir, { recursive: true });
  }

  /** Generate a timestamped backup ID */
  generateBackupId(type) {
    const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
    return `${type}_${timestamp}`;
  }

  /**
   * Save a manifest to disk.
   * @param {Object} manifest
   * @param {string} manifest.id            - Unique backup ID
   * @param {string} manifest.type          - "full" | "incremental"
   * @param {string|null} manifest.parentId - ID of the full backup this derives from
   * @param {number} manifest.timestamp     - Unix ms
   * @param {Object} manifest.files         - { relativePath: { hash, size, mtime } }
   * @param {Object} manifest.changes       - { added: [], modified: [], deleted: [] }
   */
  async save(manifest) {
    const filePath = path.join(this.#manifestDir, `${manifest.id}.json`);
    const data = JSON.stringify(manifest, null, 2);
    await fs.writeFile(filePath, data, "utf-8");
    return filePath;
  }

  /** Load a single manifest by ID */
  async load(backupId) {
    const filePath = path.join(this.#manifestDir, `${backupId}.json`);
    const data = await fs.readFile(filePath, "utf-8");
    return JSON.parse(data);
  }

  /** List all manifests, sorted oldest → newest */
  async listAll() {
    let files;
    try {
      files = await fs.readdir(this.#manifestDir);
    } catch {
      return [];
    }

    const manifests = [];
    for (const file of files) {
      if (!file.endsWith(".json")) continue;
      const data = await fs.readFile(
        path.join(this.#manifestDir, file),
        "utf-8"
      );
      manifests.push(JSON.parse(data));
    }

    return manifests.sort((a, b) => a.timestamp - b.timestamp);
  }

  /** Get the most recent full backup manifest */
  async getLatestFull() {
    const all = await this.listAll();
    const fulls = all.filter((m) => m.type === "full");
    return fulls.length > 0 ? fulls[fulls.length - 1] : null;
  }

  /** Get the most recent backup of any type */
  async getLatest() {
    const all = await this.listAll();
    return all.length > 0 ? all[all.length - 1] : null;
  }

  /** Count incremental backups since the last full */
  async countIncrementalsSinceLastFull() {
    const all = await this.listAll();
    let count = 0;
    // Walk backwards; stop when we hit a full backup
    for (let i = all.length - 1; i >= 0; i--) {
      if (all[i].type === "full") break;
      count++;
    }
    return count;
  }

  /**
   * Build the chain: [fullManifest, inc1, inc2, …, targetManifest]
   * needed to restore a given backup.
   */
  async getRestoreChain(backupId) {
    const all = await this.listAll();
    const target = all.find((m) => m.id === backupId);
    if (!target) throw new Error(`Manifest not found: ${backupId}`);

    if (target.type === "full") return [target];

    // Walk backwards to find the parent full backup
    const chain = [];
    let foundTarget = false;

    for (let i = all.length - 1; i >= 0; i--) {
      if (all[i].id === backupId) foundTarget = true;
      if (foundTarget) {
        chain.unshift(all[i]);
        if (all[i].type === "full") break;
      }
    }

    if (chain.length === 0 || chain[0].type !== "full") {
      throw new Error(`Broken chain: no parent full backup for ${backupId}`);
    }

    return chain;
  }
}
