### `src/ChangeDetector.js` — Checksums & Diffing

```javascript
import fs from "node:fs/promises";
import crypto from "node:crypto";
import path from "node:path";
import { glob } from "glob";
import config from "../config.js";

/**
 * Scans the source directory, computes per-file hashes,
 * and diffs against the previous manifest to find changes.
 */
export class ChangeDetector {
  #sourceDir;
  #algorithm;

  constructor(sourceDir, algorithm = "sha256") {
    this.#sourceDir = sourceDir;
    this.#algorithm = algorithm;
  }

  /** Compute the hash of a single file using streams */
  async #hashFile(filePath) {
    const data = await fs.readFile(filePath);
    return crypto.createHash(this.#algorithm).update(data).digest("hex");
  }

  /**
   * Scan the source directory and return a snapshot:
   * { "relative/path.txt": { hash, size, mtime } }
   */
  async snapshot() {
    const files = await glob(config.includePatterns, {
      cwd: this.#sourceDir,
      ignore: config.excludePatterns,
      nodir: true,          // files only
      dot: true,            // include dotfiles
    });

    const snapshot = {};

    // Process files with bounded concurrency
    const CONCURRENCY = 8;
    for (let i = 0; i < files.length; i += CONCURRENCY) {
      const batch = files.slice(i, i + CONCURRENCY);
      const results = await Promise.all(
        batch.map(async (relPath) => {
          const absPath = path.join(this.#sourceDir, relPath);
          const stat = await fs.stat(absPath);
          const hash = await this.#hashFile(absPath);
          return {
            relPath,
            hash,
            size: stat.size,
            mtime: stat.mtimeMs,
          };
        })
      );
      for (const r of results) {
        snapshot[r.relPath] = {
          hash: r.hash,
          size: r.size,
          mtime: r.mtime,
        };
      }
    }

    return snapshot;
  }

  /**
   * Compare a new snapshot against a previous manifest's file list.
   * Returns { added: [], modified: [], deleted: [], unchanged: [] }
   */
  diff(currentSnapshot, previousFiles) {
    const added = [];
    const modified = [];
    const unchanged = [];
    const deleted = [];

    // Check current files against previous
    for (const [relPath, info] of Object.entries(currentSnapshot)) {
      if (!previousFiles[relPath]) {
        added.push(relPath);
      } else if (previousFiles[relPath].hash !== info.hash) {
        modified.push(relPath);
      } else {
        unchanged.push(relPath);
      }
    }

    // Files in previous but not in current → deleted
    for (const relPath of Object.keys(previousFiles)) {
      if (!currentSnapshot[relPath]) {
        deleted.push(relPath);
      }
    }

    return { added, modified, deleted, unchanged };
  }
}
