### `src/BackupStrategy.js` — Decides Full vs Incremental

```javascript
import config from "../config.js";

/**
 * Determines whether the next backup should be full or incremental
 * based on history, policy, and explicit user request.
 */
export class BackupStrategy {
  #manifestStore;

  constructor(manifestStore) {
    this.#manifestStore = manifestStore;
  }

  /**
   * @param {boolean} forceFull - User explicitly requested a full backup
   * @returns {"full" | "incremental"}
   */
  async decide(forceFull = false) {
    if (forceFull) return "full";

    const latestFull = await this.#manifestStore.getLatestFull();

    // No full backup exists yet → must do a full
    if (!latestFull) {
      console.log("  → No previous full backup found. Forcing full backup.");
      return "full";
    }

    // Too many incrementals → do a full to keep restore chains short
    const incCount =
      await this.#manifestStore.countIncrementalsSinceLastFull();
    if (incCount >= config.maxIncrementalsBeforeFull) {
      console.log(
        `  → ${incCount} incrementals since last full (max ${config.maxIncrementalsBeforeFull}). Forcing full backup.`
      );
      return "full";
    }

    return "incremental";
  }
}
