### `src/BackupManager.js` — Core Orchestrator

```javascript
import fs from "node:fs/promises";
import path from "node:path";
import config from "../config.js";
import { ManifestStore } from "./ManifestStore.js";
import { ChangeDetector } from "./ChangeDetector.js";
import { BackupStrategy } from "./BackupStrategy.js";

/**
 * Orchestrates the entire backup flow:
 * 1. Decide backup type (full / incremental)
 * 2. Snapshot the source directory
 * 3. Diff against the last backup
 * 4. Copy changed files into a timestamped backup folder
 * 5. Write a manifest
 */
export class BackupManager {
  #manifestStore;
  #changeDetector;
  #strategy;

  constructor() {
    this.#manifestStore = new ManifestStore(config.manifestDir);
    this.#changeDetector = new ChangeDetector(
      config.sourceDir,
      config.hashAlgorithm
    );
    this.#strategy = new BackupStrategy(this.#manifestStore);
  }

  async init() {
    await fs.mkdir(config.backupDir, { recursive: true });
    await this.#manifestStore.init();
  }

  /**
   * Run a backup.
   * @param {Object} options
   * @param {boolean} options.forceFull - Force a full backup
   * @returns {Object} The manifest of the completed backup
   */
  async run({ forceFull = false } = {}) {
    await this.init();

    // --- Step 1: Decide type ---
    const type = await this.#strategy.decide(forceFull);
    const backupId = this.#manifestStore.generateBackupId(type);
    const backupPath = path.join(config.backupDir, backupId);

    console.log(`\n🔄 Starting ${type.toUpperCase()} backup: ${backupId}`);
    console.log(`   Source : ${config.sourceDir}`);
    console.log(`   Dest   : ${backupPath}\n`);

    // --- Step 2: Snapshot current state ---
    console.log("  Scanning source directory…");
    const currentSnapshot = await this.#changeDetector.snapshot();
    const fileCount = Object.keys(currentSnapshot).length;
    console.log(`  Found ${fileCount} file(s).\n`);

    // --- Step 3: Diff ---
    let changes;
    let parentId = null;

    if (type === "full") {
      // Full backup: everything is "added"
      changes = {
        added: Object.keys(currentSnapshot),
        modified: [],
        deleted: [],
        unchanged: [],
      };
    } else {
      // Incremental: diff against last backup
      const lastManifest = await this.#manifestStore.getLatest();
      parentId = (await this.#manifestStore.getLatestFull())?.id ?? null;
      changes = this.#changeDetector.diff(
        currentSnapshot,
        lastManifest?.files ?? {}
      );
    }

    console.log("  Changes detected:");
    console.log(`    + Added    : ${changes.added.length}`);
    console.log(`    ~ Modified : ${changes.modified.length}`);
    console.log(`    - Deleted  : ${changes.deleted.length}`);
    console.log(`    = Unchanged: ${changes.unchanged.length}\n`);

    // --- Step 4: Copy files ---
    const filesToCopy = [...changes.added, ...changes.modified];

    if (filesToCopy.length === 0 && changes.deleted.length === 0) {
      console.log("  ✅ Nothing changed. Skipping backup.\n");
      return null;
    }

    await fs.mkdir(backupPath, { recursive: true });

    let copiedBytes = 0;
    for (const relPath of filesToCopy) {
      const src = path.join(config.sourceDir, relPath);
      const dest = path.join(backupPath, relPath);

      await fs.mkdir(path.dirname(dest), { recursive: true });
      await fs.copyFile(src, dest);

      copiedBytes += currentSnapshot[relPath].size;
    }

    console.log(
      `  Copied ${filesToCopy.length} file(s) (${this.#formatBytes(copiedBytes)})`
    );

    // --- Step 5: Write manifest ---
    const manifest = {
      id: backupId,
      type,
      parentId,
      timestamp: Date.now(),
      files: currentSnapshot,          // full snapshot for restore
      changes: {
        added: changes.added,
        modified: changes.modified,
        deleted: changes.deleted,
      },
      stats: {
        totalFiles: fileCount,
        copiedFiles: filesToCopy.length,
        copiedBytes,
      },
    };

    const manifestPath = await this.#manifestStore.save(manifest);
    console.log(`  Manifest saved: ${manifestPath}`);
    console.log(`\n  ✅ Backup complete: ${backupId}\n`);

    return manifest;
  }

  /** Print a status summary */
  async status() {
    await this.init();

    const all = await this.#manifestStore.listAll();
    if (all.length === 0) {
      console.log("\nNo backups found.\n");
      return;
    }

    console.log(`\n📦 Backup History (${all.length} total)\n`);
    console.log(
      "  ID".padEnd(50) +
        "Type".padEnd(15) +
        "Files Copied".padEnd(15) +
        "Size"
    );
    console.log("  " + "─".repeat(90));

    for (const m of all) {
      const line =
        `  ${m.id}`.padEnd(50) +
        m.type.padEnd(15) +
        String(m.stats.copiedFiles).padEnd(15) +
        this.#formatBytes(m.stats.copiedBytes);
      console.log(line);
    }

    const latestFull = await this.#manifestStore.getLatestFull();
    const incCount =
      await this.#manifestStore.countIncrementalsSinceLastFull();

    console.log(`\n  Latest full backup : ${latestFull?.id ?? "none"}`);
    console.log(`  Incrementals since : ${incCount}`);
    console.log(
      `  Next forced full at: ${config.maxIncrementalsBeforeFull} incrementals\n`
    );
  }

  /** Get the manifest store (used by RestoreManager) */
  get manifestStore() {
    return this.#manifestStore;
  }

  #formatBytes(bytes) {
    if (bytes === 0) return "0 B";
    const units = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return `${(bytes / 1024 ** i).toFixed(1)} ${units[i]}`;
  }
}
