# File Watcher for Audit Logging

```javascript
const fs = require("fs");
const path = require("path");

// --- Configuration ---
const WATCH_DIR = process.argv[2] || "./watched";
const LOG_FILE = process.argv[3] || "./audit.log";

// --- Ensure watch directory exists ---
if (!fs.existsSync(WATCH_DIR)) {
  fs.mkdirSync(WATCH_DIR, { recursive: true });
  console.log(`Created watch directory: ${WATCH_DIR}`);
}

// --- Format a log entry ---
function formatEntry(eventType, filename) {
  const timestamp = new Date().toISOString();
  return `[${timestamp}] ${eventType.toUpperCase().padEnd(6)} ${filename}`;
}

// --- Write to audit log ---
function writeLog(entry) {
  console.log(entry);
  fs.appendFileSync(LOG_FILE, entry + "\n");
}

// --- Track file states for detecting adds vs changes ---
const knownFiles = new Set();

// Seed known files from current directory contents
fs.readdirSync(WATCH_DIR).forEach((file) => knownFiles.add(file));

// --- Debounce duplicate events (fs.watch fires twice on some OS) ---
const recentEvents = new Map();
const DEBOUNCE_MS = 100;

function isDuplicate(eventType, filename) {
  const key = `${eventType}:${filename}`;
  const now = Date.now();

  if (recentEvents.has(key) && now - recentEvents.get(key) < DEBOUNCE_MS) {
    return true;
  }

  recentEvents.set(key, now);
  return false;
}

// --- Start watcher ---
writeLog(formatEntry("START", `Watching ${path.resolve(WATCH_DIR)}`));

const watcher = fs.watch(WATCH_DIR, (eventType, filename) => {
  if (!filename || isDuplicate(eventType, filename)) return;

  // Skip the audit log itself if it lives in the watched dir
  if (path.resolve(WATCH_DIR, filename) === path.resolve(LOG_FILE)) return;

  const fullPath = path.join(WATCH_DIR, filename);
  const exists = fs.existsSync(fullPath);

  if (eventType === "rename") {
    if (exists && !knownFiles.has(filename)) {
      // New file appeared
      knownFiles.add(filename);
      writeLog(formatEntry("CREATE", filename));
    } else if (!exists && knownFiles.has(filename)) {
      // File removed
      knownFiles.delete(filename);
      writeLog(formatEntry("DELETE", filename));
    } else {
      writeLog(formatEntry("RENAME", filename));
    }
  } else if (eventType === "change") {
    writeLog(formatEntry("MODIFY", filename));
  }
});

// --- Graceful shutdown ---
function shutdown() {
  writeLog(formatEntry("STOP", "Watcher shutting down"));
  watcher.close();
  process.exit(0);
}

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

console.log(`Audit logger running. Logs → ${path.resolve(LOG_FILE)}`);
console.log("Press Ctrl+C to stop.\n");
```

