## Core Queue

```js
// src/queue.js
const { EventEmitter } = require("events");
const crypto = require("crypto");

class TaskQueue extends EventEmitter {
  #queue = [];        // priority queue (min-heap by priority then timestamp)
  #delayed = [];      // tasks scheduled for later
  #timerHandle = null;

  constructor() {
    super();
    this.#startDelayedChecker();
  }

  enqueue(taskName, payload = {}, options = {}) {
    const task = {
      id: crypto.randomUUID(),
      name: taskName,
      payload,
      priority: options.priority ?? 5,        // 1 (highest) – 10 (lowest)
      attempts: 0,
      maxRetries: options.maxRetries ?? 3,
      retryDelayMs: options.retryDelayMs ?? 1000,
      backoffMultiplier: options.backoffMultiplier ?? 2,
      delay: options.delay ?? 0,              // ms before becoming available
      createdAt: Date.now(),
      availableAt: Date.now() + (options.delay ?? 0),
    };

    if (task.delay > 0) {
      this.#delayed.push(task);
      this.#delayed.sort((a, b) => a.availableAt - b.availableAt);
      this.emit("delayed", task);
    } else {
      this.#insertByPriority(task);
      this.emit("enqueued", task);
    }

    return task.id;
  }

  requeue(task) {
    task.attempts += 1;
    const delay = task.retryDelayMs * Math.pow(task.backoffMultiplier, task.attempts - 1);
    task.availableAt = Date.now() + delay;

    this.#delayed.push(task);
    this.#delayed.sort((a, b) => a.availableAt - b.availableAt);
    this.emit("requeued", task);
  }

  dequeue() {
    if (this.#queue.length === 0) return null;
    const task = this.#queue.shift();
    this.emit("dequeued", task);
    return task;
  }

  get size() {
    return this.#queue.length;
  }

  get pendingDelayed() {
    return this.#delayed.length;
  }

  // Insert maintaining priority order (lower number = higher priority)
  #insertByPriority(task) {
    const idx = this.#queue.findIndex(
      (t) => t.priority > task.priority ||
             (t.priority === task.priority && t.createdAt > task.createdAt)
    );
    if (idx === -1) {
      this.#queue.push(task);
    } else {
      this.#queue.splice(idx, 0, task);
    }
  }

  // Move delayed tasks into the main queue when ready
  #startDelayedChecker() {
    this.#timerHandle = setInterval(() => {
      const now = Date.now();
      while (this.#delayed.length > 0 && this.#delayed[0].availableAt <= now) {
        const task = this.#delayed.shift();
        this.#insertByPriority(task);
        this.emit("enqueued", task);
      }
    }, 200);
  }

  shutdown() {
    clearInterval(this.#timerHandle);
  }
}

module.exports = { TaskQueue };
```

