// src/taskRegistry.js

class TaskRegistry {
  #handlers = new Map();

  register(taskName, handler, options = {}) {
    if (typeof handler !== "function") {
      throw new TypeError(`Handler for "${taskName}" must be a function`);
    }

    this.#handlers.set(taskName, {
      handler,
      timeout: options.timeout ?? 30_000,   // default 30s timeout per task
    });

    return this;
  }

  get(taskName) {
    return this.#handlers.get(taskName) ?? null;
  }

  has(taskName) {
    return this.#handlers.has(taskName);
  }

  list() {
    return [...this.#handlers.keys()];
  }
}

module.exports = { TaskRegistry };
