## Dead Letter Queue

```js
// src/deadLetterQueue.js
const fs = require("fs/promises");
const path = require("path");

class DeadLetterQueue {
  #items = [];
  #logPath;

  constructor(logDir = "./dlq-logs") {
    this.#logPath = logDir;
  }

  async add(task, error) {
    const entry = {
      task,
      error: {
        message: error.message,
        stack: error.stack,
      },
      failedAt: new Date().toISOString(),
    };

    this.#items.push(entry);

    // Persist to disk so failed tasks survive restarts
    try {
      await fs.mkdir(this.#logPath, { recursive: true });
      const file = path.join(this.#logPath, `${task.id}.json`);
      await fs.writeFile(file, JSON.stringify(entry, null, 2));
    } catch (writeErr) {
      console.error("[DLQ] Failed to persist:", writeErr.message);
    }
  }

  getAll() {
    return [...this.#items];
  }

  get size() {
    return this.#items.length;
  }
}

module.exports = { DeadLetterQueue };
```

## Queue Consumer

```js
// src/consumer.js
const { EventEmitter } = require("events");

class Consumer extends EventEmitter {
  #queue;
  #registry;
  #dlq;
  #concurrency;
  #activeCount = 0;
  #running = false;
  #pollInterval;
  #pollTimer = null;

  constructor(queue, registry, dlq, options = {}) {
    super();
    this.#queue = queue;
    this.#registry = registry;
    this.#dlq = dlq;
    this.#concurrency = options.concurrency ?? 3;
    this.#pollInterval = options.pollInterval ?? 250;
  }

  start() {
    if (this.#running) return;
    this.#running = true;
    console.log(`[Consumer] Started (concurrency=${this.#concurrency})`);

    // Poll for tasks
    this.#pollTimer = setInterval(() => this.#tick(), this.#pollInterval);

    // Also react immediately when new tasks arrive
    this.#queue.on("enqueued", () => this.#tick());
  }

  stop() {
    this.#running = false;
    clearInterval(this.#pollTimer);
    console.log("[Consumer] Stopping... waiting for active tasks to finish");
    return this.#waitForDrain();
  }

  async #tick() {
    while (this.#running && this.#activeCount < this.#concurrency && this.#queue.size > 0) {
      const task = this.#queue.dequeue();
      if (!task) break;
      this.#process(task); // fire and forget — concurrency tracked internally
    }
  }

  async #process(task) {
    this.#activeCount++;
    const registered = this.#registry.get(task.name);

    if (!registered) {
      console.error(`[Consumer] No handler registered for "${task.name}"`);
      await this.#dlq.add(task, new Error(`Unknown task: ${task.name}`));
      this.#activeCount--;
      return;
    }

    const { handler, timeout } = registered;
    const startTime = Date.now();

    try {
      console.log(`[Consumer] Processing ${task.name} (id=${task.id}, attempt=${task.attempts + 1})`);

      // Run handler with a timeout
      const result = await Promise.race([
        handler(task.payload, { taskId: task.id, attempt: task.attempts + 1 }),
        this.#createTimeout(timeout, task.id),
      ]);

      const elapsed = Date.now() - startTime;
      console.log(`[Consumer] ✓ ${task.name} completed in ${elapsed}ms`);
      this.emit("completed", { task, result, elapsed });
    } catch (err) {
      const canRetry = task.attempts < task.maxRetries;

      if (canRetry) {
        console.warn(`[Consumer] ✗ ${task.name} failed (attempt ${task.attempts + 1}/${task.maxRetries + 1}): ${err.message}. Retrying...`);
        this.#queue.requeue(task);
        this.emit("retrying", { task, error: err });
      } else {
        console.error(`[Consumer] ✗ ${task.name} permanently failed after ${task.attempts + 1} attempts: ${err.message}`);
        await this.#dlq.add(task, err);
        this.emit("failed", { task, error: err });
      }
    } finally {
      this.#activeCount--;
    }
  }

  #createTimeout(ms, taskId) {
    return new Promise((_, reject) => {
      setTimeout(() => reject(new Error(`Task ${taskId} timed out after ${ms}ms`)), ms);
    });
  }

  #waitForDrain() {
    return new Promise((resolve) => {
      const check = setInterval(() => {
        if (this.#activeCount === 0) {
          clearInterval(check);
          console.log("[Consumer] All tasks drained. Stopped.");
          resolve();
        }
      }, 100);
    });
  }

  get stats() {
    return {
      active: this.#activeCount,
      queued: this.#queue.size,
      delayed: this.#queue.pendingDelayed,
      deadLettered: this.#dlq.size,
    };
  }
}

module.exports = { Consumer };
```

## Scheduler (Recurring Tasks)

```js
// src/scheduler.js

class Scheduler {
  #queue;
  #jobs = new Map();

  constructor(queue) {
    this.#queue = queue;
  }

  /**
   * Schedule a recurring task.
   * @param {string} name       - unique schedule name
   * @param {string} taskName   - registered task name
   * @param {object} payload    - data to pass
   * @param {number} intervalMs - how often to run
   * @param {object} taskOpts   - priority, maxRetries, etc.
   */
  every(name, taskName, payload, intervalMs, taskOpts = {}) {
    if (this.#jobs.has(name)) {
      throw new Error(`Schedule "${name}" already exists`);
    }

    // Run immediately, then on interval
    const enqueue = () => this.#queue.enqueue(taskName, payload, taskOpts);
    enqueue();

    const handle = setInterval(enqueue, intervalMs);
    this.#jobs.set(name, { handle, taskName, intervalMs });

    console.log(`[Scheduler] "${name}" → ${taskName} every ${intervalMs}ms`);
    return this;
  }

  cancel(name) {
    const job = this.#jobs.get(name);
    if (job) {
      clearInterval(job.handle);
      this.#jobs.delete(name);
      console.log(`[Scheduler] Cancelled "${name}"`);
    }
  }

  cancelAll() {
    for (const [name] of this.#jobs) {
      this.cancel(name);
    }
  }
}

module.exports = { Scheduler };
```

