## Entry Point — Wiring It All Together

```js
// src/index.js
const { TaskQueue } = require("./queue");
const { TaskRegistry } = require("./taskRegistry");
const { DeadLetterQueue } = require("./deadLetterQueue");
const { Consumer } = require("./consumer");
const { Scheduler } = require("./scheduler");
const config = require("../config");

// --- Task handlers ---
const sendEmail = require("../tasks/sendEmail");
const generateReport = require("../tasks/generateReport");
const cleanupExpired = require("../tasks/cleanupExpired");

async function main() {
  // 1. Initialize components
  const queue = new TaskQueue();
  const registry = new TaskRegistry();
  const dlq = new DeadLetterQueue("./dlq-logs");
  const consumer = new Consumer(queue, registry, dlq, config.consumer);
  const scheduler = new Scheduler(queue);

  // 2. Register task handlers
  registry
    .register("send-email", sendEmail, { timeout: 10_000 })
    .register("generate-report", generateReport, { timeout: 60_000 })
    .register("cleanup-expired", cleanupExpired, { timeout: 15_000 });

  console.log("Registered tasks:", registry.list());

  // 3. Start consumer
  consumer.start();

  // 4. Enqueue one-off tasks
  queue.enqueue("send-email", {
    to: "alice@example.com",
    subject: "Welcome!",
    body: "Thanks for signing up.",
  }, { priority: 1 }); // high priority

  queue.enqueue("send-email", {
    to: "bob@example.com",
    subject: "Weekly digest",
    body: "Here's what you missed.",
  }, { priority: 5, delay: 2000 }); // delayed by 2s

  queue.enqueue("generate-report", {
    reportType: "monthly-sales",
    userId: "user-42",
  }, { priority: 3, maxRetries: 2 });

  // 5. Schedule recurring tasks
  scheduler.every(
    "nightly-cleanup",
    "cleanup-expired",
    { olderThanDays: 30 },
    10_000, // every 10s for demo (use longer in production)
    { priority: 8 }
  );

  // 6. Log consumer events
  consumer.on("completed", ({ task, elapsed }) => {
    console.log(`[Event] ✓ ${task.name}#${task.id} done (${elapsed}ms)`);
  });

  consumer.on("failed", ({ task, error }) => {
    console.log(`[Event] ✗ ${task.name}#${task.id} → DLQ: ${error.message}`);
  });

  // 7. Periodic stats
  const statsTimer = setInterval(() => {
    console.log("[Stats]", consumer.stats);
  }, 5000);

  // 8. Graceful shutdown
  async function shutdown(signal) {
    console.log(`\n[Shutdown] Received ${signal}`);
    clearInterval(statsTimer);
    scheduler.cancelAll();
    await consumer.stop();
    queue.shutdown();
    console.log("[Shutdown] DLQ entries:", dlq.size);
    process.exit(0);
  }

  process.on("SIGINT", () => shutdown("SIGINT"));
  process.on("SIGTERM", () => shutdown("SIGTERM"));
}

main().catch(console.error);
```

