## Key Design Decisions

| Concern | Approach |
|---|---|
| **Priority** | Lower number = runs first, FIFO within same priority |
| **Retry** | Exponential backoff (`delay × 2^attempt`), configurable per task |
| **Concurrency** | Capped active promises, no thread pool needed |
| **Timeout** | `Promise.race` against a reject timer per task |
| **Dead letters** | Persisted to disk as JSON for later inspection/replay |
| **Graceful shutdown** | Stops accepting, waits for in-flight tasks to complete |
| **Scheduling** | Simple interval-based; swap in `node-cron` for cron expressions |

For production, swap the in-memory queue with **Redis + BullMQ** — the consumer/registry/DLQ patterns stay identical, only the storage layer changes.

# Background Worker with Cancellation in JavaScript

## Approach 1: Web Worker with AbortController Pattern

### Worker Wrapper Class (main thread)

```javascript
class CancellableWorker {
  #worker;
  #taskId = 0;
  #pendingTasks = new Map(); // taskId -> { resolve, reject, abortController }

  constructor(scriptURL) {
    this.#worker = new Worker(scriptURL);
    this.#worker.onmessage = (e) => this.#handleMessage(e.data);
    this.#worker.onerror = (e) => this.#handleError(e);
  }

  /**
   * Run a task in the worker, returning a promise that can be
   * cancelled via the AbortSignal.
   */
  run(taskName, payload, { signal } = {}) {
    const id = ++this.#taskId;

    return new Promise((resolve, reject) => {
      // If already aborted before we even start
      if (signal?.aborted) {
        reject(new DOMException('Task cancelled before start', 'AbortError'));
        return;
      }

      // Store task metadata
      this.#pendingTasks.set(id, { resolve, reject });

      // Listen for external cancellation
      const onAbort = () => {
        this.#worker.postMessage({ type: 'cancel', id });
        this.#pendingTasks.delete(id);
        reject(new DOMException(`Task "${taskName}" was cancelled`, 'AbortError'));
      };

      signal?.addEventListener('abort', onAbort, { once: true });

      // Clean up the abort listener when the task finishes normally
      const originalResolve = resolve;
      const originalReject = reject;

      this.#pendingTasks.set(id, {
        resolve: (value) => {
          signal?.removeEventListener('abort', onAbort);
          originalResolve(value);
        },
        reject: (err) => {
          signal?.removeEventListener('abort', onAbort);
          originalReject(err);
        },
      });

      // Send task to worker
      this.#worker.postMessage({ type: 'run', id, taskName, payload });
    });
  }

  #handleMessage(data) {
    const { id, type, result, error, progress } = data;
    const task = this.#pendingTasks.get(id);
    if (!task) return; // Already cancelled

    switch (type) {
      case 'result':
        this.#pendingTasks.delete(id);
        task.resolve(result);
        break;
      case 'error':
        this.#pendingTasks.delete(id);
        task.reject(new Error(error));
        break;
      case 'progress':
        // Optional: emit progress if a callback is attached
        task.onProgress?.(progress);
        break;
    }
  }

  #handleError(event) {
    console.error('Worker error:', event.message);
    // Reject all pending tasks
    for (const [id, task] of this.#pendingTasks) {
      task.reject(new Error(`Worker error: ${event.message}`));
    }
    this.#pendingTasks.clear();
  }

  terminate() {
    this.#worker.terminate();
    for (const [, task] of this.#pendingTasks) {
      task.reject(new DOMException('Worker terminated', 'AbortError'));
    }
    this.#pendingTasks.clear();
  }
}
```

### Worker Script (`worker.js`)

```javascript
// Registry of available tasks
const tasks = {};

// Track which task IDs have been cancelled
const cancelledTasks = new Set();

// ---------- Define tasks ----------

tasks.heavyComputation = (payload, ctx) => {
  const { iterations = 1_000_000 } = payload;
  let total = 0;

  for (let i = 0; i < iterations; i++) {
    // Periodically check for cancellation (every 10k iterations)
    if (i % 10_000 === 0) {
      if (ctx.isCancelled()) return; // Stop early

      // Report progress
      ctx.reportProgress(Math.round((i / iterations) * 100));
    }
    total += Math.sqrt(i) * Math.sin(i);
  }

  return total;
};

tasks.fibonacci = (payload, ctx) => {
  const { n = 40 } = payload;

  function fib(num, depth) {
    if (ctx.isCancelled()) return 0;
    if (num <= 1) return num;
    return fib(num - 1, depth + 1) + fib(num - 2, depth + 1);
  }

  return fib(n, 0);
};

// ---------- Message handler ----------

self.onmessage = (e) => {
  const { type, id, taskName, payload } = e.data;

  if (type === 'cancel') {
    cancelledTasks.add(id);
    return;
  }

  if (type === 'run') {
    const taskFn = tasks[taskName];

    if (!taskFn) {
      self.postMessage({ id, type: 'error', error: `Unknown task: ${taskName}` });
      return;
    }

    // Build a context object the task can use
    const ctx = {
      isCancelled: () => cancelledTasks.has(id),
      reportProgress: (progress) => {
        if (!cancelledTasks.has(id)) {
          self.postMessage({ id, type: 'progress', progress });
        }
      },
    };

    try {
      const result = taskFn(payload, ctx);

      if (!cancelledTasks.has(id)) {
        self.postMessage({ id, type: 'result', result });
      }
    } catch (err) {
      if (!cancelledTasks.has(id)) {
        self.postMessage({ id, type: 'error', error: err.message });
      }
    } finally {
      cancelledTasks.delete(id);
    }
  }
};
```

