const ctrl2 = new AbortController();

const task1 = worker.run('heavyComputation', { iterations: 50_000_000 }, { signal: ctrl1.signal });
const task2 = worker.run('fibonacci', { n: 38 }, { signal: ctrl2.signal });

// Cancel only the first task
