```javascript
#!/usr/bin/env node

import { AuditLogger } from '../lib/logger.js';

const logger = new AuditLogger();
const [,, command, ...args] = process.argv;

// ── Helpers ──────────────────────────────────────────────
function printUsage() {
  console.log(`
  audit-logger — Basic CLI Audit Logging Tool

  USAGE
    audit log   <user> <action> [detail]    Add an audit entry
    audit list  [--user <name>] [--action <type>] [--last <n>]
                                             List audit entries
    audit show  <id>                         Show a single entry
    audit stats                              Show summary stats
    audit clear --confirm                    Delete all entries
    audit export <filepath>                  Export logs to CSV
    audit help                               Show this message
  `);
}

function parseFlags(args) {
  const flags = {};
  let i = 0;
  while (i < args.length) {
    if (args[i].startsWith('--')) {
      const key = args[i].slice(2);
      flags[key] = args[i + 1] ?? true;
      i += 2;
    } else {
      i++;
    }
  }
  return flags;
}

// ── Commands ─────────────────────────────────────────────
const commands = {

  log() {
    const [user, action, ...rest] = args;
    if (!user || !action) {
      console.error('  Error: "user" and "action" are required.\n');
      console.error('  Usage: audit log <user> <action> [detail]');
      process.exit(1);
    }
    const detail = rest.join(' ') || null;
    const entry = logger.log(user, action, detail);
    console.log(`  ✔ Logged entry ${entry.id}`);
    console.log(`    ${entry.timestamp} | ${entry.user} | ${entry.action}`);
  },

  list() {
    const flags = parseFlags(args);
    let entries = logger.list();

    if (flags.user) {
      entries = entries.filter(
        e => e.user.toLowerCase() === flags.user.toLowerCase()
      );
    }
    if (flags.action) {
      entries = entries.filter(
        e => e.action.toLowerCase() === flags.action.toLowerCase()
      );
    }
    if (flags.last) {
      entries = entries.slice(-Number(flags.last));
    }

    if (entries.length === 0) {
      console.log('  No entries found.');
      return;
    }

    // Table header
    console.log('');
    console.log(
      '  ' +
      'ID'.padEnd(8) +
      'TIMESTAMP'.padEnd(26) +
      'USER'.padEnd(16) +
      'ACTION'.padEnd(16) +
      'DETAIL'
    );
    console.log('  ' + '─'.repeat(80));

    for (const e of entries) {
      console.log(
        '  ' +
        e.id.toString().padEnd(8) +
        e.timestamp.padEnd(26) +
