  └──────────────────────────────`);
  },

  stats() {
    const entries = logger.list();
    if (entries.length === 0) {
      console.log('  No entries yet.');
      return;
    }

    const users = {};
    const actions = {};
    for (const e of entries) {
      users[e.user] = (users[e.user] || 0) + 1;
      actions[e.action] = (actions[e.action] || 0) + 1;
    }

    console.log(`\n  Total entries: ${entries.length}`);
    console.log(`  First entry : ${entries[0].timestamp}`);
    console.log(`  Last entry  : ${entries[entries.length - 1].timestamp}`);

    console.log('\n  By User:');
    for (const [u, count] of Object.entries(users)) {
      console.log(`    ${u.padEnd(20)} ${count}`);
    }

    console.log('\n  By Action:');
    for (const [a, count] of Object.entries(actions)) {
      console.log(`    ${a.padEnd(20)} ${count}`);
    }
    console.log('');
  },

  clear() {
    const flags = parseFlags(args);
    if (!flags.confirm) {
      console.error('  Pass --confirm to delete all entries.');
      process.exit(1);
    }
    const count = logger.clear();
    console.log(`  ✔ Cleared ${count} entries.`);
  },

  export() {
    const filepath = args[0];
    if (!filepath) {
      console.error('  Error: provide an export file path.');
      process.exit(1);
    }
    const count = logger.exportCsv(filepath);
    console.log(`  ✔ Exported ${count} entries to ${filepath}`);
  },

  help() {
    printUsage();
  }
};

