## lib/store.js

```javascript
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

/**
 * Simple JSON file store with auto-increment IDs.
 */
export class Store {
  constructor(filepath) {
    this.filepath = filepath;
    this._ensureFile();
  }

  _ensureFile() {
    const dir = dirname(this.filepath);
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }
    if (!existsSync(this.filepath)) {
      writeFileSync(this.filepath, JSON.stringify({ nextId: 1, entries: [] }));
    }
  }

  _read() {
    const raw = readFileSync(this.filepath, 'utf-8');
    return JSON.parse(raw);
  }

  _write(data) {
    writeFileSync(this.filepath, JSON.stringify(data, null, 2));
  }

  add(entry) {
    const data = this._read();
    entry.id = data.nextId++;
    data.entries.push(entry);
    this._write(data);
    return entry;
  }

  getAll() {
    return this._read().entries;
  }

  findById(id) {
    return this.getAll().find(e => e.id === id) ?? null;
  }

  clear() {
    const data = this._read();
    const count = data.entries.length;
    data.entries = [];
    data.nextId = 1;
    this._write(data);
    return count;
  }
}
```

## lib/logger.js

```javascript
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { Store } from './store.js';

const DATA_DIR = new URL('../data', import.meta.url).pathname;
const DB_PATH = resolve(DATA_DIR, 'audit.json');

export class AuditLogger {
  constructor() {
    this.store = new Store(DB_PATH);
  }

  /** Create a new audit entry. */
  log(user, action, detail = null) {
    const entry = {
      timestamp: new Date().toISOString(),
      user,
      action,
      detail
    };
    return this.store.add(entry);
  }

  /** Return all entries. */
  list() {
    return this.store.getAll();
  }

  /** Find a single entry by ID. */
  getById(id) {
    return this.store.findById(id);
  }

  /** Delete everything, return previous count. */
  clear() {
    return this.store.clear();
  }

  /** Export all entries as CSV, return count. */
  exportCsv(filepath) {
    const entries = this.list();
    const header = 'id,timestamp,user,action,detail';
    const rows = entries.map(e =>
      [e.id, e.timestamp, e.user, e.action, e.detail ?? ''].join(',')
    );
    writeFileSync(filepath, [header, ...rows].join('\n'));
    return entries.length;
  }
}
