## Key Design Decisions

| Decision | Rationale |
|---|---|
| **JSON file store** | Zero dependencies, human-readable, easy to back up |
| **Auto-increment IDs** | Simple lookup without UUIDs |
| **ISO 8601 timestamps** | Sortable, unambiguous, timezone-aware |
| **No external deps** | Entire tool uses only `node:fs` and `node:path` |
| **CSV export** | Universal format for importing into spreadsheets or SIEM tools |
| **Flag parsing by hand** | Keeps it dependency-free; sufficient for a basic tool |

# Background Worker with Rate Limiting in JavaScript

## Token Bucket Rate Limiter + Job Queue Worker

```javascript
// ============================================================
// rateLimiter.js - Token Bucket Rate Limiter
// ============================================================

class TokenBucketRateLimiter {
  /**
   * @param {number} maxTokens    - Maximum burst capacity
   * @param {number} refillRate   - Tokens added per second
   */
  constructor(maxTokens, refillRate) {
    this.maxTokens = maxTokens;
    this.tokens = maxTokens;
    this.refillRate = refillRate;
    this.lastRefillTimestamp = Date.now();
  }

  /** Refill tokens based on elapsed time */
  _refill() {
    const now = Date.now();
    const elapsedMs = now - this.lastRefillTimestamp;
    const tokensToAdd = (elapsedMs / 1000) * this.refillRate;

    this.tokens = Math.min(this.maxTokens, this.tokens + tokensToAdd);
    this.lastRefillTimestamp = now;
  }

  /** Try to consume a token; returns true if allowed */
  tryConsume(count = 1) {
    this._refill();
    if (this.tokens >= count) {
      this.tokens -= count;
      return true;
    }
    return false;
  }

  /** Returns milliseconds until `count` tokens are available */
  getWaitTime(count = 1) {
    this._refill();
    if (this.tokens >= count) return 0;
    const deficit = count - this.tokens;
    return Math.ceil((deficit / this.refillRate) * 1000);
  }

  /** Returns a snapshot of current state */
  getStatus() {
    this._refill();
    return {
      availableTokens: Math.floor(this.tokens),
      maxTokens: this.maxTokens,
      refillRate: this.refillRate,
    };
  }
}

// ============================================================
// backgroundWorker.js - Queue-based Worker with Rate Limiting
// ============================================================

class BackgroundWorker {
  /**
   * @param {Object} options
   * @param {number} options.maxTokens        - Bucket size (default: 10)
   * @param {number} options.refillRate       - Tokens/sec (default: 5)
   * @param {number} options.maxRetries       - Retry attempts (default: 3)
   * @param {number} options.baseBackoffMs    - Initial backoff (default: 1000)
   * @param {number} options.concurrency      - Parallel jobs (default: 3)
   * @param {number} options.maxQueueSize     - Max queued jobs (default: 1000)
   */
  constructor(options = {}) {
    const {
      maxTokens = 10,
      refillRate = 5,
      maxRetries = 3,
      baseBackoffMs = 1000,
      concurrency = 3,
      maxQueueSize = 1000,
    } = options;

    this.rateLimiter = new TokenBucketRateLimiter(maxTokens, refillRate);
    this.maxRetries = maxRetries;
    this.baseBackoffMs = baseBackoffMs;
    this.concurrency = concurrency;
    this.maxQueueSize = maxQueueSize;

    // Internal state
    this.queue = [];                // Pending jobs
    this.activeJobs = new Map();    // jobId → AbortController
    this.activeCount = 0;
    this.isPaused = false;
    this.isShuttingDown = false;
    this.jobIdCounter = 0;

    // Metrics
    this.metrics = {
      totalEnqueued: 0,
      totalProcessed: 0,
      totalFailed: 0,
      totalRetries: 0,
      totalRateLimited: 0,
    };

    // Event handlers
    this._handlers = {
      jobComplete: [],
      jobFailed: [],
      rateLimited: [],
      drained: [],
      error: [],
    };
  }

  // ----------------------------------------------------------
  // Event Emitter (minimal)
  // ----------------------------------------------------------

  on(event, handler) {
    if (this._handlers[event]) {
      this._handlers[event].push(handler);
    }
    return this;
  }

  _emit(event, data) {
    (this._handlers[event] || []).forEach((fn) => {
      try { fn(data); }
      catch (err) { console.error(`Handler error [${event}]:`, err); }
    });
  }

  // ----------------------------------------------------------
  // Public API
  // ----------------------------------------------------------

  /**
   * Enqueue a job for background processing
   * @param {Function} taskFn    - Async function to execute
   * @param {Object}   meta      - Optional metadata / context
   * @param {number}   priority  - Lower = higher priority (default: 5)
   * @returns {{ jobId: number, position: number }}
   */
  enqueue(taskFn, meta = {}, priority = 5) {
    if (this.isShuttingDown) {
      throw new Error("Worker is shutting down; cannot accept new jobs.");
    }
    if (this.queue.length >= this.maxQueueSize) {
      throw new Error(`Queue full (max ${this.maxQueueSize}).`);
    }

    const jobId = ++this.jobIdCounter;
    const job = {
      id: jobId,
      taskFn,
      meta,
      priority,
      retries: 0,
      createdAt: Date.now(),
    };

    // Insert in priority order (lower number = higher priority)
    const insertIdx = this.queue.findIndex((j) => j.priority > priority);
    if (insertIdx === -1) {
      this.queue.push(job);
    } else {
      this.queue.splice(insertIdx, 0, job);
    }

    this.metrics.totalEnqueued++;
    this._scheduleProcessing();

    return { jobId, position: insertIdx === -1 ? this.queue.length : insertIdx + 1 };
  }

  /** Pause processing (in-flight jobs continue) */
  pause() {
    this.isPaused = true;
  }

  /** Resume processing */
  resume() {
    this.isPaused = false;
    this._scheduleProcessing();
  }

  /** Cancel a specific job by ID */
  cancel(jobId) {
    // Remove from queue
    const idx = this.queue.findIndex((j) => j.id === jobId);
    if (idx !== -1) {
      this.queue.splice(idx, 1);
      return true;
    }
    // Abort if currently active
    const controller = this.activeJobs.get(jobId);
    if (controller) {
      controller.abort();
      return true;
    }
    return false;
  }

  /** Graceful shutdown: finish active jobs, reject remaining queue */
  async shutdown(timeoutMs = 30000) {
    this.isShuttingDown = true;
    this.queue = []; // Clear pending

    if (this.activeCount === 0) return;

    // Wait for in-flight jobs or timeout
    return new Promise((resolve) => {
      const checkInterval = setInterval(() => {
        if (this.activeCount === 0) {
          clearInterval(checkInterval);
          resolve();
        }
      }, 100);

      setTimeout(() => {
        clearInterval(checkInterval);
        // Force-abort remaining jobs
        for (const [, controller] of this.activeJobs) {
          controller.abort();
        }
        resolve();
      }, timeoutMs);
    });
  }

  /** Returns current stats */
  getStatus() {
    return {
      queueLength: this.queue.length,
      activeJobs: this.activeCount,
      isPaused: this.isPaused,
      rateLimiter: this.rateLimiter.getStatus(),
      metrics: { ...this.metrics },
    };
  }

  // ----------------------------------------------------------
  // Internal Processing Loop
  // ----------------------------------------------------------

  _scheduleProcessing() {
    // Use microtask to batch multiple enqueue calls
    if (!this._processingScheduled) {
      this._processingScheduled = true;
      queueMicrotask(() => {
        this._processingScheduled = false;
        this._processNext();
      });
    }
  }

  async _processNext() {
    // Guard clauses
    if (this.isPaused || this.isShuttingDown) return;
    if (this.queue.length === 0) {
      if (this.activeCount === 0) this._emit("drained", this.metrics);
      return;
    }
    if (this.activeCount >= this.concurrency) return;

    // --- Rate Limit Check ---
    if (!this.rateLimiter.tryConsume()) {
      const waitMs = this.rateLimiter.getWaitTime();
      this.metrics.totalRateLimited++;
      this._emit("rateLimited", { waitMs, queueLength: this.queue.length });

      // Retry after waiting for a token
      setTimeout(() => this._processNext(), waitMs);
      return;
    }

    // Dequeue the highest-priority job
    const job = this.queue.shift();
    this.activeCount++;

    // Create an AbortController for cancellation support
    const controller = new AbortController();
    this.activeJobs.set(job.id, controller);

    // Execute the job
    this._executeJob(job, controller.signal)
      .then((result) => {
        this.metrics.totalProcessed++;
        this._emit("jobComplete", {
          jobId: job.id,
          meta: job.meta,
          result,
          duration: Date.now() - job.createdAt,
        });
      })
      .catch((error) => {
        this._handleJobFailure(job, error);
      })
      .finally(() => {
        this.activeCount--;
        this.activeJobs.delete(job.id);
        // Continue processing remaining jobs
        this._processNext();
      });

    // Fill remaining concurrency slots
    if (this.activeCount < this.concurrency && this.queue.length > 0) {
      this._processNext();
    }
  }

  async _executeJob(job, signal) {
    // Wrap the task so it respects the abort signal
    return new Promise((resolve, reject) => {
      if (signal.aborted) {
        return reject(new Error("Job was cancelled."));
      }

      const onAbort = () => reject(new Error("Job was cancelled."));
      signal.addEventListener("abort", onAbort, { once: true });

      Promise.resolve(job.taskFn({ signal, meta: job.meta }))
        .then(resolve)
        .catch(reject)
        .finally(() => signal.removeEventListener("abort", onAbort));
    });
  }

  _handleJobFailure(job, error) {
    if (error.message === "Job was cancelled.") {
      this._emit("jobFailed", { jobId: job.id, error, cancelled: true });
      return;
    }

    if (job.retries < this.maxRetries) {
      job.retries++;
      this.metrics.totalRetries++;

      // Exponential backoff with jitter
      const backoff =
        this.baseBackoffMs * Math.pow(2, job.retries - 1) +
        Math.random() * 500;

      console.warn(
        `[Worker] Job ${job.id} failed (attempt ${job.retries}/${this.maxRetries}). ` +
        `Retrying in ${Math.round(backoff)}ms...`
      );

      setTimeout(() => {
        this.queue.unshift(job); // Re-add at front (high priority retry)
        this._scheduleProcessing();
      }, backoff);
    } else {
      this.metrics.totalFailed++;
      this._emit("jobFailed", {
        jobId: job.id,
        meta: job.meta,
        error,
        retries: job.retries,
      });
    }
  }
}

// ============================================================
// Demo Usage
// ============================================================

async function main() {
  // --- Create worker: 10 req burst, refills 2 tokens/sec ---
  const worker = new BackgroundWorker({
    maxTokens: 10,
    refillRate: 2,
    maxRetries: 2,
    concurrency: 3,
  });

  // --- Register event listeners ---
  worker.on("jobComplete", ({ jobId, result, duration }) => {
    console.log(`✅ Job #${jobId} completed in ${duration}ms → ${result}`);
  });

  worker.on("jobFailed", ({ jobId, error, retries }) => {
    console.error(`❌ Job #${jobId} failed after ${retries} retries: ${error.message}`);
  });

  worker.on("rateLimited", ({ waitMs, queueLength }) => {
    console.warn(`⏳ Rate limited — waiting ${waitMs}ms (${queueLength} queued)`);
  });

  worker.on("drained", (metrics) => {
    console.log("\n📊 Queue drained. Final metrics:", metrics);
  });

  // --- Simulate an external API call ---
  const fakeApiCall = async ({ signal, meta }) => {
    const delay = 200 + Math.random() * 300;
    await new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, delay);
      signal.addEventListener("abort", () => {
        clearTimeout(timer);
        reject(new Error("Aborted"));
      }, { once: true });
    });

    // Simulate 20% failure rate
    if (Math.random() < 0.2) {
      throw new Error(`API error for "${meta.url}"`);
    }

    return `Response from ${meta.url} (${Math.round(delay)}ms)`;
  };

  // --- Enqueue 20 jobs (exceeds burst of 10 → triggers rate limiting) ---
  console.log("🚀 Enqueueing 20 API jobs...\n");

  for (let i = 1; i <= 20; i++) {
    const priority = i <= 5 ? 1 : 5; // First 5 are high priority
    const { jobId, position } = worker.enqueue(
      fakeApiCall,
      { url: `/api/resource/${i}` },
      priority
    );
    console.log(`📥 Enqueued Job #${jobId} (priority ${priority}, position ${position})`);
  }

  // --- Show live status every 2 seconds ---
  const statusInterval = setInterval(() => {
    const status = worker.getStatus();
    console.log(
      `\n📈 Status: ${status.activeJobs} active, ` +
      `${status.queueLength} queued, ` +
      `${status.rateLimiter.availableTokens}/${status.rateLimiter.maxTokens} tokens`
    );
  }, 2000);

  // --- Wait for completion, then shut down ---
  worker.on("drained", async () => {
    clearInterval(statusInterval);
    await worker.shutdown();
    console.log("👋 Worker shut down gracefully.");
  });
}

main().catch(console.error);
