impl Config {
    /// Load config from a TOML file, expanding environment variables
    /// in string values that use the `${VAR}` syntax.
    fn from_file(path: &Path) -> Result<Self, ConfigError> {
        let raw = fs::read_to_string(path).map_err(|e| ConfigError::FileRead {
            path: path.display().to_string(),
            source: e,
        })?;

        // Expand environment variable references like ${VAR_NAME}
        let expanded = Self::expand_env_vars(&raw);

        let config: Config = toml::from_str(&expanded)?;
        config.validate()?;
        Ok(config)
    }

    /// Replace `${VAR}` patterns with corresponding environment variables.
    fn expand_env_vars(input: &str) -> String {
        let mut result = input.to_string();
        // Simple regex-free approach: scan for ${ ... }
        while let Some(start) = result.find("${") {
            if let Some(end) = result[start..].find('}') {
                let var_name = &result[start + 2..start + end];
                let replacement = std::env::var(var_name).unwrap_or_default();
                result = format!("{}{}{}", &result[..start], replacement, &result[start + end + 1..]);
            } else {
                break; // malformed placeholder, stop
            }
        }
        result
    }

    /// Validate the entire configuration for logical consistency.
    fn validate(&self) -> Result<(), ConfigError> {
        self.validate_global()?;
        self.validate_inputs()?;
        self.validate_aggregations()?;
        self.validate_outputs()?;
        Ok(())
    }

    fn validate_global(&self) -> Result<(), ConfigError> {
        if self.global.flush_interval_secs == 0 {
            return Err(ConfigError::Validation(
                "global.flush_interval_secs must be > 0".into(),
            ));
        }
        if self.global.max_batch_size == 0 {
            return Err(ConfigError::Validation(
                "global.max_batch_size must be > 0".into(),
            ));
        }
        Ok(())
    }

    fn validate_inputs(&self) -> Result<(), ConfigError> {
        let mut seen_names = std::collections::HashSet::new();

        for input in &self.inputs {
            if !seen_names.insert(&input.name) {
                return Err(ConfigError::Validation(format!(
                    "duplicate input name: '{}'",
                    input.name
                )));
            }
            if input.kind == InputKind::Prometheus && input.scrape_interval_secs.is_none() {
                return Err(ConfigError::Validation(format!(
                    "input '{}': prometheus inputs require scrape_interval_secs",
                    input.name
                )));
            }
        }
        Ok(())
    }

    fn validate_aggregations(&self) -> Result<(), ConfigError> {
        for agg in &self.aggregations {
            if agg.metric_pattern.is_empty() {
                return Err(ConfigError::Validation(
                    "aggregation metric_pattern must not be empty".into(),
                ));
            }

            if agg.window_secs == 0 {
                return Err(ConfigError::Validation(format!(
                    "aggregation '{}': window_secs must be > 0",
                    agg.metric_pattern
                )));
            }

            if agg.strategy == AggregationStrategy::Percentile {
                if agg.percentiles.is_empty() {
                    return Err(ConfigError::Validation(format!(
                        "aggregation '{}': percentile strategy requires at least one percentile value",
                        agg.metric_pattern
                    )));
                }
                for p in &agg.percentiles {
                    if !(0.0..=100.0).contains(p) {
                        return Err(ConfigError::Validation(format!(
                            "aggregation '{}': percentile {} is out of range [0, 100]",
                            agg.metric_pattern, p
                        )));
                    }
                }
            }
        }
        Ok(())
    }

    fn validate_outputs(&self) -> Result<(), ConfigError> {
        let mut seen_names = std::collections::HashSet::new();

        for output in &self.outputs {
            if !seen_names.insert(&output.name) {
                return Err(ConfigError::Validation(format!(
                    "duplicate output name: '{}'",
                    output.name
                )));
            }

            match output.kind {
                OutputKind::Datadog => {
                    if output.api_key.as_ref().map_or(true, |k| k.is_empty()) {
                        return Err(ConfigError::Validation(format!(
                            "output '{}': datadog output requires a non-empty api_key",
                            output.name
                        )));
                    }
                }
                OutputKind::File => {
                    if output.path.is_none() {
                        return Err(ConfigError::Validation(format!(
                            "output '{}': file output requires a path",
                            output.name
                        )));
                    }
                }
                OutputKind::Console => {} // no extra requirements
            }
        }
        Ok(())
    }
}

