/// Stores accumulated state for one aggregation window.
#[derive(Debug)]
struct AggregationBucket {
    pattern: String,
    strategy: AggregationStrategy,
    values: Vec<f64>,
    count: u64,
}

impl AggregationBucket {
    fn new(pattern: &str, strategy: AggregationStrategy) -> Self {
        Self {
            pattern: pattern.to_string(),
            strategy,
            values: Vec::new(),
            count: 0,
        }
    }

    fn push(&mut self, value: f64) {
        self.values.push(value);
        self.count += 1;
    }

    fn flush(&mut self) -> Vec<(String, f64)> {
        if self.values.is_empty() {
            return Vec::new();
        }

        let mut results = Vec::new();
        let name = &self.pattern;

        match self.strategy {
            AggregationStrategy::Sum => {
                let sum: f64 = self.values.iter().sum();
                results.push((format!("{name}.sum"), sum));
            }
            AggregationStrategy::Average => {
                let sum: f64 = self.values.iter().sum();
                let avg = sum / self.values.len() as f64;
                results.push((format!("{name}.avg"), avg));
            }
            AggregationStrategy::Count => {
                results.push((format!("{name}.count"), self.count as f64));
            }
            AggregationStrategy::Last => {
                if let Some(&last) = self.values.last() {
                    results.push((format!("{name}.last"), last));
                }
            }
            AggregationStrategy::Min => {
                if let Some(&min) = self.values.iter().min_by(|a, b| a.partial_cmp(b).unwrap()) {
                    results.push((format!("{name}.min"), min));
                }
            }
            AggregationStrategy::Max => {
                if let Some(&max) = self.values.iter().max_by(|a, b| a.partial_cmp(b).unwrap()) {
                    results.push((format!("{name}.max"), max));
                }
            }
            AggregationStrategy::Percentile => {
                // Handled separately with percentile list
            }
        }

        // Reset for next window
        self.values.clear();
        self.count = 0;

        results
    }

    /// Compute specific percentiles (for Percentile strategy).
    fn flush_percentiles(&mut self, percentiles: &[f64]) -> Vec<(String, f64)> {
        if self.values.is_empty() {
            return Vec::new();
        }

        self.values.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let len = self.values.len();

        let results: Vec<(String, f64)> = percentiles
            .iter()
            .map(|&p| {
                let idx = ((p / 100.0) * (len as f64 - 1.0)).round() as usize;
                let idx = idx.min(len - 1);
                (format!("{}.p{}", self.pattern, p as u32), self.values[idx])
            })
            .collect();

        self.values.clear();
        self.count = 0;

        results
    }
}

/// Matches a metric name against a glob-style pattern with `*` wildcards.
fn pattern_matches(pattern: &str, metric_name: &str) -> bool {
    if !pattern.contains('*') {
        return pattern == metric_name;
    }

    let parts: Vec<&str> = pattern.split('*').collect();

    // Single trailing wildcard: "system.cpu.*"
    if parts.len() == 2 {
        let prefix = parts[0];
        let suffix = parts[1];
        return metric_name.starts_with(prefix) && metric_name.ends_with(suffix);
    }

    // Exact prefix match for simple cases
    metric_name.starts_with(parts[0])
}

