use std::collections::HashMap;
use std::fmt;
use std::fs;
use std::path::{Path, PathBuf};
use std::thread;
use std::time::Duration;

// --- Error Types ---

#[derive(Debug)]
pub enum ConfigError {
    FileNotFound(PathBuf),
    ReadError { path: PathBuf, source: std::io::Error },
    ParseError { path: PathBuf, message: String },
    ValidationError(Vec<String>),
    MaxRetriesExceeded { attempts: u32, last_error: Box<ConfigError> },
    MissingRequiredKey(String),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::FileNotFound(path) => {
                write!(f, "Configuration file not found: {}", path.display())
            }
            ConfigError::ReadError { path, source } => {
                write!(
                    f,
                    "Failed to read configuration file '{}': {}",
                    path.display(),
                    source
                )
            }
            ConfigError::ParseError { path, message } => {
                write!(
                    f,
                    "Failed to parse configuration file '{}': {}",
                    path.display(),
                    message
                )
            }
            ConfigError::ValidationError(errors) => {
                write!(f, "Configuration validation failed:\n")?;
                for err in errors {
                    write!(f, "  - {}\n", err)?;
                }
                Ok(())
            }
            ConfigError::MaxRetriesExceeded {
                attempts,
                last_error,
            } => {
                write!(
                    f,
                    "Failed to load configuration after {} attempts. Last error: {}",
                    attempts, last_error
                )
            }
            ConfigError::MissingRequiredKey(key) => {
                write!(f, "Missing required configuration key: '{}'", key)
            }
        }
    }
}

impl std::error::Error for ConfigError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            ConfigError::ReadError { source, .. } => Some(source),
            ConfigError::MaxRetriesExceeded { last_error, .. } => Some(last_error.as_ref()),
            _ => None,
        }
    }
}

// --- Retry Policy ---

#[derive(Debug, Clone)]
pub struct RetryPolicy {
    pub max_attempts: u32,
    pub initial_delay: Duration,
    pub max_delay: Duration,
    pub backoff_multiplier: f64,
    pub jitter: bool,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            max_attempts: 3,
            initial_delay: Duration::from_millis(100),
            max_delay: Duration::from_secs(10),
            backoff_multiplier: 2.0,
            jitter: true,
        }
    }
}

impl RetryPolicy {
    pub fn no_retry() -> Self {
        Self {
            max_attempts: 1,
            ..Default::default()
        }
    }

    pub fn with_max_attempts(mut self, max_attempts: u32) -> Self {
        self.max_attempts = max_attempts;
        self
    }

    pub fn with_initial_delay(mut self, delay: Duration) -> Self {
        self.initial_delay = delay;
        self
    }

    pub fn with_max_delay(mut self, delay: Duration) -> Self {
        self.max_delay = delay;
        self
    }

    pub fn with_backoff_multiplier(mut self, multiplier: f64) -> Self {
        self.backoff_multiplier = multiplier;
        self
    }

    pub fn with_jitter(mut self, jitter: bool) -> Self {
        self.jitter = jitter;
        self
    }

    fn compute_delay(&self, attempt: u32) -> Duration {
        let base = self.initial_delay.as_millis() as f64
            * self.backoff_multiplier.powi(attempt as i32 - 1);
        let capped = base.min(self.max_delay.as_millis() as f64);

        let final_ms = if self.jitter {
            // Simple deterministic jitter based on attempt number
            let jitter_factor = 0.5 + (((attempt * 7 + 13) % 100) as f64 / 200.0);
            capped * jitter_factor
        } else {
            capped
        };

        Duration::from_millis(final_ms as u64)
    }
}

