// --- Configuration ---

#[derive(Debug, Clone)]
pub struct Config {
    values: HashMap<String, ConfigValue>,
    source_path: Option<PathBuf>,
}

impl Config {
    pub fn new() -> Self {
        Self {
            values: HashMap::new(),
            source_path: None,
        }
    }

    /// Get a value by dot-separated key path (e.g., "database.host")
    pub fn get(&self, key: &str) -> Option<&ConfigValue> {
        let parts: Vec<&str> = key.split('.').collect();

        if parts.len() == 1 {
            return self.values.get(key);
        }

        let mut current = &self.values;
        for (i, part) in parts.iter().enumerate() {
            match current.get(*part) {
                Some(ConfigValue::Table(table)) if i < parts.len() - 1 => {
                    current = table;
                }
                Some(value) if i == parts.len() - 1 => {
                    return Some(value);
                }
                _ => return None,
            }
        }
        None
    }

    pub fn get_str(&self, key: &str) -> Option<&str> {
        self.get(key).and_then(|v| v.as_str())
    }

    pub fn get_i64(&self, key: &str) -> Option<i64> {
        self.get(key).and_then(|v| v.as_i64())
    }

    pub fn get_f64(&self, key: &str) -> Option<f64> {
        self.get(key).and_then(|v| v.as_f64())
    }

    pub fn get_bool(&self, key: &str) -> Option<bool> {
        self.get(key).and_then(|v| v.as_bool())
    }

    pub fn require_str(&self, key: &str) -> Result<&str, ConfigError> {
        self.get_str(key)
            .ok_or_else(|| ConfigError::MissingRequiredKey(key.to_string()))
    }

    pub fn require_i64(&self, key: &str) -> Result<i64, ConfigError> {
        self.get_i64(key)
            .ok_or_else(|| ConfigError::MissingRequiredKey(key.to_string()))
    }

    pub fn set(&mut self, key: &str, value: ConfigValue) {
        let parts: Vec<&str> = key.split('.').collect();

        if parts.len() == 1 {
            self.values.insert(key.to_string(), value);
            return;
        }

        // Navigate/create nested tables
        let mut current = &mut self.values;
        for part in &parts[..parts.len() - 1] {
            current = current
                .entry(part.to_string())
                .or_insert_with(|| ConfigValue::Table(HashMap::new()))
                .as_table_mut();
        }
        current.insert(parts.last().unwrap().to_string(), value);
    }

    /// Merge another config into this one (other takes precedence)
    pub fn merge(&mut self, other: &Config) {
        merge_maps(&mut self.values, &other.values);
    }

    pub fn keys(&self) -> Vec<String> {
        collect_keys(&self.values, "")
    }

    pub fn source_path(&self) -> Option<&Path> {
        self.source_path.as_deref()
    }
}

impl ConfigValue {
    fn as_table_mut(&mut self) -> &mut HashMap<String, ConfigValue> {
        match self {
            ConfigValue::Table(t) => t,
            _ => panic!("Expected table value"),
        }
    }
}

fn merge_maps(
    base: &mut HashMap<String, ConfigValue>,
    overlay: &HashMap<String, ConfigValue>,
) {
    for (key, value) in overlay {
        match (base.get_mut(key), value) {
            (Some(ConfigValue::Table(base_table)), ConfigValue::Table(overlay_table)) => {
                merge_maps(base_table, overlay_table);
            }
            _ => {
                base.insert(key.clone(), value.clone());
            }
        }
    }
}

fn collect_keys(map: &HashMap<String, ConfigValue>, prefix: &str) -> Vec<String> {
    let mut keys = Vec::new();
    for (key, value) in map {
        let full_key = if prefix.is_empty() {
            key.clone()
        } else {
            format!("{}.{}", prefix, key)
        };
        match value {
            ConfigValue::Table(table) => {
                keys.extend(collect_keys(table, &full_key));
            }
            _ => {
                keys.push(full_key);
            }
        }
    }
    keys
}

// --- Parser for simple key=value config format ---

fn parse_config_content(content: &str, path: &Path) -> Result<Config, ConfigError> {
    let mut values = HashMap::new();
    let mut current_section = String::new();

    for (line_num, line) in content.lines().enumerate() {
        let trimmed = line.trim();

        // Skip empty lines and comments
        if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with(';') {
            continue;
        }

        // Section header [section.name]
        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            current_section = trimmed[1..trimmed.len() - 1].trim().to_string();
            continue;
        }

        // Key = value
        if let Some(eq_pos) = trimmed.find('=') {
            let key = trimmed[..eq_pos].trim().to_string();
            let raw_value = trimmed[eq_pos + 1..].trim().to_string();

            if key.is_empty() {
                return Err(ConfigError::ParseError {
                    path: path.to_path_buf(),
                    message: format!("Empty key on line {}", line_num + 1),
                });
            }

            let value = parse_value(&raw_value);

            if current_section.is_empty() {
                values.insert(key, value);
            } else {
                // Insert into nested table
                let parts: Vec<&str> = current_section.split('.').collect();
                let mut current = &mut values;

                for part in &parts {
                    current = current
                        .entry(part.to_string())
                        .or_insert_with(|| ConfigValue::Table(HashMap::new()))
                        .as_table_mut();
                }
                current.insert(key, value);
            }
        } else {
            return Err(ConfigError::ParseError {
                path: path.to_path_buf(),
                message: format!("Invalid syntax on line {}: '{}'", line_num + 1, trimmed),
            });
        }
    }

    Ok(Config {
        values,
        source_path: Some(path.to_path_buf()),
    })
}

fn parse_value(raw: &str) -> ConfigValue {
    // Remove inline comments
    let value = if let Some(pos) = raw.find(" #") {
        raw[..pos].trim()
    } else {
        raw
    };

    // Boolean
    match value.to_lowercase().as_str() {
        "true" | "yes" | "on" => return ConfigValue::Boolean(true),
        "false" | "no" | "off" => return ConfigValue::Boolean(false),
        _ => {}
    }

    // Integer
    if let Ok(i) = value.parse::<i64>() {
        return ConfigValue::Integer(i);
    }

    // Float
    if let Ok(f) = value.parse::<f64>() {
        return ConfigValue::Float(f);
    }

    // Quoted string - remove quotes
    if (value.starts_with('"') && value.ends_with('"'))
        || (value.starts_with('\'') && value.ends_with('\''))
    {
        return ConfigValue::String(value[1..value.len() - 1].to_string());
    }

    // Comma-separated list
    if value.contains(',') {
        let items: Vec<ConfigValue> = value
            .split(',')
            .map(|s| parse_value(s.trim()))
            .collect();
        return ConfigValue::List(items);
    }

    ConfigValue::String(value.to_string())
}

// --- Validation ---

pub struct ConfigValidator {
    required_keys: Vec<String>,
    custom_rules: Vec<Box<dyn Fn(&Config) -> Result<(), String>>>,
}

impl ConfigValidator {
    pub fn new() -> Self {
        Self {
            required_keys: Vec::new(),
            custom_rules: Vec::new(),
        }
    }

    pub fn require_key(mut self, key: &str) -> Self {
        self.required_keys.push(key.to_string());
        self
    }

    pub fn add_rule<F>(mut self, rule: F) -> Self
    where
        F: Fn(&Config) -> Result<(), String> + 'static,
    {
        self.custom_rules.push(Box::new(rule));
        self
    }

    pub fn validate(&self, config: &Config) -> Result<(), ConfigError> {
        let mut errors = Vec::new();

        for key in &self.required_keys {
            if config.get(key).is_none() {
                errors.push(format!("Missing required key: '{}'", key));
            }
        }

        for rule in &self.custom_rules {
            if let Err(msg) = rule(config) {
                errors.push(msg);
            }
        }

        if errors.is_empty() {
            Ok(())
        } else {
            Err(ConfigError::ValidationError(errors))
        }
    }
}

