# Incremental Backup Migration Helper in JavaScript

This example provides a full-featured migration helper that tracks file changes via checksums and timestamps, backs up only what's changed, and supports rollback.

```javascript
import { createHash } from "node:crypto";
import { EventEmitter } from "node:events";
import fs from "node:fs/promises";
import path from "node:path";

// ─── Manifest: tracks state between backup runs ──────────────────────────

class BackupManifest {
  #manifestPath;
  #data;

  constructor(manifestPath) {
    this.#manifestPath = manifestPath;
    this.#data = {
      version: 1,
      lastBackupTimestamp: null,
      lastBackupId: null,
      entries: {},       // relative path → { checksum, size, mtime, backupId }
      backupHistory: [], // ordered list of { id, timestamp, fileCount, totalSize }
    };
  }

  get lastBackupTimestamp() {
    return this.#data.lastBackupTimestamp;
  }

  get lastBackupId() {
    return this.#data.lastBackupId;
  }

  get entries() {
    return { ...this.#data.entries };
  }

  get history() {
    return [...this.#data.backupHistory];
  }

  // Load existing manifest from disk
  async load() {
    try {
      const raw = await fs.readFile(this.#manifestPath, "utf-8");
      this.#data = JSON.parse(raw);
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
      // First run — no manifest yet
    }
  }

  // Persist manifest to disk
  async save() {
    const dir = path.dirname(this.#manifestPath);
    await fs.mkdir(dir, { recursive: true });
    await fs.writeFile(
      this.#manifestPath,
      JSON.stringify(this.#data, null, 2),
      "utf-8"
    );
  }

  // Check whether a file needs to be backed up
  needsBackup(relativePath, checksum, size) {
    const existing = this.#data.entries[relativePath];
    if (!existing) return true;                    // new file
    if (existing.checksum !== checksum) return true; // content changed
    if (existing.size !== size) return true;        // size changed
    return false;
  }

  // Update an entry after a successful file backup
  updateEntry(relativePath, { checksum, size, mtime, backupId }) {
    this.#data.entries[relativePath] = { checksum, size, mtime, backupId };
  }

  // Mark files that were deleted from the source since the last run
  findDeletedEntries(currentRelativePaths) {
    const currentSet = new Set(currentRelativePaths);
    return Object.keys(this.#data.entries).filter((p) => !currentSet.has(p));
  }

  removeEntry(relativePath) {
    delete this.#data.entries[relativePath];
  }

  // Record a completed backup run
  recordBackup(backupId, fileCount, totalSize) {
    const timestamp = new Date().toISOString();
    this.#data.lastBackupTimestamp = timestamp;
    this.#data.lastBackupId = backupId;
    this.#data.backupHistory.push({ id: backupId, timestamp, fileCount, totalSize });
  }
}

// ─── Core incremental backup helper ──────────────────────────────────────

class IncrementalBackupHelper extends EventEmitter {
  #sourceDir;
  #backupDir;
  #manifest;
  #excludePatterns;

  /**
   * @param {object} options
   * @param {string} options.sourceDir      – directory to back up
   * @param {string} options.backupDir      – root directory for backup storage
   * @param {string[]} [options.exclude]    – glob-style substrings to skip
   */
  constructor({ sourceDir, backupDir, exclude = [] }) {
    super();
    this.#sourceDir = path.resolve(sourceDir);
    this.#backupDir = path.resolve(backupDir);
    this.#excludePatterns = exclude;
    this.#manifest = new BackupManifest(
      path.join(this.#backupDir, "manifest.json")
    );
  }

  // ── Public API ────────────────────────────────────────────────────────

  /** Run an incremental backup and return a summary. */
  async run() {
    await this.#manifest.load();

    const backupId = this.#generateBackupId();
    const backupSubDir = path.join(this.#backupDir, "snapshots", backupId);
    await fs.mkdir(backupSubDir, { recursive: true });

    this.emit("start", { backupId, sourceDir: this.#sourceDir });

    // 1. Scan source directory
    const sourceFiles = await this.#scanDirectory(this.#sourceDir);
    this.emit("scanned", { fileCount: sourceFiles.length });

    // 2. Determine which files changed
    const changeset = await this.#buildChangeset(sourceFiles);
    this.emit("changeset", {
      added: changeset.added.length,
      modified: changeset.modified.length,
      deleted: changeset.deleted.length,
      unchanged: changeset.unchanged.length,
    });

    // 3. Copy changed files into the snapshot directory
    let totalSize = 0;
    const backedUp = [...changeset.added, ...changeset.modified];

    for (const file of backedUp) {
      await this.#backupFile(file, backupSubDir, backupId);
      totalSize += file.size;
      this.emit("file-backed-up", { path: file.relativePath, size: file.size });
    }

    // 4. Handle deletions (record them so restore knows)
    for (const relPath of changeset.deleted) {
      this.#manifest.removeEntry(relPath);
      this.emit("file-deleted", { path: relPath });
    }

    // 5. Write deletion log into snapshot for traceability
    if (changeset.deleted.length > 0) {
      await fs.writeFile(
        path.join(backupSubDir, "_deleted.json"),
        JSON.stringify(changeset.deleted, null, 2),
        "utf-8"
      );
    }

    // 6. Update & persist manifest
    this.#manifest.recordBackup(backupId, backedUp.length, totalSize);
    await this.#manifest.save();

    const summary = {
      backupId,
      added: changeset.added.length,
      modified: changeset.modified.length,
      deleted: changeset.deleted.length,
      unchanged: changeset.unchanged.length,
      totalSize,
      snapshotPath: backupSubDir,
    };

    this.emit("complete", summary);
    return summary;
  }

  /** Restore from a specific backup (or latest). */
  async restore(targetDir, backupId = null) {
    await this.#manifest.load();

    const resolvedId = backupId ?? this.#manifest.lastBackupId;
    if (!resolvedId) {
      throw new Error("No backup found to restore from.");
    }

    targetDir = path.resolve(targetDir);
    await fs.mkdir(targetDir, { recursive: true });

    this.emit("restore-start", { backupId: resolvedId, targetDir });

    // Walk backwards through history to reconstruct latest version of each file
    const fileMap = await this.#buildRestoreMap(resolvedId);

    let restoredCount = 0;
    for (const [relativePath, snapshotSource] of fileMap) {
      const dest = path.join(targetDir, relativePath);
      await fs.mkdir(path.dirname(dest), { recursive: true });
      await fs.copyFile(snapshotSource, dest);
      restoredCount++;
      this.emit("file-restored", { path: relativePath });
    }

    this.emit("restore-complete", { restoredCount });
    return { restoredCount, backupId: resolvedId };
  }

  /** List all available backup snapshots. */
  async listBackups() {
    await this.#manifest.load();
    return this.#manifest.history;
  }

  /** Show what *would* be backed up without writing anything. */
  async dryRun() {
    await this.#manifest.load();
    const sourceFiles = await this.#scanDirectory(this.#sourceDir);
    return this.#buildChangeset(sourceFiles);
  }

  // ── Private helpers ───────────────────────────────────────────────────

  #generateBackupId() {
    const now = new Date();
    const pad = (n, len = 2) => String(n).padStart(len, "0");
    return [
      now.getFullYear(),
      pad(now.getMonth() + 1),
      pad(now.getDate()),
      "_",
      pad(now.getHours()),
      pad(now.getMinutes()),
      pad(now.getSeconds()),
      "_",
      Math.random().toString(36).slice(2, 8),
    ].join("");
  }

  /** Recursively list all files under `dir`, returning metadata. */
  async #scanDirectory(dir, base = dir) {
    const results = [];
    const dirents = await fs.readdir(dir, { withFileTypes: true });

    for (const dirent of dirents) {
      const fullPath = path.join(dir, dirent.name);
      const relativePath = path.relative(base, fullPath);

      // Skip excluded paths
      if (this.#isExcluded(relativePath)) continue;

      if (dirent.isDirectory()) {
        const nested = await this.#scanDirectory(fullPath, base);
        results.push(...nested);
      } else if (dirent.isFile()) {
        const stat = await fs.stat(fullPath);
        const checksum = await this.#checksumFile(fullPath);
        results.push({
          fullPath,
          relativePath,
          size: stat.size,
          mtime: stat.mtime.toISOString(),
          checksum,
        });
      }
    }

    return results;
  }

  #isExcluded(relativePath) {
    return this.#excludePatterns.some((pattern) =>
      relativePath.includes(pattern)
    );
  }

  /** SHA-256 checksum streamed in chunks for memory efficiency. */
  async #checksumFile(filePath) {
    const fileHandle = await fs.open(filePath, "r");
    const hash = createHash("sha256");
    const CHUNK = 64 * 1024;
    const buffer = Buffer.alloc(CHUNK);

    try {
      let bytesRead;
      let position = 0;
      do {
        ({ bytesRead } = await fileHandle.read(buffer, 0, CHUNK, position));
        if (bytesRead > 0) {
          hash.update(buffer.subarray(0, bytesRead));
          position += bytesRead;
        }
      } while (bytesRead > 0);
    } finally {
      await fileHandle.close();
    }

    return hash.digest("hex");
  }

  /** Compare source files against the manifest to classify changes. */
  async #buildChangeset(sourceFiles) {
    const added = [];
    const modified = [];
    const unchanged = [];

    const currentPaths = [];

    for (const file of sourceFiles) {
      currentPaths.push(file.relativePath);

      if (this.#manifest.needsBackup(file.relativePath, file.checksum, file.size)) {
        // Distinguish new vs. modified
        const existing = this.#manifest.entries[file.relativePath];
        if (existing) {
          modified.push(file);
        } else {
          added.push(file);
        }
      } else {
        unchanged.push(file);
      }
    }

    const deleted = this.#manifest.findDeletedEntries(currentPaths);

    return { added, modified, unchanged, deleted };
  }

  /** Copy a single file into the snapshot directory & update the manifest. */
  async #backupFile(file, snapshotDir, backupId) {
    const dest = path.join(snapshotDir, file.relativePath);
    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.copyFile(file.fullPath, dest);

    this.#manifest.updateEntry(file.relativePath, {
      checksum: file.checksum,
      size: file.size,
      mtime: file.mtime,
      backupId,
    });
  }

  /**
   * Walk snapshot history in reverse to find the most recent copy
   * of every file that exists up to `targetBackupId`.
   */
  async #buildRestoreMap(targetBackupId) {
    const history = this.#manifest.history;
    const targetIdx = history.findIndex((h) => h.id === targetBackupId);
    if (targetIdx === -1) {
      throw new Error(`Backup ID "${targetBackupId}" not found in history.`);
    }

    // Only consider snapshots up to (and including) the target
    const relevantHistory = history.slice(0, targetIdx + 1);
    const fileMap = new Map(); // relativePath → absolute path in snapshot dir

    // Accumulate deleted files so we skip them
    const deletedFiles = new Set();

    for (const entry of relevantHistory) {
      const snapshotDir = path.join(this.#backupDir, "snapshots", entry.id);

      // Track deletions
      const deletedLogPath = path.join(snapshotDir, "_deleted.json");
      try {
        const raw = await fs.readFile(deletedLogPath, "utf-8");
        for (const p of JSON.parse(raw)) {
          deletedFiles.add(p);
          fileMap.delete(p);
        }
      } catch {
        // no deletions in this snapshot
      }

      // Scan backed-up files in this snapshot
      const files = await this.#scanSnapshotDir(snapshotDir);
      for (const { relativePath, fullPath } of files) {
        if (!deletedFiles.has(relativePath)) {
          fileMap.set(relativePath, fullPath);
        }
      }
    }

    return fileMap;
  }

  /** Simple recursive scan of a snapshot directory (skips meta files). */
  async #scanSnapshotDir(dir, base = dir) {
    const results = [];
    let dirents;
    try {
      dirents = await fs.readdir(dir, { withFileTypes: true });
    } catch {
      return results;
    }

    for (const d of dirents) {
      if (d.name.startsWith("_")) continue; // skip _deleted.json etc.
      const full = path.join(dir, d.name);
      const rel = path.relative(base, full);

      if (d.isDirectory()) {
        results.push(...(await this.#scanSnapshotDir(full, base)));
      } else if (d.isFile()) {
        results.push({ relativePath: rel, fullPath: full });
      }
    }

    return results;
  }
}

// ─── Usage example ───────────────────────────────────────────────────────

