## Identified Bugs Summary

| # | Bug | Location | Type |
|---|-----|----------|------|
| 1 | No null/default check on `config` | `constructor` | Null reference |
| 2 | `rules` could be undefined before `.includes()` | `lint()` | TypeError |
| 3 | `i <= words.length` → off-by-one | `no-banned-words` loop | Logic error |
| 4 | Case-sensitive banned word check | `no-banned-words` | Logic error |
| 5 | Spam detection not user-scoped | `isSpam()` | Logic error |
| 6 | Violation count overwrites prior count | `trackViolation()` | Logic error |
| 7 | `==` instead of `===` | `lint()` return | Best practice |
| 8 | Caps ratio calculated on raw `text` | `getCapsRatio()` | Logic error |
| 9 | `lastMessage` not per-user | `isSpam()` | State error |
| 10 | Same as #6 | `trackViolation()` | Logic error |
| 11 | `warningThreshold` may be undefined | `determineAction()` | Null reference |
| 12 | URL regex too simple | `containsLink()` | Incomplete regex |

## ✅ The Fixed Code

```javascript
class ChatModerationLinter {
  constructor(config = {}) {
    // Fix 1 & 2: Default values for all config properties
    this.rules = config.rules || [];
    this.maxMessageLength = config.maxLength || 500;
    this.warningThreshold = config.warningThreshold || 3;   // Fix 11
    this.bannedWords = (config.bannedWords || []).map(      // Fix 4: normalize
      (w) => w.toLowerCase()
    );
    this.userViolations = {};
    this.userLastMessages = {};  // Fix 5 & 9: Per-user tracking
  }

  /**
   * Analyze a chat message and return violations.
   * @param {{ userId: string, text: string, timestamp: number }} message
   * @returns {{ passed: boolean, violations: Array, action: string }}
   */
  lint(message) {
    if (!message || typeof message.text !== "string") {
      throw new Error("Invalid message object");
    }

    const violations = [];

    // Rule: Check message length
    if (this.rules.includes("max-length")) {
      if (message.text.length > this.maxMessageLength) {
        violations.push({
          rule: "max-length",
          severity: "warning",
          detail: `Message exceeds ${this.maxMessageLength} chars `
                + `(got ${message.text.length})`,
        });
      }
    }

    // Rule: Check banned words
    if (this.rules.includes("no-banned-words")) {
      // Fix 4: Normalize and use a proper word boundary split
      const words = message.text.toLowerCase().split(/\s+/);
      // Fix 3: Use `<` instead of `<=`
      for (let i = 0; i < words.length; i++) {
        const cleanWord = words[i].replace(/[^a-z0-9]/g, "");
        if (this.bannedWords.includes(cleanWord)) {
          violations.push({
            rule: "no-banned-words",
            severity: "error",
            detail: `Banned word detected: "${cleanWord}"`,
          });
        }
      }
    }

    // Rule: No excessive caps
    if (this.rules.includes("no-caps-abuse")) {
      const capsRatio = this.getCapsRatio(message.text);
      if (capsRatio > 0.7 && message.text.length > 5) {
        violations.push({
          rule: "no-caps-abuse",
          severity: "warning",
          detail: `Caps ratio: ${(capsRatio * 100).toFixed(1)}%`,
        });
      }
    }

    // Rule: No spam (repeated messages per user)
    if (this.rules.includes("no-spam")) {
      if (this.isSpam(message)) {
        violations.push({
          rule: "no-spam",
          severity: "error",
          detail: "Repeated message detected",
        });
      }
    }

    // Rule: No links
    if (this.rules.includes("no-links")) {
      if (this.containsLink(message.text)) {
        violations.push({
          rule: "no-links",
          severity: "warning",
          detail: "Links are not allowed",
        });
      }
    }

    // Track violations per user
    this.trackViolation(message.userId, violations);

    return {
      passed: violations.length === 0,   // Fix 7: Strict equality
      violations,
      action: this.determineAction(message.userId),
    };
  }

  // Fix 8: Compute caps ratio correctly using `letters` only
  getCapsRatio(text) {
    const letters = text.replace(/[^a-zA-Z]/g, "");
    if (letters.length === 0) return 0;
    const caps = letters.replace(/[^A-Z]/g, "");
    return caps.length / letters.length;
  }

  // Fix 5 & 9: Track last message per user ID
  isSpam(message) {
    const { userId, text } = message;
    const lastMsg = this.userLastMessages[userId];

    const isRepeat = lastMsg && lastMsg.text === text;

    // Update stored message
    this.userLastMessages[userId] = {
      text,
      timestamp: Date.now(),
    };

    return isRepeat;
  }

  // Fix 6 & 10: Accumulate instead of overwrite
  trackViolation(userId, violations) {
    if (violations.length > 0) {
      this.userViolations[userId] =
        (this.userViolations[userId] || 0) + violations.length;
    }
  }

  determineAction(userId) {
    const count = this.userViolations[userId] || 0;
    if (count >= 10) return "ban";
    if (count >= 5) return "mute";
    if (count >= this.warningThreshold) return "warn";
    return "none";
  }

  // Fix 12: Robust URL regex
  containsLink(text) {
    const urlRegex =
      /https?:\/\/[^\s]+|www\.[^\s]+|[a-zA-Z0-9-]+\.(com|net|org|io|gg|xyz|co)\b/gi;
    return urlRegex.test(text);
  }

  // Utility: Reset a user's violation record (e.g., after cooldown)
  resetUser(userId) {
    delete this.userViolations[userId];
    delete this.userLastMessages[userId];
  }
}
