      expectPass: false,
      expectRule: "no-links",
    },
    {
      name: "Spam detected (repeat message)",
      message: { userId: "u6", text: "Buy now! Buy now!" },
      expectPass: true, // First time → not spam yet
    },
  ];

  let passed = 0;
  tests.forEach((t) => {
    const result = linter.lint(t.message);
    const ok = result.passed === t.expectPass;
    const ruleOk =
      !t.expectRule ||
      result.violations.some((v) => v.rule === t.expectRule);

    if (ok && ruleOk) {
      console.log(`  ✅ ${t.name}`);
      passed++;
    } else {
      console.error(`  ❌ ${t.name}`, result);
    }
  });

  // Spam detection — second identical message from same user
  const spamResult = linter.lint({ userId: "u6", text: "Buy now! Buy now!" });
  if (!spamResult.passed && spamResult.violations.some((v) => v.rule === "no-spam")) {
    console.log("  ✅ Spam detected on repeat");
    passed++;
  } else {
    console.error("  ❌ Spam not detected on repeat", spamResult);
  }

  console.log(`\n${passed}/${tests.length + 1} tests passed`);
}

