## Key Takeaways

| Category | What Was Fixed |
|----------|----------------|
| **Null Safety** | Default params, input validation in `lint()` |
| **Off-by-one** | `<=` → `<` in loop bounds |
| **State Mgmt** | Per-user tracking for spam & violations |
| **Accumulation** | `+=` instead of `=` for violation counts |
| **Case Handling** | `.toLowerCase()` on both input and banned list |
| **Regex** | Robust URL pattern covers `https`, `www`, TLDs |
| **Strict Equality** | `===` instead of `==` |

# Background Worker for Metrics Aggregation

## Architecture Overview

```
Producers → MetricsBuffer → Aggregator → Storage/Flush
                ↑                            ↓
            Incoming events         Aggregated snapshots
```

## Full Implementation

```javascript
// ─── metrics-worker.js ─── Main Worker Module ───

/**
 * Represents a single metric data point
 */
class MetricPoint {
  constructor(name, value, tags = {}, timestamp = Date.now()) {
    this.name = name;
    this.value = value;
    this.tags = tags;
    this.timestamp = timestamp;
  }

  /** Generate a unique key for grouping by name + tags */
  get key() {
    const sortedTags = Object.keys(this.tags)
      .sort()
      .map(k => `${k}:${this.tags[k]}`)
      .join(',');
    return `${this.name}|${sortedTags}`;
  }
}

/**
 * Tracks running statistics without storing every value (for memory efficiency).
 * Uses Welford's algorithm for numerically stable variance.
 */
class RunningStats {
  constructor() {
    this.count = 0;
    this.sum = 0;
    this.min = Infinity;
    this.max = -Infinity;
    this.mean = 0;
    this._m2 = 0;              // for variance calculation
    this._sortedValues = [];    // kept only if percentiles needed
    this._trackPercentiles = false;
  }

  enablePercentiles() {
    this._trackPercentiles = true;
    return this;
  }

  /** Ingest a single numeric value */
  push(value) {
    this.count++;
    this.sum += value;
    this.min = Math.min(this.min, value);
    this.max = Math.max(this.max, value);

    // Welford's online algorithm
    const delta = value - this.mean;
    this.mean += delta / this.count;
    const delta2 = value - this.mean;
    this._m2 += delta * delta2;

    if (this._trackPercentiles) {
      this._insertSorted(value);
    }
  }

  get variance() {
    return this.count < 2 ? 0 : this._m2 / (this.count - 1);
  }

  get stddev() {
    return Math.sqrt(this.variance);
  }

  /** Returns the p-th percentile (0–100) */
  percentile(p) {
    if (!this._trackPercentiles || this._sortedValues.length === 0) return null;
    const idx = Math.ceil((p / 100) * this._sortedValues.length) - 1;
    return this._sortedValues[Math.max(0, idx)];
  }

  /** Binary-insert to maintain sorted order */
  _insertSorted(value) {
    let lo = 0, hi = this._sortedValues.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (this._sortedValues[mid] < value) lo = mid + 1;
      else hi = mid;
    }
    this._sortedValues.splice(lo, 0, value);
  }

  /** Export a plain-object snapshot */
  snapshot() {
    const result = {
      count: this.count,
      sum: this.sum,
      min: this.count > 0 ? this.min : null,
      max: this.count > 0 ? this.max : null,
      mean: this.mean,
      stddev: this.stddev,
    };
    if (this._trackPercentiles) {
      result.p50 = this.percentile(50);
      result.p90 = this.percentile(90);
      result.p95 = this.percentile(95);
      result.p99 = this.percentile(99);
    }
    return result;
  }
}

// ─── Ring Buffer for back-pressure handling ───

class RingBuffer {
  constructor(capacity = 10_000) {
    this.capacity = capacity;
    this.buffer = new Array(capacity);
    this.head = 0;
    this.tail = 0;
    this.size = 0;
    this.dropped = 0;
  }

  push(item) {
    if (this.size === this.capacity) {
      this.dropped++;
      return false; // signal back-pressure
    }
    this.buffer[this.tail] = item;
    this.tail = (this.tail + 1) % this.capacity;
    this.size++;
    return true;
  }

  /** Drain up to `max` items into an array */
  drain(max = this.size) {
    const count = Math.min(max, this.size);
    const items = new Array(count);
    for (let i = 0; i < count; i++) {
      items[i] = this.buffer[this.head];
      this.buffer[this.head] = undefined; // allow GC
      this.head = (this.head + 1) % this.capacity;
    }
    this.size -= count;
    return items;
  }
}

// ─── Core Aggregation Worker ───

class MetricsAggregatorWorker {
  /**
   * @param {Object} options
   * @param {number} options.flushIntervalMs  – how often to flush (default 10s)
   * @param {number} options.bufferCapacity   – ring buffer size
   * @param {number} options.batchSize        – max points processed per tick
   * @param {Function} options.onFlush        – callback receiving aggregated data
   * @param {Function} options.onError        – error handler
   * @param {string[]} options.percentileMetrics – metric names needing percentiles
   */
  constructor(options = {}) {
    this.flushIntervalMs = options.flushIntervalMs ?? 10_000;
    this.batchSize = options.batchSize ?? 1_000;
    this.onFlush = options.onFlush ?? this._defaultFlush;
    this.onError = options.onError ?? console.error;
    this.percentileMetrics = new Set(options.percentileMetrics ?? []);

    // Internal state
    this.buffer = new RingBuffer(options.bufferCapacity ?? 50_000);
    this.buckets = new Map();          // key → RunningStats
    this.metricMeta = new Map();       // key → { name, tags }
    this.currentWindow = Date.now();

    // Lifecycle
    this._flushTimer = null;
    this._processTimer = null;
    this._running = false;

    // Internal metrics about the worker itself
    this._stats = {
      totalIngested: 0,
      totalDropped: 0,
      totalFlushed: 0,
      flushCount: 0,
      lastFlushMs: 0,
      errors: 0,
    };
  }

  // ─── Lifecycle ───

  start() {
    if (this._running) return;
    this._running = true;
    this.currentWindow = Date.now();

    // Process buffered points on a tight interval
    this._processTimer = setInterval(() => this._processBatch(), 50);

    // Flush aggregated results on the configured interval
    this._flushTimer = setInterval(() => this._flush(), this.flushIntervalMs);

    console.log(
      `[MetricsWorker] Started — flush every ${this.flushIntervalMs}ms`
    );
  }

  async stop() {
    if (!this._running) return;
    this._running = false;

    clearInterval(this._processTimer);
    clearInterval(this._flushTimer);

    // Drain remaining data
    this._processBatch(Infinity);
    await this._flush();

    console.log('[MetricsWorker] Stopped — final flush complete');
  }

  // ─── Public Ingestion API ───

  /**
   * Record a metric. Safe to call at high throughput.
   * @param {string} name
   * @param {number} value
   * @param {Object}  tags
   */
  record(name, value, tags = {}) {
    const point = new MetricPoint(name, value, tags);
    const accepted = this.buffer.push(point);

    if (!accepted) {
      this._stats.totalDropped++;
    } else {
      this._stats.totalIngested++;
    }
  }

  /** Convenience: record a counter increment */
  increment(name, tags = {}, delta = 1) {
    this.record(name, delta, { ...tags, _type: 'counter' });
  }

  /** Convenience: record a timing measurement */
  timing(name, durationMs, tags = {}) {
    this.record(name, durationMs, { ...tags, _type: 'timing' });
  }

  /** Convenience: record a gauge value */
  gauge(name, value, tags = {}) {
    this.record(name, value, { ...tags, _type: 'gauge' });
  }

  /** Convenience: measure an async function's duration */
  async measure(name, fn, tags = {}) {
    const start = performance.now();
    try {
      return await fn();
    } finally {
      this.timing(name, performance.now() - start, tags);
    }
  }

  // ─── Internal Processing ───

  _processBatch(limit = this.batchSize) {
    const points = this.buffer.drain(limit);

    for (const point of points) {
      const key = point.key;

      if (!this.buckets.has(key)) {
        const stats = new RunningStats();
        if (this.percentileMetrics.has(point.name)) {
          stats.enablePercentiles();
        }
        this.buckets.set(key, stats);
        this.metricMeta.set(key, { name: point.name, tags: point.tags });
      }

      this.buckets.get(key).push(point.value);
    }
  }

  async _flush() {
    const flushStart = performance.now();
    const windowStart = this.currentWindow;
    const windowEnd = Date.now();

    // Swap buckets so new data goes into a fresh map
    const buckets = this.buckets;
    const meta = this.metricMeta;
    this.buckets = new Map();
    this.metricMeta = new Map();
    this.currentWindow = windowEnd;

    if (buckets.size === 0) return;

    // Build aggregated payload
    const aggregated = [];
    for (const [key, stats] of buckets) {
      const { name, tags } = meta.get(key);
      aggregated.push({
        name,
        tags,
        window: { start: windowStart, end: windowEnd },
        stats: stats.snapshot(),
      });
    }

    // Append internal worker health metrics
    aggregated.push({
      name: '_worker.health',
      tags: {},
      window: { start: windowStart, end: windowEnd },
      stats: {
        ingested: this._stats.totalIngested,
        dropped: this._stats.totalDropped,
        flushed: this._stats.totalFlushed,
        bufferUsage: this.buffer.size,
        bufferDropped: this.buffer.dropped,
        flushCount: this._stats.flushCount,
      },
    });

    // Deliver
    try {
      await this.onFlush(aggregated);
      this._stats.totalFlushed += aggregated.length;
      this._stats.flushCount++;
    } catch (err) {
      this._stats.errors++;
      this.onError(err);
    }

    this._stats.lastFlushMs = performance.now() - flushStart;
  }

  _defaultFlush(data) {
    console.log(`[MetricsWorker] Flushed ${data.length} aggregated metrics`);
    console.table(
      data.map(d => ({
        name: d.name,
        count: d.stats.count ?? '—',
        mean: d.stats.mean?.toFixed(2) ?? '—',
        p99: d.stats.p99?.toFixed(2) ?? '—',
      }))
    );
  }

  /** Expose internal health for monitoring */
  health() {
    return { ...this._stats, bufferSize: this.buffer.size };
  }
}

// ─── Flush Adapters (plug into onFlush) ───

/** POST aggregated metrics to an HTTP endpoint */
function httpFlushAdapter(endpoint, headers = {}) {
  return async function flush(metrics) {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...headers },
      body: JSON.stringify({ metrics, flushedAt: new Date().toISOString() }),
    });
    if (!response.ok) {
      throw new Error(`Flush failed: ${response.status} ${response.statusText}`);
    }
  };
}

/** Write metrics into a console-friendly format */
function consoleFlushAdapter(verbose = false) {
  return async function flush(metrics) {
    const ts = new Date().toISOString();
    for (const m of metrics) {
      if (m.name.startsWith('_worker')) continue; // skip internal
      const tagStr = Object.entries(m.tags)
        .filter(([k]) => !k.startsWith('_'))
        .map(([k, v]) => `${k}=${v}`)
        .join(' ');
      const s = m.stats;
      console.log(
        `[${ts}] ${m.name} {${tagStr}} ` +
        `count=${s.count} mean=${s.mean?.toFixed(2)} ` +
        `min=${s.min?.toFixed(2)} max=${s.max?.toFixed(2)}` +
        (s.p99 != null ? ` p99=${s.p99.toFixed(2)}` : '')
      );
      if (verbose) console.log('  ', JSON.stringify(s));
    }
  };
}

// ─── Export ───

module.exports = {
  MetricPoint,
  RunningStats,
  RingBuffer,
  MetricsAggregatorWorker,
  httpFlushAdapter,
  consoleFlushAdapter,
};
