# Simple Log Ingestion with Retry Logic in JavaScript

## Implementation

```javascript
class LogIngester {
  constructor(options = {}) {
    this.endpoint = options.endpoint || "http://localhost:3000/logs";
    this.maxRetries = options.maxRetries || 3;
    this.baseDelay = options.baseDelay || 1000;      // 1 second
    this.maxDelay = options.maxDelay || 30000;        // 30 seconds
    this.batchSize = options.batchSize || 10;
    this.flushInterval = options.flushInterval || 5000; // 5 seconds

    this.queue = [];
    this.deadLetterQueue = [];
    this.isFlushing = false;

    // Start periodic flush
    this.timer = setInterval(() => this.flush(), this.flushInterval);
  }

  // ─── Public API ──────────────────────────────────────────

  /** Add a single log entry to the queue */
  log(level, message, metadata = {}) {
    const entry = {
      timestamp: new Date().toISOString(),
      level,
      message,
      metadata,
      id: this._generateId(),
    };

    this.queue.push(entry);
    console.log(`[Queue] Added log (queue size: ${this.queue.length})`);

    // Auto-flush when batch size is reached
    if (this.queue.length >= this.batchSize) {
      this.flush();
    }
  }

  info(message, metadata)  { this.log("INFO", message, metadata); }
  warn(message, metadata)  { this.log("WARN", message, metadata); }
  error(message, metadata) { this.log("ERROR", message, metadata); }
  debug(message, metadata) { this.log("DEBUG", message, metadata); }

  /** Flush the current queue */
  async flush() {
    if (this.isFlushing || this.queue.length === 0) return;

    this.isFlushing = true;

    // Take a batch from the queue
    const batch = this.queue.splice(0, this.batchSize);
    console.log(`[Flush] Sending batch of ${batch.length} logs...`);

    try {
      await this._sendWithRetry(batch);
      console.log(`[Flush] Batch sent successfully`);
    } catch (err) {
      console.error(`[Flush] Batch failed after all retries: ${err.message}`);
      this.deadLetterQueue.push(...batch);
      console.error(`[DLQ] ${this.deadLetterQueue.length} logs in dead-letter queue`);
    }

    this.isFlushing = false;

    // If more logs are waiting, flush again
    if (this.queue.length >= this.batchSize) {
      this.flush();
    }
  }

  /** Stop the ingester and flush remaining logs */
  async shutdown() {
    clearInterval(this.timer);
    console.log("[Shutdown] Flushing remaining logs...");
    while (this.queue.length > 0) {
      await this.flush();
    }
    console.log("[Shutdown] Complete");
  }

  // ─── Retry Logic ────────────────────────────────────────

  /**
   * Sends a batch with exponential backoff retry.
   *
   *  Attempt 1 → delay 1s (+ jitter)
   *  Attempt 2 → delay 2s (+ jitter)
   *  Attempt 3 → delay 4s (+ jitter)
   */
  async _sendWithRetry(batch, attempt = 0) {
    try {
      await this._send(batch);
    } catch (err) {
      if (attempt >= this.maxRetries) {
        throw new Error(
          `Failed after ${this.maxRetries} retries: ${err.message}`
        );
      }

      const delay = this._calculateDelay(attempt);
      console.warn(
        `[Retry] Attempt ${attempt + 1}/${this.maxRetries} ` +
        `failed (${err.message}). Retrying in ${delay}ms...`
      );

      await this._sleep(delay);
      return this._sendWithRetry(batch, attempt + 1);
    }
  }

  /** Calculate delay with exponential backoff + jitter */
  _calculateDelay(attempt) {
    const exponential = this.baseDelay * Math.pow(2, attempt);
    const jitter = Math.random() * this.baseDelay;
    return Math.min(exponential + jitter, this.maxDelay);
  }

  // ─── Network Layer ──────────────────────────────────────

  /** Send the batch to the ingestion endpoint */
  async _send(batch) {
    const response = await fetch(this.endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ logs: batch }),
    });

    if (!response.ok) {
      const isRetryable = response.status >= 500 || response.status === 429;

      const error = new Error(`HTTP ${response.status}: ${response.statusText}`);
      error.retryable = isRetryable;

      // Don't retry client errors (4xx except 429)
      if (!isRetryable) {
        throw new Error(`Non-retryable error: ${error.message}`);
      }

      throw error;
    }

    return response.json();
  }

  // ─── Helpers ─────────────────────────────────────────────

  _sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  _generateId() {
    return `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  }
}
