class CSVParser {
  /**
   * @param {object} options
   * @param {string} options.delimiter - Column separator (default: ',')
   * @param {string} options.quote - Quote character (default: '"')
   * @param {boolean} options.hasHeader - First row is header (default: true)
   * @param {string} options.lineBreak - Line terminator (default: '\n')
   */
  constructor(options = {}) {
    this.delimiter = options.delimiter ?? ",";
    this.quote = options.quote ?? '"';
    this.hasHeader = options.hasHeader ?? true;
    this.lineBreak = options.lineBreak ?? "\n";
  }

  /**
   * Parse a raw CSV string into an array of objects or arrays.
   * Handles quoted fields, embedded delimiters, and escaped quotes.
   */
  parse(csvString) {
    const rows = this.#tokenize(csvString);

    if (rows.length === 0) return { headers: [], rows: [] };

    if (this.hasHeader) {
      const headers = rows[0].map((h) => h.trim());
      const dataRows = rows.slice(1).map((row) => this.#rowToObject(headers, row));
      return { headers, rows: dataRows };
    }

    return { headers: [], rows };
  }

  /**
   * Tokenize CSV respecting quoted fields.
   * This is a state-machine approach for correctness.
   */
  #tokenize(input) {
    const rows = [];
    let currentRow = [];
    let currentField = "";
    let insideQuotes = false;
    let i = 0;

    while (i < input.length) {
      const char = input[i];

      if (insideQuotes) {
        // Escaped quote (double quote inside quoted field)
        if (char === this.quote && input[i + 1] === this.quote) {
          currentField += this.quote;
          i += 2;
          continue;
        }

        // Closing quote
        if (char === this.quote) {
          insideQuotes = false;
          i++;
          continue;
        }

        // Any character inside quotes (including delimiters and newlines)
        currentField += char;
        i++;
        continue;
      }

      // Opening quote (must be at start of field)
      if (char === this.quote) {
        insideQuotes = true;
        i++;
        continue;
      }

      // Field separator
      if (char === this.delimiter) {
        currentRow.push(currentField);
        currentField = "";
        i++;
        continue;
      }

      // Row separator — handle \r\n and \n
      if (char === "\n" || char === "\r") {
        currentRow.push(currentField);
        currentField = "";

        if (currentRow.some((field) => field.trim() !== "") || currentRow.length > 1) {
          rows.push(currentRow);
        }

        currentRow = [];

        // Skip \r\n pair
        if (char === "\r" && input[i + 1] === "\n") {
          i += 2;
        } else {
          i++;
        }
        continue;
      }

      currentField += char;
      i++;
    }

    // Push the last field and row
    if (currentField || currentRow.length > 0) {
      currentRow.push(currentField);
      if (currentRow.some((field) => field.trim() !== "") || currentRow.length > 1) {
        rows.push(currentRow);
      }
    }

    return rows;
  }

  /**
   * Map a row array to a keyed object using headers.
   */
  #rowToObject(headers, row) {
    const obj = {};
    headers.forEach((header, index) => {
      obj[header] = index < row.length ? row[index].trim() : null;
    });
    return obj;
  }

  /**
   * Serialize an array of objects back to CSV.
   */
  serialize(headers, rows) {
    const escapeField = (field) => {
      if (field === null || field === undefined) return "";
      const str = String(field);
      if (
        str.includes(this.delimiter) ||
        str.includes(this.quote) ||
        str.includes("\n")
      ) {
        return `${this.quote}${str.replace(
          new RegExp(this.quote, "g"),
          this.quote + this.quote
        )}${this.quote}`;
      }
      return str;
    };

    const lines = [headers.map(escapeField).join(this.delimiter)];

    for (const row of rows) {
      const line = headers.map((h) => escapeField(row[h])).join(this.delimiter);
      lines.push(line);
    }

    return lines.join(this.lineBreak);
  }
}

module.exports = CSVParser;
