## Validators

```javascript
// src/validators.js

const validators = {
  required(value, fieldName) {
    if (value === null || value === undefined || String(value).trim() === "") {
      return `${fieldName} is required`;
    }
    return null;
  },

  email(value, fieldName) {
    if (!value) return null; // skip empty — use `required` to catch that
    const pattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!pattern.test(value)) {
      return `${fieldName} has invalid email: "${value}"`;
    }
    return null;
  },

  numeric(value, fieldName) {
    if (!value) return null;
    if (isNaN(Number(value))) {
      return `${fieldName} must be numeric: "${value}"`;
    }
    return null;
  },

  oneOf(allowedValues) {
    return (value, fieldName) => {
      if (!value) return null;
      if (!allowedValues.includes(value)) {
        return `${fieldName} must be one of [${allowedValues.join(", ")}]: got "${value}"`;
      }
      return null;
    };
  },

  maxLength(max) {
    return (value, fieldName) => {
      if (!value) return null;
      if (String(value).length > max) {
        return `${fieldName} exceeds max length ${max}`;
      }
      return null;
    };
  },

  date(value, fieldName) {
    if (!value) return null;
    const parsed = Date.parse(value);
    if (isNaN(parsed)) {
      return `${fieldName} has invalid date: "${value}"`;
    }
    return null;
  },
};

module.exports = validators;
