## Transformers

```javascript
// src/transformers.js

const transformers = {
  /** Trim whitespace */
  trim: (value) => (typeof value === "string" ? value.trim() : value),

  /** Convert to lowercase */
  lowercase: (value) => (typeof value === "string" ? value.toLowerCase() : value),

  /** Convert to uppercase */
  uppercase: (value) => (typeof value === "string" ? value.toUpperCase() : value),

  /** Parse to integer */
  toInt: (value) => {
    const n = parseInt(value, 10);
    return isNaN(n) ? null : n;
  },

  /** Parse to float */
  toFloat: (value) => {
    const n = parseFloat(value);
    return isNaN(n) ? null : n;
  },

  /** Parse to boolean (handles common CSV representations) */
  toBoolean: (value) => {
    if (!value) return false;
    return ["true", "1", "yes", "y"].includes(String(value).toLowerCase());
  },

  /** Convert date string to ISO format */
  toISODate: (value) => {
    if (!value) return null;
    const d = new Date(value);
    return isNaN(d.getTime()) ? null : d.toISOString();
  },

  /** Provide a default when empty */
  defaultValue(fallback) {
    return (value) =>
      value === null || value === undefined || String(value).trim() === ""
        ? fallback
        : value;
  },

  /** Split a delimited sub-field into an array */
  splitBy(separator) {
    return (value) =>
      typeof value === "string"
        ? value.split(separator).map((s) => s.trim()).filter(Boolean)
        : [];
  },

  /** Rename a field (used in column mapping) */
  rename(newName) {
    return { __rename: newName };
  },
};

module.exports = transformers;
