## Migration Helper (Orchestrator)

```javascript
// src/MigrationHelper.js

const fs = require("fs");
const path = require("path");
const CSVParser = require("./CSVParser");

class MigrationHelper {
  #parser;
  #columnMap;       // { sourceCol: targetCol }
  #transforms;      // { targetCol: [fn, fn, ...] }
  #validationRules; // { targetCol: [fn, fn, ...] }
  #hooks;
  #errors;
  #stats;

  constructor(parserOptions = {}) {
    this.#parser = new CSVParser(parserOptions);
    this.#columnMap = {};
    this.#transforms = {};
    this.#validationRules = {};
    this.#errors = [];
    this.#stats = { total: 0, valid: 0, skipped: 0, transformed: 0 };
    this.#hooks = { beforeRow: null, afterRow: null, onError: null };
  }

  // ─── Configuration API (fluent / chainable) ──────────────

  /**
   * Map source columns to target columns.
   * @param {object} mapping - { sourceColumn: 'targetColumn' }
   */
  mapColumns(mapping) {
    this.#columnMap = { ...this.#columnMap, ...mapping };
    return this;
  }

  /**
   * Add transform functions for a target column.
   * @param {string} targetColumn
   * @param  {...function} fns - Transform functions
   */
  transform(targetColumn, ...fns) {
    if (!this.#transforms[targetColumn]) {
      this.#transforms[targetColumn] = [];
    }
    this.#transforms[targetColumn].push(...fns);
    return this;
  }

  /**
   * Add validation rules for a target column.
   * @param {string} targetColumn
   * @param  {...function} rules - Validator functions (return null or error string)
   */
  validate(targetColumn, ...rules) {
    if (!this.#validationRules[targetColumn]) {
      this.#validationRules[targetColumn] = [];
    }
    this.#validationRules[targetColumn].push(...rules);
    return this;
  }

  /**
   * Register lifecycle hooks.
   */
  on(event, fn) {
    if (event in this.#hooks) {
      this.#hooks[event] = fn;
    }
    return this;
  }

  // ─── Execution ────────────────────────────────────────────

  /**
   * Read and migrate from a CSV file path.
   */
  fromFile(filePath) {
    const absolutePath = path.resolve(filePath);

    if (!fs.existsSync(absolutePath)) {
      throw new Error(`File not found: ${absolutePath}`);
    }

    const raw = fs.readFileSync(absolutePath, "utf-8");
    return this.fromString(raw);
  }

  /**
   * Migrate from a raw CSV string.
   */
  fromString(csvString) {
    this.#errors = [];
    this.#stats = { total: 0, valid: 0, skipped: 0, transformed: 0 };

    const { headers, rows } = this.#parser.parse(csvString);
    const results = [];

    for (let i = 0; i < rows.length; i++) {
      this.#stats.total++;
      const sourceRow = rows[i];
      const rowNumber = i + 2; // +1 for 0-index, +1 for header row

      try {
        // Hook: beforeRow
        if (this.#hooks.beforeRow) {
          const skip = this.#hooks.beforeRow(sourceRow, rowNumber);
          if (skip === false) {
            this.#stats.skipped++;
            continue;
          }
        }

        // Step 1: Apply column mapping
        let targetRow = this.#applyColumnMap(sourceRow);

        // Step 2: Apply transforms
        targetRow = this.#applyTransforms(targetRow);
        this.#stats.transformed++;

        // Step 3: Validate
        const rowErrors = this.#applyValidation(targetRow, rowNumber);
        if (rowErrors.length > 0) {
          this.#errors.push(...rowErrors);
          this.#stats.skipped++;

          if (this.#hooks.onError) {
            this.#hooks.onError(rowErrors, sourceRow, rowNumber);
          }
          continue;
        }

        // Hook: afterRow
        if (this.#hooks.afterRow) {
          targetRow = this.#hooks.afterRow(targetRow, rowNumber) ?? targetRow;
        }

        this.#stats.valid++;
        results.push(targetRow);
      } catch (err) {
        this.#errors.push({ row: rowNumber, error: err.message });
        this.#stats.skipped++;
      }
    }

    return new MigrationResult(results, this.#errors, this.#stats, this.#parser);
  }

  // ─── Internal ─────────────────────────────────────────────

  #applyColumnMap(sourceRow) {
    // If no mapping defined, pass through
    if (Object.keys(this.#columnMap).length === 0) {
      return { ...sourceRow };
    }

    const targetRow = {};
    for (const [sourceCol, targetCol] of Object.entries(this.#columnMap)) {
      targetRow[targetCol] = sourceRow[sourceCol] ?? null;
    }
    return targetRow;
  }

  #applyTransforms(row) {
    const result = { ...row };
    for (const [col, fns] of Object.entries(this.#transforms)) {
      if (col in result) {
        for (const fn of fns) {
          result[col] = fn(result[col]);
        }
      }
    }
    return result;
  }

  #applyValidation(row, rowNumber) {
    const errors = [];
    for (const [col, rules] of Object.entries(this.#validationRules)) {
      for (const rule of rules) {
        const error = rule(row[col], col);
        if (error) {
          errors.push({ row: rowNumber, field: col, message: error });
        }
      }
    }
    return errors;
  }
}

/**
 * Wraps the migration output with helper methods.
 */
class MigrationResult {
  constructor(rows, errors, stats, parser) {
    this.rows = rows;
    this.errors = errors;
    this.stats = stats;
    this._parser = parser;
  }

  /** Get target column names from the first result row */
  get headers() {
    return this.rows.length > 0 ? Object.keys(this.rows[0]) : [];
  }

  /** Convert results back to CSV */
  toCSV() {
    return this._parser.serialize(this.headers, this.rows);
  }

  /** Convert results to JSON string */
  toJSON(pretty = true) {
    return JSON.stringify(this.rows, null, pretty ? 2 : 0);
  }

  /** Write CSV output to a file */
  writeCSV(filePath) {
    fs.writeFileSync(path.resolve(filePath), this.toCSV(), "utf-8");
    return this;
  }

  /** Write JSON output to a file */
  writeJSON(filePath, pretty = true) {
    fs.writeFileSync(path.resolve(filePath), this.toJSON(pretty), "utf-8");
    return this;
  }

  /** Print a summary to the console */
  printSummary() {
    console.log("\n┌─── Migration Summary ─────────────────┐");
    console.log(`│  Total rows processed:  ${String(this.stats.total).padStart(8)}    │`);
    console.log(`│  Successfully migrated: ${String(this.stats.valid).padStart(8)}    │`);
    console.log(`│  Skipped / errored:     ${String(this.stats.skipped).padStart(8)}    │`);
    console.log(`│  Validation errors:     ${String(this.errors.length).padStart(8)}    │`);
    console.log("└───────────────────────────────────────┘\n");

    if (this.errors.length > 0) {
      console.log("Errors:");
      this.errors.forEach((e) => {
        console.log(`  Row ${e.row}: [${e.field ?? "general"}] ${e.message ?? e.error}`);
      });
      console.log();
    }

    return this;
  }
}

module.exports = MigrationHelper;
