# Analytics Pipeline with Retry Handling

## Core Pipeline Implementation

```javascript
// ============================================================
// analytics-pipeline.js
// A simple analytics pipeline with configurable retry logic
// ============================================================

/**
 * Retry wrapper with exponential backoff
 */
class RetryHandler {
  constructor(options = {}) {
    this.maxRetries = options.maxRetries ?? 3;
    this.baseDelay = options.baseDelay ?? 1000;       // 1 second
    this.maxDelay = options.maxDelay ?? 30000;         // 30 seconds
    this.backoffFactor = options.backoffFactor ?? 2;
    this.retryableErrors = options.retryableErrors ?? [
      'TIMEOUT',
      'RATE_LIMITED',
      'SERVICE_UNAVAILABLE',
      'NETWORK_ERROR',
    ];
  }

  /**
   * Execute a function with retry logic
   */
  async execute(fn, context = {}) {
    let lastError;

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      try {
        const result = await fn(attempt);
        return { success: true, result, attempts: attempt + 1 };
      } catch (error) {
        lastError = error;

        if (attempt === this.maxRetries || !this.isRetryable(error)) {
          break;
        }

        const delay = this.calculateDelay(attempt);
        console.warn(
          `[Retry] Attempt ${attempt + 1}/${this.maxRetries} failed for ${context.name || 'unknown'}. ` +
          `Retrying in ${delay}ms... Error: ${error.message}`
        );

        await this.sleep(delay);
      }
    }

    return {
      success: false,
      error: lastError,
      attempts: this.maxRetries + 1,
    };
  }

  isRetryable(error) {
    return this.retryableErrors.includes(error.code);
  }

  calculateDelay(attempt) {
    const delay = this.baseDelay * Math.pow(this.backoffFactor, attempt);
    const jitter = delay * 0.2 * Math.random(); // ±20% jitter
    return Math.min(delay + jitter, this.maxDelay);
  }

  sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

/**
 * Dead Letter Queue for permanently failed events
 */
class DeadLetterQueue {
  constructor() {
    this.items = [];
  }

  add(event, error, metadata = {}) {
    this.items.push({
      event,
      error: { message: error.message, code: error.code },
      failedAt: new Date().toISOString(),
      ...metadata,
    });
    console.error(`[DLQ] Event added: ${event.type} (${error.message})`);
  }

  getAll() {
    return [...this.items];
  }

  get size() {
    return this.items.length;
  }

  drain() {
    const items = [...this.items];
    this.items = [];
    return items;
  }
}

/**
 * Individual pipeline stage
 */
class PipelineStage {
  constructor(name, processFn, options = {}) {
    this.name = name;
    this.processFn = processFn;
    this.retryHandler = new RetryHandler(options.retry);
    this.metrics = { processed: 0, failed: 0, retried: 0 };
  }

  async process(event) {
    const result = await this.retryHandler.execute(
      (attempt) => {
        if (attempt > 0) this.metrics.retried++;
        return this.processFn(event);
      },
      { name: this.name }
    );

    if (result.success) {
      this.metrics.processed++;
    } else {
      this.metrics.failed++;
    }

    return result;
  }

  getMetrics() {
    return { stage: this.name, ...this.metrics };
  }
}

/**
 * Main Analytics Pipeline
 */
class AnalyticsPipeline {
  constructor(options = {}) {
    this.stages = [];
    this.dlq = new DeadLetterQueue();
    this.batchSize = options.batchSize ?? 10;
    this.flushInterval = options.flushInterval ?? 5000;
    this.buffer = [];
    this.isRunning = false;
    this.flushTimer = null;
    this.onProcessed = options.onProcessed ?? (() => {});
  }

  // --- Stage Management ---

  addStage(name, processFn, options = {}) {
    this.stages.push(new PipelineStage(name, processFn, options));
    return this; // chainable
  }

  // --- Event Ingestion ---

  track(event) {
    const enrichedEvent = {
      id: this.generateId(),
      timestamp: Date.now(),
      ...event,
    };

    this.buffer.push(enrichedEvent);

    if (this.buffer.length >= this.batchSize) {
      this.flush();
    }

    return enrichedEvent.id;
  }

  // --- Processing ---

  async flush() {
    if (this.buffer.length === 0) return;

    const batch = this.buffer.splice(0, this.batchSize);
    const results = await Promise.allSettled(
      batch.map((event) => this.processEvent(event))
    );

    const summary = {
      total: batch.length,
      succeeded: results.filter((r) => r.status === 'fulfilled' && r.value.success).length,
      failed: results.filter((r) => r.status !== 'fulfilled' || !r.value.success).length,
    };

    console.log(`[Pipeline] Flush complete:`, summary);
    return summary;
  }

  async processEvent(event) {
    let currentEvent = { ...event };

    for (const stage of this.stages) {
      const result = await stage.process(currentEvent);

      if (!result.success) {
        this.dlq.add(currentEvent, result.error, {
          failedStage: stage.name,
          totalAttempts: result.attempts,
        });
        return { success: false, eventId: event.id, failedStage: stage.name };
      }

      // Stage can transform the event for the next stage
      if (result.result !== undefined && result.result !== null) {
        currentEvent = result.result;
      }
    }

    this.onProcessed(currentEvent);
    return { success: true, eventId: event.id };
  }

  // --- Lifecycle ---

  start() {
    if (this.isRunning) return;
    this.isRunning = true;

    this.flushTimer = setInterval(() => {
      if (this.buffer.length > 0) {
        this.flush();
      }
    }, this.flushInterval);

    console.log(`[Pipeline] Started (batch=${this.batchSize}, interval=${this.flushInterval}ms)`);
  }

  async stop() {
    this.isRunning = false;
    clearInterval(this.flushTimer);

    // Flush remaining events
    while (this.buffer.length > 0) {
      await this.flush();
    }

    console.log('[Pipeline] Stopped. Final metrics:', this.getMetrics());
  }

  // --- Metrics ---

  getMetrics() {
    return {
      buffer: this.buffer.length,
      dlq: this.dlq.size,
      stages: this.stages.map((s) => s.getMetrics()),
    };
  }

  generateId() {
    return `evt_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
  }
}

// ============================================================
// Export
// ============================================================
module.exports = { AnalyticsPipeline, RetryHandler, DeadLetterQueue };
```

## Usage Example

```javascript
const { AnalyticsPipeline } = require('./analytics-pipeline');

// --- Simulate external services that can fail ---

function simulateFailure(failRate = 0.3) {
  if (Math.random() < failRate) {
    const error = new Error('Service temporarily unavailable');
    error.code = 'SERVICE_UNAVAILABLE';
    throw error;
  }
}

// --- Build the pipeline ---

const pipeline = new AnalyticsPipeline({
  batchSize: 5,
  flushInterval: 3000,
  onProcessed: (event) => {
    console.log(`  ✓ Event fully processed: ${event.type} [${event.id}]`);
  },
});

// Stage 1: Validate incoming events
pipeline.addStage('validate', (event) => {
  if (!event.type) throw Object.assign(new Error('Missing event type'), { code: 'INVALID' });
  if (!event.properties) throw Object.assign(new Error('Missing properties'), { code: 'INVALID' });

  return { ...event, validated: true };
});

// Stage 2: Enrich with session/user data (may fail — retryable)
pipeline.addStage(
  'enrich',
  (event) => {
    simulateFailure(0.4);
    return {
      ...event,
      enriched: true,
      sessionId: 'sess_abc123',
      userAgent: 'Mozilla/5.0',
    };
  },
  { retry: { maxRetries: 3, baseDelay: 500 } }
);

