## Core Types

```typescript
// src/types.ts

/** Supported primitive types for config values */
export type ConfigPrimitive = string | number | boolean;

/** A config value can be a primitive, array, or nested object */
export type ConfigValue =
  | ConfigPrimitive
  | ConfigValue[]
  | { [key: string]: ConfigValue };

/** Flat key-value representation used during loading */
export type RawConfig = Record<string, unknown>;

/** Describes a single config field's rules */
export interface SchemaField<T = ConfigValue> {
  type: 'string' | 'number' | 'boolean' | 'object' | 'array';
  required?: boolean;
  default?: T;
  description?: string;
  env?: string;              // maps to an environment variable
  validator?: (value: T) => ValidationResult;
  transform?: (raw: unknown) => T;
  sensitive?: boolean;       // redacted in logs
}

/** Full schema = map of dotted paths to field definitions */
export type ConfigSchema<T extends RawConfig = RawConfig> = {
  [K in keyof T]: SchemaField<T[K]>;
};

/** Result of a single validation check */
export interface ValidationResult {
  valid: boolean;
  message?: string;
}

/** Accumulated errors from loading + validating */
export interface ValidationError {
  field: string;
  message: string;
  value?: unknown;
}

/** Options passed to the ConfigLoader constructor */
export interface ConfigLoaderOptions {
  schema: ConfigSchema<any>;
  sources?: ConfigSource[];
  envPrefix?: string;
  strict?: boolean;          // throw on unknown keys
  onError?: 'throw' | 'collect';
}

/** Any object that can provide raw config */
export interface ConfigSource {
  readonly name: string;
  readonly priority: number; // higher wins
  load(): Promise<RawConfig> | RawConfig;
}

/** Summary returned after loading */
export interface LoadResult<T> {
  config: Readonly<T>;
  errors: ValidationError[];
  sources: string[];         // which sources contributed
}
