export class ConfigValidationError extends ConfigError {
  public readonly errors: ValidationError[];

  constructor(errors: ValidationError[]) {
    const summary = errors
      .map((e) => `  - ${e.field}: ${e.message}`)
      .join('\n');

    super(`Configuration validation failed:\n${summary}`);
    this.name = 'ConfigValidationError';
    this.errors = errors;
    Object.setPrototypeOf(this, ConfigValidationError.prototype);
  }
}

export class ConfigSourceError extends ConfigError {
  public readonly sourceName: string;
  public readonly cause?: Error;

  constructor(sourceName: string, message: string, cause?: Error) {
    super(`Source "${sourceName}": ${message}`);
    this.name = 'ConfigSourceError';
    this.sourceName = sourceName;
    this.cause = cause;
    Object.setPrototypeOf(this, ConfigSourceError.prototype);
