## Validators

```typescript
// src/validators.ts

import { ValidationResult, SchemaField, ConfigValue } from './types';

// ─── Built-in validator factories ───────────────────────────────

export function isString(value: unknown): ValidationResult {
  return {
    valid: typeof value === 'string',
    message: typeof value === 'string'
      ? undefined
      : `Expected string, got ${typeof value}`,
  };
}

export function isNumber(value: unknown): ValidationResult {
  return {
    valid: typeof value === 'number' && !Number.isNaN(value),
    message:
      typeof value === 'number' && !Number.isNaN(value)
        ? undefined
        : `Expected number, got ${typeof value}`,
  };
}

export function isBoolean(value: unknown): ValidationResult {
  return {
    valid: typeof value === 'boolean',
    message: typeof value === 'boolean'
      ? undefined
      : `Expected boolean, got ${typeof value}`,
  };
}

export function isObject(value: unknown): ValidationResult {
  return {
    valid: typeof value === 'object' && value !== null && !Array.isArray(value),
    message: `Expected object, got ${Array.isArray(value) ? 'array' : typeof value}`,
  };
}

export function isArray(value: unknown): ValidationResult {
  return {
    valid: Array.isArray(value),
    message: Array.isArray(value) ? undefined : `Expected array, got ${typeof value}`,
  };
}

/** Map schema `type` string → runtime checker */
const TYPE_VALIDATORS: Record<SchemaField['type'], (v: unknown) => ValidationResult> = {
  string: isString,
  number: isNumber,
  boolean: isBoolean,
  object: isObject,
  array: isArray,
};

// ─── Composite helpers ──────────────────────────────────────────

export function inRange(min: number, max: number) {
  return (value: number): ValidationResult => ({
    valid: value >= min && value <= max,
    message: value >= min && value <= max
      ? undefined
      : `Value ${value} outside range [${min}, ${max}]`,
  });
}

export function matchesPattern(pattern: RegExp) {
  return (value: string): ValidationResult => ({
    valid: pattern.test(value),
    message: pattern.test(value) ? undefined : `Value does not match ${pattern}`,
  });
}

export function oneOf<T extends ConfigValue>(allowed: T[]) {
  return (value: T): ValidationResult => ({
    valid: allowed.includes(value),
    message: allowed.includes(value)
      ? undefined
      : `Value must be one of [${allowed.join(', ')}]`,
  });
}

// ─── Field-level validation ─────────────────────────────────────

export function validateField(
  field: string,
  value: unknown,
  schema: SchemaField,
): ValidationResult[] {
  const results: ValidationResult[] = [];

  // 1. Type check
  const typeCheck = TYPE_VALIDATORS[schema.type];
  if (typeCheck) {
    const typeResult = typeCheck(value);
    if (!typeResult.valid) {
      results.push(typeResult);
      return results; // stop early — wrong type
    }
  }

  // 2. Custom validator
  if (schema.validator) {
    const customResult = schema.validator(value as any);
    if (!customResult.valid) {
      results.push(customResult);
    }
  }

  return results;
}
