// src/sources/env-source.ts

import { ConfigSource, RawConfig, ConfigSchema, SchemaField } from '../types';

export interface EnvSourceOptions {
  prefix?: string;
  schema: ConfigSchema<any>;
  env?: Record<string, string | undefined>; // injectable for testing
  separator?: string;
}

export class EnvSource implements ConfigSource {
  public readonly name = 'environment';
  public readonly priority: number;

  private readonly prefix: string;
  private readonly schema: ConfigSchema<any>;
  private readonly env: Record<string, string | undefined>;
  private readonly separator: string;

  constructor(options: EnvSourceOptions, priority = 30) {
    this.prefix = options.prefix ?? '';
    this.schema = options.schema;
    this.env = options.env ?? process.env;
    this.separator = options.separator ?? '__';
    this.priority = priority;
  }

  load(): RawConfig {
    const config: RawConfig = {};

    for (const [key, field] of Object.entries(this.schema) as [string, SchemaField][]) {
      // Explicit env mapping takes precedence
      const envKey = field.env ?? this.buildEnvKey(key);
      const rawValue = this.env[envKey];

      if (rawValue !== undefined) {
        config[key] = this.coerce(rawValue, field);
      }
    }

    return config;
  }

  /** APP__DATABASE__PORT → APP__DATABASE__PORT */
  private buildEnvKey(configKey: string): string {
    const parts = [this.prefix, ...configKey.split('.')].filter(Boolean);
    return parts.join(this.separator).toUpperCase();
  }

  private coerce(raw: string, field: SchemaField): unknown {
    if (field.transform) return field.transform(raw);

    switch (field.type) {
      case 'number': {
        const n = Number(raw);
        return Number.isNaN(n) ? raw : n; // let validator catch it
      }
      case 'boolean':
        return raw === 'true' || raw === '1';
      case 'array':
        try {
          return JSON.parse(raw);
        } catch {
          return raw.split(',').map((s) => s.trim());
        }
      case 'object':
        try {
          return JSON.parse(raw);
        } catch {
          return raw;
        }
      default:
        return raw;
    }
  }
}
