// src/sources/file-source.ts

import * as fs from 'fs';
import * as path from 'path';
import { ConfigSource, RawConfig } from '../types';
import { ConfigSourceError } from '../errors';

export interface FileSourceOptions {
  filePath: string;
  required?: boolean;
  /** Allow injection for testing */
  readFile?: (filePath: string) => string;
}

export class FileSource implements ConfigSource {
  public readonly name: string;
  public readonly priority: number;

  private readonly filePath: string;
  private readonly required: boolean;
  private readonly readFile: (filePath: string) => string;

  constructor(options: FileSourceOptions, priority = 10) {
    this.filePath = path.resolve(options.filePath);
    this.required = options.required ?? false;
    this.readFile = options.readFile ?? ((p) => fs.readFileSync(p, 'utf-8'));
    this.name = `file:${path.basename(this.filePath)}`;
    this.priority = priority;
  }

  load(): RawConfig {
    try {
      const content = this.readFile(this.filePath);
      const parsed = JSON.parse(content);

      if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        throw new ConfigSourceError(
          this.name,
          'Config file must contain a JSON object at root level',
        );
      }

      // Flatten nested objects into dotted keys
      return this.flatten(parsed);
    } catch (error) {
      if (error instanceof ConfigSourceError) throw error;

      const err = error as NodeJS.ErrnoException;
      if (err.code === 'ENOENT' && !this.required) {
        return {};
      }

      throw new ConfigSourceError(
        this.name,
        `Failed to load config file: ${err.message}`,
        err,
      );
    }
  }

  private flatten(obj: Record<string, unknown>, prefix = ''): RawConfig {
    const result: RawConfig = {};

    for (const [key, value] of Object.entries(obj)) {
      const fullKey = prefix ? `${prefix}.${key}` : key;

      if (
        typeof value === 'object' &&
        value !== null &&
        !Array.isArray(value)
      ) {
        Object.assign(result, this.flatten(value as Record<string, unknown>, fullKey));
      } else {
        result[fullKey] = value;
      }
    }

    return result;
  }
}
