## Schema Helper

```typescript
// src/schema.ts

import { ConfigSchema, SchemaField, RawConfig, ValidationError } from './types';
import { validateField } from './validators';

/**
 * Builds a type-safe schema. This is just an identity function at
 * runtime, but helps with inference when defining config shapes.
 */
export function defineSchema<T extends RawConfig>(
  schema: ConfigSchema<T>,
): ConfigSchema<T> {
  return schema;
}

/**
 * Applies defaults from the schema to a partial raw config.
 */
export function applyDefaults<T extends RawConfig>(
  raw: RawConfig,
  schema: ConfigSchema<T>,
): RawConfig {
  const result: RawConfig = { ...raw };

  for (const [key, field] of Object.entries(schema) as [string, SchemaField][]) {
    if (result[key] === undefined && field.default !== undefined) {
      result[key] = structuredClone(field.default);
    }
  }

  return result;
}

/**
 * Full schema-level validation. Returns all errors found.
 */
export function validateConfig<T extends RawConfig>(
  raw: RawConfig,
  schema: ConfigSchema<T>,
  strict = false,
): ValidationError[] {
  const errors: ValidationError[] = [];

  // 1. Check required fields & field-level validation
  for (const [key, field] of Object.entries(schema) as [string, SchemaField][]) {
    const value = raw[key];

    if (value === undefined || value === null) {
      if (field.required) {
        errors.push({
          field: key,
          message: `Required field is missing`,
        });
      }
      continue; // nothing else to validate
    }

    const fieldErrors = validateField(key, value, field);
    for (const result of fieldErrors) {
      if (!result.valid) {
        errors.push({
          field: key,
          message: result.message ?? 'Validation failed',
          value: field.sensitive ? '[REDACTED]' : value,
        });
      }
    }
  }

  // 2. Strict mode: reject unknown keys
  if (strict) {
    const knownKeys = new Set(Object.keys(schema));
    for (const key of Object.keys(raw)) {
      if (!knownKeys.has(key)) {
        errors.push({
          field: key,
          message: `Unknown configuration key`,
          value: raw[key],
        });
      }
    }
  }

  return errors;
}

/**
 * Unflattens dotted keys into a nested object for the final config.
 *
 *   { "db.host": "localhost" }  →  { db: { host: "localhost" } }
 */
export function unflatten(raw: RawConfig): Record<string, unknown> {
  const result: Record<string, unknown> = {};

  for (const [dottedKey, value] of Object.entries(raw)) {
    const parts = dottedKey.split('.');
    let current: Record<string, unknown> = result;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      if (!(part in current) || typeof current[part] !== 'object') {
        current[part] = {};
      }
      current = current[part] as Record<string, unknown>;
    }

    current[parts[parts.length - 1]] = value;
  }

  return result;
}
