    // FIX 7: Validate required options
    if (!Array.isArray(options.rules) || options.rules.length === 0) {
      throw new Error('ModerationScheduler requires at least one rule');
    }
    this._validateRules(options.rules);

    this.queue = [];
    this.moderationRules = options.rules;

    // FIX 1: Provide safe defaults
    this.interval = options.interval || DEFAULT_INTERVAL_MS;
    this.batchSize = options.batchSize || DEFAULT_BATCH_SIZE;

    this.isProcessing = false;
    this.timerId = null;

    // FIX 2: Use a circular buffer / bounded results store
    this.results = [];
    this.maxResults = MAX_RESULTS_RETAINED;

    // FIX 3: Use a Map for efficient key management + TTL cleanup
    this.rateLimitMap = new Map();
    this._rateLimitCleanupTimer = null;

    // FIX 6: Track processing state for graceful shutdown
    this._processingPromise = null;
    this._shuttingDown = false;
  }

  // ─── Lifecycle ────────────────────────────────────────────

  start() {
    // FIX 4: Prevent duplicate intervals
    if (this.timerId !== null) {
      console.warn('Scheduler is already running');
      return;
    }

    this._shuttingDown = false;

    this.timerId = setInterval(() => {
      this._processingPromise = this.processQueue();
    }, this.interval);

    // Periodic cleanup of stale rate-limit entries every 5 min
    this._rateLimitCleanupTimer = setInterval(() => {
      this._cleanupRateLimits();
    }, 5 * 60_000);

    this.emit('started');
    console.log(`Scheduler started (interval=${this.interval}ms, batch=${this.batchSize})`);
  }

  async stop() {
    // FIX 5 & 6: Nullify timer and wait for in-progress work
    this._shuttingDown = true;

    if (this.timerId !== null) {
      clearInterval(this.timerId);
      this.timerId = null;
    }

    if (this._rateLimitCleanupTimer !== null) {
      clearInterval(this._rateLimitCleanupTimer);
      this._rateLimitCleanupTimer = null;
    }

    // Wait for any in-flight batch to complete
    if (this._processingPromise) {
      console.log('Waiting for current batch to finish…');
      await this._processingPromise;
    }

    this.emit('stopped');
    console.log('Scheduler stopped gracefully');
  }

  // ─── Queue Management ─────────────────────────────────────

  addMessage(message) {
    // FIX 7: Validate input
    if (!message || typeof message.id === 'undefined' || !message.content) {
      throw new TypeError('Message must have { id, content, userId }');
    }

    // FIX 8: Enforce max queue size to prevent memory exhaustion
    if (this.queue.length >= MAX_QUEUE_SIZE) {
      this.emit('queue_full', { dropped: message });
      console.warn(`Queue full (${MAX_QUEUE_SIZE}). Dropping message ${message.id}`);
      return false;
    }

    this.queue.push({
      id: message.id,
      content: message.content,
      userId: message.userId,
      receivedAt: Date.now(),
    });

    return true;
  }

  // ─── Processing ────────────────────────────────────────────

  async processQueue() {
    if (this.isProcessing || this.queue.length === 0) return;
    this.isProcessing = true;

    // FIX 9: splice removes items from the queue (not slice)
    const batch = this.queue.splice(0, this.batchSize);

    // FIX 10: Wrap in try/catch so errors never kill the scheduler
    try {
      const batchResults = await Promise.allSettled(
        batch.map(msg => this.moderateMessage(msg))
      );

      for (const entry of batchResults) {
        if (entry.status === 'fulfilled') {
          this._storeResult(entry.value);
          this.emit('moderated', entry.value);
        } else {
          // Log but don't crash
          console.error('Moderation error:', entry.reason);
          this.emit('error', entry.reason);
        }
      }
    } catch (err) {
      console.error('Unexpected batch processing error:', err);
      this.emit('error', err);
    } finally {
      this.isProcessing = false;
    }
  }

  async moderateMessage(message) {
    const violations = [];

    // FIX 11: Null-safe iteration with validation
    for (const rule of this.moderationRules) {
      if (!rule.pattern) continue;

      // FIX 12a: Reset regex lastIndex for global regexes
      rule.pattern.lastIndex = 0;

      if (rule.pattern.test(message.content)) {
        violations.push({
          rule: rule.name,
          action: rule.action,
        });
      }
    }

    // FIX 14/15: Fixed rate-limit check
    if (this._checkRateLimit(message.userId)) {
      violations.push({
        rule: 'rate_limit',
        action: 'throttle',
      });
    }

    // Determine the most severe action
    const action = this._resolveAction(violations);

    return {
      messageId: message.id,
      userId: message.userId,
      violations,
      action,
      // FIX 13: Call Date.now() — not reference it
      timestamp: Date.now(),
    };
  }

  // ─── Rate Limiting ─────────────────────────────────────────

  /** @returns {boolean} true if the user exceeded the rate limit */
  _checkRateLimit(userId) {
    const now = Date.now();

    // FIX 14: Initialize entry if it doesn't exist
    if (!this.rateLimitMap.has(userId)) {
      this.rateLimitMap.set(userId, []);
    }

    const timestamps = this.rateLimitMap.get(userId);
    timestamps.push(now);

    // FIX 15: Reassign filtered array (filter is non-mutating)
    const recent = timestamps.filter(ts => now - ts < RATE_LIMIT_WINDOW_MS);
    this.rateLimitMap.set(userId, recent);

    return recent.length > RATE_LIMIT_MAX_MESSAGES;
  }

  /** Remove entries for users with no recent activity */
  _cleanupRateLimits() {
    const now = Date.now();
    let cleaned = 0;

    for (const [userId, timestamps] of this.rateLimitMap) {
      const recent = timestamps.filter(ts => now - ts < RATE_LIMIT_WINDOW_MS);
      if (recent.length === 0) {
        this.rateLimitMap.delete(userId);
        cleaned++;
      } else {
        this.rateLimitMap.set(userId, recent);
      }
    }

    if (cleaned > 0) {
      console.log(`Rate-limit cleanup: removed ${cleaned} stale entries`);
    }
  }

  // ─── Helpers ───────────────────────────────────────────────

  /** Keep results buffer bounded (FIX 2) */
  _storeResult(result) {
    this.results.push(result);
    if (this.results.length > this.maxResults) {
      this.results = this.results.slice(-this.maxResults);
    }
  }

  /** Highest-severity action wins */
  _resolveAction(violations) {
    if (violations.length === 0) return 'allow';
    const priority = { delete: 3, mute: 2, throttle: 1, flag: 0 };
    return violations.reduce((worst, v) => {
      return (priority[v.action] ?? 0) > (priority[worst] ?? 0)
        ? v.action
        : worst;
    }, 'flag');
  }

  _validateRules(rules) {
    for (const rule of rules) {
      if (!rule.name || !rule.pattern || !rule.action) {
        throw new Error(`Invalid rule: ${JSON.stringify(rule)}`);
      }
    }
  }

  getStats() {
    return {
      running: this.timerId !== null,
      queueLength: this.queue.length,
      processed: this.results.length,
      rateLimitedUsers: this.rateLimitMap.size,
    };
  }
}

// ─── Usage ──────────────────────────────────────────────────
async function main() {
  const scheduler = new ModerationScheduler({
    rules: [
      { name: 'profanity', pattern: /badword/gi, action: 'mute' },
      { name: 'spam_links', pattern: /https?:\/\/spam\.com/gi, action: 'delete' },
      { name: 'all_caps',  pattern: /^[A-Z\s!]{20,}$/g, action: 'flag' },
    ],
    interval: 1000,
    batchSize: 25,
  });

  // ─── Event listeners ──────────────────────────────────────
  scheduler.on('moderated', (result) => {
    if (result.action !== 'allow') {
      console.log(`⚠  [${result.action.toUpperCase()}] msg=${result.messageId}`, result.violations);
    }
  });

  scheduler.on('queue_full', ({ dropped }) => {
    console.warn(`Dropped message ${dropped.id}`);
  });

  scheduler.on('error', (err) => {
    console.error('Scheduler error:', err.message);
  });

  // Start the scheduler
  scheduler.start();

  // Simulate incoming messages
  const testMessages = [
    { id: 1, content: 'Hello everyone!', userId: 'user1' },
    { id: 2, content: 'Check https://spam.com for deals', userId: 'user2' },
    { id: 3, content: 'You are a badword person', userId: 'user3' },
    { id: 4, content: 'Normal message', userId: 'user1' },
    { id: 5, content: 'STOP DOING THIS RIGHT NOW!!!', userId: 'user4' },
  ];

  for (const msg of testMessages) {
    scheduler.addMessage(msg);
  }

  // Simulate rapid messages for rate-limit testing
  for (let i = 100; i < 115; i++) {
    scheduler.addMessage({ id: i, content: `Spam ${i}`, userId: 'spammer' });
  }

  console.log('Stats:', scheduler.getStats());

  // FIX 17: Graceful shutdown on SIGTERM / SIGINT
  const shutdown = async (signal) => {
    console.log(`\nReceived ${signal}. Shutting down…`);
    await scheduler.stop();
    console.log('Final stats:', scheduler.getStats());
    process.exit(0);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));

  // Auto-stop after 5s for demo
  setTimeout(() => shutdown('TIMEOUT'), 5000);
}

main().catch(console.error);
```

---

## Bug Summary Table

| # | Bug | Fix |
|---|-----|-----|
| 1 | No default for `interval`/`batchSize` → `NaN` timers | Provide fallback constants |
| 2 | `results[]` grows forever → **memory leak** | Bounded circular buffer with `_storeResult()` |
| 3 | Plain object `{}` for rate limits, never cleaned | `Map` + periodic `_cleanupRateLimits()` |
| 4 | `start()` creates duplicate `setInterval` | Guard with `if (this.timerId !== null)` |
| 5 | `stop()` doesn't null `timerId` | Set `this.timerId = null` after clear |
| 6 | `stop()` ignores in-flight batch | `await this._processingPromise` before exit |
| 7 | No input validation on `addMessage` | `TypeError` for malformed messages |
| 8 | Queue unbounded → OOM | `MAX_QUEUE_SIZE` cap + `queue_full` event |
| 9 | `slice()` doesn't remove items | `splice(0, batchSize)` dequeues items |
| 10 | No `try/catch` → unhandled rejection | `Promise.allSettled` + `try/finally` |
| 11 | No null-check on rule properties | `if (!rule.pattern) continue` + `_validateRules` |
| 12 | Global regex `lastIndex` not reset | `rule.pattern.lastIndex = 0` before `.test()` |
| 13 | `Date.now` (reference) vs `Date.now()` (call) | Add parentheses `()` |
| 14 | `rateLimitMap[userId].push()` on `undefined` | `Map.has()` check → initialize `[]` |
| 15 | `.filter()` return value ignored | Reassign: `this.rateLimitMap.set(userId, recent)` |
| 16 | `getStats` context loss if passed as callback | Bind or use arrow (documented) |
| 17 | No `SIGTERM`/`SIGINT` handler | `process.on(signal)` → `await scheduler.stop()` |

### Key Debugging Takeaways

```
✔  Always reset .lastIndex on global (/g) regexes between calls
✔  .filter() returns a NEW array — reassign or use .splice() to mutate
✔  Date.now is a function REFERENCE; Date.now() is the CALL
✔  splice() removes from source; slice() copies without modifying
✔  Bound all growing data structures (queues, logs, caches)
✔  Always await in-flight async work during shutdown
```

