## Step 1: Custom Exceptions

```python
# exceptions.py

class ConfigError(Exception):
    """Base exception for all config-related errors."""
    def __init__(self, message: str, filename: str = None, line: int = None):
        self.filename = filename
        self.line = line
        location = ""
        if filename:
            location += f" in '{filename}'"
        if line is not None:
            location += f" at line {line}"
        super().__init__(f"{message}{location}")


class ConfigFileNotFoundError(ConfigError):
    """Raised when a config file doesn't exist."""
    pass


class ConfigSyntaxError(ConfigError):
    """Raised when config file has invalid syntax."""
    pass


class MissingSectionError(ConfigError):
    """Raised when a required section is missing."""
    def __init__(self, section: str, **kwargs):
        self.section = section
        super().__init__(f"Missing required section: [{section}]", **kwargs)


class MissingKeyError(ConfigError):
    """Raised when a required key is missing."""
    def __init__(self, section: str, key: str, **kwargs):
        self.section = section
        self.key = key
        super().__init__(f"Missing required key '{key}' in [{section}]", **kwargs)


class InvalidTypeError(ConfigError):
    """Raised when a value can't be converted to the expected type."""
    def __init__(self, key: str, value: str, expected_type: str, **kwargs):
        self.key = key
        self.value = value
        self.expected_type = expected_type
        super().__init__(
            f"Cannot convert '{key}={value}' to {expected_type}", **kwargs
        )
```

## Step 2: Type Validators

```python
# validators.py

from typing import Any, List

from exceptions import InvalidTypeError


class TypeValidator:
    """Handles type conversion and validation for config values."""

    # Recognized boolean strings
    BOOL_TRUE = {"true", "yes", "on", "1", "enabled"}
    BOOL_FALSE = {"false", "no", "off", "0", "disabled"}

    @staticmethod
    def as_string(value: str, key: str = "") -> str:
        return value

    @staticmethod
    def as_int(value: str, key: str = "") -> int:
        try:
            return int(value)
        except ValueError:
            raise InvalidTypeError(key, value, "int")

    @staticmethod
    def as_float(value: str, key: str = "") -> float:
        try:
            return float(value)
        except ValueError:
            raise InvalidTypeError(key, value, "float")

    @staticmethod
    def as_bool(value: str, key: str = "") -> bool:
        lower = value.strip().lower()
        if lower in TypeValidator.BOOL_TRUE:
            return True
        if lower in TypeValidator.BOOL_FALSE:
            return False
        raise InvalidTypeError(key, value, "bool")

    @staticmethod
    def as_list(value: str, key: str = "", delimiter: str = ",") -> List[str]:
        return [item.strip() for item in value.split(delimiter) if item.strip()]

    @classmethod
    def convert(cls, value: str, target_type: str, key: str = "") -> Any:
        """Convert a string value to the target type."""
        converters = {
            "str": cls.as_string,
            "int": cls.as_int,
            "float": cls.as_float,
            "bool": cls.as_bool,
            "list": cls.as_list,
        }
        converter = converters.get(target_type)
        if converter is None:
            raise ValueError(f"Unknown type: {target_type}")
        return converter(value, key)
