## Step 3: Main Config Parser

```python
# config_parser.py

import os
import re
from typing import Any, Dict, Optional, List
from collections import OrderedDict

from exceptions import (
    ConfigError,
    ConfigFileNotFoundError,
    ConfigSyntaxError,
    MissingSectionError,
    MissingKeyError,
    InvalidTypeError,
)
from validators import TypeValidator


class ConfigParser:
    """
    A robust INI-style config parser with:
    - Sections and key-value pairs
    - Comments (# and ;)
    - Type conversion and validation
    - Default values
    - Environment variable interpolation (${ENV_VAR})
    - Required fields enforcement
    """

    # --- Regex patterns for parsing ---
    SECTION_RE = re.compile(r"^\[(?P<section>[^\]]+)\]\s*$")
    KEY_VALUE_RE = re.compile(r"^(?P<key>[^=:]+)[=:](?P<value>.*)$")
    COMMENT_RE = re.compile(r"^\s*[#;]")
    BLANK_RE = re.compile(r"^\s*$")
    ENV_VAR_RE = re.compile(r"\$\{(?P<var>[^}]+)\}")

    def __init__(self, interpolate_env: bool = True):
        # Stores data as {section: {key: value}}
        self._data: OrderedDict[str, OrderedDict[str, str]] = OrderedDict()
        self._filename: Optional[str] = None
        self._interpolate_env = interpolate_env
        self._validator = TypeValidator()

    # ──────────────────── Parsing ────────────────────

    def read(self, filepath: str) -> "ConfigParser":
        """Parse a config file. Returns self for chaining."""
        self._filename = filepath

        if not os.path.exists(filepath):
            raise ConfigFileNotFoundError(
                f"Config file not found: {filepath}", filename=filepath
            )

        try:
            with open(filepath, "r", encoding="utf-8") as f:
                lines = f.readlines()
        except PermissionError:
            raise ConfigError(
                f"Permission denied reading: {filepath}", filename=filepath
            )
        except UnicodeDecodeError as e:
            raise ConfigError(
                f"Encoding error: {e}", filename=filepath
            )

        self._parse_lines(lines)
        return self

    def read_string(self, text: str) -> "ConfigParser":
        """Parse config from a string."""
        self._filename = "<string>"
        self._parse_lines(text.splitlines(keepends=True))
        return self

    def _parse_lines(self, lines: List[str]) -> None:
        """Core line-by-line parser."""
        current_section: Optional[str] = None

        for line_num, raw_line in enumerate(lines, start=1):
            line = raw_line.strip()

            # Skip blanks and comments
            if self.BLANK_RE.match(line) or self.COMMENT_RE.match(line):
                continue

            # Inline comment removal (only outside quotes)
            line = self._strip_inline_comment(line)

            # Section header
            section_match = self.SECTION_RE.match(line)
            if section_match:
                current_section = section_match.group("section").strip()
                if current_section not in self._data:
                    self._data[current_section] = OrderedDict()
                continue

            # Key = Value
            kv_match = self.KEY_VALUE_RE.match(line)
            if kv_match:
                if current_section is None:
                    raise ConfigSyntaxError(
                        "Key-value pair found outside of any section",
                        filename=self._filename,
                        line=line_num,
                    )
                key = kv_match.group("key").strip()
                value = kv_match.group("value").strip()

                # Strip surrounding quotes
                value = self._strip_quotes(value)

                # Environment variable interpolation
                if self._interpolate_env:
                    value = self._resolve_env_vars(value, line_num)

                self._data[current_section][key] = value
                continue

            # If nothing matched → syntax error
            raise ConfigSyntaxError(
                f"Unrecognized syntax: '{line}'",
                filename=self._filename,
                line=line_num,
            )

    @staticmethod
    def _strip_inline_comment(line: str) -> str:
        """Remove inline comments while respecting quoted strings."""
        in_quote = None
        for i, ch in enumerate(line):
            if ch in ('"', "'") and in_quote is None:
                in_quote = ch
            elif ch == in_quote:
                in_quote = None
            elif ch in ("#", ";") and in_quote is None:
                return line[:i].strip()
        return line

    @staticmethod
    def _strip_quotes(value: str) -> str:
        if len(value) >= 2:
            if (value[0] == value[-1]) and value[0] in ('"', "'"):
                return value[1:-1]
        return value

    def _resolve_env_vars(self, value: str, line_num: int) -> str:
        """Replace ${VAR} with environment variable values."""
        def replacer(match):
            var = match.group("var")
            env_val = os.environ.get(var)
            if env_val is None:
                raise ConfigError(
                    f"Undefined environment variable: ${{{var}}}",
                    filename=self._filename,
                    line=line_num,
                )
            return env_val
        return self.ENV_VAR_RE.sub(replacer, value)

    # ──────────────────── Access ────────────────────

    def get(
        self,
        section: str,
        key: str,
        fallback: Any = KeyError,          # sentinel
        cast: Optional[str] = None,        # "int", "float", "bool", "list"
    ) -> Any:
        """
        Retrieve a value with optional type casting and default.

            parser.get("server", "port", cast="int", fallback=8080)
        """
        try:
            value = self._data[section][key]
        except KeyError:
            if fallback is not KeyError:
                return fallback
            if section not in self._data:
                raise MissingSectionError(section, filename=self._filename)
            raise MissingKeyError(section, key, filename=self._filename)

        if cast:
            return self._validator.convert(value, cast, key=f"{section}.{key}")
        return value

    def get_int(self, section: str, key: str, fallback: Any = KeyError) -> int:
        return self.get(section, key, fallback=fallback, cast="int")

    def get_float(self, section: str, key: str, fallback: Any = KeyError) -> float:
        return self.get(section, key, fallback=fallback, cast="float")

    def get_bool(self, section: str, key: str, fallback: Any = KeyError) -> bool:
        return self.get(section, key, fallback=fallback, cast="bool")

    def get_list(self, section: str, key: str, fallback: Any = KeyError) -> list:
        return self.get(section, key, fallback=fallback, cast="list")

    # ──────────────────── Sections / Keys ────────────────────

    def sections(self) -> List[str]:
        return list(self._data.keys())

    def keys(self, section: str) -> List[str]:
        if section not in self._data:
            raise MissingSectionError(section, filename=self._filename)
        return list(self._data[section].keys())

    def has_section(self, section: str) -> bool:
        return section in self._data

    def has_key(self, section: str, key: str) -> bool:
        return section in self._data and key in self._data[section]

    def items(self, section: str) -> List[tuple]:
        if section not in self._data:
            raise MissingSectionError(section, filename=self._filename)
        return list(self._data[section].items())

    def as_dict(self) -> Dict[str, Dict[str, str]]:
        """Export entire config as nested dict."""
        return {sec: dict(kv) for sec, kv in self._data.items()}

    # ──────────────────── Validation ────────────────────

    def validate(self, schema: Dict[str, Dict[str, dict]]) -> List[str]:
        """
        Validate config against a schema. Returns list of errors.

        Schema format:
            {
                "server": {
                    "host": {"type": "str", "required": True},
                    "port": {"type": "int", "required": True, "min": 1, "max": 65535},
                    "debug": {"type": "bool", "required": False, "default": False},
                }
            }
        """
        errors: List[str] = []

        for section, fields in schema.items():
            if not self.has_section(section):
                # Check if any field is required
                required = any(f.get("required", False) for f in fields.values())
                if required:
                    errors.append(f"Missing required section: [{section}]")
                continue

            for key, rules in fields.items():
                required = rules.get("required", False)
                target_type = rules.get("type", "str")

                if not self.has_key(section, key):
                    if required:
                        errors.append(f"Missing required key: [{section}] {key}")
                    continue

                # Type check
                try:
                    value = self.get(section, key, cast=target_type)
                except (InvalidTypeError, ConfigError) as e:
                    errors.append(str(e))
                    continue

                # Range check for numeric types
                if target_type in ("int", "float"):
                    min_val = rules.get("min")
                    max_val = rules.get("max")
                    if min_val is not None and value < min_val:
                        errors.append(
                            f"[{section}] {key}={value} is below minimum ({min_val})"
                        )
                    if max_val is not None and value > max_val:
                        errors.append(
                            f"[{section}] {key}={value} exceeds maximum ({max_val})"
                        )

                # Allowed values
                allowed = rules.get("allowed")
                if allowed and value not in allowed:
                    errors.append(
                        f"[{section}] {key}={value} not in {allowed}"
                    )

        return errors

    # ──────────────────── Display ────────────────────

    def __repr__(self) -> str:
        sections = ", ".join(self.sections())
        return f"ConfigParser(sections=[{sections}])"

    def dump(self) -> str:
        """Pretty-print the parsed config."""
        lines = []
        for section, pairs in self._data.items():
            lines.append(f"[{section}]")
            for key, value in pairs.items():
                lines.append(f"  {key} = {value}")
            lines.append("")
        return "\n".join(lines)
