```javascript
/**
 * Represents a single log entry with metadata.
 */
class LogEntry {
  static VALID_LEVELS = ["DEBUG", "INFO", "WARN", "ERROR", "FATAL"];

  /**
   * @param {Object} options
   * @param {string} options.message   - Log message content
   * @param {string} options.level     - Severity level (DEBUG|INFO|WARN|ERROR|FATAL)
   * @param {string} options.source    - Origin of the log (e.g., "auth-service")
   * @param {Date}   [options.timestamp] - When the log was created
   * @param {Object} [options.metadata]  - Additional key-value data
   */
  constructor({ message, level, source, timestamp = new Date(), metadata = {} }) {
    this.#validate(message, level, source);

    this.id = LogEntry.#generateId();
    this.message = message;
    this.level = level.toUpperCase();
    this.source = source;
    this.timestamp = timestamp instanceof Date ? timestamp : new Date(timestamp);
    this.metadata = { ...metadata };
  }

  #validate(message, level, source) {
    if (!message || typeof message !== "string") {
      throw new Error("Log message is required and must be a string");
    }
    if (!level || !LogEntry.VALID_LEVELS.includes(level.toUpperCase())) {
      throw new Error(
        `Invalid log level: "${level}". Must be one of: ${LogEntry.VALID_LEVELS.join(", ")}`
      );
    }
    if (!source || typeof source !== "string") {
      throw new Error("Log source is required and must be a string");
    }
  }

  static #generateId() {
    return `log_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
  }

  /**
   * Parses a raw log string into a LogEntry.
   * Expected format: "[TIMESTAMP] LEVEL SOURCE - Message"
   * Example: "[2024-01-15T10:30:00Z] ERROR auth-service - Login failed"
   */
  static fromString(raw) {
    const regex = /^\[(.+?)\]\s+(\w+)\s+([\w-]+)\s+-\s+(.+)$/;
    const match = raw.trim().match(regex);

    if (!match) {
      throw new Error(`Cannot parse log string: "${raw}"`);
    }

    const [, timestamp, level, source, message] = match;
    return new LogEntry({
      message,
      level,
      source,
      timestamp: new Date(timestamp),
    });
  }

  /**
   * Serializes the log entry to a plain object.
   */
  toJSON() {
    return {
      id: this.id,
      message: this.message,
      level: this.level,
      source: this.source,
      timestamp: this.timestamp.toISOString(),
      metadata: this.metadata,
    };
  }

  /**
   * Formats the log entry as a readable string.
   */
  toString() {
    return `[${this.timestamp.toISOString()}] ${this.level} ${this.source} - ${this.message}`;
  }
}

module.exports = LogEntry;
