/**
 * In-memory store for log entries with querying capabilities.
 */
class LogStore {
  #logs = [];
  #maxSize;

  /**
   * @param {Object}  [options]
   * @param {number}  [options.maxSize=10000] - Maximum number of logs to retain
   */
  constructor({ maxSize = 10000 } = {}) {
    this.#maxSize = maxSize;
  }

  /** Returns the current number of stored logs. */
  get size() {
    return this.#logs.length;
  }

  /**
   * Adds one or more LogEntry objects to the store.
   * Evicts oldest entries when maxSize is exceeded.
   * @param  {...import('./LogEntry')} entries
   * @returns {number} New total count
   */
  add(...entries) {
    this.#logs.push(...entries);

    // Evict oldest if over capacity
    if (this.#logs.length > this.#maxSize) {
      const overflow = this.#logs.length - this.#maxSize;
      this.#logs.splice(0, overflow);
    }

    return this.#logs.length;
  }

  /**
   * Queries logs matching ALL provided filter criteria.
   * @param {Object}   [filters]
   * @param {string}   [filters.level]     - Exact level match
   * @param {string}   [filters.source]    - Exact source match
   * @param {string}   [filters.search]    - Substring search in message
   * @param {Date}     [filters.from]      - Start of time range (inclusive)
   * @param {Date}     [filters.to]        - End of time range (inclusive)
   * @param {number}   [filters.limit=100] - Max results to return
   * @param {number}   [filters.offset=0]  - Number of results to skip
   * @returns {import('./LogEntry')[]}
   */
  query(filters = {}) {
    const { level, source, search, from, to, limit = 100, offset = 0 } = filters;

    let results = this.#logs;

    if (level) {
      const upperLevel = level.toUpperCase();
      results = results.filter((log) => log.level === upperLevel);
    }

    if (source) {
      results = results.filter((log) => log.source === source);
    }

    if (search) {
      const lowerSearch = search.toLowerCase();
      results = results.filter((log) =>
        log.message.toLowerCase().includes(lowerSearch)
      );
    }

    if (from) {
      const fromDate = from instanceof Date ? from : new Date(from);
      results = results.filter((log) => log.timestamp >= fromDate);
    }

    if (to) {
      const toDate = to instanceof Date ? to : new Date(to);
      results = results.filter((log) => log.timestamp <= toDate);
    }

    return results.slice(offset, offset + limit);
  }

  /**
   * Returns aggregated counts grouped by log level.
   * @returns {Object<string, number>}
   */
  getStats() {
    const stats = { total: this.#logs.length };

    for (const log of this.#logs) {
      stats[log.level] = (stats[log.level] || 0) + 1;
    }

    return stats;
  }

  /** Removes all stored logs. */
  clear() {
    this.#logs = [];
  }

  /**
   * Exports all logs as a JSON-serializable array.
   * @returns {Object[]}
   */
  export() {
    return this.#logs.map((log) => log.toJSON());
  }
}

module.exports = LogStore;
