const LogEntry = require("./LogEntry");
const LogStore = require("./LogStore");

/**
 * Main log ingestion engine.
 * Accepts raw strings, objects, or batches — validates, stores, and notifies.
 */
class LogIngester {
  #store;
  #listeners;
  #batchQueue;
  #batchTimer;
  #batchSize;
  #flushInterval;

  /**
   * @param {Object}  [options]
   * @param {number}  [options.maxSize=10000]       - Max log retention
   * @param {number}  [options.batchSize=50]        - Flush batch at this count
   * @param {number}  [options.flushInterval=5000]  - Auto-flush interval (ms)
   */
  constructor({ maxSize = 10000, batchSize = 50, flushInterval = 5000 } = {}) {
    this.#store = new LogStore({ maxSize });
    this.#listeners = new Map();
    this.#batchQueue = [];
    this.#batchSize = batchSize;
    this.#flushInterval = flushInterval;
    this.#batchTimer = null;
  }

  /** Returns the underlying store's size. */
  get size() {
    return this.#store.size;
  }

  // ──────────────────────────── Ingestion ────────────────────────────

  /**
   * Ingest a single log from an object.
   * @param {Object} data - { message, level, source, timestamp?, metadata? }
   * @returns {LogEntry}  The created entry
   */
  ingest(data) {
    const entry = new LogEntry(data);
    this.#store.add(entry);
    this.#emit("log", entry);
    this.#emit(`log:${entry.level.toLowerCase()}`, entry);
    return entry;
  }

  /**
   * Ingest a log from a raw formatted string.
   * @param {string} raw
   * @returns {LogEntry}
   */
  ingestRaw(raw) {
    const entry = LogEntry.fromString(raw);
    this.#store.add(entry);
    this.#emit("log", entry);
    this.#emit(`log:${entry.level.toLowerCase()}`, entry);
    return entry;
  }

  /**
   * Queue a log for batch processing.
   * Flushes automatically when batchSize is reached.
   * @param {Object} data
   */
  enqueue(data) {
    this.#batchQueue.push(data);

    if (this.#batchQueue.length >= this.#batchSize) {
      this.flush();
    }
  }

  /**
   * Immediately processes all queued logs.
   * @returns {{ success: LogEntry[], errors: { data: Object, error: string }[] }}
   */
  flush() {
    const queued = [...this.#batchQueue];
    this.#batchQueue = [];

    const success = [];
    const errors = [];

    for (const data of queued) {
      try {
        const entry = this.ingest(data);
        success.push(entry);
      } catch (err) {
        errors.push({ data, error: err.message });
      }
    }

    this.#emit("flush", { success: success.length, errors: errors.length });
    return { success, errors };
  }

  /** Starts automatic periodic flushing. */
  startAutoFlush() {
    if (this.#batchTimer) return;
    this.#batchTimer = setInterval(() => this.flush(), this.#flushInterval);
  }

  /** Stops automatic periodic flushing. */
  stopAutoFlush() {
    if (this.#batchTimer) {
      clearInterval(this.#batchTimer);
      this.#batchTimer = null;
    }
  }

  // ──────────────────────────── Querying ─────────────────────────────

  /**
   * Query stored logs with filters.
   * @param {Object} filters - See LogStore.query()
   * @returns {LogEntry[]}
   */
  query(filters) {
    return this.#store.query(filters);
  }

  /** Get count-by-level statistics. */
  getStats() {
    return this.#store.getStats();
  }

  /** Export all logs as JSON-serializable array. */
  export() {
    return this.#store.export();
  }

  /** Clear all stored logs and queued batches. */
  clear() {
    this.#store.clear();
    this.#batchQueue = [];
  }

  // ──────────────────────────── Events ───────────────────────────────

  /**
   * Subscribe to an event.
   * Events: "log", "log:debug", "log:info", "log:warn", "log:error", "log:fatal", "flush"
   * @param {string}   event
   * @param {Function} callback
   */
  on(event, callback) {
    if (!this.#listeners.has(event)) {
      this.#listeners.set(event, []);
    }
    this.#listeners.get(event).push(callback);
  }

  /**
   * Unsubscribe from an event.
   * @param {string}   event
   * @param {Function} callback
   */
  off(event, callback) {
    const cbs = this.#listeners.get(event);
    if (cbs) {
      this.#listeners.set(
        event,
        cbs.filter((cb) => cb !== callback)
      );
    }
  }

  #emit(event, data) {
    const cbs = this.#listeners.get(event);
    if (cbs) {
      cbs.forEach((cb) => cb(data));
    }
  }
}

module.exports = LogIngester;
