This example provides a robust migration helper that tracks performance, errors, throughput, and aggregated statistics throughout a data migration process.

```javascript
// ─── Metrics Collector ───────────────────────────────────────────────
class MetricsCollector {
  #buckets = new Map();
  #timers = new Map();
  #histograms = new Map();

  constructor() {
    this.counters = new Map();
    this.gauges = new Map();
    this.timestamps = { started: null, finished: null };
  }

  // Increment a named counter by a given amount
  increment(name, amount = 1) {
    const current = this.counters.get(name) || 0;
    this.counters.set(name, current + amount);
  }

  // Set an absolute gauge value (e.g., "currentBatchSize")
  gauge(name, value) {
    this.gauges.set(name, value);
  }

  // Start a named timer
  startTimer(name) {
    this.#timers.set(name, process.hrtime.bigint());
  }

  // Stop a named timer → returns elapsed ms and stores in histogram
  stopTimer(name) {
    const start = this.#timers.get(name);
    if (!start) throw new Error(`Timer "${name}" was never started`);

    const elapsed = Number(process.hrtime.bigint() - start) / 1e6; // ms
    this.#timers.delete(name);

    // Store every observation in a histogram bucket
    if (!this.#histograms.has(name)) {
      this.#histograms.set(name, []);
    }
    this.#histograms.get(name).push(elapsed);

    return elapsed;
  }

  // Record a value directly into a time-bucketed series (per-second)
  recordBucket(name, value) {
    const bucketKey = Math.floor(Date.now() / 1000);
    if (!this.#buckets.has(name)) {
      this.#buckets.set(name, new Map());
    }
    const series = this.#buckets.get(name);
    const arr = series.get(bucketKey) || [];
    arr.push(value);
    series.set(bucketKey, arr);
  }

  // Compute aggregated stats for a histogram
  summarizeHistogram(name) {
    const values = this.#histograms.get(name);
    if (!values || values.length === 0) return null;

    const sorted = [...values].sort((a, b) => a - b);
    const sum = sorted.reduce((s, v) => s + v, 0);

    return {
      count: sorted.length,
      min: sorted[0],
      max: sorted[sorted.length - 1],
      mean: sum / sorted.length,
      median: sorted[Math.floor(sorted.length / 2)],
      p95: sorted[Math.floor(sorted.length * 0.95)],
      p99: sorted[Math.floor(sorted.length * 0.99)],
    };
  }

  // Compute throughput from a bucketed series (values per second)
  summarizeBuckets(name) {
    const series = this.#buckets.get(name);
    if (!series || series.size === 0) return null;

    const perSecond = [...series.entries()].map(([ts, vals]) => ({
      timestamp: ts,
      count: vals.length,
      total: vals.reduce((s, v) => s + v, 0),
    }));

    const counts = perSecond.map((b) => b.count);
    return {
      buckets: perSecond.length,
      avgPerSecond: counts.reduce((s, c) => s + c, 0) / counts.length,
      peakPerSecond: Math.max(...counts),
    };
  }

  // Full snapshot
  snapshot() {
    return {
      counters: Object.fromEntries(this.counters),
      gauges: Object.fromEntries(this.gauges),
      timestamps: { ...this.timestamps },
      histograms: Object.fromEntries(
        [...this.#histograms.keys()].map((k) => [k, this.summarizeHistogram(k)])
      ),
      throughput: Object.fromEntries(
        [...this.#buckets.keys()].map((k) => [k, this.summarizeBuckets(k)])
      ),
    };
  }
}

// ─── Error Journal ───────────────────────────────────────────────────
class ErrorJournal {
  constructor(maxEntries = 500) {
    this.entries = [];
    this.maxEntries = maxEntries;
    this.categoryCounts = new Map();
  }

  record(record, error, category = "general") {
    this.categoryCounts.set(
      category,
      (this.categoryCounts.get(category) || 0) + 1
    );

    if (this.entries.length < this.maxEntries) {
      this.entries.push({
        timestamp: new Date().toISOString(),
        category,
        recordId: record?.id ?? null,
        message: error.message,
        stack: error.stack?.split("\n").slice(0, 3).join("\n"),
      });
    }
  }

  summary() {
    return {
      totalErrors: [...this.categoryCounts.values()].reduce((s, c) => s + c, 0),
      byCategory: Object.fromEntries(this.categoryCounts),
      sampleErrors: this.entries.slice(0, 10),
    };
  }
}

// ─── Migration Helper ────────────────────────────────────────────────
class MigrationHelper {
  /**
   * @param {object}   opts
   * @param {function} opts.reader       - async generator yielding source records
   * @param {function} opts.transformer  - async (record, ctx) => transformed record
   * @param {function} opts.writer       - async (batch) => void
   * @param {number}   [opts.batchSize=100]
   * @param {number}   [opts.concurrency=4]
   * @param {number}   [opts.retries=2]
   * @param {function} [opts.onProgress] - (progressInfo) => void
   */
  constructor({
    reader,
    transformer,
    writer,
    batchSize = 100,
    concurrency = 4,
    retries = 2,
    onProgress,
  }) {
    this.reader = reader;
    this.transformer = transformer;
    this.writer = writer;
    this.batchSize = batchSize;
    this.concurrency = concurrency;
    this.retries = retries;
    this.onProgress = onProgress;

    this.metrics = new MetricsCollector();
    this.errors = new ErrorJournal();
    this._aborted = false;
  }

  // ── Public API ─────────────────────────────────────────────────

  async run() {
    this.metrics.timestamps.started = new Date().toISOString();
    let batch = [];

    try {
      for await (const record of this.reader()) {
        if (this._aborted) break;

        this.metrics.increment("records.read");

        // ── Transform with retry ────────────────────────────
        const transformed = await this.#transformWithRetry(record);
        if (transformed === null) continue; // skip failures

        batch.push(transformed);
        this.metrics.gauge("batch.currentSize", batch.length);

        // ── Flush when batch is full ────────────────────────
        if (batch.length >= this.batchSize) {
          await this.#flushBatch(batch);
          batch = [];
        }
      }

      // Flush remaining records
      if (batch.length > 0) {
        await this.#flushBatch(batch);
      }
    } finally {
      this.metrics.timestamps.finished = new Date().toISOString();
    }

    return this.report();
  }

  abort() {
    this._aborted = true;
  }

  report() {
    const snap = this.metrics.snapshot();
    const elapsed =
      (new Date(snap.timestamps.finished) -
        new Date(snap.timestamps.started)) /
      1000;

    return {
      status: this._aborted ? "aborted" : "completed",
      duration: `${elapsed.toFixed(2)}s`,
      records: {
        read: snap.counters["records.read"] || 0,
        transformed: snap.counters["records.transformed"] || 0,
        written: snap.counters["records.written"] || 0,
        skipped: snap.counters["records.skipped"] || 0,
        failed: snap.counters["records.failed"] || 0,
      },
      batches: {
        total: snap.counters["batches.total"] || 0,
        retried: snap.counters["batches.retried"] || 0,
      },
      timing: {
        transform: snap.histograms["transform"] ?? null,
        writeBatch: snap.histograms["writeBatch"] ?? null,
      },
      throughput: snap.throughput["writes"] ?? null,
      errors: this.errors.summary(),
    };
  }

  // ── Internals ──────────────────────────────────────────────────

  async #transformWithRetry(record) {
    for (let attempt = 0; attempt <= this.retries; attempt++) {
      try {
        this.metrics.startTimer("transform");
        const result = await this.transformer(record, {
          attempt,
          metrics: this.metrics,
        });
        this.metrics.stopTimer("transform");
        this.metrics.increment("records.transformed");
        return result;
      } catch (err) {
        this.metrics.stopTimer("transform");

        if (attempt === this.retries) {
          this.errors.record(record, err, "transform");
          this.metrics.increment("records.failed");
          return null;
        }
        this.metrics.increment("records.transform.retries");
        await this.#delay(100 * 2 ** attempt); // exponential back-off
      }
    }
  }

  async #flushBatch(batch) {
    const batchNum = (this.metrics.counters.get("batches.total") || 0) + 1;

    for (let attempt = 0; attempt <= this.retries; attempt++) {
      try {
        this.metrics.startTimer("writeBatch");
        await this.writer(batch);
        const elapsed = this.metrics.stopTimer("writeBatch");

        this.metrics.increment("batches.total");
        this.metrics.increment("records.written", batch.length);
        this.metrics.recordBucket("writes", batch.length);
        this.metrics.gauge("batch.currentSize", 0);

        this.#emitProgress(batchNum, batch.length, elapsed);
        return;
      } catch (err) {
        this.metrics.stopTimer("writeBatch");

        if (attempt === this.retries) {
          // Record every item in the failed batch
          for (const item of batch) {
            this.errors.record(item, err, "write");
            this.metrics.increment("records.failed");
          }
          this.metrics.increment("batches.total");
          return;
        }
        this.metrics.increment("batches.retried");
        await this.#delay(200 * 2 ** attempt);
      }
    }
  }

  #emitProgress(batchNum, batchLen, elapsed) {
    if (!this.onProgress) return;
    this.onProgress({
      batch: batchNum,
      batchSize: batchLen,
      writeMs: elapsed.toFixed(2),
      totalRead: this.metrics.counters.get("records.read") || 0,
      totalWritten: this.metrics.counters.get("records.written") || 0,
      totalFailed: this.metrics.counters.get("records.failed") || 0,
    });
  }

  #delay(ms) {
    return new Promise((r) => setTimeout(r, ms));
  }
}

// ─── Demo Usage ──────────────────────────────────────────────────────

async function main() {
  // Simulated source: async generator yielding 530 user records
  async function* fakeReader() {
    for (let i = 1; i <= 530; i++) {
      yield { id: i, name: `user_${i}`, score: Math.random() * 100 };
    }
  }

  // Simulated transform: normalise score, occasionally throw
  async function fakeTransformer(record) {
    await delay(randomBetween(1, 5));        // simulate work
    if (record.id % 170 === 0) {
      throw new Error("Corrupt record");     // simulate sporadic failure
    }
    return {
      ...record,
      score: Math.round(record.score * 100) / 100,
      migratedAt: new Date().toISOString(),
    };
  }

  // Simulated writer: batch insert, occasionally throw
  async function fakeWriter(batch) {
    await delay(randomBetween(10, 40));       // simulate I/O
    if (Math.random() < 0.05) {
      throw new Error("DB timeout");          // simulate transient failure
    }
  }

  // ── Run the migration ──────────────────────────────────────────
  const helper = new MigrationHelper({
    reader: fakeReader,
    transformer: fakeTransformer,
    writer: fakeWriter,
    batchSize: 50,
    concurrency: 4,
    retries: 2,
    onProgress: (info) => {
      process.stdout.write(
        `\r  Batch #${info.batch} | written: ${info.totalWritten} | ` +
        `failed: ${info.totalFailed} | last write: ${info.writeMs}ms`
      );
    },
  });

  console.log("Migration started…\n");
  const report = await helper.run();
  console.log("\n\n── Migration Report ────────────────────────────────");
  console.log(JSON.stringify(report, null, 2));
}

// Utilities
function delay(ms) {
  return new Promise((r) => setTimeout(r, ms));
}
function randomBetween(lo, hi) {
  return Math.floor(Math.random() * (hi - lo + 1)) + lo;
}

main().catch(console.error);
