## `moderator.js` — Core Logic

```js
import { readFileSync, writeFileSync, existsSync } from "fs";
import { resolve, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const CONFIG_PATH = resolve(__dirname, "config.json");
const DATA_PATH = resolve(__dirname, "data.json");

export class Moderator {
  constructor() {
    this.config = JSON.parse(readFileSync(CONFIG_PATH, "utf-8"));
    this.data = existsSync(DATA_PATH)
      ? JSON.parse(readFileSync(DATA_PATH, "utf-8"))
      : { users: {}, log: [] };
  }

  // ── Persistence ──────────────────────────────────────────

  save() {
    writeFileSync(DATA_PATH, JSON.stringify(this.data, null, 2));
  }

  saveConfig() {
    writeFileSync(CONFIG_PATH, JSON.stringify(this.config, null, 2));
  }

  // ── Message Scanning ─────────────────────────────────────

  scanMessage(username, message) {
    const lower = message.toLowerCase();
    const found = this.config.blockedWords.filter((w) =>
      lower.includes(w.toLowerCase())
    );

    if (found.length === 0) {
      return { clean: true, message: "✅ Message is clean." };
    }

    // record the strike
    this.#addStrike(username, message, found);

    const strikes = this.data.users[username].strikes;
    const action = this.#determineAction(strikes);

    return {
      clean: false,
      flaggedWords: found,
      strikes,
      action,
      message: `🚩 Flagged ${found.length} word(s): [${found.join(", ")}] → ` +
               `User "${username}" now has ${strikes} strike(s) → Action: ${action.toUpperCase()}`
    };
  }

  // ── Blocklist Management ─────────────────────────────────

  addWord(word) {
    const lower = word.toLowerCase();
    if (this.config.blockedWords.includes(lower)) {
      return `"${lower}" is already on the blocklist.`;
    }
    this.config.blockedWords.push(lower);
    this.saveConfig();
    return `➕ Added "${lower}" to the blocklist.`;
  }

  removeWord(word) {
    const lower = word.toLowerCase();
    const idx = this.config.blockedWords.indexOf(lower);
    if (idx === -1) {
      return `"${lower}" is not on the blocklist.`;
    }
    this.config.blockedWords.splice(idx, 1);
    this.saveConfig();
    return `➖ Removed "${lower}" from the blocklist.`;
  }

  listWords() {
    const words = this.config.blockedWords;
    if (words.length === 0) return "Blocklist is empty.";
    return `📋 Blocklist (${words.length}):\n` +
           words.map((w, i) => `   ${i + 1}. ${w}`).join("\n");
  }

  // ── User Management ──────────────────────────────────────

  userStatus(username) {
    const user = this.data.users[username];
    if (!user) return `No records for "${username}".`;

    return [
      `👤 User: ${username}`,
      `   Strikes : ${user.strikes}`,
      `   Status  : ${user.status}`,
      `   History : ${user.history.length} flagged message(s)`
    ].join("\n");
  }

  resetUser(username) {
    if (!this.data.users[username]) {
      return `No records for "${username}".`;
    }
    this.data.users[username] = { strikes: 0, status: "clean", history: [] };
    this.save();
    return `🔄 Reset all records for "${username}".`;
  }

  listUsers() {
    const entries = Object.entries(this.data.users);
    if (entries.length === 0) return "No user records yet.";

    return "👥 Users:\n" +
      entries
        .map(([name, u]) => `   ${name} — ${u.strikes} strike(s) — ${u.status}`)
        .join("\n");
  }

  // ── Log ──────────────────────────────────────────────────

  showLog(count = 10) {
    const recent = this.data.log.slice(-count);
    if (recent.length === 0) return "Log is empty.";

    return `📜 Last ${recent.length} log entries:\n` +
      recent.map((e) =>
        `   [${e.time}] ${e.user}: "${e.message}" → ${e.action}`
      ).join("\n");
  }

  // ── Private Helpers ──────────────────────────────────────

  #addStrike(username, message, flaggedWords) {
    if (!this.data.users[username]) {
      this.data.users[username] = { strikes: 0, status: "clean", history: [] };
    }

    const user = this.data.users[username];
    user.strikes += 1;
    user.status = this.#determineAction(user.strikes);
    user.history.push({
      message,
      flaggedWords,
      time: new Date().toISOString()
    });

    this.data.log.push({
      user: username,
      message,
      action: user.status,
      time: new Date().toISOString()
    });

    this.save();
  }

  #determineAction(strikes) {
    const { warningThreshold, actions } = this.config;

    if (strikes >= warningThreshold) return actions["3"] || "ban";
    if (strikes >= 2) return actions["2"] || "mute";
    return actions["1"] || "warn";
  }
}
```

## `index.js` — CLI Interface

```js
#!/usr/bin/env node

import { createInterface } from "readline";
import { Moderator } from "./moderator.js";

const mod = new Moderator();

const rl = createInterface({
  input: process.stdin,
  output: process.stdout,
  prompt: "mod> "
});

// ── Help Text ────────────────────────────────────────────────

const HELP = `
╔══════════════════════════════════════════════════════╗
║              CHAT MODERATION CLI                     ║
╠══════════════════════════════════════════════════════╣
║  check  <user> <message>   Scan a message            ║
║  add    <word>             Add word to blocklist      ║
║  remove <word>             Remove word from blocklist ║
║  list                      Show blocklist             ║
║  user   <username>         Show user status           ║
║  reset  <username>         Reset user strikes         ║
║  users                     List all tracked users     ║
║  log    [count]            Show recent log entries    ║
║  help                      Show this help             ║
║  exit                      Quit                       ║
╚══════════════════════════════════════════════════════╝
`;

// ── Command Router ───────────────────────────────────────────

function handleCommand(line) {
  const trimmed = line.trim();
  if (!trimmed) return;

  // split into: command, ...args
  const [command, ...rest] = trimmed.split(/\s+/);

  switch (command.toLowerCase()) {
    case "check": {
      const user = rest[0];
      const message = rest.slice(1).join(" ");
      if (!user || !message) {
        console.log("Usage: check <user> <message>");
        break;
      }
      console.log(mod.scanMessage(user, message));
      break;
    }

    case "add": {
      if (!rest[0]) { console.log("Usage: add <word>"); break; }
      console.log(mod.addWord(rest[0]));
      break;
    }

    case "remove": {
      if (!rest[0]) { console.log("Usage: remove <word>"); break; }
      console.log(mod.removeWord(rest[0]));
      break;
    }

    case "list":
      console.log(mod.listWords());
      break;

    case "user": {
      if (!rest[0]) { console.log("Usage: user <username>"); break; }
      console.log(mod.userStatus(rest[0]));
      break;
    }

    case "reset": {
      if (!rest[0]) { console.log("Usage: reset <username>"); break; }
      console.log(mod.resetUser(rest[0]));
      break;
    }

    case "users":
      console.log(mod.listUsers());
      break;

    case "log": {
      const count = parseInt(rest[0], 10) || 10;
      console.log(mod.showLog(count));
      break;
    }

    case "help":
      console.log(HELP);
      break;

    case "exit":
    case "quit":
      console.log("Goodbye.");
      rl.close();
      process.exit(0);
      break;

    default:
      console.log(`Unknown command: "${command}". Type "help" for options.`);
  }
}

// ── Start ────────────────────────────────────────────────────

console.log(HELP);
rl.prompt();

rl.on("line", (line) => {
  handleCommand(line);
  rl.prompt();
});

rl.on("close", () => process.exit(0));
