/**
 * Custom error hierarchy for granular error handling.
 * Each error carries a machine-readable `code` for programmatic checks.
 */

export class ParserError extends Error {
  /**
   * @param {string} message  – Human-readable description.
   * @param {string} code     – Machine-readable error code.
   * @param {Object} [context] – Extra data for debugging.
   */
  constructor(message, code, context = {}) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
    this.context = Object.freeze({ ...context });
    this.timestamp = new Date().toISOString();

    // Capture a clean stack trace (V8 only)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  toJSON() {
    return {
      name: this.name,
      code: this.code,
      message: this.message,
      context: this.context,
      timestamp: this.timestamp,
    };
  }
}

export class FileReadError extends ParserError {
  constructor(message, context = {}) {
    super(message, "FILE_READ_ERROR", context);
  }
}

export class JsonSyntaxError extends ParserError {
  constructor(message, context = {}) {
    super(message, "JSON_SYNTAX_ERROR", context);
  }
}

export class ValidationError extends ParserError {
  /** @param {Array} errors – Individual validation failures. */
  constructor(message, errors = [], context = {}) {
    super(message, "VALIDATION_ERROR", { ...context, errors });
    this.errors = Object.freeze([...errors]);
  }
}

export class FileSizeError extends ParserError {
  constructor(message, context = {}) {
    super(message, "FILE_SIZE_ERROR", context);
  }
}

export class NestingDepthError extends ParserError {
  constructor(message, context = {}) {
    super(message, "NESTING_DEPTH_ERROR", context);
  }
}

export class TimeoutError extends ParserError {
  constructor(message, context = {}) {
    super(message, "TIMEOUT_ERROR", context);
  }
}
