```javascript
import { NestingDepthError } from "../errors/ParserErrors.js";

/**
 * Recursively sanitise a parsed JSON value:
 *   – trims strings
 *   – rejects dangerous keys (__proto__, constructor, prototype)
 *   – enforces a maximum nesting depth
 *
 * @param {*}      value
 * @param {number} maxDepth
 * @param {number} [currentDepth=0]
 * @returns {*} Sanitised clone of `value`.
 */
export function sanitize(value, maxDepth, currentDepth = 0) {
  if (currentDepth > maxDepth) {
    throw new NestingDepthError(
      `Nesting depth exceeds maximum of ${maxDepth}`,
      { maxDepth, currentDepth },
    );
  }

  if (value === null || value === undefined) return value;

  if (typeof value === "string") return value.trim();

  if (typeof value === "number" || typeof value === "boolean") return value;

  if (Array.isArray(value)) {
    return value.map((item) => sanitize(item, maxDepth, currentDepth + 1));
  }

  if (typeof value === "object") {
    const cleaned = Object.create(null); // no inherited props
    for (const key of Object.keys(value)) {
      if (isDangerousKey(key)) continue; // silently drop
      cleaned[key] = sanitize(value[key], maxDepth, currentDepth + 1);
    }
    return cleaned;
  }

  return value;
}

const DANGEROUS_KEYS = new Set(["__proto__", "constructor", "prototype"]);

/**
 * @param {string} key
 * @returns {boolean}
 */
function isDangerousKey(key) {
  return DANGEROUS_KEYS.has(key);
}
