export class Document {
  #id;
  #type;
  #version;
  #metadata;
  #content;
  #parsedAt;
  #checksum;

  /**
   * @param {Object} params
   * @param {string} params.id
   * @param {string} params.type
   * @param {string} params.version
   * @param {Object} params.metadata
   * @param {*}      params.content
   * @param {string} [params.checksum]
   */
  constructor({ id, type, version, metadata, content, checksum = null }) {
    this.#id = id;
    this.#type = type;
    this.#version = version;
    this.#metadata = Object.freeze({ ...metadata });
    this.#content = deepFreeze(structuredClone(content));
    this.#parsedAt = new Date().toISOString();
    this.#checksum = checksum;
  }

  get id()       { return this.#id; }
  get type()     { return this.#type; }
  get version()  { return this.#version; }
  get metadata() { return this.#metadata; }
  get content()  { return this.#content; }
  get parsedAt() { return this.#parsedAt; }
  get checksum() { return this.#checksum; }

  /** Structured serialisation for logging / persistence. */
  toJSON() {
    return {
      id: this.#id,
      type: this.#type,
      version: this.#version,
      metadata: this.#metadata,
      content: this.#content,
      parsedAt: this.#parsedAt,
      checksum: this.#checksum,
    };
  }

  toString() {
    return `Document(${this.#id}, type=${this.#type}, v=${this.#version})`;
  }
}

// ── helpers ─────────────────────────────────────────────────

function deepFreeze(obj) {
  if (obj === null || typeof obj !== "object") return obj;
  Object.freeze(obj);
  for (const value of Object.values(obj)) deepFreeze(value);
  return obj;
}
