/**
 * AJV-backed schema validator.
 * Compiles the schema once and re-uses the compiled validate function.
 */
export class SchemaValidator {
  #validate;

  constructor() {
    const ajv = new Ajv({ allErrors: true, strict: true });
    addFormats(ajv);
    this.#validate = ajv.compile(SchemaValidator.documentSchema);
  }

  /**
   * @param {Object} data – Parsed JSON to validate.
   * @returns {{ valid: boolean, errors: Array }}
   */
  validate(data) {
    const valid = this.#validate(data);

    if (!valid) {
      const errors = (this.#validate.errors || []).map((err) => ({
        field: err.instancePath || "/",
        message: err.message,
        params: err.params,
      }));

      logger.debug("Schema validation failed", { errorCount: errors.length });
      return { valid: false, errors };
    }

    logger.debug("Schema validation passed");
    return { valid: true, errors: [] };
  }

  /**
   * Convenience wrapper that throws on failure.
   * @param {Object} data
   * @throws {ValidationError}
   */
  assertValid(data) {
    const { valid, errors } = this.validate(data);
    if (!valid) {
      throw new ValidationError(
        `Document failed schema validation (${errors.length} error(s))`,
        errors,
      );
    }
  }

