   */
  async readFile(filePath) {
    logger.info("Reading JSON file", { filePath });

    await this.#assertFileSize(filePath);

    let raw;
    try {
      raw = await readFile(filePath, { encoding: this.#config.encoding });
    } catch (err) {
      throw new FileReadError(`Cannot read file: ${err.message}`, {
        filePath,
        originalError: err.code,
      });
    }

