```javascript
class TaskScheduler {
  constructor() {
    this.tasks = [];
    this.running = false;
    this.timers = new Map();       // Fix 5: Track timers for cleanup
    this.taskIdCounter = 0;
  }

  // ─── Fix 1: Correct priority sort (higher priority first) ───
  addTask(name, callback, priority = 0, delay = 0) {
    const task = {
      id: ++this.taskIdCounter,
      name,
      callback,
      priority,
      delay,
      status: "pending",
      createdAt: Date.now(),
    };

    this.tasks.push(task);
    // Higher priority number = executed first (descending sort)
    this.tasks.sort((a, b) => b.priority - a.priority);

    console.log(`📋 Task added: "${name}" (priority: ${priority}, delay: ${delay}ms)`);
    return task;
  }

  // ─── Fix 2: Properly handle async callbacks with error handling ───
  async executeTask(task) {
    if (task.status === "cancelled") {
      console.log(`⏭️  Skipping cancelled task: "${task.name}"`);
      return;
    }

    task.status = "running";
    console.log(`▶️  Executing: "${task.name}"`);

    try {
      await task.callback();                 // ✅ Await async callbacks
      task.status = "completed";
      console.log(`✅ Completed: "${task.name}"`);
    } catch (error) {
      task.status = "failed";
      console.error(`❌ Failed: "${task.name}" — ${error.message}`);
    }
  }

  // ─── Fix 3 & 4: Properly await delayed tasks in sequence ───
  async run() {
    this.running = true;
    console.log("🚀 Scheduler started\n");

    // Create a snapshot to avoid issues with mutations during iteration
    const pendingTasks = this.tasks.filter(t => t.status === "pending");

    for (const task of pendingTasks) {
      if (!this.running) {
        console.log("⛔ Scheduler stopped mid-run");
        break;
      }

      if (task.status === "cancelled") continue;

      // ✅ Await the delay using a Promise wrapper
      if (task.delay > 0) {
        await this._delayedExecute(task);
      } else {
        await this.executeTask(task);        // ✅ Await execution
      }
    }

    if (this.running) {
      console.log("\n🏁 All tasks processed");
      this.running = false;
    }
  }

  // ─── Helper: Promisified delay with timer tracking ───
  _delayedExecute(task) {
    return new Promise((resolve) => {
      console.log(`⏳ Waiting ${task.delay}ms for: "${task.name}"`);

      const timerId = setTimeout(async () => {
        this.timers.delete(task.id);
        if (task.status === "cancelled") {
          console.log(`⏭️  Skipping cancelled task: "${task.name}"`);
        } else {
          await this.executeTask(task);
        }
        resolve();
      }, task.delay);

      // ✅ Fix 5: Store timer reference for cleanup
      this.timers.set(task.id, timerId);
    });
  }

  // ─── Fix 5: Cancel task AND clear its timer ───
  cancelTask(name) {
    const task = this.tasks.find(
      (t) => t.name === name && t.status === "pending"
    );

    if (!task) {
      console.log(`⚠️  Task "${name}" not found or not pending`);
      return false;
    }

    task.status = "cancelled";

    // ✅ Clear the associated timer if one exists
    if (this.timers.has(task.id)) {
      clearTimeout(this.timers.get(task.id));
      this.timers.delete(task.id);
    }

    console.log(`🚫 Cancelled: "${name}"`);
    return true;
  }

  // ─── Fix 6: Remove completed without index shifting bug ───
  removeCompleted() {
    const before = this.tasks.length;
    // ✅ Filter creates a new array — no index shifting issues
    this.tasks = this.tasks.filter((t) => t.status !== "completed");
    const removed = before - this.tasks.length;
    console.log(`🧹 Removed ${removed} completed task(s)`);
    return removed;
  }

  // ─── Fix 7: Stop scheduler AND clear all pending timers ───
  stop() {
    this.running = false;

    // ✅ Clear ALL pending timers
    for (const [taskId, timerId] of this.timers) {
      clearTimeout(timerId);
      const task = this.tasks.find((t) => t.id === taskId);
      if (task && task.status === "pending") {
        task.status = "cancelled";
      }
    }
    this.timers.clear();

    console.log("⛔ Scheduler stopped — all timers cleared");
  }

  // ─── Fix 8: Return a deep copy to prevent external mutation ───
  getTaskList() {
    return this.tasks.map((task) => ({
      ...task,
      callback: undefined,    // Don't expose callback references
    }));
  }

  // ─── Bonus: Useful status summary ───
  getStatus() {
    const counts = { pending: 0, running: 0, completed: 0, failed: 0, cancelled: 0 };
    this.tasks.forEach((t) => counts[t.status]++);
    return { running: this.running, totalTasks: this.tasks.length, ...counts };
  }
}
