## Fixed Code (all bugs resolved)

```rust
// ✅ FIXED VERSION

use actix_web::{web, App, HttpServer, HttpResponse, HttpRequest, middleware};
use actix_cors::Cors;
use serde::{Deserialize, Serialize};
use std::sync::atomic::{AtomicU64, Ordering};
use tokio::sync::RwLock;                     // FIX 1: Use tokio's async RwLock
use regex::Regex;
use log::{info, warn, error};

// ─── Models ───────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ChatMessage {
    #[serde(skip_deserializing)]             // server assigns this
    id: Option<u64>,

    #[serde(alias = "user_name")]            // FIX 3: Accept both field names
    username: String,

    content: String,

    #[serde(default)]                        // FIX: default to false
    flagged: bool,

    #[serde(default)]
    deleted: bool,                           // FIX 17: soft-delete flag

    #[serde(skip_deserializing)]
    timestamp: u64,                          // FIX 4: numeric epoch
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ModerationAction {
    moderator: String,
    target_user: String,
    action: ActionType,
    reason: String,
    timestamp: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
enum ActionType {
    Ban,
    Unban,
    DeleteMessage,
    FlagMessage,
}

#[derive(Deserialize)]
struct BanRequest {
    target_user: String,
    reason: String,
}

#[derive(Deserialize)]
struct MessageQuery {
    #[serde(default)]                        // FIX 5: Optional with default
    flagged_only: Option<bool>,

    #[serde(default = "default_limit")]
    limit: usize,
}

fn default_limit() -> usize { 50 }

// ─── Shared Application State ─────────────────────────────────────────

// No need for Clone derive since we wrap it in web::Data (uses Arc)
struct AppState {
    messages: RwLock<Vec<ChatMessage>>,       // FIX 2: No nested Mutex
    banned_users: RwLock<Vec<String>>,
    action_log: RwLock<Vec<ModerationAction>>,// FIX 2: Flat RwLock
    next_id: AtomicU64,                       // FIX 10: Atomic counter
    profanity_regex: Regex,                   // FIX 9: Pre-compiled regex
}

impl AppState {
    fn new(profanity_words: &[&str]) -> Self {
        let pattern = profanity_words
            .iter()
            .map(|w| regex::escape(w))        // escape special chars
            .collect::<Vec<_>>()
            .join("|");

        let profanity_regex = Regex::new(&format!("(?i)({})", pattern))
            .expect("Invalid profanity regex");

        Self {
            messages: RwLock::new(Vec::new()),
            banned_users: RwLock::new(Vec::new()),
            action_log: RwLock::new(Vec::new()),
            next_id: AtomicU64::new(1),
            profanity_regex,
        }
    }
}

// ─── Error type ───────────────────────────────────────────────────────

#[derive(Debug, Serialize)]
struct ApiError {
    error: String,
    code: u16,
}

impl ApiError {
    fn new(code: u16, msg: impl Into<String>) -> HttpResponse {
        let status = actix_web::http::StatusCode::from_u16(code)
            .unwrap_or(actix_web::http::StatusCode::INTERNAL_SERVER_ERROR);
        HttpResponse::build(status).json(ApiError {
            error: msg.into(),
            code,
        })
    }
}

// ─── Middleware: Simple API-key auth ──────────────────────────────────

fn extract_moderator(req: &HttpRequest) -> Result<String, HttpResponse> {
    // FIX 14: Require an API key / moderator identity
    req.headers()
        .get("X-Moderator-Key")
        .and_then(|v| v.to_str().ok())
        .map(String::from)
        .ok_or_else(|| ApiError::new(401, "Missing X-Moderator-Key header"))
}

fn current_timestamp() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

// ─── Handlers ─────────────────────────────────────────────────────────

// FIX 6: Added `async` keyword
async fn post_message(
    state: web::Data<AppState>,
    msg: web::Json<ChatMessage>,
) -> HttpResponse {
    // Validate input
    let msg = msg.into_inner();
    if msg.username.trim().is_empty() || msg.content.trim().is_empty() {
        return ApiError::new(400, "username and content are required");
    }

    if msg.content.len() > 2000 {
        return ApiError::new(400, "Message exceeds 2000 character limit");
    }

    // FIX 8: Drop read lock before acquiring write lock
    {
        let banned = state.banned_users.read().await;       // FIX 7: no unwrap
        if banned.iter().any(|u| u.eq_ignore_ascii_case(&msg.username)) {
            return ApiError::new(403, "User is banned");
        }
    } // <-- read lock dropped here

    let flagged = state.profanity_regex.is_match(&msg.content); // FIX 9: pre-compiled

    let new_msg = ChatMessage {
        id: Some(state.next_id.fetch_add(1, Ordering::SeqCst)), // FIX 10: atomic
        username: msg.username,
        content: msg.content,
        flagged,
        deleted: false,
        timestamp: current_timestamp(),
    };

    let mut messages = state.messages.write().await;
    messages.push(new_msg.clone());

    info!("New message #{} from {}", new_msg.id.unwrap(), new_msg.username);

    // FIX 11: Return proper JSON with Content-Type automatically set by .json()
    HttpResponse::Created().json(&new_msg)
}

async fn get_messages(
    state: web::Data<AppState>,
    query: web::Query<MessageQuery>,
) -> HttpResponse {
    let messages = state.messages.read().await;

    let flagged_only = query.flagged_only.unwrap_or(false); // FIX 5

    let results: Vec<&ChatMessage> = messages
        .iter()
        .filter(|m| !m.deleted)                              // skip soft-deleted
        .filter(|m| !flagged_only || m.flagged)
        .take(query.limit)                                   // FIX 12: applied .take()
        .collect();

    HttpResponse::Ok().json(results)
}

// FIX 13: Changed to POST (state-changing action)
async fn ban_user(
    req: HttpRequest,
    state: web::Data<AppState>,
    body: web::Json<BanRequest>,
) -> HttpResponse {
    // FIX 14: Authenticate the moderator
    let moderator = match extract_moderator(&req) {
        Ok(m) => m,
        Err(resp) => return resp,
    };

    if body.target_user.trim().is_empty() {
        return ApiError::new(400, "target_user is required");
    }

    let mut banned = state.banned_users.write().await;

    // FIX 15: Check for duplicate ban
    if banned.iter().any(|u| u.eq_ignore_ascii_case(&body.target_user)) {
        return ApiError::new(409, "User is already banned");
    }

    banned.push(body.target_user.clone());
    drop(banned); // release lock early

    // Log the moderation action
    let action = ModerationAction {
        moderator,
        target_user: body.target_user.clone(),
        action: ActionType::Ban,
        reason: body.reason.clone(),
        timestamp: current_timestamp(),
    };
    state.action_log.write().await.push(action);

    warn!("User '{}' banned. Reason: {}", body.target_user, body.reason);

    HttpResponse::Ok().json(serde_json::json!({
        "status": "banned",
        "user": body.target_user
    }))
}

// FIX 16: Path parameter is u64, with proper error handling
async fn delete_message(
    req: HttpRequest,
    state: web::Data<AppState>,
    path: web::Path<u64>,
) -> HttpResponse {
    let moderator = match extract_moderator(&req) {
        Ok(m) => m,
        Err(resp) => return resp,
    };

    let id = path.into_inner();
    let mut messages = state.messages.write().await;

    // FIX 17: Soft-delete instead of removing by index
    match messages.iter_mut().find(|m| m.id == Some(id)) {
        Some(msg) => {
            if msg.deleted {
                return ApiError::new(410, "Message already deleted");
            }
            msg.deleted = true;

            // Log the action
            let action = ModerationAction {
                moderator,
                target_user: msg.username.clone(),
                action: ActionType::DeleteMessage,
                reason: format!("Deleted message #{id}"),
                timestamp: current_timestamp(),
            };
            drop(messages); // release lock before acquiring another
            state.action_log.write().await.push(action);

            info!("Message #{id} soft-deleted");
            HttpResponse::Ok().json(serde_json::json!({ "status": "deleted", "id": id }))
        }
        None => ApiError::new(404, format!("Message #{id} not found")),
    }
}

async fn get_audit_log(
    req: HttpRequest,
    state: web::Data<AppState>,
) -> HttpResponse {
    if let Err(resp) = extract_moderator(&req) {
        return resp;
    }

    let log = state.action_log.read().await;
    HttpResponse::Ok().json(&*log)
}

// Health check endpoint
async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({ "status": "ok" }))
}

// ─── Server entrypoint ───────────────────────────────────────────────

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init_from_env(env_logger::Env::default().default_filter_or("info"));

    let state = web::Data::new(AppState::new(&[
        "badword1", "badword2", "slur1",
    ]));

    info!("Starting chat moderation API on http://127.0.0.1:8080");

    HttpServer::new(move || {
        // FIX 18: Add CORS middleware
        let cors = Cors::default()
            .allowed_origin("http://localhost:3000")
            .allowed_methods(vec!["GET", "POST", "DELETE"])
            .allowed_headers(vec!["Content-Type", "X-Moderator-Key"])
            .max_age(3600);

        App::new()
            .app_data(state.clone())
            .wrap(cors)
            .wrap(middleware::Logger::default())      // request logging
            .route("/health", web::get().to(health))
            .route("/messages", web::get().to(get_messages))
            .route("/messages", web::post().to(post_message))
            .route("/messages/{id}", web::delete().to(delete_message))
            .route("/ban", web::post().to(ban_user))  // FIX 13: POST not GET
            .route("/audit-log", web::get().to(get_audit_log))
    })
    .bind("127.0.0.1:8080")?
    .workers(4)
    .run()
    .await
}
