## The Fixed & Improved Code

```rust
// ✅ FIXED VERSION — all bugs resolved with detailed comments

use std::collections::HashMap;

// ── Data types ──────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Eq)]
enum Severity {
    Warning,
    Mute,
    Ban,
}

/// Represents a single violation found during linting.
#[derive(Debug, Clone)]
struct Violation {
    rule_name: String,
    severity: Severity,
    matched_text: String,
    position: usize, // byte offset in the *original* message
}

/// A configurable moderation rule that matches patterns in messages.
#[derive(Debug, Clone)]
struct LinterRule {
    name: String,
    patterns: Vec<String>,
    severity: Severity,
    case_sensitive: bool,
    max_strikes: u32,
}

// ── Moderator ───────────────────────────────────────────────────────

struct ChatModerator {
    rules: Vec<LinterRule>,
    user_strikes: HashMap<String, u32>,
    max_message_length: usize,
    spam_interval_ms: u64,
    last_message_times: HashMap<String, u64>,
}

impl ChatModerator {
    /// Constructor — no bugs here in the original, kept as-is.
    fn new(max_message_length: usize, spam_interval_ms: u64) -> Self {
        Self {
            rules: Vec::new(),
            user_strikes: HashMap::new(),
            max_message_length,          // field shorthand (idiomatic)
            spam_interval_ms,
            last_message_times: HashMap::new(),
        }
    }

    // ── FIX 2: Accept owned `LinterRule` so we can push it ──────────
    fn add_rule(&mut self, rule: LinterRule) {
        //                         ^^^^^^^^^^  was `&LinterRule`
        self.rules.push(rule);
    }

    // ── FIX 3: `&mut self` because we mutate strikes + timestamps ───
    fn lint_message(
        &mut self,
        //^^^^^^^^ was `&self`
        user_id: &str,
        message: &str,
        timestamp: u64,
    ) -> Vec<Violation> {
        let mut violations = Vec::new();

        // ── Length check ─────────────────────────────────────────────
        // FIX 4: Use strict `>` — a message of *exactly* max length is OK
        if message.len() > self.max_message_length {
            //              ^ was `>=`
            violations.push(Violation {
                rule_name: "message_too_long".into(),
                severity: Severity::Warning,
                matched_text: format!("length: {}", message.len()),
                position: 0,
            });
        }

        // ── Spam check ──────────────────────────────────────────────
        if let Some(&last_time) = self.last_message_times.get(user_id) {
            //       ^ added `&` to copy the u64 out
            // FIX 6: Guard against underflow with `saturating_sub`
            let diff = timestamp.saturating_sub(last_time);
            //                   ^^^^^^^^^^^^^^ was plain `-`
            if diff < self.spam_interval_ms {
                violations.push(Violation {
                    rule_name: "spam_detected".into(),
                    severity: Severity::Mute,
                    matched_text: format!("interval: {}ms", diff),
                    position: 0,
                });
            }
        }
        // FIX 5 & 7: Now legal because `self` is `&mut`
        self.last_message_times
            .insert(user_id.to_string(), timestamp);

        // ── Pattern matching ─────────────────────────────────────────
        for rule in &self.rules {
            // FIX 8: Lowercase when case_sensitive is FALSE (logic was inverted)
            let check_message = if rule.case_sensitive {
                message.to_string()        // keep original case
            } else {
                message.to_lowercase()     // normalize
            };

            for pattern in &rule.patterns {
                // FIX 9: Also lowercase the pattern for case-insensitive matching
                let check_pattern = if rule.case_sensitive {
                    pattern.clone()
                } else {
                    pattern.to_lowercase()
                };

                // FIX 10: Search in the *normalized* copies, report correct position
                if let Some(pos) = check_message.find(check_pattern.as_str()) {
                    //  ^ Combined `contains` + `find` into one `if let`
                    violations.push(Violation {
                        rule_name: rule.name.clone(),
                        severity: rule.severity.clone(),
                        matched_text: pattern.clone(),
                        position: pos,
                    });
                }
            }
        }

        // ── Strike bookkeeping (done AFTER collecting violations) ────
        // FIX 11: Moved outside the immutable borrow of `self.rules`
        if !violations.is_empty() {
            let strikes = self
                .user_strikes
                .entry(user_id.to_string())
                .or_insert(0);
            *strikes += violations.len() as u32;
        }

        // ── Severity escalation ──────────────────────────────────────
        // FIX 12: Use `>=` so users with MORE than 3 strikes are also banned
        if let Some(&strikes) = self.user_strikes.get(user_id) {
            if strikes >= 3 {
                //       ^^ was `==`
                for v in violations.iter_mut() {
                    v.severity = Severity::Ban;
                }
            }
        }

        violations
    }

    // ── FIX 13: Return an *owned* String, not `&str` ────────────────
    fn get_report(&self, user_id: &str) -> String {
        //                                  ^^^^^^ was `&str`
        format!(
            "User {} has {} strike(s)",
            user_id,
            self.user_strikes.get(user_id).unwrap_or(&0)
        )
        // No dangling reference — we return the String by value
    }

    /// Helper: reset a user's strikes (useful after a timeout expires).
    fn reset_strikes(&mut self, user_id: &str) {
        self.user_strikes.remove(user_id);
    }
}

// ── Tests ────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    fn make_moderator() -> ChatModerator {
        let mut m = ChatModerator::new(500, 1000);
        m.add_rule(LinterRule {
