            name: "profanity".into(),
            patterns: vec!["badword".into(), "offensive".into()],
            severity: Severity::Warning,
            case_sensitive: false,
            max_strikes: 3,
        });
        m.add_rule(LinterRule {
            name: "caps_lock".into(),
            patterns: vec![],          // placeholder — custom check
            severity: Severity::Warning,
            case_sensitive: true,
            max_strikes: 5,
        });
        m
    }

