    fn test_profanity_case_insensitive() {
        let mut moderator = make_moderator();
        // "Badword" should match "badword" because case_sensitive = false
        let v = moderator.lint_message("user1", "This is a Badword test", 1000);
        assert_eq!(v.len(), 1);
        assert_eq!(v[0].rule_name, "profanity");
