    }

    #[test]
    fn test_spam_detection() {
        let mut moderator = make_moderator();
        let _ = moderator.lint_message("user1", "hello", 1000);
        let v = moderator.lint_message("user1", "hello again", 1500); // 500ms < 1000ms
        assert!(v.iter().any(|v| v.rule_name == "spam_detected"));
    }

    #[test]
    fn test_no_spam_after_interval() {
        let mut moderator = make_moderator();
        let _ = moderator.lint_message("user1", "hello", 1000);
        let v = moderator.lint_message("user1", "hello again", 2500); // 1500ms >= 1000ms
        assert!(!v.iter().any(|v| v.rule_name == "spam_detected"));
    }

    #[test]
    fn test_strike_escalation_to_ban() {
        let mut moderator = make_moderator();
        // Accumulate 3+ strikes
        let _ = moderator.lint_message("user1", "badword", 1000);
        let _ = moderator.lint_message("user1", "offensive", 3000);
        let v = moderator.lint_message("user1", "badword again", 5000);
        assert!(v.iter().all(|v| v.severity == Severity::Ban));
    }

    #[test]
    fn test_report_generation() {
        let mut moderator = make_moderator();
        let _ = moderator.lint_message("user1", "badword", 1000);
        let report = moderator.get_report("user1");
        assert!(report.contains("1 strike"));
    }

    #[test]
    fn test_timestamp_underflow_safe() {
        let mut moderator = make_moderator();
        // Simulate out-of-order timestamps (shouldn't panic)
        let _ = moderator.lint_message("user1", "hello", 5000);
        let v = moderator.lint_message("user1", "world", 3000); // earlier timestamp!
        // saturating_sub → diff = 0, which IS less than interval → spam detected
        assert!(v.iter().any(|v| v.rule_name == "spam_detected"));
    }
