## Bug Summary Table

| # | Bug | Root Cause | Fix |
|---|-----|-----------|-----|
| 1 | (cosmetic) | Verbose field init | Used **field shorthand** |
| 2 | `push(&LinterRule)` | Borrowed value can't be moved into `Vec` | Accept **owned** `LinterRule` |
| 3 | Mutating through `&self` | `user_strikes` + `last_message_times` need mutation | Changed to **`&mut self`** |
| 4 | `>= max_length` | Off-by-one blocks exact-length messages | Changed to **`>`** |
| 5 | Insert on `&self` | Immutable borrow | Fixed by #3 (`&mut self`) |
| 6 | `timestamp - last_time` | u64 underflow if timestamps arrive out of order | **`saturating_sub`** |
| 7 | Same as #5 | Immutable borrow | Fixed by #3 |
| 8 | Case logic inverted | `to_lowercase` when `case_sensitive == true` | **Swapped branches** |
| 9 | Pattern not normalized | Lowercase message but uppercase pattern → no match | **Lowercase pattern** too |
| 10 | Redundant `contains`+`find` | Double search, possible mismatch | Combined into **`if let Some`** |
| 11 | Mutate strikes inside `&self.rules` loop | Borrow conflict | Moved strike update **after** loop |
| 12 | `strikes == 3` | Users with 4+ strikes escape the ban | Changed to **`>=`** |
| 13 | Return `&str` from local `String` |

# Rust Migration Helper with Cache Invalidation

This example demonstrates a migration system that coordinates schema/data migrations with cache invalidation strategies.

```rust
use std::collections::HashMap;
use std::fmt;
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

// ─── Error Types ────────────────────────────────────────────────────────────

#[derive(Debug)]
enum MigrationError {
    CacheError(String),
    MigrationFailed { id: String, reason: String },
    LockPoisoned(String),
    AlreadyApplied(String),
    DependencyNotMet { migration: String, dependency: String },
}

impl fmt::Display for MigrationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::CacheError(msg) => write!(f, "Cache error: {msg}"),
            Self::MigrationFailed { id, reason } => {
                write!(f, "Migration '{id}' failed: {reason}")
            }
            Self::LockPoisoned(msg) => write!(f, "Lock poisoned: {msg}"),
            Self::AlreadyApplied(id) => write!(f, "Migration '{id}' already applied"),
            Self::DependencyNotMet {
                migration,
                dependency,
            } => write!(
                f,
                "Migration '{migration}' requires '{dependency}' to be applied first"
            ),
        }
    }
}

impl std::error::Error for MigrationError {}

type Result<T> = std::result::Result<T, MigrationError>;

// ─── Cache Invalidation Strategy ────────────────────────────────────────────

/// Determines *how* cache entries are removed during a migration.
#[derive(Debug, Clone)]
enum InvalidationStrategy {
    /// Wipe the entire cache.
    FullFlush,
    /// Remove only entries matching specific key prefixes.
    SelectiveByPrefix(Vec<String>),
    /// Remove specific keys.
    SpecificKeys(Vec<String>),
    /// Bump a version namespace so old keys become unreachable.
    VersionBump { namespace: String },
    /// Remove entries matching a predicate description (simulated).
    Pattern(String),
    /// No cache invalidation needed.
    None,
}

// ─── Cache Entry ────────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct CacheEntry {
    value: String,
    version: u64,
    created_at: Instant,
    ttl: Option<Duration>,
}

impl CacheEntry {
    fn new(value: String, version: u64, ttl: Option<Duration>) -> Self {
        Self {
            value,
            version,
            created_at: Instant::now(),
            ttl,
        }
    }

    fn is_expired(&self) -> bool {
        self.ttl
            .map(|ttl| self.created_at.elapsed() > ttl)
            .unwrap_or(false)
    }
}

// ─── Cache Store ────────────────────────────────────────────────────────────

/// Thread-safe in-memory cache with namespace versioning.
struct CacheStore {
    entries: RwLock<HashMap<String, CacheEntry>>,
    namespace_versions: RwLock<HashMap<String, u64>>,
    stats: RwLock<CacheStats>,
}

#[derive(Debug, Default, Clone)]
struct CacheStats {
    hits: u64,
    misses: u64,
    invalidations: u64,
    flushes: u64,
}

impl CacheStore {
    fn new() -> Self {
        Self {
            entries: RwLock::new(HashMap::new()),
            namespace_versions: RwLock::new(HashMap::new()),
            stats: RwLock::new(CacheStats::default()),
        }
    }

    /// Build a versioned key: `namespace:v{version}:{raw_key}`
    fn versioned_key(&self, namespace: &str, key: &str) -> Result<String> {
        let versions = self
            .namespace_versions
            .read()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;
        let ver = versions.get(namespace).copied().unwrap_or(1);
        Ok(format!("{namespace}:v{ver}:{key}"))
    }

    fn get(&self, key: &str) -> Result<Option<String>> {
        let entries = self
            .entries
            .read()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;

        let mut stats = self
            .stats
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;

        match entries.get(key) {
            Some(entry) if !entry.is_expired() => {
                stats.hits += 1;
                Ok(Some(entry.value.clone()))
            }
            _ => {
                stats.misses += 1;
                Ok(None)
            }
        }
    }

    fn set(&self, key: String, value: String, ttl: Option<Duration>) -> Result<()> {
        let version = {
            let versions = self
                .namespace_versions
                .read()
                .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;
            // Extract namespace from key (everything before first ':')
            let ns = key.split(':').next().unwrap_or("default");
            versions.get(ns).copied().unwrap_or(1)
        };

        let mut entries = self
            .entries
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;
        entries.insert(key, CacheEntry::new(value, version, ttl));
        Ok(())
    }

    fn flush_all(&self) -> Result<u64> {
        let mut entries = self
            .entries
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;
        let count = entries.len() as u64;
        entries.clear();

        let mut stats = self
            .stats
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;
        stats.flushes += 1;
        stats.invalidations += count;

        Ok(count)
    }

    fn invalidate_by_prefix(&self, prefix: &str) -> Result<u64> {
        let mut entries = self
            .entries
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;

        let keys_to_remove: Vec<String> = entries
            .keys()
            .filter(|k| k.starts_with(prefix))
            .cloned()
            .collect();

        let count = keys_to_remove.len() as u64;
        for key in &keys_to_remove {
            entries.remove(key);
        }

        let mut stats = self
            .stats
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;
        stats.invalidations += count;

        Ok(count)
    }

    fn invalidate_keys(&self, keys: &[String]) -> Result<u64> {
        let mut entries = self
            .entries
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;

        let mut count = 0u64;
        for key in keys {
            if entries.remove(key).is_some() {
                count += 1;
            }
        }

        let mut stats = self
            .stats
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;
        stats.invalidations += count;

        Ok(count)
    }

    fn bump_namespace_version(&self, namespace: &str) -> Result<u64> {
        let mut versions = self
            .namespace_versions
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;

        let new_version = versions.get(namespace).copied().unwrap_or(1) + 1;
        versions.insert(namespace.to_string(), new_version);

        // Old versioned keys are now unreachable (lazy invalidation).
        // Optionally prune them eagerly:
        let prefix = format!("{namespace}:v");
        let current_prefix = format!("{namespace}:v{new_version}:");
        drop(versions); // release write lock before acquiring entries lock

        let mut entries = self
            .entries
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;

        let stale: Vec<String> = entries
            .keys()
            .filter(|k| k.starts_with(&prefix) && !k.starts_with(&current_prefix))
            .cloned()
            .collect();

        let pruned = stale.len() as u64;
        for key in &stale {
            entries.remove(key);
        }

        let mut stats = self
            .stats
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;
        stats.invalidations += pruned;

        Ok(new_version)
    }

    fn invalidate_by_pattern(&self, pattern: &str) -> Result<u64> {
        let mut entries = self
            .entries
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;

        let keys_to_remove: Vec<String> = entries
            .keys()
            .filter(|k| k.contains(pattern))
            .cloned()
            .collect();

        let count = keys_to_remove.len() as u64;
        for key in &keys_to_remove {
            entries.remove(key);
        }

        let mut stats = self
            .stats
            .write()
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))?;
        stats.invalidations += count;

        Ok(count)
    }

    fn stats(&self) -> Result<CacheStats> {
        self.stats
            .read()
            .map(|s| s.clone())
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))
    }

    fn entry_count(&self) -> Result<usize> {
        self.entries
            .read()
            .map(|e| e.len())
            .map_err(|e| MigrationError::LockPoisoned(e.to_string()))
    }
}

// ─── Migration Trait ────────────────────────────────────────────────────────

trait Migration: Send + Sync {
    /// Unique identifier (e.g. "20240101_add_user_roles").
    fn id(&self) -> &str;

    /// Human-readable description.
    fn description(&self) -> &str;

    /// IDs of migrations that must be applied before this one.
    fn dependencies(&self) -> Vec<&str> {
        vec![]
    }

    /// Which cache entries should be invalidated.
    fn invalidation_strategy(&self) -> InvalidationStrategy;

    /// Apply the forward migration (schema change, data transform, etc.).
    fn up(&self, ctx: &mut MigrationContext) -> Result<()>;

    /// Roll back the migration.
    fn down(&self, ctx: &mut MigrationContext) -> Result<()>;
}

// ─── Migration Context ──────────────────────────────────────────────────────

/// Passed into each migration so it can record what it did.
struct MigrationContext {
    migration_id: String,
    changes: Vec<String>,
    data_store: HashMap<String, String>, // simulates a DB
}

impl MigrationContext {
    fn new(migration_id: &str, data_store: HashMap<String, String>) -> Self {
        Self {
            migration_id: migration_id.to_string(),
            changes: Vec::new(),
            data_store,
        }
    }

    fn record_change(&mut self, description: &str) {
        self.changes.push(description.to_string());
        println!("  [{}] {}", self.migration_id, description);
    }

    fn set_data(&mut self, key: &str, value: &str) {
        self.data_store.insert(key.to_string(), value.to_string());
    }

    fn remove_data(&mut self, key: &str) {
        self.data_store.remove(key);
    }
}

// ─── Migration Record ───────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct MigrationRecord {
    id: String,
    applied_at: u64,       // unix seconds
    duration_ms: u128,
    keys_invalidated: u64,
    status: MigrationStatus,
}

#[derive(Debug, Clone, PartialEq)]
enum MigrationStatus {
    Applied,
    RolledBack,
    Failed(String),
}

// ─── Migration Helper ───────────────────────────────────────────────────────

struct MigrationHelper {
    cache: Arc<CacheStore>,
    migrations: Vec<Box<dyn Migration>>,
    history: Vec<MigrationRecord>,
    data_store: HashMap<String, String>,
}

impl MigrationHelper {
    fn new(cache: Arc<CacheStore>) -> Self {
        Self {
            cache,
            migrations: Vec::new(),
            history: Vec::new(),
            data_store: HashMap::new(),
        }
    }

    fn register(&mut self, migration: Box<dyn Migration>) {
        self.migrations.push(migration);
    }

    /// Check that all declared dependencies have been applied.
    fn check_dependencies(&self, migration: &dyn Migration) -> Result<()> {
        let applied: Vec<&str> = self
            .history
            .iter()
            .filter(|r| r.status == MigrationStatus::Applied)
            .map(|r| r.id.as_str())
            .collect();

        for dep in migration.dependencies() {
            if !applied.contains(&dep) {
                return Err(MigrationError::DependencyNotMet {
                    migration: migration.id().to_string(),
                    dependency: dep.to_string(),
                });
            }
        }
        Ok(())
    }

    fn is_applied(&self, id: &str) -> bool {
        self.history
            .iter()
            .any(|r| r.id == id && r.status == MigrationStatus::Applied)
    }

    /// Execute the invalidation strategy and return how many keys were removed.
    fn execute_invalidation(&self, strategy: &InvalidationStrategy) -> Result<u64> {
        match strategy {
            InvalidationStrategy::FullFlush => {
                println!("  → Flushing entire cache");
                self.cache.flush_all()
            }
            InvalidationStrategy::SelectiveByPrefix(prefixes) => {
                let mut total = 0;
                for prefix in prefixes {
                    println!("  → Invalidating prefix '{prefix}'");
                    total += self.cache.invalidate_by_prefix(prefix)?;
                }
                Ok(total)
            }
            InvalidationStrategy::SpecificKeys(keys) => {
                println!("  → Invalidating {} specific keys", keys.len());
                self.cache.invalidate_keys(keys)
            }
            InvalidationStrategy::VersionBump { namespace } => {
                let new_ver = self.cache.bump_namespace_version(namespace)?;
                println!("  → Bumped namespace '{namespace}' to v{new_ver}");
                Ok(0) // lazy invalidation, stale keys pruned in the background
            }
            InvalidationStrategy::Pattern(pat) => {
                println!("  → Invalidating pattern '*{pat}*'");
                self.cache.invalidate_by_pattern(pat)
            }
            InvalidationStrategy::None => {
                println!("  → No cache invalidation needed");
                Ok(0)
            }
        }
    }

    /// Apply a single migration by ID.
    fn apply_one(&mut self, id: &str) -> Result<MigrationRecord> {
        if self.is_applied(id) {
            return Err(MigrationError::AlreadyApplied(id.to_string()));
        }

