# Config Parser with Cache Invalidation in JavaScript

## Full Implementation

```javascript
import { readFileSync, watchFile, unwatchFile, statSync } from 'fs';
import { createHash } from 'crypto';
import { EventEmitter } from 'events';
import { extname, resolve } from 'path';

// ─── Cache Entry ────────────────────────────────────────────────
class CacheEntry {
  constructor(data, hash, options = {}) {
    this.data = Object.freeze(structuredClone(data)); // immutable snapshot
    this.hash = hash;
    this.version = options.version ?? 1;
    this.createdAt = Date.now();
    this.lastAccessed = Date.now();
    this.ttl = options.ttl ?? Infinity;
    this.hits = 0;
    this.dependencies = new Set(options.dependencies ?? []);
  }

  get isExpired() {
    return Date.now() - this.createdAt > this.ttl;
  }

  touch() {
    this.lastAccessed = Date.now();
    this.hits++;
  }
}

// ─── Invalidation Strategies ────────────────────────────────────
const InvalidationStrategy = {
  /** Expire after a fixed time-to-live */
  TTL: 'ttl',
  /** Expire when file content hash changes */
  HASH: 'hash',
  /** Expire when a version tag bumps */
  VERSION: 'version',
  /** Expire when any dependency is invalidated */
  DEPENDENCY: 'dependency',
  /** Expire via filesystem watcher */
  WATCH: 'watch',
};

// ─── Built-in Format Parsers ────────────────────────────────────
const formatParsers = {
  '.json': (content) => JSON.parse(content),

  '.ini': (content) => {
    const result = {};
    let currentSection = result;

    for (const raw of content.split('\n')) {
      const line = raw.trim();
      if (!line || line.startsWith('#') || line.startsWith(';')) continue;

      const sectionMatch = line.match(/^\[(.+)]$/);
      if (sectionMatch) {
        const section = sectionMatch[1].trim();
        result[section] = result[section] ?? {};
        currentSection = result[section];
        continue;
      }

      const kvMatch = line.match(/^([^=]+)=(.*)$/);
      if (kvMatch) {
        const key = kvMatch[1].trim();
        const val = kvMatch[2].trim();
        currentSection[key] = parseIniValue(val);
      }
    }
    return result;
  },

  '.env': (content) => {
    const result = {};
    for (const raw of content.split('\n')) {
      const line = raw.trim();
      if (!line || line.startsWith('#')) continue;

      const eqIdx = line.indexOf('=');
      if (eqIdx === -1) continue;

      const key = line.slice(0, eqIdx).trim();
      let val = line.slice(eqIdx + 1).trim();
      // strip surrounding quotes
      if ((val.startsWith('"') && val.endsWith('"')) ||
          (val.startsWith("'") && val.endsWith("'"))) {
        val = val.slice(1, -1);
      }
      result[key] = val;
    }
    return result;
  },
};

function parseIniValue(val) {
  if (val === 'true') return true;
  if (val === 'false') return false;
  if (val === '') return '';
  const num = Number(val);
  return Number.isNaN(num) ? val : num;
}

// ─── Main Config Parser ─────────────────────────────────────────
class ConfigParser extends EventEmitter {
  #cache = new Map();          // path → CacheEntry
  #watchers = new Map();       // path → fs watcher cleanup
  #customParsers = new Map();  // extension → parser fn
  #defaults;

  /**
   * @param {object} options
   * @param {number}  options.defaultTTL      - ms before auto-expire (default: none)
   * @param {string[]} options.strategies     - active invalidation strategies
   * @param {number}  options.maxCacheSize    - max entries before LRU eviction
   * @param {object}  options.defaults        - fallback values merged into every config
   */
  constructor(options = {}) {
    super();
    this.options = {
      defaultTTL: options.defaultTTL ?? Infinity,
      strategies: options.strategies ?? [
        InvalidationStrategy.HASH,
        InvalidationStrategy.TTL,
      ],
      maxCacheSize: options.maxCacheSize ?? 100,
      defaults: options.defaults ?? {},
    };
    this.#defaults = Object.freeze(structuredClone(this.options.defaults));
  }

  // ── Public API ──────────────────────────────────────────────

  /**
   * Parse (and cache) a config file.
   * Returns cached data when still valid; re-reads otherwise.
   */
  load(filePath, overrides = {}) {
    const absPath = resolve(filePath);
    const cached = this.#cache.get(absPath);

    if (cached && this.#isValid(absPath, cached)) {
      cached.touch();
      this.emit('cache:hit', { path: absPath, hits: cached.hits });
      return this.#mergeDefaults(cached.data, overrides);
    }

    // Cache miss or stale → parse fresh
    return this.#parseAndCache(absPath, overrides);
  }

  /**
   * Force-invalidate one path (or all when path is omitted).
   */
  invalidate(filePath) {
    if (filePath) {
      const absPath = resolve(filePath);
      this.#evict(absPath, 'manual');
    } else {
      for (const key of this.#cache.keys()) {
        this.#evict(key, 'manual:all');
      }
    }
  }

  /**
   * Bump the expected version for a path → next load will re-parse.
   */
  bumpVersion(filePath) {
    const absPath = resolve(filePath);
    const entry = this.#cache.get(absPath);
    if (entry) {
      // Setting version to 0 guarantees a version-strategy mismatch
      this.#evict(absPath, 'version-bump');
    }
  }

  /**
   * Register a custom parser for a file extension.
   *   parser.registerParser('.toml', tomlParseFunction);
   */
  registerParser(extension, parserFn) {
    if (typeof parserFn !== 'function') {
      throw new TypeError('Parser must be a function');
    }
    this.#customParsers.set(extension, parserFn);
    // Invalidate any cached files of this type so they re-parse
    for (const [path, entry] of this.#cache) {
      if (extname(path) === extension) {
        this.#evict(path, 'parser-replaced');
      }
    }
  }

  /**
   * Snapshot of cache statistics.
   */
  get stats() {
    const entries = [...this.#cache.entries()].map(([path, e]) => ({
      path,
      hits: e.hits,
      age: Date.now() - e.createdAt,
      expired: e.isExpired,
    }));
    return {
      size: this.#cache.size,
      entries,
    };
  }

  /**
   * Tear down watchers and clear cache.
   */
  destroy() {
    for (const [path, cleanup] of this.#watchers) {
      cleanup();
    }
    this.#watchers.clear();
    this.#cache.clear();
    this.removeAllListeners();
  }

  // ── Internals ───────────────────────────────────────────────

  #parseAndCache(absPath, overrides) {
    const content = readFileSync(absPath, 'utf-8');
    const hash = this.#computeHash(content);
    const data = this.#parseContent(absPath, content);

    const entry = new CacheEntry(data, hash, {
      ttl: this.options.defaultTTL,
    });

    this.#enforceMaxSize();
    this.#cache.set(absPath, entry);

    // Set up fs watcher if strategy requests it
    if (this.#strategyActive(InvalidationStrategy.WATCH)) {
      this.#watch(absPath);
    }

    this.emit('cache:miss', { path: absPath });
    return this.#mergeDefaults(data, overrides);
  }

  #parseContent(absPath, content) {
    const ext = extname(absPath);
    const parser =
      this.#customParsers.get(ext) ??
      formatParsers[ext];

    if (!parser) {
      throw new Error(
        `No parser registered for "${ext}" — use registerParser()`,
      );
    }

    try {
      return parser(content);
    } catch (err) {
      throw new Error(`Failed to parse ${absPath}: ${err.message}`);
    }
  }

  /**
   * Determine whether a cache entry is still valid
   * by running every active strategy.
   */
  #isValid(absPath, entry) {
    const strategies = this.options.strategies;

    // TTL check
    if (this.#strategyActive(InvalidationStrategy.TTL) && entry.isExpired) {
      this.emit('invalidate', { path: absPath, reason: 'ttl' });
      return false;
    }

    // Hash check — re-read file and compare digest
    if (this.#strategyActive(InvalidationStrategy.HASH)) {
      try {
        const content = readFileSync(absPath, 'utf-8');
        const currentHash = this.#computeHash(content);
        if (currentHash !== entry.hash) {
          this.emit('invalidate', { path: absPath, reason: 'hash' });
          return false;
        }
      } catch {
        // File deleted or unreadable → invalidate
        this.emit('invalidate', { path: absPath, reason: 'read-error' });
        return false;
      }
    }

    // Dependency check — if any dep is missing from cache it was evicted
    if (this.#strategyActive(InvalidationStrategy.DEPENDENCY)) {
      for (const dep of entry.dependencies) {
        if (!this.#cache.has(dep)) {
          this.emit('invalidate', { path: absPath, reason: 'dependency', dep });
          return false;
        }
      }
    }

    return true;
  }

  #evict(absPath, reason) {
    if (!this.#cache.has(absPath)) return;

    this.#cache.delete(absPath);
    this.emit('invalidate', { path: absPath, reason });

    // Cascade: invalidate anything that depends on this path
    if (this.#strategyActive(InvalidationStrategy.DEPENDENCY)) {
      for (const [otherPath, otherEntry] of this.#cache) {
        if (otherEntry.dependencies.has(absPath)) {
          this.#evict(otherPath, `cascade:${reason}`);
        }
      }
    }

    // Clean up watcher
    if (this.#watchers.has(absPath)) {
      this.#watchers.get(absPath)();
      this.#watchers.delete(absPath);
    }
  }

  /** LRU eviction when cache is full */
  #enforceMaxSize() {
    while (this.#cache.size >= this.options.maxCacheSize) {
      let oldest = null;
      let oldestKey = null;

      for (const [key, entry] of this.#cache) {
        if (!oldest || entry.lastAccessed < oldest.lastAccessed) {
          oldest = entry;
          oldestKey = key;
        }
      }
      if (oldestKey) this.#evict(oldestKey, 'lru');
    }
  }

  #watch(absPath) {
    if (this.#watchers.has(absPath)) return;

    const onChange = () => {
      this.#evict(absPath, 'fs-change');
    };

    watchFile(absPath, { interval: 500 }, onChange);
    this.#watchers.set(absPath, () => unwatchFile(absPath, onChange));
  }

  #computeHash(content) {
    return createHash('sha256').update(content).digest('hex');
  }

  #mergeDefaults(data, overrides) {
    return { ...this.#defaults, ...data, ...overrides };
  }

  #strategyActive(name) {
    return this.options.strategies.includes(name);
  }
}

// ─── Export ─────────────────────────────────────────────────────
export { ConfigParser, InvalidationStrategy, CacheEntry };
