use std::fmt;
use thiserror::Error;

/// Whether a failed operation can be retried.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Retryable {
    Yes,
    No,
}

/// Top-level pipeline errors.
#[derive(Error, Debug)]
pub enum PipelineError {
    #[error("Stage '{stage}' failed: {source}")]
    StageExecution {
        stage: String,
        source: StageError,
        retryable: Retryable,
    },

    #[error("Pipeline configuration error: {0}")]
    Configuration(String),

    #[error("Retry exhausted for stage '{stage}' after {attempts} attempts: {last_error}")]
    RetryExhausted {
        stage: String,
        attempts: u32,
        last_error: Box<StageError>,
    },

    #[error("Pipeline cancelled")]
    Cancelled,

    #[error("Dead letter queue error: {0}")]
    Dlq(String),
}

/// Errors occurring inside a single pipeline stage.
#[derive(Error, Debug, Clone)]
pub enum StageError {
    #[error("Data validation failed: {0}")]
    Validation(String),

    #[error("Transformation error: {0}")]
    Transformation(String),

    #[error("External service error: {0}")]
    ExternalService(String),

    #[error("Serialization error: {0}")]
    Serialization(String),

    #[error("Timeout after {0:?}")]
    Timeout(std::time::Duration),

    #[error("Rate limited – retry after {0:?}")]
    RateLimited(std::time::Duration),

    #[error("{0}")]
    Custom(String),
}

impl StageError {
    /// Decide whether the caller should retry this error.
    pub fn is_retryable(&self) -> bool {
        matches!(
            self,
            StageError::ExternalService(_)
                | StageError::Timeout(_)
                | StageError::RateLimited(_)
        )
    }
}

/// Convenience alias used throughout the crate.
pub type PipelineResult<T> = Result<T, PipelineError>;

impl fmt::Display for Retryable {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Retryable::Yes => write!(f, "retryable"),
            Retryable::No => write!(f, "non-retryable"),
        }
    }
}
