```rust
use std::time::Duration;

use serde::{Deserialize, Serialize};

/// High-level retry strategy selector.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum RetryStrategy {
    /// Fixed delay between every attempt.
    Fixed { delay: Duration },

    /// Exponential back-off with an optional cap.
    ExponentialBackoff {
        initial_delay: Duration,
        multiplier: f64,
        max_delay: Duration,
    },

    /// Linear increase: delay = base + attempt * increment.
    Linear {
        initial_delay: Duration,
        increment: Duration,
        max_delay: Duration,
    },
}

/// Full retry policy applied to a pipeline stage.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RetryPolicy {
    pub max_attempts: u32,
    pub strategy: RetryStrategy,
    /// Add ±jitter_factor * delay to prevent thundering herds.
    pub jitter_factor: f64,
    /// If `true`, only errors marked retryable will be retried.
    pub retry_only_retryable: bool,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            max_attempts: 3,
            strategy: RetryStrategy::ExponentialBackoff {
                initial_delay: Duration::from_millis(100),
                multiplier: 2.0,
                max_delay: Duration::from_secs(30),
            },
            jitter_factor: 0.1,
            retry_only_retryable: true,
        }
    }
}

impl RetryPolicy {
    /// Calculate the delay before the given attempt (0-indexed).
    pub fn delay_for_attempt(&self, attempt: u32) -> Duration {
        let base = match &self.strategy {
            RetryStrategy::Fixed { delay } => *delay,

            RetryStrategy::ExponentialBackoff {
                initial_delay,
                multiplier,
                max_delay,
            } => {
                let delay = initial_delay.mul_f64(multiplier.powi(attempt as i32));
                delay.min(*max_delay)
            }

            RetryStrategy::Linear {
                initial_delay,
                increment,
                max_delay,
            } => {
                let delay = *initial_delay + *increment * attempt;
                delay.min(*max_delay)
            }
        };

        self.apply_jitter(base)
    }

    fn apply_jitter(&self, base: Duration) -> Duration {
        if self.jitter_factor == 0.0 {
            return base;
        }
        let jitter_range = base.mul_f64(self.jitter_factor);
        let jitter = Duration::from_nanos(
            (rand::random::<f64>() * 2.0 * jitter_range.as_nanos() as f64) as u64,
        );
        // base - jitter_range + random(0 .. 2*jitter_range)
        let lower = base.saturating_sub(jitter_range);
        lower + jitter.min(jitter_range * 2)
    }

    // ── Builder helpers ──────────────────────────────────────────────

    pub fn with_max_attempts(mut self, n: u32) -> Self {
        self.max_attempts = n;
        self
    }

    pub fn with_strategy(mut self, s: RetryStrategy) -> Self {
        self.strategy = s;
        self
    }

    pub fn with_jitter(mut self, factor: f64) -> Self {
        self.jitter_factor = factor;
        self
    }

    pub fn retry_all_errors(mut self) -> Self {
        self.retry_only_retryable = false;
        self
    }
}
