## `src/retry/executor.rs`

```rust
use std::future::Future;
use std::pin::Pin;

use tracing::{error, info, warn};

use crate::error::{PipelineError, PipelineResult, Retryable, StageError};
use crate::metrics::PipelineMetrics;
use crate::retry::policy::RetryPolicy;

/// Executes an async closure with the configured retry policy.
pub struct RetryExecutor {
    policy: RetryPolicy,
}

impl RetryExecutor {
    pub fn new(policy: RetryPolicy) -> Self {
        Self { policy }
    }

    /// Run `operation` up to `max_attempts` times, applying back-off between
    /// failures. Returns the first successful result or
    /// [`PipelineError::RetryExhausted`].
    pub async fn execute<F, Fut, T>(
        &self,
        stage_name: &str,
        metrics: &PipelineMetrics,
        operation: F,
    ) -> PipelineResult<T>
    where
        F: Fn() -> Fut,
        Fut: Future<Output = Result<T, StageError>>,
    {
        let mut last_error: Option<StageError> = None;

        for attempt in 0..self.policy.max_attempts {
            match operation().await {
                Ok(value) => {
                    if attempt > 0 {
                        info!(
                            stage = stage_name,
                            attempt = attempt + 1,
                            "Stage succeeded after retry"
                        );
                    }
                    metrics.record_stage_success(stage_name);
                    return Ok(value);
                }
                Err(err) => {
                    metrics.record_stage_retry(stage_name, attempt + 1);

                    // Non-retryable errors are surfaced immediately.
                    if self.policy.retry_only_retryable && !err.is_retryable() {
                        error!(
                            stage = stage_name,
                            error = %err,
                            "Non-retryable error – aborting"
                        );
                        return Err(PipelineError::StageExecution {
                            stage: stage_name.to_string(),
                            source: err,
                            retryable: Retryable::No,
                        });
                    }

                    warn!(
                        stage = stage_name,
                        attempt = attempt + 1,
                        max_attempts = self.policy.max_attempts,
                        error = %err,
                        "Stage failed – will retry"
                    );

                    last_error = Some(err);

                    // Don't sleep after the last attempt.
                    if attempt + 1 < self.policy.max_attempts {
                        let delay = self.policy.delay_for_attempt(attempt);
                        tokio::time::sleep(delay).await;
                    }
                }
            }
        }

        let last_err = last_error.unwrap(); // safe: at least one attempt ran
        metrics.record_stage_failure(stage_name);

        Err(PipelineError::RetryExhausted {
            stage: stage_name.to_string(),
            attempts: self.policy.max_attempts,
            last_error: Box::new(last_err),
        })
    }
}
