```rust
use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

use serde::Serialize;

/// Thread-safe, lock-free per-stage counters.
#[derive(Debug, Default)]
struct StageCounters {
    successes: AtomicU64,
    failures: AtomicU64,
    retries: AtomicU64,
    total_duration_us: AtomicU64,
    items_processed: AtomicU64,
}

/// Shareable metrics collector.
#[derive(Debug, Clone)]
pub struct PipelineMetrics {
    stages: Arc<RwLock<HashMap<String, Arc<StageCounters>>>>,
    pipeline_start: Arc<RwLock<Option<Instant>>>,
    total_items: AtomicU64Wrapper,
    failed_items: AtomicU64Wrapper,
    dlq_items: AtomicU64Wrapper,
}

// Wrapper so we can derive Clone via Arc.
#[derive(Debug, Clone)]
struct AtomicU64Wrapper(Arc<AtomicU64>);

impl Default for AtomicU64Wrapper {
    fn default() -> Self {
        Self(Arc::new(AtomicU64::new(0)))
    }
}

impl AtomicU64Wrapper {
    fn inc(&self)  { self.0.fetch_add(1, Ordering::Relaxed); }
    fn get(&self) -> u64 { self.0.load(Ordering::Relaxed) }
}

impl PipelineMetrics {
    pub fn new() -> Self {
        Self {
            stages: Arc::new(RwLock::new(HashMap::new())),
            pipeline_start: Arc::new(RwLock::new(None)),
            total_items: Default::default(),
            failed_items: Default::default(),
            dlq_items: Default::default(),
        }
    }

    pub fn start_pipeline(&self) {
        *self.pipeline_start.write().unwrap() = Some(Instant::now());
    }

    // ── Per-stage helpers ────────────────────────────────────────────

    fn get_or_create(&self, stage: &str) -> Arc<StageCounters> {
        {
            let map = self.stages.read().unwrap();
            if let Some(c) = map.get(stage) {
                return Arc::clone(c);
            }
        }
        let mut map = self.stages.write().unwrap();
        Arc::clone(
            map.entry(stage.to_string())
                .or_insert_with(|| Arc::new(StageCounters::default())),
        )
    }

    pub fn record_stage_success(&self, stage: &str) {
        self.get_or_create(stage).successes.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_stage_failure(&self, stage: &str) {
        self.get_or_create(stage).failures.fetch_add(1, Ordering::Relaxed);
        self.failed_items.inc();
    }

    pub fn record_stage_retry(&self, stage: &str, _attempt: u32) {
        self.get_or_create(stage).retries.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_stage_duration(&self, stage: &str, duration: Duration) {
        self.get_or_create(stage)
            .total_duration_us
            .fetch_add(duration.as_micros() as u64, Ordering::Relaxed);
    }

    pub fn record_item_processed(&self, stage: &str) {
        self.get_or_create(stage).items_processed.fetch_add(1, Ordering::Relaxed);
        self.total_items.inc();
    }

    pub fn record_dlq_item(&self) {
        self.dlq_items.inc();
    }

    // ── Snapshot ─────────────────────────────────────────────────────

    pub fn snapshot(&self) -> MetricsSnapshot {
        let map = self.stages.read().unwrap();
        let stages = map
            .iter()
            .map(|(name, c)| {
                (
                    name.clone(),
                    StageSnapshot {
                        successes: c.successes.load(Ordering::Relaxed),
                        failures: c.failures.load(Ordering::Relaxed),
                        retries: c.retries.load(Ordering::Relaxed),
                        avg_duration_us: {
                            let total = c.total_duration_us.load(Ordering::Relaxed);
                            let items = c.items_processed.load(Ordering::Relaxed);
                            if items == 0 { 0 } else { total / items }
                        },
                        items_processed: c.items_processed.load(Ordering::Relaxed),
                    },
                )
            })
            .collect();

        let elapsed = self
            .pipeline_start
            .read()
            .unwrap()
            .map(|s| s.elapsed())
            .unwrap_or_default();

        MetricsSnapshot {
            stages,
            total_items: self.total_items.get(),
            failed_items: self.failed_items.get(),
            dlq_items: self.dlq_items.get(),
            elapsed,
        }
    }
}

#[derive(Debug, Serialize)]
pub struct StageSnapshot {
    pub successes: u64,
    pub failures: u64,
    pub retries: u64,
    pub avg_duration_us: u64,
    pub items_processed: u64,
}

#[derive(Debug, Serialize)]
pub struct MetricsSnapshot {
    pub stages: HashMap<String, StageSnapshot>,
    pub total_items: u64,
    pub failed_items: u64,
    pub dlq_items: u64,
    #[serde(serialize_with = "serialize_duration")]
    pub elapsed: Duration,
}

fn serialize_duration<S: serde::Serializer>(d: &Duration, s: S) -> Result<S::Ok, S::Error> {
    s.serialize_str(&format!("{:.3}s", d.as_secs_f64()))
}

impl std::fmt::Display for MetricsSnapshot {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        writeln!(f, "╔══════════════════════════════════════════════╗")?;
        writeln!(f, "║          Pipeline Metrics Snapshot           ║")?;
        writeln!(f, "╠══════════════════════════════════════════════╣")?;
        writeln!(f, "║ Elapsed      : {:>10.3}s                  ║", self.elapsed.as_secs_f64())?;
        writeln!(f, "║ Total items  : {:>10}                    ║", self.total_items)?;
        writeln!(f, "║ Failed items : {:>10}                    ║", self.failed_items)?;
        writeln!(f, "║ DLQ items    : {:>10}                    ║", self.dlq_items)?;
        writeln!(f, "╠══════════════════════════════════════════════╣")?;
        for (name, snap) in &self.stages {
            writeln!(f, "║ Stage: {:<38} ║", name)?;
            writeln!(f, "║   ok={} fail={} retry={} avg={}µs items={}",
                snap.successes, snap.failures, snap.retries,
                snap.avg_duration_us, snap.items_processed)?;
        }
        writeln!(f, "╚══════════════════════════════════════════════╝")
    }
