// src/types.ts

/** A single analytics event flowing through the pipeline */
export interface AnalyticsEvent {
  id: string;
  timestamp: number;
  eventType: string;
  userId: string;
  properties: Record<string, unknown>;
}

/** Result of an aggregation stage */
export interface AggregationResult {
  key: string;
  count: number;
  values: unknown[];
  metadata: Record<string, unknown>;
}

/** Metrics collected during pipeline execution */
export interface PipelineMetrics {
  inputCount: number;
  outputCount: number;
  filteredCount: number;
  errorCount: number;
  startTime: number;
  endTime: number;
  durationMs: number;
  stageMetrics: StageMetric[];
}

export interface StageMetric {
  stageName: string;
  inputCount: number;
  outputCount: number;
  durationMs: number;
  errors: string[];
}

/** Configuration for each pipeline stage */
export interface StageConfig {
  name: string;
  enabled: boolean;
}

/** Generic pipeline stage that processes data */
export interface PipelineStage<TInput, TOutput> {
  name: string;
  process(input: TInput[]): Promise<TOutput[]>;
}

/** Source stage that produces data */
export interface SourceStage<T> {
  name: string;
  fetch(): Promise<T[]>;
}

/** Sink stage that consumes final results */
export interface SinkStage<T> {
  name: string;
  write(data: T[]): Promise<void>;
  getWrittenData(): T[];
}

/** Filter predicate */
export type FilterPredicate<T> = (item: T) => boolean;

/** Transform function */
export type TransformFn<TIn, TOut> = (item: TIn) => TOut;

/** Aggregation key extractor */
export type KeyExtractor<T> = (item: T) => string;

/** Aggregation value extractor */
export type ValueExtractor<T> = (item: T) => unknown;

/** Pipeline execution result */
export interface PipelineResult<T> {
  data: T[];
  metrics: PipelineMetrics;
  success: boolean;
  errors: Error[];
}
