/**
 * Generates synthetic analytics events for testing / demo purposes.
 */
export class EventGenerator implements SourceStage<AnalyticsEvent> {
  readonly name = 'EventGenerator';

  constructor(
    private count: number,
    private eventTypes: string[] = ['page_view', 'click', 'purchase'],
    private userIds: string[] = ['user_1', 'user_2', 'user_3']
  ) {}

  async fetch(): Promise<AnalyticsEvent[]> {
    const events: AnalyticsEvent[] = [];
    const now = Date.now();

    for (let i = 0; i < this.count; i++) {
      const eventType =
        this.eventTypes[i % this.eventTypes.length];

      events.push({
        id: `evt_${i.toString().padStart(6, '0')}`,
        timestamp: now - (this.count - i) * 1000,
        eventType,
        userId: this.userIds[i % this.userIds.length],
        properties: this.generateProperties(eventType, i),
      });
    }

    return events;
  }

  private generateProperties(
    eventType: string,
    index: number
  ): Record<string, unknown> {
    switch (eventType) {
      case 'page_view':
        return {
          page: `/page/${index % 5}`,
          referrer: index % 2 === 0 ? 'google' : 'direct',
          duration: Math.floor(Math.random() * 300) + 10,
        };
      case 'click':
        return {
          element: `button_${index % 3}`,
          page: `/page/${index % 5}`,
        };
      case 'purchase':
        return {
          amount: Math.round((Math.random() * 200 + 5) * 100) / 100,
          currency: 'USD',
          items: Math.floor(Math.random() * 5) + 1,
        };
      default:
        return { index };
    }
  }
