import { AnalyticsEvent, FilterPredicate, PipelineStage } from '../types';

/**
 * Removes events that don't match the predicate.
 */
export class FilterStage implements PipelineStage<AnalyticsEvent, AnalyticsEvent> {
  readonly name: string;
  private _filteredCount = 0;

  constructor(
    name: string,
    private predicate: FilterPredicate<AnalyticsEvent>
  ) {
    this.name = name;
  }

  async process(input: AnalyticsEvent[]): Promise<AnalyticsEvent[]> {
    this._filteredCount = 0;
    const result: AnalyticsEvent[] = [];

    for (const event of input) {
      if (this.predicate(event)) {
        result.push(event);
      } else {
        this._filteredCount++;
      }
    }

    return result;
  }

  get filteredCount(): number {
    return this._filteredCount;
  }
}

// ── Pre-built filter factories ───────────────────────────────────

export function byEventType(...types: string[]): FilterStage {
  const typeSet = new Set(types);
  return new FilterStage(`FilterByEventType(${types.join(',')})`, (e) =>
    typeSet.has(e.eventType)
  );
}

export function byUser(...userIds: string[]): FilterStage {
  const userSet = new Set(userIds);
  return new FilterStage(`FilterByUser(${userIds.join(',')})`, (e) =>
    userSet.has(e.userId)
  );
}

export function byTimeRange(startMs: number, endMs: number): FilterStage {
  return new FilterStage(
    `FilterByTimeRange(${startMs}-${endMs})`,
    (e) => e.timestamp >= startMs && e.timestamp <= endMs
  );
}

export function byProperty(
  key: string,
  predicate: (value: unknown) => boolean
): FilterStage {
  return new FilterStage(`FilterByProperty(${key})`, (e) =>
    predicate(e.properties[key])
  );
}

/**
 * Removes duplicate events by id.
 */
export class DeduplicationStage
  implements PipelineStage<AnalyticsEvent, AnalyticsEvent>
{
  readonly name = 'Deduplication';
  private _duplicateCount = 0;

  async process(input: AnalyticsEvent[]): Promise<AnalyticsEvent[]> {
    this._duplicateCount = 0;
    const seen = new Set<string>();
    const result: AnalyticsEvent[] = [];

    for (const event of input) {
      if (!seen.has(event.id)) {
        seen.add(event.id);
        result.push(event);
      } else {
        this._duplicateCount++;
      }
    }

    return result;
  }

  get duplicateCount(): number {
    return this._duplicateCount;
  }
}
