/** Adds or overwrites properties on each event. */
export function enrichWith(
  extra: Record<string, unknown>
): TransformStage {
  return new TransformStage('EnrichWith', (e) => ({
    ...e,
    properties: { ...e.properties, ...extra },
  }));
}

/** Adds a computed property based on existing data. */
export function addComputedProperty(
  key: string,
  compute: (event: AnalyticsEvent) => unknown
): TransformStage {
  return new TransformStage(`AddComputed(${key})`, (e) => ({
    ...e,
    properties: { ...e.properties, [key]: compute(e) },
  }));
}

/** Normalises the event type to lower-case. */
export function normalizeEventType(): TransformStage {
  return new TransformStage('NormalizeEventType', (e) => ({
    ...e,
    eventType: e.eventType.toLowerCase().trim(),
  }));
}

/** Redacts the listed property keys (replaces with '[REDACTED]'). */
export function redactProperties(...keys: string[]): TransformStage {
  return new TransformStage(`Redact(${keys.join(',')})`, (e) => {
    const props = { ...e.properties };
    for (const k of keys) {
      if (k in props) props[k] = '[REDACTED]';
    }
    return { ...e, properties: props };
  });
}

/**
 * Applies a chain of transforms in order.
 */
export class TransformChain
  implements PipelineStage<AnalyticsEvent, AnalyticsEvent>
{
  readonly name: string;

  constructor(private stages: TransformStage[]) {
    this.name = `TransformChain(${stages.map((s) => s.name).join(' → ')})`;
  }

  async process(input: AnalyticsEvent[]): Promise<AnalyticsEvent[]> {
    let data = input;
    for (const stage of this.stages) {
      data = await stage.process(data);
    }
    return data;
  }
}
