// src/stages/aggregate.ts

import {
  AnalyticsEvent,
  AggregationResult,
  KeyExtractor,
  PipelineStage,
  ValueExtractor,
} from '../types';

/**
 * Groups events by a key and produces AggregationResults.
 */
export class AggregateStage
  implements PipelineStage<AnalyticsEvent, AggregationResult>
{
  readonly name: string;

  constructor(
    name: string,
    private keyExtractor: KeyExtractor<AnalyticsEvent>,
    private valueExtractor: ValueExtractor<AnalyticsEvent> = () => 1
  ) {
    this.name = name;
  }

  async process(input: AnalyticsEvent[]): Promise<AggregationResult[]> {
    const groups = new Map<string, AnalyticsEvent[]>();

    for (const event of input) {
      const key = this.keyExtractor(event);
      const list = groups.get(key) ?? [];
      list.push(event);
      groups.set(key, list);
    }

    const results: AggregationResult[] = [];

    for (const [key, events] of groups) {
      results.push({
        key,
        count: events.length,
        values: events.map(this.valueExtractor),
        metadata: {},
      });
    }

    return results;
  }
}

// ── Pre-built aggregation factories ──────────────────────────────

export function countByEventType(): AggregateStage {
  return new AggregateStage('CountByEventType', (e) => e.eventType);
}

export function countByUser(): AggregateStage {
  return new AggregateStage('CountByUser', (e) => e.userId);
}

export function sumByProperty(property: string): AggregateStage {
  return new AggregateStage(
    `SumBy(${property})`,
    (e) => e.eventType,
    (e) => e.properties[property] ?? 0
  );
}

/**
 * Computes numeric statistics from an array of AggregationResults.
 */
export class StatisticsStage
  implements PipelineStage<AggregationResult, AggregationResult>
{
  readonly name = 'Statistics';

  async process(input: AggregationResult[]): Promise<AggregationResult[]> {
    return input.map((r) => {
      const nums = r.values.filter((v) => typeof v === 'number') as number[];
      const sum = nums.reduce((a, b) => a + b, 0);
      const avg = nums.length > 0 ? sum / nums.length : 0;
      const min = nums.length > 0 ? Math.min(...nums) : 0;
      const max = nums.length > 0 ? Math.max(...nums) : 0;

      return {
        ...r,
        metadata: { ...r.metadata, sum, avg, min, max },
      };
    });
  }
}
