// Lightweight text tokenizer with stemming and stop word removal

const STOP_WORDS = new Set([
  'a', 'an', 'the', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for',
  'of', 'with', 'by', 'is', 'am', 'are', 'was', 'were', 'be', 'been',
  'being', 'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would',
  'could', 'should', 'may', 'might', 'shall', 'can', 'it', 'its', 'this',
  'that', 'these', 'those', 'i', 'you', 'he', 'she', 'we', 'they', 'me',
  'him', 'her', 'us', 'them', 'my', 'your', 'his', 'our', 'their', 'what',
  'which', 'who', 'whom', 'if', 'then', 'else', 'when', 'where', 'how',
  'not', 'no', 'nor', 'so', 'too', 'very', 'just', 'about', 'as', 'from',
]);

// Simple suffix-stripping stemmer (covers common English patterns)
function stem(word) {
  if (word.length < 4) return word;

  const rules = [
    [/ying$/, 'y'],
    [/ies$/, 'y'],
    [/ied$/, 'y'],
    [/ness$/, ''],
    [/ment$/, ''],
    [/able$/, ''],
    [/ible$/, ''],
    [/ful$/, ''],
    [/less$/, ''],
    [/tion$/, 't'],
    [/sion$/, 's'],
    [/ating$/, 'ate'],
    [/ting$/, 'te'],
    [/ing$/, ''],
    [/eed$/, 'ee'],
    [/ed$/, ''],
    [/ly$/, ''],
    [/er$/, ''],
    [/est$/, ''],
    [/es$/, ''],
    [/s$/, ''],
  ];

  for (const [pattern, replacement] of rules) {
    if (pattern.test(word)) {
      const result = word.replace(pattern, replacement);
      if (result.length >= 3) return result;
    }
  }

  return word;
}

export function tokenize(text, { removeStopWords = true, applyStemming = true } = {}) {
  // Split on non-alphanumeric, lowercase, filter empties
  const raw = text
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(t => t.length > 0);

  const tokens = [];

  for (const word of raw) {
    if (removeStopWords && STOP_WORDS.has(word)) continue;
    if (word.length < 2) continue;

    tokens.push(applyStemming ? stem(word) : word);
  }

  return tokens;
}

// Returns tokens with their original positions for phrase/proximity queries
export function tokenizeWithPositions(text, opts) {
  const raw = text
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(t => t.length > 0);

  const results = [];
  let pos = 0;

  for (const word of raw) {
    if (word.length < 2) { pos++; continue; }

    const token = opts?.applyStemming !== false ? stem(word) : word;
    results.push({ token, position: pos, original: word });
    pos++;
  }

  return results;
}
