*/

const DEFAULT_DIR = join(homedir(), '.searchidx');
const INDEX_FILE = 'index.json';

export class IndexStore {
  #data;
  #indexDir;
  #indexPath;
  #dirty = false;

  constructor(indexDir) {
    this.#indexDir = indexDir || DEFAULT_DIR;
    this.#indexPath = join(this.#indexDir, INDEX_FILE);
    this.#load();
  }

  // --- Persistence ---

  #load() {
    if (existsSync(this.#indexPath)) {
      try {
        const raw = readFileSync(this.#indexPath, 'utf-8');
        this.#data = JSON.parse(raw);
      } catch {
        console.error('⚠ Corrupt index file. Reinitializing.');
        this.#initEmpty();
      }
    } else {
      this.#initEmpty();
    }
  }

  #initEmpty() {
    this.#data = {
      meta: { created: new Date().toISOString(), updated: null, version: 1 },
      documents: {},
      index: {},
    };
    this.#dirty = true;
  }

  save() {
    if (!this.#dirty) return;

    mkdirSync(this.#indexDir, { recursive: true });
    this.#data.meta.updated = new Date().toISOString();
    writeFileSync(this.#indexPath, JSON.stringify(this.#data), 'utf-8');
    this.#dirty = false;
  }

  // --- Document Management ---

  static hashContent(content) {
    return createHash('sha256').update(content).digest('hex').slice(0, 16);
  }

  static makeDocId(filePath) {
    return createHash('md5').update(filePath).digest('hex').slice(0, 12);
  }

  hasDocument(docId) {
    return docId in this.#data.documents;
  }

  getDocumentByPath(filePath) {
    const docId = IndexStore.makeDocId(filePath);
    if (this.#data.documents[docId]) {
      return { docId, ...this.#data.documents[docId] };
    }
    return null;
  }

  addDocument(docId, meta) {
    this.#data.documents[docId] = meta;
    this.#dirty = true;
  }

  removeDocument(docId) {
    if (!this.#data.documents[docId]) return false;

    delete this.#data.documents[docId];

    // Remove from all postings lists
    const termsToDelete = [];
    for (const [term, entry] of Object.entries(this.#data.index)) {
      if (entry.postings[docId]) {
        delete entry.postings[docId];
        entry.df = Object.keys(entry.postings).length;
        if (entry.df === 0) termsToDelete.push(term);
      }
    }
    for (const term of termsToDelete) {
      delete this.#data.index[term];
    }

    this.#dirty = true;
    return true;
  }

  // --- Index Operations ---

  addTermPosting(term, docId, tf, positions) {
    if (!this.#data.index[term]) {
      this.#data.index[term] = { df: 0, postings: {} };
    }

    const entry = this.#data.index[term];
    const isNew = !(docId in entry.postings);
    entry.postings[docId] = { tf, positions };
    if (isNew) entry.df++;

    this.#dirty = true;
  }

  getTermEntry(term) {
    return this.#data.index[term] || null;
  }

  get totalDocuments() {
    return Object.keys(this.#data.documents).length;
  }

  get totalTerms() {
    return Object.keys(this.#data.index).length;
  }

  get documents() {
    return { ...this.#data.documents };
  }

  get meta() {
    return { ...this.#data.meta };
  }

  getAllTerms() {
    return Object.keys(this.#data.index);
  }

  clear() {
    this.#initEmpty();
    this.save();
  }

  get indexPath() {
    return this.#indexPath;
  }
}
