import { readFileSync, statSync, readdirSync } from 'node:fs';
import { resolve, extname, basename, relative } from 'node:path';
import { tokenize, tokenizeWithPositions } from './tokenizer.js';
import { IndexStore } from './index-store.js';

const INDEXABLE_EXTENSIONS = new Set([
  '.txt', '.md', '.js', '.ts', '.jsx', '.tsx', '.py', '.rb', '.go',
  '.rs', '.java', '.c', '.cpp', '.h', '.css', '.html', '.xml',
  '.json', '.yaml', '.yml', '.toml', '.sh', '.bash', '.zsh',
  '.sql', '.csv', '.log', '.env', '.cfg', '.conf', '.ini',
]);

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

export class SearchEngine {
  #store;

  constructor(indexDir) {
    this.#store = new IndexStore(indexDir);
  }

  // --- Indexing ---

  indexFile(filePath) {
    const absPath = resolve(filePath);
    const stat = statSync(absPath);

    if (!stat.isFile()) throw new Error(`Not a file: ${absPath}`);
    if (stat.size > MAX_FILE_SIZE) throw new Error(`File too large (>10MB): ${absPath}`);
    if (stat.size === 0) return { skipped: true, reason: 'empty' };

    const ext = extname(absPath).toLowerCase();
    if (!INDEXABLE_EXTENSIONS.has(ext)) {
      return { skipped: true, reason: `unsupported extension: ${ext}` };
    }

    const content = readFileSync(absPath, 'utf-8');
    const contentHash = IndexStore.hashContent(content);
    const docId = IndexStore.makeDocId(absPath);

    // Skip if content hasn't changed
    const existing = this.#store.hasDocument(docId)
      ? this.#store.documents[docId]
      : null;

    if (existing?.hash === contentHash) {
      return { skipped: true, reason: 'unchanged' };
    }

    // Re-index: remove old postings first
    if (existing) {
      this.#store.removeDocument(docId);
    }

    // Tokenize and build term frequencies + positions
    const tokensWithPos = tokenizeWithPositions(content);
    const termData = new Map(); // term -> { tf, positions }

    for (const { token, position } of tokensWithPos) {
      if (!termData.has(token)) {
        termData.set(token, { tf: 0, positions: [] });
      }
      const entry = termData.get(token);
      entry.tf++;
      entry.positions.push(position);
    }

    // Store document metadata
    this.#store.addDocument(docId, {
      path: absPath,
      title: basename(absPath),
      size: stat.size,
      indexedAt: new Date().toISOString(),
      wordCount: tokensWithPos.length,
      hash: contentHash,
    });

    // Store each term's postings
    for (const [term, { tf, positions }] of termData) {
      this.#store.addTermPosting(term, docId, tf, positions);
    }

    this.#store.save();

    return {
      skipped: false,
      docId,
      path: absPath,
      terms: termData.size,
      tokens: tokensWithPos.length,
    };
  }

  indexDirectory(dirPath, { recursive = true } = {}) {
    const absDir = resolve(dirPath);
    const stat = statSync(absDir);
    if (!stat.isDirectory()) throw new Error(`Not a directory: ${absDir}`);

    const results = { indexed: 0, skipped: 0, errors: 0, details: [] };

    const walk = (dir) => {
      const entries = readdirSync(dir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = resolve(dir, entry.name);

        // Skip hidden files/dirs and node_modules
        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;

        if (entry.isDirectory() && recursive) {
          walk(fullPath);
        } else if (entry.isFile()) {
          try {
            const result = this.indexFile(fullPath);
            if (result.skipped) {
              results.skipped++;
            } else {
              results.indexed++;
            }
            results.details.push({
              file: relative(absDir, fullPath),
              ...result,
            });
          } catch (err) {
            results.errors++;
            results.details.push({
              file: relative(absDir, fullPath),
              error: err.message,
            });
          }
        }
      }
    };

    walk(absDir);
    return results;
  }

  // --- Searching ---

  search(query, { limit = 20, snippet = true } = {}) {
    const queryTerms = tokenize(query);
    if (queryTerms.length === 0) return [];

    const N = this.#store.totalDocuments;
    if (N === 0) return [];

    // Score each document using TF-IDF
    const scores = new Map(); // docId -> score
    const matchedTerms = new Map(); // docId -> Set<term>

    for (const term of queryTerms) {
      const entry = this.#store.getTermEntry(term);
      if (!entry) continue;

      // IDF: log(N / df) — standard formula
      const idf = Math.log(N / entry.df);

      for (const [docId, posting] of Object.entries(entry.postings)) {
        // TF: 1 + log(tf) — logarithmic scaling
        const tf = 1 + Math.log(posting.tf);
        const tfidf = tf * idf;

        scores.set(docId, (scores.get(docId) || 0) + tfidf);

        if (!matchedTerms.has(docId)) matchedTerms.set(docId, new Set());
        matchedTerms.get(docId).add(term);
      }
    }

    // Boost documents matching more query terms
    for (const [docId, terms] of matchedTerms) {
      const coverage = terms.size / queryTerms.length;
      scores.set(docId, scores.get(docId) * (1 + coverage));
    }

    // Sort by score descending, take top N
    const ranked = [...scores.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, limit);

    // Build result objects
    const docs = this.#store.documents;
    return ranked.map(([docId, score]) => {
      const doc = docs[docId];
      const result = {
        docId,
        path: doc.path,
        title: doc.title,
        score: Math.round(score * 1000) / 1000,
        matchedTerms: [...matchedTerms.get(docId)],
      };

      if (snippet) {
        result.snippet = this.#extractSnippet(doc.path, queryTerms);
      }

      return result;
    });
  }

  #extractSnippet(filePath, queryTerms, contextChars = 120) {
    try {
      const content = readFileSync(filePath, 'utf-8');
      const lower = content.toLowerCase();

      // Find the best window containing query terms
      let bestPos = 0;
      let bestScore = -1;

      for (const term of queryTerms) {
        let pos = lower.indexOf(term);
        while (pos !== -1) {
          // Score: how many query terms are nearby
          let score = 0;
          for (const t of queryTerms) {
            const nearby = lower.indexOf(t, Math.max(0, pos - contextChars));
            if (nearby !== -1 && nearby < pos + contextChars) score++;
          }
          if (score > bestScore) {
            bestScore = score;
            bestPos = pos;
          }
          pos = lower.indexOf(term, pos + 1);
        }
      }

      const start = Math.max(0, bestPos - 40);
      const end = Math.min(content.length, bestPos + contextChars);
      let snip = content.slice(start, end).replace(/\s+/g, ' ').trim();

      if (start > 0) snip = '...' + snip;
      if (end < content.length) snip = snip + '...';

      return snip;
    } catch {
      return null;
    }
  }

  // --- Management ---

  removeFile(filePath) {
    const absPath = resolve(filePath);
    const docId = IndexStore.makeDocId(absPath);
    const removed = this.#store.removeDocument(docId);
    if (removed) this.#store.save();
    return removed;
  }

  listDocuments() {
    return Object.entries(this.#store.documents).map(([id, doc]) => ({
      id,
      ...doc,
    }));
  }

  getStats() {
    const docs = this.#store.documents;
    const docList = Object.values(docs);
    const totalSize = docList.reduce((sum, d) => sum + d.size, 0);
    const totalWords = docList.reduce((sum, d) => sum + d.wordCount, 0);

    return {
      documents: this.#store.totalDocuments,
      uniqueTerms: this.#store.totalTerms,
      totalWords,
      totalSize,
      indexPath: this.#store.indexPath,
      ...this.#store.meta,
    };
  }

  clear() {
    this.#store.clear();
  }
}
