```javascript
import fs from "node:fs";
import path from "node:path";
import { processCSV } from "./reporters/csv-reporter.js";
import { processJSON } from "./reporters/json-reporter.js";

// ── Configuration ──────────────────────────────────────────
const CONFIG = {
  inputDir: "./input",
  outputDir: "./output",
  processedDir: "./processed",
  pollInterval: 1000,        // fs.watch fallback
  debounceMs: 300,           // ignore duplicate events
  retryAttempts: 3,          // retry on locked files
  retryDelayMs: 500,
};

// ── File processors by extension ───────────────────────────
const PROCESSORS = {
  ".csv": processCSV,
  ".json": processJSON,
};

// ── State tracking ─────────────────────────────────────────
const processing = new Set();      // files currently being processed
const debounceTimers = new Map();  // debounce per file

// ── Ensure directories exist ───────────────────────────────
function ensureDirs() {
  for (const dir of [CONFIG.inputDir, CONFIG.outputDir, CONFIG.processedDir]) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

// ── Wait until file is fully written ───────────────────────
async function waitForStableFile(filePath, attempts = CONFIG.retryAttempts) {
  for (let i = 0; i < attempts; i++) {
    try {
      const stat1 = fs.statSync(filePath);
      await sleep(CONFIG.retryDelayMs);
      const stat2 = fs.statSync(filePath);

      // File size stopped changing — it's done writing
      if (stat1.size === stat2.size && stat1.size > 0) {
        return true;
      }
    } catch {
      // File might have been moved/deleted
      return false;
    }
  }
  return false;
}

// ── Process a single file ──────────────────────────────────
async function handleFile(filename) {
  const ext = path.extname(filename).toLowerCase();
  const processor = PROCESSORS[ext];

  if (!processor) return; // unsupported extension — skip silently
  if (processing.has(filename)) return; // already in progress

  processing.add(filename);
  const inputPath = path.join(CONFIG.inputDir, filename);

  try {
    // Wait for file to finish writing (e.g., large uploads)
    const stable = await waitForStableFile(inputPath);
    if (!stable) {
      log(`⏭  Skipping ${filename} (unstable or removed)`);
      return;
    }

    log(`📄 Processing ${filename}...`);
    const startTime = performance.now();

    // Read raw data
    const raw = fs.readFileSync(inputPath, "utf-8");

    // Generate report through the appropriate processor
    const report = await processor(raw, filename);

    // Write the report
    const reportName = `${path.parse(filename).name}_report_${timestamp()}.html`;
    const outputPath = path.join(CONFIG.outputDir, reportName);
    fs.writeFileSync(outputPath, report);

    // Move source file to processed/
    const destPath = path.join(CONFIG.processedDir, filename);
    fs.renameSync(inputPath, destPath);

    const elapsed = (performance.now() - startTime).toFixed(0);
    log(`✅ ${reportName} generated (${elapsed}ms)`);
  } catch (err) {
    log(`❌ Error processing ${filename}: ${err.message}`);
  } finally {
    processing.delete(filename);
  }
}

// ── Debounced file handler ─────────────────────────────────
function onFileChange(filename) {
  if (!filename) return;

  // Clear previous timer for this file
  if (debounceTimers.has(filename)) {
    clearTimeout(debounceTimers.get(filename));
  }

  const timer = setTimeout(() => {
    debounceTimers.delete(filename);
    handleFile(filename);
  }, CONFIG.debounceMs);

  debounceTimers.set(filename, timer);
}

// ── Process any files already sitting in input/ ────────────
function processExistingFiles() {
  const files = fs.readdirSync(CONFIG.inputDir);
  for (const file of files) {
    const ext = path.extname(file).toLowerCase();
    if (PROCESSORS[ext]) {
      handleFile(file);
    }
  }
}

// ── Start watching ─────────────────────────────────────────
function start() {
  ensureDirs();

  log("👁  Watching for files in " + path.resolve(CONFIG.inputDir));
  log("   Supported formats: " + Object.keys(PROCESSORS).join(", "));
  log("   Reports go to: " + path.resolve(CONFIG.outputDir));
  log("─".repeat(55));

  // Pick up anything already in the folder
  processExistingFiles();

  // Watch for new/changed files
  const watcher = fs.watch(CONFIG.inputDir, (eventType, filename) => {
    if (eventType === "rename" || eventType === "change") {
      onFileChange(filename);
    }
  });

  // Graceful shutdown
  process.on("SIGINT", () => {
    log("\n🛑 Shutting down watcher...");
    watcher.close();
    debounceTimers.forEach(clearTimeout);
    process.exit(0);
  });
}

// ── Helpers ────────────────────────────────────────────────
function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

function timestamp() {
  return new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
}

function log(msg) {
  const ts = new Date().toLocaleTimeString();
  console.log(`[${ts}] ${msg}`);
}

start();
