import { parse } from "csv-parse/sync";

export async function processCSV(raw, filename) {
  const records = parse(raw, {
    columns: true,       // first row = headers
    skip_empty_lines: true,
    trim: true,
  });

  if (records.length === 0) {
    throw new Error("CSV file is empty or has no data rows");
  }

  const columns = Object.keys(records[0]);

  // Build column summaries (detect numeric columns automatically)
  const summaries = columns.map((col) => {
    const values = records.map((r) => r[col]);
    const numeric = values.map(Number).filter((n) => !isNaN(n));

    if (numeric.length > values.length * 0.8) {
      // Treat as numeric column
      return {
        name: col,
        type: "numeric",
        min: Math.min(...numeric),
        max: Math.max(...numeric),
        avg: (numeric.reduce((a, b) => a + b, 0) / numeric.length).toFixed(2),
        sum: numeric.reduce((a, b) => a + b, 0).toFixed(2),
      };
    }

    // Treat as categorical — show top values
    const freq = {};
    values.forEach((v) => (freq[v] = (freq[v] || 0) + 1));
    const topValues = Object.entries(freq)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5);

    return {
      name: col,
      type: "categorical",
      unique: Object.keys(freq).length,
      topValues,
    };
  });

  return buildHTML({
    title: `CSV Report: ${filename}`,
    rowCount: records.length,
    columnCount: columns.length,
    summaries,
    sampleRows: records.slice(0, 10),
    columns,
  });
}

function buildHTML({ title, rowCount, columnCount, summaries, sampleRows, columns }) {
  const summaryRows = summaries
    .map((s) => {
      if (s.type === "numeric") {
        return `<tr>
          <td>${s.name}</td><td>Numeric</td>
          <td>Min: ${s.min} | Max: ${s.max} | Avg: ${s.avg} | Sum: ${s.sum}</td>
        </tr>`;
      }
      const top = s.topValues.map(([v, c]) => `${v} (${c})`).join(", ");
      return `<tr>
        <td>${s.name}</td><td>Text (${s.unique} unique)</td>
        <td>Top: ${top}</td>
      </tr>`;
    })
    .join("\n");

  const dataHeaders = columns.map((c) => `<th>${c}</th>`).join("");
  const dataRows = sampleRows
    .map((r) => `<tr>${columns.map((c) => `<td>${r[c]}</td>`).join("")}</tr>`)
    .join("\n");

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>${title}</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 960px; margin: 2rem auto; color: #1a1a1a; }
    h1 { border-bottom: 2px solid #2563eb; padding-bottom: .5rem; }
    .meta { background: #f0f4ff; padding: 1rem; border-radius: 8px; margin: 1rem 0; }
    table { width: 100%; border-collapse: collapse; margin: 1rem 0; }
    th, td { border: 1px solid #d1d5db; padding: 8px 12px; text-align: left; }
    th { background: #2563eb; color: white; }
    tr:nth-child(even) { background: #f9fafb; }
    .ts { color: #6b7280; font-size: .85rem; }
  </style>
</head>
<body>
  <h1>${title}</h1>
  <div class="meta">
    <strong>${rowCount.toLocaleString()}</strong> rows &middot;
    <strong>${columnCount}</strong> columns &middot;
    Generated <span class="ts">${new Date().toISOString()}</span>
  </div>

  <h2>Column Summary</h2>
  <table>
    <tr><th>Column</th><th>Type</th><th>Stats</th></tr>
    ${summaryRows}
  </table>

  <h2>Sample Data (first 10 rows)</h2>
  <table>
    <tr>${dataHeaders}</tr>
    ${dataRows}
  </table>
</body>
</html>`;
}
