export async function processJSON(raw, filename) {
  const data = JSON.parse(raw);

  // Handle both arrays and single objects
  const records = Array.isArray(data) ? data : [data];
  const analysis = analyzeStructure(records);

  return buildHTML({
    title: `JSON Report: ${filename}`,
    recordCount: records.length,
    isArray: Array.isArray(data),
    analysis,
    preview: JSON.stringify(records.slice(0, 3), null, 2),
  });
}

function analyzeStructure(records, maxDepth = 3) {
  const fields = {};

  for (const record of records) {
    crawl(record, fields, "", maxDepth);
  }

  return Object.entries(fields).map(([path, info]) => ({
    path,
    types: [...info.types],
    count: info.count,
    sample: info.sample,
    nullCount: info.nullCount,
  }));
}

function crawl(obj, fields, prefix, depth) {
  if (depth <= 0 || obj === null || obj === undefined) return;

  for (const [key, value] of Object.entries(obj)) {
    const fullPath = prefix ? `${prefix}.${key}` : key;

    if (!fields[fullPath]) {
      fields[fullPath] = { types: new Set(), count: 0, nullCount: 0, sample: null };
    }

    const f = fields[fullPath];
    const type = value === null ? "null" : Array.isArray(value) ? "array" : typeof value;
    f.types.add(type);
    f.count++;

    if (value === null || value === undefined) {
      f.nullCount++;
    } else if (f.sample === null) {
      f.sample = typeof value === "object" ? `[${type}]` : String(value).slice(0, 60);
    }

    if (typeof value === "object" && value !== null && !Array.isArray(value)) {
      crawl(value, fields, fullPath, depth - 1);
    }
  }
}

function buildHTML({ title, recordCount, isArray, analysis, preview }) {
  const fieldRows = analysis
    .map(
      (f) => `<tr>
      <td><code>${f.path}</code></td>
      <td>${f.types.join(", ")}</td>
      <td>${f.count}</td>
      <td>${f.nullCount}</td>
      <td>${f.sample || "—"}</td>
    </tr>`
    )
    .join("\n");

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>${title}</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 960px; margin: 2rem auto; color: #1a1a1a; }
    h1 { border-bottom: 2px solid #059669; padding-bottom: .5rem; }
    .meta { background: #ecfdf5; padding: 1rem; border-radius: 8px; margin: 1rem 0; }
    table { width: 100%; border-collapse: collapse; margin: 1rem 0; }
    th, td { border: 1px solid #d1d5db; padding: 8px 12px; text-align: left; }
    th { background: #059669; color: white; }
    tr:nth-child(even) { background: #f9fafb; }
    pre { background: #1e293b; color: #e2e8f0; padding: 1rem; border-radius: 8px; overflow-x: auto; }
    code { background: #f1f5f9; padding: 2px 6px; border-radius: 4px; font-size: .9rem; }
  </style>
</head>
<body>
  <h1>${title}</h1>
  <div class="meta">
    <strong>${recordCount.toLocaleString()}</strong> records &middot;
    Root type: <strong>${isArray ? "Array" : "Object"}</strong> &middot;
    <strong>${analysis.length}</strong> fields detected &middot;
    Generated ${new Date().toISOString()}
  </div>

  <h2>Field Analysis</h2>
  <table>
    <tr><th>Path</th><th>Types</th><th>Present</th><th>Nulls</th><th>Sample</th></tr>
    ${fieldRows}
  </table>

  <h2>Data Preview</h2>
  <pre>${escapeHtml(preview)}</pre>
</body>
</html>`;
}

function escapeHtml(str) {
  return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
