## src/queue.rs — Priority Queue with Delayed Tasks

```rust
use crate::task::{Task, TaskStatus};
use std::collections::BinaryHeap;
use std::sync::Arc;
use tokio::sync::{Mutex, Notify};
use tracing::{debug, info, warn};

pub struct TaskQueue {
    ready: Mutex<BinaryHeap<Task>>,
    delayed: Mutex<Vec<Task>>,
    dead_letter: Mutex<Vec<Task>>,
    notify: Notify,
    stats: Mutex<QueueStats>,
}

#[derive(Debug, Default, Clone)]
pub struct QueueStats {
    pub enqueued: u64,
    pub processed: u64,
    pub failed: u64,
    pub retried: u64,
    pub dead_lettered: u64,
}

impl TaskQueue {
    pub fn new() -> Arc<Self> {
        Arc::new(Self {
            ready: Mutex::new(BinaryHeap::new()),
            delayed: Mutex::new(Vec::new()),
            dead_letter: Mutex::new(Vec::new()),
            notify: Notify::new(),
            stats: Mutex::new(QueueStats::default()),
        })
    }

    pub async fn push(&self, task: Task) {
        if task.is_ready() {
            let mut ready = self.ready.lock().await;
            debug!(task_id = %task.id, priority = ?task.priority, "Task enqueued (ready)");
            ready.push(task);
        } else {
            let mut delayed = self.delayed.lock().await;
            debug!(task_id = %task.id, scheduled = ?task.scheduled_at, "Task enqueued (delayed)");
            delayed.push(task);
        }

        self.stats.lock().await.enqueued += 1;
        self.notify.notify_one();
    }

    pub async fn pop(&self) -> Task {
        loop {
            // Promote any delayed tasks that are now ready
            self.promote_delayed().await;

            {
                let mut ready = self.ready.lock().await;
                if let Some(task) = ready.pop() {
                    return task;
                }
            }

            // Wait for notification or check delayed tasks periodically
            tokio::select! {
                _ = self.notify.notified() => {},
                _ = tokio::time::sleep(std::time::Duration::from_secs(1)) => {},
            }
        }
    }

    /// Move delayed tasks to the ready queue when their time arrives
    async fn promote_delayed(&self) {
        let mut delayed = self.delayed.lock().await;
        let mut ready = self.ready.lock().await;

        let mut i = 0;
        while i < delayed.len() {
            if delayed[i].is_ready() {
                let task = delayed.swap_remove(i);
                debug!(task_id = %task.id, "Promoting delayed task to ready");
                ready.push(task);
                self.notify.notify_one();
            } else {
                i += 1;
            }
        }
    }

    pub async fn retry(&self, mut task: Task, error: String) {
        task.retry_count += 1;
        task.last_error = Some(error.clone());
        task.status = TaskStatus::Pending;

        let mut stats = self.stats.lock().await;

        if task.can_retry() {
            let backoff = task.backoff_duration();
            task.scheduled_at = Some(
                chrono::Utc::now() + chrono::Duration::from_std(backoff).unwrap(),
            );
            warn!(
                task_id = %task.id,
                retry = task.retry_count,
                max = task.max_retries,
                backoff_secs = backoff.as_secs(),
                "Retrying task"
            );
            stats.retried += 1;
            drop(stats);
            self.push(task).await;
        } else {
            warn!(task_id = %task.id, error = %error, "Task moved to dead letter queue");
            task.status = TaskStatus::DeadLettered;
            stats.dead_lettered += 1;
            self.dead_letter.lock().await.push(task);
        }
    }

    pub async fn mark_completed(&self) {
        self.stats.lock().await.processed += 1;
    }

    pub async fn mark_failed(&self) {
        self.stats.lock().await.failed += 1;
    }

    pub async fn stats(&self) -> QueueStats {
        self.stats.lock().await.clone()
    }

    pub async fn dead_letter_count(&self) -> usize {
        self.dead_letter.lock().await.len()
    }

    pub async fn pending_count(&self) -> usize {
        let ready = self.ready.lock().await.len();
        let delayed = self.delayed.lock().await.len();
        ready + delayed
    }
}
