## src/worker.rs — Worker Pool

```rust
use crate::handler::{handle_task, TaskError};
use crate::queue::TaskQueue;
use crate::task::TaskStatus;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::watch;
use tokio_util::sync::CancellationToken;
use tracing::{error, info, warn, Instrument};

pub struct WorkerPool {
    workers: Vec<tokio::task::JoinHandle<()>>,
    cancel: CancellationToken,
}

impl WorkerPool {
    pub fn new(
        queue: Arc<TaskQueue>,
        worker_count: usize,
        task_timeout: Duration,
    ) -> Self {
        let cancel = CancellationToken::new();
        let mut workers = Vec::with_capacity(worker_count);

        for id in 0..worker_count {
            let queue = Arc::clone(&queue);
            let cancel = cancel.clone();
            let timeout = task_timeout;

            let handle = tokio::spawn(
                async move {
                    info!(worker_id = id, "Worker started");
                    Self::run_worker(id, queue, cancel, timeout).await;
                    info!(worker_id = id, "Worker stopped");
                }
                .instrument(tracing::info_span!("worker", id)),
            );

            workers.push(handle);
        }

        Self { workers, cancel }
    }

    async fn run_worker(
        id: usize,
        queue: Arc<TaskQueue>,
        cancel: CancellationToken,
        timeout: Duration,
    ) {
        loop {
            tokio::select! {
                _ = cancel.cancelled() => {
                    info!(worker_id = id, "Shutdown signal received");
                    break;
                }
                mut task = queue.pop() => {
                    task.status = TaskStatus::Running;
                    let task_id = task.id.clone();

                    info!(
                        worker_id = id,
                        task_id = %task_id,
                        task_type = ?std::mem::discriminant(&task.payload),
                        priority = ?task.priority,
                        "Processing task"
                    );

                    // Execute with timeout
                    let result = tokio::time::timeout(
                        timeout,
                        handle_task(&task.payload),
                    ).await;

                    match result {
                        Ok(Ok(())) => {
                            task.status = TaskStatus::Completed;
                            queue.mark_completed().await;
                            info!(
                                worker_id = id,
                                task_id = %task_id,
                                "Task completed"
                            );
                        }
                        Ok(Err(TaskError::Transient(e))) => {
                            queue.mark_failed().await;
                            warn!(
                                worker_id = id,
                                task_id = %task_id,
                                error = %e,
                                "Task failed (transient)"
                            );
                            queue.retry(task, e).await;
                        }
                        Ok(Err(TaskError::Permanent(e))) => {
                            queue.mark_failed().await;
                            error!(
                                worker_id = id,
                                task_id = %task_id,
                                error = %e,
                                "Task failed permanently — no retry"
                            );
                            task.status = TaskStatus::DeadLettered;
                            task.last_error = Some(e);
                        }
                        Ok(Err(TaskError::Timeout(d))) => {
                            queue.mark_failed().await;
                            let err = format!("Task timed out after {:?}", d);
                            queue.retry(task, err).await;
                        }
                        Err(_) => {
                            queue.mark_failed().await;
                            let err = format!("Task exceeded timeout of {:?}", timeout);
                            warn!(worker_id = id, task_id = %task_id, %err);
                            queue.retry(task, err).await;
                        }
                    }
                }
            }
        }
    }

    pub async fn shutdown(self) {
        info!("Initiating graceful shutdown...");
        self.cancel.cancel();

        for (i, handle) in self.workers.into_iter().enumerate() {
            if let Err(e) = handle.await {
                error!(worker_id = i, error = %e, "Worker panicked");
            }
        }

        info!("All workers stopped");
    }
}
