```rust
use std::fmt;
use std::io;
use std::num::{ParseFloatError, ParseIntError};

/// All possible errors that can occur during config parsing.
#[derive(Debug)]
pub enum ConfigError {
    /// Failed to read the config file
    IoError(io::Error),

    /// Syntax error in the config file
    SyntaxError {
        line_number: usize,
        line_content: String,
        message: String,
    },

    /// A required section is missing
    MissingSection(String),

    /// A required key is missing within a section
    MissingKey {
        section: String,
        key: String,
    },

    /// Value could not be converted to the expected type
    TypeError {
        section: String,
        key: String,
        expected: String,
        found: String,
    },

    /// Duplicate section definition
    DuplicateSection {
        name: String,
        first_line: usize,
        duplicate_line: usize,
    },

    /// Duplicate key within a section
    DuplicateKey {
        section: String,
        key: String,
        line_number: usize,
    },
}

// Implement Display for user-friendly error messages
impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::IoError(err) => {
                write!(f, "Failed to read config file: {err}")
            }
            ConfigError::SyntaxError {
                line_number,
                line_content,
                message,
            } => {
                write!(
                    f,
                    "Syntax error on line {line_number}: {message}\n  --> {line_content}"
                )
            }
            ConfigError::MissingSection(section) => {
                write!(f, "Missing required section: [{section}]")
            }
            ConfigError::MissingKey { section, key } => {
                write!(f, "Missing key '{key}' in section [{section}]")
            }
            ConfigError::TypeError {
                section,
                key,
                expected,
                found,
            } => {
                write!(
                    f,
                    "Type error for [{section}].{key}: expected {expected}, found '{found}'"
                )
            }
            ConfigError::DuplicateSection {
                name,
                first_line,
                duplicate_line,
            } => {
                write!(
                    f,
                    "Duplicate section [{name}] on line {duplicate_line} \
                     (first defined on line {first_line})"
                )
            }
            ConfigError::DuplicateKey {
                section,
                key,
                line_number,
            } => {
                write!(
                    f,
                    "Duplicate key '{key}' in section [{section}] on line {line_number}"
                )
            }
        }
    }
}

// Implement std::error::Error for compatibility with the ? operator and error chains
impl std::error::Error for ConfigError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            ConfigError::IoError(err) => Some(err),
            _ => None,
        }
    }
}

// Conversions using From — enables the ? operator on these error types
impl From<io::Error> for ConfigError {
    fn from(err: io::Error) -> Self {
        ConfigError::IoError(err)
    }
}

impl From<ParseIntError> for ConfigError {
    fn from(_: ParseIntError) -> Self {
        // Generic fallback; the parser builds a more specific TypeError instead
        ConfigError::SyntaxError {
            line_number: 0,
            line_content: String::new(),
            message: "invalid integer".to_string(),
        }
    }
}

impl From<ParseFloatError> for ConfigError {
    fn from(_: ParseFloatError) -> Self {
        ConfigError::SyntaxError {
            line_number: 0,
            line_content: String::new(),
            message: "invalid float".to_string(),
        }
    }
}
