/// A single key-value entry with its source line number (for error reporting).
#[derive(Debug, Clone)]
pub struct ConfigValue {
    pub value: String,
    pub line_number: usize,
}

/// Section maps: key -> ConfigValue
pub type Section = HashMap<String, ConfigValue>;

/// Parsed config: section_name -> Section
#[derive(Debug)]
pub struct ParsedConfig {
    sections: HashMap<String, Section>,
    /// Track where each section was first defined
    section_lines: HashMap<String, usize>,
}

impl ParsedConfig {
    /// Parse a config file from disk.
    pub fn from_file<P: AsRef<Path>>(path: P) -> Result<Self, ConfigError> {
        let content = fs::read_to_string(path)?; // ? converts io::Error via From
        Self::from_str(&content)
    }

    /// Parse config from a string.
    pub fn from_str(input: &str) -> Result<Self, ConfigError> {
        let mut sections: HashMap<String, Section> = HashMap::new();
        let mut section_lines: HashMap<String, usize> = HashMap::new();
        let mut current_section: Option<String> = None;

        for (line_idx, raw_line) in input.lines().enumerate() {
            let line_number = line_idx + 1; // 1-based for humans
            let line = raw_line.trim();

            // Skip empty lines and comments
            if line.is_empty() || line.starts_with('#') || line.starts_with(';') {
                continue;
            }

            // Section header: [section_name]
            if line.starts_with('[') {
                let section_name = Self::parse_section_header(line, line_number, raw_line)?;

                // Check for duplicate sections
                if let Some(&first_line) = section_lines.get(&section_name) {
                    return Err(ConfigError::DuplicateSection {
                        name: section_name,
                        first_line,
                        duplicate_line: line_number,
                    });
                }

                section_lines.insert(section_name.clone(), line_number);
                sections.insert(section_name.clone(), HashMap::new());
                current_section = Some(section_name);
                continue;
            }

            // Key-value pair: key = value
            let (key, value) = Self::parse_key_value(line, line_number, raw_line)?;

            match &current_section {
                Some(section) => {
                    let section_map = sections.get_mut(section).unwrap();

                    // Check for duplicate keys within the section
                    if section_map.contains_key(&key) {
                        return Err(ConfigError::DuplicateKey {
                            section: section.clone(),
                            key,
                            line_number,
                        });
                    }

                    section_map.insert(
                        key,
                        ConfigValue {
                            value,
                            line_number,
                        },
                    );
                }
                None => {
                    return Err(ConfigError::SyntaxError {
                        line_number,
                        line_content: raw_line.to_string(),
                        message: "key-value pair found outside of any section".to_string(),
                    });
                }
            }
        }

        Ok(ParsedConfig {
            sections,
            section_lines,
        })
    }

    // --- Private parsing helpers ---

    fn parse_section_header(
        line: &str,
        line_number: usize,
        raw_line: &str,
    ) -> Result<String, ConfigError> {
        if !line.ends_with(']') {
            return Err(ConfigError::SyntaxError {
                line_number,
                line_content: raw_line.to_string(),
                message: "section header missing closing ']'".to_string(),
            });
        }

        let name = line[1..line.len() - 1].trim();

        if name.is_empty() {
            return Err(ConfigError::SyntaxError {
                line_number,
                line_content: raw_line.to_string(),
                message: "empty section name".to_string(),
            });
        }

        // Validate section name (alphanumeric + underscores)
        if !name
            .chars()
            .all(|c| c.is_alphanumeric() || c == '_' || c == '-')
        {
            return Err(ConfigError::SyntaxError {
                line_number,
                line_content: raw_line.to_string(),
                message: format!(
                    "invalid section name '{name}': only alphanumeric, '_', '-' allowed"
                ),
            });
        }

        Ok(name.to_lowercase())
    }

    fn parse_key_value(
        line: &str,
        line_number: usize,
        raw_line: &str,
    ) -> Result<(String, String), ConfigError> {
        let parts: Vec<&str> = line.splitn(2, '=').collect();

        if parts.len() != 2 {
            return Err(ConfigError::SyntaxError {
                line_number,
                line_content: raw_line.to_string(),
                message: "expected 'key = value' format".to_string(),
            });
        }

        let key = parts[0].trim();
        let value = parts[1].trim();

        if key.is_empty() {
            return Err(ConfigError::SyntaxError {
                line_number,
                line_content: raw_line.to_string(),
                message: "empty key".to_string(),
            });
        }

        // Strip surrounding quotes from value if present
        let value = if (value.starts_with('"') && value.ends_with('"'))
            || (value.starts_with('\'') && value.ends_with('\''))
        {
            &value[1..value.len() - 1]
        } else {
            value
        };

        Ok((key.to_lowercase(), value.to_string()))
    }

    // --- Public accessors with typed retrieval ---

    /// Get a raw string value.
    pub fn get(&self, section: &str, key: &str) -> Result<&str, ConfigError> {
        let sect = self.sections.get(section).ok_or_else(|| {
            ConfigError::MissingSection(section.to_string())
        })?;

        let entry = sect.get(key).ok_or_else(|| ConfigError::MissingKey {
            section: section.to_string(),
            key: key.to_string(),
        })?;

        Ok(&entry.value)
    }

    /// Get a string value with a default if missing.
    pub fn get_or(&self, section: &str, key: &str, default: &str) -> String {
        self.get(section, key)
            .map(|v| v.to_string())
            .unwrap_or_else(|_| default.to_string())
    }

    /// Get a value parsed as the given type.
    pub fn get_parsed<T>(&self, section: &str, key: &str) -> Result<T, ConfigError>
    where
        T: std::str::FromStr,
        T::Err: fmt::Display,
    {
        let raw = self.get(section, key)?;
        raw.parse::<T>().map_err(|e| ConfigError::TypeError {
            section: section.to_string(),
            key: key.to_string(),
            expected: std::any::type_name::<T>().to_string(),
            found: format!("{raw} ({e})"),
        })
    }

    /// Get a boolean value (accepts true/false, yes/no, 1/0).
    pub fn get_bool(&self, section: &str, key: &str) -> Result<bool, ConfigError> {
        let raw = self.get(section, key)?.to_lowercase();
        match raw.as_str() {
            "true" | "yes" | "1" | "on" => Ok(true),
            "false" | "no" | "0" | "off" => Ok(false),
            _ => Err(ConfigError::TypeError {
                section: section.to_string(),
                key: key.to_string(),
                expected: "boolean (true/false/yes/no/1/0)".to_string(),
                found: raw,
            }),
        }
    }

    /// List all section names.
    pub fn sections(&self) -> Vec<&str> {
        self.sections.keys().map(|s| s.as_str()).collect()
    }

    /// List all keys in a section.
    pub fn keys(&self, section: &str) -> Result<Vec<&str>, ConfigError> {
        let sect = self.sections.get(section).ok_or_else(|| {
            ConfigError::MissingSection(section.to_string())
        })?;
        Ok(sect.keys().map(|k| k.as_str()).collect())
    }
}

