use crate::error::ConfigError;
use crate::parser::ParsedConfig;

/// Strongly typed application configuration.
#[derive(Debug)]
pub struct AppConfig {
    pub database: DatabaseConfig,
    pub server: ServerConfig,
    pub logging: LoggingConfig,
}

#[derive(Debug)]
pub struct DatabaseConfig {
    pub host: String,
    pub port: u16,
    pub name: String,
    pub max_connections: u32,
}

#[derive(Debug)]
pub struct ServerConfig {
    pub host: String,
    pub port: u16,
    pub debug: bool,
    pub workers: usize,
}

#[derive(Debug, PartialEq)]
pub enum LogLevel {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
}

impl LogLevel {
    fn from_str(s: &str) -> Result<Self, String> {
        match s.to_lowercase().as_str() {
            "trace" => Ok(LogLevel::Trace),
            "debug" => Ok(LogLevel::Debug),
            "info" => Ok(LogLevel::Info),
            "warn" | "warning" => Ok(LogLevel::Warn),
            "error" => Ok(LogLevel::Error),
            other => Err(format!("unknown log level: '{other}'")),
        }
    }
}

#[derive(Debug)]
pub struct LoggingConfig {
    pub level: LogLevel,
    pub file: Option<String>,
}

impl AppConfig {
    /// Build a fully validated AppConfig from a ParsedConfig.
    /// Collects ALL errors instead of stopping at the first one.
    pub fn from_parsed(parsed: &ParsedConfig) -> Result<Self, Vec<ConfigError>> {
        let mut errors: Vec<ConfigError> = Vec::new();

        // --- Database section ---
        let database = Self::build_database(parsed, &mut errors);

        // --- Server section ---
        let server = Self::build_server(parsed, &mut errors);

        // --- Logging section ---
        let logging = Self::build_logging(parsed, &mut errors);

        if !errors.is_empty() {
            return Err(errors);
        }

        Ok(AppConfig {
            database: database.unwrap(),
            server: server.unwrap(),
            logging: logging.unwrap(),
        })
    }

    fn build_database(
        parsed: &ParsedConfig,
        errors: &mut Vec<ConfigError>,
    ) -> Option<DatabaseConfig> {
        let host = Self::try_get(parsed, "database", "host", errors)?;
        let port = Self::try_get_parsed::<u16>(parsed, "database", "port", errors)?;
        let name = Self::try_get(parsed, "database", "name", errors)?;
        let max_connections = Self::try_get_parsed::<u32>(
            parsed, "database", "max_connections", errors,
        )?;

        Some(DatabaseConfig {
            host,
            port,
            name,
            max_connections,
        })
    }

    fn build_server(
        parsed: &ParsedConfig,
        errors: &mut Vec<ConfigError>,
    ) -> Option<ServerConfig> {
        let host = parsed
            .get_or("server", "host", "127.0.0.1");
        let port = Self::try_get_parsed::<u16>(parsed, "server", "port", errors)?;

        let debug = match parsed.get_bool("server", "debug") {
            Ok(v) => v,
            Err(e) => {
                errors.push(e);
                return None;
            }
        };

        let workers = Self::try_get_parsed::<usize>(
            parsed, "server", "workers", errors,
        ).unwrap_or(num_cpus());

