```javascript
// src/errors/ParserErrors.js

"use strict";

class ParseError extends Error {
  /**
   * @param {string} message
   * @param {Object} [details]
   */
  constructor(message, details = {}) {
    super(message);
    this.name = "ParseError";
    this.code = "ERR_PARSE";
    this.details = details;
    Error.captureStackTrace(this, this.constructor);
  }

  toJSON() {
    return {
      name: this.name,
      code: this.code,
      message: this.message,
      details: this.details,
    };
  }
}

class ValidationError extends Error {
  /**
   * @param {string}   message
   * @param {string[]} schemaErrors
   */
  constructor(message, schemaErrors = []) {
    super(message);
    this.name = "ValidationError";
    this.code = "ERR_VALIDATION";
    this.schemaErrors = schemaErrors;
    Error.captureStackTrace(this, this.constructor);
  }

  toJSON() {
    return {
      name: this.name,
      code: this.code,
      message: this.message,
      schemaErrors: this.schemaErrors,
    };
  }
}

class TransformError extends Error {
  /**
   * @param {string} message
   * @param {string} transformName
   * @param {Error}  cause
   */
  constructor(message, transformName, cause) {
    super(message);
    this.name = "TransformError";
    this.code = "ERR_TRANSFORM";
    this.transformName = transformName;
    this.cause = cause;
    Error.captureStackTrace(this, this.constructor);
  }

  toJSON() {
    return {
      name: this.name,
      code: this.code,
      message: this.message,
      transformName: this.transformName,
    };
  }
}

module.exports = { ParseError, ValidationError, TransformError };
