## Schema Validator

```javascript
// src/parser/SchemaValidator.js

"use strict";

/**
 * Lightweight JSON schema validator supporting a useful subset of JSON Schema.
 * For production, swap this with `ajv` — this serves as a zero-dependency fallback.
 */
class SchemaValidator {
  /**
   * Validate data against a schema definition.
   * @param   {*}      data
   * @param   {Object} schema
   * @returns {{ valid: boolean, errors: string[] }}
   */
  validate(data, schema) {
    const errors = [];
    this._validate(data, schema, "", errors);
    return { valid: errors.length === 0, errors };
  }

  /** @private */
  _validate(data, schema, path, errors) {
    if (!schema || typeof schema !== "object") return;

    // ── type check ──────────────────────────────────────────
    if (schema.type) {
      if (!this._checkType(data, schema.type)) {
        errors.push(
          `${path || "root"}: expected type "${schema.type}", got "${this._typeOf(data)}"`
        );
        return; // skip deeper checks if type is wrong
      }
    }

    // ── required fields ─────────────────────────────────────
    if (schema.required && Array.isArray(schema.required)) {
      for (const key of schema.required) {
        if (data == null || !(key in data)) {
          errors.push(`${path || "root"}: missing required field "${key}"`);
        }
      }
    }

    // ── properties (object) ─────────────────────────────────
    if (schema.properties && typeof data === "object" && data !== null) {
      for (const [key, subSchema] of Object.entries(schema.properties)) {
        if (key in data) {
          this._validate(data[key], subSchema, `${path}.${key}`, errors);
        }
      }
    }

    // ── items (array) ───────────────────────────────────────
    if (schema.items && Array.isArray(data)) {
      data.forEach((item, idx) => {
        this._validate(item, schema.items, `${path}[${idx}]`, errors);
      });
    }

    // ── enum ────────────────────────────────────────────────
    if (schema.enum && !schema.enum.includes(data)) {
      errors.push(
        `${path || "root"}: value must be one of [${schema.enum.join(", ")}]`
      );
    }

    // ── string constraints ──────────────────────────────────
    if (typeof data === "string") {
      if (schema.minLength != null && data.length < schema.minLength) {
        errors.push(`${path}: string length below minimum ${schema.minLength}`);
      }
      if (schema.maxLength != null && data.length > schema.maxLength) {
        errors.push(`${path}: string length exceeds maximum ${schema.maxLength}`);
      }
      if (schema.pattern && !new RegExp(schema.pattern).test(data)) {
        errors.push(`${path}: string does not match pattern "${schema.pattern}"`);
      }
    }

    // ── number constraints ──────────────────────────────────
    if (typeof data === "number") {
      if (schema.minimum != null && data < schema.minimum) {
        errors.push(`${path}: value ${data} is below minimum ${schema.minimum}`);
      }
      if (schema.maximum != null && data > schema.maximum) {
        errors.push(`${path}: value ${data} exceeds maximum ${schema.maximum}`);
      }
    }
  }

  /** @private */
  _checkType(value, type) {
    switch (type) {
      case "string":  return typeof value === "string";
      case "number":  return typeof value === "number" && Number.isFinite(value);
      case "integer": return Number.isInteger(value);
      case "boolean": return typeof value === "boolean";
      case "array":   return Array.isArray(value);

