```javascript
import { createWriteStream, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const LOG_LEVELS = Object.freeze({
  error: 0,
  warn: 1,
  info: 2,
  debug: 3,
});

export class Logger {
  #level;
  #fileStream;
  #context;

  /**
   * @param {object} options
   * @param {"error"|"warn"|"info"|"debug"} options.level
   * @param {string} [options.logFile]
   * @param {string} [options.context]
   */
  constructor({ level = "info", logFile, context = "FileSync" }) {
    this.#level = LOG_LEVELS[level] ?? LOG_LEVELS.info;
    this.#context = context;

    if (logFile) {
      mkdirSync(dirname(logFile), { recursive: true });
      this.#fileStream = createWriteStream(logFile, { flags: "a" });
    }
  }

  #format(level, message, meta) {
    const entry = {
      timestamp: new Date().toISOString(),
      level,
      context: this.#context,
      message,
      ...(meta && Object.keys(meta).length > 0 ? { meta } : {}),
    };
    return JSON.stringify(entry);
  }

  #write(level, message, meta) {
    if (LOG_LEVELS[level] > this.#level) return;

    const formatted = this.#format(level, message, meta);

    // Console output with color
    const colors = { error: "\x1b[31m", warn: "\x1b[33m", info: "\x1b[36m", debug: "\x1b[90m" };
    const reset = "\x1b[0m";
    const prefix = `${colors[level]}[${level.toUpperCase()}]${reset}`;
    const metaStr = meta && Object.keys(meta).length > 0 ? ` ${JSON.stringify(meta)}` : "";
    console.log(`${prefix} ${message}${metaStr}`);

    // File output (structured JSON)
    this.#fileStream?.write(formatted + "\n");
  }

  error(message, meta) { this.#write("error", message, meta); }
  warn(message, meta)  { this.#write("warn", message, meta); }
  info(message, meta)  { this.#write("info", message, meta); }
  debug(message, meta) { this.#write("debug", message, meta); }

  child(context) {
    const child = Object.create(this);
    child.#context = `${this.#context}:${context}`;
    return child;
  }

  async close() {
    return new Promise((resolve) => {
      if (this.#fileStream) {
        this.#fileStream.end(resolve);
      } else {
        resolve();
      }
    });
  }
}
