import { readFile, access, constants } from "node:fs/promises";
import { resolve, isAbsolute } from "node:path";

/** @typedef {import("./sync-engine.js").SyncPair} SyncPair */

/**
 * @typedef {object} SyncConfig
 * @property {SyncPair[]} syncPairs
 * @property {SyncOptions} options
 */

/**
 * @typedef {object} SyncOptions
 * @property {boolean}  dryRun
 * @property {boolean}  watch
 * @property {boolean}  useChecksum
 * @property {string}   checksumAlgorithm
 * @property {number}   concurrency
 * @property {number}   retryAttempts
 * @property {number}   retryDelayMs
 * @property {string}   logLevel
 * @property {string}   [logFile]
 */

const DEFAULTS = Object.freeze({
  dryRun: false,
  watch: false,
  useChecksum: true,
  checksumAlgorithm: "sha256",
  concurrency: 10,
  retryAttempts: 3,
  retryDelayMs: 1000,
  logLevel: "info",
});

export class ConfigLoader {
  /**
   * Load and validate configuration from a JSON file, with CLI overrides.
   * @param {string} configPath
   * @param {Partial<SyncOptions>} [cliOverrides]
   * @returns {Promise<SyncConfig>}
   */
  static async load(configPath, cliOverrides = {}) {
    const absolutePath = isAbsolute(configPath)
      ? configPath
      : resolve(process.cwd(), configPath);

    await access(absolutePath, constants.R_OK).catch(() => {
      throw new Error(`Config file not found or not readable: ${absolutePath}`);
    });

    const raw = await readFile(absolutePath, "utf-8");

    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (err) {
      throw new Error(`Invalid JSON in config file: ${err.message}`);
    }

    return ConfigLoader.#validate(parsed, cliOverrides);
  }

  /**
   * @param {object} raw
   * @param {Partial<SyncOptions>} overrides
   * @returns {SyncConfig}
   */
  static #validate(raw, overrides) {
    const errors = [];

    // --- syncPairs -----------------------------------------------------------
    if (!Array.isArray(raw.syncPairs) || raw.syncPairs.length === 0) {
      errors.push('"syncPairs" must be a non-empty array.');
    }

    const pairs = (raw.syncPairs ?? []).map((pair, idx) => {
      const id = pair.id ?? `pair-${idx}`;

      if (typeof pair.source !== "string" || pair.source.trim() === "") {
        errors.push(`syncPairs[${idx}]: "source" must be a non-empty string.`);
      }
      if (typeof pair.destination !== "string" || pair.destination.trim() === "") {
        errors.push(`syncPairs[${idx}]: "destination" must be a non-empty string.`);
      }

      const exclude = Array.isArray(pair.exclude)
        ? pair.exclude.filter((e) => typeof e === "string")
        : [];

      return {
        id,
        source: resolve(process.cwd(), pair.source ?? ""),
        destination: resolve(process.cwd(), pair.destination ?? ""),
        exclude,
        deleteOrphaned: pair.deleteOrphaned === true,
      };
    });

    // --- options -------------------------------------------------------------
    const rawOpts = raw.options ?? {};
    const options = { ...DEFAULTS, ...rawOpts, ...overrides };

    if (!["error", "warn", "info", "debug"].includes(options.logLevel)) {
      errors.push(`Invalid logLevel: "${options.logLevel}".`);
    }
    if (typeof options.concurrency !== "number" || options.concurrency < 1) {
      errors.push('"concurrency" must be a positive integer.');
    }
    if (typeof options.retryAttempts !== "number" || options.retryAttempts < 0) {
      errors.push('"retryAttempts" must be a non-negative integer.');
    }

    if (errors.length > 0) {
      throw new Error(`Config validation failed:\n  - ${errors.join("\n  - ")}`);
    }

    return { syncPairs: pairs, options };
  }
}
