/**
 * @typedef {object} SyncStats
 * @property {number} filesScanned
 * @property {number} filesCopied
 * @property {number} filesDeleted
 * @property {number} dirsCreated
 * @property {number} dirsDeleted
 * @property {number} errors
 * @property {number} bytesTransferred
 * @property {number} durationMs
 */

export class SyncEngine extends EventEmitter {
  #options;
  #logger;
  #aborted = false;

  /**
   * @param {import("./config-loader.js").SyncOptions} options
   * @param {import("./logger.js").Logger} logger
   */
  constructor(options, logger) {
    super();
    this.#options = options;
    this.#logger = logger;
  }

  /** Abort any in-progress sync. */
  abort() {
    this.#aborted = true;
  }

  /**
   * Execute synchronization for a single pair.
   * @param {SyncPair} pair
   * @returns {Promise<SyncStats>}
   */
  async sync(pair) {
    this.#aborted = false;
    const start = performance.now();
    const log = this.#logger.child(pair.id);

    /** @type {SyncStats} */
    const stats = {
      filesScanned: 0,
      filesCopied: 0,
      filesDeleted: 0,
      dirsCreated: 0,
      dirsDeleted: 0,
      errors: 0,
      bytesTransferred: 0,
      durationMs: 0,
    };

    log.info("Starting sync", { source: pair.source, destination: pair.destination });

    try {
      // Build file manifests for source and destination.
      const [sourceManifest, destManifest] = await Promise.all([
        this.#buildManifest(pair.source, pair.source, pair.exclude, stats),
        this.#buildManifest(pair.destination, pair.destination, pair.exclude, stats).catch(
          () => new Map() // destination may not exist yet
        ),
      ]);

      // Determine work items.
      const toCopy = [];
      const toDelete = [];

      for (const [relPath, srcEntry] of sourceManifest) {
        const destEntry = destManifest.get(relPath);
        if (!destEntry || (await this.#needsUpdate(srcEntry, destEntry))) {
          toCopy.push(relPath);
        }
      }

      if (pair.deleteOrphaned) {
        for (const relPath of destManifest.keys()) {
          if (!sourceManifest.has(relPath)) {
            toDelete.push(relPath);
          }
        }
      }

      log.info("Sync plan computed", {
        toCopy: toCopy.length,
        toDelete: toDelete.length,
      });

      // Copy files with concurrency limiter.
      await this.#runPool(toCopy, async (relPath) => {
        await this.#copyWithRetry(pair.source, pair.destination, relPath, stats, log);
      });

      // Delete orphans.
      await this.#runPool(toDelete, async (relPath) => {
        await this.#deleteEntry(pair.destination, relPath, stats, log);
      });

      // Clean empty directories in destination after deletions.
      if (pair.deleteOrphaned && toDelete.length > 0) {
        await this.#pruneEmptyDirs(pair.destination, log, stats);
      }
    } catch (err) {
      stats.errors++;
      log.error("Sync failed with unrecoverable error", { error: err.message });
    }

    stats.durationMs = Math.round(performance.now() - start);
    log.info("Sync complete", stats);
    this.emit("sync-complete", { pairId: pair.id, stats });
    return stats;
  }

  // ---------------------------------------------------------------------------
  //  Manifest building
  // ---------------------------------------------------------------------------

  /**
   * Recursively walk a directory and build a Map<relativePath, FileEntry>.
   * @param {string} root
   * @param {string} dir
   * @param {string[]} exclude
   * @param {SyncStats} stats
   * @returns {Promise<Map<string, {absPath:string, size:number, mtimeMs:number}>>}
   */
  async #buildManifest(root, dir, exclude, stats) {
    /** @type {Map<string, {absPath:string, size:number, mtimeMs:number}>} */
    const manifest = new Map();
    await this.#walk(root, dir, exclude, manifest, stats);
    return manifest;
  }

  async #walk(root, dir, exclude, manifest, stats) {
    if (this.#aborted) return;

    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch (err) {
      this.#logger.warn("Cannot read directory", { dir, error: err.message });
      stats.errors++;
      return;
    }

    for (const entry of entries) {
      if (this.#aborted) return;
      if (this.#isExcluded(entry.name, exclude)) continue;

      const absPath = join(dir, entry.name);
      const relPath = relative(root, absPath);

      if (entry.isDirectory()) {
        await this.#walk(root, absPath, exclude, manifest, stats);
      } else if (entry.isFile() || entry.isSymbolicLink()) {
        try {
          const info = await stat(absPath);
          stats.filesScanned++;
          manifest.set(relPath, {
            absPath,
            size: info.size,
            mtimeMs: info.mtimeMs,
          });
        } catch (err) {
          this.#logger.warn("Cannot stat file", { absPath, error: err.message });
          stats.errors++;
        }
      }
    }
