import java.util.concurrent.*;
import java.util.function.Consumer;

public class TaskQueueConsumer {

    private final BlockingQueue<Runnable> taskQueue;
    private final ExecutorService executor;
    private volatile boolean running;
    private final int workerCount;

    public TaskQueueConsumer(int queueCapacity, int workerCount) {
        this.taskQueue = new LinkedBlockingQueue<>(queueCapacity);
        this.workerCount = workerCount;
        this.executor = Executors.newFixedThreadPool(workerCount);
        this.running = false;
    }

    // Start consuming tasks
    public void start() {
        running = true;
        for (int i = 0; i < workerCount; i++) {
            final int workerId = i;
            executor.submit(() -> {
                System.out.println("Worker-" + workerId + " started.");
                while (running || !taskQueue.isEmpty()) {
                    try {
                        Runnable task = taskQueue.poll(500, TimeUnit.MILLISECONDS);
                        if (task != null) {
                            System.out.println("Worker-" + workerId + " executing task...");
                            task.run();
                        }
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    } catch (Exception e) {
                        System.err.println("Worker-" + workerId + " error: " + e.getMessage());
                    }
                }
                System.out.println("Worker-" + workerId + " stopped.");
            });
        }
    }

    // Submit a task to the queue
    public boolean submit(Runnable task) {
        if (!running) {
            throw new IllegalStateException("Consumer is not running.");
        }
        return taskQueue.offer(task);
    }

    // Submit with timeout
    public boolean submit(Runnable task, long timeout, TimeUnit unit) throws InterruptedException {
        if (!running) {
            throw new IllegalStateException("Consumer is not running.");
        }
        return taskQueue.offer(task, timeout, unit);
    }

    // Schedule a delayed task
    public void submitDelayed(Runnable task, long delayMs) {
        submit(() -> {
            try {
                Thread.sleep(delayMs);
                task.run();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
    }

    // Graceful shutdown
    public void shutdown() {
        System.out.println("Shutting down... " + taskQueue.size() + " tasks remaining.");
        running = false;
        executor.shutdown();
        try {
            if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
        System.out.println("Shutdown complete.");
    }

    public int pendingTasks() {
        return taskQueue.size();
    }

    public boolean isRunning() {
        return running;
    }

    // --- Demo ---
    public static void main(String[] args) throws InterruptedException {
        TaskQueueConsumer consumer = new TaskQueueConsumer(100, 3);
        consumer.start();

        // Submit basic tasks
        for (int i = 1; i <= 10; i++) {
            final int taskId = i;
            consumer.submit(() -> {
                System.out.println("  Task-" + taskId + " running on " + Thread.currentThread().getName());
                try {
                    Thread.sleep(500); // simulate work
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                System.out.println("  Task-" + taskId + " done.");
            });
        }

        System.out.println("Pending tasks: " + consumer.pendingTasks());

        // Wait for tasks to process
        Thread.sleep(5000);

        consumer.shutdown();
    }
