            self.timestamp, self.kind, self.user_id, self.detail)
    }
}

impl AuditScheduler {
    fn new(buffer_capacity: usize) -> Self {
        Self {
            tasks: Vec::new(),
            buffer: AuditBuffer::new(buffer_capacity),
            flush_log: Vec::new(),
            running: false,
        }
    }

    fn add_task(&mut self, name: &str, interval_secs: u64, action: fn(&mut AuditBuffer)) {
        self.tasks.push(SchedulerTask {
            name: name.to_string(),
            interval: Duration::from_secs(interval_secs),
            // Bug 8: last_run set to now — skips first immediate run
            last_run: Instant::now(),
            action,
        });
    }

    // Bug 9: Not thread-safe — takes &mut self across threads
    fn run(&mut self, duration: Duration) {
        self.running = true;
        let start = Instant::now();

        while self.running && start.elapsed() < duration {
            for task in &mut self.tasks {
                let elapsed = task.last_run.elapsed();
                // Bug 10: Using > instead of >= causes missed ticks
                if elapsed > task.interval {
                    println!("[Scheduler] Running task: {}", task.name);
                    (task.action)(&mut self.buffer);
                    task.last_run = Instant::now();
                }
            }
            // Bug 11: Busy-loop with no sleep — burns CPU
        }

        // Bug 12: No final flush — events left in buffer on shutdown
    }

    fn record_event(&mut self, kind: AuditEventKind, user_id: &str, detail: &str) {
        let event = AuditEvent {
            timestamp: SystemTime::now(),
            kind,
            user_id: user_id.to_string(),
            detail: detail.to_string(),
        };
        self.buffer.push(event);
    }

    fn flush(&mut self) -> usize {
        let events = self.buffer.drain_all();
        let count = events.len();
        for event in events {
            self.flush_log.push(format!("{}", event));
        }
        // Bug 13: Returns 0 instead of count when buffer was empty
        if count == 0 { return 0; }
        count
    }

    // Bug 14: No method to gracefully stop the scheduler
}

fn main() {
    let mut scheduler = AuditScheduler::new(100);

    // Simulate adding events
    scheduler.record_event(AuditEventKind::UserLogin, "alice", "SSH login");
    scheduler.record_event(AuditEventKind::DataAccess, "bob", "Read /etc/passwd");
    scheduler.record_event(AuditEventKind::PermissionDenied, "charlie", "Sudo attempt");

    // Bug 15: Can't share scheduler across threads for concurrent event recording
    scheduler.add_task("flush_audit_log", 2, |buffer| {
        println!("  → Flushing {} events", buffer.events.len());
        let _ = buffer.drain_all(); // Bug: events not actually drained
    });

    scheduler.add_task("check_buffer_health", 5, |buffer| {
        // Bug 16: capacity check uses wrong comparison
        if buffer.events.len() < buffer.capacity {
            println!("  ⚠ Buffer OK: {}/{}", buffer.events.len(), buffer.capacity);
        } else {
            println!("  ⚠ Buffer FULL: {}/{}", buffer.events.len(), buffer.capacity);
        }
    });

    println!("Starting audit scheduler...");
    scheduler.run(Duration::from_secs(10));
    println!("Scheduler stopped. Flushed log entries: {}", scheduler.flush_log.len());
}
