use std::collections::HashMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use std::fmt;

// ───────────────────────────────────────────────
// Fix 1: Derive Clone for use inside Arc<Mutex<>>
// ───────────────────────────────────────────────
#[derive(Debug, Clone)]
enum AuditEventKind {
    UserLogin,
    UserLogout,
    DataAccess,
    ConfigChange,
    PermissionDenied,
}

#[derive(Debug, Clone)]
struct AuditEvent {
    timestamp: SystemTime,
    kind: AuditEventKind,
    user_id: String,
    detail: String,
}

// ───────────────────────────────────────────────
// Fix 7: Proper timestamp display formatting
// ───────────────────────────────────────────────
impl fmt::Display for AuditEvent {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let elapsed = self.timestamp
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default();
        let secs = elapsed.as_secs();
        write!(
            f,
            "[ts={}] {:?} by {}: {}",
            secs, self.kind, self.user_id, self.detail
        )
    }
}

// ───────────────────────────────────────────────
// Fix 2 & 5: Thread-safe buffer with capacity enforcement
// ───────────────────────────────────────────────
struct AuditBuffer {
    events: Vec<AuditEvent>,
    capacity: usize,
    dropped_count: usize, // track dropped events
}

impl AuditBuffer {
    fn new(capacity: usize) -> Self {
        Self {
            events: Vec::with_capacity(capacity),
            capacity,
            dropped_count: 0,
        }
    }

    // Fix 5: Enforce capacity — drop oldest if full
    fn push(&mut self, event: AuditEvent) {
        if self.events.len() >= self.capacity {
            self.events.remove(0); // evict oldest
            self.dropped_count += 1;
            eprintln!(
                "  ⚠ Buffer full — dropped oldest event (total dropped: {})",
                self.dropped_count
            );
        }
        self.events.push(event);
    }

    // Fix 6: Use .drain(..) to actually remove events from the buffer
    fn drain_all(&mut self) -> Vec<AuditEvent> {
        self.events.drain(..).collect()
    }

    fn len(&self) -> usize {
        self.events.len()
    }

    fn is_empty(&self) -> bool {
        self.events.is_empty()
    }
}

// ───────────────────────────────────────────────
// Fix 3: Use Box<dyn Fn> for flexible task closures
// Fix 9: Tasks work on Arc<Mutex<AuditBuffer>>
// ───────────────────────────────────────────────
struct SchedulerTask {
    name: String,
    interval: Duration,
    last_run: Instant,
    action: Box<dyn Fn(&Arc<Mutex<AuditBuffer>>) + Send>,
}

// ───────────────────────────────────────────────
// Fix 4, 9, 14, 15: Thread-safe scheduler with
// shutdown signal and shared buffer
// ───────────────────────────────────────────────
struct AuditScheduler {
    tasks: Vec<SchedulerTask>,
    buffer: Arc<Mutex<AuditBuffer>>,
    flush_log: Arc<Mutex<Vec<String>>>,
    running: Arc<AtomicBool>, // Fix 4 & 14: atomic shutdown flag
}

impl AuditScheduler {
    fn new(buffer_capacity: usize) -> Self {
        Self {
            tasks: Vec::new(),
            buffer: Arc::new(Mutex::new(AuditBuffer::new(buffer_capacity))),
            flush_log: Arc::new(Mutex::new(Vec::new())),
            running: Arc::new(AtomicBool::new(false)),
        }
    }

    // Fix 15: Return a handle to record events from any thread
    fn buffer_handle(&self) -> Arc<Mutex<AuditBuffer>> {
        Arc::clone(&self.buffer)
    }

    fn add_task<F>(&mut self, name: &str, interval_secs: u64, action: F)
    where
        F: Fn(&Arc<Mutex<AuditBuffer>>) + Send + 'static,
    {
        self.tasks.push(SchedulerTask {
            name: name.to_string(),
            interval: Duration::from_secs(interval_secs),
            // Fix 8: Set last_run to the past so the task fires immediately
            last_run: Instant::now() - Duration::from_secs(interval_secs),
            action: Box::new(action),
        });
    }

    fn run(&mut self, duration: Duration) {
        self.running.store(true, Ordering::SeqCst);
        let start = Instant::now();

        while self.running.load(Ordering::SeqCst) && start.elapsed() < duration {
            for task in &mut self.tasks {
                let elapsed = task.last_run.elapsed();
                // Fix 10: Use >= so the tick isn't missed by a nanosecond
                if elapsed >= task.interval {
                    println!("[Scheduler] Running task: {}", task.name);
                    (task.action)(&self.buffer);
                    task.last_run = Instant::now();
                }
            }
            // Fix 11: Sleep briefly to avoid burning CPU
            thread::sleep(Duration::from_millis(50));
        }

        // Fix 12: Final flush on shutdown
        println!("[Scheduler] Shutting down — final flush...");
        self.flush();
    }

    // Fix 14: Graceful stop from another thread
    fn stop_handle(&self) -> Arc<AtomicBool> {
        Arc::clone(&self.running)
    }

    fn record_event(&self, kind: AuditEventKind, user_id: &str, detail: &str) {
        let event = AuditEvent {
            timestamp: SystemTime::now(),
            kind,
            user_id: user_id.to_string(),
            detail: detail.to_string(),
        };
        // Fix 9: Lock the mutex for safe concurrent access
        let mut buf = self.buffer.lock().expect("buffer lock poisoned");
        buf.push(event);
    }

    fn flush(&self) -> usize {
        let mut buf = self.buffer.lock().expect("buffer lock poisoned");
        let events = buf.drain_all(); // Fix 6: actually drains
        let count = events.len();

        let mut log = self.flush_log.lock().expect("log lock poisoned");
        for event in &events {
            log.push(format!("{}", event));
        }

        println!("  → Flushed {} audit events to log", count);
        count
    }

    fn get_log_snapshot(&self) -> Vec<String> {
        let log = self.flush_log.lock().expect("log lock poisoned");
        log.clone()
    }
}

// ───────────────────────────────────────────────
// Helper: record events from a separate thread
// ───────────────────────────────────────────────
fn simulate_concurrent_events(buffer: Arc<Mutex<AuditBuffer>>) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let events = vec![
            (AuditEventKind::UserLogin,       "dave",    "SSH from 10.0.0.5"),
            (AuditEventKind::ConfigChange,    "eve",     "Updated firewall rules"),
            (AuditEventKind::DataAccess,      "frank",   "SELECT * FROM users"),
            (AuditEventKind::PermissionDenied,"mallory", "Attempted rm -rf /"),
