            let event = AuditEvent {
                timestamp: SystemTime::now(),
                kind,
                user_id: user.to_string(),
                detail: detail.to_string(),
            };
            let mut buf = buffer.lock().expect("buffer lock poisoned");
            buf.push(event);
            println!("  [producer] Recorded event from {}", user);
        }
    })
}

// ───────────────────────────────────────────────
// Main
// ───────────────────────────────────────────────
fn main() {
    let mut scheduler = AuditScheduler::new(100);

    // Record initial events
    scheduler.record_event(AuditEventKind::UserLogin, "alice", "SSH login");
    scheduler.record_event(AuditEventKind::DataAccess, "bob", "Read /etc/passwd");
    scheduler.record_event(
        AuditEventKind::PermissionDenied,
        "charlie",
        "Sudo attempt",
    );

    // ── Task: periodic flush ──
    let flush_log = Arc::clone(&scheduler.flush_log);
    scheduler.add_task("flush_audit_log", 2, move |buffer| {
        let mut buf = buffer.lock().expect("lock poisoned");
        let events = buf.drain_all();
        let count = events.len();
        let mut log = flush_log.lock().expect("log lock poisoned");
        for e in &events {
            log.push(format!("{}", e));
        }
        println!("  → Task flushed {} events", count);
    });

    // ── Task: health check ──
    // Fix 16: Corrected comparison (>= means full, < means OK)
    scheduler.add_task("check_buffer_health", 3, |buffer| {
        let buf = buffer.lock().expect("lock poisoned");
        if buf.len() < buf.capacity {
            println!(
                "  ✓ Buffer OK: {}/{}",
                buf.len(),
                buf.capacity
            );
        } else {
            println!(
                "  ⚠ Buffer FULL: {}/{}",
                buf.len(),
                buf.capacity
            );
        }
    });

    // Fix 15: Concurrent event recording from another thread
    let buf_handle = scheduler.buffer_handle();
    let producer = simulate_concurrent_events(buf_handle);

    // Fix 14: Graceful shutdown from another thread after 6 seconds
    let stop = scheduler.stop_handle();
    let stopper = thread::spawn(move || {
        thread::sleep(Duration::from_secs(6));
        println!("[Stopper] Requesting graceful shutdown...");
        stop.store(false, Ordering::SeqCst);
    });

    println!("═══ Starting Audit Scheduler ═══\n");
    scheduler.run(Duration::from_secs(10)); // max 10s, but stopper ends at 6s

    producer.join().expect("producer thread panicked");
    stopper.join().expect("stopper thread panicked");

    // Final report
    let log = scheduler.get_log_snapshot();
    println!("\n═══ Persisted Audit Log ({} entries) ═══", log.len());
    for (i, entry) in log.iter().enumerate() {
        println!("  {}. {}", i + 1, entry);
    }
