// src/checks/profanity.js

// In production, use a maintained word list or an external API.
// This is a minimal example with pattern matching.
const BLOCKED_PATTERNS = [
  /\bf+u+c+k+/i,
  /\bs+h+i+t+/i,
  /\ba+s+s+h+o+l+e+/i,
  /\bb+i+t+c+h+/i,
  /\bn+i+g+/i,
  /\bf+a+g+/i,
];

// Leet-speak normalization
const LEET_MAP = {
  '0': 'o', '1': 'i', '3': 'e', '4': 'a',
  '5': 's', '7': 't', '@': 'a', '$': 's',
};

function normalizeLeet(text) {
  return text.replace(/[013457@$]/g, (ch) => LEET_MAP[ch] || ch);
}

export function checkProfanity(text) {
  const normalized = normalizeLeet(text);

  for (const pattern of BLOCKED_PATTERNS) {
    if (pattern.test(normalized)) {
      return {
        passed: false,
        reason: 'profanity_detected',
        detail: `Matched pattern: ${pattern.source}`,
      };
    }
  }

  return { passed: true };
}
