// src/checks/spam.js
import config from '../config.js';

const { capsRatio, minLengthForCaps, repeatCharThreshold } = config.moderation;

export function checkSpam(text) {
  const issues = [];

  // 1. Excessive caps
  if (text.length >= minLengthForCaps) {
    const letters = text.replace(/[^a-zA-Z]/g, '');
    const upperCount = (letters.match(/[A-Z]/g) || []).length;
    if (letters.length > 0 && upperCount / letters.length > capsRatio) {
      issues.push('excessive_caps');
    }
  }

  // 2. Repeated characters ("heeeeelp" is fine, "aaaaaaaaaa" is not)
  const repeatRegex = new RegExp(`(.)\\1{${repeatCharThreshold - 1},}`, 'g');
  if (repeatRegex.test(text)) {
    issues.push('repeated_characters');
  }

  // 3. Duplicate words/phrases ("buy now buy now buy now")
  const words = text.toLowerCase().split(/\s+/);
  if (words.length >= 6) {
    const uniqueRatio = new Set(words).size / words.length;
    if (uniqueRatio < 0.4) {
      issues.push('repetitive_content');
    }
  }

  if (issues.length > 0) {
    return { passed: false, reason: 'spam_detected', detail: issues.join(', ') };
  }

  return { passed: true };
}
