```js
// src/checks/links.js

const ALLOWED_DOMAINS = new Set([
  'youtube.com', 'youtu.be',
  'twitter.com', 'x.com',
  'github.com',
]);

const URL_REGEX = /https?:\/\/([^\s/$.?#].[^\s]*)/gi;

export function checkLinks(text) {
  const urls = [...text.matchAll(URL_REGEX)];
  if (urls.length === 0) return { passed: true };

  const suspicious = [];

  for (const match of urls) {
    try {
      const hostname = new URL(match[0]).hostname.replace(/^www\./, '');
      if (!ALLOWED_DOMAINS.has(hostname)) {
        suspicious.push(hostname);
      }
    } catch {
      suspicious.push(match[0]); // malformed URL is suspicious
    }
  }

  if (suspicious.length > 0) {
    return {
      passed: false,
      reason: 'unapproved_links',
      detail: suspicious.join(', '),
    };
  }

  return { passed: true };
}
