```js
// src/checks/rateLimit.js
import Redis from 'ioredis';
import config from '../config.js';

const redis = new Redis(config.redis);
const { rateLimitMax, rateLimitWindowSec } = config.moderation;

export async function checkRateLimit(userId) {
  const key = `moderation:rate:${userId}`;

  // Sliding window counter using MULTI
  const now = Date.now();
  const windowStart = now - rateLimitWindowSec * 1000;

  const pipe = redis.multi();
  pipe.zremrangebyscore(key, 0, windowStart); // prune old entries
  pipe.zadd(key, now, `${now}-${Math.random()}`); // add current
  pipe.zcard(key); // count in window
  pipe.expire(key, rateLimitWindowSec); // auto-cleanup

  const results = await pipe.exec();
  const count = results[2][1]; // zcard result

  if (count > rateLimitMax) {
    return {
      passed: false,
      reason: 'rate_limited',
      detail: `${count} messages in ${rateLimitWindowSec}s (max ${rateLimitMax})`,
    };
  }

  return { passed: true };
}
