## Moderator (Orchestrates Checks)

```js
// src/moderator.js
import { checkProfanity } from './checks/profanity.js';
import { checkSpam } from './checks/spam.js';
import { checkLinks } from './checks/links.js';
import { checkRateLimit } from './checks/rateLimit.js';

// Each verdict: 'approve' | 'flag' | 'reject'
const SEVERITY = { approve: 0, flag: 1, reject: 2 };

const RULES = [
  {
    name: 'profanity',
    run: ({ text }) => checkProfanity(text),
    onFail: 'reject',
  },
  {
    name: 'spam',
    run: ({ text }) => checkSpam(text),
    onFail: 'flag',
  },
  {
    name: 'links',
    run: ({ text }) => checkLinks(text),
    onFail: 'flag',
  },
  {
    name: 'rate_limit',
    run: ({ userId }) => checkRateLimit(userId),
    onFail: 'reject',
  },
];

export async function moderate(message) {
  const violations = [];
  let verdict = 'approve';

  for (const rule of RULES) {
    const result = await rule.run(message);

    if (!result.passed) {
      violations.push({
        rule: rule.name,
        reason: result.reason,
        detail: result.detail,
      });

      // Escalate verdict if this failure is more severe
      if (SEVERITY[rule.onFail] > SEVERITY[verdict]) {
        verdict = rule.onFail;
      }
    }
  }

  return {
    messageId: message.messageId,
    userId: message.userId,
    roomId: message.roomId,
    verdict,
    violations,
    processedAt: new Date().toISOString(),
  };
}
