## Actions (What Happens After Moderation)

```js
// src/actions.js
import { Queue } from 'bullmq';
import config from './config.js';
import pino from 'pino';

const log = pino({ name: 'moderation-actions' });

// Downstream queues for different systems to consume
const notifyQueue = new Queue('notifications', { connection: config.redis });
const auditQueue = new Queue('audit-log', { connection: config.redis });

export async function executeVerdict(result) {
  switch (result.verdict) {
    case 'approve':
      log.info({ messageId: result.messageId }, 'Message approved');
      break;

    case 'flag':
      log.warn({ messageId: result.messageId, violations: result.violations },
        'Message flagged for review');

      // Notify human moderators
      await notifyQueue.add('flagged-message', {
        type: 'flagged_message',
        messageId: result.messageId,
        roomId: result.roomId,
        violations: result.violations,
      });
      break;

    case 'reject':
      log.warn({ messageId: result.messageId, violations: result.violations },
        'Message rejected');

      // Notify the user their message was blocked
      await notifyQueue.add('message-rejected', {
        type: 'message_rejected',
        userId: result.userId,
        reason: result.violations[0]?.reason || 'policy_violation',
      });
      break;
  }

  // Always write to audit log
  await auditQueue.add('moderation-result', result);
}
