## Worker (The Consumer)

```js
// src/worker.js
import { Worker } from 'bullmq';
import pino from 'pino';
import config from './config.js';
import { moderate } from './moderator.js';
import { executeVerdict } from './actions.js';

const log = pino({ name: 'moderation-worker' });

const worker = new Worker(
  config.queue.name,
  async (job) => {
    const message = job.data;

    log.info({ messageId: message.messageId, attempt: job.attemptsMade + 1 },
      'Processing message');

    // Run all moderation checks
    const result = await moderate(message);

    // Act on the verdict
    await executeVerdict(result);

    return result;
  },
  {
    connection: config.redis,
    concurrency: config.queue.concurrency,

    // Only retry on transient errors, not moderation logic failures
    settings: {
      backoffStrategy: (attemptsMade) => {
        return Math.min(1000 * 2 ** attemptsMade, 30_000); // exp backoff, max 30s
      },
    },
  }
);

// --- Lifecycle events ---

worker.on('completed', (job, result) => {
  log.info({
    messageId: result.messageId,
    verdict: result.verdict,
    durationMs: Date.now() - job.timestamp,
  }, 'Job completed');
});

worker.on('failed', (job, err) => {
  log.error({
    jobId: job?.id,
    err: err.message,
    attempt: job?.attemptsMade,
  }, 'Job failed');
});

worker.on('error', (err) => {
  log.error({ err: err.message }, 'Worker error');
});

// Graceful shutdown
async function shutdown(signal) {
  log.info({ signal }, 'Shutting down worker...');
  await worker.close();
  process.exit(0);
}

process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

log.info({
  queue: config.queue.name,
  concurrency: config.queue.concurrency,
}, 'Moderation worker started');
```

