## Debugged & Fixed Code

```javascript
// ✅ FIXED VERSION - searchIndexAPI.js
const express = require('express');
const app = express();

// FIX 1: Add JSON body parser middleware
app.use(express.json({ limit: '10mb' }));

// ---------- Search Index Data Structure ----------
class SearchIndex {
  constructor() {
    this.invertedIndex = new Map(); // token -> Set of doc IDs
    this.documents = new Map();     // id -> document object
  }

  // FIX 5: Append doc IDs to token entries instead of overwriting
  addDocument(id, doc) {
    // FIX 6: Store a deep copy, not a reference
    this.documents.set(String(id), structuredClone(doc));
    const tokens = SearchIndex.tokenize(`${doc.title} ${doc.body} ${(doc.tags || []).join(' ')}`);

    tokens.forEach(token => {
      if (!this.invertedIndex.has(token)) {
        this.invertedIndex.set(token, new Set());
      }
      this.invertedIndex.get(token).add(String(id));
    });
  }

  // FIX 12: Properly remove document AND its tokens from the index
  removeDocument(id) {
    const docId = String(id);
    const doc = this.documents.get(docId);
    if (!doc) return false;

    const tokens = SearchIndex.tokenize(`${doc.title} ${doc.body} ${(doc.tags || []).join(' ')}`);
    tokens.forEach(token => {
      const docSet = this.invertedIndex.get(token);
      if (docSet) {
        docSet.delete(docId);
        if (docSet.size === 0) {
          this.invertedIndex.delete(token); // Clean up empty sets
        }
      }
    });

    this.documents.delete(docId);
    return true;
  }

  // FIX 10: Return deduplicated, ranked results as documents
  search(query) {
    const tokens = SearchIndex.tokenize(query);
    if (tokens.length === 0) return [];

    const scoreMap = new Map(); // docId -> relevance score

    tokens.forEach(token => {
      const docIds = this.invertedIndex.get(token);
      if (docIds) {
        docIds.forEach(docId => {
          scoreMap.set(docId, (scoreMap.get(docId) || 0) + 1);
        });
      }
    });

    // FIX 11: Return full documents, sorted by relevance
    return Array.from(scoreMap.entries())
      .sort((a, b) => b[1] - a[1])                    // Sort by score desc
      .map(([docId, score]) => ({
        ...this.documents.get(docId),
        _score: score,
      }));
  }

  // FIX 4: Proper tokenization (remove punctuation, normalize)
  static tokenize(text) {
    if (!text || typeof text !== 'string') return [];
    return text
      .toLowerCase()
      .replace(/[^\w\s]/g, '')   // Remove punctuation
      .split(/\s+/)              // Split on any whitespace
      .filter(token => token.length > 1); // Ignore single chars
  }
}

const index = new SearchIndex();

// ---------- Middleware ----------
// Request logging
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ---------- Input Validation Helpers ----------
function validateDocument(body) {
  const errors = [];
  // FIX 3: Strict equality and proper null/undefined checks
  if (body.id === undefined || body.id === null) {
    errors.push('Field "id" is required');
  }
  if (!body.title || typeof body.title !== 'string') {
    errors.push('Field "title" must be a non-empty string');
  }
  if (!body.body || typeof body.body !== 'string') {
    errors.push('Field "body" must be a non-empty string');
  }
  if (body.tags && !Array.isArray(body.tags)) {
    errors.push('Field "tags" must be an array of strings');
  }
  return errors;
}

// ---------- Routes ----------

// POST /index — Add or update a document
app.post('/index', (req, res, next) => {
  try {
    // FIX 2: Validate input before processing
    const errors = validateDocument(req.body);
    if (errors.length > 0) {
      // FIX 7: Return after sending error response
      return res.status(400).json({ error: 'Validation failed', details: errors });
    }

    const { id, title, body, tags } = req.body;

    // Remove old version if updating
    index.removeDocument(id);
    index.addDocument(id, { id, title, body, tags: tags || [] });

    res.status(201).json({
      message: 'Document indexed successfully',
      id: String(id),
      tokenCount: SearchIndex.tokenize(`${title} ${body}`).length,
    });
  } catch (err) {
    next(err); // Forward to error handler
  }
});

// Bulk index
app.post('/index/bulk', (req, res, next) => {
  try {
    const { documents } = req.body;
    if (!Array.isArray(documents)) {
      return res.status(400).json({ error: '"documents" must be an array' });
    }

    const results = { indexed: [], failed: [] };

    documents.forEach(doc => {
      const errors = validateDocument(doc);
      if (errors.length > 0) {
        results.failed.push({ id: doc.id, errors });
      } else {
        index.removeDocument(doc.id);
        index.addDocument(doc.id, doc);
        results.indexed.push(String(doc.id));
      }
    });

    const status = results.failed.length > 0 ? 207 : 201;
    res.status(status).json(results);
  } catch (err) {
    next(err);
  }
});

// FIX 8: Use query parameters for GET /search
app.get('/search', (req, res, next) => {
  try {
    const query = req.query.q;  // ✅ Read from query string: /search?q=...

    // FIX 9: Handle missing or empty query
    if (!query || typeof query !== 'string' || query.trim().length === 0) {
      return res.status(400).json({
        error: 'Query parameter "q" is required. Usage: /search?q=your+search+terms',
      });
    }

    const page = Math.max(1, parseInt(req.query.page, 10) || 1);
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit, 10) || 10));

    const allResults = index.search(query);
    const start = (page - 1) * limit;
    const paginatedResults = allResults.slice(start, start + limit);

    res.json({
      query,
      total: allResults.length,
      page,
      limit,
      results: paginatedResults,
    });
  } catch (err) {
    next(err);
  }
});

// DELETE /index/:id — Remove a document
app.delete('/index/:id', (req, res, next) => {
  try {
    const { id } = req.params;
    const removed = index.removeDocument(id);

    // FIX 13: Always send a response
    if (removed) {
      res.status(200).json({ message: 'Document removed', id });
    } else {
      res.status(404).json({ error: 'Document not found', id });
    }
  } catch (err) {
    next(err);
  }
});

// GET /index/:id — Retrieve a single document
app.get('/index/:id', (req, res) => {
  const doc = index.documents.get(String(req.params.id));
  if (!doc) {
    return res.status(404).json({ error: 'Document not found' });
  }
  res.json(doc);
});

// GET /stats — Index statistics
app.get('/stats', (_req, res) => {
  res.json({
    totalDocuments: index.documents.size,
    totalTokens: index.invertedIndex.size,
  });
});

// ---------- FIX 14: Global Error Handling Middleware ----------
app.use((err, _req, res, _next) => {
  console.error(`[ERROR] ${err.stack || err.message}`);
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined,
  });
});

// 404 handler
app.use((_req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// FIX 15: Use environment variable with fallback
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Search Index API running on http://localhost:${PORT}`);
});

module.exports = { app, SearchIndex }; // Export for testing
```

