mod watcher;
mod processor;
mod report;

use log::{info, error};
use serde::Deserialize;
use std::fs;
use std::path::PathBuf;

#[derive(Debug, Deserialize)]
struct Config {
    watch_dir: PathBuf,
    output_dir: PathBuf,
    #[serde(default = "default_debounce")]
    debounce_secs: u64,
    #[serde(default)]
    file_extensions: Vec<String>,
}

fn default_debounce() -> u64 {
    2
}

impl Config {
    fn load(path: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let content = fs::read_to_string(path)?;
        let config: Config = toml::from_str(&content)?;

        // Ensure directories exist
        fs::create_dir_all(&config.watch_dir)?;
        fs::create_dir_all(&config.output_dir)?;

        Ok(config)
    }
}

fn main() {
    env_logger::Builder::from_env(
        env_logger::Env::default().default_filter_or("info"),
    )
    .format_timestamp_secs()
    .init();

    let config = match Config::load("config.toml") {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to load config: {e}");
            // Fall back to defaults
            Config {
                watch_dir: PathBuf::from("./input"),
                output_dir: PathBuf::from("./output"),
                debounce_secs: 2,
                file_extensions: vec!["csv".into(), "json".into()],
            }
        }
    };

    info!("Starting report watcher");
    info!("  Watching: {:?}", config.watch_dir);
    info!("  Output:   {:?}", config.output_dir);
    info!("  Types:    {:?}", config.file_extensions);

    if let Err(e) = watcher::run(config.watch_dir, config.output_dir, config.debounce_secs, config.file_extensions) {
        error!("Watcher failed: {e}");
        std::process::exit(1);
    }
}
