```rust
use crate::processor;
use log::{info, warn, error};
use notify_debouncer_mini::{new_debouncer, DebouncedEventKind};
use std::path::{Path, PathBuf};
use std::sync::mpsc;
use std::time::Duration;

pub fn run(
    watch_dir: PathBuf,
    output_dir: PathBuf,
    debounce_secs: u64,
    extensions: Vec<String>,
) -> Result<(), Box<dyn std::error::Error>> {
    let (tx, rx) = mpsc::channel();

    let mut debouncer = new_debouncer(
        Duration::from_secs(debounce_secs),
        tx,
    )?;

    debouncer.watcher().watch(
        watch_dir.as_ref(),
        notify::RecursiveMode::NonRecursive,
    )?;

    info!("Watcher active. Press Ctrl+C to stop.");

    // Process files already present on startup
    process_existing_files(&watch_dir, &output_dir, &extensions);

    // Event loop
    loop {
        match rx.recv() {
            Ok(Ok(events)) => {
                for event in events {
                    if event.kind == DebouncedEventKind::Any {
                        handle_file_event(&event.path, &output_dir, &extensions);
                    }
                }
            }
            Ok(Err(errors)) => {
                for e in errors {
                    error!("Watch error: {e:?}");
                }
            }
            Err(e) => {
                error!("Channel error: {e}");
                break;
            }
        }
    }

    Ok(())
}

fn process_existing_files(watch_dir: &Path, output_dir: &Path, extensions: &[String]) {
    let entries = match std::fs::read_dir(watch_dir) {
        Ok(e) => e,
        Err(e) => {
            warn!("Cannot read watch dir: {e}");
            return;
        }
    };

    let mut count = 0;
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_file() && has_valid_extension(&path, extensions) {
            handle_file_event(&path, output_dir, extensions);
            count += 1;
        }
    }

    if count > 0 {
        info!("Processed {count} existing file(s) on startup");
    }
}

fn handle_file_event(path: &Path, output_dir: &Path, extensions: &[String]) {
    if !path.is_file() {
        return;
    }

    if !has_valid_extension(path, extensions) {
        return;
    }

    let file_name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("unknown");

    info!("Processing: {file_name}");

    match processor::process_file(path, output_dir) {
        Ok(report_path) => {
            info!("Report generated: {}", report_path.display());
        }
        Err(e) => {
            error!("Failed to process {file_name}: {e}");
        }
    }
}

fn has_valid_extension(path: &Path, extensions: &[String]) -> bool {
    if extensions.is_empty() {
        return true;
    }

    path.extension()
        .and_then(|ext| ext.to_str())
        .map(|ext| extensions.iter().any(|e| e.eq_ignore_ascii_case(ext)))
        .unwrap_or(false)
}
