## src/processor.rs

```rust
use crate::report::{Report, ReportRow, Stats};
use log::info;
use std::path::{Path, PathBuf};
use thiserror::Error;

#[derive(Error, Debug)]
pub enum ProcessError {
    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    #[error("CSV error: {0}")]
    Csv(#[from] csv::Error),

    #[error("JSON error: {0}")]
    Json(#[from] serde_json::Error),

    #[error("Unsupported file type: {0}")]
    UnsupportedType(String),

    #[error("No data found in file")]
    EmptyFile,
}

/// Process a single input file and write a report to output_dir.
/// Returns the path to the generated report.
pub fn process_file(input: &Path, output_dir: &Path) -> Result<PathBuf, ProcessError> {
    let extension = input
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("")
        .to_lowercase();

    let rows = match extension.as_str() {
        "csv" => parse_csv(input)?,
        "json" => parse_json(input)?,
        other => return Err(ProcessError::UnsupportedType(other.to_string())),
    };

    if rows.is_empty() {
        return Err(ProcessError::EmptyFile);
    }

    info!("  Parsed {} row(s)", rows.len());

    let stats = compute_stats(&rows);
    let source_name = input
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("unknown")
        .to_string();

    let report = Report::new(source_name, rows.len(), stats, rows);
    let report_path = report.write_to(output_dir)?;

    Ok(report_path)
}

/// Parse CSV with columns: label, category, value
fn parse_csv(path: &Path) -> Result<Vec<ReportRow>, ProcessError> {
    let mut reader = csv::ReaderBuilder::new()
        .flexible(true)
        .trim(csv::Trim::All)
        .from_path(path)?;

    let mut rows = Vec::new();

    for result in reader.deserialize() {
        let row: ReportRow = result?;
        rows.push(row);
    }

    Ok(rows)
}

/// Parse JSON as an array of objects
fn parse_json(path: &Path) -> Result<Vec<ReportRow>, ProcessError> {
    let content = std::fs::read_to_string(path)?;
    let rows: Vec<ReportRow> = serde_json::from_str(&content)?;
    Ok(rows)
}

fn compute_stats(rows: &[ReportRow]) -> Stats {
    let values: Vec<f64> = rows.iter().map(|r| r.value).collect();
    let count = values.len();
    let sum: f64 = values.iter().sum();
    let mean = sum / count as f64;
    let min = values.iter().cloned().fold(f64::INFINITY, f64::min);
    let max = values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);

    // Group by category
    let mut categories: std::collections::HashMap<String, Vec<f64>> =
        std::collections::HashMap::new();
    for row in rows {
        categories
            .entry(row.category.clone())
            .or_default()
            .push(row.value);
    }

    let category_summaries: Vec<(String, f64, usize)> = categories
        .into_iter()
        .map(|(cat, vals)| {
            let cat_sum: f64 = vals.iter().sum();
            let cat_count = vals.len();
            (cat, cat_sum, cat_count)
        })
        .collect();

    Stats {
        count,
        sum,
        mean,
        min,
        max,
        category_summaries,
    }
}
```

## src/report.rs

```rust
use chrono::Local;
use serde::{Deserialize, Serialize};
use std::io::Write;
use std::path::{Path, PathBuf};

#[derive(Debug, Serialize, Deserialize)]
pub struct ReportRow {
    pub label: String,
    pub category: String,
    pub value: f64,
}

#[derive(Debug, Serialize)]
pub struct Stats {
    pub count: usize,
    pub sum: f64,
    pub mean: f64,
    pub min: f64,
    pub max: f64,
    pub category_summaries: Vec<(String, f64, usize)>, // (name, sum, count)
}

#[derive(Debug, Serialize)]
pub struct Report {
    pub generated_at: String,
    pub source: String,
    pub total_rows: usize,
    pub stats: Stats,
    pub rows: Vec<ReportRow>,
}

impl Report {
    pub fn new(source: String, total_rows: usize, stats: Stats, rows: Vec<ReportRow>) -> Self {
        Self {
            generated_at: Local::now().format("%Y-%m-%d %H:%M:%S").to_string(),
            source,
            total_rows,
            stats,
            rows,
        }
    }

    /// Write both a human-readable .txt and a machine-readable .json report.
    pub fn write_to(&self, output_dir: &Path) -> Result<PathBuf, std::io::Error> {
        let timestamp = Local::now().format("%Y%m%d_%H%M%S");
        let base_name = format!("report_{}_{}", self.source, timestamp);

        // JSON report
        let json_path = output_dir.join(format!("{base_name}.json"));
        let json = serde_json::to_string_pretty(self)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
        std::fs::write(&json_path, json)?;

        // Text report
        let txt_path = output_dir.join(format!("{base_name}.txt"));
        let mut f = std::fs::File::create(&txt_path)?;

        writeln!(f, "╔══════════════════════════════════════════╗")?;
        writeln!(f, "║            GENERATED REPORT              ║")?;
        writeln!(f, "╚══════════════════════════════════════════╝")?;
        writeln!(f)?;
        writeln!(f, "Source:       {}", self.source)?;
        writeln!(f, "Generated:    {}", self.generated_at)?;
        writeln!(f, "Total Rows:   {}", self.total_rows)?;
        writeln!(f)?;

        writeln!(f, "── Summary ──────────────────────────────")?;
        writeln!(f, "  Count:  {}", self.stats.count)?;
        writeln!(f, "  Sum:    {:.2}", self.stats.sum)?;
        writeln!(f, "  Mean:   {:.2}", self.stats.mean)?;
        writeln!(f, "  Min:    {:.2}", self.stats.min)?;
        writeln!(f, "  Max:    {:.2}", self.stats.max)?;
        writeln!(f)?;

        writeln!(f, "── By Category ──────────────────────────")?;
        let mut sorted = self.stats.category_summaries.clone();
        sorted.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        for (cat, sum, count) in &sorted {
            writeln!(f, "  {cat:<20} sum={sum:>10.2}  count={count}")?;
        }
        writeln!(f)?;

        writeln!(f, "── Detail ───────────────────────────────")?;
        writeln!(f, "  {:<20} {:<15} {:>10}", "Label", "Category", "Value")?;
        writeln!(f, "  {}", "─".repeat(47))?;
        for row in &self.rows {
            writeln!(
                f,
                "  {:<20} {:<15} {:>10.2}",
                truncate(&row.label, 20),
                truncate(&row.category, 15),
                row.value
            )?;
        }
        writeln!(f)?;
        writeln!(f, "── End of Report ────────────────────────")?;

        Ok(txt_path)
    }
}

fn truncate(s: &str, max: usize) -> &str {
    if s.len() > max {
        &s[..max]
    } else {
        s
    }
}
