## Key Design Decisions

| Decision | Rationale |
|---|---|
| **`notify-debouncer-mini`** | Prevents duplicate events from partial writes — editors often write-then-rename |
| **Startup scan** | Processes files already sitting in the input dir when the watcher starts |
| **Dual output (txt + json)** | Text for humans, JSON for downstream pipelines |
| **`thiserror` for processor** | Typed errors without boilerplate, clean `?` propagation |
| **Extension filtering** | Ignores temp files, `.swp`, OS metadata automatically |
| **Non-recursive watch** | Keeps it predictable — add `RecursiveMode::Recursive` if you need subdirs |

```javascript
import Anthropic from "@anthropic-ai/sdk";
import fs from "fs";
import path from "path";

const client = new Anthropic();

// Simple in-memory search index
const searchIndex = {};

// Conversation history for multi-turn
const conversationHistory = [];

async function analyzeFileContent(filePath, content) {
  const response = await client.messages.create({
    model: "claude-sonnet-4-20250514",
    max_tokens: 1024,
    system:
      "You are a search indexing assistant. Given a file path and its content, extract relevant keywords and a brief summary for search indexing. Respond in JSON format with keys: keywords (array of strings), summary (string).",
    messages: [
      {
        role: "user",
        content: `Index this file for search:\nPath: ${filePath}\nContent:\n${content.substring(0, 2000)}`,
      },
    ],
  });

  const text = response.content[0].text;
  try {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[0]);
    }
  } catch {
    return { keywords: [], summary: "Failed to parse" };
  }
  return { keywords: [], summary: text };
}

async function indexFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, "utf-8");
    const analysis = await analyzeFileContent(filePath, content);

    searchIndex[filePath] = {
      keywords: analysis.keywords,
      summary: analysis.summary,
      lastModified: fs.statSync(filePath).mtime.toISOString(),
      size: fs.statSync(filePath).size,
    };

    console.log(`Indexed: ${filePath}`);
    console.log(`  Keywords: ${analysis.keywords.join(", ")}`);
    console.log(`  Summary: ${analysis.summary}`);
    console.log();
  } catch (err) {
    console.error(`Error indexing ${filePath}: ${err.message}`);
  }
}

function removeFromIndex(filePath) {
  if (searchIndex[filePath]) {
    delete searchIndex[filePath];
    console.log(`Removed from index: ${filePath}`);
  }
}

async function searchQuery(query) {
  conversationHistory.push({
    role: "user",
    content: query,
  });

  const response = await client.messages.create({
    model: "claude-sonnet-4-20250514",
    max_tokens: 1024,
    system: `You are a search assistant. Here is the current search index:\n${JSON.stringify(searchIndex, null, 2)}\n\nHelp the user find files based on their queries. Reference actual indexed files and their content.`,
    messages: conversationHistory,
  });

  const assistantMessage = response.content[0].text;
  conversationHistory.push({
    role: "assistant",
    content: assistantMessage,
  });

  return assistantMessage;
}

function watchDirectory(dirPath) {
  console.log(`Watching directory: ${dirPath}\n`);

  // Initial indexing of existing files
  const files = fs.readdirSync(dirPath);
  const indexPromises = [];

  for (const file of files) {
    const fullPath = path.join(dirPath, file);
    const stat = fs.statSync(fullPath);
    if (stat.isFile() && !file.startsWith(".")) {
      indexPromises.push(indexFile(fullPath));
    }
  }

  // Start watching after initial indexing
  Promise.all(indexPromises).then(() => {
    console.log("--- Initial indexing complete ---\n");
    console.log(`Index contains ${Object.keys(searchIndex).length} files\n`);

    const watcher = fs.watch(dirPath, async (eventType, filename) => {
      if (!filename || filename.startsWith(".")) return;

      const fullPath = path.join(dirPath, filename);

      if (eventType === "rename") {
        if (fs.existsSync(fullPath)) {
          console.log(`\nFile added/created: ${filename}`);
          await indexFile(fullPath);
        } else {
          console.log(`\nFile removed: ${filename}`);
          removeFromIndex(fullPath);
        }
      } else if (eventType === "change") {
        console.log(`\nFile changed: ${filename}`);
        await indexFile(fullPath);
      }
    });

    // Interactive search via stdin
    console.log('Type a search query (or "quit" to exit):\n');

    process.stdin.setEncoding("utf-8");
    process.stdin.on("data", async (data) => {
      const input = data.trim();
      if (input === "quit") {
        watcher.close();
        console.log("\nFinal index state:");
        console.log(JSON.stringify(searchIndex, null, 2));
        process.exit(0);
      }

      if (input === "index") {
        console.log("\nCurrent index:");
        console.log(JSON.stringify(searchIndex, null, 2));
        console.log();
        return;
      }

      if (input) {
        const result = await searchQuery(input);
        console.log(`\nSearch result:\n${result}\n`);
      }
    });
  });
}

// Create a demo directory with sample files
