# Basic File Watcher for Task Scheduling (Node.js)

## `file-watcher.js`

```javascript
const fs = require("fs");
const path = require("path");

class FileWatcher {
  constructor(watchDir) {
    this.watchDir = path.resolve(watchDir);
    this.tasks = [];          // registered tasks
    this.knownFiles = new Map(); // track file mod times to detect event type
    this.watcher = null;
    this.debounceTimers = new Map();
    this.debounceMs = 300;
  }

  // --- Task Registration ---

  /**
   * Register a task to run on file events
   * @param {string}   name    - task label
   * @param {string}   pattern - glob-like extension filter (e.g. ".js", ".css", "*")
   * @param {string[]} events  - which events trigger it: "create", "change", "delete"
   * @param {Function} action  - callback(filePath, eventType)
   */
  addTask(name, pattern, events, action) {
    this.tasks.push({ name, pattern, events, action });
    console.log(`[task registered] "${name}" for ${pattern} on [${events}]`);
    return this;
  }

  // --- Matching ---

  matchesPattern(filePath, pattern) {
    if (pattern === "*") return true;
    return filePath.endsWith(pattern);
  }

  // --- Snapshot known files for create/delete detection ---

  snapshotDir() {
    this.knownFiles.clear();
    if (!fs.existsSync(this.watchDir)) return;

    const files = fs.readdirSync(this.watchDir);
    for (const file of files) {
      const full = path.join(this.watchDir, file);
      try {
        const stat = fs.statSync(full);
        if (stat.isFile()) {
          this.knownFiles.set(full, stat.mtimeMs);
        }
      } catch { /* file may have been removed */ }
    }
  }

  // --- Determine event type ---

  detectEvent(filePath) {
    const exists = fs.existsSync(filePath);
    const wasKnown = this.knownFiles.has(filePath);

    if (exists && !wasKnown) return "create";
    if (!exists && wasKnown) return "delete";
    if (exists && wasKnown) return "change";
    return null;
  }

  // --- Core: handle a raw FS event with debounce ---

  handleRawEvent(eventType, filename) {
    if (!filename) return;
    const filePath = path.join(this.watchDir, filename);

    // Debounce rapid duplicate events
    if (this.debounceTimers.has(filePath)) {
      clearTimeout(this.debounceTimers.get(filePath));
    }

    this.debounceTimers.set(
      filePath,
      setTimeout(() => {
        this.debounceTimers.delete(filePath);
        this.processEvent(filePath);
      }, this.debounceMs)
    );
  }

  processEvent(filePath) {
    const event = this.detectEvent(filePath);
    if (!event) return;

    console.log(`\n[${event}] ${filePath}`);

    // Update snapshot
    if (event === "delete") {
      this.knownFiles.delete(filePath);
    } else {
      try {
        const stat = fs.statSync(filePath);
        this.knownFiles.set(filePath, stat.mtimeMs);
      } catch { /* race condition guard */ }
    }

    // Run matching tasks
    for (const task of this.tasks) {
      if (
        task.events.includes(event) &&
        this.matchesPattern(filePath, task.pattern)
      ) {
        console.log(`  → running task "${task.name}"`);
        try {
          task.action(filePath, event);
        } catch (err) {
          console.error(`  ✖ task "${task.name}" failed:`, err.message);
        }
      }
    }
  }

  // --- Start / Stop ---

  start() {
    if (!fs.existsSync(this.watchDir)) {
      fs.mkdirSync(this.watchDir, { recursive: true });
    }

    this.snapshotDir();

    this.watcher = fs.watch(this.watchDir, (eventType, filename) => {
      this.handleRawEvent(eventType, filename);
    });

    console.log(`\n✔ Watching: ${this.watchDir}`);
    console.log("Press Ctrl+C to stop.\n");
    return this;
  }

  stop() {
    if (this.watcher) {
      this.watcher.close();
      this.watcher = null;
      // Clear pending debounce timers
      for (const timer of this.debounceTimers.values()) clearTimeout(timer);
      this.debounceTimers.clear();
      console.log("\n✔ Watcher stopped.");
    }
  }
}

module.exports = FileWatcher;
```

## `example.js` — Usage

```javascript
const FileWatcher = require("./file-watcher");
const { execSync } = require("child_process");

const watcher = new FileWatcher("./watched");

// Task 1: Log every change to any file
watcher.addTask("logger", "*", ["create", "change", "delete"], (file, evt) => {
  const timestamp = new Date().toISOString();
  console.log(`  [log] ${timestamp} | ${evt} | ${file}`);
});

// Task 2: Lint .js files on create or change
watcher.addTask("js-lint", ".js", ["create", "change"], (file) => {
  console.log(`  [lint] checking ${file}...`);
  // Replace with real linter command:
  // execSync(`npx eslint ${file}`);
});

// Task 3: Compile .scss on change
watcher.addTask("sass-compile", ".scss", ["create", "change"], (file) => {
  console.log(`  [sass] compiling ${file}...`);
  // execSync(`sass ${file} ${file.replace('.scss', '.css')}`);
});

// Task 4: Cleanup notification on delete
watcher.addTask("delete-notify", "*", ["delete"], (file) => {
  console.log(`  [notify] file removed: ${file}`);
});

// Start watching
watcher.start();

// Graceful shutdown
process.on("SIGINT", () => {
  watcher.stop();
  process.exit(0);
});
