/**
 * Custom error hierarchy for document parsing operations.
 * Each error type maps to a specific failure mode,
 * enabling targeted retry and recovery strategies.
 */

export class ParserError extends Error {
  /**
   * @param {string} message - Error description
   * @param {string} code - Machine-readable error code
   * @param {Object} [context={}] - Additional error context
   * @param {Error} [cause] - Original error that caused this one
   */
  constructor(message, code, context = {}, cause) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
    this.context = context;
    this.cause = cause;
    this.timestamp = new Date().toISOString();
    Error.captureStackTrace?.(this, this.constructor);
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      context: this.context,
      timestamp: this.timestamp,
      cause: this.cause?.message,
    };
  }
}

/** Thrown when the input document is malformed or invalid */
export class DocumentFormatError extends ParserError {
  constructor(message, context = {}, cause) {
    super(message, "DOCUMENT_FORMAT_ERROR", context, cause);
    this.retryable = false; // Bad input won't fix itself
  }
}

/** Thrown when parsing times out — always retryable */
export class ParseTimeoutError extends ParserError {
  constructor(message, context = {}, cause) {
    super(message, "PARSE_TIMEOUT_ERROR", context, cause);
    this.retryable = true;
  }
}

/** Thrown when a transient I/O or system error occurs */
export class TransientError extends ParserError {
  constructor(message, context = {}, cause) {
    super(message, "TRANSIENT_ERROR", context, cause);
    this.retryable = true;
  }
}

/** Thrown when the document type is not supported */
export class UnsupportedFormatError extends ParserError {
  constructor(format) {
    super(
      `Unsupported document format: "${format}"`,
      "UNSUPPORTED_FORMAT",
      { format }
    );
    this.retryable = false;
  }
}

/** Thrown when all retry attempts have been exhausted */
export class MaxRetriesExceededError extends ParserError {
  /**
   * @param {number} attempts - Total attempts made
   * @param {Error} lastError - The final error before giving up
   */
  constructor(attempts, lastError) {
    super(
      `All ${attempts} parsing attempts failed`,
      "MAX_RETRIES_EXCEEDED",
      { attempts, lastError: lastError?.message },
      lastError
    );
    this.retryable = false;
    this.attempts = attempts;
    this.lastError = lastError;
  }
}
