/**
 * Input validation utilities for the document parser.
 */

import { DocumentFormatError } from "../errors/ParserErrors.js";

/** @param {unknown} input */
export function validateInput(input) {
  if (input === null || input === undefined) {
    throw new DocumentFormatError("Document input cannot be null or undefined", {
      received: String(input),
    });
  }

  if (typeof input === "string" && input.trim().length === 0) {
    throw new DocumentFormatError("Document input cannot be empty", {
      received: "(empty string)",
    });
  }

  if (Buffer.isBuffer(input) && input.length === 0) {
    throw new DocumentFormatError("Document buffer cannot be empty", {
      received: "(empty buffer)",
    });
  }
}

/** @param {Object} options */
export function validateParserOptions(options) {
  if (options.maxRetries !== undefined) {
    if (!Number.isInteger(options.maxRetries) || options.maxRetries < 0) {
      throw new TypeError("maxRetries must be a non-negative integer");
    }
  }

  if (options.timeout !== undefined) {
    if (typeof options.timeout !== "number" || options.timeout <= 0) {
      throw new TypeError("timeout must be a positive number (ms)");
    }
  }

  if (options.baseDelay !== undefined) {
    if (typeof options.baseDelay !== "number" || options.baseDelay < 0) {
      throw new TypeError("baseDelay must be a non-negative number (ms)");
    }
  }
}
