/**
 * Configurable retry handler with exponential backoff,
 * jitter, circuit-breaker awareness, and abort support.
 */

import Logger from "./utils/logger.js";
import { MaxRetriesExceededError } from "./errors/ParserErrors.js";

/** @typedef {'exponential'|'linear'|'fixed'} BackoffStrategy */

/**
 * @typedef {Object} RetryOptions
 * @property {number}          [maxRetries=3]       - Maximum retry attempts
 * @property {number}          [baseDelay=1000]     - Base delay in ms
 * @property {number}          [maxDelay=30000]     - Delay cap in ms
 * @property {BackoffStrategy} [backoffStrategy='exponential']
 * @property {number}          [jitterFactor=0.3]   - 0 = no jitter, 1 = full
 * @property {number}          [backoffMultiplier=2]
 * @property {Function}        [isRetryable]        - Custom predicate
 * @property {Function}        [onRetry]            - Hook called before each retry
 * @property {AbortSignal}     [signal]             - Cancellation signal
 */

/** @type {RetryOptions} */
const DEFAULT_OPTIONS = Object.freeze({
  maxRetries: 3,
  baseDelay: 1000,
  maxDelay: 30_000,
  backoffStrategy: "exponential",
  jitterFactor: 0.3,
  backoffMultiplier: 2,
  isRetryable: (error) => error?.retryable === true,
  onRetry: null,
  signal: null,
});

export default class RetryHandler {
  #options;
  #logger;

  /** @param {Partial<RetryOptions>} options */
  constructor(options = {}) {
    this.#options = { ...DEFAULT_OPTIONS, ...options };
    this.#logger = new Logger({ context: "RetryHandler" });
  }

  /**
   * Execute an async function with automatic retries.
   *
   * @template T
   * @param {() => Promise<T>} fn - The operation to attempt
   * @param {Object} [context={}] - Metadata attached to log entries
   * @returns {Promise<T>}
   */
  async execute(fn, context = {}) {
    let lastError;

    for (let attempt = 1; attempt <= this.#options.maxRetries + 1; attempt++) {
      this.#checkAborted();

      try {
        this.#logger.debug("Attempting operation", { attempt, ...context });

        const result = await fn(attempt);

        if (attempt > 1) {
          this.#logger.info("Operation succeeded after retry", {
            attempt,
            ...context,
          });
        }

        return result;
      } catch (error) {
        lastError = error;

        // If it's the last attempt or the error isn't retryable, stop immediately
        const isLast = attempt > this.#options.maxRetries;
        if (isLast || !this.#options.isRetryable(error)) {
          this.#logger.error("Operation failed (no more retries)", {
            attempt,
            error: error.message,
            retryable: !!error.retryable,
            ...context,
          });
          break;
        }

        const delay = this.#calculateDelay(attempt);

        this.#logger.warn("Operation failed — scheduling retry", {
          attempt,
          nextAttempt: attempt + 1,
          delayMs: Math.round(delay),
          error: error.message,
          ...context,
        });

        if (typeof this.#options.onRetry === "function") {
          await this.#options.onRetry({ attempt, delay, error, context });
        }

        await this.#sleep(delay);
      }
    }

    throw new MaxRetriesExceededError(
      this.#options.maxRetries + 1,
      lastError
    );
  }

  /* ------------------------------------------------------------------ */
  /*  Private helpers                                                    */
  /* ------------------------------------------------------------------ */

  /**
   * Compute the delay for the given attempt number.
   * @param {number} attempt - 1-based attempt count
   * @returns {number} Delay in milliseconds
   */
  #calculateDelay(attempt) {
    const { baseDelay, maxDelay, backoffStrategy, backoffMultiplier } =
      this.#options;

    let delay;
    switch (backoffStrategy) {
      case "exponential":
        delay = baseDelay * backoffMultiplier ** (attempt - 1);
        break;
      case "linear":
        delay = baseDelay * attempt;
        break;
      case "fixed":
        delay = baseDelay;
        break;
      default:
        delay = baseDelay * backoffMultiplier ** (attempt - 1);
    }

    delay = Math.min(delay, maxDelay);

    // Apply jitter: ±jitterFactor * delay
    const jitter =
      delay * this.#options.jitterFactor * (2 * Math.random() - 1);

    return Math.max(0, delay + jitter);
  }

  /**
   * Sleep that respects an abort signal.
   * @param {number} ms
   * @returns {Promise<void>}
   */
  #sleep(ms) {
    return new Promise((resolve, reject) => {
      const signal = this.#options.signal;

      if (signal?.aborted) {
        return reject(new DOMException("Retry aborted", "AbortError"));
      }

      const timer = setTimeout(resolve, ms);

      signal?.addEventListener(
        "abort",
        () => {
          clearTimeout(timer);
          reject(new DOMException("Retry aborted", "AbortError"));
        },
        { once: true }
      );
    });
  }

  #checkAborted() {
    if (this.#options.signal?.aborted) {
      throw new DOMException("Operation aborted", "AbortError");
    }
  }

  /** Expose current config (read-only snapshot). */
  get options() {
    return { ...this.#options };
  }
}
