/**
 * Abstract base class every format-specific parser must extend.
 */

export default class BaseParser {
  /** Human-readable format name (override in subclass). */
  static formatName = "base";

  /**
   * Parse raw input into a structured result.
   *
   * @param {string|Buffer} input
   * @param {Object} [options={}]
   * @returns {Promise<{ data: any, metadata: Object }>}
   */
  async parse(input, options = {}) {
    const start = performance.now();
    const data = await this.doParse(input, options);
    const elapsed = performance.now() - start;

    return {
      data,
      metadata: {
        format: this.constructor.formatName,
        parsedAt: new Date().toISOString(),
        parseTimeMs: Math.round(elapsed * 100) / 100,
        inputSize: Buffer.isBuffer(input) ? input.length : input.length,
      },
    };
  }

  /**
   * Subclass hook — perform the actual parsing.
   *
   * @abstract
   * @param {string|Buffer} input
   * @param {Object} options
   * @returns {Promise<any>}
   */
  async doParse(_input, _options) {
    throw new Error(`${this.constructor.name}.doParse() is not implemented`);
  }

  /**
   * Quick heuristic: can this parser handle the given input?
   *
   * @param {string|Buffer} input
   * @returns {boolean}
   */
  canParse(_input) {
    return false;
  }
}
