import BaseParser from "./BaseParser.js";
import {
  DocumentFormatError,
  TransientError,
} from "../errors/ParserErrors.js";

export default class JSONParser extends BaseParser {
  static formatName = "json";

  /** @type {Set<string>} */
  static #TRANSIENT_MESSAGES = new Set([
    "allocation failed",
    "out of memory",
  ]);

  /** @override */
  async doParse(input, options = {}) {
    const text = Buffer.isBuffer(input) ? input.toString("utf-8") : input;
    const { reviver, maxDepth = 100 } = options;

    try {
      const parsed = JSON.parse(text, reviver);
      this.#validateDepth(parsed, maxDepth);
      return parsed;
    } catch (error) {
      if (this.#isTransient(error)) {
        throw new TransientError(
          "Transient failure during JSON parsing",
          { originalMessage: error.message },
          error
        );
      }

      throw new DocumentFormatError(
        `Invalid JSON: ${error.message}`,
        {
          preview: text.slice(0, 200),
          position: this.#extractPosition(error.message),
        },
        error
      );
    }
  }

  /** @override */
  canParse(input) {
    const text = (Buffer.isBuffer(input) ? input.toString("utf-8") : input)
      .trimStart();
    return text.startsWith("{") || text.startsWith("[");
  }

  /* ---- helpers ---- */

  #validateDepth(obj, maxDepth, currentDepth = 0) {
    if (currentDepth > maxDepth) {
      throw new DocumentFormatError(
        `JSON nesting exceeds maximum depth of ${maxDepth}`,
        { maxDepth }
      );
    }
    if (obj && typeof obj === "object") {
      for (const value of Object.values(obj)) {
        this.#validateDepth(value, maxDepth, currentDepth + 1);
      }
    }
  }

  #isTransient(error) {
    const msg = error.message.toLowerCase();
    for (const t of JSONParser.#TRANSIENT_MESSAGES) {
      if (msg.includes(t)) return true;
    }
    return false;
  }

  #extractPosition(message) {
    const match = message.match(/position\s+(\d+)/i);
    return match ? parseInt(match[1], 10) : null;
  }
}
