// src/configLoader.js

const fs = require("fs");
const path = require("path");

class ConfigLoader {
  /**
   * @param {Object} defaults - Default configuration values
   */
  constructor(defaults = {}) {
    this._defaults = { ...defaults };
    this._config = {};
    this._loaded = false;
  }

  // --- Core Methods ---

  /**
   * Load config from a JSON file
   * @param {string} filePath - Path to JSON config file
   * @returns {ConfigLoader} this (for chaining)
   */
  loadFromFile(filePath) {
    const absolutePath = path.resolve(filePath);

    if (!fs.existsSync(absolutePath)) {
      throw new ConfigError(`Config file not found: ${absolutePath}`);
    }

    const raw = fs.readFileSync(absolutePath, "utf-8");

    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (err) {
      throw new ConfigError(`Invalid JSON in config file: ${err.message}`);
    }

    if (typeof parsed !== "object" || Array.isArray(parsed) || parsed === null) {
      throw new ConfigError("Config file must contain a JSON object");
    }

    this._config = this._deepMerge(this._config, parsed);
    this._loaded = true;
    return this;
  }

  /**
   * Load config from environment variables with a prefix
   * @param {string} prefix - Env variable prefix (e.g., "APP_")
   * @param {Object} mapping - Maps env var suffixes to config keys
   * @returns {ConfigLoader} this (for chaining)
   *
   * @example
   *   loader.loadFromEnv("APP_", {
   *     "PORT": "server.port",
   *     "DB_HOST": "database.host"
   *   });
   *   // APP_PORT=3000 → { server: { port: "3000" } }
   */
  loadFromEnv(prefix = "", mapping = {}) {
    const entries = Object.entries(mapping);

    for (const [envSuffix, configPath] of entries) {
      const envKey = `${prefix}${envSuffix}`;
      const value = process.env[envKey];

      if (value !== undefined) {
        this._setNested(this._config, configPath, this._coerceType(value));
      }
    }

    this._loaded = true;
    return this;
  }

  /**
   * Manually set a config value
   * @param {string} key - Dot-notation key (e.g., "server.port")
   * @param {*} value
   * @returns {ConfigLoader}
   */
  set(key, value) {
    this._setNested(this._config, key, value);
    this._loaded = true;
    return this;
  }

  /**
   * Get the final merged configuration
   * @returns {Object} Merged config (defaults + loaded values)
   */
  getConfig() {
    return this._deepMerge(this._defaults, this._config);
  }

  /**
   * Get a single value by dot-notation key
   * @param {string} key - e.g., "server.port"
   * @param {*} fallback - Returned if key not found
   * @returns {*}
   */
  get(key, fallback = undefined) {
    const config = this.getConfig();
    return this._getNested(config, key, fallback);
  }

  /**
   * Validate that all required keys exist
   * @param {string[]} requiredKeys - Dot-notation keys
   * @throws {ConfigError} if any key is missing
   */
  validate(requiredKeys = []) {
    const config = this.getConfig();
    const missing = [];

    for (const key of requiredKeys) {
      const value = this._getNested(config, key);
      if (value === undefined) {
        missing.push(key);
      }
    }

    if (missing.length > 0) {
      throw new ConfigError(
        `Missing required config keys: ${missing.join(", ")}`
      );
    }
  }

  get isLoaded() {
    return this._loaded;
  }

  // --- Private Helpers ---

  /** Deep merge source into target (immutable) */
  _deepMerge(target, source) {
    const result = { ...target };

    for (const [key, value] of Object.entries(source)) {
      if (
        value !== null &&
        typeof value === "object" &&
        !Array.isArray(value) &&
        typeof result[key] === "object" &&
        !Array.isArray(result[key]) &&
        result[key] !== null
      ) {
        result[key] = this._deepMerge(result[key], value);
      } else {
        result[key] = value;
      }
    }

    return result;
  }

  /** Set a value at a dot-notation path */
  _setNested(obj, path, value) {
    const keys = path.split(".");
    let current = obj;

    for (let i = 0; i < keys.length - 1; i++) {
      if (!(keys[i] in current) || typeof current[keys[i]] !== "object") {
        current[keys[i]] = {};
      }
      current = current[keys[i]];
    }

    current[keys[keys.length - 1]] = value;
  }

  /** Get a value at a dot-notation path */
  _getNested(obj, path, fallback = undefined) {
    const keys = path.split(".");
    let current = obj;

    for (const key of keys) {
      if (current === null || current === undefined || !(key in current)) {
        return fallback;
      }
      current = current[key];
    }

    return current;
  }

  /** Coerce string env values to native types */
  _coerceType(value) {
    if (value === "true") return true;
    if (value === "false") return false;
    if (value === "null") return null;
    if (value !== "" && !isNaN(Number(value))) return Number(value);
    return value;
  }
}

class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = "ConfigError";
  }
}

module.exports = { ConfigLoader, ConfigError };
