// tests/configLoader.test.js

const fs = require("fs");
const path = require("path");
const { ConfigLoader, ConfigError } = require("../src/configLoader");

// --- Helpers ---

const FIXTURES = path.join(__dirname, "..", "fixtures");
const fixturePath = (name) => path.join(FIXTURES, name);

const DEFAULTS = {
  server: { host: "0.0.0.0", port: 3000 },
  database: { host: "localhost", port: 5432, name: "test" },
  logging: { level: "warn", pretty: false },
};

// --- Test Suites ---

describe("ConfigLoader", () => {
  // ==========================================
  //  Constructor & Defaults
  // ==========================================
  describe("constructor", () => {
    test("initializes with empty defaults", () => {
      const loader = new ConfigLoader();
      expect(loader.getConfig()).toEqual({});
      expect(loader.isLoaded).toBe(false);
    });

    test("initializes with provided defaults", () => {
      const loader = new ConfigLoader(DEFAULTS);
      const config = loader.getConfig();

      expect(config.server.host).toBe("0.0.0.0");
      expect(config.server.port).toBe(3000);
      expect(config.database.name).toBe("test");
    });

    test("does not mutate the defaults object", () => {
      const original = { key: "value" };
      const loader = new ConfigLoader(original);
      loader.set("key", "changed");

      expect(original.key).toBe("value");
    });
  });

  // ==========================================
  //  loadFromFile
  // ==========================================
  describe("loadFromFile", () => {
    test("loads a valid JSON config file", () => {
      const loader = new ConfigLoader();
      loader.loadFromFile(fixturePath("valid-config.json"));

      expect(loader.get("server.host")).toBe("localhost");
      expect(loader.get("server.port")).toBe(8080);
      expect(loader.get("database.name")).toBe("myapp");
      expect(loader.isLoaded).toBe(true);
    });

    test("file values override defaults", () => {
      const loader = new ConfigLoader(DEFAULTS);
      loader.loadFromFile(fixturePath("valid-config.json"));

      // Overridden
      expect(loader.get("server.host")).toBe("localhost");
      expect(loader.get("server.port")).toBe(8080);
      // Default logging.level was "warn", file has "info"
      expect(loader.get("logging.level")).toBe("info");
    });

    test("merges multiple files in order", () => {
      const loader = new ConfigLoader(DEFAULTS);
      loader.loadFromFile(fixturePath("valid-config.json"));
      loader.loadFromFile(fixturePath("custom-config.json"));

      // custom-config overrides server.port
      expect(loader.get("server.port")).toBe(9090);
      // valid-config's server.host preserved
      expect(loader.get("server.host")).toBe("localhost");
      // new key from custom-config
      expect(loader.get("features.darkMode")).toBe(true);
    });

    test("throws ConfigError for missing file", () => {
      const loader = new ConfigLoader();

      expect(() => {
        loader.loadFromFile("/nonexistent/config.json");
      }).toThrow(ConfigError);

      expect(() => {
        loader.loadFromFile("/nonexistent/config.json");
      }).toThrow(/not found/);
    });

    test("throws ConfigError for invalid JSON", () => {
      const tmpFile = path.join(FIXTURES, "_invalid.json");
      fs.writeFileSync(tmpFile, "{ broken json!!!", "utf-8");

      try {
        const loader = new ConfigLoader();
        expect(() => loader.loadFromFile(tmpFile)).toThrow(ConfigError);
        expect(() => loader.loadFromFile(tmpFile)).toThrow(/Invalid JSON/);
      } finally {
        fs.unlinkSync(tmpFile);
      }
    });

    test("throws ConfigError when file contains an array", () => {
      const tmpFile = path.join(FIXTURES, "_array.json");
      fs.writeFileSync(tmpFile, "[1, 2, 3]", "utf-8");

      try {
        const loader = new ConfigLoader();
        expect(() => loader.loadFromFile(tmpFile)).toThrow(ConfigError);
        expect(() => loader.loadFromFile(tmpFile)).toThrow(/JSON object/);
      } finally {
        fs.unlinkSync(tmpFile);
      }
    });

    test("supports method chaining", () => {
      const loader = new ConfigLoader(DEFAULTS);

      const result = loader
        .loadFromFile(fixturePath("valid-config.json"))
        .loadFromFile(fixturePath("custom-config.json"));

      expect(result).toBeInstanceOf(ConfigLoader);
      expect(result.get("server.port")).toBe(9090);
    });
