# Debugging a Linter Rule for Task Scheduling in JavaScript

Below is a buggy ESLint custom rule that validates task scheduling patterns, followed by the fully debugged version with detailed explanations.

## Buggy Code (Before)

```javascript
// ❌ task-scheduling-linter.js — Contains 8 bugs

module.exports = {
  meta: {
    type: "problem",
    docs: {
      description: "Enforce safe task scheduling patterns",
      category: "Best Practices",
    },
    // BUG 1: Missing `fixable` and `schema` properties
    messages: {
      noUnboundedInterval: "setInterval() must have a cleanup mechanism.",
      missingErrorHandler: "Scheduled task '{{name}}' is missing error handling.",
      exceedsMaxDelay:    "Delay {{delay}}ms exceeds maximum allowed ({{max}}ms).",
      missingTaskName:    "Scheduled tasks must have a descriptive name property.",
      noNestedSchedule:   "Avoid nesting scheduled tasks — flatten instead.",
      missingCancellation:"Scheduled task must store its ID for cancellation.",
    },
  },

  create(context) {
    const MAX_DELAY = context.options[0]?.maxDelay || 86400000; // default 24h
    const schedulerFns = ["setTimeout", "setInterval", "requestAnimationFrame"];
    // BUG 2: Not tracking scope depth correctly
    let nestedScheduleDepth = 0;

    // ---------- helpers ----------

    function isSchedulerCall(node) {
      // BUG 3: Only checks Identifier callee, misses window.setTimeout
      return (
        node.callee.type === "Identifier" &&
        schedulerFns.includes(node.callee.name)
      );
    }

    function getDelayArg(node) {
      const calleeName = node.callee.name;
      if (calleeName === "requestAnimationFrame") return 16;
      // BUG 4: Wrong index — delay is the 2nd arg (index 1), not index 0
      const delayArg = node.arguments[0];
      if (delayArg && delayArg.type === "Literal") {
        return delayArg.value;
      }
      return null;
    }

    function hasErrorHandling(callbackNode) {
      if (!callbackNode) return false;
      // BUG 5: Only checks arrow functions, ignores function expressions
      if (callbackNode.type !== "ArrowFunctionExpression") return false;

      const body =
        callbackNode.body.type === "BlockStatement"
          ? callbackNode.body.body
          : [callbackNode.body];

      // BUG 6: Wrong AST type — should be "TryStatement", not "TryCatchStatement"
      return body.some((stmt) => stmt.type === "TryCatchStatement");
    }

    function isReturnedOrAssigned(node) {
      const parent = node.parent;
      // BUG 7: Missing `AwaitExpression` and incomplete check
      return (
        parent.type === "VariableDeclarator" ||
        parent.type === "AssignmentExpression"
      );
    }

    // ---------- visitor ----------

    return {
      CallExpression(node) {
        if (!isSchedulerCall(node)) return;

        const calleeName = node.callee.name || node.callee.property?.name;

        // Rule 1: Check delay limit
        const delay = getDelayArg(node);
        if (delay !== null && delay > MAX_DELAY) {
          context.report({
            node,
            messageId: "exceedsMaxDelay",
            // BUG 8: Data keys don't match the message template placeholders
            data: { delayValue: delay, maxValue: MAX_DELAY },
          });
        }

        // Rule 2: Require error handling in callback
        const callback = node.arguments[0];
        if (!hasErrorHandling(callback)) {
          context.report({
            node,
            messageId: "missingErrorHandler",
            data: { name: calleeName },
          });
        }

        // Rule 3: No nested scheduling
        if (nestedScheduleDepth > 0) {
          context.report({ node, messageId: "noNestedSchedule" });
        }

        // Rule 4: setInterval must store ID for cancellation
        if (calleeName === "setInterval" && !isReturnedOrAssigned(node)) {
          context.report({ node, messageId: "missingCancellation" });
        }

        nestedScheduleDepth++;
      },

      // Never decrements nestedScheduleDepth → always flags after first hit
      "CallExpression:exit"(node) {
        if (!isSchedulerCall(node)) return;
        // missing: nestedScheduleDepth--;
      },
    };
  },
};
```

