## Debugged Code (After)

```javascript
// ✅ task-scheduling-linter.js — All 8 bugs fixed

module.exports = {
  meta: {
    type: "problem",
    docs: {
      description: "Enforce safe task scheduling patterns",
      category: "Best Practices",
    },
    // FIX 1: Added `fixable` and `schema` for configurable maxDelay
    fixable: null,
    schema: [
      {
        type: "object",
        properties: {
          maxDelay: { type: "integer", minimum: 0 },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      noUnboundedInterval:
        "setInterval() must have a cleanup mechanism.",
      missingErrorHandler:
        "Scheduled task '{{name}}' is missing error handling.",
      exceedsMaxDelay:
        "Delay {{delay}}ms exceeds maximum allowed ({{max}}ms).",
      missingTaskName:
        "Scheduled tasks must have a descriptive name property.",
      noNestedSchedule:
        "Avoid nesting scheduled tasks — flatten instead.",
      missingCancellation:
        "Scheduled task must store its ID for cancellation.",
    },
  },

  create(context) {
    const MAX_DELAY = context.options[0]?.maxDelay ?? 86_400_000; // 24 hours
    const schedulerFns = new Set([
      "setTimeout",
      "setInterval",
      "requestAnimationFrame",
    ]);

    // FIX 2: Properly tracked via increment/decrement (see exit visitor)
    let nestedScheduleDepth = 0;

    // ──────────── Helpers ────────────

    /**
     * FIX 3: Handles both `setTimeout(...)` and `window.setTimeout(...)`
     */
    function isSchedulerCall(node) {
      const { callee } = node;

      // Direct call: setTimeout(fn, 1000)
      if (callee.type === "Identifier" && schedulerFns.has(callee.name)) {
        return true;
      }

      // Member call: window.setTimeout(fn, 1000)  /  globalThis.setTimeout(...)
      if (
        callee.type === "MemberExpression" &&
        !callee.computed &&
        callee.property.type === "Identifier" &&
        schedulerFns.has(callee.property.name)
      ) {
        const obj = callee.object;
        return (
          obj.type === "Identifier" &&
          ["window", "globalThis", "self", "global"].includes(obj.name)
        );
      }

      return false;
    }

    /** Resolves the effective callee name from both call styles. */
    function getCalleeName(node) {
      if (node.callee.type === "Identifier") return node.callee.name;
      if (node.callee.type === "MemberExpression")
        return node.callee.property.name;
      return "unknown";
    }

    /**
     * FIX 4: Delay is the *second* argument (index 1), not the first.
     */
    function getDelayArg(node) {
      const calleeName = getCalleeName(node);
      if (calleeName === "requestAnimationFrame") return 16; // ~60 fps

      const delayArg = node.arguments[1]; // ← index 1, not 0
      if (delayArg && delayArg.type === "Literal" && typeof delayArg.value === "number") {
        return delayArg.value;
      }
      return null;
    }

    /**
     * FIX 5 & 6:
     *   - Accept both ArrowFunctionExpression AND FunctionExpression
     *   - Use the correct AST type "TryStatement" (not "TryCatchStatement")
     */
    function hasErrorHandling(callbackNode) {
      if (!callbackNode) return false;

      const isFn =
        callbackNode.type === "ArrowFunctionExpression" ||
        callbackNode.type === "FunctionExpression";

      if (!isFn) return false;

      const body =
        callbackNode.body.type === "BlockStatement"
          ? callbackNode.body.body
          : [callbackNode.body];

      return body.some((stmt) => stmt.type === "TryStatement"); // ← correct type
    }

    /**
     * FIX 7: Also accounts for ReturnStatement and AwaitExpression wrappers.
     *
     *   const id = setTimeout(...)          → VariableDeclarator
     *   this.id  = setTimeout(...)          → AssignmentExpression
     *   return     setTimeout(...)          → ReturnStatement
     *   const id = await scheduleAsync(...) → AwaitExpression → VariableDeclarator
     */
    function isReturnedOrAssigned(node) {
      let { parent } = node;

      // Unwrap an AwaitExpression wrapper first
      if (parent.type === "AwaitExpression") {
        parent = parent.parent;
      }

      return (
        parent.type === "VariableDeclarator" ||
        parent.type === "AssignmentExpression" ||
        parent.type === "ReturnStatement"
      );
    }

    // ──────────── Visitor ────────────

    return {
      CallExpression(node) {
        if (!isSchedulerCall(node)) return;

        const calleeName = getCalleeName(node);

        // ── Rule 1: Delay must not exceed configured maximum ──
        const delay = getDelayArg(node);
        if (delay !== null && delay > MAX_DELAY) {
          context.report({
            node,
            messageId: "exceedsMaxDelay",
            // FIX 8: Keys now match the message template placeholders
            data: { delay, max: MAX_DELAY },
          });
        }

        // ── Rule 2: Callback must contain a try/catch ──
        const callback = node.arguments[0];
        if (!hasErrorHandling(callback)) {
          context.report({
            node,
            messageId: "missingErrorHandler",
            data: { name: calleeName },
          });
        }

        // ── Rule 3: No nested scheduling calls ──
        if (nestedScheduleDepth > 0) {
          context.report({ node, messageId: "noNestedSchedule" });
        }

        // ── Rule 4: setInterval must be assigned for cancellation ──
        if (calleeName === "setInterval" && !isReturnedOrAssigned(node)) {
          context.report({ node, messageId: "missingCancellation" });
        }

        nestedScheduleDepth++;
      },

      // FIX 2 (continued): Decrement so nesting is tracked per-scope
      "CallExpression:exit"(node) {
        if (!isSchedulerCall(node)) return;
        nestedScheduleDepth--;
      },
    };
  },
};
