## Core: FileWatcher

```javascript
// src/FileWatcher.js
const fs = require("fs");
const path = require("path");
const { EventEmitter } = require("events");
const { Debouncer } = require("./Debouncer");
const { Logger } = require("./Logger");

class FileWatcher extends EventEmitter {
  #watchers = new Map();
  #debouncer;
  #logger;
  #running = false;

  constructor(options = {}) {
    super();
    this.debounceMs = options.debounceMs ?? 300;
    this.ignorePatterns = options.ignore ?? [/node_modules/, /\.git/, /\.DS_Store/];
    this.#debouncer = new Debouncer(this.debounceMs);
    this.#logger = new Logger(options.verbose ?? false);
  }

  // Watch a path with associated tasks
  watch(targetPath, tasks = []) {
    const resolved = path.resolve(targetPath);

    if (!fs.existsSync(resolved)) {
      throw new Error(`Path does not exist: ${resolved}`);
    }

    const stat = fs.statSync(resolved);

    if (stat.isDirectory()) {
      this.#watchDirectory(resolved, tasks);
    } else {
      this.#watchFile(resolved, tasks);
    }

    return this;
  }

  #watchDirectory(dirPath, tasks) {
    // Watch the directory itself
    this.#addWatcher(dirPath, tasks);

    // Recursively watch subdirectories
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dirPath, entry.name);

      if (this.#isIgnored(fullPath)) continue;

      if (entry.isDirectory()) {
        this.#watchDirectory(fullPath, tasks);
      }
    }
  }

  #watchFile(filePath, tasks) {
    this.#addWatcher(filePath, tasks);
  }

  #addWatcher(targetPath, tasks) {
    if (this.#watchers.has(targetPath)) return;

    try {
      const watcher = fs.watch(targetPath, (eventType, filename) => {
        if (!filename || this.#isIgnored(filename)) return;

        const fullPath = path.join(targetPath, filename);

        this.#debouncer.debounce(fullPath, () => {
          const changeEvent = {
            type: eventType,        // 'rename' or 'change'
            file: fullPath,
            filename,
            directory: targetPath,
            timestamp: Date.now(),
          };

          this.#logger.log(`${eventType}: ${fullPath}`);
          this.emit("change", changeEvent, tasks);

          // Handle new directories (auto-watch)
          if (eventType === "rename" && fs.existsSync(fullPath)) {
            const stat = fs.statSync(fullPath);
            if (stat.isDirectory() && !this.#watchers.has(fullPath)) {
              this.#watchDirectory(fullPath, tasks);
              this.#logger.log(`Now watching new directory: ${fullPath}`);
            }
          }
        });
      });

      watcher.on("error", (err) => {
        this.#logger.error(`Watcher error on ${targetPath}: ${err.message}`);
        this.emit("error", err, targetPath);
      });

      this.#watchers.set(targetPath, { watcher, tasks });
      this.#logger.log(`Watching: ${targetPath}`);
    } catch (err) {
      this.#logger.error(`Failed to watch ${targetPath}: ${err.message}`);
    }
  }

  #isIgnored(filePath) {
    return this.ignorePatterns.some((pattern) => {
      if (pattern instanceof RegExp) return pattern.test(filePath);
      if (typeof pattern === "string") return filePath.includes(pattern);
      return false;
    });
  }

  // Stop watching everything
  close() {
    for (const [targetPath, { watcher }] of this.#watchers) {
      watcher.close();
      this.#logger.log(`Stopped watching: ${targetPath}`);
    }
    this.#watchers.clear();
    this.#debouncer.clear();
    this.emit("close");
  }

  // List all watched paths
  get watchedPaths() {
    return [...this.#watchers.keys()];
  }

  get watcherCount() {
    return this.#watchers.size;
  }
}

module.exports = { FileWatcher };
```

## Debouncer

```javascript
// src/Debouncer.js

class Debouncer {
  #timers = new Map();
  #defaultDelay;

  constructor(defaultDelay = 300) {
    this.#defaultDelay = defaultDelay;
  }

  debounce(key, callback, delay = this.#defaultDelay) {
    if (this.#timers.has(key)) {
      clearTimeout(this.#timers.get(key));
    }

    const timer = setTimeout(() => {
      this.#timers.delete(key);
      callback();
    }, delay);

    this.#timers.set(key, timer);
  }

  cancel(key) {
    if (this.#timers.has(key)) {
      clearTimeout(this.#timers.get(key));
      this.#timers.delete(key);
    }
  }

  clear() {
    for (const timer of this.#timers.values()) {
      clearTimeout(timer);
    }
    this.#timers.clear();
  }

  get pendingCount() {
    return this.#timers.size;
  }
}

module.exports = { Debouncer };
