## Task Runner

```javascript
// src/TaskRunner.js
const { exec, spawn } = require("child_process");
const path = require("path");
const { Logger } = require("./Logger");

class TaskRunner {
  #queue = [];
  #running = false;
  #logger;
  #taskHistory = [];
  #concurrent;

  constructor(options = {}) {
    this.#logger = new Logger(options.verbose ?? false);
    this.#concurrent = options.concurrent ?? false;
  }

  // Define a task
  static task(name, config) {
    return {
      name,
      match: config.match ?? /.*/,           // file pattern to match
      command: config.command ?? null,         // shell command string
      fn: config.fn ?? null,                  // or a JS function
      cwd: config.cwd ?? process.cwd(),
      env: config.env ?? {},
      timeout: config.timeout ?? 30_000,
      onSuccess: config.onSuccess ?? null,
      onError: config.onError ?? null,
    };
  }

  // Run tasks that match a file change event
  async run(changeEvent, tasks) {
    const matchingTasks = tasks.filter((task) => {
      if (task.match instanceof RegExp) return task.match.test(changeEvent.file);
      if (typeof task.match === "function") return task.match(changeEvent);
      if (typeof task.match === "string") return changeEvent.file.endsWith(task.match);
      return true;
    });

    if (matchingTasks.length === 0) {
      this.#logger.log(`No tasks matched for: ${changeEvent.file}`);
      return [];
    }

    this.#logger.log(
      `${matchingTasks.length} task(s) matched for: ${changeEvent.filename}`
    );

    if (this.#concurrent) {
      return Promise.all(
        matchingTasks.map((task) => this.#executeTask(task, changeEvent))
      );
    }

    // Sequential by default — safer for dependent tasks
    const results = [];
    for (const task of matchingTasks) {
      results.push(await this.#executeTask(task, changeEvent));
    }
    return results;
  }

  async #executeTask(task, changeEvent) {
    const start = Date.now();

    this.#logger.log(`▶ Running: ${task.name}`);

    const result = {
      task: task.name,
      file: changeEvent.file,
      startedAt: new Date().toISOString(),
      duration: 0,
      success: false,
      output: "",
      error: null,
    };

    try {
      if (task.fn) {
        // Run JS function
        const output = await this.#runFunction(task, changeEvent);
        result.output = output ?? "";
        result.success = true;
      } else if (task.command) {
        // Run shell command with variable interpolation
        const command = this.#interpolate(task.command, changeEvent);
        result.output = await this.#runCommand(command, task);
        result.success = true;
      } else {
        throw new Error(`Task "${task.name}" has no command or function`);
      }

      result.duration = Date.now() - start;
      this.#logger.log(`✓ ${task.name} (${result.duration}ms)`);

      if (task.onSuccess) task.onSuccess(result, changeEvent);
    } catch (err) {
      result.duration = Date.now() - start;
      result.error = err.message;

      this.#logger.error(`✗ ${task.name} failed: ${err.message}`);

      if (task.onError) task.onError(err, changeEvent);
    }

    this.#taskHistory.push(result);

    // Keep history bounded
    if (this.#taskHistory.length > 200) {
      this.#taskHistory = this.#taskHistory.slice(-100);
    }

    return result;
  }

  #runFunction(task, changeEvent) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(
        () => reject(new Error(`Timeout after ${task.timeout}ms`)),
        task.timeout
      );

      Promise.resolve(task.fn(changeEvent))
        .then((result) => {
          clearTimeout(timer);
          resolve(result);
        })
        .catch((err) => {
          clearTimeout(timer);
          reject(err);
        });
    });
  }

  #runCommand(command, task) {
    return new Promise((resolve, reject) => {
      const child = exec(
        command,
        {
          cwd: task.cwd,
          timeout: task.timeout,
          env: { ...process.env, ...task.env },
          maxBuffer: 5 * 1024 * 1024, // 5MB
        },
        (err, stdout, stderr) => {
          if (err) {
            reject(new Error(stderr || err.message));
            return;
          }
          const output = stdout.trim();
          if (output) this.#logger.log(output);
          resolve(output);
        }
      );
    });
  }

  // Replace placeholders like $FILE, $DIR, $EXT in commands
  #interpolate(command, changeEvent) {
    return command
      .replace(/\$FILE/g, changeEvent.file)
      .replace(/\$FILENAME/g, changeEvent.filename)
      .replace(/\$DIR/g, changeEvent.directory)
      .replace(/\$EXT/g, path.extname(changeEvent.file))
      .replace(/\$BASENAME/g, path.basename(changeEvent.file, path.extname(changeEvent.file)));
  }

  get history() {
    return [...this.#taskHistory];
  }

  get lastResult() {
    return this.#taskHistory[this.#taskHistory.length - 1] ?? null;
  }
}

module.exports = { TaskRunner };
```

