## Main Entry Point

```javascript
// index.js
const { FileWatcher } = require("./src/FileWatcher");
const { TaskRunner } = require("./src/TaskRunner");
const config = require("./watcher.config");

function start() {
  const watcher = new FileWatcher({
    debounceMs: config.debounceMs,
    verbose: config.verbose,
    ignore: config.ignore,
  });

  const runner = new TaskRunner({ verbose: config.verbose });

  // Set up each watch group
  for (const group of config.groups) {
    for (const watchPath of group.paths) {
      try {
        watcher.watch(watchPath, group.tasks);
      } catch (err) {
        console.error(`Skipping "${group.name}" — ${err.message}`);
      }
    }
  }

  // Wire up: file change → task runner
  watcher.on("change", async (event, tasks) => {
    try {
      await runner.run(event, tasks);
    } catch (err) {
      console.error(`Task execution failed: ${err.message}`);
    }
  });

  watcher.on("error", (err, targetPath) => {
    console.error(`Watch error on ${targetPath}: ${err.message}`);
  });

  // Graceful shutdown
  const shutdown = () => {
    console.log("\nShutting down...");
    watcher.close();

    const history = runner.history;
    const succeeded = history.filter((r) => r.success).length;
    const failed = history.filter((r) => !r.success).length;

    console.log(`Tasks run: ${history.length} (${succeeded} ok, ${failed} failed)`);
    process.exit(0);
  };

  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);

  console.log(`Watching ${watcher.watcherCount} paths. Press Ctrl+C to stop.\n`);
}

start();
