```typescript
import * as fs from "fs";
import * as path from "path";
import { ModConfig, BlockedTerm, Severity } from "./types";

const CONFIG_PATH = path.join(process.cwd(), "modconfig.json");

const DEFAULT_CONFIG: ModConfig = {
  blocklist: [],
  mutedUsers: [],
  bannedUsers: [],
  logFile: "modlog.txt",
};

// Seed terms so the tool works out of the box
const SEED_TERMS: BlockedTerm[] = [
  { term: "spam", severity: Severity.Low, addedAt: new Date().toISOString() },
  { term: "scam", severity: Severity.Medium, addedAt: new Date().toISOString() },
  { term: "hack", severity: Severity.High, addedAt: new Date().toISOString() },
];

export class Store {
  private config: ModConfig;

  constructor() {
    this.config = this.load();
  }

  /** Load config from disk or create default */
  private load(): ModConfig {
    try {
      if (fs.existsSync(CONFIG_PATH)) {
        const raw = fs.readFileSync(CONFIG_PATH, "utf-8");
        return JSON.parse(raw) as ModConfig;
      }
    } catch {
      console.error("⚠  Corrupt config — resetting to defaults.");
    }

    const fresh: ModConfig = {
      ...DEFAULT_CONFIG,
      blocklist: [...SEED_TERMS],
    };
    this.save(fresh);
    return fresh;
  }

  /** Persist config to disk */
  private save(config?: ModConfig): void {
    const data = config ?? this.config;
    fs.writeFileSync(CONFIG_PATH, JSON.stringify(data, null, 2), "utf-8");
  }

  // ---- Blocklist ----

  getBlocklist(): BlockedTerm[] {
    return [...this.config.blocklist];
  }

  addTerm(term: string, severity: Severity): boolean {
    const normalized = term.toLowerCase().trim();
    if (this.config.blocklist.some((b) => b.term === normalized)) return false;

    this.config.blocklist.push({
      term: normalized,
      severity,
      addedAt: new Date().toISOString(),
    });
    this.save();
    return true;
  }

  removeTerm(term: string): boolean {
    const normalized = term.toLowerCase().trim();
    const before = this.config.blocklist.length;
    this.config.blocklist = this.config.blocklist.filter(
      (b) => b.term !== normalized
    );
    if (this.config.blocklist.length === before) return false;
    this.save();
    return true;
  }

  // ---- Users ----

  getMutedUsers(): string[] {
    return [...this.config.mutedUsers];
  }

  getBannedUsers(): string[] {
    return [...this.config.bannedUsers];
  }

  muteUser(user: string): boolean {
    const u = user.toLowerCase().trim();
    if (this.config.mutedUsers.includes(u)) return false;
    this.config.mutedUsers.push(u);
    this.save();
    return true;
  }

  unmuteUser(user: string): boolean {
    const u = user.toLowerCase().trim();
    const idx = this.config.mutedUsers.indexOf(u);
    if (idx === -1) return false;
    this.config.mutedUsers.splice(idx, 1);
    this.save();
    return true;
  }

  banUser(user: string): boolean {
    const u = user.toLowerCase().trim();
    if (this.config.bannedUsers.includes(u)) return false;
    this.config.bannedUsers.push(u);
    // also remove from muted — ban supersedes mute
    this.unmuteUser(u);
    this.save();
    return true;
  }

  unbanUser(user: string): boolean {
    const u = user.toLowerCase().trim();
    const idx = this.config.bannedUsers.indexOf(u);
    if (idx === -1) return false;
    this.config.bannedUsers.splice(idx, 1);
    this.save();
    return true;
  }

  isUserBanned(user: string): boolean {
    return this.config.bannedUsers.includes(user.toLowerCase().trim());
  }

  isUserMuted(user: string): boolean {
    return this.config.mutedUsers.includes(user.toLowerCase().trim());
  }

  // ---- Logging ----

  appendLog(entry: string): void {
    const line = `[${new Date().toISOString()}] ${entry}\n`;
    fs.appendFileSync(
      path.join(process.cwd(), this.config.logFile),
      line,
      "utf-8"
    );
  }
}
