## `src/moderator.ts`

```typescript
import { Store } from "./store";
import {
  Action,
  ModerationResult,
  Severity,
  Violation,
} from "./types";

export class Moderator {
  private store: Store;

  constructor(store: Store) {
    this.store = store;
  }

  /** Check a message for violations and return a full result */
  check(message: string): ModerationResult {
    const violations = this.findViolations(message);
    const action = this.decideAction(violations);
    const censored = this.censor(message, violations);

    return {
      original: message,
      clean: violations.length === 0,
      action,
      violations,
      censored,
    };
  }

  /** Scan the message against every blocked term */
  private findViolations(message: string): Violation[] {
    const lower = message.toLowerCase();
    const violations: Violation[] = [];

    for (const entry of this.store.getBlocklist()) {
      let start = 0;
      // find every occurrence
      while (true) {
        const idx = lower.indexOf(entry.term, start);
        if (idx === -1) break;
        violations.push({
          term: entry.term,
          severity: entry.severity,
          position: idx,
        });
        start = idx + entry.term.length;
      }
    }

    return violations;
  }

  /** Map the worst severity found to a recommended action */
  private decideAction(violations: Violation[]): Action {
    if (violations.length === 0) return Action.Allow;

    const dominated = this.worstSeverity(violations);

    switch (dominated) {
      case Severity.High:
        return Action.Ban;
      case Severity.Medium:
        return Action.Mute;
      case Severity.Low:
        return Action.Warn;
      default:
        return Action.Allow;
    }
  }

  private worstSeverity(violations: Violation[]): Severity {
    const rank: Record<Severity, number> = {
      [Severity.Low]: 1,
      [Severity.Medium]: 2,
      [Severity.High]: 3,
    };
    let worst = Severity.Low;
    for (const v of violations) {
      if (rank[v.severity] > rank[worst]) worst = v.severity;
    }
    return worst;
  }

  /** Replace matched terms with asterisks */
  private censor(message: string, violations: Violation[]): string {
    const chars = [...message];

    for (const v of violations) {
      for (let i = v.position; i < v.position + v.term.length; i++) {
        chars[i] = "*";
      }
    }

    return chars.join("");
  }

  /** Full moderation pass: check user status + message content */
  moderate(user: string, message: string): string {
    if (this.store.isUserBanned(user)) {
      this.store.appendLog(`BLOCKED banned user "${user}": ${message}`);
      return `🚫  User "${user}" is banned. Message blocked.`;
    }

    if (this.store.isUserMuted(user)) {
      this.store.appendLog(`BLOCKED muted user "${user}": ${message}`);
      return `🔇  User "${user}" is muted. Message blocked.`;
    }

    const result = this.check(message);
    const lines: string[] = [];

    if (result.clean) {
      lines.push(`✅  Clean — no violations found.`);
    } else {
      lines.push(`⚠   Violations: ${result.violations.length}`);
      for (const v of result.violations) {
        lines.push(`    • "${v.term}" [${v.severity}] at position ${v.position}`);
      }
      lines.push(`    Action : ${result.action}`);
      lines.push(`    Censored: ${result.censored}`);
      this.store.appendLog(
        `${result.action} user="${user}" violations=${result.violations.length} msg="${message}"`
      );
    }

    return lines.join("\n");
  }
}
