## `src/cli.ts`

```typescript
#!/usr/bin/env node

import * as readline from "readline";
import { Store } from "./store";
import { Moderator } from "./moderator";
import { Severity } from "./types";

// ── Colour helpers (works in most terminals) ────────────────────────
const bold = (s: string) => `\x1b[1m${s}\x1b[0m`;
const dim = (s: string) => `\x1b[2m${s}\x1b[0m`;
const cyan = (s: string) => `\x1b[36m${s}\x1b[0m`;
const green = (s: string) => `\x1b[32m${s}\x1b[0m`;
const red = (s: string) => `\x1b[31m${s}\x1b[0m`;
const yellow = (s: string) => `\x1b[33m${s}\x1b[0m`;

// ── Bootstrap ───────────────────────────────────────────────────────
const store = new Store();
const moderator = new Moderator(store);

const HELP = `
${bold("Chat Moderator CLI")}
${dim("────────────────────────────────────────")}

${cyan("Message moderation")}
  check  <message>                 Check a message for violations
  mod    <user> <message>          Full moderation pass (user + message)

${cyan("Blocklist")}
  add    <term> [low|medium|high]  Add a term  ${dim("(default: medium)")}
  remove <term>                    Remove a term
  list                             Show all blocked terms

${cyan("User management")}
  mute   <user>                    Mute a user
  unmute <user>                    Unmute a user
  ban    <user>                    Ban a user
  unban  <user>                    Unban a user
  users                            Show muted & banned users

${cyan("Other")}
  help                             Show this help
  exit                             Quit
`;

// ── Command handlers ────────────────────────────────────────────────

function handleCheck(args: string[]): void {
  if (args.length === 0) {
    console.log(red("Usage: check <message>"));
    return;
  }
  const message = args.join(" ");
  const result = moderator.check(message);

  if (result.clean) {
    console.log(green("✅  Clean — no violations."));
  } else {
    console.log(yellow(`⚠   ${result.violations.length} violation(s) found`));
    for (const v of result.violations) {
      console.log(dim(`    • "${v.term}" [${v.severity}] pos ${v.position}`));
    }
    console.log(`    Action  : ${bold(result.action)}`);
    console.log(`    Censored: ${result.censored}`);
  }
}

function handleMod(args: string[]): void {
  if (args.length < 2) {
    console.log(red("Usage: mod <user> <message>"));
    return;
  }
  const [user, ...rest] = args;
  console.log(moderator.moderate(user, rest.join(" ")));
}

function handleAdd(args: string[]): void {
  if (args.length === 0) {
    console.log(red("Usage: add <term> [low|medium|high]"));
    return;
  }
  const term = args[0];
  const severity = parseSeverity(args[1]) ?? Severity.Medium;
  const ok = store.addTerm(term, severity);
  console.log(
    ok
      ? green(`+ Added "${term}" [${severity}]`)
      : yellow(`"${term}" already in blocklist.`)
  );
}

function handleRemove(args: string[]): void {
  if (args.length === 0) {
    console.log(red("Usage: remove <term>"));
    return;
  }
  const ok = store.removeTerm(args[0]);
  console.log(
    ok ? green(`- Removed "${args[0]}"`) : yellow(`"${args[0]}" not found.`)
  );
}

function handleList(): void {
  const list = store.getBlocklist();
  if (list.length === 0) {
    console.log(dim("Blocklist is empty."));
    return;
  }
  console.log(bold(`Blocked terms (${list.length}):\n`));
  for (const entry of list) {
    const sev =
      entry.severity === Severity.High
        ? red(entry.severity)
        : entry.severity === Severity.Medium
          ? yellow(entry.severity)
          : green(entry.severity);
    console.log(`  ${entry.term.padEnd(20)} ${sev.padEnd(20)}  ${dim(entry.addedAt)}`);
  }
}

function handleUsers(): void {
  const muted = store.getMutedUsers();
  const banned = store.getBannedUsers();

  console.log(bold("Muted users:"));
  console.log(muted.length ? muted.map((u) => `  🔇 ${u}`).join("\n") : dim("  (none)"));

  console.log(bold("\nBanned users:"));
  console.log(banned.length ? banned.map((u) => `  🚫 ${u}`).join("\n") : dim("  (none)"));
}

function handleUserAction(
  action: "mute" | "unmute" | "ban" | "unban",
  args: string[]
): void {
  if (args.length === 0) {
    console.log(red(`Usage: ${action} <user>`));
    return;
  }
  const user = args[0];
  const fnMap = {
    mute: () => store.muteUser(user),
    unmute: () => store.unmuteUser(user),
    ban: () => store.banUser(user),
    unban: () => store.unbanUser(user),
  };
  const ok = fnMap[action]();
  const emoji = { mute: "🔇", unmute: "🔊", ban: "🚫", unban: "✅" }[action];
  console.log(
    ok ? green(`${emoji}  ${action} "${user}" — done.`) : yellow(`No change for "${user}".`)
  );
}

// ── Helpers ─────────────────────────────────────────────────────────

function parseSeverity(input?: string): Severity | null {
  if (!input) return null;
  const map: Record<string, Severity> = {
    low: Severity.Low,
    medium: Severity.Medium,
    high: Severity.High,
    l: Severity.Low,
    m: Severity.Medium,
    h: Severity.High,
  };
  return map[input.toLowerCase()] ?? null;
}

function dispatch(line: string): boolean {
  const parts = line.trim().split(/\s+/);
  const cmd = parts[0]?.toLowerCase();
  const args = parts.slice(1);

  switch (cmd) {
    case "check":
      handleCheck(args);
      break;
    case "mod":
      handleMod(args);
      break;
    case "add":
      handleAdd(args);
      break;
    case "remove":
    case "rm":
      handleRemove(args);
      break;
    case "list":
    case "ls":
      handleList();
      break;
    case "mute":
    case "unmute":
    case "ban":
    case "unban":
      handleUserAction(cmd as "mute" | "unmute" | "ban" | "unban", args);
      break;
    case "users":
      handleUsers();
      break;
    case "help":
    case "?":
      console.log(HELP);
      break;
    case "exit":
    case "quit":
    case "q":
      console.log(dim("Bye 👋"));
      return true; // signal exit
    default:
      if (cmd) console.log(red(`Unknown command: "${cmd}". Type "help".`));
      break;
  }

  return false;
}

// ── One-shot vs interactive mode ────────────────────────────────────

function main(): void {
  // If arguments were passed → one-shot mode
  const cliArgs = process.argv.slice(2);
  if (cliArgs.length > 0) {
    dispatch(cliArgs.join(" "));
    return;
  }

  // Interactive REPL
  console.log(HELP);

  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    prompt: cyan("chatmod> "),
  });

  rl.prompt();

  rl.on("line", (line) => {
    const shouldExit = dispatch(line);
    if (shouldExit) {
      rl.close();
      return;
    }
    rl.prompt();
  });

  rl.on("close", () => process.exit(0));
}

main();
```

