## Debugged Code (Fixed Version)

```javascript
// ✅ FIXED VERSION - task-scheduler.js

const { EventEmitter } = require('events');
const { v4: uuidv4 } = require('uuid');  // or use crypto.randomUUID()

class TaskScheduler extends EventEmitter {
  constructor(options = {}) {
    super();
    this.tasks = new Map();                             // Fix 1: Use Map for O(1) lookup
    this.timers = new Map();                            // Fix: Proper timer tracking
    this.running = false;
    this.maxConcurrent = options.maxConcurrent || 5;    // Fix 11: Concurrency control
    this.activeTasks = 0;
    this.taskQueue = [];                                // Overflow queue
  }

  /**
   * Add a task to the scheduler
   * @param {string} name - Task name
   * @param {Function} callback - Task function (sync or async)
   * @param {number} interval - Interval in ms
   * @param {number} [priority=0] - Higher = more important
   * @param {object} [options] - Additional options
   * @returns {string} Task ID
   */
  addTask(name, callback, interval, priority = 0, options = {}) {
    // Fix 2: Input validation
    if (!name || typeof name !== 'string') {
      throw new TypeError('Task name must be a non-empty string');
    }
    if (typeof callback !== 'function') {
      throw new TypeError('Callback must be a function');
    }
    if (!Number.isFinite(interval) || interval < 100) {
      throw new RangeError('Interval must be a finite number >= 100ms');
    }
    if (!Number.isFinite(priority)) {
      throw new TypeError('Priority must be a finite number');
    }

    // Fix 3: Use UUID for unique IDs that survive deletions
    const id = uuidv4 ? uuidv4() : crypto.randomUUID();

    const task = {
      id,
      name,
      callback,
      interval,
      priority,
      status: 'pending',
      lastRun: null,
      nextRun: Date.now() + interval,
      runCount: 0,
      errorCount: 0,
      maxRetries: options.maxRetries || 3,
      retryDelay: options.retryDelay || 1000,
      immediate: options.immediate || false,
      enabled: true,
      createdAt: Date.now(),
    };

    this.tasks.set(id, task);                           // Fix 1: Map-based storage
    this.emit('taskAdded', { taskId: id, name });

    // If scheduler is already running, start this task immediately
    if (this.running) {
      this._scheduleTask(task);
    }

    return id;
  }

  /**
   * Execute a single task with error handling and concurrency control
   * Fix 4 & 6: Handle async callbacks + error handling
   */
  async executeTask(taskId) {
    const task = this.tasks.get(taskId);                // Fix 5: Map.get() for lookup

    if (!task || !task.enabled) {
      return;
    }

    // Fix 11: Concurrency control
    if (this.activeTasks >= this.maxConcurrent) {
      this.taskQueue.push(taskId);
      this.emit('taskQueued', { taskId, queueLength: this.taskQueue.length });
      return;
    }

    this.activeTasks++;
    task.status = 'running';
    this.emit('taskStarted', { taskId, name: task.name });

    try {
      // Fix 4: Properly await async callbacks
      const result = await Promise.resolve(task.callback());

      task.lastRun = Date.now();
      task.status = 'completed';
      task.runCount++;
      task.nextRun = Date.now() + task.interval;
      task.errorCount = 0;                              // Reset on success

      this.emit('taskCompleted', {
        taskId,
        name: task.name,
        result,
        runCount: task.runCount,
      });
    } catch (error) {
      // Fix 6: Comprehensive error handling
      task.status = 'failed';
      task.errorCount++;

      this.emit('taskFailed', {
        taskId,
        name: task.name,
        error: error.message,
        errorCount: task.errorCount,
      });

      // Retry logic
      if (task.errorCount <= task.maxRetries) {
        this.emit('taskRetrying', {
          taskId,
          attempt: task.errorCount,
          maxRetries: task.maxRetries,
        });

        setTimeout(() => {
          if (task.enabled && this.running) {
            this.executeTask(taskId);
          }
        }, task.retryDelay * task.errorCount);            // Exponential backoff
      } else {
        task.status = 'failed_permanent';
        task.enabled = false;
        this.emit('taskDisabled', {
          taskId,
          name: task.name,
          reason: 'Max retries exceeded',
        });
      }
    } finally {
      this.activeTasks--;
      this._processQueue();                              // Process waiting tasks
    }
  }

  /**
   * Process queued tasks when a slot opens
   */
  _processQueue() {
    while (this.taskQueue.length > 0 && this.activeTasks < this.maxConcurrent) {
      const nextTaskId = this.taskQueue.shift();
      const task = this.tasks.get(nextTaskId);
      if (task && task.enabled) {
        this.executeTask(nextTaskId);
      }
    }
  }

  /**
   * Schedule a single task with self-correcting timer
   * Fix 8: Use setTimeout recursion instead of setInterval to prevent drift
   */
  _scheduleTask(task) {
    if (!task.enabled || !this.running) return;

    // Clear existing timer if any
    if (this.timers.has(task.id)) {
      clearTimeout(this.timers.get(task.id));
    }

    const scheduleNext = () => {
      if (!task.enabled || !this.running) return;

      // Fix 8: Self-correcting timer to prevent drift
      const now = Date.now();
      const drift = now - task.nextRun;
      const nextDelay = Math.max(0, task.interval - drift);

      const timerId = setTimeout(async () => {
        await this.executeTask(task.id);

        // Schedule next execution
        if (task.enabled && this.running) {
          scheduleNext();
        }
      }, nextDelay);

      this.timers.set(task.id, timerId);                // Fix 9: Track timer properly
    };

    // Execute immediately if configured
    if (task.immediate && task.runCount === 0) {
      this.executeTask(task.id).then(() => scheduleNext());
    } else {
      scheduleNext();
    }
  }

  /**
   * Start the scheduler
   * Fix 7: Sort by priority before scheduling
   */
  start() {
    if (this.running) {
      this.emit('warning', 'Scheduler is already running');
      return;
    }

    this.running = true;
    this.emit('schedulerStarted', { taskCount: this.tasks.size });

    // Fix 7: Sort tasks by priority (higher priority first)
    const sortedTasks = [...this.tasks.values()]
      .filter(task => task.enabled)
      .sort((a, b) => b.priority - a.priority);

    sortedTasks.forEach(task => this._scheduleTask(task));
  }

  /**
   * Stop the scheduler - properly clean up all timers
   * Fix 9: Actually clear all timers
   */
  stop() {
    this.running = false;

    // Fix 9: Clear ALL tracked timers
    for (const [taskId, timerId] of this.timers) {
      clearTimeout(timerId);
      const task = this.tasks.get(taskId);
      if (task) {
        task.status = 'stopped';
      }
    }
    this.timers.clear();
    this.taskQueue = [];
    this.activeTasks = 0;

    this.emit('schedulerStopped');
  }

  /**
   * Pause a specific task
   */
  pauseTask(taskId) {
    const task = this.tasks.get(taskId);
    if (!task) throw new Error(`Task ${taskId} not found`);

    task.enabled = false;
    task.status = 'paused';

    if (this.timers.has(taskId)) {
      clearTimeout(this.timers.get(taskId));
      this.timers.delete(taskId);
    }

    this.emit('taskPaused', { taskId, name: task.name });
  }

  /**
   * Resume a specific task
   */
  resumeTask(taskId) {
    const task = this.tasks.get(taskId);
    if (!task) throw new Error(`Task ${taskId} not found`);

    task.enabled = true;
    task.status = 'pending';
    task.errorCount = 0;

    if (this.running) {
      this._scheduleTask(task);
    }

    this.emit('taskResumed', { taskId, name: task.name });
  }

  /**
   * Remove a task safely
   * Fix 10: Map-based deletion doesn't affect other tasks
   */
  removeTask(taskId) {
    const task = this.tasks.get(taskId);
    if (!task) throw new Error(`Task ${taskId} not found`);

    // Clean up timer
    if (this.timers.has(taskId)) {
      clearTimeout(this.timers.get(taskId));
      this.timers.delete(taskId);
    }

    // Remove from queue if present
    this.taskQueue = this.taskQueue.filter(id => id !== taskId);

    // Fix 10: Map.delete doesn't affect other entries
    this.tasks.delete(taskId);
    this.emit('taskRemoved', { taskId, name: task.name });
  }

  /**
   * Get scheduler status
   * Fix 12: Return deep copy to prevent external mutation
   */
  getStatus() {
    const tasks = [];
    for (const [id, task] of this.tasks) {
      tasks.push({
        id: task.id,
        name: task.name,
        status: task.status,
        priority: task.priority,
        interval: task.interval,
        lastRun: task.lastRun,
        nextRun: task.nextRun,
        runCount: task.runCount,
        errorCount: task.errorCount,
        enabled: task.enabled,
      });
    }

    return {
      running: this.running,
      activeTasks: this.activeTasks,
      queueLength: this.taskQueue.length,
      totalTasks: this.tasks.size,
      tasks: tasks.sort((a, b) => b.priority - a.priority),
    };
  }

  /**
   * Graceful shutdown - wait for running tasks to complete
   */
  async gracefulShutdown(timeoutMs = 5000) {
    this.emit('shuttingDown');

    // Stop scheduling new executions
    for (const [taskId, timerId] of this.timers) {
      clearTimeout(timerId);
    }
    this.timers.clear();
    this.running = false;
    this.taskQueue = [];

    // Wait for active tasks to finish
    const startTime = Date.now();
    while (this.activeTasks > 0) {
      if (Date.now() - startTime > timeoutMs) {
        this.emit('shutdownTimeout', { activeTasks: this.activeTasks });
        break;
      }
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    this.emit('shutdown');
  }
}

module.exports = TaskScheduler;
