```rust
use std::collections::BinaryHeap;
use std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering as AtomicOrdering};
use std::sync::{Arc, Condvar, Mutex, RwLock};
use std::time::{Duration, Instant, SystemTime};
use std::thread::{self, JoinHandle};
use std::cmp::Ordering;

// ─── FIX 1 & 3: Proper derives ──────────────────────────────────────────────
#[derive(Debug, Clone, PartialEq, Eq)]
enum TaskPriority {
    Critical = 3,
    High     = 2,
    Normal   = 1,
    Low      = 0,
}

// FIX 2: Correct Ord — higher numeric value = higher priority (max-heap friendly)
impl Ord for TaskPriority {
    fn cmp(&self, other: &Self) -> Ordering {
        let to_val = |p: &TaskPriority| -> u8 {
            match p {
                TaskPriority::Critical => 3,
                TaskPriority::High     => 2,
                TaskPriority::Normal   => 1,
                TaskPriority::Low      => 0,
            }
        };
        to_val(self).cmp(&to_val(other))
    }
}

impl PartialOrd for TaskPriority {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

// ─── Task definition ─────────────────────────────────────────────────────────
#[derive(Debug, Clone, Eq)]
struct IndexTask {
    id: u64,
    collection: String,
    priority: TaskPriority,
    scheduled_at: Instant,
    max_retries: u32,
    retry_count: u32,
    document_ids: Vec<u64>,
}

// FIX 4: Account for both priority AND age to prevent starvation
impl Ord for IndexTask {
    fn cmp(&self, other: &Self) -> Ordering {
        self.priority
            .cmp(&other.priority)
            // If same priority, prefer older tasks (earlier scheduled_at)
            // `other.scheduled_at.cmp(&self.scheduled_at)` because
            // earlier instant = should be "greater" in max-heap ordering
            .then_with(|| other.scheduled_at.cmp(&self.scheduled_at))
    }
}

impl PartialOrd for IndexTask {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl PartialEq for IndexTask {
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

// ─── Stats (read-heavy) ─────────────────────────────────────────────────────
#[derive(Debug)]
struct SchedulerStats {
    tasks_completed: u64,
    tasks_failed: u64,
    tasks_retried: u64,
    total_docs_indexed: u64,
    last_run: Option<SystemTime>,
}

// ─── Scheduler ───────────────────────────────────────────────────────────────
struct IndexScheduler {
    task_queue: Arc<(Mutex<BinaryHeap<IndexTask>>, Condvar)>, // FIX 11: Condvar for signaling
    stats: Arc<RwLock<SchedulerStats>>,        // FIX 5: RwLock for read-heavy stats
    running: Arc<AtomicBool>,                  // FIX 6: AtomicBool
    max_concurrent: usize,
    active_tasks: Arc<AtomicUsize>,            // FIX 7: AtomicUsize
    next_task_id: Arc<AtomicU64>,              // FIX 8: Atomic counter (thread-safe)
    worker_handle: Mutex<Option<JoinHandle<()>>>, // FIX 19: store handle for graceful shutdown
}

impl IndexScheduler {
    fn new(max_concurrent: usize) -> Self {
        IndexScheduler {
            task_queue: Arc::new((Mutex::new(BinaryHeap::new()), Condvar::new())),
            stats: Arc::new(RwLock::new(SchedulerStats {
                tasks_completed: 0,
                tasks_failed: 0,
                tasks_retried: 0,
                total_docs_indexed: 0,
                last_run: None,
            })),
            running: Arc::new(AtomicBool::new(false)),
            max_concurrent,
            active_tasks: Arc::new(AtomicUsize::new(0)),
            next_task_id: Arc::new(AtomicU64::new(0)),
            worker_handle: Mutex::new(None),
        }
    }

    /// Thread-safe task scheduling
    fn schedule_task(&self, collection: String, priority: TaskPriority, doc_ids: Vec<u64>) {
        // FIX 8: Atomic fetch_add for unique IDs
        let id = self.next_task_id.fetch_add(1, AtomicOrdering::Relaxed);

        let task = IndexTask {
            id,
            collection,
            priority,
            scheduled_at: Instant::now(),
            max_retries: 3,
            retry_count: 0,
            document_ids: doc_ids,
        };

        // FIX 9: Handle lock poisoning gracefully
        let (lock, cvar) = &*self.task_queue;
        match lock.lock() {
            Ok(mut queue) => {
                println!("[Scheduler] Queued task #{} ({})", task.id, task.collection);
                queue.push(task);
                cvar.notify_one(); // FIX 11: Wake the worker loop
            }
            Err(poisoned) => {
                eprintln!("[Scheduler] Lock poisoned, recovering...");
                let mut queue = poisoned.into_inner();
                queue.push(task);
                cvar.notify_one();
            }
        }
    }

    fn start(&self) {
        // FIX 6: Atomic compare-and-swap prevents double-start
        if self
            .running
            .compare_exchange(false, true, AtomicOrdering::SeqCst, AtomicOrdering::Relaxed)
            .is_err()
        {
            eprintln!("[Scheduler] Already running");
            return;
        }

        let queue = Arc::clone(&self.task_queue);
        let stats = Arc::clone(&self.stats);
        let running_flag = Arc::clone(&self.running);
        let active = Arc::clone(&self.active_tasks);
        let max = self.max_concurrent;

        // FIX 19: Store handle for join on stop()
        let handle = thread::Builder::new()
            .name("index-scheduler".into())
            .spawn(move || {
                println!("[Scheduler] Worker started");
                Self::worker_loop(queue, stats, running_flag, active, max);
                println!("[Scheduler] Worker stopped");
            })
            .expect("Failed to spawn scheduler thread");

        *self.worker_handle.lock().unwrap() = Some(handle);
    }

    /// FIX 10, 11, 12, 13: Proper lock scoping + condvar wait (no busy loop)
    fn worker_loop(
        queue: Arc<(Mutex<BinaryHeap<IndexTask>>, Condvar)>,
        stats: Arc<RwLock<SchedulerStats>>,
        running: Arc<AtomicBool>,
        active_tasks: Arc<AtomicUsize>,
        max_concurrent: usize,
