        let (lock, cvar) = &*queue;

        while running.load(AtomicOrdering::SeqCst) {
            // Acquire lock, then wait for work or shutdown signal
            let mut q = lock.lock().unwrap();

            // Wait until: queue has items AND we have capacity, OR we're shutting down
            while q.is_empty()
                || active_tasks.load(AtomicOrdering::Relaxed) >= max_concurrent
            {
                if !running.load(AtomicOrdering::SeqCst) {
