                let result = cvar
                    .wait_timeout(q, Duration::from_millis(250))
                    .unwrap();
                q = result.0;
            }

            // Recheck after waking
            if !running.load(AtomicOrdering::SeqCst) {
                return;
            }

            if let Some(task) = q.pop() {
                // FIX 14: Increment *before* spawning
                active_tasks.fetch_add(1, AtomicOrdering::SeqCst);
                drop(q); // FIX 12: Explicitly release lock before spawning

                let stats_clone = Arc::clone(&stats);
                let active_clone = Arc::clone(&active_tasks);
                let queue_clone = Arc::clone(&queue);
                let running_clone = Arc::clone(&running);

                thread::spawn(move || {
                    Self::process_task(
                        task,
                        stats_clone,
                        active_clone,
                        queue_clone,
                        running_clone,
                    );
                });
            }
            // FIX 13: `q` is dropped here naturally at end of scope
        }
    }

    /// FIX 15, 16, 17, 18: Full retry logic and correct active_tasks management
