# JavaScript Task Queue Consumer

A practical, production-style queue consumer with concurrency control, retries, priority scheduling, and dead-letter handling.

## Core Implementation

```javascript
// taskQueue.js
const { EventEmitter } = require("events");

class TaskQueue extends EventEmitter {
  constructor(options = {}) {
    super();
    this.concurrency = options.concurrency ?? 3;
    this.maxRetries = options.maxRetries ?? 3;
    this.retryBaseDelay = options.retryBaseDelay ?? 1000;
    this.pollInterval = options.pollInterval ?? 500;

    // Priority queues: high (0), normal (1), low (2)
    this.queues = [[], [], []];
    this.activeTasks = new Map();    // taskId -> AbortController
    this.deadLetterQueue = [];
    this.handlers = new Map();       // taskType -> handler function
    this.running = false;
    this._pollTimer = null;
  }

  // --- Registration ---

  register(taskType, handler) {
    if (typeof handler !== "function") {
      throw new TypeError(`Handler for "${taskType}" must be a function`);
    }
    this.handlers.set(taskType, handler);
    return this;
  }

  // --- Enqueue ---

  enqueue(taskType, payload = {}, options = {}) {
    const task = {
      id: options.id ?? crypto.randomUUID(),
      type: taskType,
      payload,
      priority: this._normalizePriority(options.priority),
      attempts: 0,
      maxRetries: options.maxRetries ?? this.maxRetries,
      createdAt: Date.now(),
      scheduledFor: options.delay ? Date.now() + options.delay : Date.now(),
    };

    this.queues[task.priority].push(task);
    this.emit("enqueued", task);
    return task.id;
  }

  // --- Lifecycle ---

  start() {
    if (this.running) return;
    this.running = true;
    this.emit("started");
    this._poll();
  }

  async stop(graceful = true) {
    this.running = false;
    clearTimeout(this._pollTimer);

    if (graceful && this.activeTasks.size > 0) {
      this.emit("draining", this.activeTasks.size);
      await this._waitForActive();
    } else {
      // Abort all in-flight tasks
      for (const [taskId, controller] of this.activeTasks) {
        controller.abort();
      }
    }
    this.emit("stopped");
  }

  // --- Core Loop ---

  _poll() {
    if (!this.running) return;

    while (this.activeTasks.size < this.concurrency) {
      const task = this._dequeue();
      if (!task) break;
      this._execute(task);
    }

    this._pollTimer = setTimeout(() => this._poll(), this.pollInterval);
  }

  _dequeue() {
    const now = Date.now();

    // Drain by priority: high → normal → low
    for (const queue of this.queues) {
      const idx = queue.findIndex((t) => t.scheduledFor <= now);
      if (idx !== -1) return queue.splice(idx, 1)[0];
    }
    return null;
  }

  async _execute(task) {
    const handler = this.handlers.get(task.type);
    if (!handler) {
      this.emit("error", new Error(`No handler for task type "${task.type}"`), task);
      this._sendToDeadLetter(task, "no_handler");
      return;
    }

    const controller = new AbortController();
    this.activeTasks.set(task.id, controller);
    task.attempts++;
    task.startedAt = Date.now();

    this.emit("taskStart", task);

    try {
      const result = await handler(task.payload, {
        taskId: task.id,
        attempt: task.attempts,
        signal: controller.signal,
      });

      task.completedAt = Date.now();
      this.emit("taskComplete", task, result);
    } catch (err) {
      if (controller.signal.aborted) {
        this.emit("taskAborted", task);
        return;
      }
      this._handleFailure(task, err);
    } finally {
      this.activeTasks.delete(task.id);
    }
  }

  // --- Retry Logic ---

  _handleFailure(task, error) {
    this.emit("taskFailed", task, error);

    if (task.attempts < task.maxRetries) {
      const delay = this._backoffDelay(task.attempts);
      task.scheduledFor = Date.now() + delay;
      this.queues[task.priority].push(task);
      this.emit("taskRetry", task, delay);
    } else {
      this._sendToDeadLetter(task, error.message);
    }
  }

  _backoffDelay(attempt) {
    // Exponential backoff with jitter
    const base = this.retryBaseDelay * Math.pow(2, attempt - 1);
    const jitter = Math.random() * base * 0.3;
    return Math.floor(base + jitter);
  }

  // --- Dead Letter Queue ---

  _sendToDeadLetter(task, reason) {
    const entry = { ...task, failedAt: Date.now(), reason };
    this.deadLetterQueue.push(entry);
    this.emit("deadLetter", entry);
  }

  getDeadLetters() {
    return [...this.deadLetterQueue];
  }

  retryDeadLetters(filter) {
    const toRetry = filter
      ? this.deadLetterQueue.filter(filter)
      : [...this.deadLetterQueue];

    for (const task of toRetry) {
      const idx = this.deadLetterQueue.indexOf(task);
      this.deadLetterQueue.splice(idx, 1);
      task.attempts = 0;
      this.queues[task.priority].push(task);
    }
    return toRetry.length;
  }

  // --- Helpers ---

  _normalizePriority(input) {
    if (input === "high" || input === 0) return 0;
    if (input === "low" || input === 2) return 2;
    return 1; // default: normal
  }

  async _waitForActive() {
    while (this.activeTasks.size > 0) {
      await new Promise((r) => setTimeout(r, 100));
    }
  }

  stats() {
    return {
      pending: this.queues.reduce((sum, q) => sum + q.length, 0),
      pendingByPriority: {
        high: this.queues[0].length,
        normal: this.queues[1].length,
        low: this.queues[2].length,
      },
      active: this.activeTasks.size,
      deadLetters: this.deadLetterQueue.length,
      running: this.running,
    };
  }
}

module.exports = { TaskQueue };
```

