  console.log(`[${ctx.taskId}] Generating "${payload.name}" report...`);
  await sleep(2000);
  console.log(`[${ctx.taskId}] Report done.`);
  return { file: `/reports/${payload.name}.pdf` };
});

queue.register("data.cleanup", async (payload, ctx) => {
  console.log(`[${ctx.taskId}] Cleaning up records older than ${payload.olderThanDays}d`);
  await sleep(500);
  return { deleted: 42 };
});

// --- Wire up logging ---

queue.on("taskComplete", (task, result) => {
  const duration = task.completedAt - task.startedAt;
  console.log(`✅ ${task.type} [${task.id}] completed in ${duration}ms`, result);
});

queue.on("taskRetry", (task, delay) => {
  console.log(`🔄 ${task.type} [${task.id}] retrying in ${delay}ms (attempt ${task.attempts})`);
});

queue.on("deadLetter", (entry) => {
  console.log(`💀 ${entry.type} [${entry.id}] moved to DLQ: ${entry.reason}`);
});

// --- Enqueue tasks ---

// High-priority email
queue.enqueue("email.send", { to: "user@example.com", subject: "Welcome!" }, { priority: "high" });

// Normal priority, 3 emails
