  queue.enqueue("email.send", { to: `user${i}@test.com`, subject: `Update #${i}` });
}

// Delayed report (starts after 2s)
queue.enqueue("report.generate", { name: "monthly-sales" }, { delay: 2000, priority: "low" });

// Low-priority cleanup
queue.enqueue("data.cleanup", { olderThanDays: 30 }, { priority: "low" });

// --- Start processing ---

queue.start();

// --- Print stats periodically ---

const statsInterval = setInterval(() => {
  console.log("\n📊 Queue Stats:", queue.stats(), "\n");
}, 3000);

// --- Graceful shutdown after 10s ---

setTimeout(async () => {
  clearInterval(statsInterval);
  console.log("\n🛑 Shutting down...");
  await queue.stop(true);

  const dlq = queue.getDeadLetters();
  if (dlq.length > 0) {
    console.log(`\n💀 Dead Letter Queue (${dlq.length} tasks):`);
    dlq.forEach((t) => console.log(`  - ${t.type} [${t.id}]: ${t.reason}`));
  }

  console.log("👋 Bye.");
}, 10000);

// --- Utility ---

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}
