#!/usr/bin/env node

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

// ─── Paths ───────────────────────────────────────────────
const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_DIR = join(__dirname, "data");
const INDEX_FILE = join(DATA_DIR, "index.json");

// ─── Search Index Class ──────────────────────────────────
class SearchIndex {
  constructor() {
    // documents:     { docId: { title, body, added } }
    // invertedIndex: { token: { docId: frequency } }
    this.documents = {};
    this.invertedIndex = {};
    this.load();
  }

  // --- Persistence ---

  load() {
    if (!existsSync(DATA_DIR)) mkdirSync(DATA_DIR, { recursive: true });

    if (existsSync(INDEX_FILE)) {
      const raw = readFileSync(INDEX_FILE, "utf-8");
      const data = JSON.parse(raw);
      this.documents = data.documents ?? {};
      this.invertedIndex = data.invertedIndex ?? {};
    }
  }

  save() {
    const data = JSON.stringify(
      { documents: this.documents, invertedIndex: this.invertedIndex },
      null,
      2
    );
    writeFileSync(INDEX_FILE, data, "utf-8");
  }

  // --- Tokenizer ---

  tokenize(text) {
    return text
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, "")       // strip punctuation
      .split(/\s+/)                        // split on whitespace
      .filter((t) => t.length > 1)         // drop single chars
      .filter((t) => !STOP_WORDS.has(t));  // drop stop words
  }

  // --- CRUD ---

  add(id, title, body) {
    if (this.documents[id]) {
      this.remove(id); // re-index if already exists
    }

    this.documents[id] = { title, body, added: new Date().toISOString() };

    const tokens = this.tokenize(`${title} ${body}`);
    const freq = {};

    for (const token of tokens) {
      freq[token] = (freq[token] || 0) + 1;
    }

    for (const [token, count] of Object.entries(freq)) {
      if (!this.invertedIndex[token]) {
        this.invertedIndex[token] = {};
      }
      this.invertedIndex[token][id] = count;
    }

    this.save();
    return tokens.length;
  }

  remove(id) {
    if (!this.documents[id]) return false;

    // remove from inverted index
    for (const token of Object.keys(this.invertedIndex)) {
      delete this.invertedIndex[token][id];
      if (Object.keys(this.invertedIndex[token]).length === 0) {
        delete this.invertedIndex[token];
      }
    }

    delete this.documents[id];
    this.save();
    return true;
  }

  // --- Search with TF-IDF scoring ---

  search(query, limit = 10) {
    const tokens = this.tokenize(query);
    if (tokens.length === 0) return [];

    const totalDocs = Object.keys(this.documents).length;
    if (totalDocs === 0) return [];

    const scores = {};

    for (const token of tokens) {
      const postings = this.invertedIndex[token];
      if (!postings) continue;

      const docFreq = Object.keys(postings).length;
      const idf = Math.log(totalDocs / docFreq);

      for (const [docId, termFreq] of Object.entries(postings)) {
        const tf = 1 + Math.log(termFreq); // log-scaled TF
        scores[docId] = (scores[docId] || 0) + tf * idf;
      }
    }

    return Object.entries(scores)
      .map(([id, score]) => ({
        id,
        score: Math.round(score * 1000) / 1000,
        title: this.documents[id].title,
        snippet: this.documents[id].body.substring(0, 80),
      }))
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);
  }

  // --- Stats ---

  stats() {
    return {
      documents: Object.keys(this.documents).length,
      terms: Object.keys(this.invertedIndex).length,
    };
  }

  list() {
    return Object.entries(this.documents).map(([id, doc]) => ({
      id,
      title: doc.title,
      added: doc.added,
    }));
  }

  clear() {
    this.documents = {};
    this.invertedIndex = {};
    this.save();
  }
}

