## Core File Watcher

### `src/file-watcher.js`
```javascript
const fs = require("fs");
const path = require("path");
const { EventEmitter } = require("events");

class FileWatcher extends EventEmitter {
  #watchers = new Map();
  #cache = new Map();
  #debounceTimers = new Map();
  #debounceMs;
  #watchDir;

  constructor(watchDir, { debounceMs = 300 } = {}) {
    super();
    this.#watchDir = path.resolve(watchDir);
    this.#debounceMs = debounceMs;
  }

  // Load a JSON file safely with validation
  #readJsonFile(filePath) {
    try {
      const raw = fs.readFileSync(filePath, "utf-8");
      const parsed = JSON.parse(raw);
      return { ok: true, data: parsed, error: null };
    } catch (err) {
      return { ok: false, data: null, error: err.message };
    }
  }

  // Debounce rapid fs.watch events (common on most OSes)
  #debouncedChange(filePath, callback) {
    const existing = this.#debounceTimers.get(filePath);
    if (existing) clearTimeout(existing);

    const timer = setTimeout(() => {
      this.#debounceTimers.delete(filePath);
      callback();
    }, this.#debounceMs);

    this.#debounceTimers.set(filePath, timer);
  }

  // Watch a single JSON config file
  watch(filename) {
    const filePath = path.join(this.#watchDir, filename);
    const key = path.basename(filename, ".json");

    // Verify file exists
    if (!fs.existsSync(filePath)) {
      throw new Error(`Config file not found: ${filePath}`);
    }

    // Initial load
    const initial = this.#readJsonFile(filePath);
    if (!initial.ok) {
      throw new Error(`Failed to parse ${filename}: ${initial.error}`);
    }
    this.#cache.set(key, Object.freeze(initial.data));
    this.emit("loaded", key, initial.data);

    // Set up watcher
    const watcher = fs.watch(filePath, (eventType) => {
      if (eventType !== "change") return;

      this.#debouncedChange(filePath, () => {
        const result = this.#readJsonFile(filePath);

        if (!result.ok) {
          this.emit("error", key, result.error);
          console.error(`[FileWatcher] Bad JSON in ${filename}: ${result.error}`);
          return; // Keep old config on parse failure
        }

        const previous = this.#cache.get(key);
        this.#cache.set(key, Object.freeze(result.data));
        this.emit("changed", key, result.data, previous);
      });
    });

    watcher.on("error", (err) => {
      this.emit("error", key, err.message);
    });

    this.#watchers.set(key, watcher);
    return this;
  }

  // Watch all JSON files in the config directory
  watchAll() {
    const files = fs.readdirSync(this.#watchDir).filter((f) => f.endsWith(".json"));

    if (files.length === 0) {
      console.warn(`[FileWatcher] No JSON files found in ${this.#watchDir}`);
    }

    for (const file of files) {
      this.watch(file);
    }
    return this;
  }

  // Get current config (returns frozen object)
  get(key) {
    return this.#cache.get(key) ?? null;
  }

  // List all loaded config keys
  keys() {
    return [...this.#cache.keys()];
  }

  // Clean shutdown
  close() {
    for (const [key, watcher] of this.#watchers) {
      watcher.close();
    }
    for (const timer of this.#debounceTimers.values()) {
      clearTimeout(timer);
    }
    this.#watchers.clear();
    this.#debounceTimers.clear();
    this.#cache.clear();
    this.removeAllListeners();
  }
}

module.exports = FileWatcher;
```

## Moderator Engine

### `src/moderator.js`
```javascript
const FileWatcher = require("./file-watcher");

// Action types returned by moderation checks
const Action = Object.freeze({
  ALLOW: "allow",
  BLOCK: "block",
  WARN: "warn",
  MUTE: "mute",
});

class ChatModerator {
  #watcher;
  #userTimestamps = new Map(); // userId -> last message timestamp
  #logFn;

  constructor(configDir, { logger = console.log } = {}) {
    this.#logFn = logger;
    this.#watcher = new FileWatcher(configDir);

    // Watch and log all config changes
    this.#watcher
      .watchAll()
      .on("loaded", (key, data) => {
        this.#log(`Config loaded: ${key}`);
      })
      .on("changed", (key, data, previous) => {
        this.#log(`Config reloaded: ${key}`);
      })
      .on("error", (key, error) => {
        this.#log(`Config error in ${key}: ${error}`);
      });
  }

  #log(message) {
    const settings = this.#watcher.get("settings");
    if (settings?.logActions) {
      this.#logFn(`[Moderator] ${new Date().toISOString()} ${message}`);
    }
  }

  // --- Individual checks ---

  checkBannedUser(userId) {
    const config = this.#watcher.get("banned-users");
    if (!config) return null;

    const entry = config.banned.find((u) => u.id === userId);
    if (!entry) return null;

    // Check if ban has expired
    if (entry.expires && new Date(entry.expires) < new Date()) {
      return null;
    }

    return { action: Action.BLOCK, reason: `Banned: ${entry.reason}` };
  }

  checkMuted(userId) {
    const config = this.#watcher.get("banned-users");
    if (!config) return null;

    const entry = config.muted.find((u) => u.id === userId);
    if (!entry) return null;

    if (new Date(entry.until) < new Date()) {
      return null; // Mute expired
    }

    return { action: Action.MUTE, reason: "User is muted" };
  }

  checkBannedWords(text) {
    const config = this.#watcher.get("banned-words");
    if (!config) return null;

    const lower = text.toLowerCase();

    // Exact match check
    for (const word of config.exact) {
      if (lower.includes(word.toLowerCase())) {
        return { action: Action.BLOCK, reason: `Banned word: "${word}"` };
      }
    }

    // Regex pattern check (catches evasion attempts)
    for (const pattern of config.patterns) {
      try {
        if (new RegExp(pattern, "i").test(text)) {
          return { action: Action.BLOCK, reason: `Matched banned pattern` };
        }
      } catch {
        // Skip invalid regex patterns silently
      }
    }

    // Warning words (soft match)
    for (const word of config.warnings) {
      if (lower.includes(word.toLowerCase())) {
        return { action: Action.WARN, reason: `Warning word: "${word}"` };
      }
    }

    return null;
  }

  checkSpam(text, userId) {
    const settings = this.#watcher.get("settings");
    if (!settings) return null;

    // Message length
    if (text.length > settings.maxMessageLength) {
      return {
        action: Action.BLOCK,
        reason: `Message too long (${text.length}/${settings.maxMessageLength})`,
      };
    }

    // Rate limiting
    const now = Date.now();
    const lastTime = this.#userTimestamps.get(userId) ?? 0;
    const interval = settings.slowModeMs || settings.minMessageInterval;

    if (now - lastTime < interval) {
      const waitSec = ((interval - (now - lastTime)) / 1000).toFixed(1);
      return { action: Action.BLOCK, reason: `Rate limited. Wait ${waitSec}s` };
    }

    // Excessive caps
    if (text.length > 10) {
      const caps = text.replace(/[^A-Z]/g, "").length;
      const percentage = (caps / text.replace(/\s/g, "").length) * 100;
      if (percentage > settings.maxCapsPercentage) {
        return { action: Action.WARN, reason: "Excessive caps" };
      }
    }

    // Repeated characters (e.g., "aaaaaa")
    const repeatedMatch = text.match(/(.)\1+/g);
    if (repeatedMatch) {
      const longest = Math.max(...repeatedMatch.map((m) => m.length));
      if (longest > settings.maxRepeatedChars) {
        return { action: Action.WARN, reason: "Character spam detected" };
      }
    }

    // Link check
    if (!settings.allowLinks) {
      const urlRegex = /https?:\/\/[^\s]+/gi;
      const links = text.match(urlRegex) || [];

      for (const link of links) {
        const isWhitelisted = settings.linkWhitelist.some((domain) =>
          link.toLowerCase().includes(domain.toLowerCase())
        );
        if (!isWhitelisted) {
          return { action: Action.BLOCK, reason: "Links not allowed" };
        }
      }
    }

    return null;
  }

  // --- Main entry point ---

  moderate(userId, message) {
    const checks = [
      () => this.checkBannedUser(userId),
      () => this.checkMuted(userId),
      () => this.checkBannedWords(message),
      () => this.checkSpam(message, userId),
    ];

    for (const check of checks) {
      const result = check();
      if (result) {
        this.#log(`${result.action.toUpperCase()} user=${userId} reason="${result.reason}"`);
        return { ...result, allowed: false };
      }
    }

    // Passed all checks — update rate limit timestamp
    this.#userTimestamps.set(userId, Date.now());

    return { action: Action.ALLOW, reason: null, allowed: true };
  }

  // Get live config for admin dashboards
  getConfig(key) {
    return this.#watcher.get(key);
  }

  // Cleanup
  close() {
    this.#watcher.close();
    this.#userTimestamps.clear();
  }
}

module.exports = { ChatModerator, Action };
```

