const path = require("path");
const { ChatModerator } = require("./moderator");

const configDir = path.join(__dirname, "..", "config");
const mod = new ChatModerator(configDir);

// Simulate incoming chat messages
function simulateChat() {
  const testMessages = [
    { user: "user_001", text: "Hello everyone!" },         // Banned user
    { user: "user_100", text: "Check out badword1 lol" },  // Banned word
    { user: "user_200", text: "Normal message here" },     // Clean
    { user: "user_200", text: "Double message" },           // Rate limited
    { user: "user_300", text: "STOP IGNORING ME NOW" },    // Caps
    { user: "user_400", text: "heyyyyyyyyyy" },            // Repeated chars
    { user: "user_500", text: "visit http://evil.com" },   // Blocked link
    { user: "user_600", text: "see https://github.com/x" }, // Whitelisted link
  ];

  console.log("\n--- Chat Moderation Results ---\n");

  for (const { user, text } of testMessages) {
    const result = mod.moderate(user, text);
    const icon = result.allowed ? "✅" : result.action === "warn" ? "⚠️" : "🚫";
    console.log(`${icon} [${user}] "${text}"`);
    if (!result.allowed) {
      console.log(`   → ${result.action}: ${result.reason}\n`);
    } else {
      console.log();
    }
  }

  // Keep process alive to demonstrate hot reload
  console.log("--- Watching config files for changes. Edit them live! ---");
  console.log("--- Press Ctrl+C to exit ---\n");
}

simulateChat();

// Graceful shutdown
process.on("SIGINT", () => {
  mod.close();
  process.exit(0);
});
