## Key Design Decisions

| Decision | Reason |
|---|---|
| **Debounced `fs.watch`** | Native `fs.watch` fires duplicate events on most OSes |
| **Frozen config objects** | Prevents accidental mutation of shared config state |
| **Graceful parse failure** | Bad JSON keeps the previous working config active |
| **Check ordering** | Cheapest checks (banned user lookup) run before expensive ones (regex) |
| **No dependencies** | Uses only Node.js built-ins — drop it into any project |

# Rust Migration Helper with Rate Limiting

This example implements a migration helper that processes batches of records while respecting configurable rate limits, with retry logic and progress tracking.

```rust
use std::fmt;
use std::future::Future;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::Mutex;
use tokio::time::sleep;

// ─── Errors ──────────────────────────────────────────────────────────────────

#[derive(Debug)]
enum MigrationError {
    RateLimited { retry_after: Duration },
    Permanent(String),
    Transient(String),
}

impl fmt::Display for MigrationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::RateLimited { retry_after } =>
                write!(f, "Rate limited, retry after {:?}", retry_after),
            Self::Permanent(msg) => write!(f, "Permanent error: {msg}"),
            Self::Transient(msg) => write!(f, "Transient error: {msg}"),
        }
    }
}

impl std::error::Error for MigrationError {}

// ─── Token-bucket rate limiter ───────────────────────────────────────────────

struct TokenBucket {
    capacity: u32,
    tokens: f64,
    refill_rate: f64, // tokens per second
    last_refill: Instant,
}

impl TokenBucket {
    fn new(capacity: u32, per_second: f64) -> Self {
        Self {
            capacity,
            tokens: capacity as f64,
            refill_rate: per_second,
            last_refill: Instant::now(),
        }
    }

    /// Refill tokens based on elapsed time, capped at capacity.
    fn refill(&mut self) {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill).as_secs_f64();
        self.tokens = (self.tokens + elapsed * self.refill_rate)
            .min(self.capacity as f64);
        self.last_refill = now;
    }

    /// Try to consume `n` tokens. Returns `Ok(())` or the wait duration.
    fn try_acquire(&mut self, n: u32) -> Result<(), Duration> {
        self.refill();
        if self.tokens >= n as f64 {
            self.tokens -= n as f64;
            Ok(())
        } else {
            let deficit = n as f64 - self.tokens;
            let wait = Duration::from_secs_f64(deficit / self.refill_rate);
            Err(wait)
        }
    }
}

// ─── Rate limiter wrapper (async-safe) ───────────────────────────────────────

#[derive(Clone)]
struct RateLimiter {
    bucket: Arc<Mutex<TokenBucket>>,
}

impl RateLimiter {
    fn new(capacity: u32, per_second: f64) -> Self {
        Self {
            bucket: Arc::new(Mutex::new(TokenBucket::new(capacity, per_second))),
        }
    }

    /// Wait until `n` tokens are available, then consume them.
    async fn acquire(&self, n: u32) {
        loop {
            let result = {
                let mut bucket = self.bucket.lock().await;
                bucket.try_acquire(n)
            };
            match result {
                Ok(()) => return,
                Err(wait) => sleep(wait).await,
            }
        }
    }
}

// ─── Progress tracker ────────────────────────────────────────────────────────

struct ProgressTracker {
    total: usize,
    processed: usize,
    succeeded: usize,
    failed: usize,
    skipped: usize,
    started_at: Instant,
}

impl ProgressTracker {
    fn new(total: usize) -> Self {
        Self {
            total,
            processed: 0,
            succeeded: 0,
            failed: 0,
            skipped: 0,
            started_at: Instant::now(),
        }
    }

    fn record_success(&mut self, count: usize) {
        self.processed += count;
        self.succeeded += count;
    }

    fn record_failure(&mut self, count: usize) {
        self.processed += count;
        self.failed += count;
    }

    fn record_skip(&mut self, count: usize) {
        self.processed += count;
        self.skipped += count;
    }

    fn report(&self) {
        let elapsed = self.started_at.elapsed();
        let pct = if self.total > 0 {
            (self.processed as f64 / self.total as f64) * 100.0
        } else {
            100.0
        };
        let rate = if elapsed.as_secs() > 0 {
            self.processed as f64 / elapsed.as_secs_f64()
        } else {
            0.0
        };

        println!(
            "[Progress] {:.1}% | {}/{} processed | ✓{} ✗{} ⊘{} | {:.1} items/s | elapsed {:?}",
            pct, self.processed, self.total,
            self.succeeded, self.failed, self.skipped,
            rate, elapsed,
        );
    }
}

// ─── Retry policy ────────────────────────────────────────────────────────────

#[derive(Clone)]
struct RetryPolicy {
    max_attempts: u32,
    initial_backoff: Duration,
    max_backoff: Duration,
    backoff_multiplier: f64,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            max_attempts: 3,
            initial_backoff: Duration::from_millis(500),
            max_backoff: Duration::from_secs(30),
            backoff_multiplier: 2.0,
        }
    }
}

impl RetryPolicy {
    fn backoff_for(&self, attempt: u32) -> Duration {
        let backoff = self.initial_backoff.as_secs_f64()
            * self.backoff_multiplier.powi(attempt as i32);
        let capped = backoff.min(self.max_backoff.as_secs_f64());
        Duration::from_secs_f64(capped)
    }
}

// ─── Migration helper configuration ─────────────────────────────────────────

struct MigrationConfig {
    batch_size: usize,
    rate_limit_capacity: u32,
    rate_limit_per_second: f64,
    retry_policy: RetryPolicy,
    progress_interval: usize, // report every N batches
}

impl Default for MigrationConfig {
    fn default() -> Self {
        Self {
            batch_size: 50,
            rate_limit_capacity: 100,
            rate_limit_per_second: 50.0,
            retry_policy: RetryPolicy::default(),
            progress_interval: 5,
        }
    }
}

// ─── The migration helper ────────────────────────────────────────────────────

struct MigrationHelper<T> {
    config: MigrationConfig,
    limiter: RateLimiter,
    progress: Mutex<ProgressTracker>,
    _marker: std::marker::PhantomData<T>,
}

impl<T: Send + Sync + Clone + fmt::Debug + 'static> MigrationHelper<T> {
    fn new(config: MigrationConfig, total_items: usize) -> Self {
        let limiter = RateLimiter::new(
            config.rate_limit_capacity,
            config.rate_limit_per_second,
        );
        Self {
            config,
            limiter,
            progress: Mutex::new(ProgressTracker::new(total_items)),
            _marker: std::marker::PhantomData,
        }
    }

    /// Run the full migration.
    ///
    /// * `items`     – every record to migrate
    /// * `migrate_fn`– async closure that processes one batch
    async fn run<F, Fut>(
        &self,
        items: Vec<T>,
        migrate_fn: F,
    ) -> Result<(), MigrationError>
    where
        F: Fn(Vec<T>) -> Fut + Send + Sync,
        Fut: Future<Output = Result<BatchResult, MigrationError>> + Send,
    {
        let batches: Vec<Vec<T>> = items
            .chunks(self.config.batch_size)
            .map(|c| c.to_vec())
            .collect();

        let total_batches = batches.len();
        println!("Starting migration: {} items in {} batches (batch_size={})",
            items.len(), total_batches, self.config.batch_size);

        for (idx, batch) in batches.into_iter().enumerate() {
            let batch_num = idx + 1;
            let batch_len = batch.len();

            // Wait for enough rate-limit tokens for this batch
            self.limiter.acquire(batch_len as u32).await;

            // Execute with retry
            match self.execute_with_retry(&batch, &migrate_fn).await {
                Ok(result) => {
                    let mut prog = self.progress.lock().await;
                    prog.record_success(result.succeeded);
                    prog.record_failure(result.failed);
                    prog.record_skip(result.skipped);
                }
                Err(MigrationError::Permanent(msg)) => {
                    eprintln!("Batch {batch_num}: permanent error – {msg}");
                    let mut prog = self.progress.lock().await;
                    prog.record_failure(batch_len);
                }
                Err(e) => {
                    eprintln!("Batch {batch_num}: giving up – {e}");
                    let mut prog = self.progress.lock().await;
                    prog.record_failure(batch_len);
                }
            }

            // Periodic progress report
            if batch_num % self.config.progress_interval == 0
                || batch_num == total_batches
            {
                self.progress.lock().await.report();
            }
        }

        let prog = self.progress.lock().await;
        println!("\n=== Migration complete ===");
        prog.report();

        if prog.failed > 0 {
            Err(MigrationError::Permanent(
                format!("{} items failed", prog.failed),
            ))
        } else {
            Ok(())
        }
    }

    /// Execute a single batch with retries and back-off.
    async fn execute_with_retry<F, Fut>(
        &self,
        batch: &[T],
        migrate_fn: &F,
    ) -> Result<BatchResult, MigrationError>
    where
        F: Fn(Vec<T>) -> Fut + Send + Sync,
        Fut: Future<Output = Result<BatchResult, MigrationError>> + Send,
    {
        let policy = &self.config.retry_policy;

        for attempt in 0..policy.max_attempts {
            match migrate_fn(batch.to_vec()).await {
                Ok(result) => return Ok(result),

                // Respect the server's Retry-After header
                Err(MigrationError::RateLimited { retry_after }) => {
                    println!(
                        "  ⏳ Rate-limited (attempt {}/{}), waiting {:?}",
                        attempt + 1, policy.max_attempts, retry_after,
                    );
                    sleep(retry_after).await;
                    // Also drain limiter tokens so we slow down globally
                    self.limiter.acquire(batch.len() as u32).await;
                }

                // Transient errors use exponential back-off
                Err(MigrationError::Transient(msg)) => {
                    let backoff = policy.backoff_for(attempt);
                    println!(
                        "  ⚠ Transient error (attempt {}/{}): {msg} – retrying in {:?}",
                        attempt + 1, policy.max_attempts, backoff,
                    );
                    sleep(backoff).await;
                }

                // Permanent errors are not retried
                Err(e @ MigrationError::Permanent(_)) => return Err(e),
            }
        }

        Err(MigrationError::Transient(
            "max retry attempts exceeded".into(),
        ))
    }
}

// ─── Batch result ────────────────────────────────────────────────────────────

struct BatchResult {
    succeeded: usize,
    failed: usize,
    skipped: usize,
}

// ─── Example: simulated record migration ─────────────────────────────────────

#[derive(Debug, Clone)]
struct UserRecord {
    id: u64,
    name: String,
    email: String,
}

/// Simulates calling an external API to migrate one batch of users.
async fn migrate_users_batch(
    batch: Vec<UserRecord>,
) -> Result<BatchResult, MigrationError> {
    // Simulate network latency
    sleep(Duration::from_millis(50)).await;

    // Simulate occasional rate-limit responses (every ~7th call)
    static CALL_COUNT: std::sync::atomic::AtomicU64 =
        std::sync::atomic::AtomicU64::new(0);
    let call = CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);

    if call % 7 == 6 {
        return Err(MigrationError::RateLimited {
            retry_after: Duration::from_millis(200),
        });
    }

    // Simulate an occasional transient error
    if call % 13 == 12 {
        return Err(MigrationError::Transient("connection reset".into()));
    }

    // "Process" the batch
    let mut succeeded = 0usize;
    let skipped;

    for user in &batch {
        // Simulate: skip users whose id is divisible by 50
        if user.id % 50 != 0 {
            succeeded += 1;
        }
    }

    skipped = batch.len() - succeeded;

    Ok(BatchResult {
        succeeded,
        failed: 0,
        skipped,
    })
}

// ─── Main ────────────────────────────────────────────────────────────────────

#[tokio::main]
async fn main() {
    // Generate sample data
    let users: Vec<UserRecord> = (1..=500)
        .map(|i| UserRecord {
            id: i,
            name: format!("User {i}"),
            email: format!("user{i}@example.com"),
        })
        .collect();

    let config = MigrationConfig {
        batch_size: 25,
        rate_limit_capacity: 60,
        rate_limit_per_second: 30.0,
        retry_policy: RetryPolicy {
            max_attempts: 4,
            initial_backoff: Duration::from_millis(200),
            max_backoff: Duration::from_secs(10),
            backoff_multiplier: 2.0,
        },
        progress_interval: 4,
    };

    let helper = MigrationHelper::new(config, users.len());

    match helper.run(users, migrate_users_batch).await {
        Ok(()) => println!("\n✅ Migration finished successfully."),
        Err(e) => eprintln!("\n❌ Migration finished with errors: {e}"),
    }
}
