## Retry Policy

```typescript
// src/RetryPolicy.ts

import { RetryOptions, RetryAttempt, Logger } from './types';
import { ConfigError, ConfigRetryExhaustedError } from './errors/ConfigErrors';

const DEFAULT_RETRY_OPTIONS: RetryOptions = {
  maxRetries: 3,
  baseDelayMs: 1000,
  maxDelayMs: 30_000,
  backoffMultiplier: 2,
  jitter: true,
};

export class RetryPolicy {
  private readonly options: Required<RetryOptions>;
  private readonly logger?: Logger;

  constructor(options: Partial<RetryOptions> = {}, logger?: Logger) {
    this.options = {
      ...DEFAULT_RETRY_OPTIONS,
      ...options,
      retryableErrors: options.retryableErrors ?? [],
      onRetry: options.onRetry ?? (() => {}),
    };
    this.logger = logger;

    this.validateOptions();
  }

  private validateOptions(): void {
    if (this.options.maxRetries < 0) {
      throw new Error('maxRetries must be non-negative');
    }
    if (this.options.baseDelayMs < 0) {
      throw new Error('baseDelayMs must be non-negative');
    }
    if (this.options.maxDelayMs < this.options.baseDelayMs) {
      throw new Error('maxDelayMs must be >= baseDelayMs');
    }
    if (this.options.backoffMultiplier < 1) {
      throw new Error('backoffMultiplier must be >= 1');
    }
  }

  /**
   * Execute a function with retry logic.
   * Returns the result on success or throws ConfigRetryExhaustedError.
   */
  async execute<T>(
    fn: () => Promise<T>,
    operationName: string
  ): Promise<{ result: T; attempts: number; retryHistory: RetryAttempt[] }> {
    const retryHistory: RetryAttempt[] = [];
    let lastError: Error | undefined;

    // attempt 0 = initial try, attempts 1..maxRetries = retries
    const totalAttempts = this.options.maxRetries + 1;

    for (let attempt = 0; attempt < totalAttempts; attempt++) {
      try {
        this.logger?.debug(`Attempt ${attempt + 1}/${totalAttempts} for ${operationName}`);
        const result = await fn();
        return { result, attempts: attempt + 1, retryHistory };
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));

        this.logger?.warn(`Attempt ${attempt + 1}/${totalAttempts} failed for ${operationName}`, {
          error: lastError.message,
          attempt: attempt + 1,
        });

        // Check if this error is retryable
        if (!this.isRetryable(lastError)) {
          this.logger?.error(`Non-retryable error on ${operationName}, aborting`, {
            error: lastError.message,
          });
          throw lastError;
        }

        // If this was the last attempt, don't sleep
        if (attempt < totalAttempts - 1) {
          const delayMs = this.calculateDelay(attempt);

          const retryAttempt: RetryAttempt = {
            attempt: attempt + 1,
            error: lastError,
            delayMs,
            timestamp: new Date(),
          };
          retryHistory.push(retryAttempt);

          this.options.onRetry(lastError, attempt + 1, delayMs);

          this.logger?.info(
            `Retrying ${operationName} in ${delayMs}ms (attempt ${attempt + 2}/${totalAttempts})`,
            { delayMs, nextAttempt: attempt + 2 }
          );

          await this.sleep(delayMs);
        }
      }
    }

    throw new ConfigRetryExhaustedError(totalAttempts, lastError!);
  }

  /**
   * Calculate delay with exponential backoff and optional jitter.
   */
  calculateDelay(attempt: number): number {
    const exponentialDelay =
      this.options.baseDelayMs * Math.pow(this.options.backoffMultiplier, attempt);

    const clampedDelay = Math.min(exponentialDelay, this.options.maxDelayMs);

    if (!this.options.jitter) {
      return Math.round(clampedDelay);
    }

    // Full jitter: random value between 0 and clampedDelay
    const jitteredDelay = Math.random() * clampedDelay;
    return Math.round(Math.max(this.options.baseDelayMs * 0.5, jitteredDelay));
  }

  /**
   * Determine whether an error should trigger a retry.
   */
  private isRetryable(error: Error): boolean {
    // Non-retryable ConfigErrors are never retried
    if (error instanceof ConfigError && !error.retryable) {
      return false;
    }

    // If specific retryable error codes are configured, check them
    if (this.options.retryableErrors.length > 0) {
      if (error instanceof ConfigError) {
        return this.options.retryableErrors.includes(error.code);
      }
      return this.options.retryableErrors.includes(error.name);
    }

    return true;
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}
