// src/sources/FileSource.ts

import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { ConfigSource } from './ConfigSource';
import { ConfigNotFoundError, ConfigParseError } from '../errors/ConfigErrors';

type Parser = (content: string) => unknown;

const BUILTIN_PARSERS: Record<string, Parser> = {
  '.json': JSON.parse,
  '.env': parseEnvFile,
};

function parseEnvFile(content: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;
    const key = trimmed.slice(0, eqIndex).trim();
    let value = trimmed.slice(eqIndex + 1).trim();
    // Strip surrounding quotes
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    result[key] = value;
  }
  return result;
}

export class FileSource<T = Record<string, unknown>> implements ConfigSource<T> {
  readonly name: string;
  private readonly filePath: string;
  private readonly parser: Parser;

  constructor(filePath: string, parser?: Parser) {
    this.filePath = path.resolve(filePath);
    this.name = `file://${this.filePath}`;

    const ext = path.extname(this.filePath).toLowerCase();
    this.parser = parser ?? BUILTIN_PARSERS[ext] ?? JSON.parse;
  }

  async load(): Promise<T> {
    let content: string;
    try {
      content = await fs.readFile(this.filePath, 'utf-8');
    } catch (err) {
      const error = err as NodeJS.ErrnoException;
      if (error.code === 'ENOENT') {
        throw new ConfigNotFoundError(this.name, error);
      }
      // Permission errors, etc. are retryable (transient filesystem issues)
      throw new ConfigNotFoundError(this.name, error);
    }

    try {
      return this.parser(content) as T;
    } catch (err) {
      throw new ConfigParseError(this.name, err instanceof Error ? err : undefined);
    }
  }

  async healthCheck(): Promise<boolean> {
    try {
      await fs.access(this.filePath, fs.constants.R_OK);
      return true;
    } catch {
      return false;
    }
  }
}
