// src/sources/EnvSource.ts

import { ConfigSource } from './ConfigSource';

export interface EnvMapping {
  /** Environment variable name */
  envVar: string;
  /** Key in the resulting config object (supports dot notation) */
  configKey: string;
  /** If true, throw when the env var is missing */
  required?: boolean;
  /** Default value when the env var is missing */
  defaultValue?: string;
  /** Transform the string value */
  transform?: (value: string) => unknown;
}

export class EnvSource<T = Record<string, unknown>> implements ConfigSource<T> {
  readonly name = 'env://process.env';
  private readonly mappings: EnvMapping[];
  private readonly prefix?: string;

  constructor(options: { mappings?: EnvMapping[]; prefix?: string } = {}) {
    this.mappings = options.mappings ?? [];
    this.prefix = options.prefix;
  }

  async load(): Promise<T> {
    const config: Record<string, unknown> = {};

    // Map specific variables
    for (const mapping of this.mappings) {
      const rawValue = process.env[mapping.envVar];

      if (rawValue === undefined) {
        if (mapping.required) {
          throw new Error(`Required environment variable ${mapping.envVar} is not set`);
        }
        if (mapping.defaultValue !== undefined) {
          this.setNested(config, mapping.configKey, mapping.defaultValue);
        }
        continue;
      }

      const value = mapping.transform ? mapping.transform(rawValue) : rawValue;
      this.setNested(config, mapping.configKey, value);
    }

    // Collect all vars with the given prefix
    if (this.prefix) {
      for (const [key, value] of Object.entries(process.env)) {
        if (key.startsWith(this.prefix) && value !== undefined) {
          const configKey = key
            .slice(this.prefix.length)
            .toLowerCase()
            .replace(/__/g, '.')
            .replace(/_/g, '');
          this.setNested(config, configKey, value);
        }
      }
    }

    return config as T;
  }

  private setNested(obj: Record<string, unknown>, path: string, value: unknown): void {
    const keys = path.split('.');
    let current: Record<string, unknown> = obj;

    for (let i = 0; i < keys.length - 1; i++) {
      const key = keys[i];
      if (!(key in current) || typeof current[key] !== 'object') {
        current[key] = {};
      }
      current = current[key] as Record<string, unknown>;
    }

    current[keys[keys.length - 1]] = value;
  }
}
