import { ConfigSource } from './ConfigSource';
import {
  ConfigNotFoundError,
  ConfigParseError,
  ConfigTimeoutError,
  ConfigError,
} from '../errors/ConfigErrors';

export interface HttpSourceOptions {
  url: string;
