  parseResponse?: (body: string) => unknown;
}

export class HttpSource<T = Record<string, unknown>> implements ConfigSource<T> {
  readonly name: string;
  private readonly url: string;
  private readonly headers: Record<string, string>;
  private readonly timeoutMs: number;
  private readonly parseResponse: (body: string) => unknown;

  constructor(options: HttpSourceOptions) {
    this.url = options.url;
    this.name = `http://${new URL(options.url).host}${new URL(options.url).pathname}`;
    this.headers = options.headers ?? {};
    this.timeoutMs = options.timeoutMs ?? 10_000;
    this.parseResponse = options.parseResponse ?? JSON.parse;
  }

  async load(): Promise<T> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.timeoutMs);

    try {
      const response = await fetch(this.url, {
        headers: {
          Accept: 'application/json',
          ...this.headers,
        },
        signal: controller.signal,
      });

      if (!response.ok) {
        if (response.status === 404) {
          throw new ConfigNotFoundError(this.name);
        }
        throw new ConfigError(
          `HTTP ${response.status}: ${response.statusText} from ${this.name}`,
          'CONFIG_HTTP_ERROR',
          response.status >= 500 // 5xx is retryable, 4xx is not
        );

