class SearchIndexScheduler {
  constructor(options) {
    this.batchSize = options.batchSize;
    this.interval = options.interval;
    this.queue = [];
    this.isRunning = false;
    this.timer = null;
    this.retryLimit = options.retryLimit;
    this.indexedCount = 0;
    this.listeners = {};
  }

  // BUG 1: No validation on documents
  addToQueue(documents) {
    this.queue.push(documents);            // BUG 2: pushes entire array as one element
    this.emit('queued', documents.length);
  }

  start() {
    if (this.isRunning) return;
    this.isRunning = true;

    // BUG 3: setInterval with async callback — errors are silently swallowed
    // BUG 4: `this` context lost inside setInterval callback
    this.timer = setInterval(function () {
      this.processBatch();
    }, this.interval);

    this.emit('started');
  }

  stop() {
    this.isRunning = false;
    // BUG 5: timer is never cleared — interval keeps firing
    this.emit('stopped');
  }

  async processBatch() {
    // BUG 6: No guard — can run multiple batches concurrently
    const batch = this.queue.slice(0, this.batchSize);  // BUG 7: slice doesn't remove items

    if (batch.length === 0) return;

    for (let i = 0; i <= batch.length; i++) {           // BUG 8: off-by-one (<=)
      const doc = batch[i];
      await this.indexDocument(doc);
    }

    this.indexedCount += batch.length;
    this.emit('batchComplete', batch.length);
  }

  async indexDocument(doc, retries) {
    // BUG 9: retries parameter is never initialized on first call
    try {
      const result = await this.sendToSearchEngine(doc);
      return result;
    } catch (error) {
      if (retries < this.retryLimit) {                   // BUG 10: undefined < number = false
        // BUG 11: no delay between retries (hammers the API)
        return this.indexDocument(doc, retries++);        // BUG 12: post-increment (passes old value)
      }
      // BUG 13: failed doc is silently lost — never re-queued or logged
    }
  }

  async sendToSearchEngine(doc) {
    // Simulated API call
    return fetch('/api/search/index', {
      method: 'POST',
      body: JSON.stringify(doc)                          // BUG 14: missing Content-Type header
    });
  }

  on(event, callback) {
    this.listeners[event] = callback;                    // BUG 15: overwrites previous listeners
  }

  emit(event, data) {
    // BUG 16: no check if listener exists — throws TypeError
    this.listeners[event](data);
  }

  getStats() {
    return {
      queued: this.queue.length,
      indexed: this.indexedCount,
      isRunning: this.isRunning
      // BUG 17: missing comma won't cause error, but no failed count tracked
