  }

  /**
   * Adds documents to the indexing queue.
   * @param {Array|Object} documents - Single doc or array of docs
   */
  addToQueue(documents) {
    // FIX 1: Validate input
    if (!documents) {
      throw new Error('Documents cannot be null or undefined');
    }

    // FIX 2: Spread array elements individually; handle single docs
    const docs = Array.isArray(documents) ? documents : [documents];

    const validDocs = docs.filter(doc => {
      if (!doc || typeof doc !== 'object' || !doc.id) {
        console.warn('Skipping invalid document:', doc);
        return false;
      }
      return true;
    });

    this.queue.push(...validDocs);           // FIX 2: spread operator
    this.emit('queued', { count: validDocs.length, queueSize: this.queue.length });

    return validDocs.length;
  }

  /**
   * Starts the scheduler loop.
   */
  start() {
    if (this.isRunning) {
      console.warn('Scheduler is already running');
      return;
    }
    this.isRunning = true;

    // FIX 3 & 4: Arrow function preserves `this` + proper async handling
    this.timer = setInterval(async () => {
      try {
        await this.processBatch();
      } catch (error) {
        console.error('Batch processing error:', error);
        this.emit('error', error);
      }
    }, this.interval);

    // Process immediately on start (don't wait for first interval)
    this.processBatch().catch(err => {
      console.error('Initial batch processing error:', err);
    });

    this.emit('started', { interval: this.interval, batchSize: this.batchSize });
  }

  /**
   * Stops the scheduler and clears the timer.
   */
  stop() {
    if (!this.isRunning) return;

    this.isRunning = false;

    // FIX 5: Actually clear the interval timer
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }

    this.emit('stopped', this.getStats());
  }

  /**
   * Processes a single batch of documents from the queue.
   */
  async processBatch() {
    // FIX 6: Guard against concurrent batch processing
    if (this.isProcessing) {
      console.debug('Batch already in progress, skipping...');
      return;
    }

    if (this.queue.length === 0) return;

    this.isProcessing = true;

    try {
      // FIX 7: splice removes items from queue (instead of slice)
      const batch = this.queue.splice(0, this.batchSize);

      if (batch.length === 0) return;

      const results = { succeeded: 0, failed: 0 };

      // FIX 8: Use `<` not `<=` to prevent off-by-one error
      for (let i = 0; i < batch.length; i++) {
        const doc = batch[i];
        try {
          await this.indexDocument(doc, 0);  // FIX 9: explicit initial retry = 0
          results.succeeded++;
        } catch (error) {
          results.failed++;
          this.failedCount++;
          this.failedDocs.push({ doc, error: error.message, timestamp: Date.now() });
          this.emit('documentFailed', { doc, error });  // FIX 13: report failures
        }
      }

      this.indexedCount += results.succeeded;
      this.emit('batchComplete', {
        ...results,
        remaining: this.queue.length,
        totalIndexed: this.indexedCount,
      });
    } finally {
      // Always release the lock, even if an error occurred
      this.isProcessing = false;
    }
  }

  /**
   * Indexes a single document with retry logic.
   * @param {Object} doc       - Document to index
   * @param {number} retries   - Current retry attempt number
   */
  async indexDocument(doc, retries = 0) {      // FIX 9: default param = 0
    try {
      const result = await this.sendToSearchEngine(doc);
      return result;
    } catch (error) {
      // FIX 10: Properly compare retries with limit
      if (retries < this.retryLimit) {
        const delay = this.retryDelay * Math.pow(2, retries); // FIX 11: exponential backoff
        console.warn(
          `Retrying doc ${doc.id} (attempt ${retries + 1}/${this.retryLimit}) ` +
          `in ${delay}ms...`
        );

        await this.sleep(delay);

        // FIX 12: pre-increment (++retries) or just retries + 1
        return this.indexDocument(doc, retries + 1);
      }

      // FIX 13: Throw so the caller knows it failed (not silently lost)
      throw new Error(
        `Failed to index doc ${doc.id} after ${this.retryLimit} retries: ${error.message}`
      );
    }
  }

  /**
   * Sends a document to the search engine API.
   */
  async sendToSearchEngine(doc) {
    const response = await fetch('/api/search/index', {
      method: 'POST',
      // FIX 14: Include proper headers
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
      body: JSON.stringify(doc),
    });

    // Also check response status (fetch doesn't reject on HTTP errors)
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return response.json();
  }

  /**
   * Registers an event listener. Supports multiple listeners per event.
   */
  on(event, callback) {
    // FIX 15: Store listeners in an array — don't overwrite
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
    return this; // allow chaining
  }

  /**
   * Removes an event listener.
   */
  off(event, callback) {
    if (this.listeners[event]) {
      this.listeners[event] = this.listeners[event].filter(cb => cb !== callback);
    }
    return this;
  }

  /**
   * Emits an event to all registered listeners.
   */
  emit(event, data) {
    // FIX 16: Check if listeners exist before calling
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => {
        try {
          callback(data);
        } catch (err) {
          console.error(`Error in "${event}" listener:`, err);
        }
      });
    }
  }

  /**
   * Returns current scheduler statistics.
   */
  getStats() {
    return {
      queued: this.queue.length,
      indexed: this.indexedCount,
      failed: this.failedCount,              // FIX 17: include failure stats
      failedDocs: this.failedDocs.length,
      isRunning: this.isRunning,
      isProcessing: this.isProcessing,
    };
  }

  /**
   * Retries all previously failed documents.
   */
  async retryFailed() {
    const failed = this.failedDocs.splice(0);
    const docs = failed.map(f => f.doc);
    this.addToQueue(docs);
    return docs.length;
  }

  /** Utility: Promise-based sleep */
  sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /** Graceful shutdown — finish current batch then stop */
  async gracefulShutdown() {
    this.stop();
    // Wait for any in-progress batch to complete
    while (this.isProcessing) {
      await this.sleep(100);
    }
    this.emit('shutdown', this.getStats());
  }
}
```

