## lib/moderator.js — Rule Engine

```javascript
export class Moderator {
  constructor(rules) {
    this.rules = rules;
    this.userHistory = new Map(); // userId -> [timestamps]
  }

  /**
   * Run all moderation checks against a parsed chat message.
   * Returns an array of violations (empty = clean message).
   */
  check(message) {
    const violations = [];

    violations.push(...this.#checkBannedWords(message));
    violations.push(...this.#checkCaps(message));
    violations.push(...this.#checkLength(message));
    violations.push(...this.#checkRepeatChars(message));
    violations.push(...this.#checkLinks(message));
    violations.push(...this.#checkSpam(message));

    return violations;
  }

  // --- Private checks ---

  #checkBannedWords(msg) {
    const lower = msg.text.toLowerCase();
    const found = this.rules.bannedWords.filter(word =>
      lower.includes(word.toLowerCase())
    );

    if (found.length === 0) return [];

    return [{
      rule: "bannedWord",
      severity: "high",
      detail: `Banned words detected: [${found.join(", ")}]`,
      matched: found
    }];
  }

  #checkCaps(msg) {
    const text = msg.text.replace(/[^a-zA-Z]/g, "");
    if (text.length < 8) return []; // ignore short messages

    const upper = text.replace(/[^A-Z]/g, "").length;
    const percent = (upper / text.length) * 100;

    if (percent < this.rules.maxCapsPercent) return [];

    return [{
      rule: "caps",
      severity: "low",
      detail: `Excessive caps: ${percent.toFixed(0)}% uppercase`
    }];
  }

  #checkLength(msg) {
    if (msg.text.length <= this.rules.maxMessageLength) return [];

    return [{
      rule: "excessiveLength",
      severity: "medium",
      detail: `Message length ${msg.text.length} exceeds max ${this.rules.maxMessageLength}`
    }];
  }

  #checkRepeatChars(msg) {
    const regex = new RegExp(`(.)\\1{${this.rules.maxRepeatChars},}`, "g");
    const matches = msg.text.match(regex);

    if (!matches) return [];

    return [{
      rule: "repeatChars",
      severity: "low",
      detail: `Repeated characters: "${matches[0].substring(0, 20)}..."`
    }];
  }

  #checkLinks(msg) {
    const urlRegex = /https?:\/\/([^\s/]+)/gi;
    const urls = [...msg.text.matchAll(urlRegex)];

    if (urls.length === 0) return [];

    const suspicious = urls.filter(match => {
      const domain = match[1].toLowerCase();
      return !this.rules.linkWhitelist.some(
        allowed => domain === allowed || domain.endsWith(`.${allowed}`)
      );
    });

    if (suspicious.length === 0) return [];

    return [{
      rule: "suspiciousLink",
      severity: "medium",
      detail: `Non-whitelisted links: ${suspicious.map(m => m[1]).join(", ")}`
    }];
  }

  #checkSpam(msg) {
    const now = Date.now();
    const window = this.rules.spamWindow.seconds * 1000;

    if (!this.userHistory.has(msg.userId)) {
      this.userHistory.set(msg.userId, []);
    }

    const history = this.userHistory.get(msg.userId);

    // Prune old entries
    while (history.length > 0 && now - history[0] > window) {
      history.shift();
    }

    history.push(now);

    if (history.length <= this.rules.spamWindow.maxMessages) return [];

    return [{
      rule: "spam",
      severity: "high",
      detail: `${history.length} messages in ${this.rules.spamWindow.seconds}s (max: ${this.rules.spamWindow.maxMessages})`
    }];
  }

  /**
   * Periodically clean stale user history to prevent memory leaks.
   */
  cleanup(maxAgeMs = 60_000) {
    const now = Date.now();
    for (const [userId, timestamps] of this.userHistory) {
      const recent = timestamps.filter(t => now - t < maxAgeMs);
      if (recent.length === 0) {
        this.userHistory.delete(userId);
      } else {
        this.userHistory.set(userId, recent);
      }
    }
  }
}
