## lib/actions.js — Violation Response Handler

```javascript
import { appendFile } from "node:fs/promises";

export class ActionHandler {
  constructor(actionMap, violationLogPath) {
    this.actionMap = actionMap;
    this.logPath = violationLogPath;
    this.mutedUsers = new Map(); // userId -> unmute timestamp
  }

  async handle(message, violations) {
    if (violations.length === 0) return { allowed: true };

    const result = {
      allowed: true,
      actions: [],
      warnings: []
    };

    for (const v of violations) {
      const actionType = this.actionMap[v.rule] || "warn";

      switch (actionType) {
        case "delete_and_warn":
          result.allowed = false;
          result.actions.push(`DELETED message from ${message.userId}`);
          result.warnings.push(`⚠️  ${message.userId}: ${v.detail}`);
          break;

        case "mute_5m":
          result.allowed = false;
          this.mutedUsers.set(message.userId, Date.now() + 5 * 60_000);
          result.actions.push(`MUTED ${message.userId} for 5 minutes`);
          break;

        case "hold_for_review":
          result.allowed = false;
          result.actions.push(`HELD message from ${message.userId} for review`);
          break;

        case "truncate":
          result.actions.push(`TRUNCATED message from ${message.userId}`);
          break;

        case "warn":
        default:
          result.warnings.push(`⚠️  ${message.userId}: ${v.detail}`);
          break;
      }
    }

    // Persist violation to disk
    await this.#logViolation(message, violations, result);

    return result;
  }

  isMuted(userId) {
    const until = this.mutedUsers.get(userId);
    if (!until) return false;
    if (Date.now() > until) {
      this.mutedUsers.delete(userId);
      return false;
    }
    return true;
  }

  async #logViolation(message, violations, result) {
    const entry = {
      timestamp: new Date().toISOString(),
      userId: message.userId,
      text: message.text.substring(0, 100),
      violations: violations.map(v => ({ rule: v.rule, severity: v.severity })),
      actionsTaken: result.actions
    };

    const line = JSON.stringify(entry) + "\n";

    try {
      await appendFile(this.logPath, line);
    } catch (err) {
      console.error("Failed to write violation log:", err.message);
    }
  }
}
