## lib/watcher.js — File Watcher with Tail Behavior

```javascript
import { watch, open, stat } from "node:fs/promises";
import { resolve } from "node:path";
import { EventEmitter } from "node:events";

/**
 * Watches a directory for .log files and emits parsed chat lines
 * as they are appended. Works like `tail -f` across multiple files.
 */
export class ChatFileWatcher extends EventEmitter {
  #dir;
  #offsets;   // file path -> byte offset (tracks what we've already read)
  #ac;        // AbortController for clean shutdown

  constructor(directory) {
    super();
    this.#dir = resolve(directory);
    this.#offsets = new Map();
    this.#ac = new AbortController();
  }

  async start() {
    console.log(`👁  Watching: ${this.#dir}`);

    // Initial scan — jump to end of existing files (don't reprocess history)
    await this.#seedOffsets();

    try {
      const watcher = watch(this.#dir, {
        signal: this.#ac.signal,
        recursive: false
      });

      for await (const event of watcher) {
        if (!event.filename?.endsWith(".log")) continue;

        const filePath = resolve(this.#dir, event.filename);
        await this.#readNewLines(filePath);
      }
    } catch (err) {
      if (err.name === "AbortError") {
        console.log("Watcher stopped.");
        return;
      }
      throw err;
    }
  }

  stop() {
    this.#ac.abort();
  }

  /**
   * Set file offsets to current size so we only read NEW content.
   */
  async #seedOffsets() {
    const { readdir } = await import("node:fs/promises");
    const files = await readdir(this.#dir);

    for (const f of files) {
      if (!f.endsWith(".log")) continue;
      const filePath = resolve(this.#dir, f);
      try {
        const info = await stat(filePath);
        this.#offsets.set(filePath, info.size);
      } catch { /* file may have been removed */ }
    }
  }

  /**
   * Read only the bytes appended since our last read.
   */
  async #readNewLines(filePath) {
    let fh;

    try {
      const info = await stat(filePath);
      const prevOffset = this.#offsets.get(filePath) ?? 0;

      // File was truncated/rotated — reset offset
      if (info.size < prevOffset) {
        this.#offsets.set(filePath, 0);
      }

      const offset = this.#offsets.get(filePath) ?? 0;
      if (info.size <= offset) return; // nothing new

      const bytesToRead = info.size - offset;
      const buffer = Buffer.alloc(bytesToRead);

      fh = await open(filePath, "r");
      await fh.read(buffer, 0, bytesToRead, offset);
      await fh.close();
      fh = null;

      this.#offsets.set(filePath, info.size);

      // Parse lines and emit messages
      const chunk = buffer.toString("utf-8");
      const lines = chunk.split("\n").filter(Boolean);

      for (const line of lines) {
        const message = this.#parseLine(line, filePath);
        if (message) {
          this.emit("message", message);
        }
      }
    } catch (err) {
      console.error(`Error reading ${filePath}: ${err.message}`);
    } finally {
      if (fh) await fh.close().catch(() => {});
    }
  }

  /**
   * Expected format: `[ISO_TIMESTAMP] userId: message text`
   * Example: `[2024-01-15T09:30:00Z] user42: hello everyone`
   */
  #parseLine(line, source) {
    const match = line.match(
      /^\[(?<ts>[^\]]+)\]\s+(?<userId>\S+):\s+(?<text>.+)$/
    );

    if (!match) {
      this.emit("parseError", { line, source });
      return null;
    }

    return {
      timestamp: match.groups.ts,
      userId: match.groups.userId,
      text: match.groups.text,
      source
    };
  }
}
```

## index.js — Glue Everything Together

```javascript
import { readFile, mkdir } from "node:fs/promises";
import { ChatFileWatcher } from "./lib/watcher.js";
import { Moderator } from "./lib/moderator.js";
import { ActionHandler } from "./lib/actions.js";

// --- Load config ---
const config = JSON.parse(await readFile("./config.json", "utf-8"));

// Ensure output directory exists
await mkdir("./output", { recursive: true });
await mkdir("./logs", { recursive: true });

// --- Init components ---
const watcher = new ChatFileWatcher(config.watchDir);
const moderator = new Moderator(config.rules);
const actions = new ActionHandler(config.actions, config.violationLog);

// --- Stats ---
let stats = { processed: 0, violations: 0, blocked: 0 };

// --- Periodic cleanup (every 60s) ---
const cleanupInterval = setInterval(() => moderator.cleanup(), 60_000);

// --- Handle incoming messages ---
watcher.on("message", async (msg) => {
  stats.processed++;

  // Check if user is muted
  if (actions.isMuted(msg.userId)) {
    console.log(`🔇 [MUTED] ${msg.userId}: ${msg.text.substring(0, 50)}...`);
    return;
  }

  // Run moderation
  const violations = moderator.check(msg);

  if (violations.length === 0) {
    // Clean message — minimal logging
    if (stats.processed % 100 === 0) {
      console.log(`✅ Processed ${stats.processed} messages (${stats.violations} violations)`);
    }
    return;
  }

  stats.violations++;

  // Execute actions
  const result = await actions.handle(msg, violations);

  if (!result.allowed) {
    stats.blocked++;
  }

  // Console output
  console.log(`\n${"─".repeat(60)}`);
  console.log(`📨 ${msg.timestamp} | ${msg.userId}`);
  console.log(`   "${msg.text.substring(0, 80)}${msg.text.length > 80 ? "..." : ""}"`);

  for (const v of violations) {
    const icon = v.severity === "high" ? "🔴" : v.severity === "medium" ? "🟡" : "🟢";
    console.log(`   ${icon} [${v.rule}] ${v.detail}`);
  }

  for (const a of result.actions) {
    console.log(`   ⚡ ${a}`);
  }

  console.log(`   Allowed: ${result.allowed}`);
});

watcher.on("parseError", ({ line }) => {
  console.log(`⚠️  Unparseable line: "${line.substring(0, 60)}..."`);
});

// --- Graceful shutdown ---
function shutdown() {
  console.log("\n\nShutting down...");
  console.log(`📊 Final stats: ${stats.processed} processed, ${stats.violations} violations, ${stats.blocked} blocked`);
  clearInterval(cleanupInterval);
  watcher.stop();
  process.exit(0);
}

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

// --- Start ---
console.log("🛡️  Chat Moderator started");
console.log(`   Rules loaded: ${config.rules.bannedWords.length} banned words, caps>${config.rules.maxCapsPercent}%, spam=${config.rules.spamWindow.maxMessages}/${config.rules.spamWindow.seconds}s`);
console.log("");

watcher.start();
```

