for (const msg of testMessages) {
  const ts = new Date().toISOString();
  const line = `[${ts}] ${msg.userId}: ${msg.text}\n`;

  await appendFile(LOG, line);
  console.log(`  → ${msg.userId}: ${msg.text.substring(0, 50)}`);

  // Small delay to make spam detection realistic
  await new Promise(r => setTimeout(r, 200));
}

console.log("\nDone. Check the moderator output.");
