// ─── Base Parser Class ────────────────────────────────────────────

class ParseError extends Error {
  constructor(message, line = null, column = null) {
    super(message);
    this.name = "ParseError";
    this.line = line;
    this.column = column;
  }
}

// ─── CSV Parser ───────────────────────────────────────────────────

class CSVParser {
  constructor(options = {}) {
    this.delimiter = options.delimiter || ",";
    this.hasHeader = options.hasHeader !== undefined ? options.hasHeader : true;
    this.trimValues = options.trimValues !== undefined ? options.trimValues : true;
  }

  parse(text) {
    if (!text || typeof text !== "string") {
      throw new ParseError("Input must be a non-empty string");
    }

    const rows = this._splitRows(text);

    if (rows.length === 0) {
      return { headers: [], rows: [], records: [] };
    }

    const parsedRows = rows.map((row, index) => this._parseRow(row, index));

    if (this.hasHeader && parsedRows.length > 0) {
      const headers = parsedRows[0];
      const dataRows = parsedRows.slice(1);

      // Convert rows to objects using headers
      const records = dataRows.map((row) => {
        const record = {};
        headers.forEach((header, i) => {
          record[header] = i < row.length ? row[i] : null;
        });
        return record;
      });

      return { headers, rows: dataRows, records };
    }

    return { headers: [], rows: parsedRows, records: [] };
  }

  _splitRows(text) {
    const rows = [];
    let current = "";
    let inQuotes = false;

    for (let i = 0; i < text.length; i++) {
      const char = text[i];

      if (char === '"') {
        if (inQuotes && text[i + 1] === '"') {
          current += '"';
          i++; // skip escaped quote
        } else {
          inQuotes = !inQuotes;
        }
      } else if ((char === "\n" || char === "\r") && !inQuotes) {
        if (char === "\r" && text[i + 1] === "\n") i++; // skip \r\n
        if (current.trim() !== "") rows.push(current);
        current = "";
      } else {
        current += char;
      }
    }

    if (current.trim() !== "") rows.push(current);
    return rows;
  }

  _parseRow(row, lineIndex) {
    const values = [];
    let current = "";
    let inQuotes = false;

    for (let i = 0; i < row.length; i++) {
      const char = row[i];

      if (char === '"') {
        if (inQuotes && row[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = !inQuotes;
        }
      } else if (char === this.delimiter && !inQuotes) {
        values.push(this._processValue(current));
        current = "";
      } else {
        current += char;
      }
    }

    values.push(this._processValue(current));
    return values;
  }

  _processValue(value) {
    if (this.trimValues) value = value.trim();

    // Auto-detect types
    if (value === "") return null;
    if (value.toLowerCase() === "true") return true;
    if (value.toLowerCase() === "false") return false;
    if (!isNaN(value) && value !== "") return Number(value);

    return value;
  }
}

// ─── Key-Value Parser ─────────────────────────────────────────────

class KeyValueParser {
  constructor(options = {}) {
    this.separator = options.separator || "=";
    this.commentChar = options.commentChar || "#";
    this.supportSections = options.supportSections !== undefined
      ? options.supportSections
      : true;
  }

  parse(text) {
    if (!text || typeof text !== "string") {
      throw new ParseError("Input must be a non-empty string");
    }

    const result = {};
    let currentSection = null;
    const lines = text.split(/\r?\n/);

    lines.forEach((line, index) => {
      const trimmed = line.trim();

      // Skip empty lines and comments
      if (trimmed === "" || trimmed.startsWith(this.commentChar)) {
        return;
      }

      // Section headers [section]
      if (this.supportSections && trimmed.startsWith("[") && trimmed.endsWith("]")) {
        currentSection = trimmed.slice(1, -1).trim();
        if (!result[currentSection]) {
          result[currentSection] = {};
        }
        return;
      }

      // Key-value pairs
      const sepIndex = trimmed.indexOf(this.separator);
      if (sepIndex === -1) {
        throw new ParseError(
          `Invalid syntax: missing '${this.separator}'`,
          index + 1
        );
      }

      const key = trimmed.slice(0, sepIndex).trim();
      let value = trimmed.slice(sepIndex + this.separator.length).trim();

      // Remove inline comments
      const commentIndex = value.indexOf(` ${this.commentChar}`);
      if (commentIndex !== -1) {
        value = value.slice(0, commentIndex).trim();
      }

      // Remove surrounding quotes
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }

      // Auto-detect types
      value = this._castValue(value);

      if (currentSection) {
        result[currentSection][key] = value;
      } else {
        result[key] = value;
      }
    });

    return result;
  }

  _castValue(value) {
    if (value === "") return "";
    if (value.toLowerCase() === "true") return true;
    if (value.toLowerCase() === "false") return false;
    if (value.toLowerCase() === "null") return null;
    if (!isNaN(value) && value !== "") return Number(value);
    return value;
  }
}

// ─── Markdown Parser (subset) ─────────────────────────────────────

class MarkdownParser {
  parse(text) {
    if (!text || typeof text !== "string") {
      throw new ParseError("Input must be a non-empty string");
    }

    const tokens = [];
    const lines = text.split(/\r?\n/);
    let i = 0;

    while (i < lines.length) {
      const line = lines[i];

      // Empty line
      if (line.trim() === "") {
        i++;
        continue;
      }

      // Headings: # H1, ## H2, etc.
      const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);
      if (headingMatch) {
        tokens.push({
          type: "heading",
          level: headingMatch[1].length,
          text: headingMatch[2].trim(),
          inline: this._parseInline(headingMatch[2].trim()),
        });
        i++;
        continue;
      }

      // Horizontal rule: ---, ***, ___
      if (/^(-{3,}|\*{3,}|_{3,})$/.test(line.trim())) {
        tokens.push({ type: "hr" });
        i++;
        continue;
      }

      // Unordered list items: - item, * item
      if (/^[\s]*[-*+]\s+/.test(line)) {
        const listItems = [];
        while (i < lines.length && /^[\s]*[-*+]\s+/.test(lines[i])) {
          const itemText = lines[i].replace(/^[\s]*[-*+]\s+/, "").trim();
          listItems.push({
            text: itemText,
            inline: this._parseInline(itemText),
          });
          i++;
        }
        tokens.push({ type: "list", ordered: false, items: listItems });
        continue;
      }

      // Ordered list items: 1. item
      if (/^[\s]*\d+\.\s+/.test(line)) {
        const listItems = [];
        while (i < lines.length && /^[\s]*\d+\.\s+/.test(lines[i])) {
          const itemText = lines[i].replace(/^[\s]*\d+\.\s+/, "").trim();
          listItems.push({
            text: itemText,
            inline: this._parseInline(itemText),
          });
          i++;
        }
        tokens.push({ type: "list", ordered: true, items: listItems });
        continue;
      }

      // Code block: ```
      if (line.trim().startsWith("```")) {
        const lang = line.trim().slice(3).trim() || null;
        const codeLines = [];
        i++;
        while (i < lines.length && !lines[i].trim().startsWith("```")) {
          codeLines.push(lines[i]);
          i++;
        }
        tokens.push({
          type: "codeblock",
          language: lang,
          code: codeLines.join("\n"),
        });
        i++; // skip closing ```
        continue;
      }

      // Blockquote: > text
      if (line.trim().startsWith(">")) {
        const quoteLines = [];
        while (i < lines.length && lines[i].trim().startsWith(">")) {
          quoteLines.push(lines[i].replace(/^>\s?/, ""));
          i++;
        }
        const quoteText = quoteLines.join("\n").trim();
        tokens.push({
          type: "blockquote",
          text: quoteText,
          inline: this._parseInline(quoteText),
        });
        continue;
      }

      // Paragraph (default)
      const paraLines = [];
      while (i < lines.length && lines[i].trim() !== "" && !this._isBlockStart(lines[i])) {
        paraLines.push(lines[i]);
        i++;
      }
      if (paraLines.length > 0) {
        const paraText = paraLines.join(" ").trim();
        tokens.push({
          type: "paragraph",
          text: paraText,
          inline: this._parseInline(paraText),
        });
      }
    }

    return { tokens };
  }

  _isBlockStart(line) {
    return (
      /^#{1,6}\s/.test(line) ||
      /^[-*+]\s/.test(line.trim()) ||
      /^\d+\.\s/.test(line.trim()) ||
      line.trim().startsWith("```") ||
      line.trim().startsWith(">") ||
      /^(-{3,}|\*{3,}|_{3,})$/.test(line.trim())
    );
  }

  _parseInline(text) {
    const tokens = [];
    // Regex for inline elements: **bold**, *italic*, `code`, [link](url), ![alt](src)
    const regex = /(\*\*(.+?)\*\*|\*(.+?)\*|`(.+?)`|!\[([^\]]*)\]\(([^)]+)\)|\[([^\]]+)\]\(([^)]+)\))/g;

    let lastIndex = 0;
    let match;

    while ((match = regex.exec(text)) !== null) {
      // Text before the match
      if (match.index > lastIndex) {
        tokens.push({ type: "text", content: text.slice(lastIndex, match.index) });
      }

      if (match[2]) {
        tokens.push({ type: "bold", content: match[2] });
      } else if (match[3]) {
        tokens.push({ type: "italic", content: match[3] });
      } else if (match[4]) {
        tokens.push({ type: "code", content: match[4] });
      } else if (match[5] !== undefined) {
        tokens.push({ type: "image", alt: match[5], src: match[6] });
      } else if (match[7]) {
        tokens.push({ type: "link", text: match[7], href: match[8] });
      }

      lastIndex = regex.lastIndex;
    }

    // Remaining text
    if (lastIndex < text.length) {
      tokens.push({ type: "text", content: text.slice(lastIndex) });
    }

    return tokens;
  }
}

// ─── Document Parser Factory ──────────────────────────────────────

class DocumentParser {
  static csv(options) {
    return new CSVParser(options);
  }

  static keyValue(options) {
    return new KeyValueParser(options);
  }

  static markdown() {
    return new MarkdownParser();
  }

  /**
   * Auto-detect format and parse
   */
  static autoParse(text) {
    if (!text || typeof text !== "string") {
      throw new ParseError("Input must be a non-empty string");
    }

    const trimmed = text.trim();

    // Try JSON first
    if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
      try {
        return { format: "json", data: JSON.parse(trimmed) };
      } catch (e) {
        // Not valid JSON, continue
      }
    }

    // Check for CSV (has commas and consistent column count)
    const csvLines = trimmed.split("\n").filter((l) => l.trim());
    if (csvLines.length > 1) {
      const commaCount = (csvLines[0].match(/,/g) || []).length;
      if (commaCount > 0) {
        const consistent = csvLines.every(
          (l) => (l.match(/,/g) || []).length === commaCount
        );
        if (consistent) {
          return { format: "csv", data: new CSVParser().parse(trimmed) };
        }
      }
    }

    // Check for Markdown indicators
    if (/^#{1,6}\s/m.test(trimmed) || /^\*\s/m.test(trimmed) || /^```/m.test(trimmed)) {
      return { format: "markdown", data: new MarkdownParser().parse(trimmed) };
    }

    // Check for key-value (has = signs)
    if (/^[\w.]+\s*=\s*.+/m.test(trimmed)) {
      return { format: "keyvalue", data: new KeyValueParser().parse(trimmed) };
    }

    throw new ParseError("Unable to auto-detect document format");
  }
}

// ─── Exports ──────────────────────────────────────────────────────

module.exports = {
  DocumentParser,
  CSVParser,
  KeyValueParser,
  MarkdownParser,
  ParseError,
};
