function assertEqual(actual, expected, msg = "") {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) {
    throw new Error(`${msg}\n       Expected: ${e}\n       Received: ${a}`);
  }
}

function assertDeepEqual(actual, expected, msg = "") {
  assertEqual(actual, expected, msg);
}

function assertTrue(value, msg = "") {
  if (!value) throw new Error(msg || `Expected truthy, got: ${value}`);
}

function assertThrows(fn, errorType = Error, msg = "") {
  let threw = false;
  try {
    fn();
  } catch (err) {
    threw = true;
    if (!(err instanceof errorType)) {
      throw new Error(
        `${msg} Expected ${errorType.name}, got ${err.constructor.name}`
      );
    }
  }
  if (!threw) throw new Error(msg || `Expected function to throw ${errorType.name}`);
}

