```typescript
// src/core/types.ts

/** Unique identifier for events flowing through the pipeline */
export type EventId = string;

/** Base analytics event with metadata envelope */
export interface AnalyticsEvent<T = unknown> {
  readonly id: EventId;
  readonly timestamp: number;
  readonly source: string;
  readonly type: string;
  readonly payload: T;
  readonly metadata: Readonly<Record<string, string | number | boolean>>;
}

/** Result of processing — carries the event or an error */
export type ProcessingResult<T> =
  | { readonly success: true; readonly event: AnalyticsEvent<T> }
  | {
      readonly success: false;
      readonly event: AnalyticsEvent;
      readonly error: Error;
      readonly stage: string;
    };

/** Every pipeline stage implements this contract */
export interface PipelineStage<TIn = unknown, TOut = unknown> {
  readonly name: string;
  process(event: AnalyticsEvent<TIn>): Promise<AnalyticsEvent<TOut> | null>;
  initialize?(): Promise<void>;
  shutdown?(): Promise<void>;
}

/** Configuration for the pipeline runner */
export interface PipelineConfig {
  readonly name: string;
  readonly maxConcurrency: number;
  readonly enableMetrics: boolean;
  readonly shutdownTimeoutMs: number;
  readonly onError: ErrorStrategy;
}

export enum ErrorStrategy {
  SKIP = "skip",
  DEAD_LETTER = "dead-letter",
  HALT = "halt",
}

/** Observable metrics emitted by the pipeline */
export interface PipelineMetrics {
  eventsReceived: number;
  eventsProcessed: number;
  eventsFailed: number;
  eventsFiltered: number;
  processingTimeMs: MovingStats;
  stageMetrics: Map<string, StageMetrics>;
}

export interface StageMetrics {
  processed: number;
  failed: number;
  avgLatencyMs: number;
  lastError?: Error;
}

/** Lightweight running-statistics tracker */
export class MovingStats {
  private values: number[] = [];
  private readonly windowSize: number;

  constructor(windowSize = 1000) {
    this.windowSize = windowSize;
  }

  record(value: number): void {
    this.values.push(value);
    if (this.values.length > this.windowSize) {
      this.values.shift();
    }
  }

  get avg(): number {
    if (this.values.length === 0) return 0;
    return this.values.reduce((a, b) => a + b, 0) / this.values.length;
  }

  get p95(): number {
    if (this.values.length === 0) return 0;
    const sorted = [...this.values].sort((a, b) => a - b);
    const idx = Math.ceil(sorted.length * 0.95) - 1;
    return sorted[idx] ?? 0;
  }

  get p99(): number {
    if (this.values.length === 0) return 0;
    const sorted = [...this.values].sort((a, b) => a - b);
    const idx = Math.ceil(sorted.length * 0.99) - 1;
    return sorted[idx] ?? 0;
  }

  get count(): number {
    return this.values.length;
  }
}

/** Typed event emitter contract for pipeline lifecycle hooks */
export interface PipelineEvents {
  onEventReceived?(event: AnalyticsEvent): void;
  onEventProcessed?(event: AnalyticsEvent): void;
  onEventFailed?(event: AnalyticsEvent, error: Error, stage: string): void;
  onEventFiltered?(event: AnalyticsEvent, stage: string): void;
  onStageError?(stage: string, error: Error): void;
}

/** Utility: create an event with sensible defaults */
export function createEvent<T>(
  partial: Pick<AnalyticsEvent<T>, "source" | "type" | "payload"> &
    Partial<AnalyticsEvent<T>>
): AnalyticsEvent<T> {
  return {
    id: partial.id ?? crypto.randomUUID(),
    timestamp: partial.timestamp ?? Date.now(),
    source: partial.source,
    type: partial.type,
    payload: partial.payload,
    metadata: partial.metadata ?? {},
  };
}
