  push(...events: AnalyticsEvent<T>[]): void {
    this.queue.push(...events);
  }

  async poll(batchSize: number): Promise<AnalyticsEvent<T>[]> {
    return this.queue.splice(0, batchSize);
  }

  get pending(): number {
    return this.queue.length;
  }
