/** Wraps a callback / webhook style push source */
export class CallbackSource<T> implements EventSource<T> {
  private buffer: AnalyticsEvent<T>[] = [];
  private readonly maxBufferSize: number;

  constructor(maxBufferSize = 10_000) {
    this.maxBufferSize = maxBufferSize;
  }

  /** Called externally when a new raw event arrives */
  ingest(source: string, type: string, payload: T): AnalyticsEvent<T> {
    if (this.buffer.length >= this.maxBufferSize) {
      throw new Error(
        `Source buffer overflow: ${this.buffer.length} >= ${this.maxBufferSize}`
      );
    }
    const event = createEvent<T>({ source, type, payload });
    this.buffer.push(event);
    return event;
  }

  async poll(batchSize: number): Promise<AnalyticsEvent<T>[]> {
    return this.buffer.splice(0, batchSize);
  }

  get pending(): number {
    return this.buffer.length;
  }
}
