export class EnrichmentStage<T = unknown>
  implements PipelineStage<T, T>
{
  readonly name: string;
  private readonly enrichFn: (
    event: AnalyticsEvent<T>
  ) => Promise<Record<string, string | number | boolean>>;

  constructor(
    name: string,
    enrichFn: (
      event: AnalyticsEvent<T>
    ) => Promise<Record<string, string | number | boolean>>
  ) {
    this.name = name;
    this.enrichFn = enrichFn;
  }

  async process(event: AnalyticsEvent<T>): Promise<AnalyticsEvent<T>> {
    const extra = await this.enrichFn(event);
    return {
      ...event,
      metadata: { ...event.metadata, ...extra },
    };
  }
