import { AnalyticsEvent, PipelineStage } from "../core/types";

export type FilterPredicate<T> = (
  event: AnalyticsEvent<T>
) => Promise<boolean> | boolean;

/** Drops events that do not satisfy the predicate (returns null) */
export class FilterStage<T = unknown> implements PipelineStage<T, T> {
  readonly name: string;
  private readonly predicate: FilterPredicate<T>;

  constructor(name: string, predicate: FilterPredicate<T>) {
    this.name = name;
    this.predicate = predicate;
  }

  async process(
    event: AnalyticsEvent<T>
  ): Promise<AnalyticsEvent<T> | null> {
    const keep = await this.predicate(event);
    return keep ? event : null;
  }
}

/** Convenience: filter by event type */
export function filterByType<T>(
  ...allowedTypes: string[]
): FilterStage<T> {
  const typeSet = new Set(allowedTypes);
  return new FilterStage(
    `filter-type[${allowedTypes.join(",")}]`,
    (event) => typeSet.has(event.type)
  );
}

/** Convenience: sample events at a given rate 0..1 */
export function sampleEvents<T>(rate: number): FilterStage<T> {
  if (rate < 0 || rate > 1) {
    throw new RangeError(`Sample rate must be 0..1, got ${rate}`);
  }
  return new FilterStage(`sample[${rate}]`, () => Math.random() < rate);
}

/** Deduplicate events by id within a sliding time window */
export class DeduplicationStage<T = unknown>
  implements PipelineStage<T, T>
{
  readonly name = "dedup";
  private seen = new Map<string, number>();
  private readonly windowMs: number;

  constructor(windowMs = 60_000) {
    this.windowMs = windowMs;
  }

  async process(
    event: AnalyticsEvent<T>
  ): Promise<AnalyticsEvent<T> | null> {
    const now = Date.now();

    // Evict expired entries
    for (const [id, ts] of this.seen) {
      if (now - ts > this.windowMs) this.seen.delete(id);
    }

    if (this.seen.has(event.id)) return null;
    this.seen.set(event.id, now);
    return event;
  }
}
