// src/stages/aggregate.ts

import {
  AnalyticsEvent,
  PipelineStage,
  createEvent,
} from "../core/types";

/** The shape an aggregation window emits when it flushes */
export interface AggregationResult<TAcc> {
  windowStart: number;
  windowEnd: number;
  key: string;
  value: TAcc;
  eventCount: number;
}

export interface AggregatorConfig<TIn, TAcc> {
  /** Stage name */
  name: string;
  /** Extract the grouping key from an event */
  keyFn: (event: AnalyticsEvent<TIn>) => string;
  /** Produce the initial accumulator for a new key */
  initialValue: () => TAcc;
  /** Fold an event into the accumulator */
  reducer: (acc: TAcc, event: AnalyticsEvent<TIn>) => TAcc;
  /** How wide each tumbling window is in ms */
  windowSizeMs: number;
  /** Optional: maximum events before forcing a flush */
  maxEventsPerWindow?: number;
}

interface WindowState<TAcc> {
  acc: TAcc;
  count: number;
  start: number;
}

/**
 * Tumbling-window aggregation stage.
 * Collects events into windows by key, flushes on window expiry or maxEvents.
 */
export class AggregationStage<TIn, TAcc>
  implements PipelineStage<TIn, AggregationResult<TAcc>>
{
  readonly name: string;
  private readonly config: AggregatorConfig<TIn, TAcc>;
  private windows = new Map<string, WindowState<TAcc>>();
  private flushQueue: AggregationResult<TAcc>[] = [];
  private timer: ReturnType<typeof setInterval> | null = null;

  constructor(config: AggregatorConfig<TIn, TAcc>) {
    this.name = config.name;
    this.config = config;
  }

  async initialize(): Promise<void> {
    // Periodically check for expired windows
    this.timer = setInterval(
      () => this.flushExpired(),
      this.config.windowSizeMs / 2
    );
  }

  async shutdown(): Promise<void> {
    if (this.timer) clearInterval(this.timer);
    // Flush everything remaining
    this.flushAll();
  }

  async process(
    event: AnalyticsEvent<TIn>
  ): Promise<AnalyticsEvent<AggregationResult<TAcc>> | null> {
    const key = this.config.keyFn(event);
    const now = Date.now();

    let window = this.windows.get(key);
    if (!window) {
      window = {
        acc: this.config.initialValue(),
        count: 0,
        start: now,
      };
      this.windows.set(key, window);
    }

    window.acc = this.config.reducer(window.acc, event);
    window.count++;

    // Force-flush if max events hit
    const max = this.config.maxEventsPerWindow;
    if (max !== undefined && window.count >= max) {
      const result = this.buildResult(key, window, now);
      this.windows.delete(key);
      return this.wrapResult(result);
    }

    // Check if any queued flushes are ready
    const queued = this.flushQueue.shift();
    return queued ? this.wrapResult(queued) : null;
  }

  /** Manually drain all completed aggregation results */
  drain(): AggregationResult<TAcc>[] {
    const results = [...this.flushQueue];
    this.flushQueue = [];
    return results;
  }

  /** Flush all windows regardless of expiry */
  flushAll(): AggregationResult<TAcc>[] {
    const now = Date.now();
    const results: AggregationResult<TAcc>[] = [];
    for (const [key, window] of this.windows) {
      results.push(this.buildResult(key, window, now));
    }
    this.windows.clear();
    this.flushQueue.push(...results);
    return results;
  }

  private flushExpired(): void {
    const now = Date.now();
    for (const [key, window] of this.windows) {
      if (now - window.start >= this.config.windowSizeMs) {
        this.flushQueue.push(this.buildResult(key, window, now));
        this.windows.delete(key);
      }
    }
  }

  private buildResult(
    key: string,
    window: WindowState<TAcc>,
    now: number
  ): AggregationResult<TAcc> {
    return {
      windowStart: window.start,
      windowEnd: now,
      key,
      value: window.acc,
      eventCount: window.count,
    };
  }

  private wrapResult(
    result: AggregationResult<TAcc>
  ): AnalyticsEvent<AggregationResult<TAcc>> {
    return createEvent({
      source: this.name,
      type: "aggregation_result",
      payload: result,
    });
  }

  get activeWindows(): number {
    return this.windows.size;
  }

  get pendingResults(): number {
    return this.flushQueue.length;
  }
}
