## Retry Handler

```javascript
// src/RetryHandler.js
const EventEmitter = require('events');

class RetryHandler extends EventEmitter {
  constructor(options = {}) {
    super();
    this.maxRetries = options.maxRetries || 5;
    this.initialDelayMs = options.initialDelayMs || 1000;
    this.maxDelayMs = options.maxDelayMs || 30000;
    this.backoffMultiplier = options.backoffMultiplier || 2;
    this.retryableStatusCodes = options.retryableStatusCodes || [
      408, 429, 500, 502, 503, 504,
    ];
  }

  /**
   * Calculate delay with exponential backoff + jitter
   */
  calculateDelay(attempt) {
    const exponentialDelay =
      this.initialDelayMs * Math.pow(this.backoffMultiplier, attempt);
    const cappedDelay = Math.min(exponentialDelay, this.maxDelayMs);

    // Add jitter (±25%) to prevent thundering herd
    const jitter = cappedDelay * 0.25 * (Math.random() * 2 - 1);
    return Math.round(cappedDelay + jitter);
  }

  /**
   * Determine if an error is retryable
   */
  isRetryable(error) {
    // Network errors are retryable
    if (error.code === 'ECONNRESET' || error.code === 'ECONNREFUSED' ||
        error.code === 'ETIMEDOUT' || error.code === 'EPIPE' ||
        error.code === 'ENOTFOUND' || error.type === 'request-timeout') {
      return true;
    }

    // Check HTTP status codes
    if (error.statusCode && this.retryableStatusCodes.includes(error.statusCode)) {
      return true;
    }

    return false;
  }

  /**
   * Execute a function with retry logic
   */
  async execute(fn, context = 'operation') {
    let lastError;

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      try {
        const result = await fn(attempt);

        // Emit success after retries
        if (attempt > 0) {
          this.emit('retrySuccess', { context, attempt });
        }

        return result;
      } catch (error) {
        lastError = error;

        this.emit('error', {
          context,
          attempt,
          error: error.message,
          retryable: this.isRetryable(error),
        });

        // Don't retry if max attempts reached or error isn't retryable
        if (attempt >= this.maxRetries) {
          this.emit('maxRetriesExceeded', {
            context,
            totalAttempts: attempt + 1,
            error: error.message,
          });
          break;
        }

        if (!this.isRetryable(error)) {
          this.emit('nonRetryableError', { context, error: error.message });
          break;
        }

        // Handle rate limiting with Retry-After header
        const delay = error.retryAfter
          ? error.retryAfter * 1000
          : this.calculateDelay(attempt);

        this.emit('retry', {
          context,
          attempt: attempt + 1,
          delayMs: delay,
          reason: error.message,
        });

        await this._sleep(delay);
      }
    }

    throw lastError;
  }

  _sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

module.exports = RetryHandler;
```

## Batch Processor

```javascript
// src/BatchProcessor.js
const EventEmitter = require('events');

class BatchProcessor extends EventEmitter {
  constructor(options = {}) {
    super();
    this.maxSize = options.maxSize || 100;
    this.flushIntervalMs = options.flushIntervalMs || 5000;
    this.processFn = options.processFn;

    this.buffer = [];
    this.flushTimer = null;
    this.isFlushing = false;
    this.isShutdown = false;
  }

  /**
   * Start the batch processor
   */
  start() {
    this._scheduleFlush();
    this.emit('started');
    return this;
  }

  /**
   * Add an item to the batch
   */
  add(item) {
    if (this.isShutdown) {
      throw new Error('BatchProcessor is shut down');
    }

    this.buffer.push({
      ...item,
      _bufferedAt: Date.now(),
    });

    this.emit('itemAdded', { bufferSize: this.buffer.length });

    // Flush immediately if buffer is full
    if (this.buffer.length >= this.maxSize) {
      this.emit('bufferFull', { size: this.buffer.length });
      this._flush();
    }
  }

  /**
   * Force flush the current buffer
   */
  async flush() {
    return this._flush();
  }

  /**
   * Graceful shutdown — flush remaining items
   */
  async shutdown() {
    this.isShutdown = true;

    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }

    // Flush remaining items
    if (this.buffer.length > 0) {
      await this._flush();
    }

    this.emit('shutdown');
  }

  async _flush() {
    if (this.isFlushing || this.buffer.length === 0) return;

    this.isFlushing = true;

    // Take current buffer and reset
    const batch = this.buffer.splice(0, this.maxSize);

    try {
      this.emit('flushing', { batchSize: batch.length });
      await this.processFn(batch);
      this.emit('flushed', { batchSize: batch.length });
    } catch (error) {
      this.emit('flushError', { batchSize: batch.length, error: error.message });
      // Put failed items back at front of buffer for retry
      this.buffer.unshift(...batch);
    } finally {
      this.isFlushing = false;

      // Schedule next flush if not shutting down
      if (!this.isShutdown) {
        this._scheduleFlush();
      }
    }
  }

  _scheduleFlush() {
    if (this.flushTimer) clearTimeout(this.flushTimer);

    this.flushTimer = setTimeout(() => {
      this._flush();
    }, this.flushIntervalMs);

    // Allow Node.js to exit if this is the only timer
    if (this.flushTimer.unref) {
      this.flushTimer.unref();
    }
  }
}

module.exports = BatchProcessor;
```

## Log Ingestion Client

```javascript
// src/LogIngestionClient.js
const http = require('http');
const https = require('https');
const { URL } = require('url');
const EventEmitter = require('events');
const RetryHandler = require('./RetryHandler');
const BatchProcessor = require('./BatchProcessor');
const defaultConfig = require('./config');

class LogIngestionClient extends EventEmitter {
  constructor(config = {}) {
    super();
    this.config = { ...defaultConfig, ...config };

    // Initialize retry handler
    this.retryHandler = new RetryHandler(this.config.retry);
    this._setupRetryLogging();

    // Initialize batch processor
    this.batchProcessor = new BatchProcessor({
      ...this.config.batch,
      processFn: (batch) => this._sendBatch(batch),
    });
    this._setupBatchLogging();

    // Stats
    this.stats = {
      totalLogs: 0,
      successfulSends: 0,
      failedSends: 0,
      totalRetries: 0,
      lastError: null,
      startedAt: null,
    };
  }

  /**
   * Start the ingestion client
   */
  start() {
    this.stats.startedAt = new Date().toISOString();
    this.batchProcessor.start();
    console.log('[LogIngestion] Client started');
    return this;
  }

  /**
   * Ingest a single log entry
   */
  ingest(log) {
    const enrichedLog = this._enrichLog(log);
    this.batchProcessor.add(enrichedLog);
    this.stats.totalLogs++;
  }

  /**
   * Ingest multiple log entries
   */
  ingestBatch(logs) {
    logs.forEach((log) => this.ingest(log));
  }

  /**
   * Send a single log immediately (bypass batching)
   */
  async sendImmediate(log) {
    const enrichedLog = this._enrichLog(log);
    this.stats.totalLogs++;

    return this.retryHandler.execute(
      () => this._httpSend([enrichedLog]),
      'immediate-send'
    );
  }

  /**
   * Flush pending logs
   */
  async flush() {
    return this.batchProcessor.flush();
  }

  /**
   * Graceful shutdown
   */
  async shutdown() {
    console.log('[LogIngestion] Shutting down...');
    await this.batchProcessor.shutdown();
    console.log('[LogIngestion] Shutdown complete', this.getStats());
  }

  /**
   * Get current stats
   */
  getStats() {
    return { ...this.stats };
  }

  // ── Private Methods ──────────────────────────────

  /**
   * Enrich log with metadata
   */
  _enrichLog(log) {
    return {
      timestamp: new Date().toISOString(),
      hostname: require('os').hostname(),
      pid: process.pid,
      ...(typeof log === 'string' ? { message: log } : log),
    };
  }

  /**
   * Send a batch of logs with retry
   */
  async _sendBatch(batch) {
    try {
      await this.retryHandler.execute(
        () => this._httpSend(batch),
        `batch-send(${batch.length})`
      );
      this.stats.successfulSends += batch.length;
    } catch (error) {
      this.stats.failedSends += batch.length;
      this.stats.lastError = {
        message: error.message,
        timestamp: new Date().toISOString(),
      };
      throw error; // Re-throw so BatchProcessor can re-buffer
    }
  }

  /**
   * HTTP POST request to ingestion endpoint
   */
  _httpSend(logs) {
    return new Promise((resolve, reject) => {
      const payload = JSON.stringify({ logs });
      const url = new URL(this.config.endpoint);
      const transport = url.protocol === 'https:' ? https : http;

      const options = {
        hostname: url.hostname,
        port: url.port,
        path: url.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(payload),
          ...(this.config.apiKey && {
            Authorization: `Bearer ${this.config.apiKey}`,
          }),
        },
        timeout: this.config.requestTimeoutMs,
      };

      const req = transport.request(options, (res) => {
        let body = '';
        res.on('data', (chunk) => (body += chunk));
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve({ statusCode: res.statusCode, body });
          } else {
            const error = new Error(
              `HTTP ${res.statusCode}: ${body || res.statusMessage}`
            );
            error.statusCode = res.statusCode;

            // Parse Retry-After header for 429 responses
            if (res.headers['retry-after']) {
              error.retryAfter = parseInt(res.headers['retry-after'], 10);
            }

            reject(error);
          }
        });
      });

      req.on('timeout', () => {
        req.destroy();
        const error = new Error('Request timed out');
        error.type = 'request-timeout';
        reject(error);
      });

      req.on('error', (err) => reject(err));

      req.write(payload);
      req.end();
    });
  }

  _setupRetryLogging() {
    this.retryHandler.on('retry', ({ context, attempt, delayMs, reason }) => {
      console.warn(
        `[LogIngestion] Retry #${attempt} for ${context} in ${delayMs}ms — ${reason}`
      );
      this.stats.totalRetries++;
    });

    this.retryHandler.on('maxRetriesExceeded', ({ context, totalAttempts }) => {
      console.error(
        `[LogIngestion] Max retries exceeded for ${context} after ${totalAttempts} attempts`
      );
    });

    this.retryHandler.on('retrySuccess', ({ context, attempt }) => {
      console.log(
        `[LogIngestion] ${context} succeeded after ${attempt} retries`
      );
    });
  }

  _setupBatchLogging() {
    this.batchProcessor.on('flushing', ({ batchSize }) => {
      console.log(`[LogIngestion] Flushing batch of ${batchSize} logs`);
    });

    this.batchProcessor.on('flushError', ({ batchSize, error }) => {
      console.error(
        `[LogIngestion] Failed to flush ${batchSize} logs: ${error}`
      );
    });
  }
}

module.exports = LogIngestionClient;
```

