  batch: {
    maxSize: 50,
    flushIntervalMs: 3000,
  },
});

// ── Start Client ────────────────────────────────
client.start();

// ── Example: Ingest individual logs ─────────────
client.ingest({
  level: 'info',
  service: 'auth-service',
  message: 'User logged in',
  userId: 'usr_123',
});

client.ingest({
  level: 'error',
  service: 'payment-service',
  message: 'Payment failed',
  error: 'Insufficient funds',
  orderId: 'ord_456',
});

// ── Example: Ingest string messages ─────────────
client.ingest('Application started successfully');

// ── Example: Batch ingest ───────────────────────
const logs = Array.from({ length: 25 }, (_, i) => ({
  level: 'debug',
  service: 'data-pipeline',
  message: `Processing record ${i + 1}`,
  recordId: i + 1,
}));

client.ingestBatch(logs);

// ── Example: Immediate send (no batching) ───────
async function sendCriticalLog() {
  try {
    await client.sendImmediate({
      level: 'fatal',
      service: 'core-service',
      message: 'Database connection lost',
      alert: true,
    });
    console.log('Critical log sent successfully');
  } catch (error) {
    console.error('Failed to send critical log:', error.message);
  }
}

sendCriticalLog();

// ── Print stats periodically ────────────────────
setInterval(() => {
  console.log('[Stats]', client.getStats());
}, 10000);

// ── Graceful Shutdown ───────────────────────────
async function gracefulShutdown(signal) {
  console.log(`\nReceived ${signal}. Shutting down gracefully...`);
  await client.shutdown();
  process.exit(0);
}

process.on('SIGINT', () => gracefulShutdown('SIGINT'));
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));

module.exports = client;
