## Core: ConfigParser

```javascript
// src/ConfigParser.js
const { EventEmitter } = require("node:events");
const fs = require("node:fs");
const path = require("node:path");

class ConfigParser extends EventEmitter {
  #config = {};           // merged config store
  #sources = new Map();   // track loaded files
  #validators = [];       // registered validation functions
  #watchers = new Map();  // file watchers for hot-reload

  constructor(options = {}) {
    super();
    this.setMaxListeners(options.maxListeners || 20);
    this.#registerBuiltInParsers();
  }

  // ── built-in format parsers keyed by extension ──────────────
  #parsers = {};

  #registerBuiltInParsers() {
    // JSON
    this.#parsers[".json"] = (content) => JSON.parse(content);

    // INI / conf
    this.#parsers[".ini"] = (content) => this.#parseINI(content);
    this.#parsers[".conf"] = this.#parsers[".ini"];

    // ENV / dotenv
    this.#parsers[".env"] = (content) => this.#parseENV(content);
  }

  // ── INI parser ──────────────────────────────────────────────
  #parseINI(content) {
    const result = {};
    let currentSection = null;

    for (const raw of content.split("\n")) {
      const line = raw.trim();

      // skip blanks and comments
      if (!line || line.startsWith(";") || line.startsWith("#")) continue;

      // section header
      const sectionMatch = line.match(/^\[([^\]]+)\]$/);
      if (sectionMatch) {
        currentSection = sectionMatch[1].trim();
        result[currentSection] ??= {};
        continue;
      }

      // key=value
      const eqIdx = line.indexOf("=");
      if (eqIdx === -1) continue;

      const key = line.slice(0, eqIdx).trim();
      const value = this.#coerceValue(line.slice(eqIdx + 1).trim());

      if (currentSection) {
        result[currentSection][key] = value;
      } else {
        result[key] = value;
      }
    }
    return result;
  }

  // ── ENV parser ──────────────────────────────────────────────
  #parseENV(content) {
    const result = {};

    for (const raw of content.split("\n")) {
      const line = raw.trim();
      if (!line || line.startsWith("#")) continue;

      const eqIdx = line.indexOf("=");
      if (eqIdx === -1) continue;

      const key = line.slice(0, eqIdx).trim();
      let value = line.slice(eqIdx + 1).trim();

      // strip surrounding quotes
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      result[key] = this.#coerceValue(value);
    }
    return result;
  }

  // ── type coercion for string values ─────────────────────────
  #coerceValue(str) {
    if (str === "true") return true;
    if (str === "false") return false;
    if (str === "null") return null;
    if (str === "undefined") return undefined;
    if (/^-?\d+$/.test(str)) return parseInt(str, 10);
    if (/^-?\d+\.\d+$/.test(str)) return parseFloat(str);
    return str;
  }

  // ── public: register custom parser ──────────────────────────
  registerParser(extension, parserFn) {
    const ext = extension.startsWith(".") ? extension : `.${extension}`;
    this.#parsers[ext] = parserFn;
    this.emit("parser:registered", { extension: ext });
    return this;
  }

  // ── public: register validator ──────────────────────────────
  registerValidator(validatorFn) {
    this.#validators.push(validatorFn);
    return this;
  }

  // ── public: load a single config file ───────────────────────
  loadFile(filePath) {
    const absPath = path.resolve(filePath);
    const ext = path.extname(absPath).toLowerCase();

    if (!this.#parsers[ext]) {
      const err = new Error(`No parser registered for extension "${ext}"`);
      this.emit("error", err);
      throw err;
    }

    try {
      const content = fs.readFileSync(absPath, "utf-8");
      const parsed = this.#parsers[ext](content);

      this.emit("file:loaded", { path: absPath, extension: ext });

      // validate
      this.#validate(parsed, absPath);

      // merge into main config
      this.#deepMerge(this.#config, parsed);
      this.#sources.set(absPath, { loadedAt: new Date(), extension: ext });

      this.emit("config:updated", {
        source: absPath,
        config: this.getAll(),
      });

      return parsed;
    } catch (err) {
      if (err.message.includes("No parser")) throw err;
      const wrapped = new Error(
        `Failed to parse "${absPath}": ${err.message}`
      );
      this.emit("error", wrapped);
      throw wrapped;
    }
  }

  // ── public: load every file in a directory ──────────────────
  loadDirectory(dirPath, options = {}) {
    const absDir = path.resolve(dirPath);
    const { extensions = Object.keys(this.#parsers), recursive = false } =
      options;

    const results = {};

    const walk = (dir) => {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory() && recursive) {
          walk(full);
        } else if (entry.isFile()) {
          const ext = path.extname(entry.name).toLowerCase();
          if (extensions.includes(ext)) {
            results[full] = this.loadFile(full);
          }
        }
      }
    };

    walk(absDir);
    this.emit("directory:loaded", { path: absDir, files: Object.keys(results) });
    return results;
  }

  // ── public: watch files for changes (hot-reload) ────────────
  watch(filePath) {
    const absPath = path.resolve(filePath);

    if (this.#watchers.has(absPath)) return this;

    const watcher = fs.watch(absPath, (eventType) => {
      if (eventType !== "change") return;

      this.emit("file:changed", { path: absPath });

      try {
        // re-parse only this file; rebuild full config from all sources
        this.#config = {};
        for (const src of this.#sources.keys()) {
          const ext = path.extname(src).toLowerCase();
          const content = fs.readFileSync(src, "utf-8");
          const parsed = this.#parsers[ext](content);
          this.#deepMerge(this.#config, parsed);
        }
        this.emit("config:reloaded", {
          trigger: absPath,
          config: this.getAll(),
        });
      } catch (err) {
        this.emit("error", new Error(`Hot-reload failed for "${absPath}": ${err.message}`));
      }
    });

    this.#watchers.set(absPath, watcher);
    return this;
  }

  // ── public: stop all watchers ───────────────────────────────
  stopWatching() {
    for (const [p, w] of this.#watchers) {
      w.close();
      this.emit("watch:stopped", { path: p });
    }
    this.#watchers.clear();
    return this;
  }

  // ── public: accessors ───────────────────────────────────────
  get(keyPath, defaultValue = undefined) {
    // "events.retryAttempts" → nested lookup
    const keys = keyPath.split(".");
    let current = this.#config;

    for (const k of keys) {
      if (current == null || typeof current !== "object") return defaultValue;
      current = current[k];
    }
    return current !== undefined ? current : defaultValue;
  }

  getAll() {
    return structuredClone(this.#config);
  }

  has(keyPath) {
    return this.get(keyPath) !== undefined;
  }

  set(keyPath, value) {
    const keys = keyPath.split(".");
    let current = this.#config;

    for (let i = 0; i < keys.length - 1; i++) {
      current[keys[i]] ??= {};
      current = current[keys[i]];
    }
    current[keys[keys.length - 1]] = value;
    this.emit("config:updated", { key: keyPath, value });
    return this;
  }

  // ── private helpers ─────────────────────────────────────────
  #validate(parsed, source) {
    for (const fn of this.#validators) {
      const result = fn(parsed, source);
      if (result !== true) {
        const msg =
          typeof result === "string"
            ? result
            : `Validation failed for "${source}"`;
        const err = new Error(msg);
        this.emit("validation:error", { source, error: err });
        throw err;
      }
    }
    this.emit("validation:passed", { source });
  }

  #deepMerge(target, source) {
    for (const [key, val] of Object.entries(source)) {
      if (
        val &&
        typeof val === "object" &&
        !Array.isArray(val) &&
        target[key] &&
        typeof target[key] === "object"
      ) {
        this.#deepMerge(target[key], val);
      } else {
        target[key] = structuredClone(val);
      }
    }
    return target;
  }
}

module.exports = ConfigParser;
```

