```javascript
// src/EventProcessor.js
const { EventEmitter } = require("node:events");

class EventProcessor extends EventEmitter {
  #rules = [];
  #routes = {};
  #buffer = [];
  #config;
  #stats = { processed: 0, errors: 0, routed: {} };

  constructor(configParser) {
    super();
    this.#config = configParser;

    // react to config changes at runtime
    configParser.on("config:reloaded", ({ config }) => {
      this.#reloadRules(config);
    });
  }

  // ── initialise from current config ──────────────────────────
  initialize() {
    const rules = this.#config.get("rules", []);
    const routes = this.#config.get("routes", {});
    const maxListeners = this.#config.get("events.maxListeners", 50);

    this.setMaxListeners(maxListeners);

    // sort rules by priority (lower = higher priority)
    this.#rules = [...rules].sort((a, b) => a.priority - b.priority);
    this.#routes = routes;

    // register an internal listener for every unique event type
    const eventTypes = new Set(this.#rules.map((r) => r.event));
    for (const type of eventTypes) {
      if (type === "*") continue;               // wildcard handled separately
      this.on(type, (data) => this.#processEvent(type, data));
    }

    this.emit("processor:initialized", {
      ruleCount: this.#rules.length,
      routeCount: Object.keys(this.#routes).length,
      eventTypes: [...eventTypes],
    });

    return this;
  }

  // ── public: ingest an event ─────────────────────────────────
  ingest(eventType, payload) {
    const event = {
      id: this.#generateId(),
      type: eventType,
      payload: { ...payload },
      timestamp: Date.now(),
      metadata: { attempts: 0 },
    };

    const bufferSize = this.#config.get("events.bufferSize", 1000);

    if (this.#buffer.length >= bufferSize) {
      this.emit("buffer:overflow", { dropped: event });
      return null;
    }

    this.#buffer.push(event);
    this.emit("event:received", event);

    // dispatch through EventEmitter
    this.emit(eventType, event);

    return event;
  }

  // ── core pipeline ───────────────────────────────────────────
  #processEvent(eventType, event) {
    try {
      // find matching rules (specific + wildcard)
      const matching = this.#rules.filter(
        (r) => r.event === eventType || r.event === "*"
      );

      if (matching.length === 0) {
        this.emit("event:unmatched", event);
        return;
      }

      for (const rule of matching) {
        // evaluate conditions
        if (!this.#evaluateConditions(rule.conditions, event.payload)) {
          this.emit("rule:skipped", { ruleId: rule.id, eventId: event.id });
          continue;
        }

        // apply transforms
        const transformed = this.#applyTransforms(
          rule.transforms,
          event.payload
        );
        event.payload = transformed;

        // route
        this.#routeEvent(rule.route, event);

        this.emit("event:processed", {
          eventId: event.id,
          ruleId: rule.id,
          route: rule.route,
        });
      }

      this.#stats.processed++;
      this.#removeFromBuffer(event.id);
    } catch (err) {
      this.#stats.errors++;
      this.#handleRetry(event, err);
    }
  }

  // ── condition evaluator ─────────────────────────────────────
  #evaluateConditions(conditions, payload) {
    if (!conditions) return true;            // null = always match

    const { field, operator, value } = conditions;
    const actual = this.#getNestedValue(payload, field);

    switch (operator) {
      case "equals":
        return actual === value;
      case "notEquals":
        return actual !== value;
      case "greaterThan":
        return actual > value;
      case "lessThan":
        return actual < value;
      case "contains":
        return typeof actual === "string" && actual.includes(value);
      case "exists":
        return actual !== undefined && actual !== null;
      case "regex":
        return new RegExp(value).test(String(actual));
      default:
        this.emit("warning", `Unknown operator "${operator}"`);
        return false;
    }
  }

  // ── transform pipeline ──────────────────────────────────────
  #applyTransforms(transforms, payload) {
    let result = { ...payload };

    for (const t of transforms ?? []) {
