  }

  try {
    console.log(
      `[${new Date().toISOString()}] Executing task "${task.name}" (${taskId})`
    );
    task.status = 'running';
    task.lastRunAt = new Date().toISOString();

    // ── Simulate async work ──
    // Replace this block with real task logic
    task.status = 'completed';
    task.runCount = (task.runCount || 0) + 1;

    console.log(`[${new Date().toISOString()}] Task "${task.name}" completed.`);
  } catch (err) {
    task.status = 'failed';
    task.lastError = err.message;
    console.error(`Task "${task.name}" failed:`, err);
  }

  // FIX 16: Handle recurring tasks
  if (task.recurrence && task.recurrence !== 'none') {
    task.status = 'scheduled'; // reset for next run
    scheduleTask(taskId, RECURRENCE_MS[task.recurrence]);
  }
}

// ── Schedule / clear helpers ──────────────────────────────
function scheduleTask(taskId, delayMs) {
  // FIX 8: Store timer reference so it can be cleared later
  const timer = setTimeout(() => {
    timers.delete(taskId);
    executeTask(taskId);
  }, delayMs);

  timers.set(taskId, timer);
}

function clearScheduledTimer(taskId) {
  // FIX 13: Properly clear any pending timer
  if (timers.has(taskId)) {
    clearTimeout(timers.get(taskId));
    timers.delete(taskId);
  }
}

// ══════════════════════════════════════════════════════════
//  ROUTES
// ══════════════════════════════════════════════════════════

// ── CREATE task ───────────────────────────────────────────
app.post('/tasks', (req, res, next) => {
  try {
    // FIX 2: Full input validation
    const errors = validateTaskInput(req.body);
    if (errors.length > 0) {
      return res.status(400).json({ errors });
    }

    const { name, scheduledTime, recurrence = 'none' } = req.body;

    // FIX 3: Use crypto.randomUUID for collision-free IDs
    const id = randomUUID();

    // FIX 4: Parse date correctly
    const runAt = new Date(scheduledTime);

    // FIX 5: Consistent ISO date format everywhere
    const task = {
      id,
      name: name.trim(),
      scheduledTime: runAt.toISOString(),
      recurrence,
      status: 'scheduled',
      runCount: 0,
      createdAt: new Date().toISOString(),
      lastRunAt: null,
      lastError: null,
    };

    tasks.set(id, task);

    // FIX 6 & 7: Correct delay calculation + reject past dates
    const delay = runAt.getTime() - Date.now();

    if (delay < 0) {
      tasks.delete(id);
      return res.status(400).json({
        error: 'scheduledTime must be in the future.',
      });
    }

    scheduleTask(id, delay);

    // FIX 9: Send 201 Created with Location header
    res.status(201).json({ task });
  } catch (err) {
    next(err);
  }
});

// ── GET single task ──────────────────────────────────────
// FIX 10: Use GET (not POST) for retrieval
app.get('/tasks/:id', (req, res) => {
  const task = tasks.get(req.params.id);

  // FIX 11: Return 404 when task does not exist
  if (!task) {
    return res.status(404).json({ error: 'Task not found.' });
  }

  res.json({ task });
});

// ── LIST all tasks (with optional status filter) ─────────
app.get('/tasks', (req, res) => {
  // FIX 12: Return an array; support ?status= filtering
  let result = Array.from(tasks.values());

  const { status } = req.query;
  if (status) {
    result = result.filter((t) => t.status === status);
  }

  res.json({ count: result.length, tasks: result });
});

// ── UPDATE (reschedule) a task ───────────────────────────
app.put('/tasks/:id', (req, res, next) => {
  try {
    const task = tasks.get(req.params.id);
    if (!task) {
      return res.status(404).json({ error: 'Task not found.' });
    }

    const errors = validateTaskInput({ ...task, ...req.body });
    if (errors.length > 0) {
      return res.status(400).json({ errors });
    }

    const { name, scheduledTime, recurrence } = req.body;

    // Clear old timer before rescheduling
    clearScheduledTimer(task.id);

    if (name) task.name = name.trim();
    if (recurrence) task.recurrence = recurrence;

    if (scheduledTime) {
      const runAt = new Date(scheduledTime);
      const delay = runAt.getTime() - Date.now();

      if (delay < 0) {
        return res.status(400).json({
          error: 'scheduledTime must be in the future.',
        });
      }

      task.scheduledTime = runAt.toISOString();
      task.status = 'scheduled';
      scheduleTask(task.id, delay);
    }

    res.json({ task });
  } catch (err) {
    next(err);
  }
});

// ── DELETE a task ────────────────────────────────────────
app.delete('/tasks/:id', (req, res) => {
  const { id } = req.params;

  // FIX 14: Check existence before deleting
  if (!tasks.has(id)) {
    return res.status(404).json({ error: 'Task not found.' });
  }

  clearScheduledTimer(id);  // FIX 13: Clear timer
  tasks.delete(id);

  res.status(204).end();    // 204 No Content
});

// ══════════════════════════════════════════════════════════
//  ERROR HANDLING & STARTUP
// ══════════════════════════════════════════════════════════

// FIX 17: Global error-handling middleware
app.use((err, _req, res, _next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal server error.' });
});

// FIX 18: Use environment variable with fallback
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Task Scheduler API running on http://localhost:${PORT}`);
});

module.exports = app; // for testing
```

