# Background Worker for Event Processing in Rust

Here's a comprehensive example using `tokio` for async runtime with channels, graceful shutdown, and multiple event types:

```rust
// Cargo.toml dependencies:
// [dependencies]
// tokio = { version = "1", features = ["full"] }
// tracing = "0.1"
// tracing-subscriber = "0.3"

use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;

use tokio::sync::{mpsc, oneshot, Mutex};
use tokio::task::JoinHandle;
use tracing::{error, info, warn};

// ──────────────────────────────────────────────
// 1. Define event types
// ──────────────────────────────────────────────

#[derive(Debug, Clone)]
enum Event {
    UserSignedUp { user_id: u64, email: String },
    OrderPlaced { order_id: u64, user_id: u64, amount: f64 },
    PaymentReceived { order_id: u64, amount: f64 },
    NotificationRequested { user_id: u64, message: String },
    Custom { kind: String, payload: String },
}

impl Event {
    /// Returns a label for logging / metrics
    fn kind(&self) -> &str {
        match self {
            Event::UserSignedUp { .. } => "user_signed_up",
            Event::OrderPlaced { .. } => "order_placed",
            Event::PaymentReceived { .. } => "payment_received",
            Event::NotificationRequested { .. } => "notification_requested",
            Event::Custom { kind, .. } => kind.as_str(),
        }
    }
}

// ──────────────────────────────────────────────
// 2. Processing result & handler trait
// ──────────────────────────────────────────────

#[derive(Debug)]
enum ProcessingResult {
    Success,
    Retry { reason: String },
    Failure { error: String },
}

/// Any event handler implements this trait.
#[async_trait::async_trait]
trait EventHandler: Send + Sync {
    async fn handle(&self, event: &Event) -> ProcessingResult;
}

// We avoid the async_trait crate by using a simpler function-pointer
// approach below, but let's keep it manual for clarity.

// ──────────────────────────────────────────────
// 3. Concrete handlers
// ──────────────────────────────────────────────

struct UserSignupHandler;
struct OrderHandler;
struct NotificationHandler;

impl UserSignupHandler {
    async fn handle(&self, event: &Event) -> ProcessingResult {
        if let Event::UserSignedUp { user_id, email } = event {
            // Simulate work (e.g., send welcome email, create profile)
            tokio::time::sleep(Duration::from_millis(50)).await;
            info!(user_id, %email, "Processed user signup");
            ProcessingResult::Success
        } else {
            ProcessingResult::Success // not our concern
        }
    }
}

impl OrderHandler {
    async fn handle(&self, event: &Event) -> ProcessingResult {
        match event {
            Event::OrderPlaced { order_id, user_id, amount } => {
                tokio::time::sleep(Duration::from_millis(100)).await;
                info!(order_id, user_id, amount, "Processed new order");
                ProcessingResult::Success
            }
            Event::PaymentReceived { order_id, amount } => {
                tokio::time::sleep(Duration::from_millis(80)).await;
                info!(order_id, amount, "Payment recorded");
                ProcessingResult::Success
            }
            _ => ProcessingResult::Success,
        }
    }
}

impl NotificationHandler {
    async fn handle(&self, event: &Event) -> ProcessingResult {
        if let Event::NotificationRequested { user_id, message } = event {
            // Simulate occasional transient failure
            if message.contains("fail") {
                return ProcessingResult::Retry {
                    reason: "Notification service unavailable".into(),
                };
            }
            tokio::time::sleep(Duration::from_millis(30)).await;
            info!(user_id, %message, "Notification sent");
            ProcessingResult::Success
        } else {
            ProcessingResult::Success
        }
    }
}

// ──────────────────────────────────────────────
// 4. Worker configuration
// ──────────────────────────────────────────────

#[derive(Clone)]
struct WorkerConfig {
    /// How many events to buffer in the channel
    channel_capacity: usize,
    /// Max retries before dropping an event
    max_retries: u32,
    /// Delay between retries
    retry_delay: Duration,
    /// Number of concurrent worker tasks
    concurrency: usize,
}

impl Default for WorkerConfig {
    fn default() -> Self {
        Self {
            channel_capacity: 1024,
            max_retries: 3,
            retry_delay: Duration::from_secs(1),
            concurrency: 4,
        }
    }
}

// ──────────────────────────────────────────────
// 5. Metrics (simple atomic counters)
// ──────────────────────────────────────────────

#[derive(Debug, Default)]
struct Metrics {
    processed: std::sync::atomic::AtomicU64,
    retried: std::sync::atomic::AtomicU64,
    failed: std::sync::atomic::AtomicU64,
}

impl Metrics {
    fn inc_processed(&self) {
        self.processed
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }
    fn inc_retried(&self) {
        self.retried
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }
    fn inc_failed(&self) {
        self.failed
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }
    fn snapshot(&self) -> (u64, u64, u64) {
        (
            self.processed.load(std::sync::atomic::Ordering::Relaxed),
            self.retried.load(std::sync::atomic::Ordering::Relaxed),
            self.failed.load(std::sync::atomic::Ordering::Relaxed),
        )
    }
}

// ──────────────────────────────────────────────
// 6. The background worker
// ──────────────────────────────────────────────

struct BackgroundWorker {
    config: WorkerConfig,
    sender: mpsc::Sender<Event>,
    /// Used to signal all worker tasks to stop
    shutdown_tx: Option<oneshot::Sender<()>>,
    /// Handles to spawned tasks so we can await them
    task_handles: Vec<JoinHandle<()>>,
    metrics: Arc<Metrics>,
}

impl BackgroundWorker {
    /// Create a new worker and spawn `concurrency` processing tasks.
    fn new(config: WorkerConfig) -> Self {
        let (sender, receiver) = mpsc::channel::<Event>(config.channel_capacity);
        let (shutdown_tx, shutdown_rx) = oneshot::channel::<()>();
        let metrics = Arc::new(Metrics::default());

        // Wrap receiver in Arc<Mutex<>> so multiple tasks can pull from it
        let receiver = Arc::new(Mutex::new(receiver));
        // Wrap shutdown_rx so every task can listen to it
        let shutdown = Arc::new(Mutex::new(Some(shutdown_rx)));

        let mut task_handles = Vec::with_capacity(config.concurrency);

        // We use a broadcast-like approach: one shared tokio::sync::Notify
        let notify_shutdown = Arc::new(tokio::sync::Notify::new());

        // Spawn a task that converts the oneshot into a notify
        {
            let notify = notify_shutdown.clone();
            let shutdown_lock = shutdown.clone();
            tokio::spawn(async move {
                if let Some(rx) = shutdown_lock.lock().await.take() {
                    let _ = rx.await;
                }
                notify.notify_waiters();
            });
        }

        for worker_id in 0..config.concurrency {
            let rx = receiver.clone();
            let cfg = config.clone();
            let m = metrics.clone();
            let notify = notify_shutdown.clone();

            let handle = tokio::spawn(async move {
                info!(worker_id, "Worker task started");

                loop {
                    // Try to receive the next event, or check for shutdown
                    let event = {
                        let recv_fut = async {
                            // Lock, recv, release quickly
                            let mut guard = rx.lock().await;
                            guard.recv().await
                        };

                        tokio::select! {
                            ev = recv_fut => ev,
                            _ = notify.notified() => {
                                info!(worker_id, "Shutdown signal received");
                                // Drain remaining events
                                while let Ok(ev) = rx.lock().await.try_recv() {
                                    Self::process_event(worker_id, &ev, &cfg, &m).await;
                                }
                                break;
                            }
                        }
                    };

                    match event {
                        Some(ev) => {
                            Self::process_event(worker_id, &ev, &cfg, &m).await;
                        }
                        None => {
                            info!(worker_id, "Channel closed, worker exiting");
                            break;
                        }
                    }
                }

                info!(worker_id, "Worker task finished");
            });

            task_handles.push(handle);
        }

        Self {
            config,
            sender,
            shutdown_tx: Some(shutdown_tx),
            task_handles,
            metrics,
        }
    }

    /// Route an event through handlers with retry logic.
    async fn process_event(
        worker_id: usize,
        event: &Event,
        config: &WorkerConfig,
        metrics: &Arc<Metrics>,
    ) {
        let kind = event.kind();
        info!(worker_id, kind, "Processing event");

        // Pick the right handler(s) — in production you'd use a registry
        let result = match event {
            Event::UserSignedUp { .. } => UserSignupHandler.handle(event).await,
            Event::OrderPlaced { .. } | Event::PaymentReceived { .. } => {
                OrderHandler.handle(event).await
            }
            Event::NotificationRequested { .. } => {
                NotificationHandler.handle(event).await
            }
            Event::Custom { .. } => {
                info!(worker_id, kind, "No handler registered, skipping");
                ProcessingResult::Success
            }
        };

        match result {
            ProcessingResult::Success => {
                metrics.inc_processed();
            }
            ProcessingResult::Retry { reason } => {
                warn!(worker_id, kind, %reason, "Event needs retry");
                // Simple inline retry loop
                let mut attempts = 0u32;
                loop {
                    attempts += 1;
                    if attempts > config.max_retries {
                        error!(worker_id, kind, attempts, "Max retries exceeded");
                        metrics.inc_failed();
                        break;
                    }
                    metrics.inc_retried();
                    tokio::time::sleep(config.retry_delay).await;
                    info!(worker_id, kind, attempts, "Retrying event");

                    let retry_result = match event {
                        Event::NotificationRequested { .. } => {
                            NotificationHandler.handle(event).await
                        }
                        _ => ProcessingResult::Success,
                    };

                    match retry_result {
                        ProcessingResult::Success => {
                            metrics.inc_processed();
                            break;
                        }
                        ProcessingResult::Retry { .. } => continue,
                        ProcessingResult::Failure { error } => {
                            error!(worker_id, kind, %error, "Permanent failure");
                            metrics.inc_failed();
                            break;
                        }
                    }
                }
            }
            ProcessingResult::Failure { error } => {
                error!(worker_id, kind, %error, "Event processing failed");
                metrics.inc_failed();
            }
        }
    }

    /// Publish an event into the worker queue.
    async fn publish(&self, event: Event) -> Result<(), mpsc::error::SendError<Event>> {
        self.sender.send(event).await
    }

    /// Get a clone of the sender (e.g., to hand out to HTTP handlers).
    fn sender(&self) -> mpsc::Sender<Event> {
        self.sender.clone()
    }

    /// Return a snapshot of metrics.
    fn metrics(&self) -> (u64, u64, u64) {
        self.metrics.snapshot()
    }

    /// Gracefully shut down: signal workers, then await all tasks.
    async fn shutdown(mut self) {
        info!("Initiating graceful shutdown...");

        // Send shutdown signal
        if let Some(tx) = self.shutdown_tx.take() {
            let _ = tx.send(());
        }

        // Drop the sender so the channel eventually closes
        drop(self.sender);

        // Wait for all worker tasks to finish
        for handle in self.task_handles {
            if let Err(e) = handle.await {
                error!("Worker task panicked: {:?}", e);
            }
        }

        let (processed, retried, failed) = self.metrics.snapshot();
        info!(processed, retried, failed, "All workers shut down");
    }
}

// ──────────────────────────────────────────────
// 7. Main — demonstrate usage
// ──────────────────────────────────────────────

#[tokio::main]
async fn main() {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_target(false)
        .with_thread_ids(true)
        .init();

    // Create the worker with default config (4 concurrent tasks)
    let config = WorkerConfig {
        concurrency: 4,
        max_retries: 3,
        retry_delay: Duration::from_millis(200),
        ..Default::default()
    };
    let worker = BackgroundWorker::new(config);

    // Simulate publishing events from different parts of the application
    let tx = worker.sender();

    // Spawn a "producer" task
    let producer = tokio::spawn(async move {
        let events = vec![
            Event::UserSignedUp {
                user_id: 1,
                email: "alice@example.com".into(),
            },
            Event::UserSignedUp {
                user_id: 2,
                email: "bob@example.com".into(),
            },
            Event::OrderPlaced {
                order_id: 101,
                user_id: 1,
                amount: 59.99,
            },
            Event::PaymentReceived {
                order_id: 101,
                amount: 59.99,
            },
            Event::NotificationRequested {
                user_id: 1,
                message: "Your order is confirmed!".into(),
            },
            Event::NotificationRequested {
                user_id: 2,
                message: "fail — trigger retry".into(), // will cause retry
            },
            Event::OrderPlaced {
                order_id: 102,
                user_id: 2,
                amount: 129.50,
            },
            Event::Custom {
                kind: "analytics".into(),
                payload: r#"{"page":"home","duration":3200}"#.into(),
            },
        ];

        for event in events {
            if let Err(e) = tx.send(event).await {
                error!("Failed to publish event: {}", e);
            }
            // Small delay to simulate real traffic
            tokio::time::sleep(Duration::from_millis(20)).await;
        }

        info!("Producer finished publishing all events");
    });

    // Wait for producer to finish
    producer.await.unwrap();

    // Give workers a moment to finish processing
    tokio::time::sleep(Duration::from_secs(2)).await;

    // Print metrics before shutdown
    let (processed, retried, failed) = worker.metrics();
    info!(processed, retried, failed, "Metrics before shutdown");

    // Graceful shutdown
    worker.shutdown().await;
}
