# Simple JavaScript Log Ingestion

## Basic Log Ingestor

```javascript
const fs = require('fs');
const readline = require('readline');

// --- Log Storage ---
class LogStore {
  constructor() {
    this.logs = [];
  }

  add(entry) {
    this.logs.push(entry);
  }

  getAll() {
    return this.logs;
  }

  query(filterFn) {
    return this.logs.filter(filterFn);
  }

  size() {
    return this.logs.length;
  }
}

// --- Log Ingestor ---
class LogIngestor {
  constructor(store) {
    this.store = store;
  }

  /**
   * Parse and validate a single JSON log line
   */
  parseLine(raw) {
    let parsed;

    try {
      parsed = JSON.parse(raw);
    } catch (err) {
      throw new Error(`Invalid JSON: ${err.message}`);
    }

    // Validate required fields
    if (!parsed.level || !parsed.message) {
      throw new Error('Missing required fields: "level" and "message"');
    }

    // Normalize the log entry
    return {
      timestamp: parsed.timestamp || new Date().toISOString(),
      level: parsed.level.toUpperCase(),
      message: parsed.message,
      service: parsed.service || 'unknown',
      metadata: parsed.metadata || {},
      _ingestedAt: new Date().toISOString(),
    };
  }

  /**
   * Ingest a single JSON string
   */
  ingestOne(raw) {
    const entry = this.parseLine(raw);
    this.store.add(entry);
    console.log(`[INGESTED] ${entry.level} - ${entry.message}`);
    return entry;
  }

  /**
   * Ingest an array of JSON objects
   */
  ingestBatch(jsonArray) {
    const results = { success: 0, failed: 0, errors: [] };

    for (const item of jsonArray) {
      try {
        const raw = typeof item === 'string' ? item : JSON.stringify(item);
        this.ingestOne(raw);
        results.success++;
      } catch (err) {
        results.failed++;
        results.errors.push(err.message);
      }
    }

    console.log(`\nBatch complete: ${results.success} ok, ${results.failed} failed`);
    return results;
  }

  /**
   * Ingest from a .json or .jsonl file (one JSON object per line)
   */
  async ingestFile(filePath) {
    const stream = fs.createReadStream(filePath, 'utf-8');
    const rl = readline.createInterface({ input: stream });
    let lineNum = 0;

    for await (const line of rl) {
      lineNum++;
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('//')) continue; // skip blanks/comments

      try {
        this.ingestOne(trimmed);
      } catch (err) {
        console.error(`[ERROR] Line ${lineNum}: ${err.message}`);
      }
    }

    console.log(`\nFile ingestion done. Total stored: ${this.store.size()}`);
  }

  /**
   * Read from stdin (pipe or interactive)
   */
  async ingestStdin() {
    const rl = readline.createInterface({ input: process.stdin });
    console.log('Paste JSON log lines (Ctrl+D to finish):\n');

    for await (const line of rl) {
      const trimmed = line.trim();
      if (!trimmed) continue;

      try {
        this.ingestOne(trimmed);
      } catch (err) {
        console.error(`[ERROR] ${err.message}`);
      }
    }

    console.log(`\nStdin ingestion done. Total stored: ${this.store.size()}`);
  }
}

// --- Main ---
async function main() {
  const store = new LogStore();
  const ingestor = new LogIngestor(store);

  // 1) Ingest single entry
  console.log('=== Single Entry ===');
  ingestor.ingestOne(
    JSON.stringify({
      level: 'info',
      message: 'User logged in',
      service: 'auth-service',
      metadata: { userId: 42 },
    })
  );

  // 2) Ingest a batch
  console.log('\n=== Batch Ingest ===');
  const batch = [
    { level: 'warn', message: 'High memory usage', service: 'api-gateway' },
    { level: 'error', message: 'DB connection lost', service: 'data-service' },
    { level: 'info', message: 'Cache refreshed', service: 'cache-service' },
    { level: 'debug', message: 'Request payload logged', service: 'api-gateway' },
  ];
  ingestor.ingestBatch(batch);

  // 3) Ingest from file (if provided as CLI arg)
  const filePath = process.argv[2];
  if (filePath) {
    console.log(`\n=== File Ingest: ${filePath} ===`);
    await ingestor.ingestFile(filePath);
  }

  // 4) Query examples
  console.log('\n=== Query: ERROR logs ===');
  const errors = store.query((log) => log.level === 'ERROR');
  console.log(errors);

  console.log('\n=== Query: api-gateway logs ===');
  const gatewayLogs = store.query((log) => log.service === 'api-gateway');
  console.log(gatewayLogs);

  console.log(`\n=== Total Logs Stored: ${store.size()} ===`);
}

main().catch(console.error);
