## Key Design Points

| Feature | Detail |
|---|---|
| **Input formats** | Single JSON string, batch array, `.jsonl` file, stdin pipe |
| **Validation** | Requires `level` + `message`; rejects malformed JSON |
| **Normalization** | Auto-adds `timestamp`, uppercases `level`, adds `_ingestedAt` |
| **Querying** | Filter with any predicate function via `store.query()` |
| **Error handling** | Bad lines are logged and skipped — doesn't halt ingestion |
| **No dependencies** | Uses only Node.js built-in modules (`fs`, `readline`) |

# Metrics Aggregation Config Parser in JavaScript

## Full Implementation

```javascript
// ==========================================
// metrics-config-parser.js
// ==========================================

/**
 * Supported aggregation types and their validators
 */
const AggregationType = Object.freeze({
  SUM: 'sum',
  AVG: 'avg',
  MIN: 'min',
  MAX: 'max',
  COUNT: 'count',
  PERCENTILE: 'percentile',
  RATE: 'rate',
  HISTOGRAM: 'histogram',
});

const TimeUnit = Object.freeze({
  SECONDS: 's',
  MINUTES: 'm',
  HOURS: 'h',
  DAYS: 'd',
});

// ==========================================
// Custom Error Classes
// ==========================================

class ConfigParserError extends Error {
  constructor(message, path = null) {
    super(path ? `[${path}] ${message}` : message);
    this.name = 'ConfigParserError';
    this.path = path;
  }
}

class ValidationError extends ConfigParserError {
  constructor(message, path, value) {
    super(message, path);
    this.name = 'ValidationError';
    this.invalidValue = value;
  }
}

// ==========================================
// Schema Validators
// ==========================================

const Validators = {
  isNonEmptyString(value) {
    return typeof value === 'string' && value.trim().length > 0;
  },

  isPositiveNumber(value) {
    return typeof value === 'number' && value > 0 && Number.isFinite(value);
  },

  isPercentile(value) {
    return typeof value === 'number' && value > 0 && value <= 100;
  },

  isDuration(value) {
    if (typeof value === 'number') return value > 0;
    if (typeof value !== 'string') return false;
    return /^\d+[smhd]$/.test(value);
  },

  isAggregationType(value) {
    return Object.values(AggregationType).includes(value);
  },

  isTagMap(value) {
    if (typeof value !== 'object' || value === null || Array.isArray(value)) {
      return false;
    }
    return Object.entries(value).every(
      ([k, v]) => typeof k === 'string' && typeof v === 'string'
    );
  },
};

// ==========================================
// Duration Parser
// ==========================================

class Duration {
  static MULTIPLIERS = {
    [TimeUnit.SECONDS]: 1000,
    [TimeUnit.MINUTES]: 60_000,
    [TimeUnit.HOURS]: 3_600_000,
    [TimeUnit.DAYS]: 86_400_000,
  };

  /**
   * Parse a duration string like "30s", "5m", "1h" into milliseconds
   */
  static toMilliseconds(value) {
    if (typeof value === 'number') return value;

    const match = value.match(/^(\d+)([smhd])$/);
    if (!match) {
      throw new ConfigParserError(`Invalid duration format: "${value}"`);
    }

    const [, amount, unit] = match;
    return parseInt(amount, 10) * Duration.MULTIPLIERS[unit];
  }

  static toString(ms) {
    if (ms >= 86_400_000 && ms % 86_400_000 === 0) return `${ms / 86_400_000}d`;
    if (ms >= 3_600_000 && ms % 3_600_000 === 0) return `${ms / 3_600_000}h`;
    if (ms >= 60_000 && ms % 60_000 === 0) return `${ms / 60_000}m`;
    return `${ms / 1000}s`;
  }
}

// ==========================================
// Metric Definition
// ==========================================

class MetricDefinition {
  constructor({
    name,
    aggregation,
    field = null,
    interval,
    percentiles = null,
    buckets = null,
    tags = {},
    filters = [],
    outputName = null,
  }) {
    this.name = name;
    this.aggregation = aggregation;
    this.field = field;
    this.intervalMs = Duration.toMilliseconds(interval);
    this.interval = interval;
    this.percentiles = percentiles;
    this.buckets = buckets;
    this.tags = { ...tags };
    this.filters = [...filters];
    this.outputName = outputName || `${name}_${aggregation}`;
  }

  toJSON() {
    return {
      name: this.name,
      aggregation: this.aggregation,
      field: this.field,
      interval: this.interval,
      intervalMs: this.intervalMs,
      percentiles: this.percentiles,
      buckets: this.buckets,
      tags: this.tags,
      filters: this.filters,
      outputName: this.outputName,
    };
  }
}

// ==========================================
// Aggregation Pipeline Stage
// ==========================================

class PipelineStage {
  constructor({ type, metrics, input = null, output = null, options = {} }) {
    this.type = type;
    this.metrics = metrics; // Array of MetricDefinition
    this.input = input;
    this.output = output;
    this.options = options;
  }
}

// ==========================================
// Parsed Configuration
// ==========================================

class MetricsConfig {
  constructor() {
    this.global = {
      defaultInterval: '60s',
      defaultTags: {},
      bufferSize: 1000,
      flushInterval: '10s',
      timezone: 'UTC',
    };
    this.sources = new Map();
    this.metrics = new Map();
    this.pipelines = [];
    this.outputs = new Map();
  }

  getMetric(name) {
    return this.metrics.get(name) ?? null;
  }

  getMetricsByAggregation(type) {
    return [...this.metrics.values()].filter((m) => m.aggregation === type);
  }

  getMetricsByTag(key, value = undefined) {
    return [...this.metrics.values()].filter((m) => {
      if (value === undefined) return key in m.tags;
      return m.tags[key] === value;
    });
  }

  toJSON() {
    return {
      global: this.global,
      sources: Object.fromEntries(this.sources),
      metrics: Object.fromEntries(
        [...this.metrics.entries()].map(([k, v]) => [k, v.toJSON()])
      ),
      pipelines: this.pipelines,
      outputs: Object.fromEntries(this.outputs),
    };
  }
}

// ==========================================
// Main Config Parser
// ==========================================

class MetricsConfigParser {
  #warnings = [];

  /**
   * Parse a raw config object into a validated MetricsConfig
   */
  parse(rawConfig) {
    this.#warnings = [];

    if (!rawConfig || typeof rawConfig !== 'object') {
      throw new ConfigParserError('Configuration must be a non-null object');
    }

    const config = new MetricsConfig();

    // Parse sections in dependency order
    this.#parseGlobal(rawConfig.global, config);
    this.#parseSources(rawConfig.sources, config);
    this.#parseMetrics(rawConfig.metrics, config);
    this.#parsePipelines(rawConfig.pipelines, config);
    this.#parseOutputs(rawConfig.outputs, config);

    // Cross-reference validation
    this.#validateReferences(config);

    return {
      config,
      warnings: [...this.#warnings],
    };
  }

  /**
   * Parse from a JSON string
   */
  parseJSON(jsonString) {
    try {
      const raw = JSON.parse(jsonString);
      return this.parse(raw);
    } catch (err) {
      if (err instanceof ConfigParserError) throw err;
      throw new ConfigParserError(`Invalid JSON: ${err.message}`);
    }
  }

  /**
   * Parse a simplified DSL string for quick metric definitions
   * Format: "metric_name:aggregation_type:interval [field=value] [tag:key=value]"
   */
  parseMetricDSL(dslString) {
    const lines = dslString
      .split('\n')
      .map((l) => l.trim())
      .filter((l) => l && !l.startsWith('#'));

    const metrics = [];

    for (const line of lines) {
      const parts = line.split(/\s+/);
      const [definition, ...modifiers] = parts;

      const [name, aggregation, interval] = definition.split(':');
      if (!name || !aggregation) {
        throw new ConfigParserError(`Invalid DSL metric: "${line}"`);
      }

      const metricDef = {
        name,
        aggregation,
        interval: interval || '60s',
        tags: {},
        filters: [],
      };

      // Parse modifiers: field=X, tag:key=value, filter:field=op:value
      for (const mod of modifiers) {
        if (mod.startsWith('tag:')) {
          const [, pair] = mod.split('tag:');
          const [key, value] = pair.split('=');
          metricDef.tags[key] = value;
        } else if (mod.startsWith('field=')) {
          metricDef.field = mod.split('=')[1];
        } else if (mod.startsWith('percentiles=')) {
          metricDef.percentiles = mod.split('=')[1].split(',').map(Number);
        } else if (mod.startsWith('filter:')) {
          const filterExpr = mod.slice(7);
          metricDef.filters.push(this.#parseFilterExpression(filterExpr));
        }
      }

      metrics.push(metricDef);
    }

    return metrics.map((m) => this.#buildMetricDefinition(m, {}));
  }

  // ---- Private parsing methods ----

  #parseGlobal(raw, config) {
    if (!raw) return; // Use defaults

    const section = config.global;

    if (raw.default_interval !== undefined) {
      this.#validateField(raw.default_interval, Validators.isDuration, 'global.default_interval');
      section.defaultInterval = raw.default_interval;
    }

    if (raw.default_tags !== undefined) {
      this.#validateField(raw.default_tags, Validators.isTagMap, 'global.default_tags');
      section.defaultTags = { ...raw.default_tags };
    }

    if (raw.buffer_size !== undefined) {
      this.#validateField(raw.buffer_size, Validators.isPositiveNumber, 'global.buffer_size');
      section.bufferSize = raw.buffer_size;
    }

    if (raw.flush_interval !== undefined) {
      this.#validateField(raw.flush_interval, Validators.isDuration, 'global.flush_interval');
      section.flushInterval = raw.flush_interval;
    }

    if (raw.timezone !== undefined) {
      section.timezone = raw.timezone;
    }
  }

  #parseSources(raw, config) {
    if (!raw) return;

    if (typeof raw !== 'object' || Array.isArray(raw)) {
      throw new ConfigParserError('sources must be an object', 'sources');
    }

    for (const [name, sourceDef] of Object.entries(raw)) {
      this.#validateField(name, Validators.isNonEmptyString, `sources.${name}`);

      const source = {
        type: sourceDef.type,
        connection: sourceDef.connection || {},
        options: sourceDef.options || {},
      };

      if (!source.type) {
        throw new ValidationError('Source must have a type', `sources.${name}.type`, undefined);
      }

      config.sources.set(name, source);
    }
  }

  #parseMetrics(raw, config) {
    if (!raw) {
      this.#warnings.push('No metrics defined in configuration');
      return;
    }

    if (typeof raw !== 'object' || Array.isArray(raw)) {
      throw new ConfigParserError('metrics must be an object', 'metrics');
    }

    for (const [name, metricRaw] of Object.entries(raw)) {
      const path = `metrics.${name}`;

      // Support shorthand: "metric_name": "sum"
      const metricDef =
        typeof metricRaw === 'string' ? { aggregation: metricRaw } : { ...metricRaw };

      metricDef.name = name;
      const definition = this.#buildMetricDefinition(metricDef, config.global);
      config.metrics.set(name, definition);
    }
  }

  #buildMetricDefinition(metricDef, globalDefaults) {
    const path = `metrics.${metricDef.name}`;

    // Validate aggregation type
    if (!metricDef.aggregation) {
      throw new ValidationError('Metric must specify an aggregation type', path, undefined);
    }
    this.#validateField(
      metricDef.aggregation,
      Validators.isAggregationType,
      `${path}.aggregation`
    );

    // Merge interval with global default
    const interval = metricDef.interval || globalDefaults.defaultInterval || '60s';
    this.#validateField(interval, Validators.isDuration, `${path}.interval`);

    // Merge tags with global defaults
    const tags = {
      ...(globalDefaults.defaultTags || {}),
      ...(metricDef.tags || {}),
    };

    // Aggregation-specific validation
    this.#validateAggregationOptions(metricDef, path);

    // Parse filters
    const filters = (metricDef.filters || []).map((f, i) =>
      typeof f === 'string' ? this.#parseFilterExpression(f) : this.#validateFilter(f, `${path}.filters[${i}]`)
    );

    return new MetricDefinition({
      name: metricDef.name,
      aggregation: metricDef.aggregation,
      field: metricDef.field || null,
      interval,
      percentiles: metricDef.percentiles || null,
      buckets: metricDef.buckets || null,
      tags,
      filters,
      outputName: metricDef.output_name || null,
    });
  }

  #validateAggregationOptions(metricDef, path) {
    const { aggregation } = metricDef;

    // Field-required aggregations
    const fieldRequired = [
      AggregationType.SUM,
      AggregationType.AVG,
      AggregationType.MIN,
      AggregationType.MAX,
      AggregationType.PERCENTILE,
      AggregationType.HISTOGRAM,
    ];

    if (fieldRequired.includes(aggregation) && !metricDef.field) {
      throw new ValidationError(
        `Aggregation "${aggregation}" requires a "field" property`,
        `${path}.field`,
        undefined
      );
    }

    // Percentile-specific
    if (aggregation === AggregationType.PERCENTILE) {
      if (!metricDef.percentiles || !Array.isArray(metricDef.percentiles)) {
        throw new ValidationError(
          'Percentile aggregation requires a "percentiles" array',
          `${path}.percentiles`,
          metricDef.percentiles
        );
      }
      for (const p of metricDef.percentiles) {
        if (!Validators.isPercentile(p)) {
          throw new ValidationError(
            `Percentile values must be between 0 and 100, got ${p}`,
            `${path}.percentiles`,
            p
          );
        }
      }
    }

    // Histogram-specific
    if (aggregation === AggregationType.HISTOGRAM) {
      if (!metricDef.buckets || !Array.isArray(metricDef.buckets)) {
        throw new ValidationError(
          'Histogram aggregation requires a "buckets" array',
          `${path}.buckets`,
          metricDef.buckets
        );
      }
      const sorted = [...metricDef.buckets].sort((a, b) => a - b);
      if (JSON.stringify(sorted) !== JSON.stringify(metricDef.buckets)) {
        this.#warnings.push(`${path}.buckets: Bucket boundaries should be sorted ascending`);
        metricDef.buckets = sorted;
      }
    }
  }

  #parsePipelines(raw, config) {
    if (!raw) return;
    if (!Array.isArray(raw)) {
      throw new ConfigParserError('pipelines must be an array', 'pipelines');
    }

    for (let i = 0; i < raw.length; i++) {
      const stageDef = raw[i];
      const path = `pipelines[${i}]`;

      if (!stageDef.type) {
        throw new ValidationError('Pipeline stage must have a type', path, undefined);
      }

      const metricNames = stageDef.metrics || [];
      const resolvedMetrics = metricNames.map((name) => {
        // Allow glob patterns
        if (name.includes('*')) {
          return { pattern: name, resolved: [] }; // Resolved later
        }
