      });

      config.pipelines.push(
        new PipelineStage({
          type: stageDef.type,
          metrics: resolvedMetrics,
          input: stageDef.input || null,
          output: stageDef.output || null,
          options: stageDef.options || {},
        })
      );
    }
  }

  #parseOutputs(raw, config) {
    if (!raw) return;

    if (typeof raw !== 'object' || Array.isArray(raw)) {
      throw new ConfigParserError('outputs must be an object', 'outputs');
    }

    for (const [name, outputDef] of Object.entries(raw)) {
      if (!outputDef.type) {
        throw new ValidationError(
          'Output must have a type',
          `outputs.${name}.type`,
          undefined
        );
      }

      config.outputs.set(name, {
        type: outputDef.type,
        connection: outputDef.connection || {},
        format: outputDef.format || 'json',
        batchSize: outputDef.batch_size || 100,
        options: outputDef.options || {},
