```rust
use crate::models::{ChatMessage, Severity, Violation};
use dashmap::DashMap;
use regex::Regex;
use std::collections::VecDeque;
use std::sync::Arc;
use std::time::{Duration, Instant};

// --- Rule trait ---

pub trait ModerationRule: Send + Sync {
    fn name(&self) -> &str;
    fn check(&self, message: &ChatMessage) -> Option<Violation>;
}

// --- Profanity filter ---

pub struct ProfanityFilter {
    patterns: Vec<Regex>,
}

impl ProfanityFilter {
    pub fn new(words: &[&str]) -> Self {
        let patterns = words
            .iter()
            .map(|w| {
                // Match word boundaries, case-insensitive, handle leet speak basics
                let escaped = regex::escape(w);
                Regex::new(&format!(r"(?i)\b{}\b", escaped)).unwrap()
            })
            .collect();
        Self { patterns }
    }
}

impl ModerationRule for ProfanityFilter {
    fn name(&self) -> &str {
        "profanity_filter"
    }

    fn check(&self, message: &ChatMessage) -> Option<Violation> {
        let matched: Vec<String> = self
            .patterns
            .iter()
            .filter(|p| p.is_match(&message.content))
            .map(|p| p.as_str().to_string())
            .collect();

        if matched.is_empty() {
            return None;
        }

        Some(Violation {
            rule: self.name().into(),
            reason: format!("Matched {} profanity pattern(s)", matched.len()),
            severity: if matched.len() > 2 {
                Severity::High
            } else {
                Severity::Medium
            },
        })
    }
}

// --- Spam / rate limiter ---

pub struct RateLimiter {
    /// user_id -> timestamps of recent messages
    windows: Arc<DashMap<String, VecDeque<Instant>>>,
    max_messages: usize,
    window_duration: Duration,
}

impl RateLimiter {
    pub fn new(max_messages: usize, window_secs: u64) -> Self {
        Self {
            windows: Arc::new(DashMap::new()),
            max_messages,
            window_duration: Duration::from_secs(window_secs),
        }
    }
}

impl ModerationRule for RateLimiter {
    fn name(&self) -> &str {
        "rate_limiter"
    }

    fn check(&self, message: &ChatMessage) -> Option<Violation> {
        let now = Instant::now();
        let mut entry = self
            .windows
            .entry(message.user_id.clone())
            .or_insert_with(VecDeque::new);

        let timestamps = entry.value_mut();

        // Evict old entries
        while timestamps
            .front()
            .is_some_and(|t| now.duration_since(*t) > self.window_duration)
        {
            timestamps.pop_front();
        }

        timestamps.push_back(now);

        if timestamps.len() > self.max_messages {
            Some(Violation {
                rule: self.name().into(),
                reason: format!(
                    "User sent {} messages in {} seconds (limit: {})",
                    timestamps.len(),
                    self.window_duration.as_secs(),
                    self.max_messages
                ),
                severity: Severity::High,
            })
        } else {
            None
        }
    }
}

// --- Link spam detector ---

pub struct LinkDetector {
    max_links: usize,
    url_regex: Regex,
}

impl LinkDetector {
    pub fn new(max_links: usize) -> Self {
        Self {
            max_links,
            url_regex: Regex::new(
                r"https?://[^\s<>\"']+|www\.[^\s<>\"']+"
            ).unwrap(),
        }
    }
}

impl ModerationRule for LinkDetector {
    fn name(&self) -> &str {
        "link_detector"
    }

    fn check(&self, message: &ChatMessage) -> Option<Violation> {
        let count = self.url_regex.find_iter(&message.content).count();

        if count > self.max_links {
            Some(Violation {
                rule: self.name().into(),
                reason: format!("Message contains {} links (max: {})", count, self.max_links),
                severity: Severity::Medium,
            })
        } else {
            None
        }
    }
}

// --- Caps lock / shouting detector ---

pub struct CapsDetector {
    threshold: f64, // fraction of uppercase chars that triggers
    min_length: usize,
}

impl CapsDetector {
    pub fn new(threshold: f64, min_length: usize) -> Self {
        Self {
            threshold,
            min_length,
        }
    }
}

impl ModerationRule for CapsDetector {
    fn name(&self) -> &str {
        "caps_detector"
    }

    fn check(&self, message: &ChatMessage) -> Option<Violation> {
        let alpha_chars: Vec<char> = message.content.chars().filter(|c| c.is_alphabetic()).collect();

        if alpha_chars.len() < self.min_length {
            return None;
        }

        let uppercase_count = alpha_chars.iter().filter(|c| c.is_uppercase()).count();
        let ratio = uppercase_count as f64 / alpha_chars.len() as f64;

        if ratio > self.threshold {
            Some(Violation {
                rule: self.name().into(),
                reason: format!("Message is {:.0}% uppercase", ratio * 100.0),
                severity: Severity::Low,
            })
        } else {
            None
        }
    }
}
