```rust
use crate::models::*;
use crate::rules::ModerationRule;
use chrono::Utc;
use tracing::{info, warn};

pub struct Moderator {
    rules: Vec<Box<dyn ModerationRule>>,
}

impl Moderator {
    pub fn new(rules: Vec<Box<dyn ModerationRule>>) -> Self {
        info!("Moderator initialized with {} rules", rules.len());
        Self { rules }
    }

    pub fn evaluate(&self, message: &ChatMessage) -> ModerationResult {
        let violations: Vec<Violation> = self
            .rules
            .iter()
            .filter_map(|rule| rule.check(message))
            .collect();

        let verdict = Self::decide(&violations);

        if !violations.is_empty() {
            warn!(
                message_id = %message.id,
                user_id = %message.user_id,
                violation_count = violations.len(),
                verdict = ?verdict,
                "Message flagged"
            );
        }

        ModerationResult {
            message_id: message.id.clone(),
            user_id: message.user_id.clone(),
            verdict,
            violations,
            processed_at: Utc::now(),
        }
    }

    fn decide(violations: &[Violation]) -> Verdict {
        if violations.is_empty() {
            return Verdict::Approve;
        }

        let max_severity = violations
            .iter()
            .map(|v| v.severity)
            .max()
            .unwrap_or(Severity::Low);

        match max_severity {
            Severity::Critical => Verdict::MuteUser {
                duration_secs: 3600,
            },
            Severity::High => Verdict::Reject,
            Severity::Medium => Verdict::Flag,
            Severity::Low => Verdict::Approve, // low severity passes through
        }
    }
}
