use crate::models::{ChatMessage, ModerationResult, Verdict};
use crate::moderator::Moderator;
use lapin::{
    options::*, types::FieldTable, BasicProperties, Channel, Connection, ConnectionProperties,
    Consumer,
};
use std::sync::Arc;
use thiserror::Error;
use tokio_stream::StreamExt;
use tracing::{error, info, instrument};

#[derive(Error, Debug)]
pub enum ConsumerError {
    #[error("RabbitMQ error: {0}")]
    Lapin(#[from] lapin::Error),
    #[error("JSON error: {0}")]
    Json(#[from] serde_json::Error),
}

pub struct ModerationConsumer {
    channel: Channel,
    moderator: Arc<Moderator>,
    input_queue: String,
    results_exchange: String,
}

impl ModerationConsumer {
    pub async fn connect(
        amqp_url: &str,
        input_queue: &str,
        results_exchange: &str,
        moderator: Moderator,
    ) -> Result<Self, ConsumerError> {
        let conn = Connection::connect(amqp_url, ConnectionProperties::default()).await?;
        let channel = conn.create_channel().await?;

        // Declare input queue
        channel
            .queue_declare(
                input_queue,
                QueueDeclareOptions {
                    durable: true,
                    ..Default::default()
                },
                FieldTable::default(),
            )
            .await?;

        // Declare results exchange (fanout so multiple services can listen)
        channel
            .exchange_declare(
                results_exchange,
                lapin::ExchangeKind::Fanout,
                ExchangeDeclareOptions {
                    durable: true,
                    ..Default::default()
                },
                FieldTable::default(),
            )
            .await?;

        // Prefetch 10 messages at a time
        channel.basic_qos(10, BasicQosOptions::default()).await?;

        info!(queue = input_queue, "Connected to RabbitMQ");

        Ok(Self {
            channel,
            moderator: Arc::new(moderator),
            input_queue: input_queue.to_string(),
            results_exchange: results_exchange.to_string(),
        })
    }

    pub async fn run(&self) -> Result<(), ConsumerError> {
        let mut consumer: Consumer = self
            .channel
            .basic_consume(
                &self.input_queue,
                "chat-moderator",
                BasicConsumeOptions::default(),
                FieldTable::default(),
            )
            .await?;

        info!("Consuming from '{}'...", self.input_queue);

        while let Some(delivery_result) = consumer.next().await {
            match delivery_result {
                Ok(delivery) => {
                    let tag = delivery.delivery_tag;

                    match self.handle_delivery(&delivery.data).await {
                        Ok(_) => {
                            delivery.ack(BasicAckOptions::default()).await?;
                        }
                        Err(e) => {
                            error!(error = %e, "Failed to process message");
                            // Requeue on failure
                            delivery
                                .nack(BasicNackOptions {
                                    requeue: true,
                                    ..Default::default()
                                })
                                .await?;
                        }
                    }
                }
                Err(e) => {
                    error!(error = %e, "Consumer stream error");
                }
            }
        }

        Ok(())
    }

    #[instrument(skip(self, data), fields(message_id))]
    async fn handle_delivery(&self, data: &[u8]) -> Result<(), ConsumerError> {
        let message: ChatMessage = serde_json::from_slice(data)?;
        tracing::Span::current().record("message_id", &message.id.as_str());

        let result = self.moderator.evaluate(&message);

        // Publish moderation result
        self.publish_result(&result).await?;

        // Execute side effects based on verdict
        self.execute_verdict(&result).await;

        info!(
            verdict = ?result.verdict,
            violations = result.violations.len(),
            "Processed"
        );

        Ok(())
    }

    async fn publish_result(&self, result: &ModerationResult) -> Result<(), ConsumerError> {
        let payload = serde_json::to_vec(result)?;

        self.channel
            .basic_publish(
                &self.results_exchange,
                "", // fanout ignores routing key
                BasicPublishOptions::default(),
                &payload,
                BasicProperties::default()
                    .with_content_type("application/json".into())
                    .with_delivery_mode(2), // persistent
            )
            .await?
            .await?; // wait for confirm

        Ok(())
    }

    async fn execute_verdict(&self, result: &ModerationResult) {
        match &result.verdict {
            Verdict::Approve => {}
            Verdict::Flag => {
                info!(
                    user_id = %result.user_id,
                    message_id = %result.message_id,
                    "Message queued for human review"
                );
                // In production: insert into review DB, notify moderators
            }
            Verdict::Reject => {
                info!(
                    user_id = %result.user_id,
                    message_id = %result.message_id,
                    "Message rejected"
                );
                // In production: call chat API to delete message, notify user
            }
            Verdict::MuteUser { duration_secs } => {
                info!(
                    user_id = %result.user_id,
                    duration_secs,
                    "User muted"
                );
                // In production: call user service to apply mute
            }
        }
    }
}
