        &amqp_url,
        "chat.messages.pending",
        "chat.moderation.results",
        moderator,
    )
    .await?;

    // Run until killed — handles SIGTERM gracefully via tokio
    tokio::select! {
        result = consumer.run() => {
            if let Err(e) = result {
                tracing::error!(error = %e, "Consumer stopped with error");
            }
        }
        _ = tokio::signal::ctrl_c() => {
            tracing::info!("Shutting down...");
        }
    }

    Ok(())
}

fn build_moderator() -> Moderator {
    let rules: Vec<Box<dyn ModerationRule>> = vec![
        Box::new(ProfanityFilter::new(&[
            "badword1", "badword2", "slur1", // load from config in production
        ])),
        Box::new(RateLimiter::new(5, 10)),       // 5 msgs per 10 seconds
        Box::new(LinkDetector::new(2)),           // max 2 links per message
        Box::new(CapsDetector::new(0.7, 10)),     // 70% caps in 10+ char messages
    ];

    Moderator::new(rules)
}
