```go
package configloader

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

var (
	ErrSourceUnavailable  = errors.New("configuration source unavailable")
	ErrValidationFailed   = errors.New("configuration validation failed")
	ErrRetriesExhausted   = errors.New("all retry attempts exhausted")
	ErrLoadCancelled      = errors.New("configuration load cancelled")
	ErrNoSources          = errors.New("no configuration sources provided")
	ErrPartialLoad        = errors.New("partial configuration loaded")
	ErrSourceNotFound     = errors.New("configuration source not found")
	ErrInvalidRetryConfig = errors.New("invalid retry configuration")
)

// RetryError wraps errors from individual retry attempts.
type RetryError struct {
	Attempts []AttemptError
	Final    error
}

type AttemptError struct {
	Attempt  int
	Err      error
	Duration time.Duration
	At       time.Time
}

func (e *RetryError) Error() string {
	var b strings.Builder
	fmt.Fprintf(&b, "config load failed after %d attempts: %v", len(e.Attempts), e.Final)
	for _, a := range e.Attempts {
		fmt.Fprintf(&b, "\n  attempt %d at %s (took %s): %v",
			a.Attempt, a.At.Format(time.RFC3339), a.Duration, a.Err)
	}
	return b.String()
}

func (e *RetryError) Unwrap() error {
	return e.Final
}

// ValidationError provides detailed field-level validation errors.
type ValidationError struct {
	Fields []FieldError
}

type FieldError struct {
	Field   string
	Value   any
	Message string
}

func (e *ValidationError) Error() string {
	var b strings.Builder
	b.WriteString("validation failed:")
	for _, f := range e.Fields {
		fmt.Fprintf(&b, "\n  field %q (value: %v): %s", f.Field, f.Value, f.Message)
	}
	return b.String()
}

func (e *ValidationError) Unwrap() error {
	return ErrValidationFailed
}

// SourceError wraps an error from a specific source.
type SourceError struct {
	SourceName string
	Err        error
}

func (e *SourceError) Error() string {
	return fmt.Sprintf("source %q: %v", e.SourceName, e.Err)
}

func (e *SourceError) Unwrap() error {
	return e.Err
}
