```go
package configloader

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// Source defines a configuration data provider.
type Source interface {
	// Name returns a human-readable source identifier.
	Name() string
	// Load retrieves configuration data. Returns raw key-value pairs.
	Load(ctx context.Context) (map[string]any, error)
	// Priority returns the source priority (higher = overrides lower).
	Priority() int
}

// Validator validates a fully-merged configuration.
type Validator interface {
	Validate(cfg map[string]any) error
}

// ValidatorFunc adapts a function into a Validator.
type ValidatorFunc func(map[string]any) error

func (f ValidatorFunc) Validate(cfg map[string]any) error {
	return f(cfg)
}

// Logger abstracts structured logging.
type Logger interface {
	Debug(msg string, keysAndValues ...any)
	Info(msg string, keysAndValues ...any)
	Warn(msg string, keysAndValues ...any)
	Error(msg string, keysAndValues ...any)
}

// Event types emitted during configuration loading.
type EventType int

const (
	EventRetryAttempt EventType = iota
	EventSourceLoaded
	EventSourceFailed
	EventValidationFailed
	EventLoadSuccess
	EventLoadFailed
)

func (e EventType) String() string {
	names := [...]string{
		"RetryAttempt", "SourceLoaded", "SourceFailed",
		"ValidationFailed", "LoadSuccess", "LoadFailed",
	}
	if int(e) < len(names) {
		return names[e]
	}
	return fmt.Sprintf("EventType(%d)", e)
}

// Event is emitted during configuration loading lifecycle.
type Event struct {
	Type       EventType
	Source     string
	Attempt    int
	MaxRetries int
	Err        error
	At         time.Time
}

// EventHandler receives loader lifecycle events.
type EventHandler func(Event)

// LoadResult contains the outcome of a load operation.
type LoadResult struct {
	Config    map[string]any
	Sources   []string      // successfully loaded sources
	Duration  time.Duration // total load time
	Attempts  int           // total attempts taken
	mu        sync.RWMutex
}

// Get retrieves a configuration value by key (thread-safe).
func (r *LoadResult) Get(key string) (any, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	v, ok := r.Config[key]
	return v, ok
}

// GetString retrieves a string configuration value.
func (r *LoadResult) GetString(key string) (string, bool) {
	v, ok := r.Get(key)
	if !ok {
		return "", false
	}
	s, ok := v.(string)
	return s, ok
}

// GetInt retrieves an int configuration value.
func (r *LoadResult) GetInt(key string) (int, bool) {
	v, ok := r.Get(key)
	if !ok {
		return 0, false
	}
	switch val := v.(type) {
	case int:
		return val, true
	case int64:
		return int(val), true
	case float64:
		return int(val), true
	default:
		return 0, false
	}
}

// GetBool retrieves a bool configuration value.
func (r *LoadResult) GetBool(key string) (bool, bool) {
	v, ok := r.Get(key)
	if !ok {
		return false, false
	}
	b, ok := v.(bool)
	return b, ok
}
