## retry.go — Retry Strategy Implementation

```go
package configloader

import (
	"math"
	"math/rand/v2"
	"time"
)

// RetryStrategy defines how retries are performed.
type RetryStrategy interface {
	// NextDelay returns the delay before the next attempt.
	// Returns (delay, shouldRetry).
	NextDelay(attempt int, err error) (time.Duration, bool)
}

// RetryConfig holds configuration for the exponential backoff strategy.
type RetryConfig struct {
	MaxRetries     int           // Maximum number of retry attempts (0 = no retries)
	InitialDelay   time.Duration // Starting delay before first retry
	MaxDelay       time.Duration // Maximum delay cap
	Multiplier     float64       // Backoff multiplier (e.g., 2.0 for doubling)
	JitterFraction float64       // Jitter as fraction of delay (0.0 - 1.0)
	RetryableCheck func(error) bool // Optional: determines if an error is retryable
}

// DefaultRetryConfig returns sensible defaults.
func DefaultRetryConfig() RetryConfig {
	return RetryConfig{
		MaxRetries:     3,
		InitialDelay:   500 * time.Millisecond,
		MaxDelay:       30 * time.Second,
		Multiplier:     2.0,
		JitterFraction: 0.25,
		RetryableCheck: nil, // all errors are retryable by default
	}
}

func (c RetryConfig) validate() error {
	if c.MaxRetries < 0 {
		return fmt.Errorf("%w: MaxRetries must be >= 0, got %d", ErrInvalidRetryConfig, c.MaxRetries)
	}
	if c.InitialDelay < 0 {
		return fmt.Errorf("%w: InitialDelay must be >= 0", ErrInvalidRetryConfig)
	}
	if c.MaxDelay < c.InitialDelay {
		return fmt.Errorf("%w: MaxDelay must be >= InitialDelay", ErrInvalidRetryConfig)
	}
	if c.Multiplier < 1.0 {
		return fmt.Errorf("%w: Multiplier must be >= 1.0", ErrInvalidRetryConfig)
	}
	if c.JitterFraction < 0 || c.JitterFraction > 1.0 {
		return fmt.Errorf("%w: JitterFraction must be between 0.0 and 1.0", ErrInvalidRetryConfig)
	}
	return nil
}

// exponentialBackoff implements RetryStrategy with exponential backoff and jitter.
type exponentialBackoff struct {
	config RetryConfig
}

func newExponentialBackoff(cfg RetryConfig) *exponentialBackoff {
	return &exponentialBackoff{config: cfg}
}

func (eb *exponentialBackoff) NextDelay(attempt int, err error) (time.Duration, bool) {
	if attempt >= eb.config.MaxRetries {
		return 0, false
	}

	// Check if the error is retryable
	if eb.config.RetryableCheck != nil && !eb.config.RetryableCheck(err) {
		return 0, false
	}

	// Calculate base delay with exponential backoff
	baseDelay := float64(eb.config.InitialDelay) * math.Pow(eb.config.Multiplier, float64(attempt))

	// Cap at MaxDelay
	if baseDelay > float64(eb.config.MaxDelay) {
		baseDelay = float64(eb.config.MaxDelay)
	}

	// Apply jitter: delay ± (jitterFraction * delay)
	if eb.config.JitterFraction > 0 {
		jitter := baseDelay * eb.config.JitterFraction
		baseDelay = baseDelay - jitter + (rand.Float64() * 2 * jitter)
	}

	// Ensure non-negative
	if baseDelay < 0 {
		baseDelay = 0
	}

	return time.Duration(baseDelay), true
}

// fixedDelay implements a simple fixed-delay retry strategy.
type fixedDelay struct {
	delay      time.Duration
	maxRetries int
}

func NewFixedDelayStrategy(delay time.Duration, maxRetries int) RetryStrategy {
	return &fixedDelay{delay: delay, maxRetries: maxRetries}
}

func (fd *fixedDelay) NextDelay(attempt int, _ error) (time.Duration, bool) {
	if attempt >= fd.maxRetries {
		return 0, false
	}
	return fd.delay, true
}
