package configloader

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

// --- File Source ---

type fileSource struct {
	path     string
	priority int
}

// NewFileSource creates a source that reads from a JSON or YAML file.
func NewFileSource(path string, priority int) Source {
	return &fileSource{path: path, priority: priority}
}

func (s *fileSource) Name() string     { return fmt.Sprintf("file:%s", s.path) }
func (s *fileSource) Priority() int    { return s.priority }

func (s *fileSource) Load(ctx context.Context) (map[string]any, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}

	data, err := os.ReadFile(s.path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, fmt.Errorf("%w: %v", ErrSourceNotFound, err)
		}
		return nil, fmt.Errorf("%w: %v", ErrSourceUnavailable, err)
	}

	result := make(map[string]any)
	ext := strings.ToLower(filepath.Ext(s.path))

	switch ext {
	case ".json":
		if err := json.Unmarshal(data, &result); err != nil {
			return nil, fmt.Errorf("failed to parse JSON from %s: %w", s.path, err)
		}
	case ".yaml", ".yml":
		if err := yaml.Unmarshal(data, &result); err != nil {
			return nil, fmt.Errorf("failed to parse YAML from %s: %w", s.path, err)
		}
	default:
		// Try JSON first, then YAML
		if err := json.Unmarshal(data, &result); err != nil {
			if err2 := yaml.Unmarshal(data, &result); err2 != nil {
				return nil, fmt.Errorf("unsupported format %q for %s", ext, s.path)
			}
		}
	}

	return result, nil
}

// --- Environment Source ---

type envSource struct {
	prefix   string
	priority int
	mapping  map[string]string // env var -> config key mapping
}

// NewEnvSource creates a source that reads from environment variables.
// prefix filters env vars (e.g., "APP_" matches APP_HOST, APP_PORT).
// mapping provides explicit env-to-key translations.
func NewEnvSource(prefix string, priority int, mapping map[string]string) Source {
	return &envSource{
		prefix:   strings.ToUpper(prefix),
		priority: priority,
		mapping:  mapping,
	}
}

func (s *envSource) Name() string  { return fmt.Sprintf("env:%s*", s.prefix) }
func (s *envSource) Priority() int { return s.priority }

func (s *envSource) Load(ctx context.Context) (map[string]any, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}

	result := make(map[string]any)

	// Apply explicit mappings first
	for envKey, configKey := range s.mapping {
		if val, ok := os.LookupEnv(envKey); ok {
			result[configKey] = val
		}
	}

	// Scan all env vars with the prefix
	for _, env := range os.Environ() {
		parts := strings.SplitN(env, "=", 2)
		if len(parts) != 2 {
			continue
		}
		key, val := parts[0], parts[1]

		if s.prefix != "" && !strings.HasPrefix(key, s.prefix) {
			continue
		}

		// Skip if already mapped explicitly
		if _, mapped := s.mapping[key]; mapped {
			continue
		}

		// Convert APP_DATABASE_HOST -> database.host
		configKey := strings.ToLower(strings.TrimPrefix(key, s.prefix))
		configKey = strings.ReplaceAll(configKey, "_", ".")
		result[configKey] = val
	}

	return result, nil
}

// --- HTTP Remote Source ---

type httpSource struct {
	url      string
	priority int
	client   *http.Client
	headers  map[string]string
}

// NewHTTPSource creates a source that fetches config from an HTTP endpoint.
func NewHTTPSource(url string, priority int, opts ...HTTPSourceOption) Source {
	s := &httpSource{
		url:      url,
		priority: priority,
		client: &http.Client{
			Timeout: 10 * time.Second,
		},
		headers: make(map[string]string),
	}
	for _, opt := range opts {
		opt(s)
	}
	return s
}

type HTTPSourceOption func(*httpSource)

func WithHTTPHeader(key, value string) HTTPSourceOption {
	return func(s *httpSource) {
		s.headers[key] = value
	}
}

func WithHTTPClient(client *http.Client) HTTPSourceOption {
	return func(s *httpSource) {
		s.client = client
	}
}

func (s *httpSource) Name() string  { return fmt.Sprintf("http:%s", s.url) }
func (s *httpSource) Priority() int { return s.priority }

func (s *httpSource) Load(ctx context.Context) (map[string]any, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, s.url, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to create request: %w", err)
	}

	for k, v := range s.headers {
		req.Header.Set(k, v)
	}
	req.Header.Set("Accept", "application/json")

	resp, err := s.client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrSourceUnavailable, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 1024))
		return nil, fmt.Errorf("%w: HTTP %d from %s: %s",
			ErrSourceUnavailable, resp.StatusCode, s.url, string(body))
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 10<<20)) // 10 MB limit
	if err != nil {
		return nil, fmt.Errorf("failed to read response body: %w", err)
	}

	result := make(map[string]any)
	if err := json.Unmarshal(body, &result); err != nil {
		return nil, fmt.Errorf("failed to parse JSON response from %s: %w", s.url, err)
	}

	return result, nil
}

