```typescript
import Anthropic from "@anthropic-ai/sdk";
import * as fs from "fs";
import * as path from "path";

const client = new Anthropic();

const WATCH_DIR = "./watch";
const OUTPUT_DIR = "./reports";

// Ensure directories exist
if (!fs.existsSync(WATCH_DIR)) {
  fs.mkdirSync(WATCH_DIR, { recursive: true });
}
if (!fs.existsSync(OUTPUT_DIR)) {
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
}

async function generateReport(filePath: string, content: string): Promise<string> {
  const fileName = path.basename(filePath);

  const stream = await client.messages.stream({
    model: "claude-sonnet-4-20250514",
    max_tokens: 1024,
    messages: [
      {
        role: "user",
        content: `Analyze the following data from file "${fileName}" and generate a brief report with key findings, summary statistics if applicable, and recommendations.\n\nData:\n${content}`,
      },
    ],
  });

  let report = "";
  process.stdout.write(`\nGenerating report for ${fileName}: `);

  for await (const event of stream) {
    if (
      event.type === "content_block_delta" &&
      event.delta.type === "text_delta"
    ) {
      process.stdout.write(event.delta.text);
      report += event.delta.text;
    }
  }

  process.stdout.write("\n");
  return report;
}

function getReportPath(sourceFile: string): string {
  const baseName = path.basename(sourceFile, path.extname(sourceFile));
  const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
  return path.join(OUTPUT_DIR, `report_${baseName}_${timestamp}.md`);
}

const processedFiles = new Set<string>();

async function processFile(filePath: string): Promise<void> {
  const fullPath = path.resolve(filePath);

  if (processedFiles.has(fullPath)) {
    return;
  }
  processedFiles.add(fullPath);

  console.log(`\nDetected file: ${filePath}`);

  try {
    const content = fs.readFileSync(fullPath, "utf-8");

    if (content.trim().length === 0) {
      console.log(`Skipping empty file: ${filePath}`);
      return;
    }

    const report = await generateReport(filePath, content);
    const reportPath = getReportPath(filePath);

    const reportContent = `# Report: ${path.basename(filePath)}\n\n**Generated:** ${new Date().toISOString()}\n**Source:** ${filePath}\n\n---\n\n${report}`;

    fs.writeFileSync(reportPath, reportContent);
    console.log(`Report saved to: ${reportPath}`);
  } catch (error) {
    console.error(`Error processing ${filePath}:`, error);
  }
}

// Process existing files first
function processExistingFiles(): void {
  const existingFiles = fs.readdirSync(WATCH_DIR);
  for (const file of existingFiles) {
    const filePath = path.join(WATCH_DIR, file);
    if (fs.statSync(filePath).isFile()) {
      processFile(filePath);
    }
  }
}

// Start watching
console.log(`Watching directory: ${path.resolve(WATCH_DIR)}`);
console.log(`Reports will be saved to: ${path.resolve(OUTPUT_DIR)}`);
console.log(`Drop .txt, .csv, or .json files into ${WATCH_DIR} to generate reports.`);
console.log("Press Ctrl+C to stop.\n");

processExistingFiles();

const watcher = fs.watch(WATCH_DIR, (eventType, filename) => {
  if (eventType === "rename" && filename) {
    const filePath = path.join(WATCH_DIR, filename);
    if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
      // Small delay to ensure file is fully written
      setTimeout(() => processFile(filePath), 100);
    }
  }
});

process.on("SIGINT", () => {
  console.log("\nStopping file watcher...");
  watcher.close();
  process.exit(0);
});
```

**How it works:**

1. **Watches** `./watch` directory for new files using `fs.watch`
2. **Reads** file content when a new file is detected
3. **Streams** the content to Claude via `messages.stream()` to generate an analysis report
4. **Writes** the generated markdown report to `./reports` with a timestamp

**To test it:**

```bash
# Start the watcher
npx ts-node solution.ts

# In another terminal, drop a data file into the watch directory
echo "Sales Q1: $50k, Q2: $75k, Q3: $60k, Q4: $90k" > watch/sales.txt
```

Key details:
- Uses `client.messages.stream()` with async iteration for real-time token output
- Tracks processed files via a `Set` to avoid duplicates
- Processes any files already in the directory on startup
- Adds a small delay on file detection to handle partial writes
- Outputs reports as markdown with metadata headers

# Rust Migration Helper for Metrics Aggregation

This example demonstrates a migration helper that reads raw metric records from an old store, aggregates them by configurable strategies, and writes the results to a new store — all while tracking migration progress.

```rust
use std::collections::HashMap;
use std::fmt;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

// ──────────────────────────────────────────────
// Core metric types
// ──────────────────────────────────────────────

/// A single raw metric data point from the old store.
#[derive(Debug, Clone)]
struct MetricRecord {
    name: String,
    tags: HashMap<String, String>,
    value: f64,
    timestamp: u64, // epoch seconds
}

/// Result of aggregating multiple raw records.
#[derive(Debug, Clone)]
struct AggregatedMetric {
    name: String,
    tags: HashMap<String, String>,
    window_start: u64,
    window_end: u64,
    count: u64,
    sum: f64,
    min: f64,
    max: f64,
    avg: f64,
    p50: f64,
    p95: f64,
    p99: f64,
}

impl fmt::Display for AggregatedMetric {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "[{}] window=[{}..{}] count={} sum={:.2} avg={:.2} \
             min={:.2} max={:.2} p50={:.2} p95={:.2} p99={:.2}",
            self.name,
            self.window_start,
            self.window_end,
            self.count,
            self.sum,
            self.avg,
            self.min,
            self.max,
            self.p50,
            self.p95,
            self.p99,
        )
    }
}

// ──────────────────────────────────────────────
// Aggregation engine
// ──────────────────────────────────────────────

/// How to group raw records before aggregation.
#[derive(Debug, Clone)]
enum AggregationWindow {
    Seconds(u64),
    Minutes(u64),
    Hours(u64),
}

impl AggregationWindow {
    fn as_secs(&self) -> u64 {
        match self {
            Self::Seconds(s) => *s,
            Self::Minutes(m) => m * 60,
            Self::Hours(h) => h * 3600,
        }
    }

    /// Map a timestamp to the start of its window.
    fn bucket(&self, ts: u64) -> u64 {
        let w = self.as_secs();
        (ts / w) * w
    }
}

/// Collects values for one (name + tag‑set + window) group.
#[derive(Debug, Default)]
struct Accumulator {
    values: Vec<f64>,
}

impl Accumulator {
    fn push(&mut self, v: f64) {
        self.values.push(v);
    }

    fn finalize(
        &mut self,
        name: &str,
        tags: &HashMap<String, String>,
        window_start: u64,
        window_end: u64,
    ) -> AggregatedMetric {
        self.values.sort_by(|a, b| a.partial_cmp(b).unwrap());

        let count = self.values.len() as u64;
        let sum: f64 = self.values.iter().sum();
        let min = self.values.first().copied().unwrap_or(0.0);
        let max = self.values.last().copied().unwrap_or(0.0);
        let avg = if count > 0 { sum / count as f64 } else { 0.0 };

        AggregatedMetric {
            name: name.to_string(),
            tags: tags.clone(),
            window_start,
            window_end,
            count,
            sum,
            min,
            max,
            avg,
            p50: percentile(&self.values, 50.0),
            p95: percentile(&self.values, 95.0),
            p99: percentile(&self.values, 99.0),
        }
    }
}

fn percentile(sorted: &[f64], pct: f64) -> f64 {
    if sorted.is_empty() {
        return 0.0;
    }
    let rank = (pct / 100.0) * (sorted.len() as f64 - 1.0);
    let lower = rank.floor() as usize;
    let upper = rank.ceil() as usize;
    if lower == upper {
        sorted[lower]
    } else {
        let frac = rank - lower as f64;
        sorted[lower] * (1.0 - frac) + sorted[upper] * frac
    }
}

/// Composite key: (metric_name, serialised tags, window_start).
type BucketKey = (String, String, u64);

fn tags_key(tags: &HashMap<String, String>) -> String {
    let mut pairs: Vec<_> = tags.iter().collect();
    pairs.sort_by_key(|(k, _)| k.to_string());
    pairs
        .iter()
        .map(|(k, v)| format!("{}={}", k, v))
        .collect::<Vec<_>>()
        .join(",")
}

// ──────────────────────────────────────────────
// Source / Sink traits (old store → new store)
// ──────────────────────────────────────────────

/// Reads raw metric records in batches.
trait MetricSource {
    /// Return the next batch; empty vec ⇒ done.
    fn next_batch(&mut self, batch_size: usize) -> Result<Vec<MetricRecord>, MigrationError>;
    /// Total record count (for progress tracking), if known.
    fn total_count(&self) -> Option<u64>;
}

/// Writes aggregated metrics in batches.
trait MetricSink {
    fn write_batch(&mut self, metrics: &[AggregatedMetric]) -> Result<(), MigrationError>;
    fn flush(&mut self) -> Result<(), MigrationError>;
}

// ──────────────────────────────────────────────
// Error type
// ──────────────────────────────────────────────

#[derive(Debug)]
enum MigrationError {
    Source(String),
    Sink(String),
    Aggregation(String),
    Cancelled,
}

impl fmt::Display for MigrationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Source(e) => write!(f, "source error: {}", e),
            Self::Sink(e) => write!(f, "sink error: {}", e),
            Self::Aggregation(e) => write!(f, "aggregation error: {}", e),
            Self::Cancelled => write!(f, "migration cancelled"),
        }
    }
}

impl std::error::Error for MigrationError {}

// ──────────────────────────────────────────────
// Migration progress tracker
// ──────────────────────────────────────────────

#[derive(Debug, Clone)]
struct MigrationProgress {
    records_read: u64,
    records_total: Option<u64>,
    aggregated_written: u64,
    batches_processed: u64,
    errors: u64,
    started_at: Instant,
    last_report: Instant,
}

impl MigrationProgress {
    fn new(total: Option<u64>) -> Self {
        let now = Instant::now();
        Self {
            records_read: 0,
            records_total: total,
            aggregated_written: 0,
            batches_processed: 0,
            errors: 0,
            started_at: now,
            last_report: now,
        }
    }

    fn pct(&self) -> Option<f64> {
        self.records_total
            .map(|t| (self.records_read as f64 / t as f64) * 100.0)
    }

    fn elapsed(&self) -> Duration {
        self.started_at.elapsed()
    }

    fn records_per_sec(&self) -> f64 {
        let secs = self.elapsed().as_secs_f64();
        if secs > 0.0 {
            self.records_read as f64 / secs
        } else {
            0.0
        }
    }

    fn report(&mut self) {
        let pct_str = match self.pct() {
            Some(p) => format!("{:.1}%", p),
            None => "??%".to_string(),
        };
        println!(
            "  progress: {} | read={} written={} batches={} errors={} rate={:.0} rec/s elapsed={:.1}s",
            pct_str,
            self.records_read,
            self.aggregated_written,
            self.batches_processed,
            self.errors,
            self.records_per_sec(),
            self.elapsed().as_secs_f64(),
        );
        self.last_report = Instant::now();
    }
}

// ──────────────────────────────────────────────
// Migration configuration
// ──────────────────────────────────────────────

#[derive(Debug, Clone)]
struct MigrationConfig {
    batch_size: usize,
    window: AggregationWindow,
    report_interval: Duration,
    /// Optional filter: only migrate metrics whose name matches.
    metric_filter: Option<Vec<String>>,
    /// If true, keep raw tag sets; otherwise drop tags during aggregation.
    preserve_tags: bool,
    /// Dry-run: aggregate but don't write.
    dry_run: bool,
}

impl Default for MigrationConfig {
    fn default() -> Self {
        Self {
            batch_size: 1024,
            window: AggregationWindow::Minutes(5),
            report_interval: Duration::from_secs(5),
            metric_filter: None,
            preserve_tags: true,
            dry_run: false,
        }
    }
}

// ──────────────────────────────────────────────
// The migration helper
// ──────────────────────────────────────────────

struct MigrationHelper<S: MetricSource, K: MetricSink> {
    source: S,
    sink: K,
    config: MigrationConfig,
    buckets: HashMap<BucketKey, (HashMap<String, String>, Accumulator)>,
    progress: MigrationProgress,
    cancel: Arc<Mutex<bool>>,
}

impl<S: MetricSource, K: MetricSink> MigrationHelper<S, K> {
    fn new(source: S, sink: K, config: MigrationConfig) -> Self {
        let total = source.total_count();
        Self {
            source,
            sink,
            config,
            buckets: HashMap::new(),
            progress: MigrationProgress::new(total),
            cancel: Arc::new(Mutex::new(false)),
        }
    }

    /// Get a cloneable cancel handle.
    fn cancel_handle(&self) -> Arc<Mutex<bool>> {
        Arc::clone(&self.cancel)
    }

    /// Run the full migration.
    fn run(&mut self) -> Result<MigrationProgress, MigrationError> {
        println!("=== Migration started ===");
        println!("  window      : {:?}", self.config.window);
        println!("  batch_size  : {}", self.config.batch_size);
        println!("  dry_run     : {}", self.config.dry_run);
        println!();

        // Phase 1 — read & bucket
        self.read_phase()?;

        // Phase 2 — finalize & write
        self.write_phase()?;

        println!();
        println!("=== Migration complete ===");
        self.progress.report();

        Ok(self.progress.clone())
    }

    // ── phase 1 ─────────────────────────────

    fn read_phase(&mut self) -> Result<(), MigrationError> {
        loop {
            if *self.cancel.lock().unwrap() {
                return Err(MigrationError::Cancelled);
            }

            let batch = self.source.next_batch(self.config.batch_size)?;
            if batch.is_empty() {
                break;
            }

            for record in &batch {
                if !self.passes_filter(record) {
                    continue;
                }
                self.accumulate(record);
            }

            self.progress.records_read += batch.len() as u64;
            self.progress.batches_processed += 1;

            if self.progress.last_report.elapsed() >= self.config.report_interval {
                self.progress.report();
            }
        }
        Ok(())
    }

    fn passes_filter(&self, record: &MetricRecord) -> bool {
        match &self.config.metric_filter {
            None => true,
            Some(names) => names.iter().any(|n| record.name == *n),
        }
    }

    fn accumulate(&mut self, record: &MetricRecord) {
        let window_start = self.config.window.bucket(record.timestamp);
        let tk = if self.config.preserve_tags {
            tags_key(&record.tags)
        } else {
            String::new()
        };
        let key = (record.name.clone(), tk, window_start);

        self.buckets
            .entry(key)
            .or_insert_with(|| (record.tags.clone(), Accumulator::default()))
            .1
            .push(record.value);
    }

    // ── phase 2 ─────────────────────────────

    fn write_phase(&mut self) -> Result<(), MigrationError> {
        let window_secs = self.config.window.as_secs();
        let mut out_batch: Vec<AggregatedMetric> = Vec::with_capacity(self.config.batch_size);

        // Drain the buckets to avoid borrowing issues
        let buckets: Vec<_> = self.buckets.drain().collect();

        for ((name, _tk, ws), (tags, mut acc)) in buckets {
            let agg = acc.finalize(&name, &tags, ws, ws + window_secs);
            out_batch.push(agg);

            if out_batch.len() >= self.config.batch_size {
                self.flush_batch(&out_batch)?;
                self.progress.aggregated_written += out_batch.len() as u64;
                out_batch.clear();
            }
        }

        // flush remainder
        if !out_batch.is_empty() {
            self.flush_batch(&out_batch)?;
            self.progress.aggregated_written += out_batch.len() as u64;
        }

        if !self.config.dry_run {
            self.sink.flush()?;
        }

        Ok(())
    }

    fn flush_batch(&mut self, batch: &[AggregatedMetric]) -> Result<(), MigrationError> {
        if self.config.dry_run {
            println!("  [dry-run] would write {} aggregated metrics", batch.len());
            for m in batch {
                println!("    {}", m);
            }
            return Ok(());
        }
        self.sink.write_batch(batch)
    }
}

// ──────────────────────────────────────────────
// Example in-memory source & sink (for testing)
// ──────────────────────────────────────────────

struct InMemorySource {
    records: Vec<MetricRecord>,
    cursor: usize,
}

impl InMemorySource {
    fn new(records: Vec<MetricRecord>) -> Self {
        Self { records, cursor: 0 }
    }
}

impl MetricSource for InMemorySource {
    fn next_batch(&mut self, batch_size: usize) -> Result<Vec<MetricRecord>, MigrationError> {
        let end = (self.cursor + batch_size).min(self.records.len());
        let batch = self.records[self.cursor..end].to_vec();
        self.cursor = end;
        Ok(batch)
    }

    fn total_count(&self) -> Option<u64> {
        Some(self.records.len() as u64)
    }
}

struct InMemorySink {
    written: Vec<AggregatedMetric>,
}

impl InMemorySink {
    fn new() -> Self {
        Self {
            written: Vec::new(),
        }
    }
}

impl MetricSink for InMemorySink {
    fn write_batch(&mut self, metrics: &[AggregatedMetric]) -> Result<(), MigrationError> {
        self.written.extend_from_slice(metrics);
        Ok(())
    }

    fn flush(&mut self) -> Result<(), MigrationError> {
        println!(
            "  [sink] flushed — total aggregated records stored: {}",
            self.written.len()
        );
        Ok(())
    }
}

