fn generate_sample_records(count: usize) -> Vec<MetricRecord> {
    let base_ts = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
        - 3600; // start 1 hour ago

    let metric_names = ["http.request_duration", "http.request_count", "db.query_time"];
    let envs = ["prod", "staging"];
    let regions = ["us-east-1", "eu-west-1"];

    let mut records = Vec::with_capacity(count);
    for i in 0..count {
        let name = metric_names[i % metric_names.len()].to_string();
        let mut tags = HashMap::new();
        tags.insert("env".into(), envs[i % envs.len()].into());
        tags.insert("region".into(), regions[i % regions.len()].into());

        records.push(MetricRecord {
            name,
            tags,
            value: (i as f64 * 1.7) % 500.0 + 1.0,
            timestamp: base_ts + (i as u64 * 15), // one every 15 s
        });
    }
    records
}

