import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic();

// Simple in-memory queue
const reportQueue = [];
let processing = false;

// Add a report request to the queue
function enqueueReport(reportRequest) {
  const job = {
    id: `job_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    status: "pending",
    request: reportRequest,
    result: null,
    createdAt: new Date().toISOString(),
  };
  reportQueue.push(job);
  console.log(`[QUEUE] Job ${job.id} enqueued: "${reportRequest.title}"`);
  processQueue();
  return job;
}

// Process jobs from the queue one at a time
async function processQueue() {
  if (processing) return;
  if (reportQueue.length === 0) return;

  const pendingJob = reportQueue.find((j) => j.status === "pending");
  if (!pendingJob) return;

  processing = true;
  pendingJob.status = "processing";
  console.log(`\n[WORKER] Processing job ${pendingJob.id}...`);

  try {
    const report = await generateReport(pendingJob.request);
    pendingJob.status = "completed";
    pendingJob.result = report;
    console.log(`[WORKER] Job ${pendingJob.id} completed successfully`);
  } catch (error) {
    pendingJob.status = "failed";
    pendingJob.result = { error: error.message };
    console.error(`[WORKER] Job ${pendingJob.id} failed: ${error.message}`);
  }

  processing = false;
  // Process next job if any
  processQueue();
}

// Generate a report using Claude
async function generateReport(request) {
  const { title, dataPoints, reportType } = request;

  const prompt = `Generate a concise ${reportType} report titled "${title}".

Here is the data to analyze:
${JSON.stringify(dataPoints, null, 2)}

Format the report with:
- Executive Summary (2-3 sentences)
- Key Findings (bullet points)
- Conclusion (1-2 sentences)

Keep it professional and data-driven.`;

  console.log(`[CLAUDE] Sending request for "${title}"...`);

  const message = await client.messages.create({
    model: "claude-sonnet-4-20250514",
    max_tokens: 1024,
    messages: [{ role: "user", content: prompt }],
  });

  const reportContent = message.content[0].text;

  return {
    title,
    reportType,
    content: reportContent,
    generatedAt: new Date().toISOString(),
    tokensUsed: {
      input: message.usage.input_tokens,
      output: message.usage.output_tokens,
    },
  };
}

// Get job status
function getJobStatus(jobId) {
  return reportQueue.find((j) => j.id === jobId) || null;
}

// List all jobs
function listJobs() {
  return reportQueue.map((j) => ({
    id: j.id,
    title: j.request.title,
    status: j.status,
    createdAt: j.createdAt,
  }));
}

