      totalRevenue: "$2.4M",
      unitsSold: 15200,
      topProduct: "Widget Pro",
      growthRate: "12%",
      regions: { north: "$800K", south: "$600K", east: "$500K", west: "$500K" },
    },
  });

  const job2 = enqueueReport({
    title: "Website Traffic Analysis",
    reportType: "analytics",
    dataPoints: {
      monthlyVisitors: 245000,
      bounceRate: "34%",
      avgSessionDuration: "4m 12s",
      topPages: ["/products", "/pricing", "/blog/ai-trends"],
      conversionRate: "3.2%",
    },
  });

  const job3 = enqueueReport({
    title: "Employee Satisfaction Survey",
    reportType: "HR",
    dataPoints: {
      respondents: 342,
      overallScore: 4.2,
      categories: {
        workLifeBalance: 4.5,
        compensation: 3.8,
        management: 4.1,
        growth: 4.0,
      },
      retentionRate: "91%",
    },
  });

  // Wait for all jobs to complete
  console.log("\n[MAIN] Waiting for all jobs to complete...\n");

  await new Promise((resolve) => {
    const check = setInterval(() => {
      const allDone = reportQueue.every(
        (j) => j.status === "completed" || j.status === "failed"
      );
      if (allDone) {
        clearInterval(check);
        resolve();
      }
    }, 500);
  });

  // Print results
  console.log("\n=== All Jobs Completed ===\n");
  console.log("Job Summary:");
  console.log(JSON.stringify(listJobs(), null, 2));

  for (const job of reportQueue) {
    console.log(`\n${"=".repeat(60)}`);
    console.log(`Report: ${job.request.title} (${job.status})`);
    console.log(`${"=".repeat(60)}`);
    if (job.result && !job.result.error) {
      console.log(job.result.content);
      console.log(
        `\nTokens used - Input: ${job.result.tokensUsed.input}, Output: ${job.result.tokensUsed.output}`
      );
    } else if (job.result?.error) {
      console.log(`Error: ${job.result.error}`);
    }
  }
}

main().catch(console.error);
```

This creates a basic queue consumer for report generation using Claude:

## How it works

1. **In-memory queue** - `reportQueue` array holds job objects with status tracking (`pending` → `processing` → `completed`/`failed`)

2. **`enqueueReport()`** - Adds a report request to the queue and triggers processing

3. **`processQueue()`** - Picks up pending jobs one at a time (serial processing via the `processing` flag), calls Claude to generate each report

4. **`generateReport()`** - Sends structured data to Claude with a prompt template and returns the formatted report with token usage stats

5. **Demo** - Enqueues 3 different reports (sales, analytics, HR), waits for completion, then prints all results

Key design choices:
- **Sequential processing** prevents API rate limit issues
- **Job status tracking** lets you check on any job by ID
- **Error handling** marks failed jobs without crashing the consumer
- **Self-draining** — after each job finishes, `processQueue()` automatically picks up the next one

