## Search Client (Elasticsearch Wrapper)

```typescript
// search-client.ts

import { Client } from "@elastic/elasticsearch";
import { BulkOperation, BulkResult } from "./types";

export class SearchClient {
  private client: Client;

  constructor(node: string) {
    this.client = new Client({ node });
  }

  async bulk(operations: BulkOperation[]): Promise<BulkResult> {
    const body: object[] = [];

    for (const op of operations) {
      switch (op.action) {
        case "index":
          body.push(
            { index: { _index: op.index, _id: op.documentId } },
            op.body ?? {}
          );
          break;
        case "update":
          body.push(
            { update: { _index: op.index, _id: op.documentId } },
            { doc: op.body ?? {} }
          );
          break;
        case "delete":
          body.push({ delete: { _index: op.index, _id: op.documentId } });
          break;
      }
    }

    const response = await this.client.bulk({ body, refresh: false });

    const successful: string[] = [];
    const failed: { id: string; error: string }[] = [];

    // Each action has a corresponding result item
    let opIndex = 0;
    for (const item of response.items) {
      const result = item.index ?? item.update ?? item.delete;
      const operation = operations[opIndex];

      if (result?.error) {
        failed.push({
          id: operation.documentId,
          error: typeof result.error === "string"
            ? result.error
            : result.error.reason ?? "Unknown error",
        });
      } else {
        successful.push(operation.documentId);
      }
      opIndex++;
    }

    return { successful, failed };
  }

  async healthCheck(): Promise<boolean> {
    try {
      const resp = await this.client.cluster.health();
      return resp.status !== "red";
    } catch {
      return false;
    }
  }
}
