## Retry Utility

```typescript
// retry.ts

import { IndexMessage } from "./types";

export function calculateBackoff(attempt: number, baseMs = 1000, maxMs = 30000): number {
  const delay = Math.min(baseMs * Math.pow(2, attempt), maxMs);
  const jitter = delay * 0.2 * Math.random();
  return delay + jitter;
}

export function shouldRetry(message: IndexMessage, maxRetries: number): boolean {
  return (message.attempt ?? 0) < maxRetries;
}

export function prepareRetry(message: IndexMessage): IndexMessage {
  return {
    ...message,
    attempt: (message.attempt ?? 0) + 1,
    timestamp: Date.now(),
  };
}
