## Batch Processor

```typescript
// batch-processor.ts

import { EventEmitter } from "events";
import { IndexMessage, BulkOperation, BulkResult, ConsumerConfig } from "./types";
import { SearchClient } from "./search-client";

export class BatchProcessor extends EventEmitter {
  private buffer: IndexMessage[] = [];
  private flushTimer: NodeJS.Timeout | null = null;
  private flushing = false;

  constructor(
    private searchClient: SearchClient,
    private config: Pick<ConsumerConfig, "batchSize" | "flushIntervalMs">
  ) {
    super();
  }

  add(message: IndexMessage): void {
    this.buffer.push(message);

    if (this.buffer.length >= this.config.batchSize) {
      this.flush();
    } else if (!this.flushTimer) {
      this.flushTimer = setTimeout(() => this.flush(), this.config.flushIntervalMs);
    }
  }

  async flush(): Promise<void> {
    if (this.flushing || this.buffer.length === 0) return;

    this.flushing = true;
    this.clearTimer();

    // Grab current buffer and reset
    const batch = this.buffer.splice(0);
    const deduplicated = this.deduplicate(batch);

    try {
      const operations: BulkOperation[] = deduplicated.map((msg) => ({
        action: msg.action,
        index: msg.index,
        documentId: msg.documentId,
        body: msg.body,
      }));

      const result = await this.searchClient.bulk(operations);

      this.emit("batch:complete", {
        total: deduplicated.length,
        ...result,
      });

      // Re-emit failures so the consumer can retry them
      if (result.failed.length > 0) {
        const failedMessages = deduplicated.filter((msg) =>
          result.failed.some((f) => f.id === msg.documentId)
        );
        this.emit("batch:partial-failure", failedMessages);
      }
    } catch (error) {
      // Total failure — everything goes back for retry
      this.emit("batch:error", batch, error);
    } finally {
      this.flushing = false;
    }
  }

  get pending(): number {
    return this.buffer.length;
  }

  /**
   * If the same document appears multiple times, keep only the latest action.
   */
  private deduplicate(messages: IndexMessage[]): IndexMessage[] {
    const latest = new Map<string, IndexMessage>();

    for (const msg of messages) {
      const key = `${msg.index}:${msg.documentId}`;
      const existing = latest.get(key);

      if (!existing || msg.timestamp > existing.timestamp) {
        latest.set(key, msg);
      }
    }

    return Array.from(latest.values());
  }

  private clearTimer(): void {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }
  }

  async drain(): Promise<void> {
    this.clearTimer();
    await this.flush();
  }
}
```

## Queue Consumer

```typescript
// queue-consumer.ts

import amqp, { Channel, Connection, ConsumeMessage } from "amqplib";
import { IndexMessage, ConsumerConfig } from "./types";
import { BatchProcessor } from "./batch-processor";
import { SearchClient } from "./search-client";
import { calculateBackoff, shouldRetry, prepareRetry } from "./retry";

const DEFAULT_CONFIG: ConsumerConfig = {
  queue: "search.index",
  deadLetterQueue: "search.index.dlq",
  batchSize: 100,
  flushIntervalMs: 2000,
  maxRetries: 3,
  concurrency: 5,
};

export class QueueConsumer {
  private connection: Connection | null = null;
  private channel: Channel | null = null;
  private processor: BatchProcessor;
  private config: ConsumerConfig;
  private shutdownRequested = false;
  private activeTag: string | null = null;

  constructor(
    private amqpUrl: string,
    private searchClient: SearchClient,
    config: Partial<ConsumerConfig> = {}
  ) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.processor = new BatchProcessor(searchClient, this.config);
    this.setupProcessorEvents();
  }

  async start(): Promise<void> {
    this.connection = await amqp.connect(this.amqpUrl);
    this.channel = await this.connection.createChannel();

    // Declare queues
    await this.channel.assertQueue(this.config.queue, {
      durable: true,
      arguments: {
        "x-dead-letter-exchange": "",
        "x-dead-letter-routing-key": this.config.deadLetterQueue,
      },
    });
    await this.channel.assertQueue(this.config.deadLetterQueue, { durable: true });

    // Prefetch controls how many unacked messages we hold
    await this.channel.prefetch(this.config.batchSize * 2);

    const { consumerTag } = await this.channel.consume(
      this.config.queue,
      (msg) => this.handleMessage(msg),
      { noAck: false }
    );
    this.activeTag = consumerTag;

    console.log(`Consumer started on queue: ${this.config.queue}`);

    this.connection.on("error", (err) => {
      console.error("AMQP connection error:", err.message);
      if (!this.shutdownRequested) this.reconnect();
    });

    this.connection.on("close", () => {
      if (!this.shutdownRequested) {
        console.warn("AMQP connection closed unexpectedly, reconnecting...");
        this.reconnect();
      }
    });
  }

  private handleMessage(msg: ConsumeMessage | null): void {
    if (!msg || this.shutdownRequested) return;

    try {
      const content: IndexMessage = JSON.parse(msg.content.toString());

      // Validate required fields
      if (!content.action || !content.index || !content.documentId) {
        console.warn("Malformed message, sending to DLQ:", msg.content.toString());
        this.channel?.nack(msg, false, false); // send to DLQ
        return;
      }

      // Attach the raw message for ack/nack later
      // For simplicity, ack immediately and let the batch processor handle retries
      this.channel?.ack(msg);
      this.processor.add(content);
    } catch (err) {
      console.error("Failed to parse message:", err);
      this.channel?.nack(msg, false, false);
    }
  }

  private setupProcessorEvents(): void {
    this.processor.on("batch:complete", (result) => {
      console.log(
        `Batch indexed: ${result.successful.length} ok, ${result.failed.length} failed`
      );
    });

    this.processor.on("batch:partial-failure", (messages: IndexMessage[]) => {
      for (const msg of messages) {
        this.retryOrDLQ(msg);
      }
    });

    this.processor.on("batch:error", (messages: IndexMessage[], error: Error) => {
      console.error("Batch failed entirely:", error.message);
      for (const msg of messages) {
        this.retryOrDLQ(msg);
      }
    });
  }

  private async retryOrDLQ(message: IndexMessage): Promise<void> {
    if (!this.channel) return;

    if (shouldRetry(message, this.config.maxRetries)) {
      const retryMsg = prepareRetry(message);
      const delay = calculateBackoff(retryMsg.attempt ?? 1);

      console.log(
        `Retrying ${message.documentId} (attempt ${retryMsg.attempt}) in ${Math.round(delay)}ms`
      );

      setTimeout(() => {
        this.channel?.sendToQueue(
          this.config.queue,
          Buffer.from(JSON.stringify(retryMsg)),
          { persistent: true }
        );
      }, delay);
    } else {
      console.warn(`Max retries reached for ${message.documentId}, sending to DLQ`);
      this.channel.sendToQueue(
        this.config.deadLetterQueue,
        Buffer.from(JSON.stringify(message)),
        { persistent: true }
      );
    }
  }

  private async reconnect(): Promise<void> {
    console.log("Attempting reconnect in 5s...");
    await this.cleanup();
    setTimeout(() => this.start().catch(console.error), 5000);
  }

  async shutdown(): Promise<void> {
    console.log("Graceful shutdown initiated...");
    this.shutdownRequested = true;

    // Stop consuming new messages
    if (this.channel && this.activeTag) {
      await this.channel.cancel(this.activeTag);
    }

    // Drain remaining buffered items
    await this.processor.drain();
    console.log("Buffer drained.");

    await this.cleanup();
    console.log("Shutdown complete.");
  }

  private async cleanup(): Promise<void> {
    try {
      await this.channel?.close();
    } catch { /* already closed */ }
    try {
      await this.connection?.close();
    } catch { /* already closed */ }
    this.channel = null;
    this.connection = null;
  }
}
