## Database Store (Batched Writes)

```typescript
// src/store.ts
import { Pool, PoolClient } from "pg";
import pino from "pino";
import { AuditRecord } from "./schema";
import { config } from "./config";

const log = pino({ name: "audit-store" });

export class AuditStore {
  private pool: Pool;
  private batch: AuditRecord[] = [];
  private flushTimer: NodeJS.Timeout | null = null;
  private flushing = false;

  constructor() {
    this.pool = new Pool(config.postgres);
  }

  async initialize(): Promise<void> {
    // Create table + indexes if they don't exist
    const client = await this.pool.connect();
    try {
      await client.query(`
        CREATE TABLE IF NOT EXISTS audit_logs (
          event_id       UUID PRIMARY KEY,
          timestamp      TIMESTAMPTZ NOT NULL,
          actor_id       TEXT NOT NULL,
          actor_type     TEXT NOT NULL,
          actor_ip       INET,
          user_agent     TEXT,
          action         TEXT NOT NULL,
          resource_type  TEXT NOT NULL,
          resource_id    TEXT NOT NULL,
          tenant_id      TEXT,
          correlation_id TEXT,
          outcome        TEXT NOT NULL,
          metadata       JSONB,
          ingested_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        CREATE INDEX IF NOT EXISTS idx_audit_actor    ON audit_logs (actor_id, timestamp DESC);
        CREATE INDEX IF NOT EXISTS idx_audit_action   ON audit_logs (action, timestamp DESC);
        CREATE INDEX IF NOT EXISTS idx_audit_resource ON audit_logs (resource_type, resource_id, timestamp DESC);
        CREATE INDEX IF NOT EXISTS idx_audit_tenant   ON audit_logs (tenant_id, timestamp DESC) WHERE tenant_id IS NOT NULL;
      `);
      log.info("Audit store initialized");
    } finally {
      client.release();
    }
  }

  // Queue a record; flush when batch is full or timer fires
  async enqueue(record: AuditRecord): Promise<void> {
    this.batch.push(record);

    if (this.batch.length >= config.queue.batchSize) {
      await this.flush();
    } else if (!this.flushTimer) {
      this.flushTimer = setTimeout(
        () => this.flush(),
        config.queue.flushIntervalMs
      );
    }
  }

  async flush(): Promise<void> {
    if (this.flushing || this.batch.length === 0) return;
    this.flushing = true;

    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }

    const records = this.batch.splice(0); // take everything
    const client = await this.pool.connect();

    try {
      await this.insertBatch(client, records);
      log.info({ count: records.length }, "Flushed audit batch");
    } catch (err) {
      // Put records back at front so they retry
      this.batch.unshift(...records);
      log.error({ err, count: records.length }, "Batch insert failed");
      throw err;
    } finally {
      client.release();
      this.flushing = false;
    }
  }

  private async insertBatch(
    client: PoolClient,
    records: AuditRecord[]
  ): Promise<void> {
    // Build a single multi-row INSERT with parameterized values
    const columns = [
      "event_id", "timestamp", "actor_id", "actor_type",
      "actor_ip", "user_agent", "action", "resource_type",
      "resource_id", "tenant_id", "correlation_id", "outcome",
      "metadata", "ingested_at",
    ];
    const colCount = columns.length;

    const values: unknown[] = [];
    const rows: string[] = [];

    records.forEach((r, i) => {
      const offset = i * colCount;
      const placeholders = columns.map((_, j) => `$${offset + j + 1}`);
      rows.push(`(${placeholders.join(", ")})`);

      values.push(
        r.event_id, r.timestamp, r.actor_id, r.actor_type,
        r.actor_ip, r.user_agent, r.action, r.resource_type,
        r.resource_id, r.tenant_id, r.correlation_id, r.outcome,
        r.metadata ? JSON.stringify(r.metadata) : null,
        r.ingested_at
      );
    });

    const query = `
      INSERT INTO audit_logs (${columns.join(", ")})
      VALUES ${rows.join(",\n")}
      ON CONFLICT (event_id) DO NOTHING
    `;

    await client.query(query, values);
  }

  async shutdown(): Promise<void> {
    await this.flush();
    await this.pool.end();
  }
}
