## Event Processor (Validation + Transform)

```typescript
// src/processor.ts
import { Job } from "bullmq";
import pino from "pino";
import { auditEventSchema, AuditEvent, AuditRecord } from "./schema";
import { AuditStore } from "./store";
import { DeadLetterHandler } from "./dead-letter";

const log = pino({ name: "audit-processor" });

export class AuditProcessor {
  constructor(
    private store: AuditStore,
    private dlq: DeadLetterHandler
  ) {}

  // This is what BullMQ calls for every job
  async process(job: Job): Promise<void> {
    const parseResult = auditEventSchema.safeParse(job.data);

    if (!parseResult.success) {
      // Malformed event — no point retrying, send to DLQ
      log.warn(
        { jobId: job.id, errors: parseResult.error.flatten() },
        "Invalid audit event, sending to DLQ"
      );
      await this.dlq.capture(job.data, "validation_failed", parseResult.error);
      return; // don't throw — prevents BullMQ retry
    }

    const event = parseResult.data;
    const record = this.toRecord(event);

    await this.store.enqueue(record);

    log.debug(
      { eventId: record.event_id, action: record.action },
      "Audit event processed"
    );
  }

  private toRecord(event: AuditEvent): AuditRecord {
    const ts = event.timestamp instanceof Date
      ? event.timestamp
      : new Date(event.timestamp);

    return {
      event_id: event.eventId,
      timestamp: ts,
      actor_id: event.actor.id,
      actor_type: event.actor.type,
      actor_ip: event.actor.ip ?? null,
      user_agent: event.actor.userAgent ?? null,
      action: event.action,
      resource_type: event.resource.type,
      resource_id: event.resource.id,
      tenant_id: event.context?.tenantId ?? null,
      correlation_id: event.context?.correlationId ?? null,
      outcome: event.outcome,
      metadata: event.metadata ?? null,
      ingested_at: new Date(),
    };
  }
}
