## Dead Letter Queue Handler

```typescript
// src/dead-letter.ts
import { Queue } from "bullmq";
import pino from "pino";
import { config } from "./config";
import IORedis from "ioredis";

const log = pino({ name: "audit-dlq" });

export class DeadLetterHandler {
  private dlq: Queue;

  constructor(connection: IORedis) {
    this.dlq = new Queue(`${config.queue.name}:dlq`, { connection });
  }

  async capture(
    originalPayload: unknown,
    reason: string,
    error?: unknown
  ): Promise<void> {
    try {
      await this.dlq.add("dead-letter", {
        originalPayload,
        reason,
        error: error instanceof Error
          ? { message: error.message, stack: error.stack }
          : error,
        failedAt: new Date().toISOString(),
      });
      log.warn({ reason }, "Event sent to dead letter queue");
    } catch (err) {
      // DLQ itself failed — log to stderr as last resort
      log.error({ err, originalPayload, reason }, "CRITICAL: DLQ write failed");
    }
  }

  async shutdown(): Promise<void> {
    await this.dlq.close();
  }
}
