## Consumer (Wiring It All Together)

```typescript
// src/consumer.ts
import { Worker, QueueEvents } from "bullmq";
import IORedis from "ioredis";
import pino from "pino";
import { config } from "./config";
import { AuditProcessor } from "./processor";
import { AuditStore } from "./store";
import { DeadLetterHandler } from "./dead-letter";

const log = pino({ name: "audit-consumer" });

export class AuditConsumer {
  private connection: IORedis;
  private worker!: Worker;
  private events!: QueueEvents;
  private store: AuditStore;
  private dlq: DeadLetterHandler;
  private processor: AuditProcessor;

  constructor() {
    this.connection = new IORedis(config.redis);
    this.store = new AuditStore();
    this.dlq = new DeadLetterHandler(this.connection.duplicate());
    this.processor = new AuditProcessor(this.store, this.dlq);
  }

  async start(): Promise<void> {
    await this.store.initialize();

    this.worker = new Worker(
      config.queue.name,
      (job) => this.processor.process(job),
      {
        connection: this.connection.duplicate(),
        concurrency: config.queue.concurrency,
        removeOnComplete: { age: 3600, count: 1000 },   // keep last 1k or 1hr
        removeOnFail: { age: 86400, count: 5000 },      // keep failures 24hr
        settings: {
          backoffStrategy: (attemptsMade: number) => {
            // Exponential: 1s, 2s, 4s, 8s, 16s...
            return Math.min(
              config.retry.backoffDelay * Math.pow(2, attemptsMade - 1),
              30_000
            );
          },
        },
      }
    );

    // Event monitoring
    this.events = new QueueEvents(config.queue.name, {
      connection: this.connection.duplicate(),
    });

    this.worker.on("completed", (job) => {
      log.debug({ jobId: job.id }, "Job completed");
    });

    this.worker.on("failed", (job, err) => {
      log.error(
        { jobId: job?.id, attempt: job?.attemptsMade, err: err.message },
        "Job failed"
      );

      // If exhausted all retries, send to DLQ
      if (job && job.attemptsMade >= config.retry.maxAttempts) {
        this.dlq.capture(job.data, "max_retries_exhausted", err);
      }
    });

    this.worker.on("error", (err) => {
      log.error({ err }, "Worker error");
    });

    log.info(
      { queue: config.queue.name, concurrency: config.queue.concurrency },
      "Audit consumer started"
    );
  }

  async shutdown(): Promise<void> {
    log.info("Shutting down gracefully...");

    // Stop accepting new jobs, finish current ones
    await this.worker.close();
    await this.events.close();

    // Flush remaining buffered records
    await this.store.shutdown();
    await this.dlq.shutdown();
    await this.connection.quit();

    log.info("Shutdown complete");
  }
}
```

