## Core Implementation

### `src/rateLimiter.js` — Token Bucket & Sliding Window

```javascript
const { EventEmitter } = require("events");

/**
 * Token Bucket Rate Limiter
 * - Tokens refill at a steady rate
 * - Each job consumes one token
 * - If no tokens remain, the job must wait
 */
class TokenBucketLimiter extends EventEmitter {
  #tokens;
  #maxTokens;
  #refillRate; // tokens per second
  #refillTimer;

  constructor({ maxTokens = 10, refillRate = 1 }) {
    super();
    this.#maxTokens = maxTokens;
    this.#tokens = maxTokens;
    this.#refillRate = refillRate;
    this.#refillTimer = null;
  }

  /** Start the refill loop */
  start() {
    const intervalMs = 1000 / this.#refillRate;

    this.#refillTimer = setInterval(() => {
      if (this.#tokens < this.#maxTokens) {
        this.#tokens++;
        this.emit("tokenAvailable", this.#tokens);
      }
    }, intervalMs);

    // Allow the process to exit even if the timer is running
    this.#refillTimer.unref();
    this.emit("started", { maxTokens: this.#maxTokens, refillRate: this.#refillRate });
  }

  /** Stop the refill loop */
  stop() {
    if (this.#refillTimer) {
      clearInterval(this.#refillTimer);
      this.#refillTimer = null;
    }
    this.emit("stopped");
  }

  /** Try to consume a token immediately */
  tryConsume() {
    if (this.#tokens > 0) {
      this.#tokens--;
      return true;
    }
    return false;
  }

  /**
   * Wait until a token is available, then consume it.
   * Resolves with wait time in ms. Rejects on timeout.
   */
  waitForToken(timeoutMs = 30000) {
    // Fast path: token is available right now
    if (this.tryConsume()) {
      return Promise.resolve(0);
    }

    return new Promise((resolve, reject) => {
      const start = Date.now();

      const timeout = setTimeout(() => {
        this.removeListener("tokenAvailable", onToken);
        reject(new Error(`Rate limit timeout after ${timeoutMs}ms`));
      }, timeoutMs);

      const onToken = () => {
        if (this.tryConsume()) {
          clearTimeout(timeout);
          this.removeListener("tokenAvailable", onToken);
          resolve(Date.now() - start);
        }
      };

      this.on("tokenAvailable", onToken);
    });
  }

  get availableTokens() {
    return this.#tokens;
  }

  get stats() {
    return {
      availableTokens: this.#tokens,
      maxTokens: this.#maxTokens,
      refillRate: this.#refillRate,
    };
  }
}

/**
 * Sliding Window Rate Limiter
 * - Tracks timestamps of recent operations
 * - Allows N operations per time window
 */
class SlidingWindowLimiter extends EventEmitter {
  #maxRequests;
  #windowMs;
  #timestamps;

  constructor({ maxRequests = 10, windowMs = 60000 }) {
    super();
    this.#maxRequests = maxRequests;
    this.#windowMs = windowMs;
    this.#timestamps = [];
  }

  start() {
    this.emit("started", {
      maxRequests: this.#maxRequests,
      windowMs: this.#windowMs,
    });
  }

  stop() {
    this.#timestamps = [];
    this.emit("stopped");
  }

  /** Remove expired timestamps outside the current window */
  #cleanup() {
    const cutoff = Date.now() - this.#windowMs;
    this.#timestamps = this.#timestamps.filter((t) => t > cutoff);
  }

  /** Try to record a request; returns true if allowed */
  tryConsume() {
    this.#cleanup();
    if (this.#timestamps.length < this.#maxRequests) {
      this.#timestamps.push(Date.now());
      return true;
    }
    return false;
  }

  /** Returns how many ms until the next slot opens */
  get msUntilNextSlot() {
    this.#cleanup();
    if (this.#timestamps.length < this.#maxRequests) return 0;
    return this.#timestamps[0] + this.#windowMs - Date.now();
  }

  /** Wait for a slot to open, then consume it */
  waitForToken(timeoutMs = 30000) {
    if (this.tryConsume()) {
      return Promise.resolve(0);
    }

    return new Promise((resolve, reject) => {
      const start = Date.now();
      const waitMs = this.msUntilNextSlot;

      if (waitMs > timeoutMs) {
        return reject(
          new Error(`Rate limit wait (${waitMs}ms) exceeds timeout (${timeoutMs}ms)`)
        );
      }

      setTimeout(() => {
        if (this.tryConsume()) {
          resolve(Date.now() - start);
        } else {
          reject(new Error("Could not acquire rate limit slot"));
        }
      }, waitMs + 10); // small buffer
    });
  }

  get stats() {
    this.#cleanup();
    return {
      currentRequests: this.#timestamps.length,
      maxRequests: this.#maxRequests,
      windowMs: this.#windowMs,
      msUntilNextSlot: this.msUntilNextSlot,
    };
  }
}

module.exports = { TokenBucketLimiter, SlidingWindowLimiter };
```

### `src/jobQueue.js` — Priority Job Queue

```javascript
const { EventEmitter } = require("events");
const crypto = require("crypto");

/** Job states */
const JobStatus = {
  PENDING: "pending",
  RUNNING: "running",
  COMPLETED: "completed",
  FAILED: "failed",
  RETRYING: "retrying",
};

/**
 * Simple in-memory priority job queue.
 * Replace with Redis/BullMQ/SQS in production.
 */
class JobQueue extends EventEmitter {
  #jobs;       // Map<id, job>
  #pending;    // sorted array of pending job ids

  constructor() {
    super();
    this.#jobs = new Map();
    this.#pending = [];
  }

  /**
   * Add a job to the queue.
   * @param {object} opts
   * @param {string}   opts.type        - Job type identifier
   * @param {object}   opts.payload     - Arbitrary data
   * @param {number}   [opts.priority]  - Lower = higher priority (default 5)
   * @param {number}   [opts.maxRetries]
   */
  enqueue({ type, payload, priority = 5, maxRetries = 3 }) {
    const job = {
      id: crypto.randomUUID(),
      type,
      payload,
      priority,
      maxRetries,
      attempts: 0,
      status: JobStatus.PENDING,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      error: null,
      result: null,
    };

    this.#jobs.set(job.id, job);
    this.#insertByPriority(job.id, priority);
    this.emit("jobAdded", job);

    return job;
  }

  /** Insert job id into the pending list sorted by priority */
  #insertByPriority(id, priority) {
    const idx = this.#pending.findIndex((pendingId) => {
      const j = this.#jobs.get(pendingId);
      return j && j.priority > priority;
    });
    if (idx === -1) {
      this.#pending.push(id);
    } else {
      this.#pending.splice(idx, 0, id);
    }
  }

  /** Dequeue the highest-priority pending job */
  dequeue() {
    while (this.#pending.length > 0) {
      const id = this.#pending.shift();
      const job = this.#jobs.get(id);
      if (job && job.status === JobStatus.PENDING) {
        job.status = JobStatus.RUNNING;
        job.attempts++;
        job.updatedAt = Date.now();
        return job;
      }
    }
    return null;
  }

  /** Mark a job as completed */
  complete(id, result) {
    const job = this.#jobs.get(id);
    if (!job) return;
    job.status = JobStatus.COMPLETED;
    job.result = result;
    job.updatedAt = Date.now();
    this.emit("jobCompleted", job);
  }

  /**
   * Mark a job as failed.
   * If retries remain, re-enqueue it.
   * @returns {boolean} true if it will be retried
   */
  fail(id, error) {
    const job = this.#jobs.get(id);
    if (!job) return false;

    job.error = error.message || String(error);
    job.updatedAt = Date.now();

    if (job.attempts < job.maxRetries) {
      job.status = JobStatus.RETRYING;
      this.emit("jobRetrying", job);

      // Re-enqueue after exponential back-off delay
      const delayMs = Math.min(1000 * 2 ** job.attempts, 30000);
      setTimeout(() => {
        job.status = JobStatus.PENDING;
        this.#insertByPriority(job.id, job.priority);
        this.emit("jobAdded", job); // notify worker
      }, delayMs);

      return true;
    }

    job.status = JobStatus.FAILED;
    this.emit("jobFailed", job);
    return false;
  }

  get size() {
    return this.#pending.length;
  }

  get stats() {
    const all = [...this.#jobs.values()];
    return {
      total: all.length,
      pending: all.filter((j) => j.status === JobStatus.PENDING).length,
      running: all.filter((j) => j.status === JobStatus.RUNNING).length,
      completed: all.filter((j) => j.status === JobStatus.COMPLETED).length,
      failed: all.filter((j) => j.status === JobStatus.FAILED).length,
      retrying: all.filter((j) => j.status === JobStatus.RETRYING).length,
    };
  }
}

module.exports = { JobQueue, JobStatus };
```

### `src/worker.js` — Background Worker

```javascript
const { EventEmitter } = require("events");

/**
 * Background worker that:
 *  1. Pulls jobs from the queue
 *  2. Waits for a rate-limit token before executing
 *  3. Runs the matching handler
 *  4. Retries on failure (handled by the queue)
 */
class Worker extends EventEmitter {
  #queue;
  #limiter;
  #handlers;   // Map<jobType, async function>
  #concurrency;
  #activeJobs;
  #running;
  #pollTimer;

  /**
   * @param {object}  opts
   * @param {JobQueue}              opts.queue
   * @param {TokenBucketLimiter|SlidingWindowLimiter} opts.limiter
   * @param {number}                [opts.concurrency]  max parallel jobs
   * @param {number}                [opts.pollIntervalMs]
   */
  constructor({ queue, limiter, concurrency = 3, pollIntervalMs = 500 }) {
    super();
    this.#queue = queue;
    this.#limiter = limiter;
    this.#handlers = new Map();
    this.#concurrency = concurrency;
    this.#activeJobs = 0;
    this.#running = false;
    this.#pollTimer = null;

    // Also wake up whenever a new job is added
    this.#queue.on("jobAdded", () => this.#tick());
  }

  /** Register a handler for a job type */
  register(type, handler) {
    this.#handlers.set(type, handler);
    return this; // allow chaining
  }

  /** Start the worker loop */
  start() {
    if (this.#running) return;
    this.#running = true;
    this.#limiter.start();

    // Periodic poll as a safety net
    this.#pollTimer = setInterval(() => this.#tick(), 500);
    this.#pollTimer.unref();

    this.emit("started");
    this.#tick(); // kick off immediately
  }

  /** Gracefully stop (waits for active jobs to finish) */
  async stop() {
    this.#running = false;

    if (this.#pollTimer) {
      clearInterval(this.#pollTimer);
      this.#pollTimer = null;
    }

    // Wait until all active jobs drain
    while (this.#activeJobs > 0) {
      await new Promise((r) => setTimeout(r, 100));
    }

    this.#limiter.stop();
    this.emit("stopped");
  }

  /** Core loop: dequeue + rate-limit + execute */
  async #tick() {
    // Spawn as many concurrent jobs as allowed
    while (
      this.#running &&
      this.#activeJobs < this.#concurrency &&
      this.#queue.size > 0
    ) {
      const job = this.#queue.dequeue();
      if (!job) break;

      this.#activeJobs++;
      // Don't await — run concurrently
      this.#processJob(job).finally(() => {
        this.#activeJobs--;
        // Try to pick up more work
        if (this.#running) this.#tick();
      });
    }
  }

  async #processJob(job) {
    const handler = this.#handlers.get(job.type);
    if (!handler) {
      this.#queue.fail(job.id, new Error(`No handler for job type "${job.type}"`));
      return;
    }

    try {
      // ── Wait for rate-limit token ──
      const waitMs = await this.#limiter.waitForToken();
      if (waitMs > 0) {
        this.emit("rateLimitWait", { jobId: job.id, waitMs });
      }

      // ── Execute the handler ──
      this.emit("jobStarted", job);
      const result = await handler(job.payload, job);
      this.#queue.complete(job.id, result);
    } catch (err) {
      const willRetry = this.#queue.fail(job.id, err);
      this.emit("jobError", { job, error: err, willRetry });
    }
  }

  get stats() {
    return {
      running: this.#running,
      activeJobs: this.#activeJobs,
      concurrency: this.#concurrency,
      queue: this.#queue.stats,
      rateLimiter: this.#limiter.stats,
    };
  }
}

module.exports = { Worker };
```

