  console.log(`  ▶ Job ${job.id.slice(0, 8)} [${job.type}] attempt #${job.attempts}`);
});

worker.on("jobError", ({ job, error, willRetry }) => {
  const action = willRetry ? "will retry" : "GAVE UP";
  console.log(`  ✖ Job ${job.id.slice(0, 8)} failed: ${error.message} (${action})`);
});

queue.on("jobCompleted", (job) => {
  console.log(`  ✔ Job ${job.id.slice(0, 8)} completed:`, job.result);
});

queue.on("jobFailed", (job) => {
  console.log(`  ✖ Job ${job.id.slice(0, 8)} permanently failed: ${job.error}`);
});

// ─── Enqueue Demo Jobs ──────────────────────────────────
