  // Enqueue 15 API jobs — more than the token bucket allows at once
  for (let i = 1; i <= 12; i++) {
    queue.enqueue({
      type: "api-call",
      payload: { userId: i },
      priority: i <= 3 ? 1 : 5, // first 3 are high priority
    });
  }

