  for (const to of ["alice@test.com", "bob@test.com", "carol@test.com"]) {
    queue.enqueue({ type: "send-email", payload: { to }, priority: 3 });
  }

  console.log("Queue stats:", queue.stats, "\n");

  // Periodically print worker stats
  const statsTimer = setInterval(() => {
    const s = worker.stats;
    console.log(
      `\n📊 active=${s.activeJobs}/${s.concurrency}  ` +
        `queue=${s.queue.pending} pending / ${s.queue.completed} done / ${s.queue.failed} failed  ` +
        `tokens=${s.rateLimiter.availableTokens ?? "n/a"}\n`
    );
  }, 3000);

  // Let it run for 20 seconds, then shut down gracefully
  setTimeout(async () => {
    clearInterval(statsTimer);
    console.log("\n⏹  Shutting down...");
    await worker.stop();
    console.log("Final stats:", worker.stats);
    process.exit(0);
