## The Fixed & Improved Code

```javascript
// ✅ FIXED VERSION — scheduler.js

const EventEmitter = require('events');

class SearchIndexScheduler extends EventEmitter {
  constructor(options = {}) {
    super();

    // FIX 1: Validate options and provide safe defaults
    this.batchSize = options.batchSize || 50;
    this.interval = options.interval || 30_000;        // 30s default
    this.maxRetries = options.maxRetries || 3;
    this.retryDelay = options.retryDelay || 5_000;     // 5s backoff base
    this.concurrency = options.concurrency || 2;
    this.maxQueueSize = options.maxQueueSize || 10_000; // back-pressure

    this.indexQueue = [];
    this.processingSet = new Set();                     // dedup guard
    this.isRunning = false;
    this.activeJobs = 0;
    this.schedulerTimer = null;
    this.stats = { processed: 0, failed: 0, retries: 0 };

    if (!options.db) throw new Error('options.db is required');
    if (!options.searchClient) throw new Error('options.searchClient is required');

    this.db = options.db;
    this.searchClient = options.searchClient;
  }

  /* ---------------------------------------------------------------
   * Lifecycle
   * ------------------------------------------------------------- */

  start() {
    if (this.isRunning) {
      this.emit('warn', 'Scheduler is already running');
      return;
    }

    this.isRunning = true;
    this.emit('started');
    console.log('[Scheduler] Started');

    // FIX 3: Run immediately, THEN repeat on the interval
    this.processBatch();

    // FIX 2: Arrow function preserves `this` context
    this.schedulerTimer = setInterval(() => {
      this.processBatch();
    }, this.interval);
  }

  stop() {
    if (!this.isRunning) return;

    this.isRunning = false;

    // FIX 4: Clear the timer so it actually stops
    if (this.schedulerTimer) {
      clearInterval(this.schedulerTimer);
      this.schedulerTimer = null;
    }

    this.emit('stopped', { stats: { ...this.stats } });
    console.log('[Scheduler] Stopped', this.stats);
  }

  /** Graceful shutdown — waits for active jobs to drain */
  async shutdown(timeoutMs = 10_000) {
    this.stop();                             // stop accepting new ticks

    const deadline = Date.now() + timeoutMs;
    while (this.activeJobs > 0 && Date.now() < deadline) {
      await new Promise(r => setTimeout(r, 200));
    }

    if (this.activeJobs > 0) {
      this.emit('warn', `Forced shutdown with ${this.activeJobs} active jobs`);
    }
    this.emit('shutdown');
  }

  /* ---------------------------------------------------------------
   * Enqueue
   * ------------------------------------------------------------- */

  // FIX 5 & 6: Validate, flatten, and deduplicate incoming IDs
  enqueue(documentIds) {
    if (!Array.isArray(documentIds)) {
      documentIds = [documentIds];
    }

    const unique = documentIds.filter(id => {
      if (id == null) return false;                    // skip null/undefined
      if (this.processingSet.has(id)) return false;    // already in-flight
      if (this.indexQueue.includes(id)) return false;  // already queued
      return true;
    });

    // Back-pressure: reject if queue is full
    if (this.indexQueue.length + unique.length > this.maxQueueSize) {
      this.emit('warn', 'Queue is full — dropping new items');
      return { accepted: 0, dropped: unique.length };
    }

    // FIX 6: Spread individual IDs, not the whole array
    this.indexQueue.push(...unique);
    this.emit('enqueued', { count: unique.length, queueSize: this.indexQueue.length });

    return { accepted: unique.length, dropped: 0 };
  }

  /* ---------------------------------------------------------------
   * Core Processing
   * ------------------------------------------------------------- */

  // FIX 8: Full try/catch + event-driven monitoring (FIX 9)
  async processBatch() {
    if (!this.isRunning) return;
    if (this.activeJobs >= this.concurrency) {
      this.emit('skipped', 'Max concurrency reached');
      return;
    }

    // FIX 7: splice() removes items from the queue (not slice)
    const batch = this.indexQueue.splice(0, this.batchSize);
    if (batch.length === 0) return;

    // Track in-flight IDs for dedup
    batch.forEach(id => this.processingSet.add(id));
    this.activeJobs++;

    try {
      const documents = await this.fetchDocuments(batch);
      const transformed = this.transformForIndex(documents);
      const result = await this.indexDocuments(transformed);

      this.stats.processed += transformed.length;

      // FIX 9: Emit events for monitoring / observability
      this.emit('batch:complete', {
        count: transformed.length,
        stats: { ...this.stats },
      });
    } catch (error) {
      this.stats.failed += batch.length;
      this.emit('batch:error', { error, batchIds: batch });

      // Put failed items back at the front for retry
      this.requeueWithRetry(batch);
    } finally {
      batch.forEach(id => this.processingSet.delete(id));
      this.activeJobs--;
    }
  }

  /* ---------------------------------------------------------------
   * Database Fetch
   * ------------------------------------------------------------- */

  // FIX 10: Handle partial results and missing/deleted documents
  async fetchDocuments(ids) {
    const docs = await this.db.findByIds(ids);

    const found = new Set(docs.map(d => d.id));
    const missing = ids.filter(id => !found.has(id));

    if (missing.length > 0) {
      this.emit('warn', `Missing documents skipped: ${missing.join(', ')}`);
    }

    return docs; // only return what actually exists
  }

  /* ---------------------------------------------------------------
   * Transform
   * ------------------------------------------------------------- */

  // FIX 11: Null-safe field access with optional chaining & defaults
  transformForIndex(documents) {
    return documents
      .filter(doc => doc && doc.id)              // skip totally invalid docs
      .map(doc => ({
        id: doc.id,
        title: (doc.title ?? '').toLowerCase(),
        body: (doc.body ?? '').toLowerCase(),
        tags: Array.isArray(doc.tags) ? doc.tags.join(',') : '',
        indexedAt: new Date().toISOString(),
      }));
  }

  /* ---------------------------------------------------------------
   * Indexing with Retry
   * ------------------------------------------------------------- */

  // FIX 12: Retry with exponential back-off + per-item error handling
  async indexDocuments(documents, attempt = 1) {
    try {
      const result = await this.searchClient.bulkIndex(documents);

      // Handle partial failures returned by the search engine
      if (result?.errors) {
        const failed = result.items
          .filter(item => item.index?.error)
          .map(item => item.index._id);

        this.emit('index:partialFailure', { failedIds: failed });
      }

      return result;
    } catch (error) {
      if (attempt >= this.maxRetries) {
        this.emit('index:failed', {
          error,
          documents: documents.map(d => d.id),
          attempts: attempt,
        });
        throw error; // bubble up after final retry
      }

      this.stats.retries++;
      const delay = this.retryDelay * 2 ** (attempt - 1); // exponential
      this.emit('index:retry', { attempt, nextIn: delay });

      await new Promise(r => setTimeout(r, delay));
      return this.indexDocuments(documents, attempt + 1);
    }
  }

  /** Put IDs back at the front of the queue (max 1 retry cycle) */
  requeueWithRetry(ids) {
    const requeue = ids.filter(id => !this._retriedOnce?.has(id));
    if (requeue.length === 0) return;

    this._retriedOnce ??= new Set();
    requeue.forEach(id => this._retriedOnce.add(id));
    this.indexQueue.unshift(...requeue);
  }

  /* ---------------------------------------------------------------
   * Diagnostics
   * ------------------------------------------------------------- */

  getStatus() {
    return {
      running: this.isRunning,
      queueSize: this.indexQueue.length,
      activeJobs: this.activeJobs,
      stats: { ...this.stats },
    };
  }
}

module.exports = SearchIndexScheduler;
