# Document Parser with Retry Logic

## Implementation

```javascript
// ============================================
// Document Parser with Retry Handling
// ============================================

class DocumentParser {
  constructor(options = {}) {
    this.maxRetries = options.maxRetries || 3;
    this.baseDelay = options.baseDelay || 1000;       // 1 second
    this.maxDelay = options.maxDelay || 10000;         // 10 seconds
    this.backoffFactor = options.backoffFactor || 2;
  }

  // --- Core retry wrapper ---
  async withRetry(fn, context = "operation") {
    let lastError;

    for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
      try {
        console.log(`[Attempt ${attempt}/${this.maxRetries}] Starting ${context}...`);
        const result = await fn(attempt);
        console.log(`[Attempt ${attempt}] ${context} succeeded.`);
        return result;
      } catch (error) {
        lastError = error;
        console.warn(`[Attempt ${attempt}] ${context} failed: ${error.message}`);

        // Don't wait after the last attempt
        if (attempt < this.maxRetries) {
          const delay = this.calculateDelay(attempt);
          console.log(`  Retrying in ${delay}ms...`);
          await this.sleep(delay);
        }
      }
    }

    throw new Error(
      `${context} failed after ${this.maxRetries} attempts. Last error: ${lastError.message}`
    );
  }

  // --- Delay calculation with exponential backoff + jitter ---
  calculateDelay(attempt) {
    const exponentialDelay = this.baseDelay * Math.pow(this.backoffFactor, attempt - 1);
    const jitter = Math.random() * this.baseDelay * 0.5;
    return Math.min(exponentialDelay + jitter, this.maxDelay);
  }

  sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  // --- Parse JSON document ---
  async parseJSON(input) {
    return this.withRetry(() => {
      if (!input || typeof input !== "string") {
        throw new Error("Invalid input: expected a non-empty string");
      }
      return JSON.parse(input);
    }, "JSON parsing");
  }

  // --- Parse CSV document ---
  async parseCSV(input, delimiter = ",") {
    return this.withRetry(() => {
      if (!input || typeof input !== "string") {
        throw new Error("Invalid input: expected a non-empty string");
      }

      const lines = input.trim().split("\n");
      if (lines.length === 0) {
        throw new Error("Empty CSV document");
      }

      const headers = lines[0].split(delimiter).map((h) => h.trim());
      const rows = [];

      for (let i = 1; i < lines.length; i++) {
        const values = lines[i].split(delimiter).map((v) => v.trim());
        if (values.length !== headers.length) {
          throw new Error(`Row ${i} has ${values.length} columns, expected ${headers.length}`);
        }
        const row = {};
        headers.forEach((header, index) => {
          row[header] = values[index];
        });
        rows.push(row);
      }

      return { headers, rows };
    }, "CSV parsing");
  }

  // --- Fetch and parse remote document ---
  async fetchAndParse(url, format = "json") {
    return this.withRetry(async (attempt) => {
      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const text = await response.text();

      switch (format.toLowerCase()) {
        case "json":
          return JSON.parse(text);
        case "csv":
          return this.parseCSVString(text);
        default:
          return text;
      }
    }, `fetching ${format.toUpperCase()} from ${url}`);
  }

  // --- Synchronous CSV helper (used inside fetchAndParse) ---
  parseCSVString(input, delimiter = ",") {
    const lines = input.trim().split("\n");
    const headers = lines[0].split(delimiter).map((h) => h.trim());
    return lines.slice(1).map((line) => {
      const values = line.split(delimiter).map((v) => v.trim());
      const row = {};
      headers.forEach((h, i) => (row[h] = values[i]));
      return row;
    });
  }
}

// ============================================
// Usage Examples
// ============================================

async function main() {
  const parser = new DocumentParser({
    maxRetries: 3,
    baseDelay: 500,
  });

  // --- Example 1: Parse valid JSON ---
  console.log("=== JSON Parsing ===");
  try {
    const jsonData = await parser.parseJSON(
      '{"name": "Alice", "age": 30, "roles": ["admin", "user"]}'
    );
    console.log("Parsed JSON:", jsonData);
  } catch (error) {
    console.error("Final error:", error.message);
  }

  // --- Example 2: Parse CSV ---
  console.log("\n=== CSV Parsing ===");
  try {
    const csvInput = `name,age,city
Alice,30,New York
Bob,25,London
Charlie,35,Tokyo`;

    const csvData = await parser.parseCSV(csvInput);
    console.log("Headers:", csvData.headers);
    console.log("Rows:", csvData.rows);
  } catch (error) {
    console.error("Final error:", error.message);
  }

  // --- Example 3: Handle invalid JSON (triggers retries) ---
  console.log("\n=== Invalid JSON (will retry and fail) ===");
  try {
    await parser.parseJSON("{invalid json content}");
  } catch (error) {
    console.error("Final error:", error.message);
  }

  // --- Example 4: Simulate flaky parsing ---
  console.log("\n=== Flaky Operation (succeeds on 3rd try) ===");
  let callCount = 0;
  try {
    const result = await parser.withRetry(() => {
      callCount++;
      if (callCount < 3) {
        throw new Error(`Simulated failure #${callCount}`);
      }
      return { status: "success", data: [1, 2, 3] };
    }, "flaky document parse");
    console.log("Result:", result);
  } catch (error) {
    console.error("Final error:", error.message);
  }
}

main();
