## `src/utils/checksum.js`

```javascript
import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";

/**
 * Computes a streaming file checksum without loading the entire file into memory.
 *
 * @param {string} filePath  — Absolute path to the file.
 * @param {string} algorithm — Hash algorithm (e.g. "sha256", "md5").
 * @returns {Promise<string>} Hex-encoded hash string.
 */
export function computeChecksum(filePath, algorithm = "sha256") {
  return new Promise((resolve, reject) => {
    const hash = createHash(algorithm);
    const stream = createReadStream(filePath, { highWaterMark: 64 * 1024 });

    stream.on("data", (chunk) => hash.update(chunk));
    stream.on("end", () => resolve(hash.digest("hex")));
    stream.on("error", (err) => {
      stream.destroy();
      reject(new Error(`Checksum failed for "${filePath}": ${err.message}`));
    });
  });
}
```

## `src/utils/glob.js`

```javascript
/**
 * Minimal glob / pattern matcher.
 * Supports:
 *   *      — any sequence of non-separator characters
 *   **     — any sequence including separators (recursive)
 *   ?      — any single character
 *   [abc]  — character class
 *
 * All patterns are matched against the *relative* path inside the sync root.
 */

/**
 * Converts a glob pattern to a RegExp.
 * @param {string} pattern
 * @returns {RegExp}
 */
export function globToRegex(pattern) {
  let i = 0;
  let regex = "^";
  const len = pattern.length;

  while (i < len) {
    const ch = pattern[i];

    switch (ch) {
      case "*":
        if (pattern[i + 1] === "*") {
          // "**" matches everything including path separators
          regex += ".*";
          i += 2;
          // Skip an optional trailing slash after **
          if (pattern[i] === "/") i++;
        } else {
          // "*" matches everything except path separators
          regex += "[^/]*";
          i++;
        }
        break;

      case "?":
        regex += "[^/]";
        i++;
        break;

      case "[": {
        // Pass through character classes as-is
        const close = pattern.indexOf("]", i);
        if (close === -1) {
          regex += "\\[";
          i++;
        } else {
          regex += pattern.slice(i, close + 1);
          i = close + 1;
        }
        break;
      }

      case ".":
      case "(":
      case ")":
      case "+":
      case "^":
      case "$":
      case "{":
      case "}":
      case "|":
      case "\\":
        regex += `\\${ch}`;
        i++;
        break;

      default:
        regex += ch;
        i++;
    }
  }

  regex += "$";
  return new RegExp(regex, "i"); // case-insensitive by default
}

/**
 * Returns true when `relativePath` matches at least one pattern in the list.
 *
 * @param {string}   relativePath — Forward-slash-separated relative path.
 * @param {string[]} patterns     — Array of glob patterns.
 * @returns {boolean}
 */
export function matchesAny(relativePath, patterns) {
  if (!patterns || patterns.length === 0) return false;

  // Normalise to forward slashes
  const normalized = relativePath.replace(/\\/g, "/");
  const basename = normalized.split("/").pop();

  return patterns.some((p) => {
    const re = globToRegex(p);
    // Match against full relative path AND the bare filename
    return re.test(normalized) || re.test(basename);
  });
}
