## `src/utils/retry.js`

```javascript
/**
 * Retries an async function up to `maxAttempts` times with exponential back-off.
 *
 * @param {() => Promise<T>} fn
 * @param {object}           opts
 * @param {number}           opts.maxAttempts  — Total attempts (including the first).
 * @param {number}           opts.delayMs      — Initial delay between retries.
 * @param {number}           [opts.factor=2]   — Back-off multiplier.
 * @param {(err: Error, attempt: number) => void} [opts.onRetry]
 * @returns {Promise<T>}
 * @template T
 */
export async function retry(fn, opts) {
  const { maxAttempts = 3, delayMs = 1000, factor = 2, onRetry } = opts;

  let lastError;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;

      if (attempt === maxAttempts) break;

      if (typeof onRetry === "function") {
        onRetry(err, attempt);
      }

      const jitter = Math.random() * 200;
      const wait = delayMs * Math.pow(factor, attempt - 1) + jitter;
      await new Promise((r) => setTimeout(r, wait));
    }
  }

  throw lastError;
}
