```javascript
import { mkdirSync, appendFileSync, existsSync, statSync, renameSync } from "node:fs";
import { dirname, resolve } from "node:path";

const LEVELS = /** @type {const} */ ({
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
  silent: 4,
});

/**
 * Lightweight structured logger that writes to stdout and optionally to a file
 * with automatic size-based rotation.
 */
export class Logger {
  /** @type {keyof typeof LEVELS} */
  #level;
  /** @type {string | null} */
  #filePath;
  /** @type {number} */
  #maxBytes;
  /** @type {boolean} */
  #console;

  /**
   * @param {object}  opts
   * @param {string}  [opts.level="info"]
   * @param {string}  [opts.file]
   * @param {number}  [opts.maxSizeMB=50]
   * @param {boolean} [opts.console=true]
   */
  constructor({ level = "info", file = null, maxSizeMB = 50, console: con = true } = {}) {
    this.#level = level in LEVELS ? level : "info";
    this.#filePath = file ? resolve(file) : null;
    this.#maxBytes = maxSizeMB * 1024 * 1024;
    this.#console = con;

    if (this.#filePath) {
      mkdirSync(dirname(this.#filePath), { recursive: true });
    }
  }

  /* ---- public API ---- */

  debug(msg, meta) { this.#log("debug", msg, meta); }
  info(msg, meta)  { this.#log("info", msg, meta); }
  warn(msg, meta)  { this.#log("warn", msg, meta); }
  error(msg, meta) { this.#log("error", msg, meta); }

  /* ---- internals ---- */

  #log(level, msg, meta) {
    if (LEVELS[level] < LEVELS[this.#level]) return;

    const entry = {
      ts: new Date().toISOString(),
      level,
      msg,
      ...(meta !== undefined && { meta }),
    };

    const line = JSON.stringify(entry);

    if (this.#console) {
      const writer = level === "error" ? process.stderr : process.stdout;
      writer.write(line + "\n");
    }

    if (this.#filePath) {
      this.#rotateIfNeeded();
      appendFileSync(this.#filePath, line + "\n", "utf-8");
    }
  }

  #rotateIfNeeded() {
    try {
      if (!existsSync(this.#filePath)) return;
      const { size } = statSync(this.#filePath);
      if (size < this.#maxBytes) return;

      const rotated = `${this.#filePath}.${Date.now()}.bak`;
      renameSync(this.#filePath, rotated);
    } catch {
      // Best-effort rotation — don't crash the sync
    }
  }
}
