## `src/ConfigLoader.js`

```javascript
import { readFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";

/**
 * @typedef {object} TaskConfig
 * @property {string}   name
 * @property {boolean}  enabled
 * @property {string}   source
 * @property {string}   destination
 * @property {"one-way"|"mirror"|"two-way"} mode
 * @property {boolean}  deleteOrphaned
 * @property {boolean}  preserveTimestamps
 * @property {string}   checksum
 * @property {string[]} exclude
 * @property {string[]} include
 * @property {number}   maxConcurrency
 * @property {number}   retryAttempts
 * @property {number}   retryDelayMs
 * @property {number}   maxFileSizeMB
 * @property {"newest"|"source"|"destination"} conflictResolution
 */

/**
 * Loads, validates, and merges sync configuration from a JSON file.
 */
export class ConfigLoader {
  /**
   * @param {string} configPath — Path to the JSON config file.
   * @param {object} [cliOverrides] — CLI-level overrides (e.g. --dry-run).
   * @returns {{ logging: object, tasks: TaskConfig[] }}
   */
  static load(configPath, cliOverrides = {}) {
    const absPath = resolve(configPath);

    if (!existsSync(absPath)) {
      throw new Error(`Configuration file not found: ${absPath}`);
    }

    let raw;
    try {
      raw = JSON.parse(readFileSync(absPath, "utf-8"));
    } catch (err) {
      throw new Error(`Invalid JSON in config file "${absPath}": ${err.message}`);
    }

    ConfigLoader.#validate(raw);

    const defaults = raw.defaults ?? {};
    const logging = { ...{ level: "info", console: true }, ...raw.logging };

    const tasks = (raw.tasks ?? [])
      .filter((t) => t.enabled !== false)
      .map((t) => ConfigLoader.#mergeTask(defaults, t, cliOverrides));

    return { logging, tasks };
  }

  /* ---- validation ---- */

  static #validate(raw) {
    if (!raw || typeof raw !== "object") {
      throw new Error("Config must be a JSON object.");
    }
    if (!Array.isArray(raw.tasks) || raw.tasks.length === 0) {
      throw new Error('Config must contain a non-empty "tasks" array.');
    }

    const names = new Set();
    for (const [i, task] of raw.tasks.entries()) {
      if (!task.name || typeof task.name !== "string") {
        throw new Error(`Task at index ${i} is missing a "name" string.`);
      }
      if (names.has(task.name)) {
        throw new Error(`Duplicate task name: "${task.name}".`);
      }
      names.add(task.name);

      if (!task.source || typeof task.source !== "string") {
        throw new Error(`Task "${task.name}" is missing a "source" path.`);
      }
      if (!task.destination || typeof task.destination !== "string") {
        throw new Error(`Task "${task.name}" is missing a "destination" path.`);
      }
      if (task.mode && !["one-way", "mirror", "two-way"].includes(task.mode)) {
        throw new Error(
          `Task "${task.name}" has invalid mode "${task.mode}". ` +
          `Allowed: one-way, mirror, two-way.`
        );
      }
    }
  }

  /* ---- merge defaults + task + CLI overrides ---- */

  /**
   * @param {object} defaults
   * @param {object} task
   * @param {object} cli
   * @returns {TaskConfig}
   */
  static #mergeTask(defaults, task, cli) {
    return {
      name:               task.name,
      enabled:            true,
      source:             resolve(task.source),
      destination:        resolve(task.destination),
      mode:               task.mode ?? defaults.mode ?? "one-way",
      deleteOrphaned:     task.deleteOrphaned ?? defaults.deleteOrphaned ?? false,
      preserveTimestamps: task.preserveTimestamps ?? defaults.preserveTimestamps ?? true,
      checksum:           task.checksum ?? defaults.checksum ?? "sha256",
      exclude:            mergeArrays(defaults.exclude, task.exclude),
      include:            task.include ?? defaults.include ?? [],
      maxConcurrency:     task.maxConcurrency ?? defaults.maxConcurrency ?? 8,
      retryAttempts:      task.retryAttempts ?? defaults.retryAttempts ?? 3,
      retryDelayMs:       task.retryDelayMs ?? defaults.retryDelayMs ?? 1000,
      maxFileSizeMB:      task.maxFileSizeMB ?? defaults.maxFileSizeMB ?? Infinity,
      conflictResolution: task.conflictResolution ?? defaults.conflictResolution ?? "newest",
      // CLI overrides always win
      dryRun:             cli.dryRun ?? false,
    };
  }
}

/** Merges two optional arrays, deduplicating entries. */
function mergeArrays(a, b) {
  return [...new Set([...(a ?? []), ...(b ?? [])])];
}
