## `src/FileComparator.js`

```javascript
import { stat } from "node:fs/promises";
import { computeChecksum } from "./utils/checksum.js";

/**
 * @typedef {"create"|"update"|"delete"|"conflict"} ActionType
 *
 * @typedef {object} FileAction
 * @property {ActionType} action
 * @property {string}     relativePath
 * @property {string}     sourcePath
 * @property {string}     destPath
 * @property {string}     [reason]
 */

/**
 * Compares two file entries and decides what sync action (if any) is needed.
 */
export class FileComparator {
  /** @type {string} */
  #algorithm;

  /** @param {string} algorithm — Checksum algorithm. */
  constructor(algorithm = "sha256") {
    this.#algorithm = algorithm;
  }

  /**
   * Quick comparison by size + mtime.  Returns `true` when files appear identical.
   *
   * @param {import("node:fs").Stats} srcStat
   * @param {import("node:fs").Stats} dstStat
   * @returns {boolean}
   */
  quickCompare(srcStat, dstStat) {
    if (srcStat.size !== dstStat.size) return false;
    // Allow 2-second tolerance for FAT32 / network timestamps
    return Math.abs(srcStat.mtimeMs - dstStat.mtimeMs) < 2000;
  }

  /**
   * Deep comparison via cryptographic checksum.
   *
   * @param {string} srcPath
   * @param {string} dstPath
   * @returns {Promise<boolean>}
   */
  async deepCompare(srcPath, dstPath) {
    const [srcHash, dstHash] = await Promise.all([
      computeChecksum(srcPath, this.#algorithm),
      computeChecksum(dstPath, this.#algorithm),
    ]);
    return srcHash === dstHash;
  }

  /**
   * Full comparison pipeline: quick check first, then checksum if needed.
   *
   * @param {string} srcPath
   * @param {string} dstPath
   * @returns {Promise<{identical: boolean, srcStat: import("node:fs").Stats, dstStat: import("node:fs").Stats}>}
   */
  async compare(srcPath, dstPath) {
    const [srcStat, dstStat] = await Promise.all([stat(srcPath), stat(dstPath)]);

    if (this.quickCompare(srcStat, dstStat)) {
      return { identical: true, srcStat, dstStat };
    }

    const identical = await this.deepCompare(srcPath, dstPath);
    return { identical, srcStat, dstStat };
  }
}
