## Basic JSON Parser

```javascript
// ============================================
// Simple JSON Document Parser
// ============================================

class JSONDocumentParser {
  constructor() {
    this.data = null;
    this.errors = [];
  }

  // --- Parse JSON from a string ---
  parseString(jsonString) {
    try {
      this.data = JSON.parse(jsonString);
      this.errors = [];
      console.log("✅ JSON parsed successfully.");
      return this.data;
    } catch (error) {
      this.errors.push(error.message);
      console.error("❌ Parse error:", error.message);
      return null;
    }
  }

  // --- Parse JSON from a file (Node.js) ---
  parseFile(filePath) {
    const fs = require("fs");
    try {
      const fileContent = fs.readFileSync(filePath, "utf-8");
      return this.parseString(fileContent);
    } catch (error) {
      this.errors.push(error.message);
      console.error("❌ File error:", error.message);
      return null;
    }
  }

  // --- Get a value by key path (e.g., "user.address.city") ---
  getValue(keyPath) {
    if (!this.data) {
      console.error("❌ No data loaded.");
      return undefined;
    }

    const keys = keyPath.split(".");
    let current = this.data;

    for (const key of keys) {
      if (current === null || current === undefined) {
        return undefined;
      }
      // Handle array index access like "items.0.name"
      current = Array.isArray(current) ? current[parseInt(key)] : current[key];
    }

    return current;
  }

  // --- List all keys (flattened) ---
  getKeys(obj = this.data, prefix = "") {
    let keys = [];

    if (obj && typeof obj === "object") {
      for (const key of Object.keys(obj)) {
        const fullKey = prefix ? `${prefix}.${key}` : key;
        keys.push(fullKey);
        keys = keys.concat(this.getKeys(obj[key], fullKey));
      }
    }

    return keys;
  }

  // --- Search for a key anywhere in the document ---
  search(searchKey) {
    const results = [];

    const traverse = (obj, path = "") => {
      if (!obj || typeof obj !== "object") return;

      for (const [key, value] of Object.entries(obj)) {
        const currentPath = path ? `${path}.${key}` : key;

        if (key === searchKey) {
          results.push({ path: currentPath, value });
        }

        if (typeof value === "object" && value !== null) {
          traverse(value, currentPath);
        }
      }
    };

    traverse(this.data);
    return results;
  }

  // --- Get a summary of the document ---
  getSummary() {
    if (!this.data) return "No data loaded.";

    return {
      type: Array.isArray(this.data) ? "array" : typeof this.data,
      topLevelKeys: typeof this.data === "object" ? Object.keys(this.data) : [],
      totalKeys: this.getKeys().length,
      errors: this.errors,
    };
  }

  // --- Pretty print the parsed data ---
  prettyPrint() {
    if (!this.data) {
      console.log("No data loaded.");
      return;
    }
    console.log(JSON.stringify(this.data, null, 2));
  }
}
