## Elasticsearch Indexer

```javascript
// src/indexer.js
import { Client } from '@elastic/elasticsearch';
import config from '../config.js';

export class SearchIndexer {
  constructor() {
    this.client = new Client(config.elasticsearch);
  }

  /**
   * Bulk index/update/delete documents in Elasticsearch.
   * Returns { successful, failed } with details.
   */
  async bulkIndex(operations) {
    if (operations.length === 0) return { successful: [], failed: [] };

    const body = operations.flatMap((op) => {
      switch (op.action) {
        case 'upsert':
          return [
            { index: { _index: op.index, _id: op.docId } },
            op.document,
          ];
        case 'delete':
          return [{ delete: { _index: op.index, _id: op.docId } }];
        default:
          throw new Error(`Unknown action: ${op.action}`);
      }
    });

    const { items, errors } = await this.client.bulk({
      body,
      refresh: false,       // don't force refresh on every batch
      timeout: '30s',
    });

    const successful = [];
    const failed = [];

    // Walk results, correlating back to input operations
    let opIndex = 0;
    for (const item of items) {
      const [action] = Object.keys(item);
      const result = item[action];

      if (result.error) {
        failed.push({
          operation: operations[opIndex],
          error: result.error,
          status: result.status,
        });
      } else {
        successful.push(operations[opIndex]);
      }
      opIndex++;
    }

    return { successful, failed };
  }

  async ping() {
    const resp = await this.client.ping();
    return resp.statusCode === 200;
  }

  async close() {
    await this.client.close();
  }
}
```

## Dead Letter Queue Handler

```javascript
// src/dlq.js
import { Queue } from 'bullmq';
import config from '../config.js';

/**
 * Handles permanently failed jobs — stores them
 * for inspection and manual replay.
 */
export class DeadLetterHandler {
  constructor() {
    this.dlq = new Queue(`${config.queue.name}:dlq`, {
      connection: config.redis,
    });
  }

  async send(originalJob, error) {
    await this.dlq.add('failed-index-op', {
      originalData: originalJob.data,
      jobId: originalJob.id,
      failedAt: new Date().toISOString(),
      attempts: originalJob.attemptsMade,
      error: {
        message: error.message,
        stack: error.stack,
      },
    }, {
      removeOnComplete: false,   // keep for inspection
      removeOnFail: false,
    });

    console.error(`[DLQ] Job ${originalJob.id} moved to dead letter queue`, {
      reason: error.message,
    });
  }

  async close() {
    await this.dlq.close();
  }
}
```

## Core Consumer with Batching

```javascript
// src/consumer.js
import { Worker } from 'bullmq';
import config from '../config.js';
import { SearchIndexer } from './indexer.js';
import { DeadLetterHandler } from './dlq.js';

export class IndexingConsumer {
  #worker = null;
  #indexer;
  #dlq;
  #batch = [];
  #batchTimer = null;
  #isShuttingDown = false;
  #stats = { processed: 0, failed: 0, batches: 0 };

  constructor() {
    this.#indexer = new SearchIndexer();
    this.#dlq = new DeadLetterHandler();
  }

  start() {
    this.#worker = new Worker(
      config.queue.name,
      (job) => this.#handleJob(job),
      {
        connection: config.redis,
        concurrency: config.queue.concurrency,
        limiter: {
          max: 100,          // rate limit: 100 jobs
          duration: 1_000,   // per second
        },
        settings: {
          backoffStrategy: (attemptsMade) => {
            // exponential: 1s, 2s, 4s ...
            return Math.min(1000 * 2 ** attemptsMade, 30_000);
          },
        },
      },
    );

    this.#worker.on('completed', (job) => {
      this.#stats.processed++;
    });

    this.#worker.on('failed', (job, err) => {
      this.#stats.failed++;
      console.error(`[Consumer] Job ${job?.id} failed: ${err.message}`);

      // If exhausted all retries, send to DLQ
      if (job && job.attemptsMade >= config.retry.maxAttempts) {
        this.#dlq.send(job, err).catch(console.error);
      }
    });

    this.#worker.on('error', (err) => {
      console.error('[Consumer] Worker error:', err.message);
    });

    console.log(`[Consumer] Listening on queue "${config.queue.name}"`);
  }

  /**
   * Process a single job — validates, transforms, and batches it.
   */
  async #handleJob(job) {
    const { action, index, docId, document, timestamp } = job.data;

    // --- Validation ---
    if (!action || !index || !docId) {
      throw new Error(`Invalid job payload: missing required fields (job ${job.id})`);
    }
    if (action === 'upsert' && !document) {
      throw new Error(`Upsert requires a document body (job ${job.id})`);
    }

    // --- Transform ---
    const operation = {
      action,
      index,
      docId,
      document: action === 'upsert'
        ? { ...document, _indexed_at: new Date().toISOString() }
        : undefined,
      jobId: job.id,
    };

    // --- Batch or flush ---
    return this.#addToBatch(operation);
  }

  /**
   * Accumulate operations and flush when batch is full or timeout fires.
   */
  #addToBatch(operation) {
    return new Promise((resolve, reject) => {
      this.#batch.push({ operation, resolve, reject });

      if (this.#batch.length >= config.queue.batchSize) {
        this.#flushBatch();
      } else if (!this.#batchTimer) {
        this.#batchTimer = setTimeout(
          () => this.#flushBatch(),
          config.queue.batchTimeoutMs,
        );
      }
    });
  }

  async #flushBatch() {
    clearTimeout(this.#batchTimer);
    this.#batchTimer = null;

    // Swap out the current batch atomically
    const pending = this.#batch.splice(0);
    if (pending.length === 0) return;

    const operations = pending.map((p) => p.operation);

    try {
      const { successful, failed } = await this.#indexer.bulkIndex(operations);
      this.#stats.batches++;

      console.log(
        `[Consumer] Batch indexed: ${successful.length} ok, ${failed.length} failed`,
      );

      // Resolve successful, reject failed so BullMQ can retry them
      const failedJobIds = new Set(failed.map((f) => f.operation.jobId));

      for (const entry of pending) {
        if (failedJobIds.has(entry.operation.jobId)) {
          const match = failed.find((f) => f.operation.jobId === entry.operation.jobId);
          entry.reject(new Error(`ES bulk error: ${JSON.stringify(match.error)}`));
        } else {
          entry.resolve();
        }
      }
    } catch (err) {
      // Total failure (network, ES down) — reject everything for retry
      console.error('[Consumer] Bulk request failed:', err.message);
      for (const entry of pending) {
        entry.reject(err);
      }
    }
  }

  /**
   * Graceful shutdown: finish in-flight work, flush remaining batch.
   */
  async stop() {
    if (this.#isShuttingDown) return;
    this.#isShuttingDown = true;

    console.log('[Consumer] Shutting down...');

    // Stop accepting new jobs, wait for in-flight to finish
    if (this.#worker) {
      await this.#worker.close();
    }

    // Flush any remaining batched operations
    await this.#flushBatch();

    await this.#indexer.close();
    await this.#dlq.close();

    console.log('[Consumer] Shut down cleanly', this.#stats);
  }

  get stats() {
    return { ...this.#stats };
  }
}
