## Health Check Endpoint

```javascript
// src/health.js
import http from 'node:http';

/**
 * Minimal health endpoint for container orchestrators.
 */
export function startHealthServer(consumer, indexer, port = 8081) {
  const server = http.createServer(async (req, res) => {
    if (req.url !== '/health') {
      res.writeHead(404).end();
      return;
    }

    try {
      const esHealthy = await indexer.ping();
      const stats = consumer.stats;

      const status = esHealthy ? 200 : 503;
      res.writeHead(status, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: esHealthy ? 'healthy' : 'degraded',
        elasticsearch: esHealthy,
        stats,
        uptime: process.uptime(),
      }));
    } catch {
      res.writeHead(503).end(JSON.stringify({ status: 'unhealthy' }));
    }
  });

  server.listen(port, () => {
    console.log(`[Health] Listening on :${port}/health`);
  });

  return server;
}
