## `lib/store.js` — File-based Log Storage

```javascript
import fs from "node:fs";
import path from "node:path";
import os from "node:os";

const DEFAULT_LOG_DIR = path.join(os.homedir(), ".audit-logger");
const DEFAULT_LOG_FILE = path.join(DEFAULT_LOG_DIR, "audit.json");

export class AuditStore {
  #filepath;

  constructor(filepath = DEFAULT_LOG_FILE) {
    this.#filepath = filepath;
    this.#ensureFile();
  }

  #ensureFile() {
    const dir = path.dirname(this.#filepath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    if (!fs.existsSync(this.#filepath)) {
      fs.writeFileSync(this.#filepath, "[]", "utf-8");
    }
  }

  readAll() {
    const raw = fs.readFileSync(this.#filepath, "utf-8");
    return JSON.parse(raw);
  }

  append(entry) {
    const entries = this.readAll();
    entries.push(entry);
    fs.writeFileSync(this.#filepath, JSON.stringify(entries, null, 2), "utf-8");
    return entry;
  }

  query(filters = {}) {
    let entries = this.readAll();

    if (filters.user) {
      entries = entries.filter(
        (e) => e.user.toLowerCase() === filters.user.toLowerCase()
      );
    }

    if (filters.action) {
      entries = entries.filter(
        (e) => e.action.toLowerCase() === filters.action.toLowerCase()
      );
    }

    if (filters.since) {
      const sinceDate = new Date(filters.since);
      entries = entries.filter((e) => new Date(e.timestamp) >= sinceDate);
    }

    if (filters.until) {
      const untilDate = new Date(filters.until);
      entries = entries.filter((e) => new Date(e.timestamp) <= untilDate);
    }

    if (filters.limit) {
      entries = entries.slice(-filters.limit);
    }

    return entries;
  }

  clear() {
    fs.writeFileSync(this.#filepath, "[]", "utf-8");
  }

  get filepath() {
    return this.#filepath;
  }
}
```

## `lib/logger.js` — Entry Creation & Validation

```javascript
import crypto from "node:crypto";

const VALID_SEVERITIES = ["info", "warn", "error", "critical"];

export class AuditLogger {
  #store;

  constructor(store) {
    this.#store = store;
  }

  log({ user, action, resource = "", detail = "", severity = "info" }) {
    if (!user || !action) {
      throw new Error("Both --user and --action are required.");
    }

    if (!VALID_SEVERITIES.includes(severity)) {
      throw new Error(
        `Invalid severity "${severity}". Use: ${VALID_SEVERITIES.join(", ")}`
      );
    }

    const entry = {
      id: crypto.randomUUID(),
      timestamp: new Date().toISOString(),
      user,
      action,
      resource,
      detail,
      severity,
    };

    return this.#store.append(entry);
  }

  list(filters) {
    return this.#store.query(filters);
  }

  stats() {
    const entries = this.#store.readAll();
    const users = new Set(entries.map((e) => e.user));
    const actions = new Set(entries.map((e) => e.action));

    const bySeverity = {};
    for (const e of entries) {
      bySeverity[e.severity] = (bySeverity[e.severity] || 0) + 1;
    }

    return {
      totalEntries: entries.length,
      uniqueUsers: users.size,
      uniqueActions: actions.size,
      bySeverity,
    };
  }

  clear() {
    this.#store.clear();
  }
}
