## `lib/formatter.js` — Terminal Output Formatting

```javascript
const SEVERITY_COLORS = {
  info: "\x1b[36m",     // cyan
  warn: "\x1b[33m",     // yellow
  error: "\x1b[31m",    // red
  critical: "\x1b[35m", // magenta
};
const RESET = "\x1b[0m";
const BOLD = "\x1b[1m";
const DIM = "\x1b[2m";

export function formatEntry(entry) {
  const color = SEVERITY_COLORS[entry.severity] || "";
  const time = new Date(entry.timestamp).toLocaleString();

  let line = `${DIM}${time}${RESET} `;
  line += `${color}[${entry.severity.toUpperCase().padEnd(8)}]${RESET} `;
  line += `${BOLD}${entry.user}${RESET} `;
  line += `→ ${entry.action}`;

  if (entry.resource) {
    line += ` on ${BOLD}${entry.resource}${RESET}`;
  }
  if (entry.detail) {
    line += ` ${DIM}(${entry.detail})${RESET}`;
  }

  return line;
}

export function formatTable(entries) {
  if (entries.length === 0) {
    return "  No entries found.";
  }
  return entries.map(formatEntry).join("\n");
}

export function formatStats(stats) {
  let out = `\n${BOLD}Audit Log Statistics${RESET}\n`;
  out += `${"─".repeat(30)}\n`;
  out += `  Total entries:   ${stats.totalEntries}\n`;
  out += `  Unique users:    ${stats.uniqueUsers}\n`;
  out += `  Unique actions:  ${stats.uniqueActions}\n`;
  out += `\n  By severity:\n`;

  for (const [sev, count] of Object.entries(stats.bySeverity)) {
    const color = SEVERITY_COLORS[sev] || "";
    out += `    ${color}${sev.padEnd(10)}${RESET} ${count}\n`;
  }

  return out;
}

export function formatJSON(data) {
  return JSON.stringify(data, null, 2);
}
```

## `bin/audit.js` — CLI Entry Point

```javascript
#!/usr/bin/env node

import { AuditStore } from "../lib/store.js";
import { AuditLogger } from "../lib/logger.js";
import { formatTable, formatStats, formatJSON } from "../lib/formatter.js";

// ── Argument Parser ──────────────────────────────────

function parseArgs(argv) {
  const args = argv.slice(2);
  const command = args[0] || "help";
  const flags = {};

  for (let i = 1; i < args.length; i++) {
    if (args[i].startsWith("--")) {
      const key = args[i].slice(2);
      const next = args[i + 1];
      // treat next token as value unless it's another flag
      if (next && !next.startsWith("--")) {
        flags[key] = next;
        i++;
      } else {
        flags[key] = true;
      }
    }
  }

  return { command, flags };
}

// ── Help Text ────────────────────────────────────────

function printHelp() {
  console.log(`
  \x1b[1maudit-logger\x1b[0m — CLI audit logging tool

  \x1b[1mUSAGE\x1b[0m
    audit <command> [options]

  \x1b[1mCOMMANDS\x1b[0m
    log       Record a new audit entry
    list      View audit entries (with optional filters)
    stats     Show summary statistics
    export    Dump all entries as JSON
    clear     Remove all entries
    help      Show this message

  \x1b[1mOPTIONS FOR "log"\x1b[0m
    --user       (required)  Who performed the action
    --action     (required)  What was done
    --resource               Target resource
    --detail                 Additional context
    --severity               info | warn | error | critical  (default: info)

  \x1b[1mOPTIONS FOR "list"\x1b[0m
    --user       Filter by user
    --action     Filter by action
    --since      Start date  (ISO 8601)
    --until      End date    (ISO 8601)
    --limit      Max entries to show
    --json       Output as JSON

  \x1b[1mEXAMPLES\x1b[0m
    audit log --user alice --action "deleted file" --resource /tmp/data.csv --severity warn
    audit list --user alice --since 2025-01-01
    audit stats
    audit export > backup.json
    audit clear
  `);
}

// ── Command Handlers ─────────────────────────────────

function handleLog(logger, flags) {
  try {
    const entry = logger.log({
      user: flags.user,
      action: flags.action,
      resource: flags.resource || "",
      detail: flags.detail || "",
      severity: flags.severity || "info",
    });
    console.log(`✓ Logged [${entry.id}]`);
  } catch (err) {
    console.error(`✗ ${err.message}`);
    process.exit(1);
  }
}

function handleList(logger, flags) {
  const filters = {
    user: flags.user,
    action: flags.action,
    since: flags.since,
    until: flags.until,
    limit: flags.limit ? parseInt(flags.limit, 10) : undefined,
  };

  const entries = logger.list(filters);

  if (flags.json) {
    console.log(formatJSON(entries));
  } else {
    console.log(formatTable(entries));
  }
}

function handleStats(logger) {
  const stats = logger.stats();
  console.log(formatStats(stats));
}

function handleExport(logger) {
  const entries = logger.list();
  console.log(formatJSON(entries));
}

function handleClear(logger) {
  logger.clear();
  console.log("✓ Audit log cleared.");
}

// ── Main ─────────────────────────────────────────────

function main() {
  const { command, flags } = parseArgs(process.argv);
  const store = new AuditStore();
  const logger = new AuditLogger(store);

  const commands = {
    log: () => handleLog(logger, flags),
    list: () => handleList(logger, flags),
    stats: () => handleStats(logger),
    export: () => handleExport(logger),
    clear: () => handleClear(logger),
    help: () => printHelp(),
  };

  if (commands[command]) {
    commands[command]();
  } else {
    console.error(`Unknown command: "${command}". Run "audit help".`);
    process.exit(1);
  }
}

main();
```

## Usage

```bash
# Link globally so "audit" works from anywhere
npm link

# Log some events
audit log --user alice --action "created user" --resource users/bob --severity info
audit log --user bob   --action "deleted file" --resource /tmp/report.csv --severity warn
audit log --user alice --action "login failed" --severity error --detail "bad password"

# View all entries
audit list

# Filter by user + date range
audit list --user alice --since 2025-01-01

# Last 5 entries as JSON
audit list --limit 5 --json

# Summary stats
audit stats

# Export full log for backup
audit export > audit-backup.json

# Wipe the log
audit clear
```

