// Defines how different metric types are aggregated

class AggregationStrategies {
  static count(existing, _value) {
    return (existing || 0) + 1;
  }

  static sum(existing, value) {
    return (existing || 0) + value;
  }

  static min(existing, value) {
    return existing === undefined ? value : Math.min(existing, value);
  }

  static max(existing, value) {
    return existing === undefined ? value : Math.max(existing, value);
  }

  // Collects all values for later percentile / average computation
  static collect(existing, value) {
    const list = existing || [];
    list.push(value);
    return list;
  }

  // ---- Derived computations (run on collected arrays) ----

  static average(values) {
    if (!Array.isArray(values) || values.length === 0) return 0;
    return values.reduce((a, b) => a + b, 0) / values.length;
  }

  static percentile(values, p) {
    if (!Array.isArray(values) || values.length === 0) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const idx = Math.ceil((p / 100) * sorted.length) - 1;
    return sorted[Math.max(0, idx)];
  }

  static stddev(values) {
    if (!Array.isArray(values) || values.length === 0) return 0;
    const avg = AggregationStrategies.average(values);
    const sqDiffs = values.map((v) => (v - avg) ** 2);
    return Math.sqrt(sqDiffs.reduce((a, b) => a + b, 0) / values.length);
  }
}

module.exports = AggregationStrategies;
