```javascript
const { EventEmitter } = require("events");
const AggregationStrategies = require("./strategies/AggregationStrategies");

/**
 * Collects raw metrics and provides aggregated views.
 *
 * Metric definitions look like:
 *   { name: 'records.processed', type: 'count' }
 *   { name: 'latency.ms',       type: 'collect' }   // stores every value
 *   { name: 'payload.bytes',    type: 'sum' }
 */
class MetricsAggregator extends EventEmitter {
  constructor() {
    super();
    /** @type {Map<string, { type: string, value: any }>} */
    this.metrics = new Map();
    this.tags = new Map();            // optional dimensional tags
    this.startTime = Date.now();
    this.snapshots = [];              // periodic snapshots
    this._intervals = [];
  }

  // ──────────────── Registration ────────────────

  /**
   * Register a metric before use.
   * @param {string} name   Dot-separated metric name
   * @param {'count'|'sum'|'min'|'max'|'collect'} type  Aggregation strategy
   * @param {Record<string, string>} [metricTags]
   */
  register(name, type = "count", metricTags = {}) {
    if (this.metrics.has(name)) {
      throw new Error(`Metric "${name}" is already registered.`);
    }

    const strategy = AggregationStrategies[type];
    if (typeof strategy !== "function") {
      throw new Error(`Unknown aggregation type: "${type}"`);
    }

    this.metrics.set(name, { type, value: undefined });
    if (Object.keys(metricTags).length) {
      this.tags.set(name, metricTags);
    }
    return this;
  }

  // ──────────────── Recording ────────────────

  /**
   * Record a value for a metric.
   * @param {string} name
   * @param {number} [value=1]
   */
  record(name, value = 1) {
    const metric = this.metrics.get(name);
    if (!metric) {
      throw new Error(
        `Metric "${name}" not registered. Call register() first.`
      );
    }

    const strategy = AggregationStrategies[metric.type];
    metric.value = strategy(metric.value, value);

    this.emit("metric:recorded", { name, value, aggregated: metric.value });
    return this;
  }

  /** Convenience: start a timer that returns an `end()` function. */
  startTimer(name) {
    const start = process.hrtime.bigint();
    return {
      end: () => {
        const elapsed = Number(process.hrtime.bigint() - start) / 1e6; // ms
        this.record(name, elapsed);
        return elapsed;
      },
    };
  }

  // ──────────────── Retrieval ────────────────

  /** Get raw aggregated value for a metric. */
  get(name) {
    const metric = this.metrics.get(name);
    return metric ? metric.value : undefined;
  }

  /** Get a derived statistic for 'collect'-type metrics. */
  getStat(name, stat, ...args) {
    const metric = this.metrics.get(name);
    if (!metric || metric.type !== "collect") {
      throw new Error(`"${name}" is not a 'collect'-type metric.`);
    }

    const fn = AggregationStrategies[stat];
    if (typeof fn !== "function") {
      throw new Error(`Unknown stat: "${stat}"`);
    }
    return fn(metric.value || [], ...args);
  }

  /** Return a plain object summary of every metric. */
  summarize() {
    const summary = {
      durationMs: Date.now() - this.startTime,
      metrics: {},
    };

    for (const [name, metric] of this.metrics) {
      const entry = { type: metric.type };
      const tags = this.tags.get(name);
      if (tags) entry.tags = tags;

      if (metric.type === "collect") {
        const vals = metric.value || [];
        entry.count = vals.length;
        entry.average = AggregationStrategies.average(vals);
        entry.min = vals.length ? Math.min(...vals) : null;
        entry.max = vals.length ? Math.max(...vals) : null;
        entry.p50 = AggregationStrategies.percentile(vals, 50);
        entry.p95 = AggregationStrategies.percentile(vals, 95);
        entry.p99 = AggregationStrategies.percentile(vals, 99);
        entry.stddev = AggregationStrategies.stddev(vals);
      } else {
        entry.value = metric.value ?? 0;
      }

      summary.metrics[name] = entry;
    }

    return summary;
  }

  // ──────────────── Snapshots ────────────────

  /** Take a point-in-time snapshot. */
  snapshot(label = "") {
    const snap = { label, timestamp: Date.now(), ...this.summarize() };
    this.snapshots.push(snap);
    this.emit("metric:snapshot", snap);
    return snap;
  }

  /** Start automatic periodic snapshots. */
  startPeriodicSnapshots(intervalMs = 5000) {
    const id = setInterval(() => this.snapshot("periodic"), intervalMs);
    this._intervals.push(id);
    return this;
  }

  // ──────────────── Reset / Cleanup ────────────────

  reset() {
    for (const metric of this.metrics.values()) {
      metric.value = undefined;
    }
    this.snapshots = [];
    this.startTime = Date.now();
  }

  destroy() {
    this._intervals.forEach(clearInterval);
    this._intervals = [];
    this.removeAllListeners();
  }
}

module.exports = MetricsAggregator;
```

