const { EventEmitter } = require("events");

/**
 * Processes items in configurable batches with concurrency control.
 */
class BatchProcessor extends EventEmitter {
  /**
   * @param {object} opts
   * @param {number} [opts.batchSize=100]
   * @param {number} [opts.concurrency=3]     Batches processed in parallel
   * @param {number} [opts.retries=2]
   * @param {number} [opts.retryDelayMs=500]
   */
  constructor(opts = {}) {
    super();
    this.batchSize = opts.batchSize || 100;
    this.concurrency = opts.concurrency || 3;
    this.retries = opts.retries ?? 2;
    this.retryDelayMs = opts.retryDelayMs ?? 500;
  }

  /**
   * Process all items using the given handler.
   * @param {Array}    items
   * @param {Function} handler  async (batch, batchIndex) => results[]
   * @returns {Promise<{ results: any[], errors: any[] }>}
   */
  async process(items, handler) {
    const batches = this._chunk(items, this.batchSize);
    const results = [];
    const errors = [];

    this.emit("start", { totalItems: items.length, totalBatches: batches.length });

    // Process batches with bounded concurrency
    let batchIndex = 0;
    const pending = new Set();

    for (const batch of batches) {
      const idx = batchIndex++;
      const task = this._processBatch(batch, idx, handler, results, errors);
      pending.add(task);
      task.finally(() => pending.delete(task));

      if (pending.size >= this.concurrency) {
        await Promise.race(pending);        // wait for one slot to free
      }
    }

    await Promise.all(pending);             // drain remaining

    this.emit("complete", { results, errors });
    return { results, errors };
  }

  // ── private ──

  async _processBatch(batch, index, handler, results, errors) {
    let attempt = 0;

    while (attempt <= this.retries) {
      try {
        this.emit("batch:start", { index, size: batch.length, attempt });
        const batchResults = await handler(batch, index);
        results.push(...(batchResults || []));
        this.emit("batch:success", { index, size: batch.length, attempt });
        return;
      } catch (err) {
        attempt++;
        this.emit("batch:error", { index, attempt, error: err.message });

        if (attempt > this.retries) {
          errors.push({ batchIndex: index, items: batch, error: err.message });
          this.emit("batch:failed", { index, error: err.message });
          return;
        }
        await this._delay(this.retryDelayMs * attempt);   // exponential-ish
      }
    }
  }

  _chunk(arr, size) {
    const chunks = [];
    for (let i = 0; i < arr.length; i += size) {
      chunks.push(arr.slice(i, i + size));
    }
    return chunks;
  }

  _delay(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

module.exports = BatchProcessor;
