/**
 * Prints live progress and a final summary to the console.
 */
class ConsoleReporter {
  constructor(metrics, processor) {
    this._attachMetrics(metrics);
    this._attachProcessor(processor);
  }

  _attachMetrics(metrics) {
    metrics.on("metric:snapshot", (snap) => {
      const m = snap.metrics;
      const processed = m["records.processed"]?.value ?? 0;
      const failed = m["records.failed"]?.value ?? 0;
      const avgLatency = m["batch.latency.ms"]?.average?.toFixed(1) ?? "-";
      console.log(
        `  [snapshot] processed=${processed}  failed=${failed}  avgBatchLatency=${avgLatency}ms`
      );
    });
  }

  _attachProcessor(processor) {
    processor.on("start", ({ totalItems, totalBatches }) => {
      console.log(`\n🚀  Migration started — ${totalItems} items in ${totalBatches} batches\n`);
    });

    processor.on("batch:start", ({ index, size, attempt }) => {
      const retryLabel = attempt > 0 ? ` (retry #${attempt})` : "";
      console.log(`  ▸ batch ${index}  [${size} items]${retryLabel}`);
    });

    processor.on("batch:error", ({ index, attempt, error }) => {
      console.warn(`  ⚠  batch ${index} attempt ${attempt} failed: ${error}`);
    });

    processor.on("batch:failed", ({ index, error }) => {
      console.error(`  ✖  batch ${index} permanently failed: ${error}`);
    });

    processor.on("complete", () => {
      console.log("\n✅  All batches processed.\n");
    });
  }

  /** Call after migration to print the full summary. */
  printSummary(summary) {
    console.log("═".repeat(60));
    console.log("  MIGRATION SUMMARY");
    console.log("═".repeat(60));
    console.log(`  Total duration : ${(summary.durationMs / 1000).toFixed(2)}s`);
    console.log("");

    for (const [name, data] of Object.entries(summary.metrics)) {
      if (data.type === "collect") {
        console.log(`  ${name}`);
        console.log(`      count  : ${data.count}`);
        console.log(`      avg    : ${data.average.toFixed(2)}`);
        console.log(`      min    : ${data.min?.toFixed(2)}`);
        console.log(`      max    : ${data.max?.toFixed(2)}`);
        console.log(`      p50    : ${data.p50.toFixed(2)}`);
        console.log(`      p95    : ${data.p95.toFixed(2)}`);
        console.log(`      p99    : ${data.p99.toFixed(2)}`);
        console.log(`      stddev : ${data.stddev.toFixed(2)}`);
      } else {
        console.log(`  ${name} : ${data.value}`);
      }
    }

    console.log("═".repeat(60));
  }
}

module.exports = ConsoleReporter;
