/**
 * Writes the final summary + all snapshots to a JSON file.
 */
class JsonFileReporter {
  /**
   * @param {string} outputDir  Directory where the report is written
   */
  constructor(outputDir = ".") {
    this.outputDir = outputDir;
  }

  async write(summary, snapshots = []) {
    const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
    const filename = `migration-report-${timestamp}.json`;
    const filepath = path.join(this.outputDir, filename);

    const report = {
      generatedAt: new Date().toISOString(),
      summary,
      snapshots,
    };

    await fs.mkdir(this.outputDir, { recursive: true });
    await fs.writeFile(filepath, JSON.stringify(report, null, 2), "utf-8");

    console.log(`📄  Report written to ${filepath}`);
    return filepath;
  }
}

module.exports = JsonFileReporter;
