## src/hash.js — File Integrity Hashing

```javascript
import { createHash } from "crypto";
import { createReadStream } from "fs";
import { stat } from "fs/promises";

/**
 * Compute a file hash without reading the entire file into memory.
 * Returns null if the file can't be read (deleted, locked, etc.)
 */
export async function hashFile(filePath, algorithm = "sha256") {
  try {
    const info = await stat(filePath);

    // Skip directories and very large files (>100MB)
    if (info.isDirectory() || info.size > 100 * 1024 * 1024) {
      return null;
    }

    return new Promise((resolve, reject) => {
      const hash = createHash(algorithm);
      const stream = createReadStream(filePath);

      stream.on("data", (chunk) => hash.update(chunk));
      stream.on("end", () => resolve(hash.digest("hex")));
      stream.on("error", () => resolve(null)); // don't crash on read errors
    });
  } catch {
    return null;
  }
}

/**
 * Get basic file metadata for the audit record.
 */
export async function getFileMeta(filePath) {
  try {
    const info = await stat(filePath);
    return {
      size: info.size,
      mode: info.mode.toString(8),
      uid: info.uid,
      gid: info.gid,
      created: info.birthtime.toISOString(),
      modified: info.mtime.toISOString(),
    };
  } catch {
    return null;
  }
}
