## src/formatter.js — Log Formatting

```javascript
/**
 * Build a structured audit record from a file event.
 */
export function formatAuditRecord(event, filePath, extra = {}) {
  const record = {
    timestamp: new Date().toISOString(),
    event,
    path: filePath,
    pid: process.pid,
    user: process.env.USER || process.env.USERNAME || "unknown",
    ...extra,
  };

  // Remove null/undefined fields to keep logs clean
  return Object.fromEntries(
    Object.entries(record).filter(([, v]) => v != null)
  );
}

/**
 * Serialize a record to a single JSON line (JSONL format).
 * JSONL is easy to parse, grep, and ingest into log aggregators.
 */
export function toJSONL(record) {
  return JSON.stringify(record);
}

/**
 * Human-readable format for console output.
 */
export function toReadable(record) {
  const icon = {
    add: "✚",
    change: "✎",
    unlink: "✖",
    addDir: "📁+",
    unlinkDir: "📁-",
    ready: "✔",
    error: "⚠",
  }[record.event] || "•";

  const meta = record.hash ? ` [${record.hash.slice(0, 12)}…]` : "";
  const size = record.meta?.size != null ? ` (${formatBytes(record.meta.size)})` : "";

  return `${record.timestamp} ${icon} ${record.event.padEnd(10)} ${record.path}${size}${meta}`;
}

function formatBytes(bytes) {
  if (bytes === 0) return "0 B";
  const units = ["B", "KB", "MB", "GB"];
  const i = Math.floor(Math.log(bytes) / Math.log(1024));
  return `${(bytes / 1024 ** i).toFixed(1)} ${units[i]}`;
}
