## src/audit-logger.js — Log Writer with Rotation

```javascript
import { createWriteStream, existsSync, mkdirSync, statSync, readdirSync, unlinkSync } from "fs";
import { join } from "path";
import { toJSONL, toReadable } from "./formatter.js";

export class AuditLogger {
  #stream = null;
  #currentFile = null;
  #bytesWritten = 0;
  #config;

  constructor(config) {
    this.#config = config;

    // Ensure log directory exists
    if (!existsSync(config.dir)) {
      mkdirSync(config.dir, { recursive: true });
    }

    this.#openNewFile();
  }

  /**
   * Write a structured audit record.
   */
  write(record) {
    // Always print to console (human-readable)
    console.log(toReadable(record));

    // Write JSONL to file (machine-readable)
    const line = toJSONL(record) + "\n";
    const bytes = Buffer.byteLength(line);

    // Rotate if current file is too large
    if (this.#bytesWritten + bytes > this.#config.rotateAfterBytes) {
      this.#rotate();
    }

    this.#stream.write(line);
    this.#bytesWritten += bytes;
  }

  /**
   * Graceful shutdown — flush pending writes.
   */
  close() {
    return new Promise((resolve) => {
      if (this.#stream) {
        this.#stream.end(resolve);
      } else {
        resolve();
      }
    });
  }

  #openNewFile() {
    const filename = `audit-${this.#fileTimestamp()}.jsonl`;
    this.#currentFile = join(this.#config.dir, filename);
    this.#stream = createWriteStream(this.#currentFile, { flags: "a" });
    this.#bytesWritten = 0;

    // Check if we're appending to an existing file
    try {
      this.#bytesWritten = statSync(this.#currentFile).size;
    } catch {
      // New file
    }

    this.#stream.on("error", (err) => {
      console.error(`Audit log write error: ${err.message}`);
    });
  }

  #rotate() {
    this.#stream.end();
    this.#pruneOldFiles();
    this.#openNewFile();
  }

  #pruneOldFiles() {
    try {
      const files = readdirSync(this.#config.dir)
        .filter((f) => f.startsWith("audit-") && f.endsWith(".jsonl"))
        .sort()
        .reverse();

      // Keep only maxFiles, delete the rest
      for (const old of files.slice(this.#config.maxFiles)) {
        unlinkSync(join(this.#config.dir, old));
      }
    } catch (err) {
      console.error(`Log pruning error: ${err.message}`);
    }
  }

  #fileTimestamp() {
    return new Date().toISOString().replace(/[:.]/g, "-");
  }
}
