## src/watcher.js — Core File Watcher

```javascript
import chokidar from "chokidar";
import { hashFile, getFileMeta } from "./hash.js";
import { formatAuditRecord } from "./formatter.js";

export class FileWatcher {
  #watcher = null;
  #logger;
  #config;
  #isReady = false;

  // Track known hashes to detect actual content changes vs. mere touches
  #knownHashes = new Map();

  constructor(logger, config) {
    this.#logger = logger;
    this.#config = config;
  }

  /**
   * Start watching configured paths.
   */
  start() {
    const { watchPaths, watchOptions, events, logging } = this.#config;

    this.#watcher = chokidar.watch(watchPaths, watchOptions);

    // Register handlers for each enabled event type
    if (events.add) {
      this.#watcher.on("add", (path) => this.#handleFileEvent("add", path));
    }
    if (events.change) {
      this.#watcher.on("change", (path) => this.#handleFileEvent("change", path));
    }
    if (events.unlink) {
      this.#watcher.on("unlink", (path) => this.#handleRemove("unlink", path));
    }
    if (events.addDir) {
      this.#watcher.on("addDir", (path) => this.#handleRemove("addDir", path));
    }
    if (events.unlinkDir) {
      this.#watcher.on("unlinkDir", (path) => this.#handleRemove("unlinkDir", path));
    }

    // "ready" fires after the initial scan is complete
    this.#watcher.on("ready", () => {
      this.#isReady = true;
      const watched = this.#watcher.getWatched();
      const totalFiles = Object.values(watched).reduce((n, files) => n + files.length, 0);

      this.#logger.write(
        formatAuditRecord("ready", "-", {
          message: `Initial scan complete. Watching ${totalFiles} entries.`,
        })
      );
    });

    this.#watcher.on("error", (err) => {
      this.#logger.write(
        formatAuditRecord("error", "-", { message: err.message })
      );
    });

    return this;
  }

  /**
   * Stop the watcher and flush logs.
   */
  async stop() {
    if (this.#watcher) {
      await this.#watcher.close();
    }
    await this.#logger.close();
  }

  /**
   * Handle add/change events — compute hash + metadata.
   */
  async #handleFileEvent(event, filePath) {
    // During initial scan, optionally skip logging
    if (!this.#isReady && !this.#config.logging.logInitialScan) {
      return;
    }

    const [hash, meta] = await Promise.all([
      hashFile(filePath, this.#config.logging.hashAlgorithm),
      getFileMeta(filePath),
    ]);

    // For "change" events, skip if content hash is unchanged (metadata-only touch)
    if (event === "change" && hash) {
      const prevHash = this.#knownHashes.get(filePath);
      if (prevHash === hash) {
        return; // no actual content change
      }
    }

    if (hash) {
      this.#knownHashes.set(filePath, hash);
    }

    this.#logger.write(
      formatAuditRecord(event, filePath, {
        hash,
        meta,
        phase: this.#isReady ? "watch" : "initial-scan",
      })
    );
  }

  /**
   * Handle unlink/directory events — no hash needed.
   */
  #handleRemove(event, filePath) {
    this.#knownHashes.delete(filePath);

    this.#logger.write(
      formatAuditRecord(event, filePath, {
        phase: this.#isReady ? "watch" : "initial-scan",
      })
    );
  }
}
```

