### src/config.js

```javascript
const fs = require("node:fs");
const path = require("node:path");

class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = "ConfigError";
  }
}

class ConfigLoader {
  #config = {};
  #frozen = false;

  /**
   * Deep merge two objects. Source values override target values.
   */
  static deepMerge(target, source) {
    const result = { ...target };

    for (const key of Object.keys(source)) {
      const targetVal = target[key];
      const sourceVal = source[key];

      if (
        sourceVal &&
        typeof sourceVal === "object" &&
        !Array.isArray(sourceVal) &&
        targetVal &&
        typeof targetVal === "object" &&
        !Array.isArray(targetVal)
      ) {
        result[key] = ConfigLoader.deepMerge(targetVal, sourceVal);
      } else {
        result[key] = sourceVal;
      }
    }

    return result;
  }

  /**
   * Load a JSON config file. Returns empty object if file doesn't exist.
   */
  static loadJsonFile(filePath) {
    const resolved = path.resolve(filePath);

    if (!fs.existsSync(resolved)) {
      return {};
    }

    try {
      const content = fs.readFileSync(resolved, "utf-8");
      return JSON.parse(content);
    } catch (err) {
      throw new ConfigError(
        `Failed to parse config file "${resolved}": ${err.message}`
      );
    }
  }

  /**
   * Parse environment variable mapping.
   * Maps ENV_VAR names to config paths: { "DB_HOST": "database.host" }
   */
  static parseEnvMapping(mapping, env = process.env) {
    const result = {};

    for (const [envKey, configPath] of Object.entries(mapping)) {
      const value = env[envKey];
      if (value === undefined) continue;

      const keys = configPath.split(".");
      let current = result;

      for (let i = 0; i < keys.length - 1; i++) {
        current[keys[i]] = current[keys[i]] || {};
        current = current[keys[i]];
      }

      current[keys[keys.length - 1]] = ConfigLoader.coerceType(value);
    }

    return result;
  }

  /**
   * Coerce string env values to appropriate JS types.
   */
  static coerceType(value) {
    if (value === "true") return true;
    if (value === "false") return false;
    if (value === "null") return null;
    if (value === "") return value;

    const num = Number(value);
    if (!isNaN(num) && value.trim() !== "") return num;

    return value;
  }

  /**
   * Load config from directory with environment overlay.
   */
  loadFromDirectory(configDir, environment = null) {
    this.#assertNotFrozen();

    const env = environment || process.env.NODE_ENV || "development";
    const defaultConfig = ConfigLoader.loadJsonFile(
      path.join(configDir, "default.json")
    );
    const envConfig = ConfigLoader.loadJsonFile(
      path.join(configDir, `${env}.json`)
    );

    this.#config = ConfigLoader.deepMerge(
      ConfigLoader.deepMerge(this.#config, defaultConfig),
      envConfig
    );

    return this;
  }

  /**
   * Load environment variables using a mapping object.
   */
  loadFromEnv(mapping, env = process.env) {
    this.#assertNotFrozen();

    const envConfig = ConfigLoader.parseEnvMapping(mapping, env);
    this.#config = ConfigLoader.deepMerge(this.#config, envConfig);

    return this;
  }

  /**
   * Merge in a plain object.
   */
  merge(obj) {
    this.#assertNotFrozen();

    this.#config = ConfigLoader.deepMerge(this.#config, obj);
    return this;
  }

  /**
   * Get a value by dot-notation path.
   * Returns defaultValue if path doesn't exist.
   */
  get(keyPath, defaultValue = undefined) {
    const keys = keyPath.split(".");
    let current = this.#config;

    for (const key of keys) {
      if (current === null || current === undefined) return defaultValue;
      if (typeof current !== "object") return defaultValue;
      current = current[key];
    }

    return current !== undefined ? current : defaultValue;
  }

  /**
   * Check if a key path exists in the config.
   */
  has(keyPath) {
    const keys = keyPath.split(".");
    let current = this.#config;

    for (const key of keys) {
      if (current === null || typeof current !== "object") return false;
      if (!(key in current)) return false;
      current = current[key];
    }

    return true;
  }

  /**
   * Require specific keys to be present. Throws if any are missing.
   */
  validate(requiredKeys) {
    const missing = requiredKeys.filter((key) => !this.has(key));

    if (missing.length > 0) {
      throw new ConfigError(
        `Missing required config keys: ${missing.join(", ")}`
      );
    }

    return this;
  }

  /**
   * Freeze the config to prevent further modifications.
   */
  freeze() {
    this.#frozen = true;
    return this;
  }

  /**
   * Return the full config as a plain object (deep copy).
   */
  toObject() {
    return JSON.parse(JSON.stringify(this.#config));
  }

  #assertNotFrozen() {
    if (this.#frozen) {
      throw new ConfigError("Config is frozen and cannot be modified");
    }
  }
}

/**
 * Factory: create a fully loaded config in one call.
 */
function createConfig({ configDir, environment, envMapping, overrides } = {}) {
  const loader = new ConfigLoader();

  if (configDir) {
    loader.loadFromDirectory(configDir, environment);
  }

  if (envMapping) {
    loader.loadFromEnv(envMapping);
  }

  if (overrides) {
    loader.merge(overrides);
  }

  return loader;
}

module.exports = { ConfigLoader, ConfigError, createConfig };
```

