// ─── Helper: create temp config directory with JSON files ───

function createTempConfigDir(files) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "config-test-"));

  for (const [filename, content] of Object.entries(files)) {
    fs.writeFileSync(path.join(dir, filename), JSON.stringify(content));
  }

  // Cleanup helper
  const cleanup = () => fs.rmSync(dir, { recursive: true, force: true });
  return { dir, cleanup };
}

// ─── deepMerge ──────────────────────────────────────────────

describe("ConfigLoader.deepMerge", () => {
  it("merges flat objects", () => {
    const result = ConfigLoader.deepMerge({ a: 1, b: 2 }, { b: 3, c: 4 });
    assert.deepEqual(result, { a: 1, b: 3, c: 4 });
  });

  it("merges nested objects recursively", () => {
    const target = { db: { host: "localhost", port: 5432 } };
    const source = { db: { port: 3306, name: "test" } };
    const result = ConfigLoader.deepMerge(target, source);

    assert.deepEqual(result, {
      db: { host: "localhost", port: 3306, name: "test" },
    });
  });

  it("does not mutate original objects", () => {
    const target = { a: { b: 1 } };
    const source = { a: { c: 2 } };
    ConfigLoader.deepMerge(target, source);

    assert.deepEqual(target, { a: { b: 1 } });
    assert.deepEqual(source, { a: { c: 2 } });
  });

  it("replaces arrays instead of merging them", () => {
    const result = ConfigLoader.deepMerge(
      { tags: [1, 2, 3] },
      { tags: [4, 5] }
    );
    assert.deepEqual(result, { tags: [4, 5] });
  });

  it("handles empty objects", () => {
    assert.deepEqual(ConfigLoader.deepMerge({}, { a: 1 }), { a: 1 });
    assert.deepEqual(ConfigLoader.deepMerge({ a: 1 }, {}), { a: 1 });
  });
});

// ─── coerceType ─────────────────────────────────────────────

describe("ConfigLoader.coerceType", () => {
  it("converts 'true' to boolean true", () => {
    assert.equal(ConfigLoader.coerceType("true"), true);
  });

  it("converts 'false' to boolean false", () => {
    assert.equal(ConfigLoader.coerceType("false"), false);
  });

  it("converts 'null' to null", () => {
    assert.equal(ConfigLoader.coerceType("null"), null);
  });

  it("converts numeric strings to numbers", () => {
    assert.equal(ConfigLoader.coerceType("42"), 42);
    assert.equal(ConfigLoader.coerceType("3.14"), 3.14);
    assert.equal(ConfigLoader.coerceType("0"), 0);
