```javascript
// ✅ FIXED VERSION - searchIndexAPI.js
const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

// ─── FIX 1: Add JSON body parser middleware ──────────────────
app.use(express.json({ limit: '1mb' }));

// In-memory inverted index
let invertedIndex = {};
let documents = {};
let docIdCounter = 0;

// ─── FIX 2: Robust tokenizer with sanitization ──────────────
function tokenize(text) {
  if (!text || typeof text !== 'string') {
    return [];
  }
  return text
    .toLowerCase()                          // Normalize case
    .replace(/[^a-z0-9\s]/g, '')           // Strip special chars
    .split(/\s+/)                           // Split on whitespace
    .filter(token => token.length > 0);     // Remove empty tokens
}

// ─── FIX 3: Calculate TF for basic relevance scoring ─────────
function calculateTermFrequency(tokens) {
  const tf = {};
  tokens.forEach(token => {
    tf[token] = (tf[token] || 0) + 1;
  });
  return tf;
}

// ─── INDEX: Create/add a document ────────────────────────────
app.post('/index', (req, res, next) => {
  try {
    const { title, content } = req.body;

    // FIX 3: Input validation
    if (!title || !content) {
      return res.status(400).json({
        error: 'Both "title" and "content" fields are required'
      });
    }

    if (typeof title !== 'string' || typeof content !== 'string') {
      return res.status(400).json({
        error: '"title" and "content" must be strings'
      });
    }

    const docId = docIdCounter++;
    documents[docId] = { title, content, indexedAt: new Date().toISOString() };

    const tokens = tokenize(title + ' ' + content);
    const tf = calculateTermFrequency(tokens);

    // FIX 4: Use a Set per token to prevent duplicate docIds
    Object.keys(tf).forEach(token => {
      if (!invertedIndex[token]) {
        invertedIndex[token] = new Map();  // Map<docId, frequency>
      }
      invertedIndex[token].set(docId, tf[token]);
    });

    // FIX 5: Return 201 for resource creation
    res.status(201).json({
      id: docId,
      tokensIndexed: Object.keys(tf).length,
      message: 'Document indexed successfully'
    });
  } catch (err) {
    next(err);
  }
});

// ─── SEARCH: Query the index ─────────────────────────────────
app.get('/search', (req, res, next) => {
  try {
    const query = req.query.q;

    // FIX 7: Validate query parameter
    if (!query || typeof query !== 'string' || query.trim().length === 0) {
      return res.status(400).json({
        error: 'Query parameter "q" is required and must be non-empty'
      });
    }

    // FIX 6: Handle multi-word queries with AND logic + scoring
    const queryTokens = tokenize(query);

    if (queryTokens.length === 0) {
      return res.status(400).json({ error: 'Query produced no valid tokens' });
    }

    // Score documents: accumulate term frequency across query tokens
    const docScores = new Map();

    queryTokens.forEach(token => {
      const postingList = invertedIndex[token];
      if (postingList) {
        postingList.forEach((freq, docId) => {
          const currentScore = docScores.get(docId) || { score: 0, matchedTerms: 0 };
          currentScore.score += freq;
          currentScore.matchedTerms += 1;
          docScores.set(docId, currentScore);
        });
      }
    });

    // FIX 8: Return safe document copies, sorted by relevance
    const results = Array.from(docScores.entries())
      .map(([docId, { score, matchedTerms }]) => ({
        docId,
        score,
        matchedTerms,
        matchRatio: matchedTerms / queryTokens.length,  // % of query matched
        document: documents[docId]
          ? { title: documents[docId].title, content: documents[docId].content }
          : null
      }))
      .filter(r => r.document !== null)       // Exclude deleted docs
      .sort((a, b) => b.score - a.score);     // Sort by relevance

    res.json({
      query,
      tokens: queryTokens,
      totalResults: results.length,
      results
    });
  } catch (err) {
    next(err);
  }
});

// ─── DELETE: Remove a document and clean up index ────────────
app.delete('/documents/:id', (req, res, next) => {
  try {
    // FIX 10: Parse ID as integer for consistent comparison
    const docId = parseInt(req.params.id, 10);

    if (isNaN(docId)) {
      return res.status(400).json({ error: 'Document ID must be a number' });
    }

    if (!documents[docId]) {
      return res.status(404).json({ error: `Document ${docId} not found` });
    }

    // FIX 9: Clean up all index entries for this document
    Object.keys(invertedIndex).forEach(token => {
      invertedIndex[token].delete(docId);
      // Remove empty posting lists to save memory
      if (invertedIndex[token].size === 0) {
        delete invertedIndex[token];
      }
    });

    delete documents[docId];

    res.status(200).json({
      message: `Document ${docId} deleted and deindexed successfully`
    });
  } catch (err) {
    next(err);
  }
});

// ─── STATS: Index health endpoint ────────────────────────────
app.get('/stats', (_req, res) => {
  res.json({
    totalDocuments: Object.keys(documents).length,
    totalTerms: Object.keys(invertedIndex).length,
    nextDocId: docIdCounter
  });
});

// ─── BULK INDEX ──────────────────────────────────────────────
app.post('/index/bulk', (req, res, next) => {
  try {
    const { documents: docs } = req.body;

    if (!Array.isArray(docs) || docs.length === 0) {
      return res.status(400).json({ error: '"documents" must be a non-empty array' });
    }

    const results = [];
    const errors = [];

    docs.forEach((doc, idx) => {
      if (!doc.title || !doc.content) {
        errors.push({ index: idx, error: 'Missing title or content' });
        return;
      }

      const docId = docIdCounter++;
      documents[docId] = { ...doc, indexedAt: new Date().toISOString() };

      const tokens = tokenize(doc.title + ' ' + doc.content);
      const tf = calculateTermFrequency(tokens);

      Object.keys(tf).forEach(token => {
        if (!invertedIndex[token]) {
          invertedIndex[token] = new Map();
        }
        invertedIndex[token].set(docId, tf[token]);
      });

      results.push({ id: docId, title: doc.title });
    });

    res.status(201).json({ indexed: results, errors });
  } catch (err) {
    next(err);
  }
});

// ─── FIX 11: Global error handling middleware ────────────────
app.use((err, _req, res, _next) => {
  console.error(`[${new Date().toISOString()}] ERROR:`, err.message);
  console.error(err.stack);
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// 404 handler
app.use((_req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// ─── FIX 12: Graceful startup and shutdown ───────────────────
const server = app.listen(PORT, () => {
  console.log(`Search Index API running on http://localhost:${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => process.exit(0));
});

module.exports = app;  // For testing
```

