// fileSync.js
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

// ─── Configuration Loader ───────────────────────────────────

function loadConfig(configPath) {
  try {
    const raw = fs.readFileSync(configPath, "utf-8");
    const config = JSON.parse(raw);

    if (!config.jobs || !Array.isArray(config.jobs)) {
      throw new Error('Config must contain a "jobs" array');
    }

    // Validate each job
    config.jobs.forEach((job, index) => {
      if (!job.source) throw new Error(`Job ${index}: missing "source"`);
      if (!job.destination)
        throw new Error(`Job ${index}: missing "destination"`);
    });

    return config;
  } catch (err) {
    if (err.code === "ENOENT") {
      console.error(`Config file not found: ${configPath}`);
    } else if (err instanceof SyntaxError) {
      console.error(`Invalid JSON in config: ${err.message}`);
    } else {
      console.error(`Config error: ${err.message}`);
    }
    process.exit(1);
  }
}

// ─── Utility Functions ──────────────────────────────────────

/** Compute MD5 hash of a file for comparison */
function getFileHash(filePath) {
  const content = fs.readFileSync(filePath);
  return crypto.createHash("md5").update(content).digest("hex");
}

/** Check if a filename matches a glob-like pattern (simple wildcard) */
function matchesPattern(filename, pattern) {
  if (pattern === "*") return true;

  // Convert simple glob to regex: *.txt → /^.*\.txt$/
  const escaped = pattern
    .replace(/[.+^${}()|[\]\\]/g, "\\$&") // escape regex chars
    .replace(/\*/g, ".*") // * → .*
    .replace(/\?/g, "."); // ? → .

  const regex = new RegExp(`^${escaped}$`, "i");
  return regex.test(filename);
}

/** Determine if a file should be synced based on include/exclude rules */
function shouldInclude(filename, options) {
  const { include = ["*"], exclude = [] } = options;

  // Check excludes first
  for (const pattern of exclude) {
    if (matchesPattern(filename, pattern)) return false;
  }

  // Then check includes
  for (const pattern of include) {
    if (matchesPattern(filename, pattern)) return true;
  }

  return false;
}

/** Recursively get all files in a directory (relative paths) */
function getFilesRecursive(dir, baseDir = dir) {
  const results = [];

  if (!fs.existsSync(dir)) return results;

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(baseDir, fullPath);

    if (entry.isDirectory()) {
      results.push(...getFilesRecursive(fullPath, baseDir));
    } else if (entry.isFile()) {
      results.push(relativePath);
    }
  }

  return results;
}

/** Ensure all directories in a file path exist */
function ensureDir(filePath) {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

// ─── Sync Engine ────────────────────────────────────────────

class SyncEngine {
  constructor() {
    this.stats = { copied: 0, updated: 0, deleted: 0, skipped: 0, errors: 0 };
  }

  /** Reset stats before each job */
  resetStats() {
    this.stats = { copied: 0, updated: 0, deleted: 0, skipped: 0, errors: 0 };
  }

  /** Compare two files — returns true if they differ */
  filesAreDifferent(srcPath, destPath) {
    // If destination doesn't exist, they're "different"
    if (!fs.existsSync(destPath)) return true;

    const srcStat = fs.statSync(srcPath);
    const destStat = fs.statSync(destPath);

    // Quick check: different sizes → different
    if (srcStat.size !== destStat.size) return true;

    // Deep check: compare hashes
    return getFileHash(srcPath) !== getFileHash(destPath);
  }

  /** Copy a single file from source to destination */
  copyFile(srcPath, destPath, isUpdate = false) {
    try {
      ensureDir(destPath);
      fs.copyFileSync(srcPath, destPath);

      if (isUpdate) {
        this.stats.updated++;
      } else {
        this.stats.copied++;
      }

      const action = isUpdate ? "UPDATED" : "COPIED ";
      console.log(`  [${action}] ${path.relative(".", destPath)}`);
    } catch (err) {
      this.stats.errors++;
      console.error(`  [ERROR]   ${destPath}: ${err.message}`);
    }
  }

  /** Delete a file from destination */
  deleteFile(filePath) {
    try {
      fs.unlinkSync(filePath);
      this.stats.deleted++;
      console.log(`  [DELETED] ${path.relative(".", filePath)}`);
    } catch (err) {
      this.stats.errors++;
      console.error(`  [ERROR]   ${filePath}: ${err.message}`);
    }
  }

  /** Remove empty directories after deletion */
  cleanEmptyDirs(dir) {
    if (!fs.existsSync(dir)) return;

    const entries = fs.readdirSync(dir);

    // Recurse into subdirectories first
    for (const entry of entries) {
      const fullPath = path.join(dir, entry);
      if (fs.statSync(fullPath).isDirectory()) {
        this.cleanEmptyDirs(fullPath);
      }
    }

    // If directory is now empty, remove it
    if (fs.readdirSync(dir).length === 0) {
      fs.rmdirSync(dir);
      console.log(`  [RMDIR]   ${path.relative(".", dir)}`);
    }
  }

  /** Run a single sync job */
  runJob(job) {
    this.resetStats();

    const {
      name = "unnamed",
      source,
      destination,
      options = {},
    } = job;

    console.log(`\n${"═".repeat(50)}`);
    console.log(`Job: ${name}`);
    console.log(`  Source:      ${path.resolve(source)}`);
    console.log(`  Destination: ${path.resolve(destination)}`);
    console.log(`${"─".repeat(50)}`);

    // Validate source exists
    if (!fs.existsSync(source)) {
      console.error(`  Source directory does not exist: ${source}`);
      return this.stats;
    }

    // Create destination if it doesn't exist
    if (!fs.existsSync(destination)) {
      fs.mkdirSync(destination, { recursive: true });
      console.log(`  Created destination directory`);
    }

    // 1) Get file lists
    const sourceFiles = getFilesRecursive(source);
    const destFiles = getFilesRecursive(destination);

    // 2) Sync: source → destination
    for (const relPath of sourceFiles) {
      const filename = path.basename(relPath);

      if (!shouldInclude(filename, options)) {
        this.stats.skipped++;
        continue;
      }

      const srcPath = path.join(source, relPath);
      const destPath = path.join(destination, relPath);

      if (!fs.existsSync(destPath)) {
        // New file → copy
        this.copyFile(srcPath, destPath, false);
      } else if (this.filesAreDifferent(srcPath, destPath)) {
        // Existing but different → update
        if (options.overwriteNewer !== false) {
          this.copyFile(srcPath, destPath, true);
        } else {
          this.stats.skipped++;
          console.log(`  [SKIPPED] ${relPath} (overwrite disabled)`);
        }
      } else {
        // Identical → skip
        this.stats.skipped++;
      }
    }

    // 3) Delete orphaned files in destination (if enabled)
    if (options.deleteOrphaned) {
      const sourceSet = new Set(sourceFiles);

      for (const relPath of destFiles) {
        if (!sourceSet.has(relPath)) {
          const destPath = path.join(destination, relPath);
          this.deleteFile(destPath);
        }
      }

      // Clean up empty directories
      this.cleanEmptyDirs(destination);
    }

    // 4) Print summary
    console.log(`${"─".repeat(50)}`);
    console.log(`  Summary: ${this.stats.copied} copied, ` +
                `${this.stats.updated} updated, ` +
                `${this.stats.deleted} deleted, ` +
                `${this.stats.skipped} skipped, ` +
                `${this.stats.errors} errors`);

    return { ...this.stats };
  }

  /** Run all jobs from config */
  runAll(config) {
    console.log(`\nFile Sync — ${new Date().toISOString()}`);
    console.log(`Running ${config.jobs.length} sync job(s)...`);

    const results = [];

    for (const job of config.jobs) {
      const stats = this.runJob(job);
      results.push({ name: job.name, stats });
    }

    // Final summary
    console.log(`\n${"═".repeat(50)}`);
    console.log("All jobs complete.\n");

    return results;
  }
}

