## Key Design Points

| Feature | Implementation |
|---|---|
| **Change detection** | File size check first, then MD5 hash (avoids unnecessary reads) |
| **Pattern matching** | Simple glob (`*.txt`, `*`) converted to regex |
| **Orphan cleanup** | Compares destination against source set, removes extras |
| **Nested folders** | Recursive scanning + `mkdir -p` style directory creation |
| **Error handling** | Per-file try/catch so one failure doesn't stop the job |

# Event Processing Migration Helper in JavaScript

This example demonstrates a migration helper that transforms, validates, and migrates events from a legacy format to a new schema — with batching, retries, rollback support, and progress tracking.

```javascript
// ─── Event Schema Definitions ────────────────────────────────────────────────

const EventVersion = Object.freeze({
  V1: 'v1',
  V2: 'v2',
  V3: 'v3',
});

// ─── Custom Errors ───────────────────────────────────────────────────────────

class MigrationError extends Error {
  constructor(message, { eventId, phase, cause } = {}) {
    super(message);
    this.name = 'MigrationError';
    this.eventId = eventId;
    this.phase = phase;
    this.cause = cause;
    this.timestamp = new Date().toISOString();
  }
}

class ValidationError extends MigrationError {
  constructor(message, details = {}) {
    super(message, { ...details, phase: 'validation' });
    this.name = 'ValidationError';
  }
}

class TransformError extends MigrationError {
  constructor(message, details = {}) {
    super(message, { ...details, phase: 'transform' });
    this.name = 'TransformError';
  }
}

// ─── Logger ──────────────────────────────────────────────────────────────────

class MigrationLogger {
  #prefix;

  constructor(prefix = 'Migration') {
    this.#prefix = prefix;
  }

  info(message, data = {}) {
    console.log(`[${this.#prefix}] ℹ️  ${message}`, this.#formatData(data));
  }

  warn(message, data = {}) {
    console.warn(`[${this.#prefix}] ⚠️  ${message}`, this.#formatData(data));
  }

  error(message, data = {}) {
    console.error(`[${this.#prefix}] ❌ ${message}`, this.#formatData(data));
  }

  success(message, data = {}) {
    console.log(`[${this.#prefix}] ✅ ${message}`, this.#formatData(data));
  }

  #formatData(data) {
    return Object.keys(data).length > 0 ? JSON.stringify(data, null, 2) : '';
  }
}

// ─── Event Transformers (Strategy Pattern) ───────────────────────────────────

// Each transformer knows how to upgrade events from one version to the next.

const transformers = {
  // V1 → V2: Flatten nested user object, add schema version
  'v1_to_v2': (event) => {
    const { user, action, timestamp, ...rest } = event;

    if (!user || !action) {
      throw new TransformError('V1 event missing required fields', {
        eventId: event.id,
      });
    }

    return {
      id: event.id,
      userId: user.id,
      userName: `${user.firstName} ${user.lastName}`.trim(),
      userEmail: user.email ?? null,
      action: action.toUpperCase(),
      occurredAt: timestamp ?? new Date(0).toISOString(),
      metadata: rest,
      schemaVersion: EventVersion.V2,
    };
  },

  // V2 → V3: Add categorization, normalize action names, add processing info
  'v2_to_v3': (event) => {
    const actionCategoryMap = {
      'USER_LOGIN': 'auth',
      'USER_LOGOUT': 'auth',
      'USER_SIGNUP': 'auth',
      'PAGE_VIEW': 'analytics',
      'BUTTON_CLICK': 'analytics',
      'PURCHASE': 'transaction',
      'REFUND': 'transaction',
      'ITEM_ADDED': 'inventory',
      'ITEM_REMOVED': 'inventory',
    };

    return {
      ...event,
      category: actionCategoryMap[event.action] ?? 'uncategorized',
      processing: {
        migratedAt: new Date().toISOString(),
        sourceVersion: EventVersion.V2,
      },
      schemaVersion: EventVersion.V3,
    };
  },
};

// ─── Event Validator ─────────────────────────────────────────────────────────

class EventValidator {
  #schemas;

  constructor() {
    // Define required fields and type checks per version
    this.#schemas = {
      [EventVersion.V1]: {
        required: ['id', 'user', 'action'],
        validate: (event) => {
          if (typeof event.user !== 'object') return 'user must be an object';
          if (!event.user.id) return 'user.id is required';
          return null;
        },
      },
      [EventVersion.V2]: {
        required: ['id', 'userId', 'action', 'occurredAt', 'schemaVersion'],
        validate: (event) => {
          if (typeof event.userId !== 'string' && typeof event.userId !== 'number') {
            return 'userId must be a string or number';
          }
          return null;
        },
      },
      [EventVersion.V3]: {
        required: ['id', 'userId', 'action', 'occurredAt', 'category', 'processing', 'schemaVersion'],
        validate: (event) => {
          if (!event.processing?.migratedAt) return 'processing.migratedAt is required';
          return null;
        },
      },
    };
  }

  validate(event, version) {
    const schema = this.#schemas[version];
    if (!schema) {
      throw new ValidationError(`Unknown schema version: ${version}`);
    }

    // Check required fields
    const missing = schema.required.filter((field) => event[field] === undefined);
    if (missing.length > 0) {
      throw new ValidationError(
        `Missing required fields: ${missing.join(', ')}`,
        { eventId: event.id }
      );
    }

    // Run custom validation
    const error = schema.validate(event);
    if (error) {
      throw new ValidationError(error, { eventId: event.id });
    }

    return true;
  }
}

// ─── Migration Progress Tracker ──────────────────────────────────────────────

class ProgressTracker {
  #total;
  #processed;
  #succeeded;
  #failed;
  #skipped;
  #startTime;
  #errors;
  #onProgress;

  constructor(total, onProgress = null) {
    this.#total = total;
    this.#processed = 0;
    this.#succeeded = 0;
    this.#failed = 0;
    this.#skipped = 0;
    this.#startTime = Date.now();
    this.#errors = [];
    this.#onProgress = onProgress;
  }

  recordSuccess() {
    this.#processed++;
    this.#succeeded++;
    this.#emitProgress();
  }

  recordFailure(error) {
    this.#processed++;
    this.#failed++;
    this.#errors.push({
      message: error.message,
      eventId: error.eventId,
      phase: error.phase,
      timestamp: new Date().toISOString(),
    });
    this.#emitProgress();
  }

  recordSkip(reason) {
    this.#processed++;
    this.#skipped++;
    this.#emitProgress();
  }

  getSummary() {
    const elapsed = Date.now() - this.#startTime;
    return {
      total: this.#total,
      processed: this.#processed,
      succeeded: this.#succeeded,
      failed: this.#failed,
      skipped: this.#skipped,
      remaining: this.#total - this.#processed,
      percentComplete: ((this.#processed / this.#total) * 100).toFixed(1),
      elapsedMs: elapsed,
      eventsPerSecond: elapsed > 0 ? ((this.#processed / elapsed) * 1000).toFixed(1) : 0,
      errors: [...this.#errors],
    };
  }

  #emitProgress() {
    if (this.#onProgress) {
      this.#onProgress(this.getSummary());
    }
  }
}

// ─── Simulated Event Store (Replace with Real DB) ────────────────────────────

class EventStore {
  #events;

  constructor() {
    this.#events = new Map();
  }

  async save(event) {
    // Simulate async write with occasional failures
    await this.#delay(5);
    if (Math.random() < 0.02) {
      throw new Error('Simulated write failure');
    }
    this.#events.set(event.id, structuredClone(event));
  }

  async saveBatch(events) {
    const results = [];
    for (const event of events) {
      try {
        await this.save(event);
        results.push({ id: event.id, success: true });
      } catch (err) {
        results.push({ id: event.id, success: false, error: err.message });
      }
    }
    return results;
  }

  async getById(id) {
    await this.#delay(2);
    return this.#events.get(id) ?? null;
  }

  async delete(id) {
    await this.#delay(2);
    return this.#events.delete(id);
  }

  get size() {
    return this.#events.size;
  }

  #delay(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

// ─── Main Migration Helper ──────────────────────────────────────────────────

class EventMigrationHelper {
  #sourceVersion;
  #targetVersion;
  #validator;
  #logger;
  #store;
  #batchSize;
  #maxRetries;
  #dryRun;
  #rollbackLog;

  constructor({
    sourceVersion,
    targetVersion,
    store,
    batchSize = 100,
    maxRetries = 3,
    dryRun = false,
  }) {
    this.#sourceVersion = sourceVersion;
    this.#targetVersion = targetVersion;
    this.#validator = new EventValidator();
    this.#logger = new MigrationLogger('EventMigration');
    this.#store = store;
    this.#batchSize = batchSize;
    this.#maxRetries = maxRetries;
    this.#dryRun = dryRun;
    this.#rollbackLog = []; // Stores original events for rollback
  }

  // ── Public API ───────────────────────────────────────────────────────────

  /**
   * Migrate an array of events from source version to target version.
   * Processes in batches with retry and rollback support.
   */
  async migrate(events) {
    this.#logger.info('Starting migration', {
      source: this.#sourceVersion,
      target: this.#targetVersion,
      totalEvents: events.length,
      batchSize: this.#batchSize,
      dryRun: this.#dryRun,
    });

    const tracker = new ProgressTracker(events.length, (summary) => {
      // Log progress every 25%
      const pct = parseFloat(summary.percentComplete);
      if (pct % 25 < (1 / events.length) * 100) {
        this.#logger.info(`Progress: ${summary.percentComplete}%`, {
          succeeded: summary.succeeded,
          failed: summary.failed,
        });
      }
    });

    // Build the transformation pipeline for the version gap
    const pipeline = this.#buildPipeline(this.#sourceVersion, this.#targetVersion);

    // Split into batches
    const batches = this.#chunk(events, this.#batchSize);

    for (let i = 0; i < batches.length; i++) {
      this.#logger.info(`Processing batch ${i + 1}/${batches.length}`);
      await this.#processBatch(batches[i], pipeline, tracker);
    }

    const summary = tracker.getSummary();
    this.#logFinalSummary(summary);
    return summary;
  }

  /**
   * Transform a single event through the full pipeline (useful for testing).
   */
  transformOne(event) {
    const pipeline = this.#buildPipeline(this.#sourceVersion, this.#targetVersion);
    return this.#applyPipeline(event, pipeline);
  }

  /**
   * Roll back all migrated events to their original state.
   */
  async rollback() {
    this.#logger.warn('Rolling back migration', {
      eventsToRestore: this.#rollbackLog.length,
    });

    let restored = 0;
    for (const { id, original } of this.#rollbackLog) {
      try {
        await this.#store.save(original);
        restored++;
      } catch (err) {
        this.#logger.error(`Failed to restore event ${id}`, {
          error: err.message,
        });
      }
    }

    this.#logger.info('Rollback complete', {
      restored,
      total: this.#rollbackLog.length,
    });

    this.#rollbackLog = [];
    return { restored, total: this.#rollbackLog.length };
  }

  // ── Private Helpers ──────────────────────────────────────────────────────

  /**
   * Build an ordered list of transform functions to go from `from` → `to`.
   *
   * Example: v1 → v3 yields [v1_to_v2, v2_to_v3]
   */
  #buildPipeline(from, to) {
    const versionOrder = [EventVersion.V1, EventVersion.V2, EventVersion.V3];
    const startIdx = versionOrder.indexOf(from);
    const endIdx = versionOrder.indexOf(to);

    if (startIdx === -1 || endIdx === -1 || startIdx >= endIdx) {
      throw new MigrationError(
        `Invalid migration path: ${from} → ${to}`
      );
    }

    const steps = [];
    for (let i = startIdx; i < endIdx; i++) {
      const key = `${versionOrder[i]}_to_${versionOrder[i + 1]}`;
      const fn = transformers[key];

      if (!fn) {
        throw new MigrationError(`No transformer found for step: ${key}`);
      }

      steps.push({ key, transform: fn, targetVersion: versionOrder[i + 1] });
    }

    this.#logger.info('Pipeline built', {
      steps: steps.map((s) => s.key),
    });

    return steps;
  }

  /**
   * Run a single event through every step of the pipeline.
   */
  #applyPipeline(event, pipeline) {
    let current = structuredClone(event);

    for (const step of pipeline) {
      current = step.transform(current);
      this.#validator.validate(current, step.targetVersion);
    }

    return current;
  }

  /**
   * Process one batch of events with retry logic.
   */
  async #processBatch(batch, pipeline, tracker) {
    const migrated = [];

    for (const event of batch) {
      try {
        // Validate source event
        this.#validator.validate(event, this.#sourceVersion);

        // Transform through pipeline
        const transformed = this.#applyPipeline(event, pipeline);

        if (!this.#dryRun) {
          // Persist with retries
          await this.#withRetry(() => this.#store.save(transformed), event.id);

          // Record original for rollback
          this.#rollbackLog.push({ id: event.id, original: structuredClone(event) });
        }

        migrated.push(transformed);
        tracker.recordSuccess();
      } catch (err) {
        const migrationErr =
          err instanceof MigrationError
            ? err
            : new MigrationError(err.message, {
                eventId: event.id,
                phase: 'persist',
                cause: err,
              });

        this.#logger.error(`Failed to migrate event ${event.id}`, {
          error: migrationErr.message,
          phase: migrationErr.phase,
        });

        tracker.recordFailure(migrationErr);
      }
    }

    return migrated;
  }

  /**
   * Retry an async operation up to maxRetries times with exponential backoff.
   */
  async #withRetry(fn, eventId) {
    let lastError;

    for (let attempt = 1; attempt <= this.#maxRetries; attempt++) {
      try {
        return await fn();
      } catch (err) {
        lastError = err;
        if (attempt < this.#maxRetries) {
          const delay = Math.min(100 * 2 ** attempt, 2000);
          this.#logger.warn(
            `Retry ${attempt}/${this.#maxRetries} for event ${eventId} in ${delay}ms`
          );
          await new Promise((r) => setTimeout(r, delay));
        }
      }
    }

    throw new MigrationError(
      `All ${this.#maxRetries} retries exhausted for event ${eventId}`,
      { eventId, phase: 'persist', cause: lastError }
    );
  }

  /**
   * Split an array into chunks of the given size.
   */
  #chunk(array, size) {
    const chunks = [];
    for (let i = 0; i < array.length; i += size) {
      chunks.push(array.slice(i, i + size));
    }
    return chunks;
  }

  /**
   * Pretty-print the final migration summary.
   */
  #logFinalSummary(summary) {
    const status = summary.failed === 0 ? 'success' : 'warn';
    const logFn = status === 'success'
      ? this.#logger.success.bind(this.#logger)
      : this.#logger.warn.bind(this.#logger);

    logFn('Migration complete', {
      total: summary.total,
      succeeded: summary.succeeded,
      failed: summary.failed,
      skipped: summary.skipped,
      duration: `${summary.elapsedMs}ms`,
      throughput: `${summary.eventsPerSecond} events/sec`,
    });

    if (summary.errors.length > 0) {
      this.#logger.error('Errors encountered', {
        count: summary.errors.length,
        sample: summary.errors.slice(0, 5),
      });
    }
  }
}

