import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { loadData } from './loader.js';
import { processData } from './processor.js';
import { formatReport } from './formatters/index.js';

const HELP = `
\x1b[1mreport-cli\x1b[0m — Generate reports from CSV/JSON data

\x1b[1mUSAGE\x1b[0m
  report --input <file> [options]

\x1b[1mINPUT\x1b[0m
  --input, -i <file>        Source file (.csv or .json)
  --stdin                   Read from stdin instead of file

\x1b[1mFILTERING\x1b[0m
  --where <expr>            Filter rows (e.g. "status=active")
  --where <expr>            Can be repeated for AND logic

\x1b[1mAGGREGATION\x1b[0m
  --group, -g <column>      Group by column
  --sum <column>            Sum numeric column per group
  --avg <column>            Average of numeric column per group
  --min <column>            Min of numeric column per group
  --max <column>            Max of numeric column per group
  --count                   Count rows per group

\x1b[1mSORTING\x1b[0m
  --sort <column>           Sort by column (prefix with - for desc)

\x1b[1mLIMIT\x1b[0m
  --limit, -l <n>           Limit output rows
  --offset <n>              Skip first n rows

\x1b[1mOUTPUT\x1b[0m
  --format, -f <type>       table (default), csv, json, html
  --output, -o <file>       Write to file instead of stdout
  --columns, -c <cols>      Comma-separated columns to include
  --title <text>            Report title (used in html/table)

\x1b[1mEXAMPLES\x1b[0m
  report -i sales.csv -f table
  report -i sales.csv --where "region=West" --sort -revenue -f table
  report -i sales.csv -g region --sum revenue --avg revenue --count -f csv
  report -i data.json -g status --count --sort -count -o report.html -f html
  cat data.csv | report --stdin --columns name,email -f json
`;

/**
 * Parse CLI arguments into a structured config object.
 * No external deps — handles repeated flags and flag=value syntax.
 */
function parseArgs(argv) {
  const config = {
    input: null,
    stdin: false,
    where: [],
    group: null,
    aggregations: [],
    sort: null,
    limit: null,
    offset: 0,
    format: 'table',
    output: null,
    columns: null,
    title: 'Report',
    help: false,
  };

  const alias = {
    '-i': '--input',
    '-g': '--group',
    '-f': '--format',
    '-o': '--output',
    '-c': '--columns',
    '-l': '--limit',
    '-h': '--help',
  };

  // Normalize aliases
  const args = argv.map((a) => alias[a] || a);

  let i = 0;
  while (i < args.length) {
    const arg = args[i];

    switch (arg) {
      case '--help':
        config.help = true;
        break;
      case '--input':
        config.input = args[++i];
        break;
      case '--stdin':
        config.stdin = true;
        break;
      case '--where':
        config.where.push(args[++i]);
        break;
      case '--group':
        config.group = args[++i];
        break;
      case '--sum':
        config.aggregations.push({ type: 'sum', column: args[++i] });
        break;
      case '--avg':
        config.aggregations.push({ type: 'avg', column: args[++i] });
        break;
      case '--min':
        config.aggregations.push({ type: 'min', column: args[++i] });
        break;
      case '--max':
        config.aggregations.push({ type: 'max', column: args[++i] });
        break;
      case '--count':
        config.aggregations.push({ type: 'count' });
        break;
      case '--sort':
        config.sort = args[++i];
        break;
      case '--limit':
        config.limit = parseInt(args[++i], 10);
        break;
      case '--offset':
        config.offset = parseInt(args[++i], 10);
        break;
      case '--format':
        config.format = args[++i];
        break;
      case '--output':
        config.output = args[++i];
        break;
      case '--columns':
        config.columns = args[++i].split(',').map((c) => c.trim());
        break;
      case '--title':
        config.title = args[++i];
        break;
      default:
        // If no flag recognized and no input set, treat as input file
        if (!arg.startsWith('-') && !config.input) {
          config.input = arg;
        } else if (arg.startsWith('-')) {
          throw new Error(`Unknown option: ${arg}. Use --help for usage.`);
        }
    }
    i++;
  }

  return config;
}

/**
 * Read all of stdin as a string (for piped input).
 */
async function readStdin() {
  const chunks = [];
  for await (const chunk of process.stdin) {
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf-8');
}

/**
 * Main entry — parse args, load, process, format, output.
 */
export async function run(argv) {
  const config = parseArgs(argv);

  if (config.help || (!config.input && !config.stdin)) {
    console.log(HELP);
    return;
  }

  // 1. Load raw text
  let raw;
  let fileType;

  if (config.stdin) {
    raw = await readStdin();
    // Guess type from content
    fileType = raw.trimStart().startsWith('[') || raw.trimStart().startsWith('{')
      ? 'json'
      : 'csv';
  } else {
    const filePath = resolve(config.input);
    raw = await readFile(filePath, 'utf-8');
    fileType = filePath.endsWith('.json') ? 'json' : 'csv';
  }

  // 2. Parse into array of objects
  const rows = loadData(raw, fileType);

  if (rows.length === 0) {
    console.log('No data found.');
    return;
  }

  // 3. Process (filter → group/aggregate → sort → paginate → select columns)
  const result = processData(rows, config);

  // 4. Format output
  const output = formatReport(result.rows, {
    format: config.format,
    title: config.title,
    columns: result.columns,
    summary: result.summary,
  });

  // 5. Write
  if (config.output) {
    const { writeFile } = await import('node:fs/promises');
    await writeFile(resolve(config.output), output, 'utf-8');
    console.log(`\x1b[32m✓ Report written to ${config.output}\x1b[0m`);
  } else {
    console.log(output);
  }
}
