## src/processor.js — Filter, Group, Aggregate, Sort

```javascript
/**
 * Full data processing pipeline:
 *   filter → group/aggregate → sort → offset/limit → column selection
 *
 * Returns { rows, columns, summary } ready for formatting.
 */
export function processData(rows, config) {
  let data = [...rows];

  // --- 1. Filter ---
  if (config.where.length > 0) {
    const filters = config.where.map(parseWhereExpr);
    data = data.filter((row) => filters.every((fn) => fn(row)));
  }

  const totalBeforeAgg = data.length;

  // --- 2. Group + Aggregate ---
  if (config.group || config.aggregations.length > 0) {
    data = aggregate(data, config.group, config.aggregations);
  }

  // --- 3. Sort ---
  if (config.sort) {
    const desc = config.sort.startsWith('-');
    const sortCol = desc ? config.sort.slice(1) : config.sort;
    data.sort((a, b) => {
      const va = a[sortCol];
      const vb = b[sortCol];
      if (va == null && vb == null) return 0;
      if (va == null) return 1;
      if (vb == null) return -1;
      if (typeof va === 'number' && typeof vb === 'number') {
        return desc ? vb - va : va - vb;
      }
      const cmp = String(va).localeCompare(String(vb));
      return desc ? -cmp : cmp;
    });
  }

  // --- 4. Offset + Limit ---
  const offset = config.offset || 0;
  const limit = config.limit != null ? config.limit : data.length;
  data = data.slice(offset, offset + limit);

  // --- 5. Column Selection ---
  let columns;
  if (config.columns) {
    columns = config.columns;
    data = data.map((row) => {
      const obj = {};
      columns.forEach((col) => {
        obj[col] = row[col] !== undefined ? row[col] : null;
      });
      return obj;
    });
  } else {
    // Derive columns from data
    columns = data.length > 0 ? Object.keys(data[0]) : [];
  }

  return {
    rows: data,
    columns,
    summary: {
      totalRecords: totalBeforeAgg,
      displayedRows: data.length,
    },
  };
}

/**
 * Parse a where expression like "status=active", "revenue>1000", "name!=John".
 * Returns a predicate function.
 */
function parseWhereExpr(expr) {
  // Supported operators: =, !=, >, <, >=, <=, ~= (contains)
  const operators = ['!=', '>=', '<=', '~=', '>', '<', '='];
  let op = null;
  let splitIdx = -1;

  for (const candidate of operators) {
    const idx = expr.indexOf(candidate);
    if (idx > 0) {
      op = candidate;
      splitIdx = idx;
      break;
    }
  }

  if (!op) {
    throw new Error(`Invalid where expression: "${expr}". Use format: column=value`);
  }

  const column = expr.slice(0, splitIdx).trim();
  const rawValue = expr.slice(splitIdx + op.length).trim();
  const value = coerce(rawValue);

  const predicates = {
    '=':  (row) => row[column] == value, // loose equality for number/string
    '!=': (row) => row[column] != value,
    '>':  (row) => row[column] > value,
    '<':  (row) => row[column] < value,
    '>=': (row) => row[column] >= value,
    '<=': (row) => row[column] <= value,
    '~=': (row) => String(row[column] ?? '').toLowerCase().includes(String(value).toLowerCase()),
  };

  return predicates[op];
}

function coerce(val) {
  if (/^-?\d+(\.\d+)?$/.test(val)) return Number(val);
  if (val === 'true') return true;
  if (val === 'false') return false;
  if (val === 'null') return null;
  return val;
}

/**
 * Group rows by a column and compute aggregations.
 * If no group column, aggregates across all rows (single result).
 */
function aggregate(rows, groupCol, aggregations) {
  // Build groups
  const groups = new Map();

  if (groupCol) {
    for (const row of rows) {
      const key = String(row[groupCol] ?? '(empty)');
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(row);
    }
  } else {
    groups.set('_all', rows);
  }

  // Compute per group
  const results = [];

  for (const [key, groupRows] of groups) {
    const result = {};
    if (groupCol) result[groupCol] = key;

    for (const agg of aggregations) {
      if (agg.type === 'count') {
        result['count'] = groupRows.length;
        continue;
      }

      const values = groupRows
        .map((r) => r[agg.column])
        .filter((v) => typeof v === 'number' && !Number.isNaN(v));

      const label = `${agg.type}_${agg.column}`;

      switch (agg.type) {
        case 'sum':
          result[label] = values.reduce((a, b) => a + b, 0);
          break;
        case 'avg':
          result[label] = values.length > 0
            ? Math.round((values.reduce((a, b) => a + b, 0) / values.length) * 100) / 100
            : 0;
          break;
        case 'min':
          result[label] = values.length > 0 ? Math.min(...values) : null;
          break;
        case 'max':
          result[label] = values.length > 0 ? Math.max(...values) : null;
          break;
      }
    }

    results.push(result);
  }

  return results;
}
