        ($1, $2, $3, $4, $5, $6, NOW())
      RETURNING id, action, user_id, resource, details, metadata, ip_address, created_at
    `;

    const params = [
      action.toUpperCase(),
      userId,
      resource,
      details || null,
      metadata ? JSON.stringify(metadata) : null,
      ipAddress,
    ];

    // FIX 8: Properly await the query
    const result = await pool.query(query, params);

    // FIX 9 & 10: Send response AFTER query, with 201 status
    res.status(201).json({
      message: 'Audit log created',
      data: mapAuditLogResponse(result.rows[0]),
    });
  } catch (err) {
    next(err); // delegate to global error handler
  }
});

// ---------- GET AUDIT LOGS (with pagination & safe filtering) ----------
// FIX 11, 12, 13, 14
app.get('/api/audit-logs', async (req, res, next) => {
  try {
    const {
      userId,
      action,
      resource,
      startDate,
      endDate,
      page = 1,
      limit = 50,
    } = req.query;

    // FIX 11: Pagination validation
    const pageNum = Math.max(1, parseInt(page, 10) || 1);
    const limitNum = Math.min(100, Math.max(1, parseInt(limit, 10) || 50));
    const offset = (pageNum - 1) * limitNum;

    // FIX 12: Build query with parameterized values
    const conditions = [];
    const params = [];
    let paramIndex = 1;

    if (userId) {
      conditions.push(`user_id = $${paramIndex++}`);
      params.push(userId);
    }

    if (action) {
      if (!ALLOWED_ACTIONS.includes(action.toUpperCase())) {
        return res.status(400).json({
          error: `Invalid action filter. Allowed: ${ALLOWED_ACTIONS.join(', ')}`,
        });
      }
      conditions.push(`action = $${paramIndex++}`);
      params.push(action.toUpperCase());
    }

    if (resource) {
      conditions.push(`resource ILIKE $${paramIndex++}`);
      params.push(`%${resource}%`);
    }

    if (startDate) {
      if (!isValidISODate(startDate)) {
        return res.status(400).json({ error: 'Invalid startDate format (use ISO 8601)' });
      }
      conditions.push(`created_at >= $${paramIndex++}`);
      params.push(startDate);
    }

    if (endDate) {
      if (!isValidISODate(endDate)) {
        return res.status(400).json({ error: 'Invalid endDate format (use ISO 8601)' });
      }
      conditions.push(`created_at <= $${paramIndex++}`);
      params.push(endDate);
    }

    const whereClause = conditions.length > 0
      ? `WHERE ${conditions.join(' AND ')}`
      : '';

    // Count total for pagination metadata
    const countQuery = `SELECT COUNT(*) FROM audit_logs ${whereClause}`;
    const countResult = await pool.query(countQuery, params);
    const totalCount = parseInt(countResult.rows[0].count, 10);

    // Fetch page of results
    const dataQuery = `
      SELECT id, action, user_id, resource, details, metadata, ip_address, created_at
      FROM audit_logs
      ${whereClause}
      ORDER BY created_at DESC
      LIMIT $${paramIndex++} OFFSET $${paramIndex++}
    `;
    params.push(limitNum, offset);

    const dataResult = await pool.query(dataQuery, params);

    // FIX 14: Map response fields
    res.json({
      data: dataResult.rows.map(mapAuditLogResponse),
      pagination: {
        page: pageNum,
        limit: limitNum,
        totalCount,
        totalPages: Math.ceil(totalCount / limitNum),
      },
    });
  } catch (err) {
    next(err);
  }
});

// ---------- GET SINGLE AUDIT LOG ----------
// FIX 15, 16
app.get('/api/audit-logs/:id', async (req, res, next) => {
  try {
    const { id } = req.params;

    // FIX 15: Validate ID
    if (!isValidInteger(id)) {
      return res.status(400).json({
        error: 'Invalid audit log ID — must be a positive integer',
        code: 'INVALID_ID',
      });
    }

    // Parameterized query
    const result = await pool.query(
      `SELECT id, action, user_id, resource, details, metadata, ip_address, created_at
       FROM audit_logs WHERE id = $1`,
      [id]
    );

    // FIX 16: Handle not found
    if (result.rows.length === 0) {
      return res.status(404).json({
        error: `Audit log with id ${id} not found`,
        code: 'NOT_FOUND',
      });
    }

    res.json({ data: mapAuditLogResponse(result.rows[0]) });
  } catch (err) {
    next(err);
  }
});

// ---------- REMOVE HARD DELETE → COMPLIANCE SAFE ARCHIVE ----------
// FIX 17: Audit logs should be immutable; allow only soft-archive
app.delete('/api/audit-logs/:id', (req, res) => {
  res.status(405).json({
    error: 'Audit logs cannot be deleted (compliance requirement)',
    code: 'METHOD_NOT_ALLOWED',
  });
});

// Optional: allow archiving (soft flag) by admin only
app.patch('/api/audit-logs/:id/archive', async (req, res, next) => {
  try {
    const { id } = req.params;

    if (!isValidInteger(id)) {
      return res.status(400).json({ error: 'Invalid ID' });
    }

    const result = await pool.query(
      `UPDATE audit_logs SET archived = TRUE, archived_at = NOW()
       WHERE id = $1 AND archived = FALSE
       RETURNING id`,
      [id]
    );

    if (result.rowCount === 0) {
      return res.status(404).json({ error: 'Log not found or already archived' });
    }

    res.json({ message: `Audit log ${id} archived` });
  } catch (err) {
    next(err);
  }
});

// ─────────────────────────────────────────────
// FIX 18: Global error handler
// ─────────────────────────────────────────────
app.use((err, req, res, _next) => {
  const correlationId = uuidv4();

  // Log full error internally (send to logging service in production)
  console.error({
    correlationId,
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Return safe error to client (never leak stack traces)
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: statusCode === 500
      ? 'Internal server error'
      : err.message,
    code: err.code || 'INTERNAL_ERROR',
    correlationId,  // helps trace logs for support tickets
  });
});

// Handle unknown routes
app.use((_req, res) => {
  res.status(404).json({ error: 'Route not found', code: 'NOT_FOUND' });
});

// ─────────────────────────────────────────────
// FIX 19: Graceful shutdown
// ─────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Audit Log API running on port ${PORT}`);
});

async function gracefulShutdown(signal) {
  console.log(`\n${signal} received — shutting down gracefully...`);

  // Stop accepting new connections
  server.close(() => {
    console.log('HTTP server closed');
  });

  // Drain the database pool
  try {
    await pool.end();
    console.log('Database pool drained');
  } catch (err) {
    console.error('Error draining pool:', err.message);
  }

  process.exit(0);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app; // for testing
