"use strict";

class ConfigError extends Error {
  constructor(message, code, details = {}) {
    super(message);
    this.name = "ConfigError";
    this.code = code;
    this.details = details;
    Error.captureStackTrace(this, this.constructor);
  }
}

class ConfigFileNotFoundError extends ConfigError {
  constructor(filePath) {
    super(
      `Configuration file not found: ${filePath}`,
      "CONFIG_FILE_NOT_FOUND",
      { filePath }
    );
    this.name = "ConfigFileNotFoundError";
  }
}

class ConfigParseError extends ConfigError {
  constructor(filePath, parseError) {
    super(
      `Failed to parse configuration file: ${filePath} — ${parseError.message}`,
      "CONFIG_PARSE_ERROR",
      { filePath, originalError: parseError.message }
    );
    this.name = "ConfigParseError";
  }
}

class ConfigValidationError extends ConfigError {
  constructor(violations) {
    const messages = violations.map((v) => `  - ${v.path}: ${v.message}`);
    super(
      `Configuration validation failed:\n${messages.join("\n")}`,
      "CONFIG_VALIDATION_ERROR",
      { violations }
    );
    this.name = "ConfigValidationError";
  }
}

module.exports = {
  ConfigError,
  ConfigFileNotFoundError,
  ConfigParseError,
  ConfigValidationError,
};
