// src/ConfigValidator.js
"use strict";

const { ConfigValidationError } = require("./errors");

/**
 * Validates configuration objects against a JSON schema definition.
 * Supports type checking, required fields, ranges, patterns, and nested objects.
 */
class ConfigValidator {
  static SUPPORTED_TYPES = new Set([
    "string",
    "number",
    "boolean",
    "object",
    "array",
    "integer",
  ]);

  /**
   * @param {Object} schema - JSON schema definition for validation
   */
  constructor(schema) {
    this._schema = schema;
    this._violations = [];
  }

  /**
   * Validates the given config against the stored schema.
   * @param {Object} config - Configuration object to validate
   * @throws {ConfigValidationError} If validation fails
   * @returns {true} If validation passes
   */
  validate(config) {
    this._violations = [];
    this._validateObject(config, this._schema, "");

    if (this._violations.length > 0) {
      throw new ConfigValidationError([...this._violations]);
    }

    return true;
  }

  /**
   * Recursively validates an object against its schema.
   */
  _validateObject(obj, schema, basePath) {
    if (!schema || !schema.properties) {
      return;
    }

    // Check required fields
    if (Array.isArray(schema.required)) {
      for (const field of schema.required) {
        const fullPath = basePath ? `${basePath}.${field}` : field;
        if (obj[field] === undefined || obj[field] === null) {
          this._violations.push({
            path: fullPath,
            message: `Required field is missing`,
            rule: "required",
          });
        }
      }
    }

    // Validate each property defined in the schema
    for (const [key, propSchema] of Object.entries(schema.properties)) {
      const fullPath = basePath ? `${basePath}.${key}` : key;
      const value = obj[key];

      // Skip undefined optional fields
      if (value === undefined) {
        continue;
      }

      this._validateProperty(value, propSchema, fullPath);
    }

    // Warn about unknown properties if additionalProperties is false
    if (schema.additionalProperties === false) {
      const knownKeys = new Set(Object.keys(schema.properties));
      for (const key of Object.keys(obj)) {
        if (!knownKeys.has(key)) {
          const fullPath = basePath ? `${basePath}.${key}` : key;
          this._violations.push({
            path: fullPath,
            message: `Unknown property not allowed`,
            rule: "additionalProperties",
          });
        }
      }
    }
  }

  /**
   * Validates a single property value against its schema definition.
   */
  _validateProperty(value, propSchema, path) {
    // Type check
    if (propSchema.type) {
      if (!this._checkType(value, propSchema.type)) {
        this._violations.push({
          path,
          message: `Expected type "${propSchema.type}", got "${typeof value}"`,
          rule: "type",
          expected: propSchema.type,
          actual: typeof value,
        });
        return; // Skip further checks if type is wrong
      }
    }

    // Enum check
    if (Array.isArray(propSchema.enum)) {
      if (!propSchema.enum.includes(value)) {
        this._violations.push({
          path,
          message: `Value "${value}" not in allowed values: [${propSchema.enum.join(", ")}]`,
          rule: "enum",
          allowed: propSchema.enum,
          actual: value,
        });
      }
    }

    // Numeric range checks
    if (typeof value === "number") {
      if (propSchema.minimum !== undefined && value < propSchema.minimum) {
        this._violations.push({
          path,
          message: `Value ${value} is below minimum ${propSchema.minimum}`,
          rule: "minimum",
        });
      }
      if (propSchema.maximum !== undefined && value > propSchema.maximum) {
        this._violations.push({
          path,
          message: `Value ${value} exceeds maximum ${propSchema.maximum}`,
          rule: "maximum",
        });
      }
    }

    // String constraints
    if (typeof value === "string") {
      if (propSchema.minLength !== undefined && value.length < propSchema.minLength) {
        this._violations.push({
          path,
          message: `String length ${value.length} is below minimum ${propSchema.minLength}`,
          rule: "minLength",
        });
      }
      if (propSchema.maxLength !== undefined && value.length > propSchema.maxLength) {
        this._violations.push({
          path,
          message: `String length ${value.length} exceeds maximum ${propSchema.maxLength}`,
          rule: "maxLength",
        });
      }
      if (propSchema.pattern) {
        const regex = new RegExp(propSchema.pattern);
        if (!regex.test(value)) {
          this._violations.push({
            path,
            message: `Value does not match pattern "${propSchema.pattern}"`,
            rule: "pattern",
          });
        }
      }
    }

    // Nested object validation
    if (propSchema.type === "object" && propSchema.properties) {
      this._validateObject(value, propSchema, path);
    }

    // Array item validation
    if (propSchema.type === "array" && Array.isArray(value) && propSchema.items) {
      for (let i = 0; i < value.length; i++) {
        this._validateProperty(value[i], propSchema.items, `${path}[${i}]`);
      }
    }
  }

  /**
   * Checks whether a value matches the expected JSON schema type.
   */
  _checkType(value, expectedType) {
    switch (expectedType) {
      case "string":
        return typeof value === "string";
      case "number":
        return typeof value === "number" && !Number.isNaN(value);
      case "integer":
        return Number.isInteger(value);
      case "boolean":
        return typeof value === "boolean";
      case "object":
        return typeof value === "object" && value !== null && !Array.isArray(value);
      case "array":
        return Array.isArray(value);
      default:
        return true;
    }
  }
}

module.exports = ConfigValidator;
