"use strict";

const fs = require("fs");
const path = require("path");
const ConfigValidator = require("./ConfigValidator");
const {
  ConfigError,
  ConfigFileNotFoundError,
  ConfigParseError,
} = require("./errors");

/**
 * Production-ready configuration loader.
 *
 * Loading precedence (highest → lowest):
 *   1. Programmatic overrides
 *   2. Environment variables (mapped via envMapping)
 *   3. Environment-specific config file (e.g., production.json)
 *   4. Default config file (default.json)
 *
 * Features:
 *   - Multi-layer merging with deep merge
 *   - Environment variable interpolation
 *   - JSON schema validation
 *   - Frozen (immutable) config output
 *   - Reload support
 *   - Secret masking in logs
 */
class ConfigLoader {
  /**
   * @param {Object} options
   * @param {string}  options.configDir     - Absolute path to the config directory
   * @param {string} [options.env]          - Environment name override
   * @param {Object} [options.schema]       - JSON schema for validation
   * @param {Object} [options.defaults]     - Programmatic default values
   * @param {Object} [options.overrides]    - Programmatic overrides (highest priority)
   * @param {Object} [options.envMapping]   - Map of config paths → env var names
   * @param {string[]} [options.secretKeys] - Dot-paths to mask when logging
   */
  constructor(options = {}) {
    this._configDir = options.configDir || path.join(process.cwd(), "config");
    this._env = options.env || process.env.NODE_ENV || "development";
    this._schema = options.schema || null;
    this._defaults = options.defaults || {};
    this._overrides = options.overrides || {};
    this._envMapping = options.envMapping || {};
    this._secretKeys = new Set(options.secretKeys || []);
    this._config = null;
    this._loadedFiles = [];
    this._validator = this._schema ? new ConfigValidator(this._schema) : null;
  }

  // ─── Public API ──────────────────────────────────────────

  /**
   * Loads and returns the fully merged, validated, frozen config.
   * @returns {Object} Immutable configuration object
   */
  load() {
    this._loadedFiles = [];

    // Layer 1: programmatic defaults
    let config = this._deepClone(this._defaults);

    // Layer 2: default.json
    const defaultConfig = this._loadFile("default.json", false);
    config = this._deepMerge(config, defaultConfig);

    // Layer 3: environment-specific file
    const envConfig = this._loadFile(`${this._env}.json`, false);
    config = this._deepMerge(config, envConfig);

    // Layer 4: local overrides (not committed to VCS)
    const localConfig = this._loadFile("local.json", false);
    config = this._deepMerge(config, localConfig);

    // Layer 5: environment variables
    const envVarConfig = this._loadEnvironmentVariables();
    config = this._deepMerge(config, envVarConfig);

    // Layer 6: programmatic overrides
    config = this._deepMerge(config, this._deepClone(this._overrides));

    // Validate
    if (this._validator) {
      this._validator.validate(config);
    }

    // Freeze for immutability
    this._config = this._deepFreeze(config);

    return this._config;
  }

  /**
   * Reloads configuration from disk. Useful for SIGHUP-based reloads.
   * @returns {Object} New immutable configuration object
   */
  reload() {
    return this.load();
  }

  /**
   * Retrieves a value by dot-notation path.
   * @param {string} keyPath - e.g. "database.connection.host"
   * @param {*} [defaultValue] - Returned when the path doesn't resolve
   * @returns {*}
   */
  get(keyPath, defaultValue = undefined) {
    if (!this._config) {
      throw new ConfigError(
        "Configuration not loaded. Call load() first.",
        "CONFIG_NOT_LOADED"
      );
    }

    const keys = keyPath.split(".");
    let current = this._config;

    for (const key of keys) {
      if (current === null || current === undefined || typeof current !== "object") {
        return defaultValue;
      }
      current = current[key];
    }

    return current !== undefined ? current : defaultValue;
  }

  /**
   * Checks whether a given dot-path exists in the loaded config.
   * @param {string} keyPath
   * @returns {boolean}
   */
  has(keyPath) {
    if (!this._config) {
      return false;
    }

    const keys = keyPath.split(".");
    let current = this._config;

    for (const key of keys) {
      if (current === null || current === undefined || typeof current !== "object") {
        return false;
      }
      if (!Object.prototype.hasOwnProperty.call(current, key)) {
        return false;
      }
      current = current[key];
    }

    return true;
  }

  /**
   * Returns the entire config object (frozen).
   * @returns {Object}
   */
  getAll() {
    if (!this._config) {
      throw new ConfigError(
        "Configuration not loaded. Call load() first.",
        "CONFIG_NOT_LOADED"
      );
    }
    return this._config;
  }

  /**
   * Returns the current environment name.
   * @returns {string}
   */
  getEnvironment() {
    return this._env;
  }

  /**
   * Returns a list of config files that were actually loaded.
   * @returns {string[]}
   */
  getLoadedFiles() {
    return [...this._loadedFiles];
  }

  /**
   * Returns a log-safe representation (secrets masked).
