## src/retryHandler.js
```javascript
const { setTimeout: delay } = require("timers/promises");

class RetryHandler {
  constructor(options = {}) {
    this.maxRetries = options.maxRetries ?? 5;
    this.baseDelayMs = options.baseDelayMs ?? 500;
    this.maxDelayMs = options.maxDelayMs ?? 30000;
    this.backoffMultiplier = options.backoffMultiplier ?? 2;
    this.retryStats = { attempts: 0, successes: 0, failures: 0 };
  }

  /**
   * Calculate delay with exponential backoff + jitter
   */
  getDelay(attempt) {
    const exponentialDelay = this.baseDelayMs * Math.pow(this.backoffMultiplier, attempt);
    const jitter = Math.random() * this.baseDelayMs;
    return Math.min(exponentialDelay + jitter, this.maxDelayMs);
  }

  /**
   * Determine if an error is retryable
   */
  isRetryable(error) {
    const retryableCodes = [
      "EBUSY",      // file is locked/busy
      "EPERM",      // temporary permission issue
      "EAGAIN",     // resource temporarily unavailable
      "EMFILE",     // too many open files
      "ENFILE",     // too many open files (system)
      "EIO",        // I/O error (could be transient)
      "ETIMEDOUT",  // network timeout
      "ECONNRESET", // connection reset
    ];

    return retryableCodes.includes(error.code);
  }

  /**
   * Execute a function with retry logic
   */
  async execute(fn, label = "operation") {
    let lastError;

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      try {
        this.retryStats.attempts++;

        if (attempt > 0) {
          const delayMs = this.getDelay(attempt - 1);
          console.log(
            `  ↻ Retry ${attempt}/${this.maxRetries} for "${label}" ` +
            `(waiting ${Math.round(delayMs)}ms)`
          );
          await delay(delayMs);
        }

        const result = await fn();
        this.retryStats.successes++;
        return result;
      } catch (error) {
        lastError = error;

        // Don't retry non-retryable errors
        if (!this.isRetryable(error)) {
          console.error(`  ✗ Non-retryable error for "${label}": ${error.message}`);
          this.retryStats.failures++;
          throw error;
        }

        if (attempt < this.maxRetries) {
          console.warn(
            `  ⚠ Attempt ${attempt + 1} failed for "${label}": ` +
            `${error.code || error.message}`
          );
        }
      }
    }

    this.retryStats.failures++;
    const finalError = new Error(
      `Failed "${label}" after ${this.maxRetries + 1} attempts: ${lastError.message}`
    );
    finalError.code = "ERETRY_EXHAUSTED";
    finalError.originalError = lastError;
    throw finalError;
  }

  getStats() {
    return { ...this.retryStats };
  }

  resetStats() {
    this.retryStats = { attempts: 0, successes: 0, failures: 0 };
  }
}

module.exports = RetryHandler;
