```javascript
const fs = require("fs/promises");
const path = require("path");
const crypto = require("crypto");
const { createReadStream } = require("fs");
const RetryHandler = require("./retryHandler");

class FileSync {
  constructor(sourceDir, destDir, options = {}) {
    this.sourceDir = path.resolve(sourceDir);
    this.destDir = path.resolve(destDir);
    this.retryHandler = new RetryHandler(options.retry);
    this.ignoredPatterns = options.ignoredPatterns || [];
    this.syncLog = [];
  }

  /**
   * Compute MD5 hash of a file for comparison
   */
  async getFileHash(filePath) {
    return new Promise((resolve, reject) => {
      const hash = crypto.createHash("md5");
      const stream = createReadStream(filePath);

      stream.on("data", (data) => hash.update(data));
      stream.on("end", () => resolve(hash.digest("hex")));
      stream.on("error", reject);
    });
  }

  /**
   * Check if a filename matches ignored patterns
   */
  isIgnored(fileName) {
    return this.ignoredPatterns.some((pattern) => {
      if (pattern.includes("*")) {
        const regex = new RegExp("^" + pattern.replace(/\*/g, ".*") + "$");
        return regex.test(fileName);
      }
      return fileName === pattern;
    });
  }

  /**
   * Check if a file needs syncing by comparing metadata and hashes
   */
  async needsSync(sourcePath, destPath) {
    try {
      const [sourceStat, destStat] = await Promise.all([
        fs.stat(sourcePath),
        fs.stat(destPath),
      ]);

      // Quick check: different sizes always means out of sync
      if (sourceStat.size !== destStat.size) {
        return true;
      }

      // Same size — compare modification time
      if (sourceStat.mtimeMs <= destStat.mtimeMs) {
        return false;
      }

      // Same size but source is newer — compare hashes to be sure
      const [sourceHash, destHash] = await Promise.all([
        this.getFileHash(sourcePath),
        this.getFileHash(destPath),
      ]);

      return sourceHash !== destHash;
    } catch (error) {
      if (error.code === "ENOENT") {
        return true; // dest doesn't exist
      }
      throw error;
    }
  }

  /**
   * Copy a single file with retry
   */
  async syncFile(relativePath) {
    const sourcePath = path.join(this.sourceDir, relativePath);
    const destPath = path.join(this.destDir, relativePath);
    const label = `sync ${relativePath}`;

    return this.retryHandler.execute(async () => {
      // Ensure destination directory exists
      await fs.mkdir(path.dirname(destPath), { recursive: true });

      // Check if sync is actually needed
      if (!(await this.needsSync(sourcePath, destPath))) {
        return { file: relativePath, action: "skipped" };
      }

      // Copy file preserving timestamps
      await fs.copyFile(sourcePath, destPath);

      // Preserve modification time
      const sourceStat = await fs.stat(sourcePath);
      await fs.utimes(destPath, sourceStat.atime, sourceStat.mtime);

      console.log(`  ✓ Synced: ${relativePath}`);
      this.syncLog.push({
        file: relativePath,
        action: "copied",
        timestamp: new Date().toISOString(),
      });

      return { file: relativePath, action: "copied" };
    }, label);
  }

  /**
   * Delete a file from destination that no longer exists in source
   */
  async deleteFile(relativePath) {
    const destPath = path.join(this.destDir, relativePath);
    const label = `delete ${relativePath}`;

    return this.retryHandler.execute(async () => {
      await fs.unlink(destPath);
      console.log(`  ✓ Deleted: ${relativePath}`);
      this.syncLog.push({
        file: relativePath,
        action: "deleted",
        timestamp: new Date().toISOString(),
      });
      return { file: relativePath, action: "deleted" };
    }, label);
  }

  /**
   * Recursively list all files in a directory
   */
  async listFiles(dir, baseDir = dir) {
    const files = [];

    try {
      const entries = await fs.readdir(dir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        const relativePath = path.relative(baseDir, fullPath);

        if (this.isIgnored(entry.name)) {
          continue;
        }

        if (entry.isDirectory()) {
          const subFiles = await this.listFiles(fullPath, baseDir);
          files.push(...subFiles);
        } else if (entry.isFile()) {
          files.push(relativePath);
        }
      }
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
    }

    return files;
  }

  /**
   * Run a full synchronization
   */
  async fullSync() {
    console.log("\n🔄 Starting full sync...");
    console.log(`   Source: ${this.sourceDir}`);
    console.log(`   Dest:   ${this.destDir}`);

    const startTime = Date.now();
    const results = { copied: 0, skipped: 0, deleted: 0, failed: 0 };

    // Ensure destination root exists
    await fs.mkdir(this.destDir, { recursive: true });

    // Get file lists
    const [sourceFiles, destFiles] = await Promise.all([
      this.listFiles(this.sourceDir),
      this.listFiles(this.destDir),
    ]);

    // Sync source → destination
    for (const file of sourceFiles) {
      try {
        const result = await this.syncFile(file);
        results[result.action]++;
      } catch (error) {
        console.error(`  ✗ Failed: ${file} — ${error.message}`);
        results.failed++;
      }
    }

    // Remove files in dest that don't exist in source
    const sourceSet = new Set(sourceFiles);
    for (const file of destFiles) {
      if (!sourceSet.has(file)) {
        try {
          await this.deleteFile(file);
          results.deleted++;
        } catch (error) {
          console.error(`  ✗ Failed to delete: ${file} — ${error.message}`);
          results.failed++;
        }
      }
    }

    // Clean up empty directories in destination
    await this.removeEmptyDirs(this.destDir);

    const elapsed = Date.now() - startTime;
    console.log(`\n✅ Sync complete in ${elapsed}ms`);
    console.log(
      `   Copied: ${results.copied} | Skipped: ${results.skipped} | ` +
      `Deleted: ${results.deleted} | Failed: ${results.failed}`
    );
    console.log(`   Retry stats:`, this.retryHandler.getStats());

    return results;
  }

  /**
   * Sync a single changed file (used by watcher)
   */
  async syncSingleFile(relativePath) {
    const sourcePath = path.join(this.sourceDir, relativePath);

    try {
      await fs.access(sourcePath);
      return await this.syncFile(relativePath);
    } catch (error) {
      if (error.code === "ENOENT") {
        // Source was deleted — remove from destination
        try {
          return await this.deleteFile(relativePath);
        } catch (delError) {
          if (delError.code === "ENOENT") {
            return { file: relativePath, action: "skipped" };
          }
          throw delError;
        }
      }
      throw error;
    }
  }

  /**
   * Remove empty directories recursively
   */
  async removeEmptyDirs(dir) {
    try {
      const entries = await fs.readdir(dir, { withFileTypes: true });

      for (const entry of entries) {
        if (entry.isDirectory()) {
          await this.removeEmptyDirs(path.join(dir, entry.name));
        }
      }

      // Re-check after cleaning subdirectories
      const remaining = await fs.readdir(dir);
      if (remaining.length === 0 && dir !== this.destDir) {
        await fs.rmdir(dir);
      }
    } catch {
      // Ignore errors during cleanup
    }
  }

  getSyncLog() {
    return [...this.syncLog];
  }
}

module.exports = FileSync;
