```javascript
const fs = require("fs");
const path = require("path");
const { EventEmitter } = require("events");

class FileWatcher extends EventEmitter {
  constructor(directory, options = {}) {
    super();
    this.directory = path.resolve(directory);
    this.debounceMs = options.debounceMs || 300;
    this.ignoredPatterns = options.ignoredPatterns || [];
    this.watchers = new Map();
    this.pendingChanges = new Map();
    this.running = false;
  }

  /**
   * Check if a path should be ignored
   */
  isIgnored(filePath) {
    const fileName = path.basename(filePath);
    return this.ignoredPatterns.some((pattern) => {
      if (pattern.includes("*")) {
        const regex = new RegExp("^" + pattern.replace(/\*/g, ".*") + "$");
        return regex.test(fileName);
      }
      return fileName === pattern;
    });
  }

  /**
   * Start watching the directory
   */
  start() {
    if (this.running) return;
    this.running = true;

    console.log(`👁  Watching: ${this.directory}`);

    try {
      // Use recursive watch (supported on macOS/Windows; Linux needs polyfill)
      const watcher = fs.watch(
        this.directory,
        { recursive: true },
        (eventType, filename) => {
          if (!filename || this.isIgnored(filename)) return;
          this.handleChange(eventType, filename);
        }
      );

      watcher.on("error", (error) => {
        console.error(`Watcher error: ${error.message}`);
        this.emit("error", error);
      });

      this.watchers.set(this.directory, watcher);
    } catch (error) {
      console.error(`Failed to start watcher: ${error.message}`);
      this.emit("error", error);
    }
  }

  /**
   * Debounced change handler — groups rapid changes into one event
   */
  handleChange(eventType, filename) {
    // Normalize path separators
    const normalizedPath = filename.split(path.sep).join("/");

    // Clear existing debounce timer for this file
    if (this.pendingChanges.has(normalizedPath)) {
      clearTimeout(this.pendingChanges.get(normalizedPath));
    }

    // Set a new debounce timer
    const timer = setTimeout(() => {
      this.pendingChanges.delete(normalizedPath);
      console.log(`  📝 Changed: ${normalizedPath} (${eventType})`);
      this.emit("change", normalizedPath, eventType);
    }, this.debounceMs);

    this.pendingChanges.set(normalizedPath, timer);
  }

  /**
   * Stop watching
   */
  stop() {
    this.running = false;

    for (const [, watcher] of this.watchers) {
      watcher.close();
    }
    this.watchers.clear();

    // Clear pending debounce timers
    for (const [, timer] of this.pendingChanges) {
      clearTimeout(timer);
    }
    this.pendingChanges.clear();

    console.log("👁  Watcher stopped");
  }
}

module.exports = FileWatcher;
