## src/tokenizer.js — Text Processing

```javascript
// Stop words to exclude from indexing
const STOP_WORDS = new Set([
  'the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to',
  'for', 'of', 'with', 'by', 'is', 'are', 'was', 'were', 'be',
  'been', 'has', 'have', 'had', 'do', 'does', 'did', 'will',
  'would', 'could', 'should', 'may', 'might', 'this', 'that',
  'it', 'its', 'not', 'no', 'from', 'as', 'if', 'so', 'than',
]);

/**
 * Tokenize text into searchable terms.
 * Returns array of { term, position } objects.
 */
export function tokenize(text) {
  const tokens = [];
  // Split on non-alphanumeric, keep track of position
  const words = text.toLowerCase().match(/[a-z0-9]+/g) || [];

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (word.length < 2 || STOP_WORDS.has(word)) continue;
    tokens.push({ term: stem(word), position: i, original: word });
  }

  return tokens;
}

/**
 * Minimal suffix-stripping stemmer.
 * Not perfect — swap in `natural` or `stemmer` package for production.
 */
function stem(word) {
  if (word.length <= 3) return word;

  const suffixes = ['ing', 'tion', 'ness', 'ment', 'able', 'ible', 'ally', 'ly', 'ed', 'er', 'es', 's'];
  for (const suffix of suffixes) {
    if (word.endsWith(suffix) && word.length - suffix.length >= 3) {
      return word.slice(0, -suffix.length);
    }
  }
  return word;
}

/**
 * Extract a snippet around match positions
 */
export function extractSnippet(text, positions, windowSize = 40) {
  if (!positions.length) return text.slice(0, 100);

  const words = text.split(/\s+/);
  const firstPos = Math.min(...positions);
  const start = Math.max(0, firstPos - 5);
  const end = Math.min(words.length, firstPos + 10);
  const snippet = words.slice(start, end).join(' ');

  return (start > 0 ? '...' : '') + snippet + (end < words.length ? '...' : '');
}
