## src/indexer.js — Inverted Index

```javascript
import fs from 'fs/promises';
import path from 'path';
import { tokenize, extractSnippet } from './tokenizer.js';

const INDEX_PATH = path.resolve('search-index.json');

export class SearchIndex {
  constructor() {
    // Inverted index: term -> [{ filePath, positions, tf }]
    this.invertedIndex = new Map();
    // Forward index: filePath -> { terms, mtime, size, title }
    this.documents = new Map();
    // Track total docs for IDF calculation
    this.totalDocs = 0;
    this.dirty = false;
  }

  /**
   * Add or update a file in the index
   */
  async addFile(filePath) {
    try {
      const stat = await fs.stat(filePath);

      // Skip if unchanged
      const existing = this.documents.get(filePath);
      if (existing && existing.mtime === stat.mtimeMs) {
        return false;
      }

      const content = await fs.readFile(filePath, 'utf-8');
      const tokens = tokenize(content);

      if (tokens.length === 0) return false;

      // Remove old entries first
      this.removeFile(filePath);

      // Build term frequency map for this document
      const termFreqs = new Map();
      for (const { term, position } of tokens) {
        if (!termFreqs.has(term)) {
          termFreqs.set(term, { count: 0, positions: [] });
        }
        const entry = termFreqs.get(term);
        entry.count++;
        entry.positions.push(position);
      }

      // Store document metadata
      this.documents.set(filePath, {
        mtime: stat.mtimeMs,
        size: stat.size,
        title: this.extractTitle(filePath, content),
        termCount: tokens.length,
        terms: [...termFreqs.keys()],
      });

      // Update inverted index
      for (const [term, { count, positions }] of termFreqs) {
        if (!this.invertedIndex.has(term)) {
          this.invertedIndex.set(term, []);
        }
        this.invertedIndex.get(term).push({
          filePath,
          tf: count / tokens.length, // normalized term frequency
          positions,
          count,
        });
      }

      this.totalDocs = this.documents.size;
      this.dirty = true;
      return true;
    } catch (err) {
      if (err.code !== 'ENOENT') {
        console.error(`Index error for ${filePath}:`, err.message);
      }
      return false;
    }
  }

  /**
   * Remove a file from the index
   */
  removeFile(filePath) {
    const doc = this.documents.get(filePath);
    if (!doc) return false;

    // Remove from inverted index
    for (const term of doc.terms) {
      const postings = this.invertedIndex.get(term);
      if (!postings) continue;

      const filtered = postings.filter((p) => p.filePath !== filePath);
      if (filtered.length === 0) {
        this.invertedIndex.delete(term);
      } else {
        this.invertedIndex.set(term, filtered);
      }
    }

    this.documents.delete(filePath);
    this.totalDocs = this.documents.size;
    this.dirty = true;
    return true;
  }

  /**
   * Search the index. Returns ranked results with TF-IDF scoring.
   */
  search(query, limit = 10) {
    const queryTokens = tokenize(query);
    if (queryTokens.length === 0) return [];

    const scores = new Map(); // filePath -> score

    for (const { term } of queryTokens) {
      const postings = this.invertedIndex.get(term);
      if (!postings) continue;

      // IDF: log(totalDocs / docsContainingTerm)
      const idf = Math.log(1 + this.totalDocs / postings.length);

      for (const { filePath, tf, positions, count } of postings) {
        const tfidf = tf * idf;
        const current = scores.get(filePath) || {
          score: 0,
          matchedTerms: 0,
          positions: [],
        };

        current.score += tfidf;
        current.matchedTerms++;
        current.positions.push(...positions);
        scores.set(filePath, current);
      }
    }

    // Boost score for docs matching more query terms
    const results = [];
    for (const [filePath, { score, matchedTerms, positions }] of scores) {
      const doc = this.documents.get(filePath);
      const termCoverageBoost = matchedTerms / queryTokens.length;

      results.push({
        filePath,
        score: score * (1 + termCoverageBoost),
        title: doc?.title || path.basename(filePath),
        matchedTerms,
        positions,
      });
    }

    results.sort((a, b) => b.score - a.score);
    return results.slice(0, limit);
  }

  /**
   * Extract a reasonable title from file content
   */
  extractTitle(filePath, content) {
    // Markdown heading
    const mdMatch = content.match(/^#\s+(.+)$/m);
    if (mdMatch) return mdMatch[1].trim();

    // HTML title
    const htmlMatch = content.match(/<title>(.+?)<\/title>/i);
    if (htmlMatch) return htmlMatch[1].trim();

    // First non-empty line
    const firstLine = content.split('\n').find((l) => l.trim().length > 0);
    if (firstLine) return firstLine.trim().slice(0, 80);

    return path.basename(filePath);
  }

  /**
   * Persist index to disk
   */
  async save() {
    if (!this.dirty) return;

    const data = {
      version: 1,
      totalDocs: this.totalDocs,
      documents: Object.fromEntries(this.documents),
      invertedIndex: Object.fromEntries(this.invertedIndex),
    };

    const tmp = INDEX_PATH + '.tmp';
    await fs.writeFile(tmp, JSON.stringify(data), 'utf-8');
    await fs.rename(tmp, INDEX_PATH); // atomic write
    this.dirty = false;
    console.log(`Index saved: ${this.totalDocs} docs, ${this.invertedIndex.size} terms`);
  }

  /**
   * Load index from disk
   */
  async load() {
    try {
      const raw = await fs.readFile(INDEX_PATH, 'utf-8');
      const data = JSON.parse(raw);

      if (data.version !== 1) {
        console.warn('Index version mismatch, rebuilding...');
        return false;
      }

      this.documents = new Map(Object.entries(data.documents));
      this.invertedIndex = new Map(Object.entries(data.invertedIndex));
      this.totalDocs = data.totalDocs;
      this.dirty = false;

      console.log(`Index loaded: ${this.totalDocs} docs, ${this.invertedIndex.size} terms`);
      return true;
    } catch {
      return false;
    }
  }

  getStats() {
    return {
      documents: this.totalDocs,
      terms: this.invertedIndex.size,
      dirty: this.dirty,
    };
  }
}
