## src/watcher.js — File Watcher with Debouncing

```javascript
import chokidar from 'chokidar';
import path from 'path';
import { EventEmitter } from 'events';

// File extensions worth indexing
const INDEXABLE_EXTENSIONS = new Set([
  '.txt', '.md', '.html', '.htm', '.json', '.csv',
  '.js', '.ts', '.jsx', '.tsx', '.py', '.rb', '.go',
  '.rs', '.java', '.c', '.cpp', '.h', '.css', '.scss',
  '.yaml', '.yml', '.toml', '.xml', '.svg', '.sh',
  '.sql', '.graphql', '.prisma', '.env', '.log',
]);

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

export class FileWatcher extends EventEmitter {
  constructor(watchPaths, options = {}) {
    super();

    this.watchPaths = Array.isArray(watchPaths) ? watchPaths : [watchPaths];
    this.debounceMs = options.debounceMs ?? 300;
    this.saveIntervalMs = options.saveIntervalMs ?? 10_000;
    this.ignored = options.ignored ?? [
      /node_modules/,
      /\.git/,
      /dist\//,
      /build\//,
      /\.DS_Store/,
      /\.swp$/,
      /~$/,
    ];

    // Debounce map: filePath -> timeout
    this.pending = new Map();
    // Batch processing queue
    this.queue = { add: new Set(), remove: new Set() };
    this.processing = false;
    this.watcher = null;
    this.saveTimer = null;
  }

  start() {
    this.watcher = chokidar.watch(this.watchPaths, {
      ignored: this.ignored,
      persistent: true,
      ignoreInitial: false,        // index existing files on startup
      awaitWriteFinish: {          // wait for writes to complete
        stabilityThreshold: 200,
        pollInterval: 100,
      },
      followSymlinks: false,
    });

    this.watcher
      .on('add', (fp) => this.handleChange('add', fp))
      .on('change', (fp) => this.handleChange('update', fp))
      .on('unlink', (fp) => this.handleChange('remove', fp))
      .on('ready', () => {
        console.log('Initial scan complete. Watching for changes...');
        this.emit('ready');
      })
      .on('error', (err) => {
        console.error('Watcher error:', err.message);
        this.emit('error', err);
      });

    // Periodic save
    this.saveTimer = setInterval(() => this.emit('save'), this.saveIntervalMs);
  }

  handleChange(action, filePath) {
    const absPath = path.resolve(filePath);

    // Filter by extension
    if (action !== 'remove' && !this.isIndexable(absPath)) return;

    // Debounce: rapid saves on the same file get collapsed
    if (this.pending.has(absPath)) {
      clearTimeout(this.pending.get(absPath));
    }

    const timeout = setTimeout(() => {
      this.pending.delete(absPath);

      if (action === 'remove') {
        this.queue.add.delete(absPath);
        this.queue.remove.add(absPath);
      } else {
        this.queue.remove.delete(absPath);
        this.queue.add.add(absPath);
      }

      this.flush();
    }, this.debounceMs);

    this.pending.set(absPath, timeout);
  }

  async flush() {
    if (this.processing) return;
    this.processing = true;

    try {
      // Drain the queue
      while (this.queue.add.size > 0 || this.queue.remove.size > 0) {
        const toAdd = [...this.queue.add];
        const toRemove = [...this.queue.remove];
        this.queue.add.clear();
        this.queue.remove.clear();

        if (toRemove.length > 0) {
          this.emit('remove', toRemove);
        }
        if (toAdd.length > 0) {
          this.emit('index', toAdd);
        }
      }
    } finally {
      this.processing = false;
    }
  }

  isIndexable(filePath) {
    const ext = path.extname(filePath).toLowerCase();
    return INDEXABLE_EXTENSIONS.has(ext);
  }

  async stop() {
    if (this.saveTimer) clearInterval(this.saveTimer);
    for (const timeout of this.pending.values()) clearTimeout(timeout);
    this.pending.clear();

    if (this.watcher) {
      await this.watcher.close();
      console.log('Watcher stopped');
    }
  }
}
