```javascript
import path from 'path';
import { FileWatcher } from './watcher.js';
import { SearchIndex } from './indexer.js';

const WATCH_DIR = process.argv[2] || './data';

async function main() {
  const index = new SearchIndex();
  await index.load(); // try loading existing index

  const watcher = new FileWatcher(path.resolve(WATCH_DIR), {
    debounceMs: 300,
    saveIntervalMs: 15_000,
  });

  // Wire up events
  let indexedCount = 0;
  let removedCount = 0;

  watcher.on('index', async (filePaths) => {
    const start = performance.now();
    let changed = 0;

    for (const fp of filePaths) {
      const wasNew = await index.addFile(fp);
      if (wasNew) changed++;
    }

    if (changed > 0) {
      indexedCount += changed;
      const ms = (performance.now() - start).toFixed(1);
      console.log(`Indexed ${changed} file(s) in ${ms}ms [total: ${index.totalDocs}]`);
    }
  });

  watcher.on('remove', (filePaths) => {
    for (const fp of filePaths) {
      const removed = index.removeFile(fp);
      if (removed) {
        removedCount++;
        console.log(`Removed from index: ${path.basename(fp)}`);
      }
    }
  });

  watcher.on('save', () => index.save());
  watcher.on('ready', () => printStats(index));

  // Graceful shutdown
  const shutdown = async () => {
    console.log('\nShutting down...');
    await watcher.stop();
    await index.save();
    console.log(`Session: indexed ${indexedCount}, removed ${removedCount}`);
    process.exit(0);
  };

  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);

  // Start watching
  watcher.start();

  // Optional: interactive search via stdin
  if (process.stdin.isTTY) {
    startInteractiveSearch(index);
  }
}

function startInteractiveSearch(index) {
  const readline = await import('readline');
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  console.log('\nType a search query and press Enter (or Ctrl+C to quit):\n');

  rl.on('line', (line) => {
    const query = line.trim();
    if (!query) return;

    if (query === ':stats') {
      printStats(index);
      return;
    }

    const start = performance.now();
    const results = index.search(query);
    const ms = (performance.now() - start).toFixed(2);

    if (results.length === 0) {
      console.log(`  No results for "${query}" (${ms}ms)\n`);
      return;
    }

    console.log(`  ${results.length} result(s) for "${query}" (${ms}ms):`);
    for (const r of results) {
      const rel = path.relative(process.cwd(), r.filePath);
      console.log(`    ${r.score.toFixed(3)}  ${rel}  — ${r.title}`);
    }
    console.log();
  });
}

function printStats(index) {
  const stats = index.getStats();
  console.log(`\nIndex stats: ${stats.documents} docs, ${stats.terms} unique terms\n`);
}

main().catch(console.error);
