### `src/retry.js` — Retry with Exponential Backoff
```javascript
import { logger } from "./logger.js";

/**
 * Wraps an async function with retry logic.
 *
 * @param {Function} fn          - Async function to retry
 * @param {Object}   options
 * @param {number}   options.maxRetries    - Max retry attempts (default: 3)
 * @param {number}   options.baseDelayMs   - Initial delay in ms (default: 500)
 * @param {number}   options.maxDelayMs    - Delay cap in ms (default: 10000)
 * @param {number}   options.backoffFactor - Multiplier per attempt (default: 2)
 * @param {Function} options.shouldRetry   - Predicate for retryable errors
 * @returns {Function} Wrapped function with retry behaviour
 */
export function withRetry(fn, options = {}) {
  const {
    maxRetries    = 3,
    baseDelayMs   = 500,
    maxDelayMs    = 10_000,
    backoffFactor = 2,
    shouldRetry   = () => true,       // retry all errors by default
    onRetry       = null,             // optional callback(error, attempt)
  } = options;

  return async function retryWrapper(...args) {
    let lastError;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        return await fn(...args);
      } catch (error) {
        lastError = error;

        // Check if we should retry this specific error
        if (attempt >= maxRetries || !shouldRetry(error)) {
          break;
        }

        // Calculate delay with jitter to avoid thundering herd
        const exponentialDelay = baseDelayMs * backoffFactor ** attempt;
        const jitter = Math.random() * baseDelayMs;
        const delay = Math.min(exponentialDelay + jitter, maxDelayMs);

        logger.warn(`Retry ${attempt + 1}/${maxRetries}`, {
          function: fn.name,
          delay: `${Math.round(delay)}ms`,
          error: error.message,
        });

        if (onRetry) onRetry(error, attempt + 1);

        await sleep(delay);
      }
    }

    throw lastError;
  };
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Common retry predicates
 */
export const retryPredicates = {
  // Retry on network / transient errors
  isTransient: (error) =>
    ["ECONNRESET", "ETIMEDOUT", "ECONNREFUSED", "EPIPE"].includes(error.code) ||
    [429, 500, 502, 503, 504].includes(error.statusCode),

  // Never retry validation errors
  isNotValidation: (error) => error.name !== "ValidationError",
};
```

