import { logger } from "../logger.js";

export async function transform(events) {
  logger.info("Transforming events", { count: events.length });

  const results = { valid: [], invalid: [] };

  for (const event of events) {
    // ── Validation ──────────────────────────
    const errors = [];
    if (!event.userId) errors.push("missing userId");
    if (!event.ts)     errors.push("missing timestamp");

    if (errors.length > 0) {
      results.invalid.push({ ...event, errors });
      continue;
    }

    // ── Transformation ──────────────────────
    results.valid.push({
      eventId:   event.eventId,
      userId:    event.userId,
      action:    event.action,
      timestamp: new Date(event.ts).toISOString(),
      metadata:  extractMetadata(event),
      processed: true,
    });
  }

  logger.info("Transform complete", {
    valid: results.valid.length,
    invalid: results.invalid.length,
  });

  return results;
}

function extractMetadata(event) {
  const { eventId, userId, action, ts, raw, ...rest } = event;
  return rest;
}
