### `src/pipeline.js` — Pipeline Orchestrator
```javascript
import { withRetry, retryPredicates } from "./retry.js";
import { ingest }    from "./stages/ingest.js";
import { transform } from "./stages/transform.js";
import { enrich }    from "./stages/enrich.js";
import { load }      from "./stages/load.js";
import { logger }    from "./logger.js";

/**
 * Defines the pipeline: an ordered list of named stages,
 * each wrapped with its own retry policy.
 */
function buildStages() {
  return [
    {
      name: "ingest",
      run: withRetry(ingest, {
        maxRetries:  3,
        baseDelayMs: 300,
        shouldRetry: retryPredicates.isTransient,
      }),
    },
    {
      name: "transform",
      // Transform is pure / deterministic → no retry needed
      run: transform,
    },
    {
      name: "enrich",
      run: withRetry(enrich, {
        maxRetries:  4,
        baseDelayMs: 200,
        shouldRetry: retryPredicates.isTransient,
      }),
    },
    {
      name: "load",
      run: withRetry(load, {
        maxRetries:  3,
        baseDelayMs: 500,
        shouldRetry: retryPredicates.isTransient,
      }),
    },
  ];
}

/**
 * Runs the full analytics pipeline.
 * Each stage receives the output of the previous one.
 */
export async function runPipeline(source) {
  const stages  = buildStages();
  const metrics = { startedAt: Date.now(), stages: {} };
  let data = source;

  logger.info("═══ Pipeline started ═══", { source });

  for (const stage of stages) {
    const stageStart = Date.now();

    try {
      logger.info(`── Stage: ${stage.name} ──`);
      data = await stage.run(data);

      metrics.stages[stage.name] = {
        status:   "success",
        duration: Date.now() - stageStart,
      };
    } catch (error) {
      metrics.stages[stage.name] = {
        status:   "failed",
        duration: Date.now() - stageStart,
        error:    error.message,
      };

      logger.error(`Pipeline failed at stage: ${stage.name}`, {
        error: error.message,
      });

      return {
        success: false,
        failedStage: stage.name,
        error: error.message,
        metrics,
      };
    }
  }

  metrics.totalDuration = Date.now() - metrics.startedAt;

  logger.info("═══ Pipeline complete ═══", { metrics });

  return { success: true, data, metrics };
}
