## `src/main.rs`

```rust
use chrono::{Local, NaiveDateTime};
use clap::{Parser, Subcommand};
use serde::{Deserialize, Serialize};
use std::{fs, process, thread, time::Duration};

const STORE_FILE: &str = "tasks.json";

// ── CLI definition ──────────────────────────────────────────

#[derive(Parser)]
#[command(name = "tasksched", about = "A basic CLI task scheduler")]
struct Cli {
    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// Add a task  e.g.  add "deploy app" --at "2025-07-20 14:30"
    Add {
        /// Task description
        description: String,
        /// Schedule time  "YYYY-MM-DD HH:MM"
        #[arg(short, long)]
        at: String,
    },
    /// List all tasks
    List,
    /// Mark a task as done by ID
    Done {
        /// Task ID
        id: u32,
    },
    /// Remove a task by ID
    Remove {
        /// Task ID
        id: u32,
    },
    /// Start the scheduler daemon (polls every second)
    Run,
}

// ── Data model ──────────────────────────────────────────────

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
#[serde(rename_all = "lowercase")]
enum Status {
    Pending,
    Done,
}

#[derive(Serialize, Deserialize, Clone)]
struct Task {
    id: u32,
    description: String,
    scheduled_at: NaiveDateTime,
    status: Status,
}

// ── Persistence ─────────────────────────────────────────────

fn load_tasks() -> Vec<Task> {
    fs::read_to_string(STORE_FILE)
        .ok()
        .and_then(|data| serde_json::from_str(&data).ok())
        .unwrap_or_default()
}

fn save_tasks(tasks: &[Task]) {
    let json = serde_json::to_string_pretty(tasks).expect("failed to serialize");
    fs::write(STORE_FILE, json).expect("failed to write store file");
}

fn next_id(tasks: &[Task]) -> u32 {
    tasks.iter().map(|t| t.id).max().unwrap_or(0) + 1
}

fn find_index(tasks: &[Task], id: u32) -> Option<usize> {
    tasks.iter().position(|t| t.id == id)
}

// ── Command handlers ────────────────────────────────────────

fn cmd_add(description: &str, at: &str) {
    let scheduled_at = NaiveDateTime::parse_from_str(at, "%Y-%m-%d %H:%M")
        .unwrap_or_else(|_| {
            eprintln!("Error: bad format. Use \"YYYY-MM-DD HH:MM\"");
            process::exit(1);
        });

    let mut tasks = load_tasks();
    let id = next_id(&tasks);

    tasks.push(Task {
        id,
        description: description.to_string(),
        scheduled_at,
        status: Status::Pending,
    });
    save_tasks(&tasks);

    println!("Added task #{id}: \"{description}\" @ {scheduled_at}");
}

fn cmd_list() {
    let tasks = load_tasks();
    if tasks.is_empty() {
        println!("No tasks.");
        return;
    }

    let now = Local::now().naive_local();

    println!(
        "{:<5} {:<20} {:<10} {}",
        "ID", "Scheduled", "Status", "Description"
    );
    println!("{}", "-".repeat(65));

    for t in &tasks {
        let status_label = match &t.status {
            Status::Done => "done",
            Status::Pending if t.scheduled_at <= now => "overdue",
            Status::Pending => "pending",
        };
        println!(
            "{:<5} {:<20} {:<10} {}",
            t.id,
            t.scheduled_at.format("%Y-%m-%d %H:%M"),
            status_label,
            t.description,
        );
    }
}

fn cmd_done(id: u32) {
    let mut tasks = load_tasks();

    match find_index(&tasks, id) {
        Some(i) => {
            tasks[i].status = Status::Done;
            save_tasks(&tasks);
            println!("Task #{id} marked as done.");
        }
        None => eprintln!("Task #{id} not found."),
    }
}

fn cmd_remove(id: u32) {
    let mut tasks = load_tasks();
    let before = tasks.len();
    tasks.retain(|t| t.id != id);

    if tasks.len() < before {
        save_tasks(&tasks);
        println!("Removed task #{id}.");
    } else {
        eprintln!("Task #{id} not found.");
    }
}

fn cmd_run() {
    println!("Scheduler running (poll: 1 s). Ctrl+C to stop.\n");

    loop {
        let mut tasks = load_tasks();
        let now = Local::now().naive_local();
        let mut changed = false;

        for task in &mut tasks {
            if task.status == Status::Pending && now >= task.scheduled_at {
                println!(
                    "[{}] FIRED  #{}: {}",
                    Local::now().format("%H:%M:%S"),
                    task.id,
                    task.description,
                );
                task.status = Status::Done;
                changed = true;
            }
        }

        if changed {
            save_tasks(&tasks);
        }

        thread::sleep(Duration::from_secs(1));
    }
}

// ── Entry point ─────────────────────────────────────────────

fn main() {
    let cli = Cli::parse();

    match cli.command {
        Command::Add { description, at } => cmd_add(&description, &at),
        Command::List => cmd_list(),
        Command::Done { id } => cmd_done(id),
        Command::Remove { id } => cmd_remove(id),
        Command::Run => cmd_run(),
    }
}
```

