```bash
# Build
cargo build --release

# Add tasks (quote the datetime string)
./tasksched add "Deploy to production" --at "2025-07-20 14:30"
./tasksched add "Team standup"         --at "2025-07-21 09:00"
./tasksched add "Send report"          --at "2025-07-20 17:00"

# List all tasks
./tasksched list
# ID    Scheduled            Status     Description
# -----------------------------------------------------------------
# 1     2025-07-20 14:30     pending    Deploy to production
# 2     2025-07-21 09:00     pending    Team standup
# 3     2025-07-20 17:00     overdue    Send report

# Manually complete a task
./tasksched done 1

# Remove a task entirely
./tasksched remove 3

# Start the scheduler (fires tasks when their time arrives)
