# Scheduler running (poll: 1 s). Ctrl+C to stop.
#
# [14:30:00] FIRED  #1: Deploy to production
```

## How it works

| Piece | Role |
|---|---|
| **`tasks.json`** | Flat-file store (auto-created on first `add`) |
| **`add`** | Parses the datetime, assigns an auto-increment ID, appends to the store |
| **`list`** | Reads the store and compares each task's time to *now* for the status label (`pending` / `overdue` / `done`) |
| **`done`** | Manually flips a task's status to `done` |
| **`remove`** | Deletes a task from the store by ID |
| **`run`** | Polls the store every second; any `pending` task whose time has passed gets fired and marked `done` |

The scheduler intentionally re-reads the file each tick so you can `add`/`remove` tasks in another terminal while `run` is active.

# Cache Invalidation Migration Helper in JavaScript

Here's a comprehensive migration helper that manages cache invalidation across schema or data changes with version tracking, multiple strategies, and rollback support.

## Core Migration Helper

```javascript
// migrationHelper.js

/**
 * Represents a single migration definition.
 * @typedef {Object} MigrationDef
 * @property {string} id        - Unique migration identifier (e.g., "20240115_user_schema_v2")
 * @property {number} version   - Numeric version for ordering
 * @property {string} description
 * @property {string[]} affectedKeys  - Cache key patterns this migration invalidates
 * @property {Function} up      - Forward migration logic
 * @property {Function} down    - Rollback logic
 */

class CacheMigrationHelper {
  /**
   * @param {Object} cacheAdapter   - Adapter implementing get/set/del/keys/flush
   * @param {Object} [options]
   * @param {string} [options.metaKey="_cache_migration_meta"]
   * @param {number} [options.batchSize=100]
   * @param {Function} [options.logger=console.log]
   * @param {boolean} [options.dryRun=false]
   */
  constructor(cacheAdapter, options = {}) {
    this.cache = cacheAdapter;
    this.metaKey = options.metaKey ?? "_cache_migration_meta";
    this.batchSize = options.batchSize ?? 100;
    this.logger = options.logger ?? console.log;
    this.dryRun = options.dryRun ?? false;

    /** @type {MigrationDef[]} */
    this.migrations = [];

    /** @type {Map<string, MigrationDef>} */
    this.migrationIndex = new Map();
  }

  // ─── Registration ───────────────────────────────────────────

  /**
   * Register one or more migrations.
   * @param  {...MigrationDef} defs
   * @returns {this}
   */
  register(...defs) {
    for (const def of defs) {
      this._validateDef(def);

      if (this.migrationIndex.has(def.id)) {
        throw new Error(`Duplicate migration id: "${def.id}"`);
      }

      this.migrations.push(def);
      this.migrationIndex.set(def.id, def);
    }

    // Keep sorted by version for ordered execution
    this.migrations.sort((a, b) => a.version - b.version);
    return this;
  }

  // ─── Execution ──────────────────────────────────────────────

  /**
   * Run all pending migrations forward.
   * @returns {Promise<MigrationResult>}
   */
  async migrateUp() {
    const meta = await this._loadMeta();
    const pending = this.migrations.filter(
      (m) => !meta.applied.includes(m.id)
    );

    if (pending.length === 0) {
      this.logger("[migrate] No pending migrations.");
      return { applied: [], skipped: this.migrations.length, errors: [] };
    }

    this.logger(`[migrate] ${pending.length} pending migration(s) found.`);

    const result = { applied: [], skipped: 0, errors: [] };

    for (const migration of pending) {
      try {
        await this._runSingle(migration, "up", meta);
        result.applied.push(migration.id);
      } catch (err) {
        result.errors.push({ id: migration.id, error: err.message });
        this.logger(`[migrate] ❌ "${migration.id}" failed: ${err.message}`);
        break; // Stop on first failure
      }
    }

    return result;
  }

  /**
   * Roll back the last N applied migrations.
   * @param {number} [steps=1]
   * @returns {Promise<MigrationResult>}
   */
  async migrateDown(steps = 1) {
    const meta = await this._loadMeta();
    const toRollback = [...meta.applied].reverse().slice(0, steps);

    const result = { applied: [], skipped: 0, errors: [] };

    for (const id of toRollback) {
      const migration = this.migrationIndex.get(id);
      if (!migration) {
        result.errors.push({ id, error: "Migration definition not found" });
        continue;
      }

      try {
        await this._runSingle(migration, "down", meta);
        result.applied.push(id);
      } catch (err) {
        result.errors.push({ id, error: err.message });
        break;
      }
    }

    return result;
  }

  /**
   * Run a specific migration by ID (useful for targeted reruns).
   * @param {string} id
   * @param {"up"|"down"} direction
   */
  async runById(id, direction = "up") {
    const migration = this.migrationIndex.get(id);
    if (!migration) throw new Error(`Migration "${id}" not registered.`);

    const meta = await this._loadMeta();
    await this._runSingle(migration, direction, meta);
  }

  // ─── Cache Invalidation Strategies ──────────────────────────

  /**
   * Invalidate cache entries matching exact keys.
   * @param {string[]} keys
   * @returns {Promise<number>} count of deleted keys
   */
  async invalidateByKeys(keys) {
    let count = 0;

    for (const key of keys) {
      if (this.dryRun) {
        this.logger(`[dry-run] Would delete key: "${key}"`);
      } else {
        await this.cache.del(key);
      }
      count++;
    }

    this.logger(`[invalidate] Removed ${count} key(s) by exact match.`);
    return count;
  }

  /**
   * Invalidate cache entries matching glob/regex patterns.
   * @param {string[]} patterns - Glob-style patterns (e.g., "user:*", "session:v1:*")
   * @returns {Promise<number>}
   */
  async invalidateByPattern(patterns) {
    let totalDeleted = 0;

    for (const pattern of patterns) {
      const regex = this._patternToRegex(pattern);
      const allKeys = await this.cache.keys(pattern);

      // Process in batches to avoid blocking
      for (let i = 0; i < allKeys.length; i += this.batchSize) {
        const batch = allKeys.slice(i, i + this.batchSize);
        const matched = batch.filter((k) => regex.test(k));

        if (this.dryRun) {
          matched.forEach((k) =>
            this.logger(`[dry-run] Would delete: "${k}"`)
          );
        } else {
          await Promise.all(matched.map((k) => this.cache.del(k)));
        }

        totalDeleted += matched.length;
      }
    }

    this.logger(`[invalidate] Removed ${totalDeleted} key(s) by pattern.`);
    return totalDeleted;
  }

  /**
   * Invalidate entries by version prefix.
   * Keys are expected as "prefix:v{N}:rest" — removes all versions below `minVersion`.
   * @param {string} prefix
   * @param {number} minVersion
   * @returns {Promise<number>}
   */
  async invalidateByVersion(prefix, minVersion) {
    const allKeys = await this.cache.keys(`${prefix}:*`);
    const versionRegex = new RegExp(`^${this._escapeRegex(prefix)}:v(\\d+):`);
    let count = 0;

    for (const key of allKeys) {
      const match = key.match(versionRegex);
      if (match && parseInt(match[1], 10) < minVersion) {
        if (!this.dryRun) await this.cache.del(key);
        count++;
      }
    }

    this.logger(
      `[invalidate] Removed ${count} key(s) below v${minVersion} for "${prefix}".`
    );
    return count;
  }

  /**
   * Transform cached values in-place (lazy migration strategy).
   * Reads each matching key, runs `transform`, writes back.
   * @param {string} pattern
   * @param {Function} transform - (value, key) => newValue | null (null = delete)
   * @returns {Promise<{transformed: number, deleted: number}>}
   */
  async transformByPattern(pattern, transform) {
    const keys = await this.cache.keys(pattern);
    let transformed = 0;
    let deleted = 0;

    for (let i = 0; i < keys.length; i += this.batchSize) {
      const batch = keys.slice(i, i + this.batchSize);

      await Promise.all(
        batch.map(async (key) => {
          const value = await this.cache.get(key);
          if (value === null || value === undefined) return;

          const newValue = transform(value, key);

          if (this.dryRun) {
            this.logger(`[dry-run] Would transform: "${key}"`);
            return;
          }

          if (newValue === null) {
            await this.cache.del(key);
            deleted++;
          } else {
            await this.cache.set(key, newValue);
            transformed++;
          }
        })
      );
    }

    this.logger(
      `[transform] ${transformed} transformed, ${deleted} deleted.`
    );
    return { transformed, deleted };
  }

  // ─── Status / Inspection ────────────────────────────────────

  /**
   * Return current migration status.
   */
  async status() {
    const meta = await this._loadMeta();
    return {
      currentVersion: meta.currentVersion,
      appliedCount: meta.applied.length,
      pendingCount: this.migrations.filter(
        (m) => !meta.applied.includes(m.id)
      ).length,
      applied: meta.history.map((h) => ({
        id: h.id,
        direction: h.direction,
        timestamp: h.timestamp,
      })),
      pending: this.migrations
        .filter((m) => !meta.applied.includes(m.id))
        .map((m) => ({ id: m.id, version: m.version, description: m.description })),
    };
  }

  // ─── Internals ──────────────────────────────────────────────

  /** @private */
  async _runSingle(migration, direction, meta) {
    const label = `${direction === "up" ? "⬆" : "⬇"} ${migration.id}`;
    this.logger(`[migrate] ${label} — ${migration.description}`);

    const ctx = this._createContext(migration);
    const startTime = Date.now();

    if (direction === "up") {
      await migration.up(ctx);
      meta.applied.push(migration.id);
      meta.currentVersion = migration.version;
    } else {
      await migration.down(ctx);
      meta.applied = meta.applied.filter((id) => id !== migration.id);
      // Set version to previous migration or 0
      const remaining = this.migrations.filter((m) =>
        meta.applied.includes(m.id)
      );
      meta.currentVersion =
        remaining.length > 0 ? remaining[remaining.length - 1].version : 0;
    }

    meta.history.push({
      id: migration.id,
      direction,
      timestamp: new Date().toISOString(),
      durationMs: Date.now() - startTime,
      stats: ctx.stats,
    });

    if (!this.dryRun) {
      await this.cache.set(this.metaKey, JSON.stringify(meta));
    }

    this.logger(
      `[migrate] ${label} complete (${Date.now() - startTime}ms) — ` +
        `invalidated: ${ctx.stats.invalidated}, transformed: ${ctx.stats.transformed}`
    );
  }

  /**
   * Build a context object passed to each migration's up/down function.
   * @private
   */
  _createContext(migration) {
    const stats = { invalidated: 0, transformed: 0, errors: 0 };

    return {
      cache: this.cache,
      dryRun: this.dryRun,
      stats,

      /** Invalidate specific keys */
      invalidateKeys: async (keys) => {
        const count = await this.invalidateByKeys(keys);
        stats.invalidated += count;
      },

      /** Invalidate by glob pattern */
      invalidatePattern: async (...patterns) => {
        const count = await this.invalidateByPattern(patterns);
        stats.invalidated += count;
      },

      /** Invalidate by version threshold */
      invalidateVersion: async (prefix, minVersion) => {
        const count = await this.invalidateByVersion(prefix, minVersion);
        stats.invalidated += count;
      },

      /** Transform cached values matching a pattern */
      transform: async (pattern, fn) => {
        const result = await this.transformByPattern(pattern, fn);
        stats.transformed += result.transformed;
        stats.invalidated += result.deleted;
      },

      /** Flush entire cache (nuclear option) */
      flushAll: async () => {
        if (this.dryRun) {
          this.logger("[dry-run] Would flush entire cache.");
          return;
        }
        await this.cache.flush();
        this.logger("[migrate] Full cache flush executed.");
      },

      /** Convenience: write a new versioned key */
      setVersioned: async (prefix, id, version, value, ttl) => {
        const key = `${prefix}:v${version}:${id}`;
        if (!this.dryRun) {
          await this.cache.set(key, value, ttl);
        }
      },
    };
  }

  /** @private */
  async _loadMeta() {
    const raw = await this.cache.get(this.metaKey);
    if (raw) {
      return typeof raw === "string" ? JSON.parse(raw) : raw;
    }
    return { currentVersion: 0, applied: [], history: [] };
  }

  /** @private */
  _validateDef(def) {
    const required = ["id", "version", "up", "down"];
    for (const field of required) {
      if (!def[field]) {
        throw new Error(`Migration missing required field: "${field}"`);
      }
    }
    if (typeof def.version !== "number") {
      throw new Error(`Migration "${def.id}": version must be a number.`);
    }
  }

  /** Convert glob pattern "user:*:profile" → RegExp */
  _patternToRegex(pattern) {
    const escaped = pattern
      .replace(/[.+^${}()|[\]\\]/g, "\\$&")
      .replace(/\*/g, ".*")
      .replace(/\?/g, ".");
    return new RegExp(`^${escaped}$`);
  }

  _escapeRegex(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
}

module.exports = { CacheMigrationHelper };
```

## Cache Adapter (Redis-like in-memory example)

```javascript
// cacheAdapter.js

/**
 * In-memory cache adapter that mirrors a Redis-like API.
 * Swap this out for ioredis / node-cache / memcached in production.
 */
class InMemoryCacheAdapter {
  constructor() {
    /** @type {Map<string, {value: any, expiresAt: number|null}>} */
    this.store = new Map();
  }

  async get(key) {
    const entry = this.store.get(key);
    if (!entry) return null;

    if (entry.expiresAt && Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return null;
    }

    return entry.value;
  }

  /**
   * @param {string} key
   * @param {any} value
   * @param {number} [ttlSeconds]
   */
  async set(key, value, ttlSeconds) {
    this.store.set(key, {
      value,
      expiresAt: ttlSeconds ? Date.now() + ttlSeconds * 1000 : null,
    });
  }

  async del(key) {
    return this.store.delete(key);
  }

  /**
   * Return keys matching a glob-like pattern.
   * Supports only '*' wildcards for simplicity.
   */
  async keys(pattern = "*") {
    const regex = new RegExp(
      "^" +
        pattern
          .replace(/[.+^${}()|[\]\\]/g, "\\$&")
          .replace(/\*/g, ".*") +
        "$"
    );

    const results = [];
    for (const [key, entry] of this.store) {
      if (entry.expiresAt && Date.now() > entry.expiresAt) {
        this.store.delete(key);
        continue;
      }
      if (regex.test(key)) results.push(key);
    }
    return results;
  }

  async flush() {
    this.store.clear();
  }

  // Helpful for debugging
  dump() {
    const obj = {};
    for (const [k, v] of this.store) obj[k] = v.value;
    return obj;
  }
}

module.exports = { InMemoryCacheAdapter };
