## Config Parser

```javascript
// src/configParser.js
const fs = require("fs");
const path = require("path");
const { EventEmitter } = require("events");

// Schema definition for validation
const SCHEMA = {
  global: {
    windowMs: { type: "number", min: 1000, max: 86400000, default: 60000 },
    maxRequests: { type: "number", min: 1, max: 100000, default: 100 },
    strategy: {
      type: "enum",
      values: ["fixed-window", "sliding-window", "token-bucket"],
      default: "sliding-window",
    },
    message: { type: "string", default: "Too many requests." },
    statusCode: { type: "number", min: 400, max: 599, default: 429 },
    headers: { type: "boolean", default: true },
  },
  route: {
    windowMs: { type: "number", min: 1000, max: 86400000 },
    maxRequests: { type: "number", min: 1, max: 100000 },
    strategy: {
      type: "enum",
      values: ["fixed-window", "sliding-window", "token-bucket"],
    },
    message: { type: "string" },
    statusCode: { type: "number", min: 400, max: 599 },
    blockDurationMs: { type: "number", min: 0, max: 86400000 },
    costPerRequest: { type: "number", min: 1, max: 100, default: 1 },
    refillRate: { type: "number", min: 1, max: 10000 },
    refillIntervalMs: { type: "number", min: 1000, max: 86400000 },
  },
  tier: {
    multiplier: { type: "number", min: 0.1, max: 1000, default: 1.0 },
    burstAllowance: { type: "number", min: 0, max: 100000, default: 0 },
  },
};

class ConfigParser extends EventEmitter {
  #config = null;
  #filePath = null;
  #watcher = null;
  #envPrefix = "RATE_LIMIT";

  constructor(filePath, options = {}) {
    super();
    this.#filePath = path.resolve(filePath);
    this.#envPrefix = options.envPrefix || "RATE_LIMIT";
  }

  /**
   * Load, merge environment overrides, and validate the full config
   */
  load() {
    const raw = this.#readFile();
    const withEnv = this.#applyEnvOverrides(raw);
    const validated = this.#validate(withEnv);
    this.#config = Object.freeze(this.#deepFreeze(validated));
    this.emit("loaded", this.#config);
    return this.#config;
  }

  /**
   * Watch the config file for live changes
   */
  watch() {
    if (this.#watcher) return;

    let debounce = null;
    this.#watcher = fs.watch(this.#filePath, (eventType) => {
      if (eventType !== "change") return;

      // Debounce rapid file-system events
      clearTimeout(debounce);
      debounce = setTimeout(() => {
        try {
          const previous = this.#config;
          this.load();
          this.emit("changed", this.#config, previous);
        } catch (err) {
          this.emit("error", err);
        }
      }, 250);
    });

    this.emit("watching", this.#filePath);
  }

  stopWatching() {
    if (this.#watcher) {
      this.#watcher.close();
      this.#watcher = null;
    }
  }

  // ── Accessors ─────────────────────────────────────────────

  get config() {
    if (!this.#config) {
      throw new Error("Config not loaded. Call .load() first.");
    }
    return this.#config;
  }

  /** Resolved config for a specific route (route-specific merged over global) */
  getRouteConfig(routePath) {
    const cfg = this.config;
    const match = this.#matchRoute(routePath, cfg.routes);
    // Merge: global defaults ← route overrides
    return { ...cfg.global, costPerRequest: 1, ...match };
  }

  /** Apply tier multiplier to a route config */
  getEffectiveLimit(routePath, tier = "free") {
    const routeCfg = this.getRouteConfig(routePath);
    const tierCfg = this.config.tiers[tier] || this.config.tiers.free;

    return {
      ...routeCfg,
      maxRequests: Math.floor(
        routeCfg.maxRequests * tierCfg.multiplier + tierCfg.burstAllowance
      ),
      tier,
      multiplier: tierCfg.multiplier,
    };
  }

  isWhitelisted(ip) {
    return this.config.whitelist.some((entry) =>
      this.#matchCIDR(ip, entry)
    );
  }

  isBlacklisted(ip) {
    return this.config.blacklist.some((entry) =>
      this.#matchCIDR(ip, entry)
    );
  }

  // ── Private helpers ───────────────────────────────────────

  #readFile() {
    if (!fs.existsSync(this.#filePath)) {
      throw new ConfigError(`Config file not found: ${this.#filePath}`);
    }
    const raw = fs.readFileSync(this.#filePath, "utf-8");

    try {
      return JSON.parse(raw);
    } catch {
      throw new ConfigError(`Invalid JSON in ${this.#filePath}`);
    }
  }

  /**
   * Override any config value via environment variables.
   *   RATE_LIMIT_GLOBAL_WINDOWMS=30000
   *   RATE_LIMIT_GLOBAL_MAXREQUESTS=50
   *   RATE_LIMIT_ROUTE__API_AUTH_LOGIN__MAXREQUESTS=10
   */
  #applyEnvOverrides(config) {
    const result = structuredClone(config);
    const prefix = this.#envPrefix + "_";

    for (const [key, value] of Object.entries(process.env)) {
      if (!key.startsWith(prefix)) continue;

      const parts = key
        .slice(prefix.length)
        .toLowerCase()
        .split("_")
        .filter(Boolean);

      this.#setNested(result, parts, this.#coerceValue(value));
    }

    return result;
  }

  #setNested(obj, parts, value) {
    let current = obj;
    for (let i = 0; i < parts.length - 1; i++) {
      const key = parts[i];
      if (!(key in current) || typeof current[key] !== "object") {
        current[key] = {};
      }
      current = current[key];
    }
    current[parts.at(-1)] = value;
  }

  #coerceValue(str) {
    if (str === "true") return true;
    if (str === "false") return false;
    if (/^\d+$/.test(str)) return parseInt(str, 10);
    if (/^\d+\.\d+$/.test(str)) return parseFloat(str);
    return str;
  }

  // ── Validation ────────────────────────────────────────────

  #validate(raw) {
    const errors = [];

    // Validate global section
    const global = this.#validateSection(
      raw.global || {},
      SCHEMA.global,
      "global",
      errors
    );

    // Validate each route
    const routes = {};
    if (raw.routes && typeof raw.routes === "object") {
      for (const [route, routeCfg] of Object.entries(raw.routes)) {
        routes[route] = this.#validateSection(
          routeCfg,
          SCHEMA.route,
          `routes.${route}`,
          errors
        );

        // Token-bucket requires refillRate + refillIntervalMs
        if (routes[route].strategy === "token-bucket") {
          if (!routes[route].refillRate || !routes[route].refillIntervalMs) {
            errors.push(
              `routes.${route}: token-bucket strategy requires "refillRate" and "refillIntervalMs"`
            );
          }
        }
      }
    }

    // Validate tiers
    const tiers = {};
    if (raw.tiers && typeof raw.tiers === "object") {
      for (const [name, tierCfg] of Object.entries(raw.tiers)) {
        tiers[name] = this.#validateSection(
          tierCfg,
          SCHEMA.tier,
          `tiers.${name}`,
          errors
        );
      }
    }

    // Validate lists
    const whitelist = this.#validateIPList(raw.whitelist, "whitelist", errors);
    const blacklist = this.#validateIPList(raw.blacklist, "blacklist", errors);

    // Validate store config
    const store = this.#validateStore(raw.store, errors);

    if (errors.length > 0) {
      throw new ConfigValidationError(errors);
    }

    return {
      global,
      routes,
      tiers,
      whitelist,
      blacklist,
      keyGenerator: raw.keyGenerator || "ip",
      skipFailedRequests: Boolean(raw.skipFailedRequests),
      skipSuccessfulRequests: Boolean(raw.skipSuccessfulRequests),
      store,
    };
  }

  #validateSection(data, schema, path, errors) {
    const result = {};

    for (const [field, rules] of Object.entries(schema)) {
      let value = data[field];

      // Apply default if missing
      if (value === undefined || value === null) {
        if ("default" in rules) {
          result[field] = rules.default;
        }
        continue; // optional field with no default → skip
      }

      // Type checks
      switch (rules.type) {
        case "number":
          if (typeof value !== "number" || Number.isNaN(value)) {
            errors.push(`${path}.${field}: expected number, got ${typeof value}`);
            continue;
          }
          if (rules.min !== undefined && value < rules.min) {
            errors.push(`${path}.${field}: ${value} < minimum ${rules.min}`);
            continue;
          }
          if (rules.max !== undefined && value > rules.max) {
            errors.push(`${path}.${field}: ${value} > maximum ${rules.max}`);
            continue;
          }
          break;

        case "string":
          if (typeof value !== "string") {
            errors.push(`${path}.${field}: expected string`);
            continue;
          }
          break;

        case "boolean":
          if (typeof value !== "boolean") {
            errors.push(`${path}.${field}: expected boolean`);
            continue;
          }
          break;

        case "enum":
          if (!rules.values.includes(value)) {
            errors.push(
              `${path}.${field}: "${value}" not in [${rules.values.join(", ")}]`
            );
            continue;
          }
          break;
      }

      result[field] = value;
    }

    return result;
  }

  #validateIPList(list, name, errors) {
    if (!list) return [];
    if (!Array.isArray(list)) {
      errors.push(`${name}: expected array`);
      return [];
    }
    const ipOrCidr = /^[\d.:a-f]+(?:\/\d{1,3})?$/i;
    for (const entry of list) {
      if (!ipOrCidr.test(entry)) {
        errors.push(`${name}: invalid IP/CIDR "${entry}"`);
      }
    }
    return list;
  }

  #validateStore(store, errors) {
    const defaults = { type: "memory", cleanupIntervalMs: 300000 };
    if (!store) return defaults;

    if (!["memory", "redis"].includes(store.type)) {
      errors.push(`store.type: must be "memory" or "redis"`);
    }
    return { ...defaults, ...store };
  }

  /** Match a request path against configured route patterns */
  #matchRoute(requestPath, routes) {
    // Exact match first
    if (routes[requestPath]) return routes[requestPath];

    // Prefix match (longest wins)
    const matches = Object.keys(routes)
      .filter((pattern) => requestPath.startsWith(pattern))
      .sort((a, b) => b.length - a.length);

    return matches.length > 0 ? routes[matches[0]] : {};
  }

  /** Simple CIDR / exact IP match */
  #matchCIDR(ip, entry) {
    if (!entry.includes("/")) return ip === entry;

    const [subnet, bits] = entry.split("/");
    const mask = ~(2 ** (32 - parseInt(bits)) - 1);
    return (this.#ipToInt(ip) & mask) === (this.#ipToInt(subnet) & mask);
  }

  #ipToInt(ip) {
    return ip
      .split(".")
      .reduce((acc, octet) => (acc << 8) + parseInt(octet), 0);
  }

  #deepFreeze(obj) {
    for (const val of Object.values(obj)) {
      if (val && typeof val === "object") this.#deepFreeze(val);
    }
    return Object.freeze(obj);
  }
}

// ── Custom error types ──────────────────────────────────────

class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = "ConfigError";
  }
}

class ConfigValidationError extends Error {
  constructor(errors) {
    super(`Config validation failed:\n  • ${errors.join("\n  • ")}`);
    this.name = "ConfigValidationError";
    this.errors = errors;
  }
}

module.exports = { ConfigParser, ConfigError, ConfigValidationError };
