/** Fixed window: resets counter at fixed intervals */
class FixedWindowCounter {
  #hits = new Map();  // key → { count, resetTime }

  check(key, maxRequests, windowMs, cost = 1) {
    const now = Date.now();
    let record = this.#hits.get(key);

    if (!record || now >= record.resetTime) {
      record = { count: 0, resetTime: now + windowMs };
      this.#hits.set(key, record);
    }

    if (record.count + cost > maxRequests) {
      return {
        allowed: false,
        remaining: Math.max(0, maxRequests - record.count),
        resetTime: record.resetTime,
        retryAfter: Math.ceil((record.resetTime - now) / 1000),
      };
    }

    record.count += cost;
    return {
      allowed: true,
      remaining: maxRequests - record.count,
      resetTime: record.resetTime,
      retryAfter: 0,
    };
  }

  cleanup(maxAgeMs) {
    const cutoff = Date.now() - maxAgeMs;
    for (const [key, record] of this.#hits) {
      if (record.resetTime < cutoff) this.#hits.delete(key);
    }
  }
}

/** Sliding window: smooths bursts across window boundaries */
