// rules/no-console-in-production.js
// Custom ESLint rule: disallow console usage and generate violation reports

"use strict";

// ✅ FIX 6: Removed shared mutable state — each run is isolated

module.exports = {
    meta: {
        type: "problem",
        docs: {
            description: "Disallow console usage and generate violation reports",
            category: "Best Practices",
            recommended: true,
        },
        fixable: "code",
        // ✅ FIX: Added hasSuggestions flag (required in ESLint 8+)
        hasSuggestions: true,
        schema: [
            {
                type: "object",
                properties: {
                    allowedMethods: {
                        type: "array",
                        items: { type: "string" },
                        default: [],
                    },
                    reportFormat: {
                        type: "string",
                        enum: ["json", "csv", "text"],
                    },
                    reportOutput: {
                        type: "string",
                        description: "File path to write the report",
                    },
                },
                // ✅ FIX 5: Added to prevent typos in option keys
                additionalProperties: false,
            },
        ],
        messages: {
            // ✅ FIX 3: Placeholder now matches the data key "method"
            unexpected:
                "Unexpected console.{{method}} statement in production code.",
            suggestion: "Replace console.{{method}} with a proper logger.",
            // ✅ Added message for MemberExpression references
            unexpectedRef:
                "Unexpected reference to console.{{method}} in production code.",
        },
    },

    create(context) {
        const options = context.options[0] || {};

        // ✅ FIX 1: Default to empty array to prevent .includes() on undefined
        const allowedMethods = options.allowedMethods || [];
        const reportFormat = options.reportFormat || "json";
        const reportOutput = options.reportOutput || null;

