        const sourceCode = context.sourceCode || context.getSourceCode();

        // ✅ FIX 6: Per-run violations array (not module-level)
        const violations = [];

        /**
         * Generates a formatted report string from collected violations.
         * @param {Array<Object>} violationsList
         * @returns {string}
         */
        function generateReport(violationsList) {
            switch (reportFormat) {
                case "json":
                    return JSON.stringify(violationsList, null, 2);

                case "csv": {
                    // ✅ FIX: Added header row and proper CSV escaping
                    const header = "file,line,column,method";
                    const rows = violationsList.map((v) => {
                        const escapedFile = `"${v.file.replace(/"/g, '""')}"`;
                        return `${escapedFile},${v.line},${v.column},${v.method}`;
                    });
                    return [header, ...rows].join("\n");
                }

                case "text":
                    return violationsList
                        .map(
                            (v) =>
                                `[${v.file}] Line ${v.line}:${v.column} — ` +
                                `console.${v.method}()`
                        )
                        .join("\n");

                default:
                    return JSON.stringify(violationsList, null, 2);
            }
        }

        /**
         * Safely checks whether a node is a `console.xxx` member expression.
         * Handles both dot notation and bracket notation.
         *
         * ✅ FIX 1: Null-safe property access
         * ✅ FIX 2: Handles computed member expressions like console["log"]
         *
         * @param {ASTNode} memberExpr - A MemberExpression node
         * @returns {{ isConsole: boolean, methodName: string|null }}
         */
        function analyzeConsoleMember(memberExpr) {
            const result = { isConsole: false, methodName: null };

            // ✅ FIX 1: Guard against missing properties
            if (
                !memberExpr ||
                memberExpr.type !== "MemberExpression" ||
                !memberExpr.object ||
                !memberExpr.property
            ) {
                return result;
            }

            // Check object is the `console` identifier
            if (
                memberExpr.object.type !== "Identifier" ||
                memberExpr.object.name !== "console"
            ) {
                return result;
            }

            // ✅ FIX 2: Handle computed expressions — console["log"](...)
            let methodName = null;

            if (!memberExpr.computed && memberExpr.property.type === "Identifier") {
                // Dot notation: console.log(...)
                methodName = memberExpr.property.name;
            } else if (
                memberExpr.computed &&
                memberExpr.property.type === "Literal" &&
                typeof memberExpr.property.value === "string"
            ) {
                // Bracket notation: console["log"](...)
                methodName = memberExpr.property.value;
            }

            if (methodName) {
                result.isConsole = true;
                result.methodName = methodName;
            }

            return result;
        }

        /**
         * Records a violation and reports it via context.report().
         *
         * @param {ASTNode} node        - The offending node
         * @param {string}  methodName  - e.g., "log", "warn"
         * @param {string}  messageId   - meta.messages key
         * @param {boolean} canFix      - Whether auto-fix is safe
         */
        function reportViolation(node, methodName, messageId, canFix) {
            violations.push({
                line: node.loc.start.line,
                column: node.loc.start.column,
                method: methodName,
                file: context.filename || context.getFilename(),
            });

            const reportDescriptor = {
                node,
                messageId,
                // ✅ FIX 3: Data key "method" now matches {{method}} in template
                data: { method: methodName },
                suggest: [
                    {
                        messageId: "suggestion",
                        data: { method: methodName },
                        fix(fixer) {
                            // ✅ FIX 4: Properly replaces only "console" → "logger"
                            //           while preserving the method name and arguments
                            const calleeNode =
                                node.type === "CallExpression"
                                    ? node.callee
                                    : node;

                            if (calleeNode.type === "MemberExpression") {
                                return fixer.replaceText(
                                    calleeNode.object,
                                    "logger"
                                );
                            }
                            return null;
                        },
                    },
                ],
            };

            // ✅ FIX 4: Auto-fix removes the entire ExpressionStatement
            //           (including arguments, parens, and semicolon)
            if (canFix) {
                reportDescriptor.fix = function (fixer) {
                    // Walk up to the ExpressionStatement to remove the full line
                    const expressionStatement =
                        node.parent && node.parent.type === "ExpressionStatement"
                            ? node.parent
                            : node;

                    return fixer.remove(expressionStatement);
                };
            }

            context.report(reportDescriptor);
        }

        // ─── AST Visitors ───────────────────────────────────────────────

        return {
            /**
             * Catches:  console.log("hello")
             *           console["warn"]("oops")
             */
            CallExpression(node) {
                // ✅ FIX 1: Safe extraction via helper
                if (!node.callee || node.callee.type !== "MemberExpression") {
                    return;
                }

                const { isConsole, methodName } = analyzeConsoleMember(
                    node.callee
                );

                if (!isConsole || !methodName) {
                    return;
                }

                // ✅ FIX 1: Safe .includes() — allowedMethods is always an array
                if (allowedMethods.includes(methodName)) {
                    return;
                }

                reportViolation(node, methodName, "unexpected", /* canFix */ true);
            },

            /**
             * ✅ FIX 2: Also catches standalone references like:
             *           const log = console.log;
             *           arr.forEach(console.log);
             *
             * We skip if the parent is a CallExpression (handled above).
             */
            MemberExpression(node) {
                // Avoid double-reporting when parent is a CallExpression
                if (
                    node.parent &&
                    node.parent.type === "CallExpression" &&
                    node.parent.callee === node
                ) {
                    return;
                }

                const { isConsole, methodName } = analyzeConsoleMember(node);

                if (!isConsole || !methodName) {
                    return;
                }

                if (allowedMethods.includes(methodName)) {
                    return;
                }

                reportViolation(
                    node,
                    methodName,
                    "unexpectedRef",
                    /* canFix */ false
                );
            },

            /**
             * On program exit, compile and emit the report.
             * ✅ FIX: Report is written to disk or attached as a trailing
             *         report comment (depending on config).
             */
            "Program:exit"() {
                if (violations.length === 0) {
                    return;
                }

                const report = generateReport(violations);

                // Output the report (via stdout or file system, as configured)
                if (reportOutput) {
                    try {
                        const fs = require("fs");
                        const path = require("path");
                        const resolvedPath = path.resolve(reportOutput);

