    super();
    this.failureThreshold = options.failureThreshold || 5;
    this.resetTimeoutMs = options.resetTimeoutMs || 30000;
    this.halfOpenMaxAttempts = options.halfOpenMaxAttempts || 3;

    this.state = State.CLOSED;
    this.failureCount = 0;
    this.halfOpenAttempts = 0;
    this.lastFailureTime = null;
    this.resetTimer = null;
  }

  /** @returns {boolean} */
  isAvailable() {
    if (this.state === State.CLOSED) return true;

    if (this.state === State.OPEN) {
      const elapsed = Date.now() - this.lastFailureTime;
      if (elapsed >= this.resetTimeoutMs) {
        this._transitionTo(State.HALF_OPEN);
        return true;
      }
      return false;
    }

    // HALF_OPEN — allow limited attempts
    return this.halfOpenAttempts < this.halfOpenMaxAttempts;
  }

  /**
   * Wrap an async operation with circuit breaker protection.
   * @param {Function} fn - Async function to execute
   * @returns {Promise<*>}
   */
  async execute(fn) {
    if (!this.isAvailable()) {
      const err = new Error('Circuit breaker is OPEN — request rejected');
      err.code = 'CIRCUIT_OPEN';
      throw err;
    }

    try {
      const result = await fn();
      this._onSuccess();
      return result;
    } catch (error) {
      this._onFailure(error);
      throw error;
    }
  }

  _onSuccess() {
    if (this.state === State.HALF_OPEN) {
      logger.info('Circuit breaker recovered — transitioning to CLOSED');
    }
    this.failureCount = 0;
    this.halfOpenAttempts = 0;
    this._transitionTo(State.CLOSED);
  }

  _onFailure(error) {
    this.failureCount++;
    this.lastFailureTime = Date.now();

    if (this.state === State.HALF_OPEN) {
      this.halfOpenAttempts++;
      if (this.halfOpenAttempts >= this.halfOpenMaxAttempts) {
        this._transitionTo(State.OPEN);
      }
    } else if (this.failureCount >= this.failureThreshold) {
      this._transitionTo(State.OPEN);
    }

    logger.warn(
      { failureCount: this.failureCount, state: this.state, error: error.message },
      'Circuit breaker recorded failure'
    );
  }

  _transitionTo(newState) {
    if (this.state !== newState) {
      const prevState = this.state;
      this.state = newState;

      if (newState === State.HALF_OPEN) {
        this.halfOpenAttempts = 0;
      }

      this.emit('stateChange', { from: prevState, to: newState });
      logger.info({ from: prevState, to: newState }, 'Circuit breaker state change');
    }
  }

  reset() {
    this.state = State.CLOSED;
    this.failureCount = 0;
    this.halfOpenAttempts = 0;
    this.lastFailureTime = null;
    clearTimeout(this.resetTimer);
  }

  getState() {
    return {
      state: this.state,
      failureCount: this.failureCount,
      halfOpenAttempts: this.halfOpenAttempts,
    };
  }
}

module.exports = CircuitBreaker;
