```javascript
const { EventEmitter } = require('events');
const logger = require('./logger');

class BackpressureManager extends EventEmitter {
  /**
   * @param {Object} options
   * @param {number} options.maxQueueSize
   * @param {number} options.highWatermark
   * @param {number} options.lowWatermark
   */
  constructor(options = {}) {
    super();
    this.maxQueueSize = options.maxQueueSize || 10000;
    this.highWatermark = options.highWatermark || 8000;
    this.lowWatermark = options.lowWatermark || 5000;
    this.currentSize = 0;
    this.isPaused = false;
  }

  /**
   * Check whether a new entry can be accepted.
   * @param {number} [count=1]
   * @returns {boolean}
   */
  canAccept(count = 1) {
    return this.currentSize + count <= this.maxQueueSize;
  }

  /**
   * Record items added to the queue and emit pause/resume signals.
   * @param {number} count
   */
  recordAdd(count = 1) {
    this.currentSize += count;

    if (!this.isPaused && this.currentSize >= this.highWatermark) {
      this.isPaused = true;
      this.emit('pause');
      logger.warn({ queueSize: this.currentSize }, 'Backpressure: high watermark reached — pausing');
    }
  }

  /**
   * Record items drained from the queue.
   * @param {number} count
   */
  recordDrain(count = 1) {
    this.currentSize = Math.max(0, this.currentSize - count);

    if (this.isPaused && this.currentSize <= this.lowWatermark) {
      this.isPaused = false;
      this.emit('resume');
      logger.info({ queueSize: this.currentSize }, 'Backpressure: low watermark reached — resuming');
    }
  }

  getStats() {
    return {
      currentSize: this.currentSize,
      maxQueueSize: this.maxQueueSize,
      isPaused: this.isPaused,
      utilizationPct: ((this.currentSize / this.maxQueueSize) * 100).toFixed(1),
    };
  }
}

module.exports = BackpressureManager;
