class MetricsCollector {
  constructor() {
    this._counters = new Map();
    this._gauges = new Map();
    this._histograms = new Map();
    this._startTime = Date.now();
  }

  increment(name, value = 1) {
    const current = this._counters.get(name) || 0;
    this._counters.set(name, current + value);
  }

  gauge(name, value) {
    this._gauges.set(name, value);
  }

  recordDuration(name, durationMs) {
    if (!this._histograms.has(name)) {
      this._histograms.set(name, { count: 0, sum: 0, min: Infinity, max: -Infinity });
    }
    const h = this._histograms.get(name);
    h.count++;
    h.sum += durationMs;
    h.min = Math.min(h.min, durationMs);
    h.max = Math.max(h.max, durationMs);
  }

  getSnapshot() {
    const histogramSnapshot = {};
    for (const [name, h] of this._histograms) {
      histogramSnapshot[name] = {
        count: h.count,
        avgMs: h.count ? (h.sum / h.count).toFixed(2) : 0,
        minMs: h.min === Infinity ? 0 : h.min,
        maxMs: h.max === -Infinity ? 0 : h.max,
      };
    }

    return {
      uptimeMs: Date.now() - this._startTime,
      counters: Object.fromEntries(this._counters),
      gauges: Object.fromEntries(this._gauges),
      histograms: histogramSnapshot,
    };
  }

  reset() {
    this._counters.clear();
    this._gauges.clear();
    this._histograms.clear();
    this._startTime = Date.now();
  }
}

// Singleton
module.exports = new MetricsCollector();
