```javascript
const Ajv = require('ajv');
const addFormats = require('ajv-formats');
const logger = require('../utils/logger');
const metrics = require('../metrics/MetricsCollector');

const LOG_SCHEMA = {
  type: 'object',
  properties: {
    timestamp: { type: 'string', format: 'date-time' },
    level: {
      type: 'string',
      enum: ['trace', 'debug', 'info', 'warn', 'error', 'fatal'],
    },
    message: { type: 'string', minLength: 1, maxLength: 10000 },
    service: { type: 'string', minLength: 1, maxLength: 256 },
    traceId: { type: 'string', maxLength: 128 },
    spanId: { type: 'string', maxLength: 64 },
    host: { type: 'string', maxLength: 256 },
    metadata: { type: 'object' },
  },
  required: ['message'],
  additionalProperties: true,
};

class LogValidator {
  constructor(schema = LOG_SCHEMA) {
    this.ajv = new Ajv({ allErrors: true, coerceTypes: false });
    addFormats(this.ajv);
    this.validate = this.ajv.compile(schema);
  }

  /**
   * Parse raw input (string or Buffer) into a log entry object.
   * @param {string|Buffer} raw
   * @returns {{ valid: boolean, entry: Object|null, errors: string[]|null }}
   */
  parse(raw) {
    const input = Buffer.isBuffer(raw) ? raw.toString('utf-8') : raw;
    const trimmed = input.trim();

    if (!trimmed) {
      return { valid: false, entry: null, errors: ['Empty input'] };
    }

    let parsed;
    try {
      parsed = JSON.parse(trimmed);
    } catch (err) {
      metrics.increment('logs.parse_errors');
      return { valid: false, entry: null, errors: [`Invalid JSON: ${err.message}`] };
    }

    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      metrics.increment('logs.validation_errors');
      return { valid: false, entry: null, errors: ['Input must be a JSON object'] };
    }

    const isValid = this.validate(parsed);

    if (!isValid) {
      metrics.increment('logs.validation_errors');
      const errors = this.validate.errors.map(
        (e) => `${e.instancePath || '/'} ${e.message}`
      );
      return { valid: false, entry: null, errors };
    }

    // Normalise the entry
    const entry = this._normalise(parsed);
    metrics.increment('logs.validated');
    return { valid: true, entry, errors: null };
  }

  /**
   * Parse a batch of raw lines.
   * @param {string[]} lines
   * @returns {{ valid: Object[], invalid: { raw: string, errors: string[] }[] }}
   */
  parseBatch(lines) {
    const valid = [];
    const invalid = [];

    for (const line of lines) {
      const result = this.parse(line);
      if (result.valid) {
        valid.push(result.entry);
      } else {
        invalid.push({ raw: line, errors: result.errors });
      }
    }

    return { valid, invalid };
  }

  /**
   * Ensure every entry has a timestamp and defaults.
   * @param {Object} entry
   * @returns {Object}
   */
  _normalise(entry) {
    return {
      timestamp: entry.timestamp || new Date().toISOString(),
      level: (entry.level || 'info').toLowerCase(),
      message: entry.message,
      service: entry.service || 'unknown',
      host: entry.host || undefined,
      traceId: entry.traceId || undefined,
      spanId: entry.spanId || undefined,
      metadata: entry.metadata || {},
      _ingested_at: new Date().toISOString(),
    };
  }
}

module.exports = LogValidator;
