// Event represents a raw analytics event from JSON input.
type Event struct {
	ID        string                 `json:"id"`
	Type      string                 `json:"type"`
	Source    string                 `json:"source"`
	Timestamp time.Time              `json:"timestamp"`
	UserID    string                 `json:"user_id,omitempty"`
	SessionID string                 `json:"session_id,omitempty"`
	Data      map[string]interface{} `json:"data,omitempty"`
	Metadata  map[string]string      `json:"metadata,omitempty"`
}

// Validate checks if the event has all required fields.
func (e *Event) Validate() error {
	if e.ID == "" {
		return fmt.Errorf("event missing required field: id")
	}
	if e.Type == "" {
		return fmt.Errorf("event %s missing required field: type", e.ID)
	}
	if e.Source == "" {
		return fmt.Errorf("event %s missing required field: source", e.ID)
	}
	if e.Timestamp.IsZero() {
		return fmt.Errorf("event %s missing required field: timestamp", e.ID)
	}
	return nil
}

// Clone creates a deep copy of the event.
func (e *Event) Clone() *Event {
	clone := &Event{
		ID:        e.ID,
		Type:      e.Type,
		Source:    e.Source,
		Timestamp: e.Timestamp,
		UserID:    e.UserID,
		SessionID: e.SessionID,
	}

	if e.Data != nil {
		raw, _ := json.Marshal(e.Data)
		_ = json.Unmarshal(raw, &clone.Data)
	}

	if e.Metadata != nil {
		clone.Metadata = make(map[string]string, len(e.Metadata))
		for k, v := range e.Metadata {
			clone.Metadata[k] = v
		}
	}

	return clone
}

// ProcessedEvent wraps an Event with enrichment and processing state.
type ProcessedEvent struct {
	Event       *Event            `json:"event"`
	Enrichments map[string]string `json:"enrichments,omitempty"`
	Tags        []string          `json:"tags,omitempty"`
	ProcessedAt time.Time         `json:"processed_at"`
	PipelineID  string            `json:"pipeline_id"`
	StagesRun   []string          `json:"stages_run"`
	Errors      []string          `json:"errors,omitempty"`
}

// NewProcessedEvent wraps a raw Event for pipeline processing.
func NewProcessedEvent(evt *Event, pipelineID string) *ProcessedEvent {
	return &ProcessedEvent{
		Event:       evt,
		Enrichments: make(map[string]string),
		Tags:        make([]string, 0),
		ProcessedAt: time.Now().UTC(),
		PipelineID:  pipelineID,
		StagesRun:   make([]string, 0),
		Errors:      make([]string, 0),
	}
}

// AddTag appends a tag if it doesn't already exist.
func (pe *ProcessedEvent) AddTag(tag string) {
	for _, t := range pe.Tags {
		if t == tag {
			return
		}
	}
	pe.Tags = append(pe.Tags, tag)
}

// AggregationResult holds aggregated analytics data.
type AggregationResult struct {
	Key       string                 `json:"key"`
