}

// ReaderConfig configures the input reader.
type ReaderConfig struct {
	Type       string `json:"type"` // "file", "stdin", "http"
	Path       string `json:"path,omitempty"`
	BatchSize  int    `json:"batch_size"`
	Format     string `json:"format"` // "json_lines", "json_array"
	SkipErrors bool   `json:"skip_errors"`
}

// TransformConfig configures a single transform stage.
type TransformConfig struct {
	Name    string                 `json:"name"`
	Type    string                 `json:"type"` // "filter", "enrich", "aggregate"
	Enabled bool                   `json:"enabled"`
	Config  map[string]interface{} `json:"config,omitempty"`
}

// SinkConfig configures an output sink.
type SinkConfig struct {
	Name    string                 `json:"name"`
	Type    string                 `json:"type"` // "console", "file", "null"
	Enabled bool                   `json:"enabled"`
	Config  map[string]interface{} `json:"config,omitempty"`
}

// LoadFromFile reads config from a JSON file.
func LoadFromFile(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("reading config file %s: %w", path, err)
	}
	return Parse(data)
}

// Parse parses config from JSON bytes.
func Parse(data []byte) (*Config, error) {
	cfg := &Config{}
	if err := json.Unmarshal(data, cfg); err != nil {
		return nil, fmt.Errorf("parsing config: %w", err)
	}
	cfg.applyDefaults()
	return cfg, cfg.Validate()
}

// DefaultConfig returns a working default configuration.
func DefaultConfig() *Config {
	cfg := &Config{
		Pipeline: PipelineConfig{
			ID:              "default",
			Name:            "Default Analytics Pipeline",
			Workers:         4,
			BufferSize:      1000,
			ShutdownTimeout: 30 * time.Second,
			MetricsInterval: 10 * time.Second,
		},
		Reader: ReaderConfig{
			Type:       "stdin",
			BatchSize:  100,
			Format:     "json_lines",
			SkipErrors: true,
		},
		Sinks: []SinkConfig{
			{Name: "stdout", Type: "console", Enabled: true},
		},
	}
	return cfg
}

func (c *Config) applyDefaults() {
	if c.Pipeline.Workers <= 0 {
		c.Pipeline.Workers = 4
	}
	if c.Pipeline.BufferSize <= 0 {
		c.Pipeline.BufferSize = 1000
	}
	if c.Pipeline.ShutdownTimeout <= 0 {
		c.Pipeline.ShutdownTimeout = 30 * time.Second
	}
	if c.Pipeline.MetricsInterval <= 0 {
		c.Pipeline.MetricsInterval = 10 * time.Second
	}
	if c.Reader.BatchSize <= 0 {
		c.Reader.BatchSize = 100
	}
	if c.Reader.Format == "" {
		c.Reader.Format = "json_lines"
	}
}

// Validate checks config for logical errors.
func (c *Config) Validate() error {
	if c.Pipeline.Workers > 256 {
		return fmt.Errorf("workers %d exceeds max 256", c.Pipeline.Workers)
	}
	validFormats := map[string]bool{"json_lines": true, "json_array": true}
	if !validFormats[c.Reader.Format] {
		return fmt.Errorf("unsupported reader format: %s", c.Reader.Format)
	}
	activeSinks := 0
	for _, s := range c.Sinks {
		if s.Enabled {
			activeSinks++
		}
	}
	if activeSinks == 0 {
		return fmt.Errorf("at least one sink must be enabled")
	}
	return nil
}
