```go
package pipeline

import (
	"context"
	"fmt"

	"analytics-pipeline/model"
)

// RoutePredicate determines whether an event matches a route.
type RoutePredicate func(event *model.ProcessedEvent) bool

// Route binds a predicate to a destination stage chain.
type Route struct {
	Name      string
	Predicate RoutePredicate
	Stages    []Stage
}

// Router fans out events to different stage chains based on predicates.
type Router struct {
	name          string
	routes        []Route
	defaultStages []Stage
}

// NewRouter creates a new event router.
func NewRouter(name string) *Router {
	return &Router{
		name:   name,
		routes: make([]Route, 0),
	}
}

func (r *Router) Name() string { return r.name }

// AddRoute adds a conditional route.
func (r *Router) AddRoute(route Route) {
	r.routes = append(r.routes, route)
}

// SetDefault sets stages for events matching no route.
func (r *Router) SetDefault(stages []Stage) {
	r.defaultStages = stages
}

// Process routes the event and processes it through the matched stages.
func (r *Router) Process(ctx context.Context, event *model.ProcessedEvent) (*model.ProcessedEvent, error) {
	for _, route := range r.routes {
		if route.Predicate(event) {
			return r.runStages(ctx, event, route.Stages)
		}
	}

	if r.defaultStages != nil {
		return r.runStages(ctx, event, r.defaultStages)
	}

	return event, nil
}

func (r *Router) runStages(ctx context.Context, event *model.ProcessedEvent, stages []Stage) (*model.ProcessedEvent, error) {
	var err error
	current := event
	for _, stage := range stages {
		current, err = stage.Process(ctx, current)
		if err != nil {
			return nil, fmt.Errorf("router %s: %w", r.name, err)
		}
		if current == nil {
			return nil, nil // filtered out
		}
	}
	return current, nil
}

func (r *Router) Close() error {
	var firstErr error
	for _, route := range r.routes {
		for _, stage := range route.Stages {
			if err := stage.Close(); err != nil && firstErr == nil {
				firstErr = err
			}
		}
	}
	for _, stage := range r.defaultStages {
		if err := stage.Close(); err != nil && firstErr == nil {
			firstErr = err
		}
	}
	return firstErr
}

// ByEventType returns a predicate matching a specific event type.
func ByEventType(eventType string) RoutePredicate {
	return func(event *model.ProcessedEvent) bool {
		return event.Event.Type == eventType
	}
}

// BySource returns a predicate matching a specific source.
func BySource(source string) RoutePredicate {
	return func(event *model.ProcessedEvent) bool {
		return event.Event.Source == source
	}
}

// HasTag returns a predicate checking for a tag.
func HasTag(tag string) RoutePredicate {
	return func(event *model.ProcessedEvent) bool {
		for _, t := range event.Tags {
			if t == tag {
				return true
			}
		}
		return false
	}
}
