package pipeline

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"

	"go.uber.org/zap"

	"analytics-pipeline/config"
	"analytics-pipeline/metrics"
	"analytics-pipeline/model"
)

// Pipeline orchestrates the complete analytics processing flow.
type Pipeline struct {
	cfg     config.PipelineConfig
	logger  *zap.Logger
	metrics *metrics.Collector

	stages []Stage
	input  chan *model.Event
	output chan *model.ProcessedEvent
	errors chan error

	running  atomic.Bool
	wg       sync.WaitGroup
	cancelFn context.CancelFunc
}

// New creates a new Pipeline with the given configuration.
func New(cfg config.PipelineConfig, logger *zap.Logger, collector *metrics.Collector) *Pipeline {
	return &Pipeline{
		cfg:     cfg,
		logger:  logger.Named("pipeline").With(zap.String("pipeline_id", cfg.ID)),
		metrics: collector,
		stages:  make([]Stage, 0),
		input:   make(chan *model.Event, cfg.BufferSize),
		output:  make(chan *model.ProcessedEvent, cfg.BufferSize),
		errors:  make(chan error, cfg.BufferSize),
	}
}

// AddStage appends a processing stage to the pipeline.
func (p *Pipeline) AddStage(stage Stage) {
	p.stages = append(p.stages, stage)
}

// Input returns the input channel for submitting raw events.
func (p *Pipeline) Input() chan<- *model.Event {
	return p.input
}

// Output returns the channel of fully processed events.
func (p *Pipeline) Output() <-chan *model.ProcessedEvent {
	return p.output
}

// Errors returns the error channel.
func (p *Pipeline) Errors() <-chan error {
	return p.errors
}

// Start begins processing with the given number of workers.
func (p *Pipeline) Start(ctx context.Context) error {
	if p.running.Swap(true) {
		return fmt.Errorf("pipeline %s already running", p.cfg.ID)
	}

	ctx, p.cancelFn = context.WithCancel(ctx)

	p.logger.Info("starting pipeline",
		zap.Int("workers", p.cfg.Workers),
		zap.Int("stages", len(p.stages)),
		zap.Int("buffer_size", p.cfg.BufferSize),
	)

	// Start worker goroutines
	for i := 0; i < p.cfg.Workers; i++ {
		p.wg.Add(1)
		go p.worker(ctx, i)
	}

	// Start error logger
	p.wg.Add(1)
	go p.errorLogger(ctx)

	p.metrics.RecordPipelineStart(p.cfg.ID)
	return nil
}

// Submit sends an event into the pipeline, respecting context cancellation.
func (p *Pipeline) Submit(ctx context.Context, event *model.Event) error {
	if !p.running.Load() {
		return ErrPipelineClosed
	}

	select {
	case p.input <- event:
		p.metrics.IncrementReceived(p.cfg.ID)
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// Shutdown gracefully stops the pipeline.
func (p *Pipeline) Shutdown(ctx context.Context) error {
	if !p.running.Swap(false) {
		return nil
	}

	p.logger.Info("shutting down pipeline")

	// Close input channel to signal workers
	close(p.input)

	// Wait for workers with timeout
	done := make(chan struct{})
	go func() {
		p.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		p.logger.Info("pipeline shutdown complete")
	case <-ctx.Done():
		p.logger.Warn("pipeline shutdown timed out, cancelling workers")
		p.cancelFn()
		<-done
	}

	// Close output channels
	close(p.output)
	close(p.errors)

	// Close

