"use strict";

/**
 * Base error class for configuration-related errors.
 */
class ConfigError extends Error {
  /**
   * @param {string} message
   * @param {string} code
   * @param {Object} [context={}]
   */
  constructor(message, code, context = {}) {
    super(message);
    this.name = "ConfigError";
    this.code = code;
    this.context = context;
    this.timestamp = new Date().toISOString();
    Error.captureStackTrace?.(this, this.constructor);
  }

  toJSON() {
    return {
      name: this.name,
      code: this.code,
      message: this.message,
      context: this.context,
      timestamp: this.timestamp,
    };
  }
}

class ConfigLoadError extends ConfigError {
  /**
   * @param {string} source - Name of the source that failed
   * @param {Error} cause - The underlying error
   * @param {number} [attempt] - Which retry attempt failed
   */
  constructor(source, cause, attempt) {
    super(
      `Failed to load config from "${source}": ${cause.message}`,
      "CONFIG_LOAD_ERROR",
      { source, attempt }
    );
    this.name = "ConfigLoadError";
    this.cause = cause;
  }
}

class ConfigValidationError extends ConfigError {
  /**
   * @param {Array<{path: string, message: string}>} violations
   */
  constructor(violations) {
    const summary = violations
      .map((v) => `  - ${v.path}: ${v.message}`)
      .join("\n");
    super(
      `Configuration validation failed:\n${summary}`,
      "CONFIG_VALIDATION_ERROR",
      { violations }
    );
    this.name = "ConfigValidationError";
    this.violations = violations;
  }
}

class RetryExhaustedError extends ConfigError {
  /**
   * @param {string} source
   * @param {number} maxAttempts
   * @param {Error[]} errors
   */
  constructor(source, maxAttempts, errors) {
    super(
      `All ${maxAttempts} retry attempts exhausted for "${source}"`,
      "RETRY_EXHAUSTED",
      { source, maxAttempts, errorCount: errors.length }
    );
    this.name = "RetryExhaustedError";
    this.errors = errors;
  }
}

class CircuitOpenError extends ConfigError {
  /**
   * @param {string} source
   * @param {number} resetTimeMs
   */
  constructor(source, resetTimeMs) {
    super(
      `Circuit breaker is open for "${source}". Retry after ${resetTimeMs}ms.`,
      "CIRCUIT_OPEN",
      { source, resetTimeMs }
    );
    this.name = "CircuitOpenError";
  }
}

module.exports = {
  ConfigError,
  ConfigLoadError,
  ConfigValidationError,
  RetryExhaustedError,
  CircuitOpenError,
};
