/**
 * @typedef {'debug'|'info'|'warn'|'error'|'silent'} LogLevel
 */

const LOG_LEVELS = /** @type {const} */ ({
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
  silent: 4,
});

/**
 * Lightweight structured logger for the config loader.
 * Avoids external dependencies; swap transport in production.
 */
class Logger {
  /** @param {{ level?: LogLevel, prefix?: string }} options */
  constructor({ level = "info", prefix = "ConfigLoader" } = {}) {
    this._level = LOG_LEVELS[level] ?? LOG_LEVELS.info;
    this._prefix = prefix;
  }

  /** @param {LogLevel} level */
  setLevel(level) {
    this._level = LOG_LEVELS[level] ?? LOG_LEVELS.info;
  }

  /**
   * @param {LogLevel} level
   * @param {string} message
   * @param {Object} [meta]
   */
  _log(level, message, meta) {
    if (LOG_LEVELS[level] < this._level) return;

    const entry = {
      timestamp: new Date().toISOString(),
      level,
      component: this._prefix,
      message,
      ...(meta && { meta }),
    };

    const output = JSON.stringify(entry);

    switch (level) {
      case "error":
        process.stderr.write(output + "\n");
        break;
      case "warn":
        process.stderr.write(output + "\n");
        break;
      default:
        process.stdout.write(output + "\n");
    }
  }

  debug(msg, meta) { this._log("debug", msg, meta); }
  info(msg, meta)  { this._log("info", msg, meta); }
  warn(msg, meta)  { this._log("warn", msg, meta); }
  error(msg, meta) { this._log("error", msg, meta); }
}

module.exports = { Logger, LOG_LEVELS };
