"use strict";

const { CircuitOpenError } = require("../errors/ConfigErrors");

/**
 * @typedef {'CLOSED'|'OPEN'|'HALF_OPEN'} CircuitState
 */

/**
 * Lightweight circuit breaker to protect remote config sources.
 */
class CircuitBreaker {
  /**
   * @param {Object} options
   * @param {string}  options.name              - Identifies the protected resource
   * @param {number}  [options.failureThreshold=5]  - Failures before opening
   * @param {number}  [options.resetTimeMs=30000]   - How long to stay open (ms)
   * @param {number}  [options.halfOpenMax=1]        - Probes allowed in half-open
   */
  constructor({
    name,
    failureThreshold = 5,
    resetTimeMs = 30_000,
    halfOpenMax = 1,
  }) {
    this.name = name;
    this.failureThreshold = failureThreshold;
    this.resetTimeMs = resetTimeMs;
    this.halfOpenMax = halfOpenMax;

    /** @type {CircuitState} */
    this.state = "CLOSED";
    this.failureCount = 0;
    this.lastFailureTime = 0;
    this.halfOpenAttempts = 0;
  }

  /**
   * Execute a function through the circuit breaker.
   * @template T
   * @param {() => Promise<T>} fn
   * @returns {Promise<T>}
   */
  async execute(fn) {
    this._evaluateState();

    if (this.state === "OPEN") {
      const remaining =
        this.resetTimeMs - (Date.now() - this.lastFailureTime);
      throw new CircuitOpenError(this.name, Math.max(0, remaining));
    }

    if (this.state === "HALF_OPEN" && this.halfOpenAttempts >= this.halfOpenMax) {
      throw new CircuitOpenError(this.name, this.resetTimeMs);
    }

    try {
      if (this.state === "HALF_OPEN") {
        this.halfOpenAttempts++;
      }

      const result = await fn();

      // Success → reset
      this.state = "CLOSED";
      this.failureCount = 0;
      this.halfOpenAttempts = 0;

      return result;
    } catch (err) {
      this._recordFailure();
      throw err;
    }
  }

  /** @private */
  _recordFailure() {
    this.failureCount++;
    this.lastFailureTime = Date.now();

    if (this.state === "HALF_OPEN" || this.failureCount >= this.failureThreshold) {
      this.state = "OPEN";
      this.halfOpenAttempts = 0;
    }
  }

  /** @private */
  _evaluateState() {
    if (
      this.state === "OPEN" &&
      Date.now() - this.lastFailureTime >= this.resetTimeMs
    ) {
      this.state = "HALF_OPEN";
      this.halfOpenAttempts = 0;
    }
  }

  /** Reset to pristine closed state. */
  reset() {
    this.state = "CLOSED";
    this.failureCount = 0;
    this.halfOpenAttempts = 0;
    this.lastFailureTime = 0;
  }
}

module.exports = { CircuitBreaker };
