```javascript
"use strict";

const { RetryExhaustedError } = require("./errors/ConfigErrors");

/**
 * @typedef {Object} RetryOptions
 * @property {number}  [maxAttempts=3]       - Total attempts (including the first)
 * @property {number}  [baseDelayMs=1000]    - Initial delay before first retry
 * @property {number}  [maxDelayMs=30000]    - Cap on exponential growth
 * @property {number}  [backoffFactor=2]     - Multiplier for each successive retry
 * @property {number}  [jitterFactor=0.25]   - Random ± jitter (0 = none, 1 = full)
 * @property {(err: Error) => boolean} [retryIf] - Return false to abort early
 * @property {(info: RetryInfo) => void} [onRetry] - Called before each retry wait
 */

/**
 * @typedef {Object} RetryInfo
 * @property {number} attempt
 * @property {number} delayMs
 * @property {Error}  error
 */

class RetryPolicy {
  /** @param {RetryOptions} options */
  constructor(options = {}) {
    this.maxAttempts   = options.maxAttempts   ?? 3;
    this.baseDelayMs   = options.baseDelayMs   ?? 1_000;
    this.maxDelayMs    = options.maxDelayMs    ?? 30_000;
    this.backoffFactor = options.backoffFactor ?? 2;
    this.jitterFactor  = options.jitterFactor  ?? 0.25;
    this.retryIf       = options.retryIf       ?? (() => true);
    this.onRetry       = options.onRetry       ?? (() => {});

    this._validateOptions();
  }

  /** @private */
  _validateOptions() {
    if (this.maxAttempts < 1) {
      throw new RangeError("maxAttempts must be >= 1");
    }
    if (this.baseDelayMs < 0) {
      throw new RangeError("baseDelayMs must be >= 0");
    }
    if (this.backoffFactor < 1) {
      throw new RangeError("backoffFactor must be >= 1");
    }
    if (this.jitterFactor < 0 || this.jitterFactor > 1) {
      throw new RangeError("jitterFactor must be between 0 and 1");
    }
  }

  /**
   * Calculate delay for a given attempt (1-indexed).
   * Uses exponential backoff with decorrelated jitter.
   *
   * @param {number} attempt
   * @returns {number} milliseconds
   */
  getDelay(attempt) {
    const exponential =
      this.baseDelayMs * Math.pow(this.backoffFactor, attempt - 1);
    const capped = Math.min(exponential, this.maxDelayMs);

    if (this.jitterFactor === 0) return capped;

    const jitterRange = capped * this.jitterFactor;
    const jitter = (Math.random() * 2 - 1) * jitterRange; // ±jitterRange
    return Math.max(0, Math.round(capped + jitter));
  }

  /**
   * Execute `fn` with retry logic.  Returns the first successful result
   * or throws RetryExhaustedError.
   *
   * @template T
   * @param {() => Promise<T>} fn
   * @param {string} [label='operation'] - Descriptive label for error messages
   * @param {AbortSignal} [signal]       - Optional abort signal
   * @returns {Promise<T>}
   */
  async execute(fn, label = "operation", signal) {
    /** @type {Error[]} */
    const errors = [];

    for (let attempt = 1; attempt <= this.maxAttempts; attempt++) {
      if (signal?.aborted) {
        throw new DOMException("Retry aborted", "AbortError");
      }

      try {
        return await fn();
      } catch (err) {
        errors.push(err);

        const isLastAttempt = attempt === this.maxAttempts;
        if (isLastAttempt || !this.retryIf(err)) {
          break;
        }

        const delayMs = this.getDelay(attempt);
        this.onRetry({ attempt, delayMs, error: err });
        await this._sleep(delayMs, signal);
      }
    }

    throw new RetryExhaustedError(label, this.maxAttempts, errors);
  }

  /**
   * @param {number} ms
   * @param {AbortSignal} [signal]
   * @returns {Promise<void>}
   * @private
   */
  _sleep(ms, signal) {
    return new Promise((resolve, reject) => {
      if (signal?.aborted) {
        return reject(new DOMException("Retry aborted", "AbortError"));
      }

      const timer = setTimeout(resolve, ms);

      signal?.addEventListener(
        "abort",
        () => {
          clearTimeout(timer);
          reject(new DOMException("Retry aborted", "AbortError"));
        },
        { once: true }
      );
    });
  }
}

module.exports = { RetryPolicy };
