   * @param {string}   options.filePath       - Absolute or relative path
   * @param {string}   [options.encoding='utf-8']
   * @param {boolean}  [options.optional=false] - If true, missing file → {}
   * @param {(raw: string) => Object} [options.parser] - Custom parser
   */
  constructor({ filePath, encoding = "utf-8", optional = false, parser }) {
    super();
    this._filePath = path.resolve(filePath);
    this._encoding = encoding;
    this._optional = optional;
    this._parser = parser ?? FileSource._defaultParser(this._filePath);
  }

  get name() {
    return `file://${this._filePath}`;
  }

  async load() {
    try {
      const raw = await fs.readFile(this._filePath, this._encoding);
      return this._parser(raw);
    } catch (err) {
      if (this._optional && err.code === "ENOENT") {
        return {};
      }
      throw new ConfigLoadError(this.name, err);
    }
  }

  /**
   * Pick a parser based on file extension.
   * @param {string} filePath
   * @returns {(raw: string) => Object}
   * @private
   */
  static _defaultParser(filePath) {
    const ext = path.extname(filePath).toLowerCase();
    switch (ext) {
      case ".json":
        return (raw) => JSON.parse(raw);
      case ".js":
      case ".cjs":
        return () => require(filePath);
      default:
        return (raw) => JSON.parse(raw); // fallback to JSON
    }
  }
}

module.exports = { FileSource };
