## File Hasher Utility

```javascript
// utils/file-hasher.js
const fs = require('fs');
const crypto = require('crypto');
const { pipeline } = require('stream/promises');

/**
 * Computes a SHA-256 hash of a file using streaming to handle large files.
 */
async function hashFile(filePath) {
  const hash = crypto.createHash('sha256');
  const input = fs.createReadStream(filePath);

  await pipeline(input, hash);
  return hash.digest('hex');
}

/**
 * Gathers metadata + hash for a single file.
 */
async function getFileFingerprint(filePath) {
  const [stats, checksum] = await Promise.all([
    fs.promises.stat(filePath),
    hashFile(filePath),
  ]);

  return {
    path: filePath,
    size: stats.size,
    modifiedAt: stats.mtimeMs,
    checksum,
  };
}

module.exports = { hashFile, getFileFingerprint };
