const fs = require('fs');
const path = require('path');

/**
 * Manages a JSON manifest that records the state of every file
 * at the time of the last successful backup.
 *
 * Structure:
 * {
 *   version: 2,
 *   lastBackupId: "backup-2024-01-15T10-30-00",
 *   lastBackupTime: 1705312200000,
 *   files: {
 *     "/data/report.pdf": { checksum: "abc123...", size: 4096, modifiedAt: ... },
 *     ...
 *   }
 * }
 */
class BackupManifest {
  constructor(manifestPath) {
    this.manifestPath = manifestPath;
    this.data = null;
  }

  /** Load manifest from disk, or start fresh. */
  async load() {
    try {
      const raw = await fs.promises.readFile(this.manifestPath, 'utf-8');
      this.data = JSON.parse(raw);
      console.log(`[Manifest] Loaded – last backup: ${this.data.lastBackupId}`);
    } catch {
      this.data = { version: 2, lastBackupId: null, lastBackupTime: null, files: {} };
      console.log('[Manifest] No previous manifest found – starting fresh.');
    }
    return this;
  }

  /** Persist current state to disk atomically. */
  async save() {
    const tmpPath = `${this.manifestPath}.tmp`;
    await fs.promises.writeFile(tmpPath, JSON.stringify(this.data, null, 2));
    await fs.promises.rename(tmpPath, this.manifestPath);   // atomic on most OS
  }

  /** Return stored fingerprint for a file, or null. */
  getFileRecord(filePath) {
    return this.data.files[filePath] ?? null;
  }

  /** Update a single file's record after successful copy. */
  updateFileRecord(filePath, fingerprint) {
    this.data.files[filePath] = {
      checksum: fingerprint.checksum,
      size: fingerprint.size,
      modifiedAt: fingerprint.modifiedAt,
    };
  }

  /** Remove files from the manifest that no longer exist on disk. */
  pruneDeleted(existingPaths) {
    const existingSet = new Set(existingPaths);
    const deleted = [];

    for (const recorded of Object.keys(this.data.files)) {
      if (!existingSet.has(recorded)) {
        delete this.data.files[recorded];
        deleted.push(recorded);
      }
    }
    return deleted;
  }

  /** Mark the backup as complete with an ID and timestamp. */
  finalize(backupId) {
    this.data.lastBackupId = backupId;
    this.data.lastBackupTime = Date.now();
  }
}

module.exports = BackupManifest;
