## Backup Worker Thread

```javascript
// backup-worker.js
const { parentPort, workerData } = require('worker_threads');
const fs = require('fs');
const path = require('path');
const { getFileFingerprint } = require('./utils/file-hasher');
const BackupManifest = require('./backup-manifest');

// ── Message helper ──────────────────────────────────────────
function send(type, payload = {}) {
  parentPort.postMessage({ type, ...payload });
}

// ── Recursive directory scan ────────────────────────────────
async function scanDirectory(dir, ignore = []) {
  const entries = [];
  const items = await fs.promises.readdir(dir, { withFileTypes: true });

  for (const item of items) {
    const fullPath = path.join(dir, item.name);

    if (ignore.some((pattern) => fullPath.includes(pattern))) continue;

    if (item.isDirectory()) {
      entries.push(...(await scanDirectory(fullPath, ignore)));
    } else if (item.isFile()) {
      entries.push(fullPath);
    }
  }
  return entries;
}

// ── Detect which files actually changed ─────────────────────
async function detectChanges(filePaths, manifest) {
  const changed = [];
  const unchanged = [];

  for (const filePath of filePaths) {
    const recorded = manifest.getFileRecord(filePath);

    // Quick pre-check: if mtime hasn't changed, skip expensive hash
    if (recorded) {
      try {
        const stat = await fs.promises.stat(filePath);
        if (stat.mtimeMs === recorded.modifiedAt && stat.size === recorded.size) {
          unchanged.push(filePath);
          continue;
        }
      } catch {
        // File may have been removed between scan and stat
        continue;
      }
    }

    // Either new file or mtime changed → compute full fingerprint
    try {
      const fingerprint = await getFileFingerprint(filePath);

      if (!recorded || recorded.checksum !== fingerprint.checksum) {
        changed.push({ filePath, fingerprint });
      } else {
        // mtime changed but content identical – update mtime in manifest
        unchanged.push(filePath);
        manifest.updateFileRecord(filePath, fingerprint);
      }
    } catch (err) {
      send('warning', { message: `Skipping ${filePath}: ${err.message}` });
    }
  }

  return { changed, unchanged };
}

// ── Copy a file into the backup destination ─────────────────
async function backupFile(filePath, sourceRoot, destRoot) {
  const relative = path.relative(sourceRoot, filePath);
  const destPath = path.join(destRoot, relative);

  await fs.promises.mkdir(path.dirname(destPath), { recursive: true });
  await fs.promises.copyFile(filePath, destPath);

  return destPath;
}

// ── Main worker routine ─────────────────────────────────────
async function runBackup() {
  const {
    sourceDir,
    backupDir,
    manifestPath,
    ignorePaths = [],
    maxRetries = 3,
  } = workerData;

  const backupId = `backup-${new Date().toISOString().replace(/[:.]/g, '-')}`;
  const destRoot = path.join(backupDir, backupId);

  send('started', { backupId });

  // 1️⃣  Load manifest
  const manifest = await new BackupManifest(manifestPath).load();

  // 2️⃣  Scan source directory
  send('phase', { phase: 'scanning' });
  const allFiles = await scanDirectory(sourceDir, ignorePaths);
  send('scan-complete', { totalFiles: allFiles.length });

  // 3️⃣  Detect changed files (the "incremental" part)
  send('phase', { phase: 'detecting-changes' });
  const { changed, unchanged } = await detectChanges(allFiles, manifest);

  // 3a. Prune deleted files from manifest
  const deleted = manifest.pruneDeleted(allFiles);
  send('changes-detected', {
    changedCount: changed.length,
    unchangedCount: unchanged.length,
    deletedCount: deleted.length,
  });

  if (changed.length === 0) {
    send('completed', { backupId, copiedFiles: 0, skippedFiles: allFiles.length });
    await manifest.save();
    return;
  }

  // 4️⃣  Copy changed files with progress + retry
  send('phase', { phase: 'copying' });
  let copied = 0;
  let failed = 0;

  for (const { filePath, fingerprint } of changed) {
    let success = false;

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      try {
        await backupFile(filePath, sourceDir, destRoot);
        manifest.updateFileRecord(filePath, fingerprint);
        copied++;
        success = true;

        // Report progress every file (throttle in production)
        send('progress', {
          copied,
          total: changed.length,
          percent: Math.round((copied / changed.length) * 100),
          currentFile: path.relative(sourceDir, filePath),
        });
        break;
      } catch (err) {
        send('warning', {
          message: `Attempt ${attempt}/${maxRetries} failed for ${filePath}: ${err.message}`,
        });
        if (attempt < maxRetries) {
          await new Promise((r) => setTimeout(r, 1000 * attempt)); // exponential-ish
        }
      }
    }

    if (!success) {
      failed++;
      send('file-error', { filePath, message: 'All retry attempts exhausted' });
    }
  }

  // 5️⃣  Write backup metadata alongside the copied files
  const metadata = {
    backupId,
    createdAt: new Date().toISOString(),
    sourceDir,
    totalFiles: allFiles.length,
    copiedFiles: copied,
    failedFiles: failed,
    deletedSinceLastBackup: deleted.length,
  };
  await fs.promises.writeFile(
    path.join(destRoot, '_backup-meta.json'),
    JSON.stringify(metadata, null, 2),
  );

  // 6️⃣  Finalize manifest
  manifest.finalize(backupId);
  await manifest.save();

  send('completed', { backupId, copiedFiles: copied, failedFiles: failed });
}

// ── Run & handle fatal errors ───────────────────────────────
runBackup().catch((err) => {
  send('error', { message: err.message, stack: err.stack });
  process.exit(1);
});
