## Main Thread / Scheduler

```javascript
// main.js
const { Worker } = require('worker_threads');
const path = require('path');
const EventEmitter = require('events');

// ── Backup Manager ──────────────────────────────────────────
class BackupManager extends EventEmitter {
  constructor(config) {
    super();
    this.config = {
      sourceDir: config.sourceDir,
      backupDir: config.backupDir,
      manifestPath: config.manifestPath || path.join(config.backupDir, 'manifest.json'),
      ignorePaths: config.ignorePaths || ['node_modules', '.git', '.DS_Store'],
      intervalMs: config.intervalMs || 60 * 60 * 1000,  // default: 1 hour
      maxRetries: config.maxRetries || 3,
    };
    this.worker = null;
    this.timer = null;
    this.isRunning = false;
    this.history = [];       // recent backup summaries
  }

  /** Spin up a worker to run one incremental backup. */
  runNow() {
    if (this.isRunning) {
      console.log('[BackupManager] Backup already in progress – skipping.');
      return;
    }

    this.isRunning = true;

    this.worker = new Worker(path.join(__dirname, 'backup-worker.js'), {
      workerData: {
        sourceDir: this.config.sourceDir,
        backupDir: this.config.backupDir,
        manifestPath: this.config.manifestPath,
        ignorePaths: this.config.ignorePaths,
        maxRetries: this.config.maxRetries,
      },
    });

    this.worker.on('message', (msg) => this._handleMessage(msg));

    this.worker.on('error', (err) => {
      console.error('[BackupManager] Worker error:', err);
      this.isRunning = false;
      this.emit('error', err);
    });

    this.worker.on('exit', (code) => {
      this.isRunning = false;
      if (code !== 0) {
        console.error(`[BackupManager] Worker exited with code ${code}`);
      }
      this.worker = null;
    });
  }

  /** Start the periodic schedule. */
  start() {
    console.log(`[BackupManager] Scheduling every ${this.config.intervalMs / 1000}s`);
    this.runNow();
    this.timer = setInterval(() => this.runNow(), this.config.intervalMs);
  }

  /** Stop the schedule and abort any running backup. */
  stop() {
    if (this.timer) clearInterval(this.timer);
    if (this.worker) this.worker.terminate();
    this.isRunning = false;
    console.log('[BackupManager] Stopped.');
  }

  // ── Internal message router ─────────────────────────────
  _handleMessage(msg) {
    switch (msg.type) {
      case 'started':
        console.log(`\n🟢  Backup started: ${msg.backupId}`);
        break;

      case 'phase':
        console.log(`   ⏳ Phase: ${msg.phase}`);
        break;

      case 'scan-complete':
        console.log(`   📂 Found ${msg.totalFiles} files`);
        break;

      case 'changes-detected':
        console.log(
          `   🔍 Changed: ${msg.changedCount} | ` +
          `Unchanged: ${msg.unchangedCount} | ` +
          `Deleted: ${msg.deletedCount}`,
        );
        break;

      case 'progress':
        // Overwrite the same line for a clean progress display
        process.stdout.write(
          `\r   📦 Copying: ${msg.percent}% (${msg.copied}/${msg.total}) – ${msg.currentFile}   `,
        );
        break;

      case 'warning':
        console.warn(`\n   ⚠️  ${msg.message}`);
        break;

      case 'file-error':
        console.error(`\n   ❌ Failed: ${msg.filePath} – ${msg.message}`);
        break;

      case 'completed':
        console.log(`\n✅  Backup complete: ${msg.backupId}`);
        console.log(`   Copied ${msg.copiedFiles} files. Failed: ${msg.failedFiles ?? 0}`);
        this.history.push({ ...msg, completedAt: new Date() });
        this.emit('backup-complete', msg);
        break;

      case 'error':
        console.error(`\n🔴  Backup error: ${msg.message}`);
        this.emit('error', new Error(msg.message));
        break;

      default:
        console.log('   [unknown message]', msg);
    }
  }
}

// ── Example usage ───────────────────────────────────────────
const manager = new BackupManager({
  sourceDir: path.resolve('./data'),           // directory to back up
  backupDir: path.resolve('./backups'),         // where backups are stored
  ignorePaths: ['node_modules', '.git', 'tmp'],
  intervalMs: 30 * 60 * 1000,                  // every 30 minutes
});

// React to events programmatically
manager.on('backup-complete', ({ backupId, copiedFiles }) => {
  if (copiedFiles > 0) {
    console.log(`[Hook] Could notify Slack / rotate old backups here.`);
  }
});

manager.on('error', (err) => {
  console.error('[Hook] Could send alert:', err.message);
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\nShutting down...');
  manager.stop();
  process.exit(0);
});

// 🚀 Start
manager.start();
