## Core Pipeline Engine

```javascript
// pipeline.js
const fs = require("fs");
const path = require("path");

class AnalyticsPipeline {
  constructor(name = "default") {
    this.name = name;
    this.stages = [];
    this.metadata = {
      createdAt: new Date().toISOString(),
      stageCount: 0,
    };
  }

  // --- Input Methods ---

  /** Read JSON from a file path */
  readFromFile(filePath) {
    const absolutePath = path.resolve(filePath);

    if (!fs.existsSync(absolutePath)) {
      throw new Error(`File not found: ${absolutePath}`);
    }

    const raw = fs.readFileSync(absolutePath, "utf-8");
    return this._parseJSON(raw, filePath);
  }

  /** Read JSON from a string */
  readFromString(jsonString) {
    return this._parseJSON(jsonString, "string input");
  }

  /** Read JSON from stdin (for piped input) */
  async readFromStdin() {
    return new Promise((resolve, reject) => {
      let data = "";
      process.stdin.setEncoding("utf-8");
      process.stdin.on("data", (chunk) => (data += chunk));
      process.stdin.on("end", () => resolve(this._parseJSON(data, "stdin")));
      process.stdin.on("error", reject);
    });
  }

  // --- Stage Registration ---

  /** Add a named processing stage */
  addStage(name, fn) {
    if (typeof fn !== "function") {
      throw new TypeError(`Stage "${name}" must be a function`);
    }

    this.stages.push({ name, fn });
    this.metadata.stageCount = this.stages.length;
    return this; // allow chaining
  }

  // --- Execution ---

  /** Run all stages sequentially */
  run(data) {
    console.log(`\n🚀 Pipeline "${this.name}" started`);
    console.log(`   Input records: ${Array.isArray(data) ? data.length : "N/A"}`);
    console.log("─".repeat(50));

    let result = data;
    const timings = [];

    for (const { name, fn } of this.stages) {
      const start = performance.now();

      try {
        result = fn(result);
      } catch (err) {
        console.error(`❌ Stage "${name}" failed: ${err.message}`);
        throw err;
      }

      const elapsed = (performance.now() - start).toFixed(2);
      timings.push({ stage: name, ms: parseFloat(elapsed) });

      const count = Array.isArray(result) ? result.length : Object.keys(result).length;
      console.log(`   ✅ ${name} → ${count} items (${elapsed}ms)`);
    }

    console.log("─".repeat(50));
    console.log(`✔ Pipeline complete\n`);

    return { result, timings };
  }

  // --- Private Helpers ---

  _parseJSON(raw, source) {
    try {
      const parsed = JSON.parse(raw);
      console.log(`📄 Loaded JSON from ${source}`);
      return parsed;
    } catch (err) {
      throw new SyntaxError(`Invalid JSON from ${source}: ${err.message}`);
    }
  }
}

module.exports = { AnalyticsPipeline };
```

## Pipeline Stage Functions

```javascript
// stages.js

/**
 * Extracts a nested array from the JSON object.
 * e.g., { events: [...] } → [...]
 */
function extract(key) {
  return (data) => {
    if (!data[key] || !Array.isArray(data[key])) {
      throw new Error(`Key "${key}" not found or not an array`);
    }
    return data[key];
  };
}

/**
 * Filters records by a predicate function.
 */
function filter(predicate) {
  return (data) => data.filter(predicate);
}

/**
 * Enriches each record with computed fields.
 */
function enrich(enrichFn) {
  return (data) => data.map(enrichFn);
}

/**
 * Groups records by a given key.
 * Returns { [keyValue]: [...records] }
 */
function groupBy(key) {
  return (data) =>
    data.reduce((acc, item) => {
      const group = item[key] ?? "unknown";
      if (!acc[group]) acc[group] = [];
      acc[group].push(item);
      return acc;
    }, {});
}

/**
 * Aggregates grouped data with specified operations.
 * operations: { outputField: { op: 'sum'|'count'|'avg'|'min'|'max', field?: string } }
 */
function aggregate(operations) {
  return (groups) => {
    const results = {};

    for (const [groupKey, records] of Object.entries(groups)) {
      results[groupKey] = {};

      for (const [outField, { op, field }] of Object.entries(operations)) {
        const values = field ? records.map((r) => r[field]).filter((v) => v != null) : records;

        switch (op) {
          case "count":
            results[groupKey][outField] = records.length;
            break;
          case "sum":
            results[groupKey][outField] = values.reduce((s, v) => s + v, 0);
            break;
          case "avg":
            results[groupKey][outField] =
              values.length > 0
                ? parseFloat((values.reduce((s, v) => s + v, 0) / values.length).toFixed(2))
                : 0;
            break;
          case "min":
            results[groupKey][outField] = Math.min(...values);
            break;
          case "max":
            results[groupKey][outField] = Math.max(...values);
            break;
          default:
            throw new Error(`Unknown operation: ${op}`);
        }
      }
    }

    return results;
  };
}

/**
 * Sorts an array of records by a field.
 */
function sortBy(field, order = "asc") {
  return (data) => {
    if (!Array.isArray(data)) return data;
    return [...data].sort((a, b) => {
      if (order === "asc") return a[field] > b[field] ? 1 : -1;
      return a[field] < b[field] ? 1 : -1;
    });
  };
}

/**
 * Picks only specified fields from each record.
 */
function selectFields(...fields) {
  return (data) =>
    data.map((item) =>
      fields.reduce((obj, f) => {
        if (f in item) obj[f] = item[f];
        return obj;
      }, {})
    );
}

module.exports = {
  extract,
  filter,
  enrich,
  groupBy,
  aggregate,
  sortBy,
  selectFields,
};
```

