## File Scanner

```js
// src/FileScanner.js
import fs from "fs/promises";
import path from "path";
import { computeFileChecksum } from "./utils/checksum.js";
import { Logger } from "./utils/logger.js";

/**
 * Recursively scans a directory and returns a map of
 * relative file paths → metadata (size, mtime, checksum).
 */
export class FileScanner {
  #logger = new Logger("FileScanner");
  #excludePatterns;
  #checksumAlgorithm;

  constructor(excludePatterns = [], checksumAlgorithm = "sha256") {
    this.#excludePatterns = excludePatterns;
    this.#checksumAlgorithm = checksumAlgorithm;
  }

  /**
   * Returns Map<relativePath, { size, mtimeMs, checksum }>
   */
  async scan(baseDir) {
    const fileMap = new Map();
    await this.#walk(baseDir, baseDir, fileMap);
    this.#logger.info(`Scanned ${fileMap.size} files in ${baseDir}`);
    return fileMap;
  }

  async #walk(baseDir, currentDir, fileMap) {
    let entries;
    try {
      entries = await fs.readdir(currentDir, { withFileTypes: true });
    } catch (err) {
      this.#logger.warn(`Cannot read directory: ${currentDir}`, err.message);
      return;
    }

    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name);
      const relativePath = path.relative(baseDir, fullPath);

      if (this.#isExcluded(entry.name, relativePath)) {
        continue;
      }

      if (entry.isDirectory()) {
        await this.#walk(baseDir, fullPath, fileMap);
      } else if (entry.isFile()) {
        try {
          const stat = await fs.stat(fullPath);
          const checksum = await computeFileChecksum(
            fullPath,
            this.#checksumAlgorithm
          );

          fileMap.set(relativePath, {
            size: stat.size,
            mtimeMs: stat.mtimeMs,
            checksum,
          });
        } catch (err) {
          this.#logger.warn(`Skipping file ${relativePath}`, err.message);
        }
      }
    }
  }

  #isExcluded(name, relativePath) {
    return this.#excludePatterns.some((pattern) => {
      // Simple wildcard matching: "*.tmp" or exact name match
      if (pattern.startsWith("*")) {
        return name.endsWith(pattern.slice(1));
      }
      return name === pattern || relativePath.startsWith(pattern);
    });
  }
}
