## Backup Manifest

```js
// src/BackupManifest.js
import fs from "fs/promises";
import path from "path";
import { Logger } from "./utils/logger.js";

/**
 * Each manifest records:
 * - Backup ID and timestamp
 * - Type: 'full' or 'incremental'
 * - Parent backup ID (for incrementals)
 * - Map of all files with their checksums at backup time
 * - Lists of added / modified / deleted files in this backup
 */
export class BackupManifest {
  #manifestDir;
  #logger = new Logger("Manifest");

  constructor(manifestDir) {
    this.#manifestDir = manifestDir;
  }

  async init() {
    await fs.mkdir(this.#manifestDir, { recursive: true });
  }

  createId() {
    const now = new Date();
    const pad = (n, len = 2) => String(n).padStart(len, "0");
    return [
      now.getFullYear(),
      pad(now.getMonth() + 1),
      pad(now.getDate()),
      "T",
      pad(now.getHours()),
      pad(now.getMinutes()),
      pad(now.getSeconds()),
    ].join("");
  }

  /**
   * Build a new manifest by comparing current file map against the previous one.
   */
  buildManifest(backupId, type, currentFiles, previousManifest = null) {
    const previousFiles = previousManifest?.files ?? {};

    const added = [];
    const modified = [];
    const unchanged = [];
    const deleted = [];

    // Detect added and modified files
    for (const [filePath, meta] of currentFiles) {
      const prev = previousFiles[filePath];
      if (!prev) {
        added.push(filePath);
      } else if (prev.checksum !== meta.checksum) {
        modified.push(filePath);
      } else {
        unchanged.push(filePath);
      }
    }

    // Detect deleted files
    for (const filePath of Object.keys(previousFiles)) {
      if (!currentFiles.has(filePath)) {
        deleted.push(filePath);
      }
    }

    // Serialize current file map for storage
    const files = {};
    for (const [filePath, meta] of currentFiles) {
      files[filePath] = meta;
    }

    return {
      id: backupId,
      type,
      parentId: previousManifest?.id ?? null,
      timestamp: new Date().toISOString(),
      stats: {
        total: currentFiles.size,
        added: added.length,
        modified: modified.length,
        unchanged: unchanged.length,
        deleted: deleted.length,
      },
      changeset: { added, modified, deleted },
      files,
    };
  }

  async save(manifest) {
    const filePath = path.join(this.#manifestDir, `${manifest.id}.json`);
    await fs.writeFile(filePath, JSON.stringify(manifest, null, 2));
    this.#logger.info(`Manifest saved: ${manifest.id}`);
  }

  async loadLatest() {
    try {
      const entries = await fs.readdir(this.#manifestDir);
      const manifests = entries
        .filter((f) => f.endsWith(".json"))
        .sort()
        .reverse();

      if (manifests.length === 0) return null;

      const data = await fs.readFile(
        path.join(this.#manifestDir, manifests[0]),
        "utf-8"
      );
      return JSON.parse(data);
    } catch {
      return null;
    }
  }

  async load(backupId) {
    const filePath = path.join(this.#manifestDir, `${backupId}.json`);
    const data = await fs.readFile(filePath, "utf-8");
    return JSON.parse(data);
  }

  /**
   * Return all manifest filenames sorted oldest → newest.
   */
  async listAll() {
    try {
      const entries = await fs.readdir(this.#manifestDir);
      return entries.filter((f) => f.endsWith(".json")).sort();
    } catch {
      return [];
    }
  }

  /**
   * Count the number of consecutive incremental backups since the last full.
   */
  async countIncrementalsSinceLastFull() {
    const all = await this.listAll();
    let count = 0;

    // Walk backwards from newest
    for (let i = all.length - 1; i >= 0; i--) {
      const data = await fs.readFile(
        path.join(this.#manifestDir, all[i]),
        "utf-8"
      );
      const manifest = JSON.parse(data);
      if (manifest.type === "full") break;
      count++;
    }

    return count;
  }

  async deleteManifest(backupId) {
    const filePath = path.join(this.#manifestDir, `${backupId}.json`);
    await fs.unlink(filePath);
  }
}
