```js
// src/BackupWorker.js
import fs from "fs/promises";
import path from "path";
import { EventEmitter } from "events";
import { FileScanner } from "./FileScanner.js";
import { BackupManifest } from "./BackupManifest.js";
import { compressFile } from "./utils/compression.js";
import { Logger } from "./utils/logger.js";

export class BackupWorker extends EventEmitter {
  #config;
  #scanner;
  #manifest;
  #logger = new Logger("BackupWorker");
  #running = false;

  constructor(config) {
    super();
    this.#config = config;
    this.#scanner = new FileScanner(
      config.excludePatterns,
      config.checksumAlgorithm
    );
    this.#manifest = new BackupManifest(config.manifestDir);
  }

  get isRunning() {
    return this.#running;
  }

  async init() {
    await fs.mkdir(this.#config.backupDir, { recursive: true });
    await this.#manifest.init();
    this.#logger.info("Worker initialized", {
      source: this.#config.sourceDir,
      dest: this.#config.backupDir,
    });
  }

  /**
   * Main entry point — decides full vs. incremental, then runs the backup.
   */
  async runBackup() {
    if (this.#running) {
      this.#logger.warn("Backup already in progress, skipping");
      return null;
    }

    this.#running = true;
    const startTime = Date.now();
    this.emit("backup:start");

    try {
      // 1. Determine backup type
      const previousManifest = await this.#manifest.loadLatest();
      const incrementalCount =
        await this.#manifest.countIncrementalsSinceLastFull();

      const shouldDoFull =
        !previousManifest ||
        incrementalCount >= this.#config.maxIncrementals;

      const backupType = shouldDoFull ? "full" : "incremental";
      const backupId = this.#manifest.createId();

      this.#logger.info(
        `Starting ${backupType} backup [${backupId}] ` +
        `(incrementals since last full: ${incrementalCount})`
      );

      // 2. Scan source directory
      const currentFiles = await this.#scanner.scan(this.#config.sourceDir);

      // 3. Build manifest (diff against previous)
      const manifest = this.#manifest.buildManifest(
        backupId,
        backupType,
        currentFiles,
        previousManifest
      );

      this.#logger.info("Changeset computed", manifest.stats);

      // 4. Determine which files to copy
      const filesToCopy =
        backupType === "full"
          ? [...currentFiles.keys()]  // Copy everything
          : [
              ...manifest.changeset.added,
              ...manifest.changeset.modified,
            ];

      if (filesToCopy.length === 0 && backupType === "incremental") {
        this.#logger.info("No changes detected — skipping backup");
        this.emit("backup:skipped", { backupId });
        return null;
      }

      // 5. Create backup directory for this run
      const backupPath = path.join(this.#config.backupDir, backupId);
      await fs.mkdir(backupPath, { recursive: true });

      // 6. Copy changed files
      const result = await this.#copyFiles(
        filesToCopy,
        this.#config.sourceDir,
        backupPath
      );

      // 7. Write a deletion log (so restores know what was removed)
      if (manifest.changeset.deleted.length > 0) {
        const deletionLog = path.join(backupPath, ".deleted_files.json");
        await fs.writeFile(
          deletionLog,
          JSON.stringify(manifest.changeset.deleted, null, 2)
        );
      }

      // 8. Save manifest
      manifest.backupPath = backupPath;
      manifest.bytesCopied = result.bytesCopied;
      manifest.filesCopied = result.filesCopied;
      manifest.errors = result.errors;
      manifest.durationMs = Date.now() - startTime;

      await this.#manifest.save(manifest);

      // 9. Retention cleanup
      await this.#enforceRetention();

      this.#logger.info(
        `Backup complete [${backupId}] — ` +
        `${result.filesCopied} files, ` +
        `${this.#formatBytes(result.bytesCopied)} copied, ` +
        `${manifest.durationMs}ms`
      );

      this.emit("backup:complete", manifest);
      return manifest;
    } catch (err) {
      this.#logger.error("Backup failed", err);
      this.emit("backup:error", err);
      throw err;
    } finally {
      this.#running = false;
    }
  }

  /**
   * Copy a list of relative file paths from source → backup destination.
   */
