## lib/tokenizer.js — Text Processing

```javascript
const STOP_WORDS = new Set([
  'the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to',
  'for', 'of', 'with', 'by', 'is', 'are', 'was', 'were', 'be',
  'has', 'have', 'had', 'do', 'does', 'did', 'will', 'would',
  'could', 'should', 'may', 'might', 'this', 'that', 'it', 'not',
]);

/**
 * Normalize and split text into searchable tokens.
 * Returns an array of { term, position } objects.
 */
export function tokenize(text) {
  const tokens = [];
  // Strip markdown/html artifacts, lowercase, split on non-word chars
  const words = text
    .toLowerCase()
    .replace(/[#*_`~\[\](){}<>]/g, ' ')
    .replace(/https?:\/\/\S+/g, '')
    .split(/[^a-z0-9]+/)
    .filter(w => w.length > 1 && !STOP_WORDS.has(w));

  for (let i = 0; i < words.length; i++) {
    tokens.push({ term: words[i], position: i });
  }

  return tokens;
}

/**
 * Stem a word (simple suffix stripping — good enough for most cases).
 */
export function stem(word) {
  if (word.length < 4) return word;
  // Order matters: longest suffixes first
  const suffixes = ['ation', 'ness', 'ment', 'ing', 'tion', 'sion', 'able', 'ible', 'ous', 'ive', 'ful', 'less', 'ly', 'ed', 'er', 'es', 's'];
  for (const suffix of suffixes) {
    if (word.endsWith(suffix) && word.length - suffix.length >= 3) {
      return word.slice(0, -suffix.length);
    }
  }
  return word;
}

/**
 * Full pipeline: tokenize → stem → deduplicate with positions.
 */
export function analyze(text) {
  const tokens = tokenize(text);
  const termMap = new Map();

  for (const { term, position } of tokens) {
    const stemmed = stem(term);
    if (!termMap.has(stemmed)) {
      termMap.set(stemmed, { term: stemmed, positions: [], frequency: 0 });
    }
    const entry = termMap.get(stemmed);
    entry.positions.push(position);
    entry.frequency++;
  }

  return Array.from(termMap.values());
}
