## lib/store.js — Inverted Index Storage

```javascript
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';

/**
 * Inverted index backed by a JSON file.
 *
 * Structure:
 *   index: Map<term, Map<filePath, { frequency, positions, lastModified }>>
 *   docs:  Map<filePath, { title, size, lastModified, termCount }>
 */
export class IndexStore {
  constructor(persistPath = '.search-index.json') {
    this.persistPath = persistPath;
    // term → Map<filePath → posting>
    this.index = new Map();
    // filePath → document metadata
    this.docs = new Map();
    this.dirty = false;
  }

  /** Load index from disk. Silent no-op if file missing. */
  async load() {
    try {
      const raw = await readFile(this.persistPath, 'utf-8');
      const data = JSON.parse(raw);

      this.docs = new Map(Object.entries(data.docs ?? {}));
      this.index = new Map();

      for (const [term, postings] of Object.entries(data.index ?? {})) {
        this.index.set(term, new Map(Object.entries(postings)));
      }

      console.log(`Loaded index: ${this.docs.size} docs, ${this.index.size} terms`);
    } catch {
      console.log('No existing index found — starting fresh');
    }
  }

  /** Persist index to disk. */
  async save() {
    if (!this.dirty) return;

    const data = {
      docs: Object.fromEntries(this.docs),
      index: {},
    };

    for (const [term, postings] of this.index) {
      data.index[term] = Object.fromEntries(postings);
    }

    await mkdir(dirname(this.persistPath), { recursive: true }).catch(() => {});
    await writeFile(this.persistPath, JSON.stringify(data), 'utf-8');
    this.dirty = false;
  }

  /** Add or update a document in the index. */
  addDocument(filePath, meta, terms) {
    // Remove old postings first
    this.removeDocument(filePath);

    this.docs.set(filePath, meta);

    for (const { term, frequency, positions } of terms) {
      if (!this.index.has(term)) {
        this.index.set(term, new Map());
      }
      this.index.get(term).set(filePath, {
        frequency,
        positions,
        lastModified: meta.lastModified,
      });
    }

    this.dirty = true;
  }

  /** Remove a document and all its postings. */
  removeDocument(filePath) {
    if (!this.docs.has(filePath)) return;

    this.docs.delete(filePath);

    // Walk every term and remove this file's postings
    for (const [term, postings] of this.index) {
      postings.delete(filePath);
      if (postings.size === 0) {
        this.index.delete(term);
      }
    }

    this.dirty = true;
  }

  /**
   * Search the index. Returns ranked results.
   * Uses TF-IDF scoring with position boosting.
   */
  search(queryTerms, limit = 20) {
    const totalDocs = this.docs.size;
    if (totalDocs === 0) return [];

    const scores = new Map();

    for (const term of queryTerms) {
      const postings = this.index.get(term);
      if (!postings) continue;

      // IDF: log(totalDocs / docsContainingTerm)
      const idf = Math.log(totalDocs / postings.size);

      for (const [filePath, posting] of postings) {
        const tf = 1 + Math.log(posting.frequency); // log-scaled TF
        const score = tf * idf;

        scores.set(filePath, (scores.get(filePath) ?? 0) + score);
      }
    }

    // Boost docs that contain ALL query terms
    for (const [filePath, score] of scores) {
      let matchedTerms = 0;
      for (const term of queryTerms) {
        if (this.index.get(term)?.has(filePath)) matchedTerms++;
      }
      const completenessBoost = matchedTerms / queryTerms.length;
      scores.set(filePath, score * (1 + completenessBoost));
    }

    return Array.from(scores.entries())
      .map(([filePath, score]) => ({
        filePath,
        score: Math.round(score * 1000) / 1000,
        ...this.docs.get(filePath),
      }))
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);
  }

  get stats() {
    return {
      documents: this.docs.size,
      terms: this.index.size,
      dirty: this.dirty,
    };
  }
}
