## lib/indexer.js — Document Processing

```javascript
import { readFile, stat } from 'node:fs/promises';
import { extname, basename } from 'node:path';
import { analyze, stem, tokenize } from './tokenizer.js';

const SUPPORTED_EXTENSIONS = new Set([
  '.txt', '.md', '.markdown', '.rst',
  '.js', '.ts', '.jsx', '.tsx',
  '.py', '.rb', '.go', '.rs', '.java',
  '.json', '.yaml', '.yml', '.toml',
  '.html', '.css', '.scss',
  '.sh', '.bash', '.zsh',
  '.env', '.cfg', '.ini', '.conf',
]);

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5 MB

export class Indexer {
  constructor(store) {
    this.store = store;
    this.queue = new Map();       // filePath → timeout handle
    this.processing = new Set();  // files currently being indexed
    this.debounceMs = 300;
  }

  /** Check whether a file should be indexed. */
  shouldIndex(filePath) {
    const ext = extname(filePath).toLowerCase();
    const name = basename(filePath);

    // Skip hidden files, node_modules, build artifacts
    if (name.startsWith('.') && name !== '.env') return false;
    if (filePath.includes('node_modules')) return false;
    if (filePath.includes('.git')) return false;
    if (filePath.includes('dist/')) return false;
    if (filePath.includes('build/')) return false;

    // Allow extensionless files (Makefile, Dockerfile, etc.)
    if (ext === '') return true;

    return SUPPORTED_EXTENSIONS.has(ext);
  }

  /**
   * Schedule a file for indexing with debounce.
   * Rapid saves won't cause redundant work.
   */
  scheduleIndex(filePath) {
    if (!this.shouldIndex(filePath)) return;

    // Cancel any pending debounce for this file
    if (this.queue.has(filePath)) {
      clearTimeout(this.queue.get(filePath));
    }

    const handle = setTimeout(() => {
      this.queue.delete(filePath);
      this.indexFile(filePath);
    }, this.debounceMs);

    this.queue.set(filePath, handle);
  }

  /** Schedule a file for removal from the index. */
  scheduleRemove(filePath) {
    if (this.queue.has(filePath)) {
      clearTimeout(this.queue.get(filePath));
      this.queue.delete(filePath);
    }

    this.store.removeDocument(filePath);
    console.log(`  ✕ Removed: ${filePath}`);
  }

  /** Read and index a single file. */
  async indexFile(filePath) {
    if (this.processing.has(filePath)) return;
    this.processing.add(filePath);

    try {
      const fileStat = await stat(filePath);

      if (fileStat.size > MAX_FILE_SIZE) {
        console.log(`  ⊘ Skipped (too large): ${filePath}`);
        return;
      }

      // Skip if file hasn't changed since last index
      const existing = this.store.docs.get(filePath);
      if (existing?.lastModified === fileStat.mtimeMs) return;

      const content = await readFile(filePath, 'utf-8');
      const terms = analyze(content);

      const meta = {
        title: this.extractTitle(filePath, content),
        size: fileStat.size,
        lastModified: fileStat.mtimeMs,
        termCount: terms.length,
        extension: extname(filePath),
      };

      this.store.addDocument(filePath, meta, terms);
      console.log(`  ✓ Indexed: ${filePath} (${terms.length} terms)`);
    } catch (err) {
      if (err.code !== 'ENOENT') {
        console.error(`  ✗ Error indexing ${filePath}: ${err.message}`);
      }
    } finally {
      this.processing.delete(filePath);
    }
  }

  /** Try to extract a meaningful title from the file. */
  extractTitle(filePath, content) {
    const name = basename(filePath);

    // Markdown: first # heading
    const mdHeading = content.match(/^#\s+(.+)$/m);
    if (mdHeading) return mdHeading[1].trim();

    // HTML: <title> or first <h1>
    const htmlTitle = content.match(/<title>(.+?)<\/title>/i)
      ?? content.match(/<h1[^>]*>(.+?)<\/h1>/i);
    if (htmlTitle) return htmlTitle[1].trim();

    return name;
  }

  /** Search with the same analyzer pipeline used for indexing. */
  search(query) {
    const queryTerms = tokenize(query).map(t => stem(t.term));
    if (queryTerms.length === 0) return [];
    return this.store.search(queryTerms);
  }

  /** Flush pending debounced work and persist. */
  async flush() {
    // Wait for all debounced items to process
    for (const [filePath, handle] of this.queue) {
      clearTimeout(handle);
      await this.indexFile(filePath);
    }
    this.queue.clear();
    await this.store.save();
  }
}
