## lib/watcher.js — File System Watcher

```javascript
import chokidar from 'chokidar';
import { EventEmitter } from 'node:events';

/**
 * Wraps chokidar with sensible defaults for indexing.
 * Emits: 'add', 'change', 'remove', 'ready', 'error'
 */
export class FileWatcher extends EventEmitter {
  constructor(paths, options = {}) {
    super();
    this.paths = Array.isArray(paths) ? paths : [paths];
    this.options = {
      ignored: [
        '**/node_modules/**',
        '**/.git/**',
        '**/dist/**',
        '**/build/**',
        '**/.search-index.json',
        '**/package-lock.json',
        '**/yarn.lock',
      ],
      persistent: true,
      ignoreInitial: false,       // index existing files on startup
      awaitWriteFinish: {         // wait for writes to complete
        stabilityThreshold: 200,
        pollInterval: 50,
      },
      ...options,
    };
    this.watcher = null;
    this.fileCount = 0;
  }

  /** Start watching. Returns a promise that resolves when initial scan is done. */
  start() {
    return new Promise((resolve, reject) => {
      this.watcher = chokidar.watch(this.paths, this.options);

      this.watcher
        .on('add', (path) => {
          this.fileCount++;
          this.emit('add', path);
        })
        .on('change', (path) => {
          this.emit('change', path);
        })
        .on('unlink', (path) => {
          this.fileCount--;
          this.emit('remove', path);
        })
        .on('ready', () => {
          console.log(`Initial scan complete. Found ${this.fileCount} files.`);
          this.emit('ready');
          resolve();
        })
        .on('error', (err) => {
          console.error(`Watcher error: ${err.message}`);
          this.emit('error', err);
          reject(err);
        });
    });
  }

  /** Stop watching and clean up. */
  async stop() {
    if (this.watcher) {
      await this.watcher.close();
      this.watcher = null;
      console.log('File watcher stopped.');
    }
  }
}
