```javascript
import { resolve } from 'node:path';
import { createInterface } from 'node:readline';
import { IndexStore } from './lib/store.js';
import { Indexer } from './lib/indexer.js';
import { FileWatcher } from './lib/watcher.js';

const WATCH_PATH = process.argv[2] ?? '.';
const INDEX_PATH = resolve(WATCH_PATH, '.search-index.json');
const SAVE_INTERVAL = 10_000; // persist every 10s

async function main() {
  const store = new IndexStore(INDEX_PATH);
  const indexer = new Indexer(store);
  const watcher = new FileWatcher(resolve(WATCH_PATH));

  // Load any existing index
  await store.load();

  // Wire watcher events to the indexer
  watcher.on('add', (path) => indexer.scheduleIndex(path));
  watcher.on('change', (path) => indexer.scheduleIndex(path));
  watcher.on('remove', (path) => indexer.scheduleRemove(path));

  // Start watching (resolves after initial scan)
  await watcher.start();

  // Periodic save
  const saveTimer = setInterval(async () => {
    await store.save();
  }, SAVE_INTERVAL);

  // Interactive search REPL
  const rl = createInterface({
    input: process.stdin,
    output: process.stdout,
    prompt: '\n🔍 search> ',
  });

  console.log('\n--- Search Indexer Running ---');
  console.log(`Watching: ${resolve(WATCH_PATH)}`);
  console.log(`Index:    ${INDEX_PATH}`);
  console.log(`Stats:    ${store.stats.documents} docs, ${store.stats.terms} terms`);
  console.log('Type a query to search. Ctrl+C to quit.\n');

  rl.prompt();

  rl.on('line', (line) => {
    const query = line.trim();

    if (query === '') {
      console.log(`Stats: ${store.stats.documents} docs, ${store.stats.terms} terms`);
    } else if (query === ':flush') {
      indexer.flush().then(() => console.log('Index flushed and saved.'));
    } else {
      const results = indexer.search(query);
      if (results.length === 0) {
        console.log('  No results found.');
      } else {
        console.log(`  ${results.length} result(s):\n`);
        for (const r of results.slice(0, 10)) {
          console.log(`  ${r.score.toFixed(2).padStart(6)}  ${r.filePath}`);
          console.log(`         ${r.title} (${formatBytes(r.size)})`);
        }
      }
    }

    rl.prompt();
  });

  // Graceful shutdown
  async function shutdown() {
    console.log('\nShutting down...');
    rl.close();
    clearInterval(saveTimer);
    await indexer.flush();
    await watcher.stop();
    console.log('Done.');
    process.exit(0);
  }

  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}

function formatBytes(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

main().catch((err) => {
  console.error('Fatal:', err);
  process.exit(1);
});
