import { parseArgs } from 'node:util';
import { resolve } from 'node:path';
import { loadFile } from './loader.js';
import { Processor } from './processor.js';
import { getFormatter } from './formatters/index.js';

const HELP = `
\x1b[1mreportgen\x1b[0m — Generate reports from CSV/JSON data

\x1b[1mUSAGE\x1b[0m
  reportgen <command> <file> [options]

\x1b[1mCOMMANDS\x1b[0m
  summary    Grouped aggregation report
  detail     Filtered row-level report
  inspect    Show file schema and sample rows

\x1b[1mOPTIONS\x1b[0m
  --group-by, -g <col>            Column to group by (summary)
  --metrics, -m <specs>           Aggregations: "col:fn,col:fn"
                                  Functions: sum, avg, min, max, count
  --columns, -c <cols>            Columns to include (comma-separated)
  --filter, -f <expr>             Filter: "col=val", "col>val", "col~pattern"
  --sort, -s <spec>               Sort: "col:asc" or "col:desc"
  --limit, -l <n>                 Max rows in output
  --format <fmt>                  Output format: table (default), csv, json, html
  --output, -o <path>             Write to file instead of stdout
  --title, -t <text>              Report title
  --no-header                     Omit header row (csv format)
  --help, -h                      Show this help
  --version, -v                   Show version

\x1b[1mEXAMPLES\x1b[0m
  reportgen summary sales.csv -g region -m "revenue:sum,units:avg"
  reportgen detail sales.csv -f "region=West" -s "revenue:desc" -l 20
  reportgen summary data.json -g category -m "price:avg" --format html -o report.html
`;

const OPTIONS = {
  'group-by': { type: 'string', short: 'g' },
  metrics:    { type: 'string', short: 'm' },
  columns:    { type: 'string', short: 'c' },
  filter:     { type: 'string', short: 'f', multiple: true },
  sort:       { type: 'string', short: 's' },
  limit:      { type: 'string', short: 'l' },
  format:     { type: 'string', default: 'table' },
  output:     { type: 'string', short: 'o' },
  title:      { type: 'string', short: 't' },
  'no-header': { type: 'boolean', default: false },
  help:       { type: 'boolean', short: 'h' },
  version:    { type: 'boolean', short: 'v' },
};

function parseMetrics(spec) {
  if (!spec) return [];
  return spec.split(',').map(s => {
    const [column, fn = 'sum'] = s.trim().split(':');
    return { column, fn };
  });
}

function parseSort(spec) {
  if (!spec) return null;
  const [column, direction = 'asc'] = spec.trim().split(':');
  return { column, direction };
}

function parseFilters(filters) {
  if (!filters || filters.length === 0) return [];

  const operators = [
    { symbol: '>=', fn: (a, b) => Number(a) >= Number(b) },
    { symbol: '<=', fn: (a, b) => Number(a) <= Number(b) },
    { symbol: '!=', fn: (a, b) => String(a) !== String(b) },
    { symbol: '~',  fn: (a, b) => new RegExp(b, 'i').test(String(a)) },
    { symbol: '>',  fn: (a, b) => Number(a) > Number(b) },
    { symbol: '<',  fn: (a, b) => Number(a) < Number(b) },
    { symbol: '=',  fn: (a, b) => String(a) === String(b) },
  ];

  return filters.map(expr => {
    for (const op of operators) {
      const idx = expr.indexOf(op.symbol);
      if (idx > 0) {
        return {
          column: expr.slice(0, idx).trim(),
          value: expr.slice(idx + op.symbol.length).trim(),
          test: op.fn,
        };
      }
    }
    throw new Error(`Invalid filter expression: "${expr}"`);
  });
}

export async function run(argv) {
  const { values, positionals } = parseArgs({
    args: argv,
    options: OPTIONS,
    allowPositionals: true,
    strict: false,
  });

  if (values.help || positionals.length === 0) {
    console.log(HELP);
    return;
  }

  if (values.version) {
    console.log('reportgen v1.0.0');
    return;
  }

  const [command, filePath] = positionals;

  if (!filePath) {
    throw new Error('Missing file path. Run with --help for usage.');
  }

  // Load data
  const rows = await loadFile(resolve(filePath));

  if (rows.length === 0) {
    console.log('No data found in file.');
    return;
  }

  const processor = new Processor(rows);

  // Route to command handler
  let result;

  switch (command) {
    case 'inspect':
      result = handleInspect(processor, rows);
      break;
    case 'summary':
      result = handleSummary(processor, values);
      break;
    case 'detail':
      result = handleDetail(processor, values);
      break;
    default:
      throw new Error(`Unknown command: "${command}". Use summary, detail, or inspect.`);
  }

  // Format output
  const formatName = values.format || 'table';
  const formatter = getFormatter(formatName);
  const title = values.title || `${command} report — ${filePath}`;
  const output = formatter.render(result, { title, noHeader: values['no-header'] });

  // Write to file or stdout
  if (values.output) {
    const { writeFile } = await import('node:fs/promises');
    await writeFile(resolve(values.output), output, 'utf-8');
    console.log(`Report written to ${values.output}`);
  } else {
    console.log(output);
  }
}

function handleInspect(processor, rows) {
  const columns = Object.keys(rows[0]);
  const types = {};

  for (const col of columns) {
    const sample = rows.find(r => r[col] != null && r[col] !== '')?.[col];
    types[col] = isNaN(Number(sample)) ? 'string' : 'number';
  }

  const schema = columns.map(col => ({
    column: col,
    type: types[col],
    unique: new Set(rows.map(r => r[col])).size,
    nulls: rows.filter(r => r[col] == null || r[col] === '').length,
  }));

  const sampleRows = rows.slice(0, 5);

  return {
    headers: ['column', 'type', 'unique', 'nulls'],
    rows: schema.map(s => [s.column, s.type, s.unique, s.nulls]),
    meta: { totalRows: rows.length, totalColumns: columns.length },
  };
}

function handleSummary(processor, values) {
  const groupBy = values['group-by'];
  if (!groupBy) {
    throw new Error('summary command requires --group-by');
  }

  const metrics = parseMetrics(values.metrics || '');
  if (metrics.length === 0) {
    throw new Error('summary command requires --metrics (e.g. "revenue:sum")');
  }

  const filters = parseFilters(values.filter);
  const sort = parseSort(values.sort);
  const limit = values.limit ? parseInt(values.limit, 10) : null;

  return processor
    .filter(filters)
    .groupBy(groupBy)
    .aggregate(metrics)
    .sort(sort)
    .limit(limit)
    .toResult();
}

function handleDetail(processor, values) {
  const filters = parseFilters(values.filter);
  const sort = parseSort(values.sort);
  const limit = values.limit ? parseInt(values.limit, 10) : null;
  const columns = values.columns
    ? values.columns.split(',').map(c => c.trim())
    : null;

  return processor
    .filter(filters)
    .select(columns)
    .sort(sort)
    .limit(limit)
    .toResult();
}
