## src/loader.js

```javascript
import { readFile } from 'node:fs/promises';
import { extname } from 'node:path';

/**
 * Load CSV or JSON files into an array of row objects.
 */
export async function loadFile(filePath) {
  const ext = extname(filePath).toLowerCase();
  const content = await readFile(filePath, 'utf-8');

  switch (ext) {
    case '.csv':
    case '.tsv':
      return parseCSV(content, ext === '.tsv' ? '\t' : ',');
    case '.json':
      return parseJSON(content);
    default:
      throw new Error(`Unsupported file type: ${ext}. Use .csv, .tsv, or .json`);
  }
}

function parseCSV(content, delimiter = ',') {
  const lines = content.trim().split('\n');
  if (lines.length < 2) return [];

  const headers = parseLine(lines[0], delimiter);
  const rows = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const values = parseLine(line, delimiter);
    const row = {};

    for (let j = 0; j < headers.length; j++) {
      const raw = values[j] ?? '';
      // Auto-detect numbers
      row[headers[j]] = raw !== '' && !isNaN(Number(raw)) ? Number(raw) : raw;
    }

    rows.push(row);
  }

  return rows;
}

function parseLine(line, delimiter) {
  const fields = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (inQuotes) {
      if (char === '"' && line[i + 1] === '"') {
        current += '"';
        i++; // skip escaped quote
      } else if (char === '"') {
        inQuotes = false;
      } else {
        current += char;
      }
    } else if (char === '"') {
      inQuotes = true;
    } else if (char === delimiter) {
      fields.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }

  fields.push(current.trim());
  return fields;
}

function parseJSON(content) {
  const data = JSON.parse(content);

  if (Array.isArray(data)) return data;

  // Support { "key": [...] } wrapper
  const keys = Object.keys(data);
  for (const key of keys) {
    if (Array.isArray(data[key])) return data[key];
  }

  throw new Error('JSON must be an array or contain an array property');
}
