```javascript
import { aggregate as runAggregate } from './aggregators.js';

/**
 * Chainable data processor. Each method returns `this` for fluent API.
 * Call `.toResult()` at the end to get { headers, rows, meta }.
 */
export class Processor {
  #rows;
  #groups = null;
  #headers = null;
  #resultRows = null;
  #meta = {};

  constructor(rows) {
    this.#rows = [...rows];
  }

  /** Apply filter conditions */
  filter(filters) {
    if (!filters || filters.length === 0) return this;

    this.#rows = this.#rows.filter(row =>
      filters.every(f => f.test(row[f.column], f.value))
    );

    this.#meta.filtered = true;
    this.#meta.rowsAfterFilter = this.#rows.length;
    return this;
  }

  /** Select specific columns */
  select(columns) {
    if (!columns) {
      this.#headers = Object.keys(this.#rows[0] || {});
    } else {
      // Validate columns exist
      const available = new Set(Object.keys(this.#rows[0] || {}));
      for (const col of columns) {
        if (!available.has(col)) {
          throw new Error(`Column "${col}" not found. Available: ${[...available].join(', ')}`);
        }
      }
      this.#headers = columns;
    }

    this.#resultRows = this.#rows.map(row =>
      this.#headers.map(h => row[h])
    );

    return this;
  }

  /** Group rows by a column value */
  groupBy(column) {
    const available = Object.keys(this.#rows[0] || {});
    if (!available.includes(column)) {
      throw new Error(`Column "${column}" not found. Available: ${available.join(', ')}`);
    }

    this.#groups = new Map();

    for (const row of this.#rows) {
      const key = String(row[column] ?? '(empty)');
      if (!this.#groups.has(key)) {
        this.#groups.set(key, []);
      }
      this.#groups.get(key).push(row);
    }

    this.#meta.groupColumn = column;
    this.#meta.groupCount = this.#groups.size;
    return this;
  }

  /** Run aggregation on groups */
  aggregate(metrics) {
    if (!this.#groups) {
      throw new Error('Must call groupBy() before aggregate()');
    }

    // Build headers: groupColumn, metric1_fn, metric2_fn, ...
    const groupCol = this.#meta.groupColumn;
    this.#headers = [groupCol];

    for (const m of metrics) {
      this.#headers.push(`${m.column}_${m.fn}`);
    }

    // Always add count
    const hasCount = metrics.some(m => m.fn === 'count');
    if (!hasCount) {
      this.#headers.push('count');
    }

    this.#resultRows = [];

    for (const [key, groupRows] of this.#groups) {
      const row = [key];

      for (const m of metrics) {
        const values = groupRows.map(r => r[m.column]);
        row.push(runAggregate(values, m.fn));
      }

      if (!hasCount) {
        row.push(groupRows.length);
      }

      this.#resultRows.push(row);
    }

    return this;
  }

  /** Sort result rows */
  sort(spec) {
    if (!spec || !this.#resultRows) return this;

    const colIndex = this.#headers.indexOf(spec.column);
    if (colIndex === -1) {
      throw new Error(
        `Sort column "${spec.column}" not found. Available: ${this.#headers.join(', ')}`
      );
    }

    const dir = spec.direction === 'desc' ? -1 : 1;

    this.#resultRows.sort((a, b) => {
      const va = a[colIndex];
      const vb = b[colIndex];

      if (typeof va === 'number' && typeof vb === 'number') {
        return (va - vb) * dir;
      }
      return String(va).localeCompare(String(vb)) * dir;
    });

    return this;
  }

  /** Limit output rows */
  limit(n) {
    if (n != null && this.#resultRows) {
      this.#resultRows = this.#resultRows.slice(0, n);
    }
    return this;
  }

  /** Produce final result object consumed by formatters */
  toResult() {
    // If no explicit select/aggregate was called, dump all columns
    if (!this.#headers) {
      this.select(null);
    }

    return {
      headers: this.#headers,
      rows: this.#resultRows,
      meta: {
        ...this.#meta,
        totalRows: this.#resultRows.length,
      },
    };
  }
}
