```javascript
/**
 * Run an aggregation function on an array of values.
 * Handles nulls and non-numeric values gracefully.
 */
export function aggregate(values, fn) {
  const nums = values
    .map(Number)
    .filter(n => !isNaN(n));

  switch (fn) {
    case 'sum':
      return round(nums.reduce((a, b) => a + b, 0));

    case 'avg':
      return nums.length === 0 ? 0 : round(nums.reduce((a, b) => a + b, 0) / nums.length);

    case 'min':
      return nums.length === 0 ? 0 : Math.min(...nums);

    case 'max':
      return nums.length === 0 ? 0 : Math.max(...nums);

    case 'count':
      return values.length;

    case 'distinct':
      return new Set(values).size;

    case 'median': {
      if (nums.length === 0) return 0;
      const sorted = [...nums].sort((a, b) => a - b);
      const mid = Math.floor(sorted.length / 2);
      return sorted.length % 2 === 0
        ? round((sorted[mid - 1] + sorted[mid]) / 2)
        : sorted[mid];
    }

    default:
      throw new Error(`Unknown aggregation: "${fn}". Use sum, avg, min, max, count, distinct, median`);
  }
}

function round(n) {
  return Math.round(n * 100) / 100;
}
