/// Thread-safe counters exposed for monitoring / health-checks.
#[derive(Debug, Clone)]
pub struct Metrics {
    inner: Arc<MetricsInner>,
}

#[derive(Debug)]
struct MetricsInner {
    lines_received: AtomicU64,
    entries_parsed: AtomicU64,
    entries_stored: AtomicU64,
    parse_errors: AtomicU64,
    validation_errors: AtomicU64,
    storage_errors: AtomicU64,
    batches_flushed: AtomicU64,
    bytes_received: AtomicU64,
}

impl Metrics {
    pub fn new() -> Self {
        Self {
            inner: Arc::new(MetricsInner {
                lines_received: AtomicU64::new(0),
                entries_parsed: AtomicU64::new(0),
                entries_stored: AtomicU64::new(0),
                parse_errors: AtomicU64::new(0),
                validation_errors: AtomicU64::new(0),
                storage_errors: AtomicU64::new(0),
                batches_flushed: AtomicU64::new(0),
                bytes_received: AtomicU64::new(0),
            }),
        }
    }

    pub fn inc_lines_received(&self) {
        self.inner.lines_received.fetch_add(1, Ordering::Relaxed);
    }
    pub fn inc_entries_parsed(&self) {
        self.inner.entries_parsed.fetch_add(1, Ordering::Relaxed);
    }
    pub fn add_entries_stored(&self, n: u64) {
        self.inner.entries_stored.fetch_add(n, Ordering::Relaxed);
    }
    pub fn inc_parse_errors(&self) {
        self.inner.parse_errors.fetch_add(1, Ordering::Relaxed);
    }
    pub fn inc_validation_errors(&self) {
        self.inner.validation_errors.fetch_add(1, Ordering::Relaxed);
    }
    pub fn inc_storage_errors(&self) {
        self.inner.storage_errors.fetch_add(1, Ordering::Relaxed);
    }
    pub fn inc_batches_flushed(&self) {
        self.inner.batches_flushed.fetch_add(1, Ordering::Relaxed);
    }
    pub fn add_bytes_received(&self, n: u64) {
        self.inner.bytes_received.fetch_add(n, Ordering::Relaxed);
    }

    pub fn snapshot(&self) -> MetricsSnapshot {
        MetricsSnapshot {
            lines_received: self.inner.lines_received.load(Ordering::Relaxed),
            entries_parsed: self.inner.entries_parsed.load(Ordering::Relaxed),
            entries_stored: self.inner.entries_stored.load(Ordering::Relaxed),
            parse_errors: self.inner.parse_errors.load(Ordering::Relaxed),
            validation_errors: self.inner.validation_errors.load(Ordering::Relaxed),
            storage_errors: self.inner.storage_errors.load(Ordering::Relaxed),
            batches_flushed: self.inner.batches_flushed.load(Ordering::Relaxed),
            bytes_received: self.inner.bytes_received.load(Ordering::Relaxed),
        }
    }
}

impl Default for Metrics {
    fn default() -> Self {
        Self::new()
    }
}

