## `src/parser.rs` — JSON Parsing & Validation

```rust
use chrono::Utc;
use uuid::Uuid;

use crate::config::PipelineConfig;
use crate::error::{IngestError, Result};
use crate::models::{LogEntry, LogLevel, RawLogEntry};

/// Parses a single JSON line into a validated `LogEntry`.
pub fn parse_line(line: &str, line_number: usize, config: &PipelineConfig) -> Result<LogEntry> {
    let raw: RawLogEntry =
        serde_json::from_str(line).map_err(|e| IngestError::Parse {
            line: line_number,
            source: e,
        })?;

    validate_and_normalize(raw, config)
}

/// Normalize a raw deserialized entry into the canonical form.
fn validate_and_normalize(raw: RawLogEntry, config: &PipelineConfig) -> Result<LogEntry> {
    // Resolve message from either `message` or `msg` field.
    let message = raw
        .message
        .or(raw.msg)
        .unwrap_or_default();

    if message.is_empty() {
        return Err(IngestError::Validation {
            field: "message".into(),
            reason: "log entry must contain a non-empty 'message' or 'msg' field".into(),
        });
    }

    if config.max_message_len > 0 && message.len() > config.max_message_len {
        return Err(IngestError::Validation {
            field: "message".into(),
            reason: format!(
                "message length {} exceeds maximum {}",
                message.len(),
                config.max_message_len
            ),
        });
    }

    let now = Utc::now();

    Ok(LogEntry {
        id: Uuid::new_v4(),
        timestamp: raw.timestamp.unwrap_or(now),
        ingested_at: now,
        level: raw.level.unwrap_or(LogLevel::Info),
        message,
        source: raw.source,
        service: raw.service,
        host: raw.host,
        trace_id: raw.trace_id,
        span_id: raw.span_id,
        metadata: raw.extra,
    })
}

