```typescript
import { LogEntry, LogLevel, LogQuery, LogStats } from "./types";

/**
 * In-memory log store with querying, pagination, and statistics.
 * Keeps entries sorted by timestamp (newest first).
 */
export class LogStore {
  private logs: LogEntry[] = [];
  private readonly maxSize: number;

  constructor(maxSize: number = 10_000) {
    if (maxSize <= 0) {
      throw new Error("maxSize must be a positive number");
    }
    this.maxSize = maxSize;
  }

  /** Numeric severity for level comparison */
  private static readonly SEVERITY: Record<LogLevel, number> = {
    [LogLevel.DEBUG]: 0,
    [LogLevel.INFO]: 1,
    [LogLevel.WARN]: 2,
    [LogLevel.ERROR]: 3,
    [LogLevel.FATAL]: 4,
  };

  // ── Mutations ──────────────────────────────────────────────

  /** Add a single entry (evicts oldest if at capacity) */
  add(entry: LogEntry): void {
    this.logs.push(entry);
    this.logs.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

    if (this.logs.length > this.maxSize) {
      this.logs = this.logs.slice(0, this.maxSize);
    }
  }

  /** Add many entries at once */
  addBatch(entries: LogEntry[]): void {
    entries.forEach((e) => this.logs.push(e));
    this.logs.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

    if (this.logs.length > this.maxSize) {
      this.logs = this.logs.slice(0, this.maxSize);
    }
  }

  /** Remove all stored entries */
  clear(): void {
    this.logs = [];
  }

  // ── Queries ────────────────────────────────────────────────

  /** Return entries matching optional criteria with pagination */
  query(criteria: LogQuery = {}): LogEntry[] {
    let results = [...this.logs];

    if (criteria.level) {
      const minSev = LogStore.SEVERITY[criteria.level];
      results = results.filter(
        (log) => LogStore.SEVERITY[log.level] >= minSev
      );
    }

    if (criteria.source) {
      const src = criteria.source.toLowerCase();
      results = results.filter((log) => log.source.toLowerCase() === src);
    }

    if (criteria.startDate) {
      results = results.filter(
        (log) => log.timestamp >= criteria.startDate!
      );
    }

    if (criteria.endDate) {
      results = results.filter(
        (log) => log.timestamp <= criteria.endDate!
      );
    }

    if (criteria.keyword) {
      const kw = criteria.keyword.toLowerCase();
      results = results.filter((log) =>
        log.message.toLowerCase().includes(kw)
      );
    }

    // Pagination
    const offset = criteria.offset ?? 0;
    const limit = criteria.limit ?? results.length;
    return results.slice(offset, offset + limit);
  }

  /** Find a single entry by id */
  findById(id: string): LogEntry | undefined {
    return this.logs.find((log) => log.id === id);
  }

  /** Total number of stored entries */
  get size(): number {
    return this.logs.length;
  }

  /** Aggregate statistics across all stored entries */
  getStats(): LogStats {
    const byLevel = Object.values(LogLevel).reduce(
      (acc, lvl) => ({ ...acc, [lvl]: 0 }),
      {} as Record<LogLevel, number>
    );

    const bySources: Record<string, number> = {};

    for (const log of this.logs) {
      byLevel[log.level]++;
      bySources[log.source] = (bySources[log.source] ?? 0) + 1;
    }

    return { total: this.logs.length, byLevel, bySources };
  }
}
