### `src/LogIngestionService.ts`
```typescript
import { LogStore } from "./LogStore";
import {
  LogEntry,
  LogInput,
  LogLevel,
  LogQuery,
  LogStats,
} from "./types";

/** Generates a simple unique id (good enough for demo purposes) */
function generateId(): string {
  return `log_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
}

/** Validate that a LogInput is well-formed */
function validate(input: LogInput): string[] {
  const errors: string[] = [];

  if (!input.message || input.message.trim().length === 0) {
    errors.push("message is required");
  }

  if (!input.source || input.source.trim().length === 0) {
    errors.push("source is required");
  }

  if (!Object.values(LogLevel).includes(input.level)) {
    errors.push(`invalid log level: ${input.level}`);
  }

  return errors;
}

export interface IngestionResult {
  success: boolean;
  id?: string;
  errors?: string[];
}

export interface BatchIngestionResult {
  successful: number;
  failed: number;
  results: IngestionResult[];
}

/**
 * Service layer that validates, transforms, and stores log entries.
 */
export class LogIngestionService {
  private readonly store: LogStore;
  private readonly listeners: Array<(entry: LogEntry) => void> = [];

  constructor(store?: LogStore) {
    this.store = store ?? new LogStore();
  }

  // ── Event hooks ────────────────────────────────────────────

  /** Register a callback invoked on every successful ingestion */
  onLog(callback: (entry: LogEntry) => void): void {
    this.listeners.push(callback);
  }

  private emit(entry: LogEntry): void {
    this.listeners.forEach((cb) => cb(entry));
  }

  // ── Ingestion ──────────────────────────────────────────────

  /** Ingest a single log */
  ingest(input: LogInput): IngestionResult {
    const errors = validate(input);
    if (errors.length > 0) {
      return { success: false, errors };
    }

    const entry: LogEntry = {
      id: generateId(),
      timestamp: input.timestamp ?? new Date(),
      level: input.level,
      message: input.message.trim(),
      source: input.source.trim(),
      metadata: input.metadata,
    };

    this.store.add(entry);
    this.emit(entry);

    return { success: true, id: entry.id };
  }

  /** Ingest many logs at once */
  ingestBatch(inputs: LogInput[]): BatchIngestionResult {
    const results = inputs.map((input) => this.ingest(input));

    return {
      successful: results.filter((r) => r.success).length,
      failed: results.filter((r) => !r.success).length,
      results,
    };
  }

  // ── Reads ──────────────────────────────────────────────────

  query(criteria?: LogQuery): LogEntry[] {
    return this.store.query(criteria);
  }

  findById(id: string): LogEntry | undefined {
    return this.store.findById(id);
  }

  getStats(): LogStats {
    return this.store.getStats();
  }

  get count(): number {
    return this.store.size;
  }

  clear(): void {
    this.store.clear();
  }
}
