```typescript
import { LogStore } from "../src/LogStore";
import { LogEntry, LogLevel } from "../src/types";

// ── Helpers ──────────────────────────────────────────────────

let counter = 0;
function makeEntry(overrides: Partial<LogEntry> = {}): LogEntry {
  counter++;
  return {
    id: overrides.id ?? `id-${counter}`,
    timestamp: overrides.timestamp ?? new Date(),
    level: overrides.level ?? LogLevel.INFO,
    message: overrides.message ?? `Test message ${counter}`,
    source: overrides.source ?? "test-source",
    metadata: overrides.metadata,
  };
}

// ── Tests ────────────────────────────────────────────────────

describe("LogStore", () => {
  let store: LogStore;

  beforeEach(() => {
    store = new LogStore();
    counter = 0;
  });

  // -- Construction ------------------------------------------------

  describe("constructor", () => {
    it("creates an empty store", () => {
      expect(store.size).toBe(0);
    });

    it("throws when maxSize is zero or negative", () => {
      expect(() => new LogStore(0)).toThrow("maxSize must be a positive number");
      expect(() => new LogStore(-5)).toThrow();
    });
  });

  // -- add / addBatch -----------------------------------------------

  describe("add", () => {
    it("stores an entry and increments size", () => {
      store.add(makeEntry());
      expect(store.size).toBe(1);
    });

    it("keeps entries sorted newest-first", () => {
      const older = makeEntry({ timestamp: new Date("2024-01-01") });
      const newer = makeEntry({ timestamp: new Date("2024-06-01") });

      store.add(older);
      store.add(newer);

      const results = store.query();
      expect(results[0].id).toBe(newer.id);
      expect(results[1].id).toBe(older.id);
    });

    it("evicts oldest entries when maxSize is exceeded", () => {
      const small = new LogStore(2);
      const e1 = makeEntry({ timestamp: new Date("2024-01-01") });
      const e2 = makeEntry({ timestamp: new Date("2024-02-01") });
      const e3 = makeEntry({ timestamp: new Date("2024-03-01") });

      small.add(e1);
      small.add(e2);
      small.add(e3);

      expect(small.size).toBe(2);
      expect(small.findById(e1.id)).toBeUndefined(); // oldest evicted
      expect(small.findById(e2.id)).toBeDefined();
      expect(small.findById(e3.id)).toBeDefined();
    });
  });

  describe("addBatch", () => {
    it("adds multiple entries at once", () => {
      store.addBatch([makeEntry(), makeEntry(), makeEntry()]);
      expect(store.size).toBe(3);
    });
  });

  // -- clear --------------------------------------------------------

  describe("clear", () => {
    it("removes all entries", () => {
      store.addBatch([makeEntry(), makeEntry()]);
      store.clear();
      expect(store.size).toBe(0);
    });
  });

  // -- findById -----------------------------------------------------

  describe("findById", () => {
    it("returns the matching entry", () => {
      const entry = makeEntry({ id: "abc-123" });
      store.add(entry);
      expect(store.findById("abc-123")).toEqual(entry);
    });

    it("returns undefined for unknown ids", () => {
      expect(store.findById("nope")).toBeUndefined();
    });
  });

  // -- query --------------------------------------------------------

  describe("query", () => {
    beforeEach(() => {
      store.addBatch([
        makeEntry({ level: LogLevel.DEBUG, source: "svc-a", message: "debug msg",   timestamp: new Date("2024-01-01") }),
        makeEntry({ level: LogLevel.INFO,  source: "svc-a", message: "info msg",    timestamp: new Date("2024-02-01") }),
        makeEntry({ level: LogLevel.WARN,  source: "svc-b", message: "warn msg",    timestamp: new Date("2024-03-01") }),
        makeEntry({ level: LogLevel.ERROR, source: "svc-b", message: "error msg",   timestamp: new Date("2024-04-01") }),
        makeEntry({ level: LogLevel.FATAL, source: "svc-a", message: "fatal crash", timestamp: new Date("2024-05-01") }),
      ]);
    });

    it("returns all entries when no criteria given", () => {
      expect(store.query()).toHaveLength(5);
    });

    it("filters by minimum level (inclusive)", () => {
      const errors = store.query({ level: LogLevel.ERROR });
      expect(errors).toHaveLength(2); // ERROR + FATAL
      errors.forEach((e) =>
        expect([LogLevel.ERROR, LogLevel.FATAL]).toContain(e.level)
      );
    });

    it("filters by source (case-insensitive)", () => {
      expect(store.query({ source: "SVC-A" })).toHaveLength(3);
      expect(store.query({ source: "svc-b" })).toHaveLength(2);
    });

    it("filters by date range", () => {
      const results = store.query({
        startDate: new Date("2024-02-01"),
        endDate: new Date("2024-04-01"),
      });
      expect(results).toHaveLength(3);
    });

    it("filters by keyword in message", () => {
      expect(store.query({ keyword: "crash" })).toHaveLength(1);
      expect(store.query({ keyword: "MSG" })).toHaveLength(4); // case-insensitive
    });

    it("supports pagination with limit and offset", () => {
      const page1 = store.query({ limit: 2, offset: 0 });
      const page2 = store.query({ limit: 2, offset: 2 });

      expect(page1).toHaveLength(2);
      expect(page2).toHaveLength(2);
      expect(page1[0].id).not.toBe(page2[0].id);
    });

    it("combines multiple filters", () => {
      const results = store.query({
        level: LogLevel.WARN,
        source: "svc-b",
      });
      expect(results).toHaveLength(2); // WARN + ERROR from svc-b
    });
  });

  // -- getStats -----------------------------------------------------

  describe("getStats", () => {
    it("returns correct totals and breakdowns", () => {
      store.addBatch([
        makeEntry({ level: LogLevel.INFO,  source: "a" }),
        makeEntry({ level: LogLevel.INFO,  source: "a" }),
        makeEntry({ level: LogLevel.ERROR, source: "b" }),
      ]);

      const stats = store.getStats();

      expect(stats.total).toBe(3);
      expect(stats.byLevel[LogLevel.INFO]).toBe(2);
      expect(stats.byLevel[LogLevel.ERROR]).toBe(1);
      expect(stats.byLevel[LogLevel.DEBUG]).toBe(0);

