            ));
        }

        // Schedule must be in the future
        if self.scheduled_at <= Utc::now() {
            return Err(ApiError::PastSchedule);
        }

        // Retry limit guard
        if let Some(retries) = self.max_retries {
            if retries > 10 {
                return Err(ApiError::Validation(
                    "Max retries cannot exceed 10".into(),
                ));
            }
        }

        Ok(())
    }
}

// ─── Handlers ──────────────────────────────────────────────────────

/// POST /tasks — Create a new scheduled task.
async fn create_task(
    data: web::Data<AppState>,
    body: web::Json<CreateTaskRequest>,
) -> Result<HttpResponse, ApiError> {
    body.validate()?;                             // FIX 8: validate input

    let now = Utc::now();
    let task = Task {
        id: Uuid::new_v4().to_string(),
        name: body.name.trim().to_string(),
        description: body.description.clone(),
        scheduled_at: body.scheduled_at,
        created_at: now,
        updated_at: now,
        status: TaskStatus::Pending,
        max_retries: body.max_retries.unwrap_or(3),
        retry_count: 0,
    };

    // FIX 9: RwLock won't panic; use write lock for mutation
    let mut tasks = data.tasks.write().await;
    let task_id = task.id.clone();
    tasks.insert(task_id.clone(), task.clone());

    info!("Created task: {} ({})", task.name, task_id);

    Ok(HttpResponse::Created().json(task))        // FIX 10: 201 Created
}

/// GET /tasks/{id} — Retrieve a single task.
async fn get_task(
    data: web::Data<AppState>,
    path: web::Path<String>,
) -> Result<HttpResponse, ApiError> {
    let task_id = path.into_inner();
    let tasks = data.tasks.read().await;          // read lock for GET

    // FIX 11: proper 404 with structured error
    tasks
        .get(&task_id)
        .map(|task| HttpResponse::Ok().json(task))
        .ok_or_else(|| ApiError::NotFound(format!("Task '{task_id}' not found")))
}

/// GET /tasks — List all tasks (with optional status filter).
async fn list_tasks(
    data: web::Data<AppState>,
    query: web::Query<HashMap<String, String>>,
) -> Result<HttpResponse, ApiError> {
    let tasks = data.tasks.read().await;

    let filtered: Vec<Task> = tasks
        .values()
        .filter(|t| {
            if let Some(status_filter) = query.get("status") {
                let status_str = serde_json::to_string(&t.status)
                    .unwrap_or_default()
                    .trim_matches('"')
                    .to_string();
                status_str == *status_filter
            } else {
                true
            }
        })
        .cloned()
        .collect();

    let total = filtered.len();
    Ok(HttpResponse::Ok().json(TaskListResponse {
        tasks: filtered,
        total,
    }))
}

/// PUT /tasks/{id} — Update an existing task.
async fn update_task(
    data: web::Data<AppState>,
    path: web::Path<String>,
    body: web::Json<UpdateTaskRequest>,
) -> Result<HttpResponse, ApiError> {
    let task_id = path.into_inner();
    let mut tasks = data.tasks.write().await;     // write lock for mutation

    let task = tasks
        .get_mut(&task_id)
        .ok_or_else(|| ApiError::NotFound(format!("Task '{task_id}' not found")))?;

    // Only update provided fields
    if let Some(ref name) = body.name {
        let trimmed = name.trim();
        if trimmed.is_empty() {
            return Err(ApiError::Validation("Name cannot be empty".into()));
        }
        task.name = trimmed.to_string();
    }
    if let Some(ref desc) = body.description {
        task.description = Some(desc.clone());
    }
    if let Some(scheduled_at) = body.scheduled_at {
        if scheduled_at <= Utc::now() {
            return Err(ApiError::PastSchedule);
        }
        task.scheduled_at = scheduled_at;
    }
    if let Some(ref status) = body.status {
        task.status = status.clone();
    }

    task.updated_at = Utc::now();

    info!("Updated task: {}", task_id);
    Ok(HttpResponse::Ok().json(task.clone()))
}

/// DELETE /tasks/{id} — Remove a task.
async fn delete_task(
    data: web::Data<AppState>,
    path: web::Path<String>,
) -> Result<HttpResponse, ApiError> {
    let task_id = path.into_inner();
    let mut tasks = data.tasks.write().await;     // FIX 12: mutable write lock

    tasks
        .remove(&task_id)
        .map(|removed| {
            info!("Deleted task: {} ({})", removed.name, task_id);
            HttpResponse::NoContent().finish()    // 204 No Content
        })
        .ok_or_else(|| ApiError::NotFound(format!("Task '{task_id}' not found")))
}

/// POST /tasks/{id}/cancel — Cancel a pending task.
async fn cancel_task(
    data: web::Data<AppState>,
    path: web::Path<String>,
) -> Result<HttpResponse, ApiError> {
    let task_id = path.into_inner();
    let mut tasks = data.tasks.write().await;

    let task = tasks
        .get_mut(&task_id)
        .ok_or_else(|| ApiError::NotFound(format!("Task '{task_id}' not found")))?;

    match task.status {
        TaskStatus::Pending => {
            task.status = TaskStatus::Cancelled;
            task.updated_at = Utc::now();
            info!("Cancelled task: {}", task_id);
            Ok(HttpResponse::Ok().json(task.clone()))
        }
        _ => Err(ApiError::Validation(format!(
            "Cannot cancel task in {:?} state",
            task.status
        ))),
    }
}

// ─── Background Scheduler ──────────────────────────────────────────

/// Periodically checks for tasks that are due and marks them as running.
async fn task_scheduler_loop(state: AppState) {
    let mut interval = tokio::time::interval(
        tokio::time::Duration::from_secs(5),
    );

    loop {
        interval.tick().await;
        let now = Utc::now();

        let mut tasks = state.tasks.write().await;
        for task in tasks.values_mut() {
            if task.status == TaskStatus::Pending && task.scheduled_at <= now {
                info!("Dispatching task: {} ({})", task.name, task.id);
                task.status = TaskStatus::Running;
                task.updated_at = now;

                // In production: spawn actual work here and update to
                // Completed/Failed on finish.
            }
        }
    }
}

// ─── Health Check ──────────────────────────────────────────────────

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({
        "status": "healthy",
        "timestamp": Utc::now().to_rfc3339(),
    }))
}

// ─── Server Startup ────────────────────────────────────────────────

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    info!("Starting task scheduler API on 127.0.0.1:8080");

    // FIX: Create state *before* the closure, wrap in web::Data for sharing
    let state = AppState::new();

    // Spawn the background scheduler
    let scheduler_state = state.clone();
    tokio::spawn(async move {
        task_scheduler_loop(scheduler_state).await;
    });

    let shared_data = web::Data::new(state);

    HttpServer::new(move || {
        App::new()
            .app_data(shared_data.clone())        // clone Data, not raw state
            .wrap(middleware::Logger::default())
            .route("/health",          web::get().to(health_check))
            .route("/tasks",           web::get().to(list_tasks))
            .route("/tasks",           web::post().to(create_task))
            .route("/tasks/{id}",      web::get().to(get_task))
            .route("/tasks/{id}",      web::put().to(update_task))
            .route("/tasks/{id}",      web::delete().to(delete_task))
            .route("/tasks/{id}/cancel", web::post().to(cancel_task))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
