```ts
import { LogEntry, LogLevel, LogQuery, LogQueryResult, StorageStats } from "../types";
import { LogStorage } from "./storage.interface";

interface IndexEntry {
  id: string;
  timestamp: number;
}

export class MemoryStorage implements LogStorage {
  private entries: Map<string, LogEntry> = new Map();
  private timeIndex: IndexEntry[] = []; // sorted by timestamp
  private sourceIndex: Map<string, Set<string>> = new Map();
  private levelIndex: Map<LogLevel, Set<string>> = new Map();
  private tagIndex: Map<string, Set<string>> = new Map();
  private traceIndex: Map<string, Set<string>> = new Map();
  private readonly maxEntries: number;

  constructor(maxEntries = 1_000_000) {
    this.maxEntries = maxEntries;
  }

  async store(entry: LogEntry): Promise<void> {
    this.addEntry(entry);
    this.evictIfNeeded();
  }

  async storeBatch(entries: LogEntry[]): Promise<void> {
    for (const entry of entries) {
      this.addEntry(entry);
    }
    this.evictIfNeeded();
  }

  async query(query: LogQuery): Promise<LogQueryResult> {
    const start = performance.now();
    const limit = query.limit ?? 100;
    const offset = query.offset ?? 0;
    const sortOrder = query.sortOrder ?? "desc";

    // Start with candidate IDs from the most selective index
    let candidateIds: Set<string> | null = null;

    // Filter by trace ID (very selective)
    if (query.traceId) {
      candidateIds = this.intersect(
        candidateIds,
        this.traceIndex.get(query.traceId) ?? new Set()
      );
    }

    // Filter by levels
    if (query.levels?.length) {
      const levelIds = new Set<string>();
      for (const level of query.levels) {
        const ids = this.levelIndex.get(level);
        if (ids) ids.forEach((id) => levelIds.add(id));
      }
      candidateIds = this.intersect(candidateIds, levelIds);
    }

    // Filter by sources
    if (query.sources?.length) {
      const sourceIds = new Set<string>();
      for (const source of query.sources) {
        const ids = this.sourceIndex.get(source);
        if (ids) ids.forEach((id) => sourceIds.add(id));
      }
      candidateIds = this.intersect(candidateIds, sourceIds);
    }

    // Filter by tags
    if (query.tags?.length) {
      for (const tag of query.tags) {
        candidateIds = this.intersect(
          candidateIds,
          this.tagIndex.get(tag) ?? new Set()
        );
      }
    }

    // If no index-based filtering, use all IDs
    if (candidateIds === null) {
      candidateIds = new Set(this.entries.keys());
    }

    // Retrieve entries and apply remaining filters
    let results: LogEntry[] = [];
    for (const id of candidateIds) {
      const entry = this.entries.get(id);
      if (!entry) continue;
      if (!this.matchesTimeRange(entry, query)) continue;
      if (!this.matchesSearch(entry, query)) continue;
      if (!this.matchesMetadata(entry, query)) continue;
      results.push(entry);
    }

    // Sort
    results.sort((a, b) => {
      const diff = a.timestamp.getTime() - b.timestamp.getTime();
      return sortOrder === "asc" ? diff : -diff;
    });

    const total = results.length;
    const paged = results.slice(offset, offset + limit);

    return {
      entries: paged,
      total,
      hasMore: offset + limit < total,
      query,
      durationMs: performance.now() - start,
    };
  }

  async getById(id: string): Promise<LogEntry | null> {
    return this.entries.get(id) ?? null;
  }

