use std::sync::Arc;
use tracing::{debug, instrument};

use crate::error::{PipelineError, PipelineResult};
use crate::record::{Record, RecordBatch, Value};

// ---------------------------------------------------------------------------
// Stage traits
// ---------------------------------------------------------------------------

/// A synchronous transformation applied to each record.
pub trait Transform: Send + Sync + std::fmt::Debug {
    fn name(&self) -> &str;
    fn transform(&self, record: Record) -> PipelineResult<Record>;
}

/// A predicate that decides whether a record passes through.
pub trait Filter: Send + Sync + std::fmt::Debug {
    fn name(&self) -> &str;
    fn keep(&self, record: &Record) -> PipelineResult<bool>;
}

/// A fan-out stage: one record can become zero or more records.
pub trait FlatMap: Send + Sync + std::fmt::Debug {
    fn name(&self) -> &str;
    fn flat_map(&self, record: Record) -> PipelineResult<Vec<Record>>;
}

// ---------------------------------------------------------------------------
// Built-in transforms
// ---------------------------------------------------------------------------

/// Renames a field.
#[derive(Debug, Clone)]
pub struct RenameField {
    pub from: String,
    pub to: String,
}

impl RenameField {
    pub fn new(from: impl Into<String>, to: impl Into<String>) -> Self {
        Self {
            from: from.into(),
            to: to.into(),
        }
    }
}

impl Transform for RenameField {
    fn name(&self) -> &str {
        "rename_field"
    }

    #[instrument(skip(self, record), fields(from = %self.from, to = %self.to))]
    fn transform(&self, mut record: Record) -> PipelineResult<Record> {
        if let Some(val) = record.remove_field(&self.from) {
            record.set_field(self.to.clone(), val);
        }
        Ok(record)
    }
}

/// Adds a computed field using a closure.
#[derive(Clone)]
pub struct ComputeField {
    pub field_name: String,
    compute_fn: Arc<dyn Fn(&Record) -> PipelineResult<Value> + Send + Sync>,
}

impl std::fmt::Debug for ComputeField {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ComputeField")
            .field("field_name", &self.field_name)
            .finish()
    }
}

impl ComputeField {
    pub fn new<F>(field_name: impl Into<String>, f: F) -> Self
    where
        F: Fn(&Record) -> PipelineResult<Value> + Send + Sync + 'static,
    {
        Self {
            field_name: field_name.into(),
            compute_fn: Arc::new(f),
        }
    }
}

impl Transform for ComputeField {
    fn name(&self) -> &str {
        "compute_field"
    }

    fn transform(&self, mut record: Record) -> PipelineResult<Record> {
        let value = (self.compute_fn)(&record)?;
        record.set_field(self.field_name.clone(), value);
        Ok(record)
    }
}

/// Drops specified fields from the record.
#[derive(Debug, Clone)]
pub struct DropFields {
    pub fields: Vec<String>,
}

impl DropFields {
    pub fn new(fields: Vec<impl Into<String>>) -> Self {
        Self {
            fields: fields.into_iter().map(Into::into).collect(),
        }
    }
}

impl Transform for DropFields {
    fn name(&self) -> &str {
        "drop_fields"
    }

    fn transform(&self, mut record: Record) -> PipelineResult<Record> {
        for f in &self.fields {
            record.remove_field(f);
        }
        Ok(record)
    }
}

/// Casts a field to a target type.
#[derive(Debug, Clone)]
pub struct CastField {
    pub field: String,
    pub target: CastTarget,
}

#[derive(Debug, Clone, Copy)]
pub enum CastTarget {
    Int,
    Float,
    String,
    Bool,
}

impl CastField {
    pub fn new(field: impl Into<String>, target: CastTarget) -> Self {
        Self {
            field: field.into(),
            target,
        }
    }
}

impl Transform for CastField {
    fn name(&self) -> &str {
        "cast_field"
    }

    fn transform(&self, mut record: Record) -> PipelineResult<Record> {
        if let Some(val) = record.get_field(&self.field).cloned() {
            let casted = match self.target {
                CastTarget::Int => {
                    let v = val.to_f64().map_err(|_| PipelineError::Transform {
                        stage: self.name().into(),
                        message: format!("Cannot cast {:?} to int", val),
                    })?;
                    Value::Int(v as i64)
                }
                CastTarget::Float => {
                    let v = val.to_f64().map_err(|_| PipelineError::Transform {
                        stage: self.name().into(),
                        message: format!("Cannot cast {:?} to float", val),
                    })?;
                    Value::Float(v)
                }
                CastTarget::String => Value::String(val.to_string()),
                CastTarget::Bool => match &val {
                    Value::Bool(b) => Value::Bool(*b),
                    Value::Int(i) => Value::Bool(*i != 0),
                    Value::String(s) => Value::Bool(!s.is_empty()),
                    _ => Value::Bool(false),
                },
            };
            record.set_field(self.field.clone(), casted);
        }
        Ok(record)
    }
}

