```typescript
// src/reader.ts

import { readFileSync } from "fs";
import { extname } from "path";
import type { Row, CellValue } from "./types.js";

export function readData(filePath: string): Row[] {
  const ext = extname(filePath).toLowerCase();
  const content = readFileSync(filePath, "utf-8");

  switch (ext) {
    case ".csv":
      return parseCSV(content, ",");
    case ".tsv":
      return parseCSV(content, "\t");
    case ".json":
      return parseJSON(content);
    default:
      throw new Error(`Unsupported file type: ${ext}. Use .csv, .tsv, or .json`);
  }
}

// --- CSV parsing (handles quoted fields, embedded commas, newlines) ---

function parseCSV(content: string, delimiter: string): Row[] {
  const rows = splitCSVRows(content, delimiter);
  if (rows.length < 2) return [];

  const headers = rows[0].map((h) => h.trim());
  const dupes = headers.filter((h, i) => headers.indexOf(h) !== i);
  if (dupes.length > 0) {
    throw new Error(`Duplicate column headers: ${[...new Set(dupes)].join(", ")}`);
  }

  return rows.slice(1).map((fields) => {
    const row: Row = {};
    headers.forEach((header, i) => {
      row[header] = coerce(fields[i] ?? "");
    });
    return row;
  });
}

function splitCSVRows(content: string, delimiter: string): string[][] {
  const rows: string[][] = [];
  let current: string[] = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < content.length; i++) {
    const ch = content[i];
    const next = content[i + 1];

    if (inQuotes) {
      if (ch === '"' && next === '"') {
        field += '"';
        i++; // skip escaped quote
      } else if (ch === '"') {
        inQuotes = false;
      } else {
        field += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === delimiter) {
        current.push(field);
        field = "";
      } else if (ch === "\n" || (ch === "\r" && next === "\n")) {
        current.push(field);
        field = "";
        if (current.some((f) => f.trim() !== "")) rows.push(current);
        current = [];
        if (ch === "\r") i++; // skip \r\n
      } else {
        field += ch;
      }
    }
  }

  // flush last row
  current.push(field);
  if (current.some((f) => f.trim() !== "")) rows.push(current);

  return rows;
}

// --- JSON parsing ---

function parseJSON(content: string): Row[] {
  const parsed = JSON.parse(content);
  const arr = Array.isArray(parsed) ? parsed : [parsed];

  return arr.map((item, idx) => {
    if (typeof item !== "object" || item === null) {
      throw new Error(`JSON item at index ${idx} is not an object`);
    }
    const row: Row = {};
    for (const [key, val] of Object.entries(item)) {
      row[key] = coerceJSON(val);
    }
    return row;
  });
}

// --- Type coercion ---

function coerce(raw: string): CellValue {
  const s = raw.trim();
  if (s === "" || s.toLowerCase() === "null" || s.toLowerCase() === "n/a") return null;
  if (s.toLowerCase() === "true") return true;
  if (s.toLowerCase() === "false") return false;

  const num = Number(s);
  if (!isNaN(num) && s !== "") return num;

  return s;
}

function coerceJSON(val: unknown): CellValue {
  if (val === null || val === undefined) return null;
  if (typeof val === "string" || typeof val === "number" || typeof val === "boolean") return val;
  return JSON.stringify(val); // nested objects → string
}
