// src/pipeline.ts

import type { Row, CellValue, FilterDef, AggDef, SortOrder, Summary, ColumnStats } from "./types.js";

// --- Filtering ---

export function applyFilters(data: Row[], filters: FilterDef[]): Row[] {
  return data.filter((row) =>
    filters.every((f) => {
      const val = row[f.column];
      if (val == null) return f.op === "neq"; // null != anything is true

      const strVal = String(val);
      const numVal = Number(val);
      const numTarget = Number(f.value);

      switch (f.op) {
        case "eq":
          return strVal === f.value;
        case "neq":
          return strVal !== f.value;
        case "gt":
          return numVal > numTarget;
        case "lt":
          return numVal < numTarget;
        case "gte":
          return numVal >= numTarget;
        case "lte":
          return numVal <= numTarget;
        case "contains":
          return strVal.toLowerCase().includes(f.value.toLowerCase());
      }
    })
  );
}

// --- Sorting ---

export function sortRows(data: Row[], column: string, order: SortOrder): Row[] {
  return [...data].sort((a, b) => {
    const va = a[column];
    const vb = b[column];

    if (va == null && vb == null) return 0;
    if (va == null) return 1;
    if (vb == null) return -1;

    let cmp: number;
    if (typeof va === "number" && typeof vb === "number") {
      cmp = va - vb;
    } else {
      cmp = String(va).localeCompare(String(vb));
    }

    return order === "desc" ? -cmp : cmp;
  });
}

// --- Grouping + Aggregation ---

export function groupAndAggregate(data: Row[], groupBy: string, aggs: AggDef[]): Row[] {
  // Validate columns exist
  if (data.length > 0 && !(groupBy in data[0])) {
    throw new Error(`Group-by column "${groupBy}" not found. Available: ${Object.keys(data[0]).join(", ")}`);
  }

  const groups = new Map<string, Row[]>();
  for (const row of data) {
    const key = String(row[groupBy] ?? "(null)");
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(row);
  }

  const result: Row[] = [];

  for (const [key, rows] of groups) {
    const newRow: Row = { [groupBy]: coerceGroupKey(key, rows[0][groupBy]) };

    for (const agg of aggs) {
      const alias = `${agg.fn}_${agg.column}`;

      if (agg.fn === "count") {
        newRow[alias] =
          agg.column === "*" ? rows.length : rows.filter((r) => r[agg.column] != null).length;
        continue;
      }

      const nums = rows.map((r) => r[agg.column]).filter((v): v is number => typeof v === "number");

      switch (agg.fn) {
        case "sum":
          newRow[alias] = round(nums.reduce((a, b) => a + b, 0));
          break;
        case "avg":
          newRow[alias] = nums.length ? round(nums.reduce((a, b) => a + b, 0) / nums.length) : null;
          break;
        case "min":
          newRow[alias] = nums.length ? Math.min(...nums) : null;
          break;
        case "max":
          newRow[alias] = nums.length ? Math.max(...nums) : null;
          break;
      }
    }

    result.push(newRow);
  }

  return result;
}

function coerceGroupKey(key: string, sample: CellValue): CellValue {
  if (key === "(null)") return null;
  if (typeof sample === "number") return Number(key);
  if (typeof sample === "boolean") return key === "true";
  return key;
}

// --- Column selection & limit ---

export function selectColumns(data: Row[], columns: string[]): Row[] {
  return data.map((row) => {
    const out: Row = {};
    for (const col of columns) {
      out[col] = col in row ? row[col] : null;
    }
    return out;
  });
}

export function limitRows(data: Row[], limit: number): Row[] {
  return data.slice(0, limit);
}

// --- Summary statistics ---

export function computeSummary(data: Row[]): Summary {
  if (data.length === 0) return { totalRows: 0, columns: {} };

  const colNames = Object.keys(data[0]);
  const columns: Record<string, ColumnStats> = {};

  for (const col of colNames) {
    const values = data.map((r) => r[col]);
    const nonNull = values.filter((v) => v != null);
    const unique = new Set(nonNull.map(String)).size;
    const nums = values.filter((v): v is number => typeof v === "number");

    if (nums.length > data.length * 0.5) {
      // majority numeric → treat as number column
      columns[col] = {
        type: "number",
        nonNull: nonNull.length,
        unique,
        min: Math.min(...nums),
        max: Math.max(...nums),
        avg: round(nums.reduce((a, b) => a + b, 0) / nums.length),
        sum: round(nums.reduce((a, b) => a + b, 0)),
      };
    } else {
      columns[col] = { type: "string", nonNull: nonNull.length, unique };
    }
  }

  return { totalRows: data.length, columns };
}

function round(n: number, decimals = 2): number {
  const factor = 10 ** decimals;
  return Math.round(n * factor) / factor;
}
