function str(val: CellValue): string {
  if (val == null) return "";
  return String(val);
}

function getColumns(data: Row[]): string[] {
  return data.length > 0 ? Object.keys(data[0]) : [];
}

function isNumericColumn(data: Row[], col: string): boolean {
  return data.some((r) => typeof r[col] === "number");
}

// ─── Table (Unicode box-drawing) ───

function formatTable(data: Row[], title?: string, summary?: Summary): string {
  if (data.length === 0) return "  (no data)\n";

  const cols = getColumns(data);
  const numeric = Object.fromEntries(cols.map((c) => [c, isNumericColumn(data, c)]));

  // column widths
  const widths: Record<string, number> = {};
  for (const c of cols) widths[c] = c.length;
  for (const row of data) {
    for (const c of cols) widths[c] = Math.max(widths[c], str(row[c]).length);
  }

  const pad = (val: string, col: string) =>
    numeric[col] ? val.padStart(widths[col]) : val.padEnd(widths[col]);

  const border = (left: string, mid: string, right: string) =>
    left + cols.map((c) => "─".repeat(widths[c] + 2)).join(mid) + right;

  const rowStr = (row: Row) =>
    "│" + cols.map((c) => ` ${pad(str(row[c]), c)} `).join("│") + "│";

  const lines: string[] = [];

  if (title) {
    lines.push("");
    lines.push(`  ${title}`);
    lines.push(`  ${"─".repeat(title.length)}`);
  }

  lines.push(border("┌", "┬", "┐"));
  lines.push("│" + cols.map((c) => ` ${c.padEnd(widths[c])} `).join("│") + "│");
  lines.push(border("├", "┼", "┤"));
  for (const row of data) lines.push(rowStr(row));
  lines.push(border("└", "┴", "┘"));
  lines.push(`  ${data.length} row${data.length === 1 ? "" : "s"}`);

  if (summary) lines.push("", ...formatSummaryText(summary));

  return lines.join("\n") + "\n";
}

function formatSummaryText(s: Summary): string[] {
  const lines = [`  Summary (${s.totalRows} rows):`];
  for (const [col, stats] of Object.entries(s.columns)) {
    if (stats.type === "number") {
      lines.push(
        `    ${col}: min=${stats.min}  max=${stats.max}  avg=${stats.avg}  sum=${stats.sum}  (${stats.unique} unique)`
      );
    } else {
      lines.push(`    ${col}: ${stats.nonNull} non-null, ${stats.unique} unique values`);
    }
  }
  return lines;
}

// ─── CSV ───

function formatCSV(data: Row[]): string {
  if (data.length === 0) return "";
  const cols = getColumns(data);

  const escape = (val: string) => {
    if (val.includes(",") || val.includes('"') || val.includes("\n")) {
      return `"${val.replace(/"/g, '""')}"`;
