```javascript
// Defines the shape of v1 events and provides validation
const v1Schema = {
  version: 1,

  // Required fields in v1 events
  requiredFields: ['id', 'type', 'timestamp', 'data'],

  // Validate a v1 event object
  validate(event) {
    const errors = [];

    for (const field of this.requiredFields) {
      if (event[field] === undefined || event[field] === null) {
        errors.push(`Missing required field: "${field}"`);
      }
    }

    if (event.type && typeof event.type !== 'string') {
      errors.push(`"type" must be a string, got ${typeof event.type}`);
    }

    if (event.timestamp && !(event.timestamp instanceof Date) && isNaN(Date.parse(event.timestamp))) {
      errors.push(`"timestamp" must be a valid date, got "${event.timestamp}"`);
    }

    if (event.data && typeof event.data !== 'object') {
      errors.push(`"data" must be an object, got ${typeof event.data}`);
    }

    return { valid: errors.length === 0, errors };
  },

  // Example v1 event structure for documentation
  example: {
    id: 'evt_001',
    type: 'user.created',
    timestamp: '2024-01-15T10:30:00Z',
    data: { userId: 'u_123', email: 'user@example.com' },
    metadata: { source: 'api' }
  }
};

module.exports = v1Schema;
