### `src/schemas/v2.js` — New Event Schema

```javascript
// Defines the shape of v2 events — richer structure with namespacing,
// correlation tracking, and stricter typing
const v2Schema = {
  version: 2,

  requiredFields: [
    'eventId',
    'eventType',
    'eventSource',
    'occurredAt',
    'payload',
    'schemaVersion'
  ],

  validate(event) {
    const errors = [];

    for (const field of this.requiredFields) {
      if (event[field] === undefined || event[field] === null) {
        errors.push(`Missing required field: "${field}"`);
      }
    }

    // eventType must follow "domain.action" pattern
    if (event.eventType && !/^[a-z]+\.[a-z_.]+$/.test(event.eventType)) {
      errors.push(
        `"eventType" must match pattern "domain.action", got "${event.eventType}"`
      );
    }

    if (event.occurredAt && isNaN(Date.parse(event.occurredAt))) {
      errors.push(`"occurredAt" must be ISO-8601, got "${event.occurredAt}"`);
    }

    if (event.schemaVersion !== 2) {
      errors.push(`"schemaVersion" must be 2, got ${event.schemaVersion}`);
    }

    if (event.payload && typeof event.payload !== 'object') {
      errors.push(`"payload" must be an object, got ${typeof event.payload}`);
    }

    return { valid: errors.length === 0, errors };
  },

  example: {
    eventId: 'evt_001',
    eventType: 'user.created',
    eventSource: 'api-gateway',
    occurredAt: '2024-01-15T10:30:00.000Z',
    payload: { userId: 'u_123', email: 'user@example.com' },
    correlationId: null,
    causationId: null,
    schemaVersion: 2,
    meta: { migratedFrom: 'v1', migratedAt: '2024-06-01T00:00:00.000Z' }
  }
};

module.exports = v2Schema;
