### `src/EventTransformer.js` — Schema Mapping Logic

```javascript
const { randomUUID } = require('node:crypto');
const v1Schema = require('./schemas/v1');
const v2Schema = require('./schemas/v2');

/**
 * Transforms events from one schema version to another.
 *
 * Each "migration" is a registered function keyed by "fromVersion -> toVersion".
 * Custom field mappings can be injected at construction time.
 */
class EventTransformer {
  constructor(options = {}) {
    // Optional overrides callers can pass in per event-type
    this.fieldMappings = options.fieldMappings || {};

    // Default source when the v1 event has none
    this.defaultSource = options.defaultSource || 'legacy-system';

    // Registry: key = "from->to", value = transform function
    this.migrations = new Map();

    // Register built-in migrations
    this.#registerBuiltInMigrations();
  }

  // ── public API ──────────────────────────────────────────────

  /** Transform a single event from `fromVersion` to `toVersion`. */
  transform(event, fromVersion, toVersion) {
    const key = `${fromVersion}->${toVersion}`;
    const migrateFn = this.migrations.get(key);

    if (!migrateFn) {
      throw new Error(
        `No migration registered for ${key}. ` +
        `Available: ${[...this.migrations.keys()].join(', ') || 'none'}`
      );
    }

    // 1. Validate source event
    const sourceSchema = this.#getSchema(fromVersion);
    const sourceCheck = sourceSchema.validate(event);
    if (!sourceCheck.valid) {
      throw new Error(
        `Source event (v${fromVersion}) is invalid:\n  • ${sourceCheck.errors.join('\n  • ')}`
      );
    }

    // 2. Run transform
    const transformed = migrateFn(event);

    // 3. Validate result
    const targetSchema = this.#getSchema(toVersion);
    const targetCheck = targetSchema.validate(transformed);
    if (!targetCheck.valid) {
      throw new Error(
        `Transformed event (v${toVersion}) is invalid:\n  • ${targetCheck.errors.join('\n  • ')}`
      );
    }

    return transformed;
  }

  /** Register a custom migration function. */
  registerMigration(fromVersion, toVersion, migrateFn) {
    const key = `${fromVersion}->${toVersion}`;
    this.migrations.set(key, migrateFn);
  }

  /** List every registered migration path. */
  getAvailableMigrations() {
    return [...this.migrations.keys()];
  }

  // ── private helpers ─────────────────────────────────────────

  #registerBuiltInMigrations() {
    // v1 → v2
    this.migrations.set('1->2', (event) => this.#migrateV1ToV2(event));

    // v2 → v1 (rollback / downgrade)
    this.migrations.set('2->1', (event) => this.#migrateV2ToV1(event));
  }

  #migrateV1ToV2(v1Event) {
    const customMapping = this.fieldMappings[v1Event.type] || {};

    return {
      eventId:        v1Event.id,
      eventType:      customMapping.eventType || v1Event.type,
      eventSource:    v1Event.metadata?.source || this.defaultSource,
      occurredAt:     new Date(v1Event.timestamp).toISOString(),
      payload:        { ...v1Event.data, ...customMapping.extraPayload },
      correlationId:  v1Event.metadata?.correlationId || null,
      causationId:    v1Event.metadata?.causationId   || null,
      schemaVersion:  2,
      meta: {
        migratedFrom: 'v1',
        migratedAt:   new Date().toISOString(),
        originalEvent: v1Event        // keep full original for audit
      }
    };
  }

  #migrateV2ToV1(v2Event) {
    return {
      id:        v2Event.eventId,
      type:      v2Event.eventType,
      timestamp: v2Event.occurredAt,
      data:      { ...v2Event.payload },
      metadata: {
        source:        v2Event.eventSource,
        correlationId: v2Event.correlationId,
        causationId:   v2Event.causationId
      }
    };
  }

  #getSchema(version) {
    const schemas = { 1: v1Schema, 2: v2Schema };
    const schema = schemas[version];
    if (!schema) throw new Error(`Unknown schema version: ${version}`);
    return schema;
  }
}

module.exports = EventTransformer;
```

### `src/BatchProcessor.js` — Batch + Retry Engine

```javascript
const { EventEmitter } = require('node:events');

/**
 * Processes arrays of events in configurable batches.
 *
 * Emits progress / error events so callers can observe without polling.
 * Supports per-event retries with exponential back-off.
 */
class BatchProcessor extends EventEmitter {
  constructor(options = {}) {
    super();
    this.batchSize    = options.batchSize    || 100;
    this.maxRetries   = options.maxRetries   || 3;
    this.retryDelayMs = options.retryDelayMs || 1000;   // base delay
    this.concurrency  = options.concurrency  || 3;      // parallel batches
  }

  // ── public API ──────────────────────────────────────────────

  /**
   * Process every item through `processFn` in batches.
   *
   * @param {any[]}    items      - items to process
   * @param {Function} processFn  - async (item) => result
   * @returns {{ results, errors, stats }}
   */
  async process(items, processFn) {
    const results  = [];
    const errors   = [];
    const batches  = this.#createBatches(items);
    const stats    = {
      total:     items.length,
      processed: 0,
      failed:    0,
      retried:   0,
      startTime: Date.now(),
      endTime:   null
    };

    this.emit('start', { totalItems: items.length, totalBatches: batches.length });

    // Process batches with bounded concurrency
    for (let i = 0; i < batches.length; i += this.concurrency) {
      const window = batches.slice(i, i + this.concurrency);

      const batchResults = await Promise.all(
        window.map((batch, offset) =>
          this.#processBatch(batch, processFn, i + offset, batches.length)
        )
      );

      for (const br of batchResults) {
        results.push(...br.successes);
        errors.push(...br.failures);
        stats.processed += br.successes.length;
        stats.failed    += br.failures.length;
        stats.retried   += br.retryCount;
      }

      this.emit('progress', {
        processed: stats.processed,
        failed:    stats.failed,
        total:     stats.total,
        pct:       Math.round(((stats.processed + stats.failed) / stats.total) * 100)
      });
    }

    stats.endTime   = Date.now();
    stats.durationMs = stats.endTime - stats.startTime;

    this.emit('complete', stats);
    return { results, errors, stats };
  }

  // ── private helpers ─────────────────────────────────────────

  #createBatches(items) {
    const batches = [];
    for (let i = 0; i < items.length; i += this.batchSize) {
      batches.push(items.slice(i, i + this.batchSize));
    }
    return batches;
  }

  async #processBatch(batch, processFn, batchIndex, totalBatches) {
    const successes  = [];
    const failures   = [];
    let   retryCount = 0;

    this.emit('batchStart', {
      batchIndex,
      batchSize: batch.length,
      totalBatches
    });

    for (const item of batch) {
      try {
        const result = await this.#processWithRetry(item, processFn);
        successes.push({ item, result: result.value, retries: result.attempts - 1 });
        retryCount += result.attempts - 1;
      } catch (err) {
        failures.push({ item, error: err.message, attempts: this.maxRetries });
        retryCount += this.maxRetries - 1;
        this.emit('itemError', { item, error: err.message });
      }
    }

    this.emit('batchComplete', {
      batchIndex,
      successes: successes.length,
      failures:  failures.length
    });

    return { successes, failures, retryCount };
  }

  async #processWithRetry(item, processFn) {
    let lastError;

    for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
      try {
        const value = await processFn(item);
        return { value, attempts: attempt };
      } catch (err) {
        lastError = err;
        if (attempt < this.maxRetries) {
          const delay = this.retryDelayMs * Math.pow(2, attempt - 1); // exp backoff
          this.emit('retry', { item, attempt, nextDelayMs: delay, error: err.message });
          await this.#sleep(delay);
        }
      }
    }

    throw lastError;
  }

  #sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

module.exports = BatchProcessor;
```

### `src/MigrationStore.js` — Checkpoint / State Persistence

```javascript
const fs   = require('node:fs/promises');
const path = require('node:path');

/**
 * Persists migration state to a JSON file so that a long-running migration
 * can be resumed after a crash.
 */
class MigrationStore {
  constructor(storePath = './.migration-state.json') {
    this.storePath = path.resolve(storePath);
    this.state     = null;   // loaded lazily
  }

  // ── public API ──────────────────────────────────────────────

  /** Initialise a brand-new migration run. */
  async init(migrationId, metadata = {}) {
    this.state = {
      migrationId,
      status:       'pending',
      metadata,
      checkpoint:   0,           // index of last successfully processed item
      processedIds: [],          // ids of migrated events
      failedIds:    [],          // ids that exhausted retries
      log:          [],          // append-only log entries
      createdAt:    new Date().toISOString(),
      updatedAt:    new Date().toISOString()
    };
    await this.#save();
    return this.state;
  }

  /** Load existing state from disk (returns null if none). */
  async load() {
    try {
      const raw = await fs.readFile(this.storePath, 'utf-8');
      this.state = JSON.parse(raw);
      return this.state;
    } catch {
      return null;
    }
  }

  /** Advance the checkpoint and record processed ids. */
  async updateProgress(checkpoint, processedIds = [], failedIds = []) {
    this.#ensureLoaded();
    this.state.checkpoint = checkpoint;
    this.state.processedIds.push(...processedIds);
    this.state.failedIds.push(...failedIds);
    this.state.status    = 'in_progress';
    this.state.updatedAt = new Date().toISOString();
    await this.#save();
  }

  /** Mark migration as complete. */
  async complete(stats = {}) {
    this.#ensureLoaded();
    Object.assign(this.state, {
      status:    'completed',
      stats,
      updatedAt: new Date().toISOString()
    });
    this.#addLog('Migration completed');
    await this.#save();
  }

  /** Mark migration as failed. */
  async fail(error) {
    this.#ensureLoaded();
    Object.assign(this.state, {
      status:    'failed',
      error:     error.message || String(error),
      updatedAt: new Date().toISOString()
    });
    this.#addLog(`Migration failed: ${error.message || error}`);
    await this.#save();
  }

  /** Mark migration as rolled back. */
  async markRolledBack() {
    this.#ensureLoaded();
    this.state.status    = 'rolled_back';
    this.state.updatedAt = new Date().toISOString();
    this.#addLog('Migration rolled back');
    await this.#save();
  }

  /** Append an arbitrary log message. */
  async addLog(message) {
    this.#ensureLoaded();
    this.#addLog(message);
    await this.#save();
  }

  /** Delete the state file entirely. */
  async clean() {
    try { await fs.unlink(this.storePath); } catch { /* ignore */ }
    this.state = null;
  }

  getState() {
    return this.state;
  }

  // ── private helpers ─────────────────────────────────────────

  #ensureLoaded() {
    if (!this.state) throw new Error('No migration state loaded — call init() or load() first');
  }

  #addLog(message) {
    this.state.log.push({ timestamp: new Date().toISOString(), message });
  }

  async #save() {
    await fs.writeFile(this.storePath, JSON.stringify(this.state, null, 2), 'utf-8');
  }
}

module.exports = MigrationStore;
```

