# Basic Task Queue Consumer in JavaScript

## Implementation

```javascript
class TaskQueue {
  constructor(concurrency = 1) {
    this.queue = [];
    this.running = 0;
    this.concurrency = concurrency;
    this.paused = false;
  }

  // Add a task to the queue
  enqueue(taskFn, { priority = 0, name = "unnamed" } = {}) {
    return new Promise((resolve, reject) => {
      const task = {
        fn: taskFn,
        name,
        priority,
        resolve,
        reject,
        addedAt: Date.now(),
      };

      this.queue.push(task);
      this.queue.sort((a, b) => b.priority - a.priority); // higher priority first

      console.log(`[enqueue] "${name}" (priority: ${priority}, queue size: ${this.queue.length})`);
      this._process();
    });
  }

  // Internal: process next tasks if possible
  async _process() {
    if (this.paused) return;

    while (this.running < this.concurrency && this.queue.length > 0) {
      const task = this.queue.shift();
      this.running++;

      console.log(`[start]   "${task.name}" (running: ${this.running})`);

      this._run(task);
    }
  }

  // Internal: execute a single task
  async _run(task) {
    const start = Date.now();
    try {
      const result = await task.fn();
      const duration = Date.now() - start;
      console.log(`[done]    "${task.name}" (${duration}ms)`);
      task.resolve(result);
    } catch (err) {
      console.log(`[error]   "${task.name}": ${err.message}`);
      task.reject(err);
    } finally {
      this.running--;
      this._process(); // pick up next task
    }
  }

  // Pause processing (running tasks will finish)
  pause() {
    this.paused = true;
    console.log("[paused]  Queue paused");
  }

  // Resume processing
  resume() {
    this.paused = false;
    console.log("[resumed] Queue resumed");
    this._process();
  }

  // Get current status
  status() {
    return {
      queued: this.queue.length,
      running: this.running,
      paused: this.paused,
    };
  }

  // Clear pending tasks
  clear() {
    const removed = this.queue.length;
    this.queue.forEach((task) => task.reject(new Error("Task cleared")));
    this.queue = [];
    console.log(`[cleared] Removed ${removed} pending tasks`);
  }
}
```

## Usage

```javascript
// --- Helper: simulate async work ---
function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// --- Create queue with 2 concurrent workers ---
const queue = new TaskQueue(2);

// --- Schedule tasks ---
async function main() {
  // Fire-and-forget style
  queue.enqueue(() => delay(1000).then(() => "fetched data"), {
    name: "fetch-users",
    priority: 1,
  });

  queue.enqueue(() => delay(500).then(() => "email sent"), {
    name: "send-email",
    priority: 5, // runs first (higher priority)
  });

  queue.enqueue(() => delay(800).then(() => "report done"), {
    name: "generate-report",
    priority: 3,
  });

  // Await a result directly
  try {
    const result = await queue.enqueue(
      () => delay(300).then(() => ({ id: 1, status: "processed" })),
      { name: "process-order", priority: 10 }
    );
    console.log("Order result:", result);
  } catch (err) {
    console.error("Order failed:", err);
  }

  // Check status
  console.log("Status:", queue.status());
}

main();
```

