  fileName: string;
  sizeBytes: number;
  rowCount: number;
}

// ---------- Report generator contract ----------
export interface ReportGenerator {
  /** Validate params before heavy work begins */
  validate(params: Record<string, unknown>): void;

  /** Stream/generate the report, calling progressCb(0-100) along the way */
  generate(
    params: Record<string, unknown>,
    format: "csv" | "pdf",
    progressCb: (pct: number) => Promise<void>,
    logger: Logger
  ): Promise<ReportResult>;
}

// ---------- Registry ----------
const generators = new Map<string, ReportGenerator>();

export function registerReport(name: string, gen: ReportGenerator) {
  generators.set(name, gen);
}

export function getReport(name: string): ReportGenerator {
  const gen = generators.get(name);
  if (!gen) throw new Error(`Unknown report type: ${name}`);
  return gen;
}
