## Concrete Report: Sales Report

```typescript
// src/reports/sales-report.ts
import { stringify } from "csv-stringify/sync";
import PDFDocument from "pdfkit";
import pg from "pg";
import { DATABASE_URL } from "../config";
import { uploadToS3 } from "../storage";
import {
  ReportGenerator,
  ReportResult,
  registerReport,
} from "./registry";
import { Logger } from "winston";

interface SalesParams {
  startDate: string;
  endDate: string;
  regionId?: number;
}

class SalesReportGenerator implements ReportGenerator {
  validate(params: Record<string, unknown>): void {
    if (!params.startDate || !params.endDate) {
      throw new Error("startDate and endDate are required");
    }
    const start = new Date(params.startDate as string);
    const end = new Date(params.endDate as string);
    if (isNaN(start.getTime()) || isNaN(end.getTime())) {
      throw new Error("Invalid date format");
    }
    if (end < start) {
      throw new Error("endDate must be after startDate");
    }
  }

  async generate(
    params: Record<string, unknown>,
    format: "csv" | "pdf",
    progressCb: (pct: number) => Promise<void>,
    logger: Logger
  ): Promise<ReportResult> {
    const { startDate, endDate, regionId } = params as unknown as SalesParams;

    // 1. Query data in chunks
    const pool = new pg.Pool({ connectionString: DATABASE_URL });
    try {
      await progressCb(10);

      const { rows } = await pool.query<{
        order_id: number;
        customer: string;
        amount: number;
        region: string;
        created_at: Date;
      }>(
        `SELECT order_id, customer, amount, region, created_at
         FROM orders
         WHERE created_at BETWEEN $1 AND $2
           AND ($3::int IS NULL OR region_id = $3)
         ORDER BY created_at`,
        [startDate, endDate, regionId ?? null]
      );

      logger.info(`Fetched ${rows.length} rows for sales report`);
      await progressCb(50);

      // 2. Format output
      let buffer: Buffer;
      let contentType: string;
      let ext: string;

      if (format === "csv") {
        const csv = stringify(rows, { header: true });
        buffer = Buffer.from(csv, "utf-8");
        contentType = "text/csv";
        ext = "csv";
      } else {
        buffer = await this.buildPdf(rows);
        contentType = "application/pdf";
        ext = "pdf";
      }

      await progressCb(80);

      // 3. Upload to storage
      const fileName = `sales-report_${startDate}_${endDate}.${ext}`;
      const upload = await uploadToS3(buffer, fileName, contentType);

      await progressCb(100);

      return {
        fileUrl: upload.url,
        fileName,
        sizeBytes: upload.sizeBytes,
        rowCount: rows.length,
      };
    } finally {
      await pool.end();
    }
  }

  private buildPdf(
    rows: Array<{
      order_id: number;
      customer: string;
      amount: number;
      region: string;
      created_at: Date;
    }>
  ): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      const doc = new PDFDocument({ margin: 40, size: "A4" });
      const chunks: Buffer[] = [];

      doc.on("data", (c: Buffer) => chunks.push(c));
      doc.on("end", () => resolve(Buffer.concat(chunks)));
      doc.on("error", reject);

      // Header
      doc.fontSize(18).text("Sales Report", { align: "center" });
      doc.moveDown();

      // Table rows
      doc.fontSize(10);
      for (const row of rows) {
        doc.text(
          `#${row.order_id}  |  ${row.customer}  |  $${row.amount.toFixed(2)}  |  ${row.region}  |  ${row.created_at.toISOString().slice(0, 10)}`,
          { width: 500 }
        );
      }

      doc.end();
    });
  }
}

// Self-register
registerReport("sales", new SalesReportGenerator());
