## The Worker (Consumer)

```typescript
// src/worker.ts
import { Worker, Job } from "bullmq";
import { createLogger, format, transports } from "winston";
import { REDIS, QUEUE_NAME, WORKER_CONCURRENCY } from "./config";
import { ReportJobData, ReportResult, getReport } from "./reports/registry";

// --- Load all report generators (self-registering) ---
import "./reports/sales-report";
import "./reports/user-activity-report";

// --- Logger ---
const logger = createLogger({
  level: "info",
  format: format.combine(format.timestamp(), format.json()),
  transports: [new transports.Console()],
});

// --- Worker definition ---
const worker = new Worker<ReportJobData, ReportResult>(
  QUEUE_NAME,
  async (job: Job<ReportJobData, ReportResult>) => {
    const { reportType, params, format: fmt, requestedBy } = job.data;

    logger.info("Processing report job", {
      jobId: job.id,
      reportType,
      requestedBy,
    });

    // 1. Look up the generator
    const generator = getReport(reportType);

    // 2. Validate params (throws on bad input → moves to failed)
    generator.validate(params);

    // 3. Generate with progress tracking
    const result = await generator.generate(
      params,
      fmt,
      async (pct) => {
        await job.updateProgress(pct);
      },
      logger
    );

    logger.info("Report completed", {
      jobId: job.id,
      fileUrl: result.fileUrl,
      rowCount: result.rowCount,
    });

    // 4. Optional webhook callback
    if (job.data.callbackUrl) {
      await notifyCallback(job.data.callbackUrl, job.id!, result);
    }

    return result;
  },
  {
    connection: REDIS,
    concurrency: WORKER_CONCURRENCY,
    // Stalled job detection
    lockDuration: 300_000, // 5 min lock — reports can be slow
    limiter: {
      max: 10,
      duration: 60_000, // max 10 jobs per minute (protect DB)
    },
    removeOnComplete: { age: 7 * 86_400 }, // keep 7 days
    removeOnFail: { age: 30 * 86_400 },    // keep 30 days
  }
);

// --- Event listeners ---
worker.on("completed", (job) => {
  logger.info(`Job ${job.id} completed`);
});

worker.on("failed", (job, err) => {
  logger.error(`Job ${job?.id} failed`, {
    error: err.message,
    attempt: job?.attemptsMade,
  });
});

worker.on("error", (err) => {
  logger.error("Worker error", { error: err.message });
});

// --- Webhook notifier ---
async function notifyCallback(
  url: string,
  jobId: string,
  result: ReportResult
) {
  try {
    await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ jobId, status: "completed", ...result }),
      signal: AbortSignal.timeout(10_000),
    });
  } catch (err) {
    logger.warn("Callback notification failed", { url, error: String(err) });
    // Don't fail the job over a webhook issue
  }
}

// --- Graceful shutdown ---
async function shutdown(signal: string) {
  logger.info(`Received ${signal}, closing worker...`);
  await worker.close();    // finish current jobs, stop picking new ones
  logger.info("Worker shut down cleanly");
  process.exit(0);
}

process.on("SIGINT", () => shutdown("SIGINT"));
process.on("SIGTERM", () => shutdown("SIGTERM"));

logger.info(`Report worker started (concurrency=${WORKER_CONCURRENCY})`);
```

