// src/producer.ts
import { Queue } from "bullmq";
import { REDIS, QUEUE_NAME } from "./config";
import { ReportJobData } from "./reports/registry";

const queue = new Queue<ReportJobData>(QUEUE_NAME, {
  connection: REDIS,
  defaultJobOptions: {
    attempts: 3,
    backoff: { type: "exponential", delay: 5_000 },
    priority: 5, // default priority (lower = higher priority)
  },
});

// Convenience helpers for your API layer
export async function enqueueReport(
  data: ReportJobData,
  opts?: { priority?: number; delay?: number }
) {
  const job = await queue.add(`report:${data.reportType}`, data, {
    priority: opts?.priority,
    delay: opts?.delay,
  });
  return { jobId: job.id, queue: QUEUE_NAME };
}

export async function getJobStatus(jobId: string) {
  const job = await queue.getJob(jobId);
  if (!job) return null;

  const state = await job.getState();
  return {
    id: job.id,
    state,
    progress: job.progress,
    result: job.returnvalue,
    failedReason: job.failedReason,
    attempts: job.attemptsMade,
    createdAt: job.timestamp,
  };
}

