  const filePath = report.filePath;

  // Check file exists before streaming
  try {
    await fs.access(filePath);
  } catch {
    return res.status(410).json({
      success: false,
      error: 'Report file no longer available',
    });
  }

  const contentTypes = {
    json: 'application/json',
    csv: 'text/csv',
    pdf: 'application/pdf',
  };

  res.setHeader('Content-Type', contentTypes[report.format]);
  res.setHeader('Content-Disposition',
    `attachment; filename="report-${reportId}.${report.format}"`);

  // Stream the file instead of loading entirely into memory
  const { createReadStream } = require('fs');
  const stream = createReadStream(filePath);

  stream.on('error', (err) => {
    console.error('Stream error:', err);
    if (!res.headersSent) {
      res.status(500).json({ success: false, error: 'Download failed' });
    }
  });

  stream.pipe(res);
}));

