```javascript
// src/MetricsStore.js
import { EventEmitter } from "node:events";

/**
 * In-memory metrics store with time-bucketed storage.
 * Supports pluggable backends (Redis, in-memory).
 */
class MetricsStore extends EventEmitter {
  #buckets;         // Map<bucketKey, Map<metricName, number[]>>
  #bucketSizeMs;
  #retentionMs;
  #cleanupTimer;

  constructor({ bucketSizeMs = 60_000, retentionMs = 3_600_000 } = {}) {
    super();
    this.#buckets = new Map();
    this.#bucketSizeMs = bucketSizeMs;
    this.#retentionMs = retentionMs;

    // Periodic cleanup of expired buckets
    this.#cleanupTimer = setInterval(() => this.#evictExpired(), retentionMs / 2);
    this.#cleanupTimer.unref(); // Don't block process exit
  }

  /** Returns the bucket key (timestamp floored to bucket boundary) */
  #getBucketKey(timestamp = Date.now()) {
    return Math.floor(timestamp / this.#bucketSizeMs) * this.#bucketSizeMs;
  }

  /** Record a single metric data point */
  record(name, value, timestamp = Date.now()) {
    if (typeof name !== "string" || name.length === 0) {
      throw new TypeError("Metric name must be a non-empty string");
    }
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError("Metric value must be a finite number");
    }

    const bucketKey = this.#getBucketKey(timestamp);
    if (!this.#buckets.has(bucketKey)) {
      this.#buckets.set(bucketKey, new Map());
    }

    const bucket = this.#buckets.get(bucketKey);
    if (!bucket.has(name)) {
      bucket.set(name, []);
    }

    bucket.get(name).push(value);
    this.emit("metric:recorded", { name, value, bucketKey });
  }

  /** Get raw values for a metric within a time range */
  getRange(name, fromTs, toTs) {
    const values = [];
    const fromBucket = this.#getBucketKey(fromTs);
    const toBucket = this.#getBucketKey(toTs);

    for (const [bucketKey, metrics] of this.#buckets) {
      if (bucketKey >= fromBucket && bucketKey <= toBucket && metrics.has(name)) {
        values.push(...metrics.get(name));
      }
    }
    return values;
  }

  /** Get all metric names currently stored */
  getMetricNames() {
    const names = new Set();
    for (const metrics of this.#buckets.values()) {
      for (const name of metrics.keys()) {
        names.add(name);
      }
    }
    return [...names];
  }

  /** Drain and return all complete (non-current) buckets */
  drainCompleteBuckets() {
    const currentBucket = this.#getBucketKey();
    const drained = new Map();

    for (const [bucketKey, metrics] of this.#buckets) {
      if (bucketKey < currentBucket) {
        drained.set(bucketKey, metrics);
        this.#buckets.delete(bucketKey);
      }
    }

    return drained;
  }

  /** Remove buckets older than retention period */
  #evictExpired() {
    const cutoff = Date.now() - this.#retentionMs;
    let evicted = 0;
    for (const bucketKey of this.#buckets.keys()) {
      if (bucketKey < cutoff) {
        this.#buckets.delete(bucketKey);
        evicted++;
      }
    }
    if (evicted > 0) {
      this.emit("buckets:evicted", { count: evicted });
    }
  }

  get bucketCount() {
    return this.#buckets.size;
  }

  destroy() {
    clearInterval(this.#cleanupTimer);
    this.#buckets.clear();
    this.removeAllListeners();
  }
}

export default MetricsStore;
