## Aggregation Engine

```javascript
// src/Aggregator.js

/**
 * Computes aggregate statistics from arrays of numbers.
 * Each aggregation type is a pure function — easy to test and compose.
 */
class Aggregator {
  static #registry = new Map();

  /** Register a custom aggregation function */
  static register(name, fn) {
    if (typeof fn !== "function") {
      throw new TypeError("Aggregation function required");
    }
    Aggregator.#registry.set(name, fn);
  }

  /** Run a named aggregation */
  static compute(name, values) {
    const fn = Aggregator.#registry.get(name);
    if (!fn) throw new Error(`Unknown aggregation: ${name}`);
    return fn(values);
  }

  /** Run multiple aggregations, returning a result object */
  static aggregate(values, aggregationNames) {
    if (!Array.isArray(values) || values.length === 0) {
      return null;
    }

    const result = { count: values.length };
    for (const name of aggregationNames) {
      result[name] = Aggregator.compute(name, values);
    }
    return result;
  }
}

// ── Built-in aggregation functions ─────────────────────────

Aggregator.register("sum", (vals) => {
  let total = 0;
  for (let i = 0; i < vals.length; i++) total += vals[i];
  return total;
});

Aggregator.register("avg", (vals) => {
  let total = 0;
  for (let i = 0; i < vals.length; i++) total += vals[i];
  return total / vals.length;
});

Aggregator.register("min", (vals) => {
  let min = Infinity;
  for (let i = 0; i < vals.length; i++) {
    if (vals[i] < min) min = vals[i];
  }
  return min;
});

Aggregator.register("max", (vals) => {
  let max = -Infinity;
  for (let i = 0; i < vals.length; i++) {
    if (vals[i] > max) max = vals[i];
  }
  return max;
});

Aggregator.register("p50", (vals) => percentile(vals, 50));
Aggregator.register("p90", (vals) => percentile(vals, 90));
Aggregator.register("p95", (vals) => percentile(vals, 95));
Aggregator.register("p99", (vals) => percentile(vals, 99));

Aggregator.register("stddev", (vals) => {
  const n = vals.length;
  let sum = 0;
  for (let i = 0; i < n; i++) sum += vals[i];
  const mean = sum / n;

  let sqDiffSum = 0;
  for (let i = 0; i < n; i++) {
    sqDiffSum += (vals[i] - mean) ** 2;
  }
  return Math.sqrt(sqDiffSum / n);
});

Aggregator.register("rate", (vals) => {
  // Sum divided by 60 → per-second rate assuming 60s buckets
  let total = 0;
  for (let i = 0; i < vals.length; i++) total += vals[i];
  return total / 60;
});

// ── Percentile helper (nearest-rank method) ────────────────

function percentile(values, pct) {
  const sorted = Float64Array.from(values).sort();
  const rank = Math.ceil((pct / 100) * sorted.length) - 1;
  return sorted[Math.max(0, rank)];
}

export default Aggregator;
