## Background Worker

```javascript
// src/BackgroundWorker.js
import { EventEmitter } from "node:events";

/**
 * A generic background worker that runs a task on a fixed interval.
 * Supports:
 *  - Graceful shutdown (finish current tick before stopping)
 *  - Jitter to prevent thundering-herd
 *  - Error isolation (one failed tick doesn't kill the worker)
 *  - Backpressure (skips tick if previous is still running)
 */
class BackgroundWorker extends EventEmitter {
  #name;
  #intervalMs;
  #jitterMs;
  #taskFn;
  #timer;
  #running;
  #stopping;
  #tickCount;
  #errorCount;

  constructor({ name, intervalMs, jitterMs = 0, task }) {
    super();
    this.#name = name;
    this.#intervalMs = intervalMs;
    this.#jitterMs = jitterMs;
    this.#taskFn = task;
    this.#timer = null;
    this.#running = false;
    this.#stopping = false;
    this.#tickCount = 0;
    this.#errorCount = 0;
  }

  start() {
    if (this.#timer) return;
    this.#stopping = false;
    this.#scheduleTick();
    this.emit("started", { name: this.#name });
  }

  async stop() {
    this.#stopping = true;
    clearTimeout(this.#timer);
    this.#timer = null;

    // Wait for in-flight tick to finish
    if (this.#running) {
      await new Promise((resolve) => this.once("tick:complete", resolve));
    }
    this.emit("stopped", { name: this.#name });
  }

  #scheduleTick() {
    const jitter = Math.random() * this.#jitterMs;
    const delay = this.#intervalMs + jitter;

    this.#timer = setTimeout(() => this.#executeTick(), delay);
    this.#timer.unref();
  }

  async #executeTick() {
    if (this.#stopping) return;

    // Backpressure: skip if previous tick still running
    if (this.#running) {
      this.emit("tick:skipped", { name: this.#name, reason: "backpressure" });
      this.#scheduleTick();
      return;
    }

    this.#running = true;
    this.#tickCount++;
    const tickId = this.#tickCount;
    const startTime = performance.now();

    try {
      this.emit("tick:start", { name: this.#name, tickId });
      await this.#taskFn();
      const duration = performance.now() - startTime;
      this.emit("tick:complete", { name: this.#name, tickId, durationMs: duration });
    } catch (error) {
      this.#errorCount++;
      const duration = performance.now() - startTime;
      this.emit("tick:error", {
        name: this.#name,
        tickId,
        error,
        durationMs: duration,
        errorCount: this.#errorCount,
      });
    } finally {
      this.#running = false;
      if (!this.#stopping) {
        this.#scheduleTick();
      }
    }
  }

  get stats() {
    return {
      name: this.#name,
      ticks: this.#tickCount,
      errors: this.#errorCount,
      running: this.#running,
    };
  }
}

export default BackgroundWorker;
