## Metrics Aggregation Worker (ties it all together)

```javascript
// src/MetricsAPI.js
import MetricsStore from "./MetricsStore.js";
import Aggregator from "./Aggregator.js";
import BackgroundWorker from "./BackgroundWorker.js";
import { createLogger } from "./utils/logger.js";

const log = createLogger("MetricsAPI");

/**
 * High-level API that wires the store, aggregator, and worker together.
 *
 *  ┌────────────┐    record()    ┌──────────────┐
 *  │  Your App  │ ─────────────▶ │ MetricsStore │
 *  └────────────┘                └──────┬───────┘
 *                                       │ drain
 *                      ┌────────────────┘  (every N seconds)
 *                      ▼
 *               ┌─────────────┐
 *               │  Aggregator │  sum / avg / p99 / …
 *               └──────┬──────┘
 *                      │
 *                      ▼
 *               ┌─────────────┐
 *               │  Results DB │  (in-memory or Redis)
 *               └─────────────┘
 */
class MetricsAPI {
  #store;
  #worker;
  #results;       // Aggregated snapshots: Array<{ timestamp, metrics }>
  #maxSnapshots;
  #aggregations;

  constructor({
    bucketSizeMs = 10_000,       // 10-second raw buckets
    aggregationIntervalMs = 15_000, // aggregate every 15 seconds
    retentionMs = 3_600_000,
    maxSnapshots = 360,           // keep ~1 hour of snapshots
    aggregations = ["sum", "avg", "min", "max", "p50", "p95", "p99", "stddev"],
  } = {}) {
    this.#store = new MetricsStore({ bucketSizeMs, retentionMs });
    this.#results = [];
    this.#maxSnapshots = maxSnapshots;
    this.#aggregations = aggregations;

    // Define metric-specific overrides (metric name → aggregation list)
    this.metricConfig = new Map();

    // Create the background aggregation worker
    this.#worker = new BackgroundWorker({
      name: "metrics-aggregator",
      intervalMs: aggregationIntervalMs,
      jitterMs: 1_000,
      task: () => this.#runAggregation(),
    });

    // Wire up logging
    this.#worker.on("tick:start", ({ tickId }) =>
      log.debug(`Aggregation tick #${tickId} starting`)
    );
    this.#worker.on("tick:complete", ({ tickId, durationMs }) =>
      log.info(`Aggregation tick #${tickId} completed in ${durationMs.toFixed(1)}ms`)
    );
    this.#worker.on("tick:error", ({ tickId, error }) =>
      log.error(`Aggregation tick #${tickId} failed: ${error.message}`)
    );
    this.#worker.on("tick:skipped", ({ reason }) =>
      log.warn(`Aggregation tick skipped: ${reason}`)
    );
    this.#store.on("buckets:evicted", ({ count }) =>
      log.debug(`Evicted ${count} expired bucket(s)`)
    );
  }

  // ── Public recording API ──────────────────────────────

  /** Record a single metric value */
  record(name, value) {
    this.#store.record(name, value);
  }

  /** Record a timer metric (start → end duration in ms) */
  recordTimer(name) {
    const start = performance.now();
    return {
      stop: () => {
        const duration = performance.now() - start;
        this.record(name, duration);
        return duration;
      },
    };
  }

  /** Increment a counter by 1 (or a custom amount) */
  increment(name, amount = 1) {
    this.record(name, amount);
  }

  /** Record a gauge value (latest-wins semantics at aggregation) */
  gauge(name, value) {
    this.record(name, value);
  }

  // ── Worker lifecycle ──────────────────────────────────

  start() {
    this.#worker.start();
    log.info("Metrics aggregation worker started");
  }

  async stop() {
    await this.#worker.stop();
    // Run one final aggregation to capture remaining data
    await this.#runAggregation();
    log.info("Metrics aggregation worker stopped");
  }

  // ── Query API ─────────────────────────────────────────

  /** Get the latest aggregated snapshot */
  getLatest() {
    return this.#results.at(-1) ?? null;
  }

  /** Get all snapshots within a time range */
  getSnapshots(fromTs = 0, toTs = Date.now()) {
    return this.#results.filter(
      (s) => s.timestamp >= fromTs && s.timestamp <= toTs
    );
  }

  /** Get aggregated data for a specific metric */
  getMetric(name) {
    const latest = this.getLatest();
    return latest?.metrics[name] ?? null;
  }

  /** Get worker health stats */
  getHealth() {
    return {
      worker: this.#worker.stats,
      store: {
        bucketCount: this.#store.bucketCount,
        metricNames: this.#store.getMetricNames(),
      },
      snapshots: this.#results.length,
    };
  }

  // ── Internal aggregation logic ────────────────────────

  async #runAggregation() {
    const completeBuckets = this.#store.drainCompleteBuckets();
    if (completeBuckets.size === 0) return;

    // Merge all drained buckets by metric name
    const merged = new Map();
    for (const [, metrics] of completeBuckets) {
      for (const [name, values] of metrics) {
        if (!merged.has(name)) merged.set(name, []);
        merged.get(name).push(...values);
      }
    }

    // Aggregate each metric
    const snapshot = {
      timestamp: Date.now(),
      metrics: {},
    };

    for (const [name, values] of merged) {
      const aggs = this.metricConfig.get(name) ?? this.#aggregations;
      snapshot.metrics[name] = Aggregator.aggregate(values, aggs);
    }

    // Store the snapshot (ring-buffer style)
    this.#results.push(snapshot);
    if (this.#results.length > this.#maxSnapshots) {
      this.#results.splice(0, this.#results.length - this.#maxSnapshots);
    }

    log.info(
      `Aggregated ${merged.size} metric(s) from ${completeBuckets.size} bucket(s)`
    );
  }

  // ── Cleanup ───────────────────────────────────────────

  destroy() {
    this.#store.destroy();
    this.#results.length = 0;
  }
}

export default MetricsAPI;
