## File Sync Implementation

```javascript
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

// ─── Configuration ───────────────────────────────────────────────
const DEFAULT_CONFIG = {
  maxRetries: 3,
  retryDelayMs: 1000,       // Base delay (doubles each retry)
  syncIntervalMs: 5000,     // Poll interval for continuous sync
  logLevel: "info",         // "debug" | "info" | "warn" | "error"
};

// ─── Logger ──────────────────────────────────────────────────────
class Logger {
  constructor(level = "info") {
    this.levels = { debug: 0, info: 1, warn: 2, error: 3 };
    this.level = this.levels[level] ?? 1;
  }

  #log(level, message, data = null) {
    if (this.levels[level] >= this.level) {
      const timestamp = new Date().toISOString();
      const prefix = `[${timestamp}] [${level.toUpperCase()}]`;
      console.log(`${prefix} ${message}`, data ?? "");
    }
  }

  debug(msg, data) { this.#log("debug", msg, data); }
  info(msg, data)  { this.#log("info", msg, data); }
  warn(msg, data)  { this.#log("warn", msg, data); }
  error(msg, data) { this.#log("error", msg, data); }
}

// ─── Retry Handler ───────────────────────────────────────────────
class RetryHandler {
  constructor(maxRetries, baseDelay, logger) {
    this.maxRetries = maxRetries;
    this.baseDelay = baseDelay;
    this.logger = logger;
  }

  /** Executes an async operation with exponential backoff retries */
  async execute(operation, description = "operation") {
    let lastError;

    for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
      try {
        const result = await operation();
        if (attempt > 1) {
          this.logger.info(`✅ "${description}" succeeded on attempt ${attempt}`);
        }
        return result;

      } catch (error) {
        lastError = error;
        const delay = this.baseDelay * Math.pow(2, attempt - 1);

        this.logger.warn(
          `⚠️  "${description}" failed (attempt ${attempt}/${this.maxRetries}): ${error.message}`
        );

        if (attempt < this.maxRetries) {
          this.logger.info(`⏳ Retrying in ${delay}ms...`);
          await this.#sleep(delay);
        }
      }
    }

    this.logger.error(`❌ "${description}" failed after ${this.maxRetries} attempts`);
    throw lastError;
  }

  #sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

// ─── File Sync Engine ────────────────────────────────────────────
class FileSync {
  constructor(sourceDir, targetDir, config = {}) {
    this.sourceDir = path.resolve(sourceDir);
    this.targetDir = path.resolve(targetDir);
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.logger = new Logger(this.config.logLevel);
    this.retry = new RetryHandler(
      this.config.maxRetries,
      this.config.retryDelayMs,
      this.logger
    );
    this.stats = { copied: 0, skipped: 0, deleted: 0, errors: 0 };
    this.intervalId = null;
  }

  // ── Public API ──────────────────────────────────────────────

  /** Run a one-time sync from source → target */
  async sync() {
    this.logger.info(`🔄 Starting sync: ${this.sourceDir} → ${this.targetDir}`);
    this.#resetStats();

    try {
      this.#ensureDirectory(this.targetDir);
      await this.#syncDirectory(this.sourceDir, this.targetDir);
      await this.#cleanOrphans(this.sourceDir, this.targetDir);
      this.#logStats();
      return { success: true, stats: { ...this.stats } };

    } catch (error) {
      this.logger.error("Sync failed", error.message);
      return { success: false, error: error.message, stats: { ...this.stats } };
    }
  }

  /** Start continuous sync on an interval */
  startContinuousSync() {
    this.logger.info(`🔁 Continuous sync every ${this.config.syncIntervalMs}ms`);
    this.sync(); // Initial sync

    this.intervalId = setInterval(() => this.sync(), this.config.syncIntervalMs);
    return this;
  }

  /** Stop continuous sync */
  stopContinuousSync() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
      this.logger.info("⏹️  Continuous sync stopped");
    }
  }

  // ── Private: Directory Traversal ───────────────────────────

  async #syncDirectory(srcDir, tgtDir) {
    const entries = fs.readdirSync(srcDir, { withFileTypes: true });

    for (const entry of entries) {
      const srcPath = path.join(srcDir, entry.name);
      const tgtPath = path.join(tgtDir, entry.name);

      if (entry.isDirectory()) {
        this.#ensureDirectory(tgtPath);
        await this.#syncDirectory(srcPath, tgtPath);

      } else if (entry.isFile()) {
        await this.#syncFile(srcPath, tgtPath);
      }
    }
  }

  // ── Private: Single File Sync ──────────────────────────────

  async #syncFile(srcPath, tgtPath) {
    const relativePath = path.relative(this.sourceDir, srcPath);

    // Skip if files are identical
    if (this.#filesAreEqual(srcPath, tgtPath)) {
      this.logger.debug(`⏭️  Skipped (unchanged): ${relativePath}`);
      this.stats.skipped++;
      return;
    }

    // Copy with retry
    await this.retry.execute(
      () => this.#copyFile(srcPath, tgtPath),
      `copy ${relativePath}`
    ).then(() => {
      this.stats.copied++;
    }).catch(() => {
      this.stats.errors++;
    });
  }

  #copyFile(srcPath, tgtPath) {
    return new Promise((resolve, reject) => {
      const readStream  = fs.createReadStream(srcPath);
      const writeStream = fs.createWriteStream(tgtPath);

      readStream.on("error", reject);
      writeStream.on("error", reject);
      writeStream.on("finish", () => {
        // Preserve original file timestamps
        const { atime, mtime } = fs.statSync(srcPath);
        fs.utimesSync(tgtPath, atime, mtime);
        this.logger.info(`📄 Copied: ${path.relative(this.sourceDir, srcPath)}`);
        resolve();
      });

      readStream.pipe(writeStream);
    });
  }

  // ── Private: Orphan Cleanup ────────────────────────────────

  async #cleanOrphans(srcDir, tgtDir) {
    if (!fs.existsSync(tgtDir)) return;

    const entries = fs.readdirSync(tgtDir, { withFileTypes: true });

    for (const entry of entries) {
      const srcPath = path.join(srcDir, entry.name);
      const tgtPath = path.join(tgtDir, entry.name);

      if (!fs.existsSync(srcPath)) {
        await this.retry.execute(
          () => this.#removePath(tgtPath, entry.isDirectory()),
          `delete ${path.relative(this.targetDir, tgtPath)}`
        ).then(() => {
          this.stats.deleted++;
        }).catch(() => {
          this.stats.errors++;
        });

      } else if (entry.isDirectory()) {
        await this.#cleanOrphans(srcPath, tgtPath);
      }
    }
  }

  #removePath(targetPath, isDirectory) {
    return new Promise((resolve, reject) => {
      try {
        if (isDirectory) {
          fs.rmSync(targetPath, { recursive: true, force: true });
        } else {
          fs.unlinkSync(targetPath);
        }
        this.logger.info(`🗑️  Deleted: ${path.relative(this.targetDir, targetPath)}`);
        resolve();
      } catch (err) {
        reject(err);
      }
    });
  }

  // ── Private: Comparison Helpers ────────────────────────────

  #filesAreEqual(srcPath, tgtPath) {
    if (!fs.existsSync(tgtPath)) return false;

    const srcStat = fs.statSync(srcPath);
    const tgtStat = fs.statSync(tgtPath);

    // Quick check: size + modification time
    if (srcStat.size !== tgtStat.size) return false;
    if (srcStat.mtimeMs === tgtStat.mtimeMs) return true;

    // Deep check: content hash
    return this.#getChecksum(srcPath) === this.#getChecksum(tgtPath);
  }

  #getChecksum(filePath) {
    const content = fs.readFileSync(filePath);
    return crypto.createHash("md5").update(content).digest("hex");
  }

  // ── Private: Utilities ─────────────────────────────────────

  #ensureDirectory(dirPath) {
    if (!fs.existsSync(dirPath)) {
      fs.mkdirSync(dirPath, { recursive: true });
      this.logger.debug(`📁 Created directory: ${dirPath}`);
    }
  }

  #resetStats() {
    this.stats = { copied: 0, skipped: 0, deleted: 0, errors: 0 };
  }

  #logStats() {
    this.logger.info("─── Sync Complete ───────────────────");
    this.logger.info(`  📄 Copied:  ${this.stats.copied}`);
    this.logger.info(`  ⏭️  Skipped: ${this.stats.skipped}`);
    this.logger.info(`  🗑️  Deleted: ${this.stats.deleted}`);
    this.logger.info(`  ❌ Errors:  ${this.stats.errors}`);
    this.logger.info("─────────────────────────────────────");
  }
}

// ─── Usage Examples ──────────────────────────────────────────────

// 1) One-time sync
async function runOnce() {
  const syncer = new FileSync("./source", "./backup", {
    maxRetries: 3,
    retryDelayMs: 500,
    logLevel: "info",
  });

  const result = await syncer.sync();
  console.log("Result:", result);
}

// 2) Continuous sync (poll every 10 seconds)
function runContinuous() {
  const syncer = new FileSync("./source", "./backup", {
    maxRetries: 3,
    retryDelayMs: 500,
    syncIntervalMs: 10_000,
    logLevel: "info",
  });

  syncer.startContinuousSync();

  // Stop after 1 minute
  setTimeout(() => syncer.stopContinuousSync(), 60_000);
}

// Run one-time sync by default
runOnce();

module.exports = { FileSync, RetryHandler, Logger };
