use std::path::PathBuf;
use thiserror::Error;

/// Master error type for the document parsing system.
#[derive(Debug, Error)]
pub enum ParseError {
    #[error("I/O error reading '{path}': {source}")]
    Io {
        path: PathBuf,
        source: std::io::Error,
    },

    #[error("Invalid JSON at line {line}, column {col}: {message}")]
    InvalidJson {
        line: usize,
        col: usize,
        message: String,
    },

    #[error("Invalid XML: {message}")]
    InvalidXml { message: String },

    #[error("Invalid CSV at record {record}: {message}")]
    InvalidCsv { record: usize, message: String },

    #[error("Unsupported document format: {format}")]
    UnsupportedFormat { format: String },

    #[error("Document too large: {size_bytes} bytes (max: {max_bytes})")]
    DocumentTooLarge { size_bytes: u64, max_bytes: u64 },

    #[error("Encoding error: expected {expected}, got {detected}")]
    EncodingError { expected: String, detected: String },

    #[error("Parse timeout after {elapsed_ms}ms (limit: {timeout_ms}ms)")]
    Timeout { elapsed_ms: u64, timeout_ms: u64 },

    #[error("Resource temporarily unavailable: {reason}")]
    ResourceUnavailable { reason: String },

    #[error("Retry exhausted after {attempts} attempts: {last_error}")]
    RetryExhausted {
        attempts: u32,
        last_error: Box<ParseError>,
    },

    #[error("Pipeline error at stage '{stage}': {source}")]
    Pipeline {
        stage: String,
        source: Box<ParseError>,
    },
}

impl ParseError {
    /// Whether this error is transient and the operation should be retried.
    pub fn is_retryable(&self) -> bool {
        matches!(
            self,
            ParseError::Io { source, .. } if source.kind() == std::io::ErrorKind::Interrupted
                || source.kind() == std::io::ErrorKind::TimedOut
                || source.kind() == std::io::ErrorKind::WouldBlock
        ) || matches!(
            self,
            ParseError::Timeout { .. } | ParseError::ResourceUnavailable { .. }
        )
    }

    /// Classify error severity for monitoring / alerting.
    pub fn severity(&self) -> ErrorSeverity {
        match self {
            ParseError::DocumentTooLarge { .. } | ParseError::UnsupportedFormat { .. } => {
                ErrorSeverity::Warning
            }
            ParseError::RetryExhausted { .. } => ErrorSeverity::Critical,
            _ if self.is_retryable() => ErrorSeverity::Transient,
            _ => ErrorSeverity::Error,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ErrorSeverity {
    Transient,
    Warning,
    Error,
    Critical,
}

/// Alias used throughout the crate.
pub type ParseResult<T> = Result<T, ParseError>;
