## `src/retry.rs`

```rust
use crate::error::{ParseError, ParseResult};
use rand::Rng;
use std::future::Future;
use std::time::Duration;
use tracing::{info, warn};

/// Strategy used to compute delays between retries.
#[derive(Debug, Clone)]
pub enum BackoffStrategy {
    /// Same delay every time.
    Fixed(Duration),
    /// Doubles each attempt: base * 2^attempt.
    Exponential {
        base: Duration,
        max_delay: Duration,
    },
    /// Linear growth: base * attempt.
    Linear {
        base: Duration,
        max_delay: Duration,
    },
}

impl BackoffStrategy {
    fn delay_for(&self, attempt: u32) -> Duration {
        match self {
            Self::Fixed(d) => *d,
            Self::Exponential { base, max_delay } => {
                let delay = base.saturating_mul(2u32.saturating_pow(attempt));
                delay.min(*max_delay)
            }
            Self::Linear { base, max_delay } => {
                let delay = base.saturating_mul(attempt.saturating_add(1));
                delay.min(*max_delay)
            }
        }
    }
}

/// Full retry configuration (builder pattern).
#[derive(Debug, Clone)]
pub struct RetryPolicy {
    pub max_attempts: u32,
    pub backoff: BackoffStrategy,
    pub jitter: bool,
    pub retry_predicate: RetryPredicate,
}

/// Which errors should be retried.
#[derive(Debug, Clone, Copy)]
pub enum RetryPredicate {
    /// Retry only errors that self-identify as transient.
    TransientOnly,
    /// Retry every error except clearly permanent ones.
    AllExceptPermanent,
}

impl RetryPredicate {
    fn should_retry(&self, err: &ParseError) -> bool {
        match self {
            Self::TransientOnly => err.is_retryable(),
            Self::AllExceptPermanent => {
                !matches!(
                    err,
                    ParseError::UnsupportedFormat { .. }
                        | ParseError::DocumentTooLarge { .. }
                        | ParseError::EncodingError { .. }
                )
            }
        }
    }
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            max_attempts: 3,
            backoff: BackoffStrategy::Exponential {
                base: Duration::from_millis(100),
                max_delay: Duration::from_secs(10),
            },
            jitter: true,
            retry_predicate: RetryPredicate::TransientOnly,
        }
    }
}

impl RetryPolicy {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn max_attempts(mut self, n: u32) -> Self {
        self.max_attempts = n;
        self
    }

    pub fn backoff(mut self, strategy: BackoffStrategy) -> Self {
        self.backoff = strategy;
        self
    }

    pub fn with_jitter(mut self, jitter: bool) -> Self {
        self.jitter = jitter;
        self
    }

    pub fn retry_predicate(mut self, predicate: RetryPredicate) -> Self {
        self.retry_predicate = predicate;
        self
    }

    /// No retries at all – useful for testing or when wrapping is unwanted.
    pub fn no_retry() -> Self {
        Self {
            max_attempts: 1,
            ..Default::default()
        }
    }

    /// Compute the sleep duration for a given attempt number (0-indexed).
    fn compute_delay(&self, attempt: u32) -> Duration {
        let base_delay = self.backoff.delay_for(attempt);
        if self.jitter {
            let jitter_factor: f64 = rand::thread_rng().gen_range(0.5..1.5);
            base_delay.mul_f64(jitter_factor)
        } else {
            base_delay
        }
    }
}

/// Execute an async operation with the configured retry policy.
///
/// `operation_name` is used only for structured logging.
pub async fn retry_async<F, Fut, T>(
    policy: &RetryPolicy,
    operation_name: &str,
    mut factory: F,
) -> ParseResult<T>
where
    F: FnMut() -> Fut,
    Fut: Future<Output = ParseResult<T>>,
{
    let mut last_error: Option<ParseError> = None;

    for attempt in 0..policy.max_attempts {
        match factory().await {
            Ok(value) => {
                if attempt > 0 {
                    info!(
                        operation = operation_name,
                        attempt = attempt + 1,
                        "Operation succeeded after retry"
                    );
                }
                return Ok(value);
            }
            Err(err) => {
                let is_last_attempt = attempt + 1 >= policy.max_attempts;
                let should_retry = !is_last_attempt && policy.retry_predicate.should_retry(&err);

                if should_retry {
                    let delay = policy.compute_delay(attempt);
                    warn!(
                        operation = operation_name,
                        attempt = attempt + 1,
                        max_attempts = policy.max_attempts,
                        delay_ms = delay.as_millis() as u64,
                        error = %err,
                        "Retryable error – backing off"
                    );
                    tokio::time::sleep(delay).await;
                    last_error = Some(err);
                } else if is_last_attempt {
                    last_error = Some(err);
                } else {
                    // Non-retryable error – return immediately.
                    warn!(
                        operation = operation_name,
                        error = %err,
                        "Non-retryable error – aborting"
                    );
                    return Err(err);
                }
            }
        }
    }

    Err(ParseError::RetryExhausted {
        attempts: policy.max_attempts,
        last_error: Box::new(last_error.expect("at least one attempt was made")),
    })
}

/// Synchronous retry helper (wraps `retry_async` on a current-thread runtime).
pub fn retry_sync<F, T>(policy: &RetryPolicy, operation_name: &str, mut f: F) -> ParseResult<T>
where
    F: FnMut() -> ParseResult<T>,
{
    let mut last_error: Option<ParseError> = None;

    for attempt in 0..policy.max_attempts {
        match f() {
            Ok(value) => return Ok(value),
            Err(err) => {
                let is_last = attempt + 1 >= policy.max_attempts;
                let should_retry = !is_last && policy.retry_predicate.should_retry(&err);

                if should_retry {
                    let delay = policy.compute_delay(attempt);
                    warn!(
                        operation = operation_name,
                        attempt = attempt + 1,
                        delay_ms = delay.as_millis() as u64,
                        error = %err,
                        "Retrying (sync)"
                    );
                    std::thread::sleep(delay);
                    last_error = Some(err);
                } else if is_last {
                    last_error = Some(err);
                } else {
                    return Err(err);
                }
            }
        }
    }

    Err(ParseError::RetryExhausted {
        attempts: policy.max_attempts,
        last_error: Box::new(last_error.expect("at least one attempt")),
    })
}

