## `main.go`

```go
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"
	"unicode"
)

const version = "1.0.0"

var (
	configPath string
	statePath  string
)

func init() {
	// Allow override via env, default to ~/.chatmod/
	dir := os.Getenv("CHATMOD_DIR")
	if dir == "" {
		home, err := os.UserHomeDir()
		if err != nil {
			home = "."
		}
		dir = filepath.Join(home, ".chatmod")
	}
	configPath = filepath.Join(dir, "config.json")
	statePath = filepath.Join(dir, "state.json")
}

// ━━━━━━━━━━━━━━━━━━━━ Types ━━━━━━━━━━━━━━━━━━━━

type Config struct {
	Rules     []Rule          `json:"rules"`
	Bans      map[string]*Ban `json:"bans"`
	RateLimit RateLimitCfg    `json:"rate_limit"`
	MaxCaps   float64         `json:"max_caps_ratio"` // 0-1, 0 disables
	MaxLen    int             `json:"max_length"`      // 0 disables
	NextID    int             `json:"next_id"`
}

type Rule struct {
	ID      int    `json:"id"`
	Pattern string `json:"pattern"`
	IsRegex bool   `json:"is_regex"`
	Action  string `json:"action"` // block, warn, flag
	Reason  string `json:"reason"`
}

type Ban struct {
	Reason    string     `json:"reason"`
	CreatedAt time.Time  `json:"created_at"`
	ExpiresAt *time.Time `json:"expires_at,omitempty"`
}

type RateLimitCfg struct {
	Max    int `json:"max_messages"`    // messages per window, 0 disables
	Window int `json:"window_seconds"`
}

type State struct {
	Timestamps map[string][]int64 `json:"timestamps"`
	Violations map[string]int     `json:"violations"`
	Stats      ModStats           `json:"stats"`
}

type ModStats struct {
	Checked int64 `json:"checked"`
	Blocked int64 `json:"blocked"`
	Warned  int64 `json:"warned"`
	Flagged int64 `json:"flagged"`
}

type Verdict struct {
	Allowed bool     `json:"allowed"`
	Action  string   `json:"action"`
	Reasons []string `json:"reasons,omitempty"`
}

// ━━━━━━━━━━━━━━━━━━━━ Persistence ━━━━━━━━━━━━━━━━━━━━

func ensureDir() {
	dir := filepath.Dir(configPath)
	_ = os.MkdirAll(dir, 0o755)
}

func defaultConfig() *Config {
	return &Config{
		Rules: []Rule{},
		Bans:  make(map[string]*Ban),
		RateLimit: RateLimitCfg{
			Max:    5,
			Window: 10,
		},
		MaxCaps: 0.7,
		MaxLen:  500,
		NextID:  1,
	}
}

func loadJSON(path string, v interface{}) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, v)
}

func saveJSON(path string, v interface{}) {
	ensureDir()
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		fatal("json marshal: %v", err)
	}
	if err := os.WriteFile(path, data, 0o644); err != nil {
		fatal("write %s: %v", path, err)
	}
}

func loadConfig() *Config {
	var c Config
	if err := loadJSON(configPath, &c); err != nil {
		return defaultConfig()
	}
	if c.Bans == nil {
		c.Bans = make(map[string]*Ban)
	}
	return &c
}

func saveConfig(c *Config)  { saveJSON(configPath, c) }
func saveState(s *State)    { saveJSON(statePath, s) }

func loadState() *State {
	var s State
	if err := loadJSON(statePath, &s); err != nil {
		return freshState()
	}
	if s.Timestamps == nil {
		s.Timestamps = make(map[string][]int64)
	}
	if s.Violations == nil {
		s.Violations = make(map[string]int)
	}
	return &s
}

func freshState() *State {
	return &State{
		Timestamps: make(map[string][]int64),
		Violations: make(map[string]int),
	}
}

// ━━━━━━━━━━━━━━━━━━━━ Moderator Engine ━━━━━━━━━━━━━━━━━━━━

type Moderator struct {
	config   *Config
	state    *State
	compiled map[int]*regexp.Regexp
}

func NewModerator() *Moderator {
	m := &Moderator{
		config:   loadConfig(),
		state:    loadState(),
		compiled: make(map[int]*regexp.Regexp),
	}
	for _, r := range m.config.Rules {
		if r.IsRegex {
			if re, err := regexp.Compile("(?i)" + r.Pattern); err == nil {
				m.compiled[r.ID] = re
			}
		}
	}
	return m
}

func (m *Moderator) Save() {
	saveConfig(m.config)
	saveState(m.state)
}

// Check runs every moderation check and returns a single verdict.
// Priority order: ban → rate-limit → length → caps → content rules.
func (m *Moderator) Check(user, message string) Verdict {
	m.state.Stats.Checked++
	var reasons []string
	worst := "pass"

	// 1 ── Banned user?
	if ban, ok := m.config.Bans[user]; ok && user != "" {
		if ban.ExpiresAt != nil && time.Now().After(*ban.ExpiresAt) {
			delete(m.config.Bans, user) // expired, clean up
		} else {
			r := "user is banned"
			if ban.Reason != "" {
				r += ": " + ban.Reason
			}
			return m.recordVerdict(user, "block", []string{r})
		}
	}

	// 2 ── Rate limit
	if m.config.RateLimit.Max > 0 && user != "" {
		now := time.Now().Unix()
		cutoff := now - int64(m.config.RateLimit.Window)
		var recent []int64
		for _, ts := range m.state.Timestamps[user] {
			if ts > cutoff {
				recent = append(recent, ts)
			}
		}
		recent = append(recent, now)
		m.state.Timestamps[user] = recent

		if len(recent) > m.config.RateLimit.Max {
			reasons = append(reasons, fmt.Sprintf(
				"rate limit: %d msgs in %ds (max %d)",
				len(recent), m.config.RateLimit.Window, m.config.RateLimit.Max))
			worst = escalate(worst, "block")
		}
	}

	// 3 ── Message length
	if m.config.MaxLen > 0 && len(message) > m.config.MaxLen {
		reasons = append(reasons, fmt.Sprintf(
			"too long: %d chars (max %d)", len(message), m.config.MaxLen))
		worst = escalate(worst, "warn")
	}

	// 4 ── Caps ratio (only for messages with enough letters)
	if m.config.MaxCaps > 0 && len(message) > 8 {
		ratio := capsRatio(message)
		if ratio > m.config.MaxCaps {
			reasons = append(reasons, fmt.Sprintf(
				"excessive caps: %.0f%% (max %.0f%%)", ratio*100, m.config.MaxCaps*100))
			worst = escalate(worst, "warn")
		}
	}

	// 5 ── Content rules
	lower := strings.ToLower(message)
	for _, rule := range m.config.Rules {
		hit := false
		if rule.IsRegex {
			if re, ok := m.compiled[rule.ID]; ok {
				hit = re.MatchString(message)
			}
		} else {
			hit = strings.Contains(lower, strings.ToLower(rule.Pattern))
		}
		if hit {
			r := rule.Reason
			if r == "" {
				r = fmt.Sprintf("matched rule #%d [%s]", rule.ID, rule.Pattern)
			}
			reasons = append(reasons, r)
			worst = escalate(worst, rule.Action)
		}
	}

	return m.recordVerdict(user, worst, reasons)
}

func (m *Moderator) recordVerdict(user, action string, reasons []string) Verdict {
	switch action {
	case "block":
		m.state.Stats.Blocked++
		if user != "" {
			m.state.Violations[user]++
		}
	case "warn":
		m.state.Stats.Warned++
	case "flag":
		m.state.Stats.Flagged++
	}
	return Verdict{
		Allowed: action != "block",
		Action:  action,
		Reasons: reasons,
	}
}

// escalate returns whichever action is more severe.
func escalate(current, incoming string) string {
	order := map[string]int{"pass": 0, "flag": 1, "warn": 2, "block": 3}
	if order[incoming] > order[current] {
		return incoming
	}
	return current
}

func capsRatio(s string) float64 {
	var upper, letters int
	for _, r := range s {
		if unicode.IsLetter(r) {
			letters++
			if unicode.IsUpper(r) {
				upper++
			}
		}
	}
	if letters == 0 {
		return 0
	}
	return float64(upper) / float64(letters)
}

// ━━━━━━━━━━━━━━━━━━━━ CLI Commands ━━━━━━━━━━━━━━━━━━━━

// ── init ──

func cmdInit() {
	if _, err := os.Stat(configPath); err == nil {
		fmt.Fprintf(os.Stderr, "Config exists at %s. Overwrite? [y/N] ", configPath)
		var ans string
		fmt.Scanln(&ans)
		if strings.ToLower(strings.TrimSpace(ans)) != "y" {
			fmt.Println("Aborted.")
			return
		}
	}
	saveConfig(defaultConfig())
	saveState(freshState())
	fmt.Printf("✓ Initialized: %s\n", configPath)
}

// ── check ──

func cmdCheck(args []string) {
	f := parseFlags(args)
	msg := f["msg"]
	if msg == "" {
		fatal("usage: chatmod check -msg MESSAGE [-user USER] [-json]")
	}

	mod := NewModerator()
	v := mod.Check(f["user"], msg)
	mod.Save()

	if f["json"] == "true" {
		enc := json.NewEncoder(os.Stdout)
		enc.SetIndent("", "  ")
		_ = enc.Encode(v)
	} else {
		printVerdict(v, f["user"])
	}

	if !v.Allowed {
		os.Exit(1)
	}
}

func printVerdict(v Verdict, user string) {
	sym, color := actionStyle(v.Action)
	reset := "\033[0m"
	label := fmt.Sprintf("%s %s%s%s", sym, color, strings.ToUpper(v.Action), reset)
	if user != "" {
		label += fmt.Sprintf("  [user: %s]", user)
	}
	fmt.Println(label)
	for _, r := range v.Reasons {
		fmt.Printf("  → %s\n", r)
	}
}

func actionStyle(action string) (string, string) {
	switch action {
	case "block":
		return "✗", "\033[31m"
	case "warn":
		return "⚠", "\033[33m"
	case "flag":
		return "⚑", "\033[34m"
	default:
		return "✓", "\033[32m"
	}
}

// ── pipe (streaming JSON-lines) ──

func cmdPipe() {
	mod := NewModerator()
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	enc := json.NewEncoder(os.Stdout)

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}

		var in struct {
			User    string `json:"user"`
			Message string `json:"message"`
		}
		if err := json.Unmarshal([]byte(line), &in); err != nil {
			in.Message = line // treat plain text as message with no user
		}

		v := mod.Check(in.User, in.Message)

		_ = enc.Encode(struct {
			User    string   `json:"user,omitempty"`
			Message string   `json:"message"`
			Allowed bool     `json:"allowed"`
			Action  string   `json:"action"`
			Reasons []string `json:"reasons,omitempty"`
		}{in.User, in.Message, v.Allowed, v.Action, v.Reasons})
	}
	mod.Save()
}

// ── rule add / list / rm ──

func cmdRuleAdd(args []string) {
	f := parseFlags(args)
	pattern, action := f["pattern"], f["action"]
	if pattern == "" || action == "" {
		fatal("usage: chatmod rule add -pattern PAT -action block|warn|flag [-regex] [-reason TEXT]")
	}
	if action != "block" && action != "warn" && action != "flag" {
		fatal("action must be block, warn, or flag")
	}
	isRegex := f["regex"] == "true"
	if isRegex {
		if _, err := regexp.Compile(pattern); err != nil {
			fatal("bad regex: %v", err)
		}
	}

	cfg := loadConfig()
	rule := Rule{
		ID:      cfg.NextID,
		Pattern: pattern,
		IsRegex: isRegex,
		Action:  action,
		Reason:  f["reason"],
	}
	cfg.NextID++
	cfg.Rules = append(cfg.Rules, rule)
	saveConfig(cfg)

	typ := "exact"
	if isRegex {
		typ = "regex"
	}
	fmt.Printf("✓ Rule #%d added  [%s, %s] → %s\n", rule.ID, typ, pattern, action)
}

func cmdRuleList() {
	cfg := loadConfig()
	if len(cfg.Rules) == 0 {
		fmt.Println("No rules. Add one with: chatmod rule add -pattern ... -action ...")
		return
	}
	w := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(w, "ID\tTYPE\tACTION\tPATTERN\tREASON")
	fmt.Fprintln(w, "──\t────\t──────\t───────\t──────")
	for _, r := range cfg.Rules {
		typ := "exact"
		if r.IsRegex {
			typ = "regex"
		}
		reason := r.Reason
		if reason == "" {
			reason = "-"
		}
		fmt.Fprintf(w, "%d\t%s\t%s\t%s\t%s\n", r.ID, typ, r.Action, r.Pattern, reason)
	}
	w.Flush()
}

func cmdRuleRm(args []string) {
	f := parseFlags(args)
	idStr := f["id"]
	if idStr == "" && len(args) > 0 && !strings.HasPrefix(args[0], "-") {
		idStr = args[0] // allow: chatmod rule rm 3
	}
	if idStr == "" {
		fatal("usage: chatmod rule rm -id ID")
	}
	id, err := strconv.Atoi(idStr)
	if err != nil {
		fatal("bad id: %s", idStr)
	}

	cfg := loadConfig()
	filtered := cfg.Rules[:0]
	found := false
	for _, r := range cfg.Rules {
		if r.ID == id {
			found = true
			continue
		}
		filtered = append(filtered, r)
	}
	if !found {
		fatal("rule #%d not found", id)
	}
	cfg.Rules = filtered
	saveConfig(cfg)
	fmt.Printf("✓ Rule #%d removed\n", id)
}

// ── ban / unban / bans ──

func cmdBan(args []string) {
	f := parseFlags(args)
	user := f["user"]
	if user == "" {
		fatal("usage: chatmod ban -user USER [-reason TEXT] [-duration 24h]")
	}

	ban := &Ban{
		Reason:    f["reason"],
		CreatedAt: time.Now(),
	}
	if d := f["duration"]; d != "" {
		dur, err := time.ParseDuration(d)
		if err != nil {
			fatal("bad duration %q (use Go format: 30m, 24h, 168h)", d)
		}
		exp := time.Now().Add(dur)
		ban.ExpiresAt = &exp
	}

	cfg := loadConfig()
	cfg.Bans[user] = ban
	saveConfig(cfg)

	line := fmt.Sprintf("✓ Banned: %s", user)
	if ban.Reason != "" {
		line += fmt.Sprintf("  reason=%q", ban.Reason)
	}
	if ban.ExpiresAt != nil {
		line += fmt.Sprintf("  expires=%s", ban.ExpiresAt.Format(time.DateTime))
	} else {
		line += "  (permanent)"
	}
	fmt.Println(line)
}

func cmdUnban(args []string) {
	f := parseFlags(args)
	user := f["user"]
	if user == "" && len(args) > 0 && !strings.HasPrefix(args[0], "-") {
		user = args[0]
	}
	if user == "" {
		fatal("usage: chatmod unban -user USER")
	}

	cfg := loadConfig()
	if _, ok := cfg.Bans[user]; !ok {
		fmt.Printf("User %q is not banned.\n", user)
		return
	}
	delete(cfg.Bans, user)
	saveConfig(cfg)
	fmt.Printf("✓ Unbanned: %s\n", user)
}

func cmdBanList() {
	cfg := loadConfig()

	// Prune expired bans
	now := time.Now()
	changed := false
	for user, ban := range cfg.Bans {
		if ban.ExpiresAt != nil && now.After(*ban.ExpiresAt) {
			delete(cfg.Bans, user)
			changed = true
		}
	}
	if changed {
		saveConfig(cfg)
	}

	if len(cfg.Bans) == 0 {
		fmt.Println("No active bans.")
		return
	}

	w := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(w, "USER\tREASON\tBANNED\tEXPIRES")
	fmt.Fprintln(w, "────\t──────\t──────\t───────")
	for user, ban := range cfg.Bans {
		reason := ban.Reason
		if reason == "" {
			reason = "-"
		}
		expires := "permanent"
		if ban.ExpiresAt != nil {
			expires = ban.ExpiresAt.Format("2006-01-02 15:04")
		}
		fmt.Fprintf(w, "%s\t%s\t%s\t%s\n",
			user, reason,
			ban.CreatedAt.Format("2006-01-02 15:04"),
			expires)
	}
	w.Flush()
}

// ── stats ──

func cmdStats() {
	st := loadState()
	cfg := loadConfig()

	fmt.Println("── Moderation Stats ──")
	fmt.Printf("  Checked : %d\n", st.Stats.Checked)
	fmt.Printf("  Blocked : %d\n", st.Stats.Blocked)
	fmt.Printf("  Warned  : %d\n", st.Stats.Warned)
	fmt.Printf("  Flagged : %d\n", st.Stats.Flagged)
	fmt.Printf("  Rules   : %d\n", len(cfg.Rules))
	fmt.Printf("  Bans    : %d\n", len(cfg.Bans))

	if len(st.Violations) > 0 {
		fmt.Println("\n── Top Violators ──")
		w := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
		fmt.Fprintln(w, "  USER\tBLOCKS")
		for user, n := range st.Violations {
			fmt.Fprintf(w, "  %s\t%d\n", user, n)
		}
		w.Flush()
	}
}

// ── reset ──

func cmdReset(args []string) {
	f := parseFlags(args)
	what := f["_positional"]
	if what == "" && len(args) > 0 && !strings.HasPrefix(args[0], "-") {
		what = args[0]
	}

	switch what {
	case "stats":
		saveState(freshState())
		fmt.Println("✓ Stats reset.")
	case "rules":
		cfg := loadConfig()
		cfg.Rules = []Rule{}
		saveConfig(cfg)
		fmt.Println("✓ All rules removed.")
	case "bans":
		cfg := loadConfig()
		cfg.Bans = make(map[string]*Ban)
		saveConfig(cfg)
		fmt.Println("✓ All bans removed.")
	case "all":
		saveConfig(defaultConfig())
		saveState(freshState())
		fmt.Println("✓ Everything reset to defaults.")
	default:
		fatal("usage: chatmod reset <stats|rules|bans|all>")
	}
}

// ━━━━━━━━━━━━━━━━━━━━ Helpers ━━━━━━━━━━━━━━━━━━━━

// parseFlags does minimal flag parsing: -key value pairs, plus
// bare -flag booleans for known switches.
func parseFlags(args []string) map[string]string {
	boolFlags := map[string]bool{"regex": true, "json": true}
	flags := make(map[string]string)
	for i := 0; i < len(args); {
		a := args[i]
		if !strings.HasPrefix(a, "-") {
			i++
			continue
		}
		key := strings.TrimLeft(a, "-")
		if boolFlags[key] {
			flags[key] = "true"
			i++
			continue
		}
		if i+1 < len(args) {
			flags[key] = args[i+1]
			i += 2
		} else {
			flags[key] = ""
			i++
		}
	}
	return flags
}

func fatal(format string, a ...interface{}) {
	fmt.Fprintf(os.Stderr, "error: "+format+"\n", a...)
	os.Exit(2)
}

