# Chat Moderation Queue Consumer

## Implementation

```javascript
// moderationQueue.js

class ModerationQueue {
  constructor() {
    this.queue = [];
    this.processing = false;
    this.bannedWords = ["spam", "scam", "hate", "abuse"];
    this.results = [];
  }

  // Add message to queue
  enqueue(message) {
    this.queue.push({
      id: Date.now() + Math.random(),
      text: message.text,
      user: message.user,
      timestamp: new Date().toISOString(),
      status: "pending",
    });
    console.log(`📥 Queued message from "${message.user}"`);
    this.processNext();
  }

  // Process next message in queue
  async processNext() {
    if (this.processing || this.queue.length === 0) return;

    this.processing = true;
    const message = this.queue.shift();

    console.log(`⏳ Moderating message from "${message.user}"...`);

    try {
      const result = await this.moderate(message);
      this.results.push(result);

      if (result.status === "rejected") {
        console.log(`🚫 REJECTED: "${message.text}" — Reason: ${result.reason}`);
      } else {
        console.log(`✅ APPROVED: "${message.text}"`);
      }
    } catch (err) {
      console.error(`❌ Error moderating message: ${err.message}`);
    }

    this.processing = false;
    this.processNext(); // Process next in queue
  }

  // Moderation logic
  async moderate(message) {
    // Simulate async processing delay
    await new Promise((resolve) => setTimeout(resolve, 200));

    const text = message.text.toLowerCase();

    // Check banned words
    for (const word of this.bannedWords) {
      if (text.includes(word)) {
        return { ...message, status: "rejected", reason: `banned word: "${word}"` };
      }
    }

    // Check message length
    if (message.text.length > 500) {
      return { ...message, status: "rejected", reason: "message too long" };
    }

    // Check excessive caps (shouting)
    const capsRatio = (message.text.match(/[A-Z]/g) || []).length / message.text.length;
    if (message.text.length > 10 && capsRatio > 0.7) {
      return { ...message, status: "rejected", reason: "excessive caps" };
    }

    // Check repeated characters (e.g., "helloooooo")
    if (/(.)\1{4,}/.test(text)) {
      return { ...message, status: "rejected", reason: "character spam" };
    }

    return { ...message, status: "approved", reason: null };
  }

  // Get moderation stats
  getStats() {
    const approved = this.results.filter((r) => r.status === "approved").length;
    const rejected = this.results.filter((r) => r.status === "rejected").length;
    return {
      total: this.results.length,
      approved,
      rejected,
      pending: this.queue.length,
    };
  }
}

module.exports = ModerationQueue;
```

