## The Fixed Code (After)

```javascript
// task-scheduler-linter.js — FIXED VERSION
"use strict";

// ✅ Fix 1: Comprehensive cron regex (values, ranges, steps, lists, wildcards)
const CRON_FIELD_PATTERN =
  /^(\*|\d+(-\d+)?(\/\d+)?)(,(\*|\d+(-\d+)?(\/\d+)?))*$/;

// ✅ Fix 2: Include all five cron fields
const CRON_FIELD_RANGES = {
  minute:     { min: 0, max: 59 },
  hour:       { min: 0, max: 23 },
  dayOfMonth: { min: 1, max: 31 },
  month:      { min: 1, max: 12 },
  dayOfWeek:  { min: 0, max: 7 },       // 0 and 7 both represent Sunday
};

// ✅ Fix 3: Removed unused `taskRegistry`

class TaskSchedulerLinter {
  constructor(options = {}) {
    this.rules        = options.rules || {};
    this.errors       = [];
    this.warnings     = [];
    // ✅ Fix 4: Read maxConcurrent from options with a default
    this.maxConcurrent = options.maxConcurrent ?? 10;
  }

  // ──────────────────────────────────────────────
  //  Rule: Validate cron expression syntax
  // ──────────────────────────────────────────────
  validateCronExpression(expression, taskName) {
    if (typeof expression !== "string") {
      this.errors.push({
        rule:     "valid-cron",
        message:  `Task "${taskName}": Cron expression must be a string`,
        severity: "error",
      });
      return false;
    }

    const parts = expression.trim().split(/\s+/);

    // ✅ Fix 5: Standard cron has exactly 5 fields
    if (parts.length !== 5) {
      this.errors.push({
        rule:     "valid-cron",
        message:  `Task "${taskName}": Expected 5 cron fields, got ${parts.length}`,
        severity: "error",
      });
      return false;
    }

    const fieldNames = Object.keys(CRON_FIELD_RANGES);
    let valid = true;

    // ✅ Fix 6: Use strict < (not <=) to avoid off-by-one
    for (let i = 0; i < parts.length; i++) {
      const part      = parts[i];
      const fieldName = fieldNames[i];
      const range     = CRON_FIELD_RANGES[fieldName];

      // ✅ Fix 7: Guard against missing range definition
      if (!range) {
        this.errors.push({
          rule:     "valid-cron",
          message:  `Task "${taskName}": No range defined for field index ${i}`,
          severity: "error",
        });
        valid = false;
        continue;
      }

      // Allow wildcards and step patterns like */5
      if (part === "*" || /^\*\/\d+$/.test(part)) continue;

      // Validate each comma-separated value or range
      const subParts = part.split(",");
      for (const sub of subParts) {
        if (!CRON_FIELD_PATTERN.test(sub)) {
          this.errors.push({
            rule:     "valid-cron",
            message:  `Task "${taskName}": Invalid syntax "${sub}" in field "${fieldName}"`,
            severity: "error",
          });
          valid = false;
          continue;
        }

        // Validate numeric bounds for plain numbers & ranges
        const nums = sub.split(/[-/]/).map(Number).filter((n) => !isNaN(n));
        for (const num of nums) {
          if (num < range.min || num > range.max) {
            this.errors.push({
              rule:     "valid-cron",
              message:  `Task "${taskName}": "${fieldName}" value ${num} out of [${range.min}–${range.max}]`,
              severity: "error",
            });
            valid = false;
          }
        }
      }
    }

    return valid;
  }

  // ──────────────────────────────────────────────
  //  Rule: Detect overlapping schedules
  // ──────────────────────────────────────────────
  detectOverlappingSchedules(tasks) {
    const scheduleMap = new Map();       // ✅ Fix 10: Map avoids prototype issues

    // ✅ Fix 8: Correct destructuring order [index, task]
    for (const [index, task] of tasks.entries()) {
      const key = task.cronExpression;

      // ✅ Fix 9: Use strict equality
      if (!scheduleMap.has(key)) {
        scheduleMap.set(key, []);
      }
      scheduleMap.get(key).push(task.name);
    }

    for (const [key, names] of scheduleMap) {
      if (names.length > 1) {
        this.warnings.push({
          rule:     "no-overlapping-schedules",
          message:  `Overlapping schedule "${key}": tasks [${names.join(", ")}]`,
          severity: "warning",
        });
      }
    }
  }

  // ──────────────────────────────────────────────
  //  Rule: Require error handlers on every task
  // ──────────────────────────────────────────────
  requireErrorHandler(task) {
    // ✅ Fix 11: Verify the handler is actually a function
    if (typeof task.onError !== "function") {
      this.errors.push({
        rule:     "require-error-handler",
        message:  `Task "${task.name}": Missing or non-function error handler`,
        severity: "error",
      });
      return false;
    }
    return true;
  }

  // ──────────────────────────────────────────────
  //  Rule: Require task timeout
  // ──────────────────────────────────────────────
  requireTimeout(task) {
    // ✅ Fix 12: Compare against number 0, and ensure it's a positive number
    if (
      task.timeout === undefined ||
      task.timeout === null ||
      typeof task.timeout !== "number" ||
      task.timeout <= 0
    ) {
      this.errors.push({
        rule:     "require-timeout",
        message:  `Task "${task.name}": Must define a positive numeric timeout (got ${task.timeout})`,
        severity: "error",
      });
      return false;
    }
    return true;
  }

  // ──────────────────────────────────────────────
  //  Rule: Max concurrent task limit
  // ──────────────────────────────────────────────
  checkConcurrencyLimit(tasks) {
    const concurrentTasks = tasks.filter((t) => t.concurrent === true);

    // ✅ Fix 13: Flag when count EXCEEDS the limit (use >)
    if (concurrentTasks.length > this.maxConcurrent) {
      this.warnings.push({
        rule:     "max-concurrency",
        message:  `${concurrentTasks.length} concurrent tasks exceed limit of ${this.maxConcurrent}`,
        severity: "warning",
      });
    }
  }

  // ──────────────────────────────────────────────
  //  Rule: Ensure task cleanup / cancellation token
  // ──────────────────────────────────────────────
  requireCleanup(task) {
    // ✅ Fix 14 & 15: Both must be present; error when either is missing
    if (
      typeof task.cleanup !== "function" ||
      !task.cancellationToken
    ) {
      this.errors.push({
        rule:     "require-cleanup",
        message:  `Task "${task.name}": Must provide cleanup() AND cancellationToken`,
        severity: "error",
      });
      return false;
    }
    return true;
  }

  // ──────────────────────────────────────────────
  //  Rule: No duplicate task names
  // ──────────────────────────────────────────────
  checkDuplicateNames(tasks) {
    // ✅ Fix 16: Guard against null / non-array input
    if (!Array.isArray(tasks)) {
      this.errors.push({
        rule:     "no-duplicate-names",
        message:  "Task list must be an array",
        severity: "error",
      });
      return;
    }

    const seen = new Set();

    tasks.forEach((task) => {
      if (seen.has(task.name)) {
        this.errors.push({
          rule:     "no-duplicate-names",
          message:  `Duplicate task name: "${task.name}"`,
          severity: "error",
        });
      }
      seen.add(task.name);    // ✅ Fix 17: Actually track seen names
    });
  }

  // ──────────────────────────────────────────────
  //  Run all enabled rules against a task list
  // ──────────────────────────────────────────────
  lint(tasks) {
    // ✅ Fix 18: Reset state so successive runs don't accumulate
    this.errors   = [];
    this.warnings = [];

    for (const task of tasks) {
      if (this.rules["valid-cron"] !== false) {
        this.validateCronExpression(task.cronExpression, task.name);
      }
      if (this.rules["require-error-handler"] !== false) {
        this.requireErrorHandler(task);
      }
      if (this.rules["require-timeout"] !== false) {
        this.requireTimeout(task);
      }
      if (this.rules["require-cleanup"] !== false) {
        this.requireCleanup(task);
      }
    }

