    required_audit_fields:     Vec<String>,
    audit_log_identifiers:     Vec<String>,
    require_error_path_logging: bool,
    excluded_functions:        HashSet<String>,
}

impl Default for AuditLintConfig {
    fn default() -> Self {
        Self {
            sensitive_patterns: vec![
                "create_user".into(),    "delete_user".into(),
                "update_password".into(),"modify_role".into(),
                "grant_permission".into(),"revoke_permission".into(),
                "transfer_funds".into(), "process_payment".into(),
                "update_config".into(),  "delete_record".into(),
            ],
            required_audit_fields: vec![
                "user_id".into(),   "action".into(),
                "timestamp".into(), "resource".into(),
            ],
            audit_log_identifiers: vec![
                "audit_log".into(),         "audit_log!".into(),
                "AuditLogger::log".into(),  "emit_audit_event".into(),
            ],
            require_error_path_logging: true,
            excluded_functions: HashSet::new(),
        }
