}

// ─────────────────────────────────────────────
//  Linter Engine (Fix #3: correct counter types)
// ─────────────────────────────────────────────

struct AuditLinter {
    config:            AuditLintConfig,
    violations:        Vec<LintViolation>,
    files_scanned:     usize,              // Fix #3: was i32
    functions_checked: usize,              // Fix #3: was i32
}

impl AuditLinter {
    fn new(config: AuditLintConfig) -> Self {
        Self {
            config,
            violations: Vec::new(),
            files_scanned: 0,
            functions_checked: 0,
        }
    }

    // ───────────────────────────────────────
    //  Top-level file scanning
    // ───────────────────────────────────────

    fn lint_file(&mut self, path: &Path, source: &str) -> Result<(), LintError> {
        self.files_scanned += 1;

        let functions = self.parse_functions(source)?;

        for func in &functions {
            self.functions_checked += 1;

            if self.is_sensitive_function(func) && !self.is_excluded(func) {
                self.check_audit_logging(path, func);
                self.check_required_fields(path, func);

                if self.config.require_error_path_logging {
                    self.check_error_path_logging(path, func);
                }
            }
        }
        Ok(())
    }

    // ───────────────────────────────────────
    //  Function parser (simplified)
    // ───────────────────────────────────────

    /// Fix #4: Original parser had off-by-one in brace tracking
    ///         and failed to handle string literals containing braces
    fn parse_functions(&self, source: &str) -> Result<Vec<ParsedFunction>, LintError> {
        let mut functions = Vec::new();
        let lines: Vec<&str> = source.lines().collect();
        let mut i = 0;

        while i < lines.len() {
            let line = lines[i].trim();

            // Detect function signatures
            if let Some(func_info) = self.try_parse_fn_signature(line, i) {
                let (name, is_public, attributes) = func_info;

                // Find the opening brace
                let mut brace_line = i;
                while brace_line < lines.len() && !lines[brace_line].contains('{') {
                    brace_line += 1;
                }

                if brace_line >= lines.len() {
                    return Err(LintError::ParseError(format!(
                        "No opening brace found for function `{}` at line {}",
                        name,
                        i + 1
                    )));
                }

                // Fix #4: Correct brace-depth tracking
                //   - Start depth at 0, increment on '{', decrement on '}'
                //   - Skip characters inside string/char literals
                let mut depth: i32 = 0;
                let mut body_lines = Vec::new();
                let mut j = brace_line;

                while j < lines.len() {
                    let current = lines[j];
                    body_lines.push(current.to_string());

                    // Fix #4b: walk char-by-char, respecting strings
                    let mut in_string = false;
                    let mut prev_char = '\0';

                    for ch in current.chars() {
                        match ch {
                            '"' if prev_char != '\\' => in_string = !in_string,
                            '{' if !in_string         => depth += 1,
                            '}' if !in_string         => depth -= 1,
                            _ => {}
                        }
                        prev_char = ch;
                    }

                    // Fix #4c: original used `depth == 0` inside the
                    //   inner loop, breaking too early
                    if depth == 0 {
                        break;          // matched all braces
                    }
                    j += 1;
                }

                // Fix #5: line numbers should be 1-based for reporting
                functions.push(ParsedFunction {
                    name,
                    line_start: i + 1,      // Fix #5: was 0-based
                    line_end:   j + 1,      // Fix #5: was 0-based
                    body_lines,
                    is_public,
                    attributes,
                });

                i = j + 1;                  // resume after the function
                continue;
            }
            i += 1;
        }

        Ok(functions)
    }

    fn try_parse_fn_signature(
        &self,
        line: &str,
        line_idx: usize,
    ) -> Option<(String, bool, Vec<String>)> {
        let trimmed = line.trim();
        let is_public = trimmed.starts_with("pub ");

        // Find "fn <name>"
        let fn_pos = trimmed.find("fn ")?;
        let after_fn = &trimmed[fn_pos + 3..];
        let name_end = after_fn.find(|c: char| c == '(' || c == '<' || c.is_whitespace())?;
        let name = after_fn[..name_end].to_string();

        if name.is_empty() {
            return None;
        }

        // Collect attributes (simplified: look back from current line)
        let attributes = Vec::new();     // full impl would look at prior lines
        Some((name, is_public, attributes))
    }

    // ───────────────────────────────────────
    //  Rule: audit_log call must be present
    // ───────────────────────────────────────

    /// Fix #6: Original used `==` exact match instead of `contains`
    ///         for identifier check, missing calls like
    ///         `audit_log!(action = "create_user", ...)`
    fn check_audit_logging(&mut self, path: &Path, func: &ParsedFunction) {
        let body = func.body_lines.join("\n");

        let has_audit_call = self.config.audit_log_identifiers.iter().any(|id| {
            // Fix #6: use `contains` with trimmed body
            body.contains(id.as_str())
        });

        if !has_audit_call {
            self.violations.push(LintViolation {
                file: path.to_path_buf(),
                line: func.line_start,
                column: 1,
                rule: "audit/missing-audit-log".into(),
                message: format!(
                    "Sensitive function `{}` does not contain an audit log call. \
                     Expected one of: {:?}",
                    func.name, self.config.audit_log_identifiers
                ),
                severity: Severity::Error,
            });
        }
    }

    // ───────────────────────────────────────
    //  Rule: required fields in audit call
    // ───────────────────────────────────────

    /// Fix #7: Original collected missing fields into a `Vec` but
    ///         never checked if the vec was empty before reporting
    fn check_required_fields(&mut self, path: &Path, func: &ParsedFunction) {
        let body = func.body_lines.join("\n");

        // Only check if there IS an audit call
        let has_audit = self.config.audit_log_identifiers.iter().any(|id| body.contains(id.as_str()));
        if !has_audit {
            return;     // separate rule covers the missing-call case
        }

        // Extract the audit call region (simplified: first occurrence)
        let audit_region = self.extract_audit_call_region(&body);

        let missing: Vec<&String> = self
            .config
            .required_audit_fields
            .iter()
            .filter(|field| {
                // Fix #8: original checked `body.contains` instead of
                //         `audit_region.contains`, so fields set outside
                //         the audit call were false positives
                !audit_region.contains(field.as_str())
            })
            .collect();

        // Fix #7: guard against empty vec
        if !missing.is_empty() {
            self.violations.push(LintViolation {
                file: path.to_path_buf(),
                line: func.line_start,
                column: 1,
                rule: "audit/missing-required-fields".into(),
                message: format!(
                    "Audit log in `{}` is missing required fields: {:?}",
                    func.name, missing
                ),
                severity: Severity::Warning,
            });
        }
    }

    /// Extract the text of the first audit-log call (between parens/braces)
    fn extract_audit_call_region(&self, body: &str) -> String {
        for id in &self.config.audit_log_identifiers {
            if let Some(start) = body.find(id.as_str()) {
                let after = &body[start..];
                // Find matching paren/brace
                if let Some(region) = Self::extract_balanced(after, '(', ')') {
                    return region;
                }
                if let Some(region) = Self::extract_balanced(after, '{', '}') {
                    return region;
                }
            }
        }
        String::new()
