class JsonParser {
  /**
   * Parse a JSON string into a structured document object.
   * @param {string} content - Raw JSON string
   * @returns {object} Parsed document
   */
  parse(content) {
    if (typeof content !== "string") {
      throw new TypeError("Content must be a string");
    }

    const trimmed = content.trim();
    if (!trimmed) {
      throw new SyntaxError("Empty content cannot be parsed as JSON");
    }

    try {
      const data = JSON.parse(trimmed);
      return {
        type: "json",
        data,
        metadata: {
          keys: this._extractKeys(data),
          isArray: Array.isArray(data),
          itemCount: Array.isArray(data) ? data.length : Object.keys(data).length,
        },
      };
    } catch (err) {
      throw new SyntaxError(`Invalid JSON: ${err.message}`);
    }
  }

  /**
   * Extract all top-level keys from parsed data.
   */
  _extractKeys(data) {
    if (Array.isArray(data)) {
      // Collect unique keys across all array items
      const keySet = new Set();
      data.forEach((item) => {
        if (item && typeof item === "object" && !Array.isArray(item)) {
          Object.keys(item).forEach((k) => keySet.add(k));
        }
      });
      return [...keySet];
    }

    if (data && typeof data === "object") {
      return Object.keys(data);
    }

    return [];
  }
}

module.exports = JsonParser;
