class CsvParser {
  /**
   * @param {object} options
   * @param {string} options.delimiter - Column delimiter (default: ',')
   * @param {boolean} options.hasHeaders - First row is headers (default: true)
   */
  constructor(options = {}) {
    this.delimiter = options.delimiter || ",";
    this.hasHeaders = options.hasHeaders !== undefined ? options.hasHeaders : true;
  }

  /**
   * Parse CSV content into structured rows.
   * @param {string} content - Raw CSV string
   * @returns {object} Parsed document
   */
  parse(content) {
    if (typeof content !== "string") {
      throw new TypeError("Content must be a string");
    }

    const trimmed = content.trim();
    if (!trimmed) {
      throw new Error("Empty content cannot be parsed as CSV");
    }

    const lines = this._splitLines(trimmed);
    if (lines.length === 0) {
      throw new Error("No valid lines found in CSV");
    }

    let headers = [];
    let dataLines = lines;

    if (this.hasHeaders) {
      headers = this._parseLine(lines[0]);
      dataLines = lines.slice(1);
    }

    const rows = dataLines.map((line) => {
      const values = this._parseLine(line);

      if (this.hasHeaders) {
        // Map values to header keys
        const row = {};
        headers.forEach((header, i) => {
          row[header] = this._castValue(values[i] !== undefined ? values[i] : "");
        });
        return row;
      }

      return values.map(this._castValue);
    });

    return {
      type: "csv",
      data: rows,
      metadata: {
        headers,
        rowCount: rows.length,
        columnCount: headers.length || (rows[0] ? rows[0].length : 0),
        delimiter: this.delimiter,
      },
    };
  }

  /**
   * Split content into individual lines, handling \r\n and \n.
   */
  _splitLines(content) {
    return content
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter((line) => line.length > 0);
  }

  /**
   * Parse a single CSV line, respecting quoted fields.
   */
  _parseLine(line) {
    const fields = [];
    let current = "";
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];

      if (inQuotes) {
        if (char === '"') {
          // Check for escaped quote ""
          if (i + 1 < line.length && line[i + 1] === '"') {
            current += '"';
            i++; // skip next quote
          } else {
            inQuotes = false;
          }
        } else {
          current += char;
        }
      } else if (char === '"') {
        inQuotes = true;
      } else if (char === this.delimiter) {
        fields.push(current.trim());
        current = "";
      } else {
        current += char;
      }
    }

    fields.push(current.trim());
    return fields;
  }

  /**
   * Auto-cast string values to numbers or booleans when appropriate.
   */
  _castValue(value) {
    if (value === "") return "";
    if (value === "true") return true;
    if (value === "false") return false;
    if (value === "null") return null;

    const num = Number(value);
    if (!isNaN(num) && value !== "") return num;

    return value;
  }
}

module.exports = CsvParser;
