class KeyValueParser {
  /**
   * @param {object} options
   * @param {string} options.separator - Key-value separator (default: '=')
   * @param {string} options.commentChar - Comment prefix (default: '#')
   */
  constructor(options = {}) {
    this.separator = options.separator || "=";
    this.commentChar = options.commentChar || "#";
  }

  /**
   * Parse key-value content (e.g., .env or .ini files).
   * @param {string} content - Raw key-value string
   * @returns {object} Parsed document
   */
  parse(content) {
    if (typeof content !== "string") {
      throw new TypeError("Content must be a string");
    }

    const trimmed = content.trim();
    if (!trimmed) {
      return {
        type: "key-value",
        data: {},
        metadata: { keys: [], pairCount: 0 },
      };
    }

    const lines = trimmed.split(/\r?\n/);
    const data = {};
    const errors = [];

    lines.forEach((rawLine, index) => {
      const line = rawLine.trim();

      // Skip empty lines and comments
      if (!line || line.startsWith(this.commentChar)) {
        return;
      }

      const separatorIndex = line.indexOf(this.separator);
      if (separatorIndex === -1) {
        errors.push({ line: index + 1, content: line, error: "Missing separator" });
        return;
      }

      const key = line.substring(0, separatorIndex).trim();
      let value = line.substring(separatorIndex + this.separator.length).trim();

      if (!key) {
        errors.push({ line: index + 1, content: line, error: "Empty key" });
        return;
      }

      // Remove surrounding quotes from values
      value = this._unquote(value);
      data[key] = this._castValue(value);
    });

    return {
      type: "key-value",
      data,
      metadata: {
        keys: Object.keys(data),
        pairCount: Object.keys(data).length,
        errors: errors.length > 0 ? errors : undefined,
      },
    };
  }

  /**
   * Remove wrapping single or double quotes.
   */
  _unquote(value) {
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      return value.slice(1, -1);
    }
    return value;
  }

  /**
   * Cast string values to appropriate JS types.
   */
  _castValue(value) {
    if (value === "true") return true;
    if (value === "false") return false;
    if (value === "null") return null;
    if (value === "") return "";

    const num = Number(value);
    if (!isNaN(num) && value !== "") return num;

    return value;
  }
}

module.exports = KeyValueParser;
