class TextParser {
  /**
   * Parse plain text and extract metadata / structure.
   * @param {string} content - Raw text
   * @returns {object} Parsed document
   */
  parse(content) {
    if (typeof content !== "string") {
      throw new TypeError("Content must be a string");
    }

    const trimmed = content.trim();

    const lines = trimmed ? trimmed.split(/\r?\n/) : [];
    const paragraphs = this._extractParagraphs(trimmed);
    const words = this._extractWords(trimmed);
    const sentences = this._extractSentences(trimmed);
    const headings = this._extractMarkdownHeadings(lines);

    return {
      type: "text",
      data: {
        raw: trimmed,
        lines,
        paragraphs,
        headings,
      },
      metadata: {
        lineCount: lines.length,
        wordCount: words.length,
        charCount: trimmed.length,
        sentenceCount: sentences.length,
        paragraphCount: paragraphs.length,
        headingCount: headings.length,
        averageWordsPerSentence:
          sentences.length > 0
            ? Math.round((words.length / sentences.length) * 10) / 10
            : 0,
      },
    };
  }

  _extractWords(text) {
    if (!text) return [];
    return text.match(/\b[a-zA-Z0-9]+(?:['-][a-zA-Z0-9]+)*\b/g) || [];
  }

  _extractSentences(text) {
    if (!text) return [];
    return text
      .split(/[.!?]+/)
      .map((s) => s.trim())
      .filter((s) => s.length > 0);
  }

  _extractParagraphs(text) {
    if (!text) return [];
    return text
      .split(/\n\s*\n/)
      .map((p) => p.trim())
      .filter((p) => p.length > 0);
  }

  _extractMarkdownHeadings(lines) {
    return lines
      .filter((line) => /^#{1,6}\s+/.test(line.trim()))
      .map((line) => {
        const match = line.trim().match(/^(#{1,6})\s+(.+)$/);
        return {
          level: match[1].length,
          text: match[2].trim(),
        };
      });
  }
}

module.exports = TextParser;
```

### src/parser.js (Main Orchestrator)

```javascript
const JsonParser = require("./parsers/jsonParser");
const CsvParser = require("./parsers/csvParser");
const KeyValueParser = require("./parsers/keyValueParser");
const TextParser = require("./parsers/textParser");

class DocumentParser {
  constructor() {
    this.parsers = {
      json: new JsonParser(),
      csv: new CsvParser(),
      "csv-tsv": new CsvParser({ delimiter: "\t" }),
      "key-value": new KeyValueParser(),
      env: new KeyValueParser({ separator: "=", commentChar: "#" }),
      ini: new KeyValueParser({ separator: "=", commentChar: ";" }),
      text: new TextParser(),
    };
  }

  /**
   * Parse a document with an explicit format.
   * @param {string} content - Raw document content
   * @param {string} format - One of: json, csv, key-value, env, ini, text
   * @returns {object} Parsed result
   */
  parse(content, format) {
    const parser = this.parsers[format];
    if (!parser) {
      throw new Error(
        `Unsupported format: "${format}". Supported: ${Object.keys(this.parsers).join(", ")}`
      );
    }
    return parser.parse(content);
  }

  /**
   * Auto-detect format and parse.
   * @param {string} content - Raw document content
   * @returns {object} Parsed result
   */
  autoParse(content) {
    if (typeof content !== "string") {
      throw new TypeError("Content must be a string");
    }

    const format = this.detectFormat(content);
    return this.parse(content, format);
  }

  /**
   * Detect document format from content.
   * @param {string} content
   * @returns {string} Detected format
   */
  detectFormat(content) {
    const trimmed = content.trim();

    // JSON detection
    if (
      (trimmed.startsWith("{") && trimmed.endsWith("}")) ||
      (trimmed.startsWith("[") && trimmed.endsWith("]"))
    ) {
      try {
        JSON.parse(trimmed);
        return "json";
      } catch {
        // Not valid JSON, continue detection
      }
    }

    const lines = trimmed.split(/\r?\n/).filter((l) => l.trim());

    // CSV detection: multiple lines with consistent comma counts
    if (lines.length > 1) {
      const commaCount = (lines[0].match(/,/g) || []).length;
      if (commaCount > 0) {
        const isConsistent = lines
          .slice(1, 5)
          .every((line) => (line.match(/,/g) || []).length === commaCount);
        if (isConsistent) return "csv";
      }
    }

    // Key-value detection: lines with = separator
    const kvLines = lines.filter((l) => !l.startsWith("#") && l.includes("="));
    if (kvLines.length > 0 && kvLines.length >= lines.filter((l) => !l.startsWith("#")).length * 0.5) {
      return "key-value";
    }

    // Default to text
    return "text";
  }
}

module.exports = DocumentParser;
