        { id: 2, name: "Bob" },
      ]);
      const result = parser.parse(input);

      expect(result.metadata.isArray).toBe(true);
      expect(result.metadata.itemCount).toBe(2);
      expect(result.metadata.keys).toContain("id");
      expect(result.metadata.keys).toContain("name");
    });

    test("parses a JSON array of primitives", () => {
      const result = parser.parse("[1, 2, 3]");

      expect(result.data).toEqual([1, 2, 3]);
      expect(result.metadata.isArray).toBe(true);
      expect(result.metadata.keys).toEqual([]);
    });

    test("parses nested JSON", () => {
      const input = JSON.stringify({
        user: { name: "Alice", address: { city: "NYC" } },
      });
      const result = parser.parse(input);

      expect(result.data.user.address.city).toBe("NYC");
      expect(result.metadata.keys).toEqual(["user"]);
    });

    test("handles whitespace around content", () => {
      const result = parser.parse('  \n  {"key": "value"}  \n  ');

      expect(result.data).toEqual({ key: "value" });
    });

    test("throws TypeError for non-string input", () => {
      expect(() => parser.parse(123)).toThrow(TypeError);
      expect(() => parser.parse(null)).toThrow(TypeError);
      expect(() => parser.parse(undefined)).toThrow(TypeError);
    });

    test("throws SyntaxError for empty string", () => {
      expect(() => parser.parse("")).toThrow(SyntaxError);
      expect(() => parser.parse("   ")).toThrow(SyntaxError);
    });

    test("throws SyntaxError for invalid JSON", () => {
      expect(() => parser.parse("{name: invalid}")).toThrow(SyntaxError);
      expect(() => parser.parse("not json at all")).toThrow(SyntaxError);
    });
  });
});
