## scheduler.js

```javascript
#!/usr/bin/env node

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import readline from "readline";

// ---------- File Storage ----------

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, "tasks.json");

function loadTasks() {
  if (!fs.existsSync(DATA_FILE)) return [];
  const raw = fs.readFileSync(DATA_FILE, "utf-8");
  return JSON.parse(raw);
}

function saveTasks(tasks) {
  fs.writeFileSync(DATA_FILE, JSON.stringify(tasks, null, 2));
}

// ---------- Core Actions ----------

function addTask(description, dateStr, timeStr) {
  const tasks = loadTasks();
  const scheduledAt = new Date(`${dateStr}T${timeStr}`);

  if (isNaN(scheduledAt.getTime())) {
    console.error("❌ Invalid date/time. Use: YYYY-MM-DD HH:MM");
    process.exit(1);
  }

  const task = {
    id: tasks.length ? tasks[tasks.length - 1].id + 1 : 1,
    description,
    scheduledAt: scheduledAt.toISOString(),
    done: false,
    createdAt: new Date().toISOString(),
  };

  tasks.push(task);
  saveTasks(tasks);
  console.log(`✅ Task #${task.id} added for ${scheduledAt.toLocaleString()}`);
}

function listTasks(filter = "all") {
  const tasks = loadTasks();

  const filtered = tasks.filter((t) => {
    if (filter === "pending") return !t.done;
    if (filter === "done") return t.done;
    if (filter === "overdue") return !t.done && new Date(t.scheduledAt) < new Date();
    return true;
  });

  if (!filtered.length) {
    console.log("📭 No tasks found.");
    return;
  }

  console.log(`\n📋 Tasks (${filter}):\n`);
  console.log("ID  | Status  | Scheduled            | Description");
  console.log("----|---------|----------------------|------------");

  filtered.forEach((t) => {
    const status = t.done ? "✔ done " : "⏳ todo";
    const date = new Date(t.scheduledAt).toLocaleString();
    const overdue = !t.done && new Date(t.scheduledAt) < new Date() ? " ⚠️" : "";
    console.log(`${String(t.id).padEnd(4)}| ${status} | ${date.padEnd(21)}| ${t.description}${overdue}`);
  });

  console.log();
}

function completeTask(id) {
  const tasks = loadTasks();
  const task = tasks.find((t) => t.id === id);

  if (!task) {
    console.error(`❌ Task #${id} not found.`);
    process.exit(1);
  }

  task.done = true;
  saveTasks(tasks);
  console.log(`✅ Task #${id} marked as done.`);
}

function removeTask(id) {
  let tasks = loadTasks();
  const before = tasks.length;
  tasks = tasks.filter((t) => t.id !== id);

  if (tasks.length === before) {
    console.error(`❌ Task #${id} not found.`);
    process.exit(1);
  }

  saveTasks(tasks);
  console.log(`🗑️  Task #${id} removed.`);
}

function clearDone() {
  let tasks = loadTasks();
  const before = tasks.length;
  tasks = tasks.filter((t) => !t.done);
  saveTasks(tasks);
  console.log(`🧹 Cleared ${before - tasks.length} completed task(s).`);
}

// ---------- Watch Mode (simple polling scheduler) ----------

function watch(intervalSec = 30) {
  console.log(`👀 Watching for due tasks every ${intervalSec}s... (Ctrl+C to stop)\n`);

  const alerted = new Set();

  const check = () => {
    const tasks = loadTasks();
    const now = new Date();

    tasks.forEach((t) => {
      if (!t.done && !alerted.has(t.id) && new Date(t.scheduledAt) <= now) {
        alerted.add(t.id);
        console.log(`🔔 [${now.toLocaleTimeString()}] DUE → #${t.id}: ${t.description}`);
      }
    });
  };

  check();
  setInterval(check, intervalSec * 1000);
}

// ---------- Interactive Mode ----------

async function interactive() {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  const ask = (q) => new Promise((resolve) => rl.question(q, resolve));

  console.log("\n🗓️  Task Scheduler — Interactive Mode");
  console.log("Commands: add, list, done, remove, clear, quit\n");

  while (true) {
    const cmd = (await ask("➤ ")).trim().toLowerCase();

    switch (cmd) {
      case "add": {
        const desc = await ask("  Description: ");
        const date = await ask("  Date (YYYY-MM-DD): ");
        const time = await ask("  Time (HH:MM): ");
        addTask(desc, date, time);
        break;
      }
      case "list": {
        const filter = (await ask("  Filter (all/pending/done/overdue): ")) || "all";
        listTasks(filter.trim());
        break;
      }
      case "done": {
        const id = parseInt(await ask("  Task ID: "), 10);
        completeTask(id);
        break;
      }
      case "remove": {
        const id = parseInt(await ask("  Task ID: "), 10);
        removeTask(id);
        break;
      }
      case "clear":
        clearDone();
        break;
      case "quit":
      case "exit":
        rl.close();
        console.log("👋 Bye!");
        return;
      default:
        console.log("  Unknown command.");
    }
  }
}

// ---------- CLI Router ----------

function printHelp() {
  console.log(`
🗓️  Task Scheduler CLI

Usage:
  node scheduler.js add <description> <YYYY-MM-DD> <HH:MM>
  node scheduler.js list [all|pending|done|overdue]
  node scheduler.js done <id>
  node scheduler.js remove <id>
  node scheduler.js clear
  node scheduler.js watch [interval_seconds]
  node scheduler.js interactive
  node scheduler.js help
`);
}

// ---------- Main ----------

const [, , command, ...args] = process.argv;

switch (command) {
  case "add":
    if (args.length < 3) {
      console.error("Usage: add <description> <YYYY-MM-DD> <HH:MM>");
      process.exit(1);
    }
    addTask(args.slice(0, -2).join(" "), args.at(-2), args.at(-1));
    break;

  case "list":
    listTasks(args[0] || "all");
    break;

  case "done":
    completeTask(parseInt(args[0], 10));
    break;

  case "remove":
    removeTask(parseInt(args[0], 10));
    break;

  case "clear":
    clearDone();
    break;

  case "watch":
    watch(parseInt(args[0], 10) || 30);
    break;

  case "interactive":
  case "i":
    interactive();
    break;

  case "help":
  case undefined:
  default:
    printHelp();
    break;
}
```

