## `lib/filters.js`

```javascript
export class Filters {
  constructor(bannedWords = [], patterns = []) {
    this.bannedWords = bannedWords.map((w) => w.toLowerCase());
    this.patterns = patterns.map((p) => new RegExp(p, "gi"));
  }

  // --- Individual checks ---

  checkBannedWords(message) {
    const lower = message.toLowerCase();
    const found = this.bannedWords.filter((word) => lower.includes(word));

    return {
      passed: found.length === 0,
      reason: found.length > 0 ? `Banned words found: [${found.join(", ")}]` : null,
    };
  }

  checkExcessiveCaps(message, threshold = 0.7) {
    // Ignore short messages
    if (message.length < 8) return { passed: true, reason: null };

    const letters = message.replace(/[^a-zA-Z]/g, "");
    if (letters.length === 0) return { passed: true, reason: null };

    const capsRatio = letters.replace(/[^A-Z]/g, "").length / letters.length;
    const failed = capsRatio > threshold;

    return {
      passed: !failed,
      reason: failed ? `Excessive caps (${(capsRatio * 100).toFixed(0)}% uppercase)` : null,
    };
  }

  checkSpamPatterns(message) {
    const matches = this.patterns
      .map((p) => ({ pattern: p.source, match: message.match(p) }))
      .filter((r) => r.match);

    return {
      passed: matches.length === 0,
      reason: matches.length > 0 ? `Spam pattern detected: ${matches[0].pattern}` : null,
    };
  }

  checkMessageLength(message, maxLen = 500) {
    const failed = message.length > maxLen;

    return {
      passed: !failed,
      reason: failed ? `Message too long (${message.length}/${maxLen} chars)` : null,
    };
  }

  checkLinkSpam(message, maxLinks = 2) {
    const urlRegex = /https?:\/\/[^\s]+/gi;
    const links = message.match(urlRegex) || [];
    const failed = links.length > maxLinks;

    return {
      passed: !failed,
      reason: failed ? `Too many links (${links.length} found, max ${maxLinks})` : null,
    };
  }

  // --- Run all checks on a single message ---

  analyzeMessage(message) {
    const checks = [
      { name: "Banned Words", ...this.checkBannedWords(message) },
      { name: "Excessive Caps", ...this.checkExcessiveCaps(message) },
      { name: "Spam Patterns", ...this.checkSpamPatterns(message) },
      { name: "Message Length", ...this.checkMessageLength(message) },
      { name: "Link Spam", ...this.checkLinkSpam(message) },
    ];

    const failed = checks.filter((c) => !c.passed);

    return {
      message,
      passed: failed.length === 0,
      severity: this.#calcSeverity(failed),
      checks,
      failures: failed,
    };
  }

  // Private helper
  #calcSeverity(failures) {
    if (failures.length === 0) return "clean";
    if (failures.some((f) => f.name === "Banned Words")) return "high";
    if (failures.length >= 3) return "high";
    if (failures.length >= 2) return "medium";
    return "low";
  }
}
```

## `lib/moderator.js`

```javascript
import { Filters } from "./filters.js";
import { loadConfig, saveConfig } from "./config.js";

export class Moderator {
  constructor() {
    const config = loadConfig();
    this.config = config;
    this.filters = new Filters(config.words, config.patterns);
    this.log = []; // action log
  }

  // Check a single message, return the report
  check(message) {
    const result = this.filters.analyzeMessage(message);

    this.log.push({
      timestamp: new Date().toISOString(),
      message: message.slice(0, 80),
      passed: result.passed,
      severity: result.severity,
    });

    return result;
  }

  // Add a word to the banned list
  addBannedWord(word) {
    const lower = word.toLowerCase();
    if (this.config.words.includes(lower)) {
      return { success: false, reason: `"${lower}" is already banned.` };
    }

    this.config.words.push(lower);
    saveConfig(this.config);
    this.filters = new Filters(this.config.words, this.config.patterns);

    return { success: true, reason: `"${lower}" added to banned list.` };
  }

  // Remove a word from the banned list
  removeBannedWord(word) {
    const lower = word.toLowerCase();
    const idx = this.config.words.indexOf(lower);

    if (idx === -1) {
      return { success: false, reason: `"${lower}" is not in the banned list.` };
    }

    this.config.words.splice(idx, 1);
    saveConfig(this.config);
    this.filters = new Filters(this.config.words, this.config.patterns);

    return { success: true, reason: `"${lower}" removed from banned list.` };
  }

  // List all banned words
  listBannedWords() {
    return [...this.config.words];
  }

  // Return the action log
  getLog() {
    return [...this.log];
  }
}
