## `index.js`

```javascript
#!/usr/bin/env node

import { createInterface } from "readline";
import { Moderator } from "./lib/moderator.js";

const mod = new Moderator();

// ── Colours (basic ANSI) ───────────────────────────
const c = {
  reset: "\x1b[0m",
  red: "\x1b[31m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  cyan: "\x1b[36m",
  dim: "\x1b[2m",
  bold: "\x1b[1m",
};

// ── Helpers ────────────────────────────────────────
function severityColor(severity) {
  const map = { clean: c.green, low: c.yellow, medium: c.yellow, high: c.red };
  return map[severity] || c.reset;
}

function printBanner() {
  console.log(`
${c.cyan}${c.bold}╔══════════════════════════════════╗
║      Chat Moderator CLI          ║
╚══════════════════════════════════╝${c.reset}
${c.dim}Type "help" for available commands.${c.reset}
`);
}

function printHelp() {
  console.log(`
${c.bold}Commands:${c.reset}
  ${c.cyan}check <message>${c.reset}       Analyse a message
  ${c.cyan}add <word>${c.reset}            Add a banned word
  ${c.cyan}remove <word>${c.reset}         Remove a banned word
  ${c.cyan}list${c.reset}                  List all banned words
  ${c.cyan}log${c.reset}                   Show moderation log
  ${c.cyan}batch${c.reset}                 Enter batch mode (one message per line, empty line to finish)
  ${c.cyan}help${c.reset}                  Show this help
  ${c.cyan}exit${c.reset}                  Quit
`);
}

function printReport(result) {
  const icon = result.passed ? `${c.green}✔ PASS` : `${c.red}✘ FAIL`;
  const sev = `${severityColor(result.severity)}${result.severity.toUpperCase()}${c.reset}`;

  console.log(`\n  ${icon}${c.reset}  Severity: ${sev}`);
  console.log(`  ${c.dim}Message: "${result.message.slice(0, 60)}${result.message.length > 60 ? "…" : ""}"${c.reset}`);

  if (result.failures.length > 0) {
    console.log(`  ${c.red}Issues:${c.reset}`);
    result.failures.forEach((f) => {
      console.log(`    - ${f.name}: ${f.reason}`);
    });
  }

  console.log();
}

function printLog(log) {
  if (log.length === 0) {
    console.log(`\n  ${c.dim}No entries yet.${c.reset}\n`);
    return;
  }

  console.log(`\n  ${c.bold}Moderation Log (${log.length} entries):${c.reset}`);
  log.forEach((entry, i) => {
    const icon = entry.passed ? `${c.green}✔${c.reset}` : `${c.red}✘${c.reset}`;
    const sev = `${severityColor(entry.severity)}${entry.severity}${c.reset}`;
    console.log(
      `  ${c.dim}${String(i + 1).padStart(3)}.${c.reset} ${icon} [${sev}] ${c.dim}${entry.timestamp}${c.reset}  "${entry.message}"`
    );
  });
  console.log();
}

// ── Command router ─────────────────────────────────
function handleCommand(line, rl) {
  const trimmed = line.trim();
  if (!trimmed) return;

  const spaceIdx = trimmed.indexOf(" ");
  const cmd = (spaceIdx === -1 ? trimmed : trimmed.slice(0, spaceIdx)).toLowerCase();
  const arg = spaceIdx === -1 ? "" : trimmed.slice(spaceIdx + 1).trim();

  switch (cmd) {
    case "check": {
      if (!arg) {
        console.log(`  ${c.red}Usage: check <message>${c.reset}`);
        break;
      }
      const result = mod.check(arg);
      printReport(result);
      break;
    }

    case "add": {
      if (!arg) {
        console.log(`  ${c.red}Usage: add <word>${c.reset}`);
        break;
      }
      const res = mod.addBannedWord(arg);
      console.log(`  ${res.success ? c.green : c.yellow}${res.reason}${c.reset}`);
      break;
    }

    case "remove": {
      if (!arg) {
        console.log(`  ${c.red}Usage: remove <word>${c.reset}`);
        break;
      }
      const res = mod.removeBannedWord(arg);
      console.log(`  ${res.success ? c.green : c.yellow}${res.reason}${c.reset}`);
      break;
    }

    case "list": {
      const words = mod.listBannedWords();
      if (words.length === 0) {
        console.log(`  ${c.dim}Banned list is empty.${c.reset}`);
      } else {
        console.log(`\n  ${c.bold}Banned words (${words.length}):${c.reset}`);
        words.forEach((w) => console.log(`    • ${w}`));
        console.log();
      }
      break;
    }

    case "log": {
      printLog(mod.getLog());
      break;
    }

    case "batch": {
      console.log(`  ${c.dim}Batch mode — enter messages, empty line to finish:${c.reset}`);
      enterBatchMode(rl);
      return; // don't re-prompt; batch mode handles it
    }

    case "help": {
      printHelp();
      break;
    }

    case "exit":
    case "quit": {
      console.log(`\n${c.cyan}Goodbye!${c.reset}\n`);
      process.exit(0);
    }

    default:
      console.log(`  ${c.yellow}Unknown command: "${cmd}". Type "help" for options.${c.reset}`);
  }
}

// ── Batch mode ─────────────────────────────────────
function enterBatchMode(rl) {
  const messages = [];

  const batchHandler = (line) => {
    if (line.trim() === "") {
      rl.removeListener("line", batchHandler);

      if (messages.length === 0) {
        console.log(`  ${c.dim}No messages entered.${c.reset}\n`);
      } else {
        console.log(`\n  ${c.bold}Batch Results (${messages.length} messages):${c.reset}`);
        messages.forEach((msg) => {
          const result = mod.check(msg);
          const icon = result.passed ? `${c.green}✔${c.reset}` : `${c.red}✘${c.reset}`;
          const sev = `${severityColor(result.severity)}${result.severity}${c.reset}`;
          const reasons = result.failures.map((f) => f.reason).join("; ");
          console.log(`  ${icon} [${sev}] "${msg.slice(0, 50)}" ${c.dim}${reasons}${c.reset}`);
        });
        console.log();
      }

      rl.setPrompt(`${c.cyan}mod>${c.reset} `);
      rl.prompt();
      rl.on("line", mainHandler);
      return;
    }

    messages.push(line);
  };

  rl.removeListener("line", mainHandler);
  rl.setPrompt(`${c.dim}  >> ${c.reset}`);
  rl.prompt();
  rl.on("line", batchHandler);
}

// Keep a reference so we can remove/re-add it in batch mode
let rl;
function mainHandler(line) {
  handleCommand(line, rl);
  rl.prompt();
}

// ── Main ───────────────────────────────────────────
function main() {
  printBanner();

  rl = createInterface({
    input: process.stdin,
    output: process.stdout,
    prompt: `${c.cyan}mod>${c.reset} `,
  });

  rl.prompt();
  rl.on("line", mainHandler);
  rl.on("close", () => {
    console.log(`\n${c.cyan}Goodbye!${c.reset}\n`);
    process.exit(0);
  });
}

main();
