## Step 2: The CSV Reader (Streaming Parser)

```javascript
// src/CsvReader.js
import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';
import { EventEmitter } from 'node:events';

export class CsvReader extends EventEmitter {
  #delimiter;
  #quoteChar;
  #hasHeader;
  #skipEmpty;
  #encoding;

  constructor(options = {}) {
    super();
    this.#delimiter = options.delimiter ?? ',';
    this.#quoteChar = options.quoteChar ?? '"';
    this.#hasHeader = options.hasHeader ?? true;
    this.#skipEmpty = options.skipEmpty ?? true;
    this.#encoding  = options.encoding ?? 'utf-8';
  }

  /**
   * Parse a single CSV line, respecting quoted fields.
   * Handles: escaped quotes, embedded delimiters, multiline (pre-joined).
   */
  parseLine(line) {
    const fields = [];
    let current = '';
    let inQuotes = false;
    const q = this.#quoteChar;
    const d = this.#delimiter;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      const next = line[i + 1];

      if (inQuotes) {
        if (char === q && next === q) {
          // Escaped quote inside quoted field
          current += q;
          i++; // skip next quote
        } else if (char === q) {
          // End of quoted field
          inQuotes = false;
        } else {
          current += char;
        }
      } else {
        if (char === q && current.length === 0) {
          // Start of quoted field
          inQuotes = true;
        } else if (char === d) {
          // Field separator
          fields.push(current.trim());
          current = '';
        } else {
          current += char;
        }
      }
    }

    // Push the last field
    fields.push(current.trim());
    return fields;
  }

  /**
   * Read and parse entire CSV file into memory.
   * Good for small-to-medium files.
   */
  async readAll(filePath) {
    const rows = [];
    let headers = null;

    for await (const { row, headers: h } of this.stream(filePath)) {
      if (!headers) headers = h;
      rows.push(row);
    }

    return { headers, rows };
  }

  /**
   * Async generator that streams rows one at a time.
   * Memory-efficient for large files.
   */
  async *stream(filePath) {
    const fileStream = createReadStream(filePath, {
      encoding: this.#encoding,
    });

    const rl = createInterface({
      input: fileStream,
      crlfDelay: Infinity, // handle \r\n as single newline
    });

    let headers = null;
    let lineNumber = 0;
    let pendingLine = '';

    for await (const rawLine of rl) {
      lineNumber++;

      // Handle multiline quoted fields by detecting unmatched quotes
      const combined = pendingLine ? pendingLine + '\n' + rawLine : rawLine;
      const quoteCount = (combined.match(new RegExp(this.#quoteChar, 'g')) || []).length;

      if (quoteCount % 2 !== 0) {
        // Odd number of quotes → field continues on next line
        pendingLine = combined;
        continue;
      }

      pendingLine = '';
      const line = combined;

      // Skip empty lines
      if (this.#skipEmpty && line.trim().length === 0) continue;

      const fields = this.parseLine(line);

      // First non-empty line becomes headers
      if (this.#hasHeader && headers === null) {
        headers = fields.map(h => this.#normalizeHeader(h));
        this.emit('headers', headers);
        continue;
      }

      // Build a row object (or array if no headers)
      const row = headers
        ? Object.fromEntries(headers.map((h, i) => [h, fields[i] ?? null]))
        : fields;

      this.emit('row', row, lineNumber);
      yield { row, headers, lineNumber };
    }

    if (pendingLine) {
      throw new CsvParseError(
        `Unterminated quoted field at end of file`,
        lineNumber
      );
    }

    this.emit('end', lineNumber);
  }

  /** Normalize header names to snake_case identifiers */
  #normalizeHeader(raw) {
    return raw
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_|_$/g, '');
  }
}

export class CsvParseError extends Error {
  constructor(message, line) {
    super(`CSV Parse Error (line ${line}): ${message}`);
    this.name = 'CsvParseError';
    this.line = line;
  }
}
```

## Step 3: Validators

```javascript
// src/validators.js

/** Create a required-field validator */
export function required(fieldName) {
  return (row, lineNumber) => {
    const value = row[fieldName];
    if (value === null || value === undefined || value.trim() === '') {
      return {
        valid: false,
        field: fieldName,
        message: `"${fieldName}" is required`,
        lineNumber,
      };
    }
    return { valid: true };
  };
}

/** Validate field matches a regex pattern */
export function pattern(fieldName, regex, label) {
  return (row, lineNumber) => {
    const value = row[fieldName];
    if (value && !regex.test(value)) {
      return {
        valid: false,
        field: fieldName,
        message: `"${fieldName}" must match ${label ?? regex.toString()}`,
        lineNumber,
      };
    }
    return { valid: true };
  };
}

/** Validate field is one of allowed values */
export function oneOf(fieldName, allowedValues) {
  const allowed = new Set(allowedValues.map(v => v.toLowerCase()));
  return (row, lineNumber) => {
    const value = row[fieldName];
    if (value && !allowed.has(value.toLowerCase())) {
      return {
        valid: false,
        field: fieldName,
        message: `"${fieldName}" must be one of: ${allowedValues.join(', ')}`,
        lineNumber,
      };
    }
    return { valid: true };
  };
}

/** Validate field is a number within a range */
export function numericRange(fieldName, min = -Infinity, max = Infinity) {
  return (row, lineNumber) => {
    const value = Number(row[fieldName]);
    if (row[fieldName] && (isNaN(value) || value < min || value > max)) {
      return {
        valid: false,
        field: fieldName,
        message: `"${fieldName}" must be a number between ${min} and ${max}`,
        lineNumber,
      };
    }
    return { valid: true };
  };
}

/** Validate uniqueness across all rows (stateful) */
export function unique(fieldName) {
  const seen = new Set();
  return (row, lineNumber) => {
    const value = row[fieldName];
    if (value && seen.has(value)) {
      return {
        valid: false,
        field: fieldName,
        message: `Duplicate "${fieldName}": "${value}"`,
        lineNumber,
      };
    }
    seen.add(value);
    return { valid: true };
  };
}
