// src/transformers.js

/** Rename a column */
export function renameField(from, to) {
  return (row) => {
    if (from in row) {
      row[to] = row[from];
      delete row[from];
    }
    return row;
  };
}

/** Set a default value when field is empty/missing */
export function defaultValue(fieldName, fallback) {
  return (row) => {
    if (!row[fieldName] || row[fieldName].trim() === '') {
      row[fieldName] = typeof fallback === 'function' ? fallback(row) : fallback;
    }
    return row;
  };
}

/** Convert a field's value with a mapping function */
export function mapField(fieldName, fn) {
  return (row) => {
    if (fieldName in row) {
      row[fieldName] = fn(row[fieldName], row);
    }
    return row;
  };
}

/** Add a computed field derived from other fields */
export function computeField(fieldName, fn) {
  return (row) => {
    row[fieldName] = fn(row);
    return row;
  };
}

/** Remove fields from the output */
export function dropFields(...fieldNames) {
  const toDrop = new Set(fieldNames);
  return (row) => {
    for (const field of toDrop) {
      delete row[field];
    }
    return row;
  };
}

/** Parse a date string into ISO format */
export function parseDate(fieldName, inputFormat = 'MM/DD/YYYY') {
  return (row) => {
    const raw = row[fieldName];
    if (!raw) return row;

    // Simple date parsing for common formats
    const parts = raw.split(/[\/\-\.]/);
    let date;

    switch (inputFormat) {
      case 'MM/DD/YYYY':
        date = new Date(parts[2], parts[0] - 1, parts[1]);
        break;
      case 'DD/MM/YYYY':
        date = new Date(parts[2], parts[1] - 1, parts[0]);
        break;
      case 'YYYY-MM-DD':
        date = new Date(parts[0], parts[1] - 1, parts[2]);
        break;
      default:
        date = new Date(raw);
    }

    row[fieldName] = isNaN(date.getTime()) ? raw : date.toISOString();
    return row;
  };
}
