// src/MigrationEngine.js
import { CsvReader } from './CsvReader.js';
import { writeFile, mkdir } from 'node:fs/promises';
import { join } from 'node:path';

export class MigrationEngine {
  #reader;
  #validators;
  #transformers;
  #batchSize;
  #onBatch;
  #dryRun;

  constructor(options = {}) {
    this.#reader       = new CsvReader(options.csv);
    this.#validators   = [];
    this.#transformers  = [];
    this.#batchSize    = options.batchSize ?? 100;
    this.#dryRun       = options.dryRun ?? false;
    this.#onBatch      = options.onBatch ?? null;
  }

  /** Add one or more validators */
  validate(...validators) {
    this.#validators.push(...validators);
    return this; // chainable
  }

  /** Add one or more transform functions */
  transform(...transformers) {
    this.#transformers.push(...transformers);
    return this; // chainable
  }

  /** Set batch handler (e.g., DB insert function) */
  onBatch(handler) {
    this.#onBatch = handler;
    return this;
  }

  /** Execute the migration */
  async run(inputPath, options = {}) {
    const startTime = performance.now();
    const report = {
      inputFile: inputPath,
      dryRun: this.#dryRun,
      totalRows: 0,
      validRows: 0,
      invalidRows: 0,
      errors: [],
      batchesProcessed: 0,
      duration: 0,
    };

    let batch = [];
    const outputRows = [];

    console.log(`\n🚀 Migration started: ${inputPath}`);
    if (this.#dryRun) console.log('   ⚠️  DRY RUN — no data will be written\n');

    for await (const { row, lineNumber } of this.#reader.stream(inputPath)) {
      report.totalRows++;

      // ── Validation ──
      const errors = this.#runValidators(row, lineNumber);
      if (errors.length > 0) {
        report.invalidRows++;
        report.errors.push(...errors);
        this.#logErrors(errors);
        continue;
      }

      // ── Transformation ──
      let transformed = { ...row };
      for (const transform of this.#transformers) {
        transformed = transform(transformed);
      }

      report.validRows++;
      batch.push(transformed);
      outputRows.push(transformed);

      // ── Batch processing ──
      if (batch.length >= this.#batchSize) {
        await this.#processBatch(batch, report);
        batch = [];
      }

      // Progress indicator every 1000 rows
      if (report.totalRows % 1000 === 0) {
        process.stdout.write(`   📊 Processed ${report.totalRows} rows...\r`);
      }
    }

    // Process remaining batch
    if (batch.length > 0) {
      await this.#processBatch(batch, report);
    }

    // Optionally write output file
    if (options.outputPath && !this.#dryRun) {
      await this.#writeOutput(options.outputPath, outputRows, options.outputFormat);
    }

    report.duration = ((performance.now() - startTime) / 1000).toFixed(2);
    this.#printReport(report);

    return report;
  }

  #runValidators(row, lineNumber) {
    const errors = [];
    for (const validator of this.#validators) {
      const result = validator(row, lineNumber);
      if (!result.valid) {
        errors.push(result);
      }
    }
    return errors;
  }

  async #processBatch(batch, report) {
    if (this.#dryRun) {
      report.batchesProcessed++;
      return;
    }

    if (this.#onBatch) {
      try {
        await this.#onBatch(batch, report.batchesProcessed);
        report.batchesProcessed++;
      } catch (err) {
        console.error(`   ❌ Batch ${report.batchesProcessed} failed: ${err.message}`);
        report.errors.push({
          valid: false,
          message: `Batch error: ${err.message}`,
          batch: report.batchesProcessed,
        });
      }
    } else {
      report.batchesProcessed++;
    }
  }

  async #writeOutput(outputPath, rows, format = 'json') {
    await mkdir(join(outputPath, '..'), { recursive: true });

    switch (format) {
      case 'json':
        await writeFile(outputPath, JSON.stringify(rows, null, 2));
        break;

      case 'ndjson':
        const ndjson = rows.map(r => JSON.stringify(r)).join('\n');
        await writeFile(outputPath, ndjson);
        break;

      case 'csv': {
        if (rows.length === 0) break;
        const headers = Object.keys(rows[0]);
        const lines = [
          headers.join(','),
          ...rows.map(row =>
            headers.map(h => {
              const val = String(row[h] ?? '');
              // Quote fields that contain commas or quotes
              return val.includes(',') || val.includes('"')
                ? `"${val.replace(/"/g, '""')}"`
                : val;
            }).join(',')
          ),
        ];
        await writeFile(outputPath, lines.join('\n'));
        break;
      }

      default:
        throw new Error(`Unsupported output format: ${format}`);
    }

    console.log(`   💾 Output written to: ${outputPath}`);
  }

  #logErrors(errors) {
    for (const err of errors) {
      console.error(`   ⚠️  Line ${err.lineNumber}: ${err.message}`);
    }
  }

  #printReport(report) {
    console.log('\n' + '═'.repeat(50));
    console.log('  Migration Report');
    console.log('═'.repeat(50));
    console.log(`  File:         ${report.inputFile}`);
    console.log(`  Dry Run:      ${report.dryRun ? 'Yes' : 'No'}`);
    console.log(`  Total Rows:   ${report.totalRows}`);
    console.log(`  Valid:        ${report.validRows} ✅`);
    console.log(`  Invalid:      ${report.invalidRows} ❌`);
    console.log(`  Batches:      ${report.batchesProcessed}`);
    console.log(`  Duration:     ${report.duration}s`);
    if (report.errors.length > 0) {
      console.log(`  Errors:       ${report.errors.length} (see above)`);
    }
    console.log('═'.repeat(50) + '\n');
  }
}
