import java.util.concurrent.*;
import java.util.*;

public class ReportQueueConsumer {

    // Simple report request
    record ReportRequest(String reportId, String type, Map<String, String> parameters) {}

    // Report result
    record ReportResult(String reportId, String type, String content, String status, long generatedAt) {}

    private final BlockingQueue<ReportRequest> queue;
    private final List<ReportResult> completedReports;
    private final ExecutorService executor;
    private volatile boolean running;

    public ReportQueueConsumer(int queueCapacity, int workerCount) {
        this.queue = new LinkedBlockingQueue<>(queueCapacity);
        this.completedReports = Collections.synchronizedList(new ArrayList<>());
        this.executor = Executors.newFixedThreadPool(workerCount);
        this.running = false;
    }

    // Submit a report request to the queue
    public boolean submit(ReportRequest request) {
        boolean added = queue.offer(request);
        if (added) {
            System.out.printf("[QUEUE] Report '%s' (type=%s) queued. Queue size: %d%n",
                    request.reportId(), request.type(), queue.size());
        } else {
            System.out.printf("[QUEUE] Queue full! Report '%s' rejected.%n", request.reportId());
        }
        return added;
    }

    // Start consuming
    public void start(int consumerCount) {
        running = true;
        System.out.printf("[CONSUMER] Starting %d consumer(s)...%n", consumerCount);

        for (int i = 0; i < consumerCount; i++) {
            final int consumerId = i + 1;
            executor.submit(() -> consumeLoop(consumerId));
        }
    }

    // Stop consuming
    public void stop() {
        running = false;
        executor.shutdown();
        try {
            if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
        System.out.println("[CONSUMER] Stopped.");
    }

    private void consumeLoop(int consumerId) {
        System.out.printf("[CONSUMER-%d] Ready and waiting for reports...%n", consumerId);

        while (running) {
            try {
                ReportRequest request = queue.poll(1, TimeUnit.SECONDS);
                if (request != null) {
                    processReport(consumerId, request);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        System.out.printf("[CONSUMER-%d] Shutting down.%n", consumerId);
    }

    private void processReport(int consumerId, ReportRequest request) {
        System.out.printf("[CONSUMER-%d] Generating report '%s' (type=%s)...%n",
                consumerId, request.reportId(), request.type());

        long start = System.currentTimeMillis();

        try {
            // Simulate report generation work
            String content = generateReport(request);
            long elapsed = System.currentTimeMillis() - start;

            ReportResult result = new ReportResult(
                    request.reportId(), request.type(), content, "SUCCESS", System.currentTimeMillis());
            completedReports.add(result);

            System.out.printf("[CONSUMER-%d] Report '%s' completed in %dms (%d bytes)%n",
                    consumerId, request.reportId(), elapsed, content.length());

        } catch (Exception e) {
            ReportResult result = new ReportResult(
                    request.reportId(), request.type(), null, "FAILED: " + e.getMessage(), System.currentTimeMillis());
            completedReports.add(result);

            System.out.printf("[CONSUMER-%d] Report '%s' FAILED: %s%n",
                    consumerId, request.reportId(), e.getMessage());
        }
    }

    private String generateReport(ReportRequest request) throws InterruptedException {
        // Simulate varying generation times based on report type
        int delay = switch (request.type()) {
            case "summary" -> 500;
            case "detailed" -> 1500;
            case "analytics" -> 2000;
            default -> 800;
        };

        Thread.sleep(delay + ThreadLocalRandom.current().nextInt(500));

        // Build mock report content
        StringBuilder sb = new StringBuilder();
        sb.append("=== REPORT: ").append(request.reportId()).append(" ===\n");
        sb.append("Type: ").append(request.type()).append("\n");
        sb.append("Generated: ").append(new Date()).append("\n");
        sb.append("Parameters: ").append(request.parameters()).append("\n");
        sb.append("\n--- DATA ---\n");

        int rows = ThreadLocalRandom.current().nextInt(10, 50);
        for (int i = 1; i <= rows; i++) {
            sb.append(String.format("Row %3d | Value: %6.2f | Status: %s%n",
                    i,
                    ThreadLocalRandom.current().nextDouble(1000),
                    ThreadLocalRandom.current().nextBoolean() ? "ACTIVE" : "INACTIVE"));
        }

        sb.append("\nTotal rows: ").append(rows).append("\n");
        sb.append("=== END REPORT ===\n");

        return sb.toString();
    }

    // Get all completed reports
    public List<ReportResult> getCompletedReports() {
        return new ArrayList<>(completedReports);
    }

    // Get queue size
    public int getQueueSize() {
        return queue.size();
    }

    // --- Demo ---
    public static void main(String[] args) throws InterruptedException {
        ReportQueueConsumer consumer = new ReportQueueConsumer(100, 4);

        // Start 2 consumer threads
        consumer.start(2);

        // Simulate producers submitting report requests
        String[] types = {"summary", "detailed", "analytics", "summary", "detailed"};
        for (int i = 1; i <= 5; i++) {
            Map<String, String> params = Map.of(
                    "startDate", "2024-01-01",
                    "endDate", "2024-12-31",
                    "department", "dept-" + i
            );
            consumer.submit(new ReportRequest("RPT-" + i, types[i - 1], params));
        }

        // Wait for processing
        System.out.println("\n[MAIN] Waiting for reports to complete...\n");
        while (consumer.getCompletedReports().size() < 5) {
            Thread.sleep(500);
            System.out.printf("[MAIN] Progress: %d/5 completed, %d in queue%n",
                    consumer.getCompletedReports().size(), consumer.getQueueSize());
        }

        // Print summary
        System.out.println("\n=== COMPLETED REPORTS SUMMARY ===");
        for (ReportResult result : consumer.getCompletedReports()) {
            System.out.printf("  %s [%s] - %s - %s%n",
                    result.reportId(),
                    result.type(),
                    result.status(),
                    result.content() != null ? result.content().length() + " bytes" : "no content");
        }

        consumer.stop();
    }
}
