import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic();

const moderationQueue = [];
let processing = false;

function enqueue(message) {
  moderationQueue.push({
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    text: message,
    status: "pending",
    result: null,
  });
  console.log(`[ENQUEUED] "${message.slice(0, 50)}..." (Queue size: ${moderationQueue.length})`);
  processQueue();
}

async function moderateMessage(item) {
  const response = await client.messages.create({
    model: "claude-sonnet-4-20250514",
    max_tokens: 256,
    messages: [
      {
        role: "user",
        content: `You are a chat moderator. Evaluate the following message and respond with a JSON object containing:
- "action": one of "allow", "flag", or "block"
- "reason": brief explanation

Rules:
- Block messages with hate speech, threats, or explicit content
- Flag messages with mild profanity, spam-like patterns, or borderline content
- Allow everything else

Message to evaluate: "${item.text}"

Respond ONLY with the JSON object.`,
      },
    ],
  });

  const text = response.content[0].text.trim();
  return JSON.parse(text);
}

async function processQueue() {
  if (processing || moderationQueue.length === 0) return;

  processing = true;

  while (moderationQueue.length > 0) {
    const item = moderationQueue.shift();
    item.status = "processing";
    console.log(`[PROCESSING] id=${item.id} "${item.text.slice(0, 50)}..."`);

    try {
      const result = await moderateMessage(item);
      item.status = "done";
      item.result = result;
      console.log(
        `[RESULT] id=${item.id} action=${result.action} reason="${result.reason}"`
      );
    } catch (err) {
      item.status = "error";
      item.result = { action: "flag", reason: "Moderation error, flagged for manual review" };
      console.error(`[ERROR] id=${item.id} ${err.message}`);
    }
  }

  processing = false;
  console.log("[IDLE] Queue empty, waiting for messages...\n");
}

