  const testMessages = [
    "Hey everyone! How's your day going?",
    "I will find you and make you regret everything.",
    "Check out my website buy cheap stuff now!!! Click here!!!",
    "This game is so damn frustrating sometimes",
    "Great tutorial, thanks for sharing!",
    "You are the worst kind of human garbage and should not exist",
    "Anyone want to team up for the raid tonight?",
  ];

  console.log("=== Chat Moderation Queue Consumer ===\n");

  for (const msg of testMessages) {
    enqueue(msg);
  }

  // Wait for processing to finish
  while (processing || moderationQueue.length > 0) {
    await new Promise((resolve) => setTimeout(resolve, 100));
