const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

class FileSync {
  /**
   * @param {object} options
   * @param {boolean} options.deleteOrphans - Remove dest files not in source
   * @param {string[]} options.exclude      - Glob patterns to exclude
   * @param {boolean} options.dryRun        - Log actions without executing
   * @param {function} options.logger       - Custom logger function
   */
  constructor(options = {}) {
    this.deleteOrphans = options.deleteOrphans || false;
    this.exclude = options.exclude || [];
    this.dryRun = options.dryRun || false;
    this.logger = options.logger || console.log;
    this.stats = this._resetStats();
  }

  // ─── Public API ──────────────────────────────────────────

  /**
   * Synchronize source directory → destination directory.
   * Returns a stats object summarizing what happened.
   */
  sync(source, destination) {
    this.stats = this._resetStats();

    this._validateDirectory(source, "Source");

    if (!fs.existsSync(destination)) {
      if (!this.dryRun) {
        fs.mkdirSync(destination, { recursive: true });
      }
      this._log(`Created destination directory: ${destination}`);
    }

    this._syncDirectory(source, destination);

    if (this.deleteOrphans) {
      this._removeOrphans(source, destination);
    }

    return { ...this.stats };
  }

  /**
   * Compute the MD5 checksum of a single file.
   */
  getFileChecksum(filePath) {
    const content = fs.readFileSync(filePath);
    return crypto.createHash("md5").update(content).digest("hex");
  }

  /**
   * Compare two files by size + checksum.
   * Returns true when the files are identical.
   */
  filesAreEqual(fileA, fileB) {
    if (!fs.existsSync(fileA) || !fs.existsSync(fileB)) {
      return false;
    }

    const statA = fs.statSync(fileA);
    const statB = fs.statSync(fileB);

    // Quick reject: different sizes → definitely different
    if (statA.size !== statB.size) {
      return false;
    }

    return this.getFileChecksum(fileA) === this.getFileChecksum(fileB);
  }

  /**
   * Build a manifest { relativePath → checksum } for a directory tree.
   */
  buildManifest(directory) {
    const manifest = {};

    const walk = (dir, relative = "") => {
      const entries = fs.readdirSync(dir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        const relPath = path.join(relative, entry.name);

        if (this._isExcluded(relPath)) continue;

        if (entry.isDirectory()) {
          walk(fullPath, relPath);
        } else if (entry.isFile()) {
          manifest[relPath] = {
            checksum: this.getFileChecksum(fullPath),
            size: fs.statSync(fullPath).size,
            modified: fs.statSync(fullPath).mtime.toISOString(),
          };
        }
      }
    };

    walk(directory);
    return manifest;
  }

  // ─── Private helpers ─────────────────────────────────────

  _resetStats() {
    return {
      filesCreated: 0,
      filesUpdated: 0,
      filesDeleted: 0,
      directoriesCreated: 0,
      directoriesDeleted: 0,
      filesSkipped: 0,
      errors: [],
    };
  }

  _validateDirectory(dir, label) {
    if (!fs.existsSync(dir)) {
      throw new Error(`${label} directory does not exist: ${dir}`);
    }
    if (!fs.statSync(dir).isDirectory()) {
      throw new Error(`${label} path is not a directory: ${dir}`);
    }
  }

  _isExcluded(relativePath) {
    const normalized = relativePath.replace(/\\/g, "/");
    return this.exclude.some((pattern) => {
      if (pattern.startsWith("*.")) {
        const ext = pattern.slice(1); // e.g. ".tmp"
        return normalized.endsWith(ext);
      }
      return normalized.includes(pattern);
    });
  }

  _log(message) {
    if (this.logger) {
      this.logger(`[FileSync] ${message}`);
    }
  }

  /**
   * Recursively copy new / modified files from src → dest.
   */
  _syncDirectory(source, destination) {
    let entries;
    try {
      entries = fs.readdirSync(source, { withFileTypes: true });
    } catch (err) {
      this.stats.errors.push({ path: source, error: err.message });
      return;
    }

    for (const entry of entries) {
      const srcPath = path.join(source, entry.name);
      const destPath = path.join(destination, entry.name);
      const relPath = path.relative(
        path.resolve(source, ".."),
        srcPath
      );

      if (this._isExcluded(entry.name) || this._isExcluded(relPath)) {
        this.stats.filesSkipped++;
        this._log(`Skipped (excluded): ${relPath}`);
        continue;
      }

      try {
        if (entry.isDirectory()) {
          this._syncSubdirectory(srcPath, destPath, relPath);
        } else if (entry.isFile()) {
          this._syncFile(srcPath, destPath, relPath);
        }
      } catch (err) {
        this.stats.errors.push({ path: srcPath, error: err.message });
        this._log(`Error processing ${srcPath}: ${err.message}`);
      }
    }
  }

  _syncSubdirectory(srcPath, destPath, relPath) {
    if (!fs.existsSync(destPath)) {
      if (!this.dryRun) {
        fs.mkdirSync(destPath, { recursive: true });
      }
      this.stats.directoriesCreated++;
      this._log(`Created directory: ${relPath}`);
    }
    this._syncDirectory(srcPath, destPath);
  }

  _syncFile(srcPath, destPath, relPath) {
    if (!fs.existsSync(destPath)) {
      // New file
      if (!this.dryRun) {
        fs.copyFileSync(srcPath, destPath);
      }
      this.stats.filesCreated++;
      this._log(`Copied (new): ${relPath}`);
    } else if (!this.filesAreEqual(srcPath, destPath)) {
      // Modified file
      if (!this.dryRun) {
        fs.copyFileSync(srcPath, destPath);
      }
      this.stats.filesUpdated++;
      this._log(`Copied (updated): ${relPath}`);
    } else {
      this.stats.filesSkipped++;
      this._log(`Skipped (unchanged): ${relPath}`);
    }
  }

  /**
   * Delete files/dirs in dest that have no counterpart in source.
   */
  _removeOrphans(source, destination) {
    let entries;
    try {
      entries = fs.readdirSync(destination, { withFileTypes: true });
    } catch {
      return;
    }

    for (const entry of entries) {
      const srcPath = path.join(source, entry.name);
      const destPath = path.join(destination, entry.name);

      if (!fs.existsSync(srcPath)) {
        try {
          if (entry.isDirectory()) {
            if (!this.dryRun) {
              fs.rmSync(destPath, { recursive: true, force: true });
            }
            this.stats.directoriesDeleted++;
            this._log(`Deleted orphan directory: ${destPath}`);
          } else {
            if (!this.dryRun) {
              fs.unlinkSync(destPath);
            }
            this.stats.filesDeleted++;
            this._log(`Deleted orphan file: ${destPath}`);
          }
        } catch (err) {
          this.stats.errors.push({ path: destPath, error: err.message });
        }
      } else if (entry.isDirectory()) {
        this._removeOrphans(srcPath, destPath);
      }
    }
  }
}

module.exports = FileSync;
