/** Create a unique temp directory for each test. */
function createTempDir(prefix = "filesync-test-") {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

/** Write a file (creating intermediate dirs if needed). */
function writeFile(dir, relativePath, content = "") {
  const fullPath = path.join(dir, relativePath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, content, "utf-8");
  return fullPath;
}

/** Read a file's text content. */
function readFile(dir, relativePath) {
  return fs.readFileSync(path.join(dir, relativePath), "utf-8");
}

/** Does the relative path exist inside dir? */
function exists(dir, relativePath) {
  return fs.existsSync(path.join(dir, relativePath));
}

/** Recursively delete a directory. */
function cleanup(dir) {
  if (dir && fs.existsSync(dir)) {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

