}

#[derive(Serialize)]
struct ErrorResponse {
    error: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    details: Option<String>,
}

// FIX 3: Use tokio::sync::Mutex for safe use across .await
// FIX 7: Combine into a single struct → single lock = no deadlock
struct AppState {
    inner: Mutex<AppStateInner>,
}

struct AppStateInner {
    reports: Vec<Report>,
    next_id: u32,
