// FIX 4: All handlers are `async fn`
async fn generate_report(
    body: web::Json<ReportRequest>,
    data: web::Data<AppState>,
) -> HttpResponse {

    // FIX 5: Graceful date parsing with proper error responses
    let start = match NaiveDate::parse_from_str(&body.start_date, "%Y-%m-%d") {
        Ok(d) => d,
        Err(e) => {
            return HttpResponse::BadRequest().json(ErrorResponse {
                error: "Invalid start_date".into(),
                details: Some(format!("Expected YYYY-MM-DD, got: {}. Parse error: {}", body.start_date, e)),
            });
        }
    };

    let end = match NaiveDate::parse_from_str(&body.end_date, "%Y-%m-%d") {
        Ok(d) => d,
        Err(e) => {
            return HttpResponse::BadRequest().json(ErrorResponse {
                error: "Invalid end_date".into(),
                details: Some(format!("Expected YYYY-MM-DD, got: {}. Parse error: {}", body.end_date, e)),
            });
        }
    };

    // FIX 6: Correct comparison — reject when start is AFTER end
    if start > end {
        return HttpResponse::BadRequest().json(ErrorResponse {
            error: "start_date must be before or equal to end_date".into(),
            details: None,
        });
    }

    // Validate report type
    let valid_types = ["sales", "inventory", "users", "financial"];
    if !valid_types.contains(&body.report_type.as_str()) {
        return HttpResponse::BadRequest().json(ErrorResponse {
            error: format!("Invalid report_type: '{}'", body.report_type),
            details: Some(format!("Valid types: {:?}", valid_types)),
        });
    }

    // FIX 7: Single lock — no deadlock possible
    let mut state = data.inner.lock().await;

    let report = Report {
        id: state.next_id,
        title: format!("{} Report: {} to {}", capitalize(&body.report_type), body.start_date, body.end_date),
        content: generate_content(&body.report_type, start, end),
        generated_at: Utc::now().to_rfc3339(),
        status: ReportStatus::Completed,
    };

    state.next_id += 1;                          // FIX 8: Increment the counter!
    state.reports.push(report.clone());

    // Drop lock before responding (good practice, Rust does this automatically here)
    drop(state);

    // FIX 9: 201 Created for new resources
    HttpResponse::Created().json(report)
}

async fn get_report(
    path: web::Path<u32>,
    data: web::Data<AppState>,
) -> HttpResponse {
    let report_id = path.into_inner();
    let state = data.inner.lock().await;

    // FIX 10: Search by report.id field, not by vector index
    match state.reports.iter().find(|r| r.id == report_id) {
        Some(report) => HttpResponse::Ok().json(report),
        // FIX 11: Proper 404 with JSON body
        None => HttpResponse::NotFound().json(ErrorResponse {
            error: format!("Report with id {} not found", report_id),
            details: None,
        }),
    }
}

async fn list_reports(
    query: web::Query<HashMap<String, String>>,
    data: web::Data<AppState>,
) -> HttpResponse {
    let state = data.inner.lock().await;

    let reports: Vec<&Report> = if let Some(status_filter) = query.get("status") {
        state.reports.iter().filter(|r| {
            let status_str = serde_json::to_string(&r.status)
                .unwrap_or_default()
                .trim_matches('"')
                .to_string();
            &status_str == status_filter
        }).collect()
    } else {
        state.reports.iter().collect()
    };

    HttpResponse::Ok().json(reports)
}

async fn delete_report(
    path: web::Path<u32>,
    data: web::Data<AppState>,
) -> HttpResponse {
    let report_id = path.into_inner();
    let mut state = data.inner.lock().await;

    let len_before = state.reports.len();
    state.reports.retain(|r| r.id != report_id);

    if state.reports.len() < len_before {
        HttpResponse::NoContent().finish()        // 204 for successful delete
    } else {
        HttpResponse::NotFound().json(ErrorResponse {
            error: format!("Report with id {} not found", report_id),
            details: None,
        })
    }
}

async fn export_report(
    path: web::Path<u32>,
    query: web::Query<HashMap<String, String>>,
    data: web::Data<AppState>,
) -> HttpResponse {
    let report_id = path.into_inner();

    // FIX 3 (cont.): Clone the data we need, then DROP the lock before .await
    let report_clone = {
        let state = data.inner.lock().await;
        state.reports.iter().find(|r| r.id == report_id).cloned()
    };  // ← Lock is released here, BEFORE any .await on I/O

    let format = query.get("format").map(|s| s.as_str()).unwrap_or("csv");

    match report_clone {
        Some(report) => {
            match format {
                "csv" => {
                    let csv = format!(
                        "id,title,status,generated_at\n{},\"{}\",\"{:?}\",\"{}\"",
                        report.id, report.title, report.status, report.generated_at
                    );

                    let file_name = format!("/tmp/report_{}.csv", report_id);
                    if let Err(e) = fs::write(&file_name, &csv).await {
                        return HttpResponse::InternalServerError().json(ErrorResponse {
                            error: "Failed to write export file".into(),
                            details: Some(e.to_string()),
                        });
                    }

                    HttpResponse::Ok()
                        // FIX 12: Correct Content-Type for CSV
                        .content_type("text/csv; charset=utf-8")
                        .insert_header(("Content-Disposition",
                            format!("attachment; filename=\"report_{}.csv\"", report_id)))
                        .body(csv)
                }
                "json" => {
                    HttpResponse::Ok()
                        .content_type("application/json")
                        .json(&report)
                }
                _ => HttpResponse::BadRequest().json(ErrorResponse {
                    error: format!("Unsupported export format: '{}'", format),
                    details: Some("Supported formats: csv, json".into()),
                }),
            }
        }
        None => HttpResponse::NotFound().json(ErrorResponse {
            error: format!("Report with id {} not found", report_id),
            details: None,
        }),
    }
}

// ---------- Helpers ----------

fn generate_content(report_type: &str, start: NaiveDate, end: NaiveDate) -> String {
    let days = (end - start).num_days();
    match report_type {
        "sales"     => format!("Sales data from {} to {} ({} days, 0 records processed)", start, end, days),
        "inventory" => format!("Inventory snapshot from {} to {} ({} days)", start, end, days),
        "users"     => format!("User activity from {} to {} ({} days)", start, end, days),
        "financial" => format!("Financial summary from {} to {} ({} days)", start, end, days),
        other       => format!("Unknown report type: {}", other),
    }
}

fn capitalize(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        None    => String::new(),
        Some(c) => c.to_uppercase().to_string() + chars.as_str(),
    }
}

// ---------- Main ----------

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    log::info!("Starting report server on http://127.0.0.1:8080");

    let state = web::Data::new(AppState {
        inner: Mutex::new(AppStateInner {
            reports: Vec::new(),
            next_id: 1,
        }),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .app_data(
                web::JsonConfig::default()
                    .error_handler(|err, _req| {
                        let resp = HttpResponse::BadRequest().json(ErrorResponse {
                            error: "Invalid JSON payload".into(),
                            details: Some(err.to_string()),
                        });
                        actix_web::error::InternalError::from_response(err, resp).into()
                    })
            )
            .wrap(middleware::Logger::default())
            // REST routes
            .route("/reports",              web::post().to(generate_report))
            .route("/reports",              web::get().to(list_reports))
            .route("/reports/{id}",         web::get().to(get_report))
            .route("/reports/{id}",         web::delete().to(delete_report))
            .route("/reports/{id}/export",  web::get().to(export_report))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}

