## `src/audit-log-writer.ts` — Log Writer with Rotation

```typescript
import fs from "fs";
import fsp from "fs/promises";
import path from "path";
import { AuditEntry, AuditLogWriter } from "./types";

export class FileAuditLogWriter implements AuditLogWriter {
  private currentStream: fs.WriteStream | null = null;
  private currentLogPath = "";
  private bytesWritten = 0;
  private writeQueue: Promise<void> = Promise.resolve();

  constructor(
    private logDir: string,
    private maxLogSize: number = 10 * 1024 * 1024 // 10 MB default
  ) {}

  async init(): Promise<void> {
    await fsp.mkdir(this.logDir, { recursive: true });
    await this.rotateIfNeeded();
  }

  async write(entry: AuditEntry): Promise<void> {
    // Serialize writes to prevent interleaving
    this.writeQueue = this.writeQueue.then(() => this.doWrite(entry));
    return this.writeQueue;
  }

  private async doWrite(entry: AuditEntry): Promise<void> {
    await this.rotateIfNeeded();

    const line = JSON.stringify(entry) + "\n";
    const buf = Buffer.from(line, "utf-8");

    return new Promise((resolve, reject) => {
      if (!this.currentStream) {
        reject(new Error("Log stream not initialized"));
        return;
      }
      this.currentStream.write(buf, (err) => {
        if (err) {
          reject(err);
        } else {
          this.bytesWritten += buf.byteLength;
          resolve();
        }
      });
    });
  }

  private async rotateIfNeeded(): Promise<void> {
    if (this.currentStream && this.bytesWritten < this.maxLogSize) {
      return;
    }

    // Close existing stream
    if (this.currentStream) {
      await this.closeStream(this.currentStream);
    }

    // Create new log file with timestamp
    const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
    this.currentLogPath = path.join(this.logDir, `audit-${timestamp}.jsonl`);
    this.currentStream = fs.createWriteStream(this.currentLogPath, {
      flags: "a",
      encoding: "utf-8",
    });
    this.bytesWritten = 0;

    // Check if file already exists and has content
    try {
      const stat = await fsp.stat(this.currentLogPath);
      this.bytesWritten = stat.size;
    } catch {
      // New file, size is 0
    }
  }

  async flush(): Promise<void> {
    await this.writeQueue;
  }

  async close(): Promise<void> {
    await this.writeQueue;
    if (this.currentStream) {
      await this.closeStream(this.currentStream);
      this.currentStream = null;
    }
  }

  private closeStream(stream: fs.WriteStream): Promise<void> {
    return new Promise((resolve, reject) => {
      stream.end((err?: Error) => {
        if (err) reject(err);
        else resolve();
      });
    });
  }
}
```

## `src/hasher.ts` — File Hashing

```typescript
import { createHash } from "crypto";
import { createReadStream } from "fs";

/**
 * Compute SHA-256 hash of a file. Returns null if file is unreadable.
 */
export function hashFile(filePath: string): Promise<string | null> {
  return new Promise((resolve) => {
    const hash = createHash("sha256");
    const stream = createReadStream(filePath);

    stream.on("data", (chunk) => hash.update(chunk));
    stream.on("end", () => resolve(hash.digest("hex")));
    stream.on("error", () => resolve(null));
  });
}
```

## `src/audit-watcher.ts` — Main Watcher

```typescript
import chokidar, { FSWatcher } from "chokidar";
import { randomUUID } from "crypto";
import fsp from "fs/promises";
import path from "path";
import { AuditEntry, FileEvent, WatcherConfig, AuditLogWriter } from "./types";
import { FileAuditLogWriter } from "./audit-log-writer";
import { hashFile } from "./hasher";

type EventCallback = (entry: AuditEntry) => void;

export class AuditFileWatcher {
  private watcher: FSWatcher | null = null;
  private writer: AuditLogWriter;
  private listeners: EventCallback[] = [];
  private recentlyDeleted = new Map<string, { path: string; time: number }>();
  private config: Required<WatcherConfig>;

  constructor(config: WatcherConfig) {
    this.config = {
      paths: config.paths,
      ignored: config.ignored ?? ["**/node_modules/**", "**/.git/**"],
      logDir: config.logDir,
      maxLogSize: config.maxLogSize ?? 10 * 1024 * 1024,
      hashFiles: config.hashFiles ?? true,
      debounceMs: config.debounceMs ?? 300,
      userId: config.userId ?? process.env.USER ?? "unknown",
      recursive: config.recursive ?? true,
    };

    this.writer = new FileAuditLogWriter(
      this.config.logDir,
      this.config.maxLogSize
    );
  }

  /** Subscribe to audit events in real time */
  onEntry(cb: EventCallback): () => void {
    this.listeners.push(cb);
    return () => {
      this.listeners = this.listeners.filter((l) => l !== cb);
    };
  }

  async start(): Promise<void> {
    if (this.watcher) {
      throw new Error("Watcher already running");
    }

    await (this.writer as FileAuditLogWriter).init();

    this.watcher = chokidar.watch(this.config.paths, {
      ignored: this.config.ignored,
      persistent: true,
      ignoreInitial: true, // Don't fire for existing files on startup
      awaitWriteFinish: {
        stabilityThreshold: this.config.debounceMs,
        pollInterval: 100,
      },
      depth: this.config.recursive ? undefined : 0,
    });

    this.watcher
      .on("add", (fp) => this.handleEvent("created", fp))
      .on("change", (fp) => this.handleEvent("modified", fp))
      .on("unlink", (fp) => this.handleEvent("deleted", fp))
      .on("error", (err) => console.error("[AuditWatcher] Error:", err));

    console.log(`[AuditWatcher] Watching: ${this.config.paths.join(", ")}`);
    console.log(`[AuditWatcher] Logs: ${this.config.logDir}`);
  }

  async stop(): Promise<void> {
    if (this.watcher) {
      await this.watcher.close();
      this.watcher = null;
    }
    await this.writer.close();
    console.log("[AuditWatcher] Stopped");
  }

  private async handleEvent(event: FileEvent, filePath: string): Promise<void> {
    // Simple rename detection: if a delete is quickly followed by a create
    // with the same size, treat it as a rename
    if (event === "deleted") {
      this.recentlyDeleted.set(filePath, { path: filePath, time: Date.now() });
      // Wait briefly to see if a create follows
      setTimeout(() => this.recentlyDeleted.delete(filePath), 500);
    }

    const resolvedPath = path.resolve(filePath);
    const relativePath = this.getRelativePath(resolvedPath);

    let size: number | null = null;
    let hash: string | null = null;

    if (event !== "deleted") {
      try {
        const stat = await fsp.stat(resolvedPath);
        size = stat.size;

        // Skip directories — chokidar handles files within them
        if (stat.isDirectory()) return;
      } catch {
        // File may have been deleted between event and stat
        return;
      }

      if (this.config.hashFiles) {
        hash = await hashFile(resolvedPath);
      }
    }

    const entry: AuditEntry = {
      id: randomUUID(),
      timestamp: new Date().toISOString(),
      event,
      path: resolvedPath,
      relativePath,
      size,
      hash,
      userId: this.config.userId,
    };

    // Write to log file
    try {
      await this.writer.write(entry);
    } catch (err) {
      console.error("[AuditWatcher] Failed to write log entry:", err);
    }

    // Notify subscribers
    for (const cb of this.listeners) {
      try {
        cb(entry);
      } catch (err) {
        console.error("[AuditWatcher] Listener error:", err);
      }
    }
  }

  private getRelativePath(absPath: string): string {
    for (const watchedPath of this.config.paths) {
      const resolved = path.resolve(watchedPath);
      if (absPath.startsWith(resolved)) {
        return path.relative(resolved, absPath);
      }
    }
    return absPath;
  }
}
```

## `src/log-reader.ts` — Query Past Audit Logs

```typescript
import fsp from "fs/promises";
import path from "path";
import readline from "readline";
import fs from "fs";
import { AuditEntry, FileEvent } from "./types";

export interface LogQuery {
  /** Filter by event types */
  events?: FileEvent[];
  /** Only entries after this date */
  after?: Date;
  /** Only entries before this date */
  before?: Date;
  /** Substring match on path */
  pathContains?: string;
  /** Limit number of results */
  limit?: number;
}

export class AuditLogReader {
  constructor(private logDir: string) {}

  /**
   * Read and query audit logs. Streams through files
   * so memory stays flat even with large logs.
   */
  async query(filter: LogQuery = {}): Promise<AuditEntry[]> {
    const files = await this.getLogFiles();
    const results: AuditEntry[] = [];
    const limit = filter.limit ?? Infinity;

    for (const file of files) {
      if (results.length >= limit) break;

      const entries = await this.readLogFile(file, filter);
      results.push(...entries);
    }

    return results.slice(0, limit);
  }

  /** Stream entries one by one — good for large logs */
  async *stream(filter: LogQuery = {}): AsyncGenerator<AuditEntry> {
    const files = await this.getLogFiles();
    let count = 0;
    const limit = filter.limit ?? Infinity;

    for (const file of files) {
      if (count >= limit) return;

      const rl = readline.createInterface({
        input: fs.createReadStream(file),
        crlfDelay: Infinity,
      });

      for await (const line of rl) {
        if (count >= limit) return;
        const trimmed = line.trim();
        if (!trimmed) continue;

        try {
          const entry: AuditEntry = JSON.parse(trimmed);
          if (this.matches(entry, filter)) {
            yield entry;
            count++;
          }
        } catch {
          // Skip malformed lines
        }
      }
    }
  }

  private async getLogFiles(): Promise<string[]> {
    const entries = await fsp.readdir(this.logDir);
    return entries
      .filter((f) => f.startsWith("audit-") && f.endsWith(".jsonl"))
      .sort()
      .map((f) => path.join(this.logDir, f));
  }

  private async readLogFile(
    filePath: string,
    filter: LogQuery
  ): Promise<AuditEntry[]> {
    const results: AuditEntry[] = [];
    const rl = readline.createInterface({
      input: fs.createReadStream(filePath),
      crlfDelay: Infinity,
    });

    for await (const line of rl) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      try {
        const entry: AuditEntry = JSON.parse(trimmed);
        if (this.matches(entry, filter)) {
          results.push(entry);
        }
      } catch {
        // Skip malformed lines
      }
    }

    return results;
  }

  private matches(entry: AuditEntry, filter: LogQuery): boolean {
    if (filter.events?.length && !filter.events.includes(entry.event)) {
      return false;
    }
    if (filter.after && new Date(entry.timestamp) < filter.after) {
      return false;
    }
    if (filter.before && new Date(entry.timestamp) > filter.before) {
      return false;
    }
    if (filter.pathContains && !entry.path.includes(filter.pathContains)) {
      return false;
    }
    return true;
  }
}
```

