## `src/main.ts` — Runnable Example

```typescript
import path from "path";
import { AuditFileWatcher } from "./audit-watcher";
import { AuditLogReader } from "./log-reader";

const WATCH_DIR = process.argv[2] || "./watched";
const LOG_DIR = path.join(__dirname, "../audit-logs");

async function main() {
  const watcher = new AuditFileWatcher({
    paths: [WATCH_DIR],
    logDir: LOG_DIR,
    hashFiles: true,
    debounceMs: 300,
    ignored: ["**/node_modules/**", "**/.git/**", "**/audit-logs/**"],
  });

  // Real-time console output
  watcher.onEntry((entry) => {
    const icon =
      entry.event === "created"  ? "✅" :
      entry.event === "modified" ? "📝" :
      entry.event === "deleted"  ? "❌" :
      entry.event === "renamed"  ? "📎" : "❓";

    console.log(
      `${icon} [${entry.event.toUpperCase()}] ${entry.relativePath}` +
        (entry.size !== null ? ` (${formatBytes(entry.size)})` : "") +
        (entry.hash ? ` sha256:${entry.hash.slice(0, 12)}…` : "")
    );
  });

  await watcher.start();

  // Graceful shutdown
  const shutdown = async () => {
    console.log("\nShutting down...");
    await watcher.stop();

    // Demo: query recent logs
    const reader = new AuditLogReader(LOG_DIR);
    const recent = await reader.query({ limit: 20 });
    if (recent.length > 0) {
      console.log(`\n--- Last ${recent.length} audit entries ---`);
      for (const e of recent) {
        console.log(`  ${e.timestamp} ${e.event.padEnd(8)} ${e.relativePath}`);
      }
    }

    process.exit(0);
  };

  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

main().catch((err) => {
  console.error("Fatal:", err);
  process.exit(1);
});
