## src/engine/tokenizer.ts

```typescript
// Stop words that add noise to the index
const STOP_WORDS = new Set([
  "a", "an", "the", "and", "or", "but", "in", "on", "at", "to", "for",
  "of", "with", "by", "from", "is", "it", "as", "be", "was", "are",
  "were", "been", "has", "have", "had", "do", "does", "did", "will",
  "would", "could", "should", "may", "might", "can", "this", "that",
  "these", "those", "i", "you", "he", "she", "we", "they", "not", "no",
  "if", "then", "else", "when", "up", "out", "so", "than", "too", "very",
]);

/**
 * Minimal Porter-style suffix stripping.
 * Handles the most common English suffixes — good enough for search.
 */
function stem(word: string): string {
  if (word.length < 4) return word;

  const rules: [RegExp, string][] = [
    [/ies$/, "y"],
    [/ied$/, "y"],
    [/sses$/, "ss"],
    [/ness$/, ""],
    [/ment$/, ""],
    [/ing$/, ""],
    [/tion$/, "t"],
    [/able$/, ""],
    [/ful$/, ""],
    [/ous$/, ""],
    [/ive$/, ""],
    [/ly$/, ""],
    [/er$/, ""],
    [/ed$/, ""],
    [/s$/, ""],
  ];

  for (const [pattern, replacement] of rules) {
    if (pattern.test(word)) {
      const result = word.replace(pattern, replacement);
      // Don't reduce below 3 chars
      if (result.length >= 3) return result;
    }
  }

  return word;
}

export interface Token {
  term: string;       // Normalized, stemmed term
  original: string;   // Original text before normalization
  position: number;   // Word position in the document
}

/**
 * Full analysis pipeline: split → normalize → filter stops → stem.
 * Returns positioned tokens for phrase search support.
 */
export function tokenize(text: string): Token[] {
  const tokens: Token[] = [];
  // Split on non-word characters, keeping position tracking
  const words = text.split(/[^\w]+/).filter(Boolean);

  let position = 0;
  for (const word of words) {
    const lower = word.toLowerCase();

    // Skip stop words and very short tokens
    if (STOP_WORDS.has(lower) || lower.length < 2) {
      position++;
      continue;
    }

    // Skip pure numbers unless they look meaningful (e.g., years, codes)
    if (/^\d+$/.test(lower) && lower.length < 3) {
      position++;
      continue;
    }

    tokens.push({
      term: stem(lower),
      original: lower,
      position,
    });
    position++;
  }

  return tokens;
}

/**
 * Tokenize a search query — keeps stop words that are boolean operators.
 * Handles quoted phrases by preserving them as grouped tokens.
 */
export function tokenizeQuery(query: string): string[] {
  const terms: string[] = [];
  // Extract quoted phrases first
  const phraseRegex = /"([^"]+)"/g;
  let remaining = query;
  let match: RegExpExecArray | null;

  while ((match = phraseRegex.exec(query)) !== null) {
    // Mark phrases with a prefix so the searcher can detect them
    terms.push(`PHRASE:${match[1].toLowerCase()}`);
    remaining = remaining.replace(match[0], " ");
  }

  // Process remaining individual terms
  const words = remaining.split(/\s+/).filter(Boolean);
  for (const word of words) {
    const upper = word.toUpperCase();
    if (upper === "AND" || upper === "OR" || upper === "NOT") {
      terms.push(upper);
    } else if (word.startsWith("-")) {
      // -term syntax for exclusion
      terms.push(`NOT`);
      terms.push(stem(word.slice(1).toLowerCase()));
    } else {
      terms.push(stem(word.toLowerCase()));
    }
  }

  return terms;
}
