```typescript
/**
 * A single occurrence of a term in a document.
 * Positions enable phrase and proximity search.
 */
export interface Posting {
  docId: string;
  termFrequency: number;
  positions: number[];
}

/** Metadata stored per indexed document */
export interface DocMeta {
  docId: string;
  path: string;
  title: string;
  size: number;
  totalTokens: number;
  modifiedAt: number;   // mtime in ms — used for incremental re-indexing
  indexedAt: number;
}

/**
 * Inverted index: the core data structure.
 * Maps each term → list of postings (which docs contain it, where, how often).
 */
export class IndexStore {
  // term → postings list
  private invertedIndex = new Map<string, Posting[]>();
  // docId → metadata
  private documents = new Map<string, DocMeta>();
  // Cached document count for IDF calculation
  private _docCount = 0;

  get docCount(): number {
    return this._docCount;
  }

  get termCount(): number {
    return this.invertedIndex.size;
  }

  /** Add or update a document in the index */
  addDocument(meta: DocMeta, terms: Array<{ term: string; position: number }>): void {
    // If re-indexing, remove old postings first
    if (this.documents.has(meta.docId)) {
      this.removeDocument(meta.docId);
    }

    this.documents.set(meta.docId, meta);
    this._docCount = this.documents.size;

    // Build a local frequency map for this document
    const termMap = new Map<string, number[]>();
    for (const { term, position } of terms) {
      const positions = termMap.get(term) ?? [];
      positions.push(position);
      termMap.set(term, positions);
    }

    // Insert postings into the inverted index
    for (const [term, positions] of termMap) {
      const posting: Posting = {
        docId: meta.docId,
        termFrequency: positions.length,
        positions: positions.sort((a, b) => a - b),
      };

      const list = this.invertedIndex.get(term);
      if (list) {
        list.push(posting);
      } else {
        this.invertedIndex.set(term, [posting]);
      }
    }
  }

  /** Remove all postings for a document */
  removeDocument(docId: string): boolean {
    if (!this.documents.has(docId)) return false;

    this.documents.delete(docId);
    this._docCount = this.documents.size;

    // Purge from every postings list (expensive but necessary for correctness)
    for (const [term, postings] of this.invertedIndex) {
      const filtered = postings.filter((p) => p.docId !== docId);
      if (filtered.length === 0) {
        this.invertedIndex.delete(term);
      } else {
        this.invertedIndex.set(term, filtered);
      }
    }

    return true;
  }

  /** Look up postings for a single term */
  getPostings(term: string): Posting[] {
    return this.invertedIndex.get(term) ?? [];
  }

  /** Get document metadata by ID */
  getDoc(docId: string): DocMeta | undefined {
    return this.documents.get(docId);
  }

  /** All indexed document IDs */
  allDocIds(): string[] {
    return Array.from(this.documents.keys());
  }

  /** All document metadata */
  allDocs(): DocMeta[] {
    return Array.from(this.documents.values());
  }

  /** Average document length — used for BM25-style normalization */
  avgDocLength(): number {
    if (this._docCount === 0) return 0;
    let total = 0;
    for (const doc of this.documents.values()) {
      total += doc.totalTokens;
    }
    return total / this._docCount;
  }

  /** Wipe the entire index */
  clear(): void {
    this.invertedIndex.clear();
    this.documents.clear();
    this._docCount = 0;
  }

  // --- Serialization for disk persistence ---

  serialize(): object {
    return {
      invertedIndex: Array.from(this.invertedIndex.entries()),
      documents: Array.from(this.documents.entries()),
    };
  }

  static deserialize(data: any): IndexStore {
    const store = new IndexStore();
    if (data.invertedIndex) {
      store.invertedIndex = new Map(data.invertedIndex);
    }
    if (data.documents) {
      store.documents = new Map(data.documents);
      store._docCount = store.documents.size;
    }
    return store;
  }
}
