import * as fs from "node:fs";
import * as path from "node:path";
import * as crypto from "node:crypto";
import { tokenize } from "./tokenizer.js";
import { IndexStore, DocMeta } from "./index-store.js";

/** File extensions we know how to index */
const INDEXABLE_EXTENSIONS = new Set([
  ".txt", ".md", ".markdown", ".rst",
  ".ts", ".js", ".tsx", ".jsx",
  ".py", ".rb", ".go", ".rs", ".java", ".c", ".cpp", ".h",
  ".json", ".yaml", ".yml", ".toml",
  ".html", ".css", ".scss",
  ".sh", ".bash", ".zsh",
  ".env", ".cfg", ".conf", ".ini",
  ".csv", ".log", ".xml", ".sql",
]);

/** Directories to always skip */
const IGNORED_DIRS = new Set([
  "node_modules", ".git", ".svn", ".hg",
  "dist", "build", "out", ".next",
  "__pycache__", ".pytest_cache",
  "vendor", "target", ".idea", ".vscode",
  "coverage", ".nyc_output",
]);

export interface IndexStats {
  filesScanned: number;
  filesIndexed: number;
  filesSkipped: number;
  filesUpdated: number;
  totalTokens: number;
  elapsedMs: number;
}

export interface IndexerOptions {
  rootDir: string;
  extensions?: string[];        // Override default extensions
  ignoreDirs?: string[];        // Additional dirs to ignore
  maxFileSizeKB?: number;       // Skip files larger than this (default 512KB)
  includeHidden?: boolean;      // Index dotfiles (default false)
}

/**
 * Crawls a directory tree, reads text files, and populates the IndexStore.
 * Supports incremental indexing — skips files whose mtime hasn't changed.
 */
export class Indexer {
  private store: IndexStore;
  private options: Required<IndexerOptions>;

  constructor(store: IndexStore, options: IndexerOptions) {
    this.store = store;
    this.options = {
      rootDir: path.resolve(options.rootDir),
      extensions: options.extensions ?? Array.from(INDEXABLE_EXTENSIONS),
      ignoreDirs: options.ignoreDirs ?? [],
      maxFileSizeKB: options.maxFileSizeKB ?? 512,
      includeHidden: options.includeHidden ?? false,
    };
  }

  /** Run a full or incremental index pass */
  index(onProgress?: (file: string) => void): IndexStats {
    const start = performance.now();
    const stats: IndexStats = {
      filesScanned: 0,
      filesIndexed: 0,
      filesSkipped: 0,
      filesUpdated: 0,
      totalTokens: 0,
      elapsedMs: 0,
    };

    const allowedExts = new Set(
      this.options.extensions.map((e) => (e.startsWith(".") ? e : `.${e}`))
    );
    const ignoredDirs = new Set([...IGNORED_DIRS, ...this.options.ignoreDirs]);

    // Track which docs we've seen — anything left over was deleted
    const seenDocIds = new Set<string>();

    const walk = (dir: string): void => {
      let entries: fs.Dirent[];
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        // Permission denied, etc. — skip silently
        return;
      }

      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);

        // Skip hidden files/dirs unless configured otherwise
        if (!this.options.includeHidden && entry.name.startsWith(".")) continue;

        if (entry.isDirectory()) {
          if (!ignoredDirs.has(entry.name)) {
            walk(fullPath);
          }
          continue;
        }

        if (!entry.isFile()) continue;
        stats.filesScanned++;

        const ext = path.extname(entry.name).toLowerCase();
        if (!allowedExts.has(ext)) {
          stats.filesSkipped++;
          continue;
        }

        // Check file size
        let fileStat: fs.Stats;
        try {
          fileStat = fs.statSync(fullPath);
        } catch {
          stats.filesSkipped++;
          continue;
        }

        if (fileStat.size > this.options.maxFileSizeKB * 1024) {
          stats.filesSkipped++;
          continue;
        }

        const docId = this.makeDocId(fullPath);
        seenDocIds.add(docId);

        // Incremental: skip if mtime unchanged
        const existing = this.store.getDoc(docId);
        if (existing && existing.modifiedAt === fileStat.mtimeMs) {
          stats.filesSkipped++;
          continue;
        }

        // Read and index the file
        let content: string;
        try {
          content = fs.readFileSync(fullPath, "utf-8");
        } catch {
          stats.filesSkipped++;
          continue;
        }

        onProgress?.(path.relative(this.options.rootDir, fullPath));

        const tokens = tokenize(content);
        const title = this.extractTitle(fullPath, content);

        const meta: DocMeta = {
          docId,
          path: fullPath,
          title,
          size: fileStat.size,
          totalTokens: tokens.length,
          modifiedAt: fileStat.mtimeMs,
          indexedAt: Date.now(),
        };

        this.store.addDocument(
          meta,
          tokens.map((t) => ({ term: t.term, position: t.position }))
        );

        stats.totalTokens += tokens.length;
        if (existing) {
          stats.filesUpdated++;
        } else {
          stats.filesIndexed++;
        }
      }
    };

    walk(this.options.rootDir);

    // Remove docs for files that no longer exist
    for (const docId of this.store.allDocIds()) {
      if (!seenDocIds.has(docId)) {
        this.store.removeDocument(docId);
      }
    }

    stats.elapsedMs = Math.round(performance.now() - start);
    return stats;
  }

  /** Deterministic doc ID from file path */
  private makeDocId(filePath: string): string {
    const relative = path.relative(this.options.rootDir, filePath);
    return crypto.createHash("sha1").update(relative).digest("hex").slice(0, 12);
  }

  /** Try to extract a meaningful title from the file */
  private extractTitle(filePath: string, content: string): string {
    const ext = path.extname(filePath).toLowerCase();

    // Markdown: use first heading
    if (ext === ".md" || ext === ".markdown") {
      const headingMatch = content.match(/^#{1,3}\s+(.+)$/m);
      if (headingMatch) return headingMatch[1].trim();
    }

    // HTML: use <title> tag
    if (ext === ".html") {
      const titleMatch = content.match(/<title[^>]*>([^<]+)<\/title>/i);
      if (titleMatch) return titleMatch[1].trim();
    }

    // Fallback: use the file name
    return path.basename(filePath);
  }
}
