// ---------- violations ----------

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Violation {
    BlockedWord(String),
    ExcessiveCaps { ratio: f32 },
    RepeatedChars { sample: String },
    LinkDetected(String),
    TooLong { len: usize, max: usize },
    UserMuted { until: Option<DateTime<Utc>> },
    UserBanned,
}

impl fmt::Display for Violation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::BlockedWord(w) => write!(f, "blocked word: '{w}'"),
            Self::ExcessiveCaps { ratio } => write!(f, "caps {:.0}%", ratio * 100.0),
            Self::RepeatedChars { sample } => write!(f, "repeated: '{sample}'"),
            Self::LinkDetected(url) => write!(f, "link: {url}"),
            Self::TooLong { len, max } => write!(f, "too long: {len}/{max}"),
            Self::UserMuted { until: Some(t) } => {
                write!(f, "muted until {}", t.format("%H:%M:%S UTC"))
            }
            Self::UserMuted { until: None } => write!(f, "muted indefinitely"),
            Self::UserBanned => write!(f, "user banned"),
        }
    }
}

