```rust
use anyhow::Result;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

use crate::models::{LogEntry, UserRecord};

/// Simple JSON-file-backed store kept next to the config.
pub struct Store {
    users_path: PathBuf,
    log_path: PathBuf,
}

impl Store {
    pub fn new(data_dir: &Path) -> Result<Self> {
        fs::create_dir_all(data_dir)?;
        Ok(Self {
            users_path: data_dir.join("users.json"),
            log_path: data_dir.join("log.json"),
        })
    }

    // ---- users ----

    fn load_users(&self) -> Result<HashMap<String, UserRecord>> {
        if !self.users_path.exists() {
            return Ok(HashMap::new());
        }
        let data = fs::read_to_string(&self.users_path)?;
        Ok(serde_json::from_str(&data)?)
    }

    fn save_users(&self, users: &HashMap<String, UserRecord>) -> Result<()> {
        fs::write(&self.users_path, serde_json::to_string_pretty(users)?)?;
        Ok(())
    }

    pub fn get_user(&self, name: &str) -> Result<Option<UserRecord>> {
        Ok(self.load_users()?.get(name).cloned())
    }

    pub fn upsert_user(&self, rec: UserRecord) -> Result<()> {
        let mut users = self.load_users()?;
        users.insert(rec.username.clone(), rec);
        self.save_users(&users)
    }

    // ---- moderation log ----

    pub fn load_log(&self) -> Result<Vec<LogEntry>> {
        if !self.log_path.exists() {
            return Ok(Vec::new());
        }
        let data = fs::read_to_string(&self.log_path)?;
        Ok(serde_json::from_str(&data)?)
    }

    pub fn append_log(&self, entry: LogEntry) -> Result<()> {
        let mut log = self.load_log()?;
        log.push(entry);
        fs::write(&self.log_path, serde_json::to_string_pretty(&log)?)?;
        Ok(())
    }
}
