use regex::Regex;

use crate::config::Config;
use crate::models::{CheckResult, Violation};

pub struct Filter {
    cfg: Config,
    url_re: Regex,
}

impl Filter {
    pub fn new(cfg: Config) -> Self {
        // catches http(s) links and www. prefixed URLs
        let url_re = Regex::new(r"(?i)https?://\S+|www\.\S+").expect("valid regex");
        Self { cfg, url_re }
    }

    /// Run every rule against `msg` and collect violations.
    pub fn check(&self, msg: &str) -> CheckResult {
        let mut violations = Vec::new();

        self.check_length(msg, &mut violations);
        self.check_blocked_words(msg, &mut violations);
        self.check_caps(msg, &mut violations);
        self.check_repeats(msg, &mut violations);
        self.check_links(msg, &mut violations);

        let passed = violations.is_empty();
        let censored = if passed {
            None
        } else {
            Some(self.censor(msg))
        };

        CheckResult {
            passed,
            violations,
            censored,
        }
    }

    // ---- individual rules ----

    fn check_length(&self, msg: &str, out: &mut Vec<Violation>) {
        if msg.len() > self.cfg.max_message_length {
            out.push(Violation::TooLong {
                len: msg.len(),
                max: self.cfg.max_message_length,
            });
        }
    }

    fn check_blocked_words(&self, msg: &str, out: &mut Vec<Violation>) {
        let lower = msg.to_lowercase();
        for word in &self.cfg.blocked_words {
            if word_present(&lower, &word.to_lowercase()) {
                out.push(Violation::BlockedWord(word.clone()));
            }
        }
    }

    fn check_caps(&self, msg: &str, out: &mut Vec<Violation>) {
        let alpha: Vec<char> = msg.chars().filter(|c| c.is_alphabetic()).collect();
        if alpha.len() <= 6 {
            return; // too short to judge
        }
        let upper = alpha.iter().filter(|c| c.is_uppercase()).count();
        let ratio = upper as f32 / alpha.len() as f32;
        if ratio > self.cfg.max_caps_ratio {
            out.push(Violation::ExcessiveCaps { ratio });
        }
    }

    fn check_repeats(&self, msg: &str, out: &mut Vec<Violation>) {
        let max = self.cfg.max_repeat_chars;
        let mut prev: Option<char> = None;
        let mut run = 1usize;

        for ch in msg.chars() {
            if Some(ch) == prev {
                run += 1;
                if run > max {
                    let sample: String = std::iter::repeat(ch).take(run).collect();
                    out.push(Violation::RepeatedChars { sample });
                    return;
                }
            } else {
                prev = Some(ch);
                run = 1;
            }
        }
    }

    fn check_links(&self, msg: &str, out: &mut Vec<Violation>) {
        if !self.cfg.block_links {
            return;
        }
        for m in self.url_re.find_iter(msg) {
            let url = m.as_str();
            let allowed = self
                .cfg
                .allowed_domains
                .iter()
                .any(|d| url.to_lowercase().contains(&d.to_lowercase()));
            if !allowed {
                out.push(Violation::LinkDetected(url.to_owned()));
            }
        }
    }

    // ---- censoring ----

    fn censor(&self, msg: &str) -> String {
        let c = self.cfg.censor_char;
        let mut result = msg.to_owned();

        for word in &self.cfg.blocked_words {
            let word_lower = word.to_lowercase();
            let replacement: String = std::iter::repeat(c).take(word.len()).collect();
            let lower = result.to_lowercase();
            let mut buf = String::with_capacity(result.len());
            let mut last = 0;

            for (i, matched) in lower.match_indices(&word_lower) {
                let end = i + matched.len();
                let before_ok =
                    i == 0 || lower[..i].ends_with(|ch: char| !ch.is_alphanumeric());
                let after_ok =
                    end == lower.len() || lower[end..].starts_with(|ch: char| !ch.is_alphanumeric());

                if before_ok && after_ok {
                    buf.push_str(&result[last..i]);
                    buf.push_str(&replacement);
                    last = end;
                }
            }
            buf.push_str(&result[last..]);
            result = buf;
        }
        result
    }
}

// ---- helpers ----

/// True when `word` appears in `text` surrounded by non-alphanumeric chars (or edges).
fn word_present(text: &str, word: &str) -> bool {
    for (i, matched) in text.match_indices(word) {
        let end = i + matched.len();
        let before = i == 0 || text[..i].ends_with(|c: char| !c.is_alphanumeric());
        let after = end == text.len() || text[end..].starts_with(|c: char| !c.is_alphanumeric());
        if before && after {
            return true;
        }
    }
    false
}

