import * as fs from "fs";
import * as path from "path";
import { ModConfig } from "./types";

const DEFAULTS: ModConfig = {
  profanity: { enabled: true, words: [], severity: "high" },
  spam: { enabled: true, maxRepeatedChars: 5, maxEmojis: 10, patterns: [] },
  flood: { enabled: true, maxMessages: 5, windowSeconds: 10 },
  caps: { enabled: true, maxPercent: 70, minLength: 8 },
  links: { enabled: true, allowlist: [], blockByDefault: true },
  escalation: {
    warnThreshold: 1,
    muteThreshold: 3,
    banThreshold: 5,
    muteDurationMinutes: 10,
    decayHours: 24,
  },
  storePath: "./mod-data.json",
  logPath: "./mod-log.jsonl",
};

export function loadConfig(configPath?: string): ModConfig {
  const resolved = configPath || path.resolve(process.cwd(), "config.json");

  if (!fs.existsSync(resolved)) {
    return { ...DEFAULTS };
  }

  try {
    const raw = fs.readFileSync(resolved, "utf-8");
    const parsed = JSON.parse(raw);
    return deepMerge(DEFAULTS, parsed) as ModConfig;
  } catch (err) {
    console.error(`Failed to parse config at ${resolved}, using defaults`);
    return { ...DEFAULTS };
  }
}

function deepMerge(target: any, source: any): any {
  const result = { ...target };
  for (const key of Object.keys(source)) {
    if (
      source[key] &&
      typeof source[key] === "object" &&
      !Array.isArray(source[key])
    ) {
      result[key] = deepMerge(target[key] || {}, source[key]);
    } else {
      result[key] = source[key];
    }
  }
  return result;
}
