// src/detectors.ts

import { ChatMessage, ModConfig, UserRecord, Violation } from "./types";

// --- Profanity Detector ---

export function detectProfanity(
  msg: ChatMessage,
  config: ModConfig
): Violation | null {
  if (!config.profanity.enabled || config.profanity.words.length === 0) {
    return null;
  }

  const lower = msg.content.toLowerCase();
  // Normalize common substitutions: @ -> a, 0 -> o, 1 -> i, 3 -> e, $ -> s
  const normalized = lower
    .replace(/@/g, "a")
    .replace(/0/g, "o")
    .replace(/1/g, "i")
    .replace(/3/g, "e")
    .replace(/\$/g, "s")
    .replace(/[_\-.*]+/g, ""); // strip separators used to evade filters

  const matched: string[] = [];

  for (const word of config.profanity.words) {
    const wLower = word.toLowerCase();
    // Check both raw and normalized text
    const pattern = new RegExp(`\\b${escapeRegex(wLower)}\\b`, "i");
    if (pattern.test(lower) || pattern.test(normalized) || normalized.includes(wLower)) {
      matched.push(word);
    }
  }

  if (matched.length === 0) return null;

  return {
    type: "profanity",
    severity: config.profanity.severity,
    reason: `Blocked words detected: ${matched.join(", ")}`,
    matched,
  };
}

// --- Spam Detector ---

export function detectSpam(
  msg: ChatMessage,
  config: ModConfig
): Violation | null {
  if (!config.spam.enabled) return null;

  const matched: string[] = [];
  const content = msg.content;

  // Repeated characters: "heeeeello" -> 5 e's in a row
  const repeatMatch = content.match(/(.)\1{4,}/g);
  if (repeatMatch) {
    const maxRepeat = Math.max(...repeatMatch.map((m) => m.length));
    if (maxRepeat >= config.spam.maxRepeatedChars) {
      matched.push(`repeated chars (${maxRepeat}x)`);
    }
  }

  // Excessive emojis (Unicode emoji ranges)
  const emojiPattern =
    /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu;
  const emojis = content.match(emojiPattern);
  if (emojis && emojis.length > config.spam.maxEmojis) {
    matched.push(`excessive emojis (${emojis.length})`);
  }

  // Known spam patterns
  const lower = content.toLowerCase();
  for (const pattern of config.spam.patterns) {
    const regex = new RegExp(pattern, "i");
    if (regex.test(lower)) {
      matched.push(`pattern: "${pattern}"`);
    }
  }

  // Repeated words: "buy buy buy buy"
  const words = lower.split(/\s+/).filter(Boolean);
  if (words.length >= 4) {
    const freq = new Map<string, number>();
    for (const w of words) freq.set(w, (freq.get(w) || 0) + 1);
    for (const [word, count] of freq) {
      if (count >= 4 && count / words.length > 0.5) {
        matched.push(`repeated word "${word}" (${count}x)`);
      }
    }
  }

  if (matched.length === 0) return null;

  return {
    type: "spam",
    severity: matched.length >= 2 ? "high" : "medium",
    reason: `Spam indicators: ${matched.join("; ")}`,
    matched,
  };
}

// --- Flood Detector ---

export function detectFlood(
  msg: ChatMessage,
  config: ModConfig,
  user: UserRecord
): Violation | null {
  if (!config.flood.enabled) return null;

  const windowMs = config.flood.windowSeconds * 1000;
  const cutoff = msg.timestamp - windowMs;
  const recentCount = user.messageTimestamps.filter((t) => t > cutoff).length;

  // Count includes the current message (already pushed by the time we check)
  if (recentCount <= config.flood.maxMessages) return null;

  return {
    type: "flood",
    severity: recentCount > config.flood.maxMessages * 2 ? "high" : "medium",
    reason: `${recentCount} messages in ${config.flood.windowSeconds}s (limit: ${config.flood.maxMessages})`,
    matched: [`${recentCount} msgs`],
  };
}

// --- Caps Detector ---

export function detectCaps(
  msg: ChatMessage,
  config: ModConfig
): Violation | null {
  if (!config.caps.enabled) return null;

  const letters = msg.content.replace(/[^a-zA-Z]/g, "");
  if (letters.length < config.caps.minLength) return null;

  const upper = letters.replace(/[^A-Z]/g, "").length;
  const percent = Math.round((upper / letters.length) * 100);

  if (percent <= config.caps.maxPercent) return null;

  return {
    type: "caps",
    severity: "low",
    reason: `${percent}% caps (limit: ${config.caps.maxPercent}%)`,
    matched: [`${percent}%`],
  };
}

// --- Links Detector ---

export function detectLinks(
  msg: ChatMessage,
  config: ModConfig
): Violation | null {
  if (!config.links.enabled) return null;

  const urlPattern =
    /https?:\/\/([a-zA-Z0-9.-]+\.[a-zA-Z]{2,})(\/[^\s]*)?/gi;
  const matches = [...msg.content.matchAll(urlPattern)];

  if (matches.length === 0) return null;

  if (!config.links.blockByDefault) return null; // links allowed unless blocklisted

  const blocked: string[] = [];
  for (const m of matches) {
    const domain = m[1].toLowerCase();
    const allowed = config.links.allowlist.some(
      (a) => domain === a.toLowerCase() || domain.endsWith("." + a.toLowerCase())
    );
    if (!allowed) {
      blocked.push(domain);
    }
  }

  if (blocked.length === 0) return null;

  return {
    type: "links",
    severity: "medium",
    reason: `Unapproved links: ${blocked.join(", ")}`,
    matched: blocked,
  };
}

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
