// src/store.ts

import * as fs from "fs";
import { UserRecord, ModerationResult } from "./types";

interface StoreData {
  users: Record<string, UserRecord>;
  stats: {
    totalProcessed: number;
    totalViolations: number;
    totalWarns: number;
    totalMutes: number;
    totalBans: number;
  };
}

export class Store {
  private data: StoreData;
  private dirty = false;

  constructor(
    private storePath: string,
    private logPath: string
  ) {
    this.data = this.load();
  }

  private load(): StoreData {
    const empty: StoreData = {
      users: {},
      stats: {
        totalProcessed: 0,
        totalViolations: 0,
        totalWarns: 0,
        totalMutes: 0,
        totalBans: 0,
      },
    };

    if (!fs.existsSync(this.storePath)) return empty;

    try {
      return JSON.parse(fs.readFileSync(this.storePath, "utf-8"));
    } catch {
      return empty;
    }
  }

  save(): void {
    if (!this.dirty) return;
    fs.writeFileSync(this.storePath, JSON.stringify(this.data, null, 2));
    this.dirty = false;
  }

  getUser(userId: string, username: string): UserRecord {
    const now = Date.now();

    if (!this.data.users[userId]) {
      this.data.users[userId] = {
        userId,
        username,
        warnings: 0,
        muted: false,
        mutedUntil: null,
        banned: false,
        history: [],
        firstSeen: now,
        lastSeen: now,
        messageTimestamps: [],
      };
      this.dirty = true;
    }

    const user = this.data.users[userId];
    user.username = username;
    user.lastSeen = now;

    // Unset expired mutes
    if (user.muted && user.mutedUntil && now > user.mutedUntil) {
      user.muted = false;
      user.mutedUntil = null;
    }

    return user;
  }

  recordMessage(userId: string, timestamp: number): void {
    const user = this.data.users[userId];
    if (!user) return;

    user.messageTimestamps.push(timestamp);

    // Keep only last 60 seconds of timestamps
    const cutoff = timestamp - 60_000;
    user.messageTimestamps = user.messageTimestamps.filter((t) => t > cutoff);
    this.dirty = true;
  }

  addViolation(
    userId: string,
    type: string,
    timestamp: number
  ): number {
    const user = this.data.users[userId];
    if (!user) return 0;

    user.history.push({ type, timestamp });
    user.warnings++;
    this.data.stats.totalViolations++;
    this.dirty = true;
    return user.warnings;
  }

  muteUser(userId: string, untilMs: number): void {
    const user = this.data.users[userId];
    if (!user) return;

    user.muted = true;
    user.mutedUntil = untilMs;
    this.data.stats.totalMutes++;
    this.dirty = true;
  }

  banUser(userId: string): void {
    const user = this.data.users[userId];
    if (!user) return;

    user.banned = true;
    this.data.stats.totalBans++;
    this.dirty = true;
  }

  unmuteUser(userId: string): void {
    const user = this.data.users[userId];
    if (!user) return;
    user.muted = false;
    user.mutedUntil = null;
    this.dirty = true;
  }

  unbanUser(userId: string): void {
    const user = this.data.users[userId];
    if (!user) return;
    user.banned = false;
    user.warnings = Math.max(0, user.warnings - 2);
    this.dirty = true;
  }

  resetUser(userId: string): void {
    delete this.data.users[userId];
    this.dirty = true;
  }

  getStats() {
    return { ...this.data.stats };
  }

  getAllUsers(): UserRecord[] {
    return Object.values(this.data.users);
  }

  decayWarnings(decayHours: number): number {
    const cutoff = Date.now() - decayHours * 3600_000;
    let decayed = 0;

    for (const user of Object.values(this.data.users)) {
      const before = user.warnings;
      user.history = user.history.filter((h) => h.timestamp > cutoff);
      user.warnings = user.history.length;
      if (user.warnings < before) decayed += before - user.warnings;
    }

    if (decayed > 0) this.dirty = true;
    return decayed;
  }

  appendLog(result: ModerationResult): void {
    const entry = {
      ts: new Date(result.message.timestamp).toISOString(),
      user: result.message.username,
      userId: result.message.userId,
      action: result.action,
      passed: result.passed,
      violations: result.violations.map((v) => v.type),
      reason: result.actionReason,
      content:
        result.message.content.substring(0, 200) +
        (result.message.content.length > 200 ? "..." : ""),
    };

    fs.appendFileSync(this.logPath, JSON.stringify(entry) + "\n");
    this.data.stats.totalProcessed++;
    this.dirty = true;
  }
}
