// src/moderator.ts

import {
  ChatMessage,
  ModConfig,
  ModerationResult,
  Violation,
  ActionType,
} from "./types";
import {
  detectProfanity,
  detectSpam,
  detectFlood,
  detectCaps,
  detectLinks,
} from "./detectors";
import { Store } from "./store";

export class Moderator {
  constructor(
    private config: ModConfig,
    private store: Store
  ) {}

  process(msg: ChatMessage): ModerationResult {
    const user = this.store.getUser(msg.userId, msg.username);

    // Pre-check: already banned
    if (user.banned) {
      return {
        message: msg,
        passed: false,
        violations: [],
        action: "ban",
        actionReason: "User is banned",
      };
    }

    // Pre-check: currently muted
    if (user.muted) {
      const remaining = user.mutedUntil
        ? Math.ceil((user.mutedUntil - Date.now()) / 60_000)
        : 0;
      return {
        message: msg,
        passed: false,
        violations: [],
        action: "mute",
        actionReason: `User is muted (${remaining}min remaining)`,
      };
    }

    // Track this message for flood detection
    this.store.recordMessage(msg.userId, msg.timestamp);

    // Run all detectors
    const violations: Violation[] = [];

    const checks = [
      detectProfanity(msg, this.config),
