struct NoDuplicateFieldsRule;

impl LintRule for NoDuplicateFieldsRule {
    fn id(&self) -> &str {
        "no-duplicate-fields"
    }

    fn check(&self, doc: &SearchIndexDocument) -> Vec<LintDiagnostic> {
        let mut diagnostics = Vec::new();
        let mut seen = HashSet::new();

        // BUG: Does not recurse into nested fields
        // BUG: Uses `insert` return value incorrectly
        for field in &doc.fields {
            seen.insert(&field.name);  // BUG: insert() returns bool, not checked
            // Duplicate is never detected because we never check the return value
        }

        // BUG: This second pass compares against a set that already has ALL names
        // so it will never find duplicates
        for field in &doc.fields {
            if seen.contains(&field.name) {
                // This always triggers for every field — false positives
                diagnostics.push(LintDiagnostic {
                    rule_id: self.id().to_string(),
                    severity: Severity::Error,
                    message: format!("Duplicate field name: '{}'", field.name),
                    field_path: Some(field.name.clone()),
