```go
package docparser

import (
	"fmt"
	"strings"
	"time"
)

// Format represents a supported document format.
type Format string

const (
	FormatJSON     Format = "json"
	FormatMarkdown Format = "markdown"
	FormatText     Format = "text"
)

// Document is the canonical representation of a parsed document.
type Document struct {
	Title      string            `json:"title"`
	Format     Format            `json:"format"`
	Metadata   Metadata          `json:"metadata"`
	Sections   []Section         `json:"sections"`
	Raw        string            `json:"-"`
	ParsedAt   time.Time         `json:"parsed_at"`
	Properties map[string]string `json:"properties,omitempty"`
}

// Metadata holds document-level metadata.
type Metadata struct {
	Author      string            `json:"author,omitempty"`
	Date        string            `json:"date,omitempty"`
	Tags        []string          `json:"tags,omitempty"`
	Description string            `json:"description,omitempty"`
	Extra       map[string]string `json:"extra,omitempty"`
}

// Section represents a logical section within a document.
type Section struct {
	ID       string    `json:"id"`
	Title    string    `json:"title"`
	Level    int       `json:"level"`
	Content  string    `json:"content"`
	Children []Section `json:"children,omitempty"`
}

// WordCount returns the total word count across all sections.
func (d *Document) WordCount() int {
	count := 0
	for _, s := range d.Sections {
		count += s.wordCount()
	}
	return count
}

// FindSection searches for a section by title (case-insensitive, DFS).
func (d *Document) FindSection(title string) (*Section, bool) {
	lower := strings.ToLower(title)
	for i := range d.Sections {
		if s, ok := d.Sections[i].find(lower); ok {
			return s, true
		}
	}
	return nil, false
}

// SectionTitles returns a flat list of all section titles in DFS order.
func (d *Document) SectionTitles() []string {
	var titles []string
	for _, s := range d.Sections {
		titles = s.collectTitles(titles)
	}
	return titles
}

// String provides a human-readable summary.
func (d *Document) String() string {
	return fmt.Sprintf("Document{title=%q, format=%s, sections=%d, words=%d}",
		d.Title, d.Format, len(d.Sections), d.WordCount())
}

func (s *Section) wordCount() int {
	count := len(strings.Fields(s.Content))
	for _, child := range s.Children {
		count += child.wordCount()
	}
	return count
}

func (s *Section) find(lowerTitle string) (*Section, bool) {
	if strings.ToLower(s.Title) == lowerTitle {
		return s, true
	}
	for i := range s.Children {
		if found, ok := s.Children[i].find(lowerTitle); ok {
			return found, true
		}
	}
	return nil, false
}

func (s *Section) collectTitles(acc []string) []string {
	acc = append(acc, s.Title)
	for _, child := range s.Children {
		acc = child.collectTitles(acc)
	}
	return acc
}
