```go
package docparser

import (
	"errors"
	"fmt"
)

var (
	// ErrEmptyInput is returned when the input is empty or whitespace-only.
	ErrEmptyInput = errors.New("docparser: empty input")

	// ErrUnsupportedFormat is returned for unregistered formats.
	ErrUnsupportedFormat = errors.New("docparser: unsupported format")

	// ErrNilReader is returned when a nil reader is provided.
	ErrNilReader = errors.New("docparser: nil reader")
)

// ParseError wraps an underlying error with context about where parsing failed.
type ParseError struct {
	Format  Format
	Line    int
	Column  int
	Message string
	Err     error
}

func (e *ParseError) Error() string {
	loc := ""
	if e.Line > 0 {
		loc = fmt.Sprintf(" at line %d", e.Line)
		if e.Column > 0 {
			loc += fmt.Sprintf(", column %d", e.Column)
		}
	}
	msg := fmt.Sprintf("docparser[%s]: %s%s", e.Format, e.Message, loc)
	if e.Err != nil {
		msg += ": " + e.Err.Error()
	}
	return msg
}

func (e *ParseError) Unwrap() error {
	return e.Err
}

// newParseError creates a ParseError for a given format.
func newParseError(format Format, msg string, err error) *ParseError {
	return &ParseError{Format: format, Message: msg, Err: err}
}

// newParseErrorAt creates a ParseError with location information.
func newParseErrorAt(format Format, line, col int, msg string) *ParseError {
	return &ParseError{Format: format, Line: line, Column: col, Message: msg}
}
