## `parser.go` — Interface + Registry

```go
package docparser

import (
	"fmt"
	"io"
	"strings"
	"sync"
)

// Parser defines the interface every document parser must implement.
type Parser interface {
	// Parse reads from r and returns a structured Document.
	Parse(r io.Reader) (*Document, error)

	// ParseString is a convenience method for string input.
	ParseString(s string) (*Document, error)

	// SupportedFormat returns the format this parser handles.
	SupportedFormat() Format
}

// Registry holds registered parsers keyed by format.
type Registry struct {
	mu      sync.RWMutex
	parsers map[Format]Parser
}

// NewRegistry creates an empty Registry.
func NewRegistry() *Registry {
	return &Registry{
		parsers: make(map[Format]Parser),
	}
}

// Register adds a parser for its declared format.
// It returns an error if a parser for that format is already registered.
func (r *Registry) Register(p Parser) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	f := p.SupportedFormat()
	if _, exists := r.parsers[f]; exists {
		return fmt.Errorf("docparser: parser already registered for format %q", f)
	}
	r.parsers[f] = p
	return nil
}

// MustRegister is like Register but panics on error.
func (r *Registry) MustRegister(p Parser) {
	if err := r.Register(p); err != nil {
		panic(err)
	}
}

// Get returns the parser for a given format.
func (r *Registry) Get(f Format) (Parser, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	p, ok := r.parsers[f]
	if !ok {
		return nil, fmt.Errorf("%w: %q", ErrUnsupportedFormat, f)
	}
	return p, nil
}

// Parse auto-selects a parser by format and parses the reader.
func (r *Registry) Parse(f Format, reader io.Reader) (*Document, error) {
	p, err := r.Get(f)
	if err != nil {
		return nil, err
	}
	return p.Parse(reader)
}

// ParseString auto-selects a parser by format and parses the string.
func (r *Registry) ParseString(f Format, s string) (*Document, error) {
	p, err := r.Get(f)
	if err != nil {
		return nil, err
	}
	return p.ParseString(s)
}

// Formats returns all registered format names.
func (r *Registry) Formats() []Format {
	r.mu.RLock()
	defer r.mu.RUnlock()

	formats := make([]Format, 0, len(r.parsers))
	for f := range r.parsers {
		formats = append(formats, f)
	}
	return formats
}

// DetectFormat guesses the format of the input string.
func DetectFormat(s string) Format {
	trimmed := strings.TrimSpace(s)
	switch {
	case len(trimmed) == 0:
		return FormatText
	case trimmed[0] == '{' || trimmed[0] == '[':
		return FormatJSON
	case strings.HasPrefix(trimmed, "#") || strings.Contains(trimmed, "\n#"):
		return FormatMarkdown
	case strings.Contains(trimmed, "```") || strings.Contains(trimmed, "**"):
		return FormatMarkdown
	default:
		return FormatText
	}
}

// DefaultRegistry returns a registry pre-loaded with all built-in parsers.
func DefaultRegistry() *Registry {
	r := NewRegistry()
	r.MustRegister(NewJSONParser())
	r.MustRegister(NewMarkdownParser())
	r.MustRegister(NewTextParser())
	return r
}
