package docparser

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
	"time"
)

// JSONParser parses JSON documents into the canonical Document structure.
type JSONParser struct{}

// NewJSONParser returns a new JSONParser.
func NewJSONParser() *JSONParser {
	return &JSONParser{}
}

func (p *JSONParser) SupportedFormat() Format { return FormatJSON }

func (p *JSONParser) Parse(r io.Reader) (*Document, error) {
	if r == nil {
		return nil, ErrNilReader
	}

	data, err := io.ReadAll(r)
	if err != nil {
		return nil, newParseError(FormatJSON, "failed to read input", err)
	}

	return p.parseBytes(data)
}

func (p *JSONParser) ParseString(s string) (*Document, error) {
	return p.parseBytes([]byte(s))
}

func (p *JSONParser) parseBytes(data []byte) (*Document, error) {
	trimmed := strings.TrimSpace(string(data))
	if len(trimmed) == 0 {
		return nil, ErrEmptyInput
	}

	// Try structured document format first.
	var raw jsonDocument
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, p.enrichJSONError(data, err)
	}

	doc := &Document{
		Title:    raw.Title,
		Format:   FormatJSON,
		Raw:      trimmed,
		ParsedAt: time.Now().UTC(),
		Metadata: Metadata{
			Author:      raw.Metadata.Author,
			Date:        raw.Metadata.Date,
			Tags:        raw.Metadata.Tags,
			Description: raw.Metadata.Description,
			Extra:       raw.Metadata.Extra,
		},
		Properties: raw.Properties,
	}

	for _, rs := range raw.Sections {
		doc.Sections = append(doc.Sections, convertJSONSection(rs, 1))
	}

	// If no title was set explicitly, try to infer one.
	if doc.Title == "" && len(doc.Sections) > 0 {
		doc.Title = doc.Sections[0].Title
	}

	return doc, nil
}

func (p *JSONParser) enrichJSONError(data []byte, err error) error {
	var syntaxErr *json.SyntaxError
	if ok := isJSONSyntaxError(err, &syntaxErr); ok {
		line, col := offsetToLineCol(string(data), int(syntaxErr.Offset))
		return newParseErrorAt(FormatJSON, line, col, fmt.Sprintf("syntax error: %s", syntaxErr.Error()))
	}
	return newParseError(FormatJSON, "invalid JSON", err)
}

func isJSONSyntaxError(err error, target **json.SyntaxError) bool {
	se, ok := err.(*json.SyntaxError)
	if ok {
		*target = se
	}
	return ok
}

func offsetToLineCol(s string, offset int) (line, col int) {
	line = 1
	col = 1
	for i := 0; i < offset && i < len(s); i++ {
		if s[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	return line, col
}

// --- Internal JSON structures ---

type jsonDocument struct {
	Title      string            `json:"title"`
	Metadata   jsonMetadata      `json:"metadata"`
	Sections   []jsonSection     `json:"sections"`
	Properties map[string]string `json:"properties"`
}

type jsonMetadata struct {
	Author      string            `json:"author"`
	Date        string            `json:"date"`
	Tags        []string          `json:"tags"`
	Description string            `json:"description"`
	Extra       map[string]string `json:"extra"`
}

type jsonSection struct {
	ID       string        `json:"id"`
	Title    string        `json:"title"`
	Content  string        `json:"content"`
	Children []jsonSection `json:"children"`
}

func convertJSONSection(js jsonSection, level int) Section {
	s := Section{
		ID:      js.ID,
		Title:   js.Title,
		Level:   level,
		Content: js.Content,
	}
	for _, child := range js.Children {
		s.Children = append(s.Children, convertJSONSection(child, level+1))
	}
	return s
}
