```go
package docparser

import (
	"bufio"
	"fmt"
	"io"
	"regexp"
	"strings"
	"time"
	"unicode"
)

var (
	reHeading      = regexp.MustCompile(`^(#{1,6})\s+(.+)$`)
	reFrontmatter  = regexp.MustCompile(`^---\s*$`)
	reFrontmatterKV = regexp.MustCompile(`^(\w[\w\s]*?):\s*(.+)$`)
)

// MarkdownParser parses Markdown documents, extracting headings as sections
// and optional YAML-like frontmatter as metadata.
type MarkdownParser struct{}

// NewMarkdownParser returns a new MarkdownParser.
func NewMarkdownParser() *MarkdownParser {
	return &MarkdownParser{}
}

func (p *MarkdownParser) SupportedFormat() Format { return FormatMarkdown }

func (p *MarkdownParser) Parse(r io.Reader) (*Document, error) {
	if r == nil {
		return nil, ErrNilReader
	}

	data, err := io.ReadAll(r)
	if err != nil {
		return nil, newParseError(FormatMarkdown, "failed to read input", err)
	}

	return p.parse(string(data))
}

func (p *MarkdownParser) ParseString(s string) (*Document, error) {
	return p.parse(s)
}

func (p *MarkdownParser) parse(raw string) (*Document, error) {
	trimmed := strings.TrimSpace(raw)
	if len(trimmed) == 0 {
		return nil, ErrEmptyInput
	}

	doc := &Document{
		Format:   FormatMarkdown,
		Raw:      raw,
		ParsedAt: time.Now().UTC(),
		Metadata: Metadata{Extra: make(map[string]string)},
	}

	body := raw

	// Extract frontmatter if present.
	if strings.HasPrefix(trimmed, "---") {
		fm, rest, ok := extractFrontmatter(trimmed)
		if ok {
			parseFrontmatter(fm, &doc.Metadata)
			body = rest
		}
	}

	// Parse body into sections.
	doc.Sections = parseMarkdownSections(body)

	// Infer title from metadata or first H1.
	if doc.Metadata.Extra["title"] != "" {
		doc.Title = doc.Metadata.Extra["title"]
		delete(doc.Metadata.Extra, "title")
	} else if len(doc.Sections) > 0 && doc.Sections[0].Level == 1 {
		doc.Title = doc.Sections[0].Title
	}

	if doc.Metadata.Author == "" && doc.Metadata.Extra["author"] != "" {
		doc.Metadata.Author = doc.Metadata.Extra["author"]
		delete(doc.Metadata.Extra, "author")
	}
	if doc.Metadata.Date == "" && doc.Metadata.Extra["date"] != "" {
		doc.Metadata.Date = doc.Metadata.Extra["date"]
		delete(doc.Metadata.Extra, "date")
	}
	if doc.Metadata.Description == "" && doc.Metadata.Extra["description"] != "" {
		doc.Metadata.Description = doc.Metadata.Extra["description"]
		delete(doc.Metadata.Extra, "description")
	}

	return doc, nil
}

// extractFrontmatter splits "---\n...\n---\nbody" into frontmatter lines and body.
func extractFrontmatter(s string) (frontmatter string, body string, ok bool) {
	lines := strings.SplitAfter(s, "\n")
	if len(lines) < 3 {
		return "", s, false
	}

	// First line must be "---"
	if !reFrontmatter.MatchString(strings.TrimRight(lines[0], "\n\r")) {
		return "", s, false
	}

	// Find closing "---"
	for i := 1; i < len(lines); i++ {
		trimLine := strings.TrimRight(lines[i], "\n\r")
		if reFrontmatter.MatchString(trimLine) {
			fm := strings.Join(lines[1:i], "")
			rest := strings.Join(lines[i+1:], "")
			return fm, rest, true
		}
	}
	return "", s, false
}

// parseFrontmatter extracts key-value pairs from simple frontmatter.
func parseFrontmatter(fm string, meta *Metadata) {
	scanner := bufio.NewScanner(strings.NewReader(fm))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		matches := reFrontmatterKV.FindStringSubmatch(line)
		if len(matches) != 3 {
			continue
		}
		key := strings.TrimSpace(strings.ToLower(matches[1]))
		value := strings.TrimSpace(matches[2])

		switch key {
		case "author":
			meta.Author = value
		case "date":
			meta.Date = value
		case "description":
			meta.Description = value
		case "tags":
			meta.Tags = splitTags(value)
		default:
			meta.Extra[key] = value
		}
	}
}

func splitTags(s string) []string {
	// Support comma-separated and bracket-enclosed lists.
	s = strings.Trim(s, "[]")
	parts := strings.Split(s, ",")
	tags := make([]string, 0, len(parts))
	for _, p := range parts {
		t := strings.TrimSpace(p)
		if t != "" {
			tags = append(tags, t)
		}
	}
	return tags
}

