## `src/main.rs`

```rust
use serde::Deserialize;
use std::collections::HashMap;
use std::fmt;
use std::fs;
use std::time::Instant;
use thiserror::Error;

// ─── Error Types ──────────────────────────────────────────────

#[derive(Error, Debug)]
enum AppError {
    #[error("Failed to read config file: {0}")]
    IoError(#[from] std::io::Error),

    #[error("Failed to parse config: {0}")]
    ParseError(#[from] toml::de::Error),

    #[error("Config validation error: {0}")]
    ValidationError(String),

    #[error("Unknown rate limit policy: {0}")]
    UnknownPolicy(String),
}

// ─── Config Structures ───────────────────────────────────────

#[derive(Debug, Deserialize)]
struct AppConfig {
    server: ServerConfig,
    rate_limit: RateLimitConfig,
}

#[derive(Debug, Deserialize)]
struct ServerConfig {
    host: String,
    port: u16,
}

#[derive(Debug, Deserialize)]
struct RateLimitConfig {
    default: RateLimitRule,
    #[serde(default)]
    policies: HashMap<String, RateLimitRule>,
    #[serde(default)]
    endpoints: Vec<EndpointRateLimit>,
}

#[derive(Debug, Clone, Deserialize)]
struct RateLimitRule {
    requests_per_second: f64,
    burst_size: u32,
    #[serde(default = "default_strategy")]
    strategy: RateLimitStrategy,
}

#[derive(Debug, Clone, Deserialize)]
struct EndpointRateLimit {
    path: String,
    #[serde(default = "default_method")]
    method: String,
    requests_per_second: f64,
    burst_size: u32,
}

#[derive(Debug, Clone, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
enum RateLimitStrategy {
    TokenBucket,
    SlidingWindow,
    FixedWindow,
}

fn default_strategy() -> RateLimitStrategy {
    RateLimitStrategy::TokenBucket
}

fn default_method() -> String {
    "GET".to_string()
}

// ─── Config Parsing & Validation ─────────────────────────────

impl AppConfig {
    /// Load config from a TOML file path
    fn from_file(path: &str) -> Result<Self, AppError> {
        let content = fs::read_to_string(path)?;
        Self::from_str(&content)
    }

    /// Parse config from a TOML string
    fn from_str(content: &str) -> Result<Self, AppError> {
        let config: AppConfig = toml::from_str(content)?;
        config.validate()?;
        Ok(config)
    }

    /// Validate parsed config values
    fn validate(&self) -> Result<(), AppError> {
        self.validate_rule("default", &self.rate_limit.default)?;

        for (name, rule) in &self.rate_limit.policies {
            self.validate_rule(name, rule)?;
        }

        for endpoint in &self.rate_limit.endpoints {
            if endpoint.requests_per_second <= 0.0 {
                return Err(AppError::ValidationError(format!(
                    "Endpoint {} {} has invalid requests_per_second: {}",
                    endpoint.method, endpoint.path, endpoint.requests_per_second
                )));
            }
            if endpoint.burst_size == 0 {
                return Err(AppError::ValidationError(format!(
                    "Endpoint {} {} has zero burst_size",
                    endpoint.method, endpoint.path
                )));
            }
        }

        Ok(())
    }

    fn validate_rule(&self, name: &str, rule: &RateLimitRule) -> Result<(), AppError> {
        if rule.requests_per_second <= 0.0 {
            return Err(AppError::ValidationError(format!(
                "Policy '{}' has invalid requests_per_second: {}",
                name, rule.requests_per_second
            )));
        }
        if rule.burst_size == 0 {
            return Err(AppError::ValidationError(format!(
                "Policy '{}' has zero burst_size",
                name
            )));
        }
        if (rule.burst_size as f64) < rule.requests_per_second {
            return Err(AppError::ValidationError(format!(
                "Policy '{}': burst_size ({}) should be >= requests_per_second ({})",
                name, rule.burst_size, rule.requests_per_second
            )));
        }
        Ok(())
    }

    /// Get the rate limit rule for a specific endpoint, falling back to default
    fn rule_for_endpoint(&self, method: &str, path: &str) -> RateLimitRule {
        self.rate_limit
            .endpoints
            .iter()
            .find(|e| e.method.eq_ignore_ascii_case(method) && e.path == path)
            .map(|e| RateLimitRule {
                requests_per_second: e.requests_per_second,
                burst_size: e.burst_size,
                strategy: self.rate_limit.default.strategy.clone(),
            })
            .unwrap_or_else(|| self.rate_limit.default.clone())
    }

    /// Get a named policy
    fn policy(&self, name: &str) -> Result<&RateLimitRule, AppError> {
        self.rate_limit
            .policies
            .get(name)
            .ok_or_else(|| AppError::UnknownPolicy(name.to_string()))
    }
}

// ─── Token Bucket Rate Limiter ───────────────────────────────

/// A token bucket rate limiter driven by config rules
struct TokenBucket {
    capacity: f64,       // max tokens (burst_size)
    tokens: f64,         // current available tokens
    refill_rate: f64,    // tokens added per second
    last_refill: Instant, // last time tokens were added
}

/// Result returned when checking the rate limit
#[derive(Debug)]
struct RateLimitResult {
    allowed: bool,
    tokens_remaining: u32,
    retry_after_ms: Option<u64>,
}

impl fmt::Display for RateLimitResult {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.allowed {
            write!(f, "✅ ALLOWED ({} tokens remaining)", self.tokens_remaining)
        } else {
            write!(
                f,
                "🚫 DENIED (retry after {}ms)",
                self.retry_after_ms.unwrap_or(0)
            )
        }
    }
}

impl TokenBucket {
    /// Create a new bucket from a parsed config rule
    fn from_rule(rule: &RateLimitRule) -> Self {
        Self {
            capacity: rule.burst_size as f64,
            tokens: rule.burst_size as f64, // start full
            refill_rate: rule.requests_per_second,
            last_refill: Instant::now(),
        }
    }

    /// Refill tokens based on elapsed time
    fn refill(&mut self) {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill).as_secs_f64();
        self.tokens = (self.tokens + elapsed * self.refill_rate).min(self.capacity);
        self.last_refill = now;
    }

    /// Try to consume one token; returns detailed result
    fn try_acquire(&mut self) -> RateLimitResult {
        self.try_acquire_n(1)
    }

    /// Try to consume `n` tokens at once (for weighted requests)
    fn try_acquire_n(&mut self, n: u32) -> RateLimitResult {
        self.refill();

        let cost = n as f64;
        if self.tokens >= cost {
            self.tokens -= cost;
            RateLimitResult {
                allowed: true,
                tokens_remaining: self.tokens as u32,
                retry_after_ms: None,
            }
        } else {
            let deficit = cost - self.tokens;
            let wait_secs = deficit / self.refill_rate;
            RateLimitResult {
                allowed: false,
                tokens_remaining: 0,
                retry_after_ms: Some((wait_secs * 1000.0).ceil() as u64),
            }
        }
    }

    /// Current state snapshot (useful for metrics / headers)
    fn status(&mut self) -> (u32, u32) {
        self.refill();
        (self.tokens as u32, self.capacity as u32)
    }
}

// ─── Rate Limiter Registry ───────────────────────────────────

/// Manages per-key rate limiters (e.g., per client IP or API key)
struct RateLimiterRegistry {
    rule: RateLimitRule,
    buckets: HashMap<String, TokenBucket>,
}

impl RateLimiterRegistry {
    fn new(rule: RateLimitRule) -> Self {
        Self {
            rule,
            buckets: HashMap::new(),
        }
    }

    /// Check rate limit for a given key (IP, user ID, API key, etc.)
    fn check(&mut self, key: &str) -> RateLimitResult {
        let rule = &self.rule;
        let bucket = self
            .buckets
            .entry(key.to_string())
            .or_insert_with(|| TokenBucket::from_rule(rule));
        bucket.try_acquire()
    }

    /// Get status for a key without consuming a token
    fn status(&mut self, key: &str) -> (u32, u32) {
        let rule = &self.rule;
        let bucket = self
            .buckets
            .entry(key.to_string())
            .or_insert_with(|| TokenBucket::from_rule(rule));
        bucket.status()
    }
}

// ─── Demo / Main ─────────────────────────────────────────────

fn main() -> Result<(), AppError> {
    // Parse config from file (or fall back to embedded string for demo)
    let config = match AppConfig::from_file("config.toml") {
        Ok(cfg) => cfg,
        Err(_) => {
            println!("⚠ config.toml not found, using embedded config\n");
            AppConfig::from_str(EMBEDDED_CONFIG)?
        }
    };

    println!("═══ Parsed Configuration ═══\n");
    println!("Server: {}:{}", config.server.host, config.server.port);
    println!(
        "Default limit: {:.0} req/s, burst {}",
