    );
    println!("\nPolicies:");
    for (name, rule) in &config.rate_limit.policies {
        println!("  {:<10} → {:.0} req/s, burst {}", name, rule.requests_per_second, rule.burst_size);
    }
    println!("\nEndpoint overrides:");
    for ep in &config.rate_limit.endpoints {
        println!(
            "  {:<6} {:<15} → {:.0} req/s, burst {}",
            ep.method, ep.path, ep.requests_per_second, ep.burst_size
        );
    }

    // ── Demo 1: Single bucket from default rule ──
    println!("\n═══ Demo 1: Default Rate Limit ═══\n");
    let mut bucket = TokenBucket::from_rule(&config.rate_limit.default);
    for i in 1..=25 {
        let result = bucket.try_acquire();
        println!("  Request {i:>2}: {result}");
    }

    // ── Demo 2: Per-endpoint rule lookup ──
    println!("\n═══ Demo 2: Endpoint-Specific Rules ═══\n");
    let login_rule = config.rule_for_endpoint("POST", "/api/login");
    let mut login_bucket = TokenBucket::from_rule(&login_rule);
    println!("POST /api/login → {:.0} req/s, burst {}", login_rule.requests_per_second, login_rule.burst_size);
    for i in 1..=8 {
