## lib/store.js — Persistent JSON Storage

```javascript
const fs = require("fs");
const path = require("path");

const DATA_DIR = path.join(require("os").homedir(), ".taskr");
const TASKS_FILE = path.join(DATA_DIR, "tasks.json");
const HISTORY_FILE = path.join(DATA_DIR, "history.json");

// Ensure data directory and files exist on first run
function init() {
  if (!fs.existsSync(DATA_DIR)) {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  }
  if (!fs.existsSync(TASKS_FILE)) {
    fs.writeFileSync(TASKS_FILE, "[]");
  }
  if (!fs.existsSync(HISTORY_FILE)) {
    fs.writeFileSync(HISTORY_FILE, "[]");
  }
}

function readJSON(filepath) {
  try {
    return JSON.parse(fs.readFileSync(filepath, "utf-8"));
  } catch {
    return [];
  }
}

function writeJSON(filepath, data) {
  fs.writeFileSync(filepath, JSON.stringify(data, null, 2));
}

// ── Task CRUD ──────────────────────────────────────────────

function getTasks() {
  init();
  return readJSON(TASKS_FILE);
}

function saveTasks(tasks) {
  init();
  writeJSON(TASKS_FILE, tasks);
}

function addTask(task) {
  const tasks = getTasks();
  tasks.push(task);
  saveTasks(tasks);
  return task;
}

function removeTask(id) {
  const tasks = getTasks();
  const index = tasks.findIndex((t) => t.id === id);
  if (index === -1) return null;
  const [removed] = tasks.splice(index, 1);
  saveTasks(tasks);
  return removed;
}

function updateTask(id, updates) {
  const tasks = getTasks();
  const task = tasks.find((t) => t.id === id);
  if (!task) return null;
  Object.assign(task, updates);
  saveTasks(tasks);
  return task;
}

function findTask(idPrefix) {
  const tasks = getTasks();
  // Support partial ID matching (first 6+ chars)
  const matches = tasks.filter((t) => t.id.startsWith(idPrefix));
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) return { ambiguous: true, matches };
  return null;
}

// ── History Logging ────────────────────────────────────────

const MAX_HISTORY = 500;

function getHistory() {
  init();
  return readJSON(HISTORY_FILE);
}

function addHistoryEntry(entry) {
  const history = getHistory();
  history.push(entry);
  // Trim old entries to prevent unbounded growth
  if (history.length > MAX_HISTORY) {
    history.splice(0, history.length - MAX_HISTORY);
  }
  writeJSON(HISTORY_FILE, history);
}

module.exports = {
  getTasks,
  saveTasks,
  addTask,
  removeTask,
  updateTask,
  findTask,
  getHistory,
  addHistoryEntry,
  DATA_DIR,
};
```

## lib/display.js — Terminal Output Formatting

```javascript
const chalk = require("chalk");

const SYMBOLS = {
  success: chalk.green("✔"),
  error: chalk.red("✖"),
  info: chalk.blue("ℹ"),
  warning: chalk.yellow("⚠"),
  bullet: chalk.gray("•"),
  arrow: chalk.gray("→"),
};

// ── Table Rendering (zero-dependency) ──────────────────────

function renderTable(headers, rows, colWidths) {
  const divider = colWidths.map((w) => "─".repeat(w)).join("─┼─");

  const formatRow = (cells) =>
    cells.map((cell, i) => String(cell).padEnd(colWidths[i])).join(" │ ");

  console.log(chalk.bold(formatRow(headers)));
  console.log(chalk.gray(divider));
  rows.forEach((row) => console.log(formatRow(row)));
}

// ── Task Listing ───────────────────────────────────────────

function displayTasks(tasks) {
  if (tasks.length === 0) {
    console.log(chalk.gray("\n  No tasks scheduled. Add one with:"));
    console.log(chalk.cyan('  taskr add "backup" --cmd "tar -czf ..." --cron "0 2 * * *"\n'));
    return;
  }

  console.log(chalk.bold(`\n  Scheduled Tasks (${tasks.length})\n`));

  const headers = ["ID", "Name", "Schedule", "Command", "Status"];
  const colWidths = [8, 18, 18, 30, 10];

  const rows = tasks.map((t) => [
    chalk.gray(t.id.slice(0, 8)),
    chalk.white(truncate(t.name, 18)),
    chalk.cyan(t.cron),
    chalk.gray(truncate(t.command, 30)),
    t.enabled ? chalk.green("enabled") : chalk.red("disabled"),
  ]);

  renderTable(headers, rows, colWidths);
  console.log();
}

// ── History Display ────────────────────────────────────────

function displayHistory(history, limit = 20) {
  const entries = history.slice(-limit).reverse();

  if (entries.length === 0) {
    console.log(chalk.gray("\n  No execution history yet.\n"));
    return;
  }

  console.log(chalk.bold(`\n  Execution History (last ${entries.length})\n`));

  const headers = ["Time", "Task", "Duration", "Status", "Output"];
  const colWidths = [20, 16, 10, 8, 36];

  const rows = entries.map((e) => {
    const time = new Date(e.timestamp).toLocaleString();
    const dur = `${e.durationMs}ms`;
    const status = e.exitCode === 0 ? chalk.green("OK") : chalk.red(`ERR:${e.exitCode}`);
    const output = truncate((e.stdout || e.stderr || "").trim(), 36);
    return [chalk.gray(time), chalk.white(e.taskName), dur, status, chalk.gray(output)];
  });

  renderTable(headers, rows, colWidths);
  console.log();
}

// ── Helpers ────────────────────────────────────────────────

function truncate(str, max) {
  if (!str) return "";
  return str.length > max ? str.slice(0, max - 1) + "…" : str;
}

function success(msg) {
  console.log(`  ${SYMBOLS.success} ${msg}`);
}
function error(msg) {
  console.log(`  ${SYMBOLS.error} ${msg}`);
}
function info(msg) {
  console.log(`  ${SYMBOLS.info} ${msg}`);
}
function warning(msg) {
  console.log(`  ${SYMBOLS.warning} ${msg}`);
}

module.exports = {
  displayTasks,
  displayHistory,
  success,
  error,
  info,
  warning,
  SYMBOLS,
};
