## lib/scheduler.js — Cron Execution Engine

```javascript
const cron = require("node-cron");
const { exec } = require("child_process");
const store = require("./store");
const display = require("./display");
const chalk = require("chalk");

const activeJobs = new Map(); // id → cron job instance

// ── Execute a single task ──────────────────────────────────

function executeTask(task) {
  return new Promise((resolve) => {
    const start = Date.now();

    display.info(`Running "${task.name}" ${display.SYMBOLS.arrow} ${chalk.gray(task.command)}`);

    const child = exec(task.command, {
      timeout: (task.timeoutSec || 300) * 1000,  // default 5 min timeout
      shell: true,
      env: { ...process.env, TASKR_NAME: task.name, TASKR_ID: task.id },
    });

    let stdout = "";
    let stderr = "";

    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stderr += d));

    child.on("close", (exitCode) => {
      const durationMs = Date.now() - start;

      const entry = {
        taskId: task.id,
        taskName: task.name,
        command: task.command,
        timestamp: new Date().toISOString(),
        exitCode: exitCode ?? 1,
        durationMs,
        stdout: stdout.slice(0, 2000), // cap stored output
        stderr: stderr.slice(0, 2000),
      };

      store.addHistoryEntry(entry);

      if (exitCode === 0) {
        display.success(`"${task.name}" completed in ${durationMs}ms`);
      } else {
        display.error(`"${task.name}" failed (exit ${exitCode}) — ${stderr.trim().slice(0, 100)}`);
      }

      // Update last-run metadata on the task
      store.updateTask(task.id, {
        lastRun: entry.timestamp,
        lastExitCode: exitCode,
      });

      resolve(entry);
    });

    child.on("error", (err) => {
      const entry = {
        taskId: task.id,
        taskName: task.name,
        command: task.command,
        timestamp: new Date().toISOString(),
        exitCode: 1,
        durationMs: Date.now() - start,
        stdout: "",
        stderr: err.message,
      };
      store.addHistoryEntry(entry);
      display.error(`"${task.name}" error: ${err.message}`);
      resolve(entry);
    });
  });
}

// ── Schedule all enabled tasks ─────────────────────────────

function startAll() {
  const tasks = store.getTasks();
  const enabled = tasks.filter((t) => t.enabled);

  if (enabled.length === 0) {
    display.warning("No enabled tasks to schedule.");
    process.exit(0);
  }

  console.log(chalk.bold(`\n  taskr scheduler started — ${enabled.length} task(s)\n`));

  enabled.forEach((task) => scheduleTask(task));

  // Watch for task file changes so we can reload without restart
  const fs = require("fs");
  let debounce = null;
  fs.watch(store.DATA_DIR, () => {
    clearTimeout(debounce);
    debounce = setTimeout(() => reloadTasks(), 500);
  });

  // Graceful shutdown
  const shutdown = () => {
    console.log(chalk.gray("\n  Shutting down scheduler..."));
    activeJobs.forEach((job) => job.stop());
    process.exit(0);
  };
  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);

  display.info("Watching for task changes. Press Ctrl+C to stop.\n");
}

function scheduleTask(task) {
  if (!cron.validate(task.cron)) {
    display.error(`Invalid cron "${task.cron}" for task "${task.name}"`);
    return;
  }

  const job = cron.schedule(task.cron, () => executeTask(task), {
    scheduled: true,
    timezone: task.timezone || undefined,
  });

  activeJobs.set(task.id, job);
  display.info(
    `Scheduled "${task.name}" ${display.SYMBOLS.arrow} ${chalk.cyan(task.cron)}`
  );
}

function reloadTasks() {
  const tasks = store.getTasks();

  // Stop removed or disabled tasks
  activeJobs.forEach((job, id) => {
    const task = tasks.find((t) => t.id === id);
    if (!task || !task.enabled) {
      job.stop();
      activeJobs.delete(id);
      display.info(`Unscheduled task ${id.slice(0, 8)}`);
    }
  });

  // Start newly added or re-enabled tasks
  tasks
    .filter((t) => t.enabled && !activeJobs.has(t.id))
    .forEach((task) => scheduleTask(task));
}

module.exports = { executeTask, startAll };
```

