  .command("add <name>")
  .description("Schedule a new task")
  .requiredOption("-c, --cmd <command>", "Shell command to execute")
  .requiredOption("--cron <expression>", "Cron schedule (e.g. '*/5 * * * *')")
  .option("-t, --timeout <seconds>", "Kill task after N seconds", "300")
  .option("--tz <timezone>", "IANA timezone (e.g. America/New_York)")
  .option("--disabled", "Create in disabled state")
  .action((name, opts) => {
    // Validate cron expression before saving
    if (!cron.validate(opts.cron)) {
      display.error(`Invalid cron expression: "${opts.cron}"`);
      console.log(chalk.gray("  Examples:"));
      console.log(chalk.gray("    */5 * * * *     → every 5 minutes"));
      console.log(chalk.gray("    0 9 * * 1-5     → weekdays at 9am"));
      console.log(chalk.gray("    0 0 1 * *       → 1st of each month"));
      process.exit(1);
    }

    const task = {
      id: uuidv4(),
      name,
      command: opts.cmd,
      cron: opts.cron,
      timeoutSec: parseInt(opts.timeout, 10),
      timezone: opts.tz || null,
      enabled: !opts.disabled,
      createdAt: new Date().toISOString(),
      lastRun: null,
      lastExitCode: null,
    };

    store.addTask(task);
    console.log();
    display.success(`Task "${chalk.bold(name)}" created`);
    console.log(chalk.gray(`  ID:       ${task.id.slice(0, 8)}`));
    console.log(chalk.gray(`  Schedule: ${task.cron}`));
    console.log(chalk.gray(`  Command:  ${task.command}`));
    console.log();
  });

// ── LIST ───────────────────────────────────────────────────

program
  .command("list")
  .alias("ls")
  .description("Show all scheduled tasks")
  .option("-a, --all", "Include disabled tasks", true)
  .action(() => {
    const tasks = store.getTasks();
    display.displayTasks(tasks);
  });

// ── REMOVE ─────────────────────────────────────────────────

program
  .command("remove <id>")
  .alias("rm")
  .description("Delete a task (supports partial ID)")
  .action((id) => {
    const result = store.findTask(id);

    if (!result) {
      display.error(`No task found matching "${id}"`);
      process.exit(1);
    }
    if (result.ambiguous) {
      display.error(`Ambiguous ID "${id}" matches ${result.matches.length} tasks:`);
      result.matches.forEach((t) =>
        console.log(chalk.gray(`  ${t.id.slice(0, 8)} — ${t.name}`))
      );
      process.exit(1);
    }

    store.removeTask(result.id);
    display.success(`Removed "${result.name}" (${result.id.slice(0, 8)})`);
  });

// ── ENABLE / DISABLE ──────────────────────────────────────

program
  .command("enable <id>")
  .description("Enable a task")
  .action((id) => toggleTask(id, true));

program
  .command("disable <id>")
  .description("Disable a task")
  .action((id) => toggleTask(id, false));

function toggleTask(id, enabled) {
  const result = store.findTask(id);
  if (!result || result.ambiguous) {
    display.error(result?.ambiguous ? "Ambiguous ID" : "Task not found");
    process.exit(1);
  }
  store.updateTask(result.id, { enabled });
