## Metrics Collector

```typescript
// src/monitoring/Metrics.ts

import { PipelineMetrics, StageMetrics } from '../types';

export class MetricsCollector {
  private eventsProcessed = 0;
  private eventsFailed = 0;
  private eventsRetried = 0;
  private eventsDeadLettered = 0;
  private processingTimes: number[] = [];
  private stageMetrics: Map<string, InternalStageMetrics> = new Map();

  recordEventProcessed(durationMs: number): void {
    this.eventsProcessed++;
    this.processingTimes.push(durationMs);
    // Keep a rolling window of 10,000 entries
    if (this.processingTimes.length > 10_000) {
      this.processingTimes = this.processingTimes.slice(-10_000);
    }
  }

  recordEventFailed(): void {
    this.eventsFailed++;
  }

  recordEventRetried(): void {
    this.eventsRetried++;
  }

  recordEventDeadLettered(): void {
    this.eventsDeadLettered++;
  }

  recordStageExecution(stageName: string, durationMs: number, success: boolean): void {
    let metrics = this.stageMetrics.get(stageName);
    if (!metrics) {
      metrics = { durations: [], successes: 0, failures: 0, retries: 0 };
      this.stageMetrics.set(stageName, metrics);
    }

    metrics.durations.push(durationMs);
    if (metrics.durations.length > 10_000) {
      metrics.durations = metrics.durations.slice(-10_000);
    }

    if (success) {
      metrics.successes++;
    } else {
      metrics.failures++;
    }
  }

  recordStageRetry(stageName: string): void {
    const metrics = this.stageMetrics.get(stageName);
    if (metrics) {
      metrics.retries++;
    }
  }

  getMetrics(): PipelineMetrics {
    const stageMetricsMap = new Map<string, StageMetrics>();

    for (const [name, internal] of this.stageMetrics) {
      const sorted = [...internal.durations].sort((a, b) => a - b);
      stageMetricsMap.set(name, {
        executions: internal.successes + internal.failures,
        successes: internal.successes,
        failures: internal.failures,
        retries: internal.retries,
        avgDurationMs: this.average(sorted),
        p95DurationMs: this.percentile(sorted, 0.95),
        p99DurationMs: this.percentile(sorted, 0.99),
      });
    }

    return {
      eventsProcessed: this.eventsProcessed,
      eventsFailed: this.eventsFailed,
      eventsRetried: this.eventsRetried,
      eventsDeadLettered: this.eventsDeadLettered,
      avgProcessingTimeMs: this.average(this.processingTimes),
      stageMetrics: stageMetricsMap,
    };
  }

  reset(): void {
    this.eventsProcessed = 0;
    this.eventsFailed = 0;
    this.eventsRetried = 0;
    this.eventsDeadLettered = 0;
    this.processingTimes = [];
    this.stageMetrics.clear();
  }

  private average(values: number[]): number {
    if (values.length === 0) return 0;
    return values.reduce((sum, v) => sum + v, 0) / values.length;
  }

  private percentile(sorted: number[], p: number): number {
    if (sorted.length === 0) return 0;
    const idx = Math.ceil(sorted.length * p) - 1;
    return sorted[Math.max(0, idx)];
  }
}

interface InternalStageMetrics {
  durations: number[];
  successes: number;
  failures: number;
  retries: number;
}
