## Retry Strategies

```typescript
// src/retry/RetryStrategies.ts

import { RetryConfig } from '../types';

export function computeDelay(attempt: number, config: RetryConfig): number {
  const exponentialDelay = config.baseDelayMs * Math.pow(config.backoffMultiplier, attempt);
  const bounded = Math.min(exponentialDelay, config.maxDelayMs);

  if (!config.jitter) {
    return bounded;
  }

  // Full jitter: uniform random between 0 and bounded delay
  return Math.floor(Math.random() * bounded);
}

export function isRetryable(error: Error, config: RetryConfig): boolean {
  // NonRetryableError is never retried
  if (error.name === 'NonRetryableError') {
    return false;
  }

  // RetryableError is always retried
  if (error.name === 'RetryableError') {
    return true;
  }

  // If specific retryable error classes are configured, check membership
  if (config.retryableErrors && config.retryableErrors.length > 0) {
    return config.retryableErrors.some((ErrorClass) => error instanceof ErrorClass);
  }

  // Default: retry all errors except NonRetryableError
  return true;
}

export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxRetries: 3,
  baseDelayMs: 1000,
  maxDelayMs: 30_000,
  backoffMultiplier: 2,
  jitter: true,
};
