## Retry Policy

```typescript
// src/retry/RetryPolicy.ts

import { RetryConfig, RetryableError } from '../types';
import { computeDelay, isRetryable, sleep } from './RetryStrategies';
import { Logger } from '../monitoring/Logger';
import { MetricsCollector } from '../monitoring/Metrics';

export interface RetryResult<T> {
  success: boolean;
  result?: T;
  error?: Error;
  attempts: number;
  totalDelayMs: number;
}

export class RetryPolicy {
  private readonly logger = Logger.getInstance();

  constructor(
    private readonly config: RetryConfig,
    private readonly metrics: MetricsCollector,
    private readonly contextName: string = 'unknown'
  ) {}

  async execute<T>(
    operation: () => Promise<T>,
    operationName: string = 'operation'
  ): Promise<RetryResult<T>> {
    let lastError: Error | undefined;
    let attempts = 0;
    let totalDelayMs = 0;

    for (let attempt = 0; attempt <= this.config.maxRetries; attempt++) {
      attempts = attempt + 1;

      try {
        const result = await operation();
        return {
          success: true,
          result,
          attempts,
          totalDelayMs,
        };
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));

        this.logger.warn(`${this.contextName}/${operationName} failed on attempt ${attempts}`, {
          error: lastError.message,
          attempt: attempts,
          maxRetries: this.config.maxRetries,
        });

        // Check if we've exhausted retries
        if (attempt >= this.config.maxRetries) {
          break;
        }

        // Check if error is retryable
        if (!isRetryable(lastError, this.config)) {
          this.logger.error(`${this.contextName}/${operationName}: non-retryable error`, {
            error: lastError.message,
            errorType: lastError.name,
          });
          break;
        }

        // Calculate delay with potential override from RetryableError
        let delayMs = computeDelay(attempt, this.config);
        if (lastError instanceof RetryableError && lastError.retryAfterMs) {
          delayMs = Math.max(delayMs, lastError.retryAfterMs);
        }

        this.logger.info(`${this.contextName}/${operationName}: retrying in ${delayMs}ms`, {
          attempt: attempts,
          delayMs,
        });

        this.metrics.recordEventRetried();
        if (this.contextName !== 'unknown') {
          this.metrics.recordStageRetry(this.contextName);
        }

        await sleep(delayMs);
        totalDelayMs += delayMs;
      }
    }

    return {
      success: false,
      error: lastError,
      attempts,
      totalDelayMs,
    };
  }
}
