```typescript
// src/retry/CircuitBreaker.ts

import { CircuitOpenError, CircuitState } from '../types';
import { Logger } from '../monitoring/Logger';

export interface CircuitBreakerConfig {
  failureThreshold: number;   // failures before opening
  resetTimeoutMs: number;     // time before half-open
  halfOpenMaxAttempts: number; // attempts in half-open before closing
}

export class CircuitBreaker {
  private state: CircuitState = CircuitState.CLOSED;
  private failureCount = 0;
  private successCount = 0;
  private lastFailureTime = 0;
  private halfOpenAttempts = 0;
  private readonly logger = Logger.getInstance();

  constructor(
    private readonly name: string,
    private readonly config: CircuitBreakerConfig
  ) {}

  getState(): CircuitState {
    // Auto-transition from OPEN to HALF_OPEN after timeout
    if (
      this.state === CircuitState.OPEN &&
      Date.now() - this.lastFailureTime >= this.config.resetTimeoutMs
    ) {
      this.logger.info(`Circuit breaker "${this.name}": OPEN -> HALF_OPEN`);
      this.state = CircuitState.HALF_OPEN;
      this.halfOpenAttempts = 0;
    }
    return this.state;
  }

  async execute<T>(operation: () => Promise<T>): Promise<T> {
    const currentState = this.getState();

    if (currentState === CircuitState.OPEN) {
      const resetIn = this.config.resetTimeoutMs - (Date.now() - this.lastFailureTime);
      throw new CircuitOpenError(Math.max(0, resetIn));
    }

    try {
      const result = await operation();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      throw error;
    }
  }

  private onSuccess(): void {
    if (this.state === CircuitState.HALF_OPEN) {
      this.halfOpenAttempts++;
      if (this.halfOpenAttempts >= this.config.halfOpenMaxAttempts) {
        this.logger.info(`Circuit breaker "${this.name}": HALF_OPEN -> CLOSED`);
        this.state = CircuitState.CLOSED;
        this.failureCount = 0;
        this.successCount = 0;
      }
    }
    this.successCount++;
  }

  private onFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();

    if (this.state === CircuitState.HALF_OPEN) {
      this.logger.warn(`Circuit breaker "${this.name}": HALF_OPEN -> OPEN`);
      this.state = CircuitState.OPEN;
      return;
    }

    if (this.failureCount >= this.config.failureThreshold) {
      this.logger.warn(
        `Circuit breaker "${this.name}": CLOSED -> OPEN (${this.failureCount} failures)`
      );
      this.state = CircuitState.OPEN;
    }
  }

  reset(): void {
    this.state = CircuitState.CLOSED;
    this.failureCount = 0;
    this.successCount = 0;
    this.halfOpenAttempts = 0;
    this.lastFailureTime = 0;
  }

  getStats() {
    return {
      name: this.name,
      state: this.getState(),
      failureCount: this.failureCount,
      successCount: this.successCount,
    };
  }
}
