// ✅ FIXED VERSION - Report Generation Scheduler
class ReportScheduler {
  constructor(options = {}) {
    this.jobs = new Map();                    // ✅ Fix: Use Map for O(1) lookups
    this.running = false;
    this.timers = new Map();                  // ✅ Fix: Track timers per job
    this.maxConcurrent = options.maxConcurrent || 3;
    this.activeCount = 0;
    this.queue = [];
    this.logger = options.logger || console;
  }

  // ✅ Fix 1: Correct interval calculations with validation
  parseInterval(schedule) {
    const units = {
      's': 1000,
      'm': 60 * 1000,
      'h': 60 * 60 * 1000,       // ✅ Fixed: 3,600,000
      'd': 24 * 60 * 60 * 1000   // ✅ Fixed: 86,400,000
    };

    if (typeof schedule !== 'string' || schedule.length < 2) {
      throw new Error(`Invalid schedule format: "${schedule}". Use e.g. "30m", "1h", "24h".`);
    }

    const value = parseInt(schedule, 10);
    const unit = schedule.slice(-1).toLowerCase();

    if (isNaN(value) || value <= 0) {
      throw new Error(`Invalid schedule value: "${schedule}". Must be a positive number.`);
    }
    if (!units[unit]) {
      throw new Error(`Invalid schedule unit: "${unit}". Use s, m, h, or d.`);
    }

    return value * units[unit];
  }

  // ✅ Fix 2: Input validation and duplicate checking
  addJob(name, schedule, reportFn, options = {}) {
    if (!name || typeof name !== 'string') {
      throw new Error('Job name must be a non-empty string.');
    }
    if (typeof reportFn !== 'function') {
      throw new Error('reportFn must be a function.');
    }
    if (this.jobs.has(name)) {
      throw new Error(`Job "${name}" already exists. Remove it first or use a unique name.`);
    }

    // Validate schedule before adding
    const interval = this.parseInterval(schedule);

    const job = {
      name,
      schedule,
      interval,
      reportFn,
      lastRun: null,
      nextRun: null,
      status: 'pending',
      retries: 0,
      maxRetries: options.maxRetries ?? 3,
      retryDelay: options.retryDelay ?? 5000,
      timeout: options.timeout ?? 30000,
      runCount: 0,
      errorCount: 0,
      lastError: null,
    };

    this.jobs.set(name, job);
    this.logger.log(`[Scheduler] Job "${name}" added (every ${schedule}).`);
    return this;        // ✅ Chainable API
  }

  // ✅ Fix 3: Concurrency control with queue
  async #executeJob(job) {
    // Prevent overlapping runs of the SAME job
    if (job.status === 'running') {
      this.logger.warn(`[Scheduler] Skipping "${job.name}" — still running from previous cycle.`);
      return;
    }

    // Concurrency gate
    if (this.activeCount >= this.maxConcurrent) {
      this.logger.log(`[Scheduler] Queuing "${job.name}" — max concurrency reached.`);
      this.queue.push(job);
      return;
    }

    this.activeCount++;
    job.status = 'running';
    job.lastRun = new Date();
    job.retries = 0;

    try {
      // ✅ Fix 4: Proper async/await with timeout
      const result = await this.#runWithTimeout(job);

      job.status = 'completed';
      job.runCount++;
      job.nextRun = new Date(Date.now() + job.interval);

      // ✅ Fix 6: Return a copy, don't mutate the original result
      const reportMeta = {
        ...result,
        _meta: {
          jobName: job.name,
          generatedAt: new Date().toISOString(),
          durationMs: Date.now() - job.lastRun.getTime(),
        },
      };

      this.logger.log(
        `[Scheduler] ✅ "${job.name}" completed (run #${job.runCount}). ` +
        `Next run: ${job.nextRun.toISOString()}`
      );

      return reportMeta;

    } catch (error) {
      // ✅ Fix 7: Proper error handling with retry logic
      job.errorCount++;
      job.lastError = error.message;

      if (job.retries < job.maxRetries) {
        job.retries++;
        job.status = 'retrying';
        this.logger.warn(
          `[Scheduler] ⚠️ "${job.name}" failed (attempt ${job.retries}/${job.maxRetries}): ${error.message}`
        );
        await this.#delay(job.retryDelay * job.retries);  // Exponential backoff
        this.activeCount--;                                // Release slot before retry
        return this.#executeJob(job);
      }

      job.status = 'failed';
      this.logger.error(
        `[Scheduler] ❌ "${job.name}" failed permanently after ${job.maxRetries} retries: ${error.message}`
      );

    } finally {
      this.activeCount--;
      // ✅ Process queued jobs
      this.#processQueue();
    }
  }

  // ✅ Fix: Timeout wrapper to prevent hung jobs
  #runWithTimeout(job) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error(`Job "${job.name}" timed out after ${job.timeout}ms`));
      }, job.timeout);

      job.reportFn()
        .then(result => {
          clearTimeout(timer);
          resolve(result);
        })
        .catch(err => {
          clearTimeout(timer);
          reject(err);
        });
    });
  }

  #processQueue() {
    if (this.queue.length > 0 && this.activeCount < this.maxConcurrent) {
      const nextJob = this.queue.shift();
      this.#executeJob(nextJob);
    }
  }

  #delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  // ✅ Fix 5: Store timer references properly
  start() {
    if (this.running) {
      this.logger.warn('[Scheduler] Already running.');
      return;
    }

    this.running = true;
    this.logger.log(`[Scheduler] Starting with ${this.jobs.size} job(s)...`);

    for (const [name, job] of this.jobs) {
      // Run immediately on start, then at interval
      this.#executeJob(job);

      const timerId = setInterval(() => {
        if (this.running) {
          this.#executeJob(job);
        }
      }, job.interval);

      this.timers.set(name, timerId);    // ✅ Fixed: Store reference
    }
  }

  // ✅ Fix 9: Properly clear ALL timers
  stop() {
    this.running = false;

    for (const [name, timerId] of this.timers) {
      clearInterval(timerId);
      this.logger.log(`[Scheduler] Timer cleared for "${name}".`);
    }
    this.timers.clear();
    this.queue = [];
    this.logger.log('[Scheduler] Stopped.');
  }

  // ✅ Fix 10 & 11: Return a copy, use strict equality
  getJobStatus(name) {
    const job = this.jobs.get(name);       // ✅ Map.get — strict by default
    if (!job) return null;

    // ✅ Return a frozen copy to prevent external mutation
    return Object.freeze({
      name: job.name,
      status: job.status,
      lastRun: job.lastRun,
      nextRun: job.nextRun,
      runCount: job.runCount,
      errorCount: job.errorCount,
      lastError: job.lastError,
    });
  }

  // ✅ Fix 12 & 13: Safely remove job and its timer
  removeJob(name) {
    if (!this.jobs.has(name)) {
      this.logger.warn(`[Scheduler] Job "${name}" not found.`);
      return false;
    }

    // ✅ Clear the timer FIRST
    if (this.timers.has(name)) {
      clearInterval(this.timers.get(name));
      this.timers.delete(name);
    }

    // Remove from queue if queued
    this.queue = this.queue.filter(job => job.name !== name);

    this.jobs.delete(name);
    this.logger.log(`[Scheduler] Job "${name}" removed.`);
    return true;
  }

  // ✅ Bonus: Get summary of all jobs
  getAllStatus() {
    const statuses = [];
    for (const name of this.jobs.keys()) {
      statuses.push(this.getJobStatus(name));
    }
    return statuses;
  }
}
