    this.watchers = new Map();
    this.fileHashes = new Map();
    this.debounceTimers = new Map();
    this.running = false;

    // Ensure log directory exists
    const logDir = path.dirname(this.logFile);
    if (!fs.existsSync(logDir)) {
      fs.mkdirSync(logDir, { recursive: true });
    }
  }

  // Generate file hash for integrity checking
  computeHash(filePath) {
    try {
      const content = fs.readFileSync(filePath);
      return crypto.createHash(this.hashAlgorithm).update(content).digest('hex');
    } catch {
      return null;
    }
  }

  // Get file metadata
  getFileInfo(filePath) {
    try {
      const stats = fs.statSync(filePath);
      return {
        size: stats.size,
        mode: stats.mode.toString(8),
        uid: stats.uid,
        gid: stats.gid,
        modified: stats.mtime.toISOString(),
        created: stats.birthtime.toISOString(),
        isDirectory: stats.isDirectory(),
      };
    } catch {
      return null;
    }
  }

  // Check if path should be ignored
  shouldIgnore(filePath) {
    return this.ignorePatterns.some((pattern) => {
      if (pattern instanceof RegExp) return pattern.test(filePath);
      return filePath.includes(pattern);
    });
  }

  // Create structured audit entry
  createAuditEntry(eventType, filePath, extra = {}) {
    const entry = {
      timestamp: new Date().toISOString(),
      event: eventType,
      path: path.resolve(filePath),
      pid: process.pid,
      user: process.env.USER || process.env.USERNAME || 'unknown',
      ...extra,
    };

    // Add hash for file content events
    if (['created', 'modified'].includes(eventType)) {
      const hash = this.computeHash(filePath);
      if (hash) entry.hash = hash;

      const info = this.getFileInfo(filePath);
      if (info) entry.fileInfo = info;
    }

    return entry;
  }

  // Write audit log entry (append-only)
  writeLog(entry) {
    const line = JSON.stringify(entry) + '\n';

    try {
      fs.appendFileSync(this.logFile, line, { flag: 'a' });
      this.emit('logged', entry);
    } catch (err) {
      this.emit('error', new Error(`Failed to write audit log: ${err.message}`));
    }
  }

  // Debounced event handler to avoid duplicate events
  handleEvent(eventType, filePath) {
    if (this.shouldIgnore(filePath)) return;

    const key = `${eventType}:${filePath}`;

    if (this.debounceTimers.has(key)) {
      clearTimeout(this.debounceTimers.get(key));
    }

    this.debounceTimers.set(
      key,
      setTimeout(() => {
        this.debounceTimers.delete(key);
        this.processEvent(eventType, filePath);
      }, this.debounceMs)
    );
  }

  // Process and classify file events
  processEvent(eventType, filePath) {
    const exists = fs.existsSync(filePath);
    const hadHash = this.fileHashes.has(filePath);

    if (eventType === 'rename') {
      if (exists && !hadHash) {
        // New file
        const hash = this.computeHash(filePath);
        if (hash) this.fileHashes.set(filePath, hash);
        const entry = this.createAuditEntry('created', filePath);
        this.writeLog(entry);
        this.emit('change', entry);
      } else if (!exists && hadHash) {
        // Deleted file
        const previousHash = this.fileHashes.get(filePath);
        this.fileHashes.delete(filePath);
        const entry = this.createAuditEntry('deleted', filePath, { previousHash });
        this.writeLog(entry);
        this.emit('change', entry);
      }
    } else if (eventType === 'change' && exists) {
      const newHash = this.computeHash(filePath);
      const oldHash = this.fileHashes.get(filePath);

      // Only log if content actually changed
      if (newHash && newHash !== oldHash) {
        this.fileHashes.set(filePath, newHash);
        const entry = this.createAuditEntry('modified', filePath, {
          previousHash: oldHash || null,
        });
        this.writeLog(entry);
        this.emit('change', entry);
      }
    }
  }

  // Scan directory and build initial hash map
  buildBaseline(dirPath) {
    const entries = [];

    const scan = (dir) => {
      try {
        const items = fs.readdirSync(dir, { withFileTypes: true });
        for (const item of items) {
          const fullPath = path.join(dir, item.name);
          if (this.shouldIgnore(fullPath)) continue;

          if (item.isFile()) {
            const hash = this.computeHash(fullPath);
            if (hash) {
              this.fileHashes.set(fullPath, hash);
              entries.push({ path: fullPath, hash });
            }
          } else if (item.isDirectory() && this.recursive) {
            scan(fullPath);
          }
        }
      } catch (err) {
        this.emit('error', new Error(`Baseline scan failed for ${dir}: ${err.message}`));
      }
    };

    scan(dirPath);
    return entries;
  }

  // Start watching
  start() {
    if (this.running) return;
    this.running = true;

    const startEntry = this.createAuditEntry('watcher_started', this.logFile, {
      watchedDirs: this.watchDirs.map((d) => path.resolve(d)),
      config: {
        recursive: this.recursive,
        hashAlgorithm: this.hashAlgorithm,
        ignorePatterns: this.ignorePatterns.map(String),
      },
    });
    this.writeLog(startEntry);

    for (const dir of this.watchDirs) {
      const resolved = path.resolve(dir);

      if (!fs.existsSync(resolved)) {
        this.emit('error', new Error(`Watch directory does not exist: ${resolved}`));
        continue;
      }

      // Build baseline hashes
      const baseline = this.buildBaseline(resolved);
      const baselineEntry = this.createAuditEntry('baseline_created', resolved, {
        fileCount: baseline.length,
      });
      this.writeLog(baselineEntry);

      // Start fs.watch
      try {
        const watcher = fs.watch(resolved, { recursive: this.recursive }, (eventType, filename) => {
          if (!filename) return;
          const fullPath = path.join(resolved, filename);
          this.handleEvent(eventType, fullPath);
        });

        watcher.on('error', (err) => {
          this.emit('error', new Error(`Watcher error on ${resolved}: ${err.message}`));
        });

        this.watchers.set(resolved, watcher);
        this.emit('watching', resolved);
      } catch (err) {
        this.emit('error', new Error(`Failed to watch ${resolved}: ${err.message}`));
      }
    }

    return this;
  }

  // Stop watching
  stop() {
    if (!this.running) return;

    for (const [dir, watcher] of this.watchers) {
      watcher.close();
      this.emit('unwatched', dir);
    }

    // Clear debounce timers
    for (const timer of this.debounceTimers.values()) {
      clearTimeout(timer);
    }

    this.watchers.clear();
    this.debounceTimers.clear();
    this.running = false;

    const stopEntry = this.createAuditEntry('watcher_stopped', this.logFile);
    this.writeLog(stopEntry);

    return this;
  }

  // Verify current files against baseline
  verifyIntegrity(dirPath) {
    const results = { passed: [], failed: [], missing: [], newFiles: [] };
    const currentFiles = new Set();

    const scan = (dir) => {
      try {
        const items = fs.readdirSync(dir, { withFileTypes: true });
        for (const item of items) {
          const fullPath = path.join(dir, item.name);
          if (this.shouldIgnore(fullPath)) continue;

          if (item.isFile()) {
            currentFiles.add(fullPath);
            const currentHash = this.computeHash(fullPath);
            const baselineHash = this.fileHashes.get(fullPath);

            if (!baselineHash) {
              results.newFiles.push({ path: fullPath, hash: currentHash });
            } else if (currentHash === baselineHash) {
              results.passed.push({ path: fullPath, hash: currentHash });
            } else {
              results.failed.push({
                path: fullPath,
                expected: baselineHash,
                actual: currentHash,
              });
            }
          } else if (item.isDirectory() && this.recursive) {
            scan(fullPath);
          }
        }
      } catch (err) {
        this.emit('error', err);
      }
    };

    const resolved = path.resolve(dirPath);
    scan(resolved);

    // Check for deleted files
    for (const [filePath] of this.fileHashes) {
      if (filePath.startsWith(resolved) && !currentFiles.has(filePath)) {
        results.missing.push({ path: filePath, hash: this.fileHashes.get(filePath) });
      }
    }

    const entry = this.createAuditEntry('integrity_check', resolved, {
      passed: results.passed.length,
      failed: results.failed.length,
      missing: results.missing.length,
      newFiles: results.newFiles.length,
    });
    this.writeLog(entry);

    return results;
  }

  // Read and parse audit log
  readLog(options = {}) {
    const { since, until, events, pathFilter, limit } = options;

    try {
      const content = fs.readFileSync(this.logFile, 'utf-8');
      let entries = content
        .trim()
        .split('\n')
        .filter(Boolean)
        .map((line) => {
          try {
            return JSON.parse(line);
          } catch {
            return null;
          }
        })
        .filter(Boolean);

      if (since) {
        entries = entries.filter((e) => new Date(e.timestamp) >= new Date(since));
      }
      if (until) {
        entries = entries.filter((e) => new Date(e.timestamp) <= new Date(until));
      }
      if (events) {
        const eventSet = new Set(Array.isArray(events) ? events : [events]);
        entries = entries.filter((e) => eventSet.has(e.event));
      }
      if (pathFilter) {
        const pattern = pathFilter instanceof RegExp ? pathFilter : new RegExp(pathFilter);
        entries = entries.filter((e) => pattern.test(e.path));
      }
      if (limit) {
        entries = entries.slice(-limit);
      }

      return entries;
    } catch {
      return [];
    }
  }

  // Rotate log file
  rotateLog() {
    if (!fs.existsSync(this.logFile)) return;

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const rotatedPath = `${this.logFile}.${timestamp}`;

    fs.renameSync(this.logFile, rotatedPath);

    const entry = this.createAuditEntry('log_rotated', this.logFile, {
      archivedTo: rotatedPath,
    });
    this.writeLog(entry);

    return rotatedPath;
  }
}

// --- Demo usage ---

// Create a temp directory structure to watch
const DEMO_DIR = path.join(__dirname, 'watched-demo');
const AUDIT_LOG = path.join(__dirname, 'audit-demo.log');

function setupDemo() {
