  if (fs.existsSync(DEMO_DIR)) fs.rmSync(DEMO_DIR, { recursive: true });
  if (fs.existsSync(AUDIT_LOG)) fs.unlinkSync(AUDIT_LOG);

  fs.mkdirSync(path.join(DEMO_DIR, 'config'), { recursive: true });
  fs.mkdirSync(path.join(DEMO_DIR, 'data'), { recursive: true });

  fs.writeFileSync(path.join(DEMO_DIR, 'config', 'settings.json'), '{"debug": false}');
  fs.writeFileSync(path.join(DEMO_DIR, 'data', 'records.csv'), 'id,name\n1,Alice\n');

  console.log('Demo directory created at:', DEMO_DIR);
}

async function runDemo() {
  setupDemo();

  const watcher = new AuditFileWatcher({
    dirs: [DEMO_DIR],
    logFile: AUDIT_LOG,
    ignorePatterns: [/node_modules/, /\.git/],
    debounceMs: 50,
  });

  // Event listeners
  watcher.on('watching', (dir) => console.log(`👁  Watching: ${dir}`));
  watcher.on('change', (entry) => console.log(`📝 ${entry.event.toUpperCase()}: ${path.basename(entry.path)}`));
  watcher.on('error', (err) => console.error(`❌ ${err.message}`));

  watcher.start();

  // Simulate file operations with delays
  const delay = (ms) => new Promise((r) => setTimeout(r, ms));

  await delay(300);
  console.log('\n--- Simulating file changes ---\n');

  // Modify a file
  fs.writeFileSync(path.join(DEMO_DIR, 'config', 'settings.json'), '{"debug": true, "verbose": true}');
  await delay(300);

  // Create a new file
  fs.writeFileSync(path.join(DEMO_DIR, 'data', 'new-report.txt'), 'Quarterly report data');
  await delay(300);

  // Modify another file
  fs.appendFileSync(path.join(DEMO_DIR, 'data', 'records.csv'), '2,Bob\n3,Charlie\n');
  await delay(300);

  // Delete a file
  fs.unlinkSync(path.join(DEMO_DIR, 'data', 'new-report.txt'));
  await delay(300);

  // Run integrity check
  console.log('\n--- Integrity Check ---\n');
  const results = watcher.verifyIntegrity(DEMO_DIR);
  console.log(`  ✅ Passed:  ${results.passed.length}`);
  console.log(`  ❌ Failed:  ${results.failed.length}`);
  console.log(`  ❓ Missing: ${results.missing.length}`);
  console.log(`  🆕 New:     ${results.newFiles.length}`);

  // Query the audit log
  console.log('\n--- Audit Log (modifications only) ---\n');
  const mods = watcher.readLog({ events: ['modified', 'created', 'deleted'] });
  for (const entry of mods) {
    console.log(`  [${entry.timestamp}] ${entry.event} → ${path.basename(entry.path)}`);
    if (entry.hash) console.log(`    hash: ${entry.hash.substring(0, 16)}...`);
  }

  // Full log dump
  console.log('\n--- Full Audit Log ---\n');
  const allEntries = watcher.readLog();
  console.log(`  Total entries: ${allEntries.length}`);

  watcher.stop();

  // Cleanup
  fs.rmSync(DEMO_DIR, { recursive: true });
  fs.unlinkSync(AUDIT_LOG);
  console.log('\n✓ Demo complete, cleaned up.');
}

runDemo().catch(console.error);
