use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::time::Duration;

/// What kind of file event triggers the task
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
#[serde(rename_all = "snake_case")]
pub enum TriggerEvent {
    Create,
    Modify,
    Delete,
    Rename,
    Any,
}

/// A single watch rule: "when X happens to files matching Y, run Z"
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WatchRule {
    pub name: String,
    pub glob_pattern: String,           // e.g., "*.csv", "**/*.log"
    pub trigger: TriggerEvent,
    pub command: String,                // shell command to run
    #[serde(default = "default_debounce_ms")]
    pub debounce_ms: u64,              // collapse rapid events
    #[serde(default)]
    pub enabled: bool,
}

fn default_debounce_ms() -> u64 {
    500
}

impl WatchRule {
    pub fn debounce_duration(&self) -> Duration {
        Duration::from_millis(self.debounce_ms)
    }
}

/// Top-level configuration
