```rust
use chrono::{DateTime, Local};
use std::path::PathBuf;
use std::process::Command;
use std::time::Duration;

use crate::config::TriggerEvent;

/// A scheduled task ready for execution
#[derive(Debug, Clone)]
pub struct Task {
    pub id: u64,
    pub rule_name: String,
    pub file_path: PathBuf,
    pub trigger: TriggerEvent,
    pub command_template: String,
    pub created_at: DateTime<Local>,
    pub status: TaskStatus,
}

#[derive(Debug, Clone, PartialEq)]
pub enum TaskStatus {
    Pending,
    Running,
    Completed { exit_code: i32, duration: Duration },
    Failed { error: String, duration: Duration },
}

impl std::fmt::Display for TaskStatus {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TaskStatus::Pending => write!(f, "PENDING"),
            TaskStatus::Running => write!(f, "RUNNING"),
            TaskStatus::Completed { exit_code, duration } => {
                write!(f, "OK (exit={}, {:.1}s)", exit_code, duration.as_secs_f64())
            }
            TaskStatus::Failed { error, duration } => {
                write!(f, "FAIL ({}, {:.1}s)", error, duration.as_secs_f64())
            }
        }
    }
}

/// Result of executing a task
#[derive(Debug)]
pub struct TaskResult {
    pub task_id: u64,
    pub status: TaskStatus,
    pub stdout: String,
    pub stderr: String,
}

impl Task {
    /// Build the actual command string, substituting {file} placeholder
    fn resolve_command(&self) -> String {
        let file_str = self.file_path.display().to_string();
        let file_name = self
            .file_path
            .file_name()
            .map(|f| f.to_string_lossy().to_string())
            .unwrap_or_default();
        let file_dir = self
            .file_path
            .parent()
            .map(|p| p.display().to_string())
            .unwrap_or_default();
        let file_stem = self
            .file_path
            .file_stem()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_default();
        let file_ext = self
            .file_path
            .extension()
            .map(|e| e.to_string_lossy().to_string())
            .unwrap_or_default();

        self.command_template
            .replace("{file}", &file_str)
            .replace("{name}", &file_name)
            .replace("{dir}", &file_dir)
            .replace("{stem}", &file_stem)
            .replace("{ext}", &file_ext)
    }

    /// Execute the task command in a shell
    pub fn execute(&self) -> TaskResult {
        let cmd = self.resolve_command();
        let start = std::time::Instant::now();

        log::info!("[Task #{}] Running: {}", self.id, cmd);

        let shell = if cfg!(target_os = "windows") {
            ("cmd", "/C")
        } else {
            ("sh", "-c")
        };

        let result = Command::new(shell.0)
            .arg(shell.1)
            .arg(&cmd)
            .output();

        let elapsed = start.elapsed();

        match result {
            Ok(output) => {
                let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
                let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
                let code = output.status.code().unwrap_or(-1);

                let status = if output.status.success() {
                    TaskStatus::Completed {
                        exit_code: code,
                        duration: elapsed,
                    }
                } else {
                    TaskStatus::Failed {
                        error: format!("exit code {}", code),
                        duration: elapsed,
                    }
                };

                TaskResult {
                    task_id: self.id,
                    status,
                    stdout,
                    stderr,
                }
            }
            Err(e) => TaskResult {
                task_id: self.id,
                status: TaskStatus::Failed {
                    error: e.to_string(),
                    duration: elapsed,
                },
                stdout: String::new(),
                stderr: e.to_string(),
            },
        }
    }
}
