## `src/scheduler.rs` — Debounced Task Scheduling and Worker Pool

```rust
use crossbeam_channel::{Receiver, Sender};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Instant;

use crate::config::{TriggerEvent, WatchRule};
use crate::task::{Task, TaskResult};

/// Raw event from the file watcher before debouncing
#[derive(Debug, Clone)]
pub struct FileEvent {
    pub path: PathBuf,
    pub trigger: TriggerEvent,
    pub timestamp: Instant,
}

/// Debouncer collapses rapid duplicate events per (rule, file) pair
struct Debouncer {
    /// Key: (rule_name, file_path) → last event time
    last_seen: HashMap<(String, PathBuf), Instant>,
}

impl Debouncer {
    fn new() -> Self {
        Self {
            last_seen: HashMap::new(),
        }
    }

    /// Returns true if enough time has passed since last event for this key
    fn should_fire(&mut self, rule_name: &str, path: &PathBuf, debounce: std::time::Duration) -> bool {
        let key = (rule_name.to_string(), path.clone());
        let now = Instant::now();

        match self.last_seen.get(&key) {
            Some(last) if now.duration_since(*last) < debounce => false,
            _ => {
                self.last_seen.insert(key, now);
                true
            }
        }
    }

    /// Periodically clean stale entries to avoid unbounded growth
    fn gc(&mut self, max_age: std::time::Duration) {
        let now = Instant::now();
        self.last_seen
            .retain(|_, ts| now.duration_since(*ts) < max_age);
    }
}

pub struct Scheduler {
    rules: Vec<WatchRule>,
    event_rx: Receiver<FileEvent>,
    result_tx: Sender<TaskResult>,
    task_counter: AtomicU64,
    shutdown: Arc<AtomicBool>,
    worker_count: usize,
}

impl Scheduler {
    pub fn new(
        rules: Vec<WatchRule>,
        event_rx: Receiver<FileEvent>,
        result_tx: Sender<TaskResult>,
        shutdown: Arc<AtomicBool>,
        worker_count: usize,
    ) -> Self {
        Self {
            rules,
            event_rx,
            result_tx,
            task_counter: AtomicU64::new(1),
            shutdown,
            worker_count,
        }
    }

    /// Check if a file path matches a glob pattern
    fn matches_glob(pattern: &str, path: &PathBuf) -> bool {
        let file_name = path
            .file_name()
            .map(|f| f.to_string_lossy().to_string())
            .unwrap_or_default();

        // Try matching against full path and just the filename
        glob::Pattern::new(pattern)
            .map(|p| p.matches(&file_name) || p.matches_path(path))
            .unwrap_or(false)
    }

    /// Check if an event trigger matches a rule trigger
    fn trigger_matches(rule_trigger: &TriggerEvent, event_trigger: &TriggerEvent) -> bool {
        *rule_trigger == TriggerEvent::Any || *rule_trigger == *event_trigger
    }

    /// Find all rules that match a given file event
    fn matching_rules(&self, event: &FileEvent) -> Vec<&WatchRule> {
        self.rules
            .iter()
            .filter(|rule| {
                rule.enabled
                    && Self::trigger_matches(&rule.trigger, &event.trigger)
                    && Self::matches_glob(&rule.glob_pattern, &event.path)
            })
            .collect()
    }

    /// Main scheduler loop — dispatches tasks to a thread pool
    pub fn run(self) {
        let (task_tx, task_rx) = crossbeam_channel::bounded::<Task>(256);
        let result_tx = self.result_tx.clone();
        let shutdown = self.shutdown.clone();

        // Spawn worker threads
        let mut workers = Vec::new();
        for worker_id in 0..self.worker_count {
            let rx = task_rx.clone();
            let tx = result_tx.clone();
            let sd = shutdown.clone();

            workers.push(thread::spawn(move || {
                log::debug!("Worker {} started", worker_id);
                while !sd.load(Ordering::Relaxed) {
                    match rx.recv_timeout(std::time::Duration::from_millis(200)) {
                        Ok(task) => {
                            let result = task.execute();
                            if !result.stdout.is_empty() {
                                log::info!("[Task #{}] stdout: {}", result.task_id, result.stdout);
                            }
                            if !result.stderr.is_empty() {
                                log::warn!("[Task #{}] stderr: {}", result.task_id, result.stderr);
                            }
                            log::info!("[Task #{}] {}", result.task_id, result.status);
                            let _ = tx.send(result);
                        }
                        Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
                        Err(_) => break,
                    }
                }
                log::debug!("Worker {} stopped", worker_id);
            }));
        }

        // Event processing loop with debouncing
        let mut debouncer = Debouncer::new();
        let mut gc_timer = Instant::now();

        while !self.shutdown.load(Ordering::Relaxed) {
            match self.event_rx.recv_timeout(std::time::Duration::from_millis(100)) {
                Ok(event) => {
                    let matching = self.matching_rules(&event);

                    for rule in matching {
                        if !debouncer.should_fire(
                            &rule.name,
                            &event.path,
                            rule.debounce_duration(),
                        ) {
                            log::debug!(
                                "Debounced: rule='{}' file='{}'",
                                rule.name,
                                event.path.display()
                            );
                            continue;
                        }

                        let task_id = self.task_counter.fetch_add(1, Ordering::Relaxed);
                        let task = Task {
                            id: task_id,
                            rule_name: rule.name.clone(),
                            file_path: event.path.clone(),
                            trigger: event.trigger.clone(),
                            command_template: rule.command.clone(),
                            created_at: chrono::Local::now(),
                            status: crate::task::TaskStatus::Pending,
                        };

                        log::info!(
                            "[Task #{}] Scheduled: rule='{}' trigger={:?} file='{}'",
                            task.id,
                            task.rule_name,
                            task.trigger,
                            task.file_path.display()
                        );

                        if task_tx.send(task).is_err() {
                            log::error!("Task queue full or closed");
                            break;
                        }
                    }
                }
                Err(crossbeam_channel::RecvTimeoutError::Timeout) => {}
                Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
            }

            // GC debouncer every 30s
            if gc_timer.elapsed() > std::time::Duration::from_secs(30) {
                debouncer.gc(std::time::Duration::from_secs(60));
                gc_timer = Instant::now();
            }
        }

        drop(task_tx); // signal workers to stop
        for w in workers {
            let _ = w.join();
        }
        log::info!("Scheduler stopped");
    }
}
