import Foundation

// MARK: - Task Definition
struct ScheduledTask {
    let id: String
    let name: String
    let priority: Int
    let execute: () -> Void
}

// MARK: - Thread-Safe Task Queue
class TaskQueue {
    private var queue: [ScheduledTask] = []
    private let lock = NSLock()

    func enqueue(_ task: ScheduledTask) {
        lock.lock()
        defer { lock.unlock() }
        // Insert sorted by priority (higher priority first)
        if let index = queue.firstIndex(where: { $0.priority < task.priority }) {
            queue.insert(task, at: index)
        } else {
            queue.append(task)
        }
    }

    func dequeue() -> ScheduledTask? {
        lock.lock()
        defer { lock.unlock() }
        return queue.isEmpty ? nil : queue.removeFirst()
    }

    var count: Int {
        lock.lock()
        defer { lock.unlock() }
        return queue.count
    }

    var isEmpty: Bool {
        lock.lock()
        defer { lock.unlock() }
        return queue.isEmpty
    }
}

// MARK: - Queue Consumer
class QueueConsumer {
    private let taskQueue: TaskQueue
    private var isRunning = false
    private let workerQueue = DispatchQueue(label: "com.consumer.worker", attributes: .concurrent)
    private let pollInterval: TimeInterval

    init(queue: TaskQueue, pollInterval: TimeInterval = 0.5) {
        self.taskQueue = queue
        self.pollInterval = pollInterval
    }

    func start() {
        guard !isRunning else {
            print("[Consumer] Already running.")
            return
        }
        isRunning = true
        print("[Consumer] Started.")

        workerQueue.async { [weak self] in
            self?.poll()
        }
    }

    func stop() {
        isRunning = false
        print("[Consumer] Stopped.")
    }

    private func poll() {
        while isRunning {
            if let task = taskQueue.dequeue() {
                print("[Consumer] Processing task: \(task.name) (id: \(task.id), priority: \(task.priority))")
                task.execute()
                print("[Consumer] Finished task: \(task.name)")
            } else {
                Thread.sleep(forTimeInterval: pollInterval)
            }
        }
    }
}

