import java.util.Map;
import java.util.Objects;

/**
 * Immutable cache entry wrapping parsed config values with metadata
 * used for invalidation decisions.
 */
public final class CachedConfigEntry {

    private final Map<String, String> properties;
    private final Instant loadedAt;
    private final long sourceLastModified;  // file lastModified epoch millis
    private final String sourceFingerprint; // hash of raw content

    public CachedConfigEntry(Map<String, String> properties,
                             long sourceLastModified,
                             String sourceFingerprint) {
        this.properties = Collections.unmodifiableMap(Objects.requireNonNull(properties));
        this.loadedAt = Instant.now();
        this.sourceLastModified = sourceLastModified;
        this.sourceFingerprint = Objects.requireNonNull(sourceFingerprint);
    }

    public Map<String, String> getProperties()    { return properties; }
    public Instant getLoadedAt()                   { return loadedAt; }
    public long getSourceLastModified()            { return sourceLastModified; }
    public String getSourceFingerprint()           { return sourceFingerprint; }

    public String get(String key)                  { return properties.get(key); }
    public String get(String key, String fallback) { return properties.getOrDefault(key, fallback); }

    @Override
    public String toString() {
        return String.format("CachedConfigEntry[keys=%d, loaded=%s, modified=%d]",
                properties.size(), loadedAt, sourceLastModified);
    }
}
