/**
 * Strategy that decides whether a cached config entry is still valid.
 * Implementations can check TTL, file modification, content hash, etc.
 */
@FunctionalInterface
public interface InvalidationStrategy {

    /**
     * @param entry   the current cached entry (never null)
     * @param source  the config source to check freshness against
     * @return true if the cache entry is stale and should be reloaded
     */
    boolean isStale(CachedConfigEntry entry, ConfigSource source);
}
