package config;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * Represents a configuration source (file on disk).
 * Provides raw content, last-modified time, and content hashing.
 */
public class ConfigSource {

    private final Path path;

    public ConfigSource(Path path) {
        this.path = path;
    }

    public Path getPath() {
        return path;
    }

    /** Epoch millis of last file modification, or -1 if unavailable. */
    public long lastModified() {
        try {
            return Files.getLastModifiedTime(path).toMillis();
        } catch (IOException e) {
            return -1L;
        }
    }

    /** Read entire file content as a string. */
    public String readContent() throws IOException {
        return Files.readString(path, StandardCharsets.UTF_8);
    }

    /** SHA-256 hex digest of the file content. */
    public String contentFingerprint() throws IOException {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(readContent().getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 not available", e);
        }
    }

    @Override
    public String toString() {
        return "ConfigSource[" + path + "]";
    }
}
