### Built-in Invalidation Strategies

```java
package config;

import java.time.Duration;
import java.time.Instant;

/**
 * Factory for common invalidation strategies.
 * Strategies are composable via {@link #or} and {@link #and}.
 */
public final class InvalidationStrategies {

    private InvalidationStrategies() {} // utility class

    // ── TTL-based ──────────────────────────────────────────────

    /** Entry is stale if it was loaded more than {@code ttl} ago. */
    public static InvalidationStrategy ttl(Duration ttl) {
        return (entry, source) -> {
            boolean stale = Instant.now().isAfter(entry.getLoadedAt().plus(ttl));
            if (stale) {
                System.out.printf("  [TTL] Entry loaded at %s exceeded TTL of %s%n",
                        entry.getLoadedAt(), ttl);
            }
            return stale;
        };
    }

    // ── File-modification based ────────────────────────────────

    /** Entry is stale if the source file was modified after the cache load. */
    public static InvalidationStrategy fileModified() {
        return (entry, source) -> {
            long currentMod = source.lastModified();
            boolean stale = currentMod > entry.getSourceLastModified();
            if (stale) {
                System.out.printf("  [FILE_MOD] Source modified: cached=%d, current=%d%n",
                        entry.getSourceLastModified(), currentMod);
            }
            return stale;
        };
    }

    // ── Content-hash based (deep check) ───────────────────────

    /** Entry is stale if the SHA-256 of the source content changed. */
    public static InvalidationStrategy contentChanged() {
        return (entry, source) -> {
            try {
                String currentHash = source.contentFingerprint();
                boolean stale = !currentHash.equals(entry.getSourceFingerprint());
                if (stale) {
                    System.out.printf("  [CONTENT] Fingerprint changed: %s → %s%n",
                            entry.getSourceFingerprint().substring(0, 12) + "…",
                            currentHash.substring(0, 12) + "…");
                }
                return stale;
            } catch (Exception e) {
                return true; // assume stale on error
            }
        };
    }

    // ── Combinators ────────────────────────────────────────────

    /** Stale if ANY strategy says stale (short-circuit). */
    public static InvalidationStrategy or(InvalidationStrategy... strategies) {
        return (entry, source) -> {
            for (InvalidationStrategy s : strategies) {
                if (s.isStale(entry, source)) return true;
            }
            return false;
        };
    }

    /** Stale only if ALL strategies say stale. */
    public static InvalidationStrategy and(InvalidationStrategy... strategies) {
        return (entry, source) -> {
            for (InvalidationStrategy s : strategies) {
                if (!s.isStale(entry, source)) return false;
            }
            return true;
        };
    }
}
