### ConfigParser.java — The actual parser

```java
package config;

import java.io.IOException;
import java.io.StringReader;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses a simple config format supporting:
 *   - key = value pairs
 *   - [section] headers  →  keys become section.key
 *   - # comments
 *   - ${variable} interpolation within values
 */
public class ConfigParser {

    private static final Pattern SECTION  = Pattern.compile("^\\[(.+)]$");
    private static final Pattern KV_PAIR  = Pattern.compile("^([^=]+)=(.*)$");
    private static final Pattern VARIABLE = Pattern.compile("\\$\\{([^}]+)}");

    /**
     * Parse raw config text into a flat key→value map.
     */
    public Map<String, String> parse(String content) {
        Map<String, String> result = new LinkedHashMap<>();
        String currentSection = "";

        for (String rawLine : content.split("\\R")) {
            String line = rawLine.trim();

            // skip blanks and comments
            if (line.isEmpty() || line.startsWith("#")) continue;

            // section header
            Matcher secMatch = SECTION.matcher(line);
            if (secMatch.matches()) {
                currentSection = secMatch.group(1).trim() + ".";
                continue;
            }

            // key = value
            Matcher kvMatch = KV_PAIR.matcher(line);
            if (kvMatch.matches()) {
                String key   = currentSection + kvMatch.group(1).trim();
                String value = kvMatch.group(2).trim();
                result.put(key, value);
            }
        }

        // resolve ${variable} references
        resolveVariables(result);
        return result;
    }

    private void resolveVariables(Map<String, String> map) {
        for (Map.Entry<String, String> entry : map.entrySet()) {
            entry.setValue(interpolate(entry.getValue(), map, 0));
        }
    }

    private String interpolate(String value, Map<String, String> map, int depth) {
        if (depth > 10) return value; // guard against circular refs

        Matcher m = VARIABLE.matcher(value);
        StringBuilder sb = new StringBuilder();
        while (m.find()) {
            String ref = m.group(1);
            String replacement = map.getOrDefault(ref, "${" + ref + "}");
            m.appendReplacement(sb, Matcher.quoteReplacement(replacement));
        }
        m.appendTail(sb);

        String result = sb.toString();
        // recurse if there are still unresolved variables
        if (VARIABLE.matcher(result).find()) {
            return interpolate(result, map, depth + 1);
        }
        return result;
    }
}
