### ConfigManager.java — Cache + invalidation orchestrator

```java
package config;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.function.Consumer;

/**
 * Thread-safe config manager that:
 *   1. Parses config files via ConfigParser
 *   2. Caches results in CachedConfigEntry
 *   3. Invalidates via pluggable InvalidationStrategy
 *   4. Optionally watches the filesystem for live reload
 *   5. Notifies listeners on reload
 */
public class ConfigManager implements AutoCloseable {

    private final ConfigParser parser = new ConfigParser();
    private final Map<String, ConfigSource> sources = new ConcurrentHashMap<>();
    private final Map<String, CachedConfigEntry> cache = new ConcurrentHashMap<>();
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    private final InvalidationStrategy strategy;
    private final List<Consumer<String>> reloadListeners = new CopyOnWriteArrayList<>();

    // file watcher support
    private WatchService watchService;
    private final Map<WatchKey, String> watchKeyMap = new ConcurrentHashMap<>();
    private ScheduledExecutorService scheduler;

    public ConfigManager(InvalidationStrategy strategy) {
        this.strategy = Objects.requireNonNull(strategy);
    }

    // ── Registration ───────────────────────────────────────────

    /** Register a config source under a logical name. */
    public void register(String name, Path filePath) throws IOException {
        ConfigSource source = new ConfigSource(filePath);
        sources.put(name, source);
        load(name, source);
        System.out.printf("✓ Registered config '%s' from %s%n", name, filePath);
    }

    // ── Reads (cache-aware) ────────────────────────────────────

    /** Get a single property, checking staleness first. */
    public String get(String configName, String key) {
        return get(configName, key, null);
    }

    public String get(String configName, String key, String fallback) {
        ensureFresh(configName);
        lock.readLock().lock();
        try {
            CachedConfigEntry entry = cache.get(configName);
            if (entry == null) return fallback;
            return entry.get(key, fallback);
        } finally {
            lock.readLock().unlock();
        }
    }

    /** Get all properties for a config, checking staleness first. */
    public Map<String, String> getAll(String configName) {
        ensureFresh(configName);
        lock.readLock().lock();
        try {
            CachedConfigEntry entry = cache.get(configName);
            return entry != null ? entry.getProperties() : Collections.emptyMap();
        } finally {
            lock.readLock().unlock();
        }
    }

    // ── Cache Invalidation ─────────────────────────────────────

    /** Check if cache is stale; reload if necessary. */
    private void ensureFresh(String name) {
        CachedConfigEntry entry = cache.get(name);
        ConfigSource source = sources.get(name);
        if (entry == null || source == null) return;

        if (strategy.isStale(entry, source)) {
            System.out.printf("♻ Cache stale for '%s' — reloading…%n", name);
            try {
                load(name, source);
                notifyListeners(name);
            } catch (IOException e) {
                System.err.printf("✗ Failed to reload '%s': %s%n", name, e.getMessage());
            }
        }
    }

    /** Force-invalidate a specific config. */
    public void invalidate(String name) {
        lock.writeLock().lock();
        try {
            cache.remove(name);
            System.out.printf("🗑 Manually invalidated cache for '%s'%n", name);
        } finally {
            lock.writeLock().unlock();
        }
    }

    /** Force-invalidate all cached configs. */
    public void invalidateAll() {
        lock.writeLock().lock();
        try {
            cache.clear();
            System.out.println("🗑 All config caches invalidated");
        } finally {
            lock.writeLock().unlock();
        }
    }

    /** Force reload from disk. */
    public void reload(String name) throws IOException {
        ConfigSource source = sources.get(name);
        if (source == null) throw new IllegalArgumentException("Unknown config: " + name);
        load(name, source);
        notifyListeners(name);
        System.out.printf("♻ Force-reloaded config '%s'%n", name);
    }

    // ── Internal load ──────────────────────────────────────────

    private void load(String name, ConfigSource source) throws IOException {
        String content = source.readContent();
        Map<String, String> props = parser.parse(content);
        CachedConfigEntry entry = new CachedConfigEntry(
                props,
                source.lastModified(),
                source.contentFingerprint()
        );

        lock.writeLock().lock();
        try {
            cache.put(name, entry);
        } finally {
            lock.writeLock().unlock();
        }
    }

    // ── File Watch (live reload) ───────────────────────────────

    /** Start watching registered source files for changes. */
    public void startFileWatch() throws IOException {
        watchService = FileSystems.getDefault().newWatchService();

        for (Map.Entry<String, ConfigSource> e : sources.entrySet()) {
            Path dir = e.getValue().getPath().getParent();
            WatchKey key = dir.register(watchService,
                    StandardWatchEventKinds.ENTRY_MODIFY);
            watchKeyMap.put(key, e.getKey());
        }

