package com.filesync;

/**
 * Configuration options for file synchronization.
 */
public class SyncOptions {
    private boolean deleteOrphans;      // delete files in target not in source
    private boolean syncSubDirectories; // recurse into subdirectories
    private boolean dryRun;             // report changes without applying them

    private SyncOptions(Builder builder) {
        this.deleteOrphans = builder.deleteOrphans;
        this.syncSubDirectories = builder.syncSubDirectories;
        this.dryRun = builder.dryRun;
    }

    public boolean isDeleteOrphans() {
        return deleteOrphans;
    }

    public boolean isSyncSubDirectories() {
        return syncSubDirectories;
    }

    public boolean isDryRun() {
        return dryRun;
    }

    /** Returns default options: recursive sync, no deletion, no dry run */
    public static SyncOptions defaults() {
        return new Builder().build();
    }

    public static class Builder {
        private boolean deleteOrphans = false;
        private boolean syncSubDirectories = true;
        private boolean dryRun = false;

        public Builder deleteOrphans(boolean val) {
            this.deleteOrphans = val;
            return this;
        }

        public Builder syncSubDirectories(boolean val) {
            this.syncSubDirectories = val;
            return this;
        }

        public Builder dryRun(boolean val) {
            this.dryRun = val;
            return this;
        }

        public SyncOptions build() {
            return new SyncOptions(this);
        }
    }
}
