package com.filesync;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Tracks all changes made during a synchronization operation.
 */
public class SyncResult {

    public enum Action { COPIED, UPDATED, DELETED, DIR_CREATED }

    public record Change(Action action, Path path) {
        @Override
        public String toString() {
            return String.format("[%s] %s", action, path);
        }
    }

    private final List<Change> changes = new ArrayList<>();
    private int filesCopied;
    private int filesUpdated;
    private int filesDeleted;
    private int directoriesCreated;

    void addCopied(Path path) {
        changes.add(new Change(Action.COPIED, path));
        filesCopied++;
    }

    void addUpdated(Path path) {
        changes.add(new Change(Action.UPDATED, path));
        filesUpdated++;
    }

    void addDeleted(Path path) {
        changes.add(new Change(Action.DELETED, path));
        filesDeleted++;
    }

    void addDirectoryCreated(Path path) {
        changes.add(new Change(Action.DIR_CREATED, path));
        directoriesCreated++;
    }

    public int getFilesCopied()        { return filesCopied; }
    public int getFilesUpdated()       { return filesUpdated; }
    public int getFilesDeleted()       { return filesDeleted; }
    public int getDirectoriesCreated() { return directoriesCreated; }
    public int getTotalChanges()       { return changes.size(); }

    public List<Change> getChanges() {
        return Collections.unmodifiableList(changes);
    }

    @Override
    public String toString() {
        return String.format(
            "SyncResult{copied=%d, updated=%d, deleted=%d, dirsCreated=%d}",
            filesCopied, filesUpdated, filesDeleted, directoriesCreated
        );
    }
}
