### FileSynchronizer.java
```java
package com.filesync;

import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.nio.file.attribute.FileTime;
import java.util.HashSet;
import java.util.Set;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.stream.Stream;

/**
 * Synchronizes files from a source directory to a target directory.
 *
 * Behavior:
 *  - New files in source → copied to target
 *  - Modified files (newer mtime or different size) → overwritten in target
 *  - Files only in target → optionally deleted (if deleteOrphans is set)
 *  - Subdirectories → optionally recursed (if syncSubDirectories is set)
 */
public class FileSynchronizer {

    private static final Logger LOG = Logger.getLogger(FileSynchronizer.class.getName());

    private final Path source;
    private final Path target;
    private final SyncOptions options;

    public FileSynchronizer(Path source, Path target, SyncOptions options) {
        this.source = source.toAbsolutePath().normalize();
        this.target = target.toAbsolutePath().normalize();
        this.options = options;
    }

    public FileSynchronizer(Path source, Path target) {
        this(source, target, SyncOptions.defaults());
    }

    /**
     * Execute the synchronization and return a result summary.
     */
    public SyncResult sync() throws IOException {
        validate();
        SyncResult result = new SyncResult();
        syncDirectory(source, target, result);
        return result;
    }

    // ---- internal ----------------------------------------------------------

    private void validate() throws IOException {
        if (!Files.isDirectory(source)) {
            throw new IOException("Source is not a directory: " + source);
        }
        if (source.equals(target)) {
            throw new IOException("Source and target must be different directories");
        }
    }

    private void syncDirectory(Path srcDir, Path tgtDir, SyncResult result) throws IOException {
        // Ensure target directory exists
        if (!Files.exists(tgtDir)) {
            if (!options.isDryRun()) {
                Files.createDirectories(tgtDir);
            }
            result.addDirectoryCreated(tgtDir);
            LOG.fine(() -> "Created directory: " + tgtDir);
        }

        // Track which names exist in source (for orphan detection)
        Set<String> sourceNames = new HashSet<>();

        // --- copy / update from source to target ---
        try (Stream<Path> entries = Files.list(srcDir)) {
            for (Path srcEntry : (Iterable<Path>) entries::iterator) {
                String name = srcEntry.getFileName().toString();
                sourceNames.add(name);
                Path tgtEntry = tgtDir.resolve(name);

                if (Files.isDirectory(srcEntry)) {
                    if (options.isSyncSubDirectories()) {
                        syncDirectory(srcEntry, tgtEntry, result);
                    }
                } else if (Files.isRegularFile(srcEntry)) {
                    syncFile(srcEntry, tgtEntry, result);
                }
            }
        }

        // --- delete orphans in target ---
        if (options.isDeleteOrphans()) {
            deleteOrphans(tgtDir, sourceNames, result);
        }
    }

    private void syncFile(Path srcFile, Path tgtFile, SyncResult result) throws IOException {
        if (!Files.exists(tgtFile)) {
            // New file → copy
            if (!options.isDryRun()) {
                Files.copy(srcFile, tgtFile, StandardCopyOption.COPY_ATTRIBUTES);
            }
            result.addCopied(tgtFile);
            LOG.fine(() -> "Copied: " + srcFile + " → " + tgtFile);
        } else if (needsUpdate(srcFile, tgtFile)) {
            // Existing file is outdated → overwrite
            if (!options.isDryRun()) {
                Files.copy(srcFile, tgtFile,
                        StandardCopyOption.REPLACE_EXISTING,
                        StandardCopyOption.COPY_ATTRIBUTES);
            }
            result.addUpdated(tgtFile);
            LOG.fine(() -> "Updated: " + tgtFile);
        }
        // else: file is identical – nothing to do
    }

    /**
     * Returns true when the source file is newer or has a different size.
     */
    boolean needsUpdate(Path srcFile, Path tgtFile) throws IOException {
        BasicFileAttributes srcAttr = Files.readAttributes(srcFile, BasicFileAttributes.class);
        BasicFileAttributes tgtAttr = Files.readAttributes(tgtFile, BasicFileAttributes.class);

        if (srcAttr.size() != tgtAttr.size()) {
            return true;
        }

        FileTime srcTime = srcAttr.lastModifiedTime();
        FileTime tgtTime = tgtAttr.lastModifiedTime();
        return srcTime.compareTo(tgtTime) > 0;
    }

    private void deleteOrphans(Path tgtDir, Set<String> sourceNames, SyncResult result)
            throws IOException {
        if (!Files.isDirectory(tgtDir)) return;

        try (Stream<Path> entries = Files.list(tgtDir)) {
            for (Path tgtEntry : (Iterable<Path>) entries::iterator) {
                String name = tgtEntry.getFileName().toString();
                if (!sourceNames.contains(name)) {
                    if (Files.isDirectory(tgtEntry)) {
                        deleteRecursively(tgtEntry, result);
                    } else {
                        if (!options.isDryRun()) {
                            Files.delete(tgtEntry);
                        }
                        result.addDeleted(tgtEntry);
                        LOG.fine(() -> "Deleted orphan: " + tgtEntry);
                    }
                }
            }
        }
    }

    private void deleteRecursively(Path dir, SyncResult result) throws IOException {
        Files.walkFileTree(dir, new SimpleFileVisitor<>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs)
                    throws IOException {
                if (!options.isDryRun()) {
                    Files.delete(file);
                }
                result.addDeleted(file);
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult postVisitDirectory(Path d, IOException exc)
                    throws IOException {
                if (!options.isDryRun()) {
                    Files.delete(d);
                }
                result.addDeleted(d);
                return FileVisitResult.CONTINUE;
            }
        });
    }
}
