package com.filesync;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.FileTime;
import java.time.Instant;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class FileSynchronizerTest {

    @TempDir
    Path sourceDir;

    @TempDir
    Path targetDir;

    // ---- helper methods ----------------------------------------------------

    private Path createSourceFile(String relativePath, String content) throws IOException {
        Path file = sourceDir.resolve(relativePath);
        Files.createDirectories(file.getParent());
        Files.writeString(file, content);
        return file;
    }

    private Path createTargetFile(String relativePath, String content) throws IOException {
        Path file = targetDir.resolve(relativePath);
        Files.createDirectories(file.getParent());
        Files.writeString(file, content);
        return file;
    }

    private FileSynchronizer syncer(SyncOptions options) {
        return new FileSynchronizer(sourceDir, targetDir, options);
    }

    private FileSynchronizer syncer() {
        return new FileSynchronizer(sourceDir, targetDir);
    }

    // ---- tests: basic copy -------------------------------------------------

    @Test
    @DisplayName("Copy new files from source to empty target")
    void copyNewFiles() throws IOException {
        createSourceFile("a.txt", "hello");
        createSourceFile("b.txt", "world");

        SyncResult result = syncer().sync();

        assertEquals(2, result.getFilesCopied());
        assertEquals("hello", Files.readString(targetDir.resolve("a.txt")));
        assertEquals("world", Files.readString(targetDir.resolve("b.txt")));
    }

    @Test
    @DisplayName("Identical files are not re-copied")
    void skipIdenticalFiles() throws IOException {
        createSourceFile("same.txt", "data");

        // First sync – copies the file
        syncer().sync();

        // Second sync – nothing changed
        SyncResult result = syncer().sync();

        assertEquals(0, result.getFilesCopied());
        assertEquals(0, result.getFilesUpdated());
        assertEquals(0, result.getTotalChanges());
    }

    // ---- tests: update detection -------------------------------------------

    @Test
    @DisplayName("Update file when source is newer")
    void updateNewerFile() throws IOException {
        createSourceFile("data.txt", "version-2");
        createTargetFile("data.txt", "version-1");

        // Make source newer than target
        FileTime future = FileTime.from(Instant.now().plusSeconds(60));
        Files.setLastModifiedTime(sourceDir.resolve("data.txt"), future);

        SyncResult result = syncer().sync();

        assertEquals(1, result.getFilesUpdated());
        assertEquals("version-2", Files.readString(targetDir.resolve("data.txt")));
    }

    @Test
    @DisplayName("Update file when sizes differ even if target is newer")
    void updateDifferentSize() throws IOException {
        createSourceFile("data.txt", "short");
        createTargetFile("data.txt", "this is a much longer string");

        // Make target newer – size difference should still trigger update
        FileTime past = FileTime.from(Instant.now().minusSeconds(120));
