### `RateLimitRule.java` — A single rate limit rule

```java
package config;

import java.util.Objects;

public final class RateLimitRule {

    private final Strategy strategy;
    private final double requestsPerSecond;
    private final int burstSize;
    private final boolean enabled;

    private RateLimitRule(Builder builder) {
        this.strategy = builder.strategy;
        this.requestsPerSecond = builder.requestsPerSecond;
        this.burstSize = builder.burstSize;
        this.enabled = builder.enabled;
    }

    // ── Getters ─────────────────────────────────

    public Strategy getStrategy()        { return strategy; }
    public double getRequestsPerSecond() { return requestsPerSecond; }
    public int getBurstSize()            { return burstSize; }
    public boolean isEnabled()           { return enabled; }

    /**
     * Creates a new rule by merging this rule's defaults
     * with any non-null overrides from the given rule.
     */
    public RateLimitRule mergeWith(RateLimitRule overrides) {
        if (overrides == null) return this;
        return new Builder()
            .strategy(overrides.strategy != null ? overrides.strategy : this.strategy)
            .requestsPerSecond(overrides.requestsPerSecond > 0
                ? overrides.requestsPerSecond : this.requestsPerSecond)
            .burstSize(overrides.burstSize > 0
                ? overrides.burstSize : this.burstSize)
            .enabled(overrides.enabled)
            .build();
    }

    @Override
    public String toString() {
        return String.format(
            "RateLimitRule{strategy=%s, rps=%.1f, burst=%d, enabled=%b}",
            strategy, requestsPerSecond, burstSize, enabled
        );
    }

    // ── Builder ─────────────────────────────────

    public static class Builder {
        private Strategy strategy;
        private double requestsPerSecond;
        private int burstSize;
        private boolean enabled = true;

        public Builder strategy(Strategy s)           { this.strategy = s; return this; }
        public Builder requestsPerSecond(double rps)  { this.requestsPerSecond = rps; return this; }
        public Builder burstSize(int size)            { this.burstSize = size; return this; }
        public Builder enabled(boolean flag)          { this.enabled = flag; return this; }

        public RateLimitRule build() {
            Objects.requireNonNull(strategy, "strategy must not be null");
            if (enabled && requestsPerSecond <= 0) {
                throw new IllegalArgumentException("requestsPerSecond must be > 0");
            }
            if (enabled && burstSize <= 0) {
                throw new IllegalArgumentException("burstSize must be > 0");
            }
            return new RateLimitRule(this);
        }
    }
}
