### `RateLimitConfig.java` — Holds all parsed config

```java
package config;

import java.util.Collections;
import java.util.Map;
import java.util.Optional;

public final class RateLimitConfig {

    private final RateLimitRule globalDefault;
    private final Map<String, RateLimitRule> endpointRules;  // path → rule
    private final Map<String, RateLimitRule> tierRules;       // tier name → rule

    public RateLimitConfig(
            RateLimitRule globalDefault,
            Map<String, RateLimitRule> endpointRules,
            Map<String, RateLimitRule> tierRules) {
        this.globalDefault  = globalDefault;
        this.endpointRules  = Collections.unmodifiableMap(endpointRules);
        this.tierRules      = Collections.unmodifiableMap(tierRules);
    }

    public RateLimitRule getGlobalDefault() {
        return globalDefault;
    }

    /** Resolves the effective rule: endpoint override merged onto global default. */
    public RateLimitRule resolveForEndpoint(String path) {
        RateLimitRule endpointRule = endpointRules.get(path);
        return (endpointRule != null)
            ? globalDefault.mergeWith(endpointRule)
            : globalDefault;
    }

    /** Resolves the effective rule for a client tier. */
    public Optional<RateLimitRule> resolveForTier(String tierName) {
        return Optional.ofNullable(tierRules.get(tierName));
    }

    /** Resolves endpoint + tier, with tier taking priority for rps/burst. */
    public RateLimitRule resolve(String path, String tierName) {
        RateLimitRule base = resolveForEndpoint(path);
        RateLimitRule tier = tierRules.get(tierName);
        return (tier != null) ? base.mergeWith(tier) : base;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("RateLimitConfig {\n");
        sb.append("  global: ").append(globalDefault).append('\n');
        endpointRules.forEach((k, v) ->
            sb.append("  endpoint[").append(k).append("]: ").append(v).append('\n'));
        tierRules.forEach((k, v) ->
            sb.append("  tier[").append(k).append("]: ").append(v).append('\n'));
        sb.append('}');
        return sb.toString();
    }
}
