### `ConfigParser.java` — Parses the `.conf` file

```java
package config;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;

public final class ConfigParser {

    // Intermediate store: section → (field → value)
    // e.g. "endpoint./api/login" → {"requests_per_second": "5", ...}
    private final Map<String, Map<String, String>> sections = new LinkedHashMap<>();

    private ConfigParser() {}

    // ── Public factory methods ──────────────────

    public static RateLimitConfig parseFile(Path path) throws IOException {
        try (BufferedReader reader = Files.newBufferedReader(path)) {
            return new ConfigParser().parse(reader);
        }
    }

    public static RateLimitConfig parseResource(String resourceName) throws IOException {
        InputStream is = ConfigParser.class.getClassLoader().getResourceAsStream(resourceName);
        if (is == null) throw new IOException("Resource not found: " + resourceName);
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(is))) {
            return new ConfigParser().parse(reader);
        }
    }

    public static RateLimitConfig parseString(String configText) {
        try (BufferedReader reader = new BufferedReader(
                new java.io.StringReader(configText))) {
            return new ConfigParser().parse(reader);
        } catch (IOException e) {
            throw new RuntimeException("Failed to parse config string", e);
        }
    }

    // ── Core parsing logic ──────────────────────

    private RateLimitConfig parse(BufferedReader reader) throws IOException {
        // Phase 1: tokenize lines into sections map
        int lineNum = 0;
        String line;
        while ((line = reader.readLine()) != null) {
            lineNum++;
            line = line.trim();

            // Skip blanks and comments
            if (line.isEmpty() || line.startsWith("#")) continue;

            int eqIndex = line.indexOf('=');
            if (eqIndex < 0) {
                throw new ConfigException(lineNum, "Expected key=value, got: " + line);
            }

            String fullKey = line.substring(0, eqIndex).trim();
            String value   = line.substring(eqIndex + 1).trim();

            // Split "global.strategy" → section="global", field="strategy"
            // Split "endpoint./api/login.burst_size" → section="endpoint./api/login", field="burst_size"
            String section;
            String field;
            int lastDot = fullKey.lastIndexOf('.');
            if (lastDot < 0) {
                throw new ConfigException(lineNum, "Key must have at least one dot: " + fullKey);
            }
            section = fullKey.substring(0, lastDot);
            field   = fullKey.substring(lastDot + 1);

            sections.computeIfAbsent(section, k -> new LinkedHashMap<>())
                    .put(field, value);
        }

        // Phase 2: build typed objects from sections
        return buildConfig();
    }

    private RateLimitConfig buildConfig() {
        // ── Global defaults ───────────────────
        Map<String, String> globalProps = sections.getOrDefault("global", Map.of());
        RateLimitRule globalDefault = buildRule(globalProps, "global");

        // ── Endpoint overrides ────────────────
        Map<String, RateLimitRule> endpointRules = new LinkedHashMap<>();
        // ── Tier rules ────────────────────────
        Map<String, RateLimitRule> tierRules = new LinkedHashMap<>();

        for (Map.Entry<String, Map<String, String>> entry : sections.entrySet()) {
            String sectionKey = entry.getKey();
            Map<String, String> props = entry.getValue();

            if (sectionKey.equals("global")) {
                continue; // already handled
            }
            if (sectionKey.startsWith("endpoint.")) {
                String path = sectionKey.substring("endpoint.".length());
                endpointRules.put(path, buildRulePartial(props, sectionKey, globalDefault));
            } else if (sectionKey.startsWith("tier.")) {
                String tierName = sectionKey.substring("tier.".length());
                tierRules.put(tierName, buildRulePartial(props, sectionKey, globalDefault));
            } else {
                throw new ConfigException(0, "Unknown config section: " + sectionKey);
            }
        }

        return new RateLimitConfig(globalDefault, endpointRules, tierRules);
    }

    /** Builds a complete rule (all fields required). */
    private RateLimitRule buildRule(Map<String, String> props, String sectionName) {
        return new RateLimitRule.Builder()
            .strategy(Strategy.fromString(
                requireProp(props, "strategy", sectionName)))
            .requestsPerSecond(parseDouble(
                requireProp(props, "requests_per_second", sectionName), sectionName))
            .burstSize(parseInt(
                requireProp(props, "burst_size", sectionName), sectionName))
            .enabled(parseBoolean(
                props.getOrDefault("enabled", "true"), sectionName))
            .build();
    }

    /** Builds a partial rule (fields fall back to the global default). */
    private RateLimitRule buildRulePartial(
            Map<String, String> props, String sectionName, RateLimitRule fallback) {

        Strategy strategy = props.containsKey("strategy")
            ? Strategy.fromString(props.get("strategy"))
            : fallback.getStrategy();

        double rps = props.containsKey("requests_per_second")
            ? parseDouble(props.get("requests_per_second"), sectionName)
            : fallback.getRequestsPerSecond();

        int burst = props.containsKey("burst_size")
            ? parseInt(props.get("burst_size"), sectionName)
            : fallback.getBurstSize();

        boolean enabled = props.containsKey("enabled")
            ? parseBoolean(props.get("enabled"), sectionName)
            : fallback.isEnabled();

        return new RateLimitRule.Builder()
            .strategy(strategy)
            .requestsPerSecond(rps)
            .burstSize(burst)
            .enabled(enabled)
            .build();
    }

    // ── Parsing helpers ─────────────────────────

    private String requireProp(Map<String, String> props, String key, String section) {
        String val = props.get(key);
        if (val == null) {
            throw new ConfigException(0, "Missing required key '" + key + "' in [" + section + "]");
        }
        return val;
    }

    private double parseDouble(String val, String section) {
        try { return Double.parseDouble(val); }
        catch (NumberFormatException e) {
            throw new ConfigException(0, "Invalid number '" + val + "' in [" + section + "]");
        }
    }

    private int parseInt(String val, String section) {
        try { return Integer.parseInt(val); }
        catch (NumberFormatException e) {
            throw new ConfigException(0, "Invalid integer '" + val + "' in [" + section + "]");
        }
    }

    private boolean parseBoolean(String val, String section) {
        if ("true".equalsIgnoreCase(val))  return true;
        if ("false".equalsIgnoreCase(val)) return false;
        throw new ConfigException(0, "Invalid boolean '" + val + "' in [" + section + "]");
    }

    // ── Custom exception ────────────────────────

    public static class ConfigException extends RuntimeException {
        public ConfigException(int line, String message) {
            super(line > 0 ? "Line " + line + ": " + message : message);
        }
    }
}
