# Background Worker with Cancellation in Swift

## Using Swift Concurrency (`Task`)

```swift
import Foundation

// MARK: - Background Worker

final class BackgroundWorker<Result: Sendable>: Sendable {

    enum State: Sendable {
        case idle
        case running
        case completed(Result)
        case failed(Error)
        case cancelled
    }

    // nonisolated(unsafe) because we manage access through the task itself
    private nonisolated(unsafe) var task: Task<Result, Error>?

    /// Current state of the worker
    var state: State {
        guard let task else { return .idle }

        if task.isCancelled { return .cancelled }

        // Check if the task has already finished
        let mirror = Mirror(reflecting: task)
        _ = mirror // Task doesn't expose completion state directly
        return .running
    }

    /// Start the worker with a cancellable async operation
    @discardableResult
    func start(
        priority: TaskPriority? = nil,
        operation: @escaping @Sendable () async throws -> Result
    ) -> Task<Result, Error> {
        // Cancel any existing work
        cancel()

        let newTask = Task(priority: priority) {
            // Check for cancellation before starting
            try Task.checkCancellation()
            return try await operation()
        }

        self.task = newTask
        return newTask
    }

    /// Cancel the current operation
    func cancel() {
        task?.cancel()
        task = nil
    }

    /// Await the result of the current operation
    func value() async throws -> Result {
        guard let task else {
            throw CancellationError()
        }
        return try await task.value
    }
}
