## Practical Example: A File Processor

```swift
// MARK: - Example: Chunked File Processor

struct FileProcessor {

    /// Process data in chunks, checking for cancellation between each chunk
    static func processLargeDataSet(
        items: [String],
        chunkSize: Int = 100
    ) async throws -> [String] {
        var results: [String] = []
        results.reserveCapacity(items.count)

        for (index, chunk) in items.chunked(size: chunkSize).enumerated() {
            // ✅ Cooperative cancellation check — throws if cancelled
            try Task.checkCancellation()

            print("Processing chunk \(index + 1)...")
            let processed = try await processChunk(chunk)
            results.append(contentsOf: processed)

            // Simulate work
            try await Task.sleep(for: .milliseconds(200))
        }

        return results
    }

    private static func processChunk(_ chunk: [String]) async throws -> [String] {
        chunk.map { $0.uppercased() }
    }
}

// Helper: chunk an array
extension Array {
    func chunked(size: Int) -> [[Element]] {
        stride(from: 0, to: count, by: size).map {
            Array(self[$0..<Swift.min($0 + size, count)])
        }
    }
}
