// MARK: - Example: Polling Worker

final class PollingWorker {

    private let worker = BackgroundWorker<Void>()

    /// Start polling a resource at a regular interval
    func startPolling(interval: Duration = .seconds(5)) {
        worker.start {
            while !Task.isCancelled {      // ✅ Check flag each iteration
                await self.poll()

                do {
                    try await Task.sleep(for: interval)  // ✅ Also throws on cancel
                } catch {
                    // Task.sleep throws CancellationError when cancelled
                    break
                }
            }
            print("Polling stopped cleanly.")
        }
    }

    func stopPolling() {
        worker.cancel()
    }

    private func poll() async {
        print("[\(Date.now)] Polling...")
    }
}
