## Progress Reporting + Cancellation

```swift
// MARK: - Worker with Progress Reporting

final class ProgressWorker: ObservableObject, @unchecked Sendable {

    @Published var progress: Double = 0
    @Published var isRunning: Bool = false

    private var task: Task<Void, Error>?

    func start(totalSteps: Int) {
        cancel()
        isRunning = true
        progress = 0

        task = Task { [weak self] in
            defer {
                Task { @MainActor in self?.isRunning = false }
            }

            for step in 0..<totalSteps {
                // Two ways to handle cancellation:

                // Option 1: Throw immediately
                // try Task.checkCancellation()

                // Option 2: Clean up then exit
                guard !Task.isCancelled else {
                    print("Cancelled at step \(step). Cleaning up...")
                    await self?.cleanup()
                    return
                }

                // Simulate work
                try await Task.sleep(for: .milliseconds(300))

                let currentProgress = Double(step + 1) / Double(totalSteps)
                await MainActor.run {
                    self?.progress = currentProgress
                }
                print("Step \(step + 1)/\(totalSteps)")
            }

            print("✅ All steps completed.")
        }
    }

    func cancel() {
        task?.cancel()
        task = nil
    }

    private func cleanup() async {
        print("🧹 Cleanup complete.")
    }
}
