# exceptions.py

class RateLimitConfigError(Exception):
    """Base exception for config parsing errors."""

    def __init__(self, message: str, field: str | None = None):
        self.field = field
        detail = f" (field: '{field}')" if field else ""
        super().__init__(f"{message}{detail}")


class InvalidStrategyError(RateLimitConfigError):
    """Raised when an unknown rate limiting strategy is specified."""
    pass


class InvalidEndpointError(RateLimitConfigError):
    """Raised when endpoint config is malformed."""
    pass


class ConfigFileError(RateLimitConfigError):
    """Raised when config file cannot be read or parsed."""
    pass
