# config.py

from __future__ import annotations

import json
import os
from dataclasses import dataclass, field
from enum import Enum
from ipaddress import IPv4Address, IPv4Network, ip_address, ip_network
from pathlib import Path
from typing import Any

import yaml  # pip install pyyaml

from exceptions import (
    ConfigFileError,
    InvalidEndpointError,
    InvalidStrategyError,
    RateLimitConfigError,
)


# ── Enums ──────────────────────────────────────────────────────────

class Strategy(Enum):
    FIXED_WINDOW = "fixed_window"
    SLIDING_WINDOW = "sliding_window"
    TOKEN_BUCKET = "token_bucket"

    @classmethod
    def from_str(cls, value: str) -> Strategy:
        try:
            return cls(value.lower().strip())
        except ValueError:
            valid = [s.value for s in cls]
            raise InvalidStrategyError(
                f"Unknown strategy '{value}'. Valid options: {valid}",
                field="strategy",
            )


class StorageBackend(Enum):
    MEMORY = "memory"
    REDIS = "redis"


# ── Data Classes ───────────────────────────────────────────────────

@dataclass(frozen=True)
class RateLimitRule:
    """A single rate-limit rule with validated constraints."""

    requests: int
    window_seconds: int
    burst: int = 0
    strategy: Strategy = Strategy.SLIDING_WINDOW

    def __post_init__(self):
        if self.requests <= 0:
            raise RateLimitConfigError(
                f"'requests' must be > 0, got {self.requests}",
                field="requests",
            )
        if self.window_seconds <= 0:
            raise RateLimitConfigError(
                f"'window_seconds' must be > 0, got {self.window_seconds}",
                field="window_seconds",
            )
        if self.burst < 0:
            raise RateLimitConfigError(
                f"'burst' must be >= 0, got {self.burst}",
                field="burst",
            )

    @property
    def requests_per_second(self) -> float:
        return self.requests / self.window_seconds


@dataclass(frozen=True)
class EndpointRule:
    """Rate-limit rule scoped to a specific endpoint."""

    path: str
    method: str
    rule: RateLimitRule

    def __post_init__(self):
        if not self.path.startswith("/"):
            raise InvalidEndpointError(
                f"Endpoint path must start with '/', got '{self.path}'",
                field="path",
            )
        valid_methods = {"GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"}
        if self.method.upper() not in valid_methods:
            raise InvalidEndpointError(
                f"Invalid HTTP method '{self.method}'",
                field="method",
            )

    @property
    def key(self) -> str:
        """Unique lookup key for this endpoint."""
        return f"{self.method.upper()}:{self.path}"


@dataclass(frozen=True)
class Whitelist:
    ips: tuple[IPv4Network, ...] = ()
    api_keys: frozenset[str] = frozenset()

    def is_ip_whitelisted(self, ip: str) -> bool:
        addr = ip_address(ip)
        return any(addr in network for network in self.ips)

    def is_key_whitelisted(self, key: str) -> bool:
        return key in self.api_keys


@dataclass(frozen=True)
class ResponseConfig:
    status_code: int = 429
    retry_after_header: bool = True
    message: str = "Rate limit exceeded."


@dataclass(frozen=True)
class RedisConfig:
