    db: int = 0
    password: str | None = None
    key_prefix: str = "rl:"


@dataclass(frozen=True)
class RateLimitConfig:
    """Top-level parsed and validated rate-limiting configuration."""

    enabled: bool
    storage: StorageBackend
    default_rule: RateLimitRule
    endpoint_rules: dict[str, EndpointRule] = field(default_factory=dict)
    tier_rules: dict[str, RateLimitRule] = field(default_factory=dict)
    whitelist: Whitelist = field(default_factory=Whitelist)
    response: ResponseConfig = field(default_factory=ResponseConfig)
    redis: RedisConfig = field(default_factory=RedisConfig)

    def get_rule(
        self,
        path: str,
        method: str = "GET",
        tier: str | None = None,
    ) -> RateLimitRule:
        """Resolve the most specific rule for a request.

        Priority: endpoint > tier > default
        """
        # 1. Check endpoint-specific rules
        key = f"{method.upper()}:{path}"
        if key in self.endpoint_rules:
            return self.endpoint_rules[key].rule

        # 2. Check tier-specific rules
        if tier and tier in self.tier_rules:
            return self.tier_rules[tier]

        # 3. Fall back to default
        return self.default_rule


# ── Parser ─────────────────────────────────────────────────────────

class RateLimitConfigParser:
    """Parses rate-limit configs from YAML, JSON, dict, or env vars."""

    # Env var overrides (env var name → config path)
    ENV_MAP: dict[str, str] = {
        "RATE_LIMIT_ENABLED": "rate_limiting.enabled",
        "RATE_LIMIT_DEFAULT_REQUESTS": "rate_limiting.default.requests",
        "RATE_LIMIT_DEFAULT_WINDOW": "rate_limiting.default.window_seconds",
        "RATE_LIMIT_DEFAULT_BURST": "rate_limiting.default.burst",
        "RATE_LIMIT_DEFAULT_STRATEGY": "rate_limiting.default.strategy",
        "RATE_LIMIT_STORAGE": "rate_limiting.storage",
        "REDIS_HOST": "redis.host",
        "REDIS_PORT": "redis.port",
        "REDIS_PASSWORD": "redis.password",
    }

    def __init__(self):
        self._raw: dict[str, Any] = {}

    # ── Public loading methods ──

    def from_file(self, path: str | Path) -> RateLimitConfig:
        """Load config from a YAML or JSON file."""
        filepath = Path(path)
        if not filepath.exists():
            raise ConfigFileError(f"Config file not found: {filepath}")

        try:
            text = filepath.read_text(encoding="utf-8")
        except OSError as exc:
            raise ConfigFileError(f"Cannot read config file: {exc}")

        if filepath.suffix in (".yaml", ".yml"):
            self._raw = self._parse_yaml(text)
        elif filepath.suffix == ".json":
            self._raw = self._parse_json(text)
        else:
            raise ConfigFileError(
                f"Unsupported file format '{filepath.suffix}'. Use .yaml or .json"
            )

        self._apply_env_overrides()
        return self._build()

    def from_dict(self, data: dict[str, Any]) -> RateLimitConfig:
        """Load config from an already-parsed dictionary."""
        self._raw = data
        self._apply_env_overrides()
        return self._build()

    def from_env(self) -> RateLimitConfig:
        """Build a config purely from environment variables + defaults."""
        self._raw = {}
        self._apply_env_overrides()
        return self._build()

    # ── File format parsers ──

    @staticmethod
    def _parse_yaml(text: str) -> dict:
        try:
            data = yaml.safe_load(text)
            if not isinstance(data, dict):
                raise ConfigFileError("YAML root must be a mapping")
            return data
        except yaml.YAMLError as exc:
            raise ConfigFileError(f"Invalid YAML: {exc}")

    @staticmethod
    def _parse_json(text: str) -> dict:
        try:
            data = json.loads(text)
            if not isinstance(data, dict):
                raise ConfigFileError("JSON root must be an object")
            return data
        except json.JSONDecodeError as exc:
            raise ConfigFileError(f"Invalid JSON: {exc}")

    # ── Env-var overlay ──

    def _apply_env_overrides(self) -> None:
        """Override config values with environment variables when set."""
        for env_var, config_path in self.ENV_MAP.items():
            value = os.environ.get(env_var)
            if value is None:
                continue
            self._set_nested(self._raw, config_path.split("."), value)

    @staticmethod
    def _set_nested(data: dict, keys: list[str], value: Any) -> None:
        """Set a value in a nested dict using a list of keys."""
        for key in keys[:-1]:
            data = data.setdefault(key, {})
        # Auto-cast numeric strings
        if isinstance(value, str) and value.isdigit():
            value = int(value)
        elif isinstance(value, str) and value.lower() in ("true", "false"):
            value = value.lower() == "true"
        data[keys[-1]] = value

    # ── Safe getters ──

    def _section(self, key: str) -> dict[str, Any]:
        return self._raw.get(key, {})

    # ── Builder ──

    def _build(self) -> RateLimitConfig:
        rl = self._section("rate_limiting")

        return RateLimitConfig(
            enabled=bool(rl.get("enabled", True)),
            storage=StorageBackend(rl.get("storage", "memory")),
            default_rule=self._build_rule(rl.get("default", {})),
            endpoint_rules=self._build_endpoint_rules(rl.get("endpoints", [])),
            tier_rules=self._build_tier_rules(rl.get("tiers", {})),
            whitelist=self._build_whitelist(rl.get("whitelist", {})),
            response=self._build_response(rl.get("response", {})),
            redis=self._build_redis(self._section("redis")),
        )

    # ── Sub-builders ──

    @staticmethod
    def _build_rule(data: dict[str, Any]) -> RateLimitRule:
        strategy = Strategy.from_str(data.get("strategy", "sliding_window"))
        return RateLimitRule(
            requests=int(data.get("requests", 100)),
            window_seconds=int(data.get("window_seconds", 60)),
            burst=int(data.get("burst", 0)),
            strategy=strategy,
        )

    def _build_endpoint_rules(
        self, endpoints: list[dict],
    ) -> dict[str, EndpointRule]:
        rules: dict[str, EndpointRule] = {}
        for ep in endpoints:
            if "path" not in ep:
                raise InvalidEndpointError("Endpoint missing 'path'", field="path")
            rule = EndpointRule(
                path=ep["path"],
                method=ep.get("method", "GET").upper(),
                rule=self._build_rule(ep),
            )
            if rule.key in rules:
                raise InvalidEndpointError(
                    f"Duplicate endpoint rule: {rule.key}", field="path"
                )
            rules[rule.key] = rule
        return rules

    def _build_tier_rules(self, tiers: dict[str, dict]) -> dict[str, RateLimitRule]:
        return {name: self._build_rule(data) for name, data in tiers.items()}

    @staticmethod
    def _build_whitelist(data: dict[str, Any]) -> Whitelist:
        raw_ips = data.get("ips", [])
        networks = tuple(ip_network(ip, strict=False) for ip in raw_ips)
        keys = frozenset(data.get("api_keys", []))
        return Whitelist(ips=networks, api_keys=keys)

    @staticmethod
    def _build_response(data: dict[str, Any]) -> ResponseConfig:
        return ResponseConfig(
            status_code=int(data.get("status_code", 429)),
            retry_after_header=bool(data.get("retry_after_header", True)),
            message=str(data.get("message", "Rate limit exceeded.")),
        )

    @staticmethod
    def _build_redis(data: dict[str, Any]) -> RedisConfig:
        return RedisConfig(
            host=str(data.get("host", "localhost")),
            port=int(data.get("port", 6379)),
            db=int(data.get("db", 0)),
            password=data.get("password"),
            key_prefix=str(data.get("key_prefix", "rl:")),
        )
