// ──────────────────────────────────────────────
// 1. Core Models
// ──────────────────────────────────────────────

enum Priority {
    LOW(0), MEDIUM(1), HIGH(2), CRITICAL(3);

    private final int level;

    Priority(int level) { this.level = level; }
    public int getLevel() { return level; }
}

/**
 * Holds parsed configuration for a single event type.
 */
class EventConfig {
    private final String eventName;
    private boolean enabled;
    private Priority priority;
    private List<String> handlerNames;
    private int retryCount;
    private long timeoutMs;

    public EventConfig(String eventName) {
        this.eventName = eventName;
        this.enabled = true;
        this.priority = Priority.MEDIUM;
        this.handlerNames = new ArrayList<>();
        this.retryCount = 1;
        this.timeoutMs = 5000;
    }

    // --- Setters with validation ---
    public void setEnabled(boolean enabled) { this.enabled = enabled; }

    public void setPriority(String priority) {
        this.priority = Priority.valueOf(priority.trim().toUpperCase());
    }

    public void setHandlerNames(String csv) {
        this.handlerNames = Arrays.stream(csv.split(","))
                .map(String::trim)
                .filter(s -> !s.isEmpty())
                .collect(Collectors.toList());
    }

    public void setRetryCount(int retryCount) {
        if (retryCount < 0) throw new IllegalArgumentException("retry must be >= 0");
        this.retryCount = retryCount;
    }

    public void setTimeoutMs(long timeoutMs) {
        if (timeoutMs <= 0) throw new IllegalArgumentException("timeout must be > 0");
        this.timeoutMs = timeoutMs;
    }

    // --- Getters ---
    public String getEventName()        { return eventName; }
    public boolean isEnabled()          { return enabled; }
    public Priority getPriority()       { return priority; }
    public List<String> getHandlerNames() { return Collections.unmodifiableList(handlerNames); }
    public int getRetryCount()          { return retryCount; }
    public long getTimeoutMs()          { return timeoutMs; }

    @Override
    public String toString() {
        return String.format("EventConfig{name='%s', enabled=%s, priority=%s, handlers=%s, retry=%d, timeout=%dms}",
                eventName, enabled, priority, handlerNames, retryCount, timeoutMs);
    }
}

