// ──────────────────────────────────────────────
// 2. Config Parser
// ──────────────────────────────────────────────

class ConfigParseException extends RuntimeException {
    private final int lineNumber;

    public ConfigParseException(String message, int lineNumber) {
        super(String.format("Line %d: %s", lineNumber, message));
        this.lineNumber = lineNumber;
    }

    public ConfigParseException(String message, int lineNumber, Throwable cause) {
        super(String.format("Line %d: %s", lineNumber, message), cause);
        this.lineNumber = lineNumber;
    }

    public int getLineNumber() { return lineNumber; }
}

/**
 * Parses the .conf file into a map of EventConfig objects.
 *
 * Supported format:
 *   [event:<name>]        — starts a new event section
 *   key=value             — sets a property on the current section
 *   # comment             — ignored
 *   blank lines           — ignored
 */
class ConfigParser {

    private static final String SECTION_PREFIX = "[event:";
    private static final String SECTION_SUFFIX = "]";

    /**
     * Parse from a file path.
     */
    public Map<String, EventConfig> parseFile(String filePath) throws IOException {
        List<String> lines = Files.readAllLines(Path.of(filePath));
        return parseLines(lines);
    }

    /**
     * Parse from a raw string (useful for testing).
     */
    public Map<String, EventConfig> parseString(String content) {
        List<String> lines = Arrays.asList(content.split("\\R")); // split on any line break
        return parseLines(lines);
    }

    /**
     * Core parse logic operating on a list of lines.
     */
    private Map<String, EventConfig> parseLines(List<String> lines) {
        Map<String, EventConfig> configs = new LinkedHashMap<>();
        EventConfig current = null;
        int lineNum = 0;

        for (String rawLine : lines) {
            lineNum++;
            String line = rawLine.trim();

            // Skip blanks and comments
            if (line.isEmpty() || line.startsWith("#")) {
                continue;
            }

            // Section header: [event:some_name]
            if (line.startsWith(SECTION_PREFIX) && line.endsWith(SECTION_SUFFIX)) {
                String name = line.substring(SECTION_PREFIX.length(), line.length() - 1).trim();
                if (name.isEmpty()) {
                    throw new ConfigParseException("Empty event name", lineNum);
                }
                if (configs.containsKey(name)) {
                    throw new ConfigParseException("Duplicate event: " + name, lineNum);
                }
                current = new EventConfig(name);
                configs.put(name, current);
                continue;
            }

            // Key=value pair
            int eqIndex = line.indexOf('=');
            if (eqIndex <= 0) {
                throw new ConfigParseException("Expected key=value, got: " + line, lineNum);
            }
            if (current == null) {
                throw new ConfigParseException("Property outside of [event:] section", lineNum);
            }

            String key = line.substring(0, eqIndex).trim().toLowerCase();
            String value = line.substring(eqIndex + 1).trim();

            try {
                applyProperty(current, key, value);
            } catch (IllegalArgumentException e) {
                throw new ConfigParseException(
                        "Invalid value for '" + key + "': " + e.getMessage(), lineNum, e);
            }
        }

        return configs;
    }

    /**
     * Maps a key/value pair onto the EventConfig.
     */
    private void applyProperty(EventConfig config, String key, String value) {
        switch (key) {
            case "enabled"  -> config.setEnabled(Boolean.parseBoolean(value));
            case "priority" -> config.setPriority(value);
            case "handlers" -> config.setHandlerNames(value);
            case "retry"    -> config.setRetryCount(Integer.parseInt(value));
            case "timeout"  -> config.setTimeoutMs(Long.parseLong(value));
            default         -> throw new IllegalArgumentException("Unknown property: " + key);
        }
    }
}

// ──────────────────────────────────────────────
// 3. Event Handlers (pluggable)
// ──────────────────────────────────────────────

/**
 * All handlers implement this interface.
 */
interface EventHandler {
    String getName();
    EventResult handle(Event event);
}

class LogHandler implements EventHandler {
    @Override public String getName() { return "LogHandler"; }

    @Override
    public EventResult handle(Event event) {
        System.out.printf("    📝 LOG  [%s] %s — %s%n", event.getId(), event.getType(), event.getPayload());
        return new EventResult(EventResult.Status.SUCCESS, getName(), "Logged successfully");
    }
}

class AuthHandler implements EventHandler {
    @Override public String getName() { return "AuthHandler"; }

    @Override
    public EventResult handle(Event event) {
        Object user = event.getPayload().get("user");
        if (user == null || user.toString().isBlank()) {
            return new EventResult(EventResult.Status.FAILURE, getName(), "Missing user in payload");
        }
        System.out.printf("    🔐 AUTH [%s] Authenticated user: %s%n", event.getId(), user);
        return new EventResult(EventResult.Status.SUCCESS, getName(), "User authenticated");
    }
}

class ValidationHandler implements EventHandler {
    @Override public String getName() { return "ValidationHandler"; }

    @Override
    public EventResult handle(Event event) {
        Object amount = event.getPayload().get("amount");
        if (amount == null) {
            return new EventResult(EventResult.Status.FAILURE, getName(), "Missing 'amount'");
        }
        double val = Double.parseDouble(amount.toString());
        if (val <= 0) {
            return new EventResult(EventResult.Status.FAILURE, getName(), "Amount must be positive");
        }
        System.out.printf("    ✅ VALID [%s] Amount $%.2f OK%n", event.getId(), val);
        return new EventResult(EventResult.Status.SUCCESS, getName(), "Validation passed");
    }
}

class NotificationHandler implements EventHandler {
    @Override public String getName() { return "NotificationHandler"; }

    @Override
    public EventResult handle(Event event) {
        System.out.printf("    🔔 NOTIFY [%s] Notification sent for: %s%n", event.getId(), event.getType());
        return new EventResult(EventResult.Status.SUCCESS, getName(), "Notification sent");
    }
}

// ──────────────────────────────────────────────
// 4. Handler Registry
// ──────────────────────────────────────────────

/**
 * Maps handler names (from config) → handler instances.
 */
class HandlerRegistry {

    private final Map<String, EventHandler> handlers = new HashMap<>();

    public void register(EventHandler handler) {
        handlers.put(handler.getName(), handler);
    }

    public EventHandler get(String name) {
        EventHandler h = handlers.get(name);
        if (h == null) throw new IllegalArgumentException("Unknown handler: " + name);
        return h;
    }

    public boolean contains(String name) {
        return handlers.containsKey(name);
    }

    /**
     * Resolve an ordered list of names into handler instances.
     */
    public List<EventHandler> resolve(List<String> names) {
        return names.stream().map(this::get).collect(Collectors.toList());
    }
}

// ──────────────────────────────────────────────
// 5. Event Processor (ties everything together)
// ──────────────────────────────────────────────

/**
 * Processes events through the handler pipeline defined in config.
 * Supports retry logic, timeouts, and priority-based filtering.
 */
class EventProcessor {

    private final Map<String, EventConfig> configs;
    private final HandlerRegistry registry;
    private final List<ProcessingRecord> history = new ArrayList<>();

    public EventProcessor(Map<String, EventConfig> configs, HandlerRegistry registry) {
        this.configs = configs;
        this.registry = registry;
        validate();
    }

    /**
     * Make sure every handler referenced in config actually exists.
     */
    private void validate() {
        for (EventConfig cfg : configs.values()) {
            for (String name : cfg.getHandlerNames()) {
                if (!registry.contains(name)) {
                    throw new IllegalStateException(
                            "Event '" + cfg.getEventName() + "' references unknown handler: " + name);
                }
            }
        }
    }

    /**
     * Submit an event for processing.
     */
    public List<EventResult> process(Event event) {
        EventConfig config = configs.get(event.getType());

        if (config == null) {
            System.out.printf("⚠ No config for event type '%s' — skipping%n", event.getType());
            return List.of(new EventResult(EventResult.Status.SKIPPED, "Processor",
                    "No config for type: " + event.getType()));
        }

        if (!config.isEnabled()) {
            System.out.printf("⏸ Event '%s' is disabled — skipping%n", event.getType());
            return List.of(new EventResult(EventResult.Status.SKIPPED, "Processor",
                    "Event disabled: " + event.getType()));
        }

        System.out.printf("%n▶ Processing %s [priority=%s, retry=%d, timeout=%dms]%n",
                event, config.getPriority(), config.getRetryCount(), config.getTimeoutMs());

        List<EventHandler> pipeline = registry.resolve(config.getHandlerNames());
        List<EventResult> results = new ArrayList<>();

        for (EventHandler handler : pipeline) {
            EventResult result = executeWithRetry(handler, event, config.getRetryCount());
            results.add(result);

            // Stop pipeline on failure (fail-fast)
            if (result.getStatus() == EventResult.Status.FAILURE) {
                System.out.printf("    ❌ Pipeline halted at %s: %s%n", handler.getName(), result.getMessage());
                break;
            }
        }

        history.add(new ProcessingRecord(event, config, results));
        return results;
    }

    /**
     * Execute a handler with retry on failure.
     */
    private EventResult executeWithRetry(EventHandler handler, Event event, int maxRetries) {
        EventResult result = null;
        for (int attempt = 1; attempt <= maxRetries; attempt++) {
            try {
                result = handler.handle(event);
                if (result.getStatus() == EventResult.Status.SUCCESS) {
                    return result;
                }
            } catch (Exception e) {
                result = new EventResult(EventResult.Status.FAILURE, handler.getName(),
                        "Exception: " + e.getMessage());
            }

            if (attempt < maxRetries) {
                System.out.printf("    ⟳ Retrying %s (attempt %d/%d)%n", handler.getName(), attempt + 1, maxRetries);
            }
        }
        return result;
    }

    /**
     * Query history — e.g., all events that had at least one failure.
     */
    public List<ProcessingRecord> getHistory(Predicate<ProcessingRecord> filter) {
        return history.stream().filter(filter).collect(Collectors.toList());
    }

    public List<ProcessingRecord> getFullHistory() {
        return Collections.unmodifiableList(history);
    }

    // ---- Inner record for audit trail ----
    public static class ProcessingRecord {
        private final Event event;
        private final EventConfig config;

