<?php

class Task
{
    public function __construct(
        public readonly string $id,
        public readonly string $name,
        public readonly array $payload,
        public readonly int $priority = 0,
        public readonly ?int $runAt = null,
        public int $attempts = 0,
        public int $maxAttempts = 3
    ) {
    }
}

class TaskQueue
{
    private array $queue = [];
    private array $delayed = [];
    private array $failed = [];

    public function push(Task $task): void
    {
        if ($task->runAt !== null && $task->runAt > time()) {
            $this->delayed[] = $task;
            echo "[Queue] Task '{$task->name}' (ID: {$task->id}) scheduled for " . date('H:i:s', $task->runAt) . "\n";
            return;
        }

        $this->queue[] = $task;
        $this->sortByPriority();
        echo "[Queue] Task '{$task->name}' (ID: {$task->id}) added (priority: {$task->priority})\n";
    }

    public function pop(): ?Task
    {
        $this->promoteDelayed();

        if (empty($this->queue)) {
            return null;
        }

        return array_shift($this->queue);
    }

    public function retry(Task $task): void
    {
        $task->attempts++;
        if ($task->attempts >= $task->maxAttempts) {
            $this->failed[] = $task;
            echo "[Queue] Task '{$task->name}' moved to failed queue after {$task->attempts} attempts\n";
            return;
        }

        $this->queue[] = $task;
        $this->sortByPriority();
        echo "[Queue] Task '{$task->name}' requeued (attempt {$task->attempts}/{$task->maxAttempts})\n";
    }

    public function size(): int
    {
        return count($this->queue);
    }

    public function delayedCount(): int
    {
        return count($this->delayed);
    }

    public function failedCount(): int
    {
        return count($this->failed);
    }

    public function getFailedTasks(): array
    {
        return $this->failed;
    }

    private function promoteDelayed(): void
    {
        $now = time();
        $stillDelayed = [];

        foreach ($this->delayed as $task) {
            if ($task->runAt <= $now) {
                $this->queue[] = $task;
                echo "[Queue] Delayed task '{$task->name}' promoted to ready queue\n";
            } else {
                $stillDelayed[] = $task;
            }
        }

        if (count($stillDelayed) !== count($this->delayed)) {
            $this->sortByPriority();
        }

        $this->delayed = $stillDelayed;
    }

    private function sortByPriority(): void
    {
        usort($this->queue, fn(Task $a, Task $b) => $b->priority <=> $a->priority);
    }
}

class TaskConsumer
{
    private bool $running = false;
    private array $handlers = [];
    private int $processed = 0;
    private int $errors = 0;

    public function __construct(
        private TaskQueue $queue,
        private int $pollIntervalMs = 500,
        private int $maxTasks = 0  // 0 = unlimited
    ) {
    }

    public function registerHandler(string $taskName, callable $handler): void
    {
        $this->handlers[$taskName] = $handler;
        echo "[Consumer] Handler registered for '{$taskName}'\n";
    }

    public function start(): void
    {
        $this->running = true;
        echo "[Consumer] Started. Polling every {$this->pollIntervalMs}ms...\n";
        echo str_repeat('-', 50) . "\n";

        while ($this->running) {
            $task = $this->queue->pop();

            if ($task === null) {
                if ($this->queue->delayedCount() === 0) {
                    echo "[Consumer] Queue empty, shutting down.\n";
                    break;
                }
                usleep($this->pollIntervalMs * 1000);
                continue;
            }

            $this->process($task);

            if ($this->maxTasks > 0 && $this->processed >= $this->maxTasks) {
                echo "[Consumer] Max tasks ({$this->maxTasks}) reached.\n";
                break;
            }

            usleep($this->pollIntervalMs * 1000);
        }

        $this->printStats();
    }

    public function stop(): void
    {
        $this->running = false;
        echo "[Consumer] Stop signal received.\n";
    }

    private function process(Task $task): void
    {
        echo "[Consumer] Processing '{$task->name}' (ID: {$task->id})...\n";

        if (!isset($this->handlers[$task->name])) {
            echo "[Consumer] No handler for '{$task->name}', skipping.\n";
            $this->errors++;
            return;
        }

        try {
            $handler = $this->handlers[$task->name];
            $result = $handler($task->payload);
            $this->processed++;
            echo "[Consumer] ✓ '{$task->name}' completed" . ($result ? ": {$result}" : "") . "\n";
        } catch (\Exception $e) {
            $this->errors++;
            echo "[Consumer] ✗ '{$task->name}' failed: {$e->getMessage()}\n";
            $this->queue->retry($task);
        }
    }

    private function printStats(): void
    {
        echo str_repeat('-', 50) . "\n";
        echo "[Stats] Processed: {$this->processed} | Errors: {$this->errors} | Failed: {$this->queue->failedCount()}\n";
    }
}

