// ConfigException.java — Base and specific exceptions
public class ConfigException extends Exception {
    private final int lineNumber;
    private final String line;

    public ConfigException(String message, int lineNumber, String line) {
        super(String.format("Line %d: %s -> \"%s\"", lineNumber, message, line));
        this.lineNumber = lineNumber;
        this.line = line;
    }

    public ConfigException(String message) {
        super(message);
        this.lineNumber = -1;
        this.line = "";
    }

    public int getLineNumber() { return lineNumber; }
    public String getLine() { return line; }

    // --- Specific exception types ---

    public static class ParseException extends ConfigException {
        public ParseException(String message, int lineNumber, String line) {
            super("Parse error: " + message, lineNumber, line);
        }
    }

    public static class DuplicateKeyException extends ConfigException {
        public DuplicateKeyException(String key, String section, int lineNumber, String line) {
            super(String.format("Duplicate key '%s' in section [%s]", key, section),
                  lineNumber, line);
        }
    }

    public static class InvalidValueException extends ConfigException {
        public InvalidValueException(String key, String expectedType, String actualValue) {
            super(String.format("Key '%s' expected %s but got '%s'",
                  key, expectedType, actualValue));
        }
    }

    public static class MissingKeyException extends ConfigException {
        public MissingKeyException(String key, String section) {
            super(String.format("Required key '%s' not found in section [%s]", key, section));
        }
    }

    public static class ValidationException extends ConfigException {
        public ValidationException(String message) {
            super("Validation failed: " + message);
        }
    }
}
