// ConfigEntry.java — Represents one config value with type coercion
public class ConfigEntry {
    private final String key;
    private final String rawValue;
    private final int lineNumber;

    public ConfigEntry(String key, String rawValue, int lineNumber) {
        this.key = key;
        this.rawValue = rawValue;
        this.lineNumber = lineNumber;
    }

    public String getKey() { return key; }
    public String getRawValue() { return rawValue; }
    public int getLineNumber() { return lineNumber; }

    // --- Type-safe accessors with clear error messages ---

    public String asString() {
        return rawValue;
    }

    public int asInt() throws ConfigException.InvalidValueException {
        try {
            return Integer.parseInt(rawValue.trim());
        } catch (NumberFormatException e) {
            throw new ConfigException.InvalidValueException(key, "integer", rawValue);
        }
    }

    public long asLong() throws ConfigException.InvalidValueException {
        try {
            return Long.parseLong(rawValue.trim());
        } catch (NumberFormatException e) {
            throw new ConfigException.InvalidValueException(key, "long", rawValue);
        }
    }

    public double asDouble() throws ConfigException.InvalidValueException {
        try {
            return Double.parseDouble(rawValue.trim());
        } catch (NumberFormatException e) {
            throw new ConfigException.InvalidValueException(key, "double", rawValue);
        }
    }

    public boolean asBoolean() throws ConfigException.InvalidValueException {
        String val = rawValue.trim().toLowerCase();
        if (val.equals("true") || val.equals("yes") || val.equals("1") || val.equals("on")) {
            return true;
        }
        if (val.equals("false") || val.equals("no") || val.equals("0") || val.equals("off")) {
            return false;
        }
        throw new ConfigException.InvalidValueException(key, "boolean (true/false/yes/no/1/0/on/off)", rawValue);
    }

    public String[] asList() {
        return rawValue.split("\\s*,\\s*");
    }

    @Override
    public String toString() {
        return String.format("%s = %s (line %d)", key, rawValue, lineNumber);
    }
}
