## Step 3: Config Section

```java
// ConfigSection.java — A named group of config entries
import java.util.*;

public class ConfigSection {
    private final String name;
    private final Map<String, ConfigEntry> entries;
    private final List<String> keyOrder; // preserve insertion order

    public ConfigSection(String name) {
        this.name = name;
        this.entries = new LinkedHashMap<>();
        this.keyOrder = new ArrayList<>();
    }

    public String getName() { return name; }

    public void addEntry(ConfigEntry entry, boolean allowOverwrite)
            throws ConfigException.DuplicateKeyException {
        if (!allowOverwrite && entries.containsKey(entry.getKey())) {
            throw new ConfigException.DuplicateKeyException(
                entry.getKey(), name, entry.getLineNumber(),
                entry.getKey() + " = " + entry.getRawValue()
            );
        }
        entries.put(entry.getKey(), entry);
        if (!keyOrder.contains(entry.getKey())) {
            keyOrder.add(entry.getKey());
        }
    }

    // --- Retrieval with Optional and default fallbacks ---

    public Optional<ConfigEntry> get(String key) {
        return Optional.ofNullable(entries.get(key));
    }

    public ConfigEntry getRequired(String key) throws ConfigException.MissingKeyException {
        return get(key).orElseThrow(() -> new ConfigException.MissingKeyException(key, name));
    }

    public String getString(String key, String defaultValue) {
        return get(key).map(ConfigEntry::asString).orElse(defaultValue);
    }

    public int getInt(String key, int defaultValue) throws ConfigException.InvalidValueException {
        Optional<ConfigEntry> entry = get(key);
        if (entry.isPresent()) {
            return entry.get().asInt();
        }
        return defaultValue;
    }

    public boolean getBoolean(String key, boolean defaultValue)
            throws ConfigException.InvalidValueException {
        Optional<ConfigEntry> entry = get(key);
        if (entry.isPresent()) {
            return entry.get().asBoolean();
        }
        return defaultValue;
    }

    public boolean hasKey(String key) {
        return entries.containsKey(key);
    }

    public Set<String> getKeys() {
        return Collections.unmodifiableSet(entries.keySet());
    }

    public Map<String, ConfigEntry> getEntries() {
        return Collections.unmodifiableMap(entries);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("[").append(name).append("]\n");
        for (String key : keyOrder) {
            ConfigEntry entry = entries.get(key);
            sb.append("  ").append(key).append(" = ").append(entry.getRawValue()).append("\n");
        }
        return sb.toString();
    }
}
