// ConfigValidator.java — Declarative validation rules
import java.util.*;
import java.util.function.Predicate;

public class ConfigValidator {

    // A single validation rule
    public record Rule(
        String section,
        String key,
        boolean required,
        String description,
        Predicate<String> valuePredicate
    ) {}

    private final List<Rule> rules = new ArrayList<>();

    // --- Builder-style API ---

    public ConfigValidator requireKey(String section, String key) {
        rules.add(new Rule(section, key, true, "required key", val -> true));
        return this;
    }

    public ConfigValidator requireInt(String section, String key) {
        rules.add(new Rule(section, key, true, "must be an integer", val -> {
            try { Integer.parseInt(val.trim()); return true; }
            catch (NumberFormatException e) { return false; }
        }));
        return this;
    }

    public ConfigValidator requireIntInRange(String section, String key, int min, int max) {
        rules.add(new Rule(section, key, true,
            String.format("must be integer in [%d, %d]", min, max), val -> {
                try {
                    int v = Integer.parseInt(val.trim());
                    return v >= min && v <= max;
                } catch (NumberFormatException e) { return false; }
            }));
        return this;
    }

    public ConfigValidator requireOneOf(String section, String key, String... allowedValues) {
        Set<String> allowed = Set.of(allowedValues);
        rules.add(new Rule(section, key, true,
            "must be one of " + allowed, val -> allowed.contains(val.trim())));
        return this;
    }

    public ConfigValidator requireMatching(String section, String key, String regex, String desc) {
        rules.add(new Rule(section, key, true, desc, val -> val.trim().matches(regex)));
        return this;
    }

    public ConfigValidator optionalWithConstraint(String section, String key,
                                                   String desc, Predicate<String> pred) {
        rules.add(new Rule(section, key, false, desc, pred));
        return this;
    }

    // --- Run all rules, collect ALL errors ---

    public List<String> validate(Map<String, ConfigSection> sections) {
        List<String> errors = new ArrayList<>();

        for (Rule rule : rules) {
            ConfigSection section = sections.get(rule.section());
            if (section == null) {
                if (rule.required()) {
                    errors.add(String.format("[%s].%s — section missing (%s)",
                        rule.section(), rule.key(), rule.description()));
                }
                continue;
            }

            Optional<ConfigEntry> entry = section.get(rule.key());
            if (entry.isEmpty()) {
                if (rule.required()) {
                    errors.add(String.format("[%s].%s — key missing (%s)",
                        rule.section(), rule.key(), rule.description()));
                }
                continue;
            }

            if (!rule.valuePredicate().test(entry.get().getRawValue())) {
                errors.add(String.format("[%s].%s = '%s' — %s",
                    rule.section(), rule.key(),
                    entry.get().getRawValue(), rule.description()));
            }
        }

        return errors;
    }
}
