"use strict";

const crypto = require("crypto");
const fs = require("fs");
const { pipeline } = require("stream/promises");
const { Transform } = require("stream");

/**
 * Computes cryptographic hashes of files using streaming
 * to handle arbitrarily large files without memory pressure.
 */
class FileHasher {
  /** @param {'md5'|'sha256'|'sha512'} algorithm */
  constructor(algorithm = "sha256") {
    if (!crypto.getHashes().includes(algorithm)) {
      throw new Error(`Unsupported hash algorithm: ${algorithm}`);
    }
    this.algorithm = algorithm;
  }

  /**
   * Stream-hash a file on disk.
   * @param {string} filePath  – absolute or relative path
   * @param {object} [opts]
   * @param {number} [opts.highWaterMark=65536] – read chunk size
   * @returns {Promise<string>} hex digest
   */
  async hashFile(filePath, opts = {}) {
    const { highWaterMark = 65_536 } = opts;

    const hash = crypto.createHash(this.algorithm);
    const readStream = fs.createReadStream(filePath, { highWaterMark });

    // Transform that feeds data into the hash then passes it through
    const hashTransform = new Transform({
      transform(chunk, _encoding, cb) {
        hash.update(chunk);
        cb(null, chunk);
      },
    });

    // Discard output – we only care about the side-effect on `hash`
    const devNull = new Transform({
      transform(_chunk, _encoding, cb) {
        cb();
      },
    });

    await pipeline(readStream, hashTransform, devNull);
    return hash.digest("hex");
  }

  /**
   * Hash an in-memory buffer or string.
   * @param {string|Buffer} data
   * @returns {string} hex digest
   */
  hashData(data) {
    return crypto.createHash(this.algorithm).update(data).digest("hex");
  }

  /**
   * Compare two files by hash.
   * @returns {Promise<boolean>} true when files are byte-identical
   */
  async filesEqual(pathA, pathB) {
    const [hashA, hashB] = await Promise.all([
      this.hashFile(pathA),
      this.hashFile(pathB),
    ]);
    return hashA === hashB;
  }
}

module.exports = { FileHasher };
