"use strict";

const fs = require("fs/promises");
const path = require("path");

/**
 * @typedef {Object} FileEntry
 * @property {string}  relativePath
 * @property {string}  hash
 * @property {number}  size
 * @property {number}  mtimeMs
 * @property {boolean} isDirectory
 */

/**
 * Persistent manifest that records the last-known state of every
 * file in a sync pair.  Stored as a JSON file alongside the roots.
 */
class SyncManifest {
  /**
   * @param {string} manifestPath – where to persist the manifest
   */
  constructor(manifestPath) {
    this.manifestPath = manifestPath;
    /** @type {Map<string, FileEntry>} keyed by relativePath */
    this.entries = new Map();
    this.dirty = false;
  }

  /* ------------------------------------------------------------------ */
  /*  Persistence                                                       */
  /* ------------------------------------------------------------------ */

  /** Load from disk (no-op when the file doesn't exist yet). */
  async load() {
    try {
      const raw = await fs.readFile(this.manifestPath, "utf-8");
      const data = JSON.parse(raw);

      if (!Array.isArray(data.entries)) {
        throw new Error("Invalid manifest format");
      }

      this.entries = new Map(
        data.entries.map((e) => [e.relativePath, e])
      );
      this.dirty = false;
    } catch (err) {
      if (err.code === "ENOENT") {
        this.entries = new Map();
        this.dirty = false;
        return;
      }
      throw new Error(`Failed to load manifest: ${err.message}`);
    }
  }

  /** Atomic save: write to tmp then rename. */
  async save() {
    if (!this.dirty) return;

    const data = {
      version: 1,
      savedAt: new Date().toISOString(),
      entries: Array.from(this.entries.values()),
    };

    const tmp = `${this.manifestPath}.tmp`;
    await fs.mkdir(path.dirname(this.manifestPath), { recursive: true });
    await fs.writeFile(tmp, JSON.stringify(data, null, 2), "utf-8");
    await fs.rename(tmp, this.manifestPath);
    this.dirty = false;
  }

  /* ------------------------------------------------------------------ */
  /*  CRUD helpers                                                      */
  /* ------------------------------------------------------------------ */

  /** @param {FileEntry} entry */
  set(entry) {
    this.entries.set(entry.relativePath, { ...entry });
    this.dirty = true;
  }

  /** @returns {FileEntry|undefined} */
  get(relativePath) {
    return this.entries.get(relativePath);
  }

  /** @returns {boolean} */
  has(relativePath) {
    return this.entries.has(relativePath);
  }

  /** @returns {boolean} true if something was actually removed */
  delete(relativePath) {
    const removed = this.entries.delete(relativePath);
    if (removed) this.dirty = true;
    return removed;
  }

  /** Remove every entry. */
  clear() {
    if (this.entries.size > 0) this.dirty = true;
    this.entries.clear();
  }

  /** @returns {FileEntry[]} */
  allEntries() {
    return Array.from(this.entries.values());
  }

  /** @returns {number} */
  get size() {
    return this.entries.size;
  }
}

module.exports = { SyncManifest };
