```javascript
"use strict";

/**
 * @typedef {'source-wins'|'dest-wins'|'newest-wins'|'largest-wins'|'skip'|'custom'} Strategy
 */

/**
 * @typedef {Object} ConflictInfo
 * @property {string}  relativePath
 * @property {object}  source   – { hash, size, mtimeMs }
 * @property {object}  dest     – { hash, size, mtimeMs }
 * @property {object}  [previous] – manifest entry from last sync
 */

/**
 * @typedef {'copy-to-dest'|'copy-to-source'|'skip'} Resolution
 */

/**
 * Determines what to do when both sides changed since the last sync.
 */
class ConflictResolver {
  /**
   * @param {Strategy} strategy
   * @param {function(ConflictInfo): Resolution} [customFn] – required when strategy === 'custom'
   */
  constructor(strategy = "newest-wins", customFn = null) {
    const validStrategies = [
      "source-wins",
      "dest-wins",
      "newest-wins",
      "largest-wins",
      "skip",
      "custom",
    ];

    if (!validStrategies.includes(strategy)) {
      throw new Error(
        `Invalid strategy "${strategy}". Must be one of: ${validStrategies.join(", ")}`
      );
    }

    if (strategy === "custom" && typeof customFn !== "function") {
      throw new Error("Custom strategy requires a resolver function");
    }

    this.strategy = strategy;
    this.customFn = customFn;

    /** @type {ConflictInfo[]} */
    this.history = [];
  }

  /**
   * Resolve a single conflict.
   * @param {ConflictInfo} conflict
   * @returns {Resolution}
   */
  resolve(conflict) {
    let resolution;

    switch (this.strategy) {
      case "source-wins":
        resolution = "copy-to-dest";
        break;

      case "dest-wins":
        resolution = "copy-to-source";
        break;

      case "newest-wins":
        resolution =
          conflict.source.mtimeMs >= conflict.dest.mtimeMs
            ? "copy-to-dest"
            : "copy-to-source";
        break;

      case "largest-wins":
        resolution =
          conflict.source.size >= conflict.dest.size
            ? "copy-to-dest"
            : "copy-to-source";
        break;

      case "skip":
        resolution = "skip";
        break;

      case "custom":
        resolution = this.customFn(conflict);
        if (!["copy-to-dest", "copy-to-source", "skip"].includes(resolution)) {
          throw new Error(`Custom resolver returned invalid value: ${resolution}`);
        }
        break;

      default:
        resolution = "skip";
    }

    this.history.push({ ...conflict, resolution });
    return resolution;
  }

  /** Reset recorded history. */
  clearHistory() {
    this.history = [];
  }
}

module.exports = { ConflictResolver };
