const { SyncManifest } = require("./sync-manifest");
const { ConflictResolver } = require("./conflict-resolver");

/**
 * @typedef {'one-way'|'two-way'} SyncMode
 */

/**
 * @typedef {Object} SyncOptions
 * @property {SyncMode}  [mode='one-way']
 * @property {boolean}   [dryRun=false]
 * @property {boolean}   [deleteOrphans=false]  – remove files that no longer exist on source
 * @property {string[]}  [exclude=[]]           – glob patterns to exclude
 * @property {string[]}  [include=[]]           – glob patterns to include (empty = all)
 * @property {string}    [hashAlgorithm='sha256']
 * @property {import('./conflict-resolver').Strategy} [conflictStrategy='newest-wins']
 * @property {function}  [conflictFn]           – custom conflict resolver
 * @property {string}    [manifestDir]          – where to store the manifest (default: source root)
 */

/**
 * @typedef {Object} SyncAction
 * @property {'copy'|'delete'|'mkdir'|'conflict-resolved'|'skip'} type
 * @property {string}  relativePath
 * @property {'source'|'dest'} direction    – which side is the target of the action
 * @property {string}  [reason]
 */

/**
 * @typedef {Object} SyncResult
 * @property {number}       copied
 * @property {number}       deleted
 * @property {number}       skipped
 * @property {number}       conflicts
 * @property {number}       errors
 * @property {SyncAction[]} actions
 * @property {Error[]}      errorDetails
 * @property {number}       durationMs
 */

/**
 * Core synchronisation engine.
 *
 * Events:
 *   - `action`   (SyncAction)
 *   - `error`    (Error, relativePath)
 *   - `progress` ({ current, total, relativePath })
 *   - `complete` (SyncResult)
 */
class SyncEngine extends EventEmitter {
  /**
   * @param {string}      source  – absolute path to source root
   * @param {string}      dest    – absolute path to destination root
   * @param {SyncOptions} [options]
   */
  constructor(source, dest, options = {}) {
    super();

    this.source = path.resolve(source);
    this.dest = path.resolve(dest);

    if (this.source === this.dest) {
      throw new Error("Source and destination must be different directories");
    }

    this.options = {
      mode: "one-way",
      dryRun: false,
      deleteOrphans: false,
      exclude: [],
      include: [],
      hashAlgorithm: "sha256",
      conflictStrategy: "newest-wins",
      ...options,
    };

    this.hasher = new FileHasher(this.options.hashAlgorithm);
    this.resolver = new ConflictResolver(
      this.options.conflictStrategy,
      this.options.conflictFn
    );

    const manifestDir = this.options.manifestDir || this.source;
    this.manifest = new SyncManifest(
      path.join(manifestDir, ".sync-manifest.json")
    );

    /** True while a sync is running – prevents re-entrance. */
    this._running = false;
