  /**
   * Run a full synchronisation pass.
   * @returns {Promise<SyncResult>}
   */
  async sync() {
    if (this._running) {
      throw new Error("A sync is already in progress");
    }
    this._running = true;
    const start = Date.now();

    /** @type {SyncResult} */
    const result = {
      copied: 0,
      deleted: 0,
      skipped: 0,
      conflicts: 0,
      errors: 0,
      actions: [],
      errorDetails: [],
      durationMs: 0,
    };

    try {
      // Ensure both roots exist
      await fs.mkdir(this.source, { recursive: true });
      await fs.mkdir(this.dest, { recursive: true });

      await this.manifest.load();

      // Scan both trees
      const sourceTree = await this._scanDir(this.source);
      const destTree = await this._scanDir(this.dest);

      // Build action plan
      const actions =
        this.options.mode === "two-way"
          ? this._planTwoWay(sourceTree, destTree)
          : this._planOneWay(sourceTree, destTree);

      // Execute
      let current = 0;
      for (const action of actions) {
        current++;
        this.emit("progress", {
          current,
          total: actions.length,
          relativePath: action.relativePath,
        });

        try {
          if (!this.options.dryRun) {
            await this._executeAction(action);
          }
          result.actions.push(action);

          switch (action.type) {
            case "copy":
            case "mkdir":
              result.copied++;
              break;
            case "delete":
              result.deleted++;
              break;
            case "skip":
              result.skipped++;
              break;
            case "conflict-resolved":
              result.conflicts++;
              break;
          }

          this.emit("action", action);
        } catch (err) {
          result.errors++;
          result.errorDetails.push(err);
          this.emit("error", err, action.relativePath);
        }
      }

      // Persist manifest
      if (!this.options.dryRun) {
        await this.manifest.save();
      }
    } finally {
      result.durationMs = Date.now() - start;
      this._running = false;
      this.emit("complete", result);
    }

    return result;
  }

