namespace MigrationHelper.Models;

/// <summary>
/// Represents a single raw row parsed from a CSV file.
/// Values are keyed by column header.
/// </summary>
public class CsvRecord
{
    public int LineNumber { get; init; }
    public IReadOnlyDictionary<string, string> Fields { get; init; } = 
        new Dictionary<string, string>();

    public string GetField(string name)
    {
        return Fields.TryGetValue(name, out var value) ? value.Trim() : string.Empty;
    }

    public T GetField<T>(string name, Func<string, T> converter, T defaultValue = default!)
    {
        var raw = GetField(name);
        if (string.IsNullOrWhiteSpace(raw))
            return defaultValue;

        try
        {
            return converter(raw);
        }
        catch
        {
            return defaultValue;
        }
    }
}
