```csharp
// Parsing/CsvParser.cs
namespace MigrationHelper.Parsing;

using MigrationHelper.Models;

public class CsvParserOptions
{
    public char Delimiter { get; init; } = ',';
    public char QuoteChar { get; init; } = '"';
    public bool HasHeader { get; init; } = true;
    public bool TrimFields { get; init; } = true;
}

public class CsvParser : ICsvParser
{
    private readonly CsvParserOptions _options;

    public CsvParser(CsvParserOptions? options = null)
    {
        _options = options ?? new CsvParserOptions();
    }

    // --- Streaming async version for large files ---
    public async IAsyncEnumerable<CsvRecord> ParseAsync(
        string filePath,
        [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken ct = default)
    {
        using var reader = new StreamReader(filePath);
        string[] headers = Array.Empty<string>();
        int lineNumber = 0;

        while (await reader.ReadLineAsync(ct) is { } line)
        {
            lineNumber++;
            if (string.IsNullOrWhiteSpace(line))
                continue;

            var fields = ParseLine(line);

            if (lineNumber == 1 && _options.HasHeader)
            {
                headers = fields;
                continue;
            }

            yield return BuildRecord(headers, fields, lineNumber);
        }
    }

    // --- Synchronous version for testing / small data ---
    public IEnumerable<CsvRecord> Parse(TextReader reader)
    {
        string[] headers = Array.Empty<string>();
        int lineNumber = 0;

        string? line;
        while ((line = reader.ReadLine()) != null)
        {
            lineNumber++;
            if (string.IsNullOrWhiteSpace(line))
                continue;

            var fields = ParseLine(line);

            if (lineNumber == 1 && _options.HasHeader)
            {
                headers = fields;
                continue;
            }

            yield return BuildRecord(headers, fields, lineNumber);
        }
    }

    // --- RFC-4180-aware field splitting ---
    private string[] ParseLine(string line)
    {
        var fields = new List<string>();
        var current = new System.Text.StringBuilder();
        bool inQuotes = false;

        for (int i = 0; i < line.Length; i++)
        {
            char c = line[i];

            if (inQuotes)
            {
                if (c == _options.QuoteChar)
                {
                    // Escaped quote ("") inside a quoted field
                    if (i + 1 < line.Length && line[i + 1] == _options.QuoteChar)
                    {
                        current.Append(_options.QuoteChar);
                        i++; // skip next quote
                    }
                    else
                    {
                        inQuotes = false;
                    }
                }
                else
                {
                    current.Append(c);
                }
            }
            else if (c == _options.QuoteChar)
            {
                inQuotes = true;
            }
            else if (c == _options.Delimiter)
            {
                fields.Add(FinishField(current));
                current.Clear();
            }
            else
            {
                current.Append(c);
            }
        }

        fields.Add(FinishField(current));
        return fields.ToArray();
    }

    private string FinishField(System.Text.StringBuilder sb)
    {
        return _options.TrimFields ? sb.ToString().Trim() : sb.ToString();
    }

    private static CsvRecord BuildRecord(string[] headers, string[] fields, int lineNumber)
    {
        var dict = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        for (int i = 0; i < headers.Length && i < fields.Length; i++)
            dict[headers[i]] = fields[i];

        // Also allow index-based access ("0", "1", ...)
        for (int i = 0; i < fields.Length; i++)
            dict.TryAdd(i.ToString(), fields[i]);

        return new CsvRecord { LineNumber = lineNumber, Fields = dict };
    }
}
