// Migration/MigrationRunner.cs — orchestrator
namespace MigrationHelper.Migration;

using MigrationHelper.Mapping;
using MigrationHelper.Models;
using MigrationHelper.Parsing;
using MigrationHelper.Validation;
using System.Diagnostics;

public class MigrationRunnerOptions
{
    public int BatchSize { get; init; } = 100;
    public bool StopOnFirstError { get; init; } = false;
}

public class MigrationRunner<T>
{
    private readonly ICsvParser _parser;
    private readonly IRecordMapper<T> _mapper;
    private readonly IRecordValidator<T> _validator;
    private readonly IMigrationTarget<T> _target;
    private readonly MigrationRunnerOptions _options;

    public MigrationRunner(
        ICsvParser parser,
        IRecordMapper<T> mapper,
        IRecordValidator<T> validator,
        IMigrationTarget<T> target,
        MigrationRunnerOptions? options = null)
    {
        _parser    = parser;
        _mapper    = mapper;
        _validator = validator;
        _target    = target;
        _options   = options ?? new MigrationRunnerOptions();
    }

    public async Task<MigrationResult> RunAsync(
        string filePath, CancellationToken ct = default)
    {
        var result = new MigrationResult();
        var sw = Stopwatch.StartNew();
        var batch = new List<T>(_options.BatchSize);

        await _target.InitializeAsync(ct);

        await foreach (var record in _parser.ParseAsync(filePath, ct))
        {
            // 1. MAP
            T entity;
            try
            {
                entity = _mapper.Map(record);
            }
            catch (Exception ex)
            {
                result.Add(new RowResult(record.LineNumber,
                    RowStatus.MigrationFailed, $"Mapping error: {ex.Message}"));

                if (_options.StopOnFirstError) break;
                continue;
            }

            // 2. VALIDATE
            var (isValid, errors) = _validator.Validate(entity);
            if (!isValid)
            {
                result.Add(new RowResult(record.LineNumber,
                    RowStatus.ValidationFailed, string.Join("; ", errors)));

                if (_options.StopOnFirstError) break;
                continue;
            }

            // 3. BATCH
            batch.Add(entity);

            if (batch.Count >= _options.BatchSize)
            {
                await FlushBatchAsync(batch, result, ct);
                batch.Clear();
            }
        }

        // Flush remaining
        if (batch.Count > 0)
            await FlushBatchAsync(batch, result, ct);

        await _target.FinalizeAsync(ct);
        sw.Stop();
        result.Duration = sw.Elapsed;

        return result;
    }

    private async Task FlushBatchAsync(
        List<T> batch, MigrationResult result, CancellationToken ct)
    {
        try
        {
            await _target.InsertBatchAsync(batch, ct);

            // Mark all rows in batch as succeeded
            // (in production, track line numbers in the batch)
            for (int i = 0; i < batch.Count; i++)
                result.Add(new RowResult(0, RowStatus.Success));
        }
        catch (Exception ex)
        {
            for (int i = 0; i < batch.Count; i++)
                result.Add(new RowResult(0, RowStatus.MigrationFailed, ex.Message));
        }
    }
}
