### `src/RetryHandler.js` — Retry Logic with Exponential Backoff

```javascript
"use strict";

/**
 * @typedef {Object} RetryOptions
 * @property {number}   maxRetries       - Maximum retry attempts (default: 3)
 * @property {number}   baseDelayMs      - Initial delay in ms (default: 1000)
 * @property {number}   maxDelayMs       - Maximum delay cap in ms (default: 30000)
 * @property {number}   backoffFactor    - Multiplier per retry (default: 2)
 * @property {number}   jitterFactor     - Random jitter 0–1 (default: 0.1)
 * @property {Function} retryableCheck   - Predicate: (error) => boolean
 * @property {Function} onRetry          - Callback: (error, attempt, delayMs) => void
 */

class RetryHandler {
  /** @param {Partial<RetryOptions>} options */
  constructor(options = {}) {
    this.maxRetries = options.maxRetries ?? 3;
    this.baseDelayMs = options.baseDelayMs ?? 1000;
    this.maxDelayMs = options.maxDelayMs ?? 30000;
    this.backoffFactor = options.backoffFactor ?? 2;
    this.jitterFactor = options.jitterFactor ?? 0.1;
    this.retryableCheck = options.retryableCheck ?? RetryHandler.defaultRetryableCheck;
    this.onRetry = options.onRetry ?? (() => {});
    this._aborted = false;
  }

  /**
   * Default check: retry on transient filesystem / network errors.
   * @param {Error} error
   * @returns {boolean}
   */
  static defaultRetryableCheck(error) {
    const RETRYABLE_CODES = new Set([
      "EBUSY",     // resource busy
      "EMFILE",    // too many open files
      "ENFILE",    // file table overflow
      "ENOENT",    // race condition — file disappeared
      "EAGAIN",    // resource temporarily unavailable
      "EPERM",     // transient permission issue (e.g. antivirus lock)
      "EACCES",    // transient access issue
      "EIO",       // I/O error
      "ETIMEDOUT", // network timeout (remote mounts)
      "ECONNRESET",
      "ECONNREFUSED",
    ]);
    return RETRYABLE_CODES.has(error.code);
  }

  /**
   * Calculate delay for a given attempt using exponential backoff + jitter.
   * @param {number} attempt - Zero-based attempt index
   * @returns {number} Delay in milliseconds
   */
  calculateDelay(attempt) {
    const exponential = this.baseDelayMs * Math.pow(this.backoffFactor, attempt);
    const capped = Math.min(exponential, this.maxDelayMs);
    const jitter = capped * this.jitterFactor * Math.random();
    return Math.floor(capped + jitter);
  }

  /** Abort any in-flight retry waits. */
  abort() {
    this._aborted = true;
  }

  /**
   * Execute an async function with retries.
   * @template T
   * @param {() => Promise<T>} fn        - The operation to attempt
   * @param {string}           [context]  - Description for logging
   * @returns {Promise<T>}
   */
  async execute(fn, context = "operation") {
    let lastError;

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      if (this._aborted) {
        throw new RetryAbortedError(context, attempt, lastError);
      }

      try {
        return await fn();
      } catch (error) {
        lastError = error;

        const isLastAttempt = attempt === this.maxRetries;
        const isRetryable = this.retryableCheck(error);

        if (isLastAttempt || !isRetryable) {
          throw new RetryExhaustedError(context, attempt + 1, this.maxRetries + 1, error);
        }

        const delayMs = this.calculateDelay(attempt);
        this.onRetry(error, attempt + 1, delayMs);

        await this._sleep(delayMs);
      }
    }
  }

  /** @private */
  _sleep(ms) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, ms);
      // Allow abort to interrupt sleep
      const check = setInterval(() => {
        if (this._aborted) {
          clearTimeout(timer);
          clearInterval(check);
          reject(new RetryAbortedError("sleep", 0, null));
        }
      }, 100);
      // Clean up checker when timer fires normally
      setTimeout(() => clearInterval(check), ms + 50);
    });
  }
}

class RetryExhaustedError extends Error {
  constructor(context, attempts, maxAttempts, cause) {
    super(`${context}: failed after ${attempts}/${maxAttempts} attempts — ${cause.message}`);
    this.name = "RetryExhaustedError";
    this.code = "ERR_RETRY_EXHAUSTED";
    this.context = context;
    this.attempts = attempts;
    this.maxAttempts = maxAttempts;
    this.cause = cause;
  }
}

class RetryAbortedError extends Error {
  constructor(context, attempt, cause) {
    super(`${context}: retry aborted at attempt ${attempt}`);
    this.name = "RetryAbortedError";
    this.code = "ERR_RETRY_ABORTED";
    this.context = context;
    this.attempt = attempt;
    this.cause = cause;
  }
}

module.exports = { RetryHandler, RetryExhaustedError, RetryAbortedError };
