```javascript
"use strict";

class ConcurrencyLimiter {
  /** @param {number} limit - Maximum concurrent operations */
  constructor(limit = 5) {
    if (limit < 1) throw new RangeError("Concurrency limit must be >= 1");
    this.limit = limit;
    this._running = 0;
    this._queue = [];
  }

  /** @returns {number} Currently running operations */
  get running() {
    return this._running;
  }

  /** @returns {number} Queued operations waiting */
  get pending() {
    return this._queue.length;
  }

  /**
   * Run fn() with concurrency control.
   * @template T
   * @param {() => Promise<T>} fn
   * @returns {Promise<T>}
   */
  async run(fn) {
    // Wait until a slot is available
    if (this._running >= this.limit) {
      await new Promise((resolve) => this._queue.push(resolve));
    }

    this._running++;
    try {
      return await fn();
    } finally {
      this._running--;
      if (this._queue.length > 0) {
        const next = this._queue.shift();
        next();
      }
    }
  }

  /**
   * Map items through fn() with concurrency limiting.
   * @template T, R
   * @param {T[]}                    items
   * @param {(item: T) => Promise<R>} fn
   * @returns {Promise<PromiseSettledResult<R>[]>}
   */
  mapSettled(items, fn) {
    const tasks = items.map((item) => this.run(() => fn(item)));
    return Promise.allSettled(tasks);
  }
}

