### `src/FileComparer.js` — Checksum & Metadata Comparison

```javascript
"use strict";

const fs = require("fs/promises");
const crypto = require("crypto");
const { createReadStream } = require("fs");

/**
 * @typedef {'checksum'|'size-mtime'|'size-only'} CompareStrategy
 */

/**
 * @typedef {Object} FileFingerprint
 * @property {number}  size
 * @property {number}  mtimeMs
 * @property {string}  [checksum]
 */

class FileComparer {
  /**
   * @param {Object}          options
   * @param {CompareStrategy} [options.strategy='size-mtime']
   * @param {string}          [options.algorithm='sha256']
   * @param {number}          [options.checksumChunkSize=65536]
   */
  constructor(options = {}) {
    this.strategy = options.strategy ?? "size-mtime";
    this.algorithm = options.algorithm ?? "sha256";
    this.checksumChunkSize = options.checksumChunkSize ?? 65536;
  }

  /**
   * Compute a file's checksum using streaming.
   * @param {string} filePath
   * @returns {Promise<string>}
   */
  async computeChecksum(filePath) {
    return new Promise((resolve, reject) => {
      const hash = crypto.createHash(this.algorithm);
      const stream = createReadStream(filePath, {
        highWaterMark: this.checksumChunkSize,
      });

      stream.on("data", (chunk) => hash.update(chunk));
      stream.on("end", () => resolve(hash.digest("hex")));
      stream.on("error", reject);
    });
  }

  /**
   * Get fingerprint for a file path.
   * @param {string} filePath
   * @returns {Promise<FileFingerprint>}
   */
  async getFingerprint(filePath) {
    const stat = await fs.stat(filePath);
    const fp = { size: stat.size, mtimeMs: stat.mtimeMs };

    if (this.strategy === "checksum") {
      fp.checksum = await this.computeChecksum(filePath);
    }

    return fp;
  }

  /**
   * Determine if two files differ.
   * @param {string} srcPath
   * @param {string} destPath
   * @returns {Promise<boolean>} True if files are different
   */
  async filesAreDifferent(srcPath, destPath) {
    let destStat;
    try {
      destStat = await fs.stat(destPath);
    } catch (err) {
      if (err.code === "ENOENT") return true; // dest doesn't exist
      throw err;
    }

    const srcStat = await fs.stat(srcPath);

    // Quick reject: different sizes always means different
    if (srcStat.size !== destStat.size) return true;

    switch (this.strategy) {
      case "size-only":
        return false; // sizes match, consider same

      case "size-mtime":
        // Allow 2-second tolerance for FAT32 / network fs
        return Math.abs(srcStat.mtimeMs - destStat.mtimeMs) > 2000;

      case "checksum": {
        const [srcHash, destHash] = await Promise.all([
          this.computeChecksum(srcPath),
          this.computeChecksum(destPath),
        ]);
        return srcHash !== destHash;
      }

      default:
        throw new Error(`Unknown compare strategy: ${this.strategy}`);
    }
  }
}

module.exports = { FileComparer };
```

### `src/SyncReport.js` — Tracks Results

```javascript
"use strict";

class SyncReport {
  constructor() {
    this.startTime = Date.now();
    this.endTime = null;
    this.copied = [];
    this.deleted = [];
    this.skipped = [];
    this.failed = [];
    this.directoriesCreated = [];
    this.totalBytes = 0;
  }

  recordCopy(src, dest, bytes) {
    this.copied.push({ src, dest, bytes, timestamp: Date.now() });
    this.totalBytes += bytes;
  }

  recordDelete(filePath) {
    this.deleted.push({ path: filePath, timestamp: Date.now() });
  }

  recordSkip(src, reason) {
    this.skipped.push({ src, reason, timestamp: Date.now() });
  }

  recordFailure(src, error) {
    this.failed.push({
      src,
      error: error.message,
      code: error.code,
      attempts: error.attempts,
      timestamp: Date.now(),
    });
  }

  recordDirectoryCreated(dirPath) {
    this.directoriesCreated.push({ path: dirPath, timestamp: Date.now() });
  }

  finalize() {
    this.endTime = Date.now();
    return this;
  }

  get durationMs() {
    return (this.endTime ?? Date.now()) - this.startTime;
  }

  get summary() {
    return {
      durationMs: this.durationMs,
      copied: this.copied.length,
      deleted: this.deleted.length,
      skipped: this.skipped.length,
      failed: this.failed.length,
      directoriesCreated: this.directoriesCreated.length,
      totalBytesCopied: this.totalBytes,
    };
  }

  toJSON() {
    return {
      ...this.summary,
      details: {
        copied: this.copied,
        deleted: this.deleted,
        skipped: this.skipped,
        failed: this.failed,
        directoriesCreated: this.directoriesCreated,
      },
    };
  }
}

