```javascript
"use strict";

const LOG_LEVELS = { debug: 0, info: 1, warn: 2, error: 3, silent: 4 };

class Logger {
  /**
   * @param {Object}  options
   * @param {string}  [options.level='info']
   * @param {boolean} [options.json=false]
   * @param {string}  [options.prefix='[FileSync]']
   */
  constructor(options = {}) {
    this.level = LOG_LEVELS[options.level ?? "info"] ?? LOG_LEVELS.info;
    this.json = options.json ?? false;
    this.prefix = options.prefix ?? "[FileSync]";
  }

  _log(level, message, meta = {}) {
    if (LOG_LEVELS[level] < this.level) return;

    if (this.json) {
      const entry = {
        timestamp: new Date().toISOString(),
        level,
        message,
        ...meta,
      };
      const stream = level === "error" ? process.stderr : process.stdout;
      stream.write(JSON.stringify(entry) + "\n");
    } else {
      const ts = new Date().toISOString();
      const tag = level.toUpperCase().padEnd(5);
      const metaStr = Object.keys(meta).length
        ? " " + JSON.stringify(meta)
        : "";
      const stream = level === "error" ? process.stderr : process.stdout;
      stream.write(`${ts} ${tag} ${this.prefix} ${message}${metaStr}\n`);
    }
  }

  debug(msg, meta) { this._log("debug", msg, meta); }
  info(msg, meta)  { this._log("info", msg, meta); }
  warn(msg, meta)  { this._log("warn", msg, meta); }
  error(msg, meta) { this._log("error", msg, meta); }
}

module.exports = { Logger, LOG_LEVELS };
