## Task Registry — Pattern-Based Routing

```java
// TaskRegistry.java
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.regex.Pattern;

public class TaskRegistry {

    private final List<TaskBinding> bindings = new CopyOnWriteArrayList<>();

    /**
     * Register a task for files matching a glob pattern.
     * Examples: "*.csv", "config-*.json", "**​/logs/*.log"
     */
    public TaskRegistry on(String globPattern, FileEvent.EventType eventType, WatchTask task) {
        String regex = globToRegex(globPattern);
        bindings.add(new TaskBinding(Pattern.compile(regex), eventType, task));
        return this;
    }

    // Convenience: trigger on any event type
    public TaskRegistry onAny(String globPattern, WatchTask task) {
        for (FileEvent.EventType type : FileEvent.EventType.values()) {
            on(globPattern, type, task);
        }
        return this;
    }

    public TaskRegistry onCreated(String globPattern, WatchTask task) {
        return on(globPattern, FileEvent.EventType.CREATED, task);
    }

    public TaskRegistry onModified(String globPattern, WatchTask task) {
        return on(globPattern, FileEvent.EventType.MODIFIED, task);
    }

    public TaskRegistry onDeleted(String globPattern, WatchTask task) {
        return on(globPattern, FileEvent.EventType.DELETED, task);
    }

    /**
     * Find all tasks that match a given file event.
     */
    public List<WatchTask> match(FileEvent event) {
        List<WatchTask> matched = new ArrayList<>();
        for (TaskBinding binding : bindings) {
            if (binding.eventType == event.type()
                    && binding.pattern.matcher(event.fileName()).matches()) {
                matched.add(binding.task);
            }
        }
        return matched;
    }

    private static String globToRegex(String glob) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < glob.length(); i++) {
            char c = glob.charAt(i);
            switch (c) {
                case '*' -> sb.append(".*");
                case '?' -> sb.append('.');
                case '.' -> sb.append("\\.");
                default  -> sb.append(c);
            }
        }
        return sb.toString();
    }

    private record TaskBinding(Pattern pattern, FileEvent.EventType eventType, WatchTask task) {}
}
