## Debounced Watch Service — Solves the Duplicate Event Problem

```java
// DebouncedWatchService.java
import java.nio.file.*;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import static java.nio.file.StandardWatchEventKinds.*;

/**
 * Wraps Java's WatchService and deduplicates events.
 * The OS often fires MODIFY twice for a single save — this fixes that.
 */
public class DebouncedWatchService implements AutoCloseable {

    private final WatchService watchService;
    private final Map<String, Instant> lastSeen = new ConcurrentHashMap<>();
    private final long debounceMillis;

    public DebouncedWatchService(Path directory, long debounceMillis) throws Exception {
        this.debounceMillis = debounceMillis;
        this.watchService = directory.getFileSystem().newWatchService();
        directory.register(watchService, ENTRY_CREATE, ENTRY_MODIFY, ENTRY_DELETE);
    }

    /**
     * Blocks until a genuine (non-duplicate) event occurs.
     * Returns null if interrupted.
     */
    public FileEvent poll() {
        while (true) {
            WatchKey key;
            try {
                key = watchService.take(); // blocks
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return null;
            }

            for (WatchEvent<?> raw : key.pollEvents()) {
                if (raw.kind() == OVERFLOW) continue;

                @SuppressWarnings("unchecked")
                WatchEvent<Path> event = (WatchEvent<Path>) raw;
                Path fileName = event.context();
                FileEvent.EventType type = mapType(raw.kind());

                // Debounce: skip if we saw the same file+type recently
                String dedupeKey = fileName + ":" + type;
                Instant now = Instant.now();
                Instant last = lastSeen.get(dedupeKey);

                if (last != null && now.toEpochMilli() - last.toEpochMilli() < debounceMillis) {
                    continue; // duplicate, skip
                }
                lastSeen.put(dedupeKey, now);

                key.reset();
                return new FileEvent(fileName, type, now);
            }

            if (!key.reset()) break; // directory no longer accessible
        }
        return null;
    }

    private FileEvent.EventType mapType(WatchEvent.Kind<?> kind) {
        if (kind == ENTRY_CREATE) return FileEvent.EventType.CREATED;
        if (kind == ENTRY_DELETE) return FileEvent.EventType.DELETED;
        return FileEvent.EventType.MODIFIED;
    }

    @Override
    public void close() throws Exception {
        watchService.close();
    }
}
