## Main Scheduler — Ties It All Together

```java
// FileWatcherScheduler.java
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.*;

public class FileWatcherScheduler implements AutoCloseable {

    private final Path watchDir;
    private final TaskRegistry registry;
    private final ExecutorService taskExecutor;
    private final long debounceMillis;

    private volatile boolean running;
    private Thread watcherThread;

    // Tracks scheduled/delayed tasks so they can be cancelled
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private final ConcurrentHashMap<String, ScheduledFuture<?>> delayedTasks = new ConcurrentHashMap<>();

    private FileWatcherScheduler(Builder builder) {
        this.watchDir = builder.watchDir;
        this.registry = builder.registry;
        this.debounceMillis = builder.debounceMillis;
        this.taskExecutor = Executors.newFixedThreadPool(
            builder.threadPoolSize,
            r -> {
                Thread t = new Thread(r, "task-worker");
                t.setDaemon(true);
                return t;
            }
        );
    }

    /**
     * Start watching. Non-blocking — spawns a daemon thread.
     */
    public void start() {
        running = true;
        watcherThread = new Thread(this::watchLoop, "file-watcher");
        watcherThread.setDaemon(true);
        watcherThread.start();
        System.out.printf("[watcher] Monitoring: %s%n", watchDir.toAbsolutePath());
    }

    /**
     * Schedule a delayed task tied to a key.
     * If called again with the same key before it fires, the old one is cancelled.
     * Useful for "wait until file stops changing, then process."
     */
    public void scheduleDebounced(String key, Runnable task, long delayMs) {
        ScheduledFuture<?> existing = delayedTasks.get(key);
        if (existing != null) {
            existing.cancel(false);
        }
        ScheduledFuture<?> future = scheduler.schedule(() -> {
            delayedTasks.remove(key);
            task.run();
        }, delayMs, TimeUnit.MILLISECONDS);
        delayedTasks.put(key, future);
    }

    private void watchLoop() {
        try (var watcher = new DebouncedWatchService(watchDir, debounceMillis)) {
            while (running) {
                FileEvent event = watcher.poll();
                if (event == null) continue;

                // Resolve to full path
                Path fullPath = watchDir.resolve(event.filePath());
                FileEvent resolved = new FileEvent(fullPath, event.type(), event.timestamp());

                List<WatchTask> tasks = registry.match(event);

                if (tasks.isEmpty()) {
                    System.out.printf("[watcher] No handler for: %s (%s)%n", event.fileName(), event.type());
                    continue;
                }

                System.out.printf("[watcher] %s %s → %d task(s)%n",
                        event.type(), event.fileName(), tasks.size());

                for (WatchTask task : tasks) {
                    taskExecutor.submit(() -> {
                        try {
                            task.execute(resolved);
                        } catch (Exception e) {
                            System.err.printf("[error] Task failed for %s: %s%n",
                                    resolved.fileName(), e.getMessage());
                        }
                    });
                }
            }
        } catch (Exception e) {
            if (running) {
                System.err.println("[watcher] Fatal error: " + e.getMessage());
            }
        }
    }

    @Override
    public void close() {
        running = false;
        if (watcherThread != null) watcherThread.interrupt();
        taskExecutor.shutdown();
        scheduler.shutdown();
    }

    // --- Builder ---

    public static Builder builder(Path watchDir) {
        return new Builder(watchDir);
    }

    public static class Builder {
        private final Path watchDir;
        private final TaskRegistry registry = new TaskRegistry();
        private int threadPoolSize = 4;
        private long debounceMillis = 200;

        Builder(Path watchDir) {
            this.watchDir = watchDir;
        }

        public Builder threads(int n) {
            this.threadPoolSize = n;
            return this;
        }

        public Builder debounce(long millis) {
            this.debounceMillis = millis;
            return this;
        }

        public Builder onCreated(String pattern, WatchTask task) {
            registry.onCreated(pattern, task);
            return this;
        }

        public Builder onModified(String pattern, WatchTask task) {
            registry.onModified(pattern, task);
            return this;
        }

        public Builder onDeleted(String pattern, WatchTask task) {
            registry.onDeleted(pattern, task);
            return this;
        }

        public Builder onAny(String pattern, WatchTask task) {
            registry.onAny(pattern, task);
            return this;
        }

        public FileWatcherScheduler build() {
            return new FileWatcherScheduler(this);
        }
    }
}
