import pino from 'pino';

/**
 * Structured logger factory with child-logger support
 * and redaction of sensitive fields.
 */
export class Logger {
  /** @type {Map<string, pino.Logger>} */
  static #instances = new Map();

  /**
   * @param {string} name
   * @param {object} [options]
   * @returns {pino.Logger}
   */
  static create(name, options = {}) {
    if (Logger.#instances.has(name)) {
      return Logger.#instances.get(name);
    }

    const logger = pino({
      name,
      level: process.env.LOG_LEVEL || 'info',
      timestamp: pino.stdTimeFunctions.isoTime,
      redact: {
        paths: ['password', 'token', 'secret', 'authorization', '*.password'],
        censor: '[REDACTED]',
      },
      serializers: {
        err: pino.stdSerializers.err,
        error: pino.stdSerializers.err,
      },
      formatters: {
        level(label) {
          return { level: label };
        },
      },
      ...options,
    });

    Logger.#instances.set(name, logger);
    return logger;
  }

  static shutdown() {
    for (const logger of Logger.#instances.values()) {
      logger.flush();
    }
    Logger.#instances.clear();
  }
}
