import { Logger } from './Logger.js';
import { EventEmitter } from 'node:events';

/**
 * Lightweight in-process metrics collector.
 * Tracks counters, gauges, histograms per pipeline stage.
 */
export class Metrics extends EventEmitter {
  #counters = new Map();
  #gauges = new Map();
  #histograms = new Map();
  #startTime = Date.now();
  #reportInterval = null;
  #logger;

  /**
   * @param {object} options
   * @param {boolean} [options.enabled=true]
   * @param {number}  [options.reportIntervalMs=10000]
   */
  constructor(options = {}) {
    super();
    this.#logger = Logger.create('metrics');
    const { enabled = true, reportIntervalMs = 10_000 } = options;

    if (enabled && reportIntervalMs > 0) {
      this.#reportInterval = setInterval(() => this.report(), reportIntervalMs);
      this.#reportInterval.unref(); // don't keep process alive
    }
  }

  /** Increment a named counter */
  increment(name, value = 1) {
    const current = this.#counters.get(name) || 0;
    this.#counters.set(name, current + value);
  }

  /** Set a gauge value */
  gauge(name, value) {
    this.#gauges.set(name, value);
  }

  /** Record a histogram observation (e.g., latency) */
  observe(name, value) {
    if (!this.#histograms.has(name)) {
      this.#histograms.set(name, []);
    }
    const observations = this.#histograms.get(name);
    observations.push(value);

    // Keep bounded memory – retain last 10 000 observations
    if (observations.length > 10_000) {
      observations.splice(0, observations.length - 10_000);
    }
  }

  /** Return a snapshot of all metrics */
  snapshot() {
    const histogramStats = {};
    for (const [name, values] of this.#histograms) {
      histogramStats[name] = this.#computeStats(values);
    }

    return {
      uptime_ms: Date.now() - this.#startTime,
      counters: Object.fromEntries(this.#counters),
      gauges: Object.fromEntries(this.#gauges),
      histograms: histogramStats,
    };
  }

  /** Log current metrics */
  report() {
    const snap = this.snapshot();
    this.#logger.info({ metrics: snap }, 'Metrics report');
    this.emit('report', snap);
  }

  /** @param {number[]} values */
  #computeStats(values) {
    if (values.length === 0) return { count: 0 };
    const sorted = [...values].sort((a, b) => a - b);
    const sum = sorted.reduce((s, v) => s + v, 0);
    return {
      count: sorted.length,
      min: sorted[0],
      max: sorted[sorted.length - 1],
      mean: +(sum / sorted.length).toFixed(3),
      p50: sorted[Math.floor(sorted.length * 0.5)],
      p95: sorted[Math.floor(sorted.length * 0.95)],
      p99: sorted[Math.floor(sorted.length * 0.99)],
    };
  }

  destroy() {
    if (this.#reportInterval) {
      clearInterval(this.#reportInterval);
      this.#reportInterval = null;
    }
    this.removeAllListeners();
  }
}
