import Ajv from 'ajv';

/**
 * JSON Schema validator wrapping Ajv with caching.
 */
export class Validator {
  #ajv;
  /** @type {Map<string, import('ajv').ValidateFunction>} */
  #compiled = new Map();

  constructor() {
    this.#ajv = new Ajv({
      allErrors: true,
      coerceTypes: false,
      removeAdditional: false,
      useDefaults: true,
    });
  }

  /**
   * Validate data against a named schema.
   * @param {string} schemaId
   * @param {object} schema   - JSON Schema object
   * @param {unknown} data
   * @returns {{ valid: boolean, errors: string[] }}
   */
  validate(schemaId, schema, data) {
    let validateFn = this.#compiled.get(schemaId);
    if (!validateFn) {
      validateFn = this.#ajv.compile(schema);
      this.#compiled.set(schemaId, validateFn);
    }

    const valid = validateFn(data);
    return {
      valid: !!valid,
      errors: valid
        ? []
        : validateFn.errors.map(
            (e) => `${e.instancePath || '/'} ${e.message}`
          ),
    };
  }
}
