```javascript
import { Logger } from './Logger.js';

/**
 * Circuit breaker for protecting downstream calls
 * in sink stages (HTTP endpoints, databases, etc.).
 *
 * States: CLOSED → OPEN → HALF_OPEN → CLOSED
 */
export class CircuitBreaker {
  static State = Object.freeze({
    CLOSED: 'CLOSED',
    OPEN: 'OPEN',
    HALF_OPEN: 'HALF_OPEN',
  });

  #state = CircuitBreaker.State.CLOSED;
  #failureCount = 0;
  #successCount = 0;
  #lastFailureTime = 0;
  #logger;

  #failureThreshold;
  #recoveryTimeMs;
  #halfOpenMaxAttempts;

  /**
   * @param {object} options
   * @param {number} [options.failureThreshold=5]
   * @param {number} [options.recoveryTimeMs=30000]
   * @param {number} [options.halfOpenMaxAttempts=3]
   */
  constructor(options = {}) {
    this.#failureThreshold = options.failureThreshold ?? 5;
    this.#recoveryTimeMs = options.recoveryTimeMs ?? 30_000;
    this.#halfOpenMaxAttempts = options.halfOpenMaxAttempts ?? 3;
    this.#logger = Logger.create('circuit-breaker');
  }

  get state() {
    return this.#state;
  }

  /**
   * Execute a function through the circuit breaker.
   * @template T
   * @param {() => Promise<T>} fn
   * @returns {Promise<T>}
   */
  async execute(fn) {
    if (this.#state === CircuitBreaker.State.OPEN) {
      if (Date.now() - this.#lastFailureTime >= this.#recoveryTimeMs) {
        this.#transitionTo(CircuitBreaker.State.HALF_OPEN);
      } else {
        throw new CircuitBreakerOpenError(
          `Circuit breaker is OPEN. Retry after ${this.#recoveryTimeMs}ms.`
        );
      }
    }

    try {
      const result = await fn();
      this.#onSuccess();
      return result;
    } catch (error) {
      this.#onFailure();
      throw error;
    }
  }

  #onSuccess() {
    if (this.#state === CircuitBreaker.State.HALF_OPEN) {
      this.#successCount++;
      if (this.#successCount >= this.#halfOpenMaxAttempts) {
        this.#transitionTo(CircuitBreaker.State.CLOSED);
      }
    }
    this.#failureCount = 0;
  }

  #onFailure() {
    this.#failureCount++;
    this.#lastFailureTime = Date.now();

    if (this.#failureCount >= this.#failureThreshold) {
      this.#transitionTo(CircuitBreaker.State.OPEN);
    }
  }

  #transitionTo(newState) {
    this.#logger.warn(
      { from: this.#state, to: newState },
      'Circuit breaker state transition'
    );
    this.#state = newState;
    if (newState === CircuitBreaker.State.CLOSED) {
      this.#failureCount = 0;
      this.#successCount = 0;
    }
    if (newState === CircuitBreaker.State.HALF_OPEN) {
      this.#successCount = 0;
    }
  }

  reset() {
    this.#transitionTo(CircuitBreaker.State.CLOSED);
  }
}

export class CircuitBreakerOpenError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CircuitBreakerOpenError';
  }
}
