import { EventEmitter } from 'node:events';
import { Logger } from './Logger.js';

/**
 * Manages backpressure between pipeline stages by
 * tracking queue depth and pausing/resuming upstream.
 */
export class BackpressureManager extends EventEmitter {
  #highWaterMark;
  #lowWaterMark;
  #currentSize = 0;
  #paused = false;
  #logger;

  /**
   * @param {object} options
   * @param {number} [options.highWaterMark=10000]
   * @param {number} [options.lowWaterMark]       – defaults to 25% of highWaterMark
   */
  constructor(options = {}) {
    super();
    this.#highWaterMark = options.highWaterMark ?? 10_000;
    this.#lowWaterMark = options.lowWaterMark ?? Math.floor(this.#highWaterMark * 0.25);
    this.#logger = Logger.create('backpressure');
  }

  get paused() {
    return this.#paused;
  }

  get currentSize() {
    return this.#currentSize;
  }

  /**
   * Track items entering the buffer.
   * @param {number} count
   * @returns {boolean} whether the caller should pause
   */
  acquire(count = 1) {
    this.#currentSize += count;

    if (!this.#paused && this.#currentSize >= this.#highWaterMark) {
      this.#paused = true;
      this.#logger.warn(
        { size: this.#currentSize, highWaterMark: this.#highWaterMark },
        'Backpressure: pausing upstream'
      );
      this.emit('pause');
    }

    return this.#paused;
  }

  /**
   * Track items leaving the buffer.
   * @param {number} count
   */
  release(count = 1) {
    this.#currentSize = Math.max(0, this.#currentSize - count);

    if (this.#paused && this.#currentSize <= this.#lowWaterMark) {
      this.#paused = false;
      this.#logger.info(
        { size: this.#currentSize, lowWaterMark: this.#lowWaterMark },
        'Backpressure: resuming upstream'
      );
      this.emit('resume');
    }
  }

  reset() {
    this.#currentSize = 0;
    this.#paused = false;
  }
}
