import java.time.Duration;
import java.time.Instant;
import java.util.*;
import java.util.function.Function;

// ─── Retry Configuration ────────────────────────────────────────────
class RetryConfig {
    private final int maxRetries;
    private final long initialDelayMs;
    private final double backoffMultiplier;
    private final Set<Class<? extends Exception>> retryableExceptions;

    private RetryConfig(Builder builder) {
        this.maxRetries = builder.maxRetries;
        this.initialDelayMs = builder.initialDelayMs;
        this.backoffMultiplier = builder.backoffMultiplier;
        this.retryableExceptions = builder.retryableExceptions;
    }

    public int getMaxRetries()                          { return maxRetries; }
    public long getInitialDelayMs()                     { return initialDelayMs; }
    public double getBackoffMultiplier()                { return backoffMultiplier; }
    public Set<Class<? extends Exception>> getRetryableExceptions() {
        return retryableExceptions;
    }

    public boolean isRetryable(Exception e) {
        if (retryableExceptions.isEmpty()) return true;  // retry all if none specified
        return retryableExceptions.stream()
                .anyMatch(cls -> cls.isInstance(e));
    }

    static class Builder {
        private int maxRetries = 3;
        private long initialDelayMs = 1000;
        private double backoffMultiplier = 2.0;
        private Set<Class<? extends Exception>> retryableExceptions = new HashSet<>();

        public Builder maxRetries(int n)              { this.maxRetries = n; return this; }
        public Builder initialDelayMs(long ms)        { this.initialDelayMs = ms; return this; }
        public Builder backoffMultiplier(double m)    { this.backoffMultiplier = m; return this; }
        public Builder retryOn(Class<? extends Exception> ex) {
            this.retryableExceptions.add(ex);
            return this;
        }
        public RetryConfig build() { return new RetryConfig(this); }
    }
}

// ─── Pipeline Stage Interface ───────────────────────────────────────
@FunctionalInterface
interface PipelineStage<I, O> {
    O process(I input) throws Exception;
}

// ─── Retry Execution Result ─────────────────────────────────────────
class StageResult<T> {
    private final T data;
    private final String stageName;
    private final int attemptsUsed;
    private final Duration duration;

    StageResult(T data, String stageName, int attemptsUsed, Duration duration) {
        this.data = data;
        this.stageName = stageName;
        this.attemptsUsed = attemptsUsed;
        this.duration = duration;
    }

    public T getData()           { return data; }
    public String getStageName() { return stageName; }
    public int getAttemptsUsed() { return attemptsUsed; }
    public Duration getDuration(){ return duration; }

    @Override
    public String toString() {
        return String.format("[%s] completed in %dms (%d attempt(s))",
                stageName, duration.toMillis(), attemptsUsed);
    }
}

// ─── Retry Executor ─────────────────────────────────────────────────
class RetryExecutor {

    public static <I, O> StageResult<O> execute(
            String stageName,
            PipelineStage<I, O> stage,
            I input,
            RetryConfig config) throws Exception {

        Instant start = Instant.now();
        Exception lastException = null;
        long delay = config.getInitialDelayMs();

        for (int attempt = 1; attempt <= config.getMaxRetries() + 1; attempt++) {
            try {
                O result = stage.process(input);
                Duration elapsed = Duration.between(start, Instant.now());
                return new StageResult<>(result, stageName, attempt, elapsed);

            } catch (Exception e) {
                lastException = e;
                boolean isLastAttempt = (attempt == config.getMaxRetries() + 1);

                if (isLastAttempt || !config.isRetryable(e)) {
                    System.err.printf("  ✗ [%s] FAILED on attempt %d: %s%n",
                            stageName, attempt, e.getMessage());
                    throw new PipelineException(stageName, attempt, e);
                }

                System.out.printf("  ⟳ [%s] attempt %d failed (%s), retrying in %dms...%n",
                        stageName, attempt, e.getMessage(), delay);

                Thread.sleep(delay);
                delay = (long) (delay * config.getBackoffMultiplier());
            }
        }

        throw new PipelineException(stageName, config.getMaxRetries() + 1, lastException);
    }
}

// ─── Custom Exception ───────────────────────────────────────────────
class PipelineException extends Exception {
    private final String stageName;
    private final int attempts;

    PipelineException(String stageName, int attempts, Throwable cause) {
        super(String.format("Stage '%s' failed after %d attempt(s)", stageName, attempts), cause);
        this.stageName = stageName;
        this.attempts = attempts;
    }

    public String getStageName() { return stageName; }
    public int getAttempts()     { return attempts; }
}

// ─── Analytics Pipeline ─────────────────────────────────────────────
class AnalyticsPipeline {

    private final RetryConfig defaultRetryConfig;
    private final List<StageResult<?>> results = new ArrayList<>();

    public AnalyticsPipeline(RetryConfig defaultRetryConfig) {
        this.defaultRetryConfig = defaultRetryConfig;
    }

    /** Run a stage with the default retry config */
    public <I, O> O runStage(String name, PipelineStage<I, O> stage, I input)
            throws Exception {
        return runStage(name, stage, input, defaultRetryConfig);
    }

    /** Run a stage with a custom retry config */
    public <I, O> O runStage(String name, PipelineStage<I, O> stage, I input,
                             RetryConfig config) throws Exception {
        StageResult<O> result = RetryExecutor.execute(name, stage, input, config);
        results.add(result);
        System.out.println("  ✓ " + result);
        return result.getData();
    }

    public void printSummary() {
        System.out.println("\n══════════ Pipeline Summary ══════════");
        long totalMs = 0;
        for (StageResult<?> r : results) {
            System.out.printf("  %-20s  %5dms  %d attempt(s)%n",
                    r.getStageName(), r.getDuration().toMillis(), r.getAttemptsUsed());
            totalMs += r.getDuration().toMillis();
        }
        System.out.printf("  %-20s  %5dms%n", "TOTAL", totalMs);
        System.out.println("══════════════════════════════════════\n");
    }
}

