    static int transformCallCount = 0;

    public static void main(String[] args) {

        // -- Configure retry policy ------------------------------------------
        RetryConfig retryConfig = new RetryConfig.Builder()
                .maxRetries(3)
                .initialDelayMs(500)
                .backoffMultiplier(2.0)
                .retryOn(TransientDataException.class)
                .retryOn(java.io.IOException.class)
                .build();

        AnalyticsPipeline pipeline = new AnalyticsPipeline(retryConfig);

        try {
            System.out.println("▶ Starting analytics pipeline...\n");

            // STAGE 1 — Extract (fails twice, succeeds on 3rd attempt)
            List<Map<String, Object>> rawData = pipeline.runStage(
                "Extract",
                (Void v) -> {
                    extractCallCount++;
                    if (extractCallCount <= 2) {
                        throw new TransientDataException(
                            "Connection timeout (attempt " + extractCallCount + ")");
                    }
                    // Simulate fetched rows
                    List<Map<String, Object>> rows = new ArrayList<>();
                    rows.add(Map.of("user", "alice", "event", "click",   "value", 10));
                    rows.add(Map.of("user", "bob",   "event", "purchase","value", 250));
                    rows.add(Map.of("user", "carol", "event", "click",   "value", 15));
                    rows.add(Map.of("user", "alice", "event", "purchase","value", 80));
                    return rows;
                },
                null
            );

            // STAGE 2 — Transform / Aggregate (fails once)
            Map<String, Integer> aggregated = pipeline.runStage(
                "Transform",
                (List<Map<String, Object>> rows) -> {
                    transformCallCount++;
                    if (transformCallCount <= 1) {
                        throw new TransientDataException("Temporary parse error");
                    }
                    // Sum values per user
                    Map<String, Integer> totals = new LinkedHashMap<>();
                    for (Map<String, Object> row : rows) {
                        String user = (String) row.get("user");
                        int val = (int) row.get("value");
                        totals.merge(user, val, Integer::sum);
                    }
                    return totals;
                },
                rawData
            );

            // STAGE 3 — Load (succeeds immediately)
            String report = pipeline.runStage(
                "Load",
                (Map<String, Integer> data) -> {
                    StringBuilder sb = new StringBuilder("Analytics Report:\n");
                    data.forEach((user, total) ->
                        sb.append(String.format("  %-10s → $%d%n", user, total)));
                    return sb.toString();
                },
                aggregated
            );

            // -- Output -------------------------------------------------------
            System.out.println("\n" + report);
            pipeline.printSummary();

        } catch (PipelineException e) {
            System.err.println("\n✗ Pipeline aborted: " + e.getMessage());
            System.err.println("  Root cause: " + e.getCause().getMessage());
            pipeline.printSummary();

        } catch (Exception e) {
            System.err.println("Unexpected error: " + e.getMessage());
        }
    }
}
