```kotlin
import java.util.concurrent.LinkedBlockingQueue
import java.util.concurrent.atomic.AtomicBoolean
import java.time.Instant

data class Task(
    val id: String,
    val name: String,
    val payload: String,
    val createdAt: Instant = Instant.now()
)

enum class TaskStatus {
    PENDING, PROCESSING, COMPLETED, FAILED
}

data class TaskResult(
    val task: Task,
    val status: TaskStatus,
    val message: String
)

class TaskQueue {
    private val queue = LinkedBlockingQueue<Task>()
    private val running = AtomicBoolean(false)
    private val results = mutableListOf<TaskResult>()

    fun enqueue(task: Task) {
        queue.put(task)
        println("[ENQUEUED] Task '${task.name}' (id=${task.id}), queue size: ${queue.size}")
    }

    fun startConsumer(workerName: String = "Worker-1", handler: (Task) -> String) {
        if (running.getAndSet(true)) {
            println("Consumer is already running.")
            return
        }

        val thread = Thread({
            println("[$workerName] Consumer started. Waiting for tasks...")
            while (running.get()) {
                try {
                    val task = queue.poll(1, java.util.concurrent.TimeUnit.SECONDS)
                    if (task != null) {
                        println("[$workerName] Processing task '${task.name}' (id=${task.id})...")
                        try {
                            val resultMsg = handler(task)
                            val result = TaskResult(task, TaskStatus.COMPLETED, resultMsg)
                            synchronized(results) { results.add(result) }
                            println("[$workerName] Task '${task.name}' COMPLETED: $resultMsg")
                        } catch (e: Exception) {
                            val result = TaskResult(task, TaskStatus.FAILED, e.message ?: "Unknown error")
                            synchronized(results) { results.add(result) }
                            println("[$workerName] Task '${task.name}' FAILED: ${e.message}")
                        }
                    }
                } catch (e: InterruptedException) {
                    Thread.currentThread().interrupt()
                    break
                }
            }
            println("[$workerName] Consumer stopped.")
        }, workerName)

        thread.isDaemon = true
        thread.start()
    }

    fun stop() {
        running.set(false)
        println("[QUEUE] Stop signal sent.")
    }

    fun pendingCount(): Int = queue.size

    fun getResults(): List<TaskResult> = synchronized(results) { results.toList() }
}

// --- Demo ---

fun main() {
    val taskQueue = TaskQueue()

    // Define a simple task handler that simulates work
    val handler: (Task) -> String = { task ->
        val sleepMs = (200L..800L).random()
        Thread.sleep(sleepMs)

        if (task.payload.contains("fail", ignoreCase = true)) {
            throw RuntimeException("Simulated failure for '${task.name}'")
        }

        "Processed '${task.payload}' in ${sleepMs}ms"
    }

    // Start the consumer
    taskQueue.startConsumer("Worker-1", handler)

    // Enqueue some tasks
    val tasks = listOf(
        Task("1", "send-email", "user@example.com welcome email"),
        Task("2", "resize-image", "thumbnail 128x128"),
        Task("3", "generate-report", "monthly sales Q4"),
        Task("4", "bad-task", "this will fail"),
        Task("5", "cleanup", "temp files older than 7d")
    )

    for (task in tasks) {
        taskQueue.enqueue(task)
        Thread.sleep(100) // slight delay between enqueues
    }

    // Wait for processing to finish
    println("\nWaiting for tasks to complete...")
    while (taskQueue.pendingCount() > 0 || taskQueue.getResults().size < tasks.size) {
        Thread.sleep(500)
    }

    // Give last task a moment to log
    Thread.sleep(200)

    // Print summary
    taskQueue.stop()
    Thread.sleep(300)

    println("\n===== RESULTS =====")
    for (result in taskQueue.getResults()) {
        val icon = if (result.status == TaskStatus.COMPLETED) "✓" else "✗"
        println("  $icon [${result.status}] ${result.task.name}: ${result.message}")
    }
    println("===================")
}
```

## Key Components

| Component | Purpose |
|-----------|---------|
| `Task` | Data class holding job id, name, and payload |
| `TaskQueue` | Wraps a `LinkedBlockingQueue` with enqueue/consume logic |
| `startConsumer()` | Launches a daemon thread that polls tasks and runs a handler |
| `handler` lambda | User-defined work — receives a `Task`, returns a result string |
| `TaskResult` | Stores outcome (`COMPLETED`/`FAILED`) per task |

## How it works

1. **Enqueue** — tasks go into a thread-safe `LinkedBlockingQueue`
2. **Consumer thread** — continuously polls with a 1-second timeout (non-blocking idle)
3. **Handler** — each task is passed to the provided lambda; exceptions are caught and marked as `FAILED`
4. **Stop** — an `AtomicBoolean` flag cleanly shuts down the consumer loop
5. The demo enqueues 5 tasks (one intentionally fails), waits for completion, then prints a summary

