import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;
import java.time.LocalDateTime;

// ======================== FIXED VERSION ========================

public class SearchIndexScheduler implements AutoCloseable {

    private static final Logger logger = Logger.getLogger(SearchIndexScheduler.class.getName());

    // FIX 1: volatile for cross-thread visibility
    private volatile boolean isRunning = false;

    // FIX 2: Thread-safe ConcurrentHashMap
    private final ConcurrentMap<String, IndexTask> taskRegistry = new ConcurrentHashMap<>();

    // FIX 3: Bounded thread pool with proper naming
    private final ExecutorService executor;

    // FIX 4-7: Properly declared and initialized in constructor
    private final ScheduledExecutorService scheduler;

    // FIX 5 & 15: Thread-safe list using CopyOnWriteArrayList
    private final List<String> indexedDocuments = new CopyOnWriteArrayList<>();

    // FIX 6 & 11: Thread-safe queue
    private final BlockingQueue<Document> documentQueue = new LinkedBlockingQueue<>(10_000);

    private final int reindexIntervalHours;

    public SearchIndexScheduler(int poolSize, int reindexIntervalHours) {
        // FIX 7: Properly initialize both executors
        this.scheduler = Executors.newScheduledThreadPool(2, r -> {
            Thread t = new Thread(r, "index-scheduler");
            t.setDaemon(true);
            return t;
        });

        // FIX 3: Bounded pool with named threads
        this.executor = new ThreadPoolExecutor(
            2,                          // core pool
            poolSize,                   // max pool
            60L, TimeUnit.SECONDS,      // idle timeout
            new LinkedBlockingQueue<>(1000),  // bounded work queue
            r -> {
                Thread t = new Thread(r, "index-worker");
                t.setDaemon(true);
                return t;
            },
            new ThreadPoolExecutor.CallerRunsPolicy()  // back-pressure policy
        );

        this.reindexIntervalHours = reindexIntervalHours;

        // FIX 21: Register JVM shutdown hook
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            logger.info("JVM shutting down — closing scheduler...");
            shutdown();
        }, "shutdown-hook"));
    }

    public void start() {
        if (isRunning) {
            logger.warning("Scheduler is already running.");
            return;
        }

        isRunning = true;
        logger.info("Scheduler started at: " + LocalDateTime.now());

        // FIX 8: scheduler is now properly initialized — no NPE
        // Schedule queue processing every 30 seconds
        scheduler.scheduleAtFixedRate(
            this::processQueueSafely,
            0,
            30,
            TimeUnit.SECONDS
        );

        // FIX 9: Proper non-zero interval and initial delay
        scheduler.scheduleAtFixedRate(
            this::reindexAllSafely,
            reindexIntervalHours,   // initial delay (don't run immediately)
            reindexIntervalHours,   // repeat interval
            TimeUnit.HOURS
        );
    }

    // FIX 10: Null check + bounded queue feedback
    public boolean addDocument(Document doc) {
        if (doc == null || doc.getId() == null) {
            logger.warning("Cannot add null document or document with null ID.");
            return false;
        }

        boolean added = documentQueue.offer(doc);  // non-blocking; returns false if full
        if (added) {
            logger.fine("Queued document: " + doc.getId());
        } else {
            logger.warning("Queue full — rejected document: " + doc.getId());
        }
        return added;
    }

    // Wrapper to prevent scheduled task from dying on exception
    private void processQueueSafely() {
        try {
            processQueue();
        } catch (Exception e) {
            // FIX 12 (outer): Log unexpected errors so scheduled task doesn't silently die
            logger.log(Level.SEVERE, "Unexpected error in processQueue", e);
        }
    }

    private void processQueue() {
        if (!isRunning) return;

        int processed = 0;
        Document doc;

        // FIX 11: Use thread-safe poll from BlockingQueue
        while ((doc = documentQueue.poll()) != null) {
            // FIX 13: Null check after poll (poll returns null when empty)
            try {
                indexDocument(doc);
                processed++;
            } catch (IndexingException e) {
                // FIX 12: Proper error logging instead of swallowing
                logger.log(Level.WARNING,
                    "Failed to index document: " + doc.getId(), e);

                // Optionally re-queue for retry (with a retry limit)
                retryDocument(doc);
            }
        }

        if (processed > 0) {
            logger.info("Processed " + processed + " documents from queue.");
        }
    }

    private void indexDocument(Document doc) throws IndexingException {
        // FIX 13: Defensive null checks
        if (doc == null) {
            throw new IndexingException("Document is null");
        }

        String content = doc.getContent();
        if (content == null || content.isBlank()) {
            throw new IndexingException("Empty content for doc: " + doc.getId());
        }

        IndexTask task = new IndexTask(doc.getId(), content);

        // FIX 14: ConcurrentHashMap is thread-safe for put
        taskRegistry.put(doc.getId(), task);
        task.execute();

        // FIX 15: CopyOnWriteArrayList is thread-safe for add
        if (!indexedDocuments.contains(doc.getId())) {
            indexedDocuments.add(doc.getId());
        }

        logger.fine("Indexed: " + doc.getId());
    }

    // Wrapper for scheduled reindex
    private void reindexAllSafely() {
        try {
            reindexAll();
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Unexpected error in reindexAll", e);
        }
    }

    public void reindexAll() {
        if (!isRunning) return;

        logger.info("Starting full reindex of " + indexedDocuments.size() + " documents...");

        // FIX 16: CopyOnWriteArrayList is safe for iteration
        //         (snapshot semantics — no ConcurrentModificationException)
        List<Future<?>> futures = new ArrayList<>();

        for (String docId : indexedDocuments) {
            IndexTask task = taskRegistry.get(docId);
            if (task != null) {
                // FIX 17: Capture Future for error handling
                Future<?> future = executor.submit(() -> {
                    try {
                        task.execute();
                    } catch (Exception e) {
                        logger.log(Level.WARNING, "Reindex failed for: " + docId, e);
                    }
                });
                futures.add(future);
            }
        }

        // Wait for all reindex tasks to complete (with timeout)
        for (Future<?> future : futures) {
            try {
                future.get(5, TimeUnit.MINUTES);
            } catch (TimeoutException e) {
                future.cancel(true);
                logger.warning("Reindex task timed out");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                logger.warning("Reindex interrupted");
                return;
            } catch (ExecutionException e) {
                logger.log(Level.WARNING, "Reindex task failed", e.getCause());
            }
        }

        logger.info("Full reindex completed.");
    }

    // FIX 18: Thread-safe removal
    public boolean removeDocument(String docId) {
        if (docId == null) return false;

        // CopyOnWriteArrayList.remove and ConcurrentHashMap.remove are atomic
        boolean removed = indexedDocuments.remove(docId);
        taskRegistry.remove(docId);

        if (removed) {
            logger.info("Removed document from index: " + docId);
        }
        return removed;
    }

    // FIX 19-20: Comprehensive shutdown with drain
    public void shutdown() {
        if (!isRunning) return;

        isRunning = false;
        logger.info("Initiating scheduler shutdown...");

        // 1. Stop accepting new scheduled tasks
        scheduler.shutdown();

        // 2. Process remaining items in queue before shutting down
        drainRemainingDocuments();

        // 3. Shut down worker executor
        executor.shutdown();

        try {
            // Wait for scheduler tasks to finish
            if (!scheduler.awaitTermination(30, TimeUnit.SECONDS)) {
                logger.warning("Scheduler did not terminate in time — forcing...");
                scheduler.shutdownNow();
            }

            // Wait for worker tasks to finish
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                logger.warning("Executor did not terminate in time — forcing...");
                List<Runnable> dropped = executor.shutdownNow();
                logger.warning("Dropped " + dropped.size() + " pending tasks.");
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        logger.info("Scheduler shut down. Indexed " + indexedDocuments.size() + " documents total.");
    }

    private void drainRemainingDocuments() {
        List<Document> remaining = new ArrayList<>();
        documentQueue.drainTo(remaining);

        for (Document doc : remaining) {
            try {
                indexDocument(doc);
            } catch (IndexingException e) {
                logger.log(Level.WARNING, "Failed to index during drain: " + doc.getId(), e);
            }
        }

        if (!remaining.isEmpty()) {
            logger.info("Drained and indexed " + remaining.size() + " remaining documents.");
        }
    }

    private void retryDocument(Document doc) {
        // Simple retry: re-add to queue (in production, use a retry counter)
        if (!documentQueue.offer(doc)) {
            logger.severe("Could not re-queue document for retry: " + doc.getId());
        }
    }

    public int getQueueSize() {
        return documentQueue.size();
    }

    public int getIndexedCount() {
        return indexedDocuments.size();
    }

    // FIX 21: AutoCloseable for try-with-resources support

