using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace AnalyticsPipeline
{
    // ─── Models ──────────────────────────────────────────────────────

    public class AnalyticsEvent
    {
        public string EventId { get; set; } = Guid.NewGuid().ToString();
        public string EventType { get; set; } = string.Empty;
        public string UserId { get; set; } = string.Empty;
        public Dictionary<string, object> Properties { get; set; } = new();
        public DateTime Timestamp { get; set; } = DateTime.UtcNow;
        public bool IsValid { get; set; }
        public bool IsEnriched { get; set; }
    }

    public class PipelineResult
    {
        public bool Success { get; set; }
        public int ProcessedCount { get; set; }
        public int FailedCount { get; set; }
        public List<string> Errors { get; set; } = new();
    }

    // ─── Retry Policy ───────────────────────────────────────────────

    public class RetryPolicy
    {
        public int MaxRetries { get; set; } = 3;
        public TimeSpan InitialDelay { get; set; } = TimeSpan.FromMilliseconds(200);
        public double BackoffMultiplier { get; set; } = 2.0;
        public TimeSpan MaxDelay { get; set; } = TimeSpan.FromSeconds(30);
    }

    public class RetryHandler
    {
        private readonly RetryPolicy _policy;

        public RetryHandler(RetryPolicy? policy = null)
        {
            _policy = policy ?? new RetryPolicy();
        }

        public async Task<T> ExecuteAsync<T>(
            Func<Task<T>> operation,
            string operationName)
        {
            int attempt = 0;
            var exceptions = new List<Exception>();

            while (true)
            {
                attempt++;
                try
                {
                    Console.WriteLine($"  [{operationName}] Attempt {attempt}/{_policy.MaxRetries + 1}");
                    return await operation();
                }
                catch (Exception ex)
                {
                    exceptions.Add(ex);
                    Console.WriteLine($"  [{operationName}] Attempt {attempt} failed: {ex.Message}");

                    if (attempt > _policy.MaxRetries)
                    {
                        throw new AggregateException(
                            $"'{operationName}' failed after {attempt} attempts.",
                            exceptions);
                    }

                    TimeSpan delay = CalculateDelay(attempt);
                    Console.WriteLine($"  [{operationName}] Retrying in {delay.TotalMilliseconds}ms...");
                    await Task.Delay(delay);
                }
            }
        }

        private TimeSpan CalculateDelay(int attempt)
        {
            double delayMs = _policy.InitialDelay.TotalMilliseconds
                             * Math.Pow(_policy.BackoffMultiplier, attempt - 1);

            // Add jitter (±25%) to prevent thundering herd
            var jitter = new Random().NextDouble() * 0.5 + 0.75;
            delayMs *= jitter;

            return TimeSpan.FromMilliseconds(
                Math.Min(delayMs, _policy.MaxDelay.TotalMilliseconds));
        }
    }

    // ─── Pipeline Stages ────────────────────────────────────────────

    public interface IPipelineStage
    {
        string Name { get; }
        Task<List<AnalyticsEvent>> ProcessAsync(List<AnalyticsEvent> events);
    }

    /// Stage 1: Validate incoming events
    public class ValidationStage : IPipelineStage
    {
        public string Name => "Validation";

        public Task<List<AnalyticsEvent>> ProcessAsync(List<AnalyticsEvent> events)
        {
            var results = new List<AnalyticsEvent>();

            foreach (var evt in events)
            {
                evt.IsValid = !string.IsNullOrEmpty(evt.EventType)
                              && !string.IsNullOrEmpty(evt.UserId);

                if (evt.IsValid)
                    results.Add(evt);
                else
                    Console.WriteLine($"    Dropped invalid event {evt.EventId}");
            }

            return Task.FromResult(results);
        }
    }

    /// Stage 2: Enrich with additional data (simulates external call)
    public class EnrichmentStage : IPipelineStage
    {
        private static int _callCount;

        public string Name => "Enrichment";

        public Task<List<AnalyticsEvent>> ProcessAsync(List<AnalyticsEvent> events)
        {
            _callCount++;

            // Simulate intermittent failure on first 2 calls
            if (_callCount <= 2)
                throw new HttpRequestException("Enrichment API temporarily unavailable");

            foreach (var evt in events)
            {
                evt.Properties["region"] = "us-west-2";
                evt.Properties["enriched_at"] = DateTime.UtcNow;
                evt.IsEnriched = true;
            }

            return Task.FromResult(events);
        }
    }

    /// Stage 3: Aggregate metrics
    public class AggregationStage : IPipelineStage
    {
        public string Name => "Aggregation";

        public Task<List<AnalyticsEvent>> ProcessAsync(List<AnalyticsEvent> events)
        {
            var grouped = events
                .GroupBy(e => e.EventType)
                .Select(g =>
                {
                    Console.WriteLine($"    {g.Key}: {g.Count()} event(s)");
                    return g;
                })
                .SelectMany(g => g)
                .ToList();

            return Task.FromResult(grouped);
        }
    }

    /// Stage 4: Write to storage (simulates DB/warehouse call)
    public class StorageStage : IPipelineStage
    {
        private static int _callCount;

        public string Name => "Storage";

        public Task<List<AnalyticsEvent>> ProcessAsync(List<AnalyticsEvent> events)
        {
            _callCount++;

            // Simulate a one-time transient failure
            if (_callCount == 1)
                throw new TimeoutException("Database write timed out");

            Console.WriteLine($"    Stored {events.Count} events successfully.");
            return Task.FromResult(events);
        }
    }

    // ─── Pipeline Orchestrator ──────────────────────────────────────

    public class AnalyticsPipelineRunner
    {
        private readonly List<IPipelineStage> _stages = new();
        private readonly RetryHandler _retryHandler;

        public AnalyticsPipelineRunner(RetryPolicy? retryPolicy = null)
        {
            _retryHandler = new RetryHandler(retryPolicy);
        }

        public AnalyticsPipelineRunner AddStage(IPipelineStage stage)
        {
            _stages.Add(stage);
            return this; // fluent API
        }

        public async Task<PipelineResult> RunAsync(List<AnalyticsEvent> events)
        {
            var result = new PipelineResult();
            var current = new List<AnalyticsEvent>(events);
            int initialCount = events.Count;

            Console.WriteLine($"\n{'=',-50}");
            Console.WriteLine($" Pipeline started — {initialCount} event(s)");
            Console.WriteLine($"{'=',-50}");

            foreach (var stage in _stages)
            {
                Console.WriteLine($"\n► Stage: {stage.Name}");

                try
                {
                    current = await _retryHandler.ExecuteAsync(
                        () => stage.ProcessAsync(current),
                        stage.Name);

                    Console.WriteLine($"  ✓ {stage.Name} complete — {current.Count} event(s) remaining");
                }
                catch (AggregateException ex)
                {
                    result.Errors.Add($"Stage '{stage.Name}' failed: {ex.Message}");
                    Console.WriteLine($"  ✗ {stage.Name} FAILED permanently.");
                    break; // stop pipeline on unrecoverable failure
                }
            }

            result.ProcessedCount = current.Count;
            result.FailedCount = initialCount - current.Count;
            result.Success = result.Errors.Count == 0;

            Console.WriteLine($"\n{'=',-50}");
            Console.WriteLine($" Pipeline finished — Success: {result.Success}");
            Console.WriteLine($" Processed: {result.ProcessedCount}  Failed: {result.FailedCount}");
            if (result.Errors.Any())
                Console.WriteLine($" Errors: {string.Join("; ", result.Errors)}");
            Console.WriteLine($"{'=',-50}\n");

            return result;
        }
    }

    // ─── Entry Point ────────────────────────────────────────────────

    class Program
    {
        static async Task Main()
        {
            // Sample events (one invalid to test validation)
            var events = new List<AnalyticsEvent>
            {
                new() { EventType = "page_view",  UserId = "user_1",
                         Properties = new() { ["page"] = "/home" }},
                new() { EventType = "click",       UserId = "user_2",
                         Properties = new() { ["button"] = "signup" }},
                new() { EventType = "page_view",  UserId = "user_3",
                         Properties = new() { ["page"] = "/pricing" }},
                new() { EventType = "",            UserId = "",          // ← invalid
                         Properties = new() },
                new() { EventType = "purchase",    UserId = "user_1",
                         Properties = new() { ["amount"] = 49.99 }},
            };

            // Configure retry policy
            var retryPolicy = new RetryPolicy
            {
                MaxRetries       = 3,
                InitialDelay     = TimeSpan.FromMilliseconds(100),
                BackoffMultiplier = 2.0,
                MaxDelay         = TimeSpan.FromSeconds(5)
            };

            // Build and run the pipeline
            var pipeline = new AnalyticsPipelineRunner(retryPolicy)
                .AddStage(new ValidationStage())
                .AddStage(new EnrichmentStage())
                .AddStage(new AggregationStage())
                .AddStage(new StorageStage());

            PipelineResult result = await pipeline.RunAsync(events);
        }
    }
}
```

## How It Works

```
┌────────────┐    ┌────────────┐    ┌─────────────┐    ┌──────────┐
│ Validation │───►│ Enrichment │───►│ Aggregation │───►│ Storage  │
│  (filter)  │    │ (API call) │    │  (group by) │    │  (write) │
└────────────┘    └──────┬─────┘    └─────────────┘    └────┬─────┘
                         │                                   │
                    Fails twice,                       Fails once,
                    retries with                       retries with
                    exponential                        exponential
                    backoff ✓                           backoff ✓
```

## Key Design Decisions

| Feature | Implementation |
|---|---|
| **Retry strategy** | Exponential backoff with jitter to avoid thundering-herd |
| **Pipeline pattern** | Sequential stages via `IPipelineStage` — easy to add/remove |
| **Fluent builder** | `AddStage()` returns `this` for chaining |
| **Failure isolation** | Each stage retries independently; unrecoverable errors stop the pipeline |
| **Observability** | Console logging at every attempt/retry/failure |

