## Configuration File

```yaml
# config/metrics.yaml

version: "1.0"
global:
  default_window: 60s
  flush_interval: 10s
  timezone: UTC
  max_series: 10000

# Define metric sources
sources:
  - name: app_server
    type: statsd
    tags:
      environment: production
      service: api

  - name: system_monitor
    type: prometheus
    tags:
      environment: production
      service: infra

# Aggregation pipeline definitions
aggregations:
  # Simple average response time per endpoint
  - name: avg_response_time
    description: "Average response time grouped by endpoint"
    input_metric: http.request.duration_ms
    function: avg
    window: 60s
    group_by:
      - endpoint
      - method
    filters:
      - field: status_code
        operator: gte
        value: 200
      - field: status_code
        operator: lt
        value: 500
    output_metric: http.request.avg_duration_ms
    tags:
      aggregated: true

  # Request count per status code
  - name: request_count
    description: "Total request count by status code"
    input_metric: http.request.count
    function: sum
    window: 30s
    group_by:
      - status_code
      - endpoint
    output_metric: http.request.total_count
    tags:
      aggregated: true

  # P95 latency
  - name: p95_latency
    description: "95th percentile latency"
    input_metric: http.request.duration_ms
    function: percentile
    percentile_value: 95
    window: 120s
    group_by:
      - endpoint
    output_metric: http.request.p95_duration_ms

  # Error rate calculation
  - name: error_rate
    description: "Error rate as percentage"
    type: composite
    components:
      - alias: errors
        input_metric: http.request.count
        function: sum
        filters:
          - field: status_code
            operator: gte
            value: 500
      - alias: total
        input_metric: http.request.count
        function: sum
    formula: "(errors / total) * 100"
    window: 60s
    group_by:
      - endpoint
    output_metric: http.request.error_rate_pct

  # Min/Max memory usage
  - name: memory_extremes
    description: "Memory usage min and max"
    input_metric: system.memory.used_bytes
    function: minmax
    window: 300s
    group_by:
      - host
    output_metrics:
      min: system.memory.min_used_bytes
      max: system.memory.max_used_bytes

# Alert thresholds tied to aggregations
alerts:
  - name: high_error_rate
    aggregation_ref: error_rate
    condition:
      operator: gt
      value: 5.0
    cooldown: 300s
    severity: critical

  - name: slow_response
    aggregation_ref: p95_latency
    condition:
      operator: gt
      value: 2000
    cooldown: 120s
    severity: warning
