## Config Schema & Validator

```javascript
// src/config/schema.js

/**
 * Defines valid values and constraints for the config schema.
 */
export const AGGREGATION_FUNCTIONS = [
  'sum', 'avg', 'min', 'max', 'count',
  'percentile', 'median', 'stddev', 'minmax', 'rate'
];

export const FILTER_OPERATORS = [
  'eq', 'neq', 'gt', 'gte', 'lt', 'lte',
  'in', 'not_in', 'regex', 'exists'
];

export const SOURCE_TYPES = ['statsd', 'prometheus', 'graphite', 'custom'];

export const SEVERITY_LEVELS = ['info', 'warning', 'critical'];

/**
 * Parse a duration string like "60s", "5m", "1h" into milliseconds.
 */
export function parseDuration(durationStr) {
  if (typeof durationStr === 'number') return durationStr;

  const match = String(durationStr).match(/^(\d+(?:\.\d+)?)\s*(ms|s|m|h|d)$/);
  if (!match) {
    throw new ConfigError(`Invalid duration format: "${durationStr}". Use: 100ms, 60s, 5m, 1h, 1d`);
  }

  const value = parseFloat(match[1]);
  const unit = match[2];

  const multipliers = {
    ms: 1,
    s: 1000,
    m: 60_000,
    h: 3_600_000,
    d: 86_400_000
  };

  return value * multipliers[unit];
}

export class ConfigError extends Error {
  constructor(message, path = null) {
    super(path ? `[${path}] ${message}` : message);
    this.name = 'ConfigError';
    this.path = path;
  }
}
