```javascript
// src/config/validator.js

import {
  AGGREGATION_FUNCTIONS,
  FILTER_OPERATORS,
  SOURCE_TYPES,
  SEVERITY_LEVELS,
  parseDuration,
  ConfigError
} from './schema.js';

export class ConfigValidator {
  #errors;
  #warnings;

  constructor() {
    this.#errors = [];
    this.#warnings = [];
  }

  /**
   * Validate the entire config object. Returns { valid, errors, warnings }.
   */
  validate(config) {
    this.#errors = [];
    this.#warnings = [];

    this.#validateRequired(config, 'version', 'string', 'root');
    this.#validateGlobal(config.global);
    this.#validateSources(config.sources);
    this.#validateAggregations(config.aggregations);
    this.#validateAlerts(config.alerts, config.aggregations);
    this.#validateCrossReferences(config);

    return {
      valid: this.#errors.length === 0,
      errors: [...this.#errors],
      warnings: [...this.#warnings]
    };
  }

  #addError(message, path) {
    this.#errors.push(new ConfigError(message, path));
  }

  #addWarning(message, path) {
    this.#warnings.push({ message, path });
  }

  #validateRequired(obj, field, type, path) {
    const fullPath = `${path}.${field}`;
    if (obj == null || !(field in obj)) {
      this.#addError(`Missing required field "${field}"`, path);
      return false;
    }
    if (type && typeof obj[field] !== type) {
      this.#addError(`"${field}" must be of type ${type}, got ${typeof obj[field]}`, path);
      return false;
    }
    return true;
  }

  #validateGlobal(global) {
    if (!global) {
      this.#addWarning('No global config — defaults will be used', 'global');
      return;
    }

    const path = 'global';

    if (global.default_window) {
      try { parseDuration(global.default_window); }
      catch { this.#addError(`Invalid default_window: "${global.default_window}"`, path); }
    }

    if (global.flush_interval) {
      try { parseDuration(global.flush_interval); }
      catch { this.#addError(`Invalid flush_interval: "${global.flush_interval}"`, path); }
    }

    if (global.max_series != null && (!Number.isInteger(global.max_series) || global.max_series < 1)) {
      this.#addError('max_series must be a positive integer', path);
    }
  }

  #validateSources(sources) {
    if (!sources) return;
    if (!Array.isArray(sources)) {
      this.#addError('sources must be an array', 'sources');
      return;
    }

    const names = new Set();
    sources.forEach((source, i) => {
      const path = `sources[${i}]`;
      this.#validateRequired(source, 'name', 'string', path);
      this.#validateRequired(source, 'type', 'string', path);

      if (source.name && names.has(source.name)) {
        this.#addError(`Duplicate source name: "${source.name}"`, path);
      }
      names.add(source.name);

      if (source.type && !SOURCE_TYPES.includes(source.type)) {
        this.#addError(
          `Invalid source type "${source.type}". Valid: ${SOURCE_TYPES.join(', ')}`,
          path
        );
      }
    });
  }

  #validateAggregations(aggregations) {
    if (!aggregations || !Array.isArray(aggregations)) {
      this.#addError('aggregations must be a non-empty array', 'aggregations');
      return;
    }

    const names = new Set();
    aggregations.forEach((agg, i) => {
      const path = `aggregations[${i}]`;
      this.#validateRequired(agg, 'name', 'string', path);

      if (agg.name && names.has(agg.name)) {
        this.#addError(`Duplicate aggregation name: "${agg.name}"`, path);
      }
      names.add(agg.name);

      // Composite aggregations have different requirements
      if (agg.type === 'composite') {
        this.#validateCompositeAggregation(agg, path);
      } else {
        this.#validateSimpleAggregation(agg, path);
      }

      // Validate window
      if (agg.window) {
        try { parseDuration(agg.window); }
        catch { this.#addError(`Invalid window: "${agg.window}"`, path); }
      }

      // Validate filters
      if (agg.filters) {
        this.#validateFilters(agg.filters, path);
      }
    });
  }

  #validateSimpleAggregation(agg, path) {
    this.#validateRequired(agg, 'input_metric', 'string', path);
    this.#validateRequired(agg, 'function', 'string', path);

    if (agg.function && !AGGREGATION_FUNCTIONS.includes(agg.function)) {
      this.#addError(
        `Invalid function "${agg.function}". Valid: ${AGGREGATION_FUNCTIONS.join(', ')}`,
        path
      );
    }

    if (agg.function === 'percentile' && (agg.percentile_value == null || agg.percentile_value < 0 || agg.percentile_value > 100)) {
      this.#addError('percentile function requires percentile_value between 0 and 100', path);
    }

    // Must have output_metric or output_metrics (for minmax)
    if (agg.function === 'minmax') {
      if (!agg.output_metrics || !agg.output_metrics.min || !agg.output_metrics.max) {
        this.#addError('minmax function requires output_metrics with min and max keys', path);
      }
    } else if (!agg.output_metric) {
      this.#addWarning('No output_metric defined — input name will be reused', path);
    }
  }

  #validateCompositeAggregation(agg, path) {
    if (!Array.isArray(agg.components) || agg.components.length < 2) {
      this.#addError('Composite aggregation needs at least 2 components', path);
      return;
    }

    const aliases = new Set();
    agg.components.forEach((comp, j) => {
      const compPath = `${path}.components[${j}]`;
      this.#validateRequired(comp, 'alias', 'string', compPath);
      this.#validateRequired(comp, 'input_metric', 'string', compPath);
      this.#validateRequired(comp, 'function', 'string', compPath);

      if (comp.alias) aliases.add(comp.alias);
    });

    if (!agg.formula) {
      this.#addError('Composite aggregation requires a formula', path);
    } else {
      // Check that formula references match component aliases
      const formulaVars = agg.formula.match(/[a-zA-Z_]\w*/g) || [];
      for (const v of formulaVars) {
        if (!aliases.has(v)) {
          this.#addError(`Formula references unknown alias "${v}"`, path);
        }
      }
    }

    this.#validateRequired(agg, 'output_metric', 'string', path);
  }

  #validateFilters(filters, parentPath) {
    if (!Array.isArray(filters)) {
      this.#addError('filters must be an array', parentPath);
      return;
    }

    filters.forEach((filter, i) => {
      const path = `${parentPath}.filters[${i}]`;
      this.#validateRequired(filter, 'field', 'string', path);
      this.#validateRequired(filter, 'operator', 'string', path);

      if (filter.operator && !FILTER_OPERATORS.includes(filter.operator)) {
        this.#addError(
          `Invalid filter operator "${filter.operator}". Valid: ${FILTER_OPERATORS.join(', ')}`,
          path
        );
      }

      if (filter.operator && !['exists'].includes(filter.operator) && filter.value === undefined) {
        this.#addError('Filter requires a value (except for "exists")', path);
      }
    });
  }

  #validateAlerts(alerts, aggregations) {
    if (!alerts) return;

    const aggNames = new Set((aggregations || []).map(a => a.name));

    alerts.forEach((alert, i) => {
      const path = `alerts[${i}]`;
      this.#validateRequired(alert, 'name', 'string', path);
      this.#validateRequired(alert, 'aggregation_ref', 'string', path);

      if (alert.aggregation_ref && !aggNames.has(alert.aggregation_ref)) {
        this.#addError(`Alert references unknown aggregation "${alert.aggregation_ref}"`, path);
      }

      if (alert.severity && !SEVERITY_LEVELS.includes(alert.severity)) {
        this.#addError(`Invalid severity "${alert.severity}"`, path);
      }

      if (alert.cooldown) {
        try { parseDuration(alert.cooldown); }
        catch { this.#addError(`Invalid cooldown: "${alert.cooldown}"`, path); }
      }
    });
  }

  #validateCrossReferences(config) {
    // Ensure no circular references or dangling pointers exist
    const aggNames = new Set((config.aggregations || []).map(a => a.name));

    // Check output metric names don't collide with input metric names
    const inputMetrics = new Set();
    const outputMetrics = new Set();

    for (const agg of (config.aggregations || [])) {
      if (agg.input_metric) inputMetrics.add(agg.input_metric);
      if (agg.output_metric) {
        if (outputMetrics.has(agg.output_metric)) {
          this.#addWarning(
            `Multiple aggregations write to "${agg.output_metric}"`,
            `aggregations.${agg.name}`
          );
        }
        outputMetrics.add(agg.output_metric);
      }
    }
  }
}
