## Config Parser

```javascript
// src/config/parser.js

import { readFileSync } from 'node:fs';
import { extname } from 'node:path';
import yaml from 'js-yaml';
import { ConfigValidator } from './validator.js';
import { parseDuration, ConfigError } from './schema.js';

export class ConfigParser {
  #validator;

  constructor() {
    this.#validator = new ConfigValidator();
  }

  /**
   * Load and parse a config file (YAML or JSON).
   * @param {string} filePath
   * @returns {ParsedConfig}
   */
  parseFile(filePath) {
    const raw = readFileSync(filePath, 'utf-8');
    const ext = extname(filePath).toLowerCase();

    let data;
    if (ext === '.yaml' || ext === '.yml') {
      data = yaml.load(raw);
    } else if (ext === '.json') {
      data = JSON.parse(raw);
    } else {
      throw new ConfigError(`Unsupported config format: ${ext}`);
    }

    return this.parse(data);
  }

  /**
   * Parse a raw config object.
   * @param {object} rawConfig
   * @returns {ParsedConfig}
   */
  parse(rawConfig) {
    // 1. Validate
    const validation = this.#validator.validate(rawConfig);
    if (!validation.valid) {
      const messages = validation.errors.map(e => e.message).join('\n  • ');
      throw new ConfigError(`Config validation failed:\n  • ${messages}`);
    }

    // 2. Normalize into a structured object
    const global = this.#parseGlobal(rawConfig.global || {});
    const sources = (rawConfig.sources || []).map(s => this.#parseSource(s));
    const aggregations = rawConfig.aggregations.map(a => this.#parseAggregation(a, global));
    const alerts = (rawConfig.alerts || []).map(a => this.#parseAlert(a));

    return {
      version: rawConfig.version,
      global,
      sources,
      aggregations,
