public sealed class MigrationConfig
{
    /// <summary>Time window for grouping metrics before aggregation.</summary>
    public TimeSpan AggregationWindow { get; init; } = TimeSpan.FromMinutes(5);

    /// <summary>Which aggregation functions to apply per metric group.</summary>
    public IReadOnlyList<AggregationType> Aggregations { get; init; } =
        [AggregationType.Sum, AggregationType.Average, AggregationType.Count];

    /// <summary>Number of aggregated records per write batch.</summary>
    public int WriteBatchSize { get; init; } = 500;

    /// <summary>Maximum retry attempts for transient failures.</summary>
    public int MaxRetries { get; init; } = 3;

    /// <summary>Base delay between retries (exponential backoff).</summary>
    public TimeSpan RetryBaseDelay { get; init; } = TimeSpan.FromSeconds(1);

    /// <summary>Tags to include in the group-by key (null = all tags).</summary>
    public IReadOnlySet<string>? GroupByTags { get; init; }

    /// <summary>Optional filter: only migrate these metric names.</summary>
    public IReadOnlySet<string>? MetricNameFilter { get; init; }

    public void Validate()
    {
        if (AggregationWindow <= TimeSpan.Zero)
            throw new ArgumentException("AggregationWindow must be positive.");
        if (WriteBatchSize <= 0)
            throw new ArgumentException("WriteBatchSize must be positive.");
        if (Aggregations.Count == 0)
            throw new ArgumentException("At least one aggregation type is required.");
    }
}
