## Aggregation Engine

```csharp
// MetricsAggregator.cs
public sealed class MetricsAggregator
{
    private readonly MigrationConfig _config;

    public MetricsAggregator(MigrationConfig config) => _config = config;

    /// <summary>
    /// Groups raw records by (MetricName, Source, Tags, TimeWindow)
    /// then computes each configured aggregation.
    /// </summary>
    public IReadOnlyList<AggregatedMetric> Aggregate(IReadOnlyList<MetricRecord> records)
    {
        if (records.Count == 0) return [];

        var groups = records.GroupBy(r => BuildGroupKey(r));
        var results = new List<AggregatedMetric>();

        foreach (var group in groups)
        {
            var values = group.Select(r => r.Value).ToList();
            var windowStart = group.Min(r => r.Timestamp);
            var windowEnd = group.Max(r => r.Timestamp);
            var representative = group.First();
            var tags = BuildAggregatedTags(representative.Tags);

            foreach (var aggType in _config.Aggregations)
            {
                double aggValue = ComputeAggregation(aggType, values);

                results.Add(new AggregatedMetric(
                    MetricName: representative.MetricName,
                    Source: representative.Source,
                    Aggregation: aggType,
                    Value: aggValue,
                    SampleCount: values.Count,
                    WindowStart: windowStart,
                    WindowEnd: windowEnd,
                    Tags: tags));
            }
        }

        return results;
    }

    // --- Group key built from metric name, source, selected tags, and time bucket ---

    private string BuildGroupKey(MetricRecord record)
    {
        var timeBucket = GetTimeBucket(record.Timestamp);
        var tagKey = BuildTagKey(record.Tags);
        return $"{record.MetricName}|{record.Source}|{tagKey}|{timeBucket:O}";
    }

    private DateTimeOffset GetTimeBucket(DateTimeOffset timestamp)
    {
        long ticks = timestamp.UtcTicks;
        long windowTicks = _config.AggregationWindow.Ticks;
        long bucketTicks = (ticks / windowTicks) * windowTicks;
        return new DateTimeOffset(bucketTicks, TimeSpan.Zero);
    }

    private string BuildTagKey(IReadOnlyDictionary<string, string> tags)
    {
        var relevantTags = _config.GroupByTags is null
            ? tags.OrderBy(kv => kv.Key)
            : tags.Where(kv => _config.GroupByTags.Contains(kv.Key))
                  .OrderBy(kv => kv.Key);

        return string.Join(",", relevantTags.Select(kv => $"{kv.Key}={kv.Value}"));
    }

    private IReadOnlyDictionary<string, string> BuildAggregatedTags(
        IReadOnlyDictionary<string, string> original)
    {
        if (_config.GroupByTags is null) return original;

        return original
            .Where(kv => _config.GroupByTags.Contains(kv.Key))
            .ToDictionary(kv => kv.Key, kv => kv.Value);
    }

    // --- Aggregation math ---

    private static double ComputeAggregation(AggregationType type, List<double> values) =>
        type switch
        {
            AggregationType.Sum          => values.Sum(),
            AggregationType.Average      => values.Average(),
            AggregationType.Count        => values.Count,
            AggregationType.Min          => values.Min(),
            AggregationType.Max          => values.Max(),
            AggregationType.Percentile95 => Percentile(values, 0.95),
            AggregationType.Percentile99 => Percentile(values, 0.99),
            _ => throw new ArgumentOutOfRangeException(nameof(type), type, "Unsupported aggregation")
        };

    private static double Percentile(List<double> values, double percentile)
    {
        if (values.Count == 0) return 0;
        if (values.Count == 1) return values[0];

        var sorted = values.OrderBy(v => v).ToList();
        double rank = percentile * (sorted.Count - 1);
        int lower = (int)Math.Floor(rank);
        int upper = (int)Math.Ceiling(rank);

        if (lower == upper) return sorted[lower];

        double weight = rank - lower;
        return sorted[lower] * (1 - weight) + sorted[upper] * weight;
    }
}
