```csharp
// MetricsMigrationHelper.cs
using Microsoft.Extensions.Logging;

public sealed class MetricsMigrationHelper
{
    private readonly IMetricSource _source;
    private readonly IMetricDestination _destination;
    private readonly MigrationConfig _config;
    private readonly MetricsAggregator _aggregator;
    private readonly ILogger<MetricsMigrationHelper> _logger;

    public MetricsMigrationHelper(
        IMetricSource source,
        IMetricDestination destination,
        MigrationConfig config,
        ILogger<MetricsMigrationHelper> logger)
    {
        _source = source ?? throw new ArgumentNullException(nameof(source));
        _destination = destination ?? throw new ArgumentNullException(nameof(destination));
        _config = config ?? throw new ArgumentNullException(nameof(config));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));

        _config.Validate();
        _aggregator = new MetricsAggregator(_config);
    }

    /// <summary>
    /// Optional callback for external progress monitoring.
    /// </summary>
    public event Action<MigrationProgress>? OnProgress;

    /// <summary>
    /// Runs the full migration pipeline: read → filter → aggregate → batch write.
    /// </summary>
    public async Task<MigrationResult> MigrateAsync(
        DateTimeOffset from,
        DateTimeOffset to,
        CancellationToken ct = default)
    {
        _logger.LogInformation(
            "Starting metrics migration from {From} to {To} with {Window} window",
            from, to, _config.AggregationWindow);

        var stopwatch = System.Diagnostics.Stopwatch.StartNew();
        var errors = new List<string>();

        int totalRead = 0;
        int totalAggregated = 0;
        int totalWritten = 0;
        int failedBatches = 0;

        // --- Phase 1: Read and buffer by time window ---
        var windowBuffers = new Dictionary<DateTimeOffset, List<MetricRecord>>();

        await foreach (var record in _source.ReadMetricsAsync(from, to, ct))
        {
            // Optional name filter
            if (_config.MetricNameFilter is not null &&
                !_config.MetricNameFilter.Contains(record.MetricName))
                continue;

            totalRead++;
            var bucket = GetTimeBucket(record.Timestamp);

            if (!windowBuffers.TryGetValue(bucket, out var list))
            {
                list = [];
                windowBuffers[bucket] = list;
            }
            list.Add(record);

            if (totalRead % 10_000 == 0)
            {
                _logger.LogDebug("Read {Count} raw records so far...", totalRead);
                RaiseProgress(totalRead, totalAggregated, totalWritten);
            }
        }

        _logger.LogInformation(
            "Read complete: {TotalRead} records in {Windows} time windows",
            totalRead, windowBuffers.Count);

        // --- Phase 2: Aggregate each window and write in batches ---
        var writeBatch = new List<AggregatedMetric>(_config.WriteBatchSize);

        foreach (var (window, records) in windowBuffers.OrderBy(kv => kv.Key))
        {
            ct.ThrowIfCancellationRequested();

            var aggregated = _aggregator.Aggregate(records);
            totalAggregated += aggregated.Count;

            foreach (var metric in aggregated)
            {
                writeBatch.Add(metric);

                if (writeBatch.Count >= _config.WriteBatchSize)
                {
                    var (written, error) = await FlushBatchAsync(writeBatch, ct);
                    totalWritten += written;
                    if (error is not null)
                    {
                        failedBatches++;
                        errors.Add(error);
                    }
                    writeBatch.Clear();
                    RaiseProgress(totalRead, totalAggregated, totalWritten);
                }
            }
        }

        // Flush remaining
        if (writeBatch.Count > 0)
        {
            var (written, error) = await FlushBatchAsync(writeBatch, ct);
            totalWritten += written;
            if (error is not null)
            {
                failedBatches++;
                errors.Add(error);
            }
        }

        stopwatch.Stop();

        var result = new MigrationResult
        {
            TotalRecordsRead = totalRead,
            TotalAggregationsProduced = totalAggregated,
            TotalRecordsWritten = totalWritten,
            FailedBatches = failedBatches,
            Elapsed = stopwatch.Elapsed,
            Errors = errors
        };

        _logger.LogInformation("Migration complete: {Result}", result);
        return result;
    }

    // --- Batch writing with exponential backoff retry ---

    private async Task<(int Written, string? Error)> FlushBatchAsync(
        List<AggregatedMetric> batch,
        CancellationToken ct)
    {
        var snapshot = batch.ToList(); // defensive copy

        for (int attempt = 0; attempt <= _config.MaxRetries; attempt++)
        {
            try
            {
                await _destination.WriteBatchAsync(snapshot, ct);
                _logger.LogDebug("Wrote batch of {Count} aggregated metrics", snapshot.Count);
                return (snapshot.Count, null);
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception ex)
            {
                _logger.LogWarning(ex,
                    "Write attempt {Attempt}/{Max} failed for batch of {Count}",
                    attempt + 1, _config.MaxRetries + 1, snapshot.Count);

                if (attempt < _config.MaxRetries)
                {
                    var delay = _config.RetryBaseDelay * Math.Pow(2, attempt);
                    await Task.Delay(delay, ct);
                }
                else
                {
                    var message = $"Batch write failed after {_config.MaxRetries + 1} " +
                                  $"attempts: {ex.Message}";
                    _logger.LogError(message);
                    return (0, message);
                }
            }
        }

        return (0, "Unexpected retry loop exit");
    }

    private DateTimeOffset GetTimeBucket(DateTimeOffset timestamp)
    {
        long ticks = timestamp.UtcTicks;
        long windowTicks = _config.AggregationWindow.Ticks;
        return new DateTimeOffset((ticks / windowTicks) * windowTicks, TimeSpan.Zero);
    }

    private void RaiseProgress(int read, int aggregated, int written) =>
        OnProgress?.Invoke(new MigrationProgress(read, aggregated, written));
}

// MigrationProgress.cs
public sealed record MigrationProgress(
    int RecordsRead,
    int RecordsAggregated,
    int RecordsWritten);
