/**
 * Immutable analytics event representation.
 * Every event flowing through the pipeline is wrapped in this structure.
 */
export class AnalyticsEvent {
  /** @type {string} */            #id;
  /** @type {string} */            #type;
  /** @type {number} */            #timestamp;
  /** @type {Readonly<Object>} */  #payload;
  /** @type {Readonly<Object>} */  #metadata;

  /**
   * @param {Object} params
   * @param {string} params.type      - Event type (e.g. "page_view", "click")
   * @param {Object} params.payload   - Core event data
   * @param {Object} [params.metadata]- Ancillary info (source, version, etc.)
   * @param {string} [params.id]      - Optional explicit id
   * @param {number} [params.timestamp]
   */
  constructor({ type, payload, metadata = {}, id, timestamp }) {
    if (!type || typeof type !== 'string') {
      throw new TypeError('Event type must be a non-empty string');
    }
    if (!payload || typeof payload !== 'object') {
      throw new TypeError('Event payload must be an object');
    }

    this.#id = id ?? AnalyticsEvent.generateId();
    this.#type = type;
    this.#timestamp = timestamp ?? Date.now();
    this.#payload = Object.freeze({ ...payload });
    this.#metadata = Object.freeze({ ...metadata });
  }

  get id()        { return this.#id; }
  get type()      { return this.#type; }
  get timestamp() { return this.#timestamp; }
  get payload()   { return this.#payload; }
  get metadata()  { return this.#metadata; }

  /**
   * Return a new event with merged payload — immutability preserved.
   * @param {Object} newPayload
   * @returns {AnalyticsEvent}
   */
  withPayload(newPayload) {
    return new AnalyticsEvent({
      id: this.#id,
      type: this.#type,
      timestamp: this.#timestamp,
      payload: { ...this.#payload, ...newPayload },
      metadata: { ...this.#metadata },
    });
  }

  /**
   * Return a new event with merged metadata.
   * @param {Object} newMetadata
   * @returns {AnalyticsEvent}
   */
  withMetadata(newMetadata) {
    return new AnalyticsEvent({
      id: this.#id,
      type: this.#type,
      timestamp: this.#timestamp,
      payload: { ...this.#payload },
      metadata: { ...this.#metadata, ...newMetadata },
    });
  }

  toJSON() {
    return {
      id: this.#id,
      type: this.#type,
      timestamp: this.#timestamp,
      payload: { ...this.#payload },
      metadata: { ...this.#metadata },
    };
  }

  static generateId() {
    // Compact k-sortable ID: timestamp hex + random hex
    const timePart = Date.now().toString(36);
    const randPart = Math.random().toString(36).substring(2, 10);
    return `${timePart}-${randPart}`;
  }
}
