/**
 * Lightweight schema validator (no external deps).
 * Supports: type, required, enum, min, max, pattern, custom, nested objects/arrays.
 */
export class SchemaValidator {
  #schemas = new Map();

  /**
   * Register a schema for a given event type.
   * @param {string} eventType
   * @param {Object} schema - field definitions keyed by field name
   *
   * Each field definition can include:
   *   type:     'string' | 'number' | 'boolean' | 'object' | 'array'
   *   required: boolean
   *   enum:     Array of allowed values
   *   min:      minimum (number) or minLength (string)
   *   max:      maximum (number) or maxLength (string)
   *   pattern:  RegExp
   *   custom:   (value, fieldName) => string|null  (return error string or null)
   *   properties: nested schema (when type = 'object')
   *   items:    item schema  (when type = 'array')
   */
  register(eventType, schema) {
    if (!eventType || typeof eventType !== 'string') {
      throw new Error('eventType must be a non-empty string');
    }
    this.#schemas.set(eventType, schema);
    return this;
  }

  /**
   * Validate an event payload against its registered schema.
   * @param {string} eventType
   * @param {Object} payload
   * @returns {{ valid: boolean, errors: string[] }}
   */
  validate(eventType, payload) {
    const schema = this.#schemas.get(eventType);
    if (!schema) {
      return { valid: true, errors: [] }; // No schema = pass-through
    }
    const errors = this.#validateObject(schema, payload, '');
    return { valid: errors.length === 0, errors };
  }

  hasSchema(eventType) {
    return this.#schemas.has(eventType);
  }

  #validateObject(schema, obj, prefix) {
    const errors = [];

    for (const [field, rules] of Object.entries(schema)) {
      const path = prefix ? `${prefix}.${field}` : field;
      const value = obj?.[field];

      // Required check
      if (rules.required && (value === undefined || value === null)) {
        errors.push(`${path} is required`);
        continue;
      }
      if (value === undefined || value === null) continue;

      // Type check
      if (rules.type) {
        const actualType = Array.isArray(value) ? 'array' : typeof value;
        if (actualType !== rules.type) {
          errors.push(`${path} must be of type ${rules.type}, got ${actualType}`);
          continue;
        }
      }

      // Enum check
      if (rules.enum && !rules.enum.includes(value)) {
        errors.push(`${path} must be one of [${rules.enum.join(', ')}]`);
      }

      // Min / Max for numbers
      if (rules.type === 'number') {
        if (rules.min !== undefined && value < rules.min) {
          errors.push(`${path} must be >= ${rules.min}`);
        }
        if (rules.max !== undefined && value > rules.max) {
          errors.push(`${path} must be <= ${rules.max}`);
        }
      }

      // Min / Max length for strings
      if (rules.type === 'string') {
        if (rules.min !== undefined && value.length < rules.min) {
          errors.push(`${path} length must be >= ${rules.min}`);
        }
        if (rules.max !== undefined && value.length > rules.max) {
          errors.push(`${path} length must be <= ${rules.max}`);
        }
        if (rules.pattern && !rules.pattern.test(value)) {
          errors.push(`${path} does not match pattern ${rules.pattern}`);
        }
      }

      // Nested object
      if (rules.type === 'object' && rules.properties) {
        errors.push(...this.#validateObject(rules.properties, value, path));
      }

      // Array items
      if (rules.type === 'array' && rules.items) {
        for (let i = 0; i < value.length; i++) {
          const itemPath = `${path}[${i}]`;
          if (rules.items.type && typeof value[i] !== rules.items.type) {
            errors.push(`${itemPath} must be of type ${rules.items.type}`);
          }
        }
      }

      // Custom validator
      if (rules.custom) {
        const err = rules.custom(value, field);
        if (err) errors.push(`${path}: ${err}`);
      }
    }

    return errors;
  }
}
