/**
 * Retry with exponential back-off + jitter.
 */
export class RetryPolicy {
  #maxRetries;
  #baseDelayMs;
  #maxDelayMs;
  #jitter;

  /**
   * @param {Object} opts
   * @param {number} [opts.maxRetries=3]
   * @param {number} [opts.baseDelayMs=200]
   * @param {number} [opts.maxDelayMs=10000]
   * @param {boolean}[opts.jitter=true]
   */
  constructor({ maxRetries = 3, baseDelayMs = 200, maxDelayMs = 10_000, jitter = true } = {}) {
    this.#maxRetries = maxRetries;
    this.#baseDelayMs = baseDelayMs;
    this.#maxDelayMs = maxDelayMs;
    this.#jitter = jitter;
  }

  get maxRetries()  { return this.#maxRetries; }
  get baseDelayMs() { return this.#baseDelayMs; }

  /**
   * Execute fn with retries.
   * @template T
   * @param {() => Promise<T>} fn
   * @param {Object} [opts]
   * @param {(err: Error, attempt: number) => boolean} [opts.shouldRetry] - return false to bail early
   * @param {(err: Error, attempt: number, delayMs: number) => void} [opts.onRetry]
   * @returns {Promise<T>}
   */
  async execute(fn, { shouldRetry, onRetry } = {}) {
    let lastError;

    for (let attempt = 0; attempt <= this.#maxRetries; attempt++) {
      try {
        return await fn();
      } catch (err) {
        lastError = err;

        if (attempt === this.#maxRetries) break;
        if (shouldRetry && !shouldRetry(err, attempt)) break;

        const delay = this.#calculateDelay(attempt);
        onRetry?.(err, attempt, delay);
        await this.#sleep(delay);
      }
    }

    throw lastError;
  }

  #calculateDelay(attempt) {
    const exponential = this.#baseDelayMs * Math.pow(2, attempt);
    const capped = Math.min(exponential, this.#maxDelayMs);
    if (!this.#jitter) return capped;
    return Math.floor(capped * (0.5 + Math.random() * 0.5));
  }

  #sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}
