/**
 * Fixed-capacity ring buffer for back-pressure management.
 * When full, oldest items are evicted (with optional callback).
 */
export class RingBuffer {
  #buffer;
  #capacity;
  #head = 0;
  #size = 0;
  #totalEvicted = 0;
  #onEvict;

  /**
   * @param {number} capacity
   * @param {Object} [opts]
   * @param {(item: any) => void} [opts.onEvict] - called when an item is overwritten
   */
  constructor(capacity, { onEvict } = {}) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError('Capacity must be a positive integer');
    }
    this.#buffer = new Array(capacity);
    this.#capacity = capacity;
    this.#onEvict = onEvict ?? null;
  }

  get capacity()     { return this.#capacity; }
  get size()         { return this.#size; }
  get totalEvicted() { return this.#totalEvicted; }
  get isEmpty()      { return this.#size === 0; }
  get isFull()       { return this.#size === this.#capacity; }

  /**
   * Push an item.  Returns true if an old item was evicted.
   * @param {*} item
   * @returns {boolean}
   */
  push(item) {
    const writeIndex = (this.#head + this.#size) % this.#capacity;
    let evicted = false;

    if (this.#size === this.#capacity) {
      // Overwrite oldest
      const old = this.#buffer[this.#head];
      this.#onEvict?.(old);
      this.#head = (this.#head + 1) % this.#capacity;
      this.#totalEvicted++;
      evicted = true;
    } else {
      this.#size++;
    }

    this.#buffer[writeIndex] = item;
    return evicted;
  }

  /**
   * Remove and return the oldest item.
   * @returns {*|undefined}
   */
  shift() {
    if (this.#size === 0) return undefined;
    const item = this.#buffer[this.#head];
    this.#buffer[this.#head] = undefined;
    this.#head = (this.#head + 1) % this.#capacity;
    this.#size--;
    return item;
  }

  /**
   * Drain up to `count` items from oldest to newest.
   * @param {number} count
   * @returns {Array}
   */
  drain(count = this.#size) {
    const items = [];
    const n = Math.min(count, this.#size);
    for (let i = 0; i < n; i++) {
      items.push(this.shift());
    }
    return items;
  }

  /**
   * Peek at the oldest item without removing it.
   * @returns {*|undefined}
   */
  peek() {
    if (this.#size === 0) return undefined;
    return this.#buffer[this.#head];
  }

  /**
   * Iterate all items oldest → newest without removing.
   */
  *[Symbol.iterator]() {
    for (let i = 0; i < this.#size; i++) {
      yield this.#buffer[(this.#head + i) % this.#capacity];
    }
  }

  clear() {
    this.#buffer.fill(undefined);
    this.#head = 0;
    this.#size = 0;
  }
}
