    private final String type;
    private final String sourceVersion;
    private final String targetVersion;
    private final Map<String, Object> payload;
    private final Map<String, String> metadata;
    private final Instant createdAt;
    private final Priority priority;
    private int attemptCount;

    private MigrationEvent(Builder builder) {
        this.id = builder.id;
        this.type = builder.type;
        this.sourceVersion = builder.sourceVersion;
        this.targetVersion = builder.targetVersion;
        this.payload = Collections.unmodifiableMap(new HashMap<>(builder.payload));
        this.metadata = Collections.unmodifiableMap(new HashMap<>(builder.metadata));
        this.createdAt = builder.createdAt;
        this.priority = builder.priority;
        this.attemptCount = 0;
    }

    // --- Getters ---
    public String getId()             { return id; }
    public String getType()           { return type; }
    public String getSourceVersion()  { return sourceVersion; }
    public String getTargetVersion()  { return targetVersion; }
    public Map<String, Object> getPayload()  { return payload; }
    public Map<String, String> getMetadata() { return metadata; }
    public Instant getCreatedAt()     { return createdAt; }
    public Priority getPriority()     { return priority; }
    public int getAttemptCount()      { return attemptCount; }
    public void incrementAttempt()    { this.attemptCount++; }

    /** Create a new event with a transformed payload (immutable pattern). */
    public MigrationEvent withPayload(Map<String, Object> newPayload) {
        return new Builder()
                .id(this.id)
                .type(this.type)
                .sourceVersion(this.sourceVersion)
                .targetVersion(this.targetVersion)
                .payload(newPayload)
                .metadata(this.metadata)
                .createdAt(this.createdAt)
                .priority(this.priority)
                .build();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof MigrationEvent)) return false;
        return Objects.equals(id, ((MigrationEvent) o).id);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }

    @Override
    public String toString() {
        return String.format("MigrationEvent{id='%s', type='%s', v%s→v%s, priority=%s}",
                id, type, sourceVersion, targetVersion, priority);
    }

    // --- Builder ---
    public static class Builder {
        private String id = UUID.randomUUID().toString();
        private String type;
        private String sourceVersion;
        private String targetVersion;
        private Map<String, Object> payload = new HashMap<>();
        private Map<String, String> metadata = new HashMap<>();
        private Instant createdAt = Instant.now();
        private Priority priority = Priority.NORMAL;

        public Builder id(String id)                       { this.id = id; return this; }
        public Builder type(String type)                   { this.type = type; return this; }
        public Builder sourceVersion(String v)             { this.sourceVersion = v; return this; }
        public Builder targetVersion(String v)             { this.targetVersion = v; return this; }
        public Builder payload(Map<String, Object> p)      { this.payload = new HashMap<>(p); return this; }
        public Builder metadata(Map<String, String> m)     { this.metadata = new HashMap<>(m); return this; }
        public Builder createdAt(Instant t)                { this.createdAt = t; return this; }
        public Builder priority(Priority p)                { this.priority = p; return this; }

        public Builder addPayload(String key, Object val)  { this.payload.put(key, val); return this; }
        public Builder addMetadata(String key, String val) { this.metadata.put(key, val); return this; }

        public MigrationEvent build() {
            Objects.requireNonNull(type, "Event type is required");
            Objects.requireNonNull(sourceVersion, "Source version is required");
            Objects.requireNonNull(targetVersion, "Target version is required");
            return new MigrationEvent(this);
        }
    }
}
