// model/MigrationState.java
package com.migration.model;

public enum MigrationState {
    INITIALIZED,
    VALIDATING,
    IN_PROGRESS,
    PAUSED,
    ROLLING_BACK,
    COMPLETED,
    FAILED;

    /** Only certain transitions are valid. */
    public boolean canTransitionTo(MigrationState next) {
        switch (this) {
            case INITIALIZED:  return next == VALIDATING || next == FAILED;
            case VALIDATING:   return next == IN_PROGRESS || next == FAILED;
            case IN_PROGRESS:  return next == PAUSED || next == COMPLETED
                                   || next == ROLLING_BACK || next == FAILED;
            case PAUSED:       return next == IN_PROGRESS || next == ROLLING_BACK || next == FAILED;
            case ROLLING_BACK: return next == INITIALIZED || next == FAILED;
            case COMPLETED:
            case FAILED:       return false;          // terminal states
            default:           return false;
        }
    }
}
