package com.migration.model;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

public class MigrationResult {

    private final String migrationId;
    private final Instant startTime;
    private volatile Instant endTime;
    private volatile MigrationState finalState;

    private final AtomicInteger totalProcessed = new AtomicInteger(0);
    private final AtomicInteger successCount   = new AtomicInteger(0);
    private final AtomicInteger failureCount   = new AtomicInteger(0);
    private final AtomicInteger skippedCount   = new AtomicInteger(0);
    private final List<String> errors = Collections.synchronizedList(new ArrayList<>());

    public MigrationResult(String migrationId) {
        this.migrationId = migrationId;
        this.startTime = Instant.now();
    }

    // --- Recording methods (thread-safe) ---
    public void recordSuccess()                { successCount.incrementAndGet(); totalProcessed.incrementAndGet(); }
    public void recordFailure(String error)    { failureCount.incrementAndGet(); totalProcessed.incrementAndGet(); errors.add(error); }
    public void recordSkipped()                { skippedCount.incrementAndGet(); totalProcessed.incrementAndGet(); }

    public void complete(MigrationState state) {
        this.endTime = Instant.now();
        this.finalState = state;
    }

    // --- Getters ---
    public String getMigrationId()     { return migrationId; }
    public Instant getStartTime()      { return startTime; }
    public Instant getEndTime()        { return endTime; }
    public MigrationState getFinalState() { return finalState; }
    public int getTotalProcessed()     { return totalProcessed.get(); }
    public int getSuccessCount()       { return successCount.get(); }
    public int getFailureCount()       { return failureCount.get(); }
    public int getSkippedCount()       { return skippedCount.get(); }
    public List<String> getErrors()    { return Collections.unmodifiableList(errors); }

    public Duration getDuration() {
        Instant end = (endTime != null) ? endTime : Instant.now();
        return Duration.between(startTime, end);
    }

    public double getSuccessRate() {
        int total = totalProcessed.get();
        return total == 0 ? 0.0 : (double) successCount.get() / total * 100.0;
    }

    @Override
    public String toString() {
        return String.format(
            "MigrationResult{id='%s', state=%s, total=%d, success=%d, failed=%d, skipped=%d, rate=%.1f%%, duration=%s}",
            migrationId, finalState, totalProcessed.get(),
            successCount.get(), failureCount.get(), skippedCount.get(),
            getSuccessRate(), getDuration()
        );
    }
}
