// processor/ValidatingProcessor.java
package com.migration.processor;

import com.migration.model.MigrationEvent;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import java.util.logging.Logger;

/**
 * Validates events against registered rules before migration.
 * Returns null (= skip) for invalid events.
 */
public class ValidatingProcessor implements EventProcessor {

    private static final Logger LOG = Logger.getLogger(ValidatingProcessor.class.getName());

    private final List<ValidationRule> rules = new ArrayList<>();

    /** A named predicate — returns true when the event is valid. */
    public record ValidationRule(String name, Predicate<MigrationEvent> predicate) {}

    // --- Fluent rule registration ---

    public ValidatingProcessor addRule(String name, Predicate<MigrationEvent> predicate) {
        rules.add(new ValidationRule(name, predicate));
        return this;
    }

    public ValidatingProcessor requireField(String fieldName) {
        return addRule(
            "required_field:" + fieldName,
            evt -> evt.getPayload().containsKey(fieldName)
                   && evt.getPayload().get(fieldName) != null
        );
    }

    public ValidatingProcessor requireNonEmptyPayload() {
        return addRule("non_empty_payload", evt -> !evt.getPayload().isEmpty());
    }

    // --- Processing ---

    @Override
    public MigrationEvent process(MigrationEvent event) {
        List<String> failures = new ArrayList<>();

        for (ValidationRule rule : rules) {
            if (!rule.predicate().test(event)) {
                failures.add(rule.name());
            }
        }

        if (!failures.isEmpty()) {
            LOG.warning(() -> String.format(
                "Event %s failed validation rules: %s", event.getId(), failures));
            return null;   // signal "skip"
        }

        LOG.fine(() -> "Event " + event.getId() + " passed all validation rules");
        return event;
    }
}
