## Config Parser

```javascript
// src/ConfigParser.js

import { readFile, access, stat } from "node:fs/promises";
import { resolve, dirname, isAbsolute } from "node:path";
import { homedir } from "node:os";
import { parse as parseYAML } from "yaml";
import { EventEmitter } from "node:events";

// ── Schema definitions for validation ────────────────────────────────

const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"];
const VALID_CHECKSUM_ALGOS = ["md5", "sha256", "sha512"];
const VALID_COMPRESSION_ALGOS = ["gzip", "brotli", "none"];
const VALID_CHANGE_DETECTION = ["checksum", "mtime", "size"];
const VALID_HOOK_FAILURE_MODES = ["abort", "warn", "skip"];

const DEFAULTS = Object.freeze({
  global: {
    log_level: "info",
    temp_dir: "/tmp/backups",
    max_concurrent: 2,
    checksum_algorithm: "sha256",
  },
  incremental: {
    enabled: true,
    full_backup_interval: 7,
    manifest_path: ".backup-manifest.json",
    change_detection: "checksum",
  },
  retention: {
    keep_daily: 7,
    keep_weekly: 4,
    keep_monthly: 6,
    max_incremental_chain: 6,
  },
  compression: {
    enabled: true,
    algorithm: "gzip",
    level: 6,
  },
  hook: {
    timeout: 120,
    on_failure: "abort",
  },
});

// ── Validation error ─────────────────────────────────────────────────

class ConfigValidationError extends Error {
  /**
   * @param {string} message
   * @param {string} path    – dotted config path where the error occurred
   * @param {*}      value   – the offending value
   */
  constructor(message, path, value) {
    super(`[${path}] ${message}`);
    this.name = "ConfigValidationError";
    this.configPath = path;
    this.value = value;
  }
}

// ── Main parser class ────────────────────────────────────────────────

class ConfigParser extends EventEmitter {
  #rawConfig = null;
  #parsedConfig = null;
  #configFilePath = null;
  #errors = [];
  #warnings = [];

  constructor() {
    super();
  }

  // ── Public API ───────────────────────────────────────────────────

  /**
   * Load + parse + validate a YAML (or JSON) config file.
   * Returns the fully‑resolved configuration object.
   */
  async loadFromFile(filePath) {
    this.#configFilePath = resolve(filePath);
    this.#errors = [];
    this.#warnings = [];

    const raw = await this.#readConfigFile(this.#configFilePath);
    this.#rawConfig = this.#parseRawContent(raw, this.#configFilePath);
    this.#parsedConfig = this.#validate(this.#rawConfig);

    if (this.#errors.length > 0) {
      const summary = this.#errors.map((e) => e.message).join("\n  • ");
      throw new ConfigValidationError(
        `Config validation failed with ${this.#errors.length} error(s):\n  • ${summary}`,
        "root",
        null
      );
    }

    this.emit("loaded", this.#parsedConfig);
    return this.#parsedConfig;
  }

  /** Parse a plain object (useful in tests). */
  loadFromObject(obj) {
    this.#errors = [];
    this.#warnings = [];
    this.#rawConfig = obj;
    this.#parsedConfig = this.#validate(obj);

    if (this.#errors.length > 0) {
      const summary = this.#errors.map((e) => e.message).join("\n  • ");
      throw new ConfigValidationError(
        `Config validation failed with ${this.#errors.length} error(s):\n  • ${summary}`,
        "root",
        null
      );
    }

    return this.#parsedConfig;
  }

  /** Retrieve a single profile by name (post‑validation). */
  getProfile(name) {
    if (!this.#parsedConfig) {
      throw new Error("Config not loaded – call loadFromFile first");
    }
    const profile = this.#parsedConfig.profiles.get(name);
    if (!profile) {
      throw new Error(
        `Profile "${name}" not found. Available: ${[...this.#parsedConfig.profiles.keys()].join(", ")}`
      );
    }
    return profile;
  }

  /** All enabled profiles. */
  getEnabledProfiles() {
    if (!this.#parsedConfig) {
      throw new Error("Config not loaded");
    }
    return [...this.#parsedConfig.profiles.entries()]
      .filter(([, p]) => p.enabled)
      .map(([name, profile]) => ({ name, ...profile }));
  }

  get errors() {
    return [...this.#errors];
  }
  get warnings() {
    return [...this.#warnings];
  }
  get config() {
    return this.#parsedConfig;
  }

  // ── File reading ─────────────────────────────────────────────────

  async #readConfigFile(absPath) {
    try {
      await access(absPath);
    } catch {
      throw new Error(`Config file not found: ${absPath}`);
    }

    const info = await stat(absPath);
    if (info.size > 1024 * 1024) {
      throw new Error("Config file exceeds 1 MB limit");
    }

    return readFile(absPath, "utf-8");
  }

  // ── Raw parsing (YAML / JSON) ───────────────────────────────────

  #parseRawContent(content, filePath) {
    const ext = filePath.split(".").pop().toLowerCase();

    try {
      if (ext === "json") return JSON.parse(content);
      // default → YAML
      return parseYAML(content);
    } catch (err) {
      throw new Error(`Failed to parse config (${ext}): ${err.message}`);
    }
  }

  // ── Top‑level validation orchestrator ────────────────────────────

  #validate(raw) {
    if (!raw || typeof raw !== "object") {
      this.#addError("root", "Config must be a non‑null object", raw);
      return null;
    }

    const globalCfg = this.#validateGlobal(raw.global);
    const profiles = this.#validateProfiles(raw.profiles, globalCfg);
    const notifications = this.#validateNotifications(raw.notifications);

    return Object.freeze({ global: globalCfg, profiles, notifications });
  }

  // ── Global section ───────────────────────────────────────────────

  #validateGlobal(raw) {
    const g = { ...DEFAULTS.global, ...(raw ?? {}) };

    if (!VALID_LOG_LEVELS.includes(g.log_level)) {
      this.#addError("global.log_level", `Must be one of ${VALID_LOG_LEVELS}`, g.log_level);
    }

    if (!VALID_CHECKSUM_ALGOS.includes(g.checksum_algorithm)) {
      this.#addError(
        "global.checksum_algorithm",
        `Must be one of ${VALID_CHECKSUM_ALGOS}`,
        g.checksum_algorithm
      );
    }

    g.max_concurrent = this.#expectPositiveInt("global.max_concurrent", g.max_concurrent, 2);
    g.temp_dir = this.#resolvePath(g.temp_dir);

    return Object.freeze(g);
  }

  // ── Profiles section ─────────────────────────────────────────────

  #validateProfiles(raw, globalCfg) {
    const profiles = new Map();

    if (!raw || typeof raw !== "object") {
      this.#addError("profiles", "At least one backup profile is required", raw);
      return profiles;
    }

    for (const [name, def] of Object.entries(raw)) {
      const prefix = `profiles.${name}`;
      const profile = this.#validateSingleProfile(prefix, def, globalCfg);
      if (profile) profiles.set(name, Object.freeze(profile));
    }

    if (profiles.size === 0) {
      this.#addWarning("profiles", "No valid profiles found");
    }

    return profiles;
  }

  #validateSingleProfile(prefix, raw, globalCfg) {
    if (!raw || typeof raw !== "object") {
      this.#addError(prefix, "Profile must be an object", raw);
      return null;
    }

    // Required fields
    if (!raw.source) {
      this.#addError(`${prefix}.source`, "source is required", raw.source);
    }
    if (!raw.destination) {
      this.#addError(`${prefix}.destination`, "destination is required", raw.destination);
    }

    return {
      enabled: raw.enabled !== false,
      source: this.#resolvePath(raw.source ?? ""),
      destination: this.#resolvePath(raw.destination ?? ""),
      schedule: this.#validateCron(`${prefix}.schedule`, raw.schedule),
      incremental: this.#validateIncremental(`${prefix}.incremental`, raw.incremental),
      retention: this.#validateRetention(`${prefix}.retention`, raw.retention),
      exclude: this.#validateGlobs(`${prefix}.exclude`, raw.exclude),
      include: this.#validateGlobs(`${prefix}.include`, raw.include),
      compression: this.#validateCompression(`${prefix}.compression`, raw.compression),
      preHooks: this.#validateHooks(`${prefix}.pre_hooks`, raw.pre_hooks),
      postHooks: this.#validateHooks(`${prefix}.post_hooks`, raw.post_hooks),
    };
  }

  // ── Incremental sub‑section ──────────────────────────────────────

  #validateIncremental(prefix, raw) {
    const inc = { ...DEFAULTS.incremental, ...(raw ?? {}) };

    if (typeof inc.enabled !== "boolean") {
      this.#addError(`${prefix}.enabled`, "Must be boolean", inc.enabled);
      inc.enabled = true;
    }

    inc.full_backup_interval = this.#expectPositiveInt(
      `${prefix}.full_backup_interval`,
      inc.full_backup_interval,
      7
    );

    if (!VALID_CHANGE_DETECTION.includes(inc.change_detection)) {
      this.#addError(
        `${prefix}.change_detection`,
        `Must be one of ${VALID_CHANGE_DETECTION}`,
        inc.change_detection
      );
      inc.change_detection = "checksum";
    }

    return Object.freeze(inc);
  }

  // ── Retention sub‑section ────────────────────────────────────────

  #validateRetention(prefix, raw) {
    const ret = { ...DEFAULTS.retention, ...(raw ?? {}) };

    for (const key of ["keep_daily", "keep_weekly", "keep_monthly", "max_incremental_chain"]) {
      ret[key] = this.#expectNonNegativeInt(`${prefix}.${key}`, ret[key], DEFAULTS.retention[key]);
    }

    if (ret.max_incremental_chain === 0) {
      this.#addWarning(
        `${prefix}.max_incremental_chain`,
        "Value 0 means every backup will be a full backup"
      );
    }

    return Object.freeze(ret);
  }

  // ── Compression sub‑section ──────────────────────────────────────

  #validateCompression(prefix, raw) {
    const comp = { ...DEFAULTS.compression, ...(raw ?? {}) };

    if (!VALID_COMPRESSION_ALGOS.includes(comp.algorithm)) {
      this.#addError(
        `${prefix}.algorithm`,
        `Must be one of ${VALID_COMPRESSION_ALGOS}`,
        comp.algorithm
      );
      comp.algorithm = "gzip";
    }

    if (typeof comp.level !== "number" || comp.level < 1 || comp.level > 9) {
      this.#addWarning(`${prefix}.level`, `Clamping to 1–9 range (was ${comp.level})`);
      comp.level = Math.max(1, Math.min(9, Number(comp.level) || 6));
    }

    return Object.freeze(comp);
  }

  // ── Hooks ────────────────────────────────────────────────────────

  #validateHooks(prefix, raw) {
    if (!raw) return Object.freeze([]);
    if (!Array.isArray(raw)) {
      this.#addError(prefix, "Hooks must be an array", raw);
      return Object.freeze([]);
    }

    return Object.freeze(
      raw.map((hook, i) => {
        const p = `${prefix}[${i}]`;
        if (!hook.command) {
          this.#addError(`${p}.command`, "command is required", hook);
        }
