          ? hook.on_failure
          : DEFAULTS.hook.on_failure;

        return Object.freeze({
          command: hook.command ?? "",
          timeout: this.#expectPositiveInt(`${p}.timeout`, hook.timeout, DEFAULTS.hook.timeout),
          on_failure,
        });
      })
    );
  }

  // ── Notifications ────────────────────────────────────────────────

  #validateNotifications(raw) {
    if (!raw) return Object.freeze({ on_success: false, on_failure: true, channels: [] });

    const channels = [];

    if (raw.email?.enabled) {
