import { EventEmitter } from "node:events";
import logger from "./logger.js";

const State = Object.freeze({
  CLOSED: "CLOSED",
  OPEN: "OPEN",
  HALF_OPEN: "HALF_OPEN",
});

export default class CircuitBreaker extends EventEmitter {
  #state = State.CLOSED;
  #failureCount = 0;
  #successCount = 0;
  #lastFailureTime = 0;
  #options;

  /**
   * @param {Object} options
   * @param {number} options.failureThreshold - Failures before opening
   * @param {number} options.resetTimeoutMs   - Ms before half-open attempt
   * @param {number} options.halfOpenMax      - Successes to close again
   */
  constructor(options = {}) {
    super();
    this.#options = {
      failureThreshold: options.failureThreshold ?? 5,
      resetTimeoutMs: options.resetTimeoutMs ?? 30_000,
      halfOpenMax: options.halfOpenMax ?? 3,
    };
  }

  get state() {
    return this.#state;
  }

  /**
   * Execute a function through the circuit breaker.
   * @param {() => Promise<T>} fn
   * @returns {Promise<T>}
   */
  async execute(fn) {
    if (this.#state === State.OPEN) {
      if (Date.now() - this.#lastFailureTime >= this.#options.resetTimeoutMs) {
        this.#transitionTo(State.HALF_OPEN);
      } else {
        throw new Error("Circuit breaker is OPEN – request rejected");
      }
    }

    try {
      const result = await fn();
      this.#onSuccess();
      return result;
    } catch (error) {
      this.#onFailure();
      throw error;
    }
  }

  #onSuccess() {
    this.#failureCount = 0;
    if (this.#state === State.HALF_OPEN) {
      this.#successCount += 1;
      if (this.#successCount >= this.#options.halfOpenMax) {
        this.#transitionTo(State.CLOSED);
      }
    }
  }

  #onFailure() {
    this.#failureCount += 1;
    this.#lastFailureTime = Date.now();
    if (
      this.#state === State.HALF_OPEN ||
      this.#failureCount >= this.#options.failureThreshold
    ) {
      this.#transitionTo(State.OPEN);
    }
  }

  #transitionTo(newState) {
    const prev = this.#state;
    this.#state = newState;
    if (newState === State.CLOSED) {
      this.#failureCount = 0;
      this.#successCount = 0;
    }
    if (newState === State.HALF_OPEN) {
      this.#successCount = 0;
    }
    logger.info({ prev, current: newState }, "Circuit breaker state change");
    this.emit("stateChange", { prev, current: newState });
  }
}
