```javascript
import logger from "../../utils/logger.js";
import metrics from "../../utils/metrics.js";
import config from "../../config.js";

export default class JsonParser {
  #maxSizeBytes;

  constructor() {
    this.#maxSizeBytes = config.processing.maxLogSizeBytes;
  }

  /**
   * Parse raw input into an array of log objects.
   * Supports:
   *   - single JSON object
   *   - JSON array of objects
   *   - newline-delimited JSON (NDJSON)
   *
   * @param {string|Buffer} raw
   * @returns {{ logs: object[], errors: Error[] }}
   */
  parse(raw) {
    const input = Buffer.isBuffer(raw) ? raw.toString("utf-8") : raw;
    const logs = [];
    const errors = [];

    if (input.length > this.#maxSizeBytes) {
      metrics.increment("parser.oversized");
      errors.push(
        new Error(
          `Input exceeds max size: ${input.length} > ${this.#maxSizeBytes}`
        )
      );
      return { logs, errors };
    }

    const trimmed = input.trim();

    if (trimmed.length === 0) {
      return { logs, errors };
    }

    // Try single JSON object or array first
    if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
      try {
        const parsed = JSON.parse(trimmed);
        if (Array.isArray(parsed)) {
          for (let i = 0; i < parsed.length; i++) {
            if (this.#isPlainObject(parsed[i])) {
              logs.push(parsed[i]);
            } else {
              errors.push(
                new Error(`Array element [${i}] is not a JSON object`)
              );
            }
          }
        } else if (this.#isPlainObject(parsed)) {
          logs.push(parsed);
        } else {
          errors.push(new Error("Parsed JSON is not an object or array"));
        }
        metrics.increment("parser.success", logs.length);
        return { logs, errors };
      } catch {
        // Fall through to NDJSON parsing
      }
    }

    // NDJSON: one JSON object per line
    const lines = trimmed.split(/\r?\n/);
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (line.length === 0) continue;

      try {
        const parsed = JSON.parse(line);
        if (this.#isPlainObject(parsed)) {
          logs.push(parsed);
        } else {
          errors.push(
            new Error(`Line ${i + 1}: parsed value is not a JSON object`)
          );
        }
      } catch (err) {
        errors.push(new Error(`Line ${i + 1}: ${err.message}`));
        metrics.increment("parser.line_error");
      }
    }

    metrics.increment("parser.success", logs.length);
    metrics.increment("parser.error", errors.length);

    if (errors.length > 0) {
      logger.warn({ errorCount: errors.length }, "Parse errors encountered");
    }

    return { logs, errors };
  }

  #isPlainObject(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
  }
}
