// Flexible schema: requires at least a message or level
const LOG_SCHEMA = {
  type: "object",
  properties: {
    timestamp: { type: "string" },
    level: {
      type: "string",
      enum: [
        "trace",
        "debug",
        "info",
        "warn",
        "error",
        "fatal",
        "TRACE",
        "DEBUG",
        "INFO",
        "WARN",
        "ERROR",
        "FATAL",
      ],
    },
    message: { type: "string", maxLength: 32_768 },
    service: { type: "string", maxLength: 256 },
    host: { type: "string", maxLength: 256 },
    traceId: { type: "string", maxLength: 128 },
    spanId: { type: "string", maxLength: 128 },
    metadata: { type: "object" },
  },
  anyOf: [{ required: ["message"] }, { required: ["msg"] }, { required: ["level"] }],
  additionalProperties: true,
};

export default class LogValidator {
  #validate;

  constructor(schema = LOG_SCHEMA) {
    const ajv = new Ajv({ allErrors: true, coerceTypes: false });
    addFormats(ajv);
    this.#validate = ajv.compile(schema);
  }

  /**
   * Validate a single log entry.
   * @param {object} log
   * @returns {{ valid: boolean, errors: string[] | null }}
   */
  validate(log) {
    const valid = this.#validate(log);

    if (!valid) {
      const errors = this.#validate.errors.map(
        (e) => `${e.instancePath || "/"} ${e.message}`
      );
      metrics.increment("validator.rejected");
      logger.debug({ errors }, "Log validation failed");
      return { valid: false, errors };
    }

    metrics.increment("validator.accepted");
    return { valid: true, errors: null };
  }

  /**
   * Validate a batch; returns accepted and rejected lists.
   * @param {object[]} logs
   * @returns {{ accepted: object[], rejected: { log: object, errors: string[] }[] }}
   */
  validateBatch(logs) {
    const accepted = [];
    const rejected = [];

    for (const log of logs) {
      const result = this.validate(log);
      if (result.valid) {
        accepted.push(log);
      } else {
        rejected.push({ log, errors: result.errors });
      }
    }

    return { accepted, rejected };
  }
}
