import { createInterface } from "node:readline";
import { EventEmitter } from "node:events";
import logger from "../../utils/logger.js";
import metrics from "../../utils/metrics.js";

export default class StdinSource extends EventEmitter {
  #rl = null;
  #buffer = "";
  #running = false;

  async start() {
    if (this.#running) return;
    this.#running = true;

    logger.info("Starting stdin source");

    this.#rl = createInterface({
      input: process.stdin,
      crlfDelay: Infinity,
    });

    this.#rl.on("line", (line) => {
      metrics.increment("source.stdin.lines_read");
      this.emit("data", line);
    });

    this.#rl.on("close", () => {
      logger.info("Stdin stream closed");
      this.emit("end");
    });

    this.#rl.on("error", (err) => {
      logger.error({ err }, "Stdin read error");
      metrics.increment("source.stdin.errors");
      this.emit("error", err);
    });
  }

  async stop() {
    if (!this.#running) return;
    this.#running = false;
    this.#rl?.close();
    logger.info("Stdin source stopped");
  }
}
