# Analytics Pipeline with Retry Handling in C++

```cpp
#include <iostream>
#include <functional>
#include <vector>
#include <string>
#include <chrono>
#include <thread>
#include <stdexcept>
#include <variant>
#include <unordered_map>
#include <sstream>
#include <random>
#include <optional>

// ---------------------------------------------------------------------------
// Data record flowing through the pipeline
// ---------------------------------------------------------------------------
struct Record {
    int id;
    std::unordered_map<std::string, std::string> fields;

    std::string toString() const {
        std::ostringstream oss;
        oss << "Record{id=" << id << ", fields={";
        bool first = true;
        for (const auto& [k, v] : fields) {
            if (!first) oss << ", ";
            oss << k << ": " << v;
            first = false;
        }
        oss << "}}";
        return oss.str();
    }
};

using Batch = std::vector<Record>;

// ---------------------------------------------------------------------------
// Retry configuration
// ---------------------------------------------------------------------------
struct RetryPolicy {
    int    maxAttempts      = 3;
    int    baseDelayMs      = 100;      // milliseconds
    double backoffMultiplier = 2.0;
    int    maxDelayMs       = 5000;

    int delayForAttempt(int attempt) const {
        double delay = baseDelayMs * std::pow(backoffMultiplier, attempt);
        return std::min(static_cast<int>(delay), maxDelayMs);
    }
};

// ---------------------------------------------------------------------------
// Result of executing a pipeline stage
// ---------------------------------------------------------------------------
struct StageResult {
    bool        success;
    std::string error;
    int         attempts;
};

// ---------------------------------------------------------------------------
// A single pipeline stage: name + processing function + retry policy
// ---------------------------------------------------------------------------
class PipelineStage {
public:
    using ProcessFn = std::function<Batch(const Batch&)>;

    PipelineStage(std::string name, ProcessFn fn, RetryPolicy policy = {})
        : name_(std::move(name))
        , processFn_(std::move(fn))
        , retryPolicy_(policy)
    {}

    // Run the stage with retries; returns processed batch on success
    std::pair<std::optional<Batch>, StageResult> execute(const Batch& input) const {
        for (int attempt = 0; attempt < retryPolicy_.maxAttempts; ++attempt) {
            try {
                if (attempt > 0) {
                    int delayMs = retryPolicy_.delayForAttempt(attempt - 1);
                    std::cout << "  [" << name_ << "] retry #" << attempt
                              << " after " << delayMs << " ms\n";
                    std::this_thread::sleep_for(
                        std::chrono::milliseconds(delayMs));
                }

                Batch result = processFn_(input);
                return {result, {true, "", attempt + 1}};

            } catch (const std::exception& ex) {
                std::cout << "  [" << name_ << "] attempt " << (attempt + 1)
                          << " failed: " << ex.what() << "\n";

                if (attempt + 1 == retryPolicy_.maxAttempts) {
                    return {std::nullopt,
                            {false, ex.what(), attempt + 1}};
                }
            }
        }
        // Should never reach here
        return {std::nullopt, {false, "unknown", retryPolicy_.maxAttempts}};
    }

    const std::string& name() const { return name_; }

private:
    std::string  name_;
    ProcessFn    processFn_;
    RetryPolicy  retryPolicy_;
};

// ---------------------------------------------------------------------------
// The pipeline: a chain of stages executed sequentially
// ---------------------------------------------------------------------------
class AnalyticsPipeline {
public:
    explicit AnalyticsPipeline(std::string name)
        : name_(std::move(name)) {}

    void addStage(PipelineStage stage) {
        stages_.push_back(std::move(stage));
    }

    bool run(const Batch& input) {
        std::cout << "=== Pipeline [" << name_ << "] started with "
                  << input.size() << " records ===\n\n";

        Batch current = input;

        for (size_t i = 0; i < stages_.size(); ++i) {
            const auto& stage = stages_[i];
            std::cout << "--- Stage " << (i + 1) << "/" << stages_.size()
                      << ": " << stage.name() << " ---\n";

            auto [result, status] = stage.execute(current);

            if (!status.success) {
                std::cout << "\n*** Pipeline FAILED at stage \""
                          << stage.name() << "\" after "
                          << status.attempts << " attempts: "
                          << status.error << " ***\n";
                return false;
            }

            current = std::move(*result);
            std::cout << "  [" << stage.name() << "] succeeded after "
                      << status.attempts << " attempt(s) — "
                      << current.size() << " records output\n\n";
        }

        std::cout << "=== Pipeline [" << name_
                  << "] completed successfully ===\n";
        return true;
    }

private:
    std::string name_;
    std::vector<PipelineStage> stages_;
};

// ---------------------------------------------------------------------------
// Helper: create a function that fails N times then succeeds
// (simulates transient errors like network hiccups)
// ---------------------------------------------------------------------------
auto makeFlaky(int failCount, std::string tag, PipelineStage::ProcessFn inner)
    -> PipelineStage::ProcessFn
{
    // Shared mutable counter captured by value in a shared_ptr
    auto counter = std::make_shared<int>(0);
    return [=](const Batch& batch) -> Batch {
        if ((*counter)++ < failCount) {
            throw std::runtime_error(tag + " transient error");
        }
        return inner(batch);
    };
}

// ---------------------------------------------------------------------------
// Example stage implementations
// ---------------------------------------------------------------------------

// 1. Ingest: pass‑through (could read from file / Kafka / etc.)
Batch ingest(const Batch& batch) {
    return batch; // identity — data already provided
}

// 2. Clean: drop records with missing "value" field, trim whitespace
Batch clean(const Batch& batch) {
    Batch out;
    for (auto& rec : batch) {
        if (rec.fields.count("value") && !rec.fields.at("value").empty()) {
            out.push_back(rec);
        }
    }
    return out;
}

// 3. Transform: parse "value" → int, double it, store as "result"
Batch transform(const Batch& batch) {
    Batch out;
    for (auto rec : batch) {
        int val = std::stoi(rec.fields.at("value"));
        rec.fields["result"] = std::to_string(val * 2);
        out.push_back(std::move(rec));
    }
    return out;
}

// 4. Aggregate: sum all "result" fields into a single summary record
Batch aggregate(const Batch& batch) {
    long long sum = 0;
    for (const auto& rec : batch) {
        sum += std::stoll(rec.fields.at("result"));
    }
    Record summary;
    summary.id = 0;
    summary.fields["total"] = std::to_string(sum);
    summary.fields["count"] = std::to_string(batch.size());
    return {summary};
}

// 5. Export: "write" results (print to stdout)
Batch exportResults(const Batch& batch) {
    std::cout << "  >> Export output:\n";
    for (const auto& rec : batch) {
        std::cout << "     " << rec.toString() << "\n";
    }
    return batch;
}

// ---------------------------------------------------------------------------
// Main — wire up and run the pipeline
// ---------------------------------------------------------------------------
int main() {
    // --- Build sample data ---
    Batch data = {
        {1, {{"user", "alice"}, {"value", "10"}}},
        {2, {{"user", "bob"},   {"value", ""}}},       // missing value → filtered
        {3, {{"user", "carol"}, {"value", "30"}}},
        {4, {{"user", "dave"},  {"value", "20"}}},
        {5, {{"user", "eve"}}},                         // no "value" key → filtered
    };

    // --- Configure retry policies per stage ---
    RetryPolicy defaultPolicy{3, 100, 2.0, 5000};
    RetryPolicy aggressivePolicy{5, 50, 1.5, 3000};

    // --- Build pipeline ---
    AnalyticsPipeline pipeline("daily-user-stats");

    pipeline.addStage({"Ingest",    ingest,        defaultPolicy});
    pipeline.addStage({"Clean",     clean,         defaultPolicy});

    // Simulate a flaky transform (fails twice, then succeeds)
    pipeline.addStage({"Transform",
                       makeFlaky(2, "Transform", transform),
                       aggressivePolicy});

    pipeline.addStage({"Aggregate", aggregate,     defaultPolicy});
    pipeline.addStage({"Export",    exportResults,  defaultPolicy});

    // --- Run ---
    bool ok = pipeline.run(data);

    std::cout << "\nExit status: " << (ok ? "SUCCESS" : "FAILURE") << "\n";
    return ok ? 0 : 1;
}
```

## How It Works

```
┌────────┐    ┌───────┐    ┌───────────┐    ┌───────────┐    ┌────────┐
│ Ingest │───▶│ Clean │───▶│ Transform │───▶│ Aggregate │───▶│ Export │
└────────┘    └───────┘    └───────────┘    └───────────┘    └────────┘
                             fails twice        sums all        prints
                             then succeeds      "result"s       output
```

## Key Design Points

| Component | Purpose |
|---|---|
| **`RetryPolicy`** | Configurable max attempts, base delay, exponential backoff multiplier, and max delay cap |
| **`PipelineStage`** | Wraps any `std::function<Batch(Batch)>` with retry logic and reports success/failure |
| **`AnalyticsPipeline`** | Chains stages sequentially — stops on first permanent failure |
| **`makeFlaky()`** | Test helper that simulates transient failures (network timeouts, etc.) |
| **Backoff formula** | `delay = baseDelay × multiplier^attempt`, capped at `maxDelayMs` |

## Sample Output

```
=== Pipeline [daily-user-stats] started with 5 records ===

--- Stage 1/5: Ingest ---
  [Ingest] succeeded after 1 attempt(s) — 5 records output

--- Stage 2/5: Clean ---
  [Clean] succeeded after 1 attempt(s) — 3 records output

--- Stage 3/5: Transform ---
  [Transform] attempt 1 failed: Transform transient error
  [Transform] retry #1 after 50 ms
  [Transform] attempt 2 failed: Transform transient error
  [Transform] retry #2 after 75 ms
  [Transform] succeeded after 3 attempt(s) — 3 records output

--- Stage 4/5: Aggregate ---
  [Aggregate] succeeded after 1 attempt(s) — 1 records output

--- Stage 5/5: Export ---
  >> Export output:
     Record{id=0, fields={count: 3, total: 120}}
  [Export] succeeded after 1 attempt(s) — 1 records output

=== Pipeline [daily-user-stats] completed successfully ===

Exit status: SUCCESS
```

## Extending This

- **Parallel stages** — replace sequential loop with `std::async` fan-out
- **Dead-letter queue** — collect failed records instead of aborting the whole pipeline
- **Circuit breaker** — stop retrying if error rate exceeds a threshold
- **Metrics** — track latency/throughput per stage via `std::chrono` timestamps

# Simple JSON Document Parser in Swift

## Basic JSON Parser

```swift
import Foundation

// MARK: - Models

struct Document: Codable {
    let title: String
    let author: String
    let pages: Int
    let tags: [String]
    let metadata: Metadata?
}

struct Metadata: Codable {
    let createdAt: String
    let version: Double
    let isPublished: Bool

    enum CodingKeys: String, CodingKey {
        case createdAt = "created_at"
        case version
        case isPublished = "is_published"
    }
}

// MARK: - JSON Parser

class JSONDocumentParser {

    // Parse JSON string into a Document
    func parse(jsonString: String) -> Document? {
        guard let data = jsonString.data(using: .utf8) else {
            print("❌ Error: Could not convert string to data")
            return nil
        }
        return parse(data: data)
    }

    // Parse JSON Data into a Document
    func parse(data: Data) -> Document? {
        let decoder = JSONDecoder()
        do {
            let document = try decoder.decode(Document.self, from: data)
            return document
        } catch let DecodingError.keyNotFound(key, context) {
            print("❌ Missing key: '\(key.stringValue)' — \(context.debugDescription)")
        } catch let DecodingError.typeMismatch(type, context) {
            print("❌ Type mismatch: expected \(type) — \(context.debugDescription)")
        } catch let DecodingError.valueNotFound(type, context) {
            print("❌ Missing value: expected \(type) — \(context.debugDescription)")
        } catch {
            print("❌ Decoding error: \(error.localizedDescription)")
        }
        return nil
    }

    // Parse JSON file from disk
    func parse(fileAtPath path: String) -> Document? {
        guard FileManager.default.fileExists(atPath: path) else {
            print("❌ File not found at: \(path)")
            return nil
        }
        do {
            let data = try Data(contentsOf: URL(fileURLWithPath: path))
            return parse(data: data)
        } catch {
            print("❌ File read error: \(error.localizedDescription)")
            return nil
        }
    }

    // Parse a JSON array of documents
    func parseArray(jsonString: String) -> [Document]? {
        guard let data = jsonString.data(using: .utf8) else { return nil }
        let decoder = JSONDecoder()
        do {
            return try decoder.decode([Document].self, from: data)
        } catch {
            print("❌ Array decoding error: \(error.localizedDescription)")
            return nil
        }
    }

    // Parse raw JSON into a dictionary (untyped)
    func parseRaw(jsonString: String) -> [String: Any]? {
        guard let data = jsonString.data(using: .utf8) else { return nil }
        do {
            let json = try JSONSerialization.jsonObject(with: data) as? [String: Any]
            return json
        } catch {
            print("❌ Raw parsing error: \(error.localizedDescription)")
            return nil
        }
    }
}

// MARK: - Pretty Print Helper

extension Document: CustomStringConvertible {
    var description: String {
        """
        📄 Document
           Title:     \(title)
           Author:    \(author)
           Pages:     \(pages)
           Tags:      \(tags.joined(separator: ", "))
           Published: \(metadata?.isPublished ?? false)
           Version:   \(metadata?.version ?? 0.0)
        """
    }
}

// MARK: - Usage

let sampleJSON = """
{
    "title": "Swift Programming Guide",
    "author": "Jane Doe",
    "pages": 350,
    "tags": ["swift", "ios", "programming"],
    "metadata": {
        "created_at": "2024-01-15",
        "version": 2.1,
        "is_published": true
    }
}
"""

let sampleArrayJSON = """
[
    {
        "title": "Book One",
        "author": "Author A",
        "pages": 200,
        "tags": ["fiction"],
        "metadata": null
    },
    {
        "title": "Book Two",
        "author": "Author B",
        "pages": 150,
        "tags": ["science", "research"],
        "metadata": {
            "created_at": "2024-06-01",
            "version": 1.0,
            "is_published": false
        }
    }
]
"""

let parser = JSONDocumentParser()

// 1. Parse single document
print("=== Single Document ===")
if let doc = parser.parse(jsonString: sampleJSON) {
    print(doc)
}

// 2. Parse array of documents
print("\n=== Document Array ===")
if let docs = parser.parseArray(jsonString: sampleArrayJSON) {
    docs.forEach { print($0) }
}

// 3. Parse raw JSON (untyped)
print("\n=== Raw Dictionary ===")
if let raw = parser.parseRaw(jsonString: sampleJSON) {
    raw.forEach { print("  \($0.key): \($0.value)") }
}

// 4. Handle bad input gracefully
print("\n=== Error Handling ===")
let badJSON = """
{ "title": 123, "author": "Test", "pages": "not_a_number", "tags": [] }
"""
let _ = parser.parse(jsonString: badJSON)
