```javascript
/**
 * Custom error class for document parsing failures.
 * Provides structured error information including line/column positions.
 */
class ParseError extends Error {
  /**
   * @param {string} message - Human-readable error description
   * @param {Object} [options={}]
   * @param {number} [options.line] - Line number where error occurred (1-based)
   * @param {number} [options.column] - Column number where error occurred (1-based)
   * @param {string} [options.source] - Source format that failed to parse
   * @param {string} [options.snippet] - Code snippet near the error
   * @param {Error} [options.cause] - Original error that caused this failure
   */
  constructor(message, options = {}) {
    const { line, column, source, snippet, cause } = options;

    let fullMessage = `[ParseError]`;
    if (source) fullMessage += ` (${source})`;
    if (line != null) {
      fullMessage += ` at line ${line}`;
      if (column != null) fullMessage += `, column ${column}`;
    }
    fullMessage += `: ${message}`;
    if (snippet) fullMessage += `\n  → ${snippet}`;

    super(fullMessage);

    this.name = 'ParseError';
    this.line = line ?? null;
    this.column = column ?? null;
    this.source = source ?? null;
    this.snippet = snippet ?? null;
    this.cause = cause ?? null;
  }

  /**
   * Serializes the error to a plain object for logging/transport.
   * @returns {Object}
   */
  toJSON() {
    return {
      name: this.name,
      message: this.message,
      line: this.line,
      column: this.column,
      source: this.source,
      snippet: this.snippet,
      stack: this.stack
    };
  }
}

module.exports = ParseError;
