/**
 * Input validation utilities for the document parser.
 * All validators throw descriptive errors on invalid input.
 */

const ParseError = require('../errors/ParseError');

/**
 * Validates that input is a non-empty string.
 * @param {*} input - Value to validate
 * @param {string} [context='input'] - Description for error messages
 * @returns {string} Trimmed input string
 * @throws {ParseError} If input is not a valid string
 */
function validateStringInput(input, context = 'input') {
  if (input === null || input === undefined) {
    throw new ParseError(`${context} must not be null or undefined`);
  }

  if (typeof input !== 'string') {
    throw new ParseError(
      `${context} must be a string, received ${typeof input}`
    );
  }

  if (input.trim().length === 0) {
    throw new ParseError(`${context} must not be empty or whitespace-only`);
  }

  return input;
}

/**
 * Validates parser options object.
 * @param {*} options - Options to validate
 * @param {Object} schema - Schema mapping keys to expected types
 * @returns {Object} Validated options
 * @throws {ParseError} If options are invalid
 */
function validateOptions(options, schema) {
  if (options === null || options === undefined) {
    return {};
  }

  if (typeof options !== 'object' || Array.isArray(options)) {
    throw new ParseError('Options must be a plain object');
  }

  const validated = {};

  for (const [key, value] of Object.entries(options)) {
    if (!(key in schema)) {
      continue; // Ignore unknown options
    }

    const expectedType = schema[key];
    const actualType = Array.isArray(value) ? 'array' : typeof value;

    if (actualType !== expectedType) {
      throw new ParseError(
        `Option "${key}" must be of type ${expectedType}, received ${actualType}`
      );
    }

    validated[key] = value;
  }

  return validated;
}

/**
 * Checks if a value is a plain object (not an array, null, etc.).
 * @param {*} value
 * @returns {boolean}
 */
function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

module.exports = {
  validateStringInput,
  validateOptions,
  isPlainObject
};
