/**
 * Abstract base class for all document parsers.
 * Provides common interface, timing, and error handling.
 */
class BaseParser {
  /**
   * @param {string} formatName - Name of the format this parser handles
   */
  constructor(formatName) {
    if (new.target === BaseParser) {
      throw new Error('BaseParser is abstract and cannot be instantiated directly');
    }

    this.formatName = formatName;
  }

  /**
   * Parse a document string into a structured result.
   * Wraps _doParse with timing and standardized output.
   *
   * @param {string} input - Raw document string
   * @param {Object} [options={}] - Parser-specific options
   * @returns {Object} Parsed result with metadata
   */
  parse(input, options = {}) {
    const startTime = performance.now();

    const data = this._doParse(input, options);

    const endTime = performance.now();

    return {
      success: true,
      format: this.formatName,
      data,
      metadata: {
        parseTimeMs: Math.round((endTime - startTime) * 100) / 100,
        inputLength: input.length,
        lineCount: input.split('\n').length
      }
    };
  }

  /**
   * Template method — subclasses must implement parsing logic.
   * @abstract
   * @param {string} input
   * @param {Object} options
   * @returns {*} Parsed data
   */
  _doParse(input, options) {
    throw new Error(`_doParse() must be implemented by ${this.constructor.name}`);
  }

  /**
   * Checks whether this parser can likely handle the given input.
   * @abstract
   * @param {string} input
   * @returns {boolean}
   */
  canParse(input) {
    throw new Error(`canParse() must be implemented by ${this.constructor.name}`);
  }
}

module.exports = BaseParser;
