const BaseParser = require('./BaseParser');
const ParseError = require('../errors/ParseError');
const { validateStringInput, validateOptions } = require('../utils/validators');

/**
 * Parses JSON documents with enhanced error reporting.
 * Supports options for comment stripping and trailing comma removal.
 */
class JSONParser extends BaseParser {
  constructor() {
    super('json');
  }

  static OPTIONS_SCHEMA = {
    allowComments: 'boolean',
    allowTrailingCommas: 'boolean',
    reviver: 'function'
  };

  /**
   * @param {string} input - JSON string to parse
   * @param {Object} [options={}]
   * @param {boolean} [options.allowComments=false] - Strip // and block comments
   * @param {boolean} [options.allowTrailingCommas=false] - Remove trailing commas
   * @param {Function} [options.reviver] - JSON.parse reviver function
   * @returns {*} Parsed JSON value
   * @throws {ParseError}
   */
  _doParse(input, options = {}) {
    validateStringInput(input, 'JSON input');
    const opts = validateOptions(options, JSONParser.OPTIONS_SCHEMA);

    let processed = input;

    if (opts.allowComments) {
      processed = this._stripComments(processed);
    }

    if (opts.allowTrailingCommas) {
      processed = this._removeTrailingCommas(processed);
    }

    try {
      return JSON.parse(processed, opts.reviver);
    } catch (err) {
      const { line, column, snippet } = this._locateError(input, err);
      throw new ParseError('Invalid JSON', {
        line,
        column,
        source: 'json',
        snippet,
        cause: err
      });
    }
  }

  /** @inheritdoc */
  canParse(input) {
    if (typeof input !== 'string') return false;
    const trimmed = input.trim();
    return (
      (trimmed.startsWith('{') && trimmed.endsWith('}')) ||
      (trimmed.startsWith('[') && trimmed.endsWith(']')) ||
      trimmed === 'true' ||
      trimmed === 'false' ||
      trimmed === 'null' ||
      /^-?\d/.test(trimmed) ||
      (trimmed.startsWith('"') && trimmed.endsWith('"'))
    );
  }

  /**
   * Strips single-line (//) and block comments from JSON-like input.
   * Respects string boundaries.
   * @private
   * @param {string} text
   * @returns {string}
   */
  _stripComments(text) {
    let result = '';
    let i = 0;
    let inString = false;

    while (i < text.length) {
      // Handle string boundaries
      if (text[i] === '"' && (i === 0 || text[i - 1] !== '\\')) {
        inString = !inString;
        result += text[i];
        i++;
        continue;
      }

      if (inString) {
        result += text[i];
        i++;
        continue;
      }

      // Single-line comment
      if (text[i] === '/' && text[i + 1] === '/') {
        const newline = text.indexOf('\n', i);
        i = newline === -1 ? text.length : newline;
        continue;
      }

      // Block comment
      if (text[i] === '/' && text[i + 1] === '*') {
        const end = text.indexOf('*/', i + 2);
        if (end === -1) {
          throw new ParseError('Unterminated block comment', { source: 'json' });
        }
        i = end + 2;
        continue;
      }

      result += text[i];
      i++;
    }

    return result;
  }

  /**
   * Removes trailing commas before } and ].
   * @private
   * @param {string} text
   * @returns {string}
   */
  _removeTrailingCommas(text) {
    return text.replace(/,\s*([\]}])/g, '$1');
  }

  /**
   * Attempts to extract line/column from a native JSON parse error.
   * @private
   * @param {string} input
   * @param {Error} err
   * @returns {{ line: number|null, column: number|null, snippet: string|null }}
   */
  _locateError(input, err) {
    const posMatch = err.message.match(/position\s+(\d+)/i);
    const lineColMatch = err.message.match(/line\s+(\d+)\s+column\s+(\d+)/i);

    let line = null;
    let column = null;
    let snippet = null;

    if (lineColMatch) {
      line = parseInt(lineColMatch[1], 10);
      column = parseInt(lineColMatch[2], 10);
    } else if (posMatch) {
      const pos = parseInt(posMatch[1], 10);
      const upToPos = input.substring(0, pos);
      const lines = upToPos.split('\n');
      line = lines.length;
      column = lines[lines.length - 1].length + 1;
    }

    if (line !== null) {
      const inputLines = input.split('\n');
      if (line <= inputLines.length) {
        snippet = inputLines[line - 1].trim();
        if (snippet.length > 60) {
          snippet = snippet.substring(0, 60) + '…';
        }
      }
    }

    return { line, column, snippet };
  }
}

module.exports = JSONParser;
