   * @param {boolean} [options.hasHeader=true] - Treat first row as header
   * @param {boolean} [options.trimFields=true] - Trim whitespace from fields
   * @param {boolean} [options.skipEmptyLines=true] - Ignore blank lines
   * @param {boolean} [options.cast=false] - Auto-cast numbers and booleans
   * @returns {{ headers: string[]|null, rows: Array<Object|string[]>, rowCount: number }}
   * @throws {ParseError}
   */
  _doParse(input, options = {}) {
    validateStringInput(input, 'CSV input');
    const opts = {
      delimiter: ',',
      hasHeader: true,
      trimFields: true,
      skipEmptyLines: true,
      cast: false,
      ...validateOptions(options, CSVParser.OPTIONS_SCHEMA)
    };

    if (opts.delimiter.length !== 1) {
      throw new ParseError('Delimiter must be a single character', {
        source: 'csv'
      });
    }

    const records = this._parseRecords(input, opts);

    if (records.length === 0) {
      return { headers: null, rows: [], rowCount: 0 };
    }

    let headers = null;
    let dataRows = records;

    if (opts.hasHeader) {
      headers = records[0];
      dataRows = records.slice(1);

      // Validate consistent column count
      const expectedCols = headers.length;
      for (let i = 0; i < dataRows.length; i++) {
        if (dataRows[i].length !== expectedCols) {
          throw new ParseError(
            `Row ${i + 2} has ${dataRows[i].length} fields, expected ${expectedCols}`,
            { line: i + 2, source: 'csv' }
