"use strict";

/**
 * Base error for log ingestion operations.
 */
class LogIngestionError extends Error {
  /**
   * @param {string} message
   * @param {object} [options]
   * @param {Error} [options.cause]
   * @param {object} [options.context]
   */
  constructor(message, { cause, context } = {}) {
    super(message);
    this.name = "LogIngestionError";
    this.cause = cause;
    this.context = context ?? {};
    this.timestamp = new Date().toISOString();
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      timestamp: this.timestamp,
      context: this.context,
      cause: this.cause?.message,
      stack: this.stack,
    };
  }
}

/**
 * Thrown when all retry attempts are exhausted.
 */
class RetryExhaustedError extends LogIngestionError {
  /**
   * @param {number} attempts
   * @param {Error} lastError
   * @param {object} [context]
   */
  constructor(attempts, lastError, context) {
    super(`All ${attempts} retry attempts exhausted`, {
      cause: lastError,
      context: { ...context, totalAttempts: attempts },
    });
    this.name = "RetryExhaustedError";
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

/**
 * Thrown when the circuit breaker is open.
 */
class CircuitBreakerOpenError extends LogIngestionError {
  /**
   * @param {number} resetTimeout
   */
  constructor(resetTimeout) {
    super(`Circuit breaker is open. Retry after ${resetTimeout}ms`);
    this.name = "CircuitBreakerOpenError";
    this.resetTimeout = resetTimeout;
  }
}

/**
 * Thrown when rate limit is exceeded.
 */
class RateLimitError extends LogIngestionError {
  /**
   * @param {number} retryAfterMs
   */
  constructor(retryAfterMs) {
    super(`Rate limit exceeded. Retry after ${retryAfterMs}ms`);
    this.name = "RateLimitError";
    this.retryAfterMs = retryAfterMs;
  }
}

/**
 * Thrown for non-retryable failures (e.g., 4xx responses).
 */
class NonRetryableError extends LogIngestionError {
  constructor(message, options) {
    super(message, options);
    this.name = "NonRetryableError";
  }
}

module.exports = {
  LogIngestionError,
  RetryExhaustedError,
  CircuitBreakerOpenError,
  RateLimitError,
  NonRetryableError,
};
