"use strict";

const { EventEmitter } = require("events");

/**
 * Lightweight metrics collector.
 * Emits events that can be forwarded to Prometheus, Datadog, etc.
 */
class MetricsCollector extends EventEmitter {
  #counters = new Map();
  #histograms = new Map();
  #gauges = new Map();

  /** Increment a counter. */
  increment(name, value = 1, tags = {}) {
    const key = this.#key(name, tags);
    this.#counters.set(key, (this.#counters.get(key) ?? 0) + value);
    this.emit("counter", { name, value, tags });
  }

  /** Record a histogram observation (e.g., latency). */
  observe(name, value, tags = {}) {
    const key = this.#key(name, tags);
    if (!this.#histograms.has(key)) {
      this.#histograms.set(key, []);
    }
    this.#histograms.get(key).push(value);
    this.emit("histogram", { name, value, tags });
  }

  /** Set a gauge value. */
  gauge(name, value, tags = {}) {
    const key = this.#key(name, tags);
    this.#gauges.set(key, value);
    this.emit("gauge", { name, value, tags });
  }

  /** Snapshot all collected metrics. */
  snapshot() {
    return {
      counters: Object.fromEntries(this.#counters),
      gauges: Object.fromEntries(this.#gauges),
      histograms: Object.fromEntries(
        [...this.#histograms.entries()].map(([k, v]) => [
          k,
          {
            count: v.length,
            min: Math.min(...v),
            max: Math.max(...v),
            avg: v.reduce((a, b) => a + b, 0) / v.length,
            p99: this.#percentile(v, 99),
          },
        ])
      ),
    };
  }

  reset() {
    this.#counters.clear();
    this.#histograms.clear();
    this.#gauges.clear();
  }

  #key(name, tags) {
    const tagStr = Object.entries(tags)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => `${k}:${v}`)
      .join(",");
    return tagStr ? `${name}{${tagStr}}` : name;
  }

  #percentile(values, pct) {
    const sorted = [...values].sort((a, b) => a - b);
    const idx = Math.ceil((pct / 100) * sorted.length) - 1;
    return sorted[Math.max(0, idx)];
  }
}

module.exports = { MetricsCollector };
