"use strict";

const {
  RetryExhaustedError,
  NonRetryableError,
  RateLimitError,
} = require("./utils/errors");

/**
 * @typedef {object} RetryPolicyConfig
 * @property {number}   [maxAttempts=5]       Total attempts (initial + retries).
 * @property {number}   [baseDelayMs=500]     Base delay before first retry.
 * @property {number}   [maxDelayMs=30000]    Ceiling for computed delay.
 * @property {number}   [backoffMultiplier=2] Exponential multiplier.
 * @property {number}   [jitterFactor=0.5]    0–1 range; portion of delay that is random.
 * @property {function} [isRetryable]         Predicate: (error) => boolean.
 */

/** @type {RetryPolicyConfig} */
const DEFAULTS = Object.freeze({
  maxAttempts: 5,
  baseDelayMs: 500,
  maxDelayMs: 30_000,
  backoffMultiplier: 2,
  jitterFactor: 0.5,
  isRetryable: (err) => {
    if (err instanceof NonRetryableError) return false;
    if (err instanceof RateLimitError) return true;

    // HTTP-style: retry on 429 and 5xx
    const status = err.statusCode ?? err.status ?? err.code;
    if (typeof status === "number") {
      return status === 429 || (status >= 500 && status <= 599);
    }

    // Network errors
    const networkCodes = new Set([
      "ECONNRESET",
      "ECONNREFUSED",
      "ETIMEDOUT",
      "EPIPE",
      "EAI_AGAIN",
      "ENOTFOUND",
      "UND_ERR_CONNECT_TIMEOUT",
      "UND_ERR_HEADERS_TIMEOUT",
      "UND_ERR_BODY_TIMEOUT",
      "UND_ERR_SOCKET",
    ]);
    if (typeof status === "string" && networkCodes.has(status)) return true;

    return true; // Default to retryable for unknown errors
  },
});

class RetryPolicy {
  #config;
  #logger;
  #metrics;

  /**
   * @param {RetryPolicyConfig} [config]
   * @param {{ logger?: object, metrics?: object }} [deps]
   */
  constructor(config = {}, { logger, metrics } = {}) {
    this.#config = { ...DEFAULTS, ...config };
    this.#logger = logger;
    this.#metrics = metrics;

    if (this.#config.maxAttempts < 1) {
      throw new RangeError("maxAttempts must be ≥ 1");
    }
  }

  /**
   * Execute `fn` with retry logic.
   *
   * @template T
   * @param {(attempt: number, signal?: AbortSignal) => Promise<T>} fn
   * @param {{ signal?: AbortSignal, context?: object }} [options]
   * @returns {Promise<T>}
   */
  async execute(fn, { signal, context } = {}) {
    const { maxAttempts, isRetryable } = this.#config;
    let lastError;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      signal?.throwIfAborted();

      try {
        const start = Date.now();
        const result = await fn(attempt, signal);
        const duration = Date.now() - start;

        this.#metrics?.observe("retry_policy.success_latency_ms", duration);
        this.#metrics?.increment("retry_policy.success", 1, {
          attempt: String(attempt),
        });

        return result;
      } catch (error) {
        lastError = error;

        this.#metrics?.increment("retry_policy.attempt_failure", 1, {
          attempt: String(attempt),
          error: error.name,
        });

        if (!isRetryable(error)) {
          this.#logger?.warn("Non-retryable error; aborting", {
            attempt,
            error: error.message,
            ...context,
          });
          throw error;
        }

        if (attempt < maxAttempts) {
          const delay = this.#computeDelay(attempt, error);

          this.#logger?.warn("Retrying after failure", {
            attempt,
            nextAttempt: attempt + 1,
            maxAttempts,
            delayMs: delay,
            error: error.message,
            ...context,
          });

          await this.#sleep(delay, signal);
        }
      }
    }

    this.#metrics?.increment("retry_policy.exhausted");
    throw new RetryExhaustedError(maxAttempts, lastError, context);
  }

  /**
   * Calculate delay with exponential backoff + jitter.
   * Honors Retry-After / retryAfterMs from rate-limit errors.
   *
   * @param {number} attempt
   * @param {Error} error
   * @returns {number}
   */
  #computeDelay(attempt, error) {
    const { baseDelayMs, maxDelayMs, backoffMultiplier, jitterFactor } =
      this.#config;

    // Honor server-specified Retry-After
    if (error instanceof RateLimitError && error.retryAfterMs > 0) {
      return Math.min(error.retryAfterMs, maxDelayMs);
    }

    const exponentialDelay = baseDelayMs * backoffMultiplier ** (attempt - 1);
    const clampedDelay = Math.min(exponentialDelay, maxDelayMs);

    // Apply jitter: delay ∈ [clampedDelay * (1 - jitter), clampedDelay]
    const jitterRange = clampedDelay * jitterFactor;
    const jitter = jitterRange * Math.random();

    return Math.round(clampedDelay - jitterRange + jitter);
  }

  /**
   * Abortable sleep.
   * @param {number} ms
   * @param {AbortSignal} [signal]
   * @returns {Promise<void>}
   */
  #sleep(ms, signal) {
    return new Promise((resolve, reject) => {
      if (signal?.aborted) return reject(signal.reason);

      const timer = setTimeout(resolve, ms);

      signal?.addEventListener(
        "abort",
        () => {
          clearTimeout(timer);
          reject(signal.reason);
        },
        { once: true }
      );
    });
  }
}

module.exports = { RetryPolicy };
