### `src/CircuitBreaker.js` — Circuit Breaker Pattern

```javascript
"use strict";

const { CircuitBreakerOpenError } = require("./utils/errors");

const State = Object.freeze({
  CLOSED: "CLOSED",
  OPEN: "OPEN",
  HALF_OPEN: "HALF_OPEN",
});

/**
 * @typedef {object} CircuitBreakerConfig
 * @property {number} [failureThreshold=5]      Failures to trip the breaker.
 * @property {number} [resetTimeoutMs=30000]     Time in OPEN state before HALF_OPEN.
 * @property {number} [halfOpenMaxAttempts=3]    Probes allowed in HALF_OPEN.
 * @property {number} [successThreshold=2]       Successes in HALF_OPEN to close again.
 * @property {number} [monitorWindowMs=60000]    Rolling window for failure counting.
 */

class CircuitBreaker {
  #config;
  #state = State.CLOSED;
  #failures = [];
  #halfOpenSuccesses = 0;
  #halfOpenAttempts = 0;
  #lastFailureTime = 0;
  #logger;
  #metrics;

  /**
   * @param {CircuitBreakerConfig} [config]
   * @param {{ logger?: object, metrics?: object }} [deps]
   */
  constructor(config = {}, { logger, metrics } = {}) {
    this.#config = {
      failureThreshold: 5,
      resetTimeoutMs: 30_000,
      halfOpenMaxAttempts: 3,
      successThreshold: 2,
      monitorWindowMs: 60_000,
      ...config,
    };
    this.#logger = logger;
    this.#metrics = metrics;
  }

  get state() {
    // Auto-transition OPEN → HALF_OPEN when timeout elapses
    if (
      this.#state === State.OPEN &&
      Date.now() - this.#lastFailureTime >= this.#config.resetTimeoutMs
    ) {
      this.#transitionTo(State.HALF_OPEN);
    }
    return this.#state;
  }

  /**
   * Guard + execute.
   * @template T
   * @param {() => Promise<T>} fn
   * @returns {Promise<T>}
   */
  async execute(fn) {
    const currentState = this.state; // triggers auto-transition

    if (currentState === State.OPEN) {
      this.#metrics?.increment("circuit_breaker.rejected");
      throw new CircuitBreakerOpenError(this.#config.resetTimeoutMs);
    }

    if (
      currentState === State.HALF_OPEN &&
      this.#halfOpenAttempts >= this.#config.halfOpenMaxAttempts
    ) {
      this.#metrics?.increment("circuit_breaker.rejected");
      throw new CircuitBreakerOpenError(this.#config.resetTimeoutMs);
    }

    try {
      if (currentState === State.HALF_OPEN) {
        this.#halfOpenAttempts++;
      }

      const result = await fn();
      this.#onSuccess();
      return result;
    } catch (error) {
      this.#onFailure();
      throw error;
    }
  }

  #onSuccess() {
    if (this.#state === State.HALF_OPEN) {
      this.#halfOpenSuccesses++;
      if (this.#halfOpenSuccesses >= this.#config.successThreshold) {
        this.#transitionTo(State.CLOSED);
      }
    }
    // In CLOSED state, no action needed
    this.#metrics?.increment("circuit_breaker.success");
  }

  #onFailure() {
    const now = Date.now();
    this.#lastFailureTime = now;

    if (this.#state === State.HALF_OPEN) {
      this.#transitionTo(State.OPEN);
      return;
    }

    // Sliding window failure tracking
    const windowStart = now - this.#config.monitorWindowMs;
    this.#failures.push(now);
    this.#failures = this.#failures.filter((t) => t >= windowStart);

    this.#metrics?.increment("circuit_breaker.failure");
    this.#metrics?.gauge("circuit_breaker.failure_count", this.#failures.length);

    if (this.#failures.length >= this.#config.failureThreshold) {
      this.#transitionTo(State.OPEN);
    }
  }

  #transitionTo(newState) {
    const prev = this.#state;
    this.#state = newState;

    if (newState === State.CLOSED) {
      this.#failures = [];
      this.#halfOpenSuccesses = 0;
      this.#halfOpenAttempts = 0;
    } else if (newState === State.HALF_OPEN) {
      this.#halfOpenSuccesses = 0;
      this.#halfOpenAttempts = 0;
    }

    this.#logger?.info("Circuit breaker state transition", {
      from: prev,
      to: newState,
    });
    this.#metrics?.increment("circuit_breaker.transition", 1, {
      from: prev,
      to: newState,
    });
  }

  /** Force-reset (for testing or manual intervention). */
  reset() {
    this.#transitionTo(State.CLOSED);
  }
}

module.exports = { CircuitBreaker, State };
