package audit;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.UUID;

/**
 * Immutable audit log entry.
 */
public final class AuditEntry {

    private static final String DELIMITER = "\t";
    private static final DateTimeFormatter DISPLAY_FMT =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")
                    .withZone(ZoneId.systemDefault());

    private final String id;
    private final Instant timestamp;
    private final String user;
    private final String action;
    private final String resource;
    private final String detail;

    public AuditEntry(String user, String action, String resource, String detail) {
        this.id = UUID.randomUUID().toString().substring(0, 8);
        this.timestamp = Instant.now();
        this.user = user;
        this.action = action;
        this.resource = resource;
        this.detail = detail;
    }

    private AuditEntry(String id, Instant timestamp, String user,
                       String action, String resource, String detail) {
        this.id = id;
        this.timestamp = timestamp;
        this.user = user;
        this.action = action;
        this.resource = resource;
        this.detail = detail;
    }

    // --- Accessors ---

    public String getId()        { return id; }
    public Instant getTimestamp() { return timestamp; }
    public String getUser()      { return user; }
    public String getAction()    { return action; }
    public String getResource()  { return resource; }
    public String getDetail()    { return detail; }

    // --- Serialization (tab-delimited, one line per entry) ---

    public String serialize() {
        return String.join(DELIMITER, id, timestamp.toString(), user, action, resource, detail);
    }

    public static AuditEntry deserialize(String line) {
        String[] parts = line.split(DELIMITER, 6);
        if (parts.length < 6) {
            throw new IllegalArgumentException("Malformed log line: " + line);
        }
        return new AuditEntry(
                parts[0],
                Instant.parse(parts[1]),
                parts[2],
                parts[3],
                parts[4],
                parts[5]
        );
    }

    // --- Display ---

    public String formatRow() {
        return String.format("%-10s %-20s %-12s %-10s %-15s %s",
                id, DISPLAY_FMT.format(timestamp), user, action, resource, detail);
    }

    public static String headerRow() {
        return String.format("%-10s %-20s %-12s %-10s %-15s %s",
                "ID", "TIMESTAMP", "USER", "ACTION", "RESOURCE", "DETAIL");
    }

    public static String separatorRow() {
        return "-".repeat(90);
    }

    @Override
    public String toString() {
        return formatRow();
    }
}
