package audit;

import java.io.IOException;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;
import java.util.stream.Collectors;

/**
 * Append-only file store for audit entries.
 * Each line is one tab-delimited record.
 */
public final class AuditStore {

    private final Path filePath;

    public AuditStore(String filePath) {
        this.filePath = Paths.get(filePath);
    }

    /** Append a single entry to the log file. */
    public void append(AuditEntry entry) throws IOException {
        Files.writeString(
                filePath,
                entry.serialize() + System.lineSeparator(),
                StandardOpenOption.CREATE,
                StandardOpenOption.APPEND
        );
    }

    /** Read every entry from the file. */
    public List<AuditEntry> readAll() throws IOException {
        if (!Files.exists(filePath)) {
            return Collections.emptyList();
        }

        List<AuditEntry> entries = new ArrayList<>();
        for (String line : Files.readAllLines(filePath)) {
            if (!line.isBlank()) {
                entries.add(AuditEntry.deserialize(line));
            }
        }
        return entries;
    }

    /** Return entries matching an arbitrary predicate. */
    public List<AuditEntry> query(Predicate<AuditEntry> filter) throws IOException {
        return readAll().stream()
                .filter(filter)
                .collect(Collectors.toList());
    }

    /** Return the last N entries. */
    public List<AuditEntry> tail(int n) throws IOException {
        List<AuditEntry> all = readAll();
        int from = Math.max(0, all.size() - n);
        return all.subList(from, all.size());
    }

    /** Total entry count. */
    public int count() throws IOException {
        return readAll().size();
    }

    /** Delete the log file. */
    public void clear() throws IOException {
        Files.deleteIfExists(filePath);
    }

    /** Export all entries to a target file. */
    public void export(String targetPath) throws IOException {
        List<AuditEntry> entries = readAll();
        StringBuilder sb = new StringBuilder();
        sb.append(AuditEntry.headerRow()).append(System.lineSeparator());
        sb.append(AuditEntry.separatorRow()).append(System.lineSeparator());
        for (AuditEntry e : entries) {
            sb.append(e.formatRow()).append(System.lineSeparator());
        }
        Files.writeString(Paths.get(targetPath), sb.toString());
    }
}
