### `src/audit/AuditCLI.java`

```java
package audit;

import java.io.IOException;
import java.util.List;

/**
 * CLI entry point.
 *
 * Usage:
 *   audit log   -u <user> -a <action> -r <resource> [-d <detail>]
 *   audit list
 *   audit search -u <user>
 *   audit search -a <action>
 *   audit tail   [n]
 *   audit count
 *   audit export <file>
 *   audit clear  --confirm
 */
public final class AuditCLI {

    private static final String LOG_FILE = "audit.log";
    private final AuditStore store;

    public AuditCLI() {
        this.store = new AuditStore(LOG_FILE);
    }

    // ---- main ----

    public static void main(String[] args) {
        AuditCLI cli = new AuditCLI();

        if (args.length == 0) {
            printUsage();
            System.exit(1);
        }

        try {
            switch (args[0]) {
                case "log"    -> cli.handleLog(args);
                case "list"   -> cli.handleList();
                case "search" -> cli.handleSearch(args);
                case "tail"   -> cli.handleTail(args);
                case "count"  -> cli.handleCount();
                case "export" -> cli.handleExport(args);
                case "clear"  -> cli.handleClear(args);
                default       -> {
                    System.err.println("Unknown command: " + args[0]);
                    printUsage();
                    System.exit(1);
                }
            }
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
            System.exit(1);
        }
    }

    // ---- command handlers ----

    private void handleLog(String[] args) throws IOException {
        String user = null, action = null, resource = null, detail = "";

        for (int i = 1; i < args.length - 1; i++) {
            switch (args[i]) {
                case "-u" -> user     = args[++i];
                case "-a" -> action   = args[++i];
                case "-r" -> resource = args[++i];
                case "-d" -> detail   = args[++i];
            }
        }

        if (user == null || action == null || resource == null) {
            System.err.println("Required: -u <user> -a <action> -r <resource>");
            System.exit(1);
        }

        AuditEntry entry = new AuditEntry(user, action, resource, detail);
        store.append(entry);
        System.out.println("Logged: " + entry.formatRow());
    }

    private void handleList() throws IOException {
        printEntries(store.readAll());
    }

    private void handleSearch(String[] args) throws IOException {
        if (args.length < 3) {
            System.err.println("Usage: search -u <user> | -a <action> | -r <resource>");
            System.exit(1);
        }

        String flag  = args[1];
        String value = args[2].toLowerCase();

        List<AuditEntry> results = store.query(entry -> switch (flag) {
            case "-u" -> entry.getUser().toLowerCase().contains(value);
            case "-a" -> entry.getAction().toLowerCase().contains(value);
            case "-r" -> entry.getResource().toLowerCase().contains(value);
            default   -> false;
        });

        System.out.println("Found " + results.size() + " result(s):");
        printEntries(results);
    }

    private void handleTail(String[] args) throws IOException {
        int n = 10;
        if (args.length > 1) {
            n = Integer.parseInt(args[1]);
        }
        System.out.println("Last " + n + " entries:");
        printEntries(store.tail(n));
    }

    private void handleCount() throws IOException {
        System.out.println("Total audit entries: " + store.count());
    }

    private void handleExport(String[] args) throws IOException {
        if (args.length < 2) {
            System.err.println("Usage: export <filename>");
            System.exit(1);
        }
        store.export(args[1]);
        System.out.println("Exported " + store.count() + " entries to " + args[1]);
    }

    private void handleClear(String[] args) throws IOException {
        if (args.length < 2 || !args[1].equals("--confirm")) {
            System.err.println("Pass --confirm to delete all audit logs.");
            System.exit(1);
        }
        int count = store.count();
        store.clear();
        System.out.println("Cleared " + count + " entries.");
    }

    // ---- helpers ----

    private void printEntries(List<AuditEntry> entries) {
        if (entries.isEmpty()) {
            System.out.println("(no entries)");
            return;
        }
        System.out.println(AuditEntry.headerRow());
        System.out.println(AuditEntry.separatorRow());
        entries.forEach(e -> System.out.println(e.formatRow()));
    }

    private static void printUsage() {
        System.out.println("""
            Audit Logger CLI
            ─────────────────────────────────────────────────
            Commands:
              log    -u <user> -a <action> -r <resource> [-d <detail>]
              list
              search -u <user> | -a <action> | -r <resource>
              tail   [n]           (default 10)
              count
              export <file>
              clear  --confirm
            """);
    }
}
