    /// <summary>Glob patterns to exclude (e.g., "*.tmp", ".git/**").</summary>
    public IReadOnlyList<string> ExcludePatterns { get; init; } = Array.Empty<string>();

    /// <summary>Delete destination files not present in source.</summary>
    public bool DeleteOrphans { get; init; } = false;

    /// <summary>Use file content hashing instead of timestamp comparison.</summary>
    public bool UseContentHash { get; init; } = true;

    /// <summary>Buffer size for file copy operations.</summary>
    public int BufferSize { get; init; } = 81920; // 80 KB

    /// <summary>Maximum degree of parallelism for file operations.</summary>
    public int MaxParallelism { get; init; } = 4;

    /// <summary>How to resolve conflicts when both files have changed.</summary>
    public ConflictResolution ConflictResolution { get; init; } = ConflictResolution.SourceWins;

    /// <summary>Create a backup before overwriting files.</summary>
    public bool BackupBeforeOverwrite { get; init; } = true;

    /// <summary>Dry run mode — log actions without making changes.</summary>
    public bool DryRun { get; init; } = false;
}

