## Retry Policy

```csharp
// Policies/RetryPolicy.cs
using Microsoft.Extensions.Logging;

namespace FileSyncService.Policies;

/// <summary>
/// Configurable retry policy with exponential backoff and jitter.
/// </summary>
public sealed class RetryPolicy
{
    private readonly int _maxAttempts;
    private readonly TimeSpan _initialDelay;
    private readonly TimeSpan _maxDelay;
    private readonly ILogger _logger;

    // Transient exceptions that justify a retry
    private static readonly HashSet<Type> TransientExceptionTypes = new()
    {
        typeof(IOException),
        typeof(UnauthorizedAccessException),
        typeof(TimeoutException)
    };

    public RetryPolicy(
        int maxAttempts,
        TimeSpan initialDelay,
        TimeSpan maxDelay,
        ILogger logger)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(maxAttempts, 1);

        _maxAttempts = maxAttempts;
        _initialDelay = initialDelay;
        _maxDelay = maxDelay;
        _logger = logger;
    }

    /// <summary>
    /// Execute an async action with retry logic.
    /// Returns (success, attempts, lastException).
    /// </summary>
    public async Task<RetryResult> ExecuteAsync(
        Func<CancellationToken, Task> action,
        string operationName,
        CancellationToken cancellationToken = default)
    {
        Exception? lastException = null;

        for (int attempt = 1; attempt <= _maxAttempts; attempt++)
        {
            try
            {
                cancellationToken.ThrowIfCancellationRequested();
                await action(cancellationToken).ConfigureAwait(false);

                if (attempt > 1)
                {
                    _logger.LogInformation(
                        "Operation '{Operation}' succeeded on attempt {Attempt}/{Max}",
                        operationName, attempt, _maxAttempts);
                }

                return new RetryResult(true, attempt, null);
            }
            catch (OperationCanceledException)
            {
                throw; // Don't retry cancellations
            }
            catch (Exception ex) when (IsTransient(ex) && attempt < _maxAttempts)
            {
                lastException = ex;
                TimeSpan delay = CalculateDelay(attempt);

                _logger.LogWarning(ex,
                    "Transient error on attempt {Attempt}/{Max} for '{Operation}'. " +
                    "Retrying in {Delay:F1}s...",
                    attempt, _maxAttempts, operationName, delay.TotalSeconds);

                await Task.Delay(delay, cancellationToken).ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                // Non-transient or final attempt — do not retry
                _logger.LogError(ex,
                    "Non-transient error or final attempt {Attempt}/{Max} for '{Operation}'",
                    attempt, _maxAttempts, operationName);

                return new RetryResult(false, attempt, ex);
            }
        }

        // Should be unreachable, but just in case
        return new RetryResult(false, _maxAttempts, lastException);
    }

    /// <summary>
    /// Execute an async function with retry logic.
    /// </summary>
    public async Task<RetryResult<T>> ExecuteAsync<T>(
        Func<CancellationToken, Task<T>> func,
        string operationName,
        CancellationToken cancellationToken = default)
    {
        T? result = default;
        var retryResult = await ExecuteAsync(
            async ct => { result = await func(ct).ConfigureAwait(false); },
            operationName,
            cancellationToken).ConfigureAwait(false);

        return new RetryResult<T>(retryResult.Success, retryResult.Attempts,
            retryResult.Exception, result);
    }

    private TimeSpan CalculateDelay(int attempt)
    {
        // Exponential backoff: initialDelay * 2^(attempt-1)
        double exponentialMs = _initialDelay.TotalMilliseconds * Math.Pow(2, attempt - 1);

        // Add jitter: ±25% randomization to prevent thundering herd
        double jitter = exponentialMs * 0.25 * (Random.Shared.NextDouble() * 2 - 1);
        double totalMs = exponentialMs + jitter;

        // Clamp to max delay
        totalMs = Math.Min(totalMs, _maxDelay.TotalMilliseconds);
        totalMs = Math.Max(totalMs, 0);

        return TimeSpan.FromMilliseconds(totalMs);
    }

    private static bool IsTransient(Exception ex)
    {
        // Check the exception itself and any inner exceptions
        Exception? current = ex;
        while (current is not null)
        {
            if (TransientExceptionTypes.Contains(current.GetType()))
                return true;

            // Win32 sharing violations, lock errors, etc.
            if (current is IOException ioEx &&
                (ioEx.HResult == unchecked((int)0x80070020) ||  // ERROR_SHARING_VIOLATION
                 ioEx.HResult == unchecked((int)0x80070021)))   // ERROR_LOCK_VIOLATION
            {
                return true;
            }

            current = current.InnerException;
        }

        return false;
    }
}

public sealed record RetryResult(
    bool Success,
    int Attempts,
    Exception? Exception);

public sealed record RetryResult<T>(
    bool Success,
    int Attempts,
    Exception? Exception,
    T? Value);
