// Services/FileHashService.cs
using System.Security.Cryptography;
using Microsoft.Extensions.Logging;

namespace FileSyncService.Services;

public sealed class FileHashService : IFileHashService
{
    private readonly ILogger<FileHashService> _logger;
    private const int BufferSize = 81920;

    public FileHashService(ILogger<FileHashService> logger)
    {
        _logger = logger;
    }

    public async Task<string> ComputeHashAsync(
        string filePath,
        CancellationToken cancellationToken = default)
    {
        using var sha256 = SHA256.Create();

        await using var stream = new FileStream(
            filePath,
            FileMode.Open,
            FileAccess.Read,
            FileShare.Read,
            BufferSize,
            FileOptions.Asynchronous | FileOptions.SequentialScan);

        byte[] hash = await sha256.ComputeHashAsync(stream, cancellationToken)
            .ConfigureAwait(false);

        return Convert.ToHexString(hash);
    }

    public async Task<bool> AreFilesIdenticalAsync(
        string path1,
        string path2,
        CancellationToken cancellationToken = default)
    {
        var info1 = new FileInfo(path1);
        var info2 = new FileInfo(path2);

        // Quick check: different sizes → not identical
        if (info1.Length != info2.Length)
            return false;

        // Empty files are identical
        if (info1.Length == 0)
            return true;

        // Compare hashes
        string hash1 = await ComputeHashAsync(path1, cancellationToken).ConfigureAwait(false);
        string hash2 = await ComputeHashAsync(path2, cancellationToken).ConfigureAwait(false);

        bool identical = string.Equals(hash1, hash2, StringComparison.Ordinal);

        _logger.LogTrace(
            "Hash comparison for '{Path}': {Result} ({Hash1} vs {Hash2})",
            Path.GetFileName(path1), identical ? "IDENTICAL" : "DIFFERENT", hash1, hash2);

        return identical;
    }
}
