    public async Task CopyFileAsync(
        string sourcePath,
        string destinationPath,
        int bufferSize,
        IProgress<long>? progress = null,
        CancellationToken cancellationToken = default)
    {
        // Ensure destination directory exists
        string? destDir = Path.GetDirectoryName(destinationPath);
        if (destDir is not null)
            Directory.CreateDirectory(destDir);

        // Write to a temp file first, then atomically move
        string tempPath = destinationPath + ".tmp." + Guid.NewGuid().ToString("N")[..8];

        try
        {
            await using (var sourceStream = new FileStream(
                sourcePath,
                FileMode.Open,
                FileAccess.Read,
                FileShare.Read,
                bufferSize,
                FileOptions.Asynchronous | FileOptions.SequentialScan))
            {
                await using var destStream = new FileStream(
                    tempPath,
                    FileMode.Create,
                    FileAccess.Write,
                    FileShare.None,
                    bufferSize,
                    FileOptions.Asynchronous | FileOptions.SequentialScan);

                byte[] buffer = new byte[bufferSize];
                long totalBytesRead = 0;
                int bytesRead;

                while ((bytesRead = await sourceStream
                    .ReadAsync(buffer.AsMemory(0, bufferSize), cancellationToken)
                    .ConfigureAwait(false)) > 0)
                {
                    await destStream
                        .WriteAsync(buffer.AsMemory(0, bytesRead), cancellationToken)
                        .ConfigureAwait(false);

                    totalBytesRead += bytesRead;
                    progress?.Report(totalBytesRead);
                }

                await destStream.FlushAsync(cancellationToken).ConfigureAwait(false);
            }

            // Preserve timestamps
            var sourceInfo = new FileInfo(sourcePath);
            File.SetLastWriteTimeUtc(tempPath, sourceInfo.LastWriteTimeUtc);
            File.SetCreationTimeUtc(tempPath, sourceInfo.CreationTimeUtc);

            // Atomic replace
            File.Move(tempPath, destinationPath, overwrite: true);

            _logger.LogDebug("Copied '{Source}' → '{Dest}'", sourcePath, destinationPath);
        }
        catch
