'use strict';

class ValidationError extends Error {
  constructor(message, field, value) {
    super(message);
    this.name = 'ValidationError';
    this.field = field;
    this.value = value;
  }
}

class LogValidator {
  /**
   * @param {object} options
   * @param {string[]} options.allowedLevels
   * @param {number} options.maxMessageLength
   * @param {number} options.maxMetadataKeys
   */
  constructor(options = {}) {
    this.allowedLevels = options.allowedLevels || ['DEBUG', 'INFO', 'WARN', 'ERROR', 'FATAL'];
    this.maxMessageLength = options.maxMessageLength || 10000;
    this.maxMetadataKeys = options.maxMetadataKeys || 50;
  }

  /**
   * Validates a single log entry.
   * @param {object} entry - The log entry to validate.
   * @returns {{ valid: boolean, errors: ValidationError[], sanitized: object|null }}
   */
  validate(entry) {
    const errors = [];

    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      errors.push(new ValidationError('Log entry must be a non-null object', 'entry', entry));
      return { valid: false, errors, sanitized: null };
    }

    // Validate level
    if (!entry.level) {
      errors.push(new ValidationError('level is required', 'level', undefined));
    } else if (typeof entry.level !== 'string') {
      errors.push(new ValidationError('level must be a string', 'level', entry.level));
    } else if (!this.allowedLevels.includes(entry.level.toUpperCase())) {
      errors.push(
        new ValidationError(
          `level must be one of: ${this.allowedLevels.join(', ')}`,
          'level',
          entry.level,
        ),
      );
    }

    // Validate message
    if (!entry.message && entry.message !== '') {
      errors.push(new ValidationError('message is required', 'message', undefined));
    } else if (typeof entry.message !== 'string') {
      errors.push(new ValidationError('message must be a string', 'message', entry.message));
    } else if (entry.message.length === 0) {
      errors.push(new ValidationError('message must not be empty', 'message', entry.message));
    } else if (entry.message.length > this.maxMessageLength) {
      errors.push(
        new ValidationError(
          `message exceeds max length of ${this.maxMessageLength}`,
          'message',
          `[${entry.message.length} chars]`,
        ),
      );
    }

    // Validate timestamp (optional, but must be valid if present)
    if (entry.timestamp !== undefined) {
      const ts = new Date(entry.timestamp);
      if (isNaN(ts.getTime())) {
        errors.push(new ValidationError('timestamp must be a valid date', 'timestamp', entry.timestamp));
      }
    }

    // Validate source (optional string)
    if (entry.source !== undefined && typeof entry.source !== 'string') {
      errors.push(new ValidationError('source must be a string', 'source', entry.source));
    }

    // Validate metadata (optional object)
    if (entry.metadata !== undefined) {
      if (typeof entry.metadata !== 'object' || Array.isArray(entry.metadata) || entry.metadata === null) {
        errors.push(new ValidationError('metadata must be a plain object', 'metadata', entry.metadata));
      } else if (Object.keys(entry.metadata).length > this.maxMetadataKeys) {
        errors.push(
          new ValidationError(
            `metadata exceeds max keys of ${this.maxMetadataKeys}`,
            'metadata',
            `[${Object.keys(entry.metadata).length} keys]`,
          ),
        );
      }
    }

    if (errors.length > 0) {
      return { valid: false, errors, sanitized: null };
    }

    // Build sanitized entry
    const sanitized = {
      level: entry.level.toUpperCase(),
      message: entry.message.trim(),
      timestamp: entry.timestamp ? new Date(entry.timestamp).toISOString() : undefined,
      source: entry.source ? entry.source.trim() : undefined,
      metadata: entry.metadata ? { ...entry.metadata } : undefined,
    };

    // Strip undefined fields
    Object.keys(sanitized).forEach((key) => {
      if (sanitized[key] === undefined) delete sanitized[key];
    });

    return { valid: true, errors: [], sanitized };
  }

  /**
   * Validates an array of log entries (batch).
   * @param {object[]} entries
   * @returns {{ validEntries: object[], invalidEntries: { index: number, errors: ValidationError[] }[] }}
   */
  validateBatch(entries) {
    if (!Array.isArray(entries)) {
      return {
        validEntries: [],
        invalidEntries: [{ index: -1, errors: [new ValidationError('Batch must be an array', 'batch', typeof entries)] }],
      };
    }

    const validEntries = [];
    const invalidEntries = [];

    entries.forEach((entry, index) => {
      const result = this.validate(entry);
      if (result.valid) {
        validEntries.push(result.sanitized);
      } else {
        invalidEntries.push({ index, errors: result.errors });
      }
    });

    return { validEntries, invalidEntries };
  }
}

module.exports = { LogValidator, ValidationError };
