'use strict';

const { EventEmitter } = require('events');

/**
 * Buffers log entries in memory and flushes in configurable batches.
 * Emits 'flush' when a batch is ready, 'overflow' when buffer is full.
 */
class LogBuffer extends EventEmitter {
  /**
   * @param {object} options
   * @param {number} options.maxSize        - Max entries before forced flush (default 1000)
   * @param {number} options.flushIntervalMs - Auto-flush interval in ms (default 5000)
   */
  constructor(options = {}) {
    super();
    this.maxSize = options.maxSize || 1000;
    this.flushIntervalMs = options.flushIntervalMs || 5000;

    /** @type {object[]} */
    this._buffer = [];
    this._flushTimer = null;
    this._flushing = false;
    this._started = false;
    this._stats = {
      totalReceived: 0,
      totalFlushed: 0,
      flushCount: 0,
      overflowCount: 0,
      lastFlushTime: null,
    };
  }

  /** Starts the auto-flush timer. */
  start() {
    if (this._started) return;
    this._started = true;
    this._scheduleFlush();
  }

  /** Stops the auto-flush timer and performs a final flush. */
  async stop() {
    this._started = false;
    if (this._flushTimer) {
      clearTimeout(this._flushTimer);
      this._flushTimer = null;
    }
    if (this._buffer.length > 0) {
      await this._flush();
    }
  }

  /**
   * Adds a single entry to the buffer.
   * @param {object} entry
   * @returns {boolean} true if accepted, false if buffer was full (overflow triggered)
   */
  add(entry) {
    this._stats.totalReceived++;

    if (this._buffer.length >= this.maxSize) {
      this._stats.overflowCount++;
      this.emit('overflow', { bufferSize: this._buffer.length, dropped: entry });
      return false;
    }

    this._buffer.push(entry);

    if (this._buffer.length >= this.maxSize) {
      // Buffer just reached capacity — trigger immediate flush
      this._flush().catch((err) => this.emit('error', err));
    }

    return true;
  }

  /**
   * Adds multiple entries to the buffer.
   * @param {object[]} entries
   * @returns {{ accepted: number, dropped: number }}
   */
  addBatch(entries) {
    let accepted = 0;
    let dropped = 0;
    for (const entry of entries) {
      if (this.add(entry)) {
        accepted++;
      } else {
        dropped++;
      }
    }
    return { accepted, dropped };
  }

  /** Returns current buffer length. */
  get size() {
    return this._buffer.length;
  }

  /** Returns a copy of the buffer stats. */
  get stats() {
    return { ...this._stats, currentSize: this._buffer.length };
  }

  /** @private */
  _scheduleFlush() {
    if (!this._started) return;
    this._flushTimer = setTimeout(async () => {
      try {
        await this._flush();
      } catch (err) {
        this.emit('error', err);
      }
      this._scheduleFlush();
    }, this.flushIntervalMs);

    // Allow Node.js to exit even if timer is still pending
    if (this._flushTimer.unref) {
      this._flushTimer.unref();
    }
  }

  /** @private */
  async _flush() {
    if (this._flushing || this._buffer.length === 0) return;

    this._flushing = true;
    const batch = this._buffer.splice(0, this._buffer.length);

    try {
      this.emit('flush', batch);
      this._stats.totalFlushed += batch.length;
      this._stats.flushCount++;
      this._stats.lastFlushTime = new Date().toISOString();
    } catch (err) {
      // Put entries back at front of buffer on failure
      this._buffer.unshift(...batch);
      throw err;
    } finally {
      this._flushing = false;
    }
  }
}

module.exports = { LogBuffer };
