   * @param {string} options.serviceName - Name of the ingesting service
   * @param {string} options.environment - Deployment environment (e.g., production)
   * @param {Function[]} options.transforms - Additional transform functions
   */
  constructor(options = {}) {
    this.serviceName = options.serviceName || 'log-ingestion';
    this.environment = options.environment || process.env.NODE_ENV || 'development';
    this.transforms = options.transforms || [];
  }

  /**
   * Processes a single log entry — enriches with id, timestamp, service info.
   * @param {object} entry - A validated/sanitized entry.
   * @returns {object} Fully enriched log record.
   */
  process(entry) {
    let record = {
      id: uuidv4(),
      timestamp: entry.timestamp || new Date().toISOString(),
      ingestedAt: new Date().toISOString(),
      level: entry.level,
      message: entry.message,
      source: entry.source || 'unknown',
      service: this.serviceName,
      environment: this.environment,
      metadata: entry.metadata || {},
    };

    // Apply custom transforms in order
    for (const transform of this.transforms) {
      record = transform(record);
    }

    return record;
  }

  /**
   * Processes a batch of entries.
   * @param {object[]} entries
   * @returns {{ processed: object[], failed: { entry: object, error: Error }[] }}
   */
  processBatch(entries) {
    const processed = [];
    const failed = [];

    for (const entry of entries) {
      try {
        processed.push(this.process(entry));
      } catch (error) {
        failed.push({ entry, error });
      }
    }

    return { processed, failed };
  }

  /**
   * Adds a transform function to the pipeline.
   * @param {Function} fn - (record) => record
   */
  addTransform(fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('Transform must be a function');
    }
    this.transforms.push(fn);
  }
}

module.exports = { LogProcessor };
