// model/ModerationResult.java
package moderation.model;

import java.util.List;
import java.util.ArrayList;
import java.util.Collections;

public final class ModerationResult {

    public enum Action { APPROVE, FLAG_FOR_REVIEW, REJECT, MUTE_USER }
    public enum Severity { NONE, LOW, MEDIUM, HIGH, CRITICAL }

    private final ChatMessage message;
    private final Action action;
    private final Severity severity;
    private final List<String> violations;

    private ModerationResult(ChatMessage message, Action action,
                             Severity severity, List<String> violations) {
        this.message = message;
        this.action = action;
        this.severity = severity;
        this.violations = List.copyOf(violations);
    }

    // Getters
    public ChatMessage message()       { return message; }
    public Action action()             { return action; }
    public Severity severity()         { return severity; }
    public List<String> violations()   { return violations; }
    public boolean isClean()           { return violations.isEmpty(); }

    // Builder — accumulates violations from multiple rules
    public static class Builder {
        private final ChatMessage message;
        private final List<String> violations = new ArrayList<>();
        private Severity worstSeverity = Severity.NONE;

        public Builder(ChatMessage message) {
            this.message = message;
        }

        public Builder addViolation(String reason, Severity severity) {
            violations.add(reason);
            if (severity.ordinal() > worstSeverity.ordinal()) {
                worstSeverity = severity;
            }
            return this;
        }

        public ModerationResult build() {
            Action action = switch (worstSeverity) {
                case NONE       -> Action.APPROVE;
                case LOW        -> Action.APPROVE;      // log only
                case MEDIUM     -> Action.FLAG_FOR_REVIEW;
                case HIGH       -> Action.REJECT;
                case CRITICAL   -> Action.MUTE_USER;
            };
            return new ModerationResult(message, action, worstSeverity, violations);
        }
    }

    @Override
    public String toString() {
        return "ModerationResult{action=%s, severity=%s, violations=%s, msgId=%s}"
            .formatted(action, severity, violations, message.messageId());
    }
}
