package moderation.rules;

import moderation.model.ChatMessage;
import moderation.model.ModerationResult;
import moderation.model.ModerationResult.Severity;

import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class ProfanityRule implements ModerationRule {

    // In production: load from a config file or remote service
    private static final Set<String> BLOCKED_WORDS = Set.of(
        "badword1", "badword2", "slur1"
    );

    private static final Set<String> FLAGGED_WORDS = Set.of(
        "mildword1", "mildword2"
    );

    // Pre-compiled patterns for whole-word matching
    private final Pattern blockedPattern;
    private final Pattern flaggedPattern;

    public ProfanityRule() {
        blockedPattern = buildPattern(BLOCKED_WORDS);
        flaggedPattern = buildPattern(FLAGGED_WORDS);
    }

    @Override
    public void evaluate(ChatMessage message, ModerationResult.Builder result) {
        String text = message.content().toLowerCase();

        if (blockedPattern.matcher(text).find()) {
            result.addViolation("Blocked profanity detected", Severity.HIGH);
        } else if (flaggedPattern.matcher(text).find()) {
            result.addViolation("Mild profanity detected", Severity.MEDIUM);
        }
    }

    private static Pattern buildPattern(Set<String> words) {
        String joined = words.stream()
            .map(Pattern::quote)
            .collect(Collectors.joining("|"));
        return Pattern.compile("\\b(" + joined + ")\\b", Pattern.CASE_INSENSITIVE);
    }
}
