// rules/SpamRule.java
package moderation.rules;

import moderation.model.ChatMessage;
import moderation.model.ModerationResult;
import moderation.model.ModerationResult.Severity;

import java.util.regex.Pattern;

public class SpamRule implements ModerationRule {

    private static final int MAX_LENGTH = 2000;
    private static final int MAX_CAPS_PERCENT = 70;
    private static final int MIN_CAPS_CHECK_LENGTH = 10;
    private static final int MAX_REPEATED_CHARS = 8;
    private static final int MAX_LINKS = 3;

    private static final Pattern LINK_PATTERN =
        Pattern.compile("https?://\\S+", Pattern.CASE_INSENSITIVE);

    private static final Pattern REPEATED_CHAR_PATTERN =
        Pattern.compile("(.)\\1{" + (MAX_REPEATED_CHARS - 1) + ",}");

    @Override
    public void evaluate(ChatMessage message, ModerationResult.Builder result) {
        String text = message.content();

        // Message too long
        if (text.length() > MAX_LENGTH) {
            result.addViolation("Message exceeds max length (%d)".formatted(MAX_LENGTH),
                                Severity.MEDIUM);
        }

        // Excessive caps
        if (text.length() >= MIN_CAPS_CHECK_LENGTH) {
            long upperCount = text.chars().filter(Character::isUpperCase).count();
            long letterCount = text.chars().filter(Character::isLetter).count();
            if (letterCount > 0 && (upperCount * 100 / letterCount) > MAX_CAPS_PERCENT) {
                result.addViolation("Excessive caps (%d%%)".formatted(upperCount * 100 / letterCount),
                                    Severity.LOW);
            }
        }

        // Repeated characters (e.g. "aaaaaaaaaa")
        if (REPEATED_CHAR_PATTERN.matcher(text).find()) {
            result.addViolation("Repeated character spam", Severity.MEDIUM);
        }

        // Too many links
        long linkCount = LINK_PATTERN.matcher(text).results().count();
        if (linkCount > MAX_LINKS) {
            result.addViolation("Too many links (%d)".formatted(linkCount), Severity.HIGH);
        }
    }
}
