// rules/RateLimitRule.java
package moderation.rules;

import moderation.model.ChatMessage;
import moderation.model.ModerationResult;
import moderation.model.ModerationResult.Severity;

import java.time.Instant;
import java.util.Deque;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.time.Duration;

public class RateLimitRule implements ModerationRule {

    private final int maxMessages;
    private final Duration window;

    // userId -> timestamps of recent messages
    private final ConcurrentHashMap<String, Deque<Instant>> history =
        new ConcurrentHashMap<>();

    public RateLimitRule(int maxMessages, Duration window) {
        this.maxMessages = maxMessages;
        this.window = window;
    }

    @Override
    public void evaluate(ChatMessage message, ModerationResult.Builder result) {
        String userId = message.userId();
        Instant now = message.timestamp();
        Instant cutoff = now.minus(window);

        Deque<Instant> timestamps = history.computeIfAbsent(userId,
            k -> new ConcurrentLinkedDeque<>());

        // Evict old entries
        while (!timestamps.isEmpty() && timestamps.peekFirst().isBefore(cutoff)) {
            timestamps.pollFirst();
        }

        timestamps.addLast(now);

        if (timestamps.size() > maxMessages) {
            result.addViolation(
                "Rate limit exceeded: %d msgs in %ds".formatted(timestamps.size(), window.toSeconds()),
                Severity.CRITICAL
            );
        }
    }
}
