package moderation.action;

import moderation.model.ModerationResult;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ModerationActionHandler {

    private static final Logger log = LoggerFactory.getLogger(ModerationActionHandler.class);

    public void handle(ModerationResult result) {
        switch (result.action()) {
            case APPROVE -> approve(result);
            case FLAG_FOR_REVIEW -> flag(result);
            case REJECT -> reject(result);
            case MUTE_USER -> mute(result);
        }
    }

    private void approve(ModerationResult r) {
        log.info("✅ APPROVED  [{}] user={} \"{}\"",
            r.message().messageId(),
            r.message().userId(),
            truncate(r.message().content()));

        // publish to "approved-messages" topic / forward to chat service
    }

    private void flag(ModerationResult r) {
        log.warn("⚠️  FLAGGED   [{}] user={} reasons={} \"{}\"",
            r.message().messageId(),
            r.message().userId(),
            r.violations(),
            truncate(r.message().content()));

        // insert into review_queue table / send to moderation dashboard
    }

    private void reject(ModerationResult r) {
        log.warn("🚫 REJECTED  [{}] user={} reasons={}",
            r.message().messageId(),
            r.message().userId(),
            r.violations());

        // notify user their message was blocked
    }

    private void mute(ModerationResult r) {
        log.error("🔇 MUTED     [{}] user={} reasons={}",
            r.message().messageId(),
            r.message().userId(),
            r.violations());

        // call user-service to temporarily mute
        // persist mute event for audit trail
    }

    private static String truncate(String s) {
        return s.length() <= 80 ? s : s.substring(0, 77) + "...";
    }
}
