// consumer/ModerationConsumer.java
package moderation.consumer;

import moderation.action.ModerationActionHandler;
import moderation.model.ChatMessage;
import moderation.model.ModerationResult;
import moderation.rules.ModerationRule;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Pulls ChatMessages off a queue, runs moderation rules, dispatches actions.
 *
 * Swap BlockingQueue for a Kafka/RabbitMQ/SQS consumer in production —
 * the processing loop stays the same.
 */
public class ModerationConsumer implements Runnable {

    private static final Logger log = LoggerFactory.getLogger(ModerationConsumer.class);

    private final BlockingQueue<ChatMessage> queue;
    private final List<ModerationRule> rules;
    private final ModerationActionHandler actionHandler;
    private final AtomicBoolean running = new AtomicBoolean(true);
    private final String consumerId;

    public ModerationConsumer(String consumerId,
                              BlockingQueue<ChatMessage> queue,
                              List<ModerationRule> rules,
                              ModerationActionHandler actionHandler) {
        this.consumerId = consumerId;
        this.queue = queue;
        this.rules = rules;
        this.actionHandler = actionHandler;
    }

    @Override
    public void run() {
        log.info("[{}] Consumer started", consumerId);

        while (running.get()) {
            try {
                ChatMessage message = queue.take();   // blocks until available
                process(message);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                log.info("[{}] Consumer interrupted, shutting down", consumerId);
                break;
            } catch (Exception e) {
                // Don't let one bad message kill the consumer
                log.error("[{}] Error processing message", consumerId, e);
            }
        }

        log.info("[{}] Consumer stopped", consumerId);
    }

    private void process(ChatMessage message) {
        ModerationResult.Builder builder = new ModerationResult.Builder(message);

        for (ModerationRule rule : rules) {
            try {
                rule.evaluate(message, builder);
            } catch (Exception e) {
                log.error("[{}] Rule {} failed for msg {}",
                    consumerId, rule.getClass().getSimpleName(),
                    message.messageId(), e);
                // Fail open: don't block the message because one rule threw
            }
        }

        ModerationResult result = builder.build();
        actionHandler.handle(result);
    }

    public void stop() {
        running.set(false);
    }
}
