```javascript
/**
 * Validates events against a schema definition.
 * Rejects or tags events that don't meet requirements.
 */
class ValidateStage {
  constructor(schema, { strict = false } = {}) {
    if (!schema || typeof schema !== "object") {
      throw new Error("ValidateStage requires a schema object");
    }
    this.schema = schema;
    this.strict = strict; // strict mode drops invalid events entirely
    this.errors = [];
  }

  /**
   * Validate a single event against the schema
   * @param {Object} event
   * @returns {{ valid: boolean, errors: string[] }}
   */
  validateEvent(event) {
    const errors = [];

    for (const [field, rules] of Object.entries(this.schema)) {
      const value = event[field];

      // Check required fields
      if (rules.required && (value === undefined || value === null)) {
        errors.push(`Missing required field: "${field}"`);
        continue;
      }

      // Skip further checks if field is absent and not required
      if (value === undefined || value === null) continue;

      // Type checking
      if (rules.type && typeof value !== rules.type) {
        errors.push(
          `Field "${field}" expected type "${rules.type}", got "${typeof value}"`
        );
      }

      // Enum validation
      if (rules.enum && !rules.enum.includes(value)) {
        errors.push(
          `Field "${field}" must be one of [${rules.enum.join(", ")}], got "${value}"`
        );
      }

      // Min value (for numbers)
      if (rules.min !== undefined && typeof value === "number" && value < rules.min) {
        errors.push(
          `Field "${field}" must be >= ${rules.min}, got ${value}`
        );
      }

      // Max value (for numbers)
      if (rules.max !== undefined && typeof value === "number" && value > rules.max) {
        errors.push(
          `Field "${field}" must be <= ${rules.max}, got ${value}`
        );
      }

      // Pattern matching (for strings)
      if (rules.pattern && typeof value === "string" && !rules.pattern.test(value)) {
        errors.push(
          `Field "${field}" does not match required pattern`
        );
      }

      // Custom validator function
      if (rules.validate && typeof rules.validate === "function") {
        const customResult = rules.validate(value);
        if (customResult !== true) {
          errors.push(
            `Field "${field}" failed custom validation: ${customResult || "invalid"}`
          );
        }
      }
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Process a batch of events
   * @param {Object[]} events
   * @returns {Object[]} validated events (tagged or filtered)
   */
  process(events) {
    this.errors = [];

    return events.reduce((result, event) => {
      const { valid, errors } = this.validateEvent(event);

      if (!valid) {
        this.errors.push({ event, errors });

        if (this.strict) {
          return result; // drop invalid events
        }

        // In non-strict mode, tag the event
        result.push({
          ...event,
          _validation: { valid: false, errors },
        });
      } else {
        result.push({
          ...event,
          _validation: { valid: true, errors: [] },
        });
      }

      return result;
    }, []);
  }

  getErrors() {
    return [...this.errors];
  }
}

module.exports = ValidateStage;
