/**
 * Filters events based on one or more predicate functions.
 * Supports both include and exclude modes.
 */
class FilterStage {
  constructor(predicates = [], { mode = "include" } = {}) {
    if (!Array.isArray(predicates)) {
      predicates = [predicates];
    }

    this.predicates = predicates.map((p) => {
      if (typeof p === "function") return p;
      throw new Error("Each predicate must be a function");
    });

    if (!["include", "exclude"].includes(mode)) {
      throw new Error('Mode must be "include" or "exclude"');
    }
    this.mode = mode;
    this.filtered = [];
  }

  /**
   * Test a single event against all predicates
   * @param {Object} event
   * @returns {boolean}
   */
  matches(event) {
    return this.predicates.every((predicate) => predicate(event));
  }

  /**
   * Process a batch of events
   * @param {Object[]} events
   * @returns {Object[]}
   */
  process(events) {
    this.filtered = [];

    return events.filter((event) => {
      const match = this.matches(event);
      const keep = this.mode === "include" ? match : !match;

      if (!keep) {
        this.filtered.push(event);
      }

      return keep;
    });
  }

  getFiltered() {
    return [...this.filtered];
  }
}

module.exports = FilterStage;
