/**
 * Transforms events by applying one or more transformation functions.
 * Supports field mapping, enrichment, and computed fields.
 */
class TransformStage {
  constructor(transformations = []) {
    if (!Array.isArray(transformations)) {
      transformations = [transformations];
    }

    this.transformations = transformations.map((t) => {
      if (typeof t === "function") return t;
      throw new Error("Each transformation must be a function");
    });
  }

  /**
   * Apply all transformations to a single event
   * @param {Object} event
   * @returns {Object}
   */
  transformEvent(event) {
    return this.transformations.reduce((result, transform) => {
      const transformed = transform(result);
      if (!transformed || typeof transformed !== "object") {
        throw new Error("Transformation must return an object");
      }
      return transformed;
    }, { ...event });
  }

  /**
   * Process a batch of events
   * @param {Object[]} events
   * @returns {Object[]}
   */
  process(events) {
    return events.map((event) => this.transformEvent(event));
  }

  /**
   * Factory: create a field renaming transformation
   */
  static renameFields(fieldMap) {
    return (event) => {
      const result = { ...event };
      for (const [oldName, newName] of Object.entries(fieldMap)) {
        if (oldName in result) {
          result[newName] = result[oldName];
          delete result[oldName];
        }
      }
      return result;
    };
  }

  /**
   * Factory: add a computed field
   */
  static addComputedField(fieldName, computeFn) {
    return (event) => ({
      ...event,
      [fieldName]: computeFn(event),
    });
  }

  /**
   * Factory: remove specified fields
   */
  static removeFields(fields) {
    return (event) => {
      const result = { ...event };
      fields.forEach((field) => delete result[field]);
      return result;
    };
  }

  /**
   * Factory: add a timestamp
   */
  static addTimestamp(fieldName = "processedAt") {
    return (event) => ({
      ...event,
      [fieldName]: new Date().toISOString(),
    });
  }
}

module.exports = TransformStage;
