/**
 * Aggregates events by grouping and computing metrics.
 * Supports count, sum, average, min, max, and custom aggregations.
 */
class AggregateStage {
  constructor(config) {
    if (!config || !config.groupBy) {
      throw new Error("AggregateStage requires a groupBy field");
    }

    this.groupBy = config.groupBy;
    this.metrics = config.metrics || [{ name: "count", type: "count" }];
  }

  /**
   * Extract the group key from an event
   */
  getGroupKey(event) {
    if (typeof this.groupBy === "function") {
      return this.groupBy(event);
    }

    if (Array.isArray(this.groupBy)) {
      return this.groupBy.map((field) => event[field]).join("::");
    }

    return String(event[this.groupBy] ?? "undefined");
  }

  /**
   * Compute a single metric across a group of events
   */
  computeMetric(metric, events) {
    switch (metric.type) {
      case "count":
        return events.length;

      case "sum":
        return events.reduce(
          (sum, e) => sum + (Number(e[metric.field]) || 0), 0
        );

      case "average": {
        const values = events
          .map((e) => e[metric.field])
          .filter((v) => v !== undefined && v !== null);
        if (values.length === 0) return 0;
        const total = values.reduce((sum, v) => sum + Number(v), 0);
        return total / values.length;
      }

      case "min": {
        const vals = events
          .map((e) => e[metric.field])
          .filter((v) => v !== undefined && v !== null)
          .map(Number);
        return vals.length > 0 ? Math.min(...vals) : null;
      }

      case "max": {
        const vals = events
          .map((e) => e[metric.field])
          .filter((v) => v !== undefined && v !== null)
          .map(Number);
        return vals.length > 0 ? Math.max(...vals) : null;
      }

      case "distinct": {
        const vals = events.map((e) => e[metric.field]);
        return [...new Set(vals)].length;
      }

      case "custom":
        if (typeof metric.fn !== "function") {
          throw new Error("Custom metric requires a fn function");
        }
        return metric.fn(events);

      default:
        throw new Error(`Unknown metric type: "${metric.type}"`);
    }
  }

  /**
   * Process a batch of events and return aggregated results
   * @param {Object[]} events
   * @returns {Object[]} aggregation results
   */
  process(events) {
    // Group events
    const groups = new Map();

    for (const event of events) {
      const key = this.getGroupKey(event);
      if (!groups.has(key)) {
        groups.set(key, []);
      }
      groups.get(key).push(event);
    }

    // Compute metrics for each group
    const results = [];

    for (const [key, groupEvents] of groups) {
      const result = { group: key };

      for (const metric of this.metrics) {
        const metricName = metric.name || `${metric.type}_${metric.field || ""}`;
        result[metricName] = this.computeMetric(metric, groupEvents);
      }

      results.push(result);
    }

    return results;
  }
}

module.exports = AggregateStage;
