/**
 * Core Pipeline class that chains processing stages.
 * Supports sequential execution, error handling, and metrics.
 */
class Pipeline {
  constructor(name = "default") {
    this.name = name;
    this.stages = [];
    this.hooks = {
      beforeStage: [],
      afterStage: [],
      onError: [],
    };
    this.metrics = {
      inputCount: 0,
      outputCount: 0,
      stageMetrics: [],
      startTime: null,
      endTime: null,
      errors: [],
    };
  }

  /**
   * Add a stage to the pipeline
   * @param {string} name
   * @param {Object} stage - must have a process(events) method
   * @returns {Pipeline} this (for chaining)
   */
  addStage(name, stage) {
    if (!stage || typeof stage.process !== "function") {
      throw new Error(`Stage "${name}" must have a process() method`);
    }

    this.stages.push({ name, stage });
    return this;
  }

  /**
   * Register a hook
   */
  on(event, callback) {
    if (!this.hooks[event]) {
      throw new Error(`Unknown hook event: "${event}"`);
    }
    this.hooks[event].push(callback);
    return this;
  }

  /**
   * Emit a hook event
   */
  _emit(event, data) {
    for (const callback of this.hooks[event]) {
      callback(data);
    }
  }

  /**
   * Execute the full pipeline
   * @param {Object[]} events - input events
   * @returns {{ results: Object[], metrics: Object }}
   */
  execute(events) {
    if (!Array.isArray(events)) {
      throw new Error("Pipeline input must be an array");
    }

    this.metrics = {
      inputCount: events.length,
      outputCount: 0,
      stageMetrics: [],
      startTime: Date.now(),
      endTime: null,
      errors: [],
    };

    let currentData = [...events];

    for (const { name, stage } of this.stages) {
      const stageStart = Date.now();
      const inputCount = currentData.length;

      try {
        this._emit("beforeStage", {
          stageName: name,
          inputCount,
          data: currentData,
        });

        currentData = stage.process(currentData);

        const stageMetric = {
          name,
          inputCount,
          outputCount: currentData.length,
          duration: Date.now() - stageStart,
        };

        this.metrics.stageMetrics.push(stageMetric);

        this._emit("afterStage", {
          stageName: name,
          metric: stageMetric,
          data: currentData,
        });
      } catch (error) {
        const errorInfo = {
          stage: name,
          error: error.message,
          timestamp: Date.now(),
        };

        this.metrics.errors.push(errorInfo);
        this._emit("onError", errorInfo);

        throw new Error(
          `Pipeline "${this.name}" failed at stage "${name}": ${error.message}`
        );
      }
    }

    this.metrics.outputCount = currentData.length;
    this.metrics.endTime = Date.now();

    return {
      results: currentData,
      metrics: { ...this.metrics },
    };
  }

  /**
   * Get a summary of the last pipeline run
   */
  getSummary() {
    const duration = this.metrics.endTime
      ? this.metrics.endTime - this.metrics.startTime
      : null;

    return {
      pipeline: this.name,
      inputCount: this.metrics.inputCount,
      outputCount: this.metrics.outputCount,
      totalDuration: duration,
      stages: this.metrics.stageMetrics.map((s) => ({
        name: s.name,
        inputCount: s.inputCount,
        outputCount: s.outputCount,
        duration: s.duration,
        dropRate:
          s.inputCount > 0
            ? ((s.inputCount - s.outputCount) / s.inputCount * 100).toFixed(1) + "%"
            : "0%",
      })),
      errors: this.metrics.errors,
    };
  }
}

module.exports = Pipeline;
