## SearchIndex.java — Inverted Index

```java
import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class SearchIndex {

    // word -> set of file paths containing that word
    private final Map<String, Set<String>> invertedIndex = new ConcurrentHashMap<>();
    // file path -> set of words (for fast removal on update/delete)
    private final Map<String, Set<String>> fileWords = new ConcurrentHashMap<>();

    /**
     * Add or re-index a file.
     */
    public void indexFile(Path path) {
        // Remove old entries first (handles updates)
        removeFile(path);

        try {
            String content = Files.readString(path);
            Set<String> words = tokenize(content);

            fileWords.put(path.toString(), words);

            for (String word : words) {
                invertedIndex.computeIfAbsent(word, k -> ConcurrentHashMap.newKeySet())
                             .add(path.toString());
            }

            System.out.println("[INDEX] Indexed: " + path + " (" + words.size() + " unique terms)");
        } catch (IOException e) {
            System.err.println("[INDEX] Failed to read: " + path + " — " + e.getMessage());
        }
    }

    /**
     * Remove a file from the index.
     */
    public void removeFile(Path path) {
        Set<String> words = fileWords.remove(path.toString());
        if (words == null) return;

        for (String word : words) {
            Set<String> files = invertedIndex.get(word);
            if (files != null) {
                files.remove(path.toString());
                if (files.isEmpty()) {
                    invertedIndex.remove(word);
                }
            }
        }
        System.out.println("[INDEX] Removed: " + path);
    }

    /**
     * Search for files containing ALL given query terms.
     */
    public List<String> search(String query) {
        Set<String> terms = tokenize(query);
        if (terms.isEmpty()) return Collections.emptyList();

        Iterator<String> it = terms.iterator();
        Set<String> result = new HashSet<>(
            invertedIndex.getOrDefault(it.next(), Collections.emptySet())
        );

        while (it.hasNext()) {
            result.retainAll(
                invertedIndex.getOrDefault(it.next(), Collections.emptySet())
            );
        }

        return new ArrayList<>(result);
    }

    public int totalFiles() {
        return fileWords.size();
    }

    public int totalTerms() {
        return invertedIndex.size();
    }

    private Set<String> tokenize(String text) {
        return Arrays.stream(text.toLowerCase().split("[^a-zA-Z0-9]+"))
                     .filter(w -> !w.isBlank() && w.length() > 1)
                     .collect(Collectors.toSet());
    }
}
