## FileWatcher.java — Directory Monitor

```java
import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;

import static java.nio.file.StandardWatchEventKinds.*;

public class FileWatcher implements Runnable {

    private final Path rootDir;
    private final SearchIndex index;
    private final WatchService watchService;

    public FileWatcher(Path rootDir, SearchIndex index) throws IOException {
        this.rootDir = rootDir;
        this.index = index;
        this.watchService = FileSystems.getDefault().newWatchService();
    }

    /**
     * Index all existing files, then watch for changes.
     */
    @Override
    public void run() {
        try {
            indexExistingFiles();
            registerDirectories();
            System.out.println("[WATCHER] Watching: " + rootDir);
            pollEvents();
        } catch (IOException | InterruptedException e) {
            System.err.println("[WATCHER] Error: " + e.getMessage());
            Thread.currentThread().interrupt();
        }
    }

    private void indexExistingFiles() throws IOException {
        Files.walkFileTree(rootDir, new SimpleFileVisitor<>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                if (isTextFile(file)) {
                    index.indexFile(file);
                }
                return FileVisitResult.CONTINUE;
            }
        });
        System.out.println("[WATCHER] Initial indexing complete — "
                + index.totalFiles() + " files, "
                + index.totalTerms() + " terms");
    }

    private void registerDirectories() throws IOException {
        Files.walkFileTree(rootDir, new SimpleFileVisitor<>() {
            @Override
            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs)
                    throws IOException {
                dir.register(watchService, ENTRY_CREATE, ENTRY_MODIFY, ENTRY_DELETE);
                return FileVisitResult.CONTINUE;
            }
        });
    }

    private void pollEvents() throws InterruptedException, IOException {
        while (!Thread.currentThread().isInterrupted()) {
            WatchKey key = watchService.take(); // blocks until event
            Path dir = (Path) key.watchable();

            for (WatchEvent<?> event : key.pollEvents()) {
                WatchEvent.Kind<?> kind = event.kind();
                if (kind == StandardWatchEventKinds.OVERFLOW) continue;

                Path changed = dir.resolve((Path) event.context());

                if (kind == ENTRY_DELETE) {
                    index.removeFile(changed);
                } else if (isTextFile(changed) && Files.isRegularFile(changed)) {
                    // Handles both CREATE and MODIFY
                    index.indexFile(changed);
                }

                // If a new directory was created, register it too
                if (kind == ENTRY_CREATE && Files.isDirectory(changed)) {
                    changed.register(watchService, ENTRY_CREATE, ENTRY_MODIFY, ENTRY_DELETE);
                    System.out.println("[WATCHER] Now watching new dir: " + changed);
                }
            }

            if (!key.reset()) {
                System.out.println("[WATCHER] Directory no longer accessible: " + dir);
                break;
            }
        }
    }

    private boolean isTextFile(Path path) {
        String name = path.getFileName().toString().toLowerCase();
        return name.endsWith(".txt")
            || name.endsWith(".md")
            || name.endsWith(".java")
            || name.endsWith(".html")
            || name.endsWith(".json")
            || name.endsWith(".xml")
            || name.endsWith(".csv")
            || name.endsWith(".log");
    }
}
