            Thread watcherThread = new Thread(watcher, "file-watcher");
            watcherThread.setDaemon(true);
            watcherThread.start();
        } catch (IOException e) {
            System.err.println("Failed to start watcher: " + e.getMessage());
            return;
        }

        // Interactive search loop
        System.out.println("\n=== File Search Indexer ===");
        System.out.println("Watching: " + root);
        System.out.println("Type a query to search, 'stats' for index info, 'quit' to exit.\n");

