## Token Bucket Rate Limiter

```java
package ratelimit;

import java.util.concurrent.locks.ReentrantLock;

/**
 * Thread-safe token bucket rate limiter.
 * Tokens are added at a fixed rate up to a max capacity.
 * Each operation consumes one token; if none are available, it waits or rejects.
 */
public class TokenBucketRateLimiter {

    private final int maxTokens;
    private final double refillRatePerSecond;
    private double availableTokens;
    private long lastRefillNanos;
    private final ReentrantLock lock = new ReentrantLock();

    public TokenBucketRateLimiter(int maxTokens, double refillRatePerSecond) {
        if (maxTokens <= 0 || refillRatePerSecond <= 0) {
            throw new IllegalArgumentException("maxTokens and refillRate must be positive");
        }
        this.maxTokens = maxTokens;
        this.refillRatePerSecond = refillRatePerSecond;
        this.availableTokens = maxTokens; // start full
        this.lastRefillNanos = System.nanoTime();
    }

    /**
     * Try to acquire a token without blocking.
     * @return true if a token was acquired, false otherwise
     */
    public boolean tryAcquire() {
        lock.lock();
        try {
            refill();
            if (availableTokens >= 1.0) {
                availableTokens -= 1.0;
                return true;
            }
            return false;
        } finally {
            lock.unlock();
        }
    }

    /**
     * Block until a token is available, with a timeout.
     * @param timeoutMillis max time to wait in milliseconds
     * @return true if a token was acquired within the timeout
     * @throws InterruptedException if the thread is interrupted while waiting
     */
    public boolean acquire(long timeoutMillis) throws InterruptedException {
        long deadline = System.currentTimeMillis() + timeoutMillis;

        while (System.currentTimeMillis() < deadline) {
            if (tryAcquire()) {
                return true;
            }
            // Sleep briefly before retrying — avoids busy-waiting
            long waitMs = Math.min(getEstimatedWaitMillis(), deadline - System.currentTimeMillis());
            if (waitMs > 0) {
                Thread.sleep(waitMs);
            }
        }
        return false;
    }

    /**
     * Block indefinitely until a token is available.
     * @throws InterruptedException if the thread is interrupted while waiting
     */
    public void acquire() throws InterruptedException {
        while (!tryAcquire()) {
            long waitMs = getEstimatedWaitMillis();
            if (waitMs > 0) {
                Thread.sleep(waitMs);
            }
        }
    }

    /**
     * Estimated milliseconds until the next token is available.
     */
    public long getEstimatedWaitMillis() {
        lock.lock();
        try {
            refill();
            if (availableTokens >= 1.0) {
                return 0;
            }
            double tokensNeeded = 1.0 - availableTokens;
            return (long) Math.ceil((tokensNeeded / refillRatePerSecond) * 1000);
        } finally {
            lock.unlock();
        }
    }

    /**
     * Current number of available tokens (snapshot).
     */
    public double getAvailableTokens() {
        lock.lock();
        try {
            refill();
            return availableTokens;
        } finally {
            lock.unlock();
        }
    }

    // -- internals --

    private void refill() {
        long now = System.nanoTime();
        double elapsed = (now - lastRefillNanos) / 1_000_000_000.0;
        double tokensToAdd = elapsed * refillRatePerSecond;

        if (tokensToAdd > 0) {
            availableTokens = Math.min(maxTokens, availableTokens + tokensToAdd);
            lastRefillNanos = now;
        }
    }
}
