package ratelimit;

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Consumer;

/**
 * Background worker that pulls tasks from a queue and processes them
 * while respecting a configurable rate limit.
 *
 * Features:
 *  - Token-bucket rate limiting
 *  - Configurable retry with exponential backoff
 *  - Multiple worker threads
 *  - Graceful shutdown
 *  - Basic metrics
 */
public class RateLimitedWorker<T> {

    // --- configuration ---
    private final String name;
    private final BlockingQueue<T> taskQueue;
    private final TokenBucketRateLimiter rateLimiter;
    private final Consumer<T> taskHandler;
    private final int workerCount;
    private final int maxRetries;
    private final long baseRetryDelayMs;
    private final long acquireTimeoutMs;

    // --- runtime state ---
    private final ExecutorService executor;
    private final ScheduledExecutorService scheduler;
    private volatile boolean running;

    // --- metrics ---
    private final AtomicLong processedCount  = new AtomicLong();
    private final AtomicLong failedCount     = new AtomicLong();
    private final AtomicLong retriedCount    = new AtomicLong();
    private final AtomicLong rateLimitedCount = new AtomicLong();

    // --- builder ---

    public static class Builder<T> {
        private final String name;
        private final Consumer<T> handler;

        private int    queueCapacity      = 1000;
        private int    maxTokens          = 10;
        private double refillRate         = 5.0;   // tokens/sec
        private int    workerCount        = 1;
        private int    maxRetries         = 3;
        private long   baseRetryDelayMs   = 1000;
        private long   acquireTimeoutMs   = 5000;

        public Builder(String name, Consumer<T> handler) {
            this.name    = name;
            this.handler = handler;
        }

        public Builder<T> queueCapacity(int v)      { queueCapacity = v;    return this; }
        public Builder<T> maxTokens(int v)           { maxTokens = v;        return this; }
        public Builder<T> refillRate(double v)       { refillRate = v;       return this; }
        public Builder<T> workerCount(int v)         { workerCount = v;      return this; }
        public Builder<T> maxRetries(int v)          { maxRetries = v;       return this; }
        public Builder<T> baseRetryDelayMs(long v)   { baseRetryDelayMs = v; return this; }
        public Builder<T> acquireTimeoutMs(long v)   { acquireTimeoutMs = v; return this; }

        public RateLimitedWorker<T> build() {
            return new RateLimitedWorker<>(this);
        }
    }

    // --- construction ---

    private RateLimitedWorker(Builder<T> b) {
        this.name              = b.name;
        this.taskHandler       = b.handler;
        this.workerCount       = b.workerCount;
        this.maxRetries        = b.maxRetries;
        this.baseRetryDelayMs  = b.baseRetryDelayMs;
        this.acquireTimeoutMs  = b.acquireTimeoutMs;
        this.taskQueue         = new LinkedBlockingQueue<>(b.queueCapacity);
        this.rateLimiter       = new TokenBucketRateLimiter(b.maxTokens, b.refillRate);

        // Thread factory with descriptive names
        AtomicInteger threadNum = new AtomicInteger(1);
        ThreadFactory tf = r -> {
            Thread t = new Thread(r, name + "-worker-" + threadNum.getAndIncrement());
            t.setDaemon(true);
            return t;
        };

        this.executor  = Executors.newFixedThreadPool(b.workerCount, tf);
        this.scheduler = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r, name + "-scheduler");
            t.setDaemon(true);
            return t;
        });
    }

    // --- lifecycle ---

    /** Start the worker threads. */
    public void start() {
        if (running) return;
        running = true;
        for (int i = 0; i < workerCount; i++) {
            executor.submit(this::workerLoop);
        }
        System.out.printf("[%s] Started %d worker(s)  |  rate limit: %.1f req/s  burst: %s%n",
                name, workerCount, rateLimiter.getAvailableTokens(),
                rateLimiter.getAvailableTokens());
    }

    /** Graceful shutdown: finish queued tasks, then stop. */
    public void shutdown() {
        System.out.printf("[%s] Shutting down...%n", name);
        running = false;
        executor.shutdown();
        scheduler.shutdown();
        try {
            if (!executor.awaitTermination(30, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
        System.out.printf("[%s] Shutdown complete.  %s%n", name, getStats());
    }

    // --- submitting work ---

    /**
     * Submit a task. Blocks if the queue is full.
     * @throws InterruptedException if interrupted while waiting for queue space
     */
    public void submit(T task) throws InterruptedException {
        taskQueue.put(task);
    }

    /**
     * Try to submit a task without blocking.
     * @return true if the task was enqueued
     */
    public boolean trySubmit(T task) {
        return taskQueue.offer(task);
    }

    // --- core worker loop ---

    private void workerLoop() {
        String threadName = Thread.currentThread().getName();
        System.out.printf("[%s] Worker loop started%n", threadName);

        while (running || !taskQueue.isEmpty()) {
            try {
                // 1. Pull next task (wait up to 1 s so we can check `running`)
                T task = taskQueue.poll(1, TimeUnit.SECONDS);
                if (task == null) continue;

                // 2. Acquire a rate-limit token
                if (!rateLimiter.acquire(acquireTimeoutMs)) {
                    rateLimitedCount.incrementAndGet();
                    System.out.printf("[%s] Rate-limit timeout — requeuing %s%n",
                            threadName, task);
                    taskQueue.put(task);       // put it back
                    continue;
                }

                // 3. Process
                processTask(task, threadName);

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        System.out.printf("[%s] Worker loop exited%n", threadName);
    }

    @SuppressWarnings("unchecked")
    private void processTask(T task, String threadName) {
        try {
            System.out.printf("[%s] Processing %s  (tokens left: %.1f)%n",
                    threadName, task, rateLimiter.getAvailableTokens());

            taskHandler.accept(task);
            processedCount.incrementAndGet();

        } catch (Exception ex) {
            failedCount.incrementAndGet();

            // --- retry logic (only works for Task subtype) ---
            if (task instanceof Task) {
                Task t = (Task) task;
                if (t.getRetryCount() < maxRetries) {
                    t.incrementRetry();
                    retriedCount.incrementAndGet();
                    long delay = baseRetryDelayMs * (1L << (t.getRetryCount() - 1)); // exp backoff
                    System.out.printf("[%s] Task %s failed (%s), retry #%d in %dms%n",
                            threadName, t.getId(), ex.getMessage(), t.getRetryCount(), delay);

                    scheduler.schedule(() -> {
                        try { taskQueue.put(task); }
                        catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
                    }, delay, TimeUnit.MILLISECONDS);
                } else {
                    System.out.printf("[%s] Task %s permanently failed after %d retries: %s%n",
                            threadName, t.getId(), t.getRetryCount(), ex.getMessage());
                }
            } else {
                System.out.printf("[%s] Task failed (no retry): %s%n",
                        threadName, ex.getMessage());
            }
        }
    }

    // --- metrics ---

    public String getStats() {
        return String.format(
            "Stats{processed=%d, failed=%d, retried=%d, rateLimited=%d, queued=%d}",
            processedCount.get(), failedCount.get(),
            retriedCount.get(), rateLimitedCount.get(), taskQueue.size());
    }

    public long getProcessedCount()   { return processedCount.get(); }
    public long getFailedCount()       { return failedCount.get(); }
    public int  getQueueSize()         { return taskQueue.size(); }
}
