class TaskScheduler {

    // ✅ FIX 4: Thread-safe priority queue
    private final PriorityBlockingQueue<Task> taskQueue = new PriorityBlockingQueue<>();

    // ✅ FIX 5: volatile for cross-thread visibility
    private volatile boolean running = false;

    private Thread schedulerThread;

    // ✅ FIX 6: ConcurrentHashMap for thread-safe access
    private final ConcurrentHashMap<String, Task> taskMap = new ConcurrentHashMap<>();

    // Thread pool for executing tasks (avoids blocking scheduler thread)
    private final ExecutorService executor = Executors.newFixedThreadPool(4);

    // Lock + condition for efficient waiting (FIX 9)
    private final Object lock = new Object();

    private static final DateTimeFormatter FMT =
            DateTimeFormatter.ofPattern("HH:mm:ss.SSS");


    public void addTask(Task task) {
        // ✅ FIX 7b: Null + duplicate check
        if (task == null)
            throw new IllegalArgumentException("Task cannot be null");

        if (taskMap.containsKey(task.getName()))
            throw new IllegalArgumentException(
                    "Duplicate task name: " + task.getName());

        taskMap.put(task.getName(), task);
        taskQueue.offer(task);

        log("Added: " + task.getName());

        // Wake scheduler if it's sleeping — new task might be sooner
        synchronized (lock) {
            lock.notify();
        }
    }

    public boolean cancelTask(String taskName) {
        // ✅ FIX 8: Null check and return status
        if (taskName == null) return false;

        Task task = taskMap.remove(taskName);
        if (task == null) {
            log("Cancel failed — task not found: " + taskName);
            return false;
        }

        task.cancel();
        log("Cancelled: " + taskName);

        // Wake scheduler to re-evaluate queue
        synchronized (lock) {
            lock.notify();
        }
        return true;
    }

    public void start() {
        if (running) {
            log("Scheduler is already running.");
            return;
        }

        running = true;
        schedulerThread = new Thread(this::schedulerLoop, "Scheduler-Thread");
        schedulerThread.setDaemon(true);
        schedulerThread.start();

        log("Scheduler started.");
    }

    private void schedulerLoop() {
        while (running) {
            try {
                Task task = taskQueue.peek();

                if (task == null) {
                    // ✅ FIX 9: Wait instead of busy-spin
                    synchronized (lock) {
                        lock.wait(1000);  // Wait until notified or 1s timeout
                    }
                    continue;
                }

                long now = System.currentTimeMillis();
                long delay = task.getScheduledTimeMs() - now;

                if (delay > 0) {
                    // ✅ FIX 9: Sleep precisely until next task is due
                    synchronized (lock) {
                        lock.wait(delay);
                    }
                    continue; // Re-check after waking (new task may have arrived)
                }

                // Remove the task from the queue
                taskQueue.poll();

                // ✅ FIX 10: Skip cancelled tasks
                if (task.isCancelled()) {
                    taskMap.remove(task.getName());
                    log("Skipped cancelled task: " + task.getName());
                    continue;
                }

                // Execute on thread pool — NOT on scheduler thread
                executor.submit(() -> {
                    try {
                        log("Executing: " + task.getName()
                                + " [priority=" + task.getPriority() + "]");
                        task.getAction().run();
                        log("Completed: " + task.getName());
                    } catch (Exception e) {
                        log("ERROR in task " + task.getName() + ": " + e.getMessage());
                    }
                });

                // Reschedule recurring tasks
                if (task.isRecurring() && !task.isCancelled()) {
                    task.reschedule();
                    taskQueue.offer(task);
                    log("Rescheduled: " + task.getName()
                            + " → next at +" + task.getIntervalMs() + "ms");
                } else {
                    taskMap.remove(task.getName());
                }

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                log("Scheduler interrupted.");
                break;
            }
        }

        log("Scheduler loop exited.");
    }

    public void stop() {
        log("Stopping scheduler...");
        running = false;

        // ✅ FIX: Interrupt + join for clean shutdown
        if (schedulerThread != null) {
            schedulerThread.interrupt();
            try {
                schedulerThread.join(5000);  // Wait up to 5 seconds
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        log("Scheduler stopped. Remaining tasks: " + taskQueue.size());
    }

    public int getQueueSize()       { return taskQueue.size(); }
    public int getRegisteredTasks() { return taskMap.size(); }

    private void log(String msg) {
        System.out.printf("[%s] [%s] %s%n",
                LocalDateTime.now().format(FMT),
                Thread.currentThread().getName(),
                msg);
    }
}


