    private Consumer<Exception> onError;
    private Runnable onCancelled;
    private Consumer<Integer> onProgressChanged;

    // --- Task definition ---
    private final WorkerTask<T> task;

    /**
     * Functional interface for the actual work.
     * Receives a CancellationToken to check for cancellation.
     */
    @FunctionalInterface
    public interface WorkerTask<T> {
        T execute(CancellationToken token) throws Exception;
    }

    /**
     * Token passed into the task so it can cooperatively check for cancellation
     * and report progress.
     */
    public static class CancellationToken {
        private final AtomicBoolean cancelFlag;
        private final AtomicInteger progressRef;
        private final Consumer<Integer> progressCallback;

        CancellationToken(AtomicBoolean cancelFlag,
                          AtomicInteger progressRef,
                          Consumer<Integer> progressCallback) {
            this.cancelFlag = cancelFlag;
            this.progressRef = progressRef;
            this.progressCallback = progressCallback;
        }

        /** Returns true if cancellation has been requested. */
        public boolean isCancellationRequested() {
            return cancelFlag.get();
        }

        /** Throws CancellationException if cancellation was requested. */
        public void throwIfCancelled() {
            if (cancelFlag.get()) {
                throw new CancellationException("Task was cancelled");
            }
        }

        /** Reports progress (0–100). */
        public void reportProgress(int percent) {
            int clamped = Math.max(0, Math.min(100, percent));
            progressRef.set(clamped);
            if (progressCallback != null) {
                progressCallback.accept(clamped);
            }
        }
    }

    // --- Constructor ---

    public BackgroundWorker(WorkerTask<T> task) {
        this(task, Executors.newSingleThreadExecutor(r -> {
            Thread t = new Thread(r, "BackgroundWorker");
            t.setDaemon(true);          // won't prevent JVM shutdown
            return t;
        }));
    }

    public BackgroundWorker(WorkerTask<T> task, ExecutorService executor) {
        this.task = task;
        this.executor = executor;
    }

    // --- Fluent callback setters ---

    public BackgroundWorker<T> onComplete(Consumer<T> callback) {
        this.onComplete = callback;
        return this;
    }

    public BackgroundWorker<T> onError(Consumer<Exception> callback) {
        this.onError = callback;
        return this;
    }

    public BackgroundWorker<T> onCancelled(Runnable callback) {
        this.onCancelled = callback;
        return this;
    }

    public BackgroundWorker<T> onProgressChanged(Consumer<Integer> callback) {
        this.onProgressChanged = callback;
        return this;
    }

    // --- Control methods ---

    /** Starts the background task. */
    public synchronized void start() {
        if (runningTask != null && !runningTask.isDone()) {
            throw new IllegalStateException("Worker is already running");
        }

        cancelRequested.set(false);
        progress.set(0);

        CancellationToken token = new CancellationToken(
                cancelRequested, progress, onProgressChanged
        );

        runningTask = executor.submit(() -> {
            try {
                T result = task.execute(token);

                if (cancelRequested.get()) {
                    invokeCallback(onCancelled);
                } else {
                    invokeCallback(onComplete, result);
                }
            } catch (CancellationException e) {
                invokeCallback(onCancelled);
            } catch (Exception e) {
                invokeCallback(onError, e);
            }
        });
    }

    /** Requests cooperative cancellation. */
    public void cancel() {
        cancelRequested.set(true);
        // Also interrupt the thread in case it's blocked on I/O or sleep
        Future<?> f = runningTask;
        if (f != null) {
            f.cancel(true);
        }
    }

    /** Returns true if the task is still running. */
    public boolean isRunning() {
        Future<?> f = runningTask;
        return f != null && !f.isDone();
    }

    /** Returns the last reported progress (0–100). */
    public int getProgress() {
        return progress.get();
    }

    /** Shuts down the executor (call when completely done). */
    public void shutdown() {
        executor.shutdownNow();
    }

    // --- Helpers ---

    private void invokeCallback(Runnable cb) {
        if (cb != null) cb.run();
    }

    private <V> void invokeCallback(Consumer<V> cb, V value) {
        if (cb != null) cb.accept(value);
    }
}
```

## Usage Example

```java
public class BackgroundWorkerDemo {

    public static void main(String[] args) throws InterruptedException {

        // 1. Define a long-running task
        BackgroundWorker<String> worker = new BackgroundWorker<>(token -> {
            StringBuilder result = new StringBuilder();

            for (int i = 1; i <= 100; i++) {
                // ✅ Cooperative cancellation check
                token.throwIfCancelled();

                // Simulate work
                Thread.sleep(50);
                result.append(".");

                // Report progress
                token.reportProgress(i);
            }

            return "Processed " + result.length() + " items";
        });

        // 2. Wire up callbacks
        worker
            .onProgressChanged(p -> System.out.printf("\rProgress: %d%%", p))
            .onComplete(result -> System.out.println("\n✅ Done: " + result))
            .onCancelled(() -> System.out.println("\n⛔ Cancelled at " + worker.getProgress() + "%"))
            .onError(ex -> System.out.println("\n❌ Error: " + ex.getMessage()));

        // 3. Start the worker
        System.out.println("Starting worker...");
        worker.start();

        // 4. Cancel after 2 seconds
        Thread.sleep(2000);
        System.out.println("\nRequesting cancellation...");
        worker.cancel();

        // Wait a moment for callback to fire
        Thread.sleep(500);
        worker.shutdown();
    }
}
```

## Polling-Style Cancellation (Alternative Pattern)

```java
// Instead of throwIfCancelled(), check the flag in a loop:
BackgroundWorker<List<String>> worker = new BackgroundWorker<>(token -> {
    List<String> results = new ArrayList<>();

    for (String url : urls) {
        // ✅ Check-and-break pattern
        if (token.isCancellationRequested()) {
            System.out.println("Stopping early, returning partial results");
            break;   // return what we have so far
        }

        results.add(download(url));
        token.reportProgress((results.size() * 100) / urls.size());
    }

    return results;   // partial or full results
});
```

