## JSON Document Parser

```kotlin
import kotlinx.serialization.json.*
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.encodeToString
import java.io.File

class DocumentParser {

    // Configure the JSON parser
    private val json = Json {
        prettyPrint = true          // formatted output
        ignoreUnknownKeys = true    // skip unknown fields
        isLenient = true            // relaxed parsing
        coerceInputValues = true    // use defaults for nulls
    }

    // --- Parse from String ---
    fun parseFromString(jsonString: String): Document {
        return json.decodeFromString<Document>(jsonString)
    }

    // --- Parse from File ---
    fun parseFromFile(filePath: String): Document {
        val content = File(filePath).readText()
        return parseFromString(content)
    }

    // --- Parse raw JSON (no model needed) ---
    fun parseRawJson(jsonString: String): JsonElement {
        return json.parseToJsonElement(jsonString)
    }

    // --- Extract specific fields dynamically ---
    fun extractField(jsonString: String, fieldName: String): String? {
        val element = json.parseToJsonElement(jsonString)
        return element.jsonObject[fieldName]?.toString()
    }

    // --- Convert Document back to JSON string ---
    fun toJsonString(document: Document): String {
        return json.encodeToString(document)
    }

    // --- Parse a list of documents ---
    fun parseDocumentList(jsonArray: String): List<Document> {
        return json.decodeFromString<List<Document>>(jsonArray)
    }
}
```

## Dynamic JSON Explorer (No Data Classes Needed)

```kotlin
class JsonExplorer {

    private val json = Json { ignoreUnknownKeys = true }

    // Walk through JSON and print structure
    fun explore(jsonString: String, indent: Int = 0) {
        val element = json.parseToJsonElement(jsonString)
        printElement("root", element, indent)
    }

    private fun printElement(key: String, element: JsonElement, indent: Int) {
        val prefix = "  ".repeat(indent)

        when (element) {
            is JsonObject -> {
                println("$prefix📁 \"$key\": {")
                element.jsonObject.forEach { (k, v) ->
                    printElement(k, v, indent + 1)
                }
                println("$prefix}")
            }
            is JsonArray -> {
                println("$prefix📋 \"$key\": [${element.size} items]")
                element.forEachIndexed { index, item ->
                    printElement("[$index]", item, indent + 1)
                }
            }
            is JsonPrimitive -> {
                val type = when {
                    element.isString       -> "String"
                    element.booleanOrNull != null -> "Boolean"
                    element.intOrNull != null     -> "Int"
                    element.doubleOrNull != null  -> "Double"
                    else -> "Null"
                }
                println("$prefix📄 \"$key\": ${element.content} ($type)")
            }
        }
    }

    // Extract all values for a given key (recursive search)
    fun findAllByKey(jsonString: String, targetKey: String): List<String> {
        val element = json.parseToJsonElement(jsonString)
        val results = mutableListOf<String>()
        searchKey(element, targetKey, results)
        return results
    }

    private fun searchKey(element: JsonElement, targetKey: String, results: MutableList<String>) {
        when (element) {
            is JsonObject -> {
                element.jsonObject.forEach { (key, value) ->
                    if (key == targetKey) {
                        results.add(value.toString())
                    }
                    searchKey(value, targetKey, results)
                }
            }
            is JsonArray -> {
                element.forEach { searchKey(it, targetKey, results) }
            }
            else -> { /* primitives — nothing to recurse */ }
        }
    }
}
```

