fun main() {
    // ---- Sample JSON input ----
    val sampleJson = """
    {
        "title": "Kotlin Programming Guide",
        "author": {
            "name": "Jane Doe",
            "email": "jane@example.com"
        },
        "pages": 350,
        "tags": ["kotlin", "programming", "jvm"],
        "sections": [
            {
                "heading": "Introduction",
                "content": "Welcome to Kotlin programming.",
                "subsections": [
                    {
