                    }
                ]
            },
            {
                "heading": "Data Classes",
                "content": "Data classes hold data with minimal boilerplate."
            }
        ]
    }
    """.trimIndent()

    val parser = DocumentParser()
    val explorer = JsonExplorer()

    // 1) Parse into a typed object
    println("=== Typed Parsing ===")
    val doc = parser.parseFromString(sampleJson)
    println("Title  : ${doc.title}")
    println("Author : ${doc.author.name} (${doc.author.email})")
    println("Pages  : ${doc.pages}")
    println("Tags   : ${doc.tags.joinToString()}")
    println("Sections: ${doc.sections.size}")
    doc.sections.forEach { section ->
        println("  • ${section.heading}: ${section.content}")
        section.subsections.forEach { sub ->
            println("    └─ ${sub.heading}: ${sub.content}")
        }
    }

    // 2) Convert back to JSON
    println("\n=== Serialize Back to JSON ===")
    println(parser.toJsonString(doc))

    // 3) Extract a single field dynamically
    println("\n=== Dynamic Field Extraction ===")
    println("title = ${parser.extractField(sampleJson, "title")}")
    println("pages = ${parser.extractField(sampleJson, "pages")}")

    // 4) Explore the full structure
    println("\n=== JSON Structure Explorer ===")
    explorer.explore(sampleJson)

    // 5) Recursive key search
    println("\n=== Find All 'heading' Values ===")
    val headings = explorer.findAllByKey(sampleJson, "heading")
    headings.forEach { println("  → $it") }
}
