## Config Parser Header

```cpp
// config_parser.h
#pragma once

#include <string>
#include <unordered_map>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <vector>
#include <functional>
#include <algorithm>
#include <iostream>
#include <optional>

// ─── Parsed config value with type conversions ───────────────────────────
class ConfigValue {
    std::string raw_;

public:
    ConfigValue() = default;
    explicit ConfigValue(std::string value) : raw_(std::move(value)) {}

    // String (default)
    const std::string& as_string() const { return raw_; }

    // Integer
    int as_int() const {
        try { return std::stoi(raw_); }
        catch (...) {
            throw std::runtime_error("Cannot convert '" + raw_ + "' to int");
        }
    }

    // Float
    float as_float() const {
        try { return std::stof(raw_); }
        catch (...) {
            throw std::runtime_error("Cannot convert '" + raw_ + "' to float");
        }
    }

    // Double
    double as_double() const {
        try { return std::stod(raw_); }
        catch (...) {
            throw std::runtime_error("Cannot convert '" + raw_ + "' to double");
        }
    }

    // Boolean ("true", "1", "yes", "on" → true)
    bool as_bool() const {
        std::string lower = raw_;
        std::transform(lower.begin(), lower.end(), lower.begin(), ::tolower);
        return lower == "true" || lower == "1" || lower == "yes" || lower == "on";
    }

    // Implicit string conversion
    operator const std::string&() const { return raw_; }

    bool empty() const { return raw_.empty(); }
};

// ─── Section: a named group of key-value pairs ──────────────────────────
class ConfigSection {
    std::string name_;
    std::unordered_map<std::string, ConfigValue> values_;

public:
    explicit ConfigSection(std::string name = "") : name_(std::move(name)) {}

    void set(const std::string& key, const std::string& value) {
        values_[key] = ConfigValue(value);
    }

    // Access with bounds checking
    const ConfigValue& get(const std::string& key) const {
        auto it = values_.find(key);
        if (it == values_.end())
            throw std::runtime_error("Key '" + key + "' not found in [" + name_ + "]");
        return it->second;
    }

    // Access with default fallback
    ConfigValue get_or(const std::string& key, const std::string& fallback) const {
        auto it = values_.find(key);
        return (it != values_.end()) ? it->second : ConfigValue(fallback);
    }

    // Check existence
    bool has(const std::string& key) const {
        return values_.count(key) > 0;
    }

    const std::string& name() const { return name_; }

    // Iteration support
    auto begin() const { return values_.begin(); }
    auto end()   const { return values_.end(); }
    size_t size() const { return values_.size(); }
};

// ─── Config change event (fired when values are modified) ───────────────
struct ConfigChangeEvent {
    std::string section;
    std::string key;
    std::string old_value;
    std::string new_value;
};

// ─── Main config parser ─────────────────────────────────────────────────
class ConfigParser {
public:
    using ChangeCallback = std::function<void(const ConfigChangeEvent&)>;

private:
    std::unordered_map<std::string, ConfigSection> sections_;
    std::vector<ChangeCallback> change_listeners_;

    // ── Utility: trim whitespace ────────────────────────────────────
    static std::string trim(const std::string& str) {
        size_t start = str.find_first_not_of(" \t\r\n");
        size_t end   = str.find_last_not_of(" \t\r\n");
        return (start == std::string::npos) ? "" : str.substr(start, end - start + 1);
    }

    // ── Fire change event to all listeners ──────────────────────────
    void notify_change(const ConfigChangeEvent& event) {
        for (auto& cb : change_listeners_) {
            cb(event);
        }
    }

public:
    // ── Parse from file ─────────────────────────────────────────────
    bool load(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            std::cerr << "[ConfigParser] Failed to open: " << filename << "\n";
            return false;
        }

        std::string line;
        std::string current_section = "global";  // default section
        int line_number = 0;

        while (std::getline(file, line)) {
            line_number++;
            line = trim(line);

            // Skip empty lines and comments
            if (line.empty() || line[0] == '#' || line[0] == ';')
                continue;

            // Section header: [section_name]
            if (line.front() == '[' && line.back() == ']') {
                current_section = trim(line.substr(1, line.size() - 2));
                if (current_section.empty()) {
                    std::cerr << "[ConfigParser] Empty section name at line "
                              << line_number << "\n";
                    return false;
                }
                // Create section if it doesn't exist
                if (sections_.find(current_section) == sections_.end())
                    sections_[current_section] = ConfigSection(current_section);
                continue;
            }

            // Key = Value pair
            size_t eq_pos = line.find('=');
            if (eq_pos == std::string::npos) {
                std::cerr << "[ConfigParser] Malformed line " << line_number
                          << ": " << line << "\n";
                return false;
            }

            std::string key   = trim(line.substr(0, eq_pos));
            std::string value = trim(line.substr(eq_pos + 1));

            // Strip inline comments (only outside quotes)
            if (!value.empty() && value[0] != '"') {
                size_t comment = value.find('#');
                if (comment != std::string::npos)
                    value = trim(value.substr(0, comment));
                comment = value.find(';');
                if (comment != std::string::npos)
                    value = trim(value.substr(0, comment));
            }

            // Strip surrounding quotes
            if (value.size() >= 2 && value.front() == '"' && value.back() == '"')
                value = value.substr(1, value.size() - 2);

            // Ensure section exists, then insert
            if (sections_.find(current_section) == sections_.end())
                sections_[current_section] = ConfigSection(current_section);

            sections_[current_section].set(key, value);
        }

        std::cout << "[ConfigParser] Loaded " << sections_.size()
                  << " sections from " << filename << "\n";
        return true;
    }

    // ── Parse from string (useful for testing) ──────────────────────
    bool load_from_string(const std::string& content) {
        std::istringstream stream(content);
        std::string line;
        std::string current_section = "global";

        while (std::getline(stream, line)) {
            line = trim(line);
            if (line.empty() || line[0] == '#' || line[0] == ';')
                continue;

            if (line.front() == '[' && line.back() == ']') {
                current_section = trim(line.substr(1, line.size() - 2));
                if (sections_.find(current_section) == sections_.end())
                    sections_[current_section] = ConfigSection(current_section);
                continue;
            }

            size_t eq = line.find('=');
            if (eq == std::string::npos) continue;

            std::string key   = trim(line.substr(0, eq));
            std::string value = trim(line.substr(eq + 1));

            if (sections_.find(current_section) == sections_.end())
                sections_[current_section] = ConfigSection(current_section);

            sections_[current_section].set(key, value);
        }
        return true;
    }

    // ── Access a section ────────────────────────────────────────────
    const ConfigSection& section(const std::string& name) const {
        auto it = sections_.find(name);
        if (it == sections_.end())
            throw std::runtime_error("Section [" + name + "] not found");
        return it->second;
    }

    bool has_section(const std::string& name) const {
        return sections_.count(name) > 0;
    }

    // ── Shorthand: config["section"]["key"] ─────────────────────────
    const ConfigSection& operator[](const std::string& name) const {
        return section(name);
    }

    // ── Modify a value at runtime (fires change event) ──────────────
    void set(const std::string& sect, const std::string& key,
             const std::string& value) {
        std::string old_value;

        if (sections_.find(sect) == sections_.end())
            sections_[sect] = ConfigSection(sect);

        if (sections_[sect].has(key))
            old_value = sections_[sect].get(key).as_string();

        sections_[sect].set(key, value);

        notify_change({sect, key, old_value, value});
    }

    // ── Register a config-change listener ───────────────────────────
    void on_change(ChangeCallback callback) {
        change_listeners_.push_back(std::move(callback));
    }

    // ── Dump all values (debug) ─────────────────────────────────────
    void dump(std::ostream& os = std::cout) const {
        for (auto& [sect_name, sect] : sections_) {
            os << "[" << sect_name << "]\n";
            for (auto& [key, val] : sect) {
                os << "  " << key << " = " << val.as_string() << "\n";
            }
        }
    }

    // ── Iteration ───────────────────────────────────────────────────
    auto begin() const { return sections_.begin(); }
    auto end()   const { return sections_.end(); }
};
```

## Event System Header

```cpp
// event_system.h
#pragma once

#include <string>
