// ─── Event priority levels ──────────────────────────────────────────────
enum class EventPriority { LOW = 0, NORMAL = 1, HIGH = 2, CRITICAL = 3 };

// ─── Base event ─────────────────────────────────────────────────────────
struct Event {
    std::string  type;
    EventPriority priority = EventPriority::NORMAL;
    std::chrono::steady_clock::time_point timestamp =
        std::chrono::steady_clock::now();
    bool consumed = false;   // stop propagation when true

    virtual ~Event() = default;

    double age_ms() const {
        auto now = std::chrono::steady_clock::now();
        return std::chrono::duration<double, std::milli>(now - timestamp).count();
    }
};

// ─── Concrete event types ───────────────────────────────────────────────
struct NetworkEvent : Event {
    std::string host;
    int         port{};
    std::string message;

    NetworkEvent(std::string h, int p, std::string msg)
        : host(std::move(h)), port(p), message(std::move(msg)) {
        type = "network";
    }
};

struct TimerEvent : Event {
    int    timer_id{};
    double interval_ms{};

    TimerEvent(int id, double interval)
        : timer_id(id), interval_ms(interval) {
        type = "timer";
    }
};

struct InputEvent : Event {
    std::string source;   // "keyboard", "mouse", etc.
    std::string action;
    int         key_code{};

    InputEvent(std::string src, std::string act, int key = 0)
        : source(std::move(src)), action(std::move(act)), key_code(key) {
        type = "input";
    }
};

struct SystemEvent : Event {
    std::string action;   // "startup", "shutdown", "config_reload"
    std::string detail;

    SystemEvent(std::string act, std::string det = "")
        : action(std::move(act)), detail(std::move(det)) {
        type = "system";
    }
};

// ─── Handler wrapper with priority ─────────────────────────────────────
struct HandlerEntry {
    std::function<void(Event&)> handler;
    EventPriority min_priority;
    std::string   name;        // for logging / debug
};

// ─── Event queue entry (for deferred processing) ────────────────────────
struct QueuedEvent {
    std::shared_ptr<Event> event;

    // Higher priority → processed first
    bool operator<(const QueuedEvent& other) const {
        return static_cast<int>(event->priority)
             < static_cast<int>(other.event->priority);
    }
};

// ─── The main event processor ───────────────────────────────────────────
