# C# Background Worker with Rate Limiting

## Rate Limiter (Token Bucket Algorithm)

```csharp
using System;
using System.Threading;
using System.Threading.Tasks;

/// <summary>
/// Token bucket rate limiter - allows bursts up to a max,
/// then refills tokens at a steady rate.
/// </summary>
public sealed class TokenBucketRateLimiter : IDisposable
{
    private readonly SemaphoreSlim _semaphore = new(1, 1);
    private readonly int _maxTokens;
    private readonly double _refillRatePerSecond;
    private double _currentTokens;
    private DateTime _lastRefillTime;

    public TokenBucketRateLimiter(int maxTokens, double refillRatePerSecond)
    {
        _maxTokens = maxTokens;
        _refillRatePerSecond = refillRatePerSecond;
        _currentTokens = maxTokens;           // start full
        _lastRefillTime = DateTime.UtcNow;
    }

    /// <summary>
    /// Waits until a token is available, then consumes it.
    /// </summary>
    public async Task WaitForTokenAsync(CancellationToken ct = default)
    {
        while (true)
        {
            ct.ThrowIfCancellationRequested();

            await _semaphore.WaitAsync(ct);
            try
            {
                Refill();

                if (_currentTokens >= 1.0)
                {
                    _currentTokens -= 1.0;
                    return; // token acquired
                }

                // Calculate how long until the next token arrives
                double tokensNeeded = 1.0 - _currentTokens;
                double waitSeconds = tokensNeeded / _refillRatePerSecond;
                TimeSpan delay = TimeSpan.FromSeconds(Math.Ceiling(waitSeconds * 1000) / 1000);

                // Release lock before sleeping
                _semaphore.Release();
                await Task.Delay(delay, ct);
                continue; // retry after waiting
            }
            catch
            {
                // Ensure semaphore is released on exception
                if (_semaphore.CurrentCount == 0)
                    _semaphore.Release();
                throw;
            }
        }
    }

    /// <summary>
    /// Tries to acquire a token without waiting.
    /// </summary>
    public bool TryAcquire()
    {
        _semaphore.Wait();
        try
        {
            Refill();
            if (_currentTokens >= 1.0)
            {
                _currentTokens -= 1.0;
                return true;
            }
            return false;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private void Refill()
    {
        var now = DateTime.UtcNow;
        double elapsed = (now - _lastRefillTime).TotalSeconds;
        _currentTokens = Math.Min(_maxTokens, _currentTokens + elapsed * _refillRatePerSecond);
        _lastRefillTime = now;
    }

    public void Dispose() => _semaphore.Dispose();
}
