## Background Worker Service

```csharp
using System.Threading.Channels;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

/// <summary>
/// A hosted background worker that pulls items from a channel
/// and processes them while respecting a rate limit.
/// </summary>
public class RateLimitedWorker : BackgroundService
{
    private readonly Channel<WorkItem> _queue;
    private readonly TokenBucketRateLimiter _rateLimiter;
    private readonly ILogger<RateLimitedWorker> _logger;
    private readonly HttpClient _httpClient;

    private const int MaxRetries = 3;

    public RateLimitedWorker(
        Channel<WorkItem> queue,
        TokenBucketRateLimiter rateLimiter,
        HttpClient httpClient,
        ILogger<RateLimitedWorker> logger)
    {
        _queue = queue;
        _rateLimiter = rateLimiter;
        _httpClient = httpClient;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("RateLimitedWorker started.");

        await foreach (var item in _queue.Reader.ReadAllAsync(stoppingToken))
        {
            try
            {
                // Block here until the rate limiter allows us to proceed
                await _rateLimiter.WaitForTokenAsync(stoppingToken);

                await ProcessItemAsync(item, stoppingToken);
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                _logger.LogWarning("Worker stopping — cancellation requested.");
                break;
            }
            catch (Exception ex)
            {
                await HandleFailureAsync(item, ex, stoppingToken);
            }
        }

        _logger.LogInformation("RateLimitedWorker stopped.");
    }

    private async Task ProcessItemAsync(WorkItem item, CancellationToken ct)
    {
        _logger.LogInformation(
            "Processing item {Id} (attempt {Attempt}) — queued {Ago:F1}s ago",
            item.Id,
            item.RetryCount + 1,
            (DateTime.UtcNow - item.EnqueuedAt).TotalSeconds);

        // --- Example: call an external API ---
        var response = await _httpClient.PostAsync(
            "https://api.example.com/process",
            new StringContent(item.Payload),
            ct);

        // Handle server-side rate limiting (HTTP 429)
        if (response.StatusCode == System.Net.HttpStatusCode.TooManyRequests)
        {
            TimeSpan retryAfter = response.Headers.RetryAfter?.Delta
                                  ?? TimeSpan.FromSeconds(5);

            _logger.LogWarning(
                "Received 429 for item {Id}. Backing off {Seconds}s",
                item.Id, retryAfter.TotalSeconds);

            await Task.Delay(retryAfter, ct);
            throw new HttpRequestException("Rate limited by server (429).");
        }

        response.EnsureSuccessStatusCode();

        _logger.LogInformation("Item {Id} processed successfully.", item.Id);
    }

    private async Task HandleFailureAsync(
        WorkItem item, Exception ex, CancellationToken ct)
    {
        item.RetryCount++;

        if (item.RetryCount < MaxRetries)
        {
            // Exponential back-off: 2s, 4s, 8s …
            var delay = TimeSpan.FromSeconds(Math.Pow(2, item.RetryCount));

            _logger.LogWarning(ex,
                "Item {Id} failed (attempt {Attempt}). Retrying in {Delay}s",
                item.Id, item.RetryCount, delay.TotalSeconds);

            await Task.Delay(delay, ct);
            await _queue.Writer.WriteAsync(item, ct);   // re-enqueue
        }
        else
        {
            _logger.LogError(ex,
                "Item {Id} failed permanently after {MaxRetries} attempts.",
                item.Id, MaxRetries);
            // TODO: move to dead-letter queue / alert
        }
    }
}
