## Registration & Dependency Injection

```csharp
using System.Threading.Channels;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

// Bounded channel acts as the work queue (back-pressure at 500 items)
builder.Services.AddSingleton(
    Channel.CreateBounded<WorkItem>(new BoundedChannelOptions(500)
    {
        FullMode = BoundedChannelFullMode.Wait
    }));

// Rate limiter: 10 requests max burst, refill at 5 tokens/sec
builder.Services.AddSingleton(
    new TokenBucketRateLimiter(maxTokens: 10, refillRatePerSecond: 5));

builder.Services.AddHttpClient();

// Register the background worker
builder.Services.AddHostedService<RateLimitedWorker>();

// Register a producer so controllers/services can enqueue work
builder.Services.AddSingleton<WorkItemProducer>();

var app = builder.Build();
app.Run();
```

## Producer (Enqueuing Work)

```csharp
using System.Threading.Channels;

/// <summary>
/// Inject this into controllers or other services to submit work.
/// </summary>
public class WorkItemProducer
{
    private readonly Channel<WorkItem> _channel;
    private int _nextId;

    public WorkItemProducer(Channel<WorkItem> channel) => _channel = channel;

    public async ValueTask EnqueueAsync(string payload, CancellationToken ct = default)
    {
        var item = new WorkItem
        {
            Id = Interlocked.Increment(ref _nextId),
            Payload = payload
        };

        await _channel.Writer.WriteAsync(item, ct);
    }
}
