    // ──────────────────────────────────────────────────────────

    @Override
    public Void visitCatch(CatchTree node, Void unused) {
        if (isSecurityException(node)) {
            // deep-scan the catch body
            AuditCallFinder finder = new AuditCallFinder();
            finder.scan(node.getBlock(), null);

            // FIX 8 ► condition was inverted — report when audit is ABSENT
            if (!finder.hasAuditLogCall()) {
                reportViolation(node,
                    "MISSING_CATCH_AUDIT",
                    "Security-exception catch block must include audit logging");
            }
        }
        return super.visitCatch(node, unused);
    }

    // ──────────────────────────────────────────────────────────
    //  Deep subtree scanner for audit calls & fields
    // ──────────────────────────────────────────────────────────

    /**
     * Inner scanner that walks an arbitrary subtree looking for
     * audit-log method invocations and the field names passed to them.
     *
     * FIX 3, 14 ► replaces shallow single-level loop
     */
    private static class AuditCallFinder extends TreeScanner<Void, Void> {

        private boolean found = false;
        private final Set<String> auditFields = new HashSet<>();

        @Override
        public Void visitMethodInvocation(MethodInvocationTree node, Void v) {
            String call = node.getMethodSelect().toString();

            // FIX 11 ► use endsWith so "auditService.auditLog" matches
            for (String method : AUDIT_LOG_METHODS) {
                if (call.endsWith(method)) {
                    found = true;
                    collectFieldsFromArgs(node);
                    break;
                }
            }
            return super.visitMethodInvocation(node, v);
        }

        /** Collect field names that appear in audit-call arguments. */
        private void collectFieldsFromArgs(MethodInvocationTree call) {
            for (ExpressionTree arg : call.getArguments()) {
                String argText = arg.toString();
                for (String field : REQUIRED_AUDIT_FIELDS) {
                    if (argText.contains(field)) {
                        auditFields.add(field);
                    }
                }
            }
        }

        boolean hasAuditLogCall()      { return found;       }
        Set<String> getAuditFields()   { return auditFields; }
    }

    // ──────────────────────────────────────────────────────────
    //  Sensitivity detection
    // ──────────────────────────────────────────────────────────

    private boolean isSensitiveMethod(MethodTree node, String name) {
        // 1. Check annotations
        for (AnnotationTree ann : node.getModifiers().getAnnotations()) {
            // FIX 9 ► extract simple name from possible FQ name
            String annName = extractSimpleName(
                                 ann.getAnnotationType().toString());
            if (SENSITIVE_ANNOTATIONS.contains(annName)) {
                return true;
            }
        }

        // 2. Check method-name prefix
        // FIX 10 ► case-insensitive comparison
        String lowerName = name.toLowerCase(Locale.ROOT);
        for (String prefix : SENSITIVE_METHOD_PREFIXES) {
            if (lowerName.startsWith(prefix)) {
                return true;
            }
        }
        return false;
    }

    /** "com.example.Secured" → "Secured" */
    private static String extractSimpleName(String possiblyQualified) {
        int dot = possiblyQualified.lastIndexOf('.');
        return dot < 0 ? possiblyQualified
                       : possiblyQualified.substring(dot + 1);
    }

    // ──────────────────────────────────────────────────────────
    //  Audit-field validation
    // ──────────────────────────────────────────────────────────

    private void validateAuditFields(MethodTree node,
                                     Set<String> foundFields) {
        Set<String> missing = new TreeSet<>(REQUIRED_AUDIT_FIELDS);
        missing.removeAll(foundFields);

        // FIX 13 ► single summary violation listing all missing fields
        if (!missing.isEmpty()) {
            String list = String.join(", ", missing);
            reportViolation(node,
                "MISSING_AUDIT_FIELDS",
                "Audit-log call is missing required fields: " + list);
        }
    }

    // ──────────────────────────────────────────────────────────
    //  Security-exception check
    // ──────────────────────────────────────────────────────────

    /** FIX 15 ► checks against a full set of security-exception types. */
    private boolean isSecurityException(CatchTree node) {
        String type = node.getParameter().getType().toString();
        for (String secType : SECURITY_EXCEPTION_TYPES) {
            if (type.contains(secType)) {
                return true;
            }
        }
        return false;
    }

