# `reportgen` — CLI Report Generation Tool

A zero-dependency Python CLI tool that reads CSV/JSON, applies filters/aggregations, and outputs reports in multiple formats.

## Project Structure

```
reportgen/
├── reportgen.py          # Main tool (single file, no deps)
├── sample_data.py        # Generates test data
└── reports/
    └── monthly.json      # Saved report config
```

## The Tool

```python
#!/usr/bin/env python3
"""
reportgen - Generate reports from CSV/JSON data via the command line.

Usage:
    python reportgen.py sales.csv
    python reportgen.py data.json --filter "status=active" --sort revenue --desc
    python reportgen.py sales.csv --group-by region --agg "revenue:sum,revenue:avg"
    python reportgen.py sales.csv --format html -o report.html --title "Q4 Sales"
    cat data.csv | python reportgen.py --stdin --format markdown
"""

import argparse
import csv
import json
import sys
from collections import defaultdict
from datetime import datetime
from io import StringIO
from pathlib import Path
from typing import Any


# ── ANSI Colors (auto-disabled when piping) ──────────────────────────

class Style:
    BOLD = "\033[1m"
    DIM = "\033[2m"
    CYAN = "\033[96m"
    GREEN = "\033[92m"
    RED = "\033[91m"
    RESET = "\033[0m"

    @classmethod
    def disable(cls):
        for attr in ("BOLD", "DIM", "CYAN", "GREEN", "RED", "RESET"):
            setattr(cls, attr, "")

    @classmethod
    def auto(cls):
        if not sys.stdout.isatty():
            cls.disable()


# ── Data Loading ─────────────────────────────────────────────────────

class DataLoader:
    """Loads rows from CSV, JSON arrays, or JSON-lines files."""

    @classmethod
    def load(cls, source: str | None, from_stdin: bool = False) -> list[dict]:
        if from_stdin:
            return cls._detect(sys.stdin.read())

        path = Path(source)
        if not path.exists():
            raise FileNotFoundError(f"File not found: {source}")

        text = path.read_text(encoding="utf-8")
        if path.suffix.lower() == ".csv":
            return cls._load_csv(text)
        if path.suffix.lower() in (".json", ".jsonl"):
            return cls._load_json(text)
        return cls._detect(text)

    @staticmethod
    def _load_csv(text: str) -> list[dict]:
        return list(csv.DictReader(StringIO(text)))

    @staticmethod
    def _load_json(text: str) -> list[dict]:
        text = text.strip()
        # standard JSON array or object
        try:
            data = json.loads(text)
            if isinstance(data, list):
                return data
            if isinstance(data, dict):
                for key in ("data", "results", "records", "items", "rows"):
                    if key in data and isinstance(data[key], list):
                        return data[key]
                return [data]
        except json.JSONDecodeError:
            pass
        # JSON-lines fallback
        return [json.loads(line) for line in text.splitlines() if line.strip()]

    @classmethod
    def _detect(cls, text: str) -> list[dict]:
        stripped = text.strip()
        if stripped and stripped[0] in ("[", "{"):
            return cls._load_json(text)
        return cls._load_csv(text)


# ── Type Coercion ────────────────────────────────────────────────────

def coerce(value: str) -> Any:
    """Convert string → int/float/bool/None where sensible."""
    if value is None or value == "":
        return None
    low = value.lower()
    if low in ("true", "yes"):
        return True
    if low in ("false", "no"):
        return False
    for cast in (int, float):
        try:
            return cast(value)
        except (ValueError, TypeError):
            continue
    return value


def coerce_row(row: dict) -> dict:
    return {k: coerce(v) if isinstance(v, str) else v for k, v in row.items()}


# ── Filtering ────────────────────────────────────────────────────────

class Filter:
    """
    Supported operators (checked in this order):
        >=  <=  !=  >  <  =  ~  (~ means 'contains')
    """

    OPS = (">=", "<=", "!=", ">", "<", "=", "~")

    @classmethod
    def parse(cls, expr: str) -> tuple[str, str, str]:
        for op in cls.OPS:
            if op in expr:
                col, val = expr.split(op, 1)
                return col.strip(), op, val.strip()
        raise ValueError(f"Cannot parse filter: {expr!r}")

    @classmethod
    def match(cls, row_val: Any, op: str, target: str) -> bool:
        if row_val is None:
            return op == "!=" and target.lower() != "none"

        # try numeric comparison first
        try:
            rv = float(row_val) if not isinstance(row_val, (int, float)) else row_val
            tv = float(target)
            ops = {"=": rv == tv, "!=": rv != tv, ">": rv > tv,
                   "<": rv < tv, ">=": rv >= tv, "<=": rv <= tv,
                   "~": target.lower() in str(row_val).lower()}
            return ops[op]
        except (ValueError, TypeError):
            pass

        # fall back to case-insensitive string comparison
        rs, ts = str(row_val).lower(), target.lower()
        return {"=": rs == ts, "!=": rs != ts, ">": rs > ts,
                "<": rs < ts, ">=": rs >= ts, "<=": rs <= ts,
                "~": ts in rs}[op]

    @classmethod
    def apply(cls, rows: list[dict], expressions: list[str]) -> list[dict]:
        parsed = [cls.parse(e) for e in expressions]
        return [
            row for row in rows
            if all(cls.match(row.get(c), op, v) for c, op, v in parsed)
        ]


# ── Aggregation ──────────────────────────────────────────────────────

class Aggregator:
    FUNCS: dict[str, Any] = {
        "count":  lambda vs: len(vs),
        "sum":    lambda vs: sum(v for v in vs if isinstance(v, (int, float))),
        "avg":    lambda vs: (
            sum(v for v in vs if isinstance(v, (int, float)))
            / max(1, sum(1 for v in vs if isinstance(v, (int, float))))
        ),
        "min":    lambda vs: min((v for v in vs if v is not None), default=None),
        "max":    lambda vs: max((v for v in vs if v is not None), default=None),
        "unique": lambda vs: len({v for v in vs if v is not None}),
    }

    @classmethod
    def parse_specs(cls, spec_str: str) -> list[tuple[str, str]]:
        """Parse 'col:func,col:func' → [(col, func), ...]"""
        specs = []
        for part in spec_str.split(","):
            part = part.strip()
            if ":" in part:
                col, func = part.rsplit(":", 1)
                specs.append((col.strip(), func.strip().lower()))
            else:
                specs.append((part.strip(), "count"))
        return specs

    @classmethod
    def group_and_aggregate(
        cls,
        rows: list[dict],
        group_cols: list[str],
        agg_specs: list[tuple[str, str]],
    ) -> list[dict]:
        groups: dict[tuple, list[dict]] = defaultdict(list)
        for row in rows:
            key = tuple(row.get(c) for c in group_cols)
            groups[key].append(row)

        result = []
        for key, group in groups.items():
            out = dict(zip(group_cols, key))
            for col, func in agg_specs:
                if func not in cls.FUNCS:
                    raise ValueError(
                        f"Unknown function '{func}'. "
                        f"Choose from: {', '.join(cls.FUNCS)}"
                    )
                values = [r.get(col) for r in group]
                out[f"{func}({col})"] = cls.FUNCS[func](values)
            result.append(out)
        return result

    @classmethod
    def summarize(cls, rows: list[dict], columns: list[str]) -> dict:
        """Per-column statistics for --summary mode."""
        stats = {}
        for col in columns:
            vals = [r.get(col) for r in rows if r.get(col) is not None]
            nums = [v for v in vals if isinstance(v, (int, float))]
            info: dict[str, Any] = {"total": len(vals), "nulls": len(rows) - len(vals)}
            if nums:
                info |= {
                    "min": min(nums), "max": max(nums),
                    "sum": sum(nums), "avg": sum(nums) / len(nums),
                }
            else:
                uniq = {str(v) for v in vals}
                info["unique"] = len(uniq)
                if len(uniq) <= 8:
                    info["top_values"] = sorted(uniq)
            stats[col] = info
        return stats


# ── Formatters ───────────────────────────────────────────────────────

def _all_columns(rows: list[dict], selected: list[str] | None = None) -> list[str]:
    if selected:
        return selected
    seen: dict[str, None] = {}
    for row in rows:
        for k in row:
            seen.setdefault(k, None)
    return list(seen)


def _fmt_val(value: Any, width: int = 40) -> str:
    if value is None:
        return ""
    if isinstance(value, float):
        s = f"{value:,.2f}"
    elif isinstance(value, int):
        s = f"{value:,}"
    else:
        s = str(value)
    return s[:width - 1] + "…" if len(s) > width else s


def format_table(
    rows: list[dict],
    columns: list[str] | None = None,
    title: str | None = None,
    max_w: int = 30,
) -> str:
    cols = _all_columns(rows, columns)
    if not cols:
        return "No data.\n"

    widths = {
        c: min(max_w, max(len(c), *(len(_fmt_val(r.get(c), max_w)) for r in rows)))
        for c in cols
    }

    lines: list[str] = []

    if title:
        lines += [
            "",
            f"  {Style.BOLD}{Style.CYAN}{title}{Style.RESET}",
            f"  {Style.DIM}{'─' * (sum(widths.values()) + 3 * len(cols))}{Style.RESET}",
        ]

    header = "  ".join(f"{Style.BOLD}{c:<{widths[c]}}{Style.RESET}" for c in cols)
    sep = f"{Style.DIM}  {'  '.join('─' * widths[c] for c in cols)}{Style.RESET}"
    lines += [f"  {header}", sep]

    for row in rows:
        cells = []
        for c in cols:
            v = _fmt_val(row.get(c), max_w)
            if isinstance(row.get(c), (int, float)):
                cells.append(f"{v:>{widths[c]}}")
            else:
                cells.append(f"{v:<{widths[c]}}")
        lines.append(f"  {'  '.join(cells)}")

    lines += [sep, f"  {Style.DIM}{len(rows)} row(s){Style.RESET}", ""]
    return "\n".join(lines)


def format_csv(rows: list[dict], columns: list[str] | None = None) -> str:
    cols = _all_columns(rows, columns)
    buf = StringIO()
    w = csv.DictWriter(buf, fieldnames=cols, extrasaction="ignore")
    w.writeheader()
    w.writerows(rows)
    return buf.getvalue()


def format_json(rows: list[dict], columns: list[str] | None = None) -> str:
    if columns:
        rows = [{k: r.get(k) for k in columns} for r in rows]
    return json.dumps(rows, indent=2, default=str)


def format_markdown(
    rows: list[dict],
    columns: list[str] | None = None,
    title: str | None = None,
) -> str:
    cols = _all_columns(rows, columns)
    if not cols:
        return "*No data.*\n"

    widths = {
        c: max(len(c), *(len(_fmt_val(r.get(c))) for r in rows))
        for c in cols
    }

    lines: list[str] = []
    if title:
        lines.append(f"## {title}\n")

    lines.append("| " + " | ".join(f"{c:<{widths[c]}}" for c in cols) + " |")

    seps = []
    for c in cols:
        is_num = any(isinstance(r.get(c), (int, float)) for r in rows[:5])
        seps.append(("-" * (widths[c] - 1) + ":") if is_num else ("-" * widths[c]))
    lines.append("| " + " | ".join(seps) + " |")

    for row in rows:
        cells = [f"{_fmt_val(row.get(c)):<{widths[c]}}" for c in cols]
        lines.append("| " + " | ".join(cells) + " |")

    lines.append(f"\n*{len(rows)} row(s)*")
    return "\n".join(lines)


def format_html(
    rows: list[dict],
    columns: list[str] | None = None,
    title: str | None = None,
) -> str:
    cols = _all_columns(rows, columns)
    t = title or "Report"
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    css = (
        "body{font-family:system-ui,sans-serif;margin:40px;background:#f5f5f5}"
        "h1{color:#2c3e50;margin:0 0 4px}.meta{color:#888;font-size:.85em;margin-bottom:20px}"
        "table{border-collapse:collapse;width:100%;background:#fff;"
        "box-shadow:0 1px 4px rgba(0,0,0,.08);border-radius:8px;overflow:hidden}"
        "th{background:#2c3e50;color:#fff;padding:12px 16px;text-align:left;"
        "font-size:.8em;text-transform:uppercase;letter-spacing:.5px}"
        "td{padding:10px 16px;border-bottom:1px solid #eee}"
        "tr:hover td{background:#f8f9fa}.n{text-align:right;font-variant-numeric:tabular-nums}"
        ".foot{margin-top:12px;color:#888;font-size:.85em}"
    )

    h = [
        "<!DOCTYPE html>",
        f"<html><head><meta charset='utf-8'><title>{t}</title>",
        f"<style>{css}</style></head><body>",
        f"<h1>{t}</h1><p class='meta'>Generated {ts}</p>",
        "<table><thead><tr>",
        *[f"<th>{c}</th>" for c in cols],
        "</tr></thead><tbody>",
    ]

    for row in rows:
        h.append("<tr>")
        for c in cols:
            v = row.get(c)
            cls_attr = " class='n'" if isinstance(v, (int, float)) else ""
            h.append(f"<td{cls_attr}>{_fmt_val(v)}</td>")
        h.append("</tr>")

    h += [
        "</tbody></table>",
        f"<p class='foot'>{len(rows)} row(s)</p>",
        "</body></html>",
    ]
    return "\n".join(h)


def format_summary(stats: dict, title: str = "Column Summary") -> str:
    lines = [
        "",
        f"  {Style.BOLD}{Style.CYAN}{title}{Style.RESET}",
        f"  {Style.DIM}{'─' * 60}{Style.RESET}",
    ]
    for col, info in stats.items():
        lines.append(f"\n  {Style.BOLD}{col}{Style.RESET}")
        for k, v in info.items():
            if isinstance(v, list):
                v_str = ", ".join(v)
            elif isinstance(v, float):
                v_str = f"{v:,.2f}"
            else:
                v_str = str(v)
            lines.append(f"    {Style.DIM}{k:>12}:{Style.RESET} {v_str}")
    lines.append("")
    return "\n".join(lines)


FORMATTERS = {
    "table":    format_table,
    "csv":      format_csv,
    "json":     format_json,
    "markdown": format_markdown,
    "md":       format_markdown,
    "html":     format_html,
}


# ── Report Engine ────────────────────────────────────────────────────

class ReportEngine:
    def __init__(self, args: argparse.Namespace):
        self.a = args

    def run(self) -> str:
        # 1. load
        rows = DataLoader.load(self.a.source, from_stdin=self.a.stdin)
        if not rows:
            return "No data found.\n"

        # 2. coerce types
        if not self.a.no_coerce:
            rows = [coerce_row(r) for r in rows]

        # 3. filter
        if self.a.filter:
            rows = Filter.apply(rows, self.a.filter)
            if not rows:
                return "All rows filtered out.\n"

        # 4. group + aggregate
        if self.a.group_by:
            gcols = [c.strip() for c in self.a.group_by.split(",")]
            specs = (
                Aggregator.parse_specs(self.a.agg)
                if self.a.agg
                else [(list(rows[0].keys())[0], "count")]
            )
            rows = Aggregator.group_and_aggregate(rows, gcols, specs)

        # 5. select columns
        columns = (
            [c.strip() for c in self.a.columns.split(",")]
            if self.a.columns
            else None
        )

        # 6. sort
        if self.a.sort:
            rows.sort(
                key=lambda r: (r.get(self.a.sort) is None, r.get(self.a.sort, "")),
                reverse=self.a.desc,
            )

        # 7. limit
        if self.a.limit:
            rows = rows[: self.a.limit]

        # 8. summary mode
        if self.a.summary:
            cols = columns or _all_columns(rows)
            return format_summary(
                Aggregator.summarize(rows, cols),
                title=self.a.title or "Data Summary",
            )

        # 9. format
        fmt_fn = FORMATTERS.get(self.a.format)
        if not fmt_fn:
            raise ValueError(
                f"Unknown format '{self.a.format}'. "
                f"Choose from: {', '.join(FORMATTERS)}"
            )

        if fmt_fn in (format_csv, format_json):
            return fmt_fn(rows, columns)
        return fmt_fn(rows, columns, self.a.title)


