using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

/// <summary>
/// Thread-safe task scheduler with support for one-time and recurring tasks.
/// </summary>
public class TaskSchedulerService : IDisposable                     // FIX 1: IDisposable
{
    // FIX 2: Thread-safe collection
    private readonly ConcurrentDictionary<Guid, ScheduledTask> _tasks = new();
    private Timer _timer;
    private readonly object _executionLock = new();                  // FIX 9: Re-entrancy guard
    private CancellationTokenSource _cts;                           // FIX 3: Cancellation support
    private bool _isRunning;
    private bool _disposed;

    // ---------- Event for logging / monitoring ----------
    public event EventHandler<TaskExecutedEventArgs> TaskExecuted;
    public event EventHandler<TaskFailedEventArgs> TaskFailed;

    /// <summary>Start the scheduler.</summary>
    public void Start()
    {
        ObjectDisposedException.ThrowIf(_disposed, this);

        _cts = new CancellationTokenSource();
        _isRunning = true;

        // FIX 4 & 5: 1-second initial delay; 1-second tick (configurable)
        _timer = new Timer(
            callback: ExecuteTasks,
            state: null,
            dueTime: TimeSpan.FromSeconds(1),
            period: TimeSpan.FromSeconds(1)
