        Console.WriteLine("[Scheduler] Started.");
    }

    /// <summary>Schedule a one-time or recurring task.</summary>
    public Guid ScheduleTask(
        string name,
        Action action,
        DateTime scheduledTimeUtc,
        TimeSpan? recurrenceInterval = null)                        // FIX 18: Recurring support
    {
        // FIX 6: Input validation
        ArgumentNullException.ThrowIfNull(action);
        ArgumentException.ThrowIfNullOrWhiteSpace(name);

        if (scheduledTimeUtc.Kind != DateTimeKind.Utc)
            throw new ArgumentException("Use UTC time.", nameof(scheduledTimeUtc));

        if (scheduledTimeUtc < DateTime.UtcNow)
            throw new ArgumentException("Scheduled time is in the past.", nameof(scheduledTimeUtc));

        var task = new ScheduledTask
        {
            Id = Guid.NewGuid(),                                    // FIX 17: Unique ID
            Name = name,
            Action = action,
            ScheduledTimeUtc = scheduledTimeUtc,                    // FIX 11: UTC
            RecurrenceInterval = recurrenceInterval,
            IsCompleted = false,
            CreatedAtUtc = DateTime.UtcNow
        };

        // FIX 7: Thread-safe add
        if (!_tasks.TryAdd(task.Id, task))
            throw new InvalidOperationException("Failed to schedule task.");

        Console.WriteLine($"[Scheduler] Task '{name}' scheduled for {scheduledTimeUtc:u}");
        return task.Id;
    }

    /// <summary>Cancel a scheduled task by ID.</summary>
    public bool CancelTask(Guid taskId)
    {
        return _tasks.TryRemove(taskId, out _);
    }

    /// <summary>Timer callback — executes due tasks.</summary>
    private void ExecuteTasks(object state)
    {
        // FIX 9: Prevent overlapping executions
        if (!Monitor.TryEnter(_executionLock))
            return;

        try
        {
            if (!_isRunning || _cts.IsCancellationRequested)
                return;

            var now = DateTime.UtcNow;                              // FIX 11: UTC

            // FIX 10 & 14: Snapshot of keys — safe iteration
            var dueTasks = _tasks.Values
                .Where(t => !t.IsCompleted && t.ScheduledTimeUtc <= now)  // FIX 12: <= not ==
                .ToList();

            foreach (var task in dueTasks)
            {
                if (_cts.IsCancellationRequested) break;

                // FIX 13: Exception handling per task
                try
                {
                    task.Action.Invoke();
                    task.LastExecutedUtc = DateTime.UtcNow;
                    task.ExecutionCount++;

                    TaskExecuted?.Invoke(this,
                        new TaskExecutedEventArgs(task.Id, task.Name));

                    // Handle recurring vs one-time
                    if (task.RecurrenceInterval.HasValue)            // FIX 18
                    {
                        task.ScheduledTimeUtc =
                            DateTime.UtcNow + task.RecurrenceInterval.Value;
                    }
                    else
                    {
                        task.IsCompleted = true;
                        _tasks.TryRemove(task.Id, out _);          // FIX 14: Safe removal
                    }
                }
                catch (Exception ex)
                {
                    task.LastError = ex;
                    task.ConsecutiveFailures++;

                    TaskFailed?.Invoke(this,
                        new TaskFailedEventArgs(task.Id, task.Name, ex));

                    Console.WriteLine(
                        $"[Scheduler] Task '{task.Name}' failed: {ex.Message}");

                    // Auto-disable after 3 consecutive failures
                    if (task.ConsecutiveFailures >= 3)
                    {
                        task.IsCompleted = true;
                        _tasks.TryRemove(task.Id, out _);
                        Console.WriteLine(
                            $"[Scheduler] Task '{task.Name}' disabled after 3 failures.");
                    }
                }
            }
        }
        finally
        {
            Monitor.Exit(_executionLock);
        }
    }

    /// <summary>Get a snapshot of all pending tasks.</summary>     // FIX 16
    public IReadOnlyList<ScheduledTask> GetPendingTasks()
    {
        return _tasks.Values
            .Where(t => !t.IsCompleted)
            .OrderBy(t => t.ScheduledTimeUtc)
            .ToList()
            .AsReadOnly();
    }

    /// <summary>Gracefully stop the scheduler.</summary>
    public void Stop()
    {
        if (!_isRunning) return;

        _isRunning = false;
        _cts?.Cancel();

        // FIX 15: Properly dispose timer
        _timer?.Change(Timeout.Infinite, Timeout.Infinite);
        _timer?.Dispose();
        _timer = null;

        Console.WriteLine("[Scheduler] Stopped.");
    }

    // FIX 1: Proper Dispose pattern
    public void Dispose()
    {
        if (_disposed) return;
        Stop();
        _cts?.Dispose();
        _tasks.Clear();
        _disposed = true;
        GC.SuppressFinalize(this);
    }
}

// ─── Improved Model ───────────────────────────────────────────
public class ScheduledTask
{
    public Guid Id { get; set; }                          // FIX 17
    public string Name { get; set; }
    public Action Action { get; set; }
    public DateTime ScheduledTimeUtc { get; set; }        // FIX 11
    public TimeSpan? RecurrenceInterval { get; set; }     // FIX 18
    public bool IsCompleted { get; set; }
    public DateTime CreatedAtUtc { get; set; }
    public DateTime? LastExecutedUtc { get; set; }
    public int ExecutionCount { get; set; }
    public int ConsecutiveFailures { get; set; }
    public Exception LastError { get; set; }
}

// ─── Event Args ───────────────────────────────────────────────
public class TaskExecutedEventArgs : EventArgs
{
    public Guid TaskId { get; }
    public string TaskName { get; }
    public TaskExecutedEventArgs(Guid id, string name)
    { TaskId = id; TaskName = name; }
}

public class TaskFailedEventArgs : EventArgs
{
    public Guid TaskId { get; }
    public string TaskName { get; }
    public Exception Exception { get; }
    public TaskFailedEventArgs(Guid id, string name, Exception ex)
    { TaskId = id; TaskName = name; Exception = ex; }
}
