## ✅ Fixed & Improved Code

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

// ── Enums & Models ──────────────────────────────────────────

public enum ScheduleFrequency
{
    Hourly,
    Daily,
    Weekly,
    Monthly
}

public enum ReportStatus
{
    Pending,
    Running,
    Completed,
    Failed
}

public class ScheduledReport
{
    public Guid Id { get; } = Guid.NewGuid();               // FIX 5: Unique identifier
    public string Name { get; set; } = string.Empty;
    public DateTime NextRunTimeUtc { get; set; }             // FIX 10: UTC-based
    public DateTime? LastRunTimeUtc { get; set; }            // FIX 12: Track last run
    public ScheduleFrequency Frequency { get; set; }
    public ReportStatus Status { get; set; } = ReportStatus.Pending;
    public string? LastError { get; set; }                   // FIX 12: Error tracking
    public int ConsecutiveFailures { get; set; }

    public override string ToString()
        => $"[{Id:N8}] {Name} | Next: {NextRunTimeUtc:u} | Status: {Status}";
}

// ── Scheduler ───────────────────────────────────────────────

public class ReportScheduler : IDisposable      // FIX 15: IDisposable
{
    // FIX 1: Thread-safe collection
    private readonly ConcurrentDictionary<Guid, ScheduledReport> _reports = new();
    private readonly ILogger<ReportScheduler> _logger;
    private readonly IReportGenerator _generator;

    private Timer? _timer;
    private CancellationTokenSource? _cts;       // FIX 2: Cancellation support
    private int _isProcessing;                   // FIX 7: Re-entrancy guard (0 or 1)
    private bool _disposed;

    private const int PollingIntervalMs = 30_000;  // FIX 3: Sensible default (30 s)
    private const int MaxConsecutiveFailures = 5;

    public ReportScheduler(
        ILogger<ReportScheduler> logger,
        IReportGenerator generator)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _generator = generator ?? throw new ArgumentNullException(nameof(generator));
    }

    // ── Public API ──────────────────────────────────────────

    public void AddReport(ScheduledReport report)
    {
        // FIX 4: Null check
        ArgumentNullException.ThrowIfNull(report);

        // FIX 5: Duplicate check via ConcurrentDictionary
        if (!_reports.TryAdd(report.Id, report))
        {
            _logger.LogWarning("Report {Name} ({Id}) already scheduled.", report.Name, report.Id);
            return;
        }

        _logger.LogInformation("Report scheduled: {Report}", report);
    }

    public bool RemoveReport(Guid reportId)
        => _reports.TryRemove(reportId, out _);

    public IReadOnlyList<ScheduledReport> GetAllReports()
        => _reports.Values.ToList().AsReadOnly();

    public void Start()
    {
        ObjectDisposedException.ThrowIf(_disposed, this);

        _cts = new CancellationTokenSource();

        // FIX 3: Valid interval; use Threading.Timer for async-friendly callbacks
        _timer = new Timer(
            callback: _ => _ = ProcessDueReportsAsync(),  // fire-and-forget safe wrapper
            state: null,
            dueTime: TimeSpan.Zero,
            period: TimeSpan.FromMilliseconds(PollingIntervalMs));

        _logger.LogInformation("Scheduler started. Polling every {Interval} ms.", PollingIntervalMs);
    }

    public void Stop()
    {
        _cts?.Cancel();
        _timer?.Change(Timeout.Infinite, Timeout.Infinite);  // FIX 6: Stop cleanly
        _logger.LogInformation("Scheduler stopped.");
    }

    // ── Core Processing Loop ────────────────────────────────

    private async Task ProcessDueReportsAsync()
    {
        // FIX 7: Prevent re-entrancy with Interlocked
        if (Interlocked.CompareExchange(ref _isProcessing, 1, 0) == 1)
        {
            _logger.LogDebug("Previous cycle still running — skipping.");
            return;
        }

        try
        {
            var token = _cts?.Token ?? CancellationToken.None;

            // FIX 8: Snapshot avoids "collection modified" errors
            var dueReports = _reports.Values
                .Where(r => r.NextRunTimeUtc <= DateTime.UtcNow        // FIX 10: UtcNow
                         && r.Status != ReportStatus.Running
                         && r.ConsecutiveFailures < MaxConsecutiveFailures)
                .ToList();

            foreach (var report in dueReports)
            {
                if (token.IsCancellationRequested) break;              // FIX 2

                // FIX 9: Isolated try/catch — one failure doesn't kill others
                await ProcessSingleReportAsync(report, token);
            }
        }
        catch (OperationCanceledException)
        {
            _logger.LogInformation("Processing cancelled.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Unexpected error in scheduler loop.");
        }
        finally
        {
            Interlocked.Exchange(ref _isProcessing, 0);                // FIX 7
        }
    }

    private async Task ProcessSingleReportAsync(
        ScheduledReport report, CancellationToken token)
    {
        try
        {
            report.Status = ReportStatus.Running;
            _logger.LogInformation("Generating report: {Name}", report.Name);

            // FIX 11: Properly await async call (no .Result deadlock)
            var result = await _generator.GenerateAsync(report, token);

            // FIX 12: Update status & tracking fields
            report.Status = ReportStatus.Completed;
            report.LastRunTimeUtc = DateTime.UtcNow;
            report.LastError = null;
            report.ConsecutiveFailures = 0;

            _logger.LogInformation("Report completed: {Name} → {Result}", report.Name, result);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            report.Status = ReportStatus.Failed;
            report.LastError = ex.Message;
            report.ConsecutiveFailures++;

            _logger.LogError(ex,
                "Report {Name} failed (attempt {Count}/{Max}).",
                report.Name, report.ConsecutiveFailures, MaxConsecutiveFailures);
        }
        finally
        {
            // FIX 13 + 14: Always advance NextRunTime so we never loop infinitely
            report.NextRunTimeUtc = CalculateNextRunUtc(report);
        }
    }

    // ── Schedule Calculation ────────────────────────────────

    private static DateTime CalculateNextRunUtc(ScheduledReport report)
    {
        // FIX 13: Handle ALL enum values
        var next = report.Frequency switch
        {
            ScheduleFrequency.Hourly  => report.NextRunTimeUtc.AddHours(1),
            ScheduleFrequency.Daily   => report.NextRunTimeUtc.AddDays(1),
            ScheduleFrequency.Weekly  => report.NextRunTimeUtc.AddDays(7),
            ScheduleFrequency.Monthly => report.NextRunTimeUtc.AddMonths(1),
            _ => throw new InvalidOperationException(
                     $"Unknown frequency: {report.Frequency}")  // FIX 14: Fail loud
        };

        // If we've fallen behind, skip forward to the next future slot
        while (next <= DateTime.UtcNow)
            next = AdvanceByFrequency(next, report.Frequency);

        return next;
    }

    private static DateTime AdvanceByFrequency(DateTime dt, ScheduleFrequency freq)
        => freq switch
        {
            ScheduleFrequency.Hourly  => dt.AddHours(1),
            ScheduleFrequency.Daily   => dt.AddDays(1),
            ScheduleFrequency.Weekly  => dt.AddDays(7),
            ScheduleFrequency.Monthly => dt.AddMonths(1),
            _ => throw new InvalidOperationException()
        };

    // ── IDisposable ─────────────────────────────────────────

    public void Dispose()                       // FIX 15
    {
        if (_disposed) return;
        _disposed = true;

        Stop();
        _timer?.Dispose();
        _cts?.Dispose();

        _logger.LogInformation("Scheduler disposed.");
    }
}

// ── Abstraction for Report Generation ───────────────────────

public interface IReportGenerator
{
    Task<string> GenerateAsync(ScheduledReport report, CancellationToken token);
}

public class SampleReportGenerator : IReportGenerator
{
    public async Task<string> GenerateAsync(ScheduledReport report, CancellationToken token)
    {
        await Task.Delay(1000, token);  // simulate work
        return $"[{DateTime.UtcNow:u}] {report.Name} data exported.";
    }
}
```

