## Retry Handler with Exponential Backoff + Jitter

```javascript
// src/retry/RetryHandler.js
'use strict';

const { EventEmitter } = require('node:events');

/**
 * @typedef {Object} RetryOptions
 * @property {number} maxAttempts
 * @property {number} baseDelayMs
 * @property {number} maxDelayMs
 * @property {number} backoffMultiplier
 * @property {number} jitterFactor
 * @property {Set<number>} retryableStatusCodes
 * @property {Set<string>} retryableErrors
 */

/**
 * @typedef {Object} RetryResult
 * @property {boolean} success
 * @property {*} data
 * @property {number} attempts
 * @property {Error|null} lastError
 * @property {number} totalDelayMs
 */

class RetryHandler extends EventEmitter {
  /** @type {RetryOptions} */
  #options;
  /** @type {Map<string, AbortController>} */
  #activeRetries = new Map();

  /**
   * @param {RetryOptions} options
   */
  constructor(options) {
    super();
    this.#options = { ...options };
  }

  /**
   * Execute an operation with retry logic.
   *
   * @param {string} operationId - Unique ID for tracking/cancellation
   * @param {(signal: AbortSignal) => Promise<*>} operation - The async operation
   * @param {object} [context={}] - Metadata for logging/events
   * @returns {Promise<RetryResult>}
   */
  async execute(operationId, operation, context = {}) {
    const controller = new AbortController();
    this.#activeRetries.set(operationId, controller);

    let lastError = null;
    let totalDelayMs = 0;

    try {
      for (let attempt = 1; attempt <= this.#options.maxAttempts; attempt++) {
        if (controller.signal.aborted) {
          throw new RetryAbortedError(operationId, attempt, lastError);
        }

        try {
          this.emit('attempt', { operationId, attempt, context });

          const data = await operation(controller.signal);

          this.emit('success', { operationId, attempt, totalDelayMs, context });

          return {
            success: true,
            data,
            attempts: attempt,
            lastError: null,
            totalDelayMs,
          };
        } catch (error) {
          lastError = error;

          if (controller.signal.aborted) {
            throw new RetryAbortedError(operationId, attempt, error);
          }

          if (!this.#isRetryable(error)) {
            this.emit('nonRetryableError', {
              operationId, attempt, error, context,
            });
            break;
          }

          if (attempt < this.#options.maxAttempts) {
            const delayMs = this.#calculateDelay(attempt);
            totalDelayMs += delayMs;

            this.emit('retry', {
              operationId, attempt, delayMs, error, context,
            });

            await this.#sleep(delayMs, controller.signal);
          }
        }
      }

      this.emit('exhausted', {
        operationId,
        attempts: this.#options.maxAttempts,
        lastError,
        totalDelayMs,
        context,
      });

      return {
        success: false,
        data: null,
        attempts: this.#options.maxAttempts,
        lastError,
        totalDelayMs,
      };
    } finally {
      this.#activeRetries.delete(operationId);
    }
  }

  /**
   * Cancel a specific in-flight retry sequence.
   * @param {string} operationId
   */
  cancel(operationId) {
    const controller = this.#activeRetries.get(operationId);
    if (controller) {
      controller.abort();
      this.emit('cancelled', { operationId });
    }
  }

  /** Cancel all in-flight retries. */
  cancelAll() {
    for (const [id, controller] of this.#activeRetries) {
      controller.abort();
      this.emit('cancelled', { operationId: id });
    }
    this.#activeRetries.clear();
  }

  /** @returns {number} */
  get activeCount() {
    return this.#activeRetries.size;
  }

  /**
   * Decorrelated jitter backoff.
   * @param {number} attempt - 1-based
   * @returns {number} delay in ms
   */
  #calculateDelay(attempt) {
    const exponentialDelay =
      this.#options.baseDelayMs *
      Math.pow(this.#options.backoffMultiplier, attempt - 1);

    const jitter =
      exponentialDelay *
      this.#options.jitterFactor *
      (Math.random() * 2 - 1);

    return Math.min(
      Math.max(0, Math.round(exponentialDelay + jitter)),
      this.#options.maxDelayMs,
    );
  }

  /**
   * @param {Error & {statusCode?: number; code?: string}} error
   * @returns {boolean}
   */
  #isRetryable(error) {
    if (error.statusCode && this.#options.retryableStatusCodes.has(error.statusCode)) {
      return true;
    }
    if (error.code && this.#options.retryableErrors.has(error.code)) {
      return true;
    }
    // Respect Retry-After header hints
    if (error.retryAfter != null) {
      return true;
    }
    return false;
  }

  /**
   * @param {number} ms
   * @param {AbortSignal} signal
   * @returns {Promise<void>}
   */
  #sleep(ms, signal) {
    return new Promise((resolve, reject) => {
      if (signal.aborted) {
        return reject(new Error('Aborted'));
      }

      const timer = setTimeout(resolve, ms);

      const onAbort = () => {
        clearTimeout(timer);
        reject(new Error('Aborted during sleep'));
      };

      signal.addEventListener('abort', onAbort, { once: true });
    });
  }
}

class RetryAbortedError extends Error {
  /**
   * @param {string} operationId
   * @param {number} attempt
   * @param {Error|null} cause
   */
  constructor(operationId, attempt, cause) {
    super(`Retry aborted for operation "${operationId}" at attempt ${attempt}`);
    this.name = 'RetryAbortedError';
    this.operationId = operationId;
    this.attempt = attempt;
    this.cause = cause;
  }
}

module.exports = { RetryHandler, RetryAbortedError };
