## Circuit Breaker

```javascript
// src/retry/CircuitBreaker.js
'use strict';

const { EventEmitter } = require('node:events');

const State = Object.freeze({
  CLOSED: 'CLOSED',
  OPEN: 'OPEN',
  HALF_OPEN: 'HALF_OPEN',
});

class CircuitBreaker extends EventEmitter {
  #state = State.CLOSED;
  #failureCount = 0;
  #successCount = 0;
  #halfOpenAttempts = 0;
  #nextAttemptTime = 0;
  #options;

  /**
   * @param {object} options
   * @param {number} options.failureThreshold
   * @param {number} options.successThreshold
   * @param {number} options.openTimeoutMs
   * @param {number} options.halfOpenMaxAttempts
   */
  constructor(options) {
    super();
    this.#options = { ...options };
  }

  get state() {
    return this.#state;
  }

  get stats() {
    return Object.freeze({
      state: this.#state,
      failureCount: this.#failureCount,
      successCount: this.#successCount,
    });
  }

  /**
   * Execute an operation through the circuit breaker.
   * @template T
   * @param {() => Promise<T>} operation
   * @returns {Promise<T>}
   */
  async execute(operation) {
    if (!this.#canExecute()) {
      throw new CircuitOpenError(this.#state, this.#nextAttemptTime - Date.now());
    }

    if (this.#state === State.OPEN) {
      this.#transitionTo(State.HALF_OPEN);
    }

    try {
      const result = await operation();
      this.#onSuccess();
      return result;
    } catch (error) {
      this.#onFailure();
      throw error;
    }
  }

  /** Allow execution? */
  #canExecute() {
    switch (this.#state) {
      case State.CLOSED:
        return true;
      case State.OPEN:
        return Date.now() >= this.#nextAttemptTime;
      case State.HALF_OPEN:
        return this.#halfOpenAttempts < this.#options.halfOpenMaxAttempts;
      default:
        return false;
    }
  }

  #onSuccess() {
    switch (this.#state) {
      case State.HALF_OPEN:
        this.#successCount++;
        if (this.#successCount >= this.#options.successThreshold) {
          this.#transitionTo(State.CLOSED);
        }
        break;
      case State.CLOSED:
        // Reset rolling failure count on success
        this.#failureCount = Math.max(0, this.#failureCount - 1);
        break;
    }
  }

  #onFailure() {
    switch (this.#state) {
      case State.HALF_OPEN:
        this.#transitionTo(State.OPEN);
        break;
      case State.CLOSED:
        this.#failureCount++;
        if (this.#failureCount >= this.#options.failureThreshold) {
          this.#transitionTo(State.OPEN);
        }
        break;
    }
  }

  /** @param {string} newState */
  #transitionTo(newState) {
    const previousState = this.#state;
    this.#state = newState;

    switch (newState) {
      case State.OPEN:
        this.#nextAttemptTime = Date.now() + this.#options.openTimeoutMs;
        this.#successCount = 0;
        this.#halfOpenAttempts = 0;
        break;
      case State.HALF_OPEN:
        this.#halfOpenAttempts = 0;
        this.#successCount = 0;
        break;
      case State.CLOSED:
        this.#failureCount = 0;
        this.#successCount = 0;
        this.#halfOpenAttempts = 0;
        break;
    }

    this.emit('stateChange', { from: previousState, to: newState });
  }

  reset() {
    this.#transitionTo(State.CLOSED);
  }
}

class CircuitOpenError extends Error {
  /**
   * @param {string} state
   * @param {number} retryAfterMs
   */
  constructor(state, retryAfterMs) {
    super(`Circuit breaker is ${state}. Retry after ${retryAfterMs}ms`);
    this.name = 'CircuitOpenError';
    this.state = state;
    this.retryAfterMs = Math.max(0, retryAfterMs);
  }
}

module.exports = { CircuitBreaker, CircuitOpenError, State };
