## Dead Letter Queue

```javascript
// src/retry/DeadLetterQueue.js
'use strict';

const fs = require('node:fs');
const fsp = require('node:fs/promises');
const path = require('node:path');
const { EventEmitter } = require('node:events');

class DeadLetterQueue extends EventEmitter {
  /** @type {Array<{entry: object, error: Error, timestamp: number, attempts: number}>} */
  #items = [];
  #options;
  #persistPath;

  /**
   * @param {object} options
   * @param {number} options.maxSize
   * @param {string} options.persistPath
   */
  constructor(options) {
    super();
    this.#options = { ...options };
    this.#persistPath = options.persistPath;
  }

  async init() {
    await fsp.mkdir(this.#persistPath, { recursive: true });
    await this.#loadFromDisk();
  }

  /**
   * Enqueue a failed log entry.
   * @param {object} entry - The log entry
   * @param {Error} error - The final error
   * @param {number} attempts - Number of attempts made
   */
  async enqueue(entry, error, attempts) {
    const dlqEntry = {
      id: `dlq_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      entry,
      error: {
        message: error.message,
        name: error.name,
        code: error.code,
        statusCode: error.statusCode,
      },
      attempts,
      timestamp: Date.now(),
      enqueuedAt: new Date().toISOString(),
    };

    if (this.#items.length >= this.#options.maxSize) {
      const evicted = this.#items.shift();
      this.emit('evicted', evicted);
    }

    this.#items.push(dlqEntry);
    this.emit('enqueued', dlqEntry);

    await this.#persistToDisk(dlqEntry);
  }

  /** @returns {Array} Snapshot of DLQ items. */
  peek(limit = 100) {
    return this.#items.slice(0, limit).map((item) => ({ ...item }));
  }

  /** @returns {number} */
  get size() {
    return this.#items.length;
  }

  /**
   * Replay entries through a handler.
   * @param {(entry: object) => Promise<boolean>} handler
   * @returns {Promise<{replayed: number, failed: number}>}
   */
  async replay(handler) {
    let replayed = 0;
    let failed = 0;
    const remaining = [];

    for (const item of this.#items) {
      try {
        const success = await handler(item.entry);
        if (success) {
          replayed++;
        } else {
          remaining.push(item);
          failed++;
        }
      } catch {
        remaining.push(item);
        failed++;
      }
    }

    this.#items = remaining;
    await this.#rebuildDiskStore();
    this.emit('replayed', { replayed, failed });

    return { replayed, failed };
  }

  async clear() {
    this.#items = [];
    const files = await fsp.readdir(this.#persistPath);
    await Promise.all(
      files
        .filter((f) => f.endsWith('.json'))
        .map((f) => fsp.unlink(path.join(this.#persistPath, f))),
    );
  }

  /** @param {object} entry */
  async #persistToDisk(entry) {
    const filePath = path.join(this.#persistPath, `${entry.id}.json`);
    await fsp.writeFile(filePath, JSON.stringify(entry), 'utf8');
  }

  async #loadFromDisk() {
    try {
      const files = await fsp.readdir(this.#persistPath);
      const jsonFiles = files.filter((f) => f.endsWith('.json')).sort();

      for (const file of jsonFiles) {
        try {
          const content = await fsp.readFile(
            path.join(this.#persistPath, file),
            'utf8',
          );
          this.#items.push(JSON.parse(content));
        } catch (err) {
          this.emit('corruptEntry', { file, error: err });
        }
      }
    } catch (err) {
      if (err.code !== 'ENOENT') throw err;
    }
  }

  async #rebuildDiskStore() {
    const files = await fsp.readdir(this.#persistPath);
    await Promise.all(
      files
        .filter((f) => f.endsWith('.json'))
        .map((f) => fsp.unlink(path.join(this.#persistPath, f))),
    );
    await Promise.all(this.#items.map((item) => this.#persistToDisk(item)));
  }
}

module.exports = { DeadLetterQueue };
