package com.config.source;

import java.util.Map;
import java.util.Optional;

/**
 * Abstraction for a configuration data source.
 * Sources are checked in priority order (highest first).
 */
public interface ConfigSource {

    /** Human-readable name for logging/debugging. */
    String name();

    /**
     * Priority of this source. Higher values = checked first.
     * Environment: 300, System props: 200, File: 100
     */
    int priority();

    /** Retrieve a value by key, or empty if not present. */
    Optional<String> get(String key);

    /** Return all key-value pairs from this source. */
    Map<String, String> getAll();

    /** Reload configuration from the underlying store. */
    default void reload() {
        // No-op by default
    }
}
