```java
package com.config.source;

import com.config.ConfigurationException;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public final class PropertiesFileSource implements ConfigSource {

    private final String resourcePath;
    private final Path filePath;
    private final boolean required;
    private final Map<String, String> properties = new ConcurrentHashMap<>();

    private PropertiesFileSource(String resourcePath, Path filePath, boolean required) {
        this.resourcePath = resourcePath;
        this.filePath = filePath;
        this.required = required;
        reload();
    }

    /** Load from classpath resource. */
    public static PropertiesFileSource ofClasspath(String resourcePath, boolean required) {
        return new PropertiesFileSource(
                Objects.requireNonNull(resourcePath, "resourcePath"), null, required);
    }

    /** Load from filesystem path. */
    public static PropertiesFileSource ofPath(Path filePath, boolean required) {
        return new PropertiesFileSource(
                null, Objects.requireNonNull(filePath, "filePath"), required);
    }

    @Override
    public String name() {
        return "PropertiesFile[" + (resourcePath != null ? resourcePath : filePath) + "]";
    }

    @Override
    public int priority() {
        return 100;
    }

    @Override
    public Optional<String> get(String key) {
        return Optional.ofNullable(properties.get(key));
    }

    @Override
    public Map<String, String> getAll() {
        return Collections.unmodifiableMap(new HashMap<>(properties));
    }

    @Override
    public void reload() {
        properties.clear();
        Properties props = new Properties();

        try {
            if (resourcePath != null) {
                loadFromClasspath(props);
            } else {
                loadFromFilesystem(props);
            }
        } catch (IOException e) {
            if (required) {
                throw new ConfigurationException(
                        "Failed to load required config: " + name(), e);
            }
            // Silently ignore optional missing files
            return;
        }

        props.forEach((k, v) -> properties.put(k.toString().trim(), v.toString().trim()));
    }

    private void loadFromClasspath(Properties props) throws IOException {
        try (InputStream in = Thread.currentThread()
                .getContextClassLoader()
                .getResourceAsStream(resourcePath)) {
            if (in == null) {
                if (required) {
                    throw new IOException("Classpath resource not found: " + resourcePath);
                }
                return;
            }
            props.load(in);
        }
    }

    private void loadFromFilesystem(Properties props) throws IOException {
        if (!Files.exists(filePath)) {
            if (required) {
                throw new IOException("Config file not found: " + filePath);
            }
            return;
        }
        try (InputStream in = Files.newInputStream(filePath)) {
            props.load(in);
        }
    }
}
