```java
package com.config.source;

import java.util.*;
import java.util.function.Supplier;

public final class EnvironmentSource implements ConfigSource {

    private final String prefix;
    private final Supplier<Map<String, String>> envSupplier;

    /**
     * @param prefix Only include env vars starting with this prefix.
     *               Pass empty string for all vars.
     */
    public EnvironmentSource(String prefix) {
        this(prefix, System::getenv);
    }

    // Visible for testing
    EnvironmentSource(String prefix, Supplier<Map<String, String>> envSupplier) {
        this.prefix = Objects.requireNonNull(prefix);
        this.envSupplier = envSupplier;
    }

    @Override
    public String name() {
        return "Environment[prefix=" + prefix + "]";
    }

    @Override
    public int priority() {
        return 300;
    }

    @Override
    public Optional<String> get(String key) {
        // Try exact env var name: db.host -> DB_HOST
        String envKey = toEnvKey(key);
        String value = envSupplier.get().get(envKey);
        if (value != null) {
            return Optional.of(value);
        }
        // Try with prefix: db.host -> APP_DB_HOST
        if (!prefix.isEmpty()) {
            String prefixedKey = prefix + "_" + envKey;
            value = envSupplier.get().get(prefixedKey);
            return Optional.ofNullable(value);
        }
        return Optional.empty();
    }

    @Override
    public Map<String, String> getAll() {
        Map<String, String> result = new HashMap<>();
        envSupplier.get().forEach((key, value) -> {
            if (prefix.isEmpty() || key.startsWith(prefix + "_") || key.startsWith(prefix)) {
                result.put(key, value);
            }
        });
        return Collections.unmodifiableMap(result);
    }

    /** Convert dot.notation.key to ENV_VAR_KEY. */
    static String toEnvKey(String key) {
        return key.replace('.', '_')
                  .replace('-', '_')
                  .toUpperCase(Locale.ROOT);
    }
}
