```java
package com.config.converter;

import com.config.ConfigurationException;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public final class TypeConverters {

    private static final Map<Class<?>, TypeConverter<?>> REGISTRY = new ConcurrentHashMap<>();

    static {
        register(String.class, v -> v);
        register(Integer.class, Integer::parseInt);
        register(int.class, Integer::parseInt);
        register(Long.class, Long::parseLong);
        register(long.class, Long::parseLong);
        register(Double.class, Double::parseDouble);
        register(double.class, Double::parseDouble);
        register(Float.class, Float::parseFloat);
        register(float.class, Float::parseFloat);
        register(Boolean.class, TypeConverters::parseBoolean);
        register(boolean.class, TypeConverters::parseBoolean);
        register(Duration.class, TypeConverters::parseDuration);
        register(List.class, TypeConverters::parseList);
    }

    private TypeConverters() {}

    public static <T> void register(Class<T> type, TypeConverter<T> converter) {
        REGISTRY.put(type, converter);
    }

    @SuppressWarnings("unchecked")
    public static <T> T convert(String value, Class<T> type) {
        TypeConverter<?> converter = REGISTRY.get(type);
        if (converter == null) {
            throw new ConfigurationException(
                    "No converter registered for type: " + type.getName());
        }
        try {
            return (T) converter.convert(value);
        } catch (ConfigurationException e) {
            throw e;
        } catch (Exception e) {
            throw new ConfigurationException(
                    "Failed to convert '" + value + "' to " + type.getSimpleName(), e);
        }
    }

    private static Boolean parseBoolean(String value) {
        return switch (value.toLowerCase(Locale.ROOT)) {
            case "true", "yes", "1", "on" -> true;
            case "false", "no", "0", "off" -> false;
            default -> throw new ConfigurationException(
                    "Cannot parse boolean from: '" + value + "'");
        };
    }

    /** Parse durations like "500ms", "30s", "5m", "2h". */
    private static Duration parseDuration(String value) {
        String trimmed = value.trim().toLowerCase(Locale.ROOT);
        if (trimmed.endsWith("ms")) {
            return Duration.ofMillis(Long.parseLong(trimmed.replace("ms", "")));
        } else if (trimmed.endsWith("s")) {
            return Duration.ofSeconds(Long.parseLong(trimmed.replace("s", "")));
        } else if (trimmed.endsWith("m")) {
            return Duration.ofMinutes(Long.parseLong(trimmed.replace("m", "")));
        } else if (trimmed.endsWith("h")) {
            return Duration.ofHours(Long.parseLong(trimmed.replace("h", "")));
        }
        // Fallback: try ISO-8601 format (PT10S)
        return Duration.parse(trimmed);
    }

    @SuppressWarnings("unchecked")
    private static List<String> parseList(String value) {
        if (value == null || value.isBlank()) {
            return List.of();
        }
        return Arrays.stream(value.split(","))
                     .map(String::trim)
                     .filter(s -> !s.isEmpty())
                     .toList();
    }
}
