package com.config;

import java.util.*;
import java.util.function.Predicate;

/**
 * Validates a Configuration against declared constraints.
 * Collects ALL violations before throwing (fail-fast would hide errors).
 */
public final class ConfigValidator {

    private final List<Rule> rules = new ArrayList<>();

    public ConfigValidator required(String... keys) {
        for (String key : keys) {
            rules.add(new Rule(key, "is required", config ->
                    config.getString(key).isPresent()));
        }
        return this;
    }

    public ConfigValidator range(String key, int min, int max) {
        rules.add(new Rule(key, "must be between " + min + " and " + max, config -> {
            Optional<Integer> val = config.getInt(key);
            return val.isEmpty() || (val.get() >= min && val.get() <= max);
        }));
        return this;
    }

    public ConfigValidator matches(String key, String regex) {
        rules.add(new Rule(key, "must match pattern: " + regex, config -> {
            Optional<String> val = config.getString(key);
            return val.isEmpty() || val.get().matches(regex);
        }));
        return this;
    }

    public ConfigValidator custom(String key, String description, Predicate<Configuration> check) {
        rules.add(new Rule(key, description, check));
        return this;
    }

    /**
     * Validates and throws if any rule fails.
     *
     * @throws ConfigurationException with details of ALL violations
     */
    public void validate(Configuration config) {
        List<String> violations = new ArrayList<>();

        for (Rule rule : rules) {
            try {
                if (!rule.check.test(config)) {
                    violations.add(rule.key + ": " + rule.description);
                }
            } catch (Exception e) {
                violations.add(rule.key + ": " + rule.description + " (error: " + e.getMessage() + ")");
            }
        }

        if (!violations.isEmpty()) {
            throw new ConfigurationException(
                    "Configuration validation failed:\n  - " +
                    String.join("\n  - ", violations));
        }
    }

    private record Rule(String key, String description, Predicate<Configuration> check) {}
}
