### `src/RetryHandler.js` — Exponential Backoff Retry Logic

```javascript
"use strict";

const { MaxRetriesExceededError } = require("./errors");

class RetryHandler {
  #maxRetries;
  #baseDelayMs;
  #maxDelayMs;
  #backoffMultiplier;
  #jitterFraction;
  #logger;

  /**
   * @param {object} options
   * @param {number} options.maxRetries        - Maximum number of retry attempts (default: 3)
   * @param {number} options.baseDelayMs       - Initial delay in milliseconds (default: 1000)
   * @param {number} options.maxDelayMs        - Maximum delay cap in milliseconds (default: 30000)
   * @param {number} options.backoffMultiplier - Multiplier for exponential backoff (default: 2)
   * @param {number} options.jitterFraction    - Random jitter fraction 0-1 (default: 0.1)
   * @param {Logger} options.logger
   */
  constructor({
    maxRetries = 3,
    baseDelayMs = 1000,
    maxDelayMs = 30000,
    backoffMultiplier = 2,
    jitterFraction = 0.1,
    logger = null,
  } = {}) {
    this.#maxRetries = maxRetries;
    this.#baseDelayMs = baseDelayMs;
    this.#maxDelayMs = maxDelayMs;
    this.#backoffMultiplier = backoffMultiplier;
    this.#jitterFraction = jitterFraction;
    this.#logger = logger;
  }

  /**
   * Calculate delay for a given attempt using exponential backoff + jitter.
   * @param {number} attempt - Zero-based attempt index
   * @returns {number} Delay in milliseconds
   */
  calculateDelay(attempt) {
    const exponentialDelay =
      this.#baseDelayMs * Math.pow(this.#backoffMultiplier, attempt);
    const cappedDelay = Math.min(exponentialDelay, this.#maxDelayMs);
    const jitter = cappedDelay * this.#jitterFraction * Math.random();
    return Math.floor(cappedDelay + jitter);
  }

  /**
   * Execute a function with retries.
   * @param {Function} fn                - Async function to execute
   * @param {object}   options
   * @param {string}   options.label     - Label for logging
   * @param {Function} options.shouldRetry - Predicate to decide if error is retriable
   * @param {Function} options.onRetry    - Callback before each retry
   * @param {AbortSignal} options.signal  - Optional abort signal
   * @returns {Promise<*>} Result of fn
   */
  async execute(fn, { label = "operation", shouldRetry = null, onRetry = null, signal = null } = {}) {
    let lastError;

    for (let attempt = 0; attempt <= this.#maxRetries; attempt++) {
      // Check for abort before each attempt
      if (signal?.aborted) {
        throw new DOMException("Operation aborted", "AbortError");
      }

      try {
        const result = await fn(attempt);
        if (attempt > 0) {
          this.#logger?.info(`${label} succeeded on retry #${attempt}`);
        }
        return result;
      } catch (error) {
        lastError = error;

        // Check if error is retriable
        const isRetriable = shouldRetry
          ? shouldRetry(error)
          : error.retriable !== false;

        if (!isRetriable || attempt >= this.#maxRetries) {
          break;
        }

        const delayMs = this.calculateDelay(attempt);

        this.#logger?.warn(`${label} failed (attempt ${attempt + 1}/${this.#maxRetries + 1}), ` +
          `retrying in ${delayMs}ms`, {
          error: error.message,
          attempt: attempt + 1,
          nextDelayMs: delayMs,
        });

        if (onRetry) {
          await onRetry(error, attempt, delayMs);
        }

        await this.#sleep(delayMs, signal);
      }
    }

    throw new MaxRetriesExceededError(
      label,
      this.#maxRetries + 1,
      lastError
    );
  }

  /**
   * Sleep with abort signal support.
   * @param {number}      ms
   * @param {AbortSignal} signal
   * @returns {Promise<void>}
   */
  #sleep(ms, signal) {
    return new Promise((resolve, reject) => {
      if (signal?.aborted) {
        return reject(new DOMException("Operation aborted", "AbortError"));
      }

      const timer = setTimeout(resolve, ms);

      signal?.addEventListener(
        "abort",
        () => {
          clearTimeout(timer);
          reject(new DOMException("Operation aborted", "AbortError"));
        },
        { once: true }
      );
    });
  }
}

module.exports = { RetryHandler };
