### `src/FileHasher.js` — Streaming File Checksums

```javascript
"use strict";

const fs = require("fs");
const crypto = require("crypto");
const { pipeline } = require("stream/promises");

class FileHasher {
  #algorithm;
  #encoding;

  /**
   * @param {object} options
   * @param {string} options.algorithm - Hash algorithm (default: "sha256")
   * @param {string} options.encoding  - Output encoding (default: "hex")
   */
  constructor({ algorithm = "sha256", encoding = "hex" } = {}) {
    this.#algorithm = algorithm;
    this.#encoding = encoding;
  }

  /**
   * Compute hash of a file using streams (memory-efficient for large files).
   * @param {string} filePath
   * @returns {Promise<string>} Hex-encoded hash
   */
  async hashFile(filePath) {
    const hash = crypto.createHash(this.#algorithm);
    const readStream = fs.createReadStream(filePath, {
      highWaterMark: 64 * 1024, // 64KB chunks
    });

    await pipeline(readStream, hash);
    return hash.digest(this.#encoding);
  }

  /**
   * Compute hash of a Buffer.
   * @param {Buffer} buffer
   * @returns {string}
   */
  hashBuffer(buffer) {
    return crypto
      .createHash(this.#algorithm)
      .update(buffer)
      .digest(this.#encoding);
  }

  /**
   * Compare two files by hash.
   * @param {string} fileA
   * @param {string} fileB
   * @returns {Promise<boolean>}
   */
  async filesEqual(fileA, fileB) {
    const [hashA, hashB] = await Promise.all([
      this.hashFile(fileA),
      this.hashFile(fileB),
    ]);
    return hashA === hashB;
  }
}

module.exports = { FileHasher };
