```javascript
"use strict";

const fs = require("fs/promises");
const path = require("path");

/**
 * Persists a manifest of synced files (path → hash + mtime) so we can
 * detect changes across runs without re-hashing every file.
 */
class SyncManifest {
  #manifestPath;
  #entries; // Map<relativePath, { hash, mtimeMs, size }>

  constructor(manifestPath) {
    this.#manifestPath = manifestPath;
    this.#entries = new Map();
  }

  /** Load manifest from disk. */
  async load() {
    try {
      const raw = await fs.readFile(this.#manifestPath, "utf-8");
      const data = JSON.parse(raw);

      this.#entries = new Map(Object.entries(data.files || {}));
    } catch (err) {
      if (err.code === "ENOENT") {
        this.#entries = new Map();
      } else {
        throw err;
      }
    }
  }

  /** Persist manifest to disk atomically. */
  async save() {
    const data = {
      version: 1,
      updatedAt: new Date().toISOString(),
      files: Object.fromEntries(this.#entries),
    };

    const tmpPath = this.#manifestPath + ".tmp";
    await fs.writeFile(tmpPath, JSON.stringify(data, null, 2), "utf-8");
    await fs.rename(tmpPath, this.#manifestPath);
  }

  /** Get stored metadata for a relative path. */
  get(relativePath) {
    return this.#entries.get(relativePath) || null;
  }

  /** Update stored metadata. */
  set(relativePath, { hash, mtimeMs, size }) {
    this.#entries.set(relativePath, { hash, mtimeMs, size });
  }

  /** Remove a path from the manifest. */
  delete(relativePath) {
    this.#entries.delete(relativePath);
  }

  /** All tracked relative paths. */
  keys() {
    return [...this.#entries.keys()];
  }

  /** Check if a file has changed vs. the manifest. */
  hasChanged(relativePath, currentMtimeMs, currentSize) {
    const entry = this.#entries.get(relativePath);
    if (!entry) return true; // Not tracked → treat as new
    // Quick check: size or mtime differ
    return entry.mtimeMs !== currentMtimeMs || entry.size !== currentSize;
  }
}

module.exports = { SyncManifest };
