### `src/ConcurrencyPool.js` — Limit Parallel Operations

```javascript
"use strict";

/**
 * Limits the number of concurrent async operations.
 */
class ConcurrencyPool {
  #maxConcurrency;
  #running;
  #queue;

  constructor(maxConcurrency = 5) {
    if (maxConcurrency < 1) {
      throw new RangeError("maxConcurrency must be >= 1");
    }
    this.#maxConcurrency = maxConcurrency;
    this.#running = 0;
    this.#queue = [];
  }

  /**
   * Run an async function with concurrency control.
   * @param {Function} fn - Async function to run
   * @returns {Promise<*>}
   */
  run(fn) {
    return new Promise((resolve, reject) => {
      const task = async () => {
        this.#running++;
        try {
          const result = await fn();
          resolve(result);
        } catch (err) {
          reject(err);
        } finally {
          this.#running--;
          this.#dequeue();
        }
      };

      if (this.#running < this.#maxConcurrency) {
        task();
      } else {
        this.#queue.push(task);
      }
    });
  }

  #dequeue() {
    if (this.#queue.length > 0 && this.#running < this.#maxConcurrency) {
      const next = this.#queue.shift();
      next();
    }
  }

  /** Run multiple tasks, collecting results (like Promise.allSettled). */
  async allSettled(tasks) {
    return Promise.allSettled(tasks.map((fn) => this.run(fn)));
  }

  get pendingCount() {
    return this.#queue.length;
  }

  get runningCount() {
    return this.#running;
  }
}

module.exports = { ConcurrencyPool };
