// Config/ConfigSection.cs
namespace ConfigEventProcessor.Config;

/// <summary>
/// Represents a parsed [Section] from the config file,
/// containing key-value entries.
/// </summary>
public sealed class ConfigSection
{
    public string Name { get; }
    private readonly Dictionary<string, string> _entries = new(StringComparer.OrdinalIgnoreCase);

    public ConfigSection(string name)
    {
        Name = name ?? throw new ArgumentNullException(nameof(name));
    }

    public IReadOnlyDictionary<string, string> Entries => _entries;

    public void Set(string key, string value) => _entries[key] = value;

    public string? Get(string key) =>
        _entries.TryGetValue(key, out var value) ? value : null;

    public T Get<T>(string key, T defaultValue = default!) where T : IParsable<T> =>
        _entries.TryGetValue(key, out var raw) && T.TryParse(raw, null, out var result)
            ? result
            : defaultValue;

    public bool GetBool(string key, bool defaultValue = false) =>
        _entries.TryGetValue(key, out var raw) && bool.TryParse(raw, out var result)
            ? result
            : defaultValue;

    public int GetInt(string key, int defaultValue = 0) =>
        _entries.TryGetValue(key, out var raw) && int.TryParse(raw, out var result)
            ? result
            : defaultValue;

    public string[] GetList(string key, char separator = ',') =>
        _entries.TryGetValue(key, out var raw)
            ? raw.Split(separator, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            : [];

    public override string ToString() => $"[{Name}] ({_entries.Count} entries)";
}
