{
    public string Field { get; init; } = string.Empty;
    public FilterOperator Operator { get; init; } = FilterOperator.Equals;
    public string Value { get; init; } = string.Empty;

    /// <summary>
    /// Evaluates whether an event's data matches this filter.
    /// </summary>
    public bool Matches(AppEvent appEvent)
    {
        if (!appEvent.Data.TryGetValue(Field, out var actual))
            return false;

        var actualStr = actual?.ToString() ?? string.Empty;

        return Operator switch
        {
            FilterOperator.Equals    => string.Equals(actualStr, Value, StringComparison.OrdinalIgnoreCase),
            FilterOperator.NotEquals => !string.Equals(actualStr, Value, StringComparison.OrdinalIgnoreCase),
            FilterOperator.Contains  => actualStr.Contains(Value, StringComparison.OrdinalIgnoreCase),

            FilterOperator.GreaterThan when double.TryParse(actualStr, out var a)
                                        && double.TryParse(Value, out var b) => a > b,

            FilterOperator.LessThan when double.TryParse(actualStr, out var a)
                                     && double.TryParse(Value, out var b) => a < b,

            _ => false
        };
    }
}
