// Config/ConfigParser.cs
using System.Diagnostics;
using System.Text.RegularExpressions;

namespace ConfigEventProcessor.Config;

/// <summary>
/// Parses INI-style config files, raising events at each parsing stage.
/// </summary>
public sealed partial class ConfigParser
{
    // ── Events ──────────────────────────────────────────────────────────

    /// <summary>Raised when a [Section] header is fully parsed.</summary>
    public event EventHandler<SectionParsedEventArgs>? SectionParsed;

    /// <summary>Raised for each Key=Value entry.</summary>
    public event EventHandler<EntryParsedEventArgs>? EntryParsed;

    /// <summary>Raised on malformed lines; set Handled=true to suppress.</summary>
    public event EventHandler<ParseErrorEventArgs>? ParseError;

    /// <summary>Raised once parsing is complete.</summary>
    public event EventHandler<ParseCompleteEventArgs>? ParseComplete;

    // ── Compiled regex via source generators (.NET 7+) ──────────────────

    [GeneratedRegex(@"^\[(?<name>[^\]]+)\]$")]
    private static partial Regex SectionPattern();

    [GeneratedRegex(@"^(?<key>[^=]+?)=(?<value>.*)$")]
    private static partial Regex EntryPattern();

    // ── Public API ──────────────────────────────────────────────────────

    /// <summary>
    /// Parses a config file and returns all sections found.
    /// </summary>
    public IReadOnlyList<ConfigSection> ParseFile(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("Config file not found.", filePath);

        var lines = File.ReadAllLines(filePath);
        return ParseLines(lines);
    }

    /// <summary>
    /// Parses config content supplied as a string.
    /// </summary>
    public IReadOnlyList<ConfigSection> ParseContent(string content)
    {
        var lines = content.Split(["\r\n", "\n"], StringSplitOptions.None);
        return ParseLines(lines);
    }

    // ── Parsing engine ──────────────────────────────────────────────────

    private IReadOnlyList<ConfigSection> ParseLines(string[] lines)
    {
        var stopwatch   = Stopwatch.StartNew();
        var sections    = new List<ConfigSection>();
        ConfigSection?  current = null;
        int entryCount  = 0;
        int errorCount  = 0;

        for (int i = 0; i < lines.Length; i++)
        {
            var line       = lines[i].Trim();
            int lineNumber = i + 1;

            // Skip blank lines and comments
            if (string.IsNullOrEmpty(line) || line.StartsWith('#') || line.StartsWith(';'))
                continue;

            // ── Section header ──────────────────────────────────────────
            var sectionMatch = SectionPattern().Match(line);
            if (sectionMatch.Success)
            {
                current = new ConfigSection(sectionMatch.Groups["name"].Value);
                sections.Add(current);
                OnSectionParsed(current);
                continue;
            }

            // ── Key=Value entry ─────────────────────────────────────────
            var entryMatch = EntryPattern().Match(line);
            if (entryMatch.Success)
            {
                if (current is null)
                {
                    OnParseError(lineNumber, line, "Entry found before any section header.", ref errorCount);
                    continue;
                }

                var key   = entryMatch.Groups["key"].Value.Trim();
                var value = entryMatch.Groups["value"].Value.Trim();

                current.Set(key, value);
                entryCount++;
                OnEntryParsed(current.Name, key, value);
                continue;
            }

            // ── Malformed line ──────────────────────────────────────────
            OnParseError(lineNumber, line, "Unrecognised syntax.", ref errorCount);
        }

        stopwatch.Stop();
        OnParseComplete(sections.Count, entryCount, errorCount, stopwatch.Elapsed);

        return sections;
    }

    // ── Event raisers ───────────────────────────────────────────────────

    private void OnSectionParsed(ConfigSection section) =>
        SectionParsed?.Invoke(this, new SectionParsedEventArgs(section));

    private void OnEntryParsed(string section, string key, string value) =>
        EntryParsed?.Invoke(this, new EntryParsedEventArgs(section, key, value));

    private void OnParseError(int lineNumber, string line, string message, ref int errorCount)
    {
        var args = new ParseErrorEventArgs(lineNumber, line, message);
        ParseError?.Invoke(this, args);

        if (!args.Handled)
            errorCount++;
    }

    private void OnParseComplete(int sections, int entries, int errors, TimeSpan elapsed) =>
        ParseComplete?.Invoke(this, new ParseCompleteEventArgs(sections, entries, errors, elapsed));
}
