```js
// src/ConfigSchema.js

const { ConfigValidationError } = require('./ConfigError');

/**
 * Supported schema types and their validators/coercers.
 * @readonly
 */
const SchemaTypes = Object.freeze({
  STRING: 'string',
  NUMBER: 'number',
  INTEGER: 'integer',
  BOOLEAN: 'boolean',
  ARRAY: 'array',
  OBJECT: 'object',
  ENUM: 'enum',
});

/**
 * Defines and validates configuration schemas.
 *
 * Schema definition format:
 * {
 *   'server.port': {
 *     type: 'integer',
 *     required: true,
 *     default: 3000,
 *     min: 1,
 *     max: 65535,
 *     description: 'Server listening port',
 *   },
 *   'server.host': {
 *     type: 'string',
 *     default: 'localhost',
 *     pattern: /^[\w.-]+$/,
 *   },
 *   'features.flags': {
 *     type: 'array',
 *     items: { type: 'string' },
 *     default: [],
 *   },
 *   'log.level': {
 *     type: 'enum',
 *     values: ['debug', 'info', 'warn', 'error'],
 *     default: 'info',
 *   }
 * }
 */
class ConfigSchema {
  /** @param {Record<string, SchemaFieldDef>} definition */
  constructor(definition) {
    if (!definition || typeof definition !== 'object') {
      throw new TypeError('Schema definition must be a non-null object');
    }
    this._definition = Object.freeze({ ...definition });
    this._validateDefinition();
  }

  /** @returns {Record<string, SchemaFieldDef>} */
  get definition() {
    return this._definition;
  }

  /**
   * Validate the schema definition itself (meta-validation).
   * @private
   */
  _validateDefinition() {
    const validTypes = new Set(Object.values(SchemaTypes));

    for (const [key, field] of Object.entries(this._definition)) {
      if (!field || typeof field !== 'object') {
        throw new TypeError(`Schema field "${key}" must be an object`);
      }
      if (!validTypes.has(field.type)) {
        throw new TypeError(
          `Schema field "${key}" has invalid type "${field.type}". ` +
          `Valid types: ${[...validTypes].join(', ')}`
        );
      }
      if (field.type === SchemaTypes.ENUM) {
        if (!Array.isArray(field.values) || field.values.length === 0) {
          throw new TypeError(
            `Enum field "${key}" must have a non-empty "values" array`
          );
        }
      }
      if (field.min !== undefined && typeof field.min !== 'number') {
        throw new TypeError(`Schema field "${key}": "min" must be a number`);
      }
      if (field.max !== undefined && typeof field.max !== 'number') {
        throw new TypeError(`Schema field "${key}": "max" must be a number`);
      }
    }
  }

  /**
   * Coerce a raw value to the expected schema type.
   * Returns the coerced value or throws on impossible coercion.
   *
   * @param {string} key
   * @param {*} value
   * @returns {*}
   */
  coerce(key, value) {
    const field = this._definition[key];
    if (!field) return value;
    if (value === undefined || value === null) return value;

    switch (field.type) {
      case SchemaTypes.STRING:
        return String(value);

      case SchemaTypes.NUMBER: {
        const num = Number(value);
        if (Number.isNaN(num)) {
          throw new ConfigValidationError(
            `Cannot coerce "${value}" to number for key "${key}"`,
            [{ key, message: `"${value}" is not a valid number` }]
          );
        }
        return num;
      }

      case SchemaTypes.INTEGER: {
        const int = Number(value);
        if (Number.isNaN(int) || !Number.isInteger(int)) {
          throw new ConfigValidationError(
            `Cannot coerce "${value}" to integer for key "${key}"`,
            [{ key, message: `"${value}" is not a valid integer` }]
          );
        }
        return int;
      }

      case SchemaTypes.BOOLEAN: {
        if (typeof value === 'boolean') return value;
        if (typeof value === 'string') {
          const lower = value.toLowerCase().trim();
          if (['true', '1', 'yes', 'on'].includes(lower)) return true;
          if (['false', '0', 'no', 'off'].includes(lower)) return false;
        }
        if (typeof value === 'number') return value !== 0;
        throw new ConfigValidationError(
          `Cannot coerce "${value}" to boolean for key "${key}"`,
          [{ key, message: `"${value}" is not a valid boolean` }]
        );
      }

      case SchemaTypes.ARRAY: {
        if (Array.isArray(value)) return value;
        if (typeof value === 'string') {
          try {
            const parsed = JSON.parse(value);
            if (Array.isArray(parsed)) return parsed;
          } catch {
            // Try comma-separated
            return value.split(',').map((s) => s.trim()).filter(Boolean);
          }
        }
        throw new ConfigValidationError(
          `Cannot coerce "${value}" to array for key "${key}"`,
          [{ key, message: `"${value}" is not a valid array` }]
        );
      }

      case SchemaTypes.OBJECT: {
        if (typeof value === 'object' && !Array.isArray(value)) return value;
        if (typeof value === 'string') {
          try {
            const parsed = JSON.parse(value);
            if (typeof parsed === 'object' && !Array.isArray(parsed)) {
              return parsed;
            }
          } catch { /* fall through */ }
        }
        throw new ConfigValidationError(
          `Cannot coerce "${value}" to object for key "${key}"`,
          [{ key, message: `"${value}" is not a valid object` }]
        );
      }

      case SchemaTypes.ENUM:
        return value; // validated separately

      default:
        return value;
    }
  }

  /**
   * Validate a flat config object against this schema.
   * Returns an array of violations (empty = valid).
   *
   * @param {Record<string, *>} flatConfig - Dot-notation keyed config
   * @returns {Array<{key: string, message: string}>}
   */
  validate(flatConfig) {
    const violations = [];

    for (const [key, field] of Object.entries(this._definition)) {
      const value = flatConfig[key];
      const hasValue = value !== undefined && value !== null;

      // Required check
      if (field.required && !hasValue && field.default === undefined) {
        violations.push({ key, message: `Required field "${key}" is missing` });
        continue;
      }

      if (!hasValue) continue;

      // Type check (post-coercion)
      const typeViolation = this._checkType(key, value, field);
      if (typeViolation) {
        violations.push(typeViolation);
        continue;
      }

      // Range checks for numbers
      if (
        (field.type === SchemaTypes.NUMBER || field.type === SchemaTypes.INTEGER)
      ) {
        if (field.min !== undefined && value < field.min) {
          violations.push({
            key,
            message: `"${key}" must be >= ${field.min}, got ${value}`,
          });
        }
        if (field.max !== undefined && value > field.max) {
          violations.push({
            key,
            message: `"${key}" must be <= ${field.max}, got ${value}`,
          });
        }
      }

      // String length checks
      if (field.type === SchemaTypes.STRING) {
        if (field.minLength !== undefined && value.length < field.minLength) {
          violations.push({
            key,
            message: `"${key}" must have length >= ${field.minLength}`,
          });
        }
        if (field.maxLength !== undefined && value.length > field.maxLength) {
          violations.push({
            key,
            message: `"${key}" must have length <= ${field.maxLength}`,
          });
        }
        if (field.pattern && !field.pattern.test(value)) {
          violations.push({
            key,
            message: `"${key}" does not match pattern ${field.pattern}`,
          });
        }
      }

      // Enum check
      if (field.type === SchemaTypes.ENUM && !field.values.includes(value)) {
        violations.push({
          key,
          message: `"${key}" must be one of [${field.values.join(', ')}], got "${value}"`,
        });
      }

      // Custom validator
      if (typeof field.validate === 'function') {
        const customError = field.validate(value);
        if (typeof customError === 'string') {
          violations.push({ key, message: customError });
        }
      }
    }

    return violations;
  }

  /**
   * @private
   * @returns {{key: string, message: string} | null}
   */
  _checkType(key, value, field) {
    const { type } = field;

    const typeChecks = {
      [SchemaTypes.STRING]: () => typeof value === 'string',
      [SchemaTypes.NUMBER]: () => typeof value === 'number' && !Number.isNaN(value),
      [SchemaTypes.INTEGER]: () => Number.isInteger(value),
      [SchemaTypes.BOOLEAN]: () => typeof value === 'boolean',
      [SchemaTypes.ARRAY]: () => Array.isArray(value),
      [SchemaTypes.OBJECT]: () => typeof value === 'object' && !Array.isArray(value),
      [SchemaTypes.ENUM]: () => true, // checked separately
    };

    const checker = typeChecks[type];
    if (checker && !checker()) {
      return {
        key,
        message: `"${key}" expected type "${type}", got "${typeof value}"`,
      };
    }
    return null;
  }

  /**
   * Extract defaults from schema definition.
   * @returns {Record<string, *>}
   */
  getDefaults() {
    const defaults = {};
    for (const [key, field] of Object.entries(this._definition)) {
      if (field.default !== undefined) {
        // Deep clone to prevent mutation of default arrays/objects
        defaults[key] = structuredClone(field.default);
      }
    }
    return defaults;
  }
}

module.exports = { ConfigSchema, SchemaTypes };
