// src/sources/ObjectSource.js

const { ConfigSourceError } = require('../ConfigError');

/**
 * Configuration source backed by a plain JavaScript object.
 */
class ObjectSource {
  /**
   * @param {Record<string, *>} data
   * @param {object} [options]
   * @param {string} [options.name='object'] - Source name for error messages
   */
  constructor(data, { name = 'object' } = {}) {
    if (!data || typeof data !== 'object' || Array.isArray(data)) {
      throw new ConfigSourceError('ObjectSource requires a plain object', {
        source: name,
      });
    }
    this._data = data;
    this._name = name;
  }

  get name() {
    return this._name;
  }

  /**
   * Load configuration and return flat dot-notation map.
   * @returns {Record<string, *>}
   */
  load() {
    return ObjectSource.flatten(this._data);
  }

  /**
   * Flatten a nested object into dot-notation keys.
   * @param {Record<string, *>} obj
   * @param {string} [prefix='']
   * @returns {Record<string, *>}
   */
  static flatten(obj, prefix = '') {
    const result = {};

    for (const [key, value] of Object.entries(obj)) {
      const fullKey = prefix ? `${prefix}.${key}` : key;

      if (
        value !== null &&
        typeof value === 'object' &&
        !Array.isArray(value) &&
        Object.keys(value).length > 0
      ) {
        Object.assign(result, ObjectSource.flatten(value, fullKey));
      } else {
        result[fullKey] = value;
      }
    }

    return result;
  }

  /**
   * Expand a flat dot-notation map into a nested object.
   * @param {Record<string, *>} flat
   * @returns {Record<string, *>}
   */
  static expand(flat) {
    const result = {};

    for (const [key, value] of Object.entries(flat)) {
      const parts = key.split('.');
      let current = result;

      for (let i = 0; i < parts.length - 1; i++) {
        const part = parts[i];
        if (!(part in current) || typeof current[part] !== 'object') {
          current[part] = {};
        }
        current = current[part];
      }

      current[parts[parts.length - 1]] = value;
    }

    return result;
  }
}

module.exports = { ObjectSource };
