   * @param {string} [options.prefix='APP'] - Env variable prefix
   * @param {string} [options.separator='_'] - Separator in env var names
   * @param {Record<string, string>} [options.mapping] - Explicit env->key mapping
   * @param {Record<string, string>} [options.env=process.env] - Environment object
   */
  constructor({
    prefix = 'APP',
    separator = '_',
    mapping = {},
    env = process.env,
  } = {}) {
    if (typeof prefix !== 'string') {
      throw new ConfigSourceError('EnvSource prefix must be a string', {
        source: 'env',
      });
    }
    this._prefix = prefix.toUpperCase();
    this._separator = separator;
    this._mapping = Object.freeze({ ...mapping });
    this._env = env;
  }

  get name() {
    return 'env';
  }

  /**
   * Load configuration from environment variables.
   * @returns {Record<string, string>}
   */
  load() {
    const config = {};

    // Apply explicit mappings first
    for (const [envKey, configKey] of Object.entries(this._mapping)) {
      const value = this._env[envKey];
      if (value !== undefined) {
        config[configKey] = value;
      }
    }

    // Auto-discover prefixed variables
    const prefixWithSep = `${this._prefix}${this._separator}`;

    for (const [envKey, value] of Object.entries(this._env)) {
      if (!envKey.startsWith(prefixWithSep)) continue;

      const configKey = envKey
        .slice(prefixWithSep.length)
        .toLowerCase()
        .replace(new RegExp(`\\${this._separator}`, 'g'), '.');

      // Explicit mappings take precedence
      if (!Object.values(this._mapping).includes(configKey)) {
        config[configKey] = value;
      }
    }

    return config;
  }
}

module.exports = { EnvSource };
