using System.Text.Json.Serialization;

namespace AuditLogger.Models;

public sealed class AuditEntry
{
    public Guid Id { get; init; } = Guid.NewGuid();
    public DateTime Timestamp { get; init; } = DateTime.UtcNow;
    public required string User { get; init; }
    public required string Action { get; init; }
    public string? Resource { get; init; }
    public string? Detail { get; init; }
    public Severity Severity { get; init; } = Severity.Info;

    public override string ToString()
    {
        var sev = Severity switch
        {
            Severity.Info    => "INFO",
            Severity.Warning => "WARN",
            Severity.Error   => "ERR ",
            Severity.Critical => "CRIT",
            _ => "INFO"
        };

        var resource = Resource is not null ? $" on [{Resource}]" : "";
        var detail   = Detail   is not null ? $" -- {Detail}"     : "";

        return $"[{Timestamp:yyyy-MM-dd HH:mm:ss}] [{sev}] {User}: {Action}{resource}{detail}  (id:{Id.ToString()[..8]})";
    }
}

[JsonConverter(typeof(JsonStringEnumConverter))]
public enum Severity
{
    Info,
    Warning,
    Error,
    Critical
}
