```csharp
using System.Text.Json;
using AuditLogger.Models;

namespace AuditLogger.Services;

public sealed class JsonFileAuditStore : IAuditStore
{
    private readonly string _filePath;
    private readonly object _lock = new();

    private static readonly JsonSerializerOptions JsonOpts = new()
    {
        WriteIndented = true,
        PropertyNameCaseInsensitive = true
    };

    public JsonFileAuditStore(string filePath = "audit_log.json")
    {
        _filePath = filePath;
    }

    // --- public API ---------------------------------------------------

    public void Append(AuditEntry entry)
    {
        lock (_lock)
        {
            var entries = LoadEntries();
            entries.Add(entry);
            Save(entries);
        }
    }

    public IReadOnlyList<AuditEntry> GetAll()
    {
        lock (_lock) return LoadEntries().AsReadOnly();
    }

    public IReadOnlyList<AuditEntry> Query(Func<AuditEntry, bool> predicate)
    {
        lock (_lock)
            return LoadEntries().Where(predicate).ToList().AsReadOnly();
    }

    public int Purge(DateTime olderThan)
    {
        lock (_lock)
        {
            var entries = LoadEntries();
            int before = entries.Count;
            entries.RemoveAll(e => e.Timestamp < olderThan);
            Save(entries);
            return before - entries.Count;
        }
    }

    // --- helpers ------------------------------------------------------

    private List<AuditEntry> LoadEntries()
    {
        if (!File.Exists(_filePath))
            return new List<AuditEntry>();

        var json = File.ReadAllText(_filePath);
        return string.IsNullOrWhiteSpace(json)
            ? new List<AuditEntry>()
            : JsonSerializer.Deserialize<List<AuditEntry>>(json, JsonOpts) ?? new();
    }

    private void Save(List<AuditEntry> entries)
    {
        File.WriteAllText(_filePath, JsonSerializer.Serialize(entries, JsonOpts));
    }
}
