```csharp
using AuditLogger.Models;
using AuditLogger.Services;

namespace AuditLogger.Commands;

public sealed class CommandParser
{
    private readonly IAuditStore _store;

    public CommandParser(IAuditStore store) => _store = store;

    public int Run(string[] args)
    {
        if (args.Length == 0)
        {
            PrintUsage();
            return 1;
        }

        var command = args[0].ToLowerInvariant();

        return command switch
        {
            "log"    => HandleLog(args[1..]),
            "list"   => HandleList(args[1..]),
            "search" => HandleSearch(args[1..]),
            "purge"  => HandlePurge(args[1..]),
            "help"   => ShowHelp(),
            _        => Unknown(command)
        };
    }

    // --- log ----------------------------------------------------------

    private int HandleLog(string[] args)
    {
        string? user = null, action = null, resource = null, detail = null;
        var severity = Severity.Info;

        for (int i = 0; i < args.Length - 1; i += 2)
        {
            switch (args[i])
            {
                case "--user"     or "-u": user     = args[i + 1]; break;
                case "--action"   or "-a": action   = args[i + 1]; break;
                case "--resource" or "-r": resource = args[i + 1]; break;
                case "--detail"   or "-d": detail   = args[i + 1]; break;
                case "--severity" or "-s":
                    if (!Enum.TryParse<Severity>(args[i + 1], true, out severity))
                    {
                        Console.Error.WriteLine($"Invalid severity: {args[i + 1]}");
                        return 1;
                    }
                    break;
            }
        }

        if (user is null || action is null)
        {
            Console.Error.WriteLine("--user and --action are required.");
            return 1;
        }

        var entry = new AuditEntry
        {
            User     = user,
            Action   = action,
            Resource = resource,
            Detail   = detail,
            Severity = severity
        };

        _store.Append(entry);
        Console.WriteLine($"Logged: {entry}");
        return 0;
    }

    // --- list ---------------------------------------------------------

    private int HandleList(string[] args)
    {
        int last = 0; // 0 = all
        string? severityFilter = null;

        for (int i = 0; i < args.Length - 1; i += 2)
        {
            switch (args[i])
            {
                case "--last"     or "-n": last = int.Parse(args[i + 1]); break;
                case "--severity" or "-s": severityFilter = args[i + 1];  break;
            }
        }

        IReadOnlyList<AuditEntry> entries;

        if (severityFilter is not null &&
            Enum.TryParse<Severity>(severityFilter, true, out var sev))
        {
            entries = _store.Query(e => e.Severity == sev);
        }
        else
        {
            entries = _store.GetAll();
        }

        if (last > 0)
            entries = entries.TakeLast(last).ToList();

        if (entries.Count == 0)
        {
            Console.WriteLine("No entries found.");
            return 0;
        }

        foreach (var e in entries)
            Console.WriteLine(e);

        Console.WriteLine($"\n{entries.Count} entry(ies).");
        return 0;
    }

    // --- search -------------------------------------------------------

    private int HandleSearch(string[] args)
    {
        string? user = null, action = null, resource = null;

        for (int i = 0; i < args.Length - 1; i += 2)
        {
            switch (args[i])
            {
                case "--user"     or "-u": user     = args[i + 1]; break;
                case "--action"   or "-a": action   = args[i + 1]; break;
                case "--resource" or "-r": resource = args[i + 1]; break;
            }
        }

        var results = _store.Query(e =>
            (user     is null || e.User.Contains(user, StringComparison.OrdinalIgnoreCase)) &&
            (action   is null || e.Action.Contains(action, StringComparison.OrdinalIgnoreCase)) &&
            (resource is null || (e.Resource?.Contains(resource, StringComparison.OrdinalIgnoreCase) ?? false))
        );

        if (results.Count == 0)
        {
            Console.WriteLine("No matching entries.");
            return 0;
        }

        foreach (var e in results)
            Console.WriteLine(e);

        Console.WriteLine($"\n{results.Count} match(es).");
        return 0;
    }

    // --- purge --------------------------------------------------------

    private int HandlePurge(string[] args)
    {
        int days = 30;

        for (int i = 0; i < args.Length - 1; i += 2)
        {
            if (args[i] is "--days" or "-d")
                days = int.Parse(args[i + 1]);
        }

        var cutoff  = DateTime.UtcNow.AddDays(-days);
        int removed = _store.Purge(cutoff);

        Console.WriteLine($"Purged {removed} entry(ies) older than {days} day(s).");
        return 0;
    }

    // --- help ---------------------------------------------------------

    private static int ShowHelp()
    {
        PrintUsage();
        return 0;
    }

    private static int Unknown(string cmd)
    {
        Console.Error.WriteLine($"Unknown command: {cmd}");
        PrintUsage();
        return 1;
    }

    private static void PrintUsage()
    {
        Console.WriteLine("""

        audit-cli — simple audit logger

        USAGE
          audit-cli <command> [options]

        COMMANDS
          log       Record a new audit entry
            --user,     -u   (required) Who performed the action
            --action,   -a   (required) What was done
            --resource, -r   Target resource
            --detail,   -d   Extra detail text
            --severity, -s   Info | Warning | Error | Critical  (default: Info)

          list      Show audit entries
            --last,     -n   Show only last N entries
            --severity, -s   Filter by severity level

          search    Search entries
            --user,     -u   Filter by user (substring)
            --action,   -a   Filter by action (substring)
            --resource, -r   Filter by resource (substring)

          purge     Remove old entries
            --days,     -d   Remove entries older than N days (default: 30)

          help      Show this message
        """);
    }
}
