// Services/FileHasher.cs
using System.Security.Cryptography;

namespace IncrementalBackup.Services;

public class FileHasher
{
    /// <summary>
    /// Computes SHA-256 hash of a file using buffered streaming.
    /// </summary>
    public async Task<string> ComputeHashAsync(
        string filePath, CancellationToken ct = default)
    {
        using var sha256 = SHA256.Create();
        await using var stream = new FileStream(
            filePath,
            FileMode.Open,
            FileAccess.Read,
            FileShare.Read,
            bufferSize: 81920,
            useAsync: true);

        var hashBytes = await sha256.ComputeHashAsync(stream, ct);
        return Convert.ToHexString(hashBytes).ToLowerInvariant();
    }

    /// <summary>
    /// Quick change detection: compare size + last-write time 
    /// before falling back to hash comparison.
    /// </summary>
    public bool HasQuickChangeIndicator(
        FileInfo file, long previousSize, DateTime previousModifiedUtc)
    {
        return file.Length != previousSize
            || file.LastWriteTimeUtc != previousModifiedUtc;
    }
}
