// Services/BackupManifestManager.cs
using System.Text.Json;
using IncrementalBackup.Models;

namespace IncrementalBackup.Services;

public class BackupManifestManager
{
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        WriteIndented = true,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };

    private readonly string _manifestPath;

    public BackupManifestManager(string backupDirectory)
    {
        _manifestPath = Path.Combine(backupDirectory, "backup-manifest.json");
    }

    public async Task<BackupManifest> LoadAsync(CancellationToken ct = default)
    {
        if (!File.Exists(_manifestPath))
            return new BackupManifest();

        await using var stream = File.OpenRead(_manifestPath);
        return await JsonSerializer.DeserializeAsync<BackupManifest>(
                   stream, JsonOptions, ct)
               ?? new BackupManifest();
    }

    public async Task SaveAsync(
        BackupManifest manifest, CancellationToken ct = default)
    {
        // Write to temp file, then atomic rename to prevent corruption
        var tempPath = _manifestPath + ".tmp";

        await using (var stream = File.Create(tempPath))
        {
            await JsonSerializer.SerializeAsync(
                stream, manifest, JsonOptions, ct);
        }

        File.Move(tempPath, _manifestPath, overwrite: true);
    }
}
