```csharp
// Services/IncrementalBackupService.cs
using IncrementalBackup.Config;
using IncrementalBackup.Models;
using Microsoft.Extensions.Logging;

namespace IncrementalBackup.Services;

public enum BackupType { Full, Incremental }

public class BackupResult
{
    public BackupType Type { get; init; }
    public int FilesCopied { get; set; }
    public int FilesSkipped { get; set; }
    public int FilesDeleted { get; set; }
    public long BytesCopied { get; set; }
    public List<string> Errors { get; } = new();
    public TimeSpan Duration { get; set; }
    public string SnapshotDirectory { get; set; } = string.Empty;
}

public class IncrementalBackupService
{
    private readonly BackupConfiguration _config;
    private readonly BackupManifestManager _manifestManager;
    private readonly FileHasher _hasher;
    private readonly ILogger<IncrementalBackupService> _logger;

    public IncrementalBackupService(
        BackupConfiguration config,
        ILogger<IncrementalBackupService> logger)
    {
        _config = config;
        _manifestManager = new BackupManifestManager(config.BackupDirectory);
        _hasher = new FileHasher();
        _logger = logger;
    }

    /// <summary>
    /// Runs a single backup pass: decides full vs. incremental,
    /// copies changed files, updates the manifest.
    /// </summary>
    public async Task<BackupResult> RunBackupAsync(CancellationToken ct)
    {
        var stopwatch = System.Diagnostics.Stopwatch.StartNew();

        // Ensure backup root exists
        Directory.CreateDirectory(_config.BackupDirectory);

        var manifest = await _manifestManager.LoadAsync(ct);
        var backupType = ShouldRunFullBackup(manifest)
            ? BackupType.Full
            : BackupType.Incremental;

        _logger.LogInformation(
            "Starting {BackupType} backup. Source: {Source}",
            backupType, _config.SourceDirectory);

        // Create timestamped snapshot directory
        var timestamp = DateTime.UtcNow.ToString("yyyyMMdd_HHmmss");
        var snapshotDir = Path.Combine(
            _config.BackupDirectory,
            $"{backupType}_{timestamp}");
        Directory.CreateDirectory(snapshotDir);

        var result = new BackupResult
        {
            Type = backupType,
            SnapshotDirectory = snapshotDir
        };

        // Discover all eligible source files
        var sourceFiles = DiscoverSourceFiles();
        _logger.LogInformation("Discovered {Count} source files", sourceFiles.Count);

        // --- Copy new / changed files ---
        var newManifestFiles = new Dictionary<string, FileBackupRecord>();

        foreach (var file in sourceFiles)
        {
            ct.ThrowIfCancellationRequested();

            var relativePath = Path.GetRelativePath(
                _config.SourceDirectory, file.FullName);

            try
            {
                bool needsCopy = await NeedsCopyAsync(
                    file, relativePath, manifest, backupType, ct);

                if (needsCopy)
                {
                    await CopyFileAsync(file, relativePath, snapshotDir, ct);

                    var hash = await _hasher.ComputeHashAsync(file.FullName, ct);
                    newManifestFiles[relativePath] = new FileBackupRecord
                    {
                        RelativePath = relativePath,
                        Hash = hash,
                        SizeBytes = file.Length,
                        LastModifiedUtc = file.LastWriteTimeUtc,
                        BackedUpAtUtc = DateTime.UtcNow
                    };

                    result.FilesCopied++;
                    result.BytesCopied += file.Length;
                }
                else
                {
                    // Carry forward the existing record
                    if (manifest.Files.TryGetValue(relativePath, out var existing))
                        newManifestFiles[relativePath] = existing;

                    result.FilesSkipped++;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex,
                    "Failed to process {File}", relativePath);
                result.Errors.Add($"{relativePath}: {ex.Message}");
            }
        }

        // --- Detect deleted files ---
        foreach (var previousPath in manifest.Files.Keys)
        {
            if (!newManifestFiles.ContainsKey(previousPath))
            {
                _logger.LogInformation("File deleted from source: {Path}", previousPath);
                result.FilesDeleted++;
            }
        }

        // --- Update manifest ---
        manifest.Files = newManifestFiles;
        manifest.LastIncrementalUtc = DateTime.UtcNow;

        if (backupType == BackupType.Full)
        {
            manifest.LastFullBackupUtc = DateTime.UtcNow;
            manifest.IncrementalCount = 0;
        }
        else
        {
            manifest.IncrementalCount++;
        }

        await _manifestManager.SaveAsync(manifest, ct);

        // --- Retention cleanup ---
        CleanupOldSnapshots();

        stopwatch.Stop();
        result.Duration = stopwatch.Elapsed;

        _logger.LogInformation(
            "Backup complete. Type={Type}, Copied={Copied}, " +
            "Skipped={Skipped}, Deleted={Deleted}, " +
            "Bytes={Bytes}, Duration={Duration}",
            result.Type, result.FilesCopied, result.FilesSkipped,
            result.FilesDeleted, result.BytesCopied, result.Duration);

        return result;
    }

    // ----------------------------------------------------------------
    // Private helpers
    // ----------------------------------------------------------------

    private bool ShouldRunFullBackup(BackupManifest manifest)
    {
        if (manifest.LastFullBackupUtc == default)
            return true; // first run

        return manifest.IncrementalCount >= _config.FullBackupAfterIncrementals;
    }

    private List<FileInfo> DiscoverSourceFiles()
    {
        var sourceDir = new DirectoryInfo(_config.SourceDirectory);
        if (!sourceDir.Exists)
            throw new DirectoryNotFoundException(
                $"Source directory not found: {_config.SourceDirectory}");

        var maxBytes = _config.MaxFileSizeMb > 0
            ? _config.MaxFileSizeMb * 1024 * 1024
            : long.MaxValue;

        var files = new List<FileInfo>();

        foreach (var pattern in _config.IncludePatterns)
        {
            var matched = sourceDir
                .EnumerateFiles(pattern, SearchOption.AllDirectories)
                .Where(f => !IsExcludedDirectory(f.DirectoryName ?? ""))
                .Where(f => f.Length <= maxBytes);

            files.AddRange(matched);
        }

        // Deduplicate by full path (multiple patterns may match same file)
        return files
            .GroupBy(f => f.FullName)
            .Select(g => g.First())
            .ToList();
    }

    private bool IsExcludedDirectory(string directoryPath)
    {
        return _config.ExcludeDirectories.Any(excluded =>
            directoryPath.Split(Path.DirectorySeparatorChar)
                .Any(part => part.Equals(
                    excluded, StringComparison.OrdinalIgnoreCase)));
    }

    private async Task<bool> NeedsCopyAsync(
        FileInfo file,
        string relativePath,
        BackupManifest manifest,
        BackupType backupType,
        CancellationToken ct)
    {
        // Full backup → copy everything
        if (backupType == BackupType.Full)
            return true;

        // New file → copy
        if (!manifest.Files.TryGetValue(relativePath, out var record))
            return true;

        // Quick check: size or timestamp changed?
        if (_hasher.HasQuickChangeIndicator(
                file, record.SizeBytes, record.LastModifiedUtc))
        {
            // Confirm with hash to avoid false positives
            var currentHash = await _hasher.ComputeHashAsync(file.FullName, ct);
            return currentHash != record.Hash;
        }

        return false; // unchanged
    }

    private static async Task CopyFileAsync(
        FileInfo sourceFile,
        string relativePath,
        string snapshotDir,
        CancellationToken ct)
    {
        var destPath = Path.Combine(snapshotDir, relativePath);
        var destDir = Path.GetDirectoryName(destPath)!;
        Directory.CreateDirectory(destDir);

        await using var sourceStream = sourceFile.OpenRead();
        await using var destStream = new FileStream(
            destPath, FileMode.Create, FileAccess.Write,
            FileShare.None, 81920, useAsync: true);

        await sourceStream.CopyToAsync(destStream, ct);
    }

    private void CleanupOldSnapshots()
    {
        var backupRoot = new DirectoryInfo(_config.BackupDirectory);
        var snapshots = backupRoot
            .GetDirectories()
            .Where(d => d.Name.StartsWith("Full_") ||
                        d.Name.StartsWith("Incremental_"))
            .OrderByDescending(d => d.CreationTimeUtc)
            .ToList();

        if (snapshots.Count <= _config.RetentionCount)
            return;

        foreach (var old in snapshots.Skip(_config.RetentionCount))
        {
            _logger.LogInformation(
                "Removing old snapshot: {Name}", old.Name);
            try { old.Delete(recursive: true); }
            catch (Exception ex)
            {
                _logger.LogWarning(ex,
                    "Could not delete snapshot {Name}", old.Name);
            }
        }
    }
}
