## Validation

```csharp
// Validation/LogEntryValidator.cs
using LogIngestion.Configuration;
using LogIngestion.Models;
using Microsoft.Extensions.Options;

namespace LogIngestion.Validation;

public interface ILogEntryValidator
{
    (bool IsValid, string? Error) Validate(LogEntry entry);
}

public sealed class LogEntryValidator : ILogEntryValidator
{
    private readonly LogIngestionOptions _options;

    public LogEntryValidator(IOptions<LogIngestionOptions> options)
    {
        _options = options.Value;
    }

    public (bool IsValid, string? Error) Validate(LogEntry entry)
    {
        if (entry is null)
            return (false, "Log entry is null.");

        if (string.IsNullOrWhiteSpace(entry.Message))
            return (false, "Message is required.");

        if (entry.Message.Length > _options.MaxMessageLength)
            return (false, $"Message exceeds max length of {_options.MaxMessageLength}.");

        if (entry.Timestamp == default)
            return (false, "Timestamp is required.");

        var now = DateTimeOffset.UtcNow;

        if (entry.Timestamp < now - _options.MaxTimestampAge)
            return (false, $"Timestamp is older than {_options.MaxTimestampAge.TotalDays} days.");

        if (entry.Timestamp > now + _options.MaxTimestampFuture)
            return (false, "Timestamp is too far in the future.");

        if (!Enum.IsDefined(entry.Level))
            return (false, $"Invalid log level: {entry.Level}.");

        return (true, null);
    }
}
