// Services/JsonLogParser.cs
using System.Runtime.CompilerServices;
using System.Text.Json;
using LogIngestion.Configuration;
using LogIngestion.Models;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace LogIngestion.Services;

public sealed class JsonLogParser : ILogParser
{
    private readonly JsonSerializerOptions _jsonOptions;
    private readonly LogIngestionOptions _ingestionOptions;
    private readonly ILogger<JsonLogParser> _logger;

    public JsonLogParser(
        IOptions<LogIngestionOptions> ingestionOptions,
        ILogger<JsonLogParser> logger)
    {
        _ingestionOptions = ingestionOptions.Value;
        _logger = logger;

        _jsonOptions = new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true,
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            ReadCommentHandling = JsonCommentHandling.Skip,
            AllowTrailingCommas = true,
            MaxDepth = 32,
            Converters = { new JsonStringEnumConverter(JsonNamingPolicy.CamelCase) }
        };
    }

    public async Task<LogEntry?> ParseEntryAsync(Stream stream, CancellationToken ct = default)
    {
        try
        {
            return await JsonSerializer.DeserializeAsync<LogEntry>(stream, _jsonOptions, ct);
        }
        catch (JsonException ex)
        {
            _logger.LogWarning(ex, "Failed to parse single log entry from JSON");
            return null;
        }
    }

    public async Task<LogBatch?> ParseBatchAsync(Stream stream, CancellationToken ct = default)
    {
        try
        {
            // Try parsing as a LogBatch first
            var batch = await JsonSerializer.DeserializeAsync<LogBatch>(stream, _jsonOptions, ct);
            if (batch?.Entries.Count > 0)
                return batch;

            // Fall back: try parsing as an array of LogEntry
            stream.Position = 0;
            var entries = await JsonSerializer.DeserializeAsync<List<LogEntry>>(stream, _jsonOptions, ct);
            if (entries is not null)
            {
                return new LogBatch { Entries = entries };
            }

            return null;
        }
        catch (JsonException ex)
        {
            _logger.LogWarning(ex, "Failed to parse log batch from JSON");
            return null;
        }
    }

    /// <summary>
    /// Uses System.Text.Json's Utf8JsonReader for streaming parse,
    /// yielding one LogEntry at a time without loading the full array into memory.
    /// </summary>
    public async IAsyncEnumerable<LogEntry> StreamEntriesAsync(
        Stream stream,
        [EnumeratorCancellation] CancellationToken ct = default)
    {
        // Buffer the stream for efficient reading
        const int bufferSize = 16 * 1024;
        var buffer = new byte[bufferSize];
        var leftover = ReadOnlyMemory<byte>.Empty;
        var jsonState = new JsonReaderState(new JsonReaderOptions
        {
            CommentHandling = JsonCommentHandling.Skip,
            AllowTrailingCommas = true
        });

        int depth = 0;
        bool insideArray = false;
        using var entryStream = new MemoryStream();
        int objectDepth = 0;
        bool capturingObject = false;

        await using var bufferedStream = new BufferedStream(stream, bufferSize);
        using var reader = new StreamReader(bufferedStream);

        // Simpler streaming approach: read line-delimited JSON or use
        // DeserializeAsyncEnumerable for .NET 8+
        // For production, use the built-in streaming API:
        await foreach (var entry in JsonSerializer
            .DeserializeAsyncEnumerable<LogEntry>(stream, _jsonOptions, ct))
        {
            if (entry is not null)
                yield return entry;
        }
    }
}
