// Services/DatabaseLogSink.cs
using System.Data;
using System.Text.Json;
using LogIngestion.Configuration;
using LogIngestion.Models;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace LogIngestion.Services;

/// <summary>
/// Writes log entries to SQL Server using bulk copy for high throughput.
/// Replace with your preferred storage (PostgreSQL, Elasticsearch, etc.).
/// </summary>
public sealed class DatabaseLogSink : ILogSink, IAsyncDisposable
{
    private readonly string _connectionString;
    private readonly ILogger<DatabaseLogSink> _logger;
    private readonly JsonSerializerOptions _jsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };

    public DatabaseLogSink(
        IOptions<LogIngestionOptions> options,
        ILogger<DatabaseLogSink> logger)
    {
        _connectionString = options.Value.ConnectionString
            ?? throw new ArgumentNullException(nameof(options), "ConnectionString is required.");
        _logger = logger;
    }

    public async Task<int> WriteAsync(IReadOnlyList<LogEntry> entries, CancellationToken ct = default)
    {
        if (entries.Count == 0) return 0;

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(ct);

        using var bulkCopy = new SqlBulkCopy(connection)
        {
            DestinationTableName = "dbo.Logs",
            BatchSize = entries.Count,
            BulkCopyTimeout = 60
        };

        MapColumns(bulkCopy);

        using var table = CreateDataTable(entries);
        await bulkCopy.WriteToServerAsync(table, ct);

        _logger.LogDebug("Wrote {Count} log entries to database", entries.Count);
        return entries.Count;
    }

    public async Task<bool> IsHealthyAsync(CancellationToken ct = default)
    {
        try
        {
            await using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync(ct);
            return true;
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Database health check failed");
            return false;
        }
    }

    private static void MapColumns(SqlBulkCopy bulkCopy)
    {
        bulkCopy.ColumnMappings.Add("Id", "Id");
        bulkCopy.ColumnMappings.Add("Timestamp", "Timestamp");
        bulkCopy.ColumnMappings.Add("Level", "Level");
        bulkCopy.ColumnMappings.Add("Message", "Message");
        bulkCopy.ColumnMappings.Add("Source", "Source");
        bulkCopy.ColumnMappings.Add("TraceId", "TraceId");
        bulkCopy.ColumnMappings.Add("SpanId", "SpanId");
        bulkCopy.ColumnMappings.Add("ExceptionJson", "ExceptionJson");
        bulkCopy.ColumnMappings.Add("PropertiesJson", "PropertiesJson");
        bulkCopy.ColumnMappings.Add("Tags", "Tags");
        bulkCopy.ColumnMappings.Add("IngestedAt", "IngestedAt");
    }

    private DataTable CreateDataTable(IReadOnlyList<LogEntry> entries)
    {
        var table = new DataTable();
        table.Columns.Add("Id", typeof(string));
        table.Columns.Add("Timestamp", typeof(DateTimeOffset));
        table.Columns.Add("Level", typeof(string));
        table.Columns.Add("Message", typeof(string));
        table.Columns.Add("Source", typeof(string));
        table.Columns.Add("TraceId", typeof(string));
        table.Columns.Add("SpanId", typeof(string));
        table.Columns.Add("ExceptionJson", typeof(string));
        table.Columns.Add("PropertiesJson", typeof(string));
        table.Columns.Add("Tags", typeof(string));
        table.Columns.Add("IngestedAt", typeof(DateTimeOffset));

        foreach (var entry in entries)
        {
            table.Rows.Add(
                entry.Id ?? Guid.NewGuid().ToString("N"),
                entry.Timestamp,
                entry.Level.ToString(),
                entry.Message,
                entry.Source ?? (object)DBNull.Value,
                entry.TraceId ?? (object)DBNull.Value,
                entry.SpanId ?? (object)DBNull.Value,
                entry.Exception is not null
                    ? JsonSerializer.Serialize(entry.Exception, _jsonOptions)
                    : (object)DBNull.Value,
                entry.Properties is not null
                    ? JsonSerializer.Serialize(entry.Properties, _jsonOptions)
                    : (object)DBNull.Value,
                entry.Tags is not null
                    ? string.Join(",", entry.Tags)
                    : (object)DBNull.Value,
                entry.IngestedAt
            );
        }

        return table;
    }

    public ValueTask DisposeAsync() => ValueTask.CompletedTask;
}
