namespace ConfigParser.Models
{
    /// <summary>
    /// Wraps a cached configuration value with metadata for invalidation decisions.
    /// </summary>
    public sealed class CacheEntry<T>
    {
        public T Value { get; }
        public DateTimeOffset CreatedAt { get; }
        public DateTimeOffset? LastAccessedAt { get; private set; }
        public long Version { get; }
        public string SourceHash { get; }

        public CacheEntry(T value, long version, string sourceHash)
        {
            Value = value;
            CreatedAt = DateTimeOffset.UtcNow;
            LastAccessedAt = null;
            Version = version;
            SourceHash = sourceHash;
        }

        public CacheEntry<T> WithAccess()
        {
            LastAccessedAt = DateTimeOffset.UtcNow;
            return this;
        }

        public TimeSpan Age => DateTimeOffset.UtcNow - CreatedAt;
    }
}
