// Models/ConfigSection.cs
using System;
using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;

namespace ConfigParser.Models
{
    /// <summary>
    /// Represents a parsed configuration section with typed accessors.
    /// </summary>
    public sealed class ConfigSection
    {
        private readonly Dictionary<string, string> _values;
        private readonly Dictionary<string, ConfigSection> _children;

        public string Name { get; }
        public IReadOnlyDictionary<string, string> Values => _values;
        public IReadOnlyDictionary<string, ConfigSection> Children => _children;

        public ConfigSection(string name)
        {
            Name = name;
            _values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            _children = new Dictionary<string, ConfigSection>(StringComparer.OrdinalIgnoreCase);
        }

        public void Set(string key, string value) => _values[key] = value;

        public void AddChild(ConfigSection child) => _children[child.Name] = child;

        // --- Typed accessors with safe fallback ---

        public string GetString(string key, string defaultValue = "")
            => _values.TryGetValue(key, out var val) ? val : defaultValue;

        public int GetInt(string key, int defaultValue = 0)
            => _values.TryGetValue(key, out var val) && int.TryParse(val, out var n)
                ? n : defaultValue;

        public bool GetBool(string key, bool defaultValue = false)
            => _values.TryGetValue(key, out var val) && bool.TryParse(val, out var b)
                ? b : defaultValue;

        public double GetDouble(string key, double defaultValue = 0.0)
            => _values.TryGetValue(key, out var val) && double.TryParse(val, out var d)
                ? d : defaultValue;

        public TimeSpan GetTimeSpan(string key, TimeSpan defaultValue = default)
            => _values.TryGetValue(key, out var val) && TimeSpan.TryParse(val, out var ts)
                ? ts : defaultValue;

        public bool TryGetSection(string name, [NotNullWhen(true)] out ConfigSection? section)
            => _children.TryGetValue(name, out section);

        /// <summary>
        /// Navigate a dotted path like "Database.Connection.Timeout".
        /// </summary>
        public string? GetByPath(string dottedPath)
        {
            var parts = dottedPath.Split('.');
            var current = this;

            for (int i = 0; i < parts.Length - 1; i++)
            {
                if (!current._children.TryGetValue(parts[i], out var child))
                    return null;
                current = child;
            }

            return current._values.TryGetValue(parts[^1], out var value) ? value : null;
        }
    }
}
