using System;
using System.Threading;
using ConfigParser.Models;

namespace ConfigParser.Invalidation
{
    /// <summary>
    /// Invalidates cache entries after a fixed time-to-live.
    /// Optionally runs a background sweep to proactively trigger expiration.
    /// </summary>
    public sealed class TtlInvalidationStrategy : IInvalidationStrategy
    {
        private readonly TimeSpan _ttl;
        private readonly Timer? _sweepTimer;
        private bool _disposed;

        public event EventHandler? InvalidationTriggered;

        public TtlInvalidationStrategy(TimeSpan ttl, TimeSpan? sweepInterval = null)
        {
            if (ttl <= TimeSpan.Zero)
                throw new ArgumentOutOfRangeException(nameof(ttl), "TTL must be positive.");

            _ttl = ttl;

            // Optional: proactive sweep fires InvalidationTriggered periodically
            if (sweepInterval.HasValue)
            {
                _sweepTimer = new Timer(
                    _ => InvalidationTriggered?.Invoke(this, EventArgs.Empty),
                    null,
                    sweepInterval.Value,
                    sweepInterval.Value);
            }
        }

        public bool IsValid<T>(string key, CacheEntry<T> entry)
            => entry.Age < _ttl;

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _sweepTimer?.Dispose();
        }
    }
}
