using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using ConfigParser.Models;

namespace ConfigParser.Invalidation
{
    /// <summary>
    /// Watches a config file on disk and invalidates the cache
    /// when the file content hash changes.
    /// </summary>
    public sealed class FileWatcherInvalidationStrategy : IInvalidationStrategy
    {
        private readonly FileSystemWatcher _watcher;
        private readonly string _filePath;
        private string _lastHash;
        private readonly ReaderWriterLockSlim _hashLock = new();
        private bool _disposed;

        public event EventHandler? InvalidationTriggered;

        public FileWatcherInvalidationStrategy(string filePath)
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException("Config file not found.", filePath);

            _filePath = Path.GetFullPath(filePath);
            _lastHash = ComputeFileHash(_filePath);

            var directory = Path.GetDirectoryName(_filePath)!;
            var fileName = Path.GetFileName(_filePath);

            _watcher = new FileSystemWatcher(directory, fileName)
            {
                NotifyFilter = NotifyFilters.LastWrite | NotifyFilters.Size,
                EnableRaisingEvents = true
            };

            // Debounce: files often trigger multiple events per save
            Timer? debounce = null;
            _watcher.Changed += (_, _) =>
            {
                debounce?.Dispose();
                debounce = new Timer(_ => OnFileChanged(), null, 300, Timeout.Infinite);
            };
        }

        private void OnFileChanged()
        {
            var newHash = ComputeFileHash(_filePath);

            _hashLock.EnterWriteLock();
            try
            {
                if (newHash == _lastHash) return; // content didn't actually change
                _lastHash = newHash;
            }
            finally
            {
                _hashLock.ExitWriteLock();
            }

            InvalidationTriggered?.Invoke(this, EventArgs.Empty);
        }

        public bool IsValid<T>(string key, CacheEntry<T> entry)
        {
            _hashLock.EnterReadLock();
            try
            {
                // Entry is valid only if its source hash matches current file hash
                return entry.SourceHash == _lastHash;
            }
            finally
            {
                _hashLock.ExitReadLock();
            }
        }

        public string CurrentHash
        {
            get
            {
                _hashLock.EnterReadLock();
                try { return _lastHash; }
                finally { _hashLock.ExitReadLock(); }
            }
        }

        private static string ComputeFileHash(string path)
        {
            using var stream = File.OpenRead(path);
            var hash = SHA256.HashData(stream);
            return Convert.ToHexString(hash);
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _watcher.Dispose();
            _hashLock.Dispose();
        }
    }
}
