    /// <summary>
    /// Combines multiple strategies. Entry is invalid if ANY strategy says so.
    /// </summary>
    public sealed class CompositeInvalidationStrategy : IInvalidationStrategy
    {
        private readonly List<IInvalidationStrategy> _strategies;
        private bool _disposed;

        public event EventHandler? InvalidationTriggered;

        public CompositeInvalidationStrategy(params IInvalidationStrategy[] strategies)
        {
            _strategies = strategies.ToList();

            foreach (var s in _strategies)
                s.InvalidationTriggered += (sender, args) =>
                    InvalidationTriggered?.Invoke(sender, args);
        }

        public bool IsValid<T>(string key, CacheEntry<T> entry)
            => _strategies.All(s => s.IsValid(key, entry));

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _strategies.ForEach(s => s.Dispose());
        }
    }
}
