// Parsing/JsonConfigParser.cs
using System;
using System.Text.Json;
using ConfigParser.Models;

namespace ConfigParser.Parsing
{
    public sealed class JsonConfigParser : IConfigParser
    {
        public string SupportedExtension => ".json";

        public ConfigSection Parse(string content)
        {
            using var doc = JsonDocument.Parse(content, new JsonDocumentOptions
            {
                CommentHandling = JsonCommentHandling.Skip,
                AllowTrailingCommas = true
            });

            var root = new ConfigSection("Root");
            PopulateSection(root, doc.RootElement);
            return root;
        }

        private static void PopulateSection(ConfigSection section, JsonElement element)
        {
            if (element.ValueKind != JsonValueKind.Object)
                throw new FormatException("Expected a JSON object at section level.");

            foreach (var prop in element.EnumerateObject())
            {
                switch (prop.Value.ValueKind)
                {
                    case JsonValueKind.Object:
                        var child = new ConfigSection(prop.Name);
                        PopulateSection(child, prop.Value);
                        section.AddChild(child);
                        break;

                    case JsonValueKind.Array:
                        // Flatten array to comma-separated string
                        var items = new System.Collections.Generic.List<string>();
                        foreach (var item in prop.Value.EnumerateArray())
                            items.Add(item.ToString());
                        section.Set(prop.Name, string.Join(",", items));
                        break;

                    default:
                        section.Set(prop.Name, prop.Value.ToString());
                        break;
                }
            }
        }
    }
}
