// Parsing/IniConfigParser.cs
using System;
using ConfigParser.Models;

namespace ConfigParser.Parsing
{
    public sealed class IniConfigParser : IConfigParser
    {
        public string SupportedExtension => ".ini";

        public ConfigSection Parse(string content)
        {
            var root = new ConfigSection("Root");
            var currentSection = root;

            var lines = content.Split('\n', StringSplitOptions.TrimEntries);
            int lineNumber = 0;

            foreach (var rawLine in lines)
            {
                lineNumber++;
                var line = rawLine;

                // Strip inline comments
                var commentIdx = line.IndexOf(';');
                if (commentIdx >= 0) line = line[..commentIdx].TrimEnd();

                commentIdx = line.IndexOf('#');
                if (commentIdx >= 0) line = line[..commentIdx].TrimEnd();

                if (string.IsNullOrWhiteSpace(line))
                    continue;

                // Section header: [SectionName]
                if (line.StartsWith('[') && line.EndsWith(']'))
                {
                    var name = line[1..^1].Trim();
                    if (string.IsNullOrEmpty(name))
                        throw new FormatException($"Empty section name at line {lineNumber}.");

                    currentSection = new ConfigSection(name);
                    root.AddChild(currentSection);
                    continue;
                }

                // Key=Value pair
                var eqIndex = line.IndexOf('=');
                if (eqIndex < 1)
                    throw new FormatException($"Invalid syntax at line {lineNumber}: '{line}'");

                var key = line[..eqIndex].Trim();
                var value = line[(eqIndex + 1)..].Trim();

                // Remove surrounding quotes
                if (value.Length >= 2 &&
                    ((value.StartsWith('"') && value.EndsWith('"')) ||
                     (value.StartsWith('\'') && value.EndsWith('\''))))
                {
                    value = value[1..^1];
                }

                currentSection.Set(key, value);
            }

            return root;
        }
    }
}
