# Debugging a C# Roslyn Analyzer for Audit Logging

Below is a **buggy** Roslyn analyzer that enforces audit logging in service/controller methods, followed by the **debugged version** with detailed explanations.

## The Buggy Code

```csharp
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Diagnostics;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;

namespace AuditLoggingAnalyzer
{
    [DiagnosticAnalyzer(LanguageNames.CSharp)]
    public class AuditLogAnalyzer : DiagnosticAnalyzer
    {
        // Rule IDs
        public const string MissingAuditLogRuleId = "AUDIT001";
        public const string MissingUserContextRuleId = "AUDIT002";
        public const string MissingSensitiveDataMaskRuleId = "AUDIT003";
        public const string MissingTryCatchAuditRuleId = "AUDIT004";

        // BUG 1: Descriptors use wrong category and missing help link
        private static readonly DiagnosticDescriptor MissingAuditLogRule = new(
            MissingAuditLogRuleId,
            "Missing audit log",
            "Method '{0}' modifies data but has no audit logging",
            "Naming",  // Wrong category
            DiagnosticSeverity.Warning,
            isEnabledByDefault: true
            // Missing helpLinkUri
        );

        private static readonly DiagnosticDescriptor MissingUserContextRule = new(
            MissingUserContextRuleId,
            "Missing user context in audit log",
            "Audit log in '{0}' does not include user context",
            "Security",
            DiagnosticSeverity.Warning,
            isEnabledByDefault: true
        );

        private static readonly DiagnosticDescriptor MissingSensitiveDataMaskRule = new(
            MissingSensitiveDataMaskRuleId,
            "Sensitive data not masked in audit log",
            "Audit log in '{0}' may contain unmasked sensitive data: {1}",
            "Security",
            DiagnosticSeverity.Error,
            isEnabledByDefault: true
        );

        private static readonly DiagnosticDescriptor MissingTryCatchAuditRule = new(
            MissingTryCatchAuditRuleId,
            "Audit log not in try-catch",
            "Data modification in '{0}' should log failures in catch block",
            "Security",
            DiagnosticSeverity.Warning,
            isEnabledByDefault: true
        );

        // BUG 2: Not all rules are reported to SupportedDiagnostics
        public override ImmutableArray<DiagnosticDescriptor> SupportedDiagnostics =>
            ImmutableArray.Create(
                MissingAuditLogRule,
                MissingUserContextRule
                // Missing: MissingSensitiveDataMaskRule, MissingTryCatchAuditRule
            );

        // BUG 3: Registering wrong action type — SyntaxNode is better here
        public override void Initialize(AnalysisContext context)
        {
            // Missing: concurrent execution and generated code config
            context.RegisterSyntaxTreeAction(AnalyzeTree);
        }

        // BUG 4: Analyzing entire tree instead of individual method declarations
        private void AnalyzeTree(SyntaxTreeAnalysisContext context)
        {
            var root = context.Tree.GetRoot(context.CancellationToken);
            var methods = root.DescendantNodes().OfType<MethodDeclarationSyntax>();

            foreach (var method in methods)
            {
                // BUG 5: No null check, no cancellation token check
                AnalyzeMethod(method, context);
            }
        }

        private void AnalyzeMethod(
            MethodDeclarationSyntax method,
            SyntaxTreeAnalysisContext context)
        {
            // BUG 6: Only checks class name ends with "Controller"
            //         Misses "Service" classes and attribute-based detection
            var parentClass = method.Parent as ClassDeclarationSyntax;
            if (!parentClass.Identifier.Text.EndsWith("Controller"))
                return;

            // BUG 7: Only checks public methods — misses protected virtual
            if (!method.Modifiers.Any(SyntaxKind.PublicKeyword))
                return;

            var methodBody = method.Body;
            // BUG 8: Doesn't handle expression-bodied members (=>)
            if (methodBody == null)
                return;

            var invocations = methodBody.DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .ToList();

            bool hasDataModification = CheckForDataModification(invocations);
            bool hasAuditLog = CheckForAuditLog(invocations);

            if (hasDataModification && !hasAuditLog)
            {
                // BUG 9: Reports diagnostic at class level, not method level
                var diagnostic = Diagnostic.Create(
                    MissingAuditLogRule,
                    parentClass.GetLocation(),
                    method.Identifier.Text
                );
                context.ReportDiagnostic(diagnostic);
            }

            if (hasAuditLog)
            {
                CheckUserContext(method, invocations, context);
                CheckSensitiveData(method, invocations, context);
                CheckTryCatchWrapping(method, invocations, context);
            }
        }

        // BUG 10: Incomplete list and using string matching (fragile)
        private bool CheckForDataModification(
            List<InvocationExpressionSyntax> invocations)
        {
            string[] dataModMethods = { "SaveChanges", "Update", "Delete" };
            // Misses: SaveChangesAsync, Remove, Add, Insert, Execute, etc.

            foreach (var inv in invocations)
            {
                var name = inv.Expression.ToString();
                // BUG 11: Uses Contains instead of checking method name properly
                if (dataModMethods.Any(m => name.Contains(m)))
                    return true;
            }
            return false;
        }

        // BUG 12: Only checks for one specific logger pattern
        private bool CheckForAuditLog(List<InvocationExpressionSyntax> invocations)
        {
            foreach (var inv in invocations)
            {
                var expr = inv.Expression.ToString();
                // Only checks "_auditLogger.Log" — misses other patterns
                if (expr == "_auditLogger.Log")
                    return true;
            }
            return false;
        }

        private void CheckUserContext(
            MethodDeclarationSyntax method,
            List<InvocationExpressionSyntax> invocations,
            SyntaxTreeAnalysisContext context)
        {
            var auditCalls = invocations
                .Where(i => i.Expression.ToString().Contains("auditLog"));

            foreach (var call in auditCalls)
            {
                var args = call.ArgumentList.Arguments;
                // BUG 13: Checking argument text with string match is unreliable
                bool hasUserContext = args.Any(a =>
                    a.ToString().Contains("userId") ||
                    a.ToString().Contains("UserContext"));

                if (!hasUserContext)
                {
                    var diag = Diagnostic.Create(
                        MissingUserContextRule,
                        call.GetLocation(),
                        method.Identifier.Text
                    );
                    context.ReportDiagnostic(diag);
                }
            }
        }

        private void CheckSensitiveData(
            MethodDeclarationSyntax method,
            List<InvocationExpressionSyntax> invocations,
            SyntaxTreeAnalysisContext context)
        {
            // BUG 14: Hardcoded sensitive field names — should be configurable
            string[] sensitiveFields = { "password", "ssn", "creditCard" };
            // Missing: email, token, secret, key, etc.

            var auditCalls = invocations
                .Where(i => i.Expression.ToString().Contains("auditLog"));

            foreach (var call in auditCalls)
            {
                var argText = call.ArgumentList.ToString().ToLower();
                var found = sensitiveFields
                    .Where(f => argText.Contains(f))
                    .ToList();

                if (found.Any())
                {
                    // BUG 15: Reports rule that's not in SupportedDiagnostics
                    var diag = Diagnostic.Create(
                        MissingSensitiveDataMaskRule,
                        call.GetLocation(),
                        method.Identifier.Text,
                        string.Join(", ", found)
                    );
                    context.ReportDiagnostic(diag);
                }
            }
        }

        private void CheckTryCatchWrapping(
            MethodDeclarationSyntax method,
            List<InvocationExpressionSyntax> invocations,
            SyntaxTreeAnalysisContext context)
        {
            var dataModCalls = invocations
                .Where(i => i.Expression.ToString().Contains("SaveChanges"));

            foreach (var call in dataModCalls)
            {
                // BUG 16: Checks if ANY ancestor is try — should check for
                //         audit log specifically in the catch block
                var isInTry = call.Ancestors()
                    .OfType<TryStatementSyntax>()
                    .Any();

                if (!isInTry)
                {
                    var diag = Diagnostic.Create(
                        MissingTryCatchAuditRule,
                        call.GetLocation(),
                        method.Identifier.Text
                    );
                    context.ReportDiagnostic(diag);
                }
            }
        }
    }
}
