# Simple JSON Document Parser in C++

## Using nlohmann/json (Header-Only Library)

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include "nlohmann/json.hpp" // Download from https://github.com/nlohmann/json

using json = nlohmann::json;

// ---------- Data Structures ----------
struct Address {
    std::string street;
    std::string city;
    std::string state;
    int zip;
};

struct Person {
    std::string name;
    int age;
    std::string email;
    Address address;
    std::vector<std::string> hobbies;
};

// ---------- Parsing Functions ----------

/// Parse Address from JSON object
Address parseAddress(const json& j) {
    Address addr;
    addr.street = j.value("street", "");
    addr.city   = j.value("city", "");
    addr.state  = j.value("state", "");
    addr.zip    = j.value("zip", 0);
    return addr;
}

/// Parse Person from JSON object
Person parsePerson(const json& j) {
    Person p;
    p.name  = j.value("name", "Unknown");
    p.age   = j.value("age", 0);
    p.email = j.value("email", "");

    if (j.contains("address")) {
        p.address = parseAddress(j["address"]);
    }

    if (j.contains("hobbies")) {
        for (const auto& hobby : j["hobbies"]) {
            p.hobbies.push_back(hobby.get<std::string>());
        }
    }

    return p;
}

// ---------- Display Functions ----------

void printPerson(const Person& p) {
    std::cout << "===========================\n";
    std::cout << "Name    : " << p.name << "\n";
    std::cout << "Age     : " << p.age << "\n";
    std::cout << "Email   : " << p.email << "\n";
    std::cout << "Address : " << p.address.street << ", "
              << p.address.city << ", "
              << p.address.state << " "
              << p.address.zip << "\n";
    std::cout << "Hobbies : ";
    for (size_t i = 0; i < p.hobbies.size(); ++i) {
        std::cout << p.hobbies[i];
        if (i < p.hobbies.size() - 1) std::cout << ", ";
    }
    std::cout << "\n===========================\n";
}

// ---------- File I/O ----------

/// Read and parse JSON from a file
json readJsonFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open file: " + filename);
    }

    json j;
    file >> j;
    return j;
}

/// Read and parse JSON from a string
json readJsonString(const std::string& jsonStr) {
    return json::parse(jsonStr);
}

// ---------- Main ----------

int main() {
    // --- Example 1: Parse from a JSON string ---
    std::string jsonString = R"(
    {
        "people": [
            {
                "name": "Alice Johnson",
                "age": 30,
                "email": "alice@example.com",
                "address": {
                    "street": "123 Main St",
                    "city": "Springfield",
                    "state": "IL",
                    "zip": 62704
                },
                "hobbies": ["reading", "hiking", "coding"]
            },
            {
                "name": "Bob Smith",
                "age": 25,
                "email": "bob@example.com",
                "address": {
                    "street": "456 Oak Ave",
                    "city": "Portland",
                    "state": "OR",
                    "zip": 97201
                },
                "hobbies": ["gaming", "cooking"]
            }
        ],
        "metadata": {
            "version": "1.0",
            "count": 2
        }
    }
    )";

    try {
        // Parse the JSON string
        json doc = readJsonString(jsonString);

        // Access metadata
        std::cout << "Document Version: "
                  << doc["metadata"]["version"].get<std::string>() << "\n";
        std::cout << "Total People: "
                  << doc["metadata"]["count"].get<int>() << "\n\n";

        // Parse and display each person
        std::vector<Person> people;
        for (const auto& item : doc["people"]) {
            Person p = parsePerson(item);
            people.push_back(p);
            printPerson(p);
        }

