        for (auto& [key, value] : doc.items()) {
            std::cout << "Key: " << key
                      << " | Type: " << value.type_name() << "\n";
        }

    } catch (const json::parse_error& e) {
        std::cerr << "JSON Parse Error: " << e.what() << "\n";
