## src/models/LogEntry.js

```js
"use strict";

const { randomUUID } = require("crypto");

/**
 * Numeric severity: higher = more severe.
 */
const LEVEL_PRIORITY = Object.freeze({
  TRACE: 0,
  DEBUG: 1,
  INFO: 2,
  WARN: 3,
  ERROR: 4,
  FATAL: 5,
});

class LogEntry {
  /**
   * @param {object} params
   * @param {string}  params.message
   * @param {string}  params.level
   * @param {string}  [params.source]
   * @param {object}  [params.metadata]
   * @param {string}  [params.id]
   * @param {string}  [params.timestamp]
   * @param {string}  [params.traceId]
   * @param {string}  [params.spanId]
   */
  constructor({
    message,
    level,
    source = "unknown",
    metadata = {},
    id = null,
    timestamp = null,
    traceId = null,
    spanId = null,
  }) {
    this.id = id || randomUUID();
    this.timestamp = timestamp || new Date().toISOString();
    this.level = (level || "INFO").toUpperCase();
    this.message = message;
    this.source = source;
    this.metadata = Object.freeze({ ...metadata });
    this.traceId = traceId || null;
    this.spanId = spanId || null;
    this.ingestedAt = new Date().toISOString();
  }

  get priority() {
    return LEVEL_PRIORITY[this.level] ?? -1;
  }

  toJSON() {
    return {
      id: this.id,
      timestamp: this.timestamp,
      ingestedAt: this.ingestedAt,
      level: this.level,
      message: this.message,
      source: this.source,
      metadata: this.metadata,
      traceId: this.traceId,
      spanId: this.spanId,
    };
  }

  toString() {
    return `[${this.timestamp}] [${this.level}] [${this.source}] ${this.message}`;
  }

  static fromRaw(raw) {
    if (typeof raw === "string") {
      return new LogEntry({ message: raw, level: "INFO" });
    }
    return new LogEntry(raw);
  }

  static get LEVEL_PRIORITY() {
    return LEVEL_PRIORITY;
  }
}

module.exports = LogEntry;
