```js
"use strict";

const config = require("../config");
const LogEntry = require("../models/LogEntry");

class ValidationError extends Error {
  constructor(field, message) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

class LogValidator {
  constructor(options = {}) {
    this.maxMessageLength =
      options.maxMessageLength ?? config.validation.maxMessageLength;
    this.maxMetadataKeys =
      options.maxMetadataKeys ?? config.validation.maxMetadataKeys;
    this.allowedLevels =
      options.allowedLevels ?? config.validation.allowedLevels;
  }

  /**
   * Validates raw input and returns an array of errors (empty = valid).
   * @param {object} raw
   * @returns {ValidationError[]}
   */
  validate(raw) {
    const errors = [];

    if (!raw || typeof raw !== "object") {
      errors.push(new ValidationError("body", "Log entry must be an object"));
      return errors;
    }

    // message
    if (raw.message === undefined || raw.message === null) {
      errors.push(new ValidationError("message", "Message is required"));
    } else if (typeof raw.message !== "string") {
      errors.push(
        new ValidationError("message", "Message must be a string")
      );
    } else if (raw.message.trim().length === 0) {
      errors.push(
        new ValidationError("message", "Message must not be empty")
      );
    } else if (raw.message.length > this.maxMessageLength) {
      errors.push(
        new ValidationError(
          "message",
          `Message exceeds max length of ${this.maxMessageLength}`
        )
      );
    }

    // level
    if (raw.level !== undefined) {
      const upper = String(raw.level).toUpperCase();
      if (!this.allowedLevels.includes(upper)) {
        errors.push(
          new ValidationError(
            "level",
            `Invalid level "${raw.level}". Allowed: ${this.allowedLevels.join(", ")}`
          )
        );
      }
    }

    // timestamp
    if (raw.timestamp !== undefined) {
      const d = new Date(raw.timestamp);
      if (isNaN(d.getTime())) {
        errors.push(
          new ValidationError("timestamp", "Invalid timestamp format")
        );
      }
    }

    // metadata
    if (raw.metadata !== undefined) {
      if (typeof raw.metadata !== "object" || Array.isArray(raw.metadata)) {
        errors.push(
          new ValidationError("metadata", "Metadata must be a plain object")
        );
      } else {
        const keyCount = Object.keys(raw.metadata).length;
        if (keyCount > this.maxMetadataKeys) {
          errors.push(
            new ValidationError(
              "metadata",
              `Metadata exceeds max key count of ${this.maxMetadataKeys}`
            )
          );
        }
      }
    }

    // source
    if (raw.source !== undefined && typeof raw.source !== "string") {
      errors.push(
        new ValidationError("source", "Source must be a string")
      );
    }

    return errors;
  }

  /**
   * Throws on first error; returns nothing when valid.
   * @param {object} raw
   */
  assertValid(raw) {
    const errors = this.validate(raw);
    if (errors.length > 0) {
      throw errors[0];
    }
  }

  /**
   * Returns true when valid.
   * @param {object} raw
   * @returns {boolean}
   */
  isValid(raw) {
    return this.validate(raw).length === 0;
  }
}

module.exports = { LogValidator, ValidationError };
