```js
"use strict";

const LogEntry = require("../models/LogEntry");

/**
 * Parsers convert raw text / structured data into LogEntry instances.
 */
class LogParser {
  /**
   * Parse a JSON string or object into a LogEntry.
   * @param {string|object} input
   * @returns {LogEntry}
   */
  static parseJSON(input) {
    const obj = typeof input === "string" ? JSON.parse(input) : input;
    return new LogEntry(obj);
  }

  /**
   * Parse an array of raw entries.
   * @param {Array<string|object>} items
   * @returns {{ entries: LogEntry[], errors: Array<{index: number, error: Error}> }}
   */
  static parseBatch(items) {
    const entries = [];
    const errors = [];

    for (let i = 0; i < items.length; i++) {
      try {
        entries.push(LogParser.parseJSON(items[i]));
      } catch (err) {
        errors.push({ index: i, error: err });
      }
    }

    return { entries, errors };
  }

  /**
   * Parse common syslog-style format:
   *   <timestamp> <level> <source> <message>
   *
   * Example:
   *   "2024-01-15T10:30:00Z ERROR api-gateway Connection timeout"
   *
   * @param {string} line
   * @returns {LogEntry}
   */
  static parseSyslog(line) {
    if (typeof line !== "string" || line.trim().length === 0) {
      throw new Error("Cannot parse empty syslog line");
    }

    const parts = line.trim().split(/\s+/);
    if (parts.length < 4) {
      throw new Error(
        "Syslog line must have at least: timestamp level source message"
      );
    }

    const [timestamp, level, source, ...messageParts] = parts;
    return new LogEntry({
      timestamp,
      level,
      source,
      message: messageParts.join(" "),
    });
  }

  /**
   * Parse common combined log format (Apache / nginx access log).
   *
   * Example:
   *   127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /index.html HTTP/1.0" 200 2326
   *
   * @param {string} line
   * @returns {LogEntry}
   */
  static parseAccessLog(line) {
    // eslint-disable-next-line max-len
    const regex =
      /^(\S+)\s+(\S+)\s+(\S+)\s+\[([^\]]+)]\s+"([^"]+)"\s+(\d{3})\s+(\d+|-)/;

    const match = line.match(regex);
    if (!match) {
      throw new Error("Line does not match access-log format");
    }

    const [, ip, , user, timestamp, request, statusStr, bytesStr] = match;
    const status = parseInt(statusStr, 10);
    const bytes = bytesStr === "-" ? 0 : parseInt(bytesStr, 10);

    let level = "INFO";
    if (status >= 500) level = "ERROR";
    else if (status >= 400) level = "WARN";

    return new LogEntry({
      message: request,
      level,
      source: "access-log",
      timestamp: LogParser._parseAccessLogDate(timestamp),
      metadata: { ip, user, status, bytes },
    });
  }

  /**
   * Auto-detect format and parse.
   * @param {string|object} input
   * @returns {LogEntry}
   */
  static autoParse(input) {
    // Object / JSON string
    if (typeof input === "object") {
      return LogParser.parseJSON(input);
    }

    if (typeof input !== "string") {
      throw new Error(`Cannot parse input of type ${typeof input}`);
    }

    const trimmed = input.trim();

    // Looks like JSON
    if (trimmed.startsWith("{")) {
      return LogParser.parseJSON(trimmed);
    }

    // Looks like access log
    if (/^\S+\s+\S+\s+\S+\s+\[/.test(trimmed)) {
      return LogParser.parseAccessLog(trimmed);
    }

    // Fallback: syslog
    try {
      return LogParser.parseSyslog(trimmed);
    } catch {
      // Last resort: treat entire string as the message
      return new LogEntry({ message: trimmed, level: "INFO" });
    }
  }

  /**
   * Convert Apache-style date to ISO.
   * @private
   */
  static _parseAccessLogDate(dateStr) {
    // "10/Oct/2000:13:55:36 -0700"
    const months = {
      Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5,
      Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11,
    };
    const m = dateStr.match(
      /(\d{2})\/(\w{3})\/(\d{4}):(\d{2}):(\d{2}):(\d{2})\s+([+-]\d{4})/
    );
    if (!m) return new Date().toISOString();

    const [, day, mon, year, h, min, s] = m;
    const d = new Date(
      Date.UTC(+year, months[mon] || 0, +day, +h, +min, +s)
    );
    return d.toISOString();
  }
}

module.exports = LogParser;
```

