"use strict";

const StorageBackend = require("./StorageBackend");
const LogEntry = require("../models/LogEntry");
const config = require("../config");

class InMemoryStorage extends StorageBackend {
  constructor(options = {}) {
    super();
    this.maxEntries =
      options.maxEntries ?? config.storage.maxEntriesInMemory;
    /** @type {Map<string, object>} */
    this._store = new Map();
    this._initialized = false;
  }

  async initialize() {
    this._initialized = true;
  }

  async writeBatch(entries) {
    this._assertInitialized();

    for (const entry of entries) {
      if (this._store.size >= this.maxEntries) {
        // Evict oldest (first inserted)
        const firstKey = this._store.keys().next().value;
        this._store.delete(firstKey);
      }
      this._store.set(entry.id, entry.toJSON());
    }

    return entries.length;
  }

  /**
   * Query log entries with filters.
   *
   * @param {object}  q
   * @param {string}  [q.level]       - Exact level match
   * @param {string}  [q.minLevel]    - Minimum severity
   * @param {string}  [q.source]      - Source substring (case-insensitive)
   * @param {string}  [q.search]      - Message substring (case-insensitive)
   * @param {string}  [q.from]        - ISO date lower bound
   * @param {string}  [q.to]          - ISO date upper bound
   * @param {string}  [q.traceId]     - Trace-ID exact match
   * @param {number}  [q.limit=100]
   * @param {number}  [q.offset=0]
   * @param {string}  [q.sort='desc'] - 'asc' | 'desc' by timestamp
   */
  async query(q = {}) {
    this._assertInitialized();

    let results = [...this._store.values()];

    // — Filters —
    if (q.level) {
      const lvl = q.level.toUpperCase();
      results = results.filter((e) => e.level === lvl);
    }

    if (q.minLevel) {
      const minPri =
        LogEntry.LEVEL_PRIORITY[q.minLevel.toUpperCase()] ?? 0;
      results = results.filter(
        (e) => (LogEntry.LEVEL_PRIORITY[e.level] ?? 0) >= minPri
      );
