 * Base error for all parser-related failures.
 */
export class ParserError extends Error {
  /**
   * @param {string}  message
   * @param {string}  code
   * @param {boolean} retryable
   * @param {Object}  [context]
   */
  constructor(message, code, retryable = false, context = {}) {
    super(message);
    this.name = 'ParserError';
    this.code = code;
    this.retryable = retryable;
    this.context = context;
    this.timestamp = new Date().toISOString();
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      retryable: this.retryable,
      context: this.context,
      timestamp: this.timestamp,
      stack: this.stack,
    };
  }
}

export class RetryExhaustedError extends ParserError {
  /**
   * @param {number}  attempts
   * @param {Error}   lastError
   * @param {Object}  [context]
   */
  constructor(attempts, lastError, context = {}) {
    super(
      `All ${attempts} retry attempts exhausted. Last error: ${lastError.message}`,
      'RETRY_EXHAUSTED',
      false,
      { ...context, attempts, lastErrorCode: lastError.code }
    );
    this.name = 'RetryExhaustedError';
    this.lastError = lastError;
    this.attempts = attempts;
  }
}

export class CircuitOpenError extends ParserError {
  /** @param {number} recoveryTimeMs */
  constructor(recoveryTimeMs) {
    super(
      `Circuit breaker is OPEN. Retry after ${recoveryTimeMs}ms.`,
      'CIRCUIT_OPEN',
      false,
      { recoveryTimeMs }
    );
    this.name = 'CircuitOpenError';
  }
}

export class ValidationError extends ParserError {
  /**
   * @param {string}   message
   * @param {string[]} violations
   */
  constructor(message, violations = []) {
    super(message, 'VALIDATION_ERROR', false, { violations });
    this.name = 'ValidationError';
    this.violations = violations;
  }
}

export class ParseTimeoutError extends ParserError {
  /** @param {number} timeoutMs */
  constructor(timeoutMs) {
    super(
      `Parsing timed out after ${timeoutMs}ms`,
      'PARSE_TIMEOUT',
      true,
      { timeoutMs }
    );
    this.name = 'ParseTimeoutError';
  }
}
