// src/retry/RetryPolicy.js
import logger from '../logger.js';
import config from '../config.js';
import { RetryExhaustedError, ParserError } from './errors.js';

/**
 * Configurable retry policy with exponential backoff, jitter, and
 * per-attempt hooks for observability.
 */
export default class RetryPolicy {
  /** @param {Partial<import('../config.js').RetryConfig>} [overrides] */
  constructor(overrides = {}) {
    this.config = { ...config.retry, ...overrides };
  }

  // ─── public API ────────────────────────────────────────────

  /**
   * Execute `fn` with automatic retries on retryable failures.
   *
   * @template T
   * @param {() => Promise<T>}  fn              - Async work to execute
   * @param {Object}            [opts]
   * @param {string}            [opts.operationName]   - Label for logs
   * @param {string}            [opts.correlationId]   - Correlation / trace id
   * @param {(a: number, e: Error) => void} [opts.onRetry] - Per-retry callback
   * @param {AbortSignal}       [opts.signal]   - External abort signal
   * @returns {Promise<T>}
   */
  async execute(fn, opts = {}) {
    const {
      operationName = 'operation',
      correlationId = '',
      onRetry,
      signal,
    } = opts;

    let lastError;

    for (let attempt = 0; attempt <= this.config.maxRetries; attempt++) {
      // Check if externally aborted
      if (signal?.aborted) {
        throw new ParserError(
          'Operation aborted',
          'ABORTED',
          false,
          { operationName, attempt }
        );
      }

      try {
        if (attempt > 0) {
          const delay = this._calculateDelay(attempt);

          logger.warn('Retrying operation', {
            correlationId,
            operationName,
            attempt,
            maxRetries: this.config.maxRetries,
            delayMs: delay,
            lastError: lastError?.message,
          });

          onRetry?.(attempt, lastError);
          await this._sleep(delay, signal);
        }

        const result = await fn();

        if (attempt > 0) {
          logger.info('Operation succeeded after retry', {
            correlationId,
            operationName,
            attempt,
          });
        }

        return result;
      } catch (error) {
        lastError = error;

        if (!this._isRetryable(error)) {
          logger.error('Non-retryable error encountered', {
            correlationId,
            operationName,
            attempt,
            error: error.message,
            code: error.code,
          });
          throw error;
        }

        logger.warn('Retryable error encountered', {
          correlationId,
          operationName,
          attempt,
          remainingRetries: this.config.maxRetries - attempt,
          error: error.message,
          code: error.code,
        });
      }
    }

    throw new RetryExhaustedError(
      this.config.maxRetries,
      lastError,
      { operationName, correlationId }
    );
  }

  // ─── internals ─────────────────────────────────────────────

  /**
   * Exponential backoff with jitter:
   *   delay = min(base * multiplier^attempt, maxDelay) ± jitter
   * @param {number} attempt
   * @returns {number}
   */
  _calculateDelay(attempt) {
    const { baseDelayMs, backoffMultiplier, maxDelayMs, jitterFactor } =
      this.config;

    const exponential = baseDelayMs * Math.pow(backoffMultiplier, attempt - 1);
    const capped = Math.min(exponential, maxDelayMs);
    const jitter = capped * jitterFactor * (Math.random() * 2 - 1);

    return Math.max(0, Math.round(capped + jitter));
  }

  /**
   * Determine whether `error` qualifies for a retry.
   * @param {Error} error
   * @returns {boolean}
   */
  _isRetryable(error) {
    // Explicit flag on custom errors
    if (error instanceof ParserError) {
      return error.retryable;
    }

    // Match on error codes (ECONNRESET, ETIMEDOUT, …)
    if (error.code && this.config.retryableErrors.includes(error.code)) {
      return true;
    }

    // Match on HTTP status codes
    if (
      error.statusCode &&
      this.config.retryableStatusCodes.includes(error.statusCode)
    ) {
      return true;
    }

    return false;
  }

  /**
   * Abortable sleep helper.
   * @param {number}       ms
   * @param {AbortSignal}  [signal]
   * @returns {Promise<void>}
   */
  _sleep(ms, signal) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, ms);

      signal?.addEventListener('abort', () => {
        clearTimeout(timer);
        reject(
          new ParserError('Retry wait aborted', 'ABORTED', false)
        );
      }, { once: true });
    });
  }
}
