// src/retry/CircuitBreaker.js
import { EventEmitter } from 'node:events';
import logger from '../logger.js';
import config from '../config.js';
import { CircuitOpenError } from './errors.js';

/** @enum {string} */
const State = Object.freeze({
  CLOSED: 'CLOSED',
  OPEN: 'OPEN',
  HALF_OPEN: 'HALF_OPEN',
});

/**
 * Circuit breaker that wraps any async operation and prevents cascade
 * failures by short-circuiting when error rates exceed a threshold.
 *
 * Emits: 'stateChange', 'success', 'failure', 'rejected'
 */
export default class CircuitBreaker extends EventEmitter {
  /**
   * @param {Partial<import('../config.js').CircuitBreakerConfig>} [overrides]
   */
  constructor(overrides = {}) {
    super();
    this.config = { ...config.circuitBreaker, ...overrides };

    this._state = State.CLOSED;
    this._failureCount = 0;
    this._successCount = 0;
    this._lastFailureTime = 0;
    this._halfOpenInFlight = false;

    /** @type {Array<{ timestamp: number, success: boolean }>} */
    this._metrics = [];
  }

  // ─── public API ────────────────────────────────────────────

  /** @returns {string} Current state label */
  get state() {
    return this._state;
  }

  get metrics() {
    const now = Date.now();
    const window = this._metrics.filter(
      (m) => now - m.timestamp < this.config.monitorIntervalMs
    );
    const total = window.length || 1;
    const failures = window.filter((m) => !m.success).length;
    return {
      state: this._state,
      failureCount: this._failureCount,
      successCount: this._successCount,
      failureRate: (failures / total) * 100,
      windowSize: window.length,
    };
  }

  /**
   * Execute `fn` through the circuit breaker.
   *
   * @template T
   * @param {() => Promise<T>} fn
   * @returns {Promise<T>}
   * @throws {CircuitOpenError} if the circuit is open
   */
  async execute(fn) {
    if (!this._canExecute()) {
      this.emit('rejected');
      throw new CircuitOpenError(this.config.recoveryTimeMs);
    }

    try {
      const result = await fn();
      this._onSuccess();
      return result;
    } catch (error) {
      this._onFailure();
      throw error;
    }
  }

  /** Force the circuit closed (useful in tests / admin endpoints). */
  reset() {
    this._setState(State.CLOSED);
    this._failureCount = 0;
    this._successCount = 0;
    this._halfOpenInFlight = false;
    this._metrics = [];
  }

  // ─── internals ─────────────────────────────────────────────

  /** @returns {boolean} */
  _canExecute() {
    switch (this._state) {
      case State.CLOSED:
        return true;

      case State.OPEN: {
        const elapsed = Date.now() - this._lastFailureTime;
        if (elapsed >= this.config.recoveryTimeMs) {
          this._setState(State.HALF_OPEN);
          return true;
        }
        return false;
      }

      case State.HALF_OPEN:
        // Allow only one probe request at a time
        if (this._halfOpenInFlight) return false;
        this._halfOpenInFlight = true;
        return true;

      default:
        return false;
    }
  }

  _onSuccess() {
    this._record(true);
    this._halfOpenInFlight = false;

    switch (this._state) {
      case State.HALF_OPEN:
        this._successCount++;
        if (this._successCount >= this.config.successThreshold) {
          this._setState(State.CLOSED);
          this._failureCount = 0;
          this._successCount = 0;
        }
        break;

      case State.CLOSED:
        this._failureCount = Math.max(0, this._failureCount - 1);
        break;
    }

    this.emit('success');
  }

  _onFailure() {
    this._record(false);
    this._failureCount++;
    this._lastFailureTime = Date.now();
    this._halfOpenInFlight = false;

    if (this._state === State.HALF_OPEN) {
      this._setState(State.OPEN);
      this._successCount = 0;
    } else if (this._failureCount >= this.config.failureThreshold) {
      this._setState(State.OPEN);
    }

    this.emit('failure');
  }

  /** @param {string} newState */
  _setState(newState) {
    const prev = this._state;
    if (prev === newState) return;

    this._state = newState;
    logger.info('Circuit breaker state change', { from: prev, to: newState });
    this.emit('stateChange', { from: prev, to: newState });
  }

  /** @param {boolean} success */
  _record(success) {
    const now = Date.now();
    this._metrics.push({ timestamp: now, success });
    // Trim old entries
    const cutoff = now - this.config.monitorIntervalMs * 2;
    this._metrics = this._metrics.filter((m) => m.timestamp > cutoff);
  }
}
