public class ConfigParserException : Exception
{
    public string? FilePath { get; }
    public int? LineNumber { get; }
    public string? LineContent { get; }

    public ConfigParserException(string message) : base(message) { }

    public ConfigParserException(string message, string filePath, int lineNumber, string lineContent)
        : base($"{message} (File: {filePath}, Line: {lineNumber}: \"{lineContent.Trim()}\")")
    {
        FilePath = filePath;
        LineNumber = lineNumber;
        LineContent = lineContent;
    }

    public ConfigParserException(string message, Exception inner) : base(message, inner) { }
}

public class ConfigKeyNotFoundException : ConfigParserException
{
    public string Section { get; }
    public string Key { get; }

    public ConfigKeyNotFoundException(string section, string key)
        : base($"Key '{key}' not found in section '[{section}]'")
    {
        Section = section;
        Key = key;
    }
}

public class ConfigSectionNotFoundException : ConfigParserException
{
    public string Section { get; }

    public ConfigSectionNotFoundException(string section)
        : base($"Section '[{section}]' not found")
    {
        Section = section;
    }
}

public class ConfigValueException : ConfigParserException
{
    public ConfigValueException(string message) : base(message) { }
    public ConfigValueException(string key, string value, Type targetType)
        : base($"Cannot convert value '{value}' of key '{key}' to {targetType.Name}") { }
}
