### Config Value Wrapper

```csharp
// ConfigValue.cs
public class ConfigValue
{
    public string Raw { get; }
    public string Key { get; }
    public string Section { get; }
    public int LineNumber { get; }

    public ConfigValue(string raw, string key, string section, int lineNumber)
    {
        Raw = raw;
        Key = key;
        Section = section;
        LineNumber = lineNumber;
    }

    // --- Type-safe accessors with error handling ---

    public string AsString() => Raw;

    public int AsInt()
    {
        if (!int.TryParse(Raw, out int result))
            throw new ConfigValueException(Key, Raw, typeof(int));
        return result;
    }

    public double AsDouble()
    {
        if (!double.TryParse(Raw, System.Globalization.NumberStyles.Float,
            System.Globalization.CultureInfo.InvariantCulture, out double result))
            throw new ConfigValueException(Key, Raw, typeof(double));
        return result;
    }

    public bool AsBool()
    {
        return Raw.ToLowerInvariant() switch
        {
            "true" or "yes" or "1" or "on" => true,
            "false" or "no" or "0" or "off" => false,
            _ => throw new ConfigValueException(Key, Raw, typeof(bool))
        };
    }

    public T AsEnum<T>() where T : struct, Enum
    {
        if (!Enum.TryParse<T>(Raw, ignoreCase: true, out T result))
            throw new ConfigValueException(
                $"Cannot convert '{Raw}' to {typeof(T).Name}. " +
                $"Valid values: {string.Join(", ", Enum.GetNames<T>())}");
        return result;
    }

    public string[] AsArray(char separator = ',')
    {
        return Raw.Split(separator, StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
    }

    public override string ToString() => Raw;
}
