// ConfigSection.cs
public class ConfigSection : IEnumerable<KeyValuePair<string, ConfigValue>>
{
    public string Name { get; }
    private readonly Dictionary<string, ConfigValue> _values = new(StringComparer.OrdinalIgnoreCase);

    public ConfigSection(string name)
    {
        Name = name;
    }

    internal void Add(string key, ConfigValue value)
    {
        _values[key] = value;
    }

    public ConfigValue Get(string key)
    {
        if (!_values.TryGetValue(key, out var value))
            throw new ConfigKeyNotFoundException(Name, key);
        return value;
    }

    public ConfigValue? GetOptional(string key)
    {
        _values.TryGetValue(key, out var value);
        return value;
    }

    public T Get<T>(string key, T defaultValue)
    {
        if (!_values.TryGetValue(key, out var configValue))
            return defaultValue;

        try
        {
            return (T)Convert.ChangeType(configValue.Raw, typeof(T),
                System.Globalization.CultureInfo.InvariantCulture);
        }
        catch
        {
            return defaultValue;
        }
    }

    public bool ContainsKey(string key) => _values.ContainsKey(key);
    public int Count => _values.Count;

    public IEnumerator<KeyValuePair<string, ConfigValue>> GetEnumerator() => _values.GetEnumerator();
    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();
}
