### Main Parser

```csharp
// ConfigParser.cs
public class ConfigParser
{
    private readonly Dictionary<string, ConfigSection> _sections = new(StringComparer.OrdinalIgnoreCase);
    private readonly List<string> _parseErrors = new();

    public IReadOnlyList<string> ParseErrors => _parseErrors.AsReadOnly();
    public bool HasErrors => _parseErrors.Count > 0;
    public string? FilePath { get; private set; }

    // --- Parsing modes ---
    public enum ErrorMode
    {
        Strict,     // Throw on first error
        Lenient     // Collect errors, continue parsing
    }

    // --- Parse from file ---
    public static ConfigParser FromFile(string filePath, ErrorMode mode = ErrorMode.Strict)
    {
        if (!File.Exists(filePath))
            throw new ConfigParserException($"Config file not found: {filePath}");

        string[] lines;
        try
        {
            lines = File.ReadAllLines(filePath);
        }
        catch (IOException ex)
        {
            throw new ConfigParserException($"Cannot read config file: {filePath}", ex);
        }

        var parser = new ConfigParser { FilePath = filePath };
        parser.Parse(lines, filePath, mode);
        return parser;
    }

    // --- Parse from string ---
    public static ConfigParser FromString(string content, ErrorMode mode = ErrorMode.Strict)
    {
        var lines = content.Split('\n');
        var parser = new ConfigParser { FilePath = "<string>" };
        parser.Parse(lines, "<string>", mode);
        return parser;
    }

    // --- Core parsing logic ---
    private void Parse(string[] lines, string source, ErrorMode mode)
    {
        string currentSection = "Global"; // default section for top-level keys
        _sections[currentSection] = new ConfigSection(currentSection);

        for (int i = 0; i < lines.Length; i++)
        {
            int lineNumber = i + 1;
            string line = lines[i].Trim();

            // Skip empty lines and comments
            if (string.IsNullOrEmpty(line) || line.StartsWith('#') || line.StartsWith(';'))
                continue;

            // Strip inline comments
            int commentIndex = line.IndexOf(" #");
            if (commentIndex >= 0)
                line = line[..commentIndex].TrimEnd();

            try
            {
                if (line.StartsWith('['))
                {
                    currentSection = ParseSectionHeader(line, source, lineNumber);
                    if (!_sections.ContainsKey(currentSection))
                        _sections[currentSection] = new ConfigSection(currentSection);
                }
                else
                {
                    var (key, value) = ParseKeyValue(line, source, lineNumber);
                    _sections[currentSection].Add(key,
                        new ConfigValue(value, key, currentSection, lineNumber));
                }
            }
            catch (ConfigParserException ex) when (mode == ErrorMode.Lenient)
            {
                _parseErrors.Add(ex.Message);
            }
        }
    }

    private static string ParseSectionHeader(string line, string source, int lineNumber)
    {
        if (!line.EndsWith(']'))
            throw new ConfigParserException("Malformed section header — missing ']'",
                source, lineNumber, line);

        string name = line[1..^1].Trim();

        if (string.IsNullOrWhiteSpace(name))
            throw new ConfigParserException("Empty section name",
                source, lineNumber, line);

        if (name.Any(c => !char.IsLetterOrDigit(c) && c != '_' && c != '-' && c != '.'))
            throw new ConfigParserException(
                $"Invalid characters in section name: '{name}'",
                source, lineNumber, line);

        return name;
    }

    private static (string key, string value) ParseKeyValue(string line, string source, int lineNumber)
    {
        // Support both '=' and ':' as delimiters
        int eqIndex = line.IndexOf('=');
        int colonIndex = line.IndexOf(':');

        int delimIndex = (eqIndex, colonIndex) switch
        {
            ( >= 0, >= 0) => Math.Min(eqIndex, colonIndex),
            ( >= 0, _)    => eqIndex,
            (_, >= 0)     => colonIndex,
            _             => -1
        };

        if (delimIndex <= 0)
            throw new ConfigParserException("Invalid syntax — expected 'key = value'",
                source, lineNumber, line);

        string key = line[..delimIndex].Trim();
        string value = line[(delimIndex + 1)..].Trim();

        if (string.IsNullOrWhiteSpace(key))
            throw new ConfigParserException("Empty key",
                source, lineNumber, line);

        // Handle quoted strings
        if ((value.StartsWith('"') && value.EndsWith('"')) ||
            (value.StartsWith('\'') && value.EndsWith('\'')))
        {
            value = value[1..^1];
        }

        return (key, value);
    }

    // --- Public accessors ---

    public ConfigSection GetSection(string name)
    {
        if (!_sections.TryGetValue(name, out var section))
            throw new ConfigSectionNotFoundException(name);
        return section;
    }

    public ConfigSection? GetSectionOrDefault(string name)
    {
        _sections.TryGetValue(name, out var section);
        return section;
    }

    public ConfigValue Get(string section, string key)
        => GetSection(section).Get(key);

    public ConfigValue? GetOptional(string section, string key)
        => GetSectionOrDefault(section)?.GetOptional(key);

    public bool HasSection(string name) => _sections.ContainsKey(name);

    public IEnumerable<string> SectionNames => _sections.Keys;

    // --- Bind to strongly-typed object ---
    public T Bind<T>(string sectionName) where T : new()
    {
        var section = GetSection(sectionName);
        var obj = new T();
        var properties = typeof(T).GetProperties(
            System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);

        foreach (var prop in properties)
        {
            var configVal = section.GetOptional(prop.Name);
            if (configVal == null) continue;

            try
            {
                object? converted = prop.PropertyType switch
                {
                    Type t when t == typeof(string) => configVal.AsString(),
                    Type t when t == typeof(int)    => configVal.AsInt(),
                    Type t when t == typeof(double)  => configVal.AsDouble(),
                    Type t when t == typeof(bool)   => configVal.AsBool(),
                    Type t when t == typeof(float)  => (float)configVal.AsDouble(),
                    Type t when t.IsEnum            => Enum.Parse(t, configVal.Raw, ignoreCase: true),
                    _ => Convert.ChangeType(configVal.Raw, prop.PropertyType,
                            System.Globalization.CultureInfo.InvariantCulture)
                };
                prop.SetValue(obj, converted);
            }
            catch (Exception ex) when (ex is not ConfigParserException)
            {
                throw new ConfigValueException(
                    $"Cannot bind '{configVal.Raw}' to property '{prop.Name}' ({prop.PropertyType.Name})");
            }
        }
        return obj;
    }

    // --- Debug dump ---
    public void Dump(TextWriter? writer = null)
    {
        writer ??= Console.Out;
        foreach (var (name, section) in _sections)
        {
            if (section.Count == 0) continue;
            writer.WriteLine($"[{name}]");
            foreach (var (key, value) in section)
                writer.WriteLine($"  {key} = {value.Raw}");
            writer.WriteLine();
        }
    }
}
