// Program.cs
using System;

// --- Strongly-typed config classes ---
public class DatabaseConfig
{
    public string Host { get; set; } = "localhost";
    public int Port { get; set; } = 5432;
    public string Name { get; set; } = "";
    public int MaxConnections { get; set; } = 5;
    public bool EnableSSL { get; set; } = false;
}

public enum LogLevel { Trace, Debug, Info, Warning, Error, Fatal }

public class LoggingConfig
{
    public LogLevel Level { get; set; } = LogLevel.Info;
    public string FilePath { get; set; } = "";
    public double MaxFileSizeMB { get; set; } = 100.0;
}

class Program
{
    static void Main()
    {
        // ── Example 1: Parse from string ──
        Console.WriteLine("=== Basic Parsing ===\n");

        string configText = """
            [Database]
            Host = db.example.com
            Port = 5432
            Name = production
            MaxConnections = 25
            EnableSSL = true

            [Logging]
            Level = Debug
            FilePath = /var/log/app.log
            MaxFileSizeMB = 50.5

            [Cache]
            Servers = redis1,redis2,redis3
            TTL = 300
            """;

        var config = ConfigParser.FromString(configText);
        config.Dump();

        // Manual access
        string host = config.Get("Database", "Host").AsString();
        int port = config.Get("Database", "Port").AsInt();
        bool ssl = config.Get("Database", "EnableSSL").AsBool();
