## lib/tokenizer.js — Text Processing Pipeline

```javascript
const STOP_WORDS = new Set([
  'a','an','the','and','or','but','in','on','at','to','for','of','with',
  'by','from','is','it','its','this','that','are','was','were','be','been',
  'has','had','have','will','would','could','should','may','can','do','does',
  'did','not','no','so','if','as','also','than','then','just','only','very',
  'about','up','out','into','over','after','all','new','more','some','when',
  'who','which','their','there','what','each','how','them','other','these'
]);

// Lightweight suffix stripping (covers ~80% of English cases without a full stemmer)
function stem(word) {
  if (word.length < 4) return word;

  const rules = [
    [/ational$/, 'ate'],  [/tional$/, 'tion'], [/enci$/, 'ence'],
    [/anci$/, 'ance'],    [/izer$/, 'ize'],    [/ously$/, 'ous'],
    [/iveness$/, 'ive'],  [/fulness$/, 'ful'], [/ation$/, 'ate'],
    [/ment$/, ''],        [/ness$/, ''],       [/ity$/, ''],
    [/ing$/, ''],         [/ies$/, 'y'],       [/ive$/, ''],
    [/able$/, ''],        [/ible$/, ''],       [/ally$/, ''],
    [/tion$/, 't'],       [/ed$/, ''],         [/ly$/, ''],
    [/er$/, ''],          [/es$/, ''],         [/s$/, '']
  ];

  for (const [pattern, replacement] of rules) {
    if (pattern.test(word)) {
      const result = word.replace(pattern, replacement);
      if (result.length >= 3) return result;
    }
  }

  return word;
}

function tokenize(text) {
  return text
    .toLowerCase()
    // Split camelCase and snake_case
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/_/g, ' ')
    // Strip everything except alphanumeric and whitespace
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(t => t.length >= 2 && !STOP_WORDS.has(t));
}

function analyze(text) {
  return tokenize(text).map(stem);
}

// Build a frequency map from tokens
function termFrequencies(tokens) {
  const freqs = {};
  for (const t of tokens) {
    freqs[t] = (freqs[t] || 0) + 1;
  }
  return freqs;
}

module.exports = { tokenize, stem, analyze, termFrequencies, STOP_WORDS };
