## lib/crawler.js — File Discovery

```javascript
const fs = require('fs');
const path = require('path');

const DEFAULT_EXTENSIONS = new Set([
  '.txt','.md','.js','.mjs','.cjs','.ts','.tsx','.jsx',
  '.json','.html','.css','.scss','.py','.rb','.go','.rs',
  '.java','.c','.h','.cpp','.hpp','.cs','.php','.sh',
  '.yml','.yaml','.toml','.xml','.sql','.r','.swift','.kt'
]);

const IGNORE_DIRS = new Set([
  'node_modules','.git','.svn','.hg','dist','build','out',
  '__pycache__','.next','.nuxt','vendor','target','.venv',
  'coverage','.cache','.idea','.vscode'
]);

const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2 MB

/**
 * Walk a directory tree and yield file paths matching criteria.
 * Returns { files, skipped, errors } for reporting.
 */
function crawl(rootDir, options = {}) {
  const extensions = options.extensions
    ? new Set(options.extensions.map(e => e.startsWith('.') ? e : `.${e}`))
    : DEFAULT_EXTENSIONS;

  const ignoreDirs = new Set([...IGNORE_DIRS, ...(options.ignore || [])]);
  const maxSize = options.maxSize || MAX_FILE_SIZE;

  const result = { files: [], skipped: 0, errors: 0 };

  function walk(dir, depth) {
    if (depth > 50) return; // safety limit

    let entries;
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      result.errors++;
      return;
    }

    for (const entry of entries) {
      const name = entry.name;
      if (name.startsWith('.') && name.length > 1) continue;

      const fullPath = path.join(dir, name);

      if (entry.isDirectory()) {
        if (!ignoreDirs.has(name)) walk(fullPath, depth + 1);
        continue;
      }

      if (!entry.isFile()) continue;

      const ext = path.extname(name).toLowerCase();
      if (!extensions.has(ext)) {
        result.skipped++;
        continue;
      }

      try {
        const stat = fs.statSync(fullPath);
        if (stat.size > maxSize || stat.size === 0) {
          result.skipped++;
          continue;
        }
        result.files.push({
          absolute: fullPath,
          relative: path.relative(rootDir, fullPath),
          size: stat.size,
          modified: stat.mtimeMs
        });
      } catch {
        result.errors++;
      }
    }
  }

  walk(rootDir, 0);
  return result;
}

module.exports = { crawl, DEFAULT_EXTENSIONS, IGNORE_DIRS };
