## lib/index.js — Inverted Index with TF-IDF

```javascript
const fs = require('fs');
const path = require('path');
const { analyze, termFrequencies } = require('./tokenizer');

const INDEX_FILENAME = '.searchindex.json';
const INDEX_VERSION = 2;

class SearchIndex {
  constructor() {
    // docId → metadata
    this.docs = {};
    // term → { docId: rawFrequency, ... }
    this.postings = {};
    // total document count (stored separately for fast access)
    this.totalDocs = 0;
  }

  // ─── Indexing ────────────────────────────────────────────

  addDocument(docId, content, meta = {}) {
    // If re-indexing, remove old version first
    if (this.docs[docId]) this.removeDocument(docId);

    const tokens = analyze(content);
    const freqs = termFrequencies(tokens);

    this.docs[docId] = {
      ...meta,
      termCount: tokens.length,
      uniqueTerms: Object.keys(freqs).length,
      indexedAt: Date.now()
    };

    for (const [term, freq] of Object.entries(freqs)) {
      if (!this.postings[term]) this.postings[term] = {};
      this.postings[term][docId] = freq;
    }

    this.totalDocs++;
  }

  removeDocument(docId) {
    if (!this.docs[docId]) return false;

    for (const term of Object.keys(this.postings)) {
      if (this.postings[term][docId] !== undefined) {
        delete this.postings[term][docId];
        if (Object.keys(this.postings[term]).length === 0) {
          delete this.postings[term];
        }
      }
    }

    delete this.docs[docId];
    this.totalDocs--;
    return true;
  }

  // ─── Searching ───────────────────────────────────────────

  search(query, options = {}) {
    const limit = options.limit || 10;
    const queryTokens = analyze(query);

    if (queryTokens.length === 0) return [];

    const scores = {};
    const matchedTerms = {}; // docId → Set of matched query terms

    for (const term of queryTokens) {
      const posting = this.postings[term];
      if (!posting) continue;

      const df = Object.keys(posting).length;
      const idf = Math.log((this.totalDocs + 1) / (df + 1)) + 1; // smoothed IDF

      for (const [docId, rawTf] of Object.entries(posting)) {
        const doc = this.docs[docId];
        if (!doc) continue;

        // Log-normalized TF × IDF
        const tf = 1 + Math.log(rawTf);
        const lengthNorm = 1 / Math.sqrt(doc.termCount || 1);
        const score = tf * idf * lengthNorm;

        scores[docId] = (scores[docId] || 0) + score;

        if (!matchedTerms[docId]) matchedTerms[docId] = new Set();
        matchedTerms[docId].add(term);
      }
    }

    // Boost documents matching more distinct query terms
    for (const docId of Object.keys(scores)) {
      const coverage = matchedTerms[docId].size / queryTokens.length;
      scores[docId] *= (1 + coverage); // up to 2x boost for full match
    }

    return Object.entries(scores)
      .sort(([, a], [, b]) => b - a)
      .slice(0, limit)
      .map(([docId, score]) => ({
        docId,
        score: Math.round(score * 1000) / 1000,
        terms: [...matchedTerms[docId]],
        ...this.docs[docId]
      }));
  }

  // ─── Persistence ─────────────────────────────────────────

  save(dir) {
    const filePath = path.join(dir, INDEX_FILENAME);
    const data = {
      version: INDEX_VERSION,
      createdAt: new Date().toISOString(),
      totalDocs: this.totalDocs,
      totalTerms: Object.keys(this.postings).length,
      docs: this.docs,
      postings: this.postings
    };

    fs.writeFileSync(filePath, JSON.stringify(data));
    return filePath;
  }

  static load(dir) {
    const filePath = path.join(dir, INDEX_FILENAME);
    const index = new SearchIndex();

    if (!fs.existsSync(filePath)) return null;

    const raw = fs.readFileSync(filePath, 'utf-8');
    const data = JSON.parse(raw);

    if (data.version !== INDEX_VERSION) {
      throw new Error(`Index version mismatch: expected ${INDEX_VERSION}, got ${data.version}. Re-index.`);
    }

    index.docs = data.docs;
    index.postings = data.postings;
    index.totalDocs = data.totalDocs;
    return index;
  }

  static exists(dir) {
    return fs.existsSync(path.join(dir, INDEX_FILENAME));
  }

  static clear(dir) {
    const filePath = path.join(dir, INDEX_FILENAME);
    if (fs.existsSync(filePath)) {
      fs.unlinkSync(filePath);
      return true;
    }
    return false;
  }

  // ─── Stats ───────────────────────────────────────────────

  stats() {
    const terms = Object.keys(this.postings).length;
    const indexPath = null; // filled by caller if needed
    return {
      documents: this.totalDocs,
      uniqueTerms: terms,
      avgTermsPerDoc: this.totalDocs > 0
        ? Math.round(Object.values(this.docs).reduce((s, d) => s + d.termCount, 0) / this.totalDocs)
        : 0
    };
  }
}

module.exports = { SearchIndex, INDEX_FILENAME };
```

