function extractSnippet(content, terms, contextChars = 120) {
  const lower = content.toLowerCase();

  // Find the best window containing the most terms
  let bestPos = 0;
  let bestCount = 0;

  for (let i = 0; i < lower.length; i += 40) {
    const window = lower.slice(i, i + contextChars);
    let count = 0;
    for (const term of terms) {
      if (window.includes(term)) count++;
    }
    if (count > bestCount) {
      bestCount = count;
      bestPos = i;
    }
  }

  let start = Math.max(0, bestPos - 20);
  let end = Math.min(content.length, start + contextChars);

  // Snap to word boundaries
  if (start > 0) {
    const spaceIdx = content.indexOf(' ', start);
    if (spaceIdx !== -1 && spaceIdx < start + 20) start = spaceIdx + 1;
  }
  if (end < content.length) {
    const spaceIdx = content.lastIndexOf(' ', end);
    if (spaceIdx > end - 20) end = spaceIdx;
  }

  let snippet = content.slice(start, end).replace(/\s+/g, ' ').trim();
  if (start > 0) snippet = '...' + snippet;
  if (end < content.length) snippet = snippet + '...';

  return snippet;
}

