using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;

namespace FileWatcherSearchIndex
{
    public class SearchIndex
    {
        private readonly ConcurrentDictionary<string, HashSet<string>> _invertedIndex = new();
        private readonly ConcurrentDictionary<string, DateTime> _indexedFiles = new();
        private readonly ReaderWriterLockSlim _lock = new();

        public void IndexFile(string filePath)
        {
            if (!File.Exists(filePath))
                return;

            try
            {
                string content = File.ReadAllText(filePath);
                string[] words = Tokenize(content);
                string normalizedPath = Path.GetFullPath(filePath);

                RemoveFile(normalizedPath);

                _lock.EnterWriteLock();
                try
                {
                    foreach (string word in words)
                    {
                        _invertedIndex.AddOrUpdate(
                            word,
                            _ => new HashSet<string> { normalizedPath },
                            (_, set) => { lock (set) { set.Add(normalizedPath); } return set; }
                        );
                    }
                    _indexedFiles[normalizedPath] = DateTime.UtcNow;
                }
                finally
                {
                    _lock.ExitWriteLock();
                }

                Console.WriteLine($"  [Index] Indexed: {Path.GetFileName(filePath)} ({words.Length} tokens)");
            }
            catch (IOException ex)
            {
                Console.WriteLine($"  [Index] Error reading {filePath}: {ex.Message}");
            }
        }

        public void RemoveFile(string filePath)
        {
            string normalizedPath = Path.GetFullPath(filePath);

            _lock.EnterWriteLock();
            try
            {
                foreach (var kvp in _invertedIndex)
                {
                    lock (kvp.Value)
                    {
                        kvp.Value.Remove(normalizedPath);
                    }
                }
                _indexedFiles.TryRemove(normalizedPath, out _);
            }
            finally
            {
                _lock.ExitWriteLock();
            }
        }

        public List<string> Search(string query)
        {
            string[] queryTokens = Tokenize(query);
            if (queryTokens.Length == 0)
                return new List<string>();

            _lock.EnterReadLock();
            try
            {
                HashSet<string>? resultSet = null;

                foreach (string token in queryTokens)
                {
                    if (_invertedIndex.TryGetValue(token, out var files))
                    {
                        HashSet<string> copy;
                        lock (files) { copy = new HashSet<string>(files); }

                        resultSet = resultSet == null ? copy : new HashSet<string>(resultSet.Intersect(copy));
                    }
                    else
                    {
                        return new List<string>();
                    }
                }

                return resultSet?.ToList() ?? new List<string>();
            }
            finally
            {
                _lock.ExitReadLock();
            }
        }

        public int FileCount => _indexedFiles.Count;
        public int TermCount => _invertedIndex.Count(kvp => { lock (kvp.Value) { return kvp.Value.Count > 0; } });

        private static string[] Tokenize(string text)
        {
            return text
                .ToLowerInvariant()
                .Split(new[] { ' ', '\t', '\n', '\r', '.', ',', ';', ':', '!', '?', '(', ')', '[', ']', '{', '}', '"', '\'', '/', '\\', '-', '_', '=', '+', '<', '>', '&', '|', '#', '@', '*' },
                    StringSplitOptions.RemoveEmptyEntries)
                .Where(w => w.Length > 1)
                .Distinct()
                .ToArray();
        }
    }

