            Console.WriteLine($"[Watcher] Watching for changes...\n");
            _watcher.EnableRaisingEvents = true;
        }

        public void Stop()
        {
            _watcher.EnableRaisingEvents = false;
            foreach (var timer in _debounceTimers.Values)
                timer.Dispose();
            _debounceTimers.Clear();
        }

        private void OnChanged(object sender, FileSystemEventArgs e)
        {
            if (!IsWatchedExtension(e.FullPath)) return;

            Console.WriteLine($"[Event] {e.ChangeType}: {e.Name}");
            Debounce(e.FullPath, () => _index.IndexFile(e.FullPath));
        }

        private void OnDeleted(object sender, FileSystemEventArgs e)
        {
            if (!IsWatchedExtension(e.FullPath)) return;

            Console.WriteLine($"[Event] Deleted: {e.Name}");
            _index.RemoveFile(e.FullPath);
            Console.WriteLine($"  [Index] Removed: {e.Name}");
        }

        private void OnRenamed(object sender, RenamedEventArgs e)
        {
            Console.WriteLine($"[Event] Renamed: {e.OldName} -> {e.Name}");

            if (IsWatchedExtension(e.OldFullPath))
            {
                _index.RemoveFile(e.OldFullPath);
                Console.WriteLine($"  [Index] Removed old: {e.OldName}");
            }

            if (IsWatchedExtension(e.FullPath))
            {
                Debounce(e.FullPath, () => _index.IndexFile(e.FullPath));
            }
        }

        private void OnError(object sender, ErrorEventArgs e)
        {
            Console.WriteLine($"[Watcher Error] {e.GetException().Message}");
        }

        private void Debounce(string key, Action action)
        {
            if (_debounceTimers.TryRemove(key, out var existing))
                existing.Dispose();

            var timer = new Timer(_ =>
            {
                _debounceTimers.TryRemove(key, out _);
                action();
            }, null, _debounceInterval, Timeout.InfiniteTimeSpan);

            _debounceTimers[key] = timer;
        }

        private bool IsWatchedExtension(string path)
        {
            string ext = Path.GetExtension(path).ToLowerInvariant();
            return _extensions.Contains(ext);
        }

        public void Dispose()
        {
            Stop();
            _watcher.Dispose();
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            string watchPath = args.Length > 0 ? args[0] : Path.Combine(Path.GetTempPath(), "search-index-demo");
            Directory.CreateDirectory(watchPath);

            Console.WriteLine("=== File Watcher Search Index ===");
            Console.WriteLine($"Watching: {watchPath}\n");

            var index = new SearchIndex();

            using var watcher = new DebouncedFileWatcher(watchPath, index);
            watcher.Start();

            Console.WriteLine("Commands:");
            Console.WriteLine("  search <query>   - Search indexed files");
            Console.WriteLine("  stats            - Show index statistics");
            Console.WriteLine("  demo             - Create sample files for testing");
            Console.WriteLine("  quit             - Exit\n");

            while (true)
            {
                Console.Write("> ");
                string? input = Console.ReadLine()?.Trim();
                if (string.IsNullOrEmpty(input)) continue;

                if (input.Equals("quit", StringComparison.OrdinalIgnoreCase))
                    break;

                if (input.Equals("stats", StringComparison.OrdinalIgnoreCase))
                {
                    Console.WriteLine($"  Files indexed: {index.FileCount}");
                    Console.WriteLine($"  Unique terms: {index.TermCount}");
                    continue;
                }

                if (input.Equals("demo", StringComparison.OrdinalIgnoreCase))
                {
                    CreateDemoFiles(watchPath);
                    continue;
                }

                if (input.StartsWith("search ", StringComparison.OrdinalIgnoreCase))
                {
                    string query = input.Substring(7).Trim();
                    var results = index.Search(query);

                    if (results.Count == 0)
                    {
                        Console.WriteLine("  No results found.");
                    }
                    else
                    {
                        Console.WriteLine($"  Found {results.Count} file(s):");
                        foreach (string file in results)
                            Console.WriteLine($"    - {Path.GetFileName(file)}");
                    }
                    continue;
                }

                Console.WriteLine("  Unknown command. Try: search, stats, demo, quit");
            }

            Console.WriteLine("Shutting down...");
        }

        static void CreateDemoFiles(string path)
        {
            var files = new Dictionary<string, string>
            {
                ["readme.txt"] = "Welcome to the search index demo project. This file contains basic information about the system.",
                ["notes.md"] = "# Development Notes\nThe search index uses an inverted index data structure for fast lookups.",
                ["config.json"] = "{ \"name\": \"search-indexer\", \"version\": \"1.0\", \"debug\": true }",
                ["todo.txt"] = "TODO: Add support for fuzzy search and ranking. Improve the tokenizer for better results.",
                ["example.cs"] = "using System;\nnamespace Example\n{\n    class Program\n    {\n        static void Main() => Console.WriteLine(\"Hello search world\");\n    }\n}"
            };

            foreach (var (name, content) in files)
            {
                File.WriteAllText(Path.Combine(path, name), content);
            }

            Console.WriteLine($"  Created {files.Count} demo files in {path}");
            Console.WriteLine("  Wait a moment then try: search index");
        }
    }
}
```

## How it works

**SearchIndex** — an inverted index mapping each token (word) to the set of files containing it:
- `IndexFile` reads a file, tokenizes its content, and stores word→file mappings
- `RemoveFile` clears a file from all postings
- `Search` intersects posting lists for multi-word AND queries

**DebouncedFileWatcher** — wraps `FileSystemWatcher` with practical improvements:
- **Debouncing** — `FileSystemWatcher` often fires duplicate events; a 300ms timer coalesces them
- **Extension filtering** — only indexes text-based files (`.txt`, `.cs`, `.md`, etc.)
- **Initial scan** — indexes all existing files on startup before watching for changes
- Handles `Created`, `Changed`, `Deleted`, and `Renamed` events

**Usage flow:**
1. Run it (optionally pass a directory path as an argument)
2. Type `demo` to create sample files
3. Type `search <words>` to query the index
4. Edit/add/delete files in the watched directory and see live re-indexing

