export class PipelineExecutionError extends Error {
  public readonly stageName: string;
  public readonly cause?: Error;
  public readonly isRetryable: boolean;

  constructor(
    stageName: string,
    message: string,
    options?: { cause?: Error; isRetryable?: boolean },
  ) {
    super(`[${stageName}] ${message}`);
    this.name = "PipelineExecutionError";
    this.stageName = stageName;
    this.cause = options?.cause;
    this.isRetryable = options?.isRetryable ?? false;

    // Maintain correct prototype chain
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class ValidationError extends PipelineExecutionError {
  public readonly issues: readonly string[];

  constructor(stageName: string, issues: readonly string[]) {
    super(stageName, `Validation failed: ${issues.join("; ")}`, {
      isRetryable: false,
    });
    this.name = "ValidationError";
    this.issues = issues;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

