// src/observability/Metrics.ts

import type { IMetricsCollector } from "../types/pipeline.types.js";

interface MetricEntry {
  readonly name: string;
  readonly type: "counter" | "gauge" | "histogram";
  value: number;
  readonly tags: Record<string, string>;
  readonly samples: number[];
}

/**
 * In-memory metrics collector.
 * Replace with Prometheus / StatsD / Datadog client in production.
 */
export class InMemoryMetrics implements IMetricsCollector {
  private readonly store = new Map<string, MetricEntry>();

  private key(name: string, tags?: Record<string, string>): string {
    const tagStr = tags
      ? Object.entries(tags)
          .sort(([a], [b]) => a.localeCompare(b))
          .map(([k, v]) => `${k}:${v}`)
          .join(",")
      : "";
    return `${name}|${tagStr}`;
  }

  increment(metric: string, value = 1, tags?: Record<string, string>): void {
    const k = this.key(metric, tags);
    const existing = this.store.get(k);
    if (existing) {
      existing.value += value;
    } else {
      this.store.set(k, {
        name: metric,
        type: "counter",
        value,
        tags: tags ?? {},
        samples: [],
      });
    }
  }

  gauge(metric: string, value: number, tags?: Record<string, string>): void {
    const k = this.key(metric, tags);
    this.store.set(k, {
      name: metric,
      type: "gauge",
      value,
      tags: tags ?? {},
      samples: [],
    });
  }

  histogram(metric: string, value: number, tags?: Record<string, string>): void {
    const k = this.key(metric, tags);
    const existing = this.store.get(k);
    if (existing) {
      existing.samples.push(value);
      existing.value = value;
    } else {
      this.store.set(k, {
        name: metric,
        type: "histogram",
        value,
        tags: tags ?? {},
        samples: [value],
      });
    }
  }

  timing(metric: string, durationMs: number, tags?: Record<string, string>): void {
    this.histogram(metric, durationMs, tags);
  }

  /** Return a snapshot for inspection / export */
  snapshot(): ReadonlyMap<string, Readonly<MetricEntry>> {
    return new Map(this.store);
  }

  reset(): void {
    this.store.clear();
  }
}
