// src/utils/retry.ts

import type { ILogger } from "../types/pipeline.types.js";

export interface RetryOptions {
  readonly maxAttempts: number;
  readonly baseDelayMs: number;
  readonly maxDelayMs?: number;
  readonly backoffMultiplier?: number;
  readonly logger?: ILogger;
}

/**
 * Retries `fn` with exponential backoff.
 * Resolves with the successful result or throws the final error.
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  options: RetryOptions,
): Promise<T> {
  const {
    maxAttempts,
    baseDelayMs,
    maxDelayMs = 30_000,
    backoffMultiplier = 2,
    logger,
  } = options;

  let lastError: Error | undefined;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err instanceof Error ? err : new Error(String(err));

      if (attempt === maxAttempts) break;

      const jitter = Math.random() * 0.3 + 0.85; // 0.85–1.15
      const delay = Math.min(
        baseDelayMs * backoffMultiplier ** (attempt - 1) * jitter,
        maxDelayMs,
      );

      logger?.warn(`Attempt ${attempt}/${maxAttempts} failed, retrying in ${Math.round(delay)}ms`, {
        error: lastError.message,
      });

      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }

  throw lastError;
}
