### CsvRecord.java — Represents a Single Row

```java
package migration;

import java.util.*;

/**
 * Represents a single parsed CSV row with both index-based
 * and header-based field access.
 */
public class CsvRecord {

    private final int lineNumber;
    private final String[] headers;
    private final String[] values;
    private final Map<String, Integer> headerIndex;

    public CsvRecord(int lineNumber, String[] headers, String[] values) {
        this.lineNumber = lineNumber;
        this.headers = headers;
        this.values = values;

        // Build lookup map for header-based access
        this.headerIndex = new HashMap<>();
        if (headers != null) {
            for (int i = 0; i < headers.length; i++) {
                headerIndex.put(headers[i].toLowerCase().trim(), i);
            }
        }
    }

    /** Get field by column name (case-insensitive). */
    public String get(String header) {
        Integer idx = headerIndex.get(header.toLowerCase().trim());
        if (idx == null || idx >= values.length) {
            return null;
        }
        return values[idx].trim();
    }

    /** Get field by column index. */
    public String get(int index) {
        if (index < 0 || index >= values.length) {
            return null;
        }
        return values[index].trim();
    }

    /** Get field as integer, or default if missing/invalid. */
    public int getInt(String header, int defaultValue) {
        String val = get(header);
        if (val == null || val.isEmpty()) return defaultValue;
        try {
            return Integer.parseInt(val);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    /** Get field as double, or default if missing/invalid. */
    public double getDouble(String header, double defaultValue) {
        String val = get(header);
        if (val == null || val.isEmpty()) return defaultValue;
        try {
            return Double.parseDouble(val);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    /** Check if a field is present and non-empty. */
    public boolean hasValue(String header) {
        String val = get(header);
        return val != null && !val.isEmpty();
    }

    public int getLineNumber()  { return lineNumber; }
    public String[] getHeaders() { return headers; }
    public String[] getValues()  { return values; }
    public int fieldCount()      { return values.length; }

    @Override
    public String toString() {
        StringJoiner sj = new StringJoiner(", ", "CsvRecord[line=" + lineNumber + "]{", "}");
        for (int i = 0; i < values.length; i++) {
            String label = (headers != null && i < headers.length) ? headers[i] : String.valueOf(i);
            sj.add(label + "=" + values[i]);
        }
        return sj.toString();
    }
