### CsvReader.java — The Parsing Engine

```java
package migration;

import java.io.*;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.function.Consumer;
import java.util.stream.*;

/**
 * Streaming CSV reader that handles:
 *   - Quoted fields (including embedded commas and newlines)
 *   - Escaped quotes ("")
 *   - Configurable delimiter and charset
 *   - Optional header row
 */
public class CsvReader implements Closeable {

    private final BufferedReader reader;
    private final char delimiter;
    private final boolean hasHeader;
    private String[] headers;
    private int currentLine;

    // ── Builder for configuration ──────────────────────────────

    public static class Builder {
        private char delimiter = ',';
        private Charset charset = StandardCharsets.UTF_8;
        private boolean hasHeader = true;

        public Builder delimiter(char d)   { this.delimiter = d; return this; }
        public Builder charset(Charset c)  { this.charset = c; return this; }
        public Builder hasHeader(boolean h) { this.hasHeader = h; return this; }

        public CsvReader open(Path path) throws IOException {
            BufferedReader br = Files.newBufferedReader(path, charset);
            return new CsvReader(br, delimiter, hasHeader);
        }

        public CsvReader open(InputStream is) {
            BufferedReader br = new BufferedReader(new InputStreamReader(is, charset));
            return new CsvReader(br, delimiter, hasHeader);
        }

        public CsvReader open(String csvContent) {
            BufferedReader br = new BufferedReader(new StringReader(csvContent));
            return new CsvReader(br, delimiter, hasHeader);
        }
    }

    public static Builder builder() {
        return new Builder();
    }

    // ── Constructor ────────────────────────────────────────────

    private CsvReader(BufferedReader reader, char delimiter, boolean hasHeader) {
        this.reader = reader;
        this.delimiter = delimiter;
        this.hasHeader = hasHeader;
        this.currentLine = 0;

        if (hasHeader) {
            try {
                String headerLine = reader.readLine();
                currentLine++;
                this.headers = (headerLine != null) ? parseLine(headerLine) : new String[0];
            } catch (IOException e) {
                throw new UncheckedIOException("Failed to read CSV header", e);
            }
        }
    }

    // ── Public API ─────────────────────────────────────────────

    /** Read the next record, or null if EOF. */
    public CsvRecord next() throws IOException {
        String line = readFullLine();
        if (line == null) return null;
        String[] fields = parseLine(line);
        return new CsvRecord(currentLine, headers, fields);
    }

    /** Read all remaining records into a list. */
    public List<CsvRecord> readAll() throws IOException {
        List<CsvRecord> records = new ArrayList<>();
        CsvRecord rec;
        while ((rec = next()) != null) {
            records.add(rec);
        }
        return records;
    }

    /** Stream records lazily (auto-closes on terminal operation). */
    public Stream<CsvRecord> stream() {
        Iterator<CsvRecord> iterator = new Iterator<>() {
            private CsvRecord upcoming = advance();

            private CsvRecord advance() {
                try { return next(); }
                catch (IOException e) { throw new UncheckedIOException(e); }
            }

            @Override public boolean hasNext()  { return upcoming != null; }
            @Override public CsvRecord next()    {
                CsvRecord current = upcoming;
                upcoming = advance();
                return current;
            }
        };

        return StreamSupport.stream(
            Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), false
        ).onClose(() -> { try { close(); } catch (IOException ignored) {} });
    }

    /** Process each record with a consumer (auto-closes). */
    public void forEach(Consumer<CsvRecord> action) throws IOException {
        try {
            CsvRecord rec;
            while ((rec = next()) != null) {
                action.accept(rec);
            }
        } finally {
            close();
        }
    }

    public String[] getHeaders() { return headers; }

    @Override
    public void close() throws IOException {
        reader.close();
    }

    // ── CSV Parsing Logic ──────────────────────────────────────

    /**
     * Reads a complete logical line, joining physical lines
     * when a quoted field spans multiple lines.
     */
    private String readFullLine() throws IOException {
        String line = reader.readLine();
        if (line == null) return null;
        currentLine++;

        // If the line has an odd number of unescaped quotes,
        // the record spans multiple physical lines
        while (hasUnclosedQuote(line)) {
            String continuation = reader.readLine();
            currentLine++;
            if (continuation == null) break;   // EOF mid-record
            line = line + "\n" + continuation;
        }
        return line;
    }

    private boolean hasUnclosedQuote(String line) {
        boolean inQuotes = false;
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c == '"') {
                // Look ahead for escaped quote ("")
                if (inQuotes && i + 1 < line.length() && line.charAt(i + 1) == '"') {
                    i++; // skip escaped quote
                } else {
                    inQuotes = !inQuotes;
                }
            }
        }
        return inQuotes;
    }

    /** Parse a logical CSV line into individual field values. */
    private String[] parseLine(String line) {
        List<String> fields = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean inQuotes = false;

        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);

            if (inQuotes) {
                if (c == '"') {
                    // Escaped quote "" → literal "
                    if (i + 1 < line.length() && line.charAt(i + 1) == '"') {
                        current.append('"');
                        i++;
                    } else {
                        inQuotes = false;  // closing quote
                    }
                } else {
                    current.append(c);
                }
            } else {
                if (c == '"') {
                    inQuotes = true;       // opening quote
                } else if (c == delimiter) {
                    fields.add(current.toString());
                    current.setLength(0);  // reset for next field
                } else {
                    current.append(c);
                }
            }
        }
        fields.add(current.toString()); // last field

        return fields.toArray(String[]::new);
    }
}
