/**
 * Collects statistics and errors during migration.
 * Thread-safe for potential parallel use.
 */
public class MigrationResult {

    private int totalRead;
    private int successCount;
    private int skipCount;
    private int errorCount;
    private final List<ValidationError> validationErrors = Collections.synchronizedList(new ArrayList<>());
    private final List<String> processingErrors = Collections.synchronizedList(new ArrayList<>());
    private Instant startTime;
    private Instant endTime;

    public void markStart()  { this.startTime = Instant.now(); }
    public void markEnd()    { this.endTime = Instant.now(); }

    public synchronized void incrementRead()    { totalRead++; }
    public synchronized void incrementSuccess() { successCount++; }
    public synchronized void incrementSkip()    { skipCount++; }
    public synchronized void incrementError()   { errorCount++; }

    public void addValidationErrors(List<ValidationError> errors) {
        validationErrors.addAll(errors);
    }

    public void addProcessingError(int line, String message) {
        processingErrors.add(String.format("Line %d: %s", line, message));
    }

    public Duration getDuration() {
        if (startTime == null || endTime == null) return Duration.ZERO;
        return Duration.between(startTime, endTime);
    }

    // ── Report Generation ──────────────────────────────────────

    public String generateReport() {
        StringBuilder sb = new StringBuilder();
        sb.append("\n╔══════════════════════════════════════╗\n");
        sb.append("║       MIGRATION REPORT               ║\n");
        sb.append("╠══════════════════════════════════════╣\n");
        sb.append(String.format("║  Total read:    %8d            ║\n", totalRead));
        sb.append(String.format("║  Successful:    %8d            ║\n", successCount));
        sb.append(String.format("║  Skipped:       %8d            ║\n", skipCount));
        sb.append(String.format("║  Errors:        %8d            ║\n", errorCount));
        sb.append(String.format("║  Duration:      %8.2f sec        ║\n", getDuration().toMillis() / 1000.0));
        sb.append("╚══════════════════════════════════════╝\n");

        if (!validationErrors.isEmpty()) {
            sb.append("\n── Validation Errors (" + validationErrors.size() + ") ──\n");
            validationErrors.stream().limit(20).forEach(e -> sb.append("  • ").append(e).append("\n"));
            if (validationErrors.size() > 20) {
                sb.append("  ... and ").append(validationErrors.size() - 20).append(" more\n");
            }
        }

        if (!processingErrors.isEmpty()) {
            sb.append("\n── Processing Errors (" + processingErrors.size() + ") ──\n");
            processingErrors.stream().limit(10).forEach(e -> sb.append("  • ").append(e).append("\n"));
        }

        return sb.toString();
    }

    // Getters
    public int getTotalRead()    { return totalRead; }
    public int getSuccessCount() { return successCount; }
    public int getSkipCount()    { return skipCount; }
    public int getErrorCount()   { return errorCount; }
    public List<ValidationError> getValidationErrors() { return validationErrors; }
}
