export enum LogLevel {
  Debug = 0,
  Info = 1,
  Warn = 2,
  Error = 3,
  Silent = 4,
}

export interface LogEntry {
  level: LogLevel;
  message: string;
  timestamp: Date;
  context?: Record<string, unknown>;
}

export interface ILogger {
  debug(message: string, context?: Record<string, unknown>): void;
  info(message: string, context?: Record<string, unknown>): void;
  warn(message: string, context?: Record<string, unknown>): void;
  error(message: string, context?: Record<string, unknown>): void;
}

export class Logger implements ILogger {
  private level: LogLevel;
  private logs: LogEntry[] = [];

  constructor(level: LogLevel = LogLevel.Info) {
    this.level = level;
  }

  debug(message: string, context?: Record<string, unknown>): void {
    this.log(LogLevel.Debug, message, context);
  }

  info(message: string, context?: Record<string, unknown>): void {
    this.log(LogLevel.Info, message, context);
  }

  warn(message: string, context?: Record<string, unknown>): void {
    this.log(LogLevel.Warn, message, context);
  }

  error(message: string, context?: Record<string, unknown>): void {
    this.log(LogLevel.Error, message, context);
  }

  getLogs(): ReadonlyArray<LogEntry> {
    return [...this.logs];
  }

  clear(): void {
    this.logs = [];
  }

  private log(
    level: LogLevel,
    message: string,
    context?: Record<string, unknown>
  ): void {
    const entry: LogEntry = { level, message, timestamp: new Date(), context };
    this.logs.push(entry);

    if (level < this.level) return;

    const prefix = `[${LogLevel[level].toUpperCase()}]`;
    const ts = entry.timestamp.toISOString();
    const msg = `${ts} ${prefix} ${message}`;

    switch (level) {
      case LogLevel.Debug:
        console.debug(msg, context ?? "");
        break;
      case LogLevel.Info:
        console.info(msg, context ?? "");
        break;
      case LogLevel.Warn:
        console.warn(msg, context ?? "");
        break;
      case LogLevel.Error:
        console.error(msg, context ?? "");
        break;
    }
  }
}
