```ts
import * as crypto from "node:crypto";
import * as fs from "node:fs";
import { HashAlgorithm } from "./types";
import { HashError } from "./errors";

const STREAM_HIGH_WATER_MARK = 64 * 1024; // 64KB chunks

export class FileHasher {
  private readonly algorithm: HashAlgorithm;
  private readonly cache: Map<string, { hash: string; mtimeMs: number }> =
    new Map();

  constructor(algorithm: HashAlgorithm = "sha256") {
    this.algorithm = algorithm;
  }

  /**
   * Compute hash of a file using streaming for memory efficiency.
   * Caches results based on path + mtime.
   */
  async hashFile(filePath: string): Promise<string> {
    try {
      const stat = await fs.promises.stat(filePath);

      const cached = this.cache.get(filePath);
      if (cached && cached.mtimeMs === stat.mtimeMs) {
        return cached.hash;
      }

      const hash = await this.computeStreamHash(filePath);

      this.cache.set(filePath, { hash, mtimeMs: stat.mtimeMs });
      return hash;
    } catch (err) {
      throw new HashError(filePath, err instanceof Error ? err : undefined);
    }
  }

  /**
   * Compute hash of a string or buffer directly.
   */
  hashContent(content: string | Buffer): string {
    return crypto.createHash(this.algorithm).update(content).digest("hex");
  }

  /**
   * Compare two files by hash without loading both fully in memory.
   */
  async areFilesEqual(pathA: string, pathB: string): Promise<boolean> {
    const [hashA, hashB] = await Promise.all([
      this.hashFile(pathA),
      this.hashFile(pathB),
    ]);
    return hashA === hashB;
  }

  clearCache(): void {
    this.cache.clear();
  }

  get cacheSize(): number {
    return this.cache.size;
  }

  private computeStreamHash(filePath: string): Promise<string> {
    return new Promise((resolve, reject) => {
      const hash = crypto.createHash(this.algorithm);
      const stream = fs.createReadStream(filePath, {
        highWaterMark: STREAM_HIGH_WATER_MARK,
      });

      stream.on("data", (chunk: Buffer) => hash.update(chunk));
      stream.on("end", () => resolve(hash.digest("hex")));
      stream.on("error", (err) => reject(err));
    });
  }
}
