import * as fs from "node:fs";
import * as path from "node:path";
import { FileEntry } from "./types";
import { ScanError } from "./errors";
import { FileHasher } from "./file-hasher";
import { ILogger } from "./logger";

export interface ScanOptions {
  ignorePatterns: string[];
  followSymlinks: boolean;
  computeHashes: boolean;
}

const DEFAULT_SCAN_OPTIONS: ScanOptions = {
  ignorePatterns: [],
  followSymlinks: false,
  computeHashes: true,
};

export class FileScanner {
  private readonly hasher: FileHasher;
  private readonly logger: ILogger;

  constructor(hasher: FileHasher, logger: ILogger) {
    this.hasher = hasher;
    this.logger = logger;
  }

  /**
   * Recursively scan a directory and return a map of relative path → FileEntry.
   */
  async scan(
    baseDir: string,
    options: Partial<ScanOptions> = {}
  ): Promise<Map<string, FileEntry>> {
    const opts = { ...DEFAULT_SCAN_OPTIONS, ...options };
    const entries = new Map<string, FileEntry>();

    try {
      await fs.promises.access(baseDir, fs.constants.R_OK);
    } catch {
      throw new ScanError(baseDir, new Error("Directory not accessible"));
    }

    await this.scanRecursive(baseDir, baseDir, entries, opts);

    this.logger.info(`Scanned ${entries.size} entries in ${baseDir}`);
    return entries;
  }

  private async scanRecursive(
    baseDir: string,
    currentDir: string,
    entries: Map<string, FileEntry>,
    options: ScanOptions
  ): Promise<void> {
    let dirEntries: fs.Dirent[];

    try {
      dirEntries = await fs.promises.readdir(currentDir, {
        withFileTypes: true,
      });
    } catch (err) {
      throw new ScanError(
        currentDir,
        err instanceof Error ? err : undefined
      );
    }

    for (const dirent of dirEntries) {
      const fullPath = path.join(currentDir, dirent.name);
      const relativePath = path.relative(baseDir, fullPath);

      if (this.shouldIgnore(relativePath, dirent.name, options.ignorePatterns)) {
        this.logger.debug(`Ignoring: ${relativePath}`);
        continue;
      }

      try {
        const stat = options.followSymlinks
          ? await fs.promises.stat(fullPath)
          : await fs.promises.lstat(fullPath);

        if (stat.isSymbolicLink() && !options.followSymlinks) {
          this.logger.debug(`Skipping symlink: ${relativePath}`);
          continue;
        }

        if (stat.isDirectory()) {
          const dirEntry: FileEntry = {
            relativePath: this.normalizePath(relativePath),
            size: 0,
            hash: "",
            modifiedTimeMs: stat.mtimeMs,
            isDirectory: true,
            permissions: stat.mode,
          };

          entries.set(dirEntry.relativePath, dirEntry);
          await this.scanRecursive(baseDir, fullPath, entries, options);
        } else if (stat.isFile()) {
          const hash = options.computeHashes
            ? await this.hasher.hashFile(fullPath)
            : "";

          const fileEntry: FileEntry = {
            relativePath: this.normalizePath(relativePath),
            size: stat.size,
            hash,
            modifiedTimeMs: stat.mtimeMs,
            isDirectory: false,
            permissions: stat.mode,
          };

          entries.set(fileEntry.relativePath, fileEntry);
        }
      } catch (err) {
        this.logger.warn(`Failed to process: ${relativePath}`, {
          error: String(err),
        });
      }
    }
  }

  private shouldIgnore(
    relativePath: string,
    name: string,
    patterns: string[]
  ): boolean {
    const normalizedPath = this.normalizePath(relativePath);

    for (const pattern of patterns) {
      // Direct name match
      if (name === pattern) return true;

      // Simple glob: *.ext
      if (pattern.startsWith("*.")) {
        const ext = pattern.slice(1);
        if (name.endsWith(ext)) return true;
      }

      // Path prefix
      if (
        normalizedPath.startsWith(pattern + "/") ||
        normalizedPath === pattern
      ) {
        return true;
      }

      // Contains pattern
      if (normalizedPath.includes("/" + pattern + "/")) return true;
    }

    return false;
  }

  private normalizePath(p: string): string {
    return p.split(path.sep).join("/");
  }
}
