## `lib/engine.js` — Core Moderation Engine

```javascript
const EVASION_MAP = {
  '@': 'a', '4': 'a', '^': 'a',
  '8': 'b',
  '3': 'e',
  '1': 'i', '!': 'i', '|': 'i',
  '0': 'o',
  '$': 's', '5': 's',
  '7': 't', '+': 't',
  'v': 'u',
};

class ModerationEngine {
  constructor(config = {}) {
    this.config = {
      bannedWords: [],
      bannedPatterns: [],
      linkWhitelist: [],
      maxCapsRatio: 0.7,
      maxRepeatChars: 4,
      minLengthForCapsCheck: 8,
      thresholds: { flag: 2, warn: 4, mute: 7, ban: 10 },
      ...config,
    };

    // Pre-compile regex patterns from config
    this.compiledPatterns = this.config.bannedPatterns.map((p) => ({
      pattern: new RegExp(p.regex, p.flags || 'gi'),
      severity: p.severity || 5,
      label: p.label || 'custom_pattern',
    }));
  }

  // ── Main Analysis ─────────────────────────────────────────────

  analyze(text) {
    const violations = [
      ...this.#checkBannedWords(text),
      ...this.#checkPatterns(text),
      ...this.#checkCaps(text),
      ...this.#checkRepeatedChars(text),
      ...this.#checkLinks(text),
      ...this.#checkFlooding(text),
    ];

    const score = violations.reduce((sum, v) => sum + v.severity, 0);
    const { thresholds } = this.config;

    let action = 'pass';
    if (score >= thresholds.ban) action = 'ban';
    else if (score >= thresholds.mute) action = 'mute';
    else if (score >= thresholds.warn) action = 'warn';
    else if (score >= thresholds.flag) action = 'flag';

    return {
      text,
      clean: violations.length === 0,
      violations,
      score,
      action,
      timestamp: new Date().toISOString(),
    };
  }

  // Returns the message with banned words replaced
  censor(text, char = '*') {
    let output = text;
    for (const entry of this.config.bannedWords) {
      const word = typeof entry === 'string' ? entry : entry.word;
      const re = new RegExp(`\\b${this.#escRe(word)}\\b`, 'gi');
      output = output.replace(re, char.repeat(word.length));
    }
    return output;
  }

  // ── Filter Checks (private) ──────────────────────────────────

  #checkBannedWords(text) {
    const violations = [];
    const normalized = this.#normalizeEvasion(text.toLowerCase());

    for (const entry of this.config.bannedWords) {
      const word = typeof entry === 'string' ? entry : entry.word;
      const severity = typeof entry === 'string' ? 5 : entry.severity ?? 5;
      const category = typeof entry === 'string' ? 'banned_word' : entry.category ?? 'banned_word';

      const re = new RegExp(`\\b${this.#escRe(word.toLowerCase())}\\b`, 'g');

      // Check both raw and evasion-normalized text
      const rawMatches = text.toLowerCase().match(re);
      const normMatches = normalized.match(re);
      const matchCount = Math.max(rawMatches?.length ?? 0, normMatches?.length ?? 0);

      if (matchCount > 0) {
        violations.push({
          type: category,
          matched: word,
          count: matchCount,
          severity,
          evasionDetected: !rawMatches && !!normMatches,
        });
      }
    }
    return violations;
  }

  #checkPatterns(text) {
    const violations = [];
    for (const { pattern, severity, label } of this.compiledPatterns) {
      pattern.lastIndex = 0;
      const matches = text.match(pattern);
      if (matches) {
        violations.push({
          type: 'pattern',
          label,
          matched: matches[0],
          count: matches.length,
          severity,
        });
      }
    }
    return violations;
  }

  #checkCaps(text) {
    if (text.length < this.config.minLengthForCapsCheck) return [];
    const letters = text.replace(/[^a-zA-Z]/g, '');
    if (letters.length === 0) return [];

    const ratio = letters.replace(/[^A-Z]/g, '').length / letters.length;
    if (ratio <= this.config.maxCapsRatio) return [];

    return [{
      type: 'spam',
      label: 'excessive_caps',
      detail: `${Math.round(ratio * 100)}% uppercase`,
      severity: 2,
    }];
  }

  #checkRepeatedChars(text) {
    const re = new RegExp(`(.)\\1{${this.config.maxRepeatChars},}`, 'g');
    const matches = text.match(re);
    if (!matches) return [];

    return [{
      type: 'spam',
      label: 'repeated_chars',
      matched: matches.map((m) => `"${m.slice(0, 8)}"`).join(', '),
      severity: 2,
    }];
  }

  #checkLinks(text) {
    const urlRe = /https?:\/\/[^\s]+|www\.[^\s]+/gi;
    const links = text.match(urlRe);
    if (!links) return [];

    const blocked = links.filter(
      (link) => !this.config.linkWhitelist.some(
        (domain) => link.toLowerCase().includes(domain.toLowerCase())
      )
    );

    if (blocked.length === 0) return [];
    return [{
      type: 'link',
      label: 'unwhitelisted_link',
      matched: blocked.join(', '),
      count: blocked.length,
      severity: 3,
    }];
  }

  #checkFlooding(text) {
    // Detect repeated words/phrases (e.g. "buy buy buy buy")
    const words = text.toLowerCase().split(/\s+/);
    if (words.length < 4) return [];

    const freq = {};
    for (const w of words) freq[w] = (freq[w] || 0) + 1;
    const maxFreq = Math.max(...Object.values(freq));
    const ratio = maxFreq / words.length;

    if (ratio < 0.6 || maxFreq < 4) return [];
    return [{
      type: 'spam',
      label: 'word_flooding',
      detail: `"${Object.entries(freq).sort((a, b) => b[1] - a[1])[0][0]}" repeated ${maxFreq}x`,
      severity: 3,
    }];
  }

  // ── Helpers ───────────────────────────────────────────────────

  #normalizeEvasion(text) {
    return [...text].map((c) => EVASION_MAP[c] || c).join('')
      .replace(/[.\-_]/g, '');   // strip separators like "f.u.c.k"
  }

  #escRe(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }
}

module.exports = { ModerationEngine };
```

