# Background Worker with Cancellation in Kotlin

## Core Implementation Using Coroutines

```kotlin
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*
import java.util.concurrent.atomic.AtomicBoolean

// --- Sealed class representing worker state ---
sealed class WorkerState<out T> {
    object Idle : WorkerState<Nothing>()
    data class Running(val progress: Int = 0) : WorkerState<Nothing>()
    data class Completed<T>(val result: T) : WorkerState<T>()
    data class Failed(val error: Throwable) : WorkerState<Nothing>()
    object Cancelled : WorkerState<Nothing>()
}

// --- The Background Worker ---
class BackgroundWorker<T>(
    private val dispatcher: CoroutineDispatcher = Dispatchers.Default
) {
    private var job: Job? = null
    private val _state = MutableStateFlow<WorkerState<T>>(WorkerState.Idle)
    val state: StateFlow<WorkerState<T>> = _state.asStateFlow()

    val isRunning: Boolean
        get() = job?.isActive == true

    /**
     * Starts the background work.
     * @param scope The parent CoroutineScope
     * @param block The suspending work to perform. Receives a progress reporter callback.
     */
    fun start(
        scope: CoroutineScope,
        block: suspend (reportProgress: (Int) -> Unit) -> T
    ) {
        // Prevent multiple concurrent executions
        if (isRunning) {
            throw IllegalStateException("Worker is already running. Cancel first.")
        }

        job = scope.launch(dispatcher) {
            try {
                _state.value = WorkerState.Running(0)

                val result = block { progress ->
                    // Check cancellation at each progress report
                    ensureActive()
                    _state.value = WorkerState.Running(progress)
                }

                _state.value = WorkerState.Completed(result)
            } catch (e: CancellationException) {
                _state.value = WorkerState.Cancelled
                throw e  // Re-throw to respect structured concurrency
            } catch (e: Throwable) {
                _state.value = WorkerState.Failed(e)
            }
        }
    }

    /**
     * Cancels the running work.
     */
    fun cancel() {
        job?.cancel(CancellationException("Worker cancelled by user"))
        job = null
    }

    /**
     * Suspends until the worker completes (or is cancelled/fails).
     */
    suspend fun await(): WorkerState<T> {
        job?.join()
        return _state.value
    }
}
```

## Practical Example: File Processor Simulation

```kotlin
// --- A simulated long-running task ---
class DataProcessor {

    /**
     * Simulates processing a large dataset in chunks.
     * Checks for cancellation between chunks.
     */
    suspend fun processData(
        items: List<String>,
        reportProgress: (Int) -> Unit
    ): String = coroutineScope {
        val results = mutableListOf<String>()

        for ((index, item) in items.withIndex()) {
            // This is the cooperative cancellation check
            ensureActive()

            // Simulate CPU-intensive work
            delay(500)
            results.add(item.uppercase())

            val progress = ((index + 1) * 100) / items.size
            reportProgress(progress)
        }

        "Processed ${results.size} items: ${results.joinToString()}"
    }
}
