## Main Demo

```kotlin
fun main() = runBlocking {
    println("=== Background Worker Demo ===\n")

    val worker = BackgroundWorker<String>()
    val processor = DataProcessor()
    val items = listOf("alpha", "beta", "gamma", "delta", "epsilon")

    // --- Observe state changes in a separate coroutine ---
    val observer = launch {
        worker.state.collect { state ->
            when (state) {
                is WorkerState.Idle      -> println("[Observer] Idle")
                is WorkerState.Running   -> println("[Observer] Progress: ${state.progress}%")
                is WorkerState.Completed -> println("[Observer] Done: ${state.result}")
                is WorkerState.Failed    -> println("[Observer] Error: ${state.error.message}")
                is WorkerState.Cancelled -> println("[Observer] Cancelled!")
            }
        }
    }

    // -------------------------------------------------------
    // Demo 1: Run to completion
    // -------------------------------------------------------
    println("--- Demo 1: Full run ---")
    worker.start(this) { reportProgress ->
        processor.processData(items, reportProgress)
    }
    worker.await()

    println()
    delay(100) // Let observer print

    // -------------------------------------------------------
    // Demo 2: Cancel mid-way
    // -------------------------------------------------------
    println("--- Demo 2: Cancel after 1.2s ---")
    worker.start(this) { reportProgress ->
        processor.processData(items, reportProgress)
    }

    delay(1200)          // Let it run for a bit
    worker.cancel()      // Then cancel
    worker.await()

    delay(100)

    // -------------------------------------------------------
    // Demo 3: Error handling
    // -------------------------------------------------------
    println("\n--- Demo 3: Error handling ---")
    worker.start(this) { reportProgress ->
        reportProgress(50)
        throw RuntimeException("Something went wrong!")
    }
    worker.await()

    delay(100)
    observer.cancel()    // Stop observing
}
