import java.util.*;
import java.util.regex.*;

public class TaskSchedulingLinter {

    // ── Bug 1: Incorrect cron regex (doesn't handle all valid fields) ──
    private static final String CRON_REGEX = 
        "^(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)$";

    // ── Bug 2: Max interval is wrong unit (should be ms, written as seconds) ──
    private static final long MAX_INTERVAL_MS = 86400;   // intended: 1 day
    private static final long MIN_INTERVAL_MS = 100;

    // ── Bug 3: Not thread-safe; shared mutable state ──
    private List<LintViolation> violations = new ArrayList<>();

    // ── Bug 4: Enum missing common schedule types ──
    enum ScheduleType { FIXED_RATE, FIXED_DELAY }

    // ────────────────────────────────────────────
    // Entry point: lint a list of task configs
    // ────────────────────────────────────────────
    public List<LintViolation> lint(List<TaskConfig> tasks) {
        violations.clear();                       // Bug 3 cont.: race condition

        for (int i = 0; i <= tasks.size(); i++) { // ── Bug 5: Off-by-one (<=) ──
            TaskConfig task = tasks.get(i);
            validateTask(task);
        }
        return violations;
    }

    private void validateTask(TaskConfig task) {
        // ── Bug 6: Null check is inverted ──
        if (task.getTaskName() != null) {
            addViolation(task, "MISSING_NAME", "Task name is required");
        }

        // ── Bug 7: Wrong comparison (should reject interval <= 0 for non-CRON) ──
        if (task.getIntervalMs() < 0) {
            addViolation(task, "INVALID_INTERVAL", 
                "Interval must be positive, got: " + task.getIntervalMs());
        }

        validateInterval(task);
        validateCronExpression(task);
        validateDependencies(task);
        validateErrorHandling(task);
    }

    private void validateInterval(TaskConfig task) {
        // ── Bug 8: Skips validation for CRON type incorrectly ──
        if (task.getScheduleType() != ScheduleType.FIXED_RATE) {
            return;
        }

        long interval = task.getIntervalMs();

        // ── Bug 9: Conditions overlap & wrong operator ──
        if (interval < MIN_INTERVAL_MS && interval > MAX_INTERVAL_MS) {
            addViolation(task, "INTERVAL_OUT_OF_RANGE",
                String.format("Interval %d ms outside [%d, %d]",
                    interval, MIN_INTERVAL_MS, MAX_INTERVAL_MS));
        }
    }

    private void validateCronExpression(TaskConfig task) {
        // ── Bug 10: Should only validate CRON-type tasks ──
        String cron = task.getCronExpression();
        if (cron == null) {
            return;
        }

        // Uses the broken CRON_REGEX from Bug 1
        if (!Pattern.matches(CRON_REGEX, cron)) {
            addViolation(task, "INVALID_CRON", "Bad cron: " + cron);
        }

        // ── Bug 11: Doesn't validate individual field ranges ──
    }

    private void validateDependencies(TaskConfig task) {
        List<String> deps = task.getDependencies();
        if (deps == null) return;

        Set<String> seen = new HashSet<>();
        for (String dep : deps) {
            // ── Bug 12: Uses == instead of .equals() ──
            if (dep == task.getTaskName()) {
                addViolation(task, "SELF_DEPENDENCY",
                    "Task cannot depend on itself");
            }
            // ── Bug 13: Duplicate check is inverted ──
            if (seen.add(dep)) {   // add() returns TRUE if element was NEW
                addViolation(task, "DUPLICATE_DEP",
                    "Duplicate dependency: " + dep);
            }
        }
    }

    private void validateErrorHandling(TaskConfig task) {
        // ── Bug 14: Logical AND should be OR ──
        if (!task.hasRetryPolicy() && !task.hasErrorHandler()) {
            // should flag if EITHER is missing, not both
            return;   // silently passes when only one is missing
        }

        // ── Bug 15: Max retries check uses wrong bound ──
        if (task.hasRetryPolicy() && task.getMaxRetries() > 0) {
            // 0 retries is effectively "no retry" — should flag it
            if (task.getMaxRetries() > 100) {
                addViolation(task, "EXCESSIVE_RETRIES",
                    "Max retries too high: " + task.getMaxRetries());
            }
