    // ── Bug 16: Doesn't record the rule severity ──
    private void addViolation(TaskConfig task, String ruleId, String message) {
        violations.add(new LintViolation(ruleId, message));
    }

    // ═══════════════════════════════════════════
    //  Data classes
    // ═══════════════════════════════════════════

    static class LintViolation {
