## Debugged Code (After) — with all 16 fixes

```java
import java.util.*;
import java.util.regex.*;

/**
 * Linter that validates {@link TaskConfig} objects for common
 * scheduling anti-patterns and misconfigurations.
 *
 * Fixed issues:
 *  #1  Cron regex now supports *, /, -, and ? wildcards
 *  #2  MAX_INTERVAL_MS is now actually in milliseconds
 *  #3  violations list is local → thread-safe
 *  #4  ScheduleType includes CRON
 *  #5  Off-by-one in loop bound
 *  #6  Null-name check was inverted
 *  #7  Zero-interval check now rejects <= 0
 *  #8  Interval validation applies to FIXED_RATE *and* FIXED_DELAY
 *  #9  Range check uses || not &&
 *  #10 Cron validation only runs for CRON-type tasks
 *  #11 Added per-field cron range validation
 *  #12 String comparison uses .equals()
 *  #13 Duplicate-detection logic corrected
 *  #14 Error-handling check uses || (flag if either is missing)
 *  #15 maxRetries <= 0 is now flagged
 *  #16 Severity is recorded on every violation
 */
public class TaskSchedulingLinter {

    // ─── FIX #1: Comprehensive cron regex ────────────────────────
    // Supports: numbers, *, /, -, ?,  for 5-field and 6-field cron
    private static final String CRON_FIELD = "[0-9*?/,\\-]+";
    private static final Pattern CRON_PATTERN = Pattern.compile(
        "^" + CRON_FIELD                        // second | minute
        + "(\\s+" + CRON_FIELD + "){4,5}$"      // 4-5 more fields
    );

    // Per-field numeric upper bounds:  sec  min  hr  dom  mon  dow
    private static final int[] CRON_MAX = { 59, 59, 23, 31, 12, 7 };

    // ─── FIX #2: 86_400_000 ms = 1 day ──────────────────────────
    private static final long MAX_INTERVAL_MS = 86_400_000L;
    private static final long MIN_INTERVAL_MS = 100L;

    // ─── FIX #4: Added CRON schedule type ────────────────────────
    enum ScheduleType { FIXED_RATE, FIXED_DELAY, CRON }

    // ─── FIX #3: No shared mutable state ─────────────────────────
    //  (violations list is now local to lint())

    // Severity map for each rule
    private static final Map<String, Severity> SEVERITY_MAP = new HashMap<>();
    static {
        SEVERITY_MAP.put("MISSING_NAME",       Severity.ERROR);
        SEVERITY_MAP.put("INVALID_INTERVAL",   Severity.ERROR);
        SEVERITY_MAP.put("INTERVAL_OUT_OF_RANGE", Severity.WARNING);
        SEVERITY_MAP.put("INVALID_CRON",       Severity.ERROR);
        SEVERITY_MAP.put("CRON_FIELD_RANGE",   Severity.ERROR);
        SEVERITY_MAP.put("SELF_DEPENDENCY",     Severity.ERROR);
        SEVERITY_MAP.put("DUPLICATE_DEP",       Severity.WARNING);
        SEVERITY_MAP.put("MISSING_RETRY",       Severity.WARNING);
        SEVERITY_MAP.put("MISSING_ERR_HANDLER", Severity.WARNING);
        SEVERITY_MAP.put("EXCESSIVE_RETRIES",   Severity.WARNING);
        SEVERITY_MAP.put("ZERO_RETRIES",        Severity.INFO);
    }

    // ═══════════════════════════════════════════════════════════════
    //  Public API
    // ═══════════════════════════════════════════════════════════════

    /**
     * Lint a list of task configurations and return all violations.
     * Thread-safe: each call uses its own violations list.
     */
    public List<LintViolation> lint(List<TaskConfig> tasks) {
        // ─── FIX #3: Local list → no race condition ──────────────
        List<LintViolation> violations = new ArrayList<>();

        if (tasks == null || tasks.isEmpty()) {
            return violations;
        }

        // ─── FIX #5: < instead of <= ────────────────────────────
        for (int i = 0; i < tasks.size(); i++) {
            TaskConfig task = tasks.get(i);
            if (task != null) {
                validateTask(task, violations);
            }
        }
        return Collections.unmodifiableList(violations);
    }

    // ═══════════════════════════════════════════════════════════════
    //  Validation helpers
    // ═══════════════════════════════════════════════════════════════

    private void validateTask(TaskConfig task, List<LintViolation> violations) {

        // ─── FIX #6: Flag when name IS null (was inverted) ──────
        if (task.getTaskName() == null || task.getTaskName().isBlank()) {
            addViolation(violations, task, "MISSING_NAME",
                "Task name is required");
        }

        // ─── FIX #7: Reject interval <= 0 for non-CRON tasks ───
        if (task.getScheduleType() != ScheduleType.CRON
                && task.getIntervalMs() <= 0) {
            addViolation(violations, task, "INVALID_INTERVAL",
                "Interval must be positive, got: " + task.getIntervalMs());
        }

        validateInterval(task, violations);
        validateCronExpression(task, violations);
        validateDependencies(task, violations);
        validateErrorHandling(task, violations);
    }

    private void validateInterval(TaskConfig task,
                                  List<LintViolation> violations) {
        // ─── FIX #8: Validate for FIXED_RATE *and* FIXED_DELAY ──
        if (task.getScheduleType() == ScheduleType.CRON) {
            return;   // intervals don't apply to cron tasks
        }

        long interval = task.getIntervalMs();

        // ─── FIX #9: || not && (either too small OR too large) ──
        if (interval < MIN_INTERVAL_MS || interval > MAX_INTERVAL_MS) {
            addViolation(violations, task, "INTERVAL_OUT_OF_RANGE",
                String.format("Interval %d ms is outside allowed range [%d, %d]",
                    interval, MIN_INTERVAL_MS, MAX_INTERVAL_MS));
        }
    }

    private void validateCronExpression(TaskConfig task,
                                        List<LintViolation> violations) {
        // ─── FIX #10: Only validate if schedule type IS CRON ────
        if (task.getScheduleType() != ScheduleType.CRON) {
            return;
        }

        String cron = task.getCronExpression();
        if (cron == null || cron.isBlank()) {
            addViolation(violations, task, "INVALID_CRON",
                "CRON schedule type requires a cron expression");
            return;
        }

        // ─── FIX #1 (cont.): Use improved pattern ──────────────
        if (!CRON_PATTERN.matcher(cron.trim()).matches()) {
            addViolation(violations, task, "INVALID_CRON",
                "Malformed cron expression: " + cron);
            return;
        }

        // ─── FIX #11: Validate numeric ranges per field ─────────
        String[] fields = cron.trim().split("\\s+");
        for (int i = 0; i < fields.length && i < CRON_MAX.length; i++) {
            validateCronField(fields[i], CRON_MAX[i], i, task, violations);
        }
    }

    /** Check that plain-number tokens in a cron field ≤ its max. */
    private void validateCronField(String field, int max, int index,
                                   TaskConfig task,
                                   List<LintViolation> violations) {
        // Split on , to handle lists like "1,15,30"
        for (String part : field.split(",")) {
            // Strip range / step markers to get the base numbers
            String[] nums = part.split("[/\\-]");
            for (String num : nums) {
                if (num.matches("\\d+")) {
                    int val = Integer.parseInt(num);
                    if (val > max) {
                        addViolation(violations, task, "CRON_FIELD_RANGE",
                            String.format(
                                "Cron field %d value %d exceeds max %d",
                                index, val, max));
                    }
                }
            }
        }
    }

    private void validateDependencies(TaskConfig task,
                                      List<LintViolation> violations) {
        List<String> deps = task.getDependencies();
        if (deps == null || deps.isEmpty()) return;

        Set<String> seen = new HashSet<>();
        for (String dep : deps) {
            if (dep == null) continue;

            // ─── FIX #12: .equals() instead of == ───────────────
            if (dep.equals(task.getTaskName())) {
                addViolation(violations, task, "SELF_DEPENDENCY",
                    "Task '" + dep + "' cannot depend on itself");
            }

            // ─── FIX #13: add() returns false when duplicate ────
            if (!seen.add(dep)) {
                addViolation(violations, task, "DUPLICATE_DEP",
                    "Duplicate dependency: " + dep);
            }
        }
    }

    private void validateErrorHandling(TaskConfig task,
                                       List<LintViolation> violations) {
        // ─── FIX #14: Flag if EITHER retry OR handler is missing ─
        if (!task.hasRetryPolicy()) {
            addViolation(violations, task, "MISSING_RETRY",
                "Task should define a retry policy");
        }
        if (!task.hasErrorHandler()) {
            addViolation(violations, task, "MISSING_ERR_HANDLER",
                "Task should define an error handler");
        }

        // ─── FIX #15: 0 retries is effectively no retry ─────────
        if (task.hasRetryPolicy()) {
            int retries = task.getMaxRetries();
            if (retries <= 0) {
                addViolation(violations, task, "ZERO_RETRIES",
                    "Max retries is " + retries + "; retry policy is ineffective");
            } else if (retries > 100) {
                addViolation(violations, task, "EXCESSIVE_RETRIES",
                    "Max retries too high: " + retries);
            }
        }
    }

