public class SearchIndexService
{
    // BUG 1: Using non-thread-safe Dictionary in concurrent environment
    private Dictionary<string, SearchDocument> _documents = new();
    private Dictionary<string, HashSet<string>> _invertedIndex = new();

    public void IndexDocument(SearchDocument document)
    {
        // BUG 2: No null/empty validation
        _documents[document.Id] = document;

        // BUG 3: Doesn't remove old terms when re-indexing a document
        var terms = Tokenize(document.Content + " " + document.Title);
        foreach (var term in terms)
        {
            if (!_invertedIndex.ContainsKey(term))
                _invertedIndex[term] = new HashSet<string>();

            _invertedIndex[term].Add(document.Id);
        }
    }

    public void DeleteDocument(string documentId)
    {
        // BUG 4: Doesn't clean up inverted index entries
        _documents.Remove(documentId);
    }

    public List<SearchResult> Search(string query, int page, int pageSize)
    {
        // BUG 5: No query validation, will crash on null
        var terms = Tokenize(query);
        var scores = new Dictionary<string, double>();

        foreach (var term in terms)
        {
            // BUG 6: KeyNotFoundException if term not in index
            var docIds = _invertedIndex[term];
            foreach (var docId in docIds)
            {
                // BUG 7: No check if document still exists
                scores[docId] = scores.GetValueOrDefault(docId) + CalculateTfIdf(term, docId);
            }
        }

        // BUG 8: Incorrect pagination (skips wrong number of results)
        return scores
            .OrderByDescending(x => x.Value)
            .Skip(page)
            .Take(pageSize)
            .Select(x => new SearchResult
            {
                DocumentId = x.Key,
                Score = x.Value,
                // BUG 9: Highlight not generated
                Highlight = ""
            })
            .ToList();
    }

    private double CalculateTfIdf(string term, string docId)
    {
        var doc = _documents[docId];
        var words = Tokenize(doc.Content);

        // BUG 10: Integer division gives 0 for tf
        double tf = words.Count(w => w == term) / words.Count();

        // BUG 11: Log of 0 when all docs contain term → NaN/crash
        double idf = Math.Log(_documents.Count / _invertedIndex[term].Count);

        return tf * idf;
    }

    private List<string> Tokenize(string text)
    {
        // BUG 12: Doesn't handle null text, no lowercasing, keeps punctuation
        return text.Split(' ').ToList();
    }
}

