{
    // FIX: ConcurrentDictionary for thread safety
    private readonly ConcurrentDictionary<string, SearchDocument> _documents = new();
    private readonly ConcurrentDictionary<string, ConcurrentHashSet<string>> _invertedIndex = new();
    private readonly ReaderWriterLockSlim _indexLock = new();
    private readonly ILogger<SearchIndexService> _logger;

    public SearchIndexService(ILogger<SearchIndexService> logger)
    {
        _logger = logger;
    }

    public IndexResponse IndexDocument(SearchDocument document)
    {
        // FIX 2: Input validation
        if (document == null)
            throw new ArgumentNullException(nameof(document));
        if (string.IsNullOrWhiteSpace(document.Id))
            throw new ArgumentException("Document Id is required.", nameof(document));
        if (string.IsNullOrWhiteSpace(document.Content) && string.IsNullOrWhiteSpace(document.Title))
            throw new ArgumentException("Document must have Title or Content.");

        document.IndexedAt = DateTime.UtcNow;

        _indexLock.EnterWriteLock();
        try
        {
            // FIX 3: Remove old terms before re-indexing
            if (_documents.TryGetValue(document.Id, out var existingDoc))
            {
                RemoveDocumentFromIndex(document.Id, existingDoc);
            }

            _documents[document.Id] = document;

            var terms = Tokenize($"{document.Title} {document.Content}");
            foreach (var term in terms)
            {
                var docSet = _invertedIndex.GetOrAdd(term, _ => new ConcurrentHashSet<string>());
                docSet.Add(document.Id);
            }

            _logger.LogInformation("Indexed document {DocId} with {TermCount} terms",
                document.Id, terms.Distinct().Count());

            return new IndexResponse
            {
                DocumentId = document.Id,
                Success = true,
                Message = "Document indexed successfully.",
                TermCount = terms.Distinct().Count()
            };
        }
        finally
        {
            _indexLock.ExitWriteLock();
        }
    }

    public bool DeleteDocument(string documentId)
    {
        if (string.IsNullOrWhiteSpace(documentId))
            return false;

        _indexLock.EnterWriteLock();
        try
        {
            if (!_documents.TryRemove(documentId, out var document))
                return false;

            // FIX 4: Clean up inverted index on delete
            RemoveDocumentFromIndex(documentId, document);

            _logger.LogInformation("Deleted document {DocId}", documentId);
            return true;
        }
        finally
        {
            _indexLock.ExitWriteLock();
        }
    }

    private void RemoveDocumentFromIndex(string documentId, SearchDocument document)
    {
        var oldTerms = Tokenize($"{document.Title} {document.Content}");
        foreach (var term in oldTerms)
        {
            if (_invertedIndex.TryGetValue(term, out var docSet))
            {
                docSet.Remove(documentId);
                // Clean up empty term entries
                if (docSet.Count == 0)
                    _invertedIndex.TryRemove(term, out _);
            }
        }
    }

    public SearchResponse Search(string query, int page, int pageSize)
    {
        var stopwatch = System.Diagnostics.Stopwatch.StartNew();

        // FIX 5: Validate query
        if (string.IsNullOrWhiteSpace(query))
        {
            return new SearchResponse
            {
                Results = new List<SearchResult>(),
                TotalCount = 0,
                Page = page,
                PageSize = pageSize
            };
        }

        var terms = Tokenize(query);
        var scores = new Dictionary<string, double>();

        _indexLock.EnterReadLock();
        try
        {
            foreach (var term in terms)
            {
                // FIX 6: Use TryGetValue instead of direct access
                if (!_invertedIndex.TryGetValue(term, out var docIds))
                    continue;

                foreach (var docId in docIds.ToList()) // snapshot to avoid modification
                {
                    // FIX 7: Verify document still exists
                    if (!_documents.ContainsKey(docId))
                        continue;

                    scores[docId] = scores.GetValueOrDefault(docId) + CalculateTfIdf(term, docId);
                }
            }

            var totalCount = scores.Count;

            // FIX 8: Correct pagination formula: (page - 1) * pageSize
            var results = scores
                .OrderByDescending(x => x.Value)
                .Skip((page - 1) * pageSize)
                .Take(pageSize)
                .Select(x =>
                {
                    var doc = _documents[x.Key];
                    return new SearchResult
                    {
                        DocumentId = x.Key,
                        Score = Math.Round(x.Value, 4),
                        Title = doc.Title,
                        // FIX 9: Generate highlight snippets
                        Highlight = GenerateHighlight(doc.Content, terms)
                    };
                })
                .ToList();

            stopwatch.Stop();

            return new SearchResponse
            {
                Results = results,
                TotalCount = totalCount,
                Page = page,
                PageSize = pageSize,
                ElapsedMs = stopwatch.Elapsed.TotalMilliseconds
            };
        }
        finally
        {
            _indexLock.ExitReadLock();
        }
    }

    private double CalculateTfIdf(string term, string docId)
    {
        if (!_documents.TryGetValue(docId, out var doc))
            return 0;

        var words = Tokenize(doc.Content);
        if (words.Count == 0) return 0;

        // FIX 10: Cast to double BEFORE division to avoid integer division
        double tf = (double)words.Count(w => w == term) / words.Count;

        // FIX 11: Add 1 to denominator to prevent log(0) → NaN
        double idf = Math.Log((double)_documents.Count / (_invertedIndex[term].Count + 1)) + 1;

        return tf * idf;
    }

    // FIX 12: Proper tokenization with null handling, lowercase, punctuation removal
    private List<string> Tokenize(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return new List<string>();

        return Regex.Replace(text.ToLowerInvariant(), @"[^\w\s]", "")
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(t => t.Length > 1)  // skip single chars
            .ToList();
    }

    private string GenerateHighlight(string content, List<string> terms, int snippetLength = 150)
    {
        if (string.IsNullOrWhiteSpace(content))
            return string.Empty;

        var lowerContent = content.ToLowerInvariant();

        // Find the first matching term position
        int bestPos = -1;
        foreach (var term in terms)
        {
            int pos = lowerContent.IndexOf(term, StringComparison.Ordinal);
            if (pos >= 0 && (bestPos < 0 || pos < bestPos))
                bestPos = pos;
        }

        if (bestPos < 0)
            return content.Length > snippetLength
                ? content[..snippetLength] + "..."
                : content;

        // Extract snippet around match
        int start = Math.Max(0, bestPos - snippetLength / 3);
        int end = Math.Min(content.Length, start + snippetLength);
        var snippet = content[start..end];

        if (start > 0) snippet = "..." + snippet;
        if (end < content.Length) snippet += "...";

        // Bold matching terms
        foreach (var term in terms)
        {
            snippet = Regex.Replace(snippet, Regex.Escape(term), $"<b>{term}</b>",
                RegexOptions.IgnoreCase);
        }

        return snippet;
    }

    public int DocumentCount => _documents.Count;
    public int TermCount => _invertedIndex.Count;
