"use strict";

/**
 * Base error class for all parser-related errors.
 */
class ParserError extends Error {
  /**
   * @param {string} message - Error message
   * @param {string} code - Machine-readable error code
   * @param {Object} [context={}] - Additional context about the error
   */
  constructor(message, code, context = {}) {
    super(message);
    this.name = "ParserError";
    this.code = code;
    this.context = context;
    this.timestamp = new Date().toISOString();

    // Maintains proper stack trace in V8
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      context: this.context,
      timestamp: this.timestamp,
    };
  }
}

/**
 * Thrown when input content cannot be parsed in the expected format.
 */
class ParseError extends ParserError {
  /**
   * @param {string} message
   * @param {Object} [context={}]
   */
  constructor(message, context = {}) {
    super(message, "PARSE_ERROR", context);
    this.name = "ParseError";
  }
}

/**
 * Thrown when no parser is registered for the requested format.
 */
class UnsupportedFormatError extends ParserError {
  /**
   * @param {string} format
   */
  constructor(format) {
    super(
      `Unsupported document format: "${format}"`,
      "UNSUPPORTED_FORMAT",
      { format }
    );
    this.name = "UnsupportedFormatError";
  }
}

/**
 * Thrown when input validation fails before parsing.
 */
class ValidationError extends ParserError {
  /**
   * @param {string} message
   * @param {Object} [context={}]
   */
  constructor(message, context = {}) {
    super(message, "VALIDATION_ERROR", context);
    this.name = "ValidationError";
  }
}

/**
 * Thrown when a file cannot be read from disk.
 */
class FileReadError extends ParserError {
  /**
   * @param {string} filePath
   * @param {Error} originalError
   */
  constructor(filePath, originalError) {
    super(
      `Failed to read file: ${filePath}`,
      "FILE_READ_ERROR",
      { filePath, originalError: originalError.message }
    );
    this.name = "FileReadError";
    this.originalError = originalError;
  }
}

module.exports = {
  ParserError,
  ParseError,
  UnsupportedFormatError,
  ValidationError,
