```javascript
"use strict";

const { ValidationError } = require("../errors/ParserErrors");

/**
 * @typedef {Object} ParseResult
 * @property {*} data - The parsed data
 * @property {Object} metadata - Metadata about the parsing operation
 * @property {string} metadata.format - The format that was parsed
 * @property {number} metadata.inputLength - Length of input in characters
 * @property {number} metadata.parseTimeMs - Time taken to parse in milliseconds
 * @property {string} metadata.parsedAt - ISO timestamp of parse operation
 */

/**
 * @typedef {Object} ParserOptions
 * @property {string} [encoding='utf-8'] - Character encoding
 * @property {boolean} [strict=true] - Enable strict parsing mode
 * @property {number} [maxSize=10485760] - Maximum input size in bytes (default 10MB)
 * @property {boolean} [trim=true] - Trim whitespace from input
 */

/**
 * Abstract base class for all document parsers.
 * Enforces a consistent interface and provides shared validation logic.
 */
class BaseParser {
  /** @type {string} */
  static FORMAT = "base";

  /** @type {string[]} */
  static EXTENSIONS = [];

  /** @type {string[]} */
  static MIME_TYPES = [];

  /**
   * @param {ParserOptions} [options={}]
   */
  constructor(options = {}) {
    if (new.target === BaseParser) {
      throw new Error("BaseParser is abstract and cannot be instantiated directly");
    }

    /** @type {ParserOptions} */
    this.options = {
      encoding: "utf-8",
      strict: true,
      maxSize: 10 * 1024 * 1024, // 10MB
      trim: true,
      ...options,
    };
  }

  /**
   * Validate input before parsing.
   * @param {string} content
   * @throws {ValidationError}
   */
  validate(content) {
    if (content === null || content === undefined) {
      throw new ValidationError("Input content cannot be null or undefined");
    }

    if (typeof content !== "string") {
      throw new ValidationError(
        `Input must be a string, received ${typeof content}`,
        { receivedType: typeof content }
      );
    }

    const byteSize = Buffer.byteLength(content, this.options.encoding);
    if (byteSize > this.options.maxSize) {
      throw new ValidationError(
        `Input exceeds maximum size of ${this.options.maxSize} bytes`,
        { inputSize: byteSize, maxSize: this.options.maxSize }
      );
    }

    if (this.options.trim) {
      content = content.trim();
    }

    if (content.length === 0) {
      throw new ValidationError("Input content is empty after trimming");
    }

    return content;
  }

  /**
   * Parse content string into structured data.
   * Must be implemented by subclasses.
   *
   * @param {string} content - Raw content to parse
   * @returns {ParseResult}
   * @abstract
   */
  parse(content) {
    throw new Error("parse() must be implemented by subclass");
  }

  /**
   * Wrap raw parsed data into a standardized ParseResult.
   * @param {*} data
   * @param {string} content - Original input
   * @param {number} startTime - High-resolution start time
   * @returns {ParseResult}
   */
  buildResult(data, content, startTime) {
    const elapsed = performance.now() - startTime;
    return {
      data,
      metadata: {
        format: this.constructor.FORMAT,
        inputLength: content.length,
        parseTimeMs: Math.round(elapsed * 1000) / 1000,
        parsedAt: new Date().toISOString(),
      },
    };
  }

  /**
   * Check whether this parser can handle the given MIME type.
   * @param {string} mimeType
   * @returns {boolean}
   */
  supportsMimeType(mimeType) {
    return this.constructor.MIME_TYPES.includes(mimeType.toLowerCase());
  }

  /**
   * Check whether this parser can handle the given file extension.
   * @param {string} ext - File extension including leading dot
   * @returns {boolean}
   */
  supportsExtension(ext) {
    return this.constructor.EXTENSIONS.includes(ext.toLowerCase());
  }
}

module.exports = BaseParser;
