"use strict";

const BaseParser = require("./BaseParser");
const { ParseError } = require("../errors/ParserErrors");

/**
 * Parser for JSON documents.
 *
 * @extends BaseParser
 */
class JSONParser extends BaseParser {
  static FORMAT = "json";
  static EXTENSIONS = [".json"];
  static MIME_TYPES = ["application/json", "text/json"];

  /**
   * @param {Object} [options={}]
   * @param {Function|null} [options.reviver=null] - JSON.parse reviver function
   * @param {boolean} [options.allowComments=false] - Strip single-line comments before parsing
   */
  constructor(options = {}) {
    super(options);
    this.reviver = options.reviver || null;
    this.allowComments = options.allowComments || false;
  }

  /**
   * Parse a JSON string into a JavaScript value.
   *
   * @param {string} content
   * @returns {import('./BaseParser').ParseResult}
   * @throws {ParseError}
   */
  parse(content) {
    const startTime = performance.now();
    content = this.validate(content);

    if (this.allowComments) {
      content = this._stripComments(content);
    }

    try {
      const data = JSON.parse(content, this.reviver);
      return this.buildResult(data, content, startTime);
    } catch (err) {
      const position = this._extractErrorPosition(err.message);
      throw new ParseError("Invalid JSON content", {
        originalMessage: err.message,
        position,
        snippet: this._getSnippet(content, position),
      });
    }
  }

  /**
   * Strip single-line `//` comments from JSON.
   * @private
   * @param {string} content
   * @returns {string}
   */
  _stripComments(content) {
    return content.replace(/^\s*\/\/.*$/gm, "");
  }

  /**
   * Attempt to extract a character position from the native JSON parse error.
   * @private
   * @param {string} message
   * @returns {number|null}
   */
  _extractErrorPosition(message) {
    const match = message.match(/position\s+(\d+)/i);
    return match ? parseInt(match[1], 10) : null;
  }

  /**
   * Return a small window of characters around an error position.
   * @private
   * @param {string} content
   * @param {number|null} position
   * @returns {string|null}
   */
  _getSnippet(content, position) {
    if (position === null) return null;
    const start = Math.max(0, position - 20);
    const end = Math.min(content.length, position + 20);
    return content.slice(start, end);
  }
}

module.exports = JSONParser;
