"use strict";

const BaseParser = require("./BaseParser");
const { ParseError, ValidationError } = require("../errors/ParserErrors");

/**
 * @typedef {Object} CSVParserOptions
 * @property {string} [delimiter=','] - Column delimiter character
 * @property {string} [quote='"'] - Quote character for escaping
 * @property {boolean} [hasHeader=true] - First row is a header row
 * @property {boolean} [skipEmptyLines=true] - Ignore blank lines
 * @property {string|null} [comment=null] - Lines starting with this are comments
 * @property {boolean} [trimFields=true] - Trim whitespace from each field
 * @property {boolean} [dynamicTyping=false] - Auto-convert numbers and booleans
 */

class CSVParser extends BaseParser {
  static FORMAT = "csv";
  static EXTENSIONS = [".csv", ".tsv"];
  static MIME_TYPES = ["text/csv", "text/tab-separated-values"];

  /**
   * @param {CSVParserOptions & import('./BaseParser').ParserOptions} [options={}]
   */
  constructor(options = {}) {
    super(options);

    /** @type {CSVParserOptions} */
    this.csvOptions = {
      delimiter: options.delimiter || ",",
      quote: options.quote || '"',
      hasHeader: options.hasHeader !== false,
      skipEmptyLines: options.skipEmptyLines !== false,
      comment: options.comment || null,
      trimFields: options.trimFields !== false,
      dynamicTyping: options.dynamicTyping || false,
    };
  }

  /**
   * Parse CSV content into an array of objects (with header) or array of arrays.
   *
   * @param {string} content
   * @returns {import('./BaseParser').ParseResult}
   * @throws {ParseError}
   */
  parse(content) {
    const startTime = performance.now();
    content = this.validate(content);

    try {
      const rows = this._tokenize(content);
      const filteredRows = this._filterRows(rows);

      if (filteredRows.length === 0) {
        throw new ParseError("CSV contains no data rows");
      }

      let data;
      let headers = null;

      if (this.csvOptions.hasHeader) {
        headers = filteredRows[0];
        this._validateHeaders(headers);
        const dataRows = filteredRows.slice(1);
        data = dataRows.map((row, idx) =>
          this._rowToObject(row, headers, idx + 2)
        );
      } else {
        data = filteredRows;
      }

      const result = this.buildResult(data, content, startTime);
      result.metadata.headers = headers;
      result.metadata.rowCount = Array.isArray(data) ? data.length : 0;
      return result;
    } catch (err) {
      if (err instanceof ParseError || err instanceof ValidationError) {
        throw err;
      }
      throw new ParseError("Failed to parse CSV content", {
        originalMessage: err.message,
      });
    }
  }

  /**
   * RFC 4180-compliant tokenizer that handles quoted fields correctly.
   * @private
