"use strict";

const fs = require("fs");
const fsp = fs.promises;
const path = require("path");
const crypto = require("crypto");

/**
 * Compute the SHA-256 checksum of a file via streaming.
 * @param {string} filePath
 * @returns {Promise<string>}
 */
async function computeChecksum(filePath) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash("sha256");
    const stream = fs.createReadStream(filePath, { highWaterMark: 64 * 1024 });
    stream.on("data", (chunk) => hash.update(chunk));
    stream.on("end", () => resolve(hash.digest("hex")));
    stream.on("error", reject);
  });
}

/**
 * Recursively walk a directory and return relative file paths.
 * Symbolic links are not followed.
 * @param {string}   dir            Root directory
 * @param {string[]} excludePatterns Glob-like patterns to skip
 * @param {string}   [base=""]      Accumulator for relative paths
 * @returns {Promise<string[]>}
 */
async function walkDirectory(dir, excludePatterns = [], base = "") {
  const results = [];

  let entries;
  try {
    entries = await fsp.readdir(dir, { withFileTypes: true });
  } catch (err) {
    if (err.code === "ENOENT") return results;
    throw err;
  }

  for (const entry of entries) {
    const relativePath = base ? path.join(base, entry.name) : entry.name;

    if (shouldExclude(relativePath, entry.name, excludePatterns)) {
      continue;
    }

    if (entry.isDirectory()) {
      const nested = await walkDirectory(
        path.join(dir, entry.name),
        excludePatterns,
        relativePath
      );
      results.push(...nested);
    } else if (entry.isFile()) {
      results.push(relativePath);
    }
  }

  return results;
}

/**
 * Check whether a path matches any exclusion pattern.
 * Supports simple wildcards (* matches anything) and exact folder names.
 */
function shouldExclude(relativePath, name, patterns) {
  for (const pattern of patterns) {
    // Exact name match (e.g. "node_modules", ".git")
    if (name === pattern || relativePath === pattern) return true;

    // Simple glob: *.ext
    if (pattern.startsWith("*.")) {
      const ext = pattern.slice(1); // ".ext"
      if (name.endsWith(ext)) return true;
    }

    // Folder prefix: "dist/"
    if (pattern.endsWith("/")) {
      const prefix = pattern.slice(0, -1);
      if (
        relativePath.startsWith(prefix + path.sep) ||
        relativePath.startsWith(prefix + "/") ||
        name === prefix
      ) {
        return true;
      }
    }

    // Contains segment
    const segments = relativePath.split(path.sep);
    if (segments.includes(pattern)) return true;
  }
  return false;
}

/**
 * Retrieve fs.Stats for a file, or null if it doesn't exist.
 */
async function safeStat(filePath) {
  try {
    return await fsp.stat(filePath);
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
}

/**
 * Copy a file, creating intermediate directories as needed.
 * Preserves the modified timestamp.
 */
async function copyFile(src, dest) {
  await fsp.mkdir(path.dirname(dest), { recursive: true });
  await fsp.copyFile(src, dest);

  // Preserve mtime
  const stat = await fsp.stat(src);
  await fsp.utimes(dest, stat.atime, stat.mtime);
}

/**
 * Delete a file and remove empty parent directories up to a boundary.
 */
async function deleteFile(filePath, boundaryDir) {
  await fsp.unlink(filePath);

  // Clean up empty ancestors
  let dir = path.dirname(filePath);
  while (dir !== boundaryDir && dir !== path.dirname(dir)) {
    try {
      const contents = await fsp.readdir(dir);
      if (contents.length === 0) {
        await fsp.rmdir(dir);
        dir = path.dirname(dir);
      } else {
        break;
      }
    } catch {
      break;
    }
  }
}

/**
 * Ensure a directory exists.
 */
async function ensureDir(dir) {
  await fsp.mkdir(dir, { recursive: true });
}

module.exports = {
  computeChecksum,
  walkDirectory,
  shouldExclude,
  safeStat,
  copyFile,
  deleteFile,
  ensureDir,
};
