"use strict";

const path = require("path");
const { FileStatus } = require("./constants");
const {
  walkDirectory,
  safeStat,
  computeChecksum,
} = require("./utils");

/**
 * @typedef {Object} ComparisonResult
 * @property {string}     relativePath
 * @property {FileStatus} status
 * @property {import('fs').Stats|null} sourceStats
 * @property {import('fs').Stats|null} destStats
 * @property {string|null} sourceChecksum
 * @property {string|null} destChecksum
 */

class FileComparator {
  /**
   * @param {Object} options
   * @param {string}   options.source
   * @param {string}   options.destination
   * @param {boolean}  [options.useChecksum=true]
   * @param {string[]} [options.exclude=[]]
   * @param {number}   [options.timeTolerance=2000] ms tolerance for mtime
   */
  constructor(options) {
    this.source = options.source;
    this.destination = options.destination;
    this.useChecksum = options.useChecksum !== false;
    this.exclude = options.exclude || [];
    this.timeTolerance = options.timeTolerance ?? 2000;
  }

  /**
   * Compare every file in source and destination.
   * @returns {Promise<ComparisonResult[]>}
   */
  async compare() {
    const [sourceFiles, destFiles] = await Promise.all([
      walkDirectory(this.source, this.exclude),
      walkDirectory(this.destination, this.exclude),
    ]);

    const sourceSet = new Set(sourceFiles);
    const destSet = new Set(destFiles);
    const allFiles = new Set([...sourceFiles, ...destFiles]);
    const results = [];

    for (const relativePath of allFiles) {
      const inSource = sourceSet.has(relativePath);
      const inDest = destSet.has(relativePath);

      const result = await this._compareFile(relativePath, inSource, inDest);
      results.push(result);
    }

    return results;
  }

  /**
   * @private
   */
  async _compareFile(relativePath, inSource, inDest) {
    const srcPath = path.join(this.source, relativePath);
    const destPath = path.join(this.destination, relativePath);

    const sourceStats = inSource ? await safeStat(srcPath) : null;
    const destStats = inDest ? await safeStat(destPath) : null;

    // Only in source
    if (inSource && !inDest) {
      return {
        relativePath,
        status: FileStatus.SOURCE_ONLY,
        sourceStats,
        destStats: null,
        sourceChecksum: null,
        destChecksum: null,
      };
    }

    // Only in destination
    if (!inSource && inDest) {
      return {
        relativePath,
        status: FileStatus.DEST_ONLY,
        sourceStats: null,
        destStats,
        sourceChecksum: null,
        destChecksum: null,
      };
    }

    // In both — compare content
    return this._compareExisting(relativePath, srcPath, destPath, sourceStats, destStats);
  }

  /**
   * @private
   */
  async _compareExisting(relativePath, srcPath, destPath, sourceStats, destStats) {
    // Quick check: same size?
    if (sourceStats.size !== destStats.size) {
      return this._buildModifiedResult(
        relativePath, srcPath, destPath, sourceStats, destStats
      );
    }

    // Checksum comparison for accuracy
    if (this.useChecksum) {
      const [srcHash, destHash] = await Promise.all([
        computeChecksum(srcPath),
        computeChecksum(destPath),
      ]);

      if (srcHash === destHash) {
        return {
          relativePath,
          status: FileStatus.IDENTICAL,
          sourceStats,
          destStats,
          sourceChecksum: srcHash,
          destChecksum: destHash,
        };
      }

      // Content differs — determine direction by mtime
      return this._resolveDirection(
        relativePath, sourceStats, destStats, srcHash, destHash
      );
    }

    // Fallback: mtime comparison with tolerance
    const timeDiff = Math.abs(sourceStats.mtimeMs - destStats.mtimeMs);
    if (timeDiff <= this.timeTolerance) {
      return {
        relativePath,
        status: FileStatus.IDENTICAL,
        sourceStats,
        destStats,
        sourceChecksum: null,
        destChecksum: null,
      };
    }

    return this._resolveDirection(relativePath, sourceStats, destStats, null, null);
  }

  /**
   * @private
   */
  async _buildModifiedResult(relativePath, srcPath, destPath, sourceStats, destStats) {
    let srcHash = null;
    let destHash = null;
    if (this.useChecksum) {
      [srcHash, destHash] = await Promise.all([
        computeChecksum(srcPath),
        computeChecksum(destPath),
      ]);
    }
    return this._resolveDirection(relativePath, sourceStats, destStats, srcHash, destHash);
  }

  /**
   * @private
   */
  _resolveDirection(relativePath, sourceStats, destStats, srcHash, destHash) {
    const srcTime = sourceStats.mtimeMs;
    const destTime = destStats.mtimeMs;
    const timeDiff = Math.abs(srcTime - destTime);

    let status;
    if (timeDiff <= this.timeTolerance) {
      // Same time but different content → conflict
      status = FileStatus.CONFLICT;
    } else if (srcTime > destTime) {
      status = FileStatus.SOURCE_NEWER;
    } else {
      status = FileStatus.DEST_NEWER;
    }

    return {
      relativePath,
      status,
      sourceStats,
      destStats,
      sourceChecksum: srcHash,
      destChecksum: destHash,
    };
  }
}

module.exports = { FileComparator };
