   * @param {boolean}          options.dryRun
   * @param {Function|null}    options.onConflict  manual resolver (relativePath, srcStats, destStats) => FileAction
   * @param {Function|null}    options.onProgress  (operation) => void
   * @param {Function|null}    options.logger
   */
  constructor(options) {
    this.source = options.source;
    this.destination = options.destination;
    this.mode = options.mode || SyncMode.ONE_WAY;
    this.conflictStrategy = options.conflictStrategy || ConflictStrategy.NEWER_WINS;
    this.dryRun = options.dryRun || false;
    this.onConflict = options.onConflict || null;
    this.onProgress = options.onProgress || null;
    this.logger = options.logger || null;
  }

  /**
   * Plan and optionally execute synchronization.
   * @param {import('./comparator').ComparisonResult[]} comparisons
   * @returns {Promise<SyncReport>}
   */
  async execute(comparisons) {
    const startTime = new Date();
    const operations = [];

    for (const entry of comparisons) {
      const action = this._planAction(entry);
