package backup.model;

import java.io.Serializable;
import java.time.Instant;

/**
 * Immutable snapshot of a file's metadata at backup time.
 */
public record FileRecord(
        String relativePath,
        long sizeBytes,
        Instant lastModified,
        String sha256Checksum
) implements Serializable {

    private static final long serialVersionUID = 1L;

    /**
     * Quick check: size or timestamp changed since last record.
     */
    public boolean mightHaveChanged(FileRecord other) {
        return this.sizeBytes != other.sizeBytes
                || !this.lastModified.equals(other.lastModified);
    }

    /**
     * Definitive check: content hash differs.
     */
    public boolean contentChanged(FileRecord other) {
        return !this.sha256Checksum.equals(other.sha256Checksum);
    }
}
