package backup.model;

import java.io.*;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Collections;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Stores the state of the last successful backup.
 * Persisted to disk as a serialized file so backups survive restarts.
 */
public class BackupManifest implements Serializable {

    private static final long serialVersionUID = 1L;

    private Instant lastBackupTime;
    private int backupGeneration;  // incremented each run
    private final ConcurrentHashMap<String, FileRecord> fileRecords;

    public BackupManifest() {
        this.lastBackupTime = Instant.EPOCH;
        this.backupGeneration = 0;
        this.fileRecords = new ConcurrentHashMap<>();
    }

    // --- Accessors ---

    public Instant getLastBackupTime() {
        return lastBackupTime;
    }

    public int getBackupGeneration() {
        return backupGeneration;
    }

    public Map<String, FileRecord> getFileRecords() {
        return Collections.unmodifiableMap(fileRecords);
    }

    // --- Mutations (called only by backup worker) ---

    public void incrementGeneration() {
        this.backupGeneration++;
        this.lastBackupTime = Instant.now();
    }

    public void putRecord(FileRecord record) {
        fileRecords.put(record.relativePath(), record);
    }

    public void removeRecord(String relativePath) {
        fileRecords.remove(relativePath);
    }

    // --- Persistence ---

    public void saveTo(Path path) throws IOException {
        try (var oos = new ObjectOutputStream(new FileOutputStream(path.toFile()))) {
            oos.writeObject(this);
        }
    }

    public static BackupManifest loadFrom(Path path) throws IOException, ClassNotFoundException {
        try (var ois = new ObjectInputStream(new FileInputStream(path.toFile()))) {
            return (BackupManifest) ois.readObject();
        }
    }

    public static BackupManifest loadOrCreate(Path path) {
        if (path.toFile().exists()) {
            try {
                return loadFrom(path);
            } catch (IOException | ClassNotFoundException e) {
                System.err.println("⚠ Corrupt manifest, starting fresh: " + e.getMessage());
            }
        }
        return new BackupManifest();
    }
}
