        deletedFiles.add(path);
    }

    public void addUnchanged(String path) {
        unchangedFiles.add(path);
    }

    public void addError(String detail) {
        errors.add(detail);
    }

    public void complete() {
        this.endTime = Instant.now();
        this.status = errors.isEmpty() ? Status.SUCCESS
                : copiedFiles.isEmpty() && deletedFiles.isEmpty() ? Status.FAILED
                : Status.PARTIAL_FAILURE;
    }

    // --- Accessors ---

    public Status getStatus()                   { return status; }
    public List<String> getCopiedFiles()         { return Collections.unmodifiableList(copiedFiles); }
    public List<String> getDeletedFiles()        { return Collections.unmodifiableList(deletedFiles); }
    public List<String> getErrors()              { return Collections.unmodifiableList(errors); }

    @Override
    public String toString() {
        Duration elapsed = Duration.between(startTime, endTime != null ? endTime : Instant.now());
        return """
                ╔══════════════════════════════════════════════╗
                ║          BACKUP RESULT  (Gen #%d)            ║
                ╠══════════════════════════════════════════════╣
                ║  Status     : %-30s  ║
                ║  Duration   : %-30s  ║
                ║  Copied     : %-5d files  (%s)%s║
                ║  Deleted    : %-5d tracked removals         ║
                ║  Unchanged  : %-5d files                    ║
                ║  Errors     : %-5d                          ║
                ╚══════════════════════════════════════════════╝
                """.formatted(
                generation,
                status,
                elapsed,
                copiedFiles.size(), humanReadableBytes(totalBytesCopied),
                " ".repeat(Math.max(1, 14 - humanReadableBytes(totalBytesCopied).length())),
                deletedFiles.size(),
                unchangedFiles.size(),
                errors.size()
        );
    }

    private static String humanReadableBytes(long bytes) {
        if (bytes < 1024) return bytes + " B";
        int exp = (int) (Math.log(bytes) / Math.log(1024));
        char unit = "KMGTPE".charAt(exp - 1);
        return "%.1f %sB".formatted(bytes / Math.pow(1024, exp), unit);
    }
}
