### IncrementalBackupWorker.java
```java
package backup.worker;

import backup.model.BackupManifest;
import backup.model.BackupResult;
import backup.model.FileRecord;
import backup.util.ChecksumUtil;

import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.locks.ReentrantLock;

/**
 * Performs an incremental backup:
 *   1. Walks the source directory
 *   2. Compares each file against the manifest (fast: size+mtime, then checksum)
 *   3. Copies only new/changed files into a generation-stamped backup folder
 *   4. Records deletions
 *   5. Persists the updated manifest
 *
 * Thread-safe: uses a lock to prevent overlapping runs.
 */
public class IncrementalBackupWorker {

    private final Path sourceDir;
    private final Path backupRoot;
    private final Path manifestPath;
    private final ReentrantLock runLock = new ReentrantLock();
    private final AtomicBoolean cancelled = new AtomicBoolean(false);

    private BackupManifest manifest;

    public IncrementalBackupWorker(Path sourceDir, Path backupRoot) {
        this.sourceDir = sourceDir.toAbsolutePath();
        this.backupRoot = backupRoot.toAbsolutePath();
        this.manifestPath = backupRoot.resolve(".backup-manifest.dat");
    }

    // --- Public API ---

    /**
     * Initializes (or reloads) the manifest. Call once before first run.
     */
    public void initialize() throws IOException {
        Files.createDirectories(backupRoot);
        this.manifest = BackupManifest.loadOrCreate(manifestPath);
        System.out.printf("✔ Initialized. Last backup: gen #%d at %s%n",
                manifest.getBackupGeneration(), manifest.getLastBackupTime());
    }

    /**
     * Runs one incremental backup cycle. Returns a result summary.
     */
    public BackupResult runBackup() {
        if (!runLock.tryLock()) {
            System.out.println("⚠ Backup already in progress — skipping.");
            var skip = new BackupResult(-1);
            skip.addError("Concurrent run skipped");
            skip.complete();
            return skip;
        }

        try {
            cancelled.set(false);
            manifest.incrementGeneration();
            int gen = manifest.getBackupGeneration();
            BackupResult result = new BackupResult(gen);

            Path genDir = backupRoot.resolve("gen-" + gen);
            Files.createDirectories(genDir);

            System.out.printf("▶ Starting incremental backup gen #%d ...%n", gen);

            // 1. Scan source and process each file
            Set<String> currentFiles = scanAndBackup(genDir, result);

            // 2. Detect deletions (files in manifest but no longer on disk)
            detectDeletions(currentFiles, result);

            // 3. Persist manifest
            manifest.saveTo(manifestPath);

            result.complete();
            System.out.print(result);
            return result;

        } catch (IOException e) {
            var failResult = new BackupResult(manifest.getBackupGeneration());
            failResult.addError("Fatal: " + e.getMessage());
            failResult.complete();
            System.err.println("✖ Backup failed: " + e.getMessage());
            return failResult;

        } finally {
            runLock.unlock();
        }
    }

    /**
     * Signals the current run to stop as soon as possible.
     */
    public void cancel() {
        cancelled.set(true);
    }

    // --- Internal logic ---

    /**
     * Walks the source tree, compares each file with the manifest,
     * and copies changed files to the generation directory.
     * Returns the set of relative paths found on disk.
     */
    private Set<String> scanAndBackup(Path genDir, BackupResult result) throws IOException {
        Set<String> currentFiles = new HashSet<>();

        Files.walkFileTree(sourceDir, new SimpleFileVisitor<>() {

            @Override
            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                // Skip hidden directories (e.g., .git)
                if (dir.getFileName() != null
                        && dir.getFileName().toString().startsWith(".")
                        && !dir.equals(sourceDir)) {
                    return FileVisitResult.SKIP_SUBTREE;
                }
                return cancelled.get() ? FileVisitResult.TERMINATE : FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                if (cancelled.get()) return FileVisitResult.TERMINATE;
                if (!attrs.isRegularFile()) return FileVisitResult.CONTINUE;

                String relPath = sourceDir.relativize(file).toString();
                currentFiles.add(relPath);

                try {
                    processFile(file, relPath, attrs, genDir, result);
                } catch (IOException e) {
                    result.addError("Error processing " + relPath + ": " + e.getMessage());
                }
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFileFailed(Path file, IOException exc) {
                result.addError("Cannot access " + file + ": " + exc.getMessage());
                return FileVisitResult.CONTINUE;
            }
        });

        return currentFiles;
    }

    /**
     * Decides whether a single file needs backing up.
     * Uses a two-phase comparison for performance:
     *   Phase 1 (fast): compare size + last-modified timestamp
     *   Phase 2 (slow): compute SHA-256 checksum only if phase 1 flags a change
     */
    private void processFile(Path file, String relPath,
                             BasicFileAttributes attrs, Path genDir,
                             BackupResult result) throws IOException {

        FileRecord current = buildRecord(file, relPath, attrs, false);  // no checksum yet
        FileRecord previous = manifest.getFileRecords().get(relPath);

        if (previous != null && !current.mightHaveChanged(previous)) {
            // Fast path: nothing changed
            result.addUnchanged(relPath);
            return;
        }

        // Something might have changed — compute full checksum
        current = buildRecord(file, relPath, attrs, true);

        if (previous != null && !current.contentChanged(previous)) {
            // Metadata changed but content identical (e.g., touch)
            manifest.putRecord(current);  // update timestamp in manifest
            result.addUnchanged(relPath);
            return;
        }

        // File is new or content changed — copy it
        copyToBackup(file, relPath, genDir);
        manifest.putRecord(current);
        result.addCopied(relPath, attrs.size());
    }

    private void detectDeletions(Set<String> currentFiles, BackupResult result) {
        List<String> removed = new ArrayList<>();
        for (String tracked : manifest.getFileRecords().keySet()) {
            if (!currentFiles.contains(tracked)) {
                removed.add(tracked);
            }
        }
        for (String path : removed) {
            manifest.removeRecord(path);
            result.addDeleted(path);
        }
    }

    private void copyToBackup(Path sourceFile, String relPath, Path genDir) throws IOException {
        Path target = genDir.resolve(relPath);
        Files.createDirectories(target.getParent());
        Files.copy(sourceFile, target, StandardCopyOption.REPLACE_EXISTING,
                StandardCopyOption.COPY_ATTRIBUTES);
    }

    private FileRecord buildRecord(Path file, String relPath,
                                   BasicFileAttributes attrs,
                                   boolean computeChecksum) throws IOException {
        String checksum = computeChecksum ? ChecksumUtil.sha256(file) : "";

