   * @param {object} options
   * @param {any[]} options.records - Data records to process
   * @param {Map<string, any>} [options.metadata] - Pipeline metadata
   * @param {any[]} [options.errors] - Accumulated errors
   * @param {Map<string, number>} [options.metrics] - Accumulated metrics
   */
  constructor({ records = [], metadata = new Map(), errors = [], metrics = new Map() } = {}) {
    this.#id = crypto.randomUUID?.() ?? `ctx-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    this.#records = [...records];
    this.#metadata = new Map(metadata);
    this.#errors = [...errors];
    this.#metrics = new Map(metrics);
    this.#createdAt = new Date();
    this.#currentStage = null;
    Object.freeze(this);
  }

  get id() { return this.#id; }
  get records() { return [...this.#records]; }
  get metadata() { return new Map(this.#metadata); }
  get errors() { return [...this.#errors]; }
  get metrics() { return new Map(this.#metrics); }
  get createdAt() { return this.#createdAt; }
  get currentStage() { return this.#currentStage; }
  get recordCount() { return this.#records.length; }
  get errorCount() { return this.#errors.length; }
  get hasErrors() { return this.#errors.length > 0; }

  /**
   * Create new context with replaced records (immutable update).
   * @param {any[]} records
   * @returns {PipelineContext}
   */
  withRecords(records) {
    const ctx = new PipelineContext({
      records,
      metadata: this.#metadata,
      errors: this.#errors,
      metrics: this.#metrics,
    });
    return ctx;
  }

  /**
   * Create new context with an appended error.
   * @param {object} error
   * @returns {PipelineContext}
   */
  withError(error) {
    return new PipelineContext({
      records: this.#records,
      metadata: this.#metadata,
      errors: [...this.#errors, { ...error, timestamp: new Date().toISOString() }],
      metrics: this.#metrics,
    });
  }

  /**
   * Create new context with updated metadata.
   * @param {string} key
   * @param {any} value
   * @returns {PipelineContext}
   */
  withMetadata(key, value) {
    const meta = new Map(this.#metadata);
    meta.set(key, value);
    return new PipelineContext({
      records: this.#records,
      metadata: meta,
      errors: this.#errors,
      metrics: this.#metrics,
    });
  }

  /**
   * Create new context with an incremented metric.
   * @param {string} key
   * @param {number} [value=1]
   * @returns {PipelineContext}
   */
  withMetric(key, value = 1) {
    const m = new Map(this.#metrics);
    m.set(key, (m.get(key) ?? 0) + value);
    return new PipelineContext({
      records: this.#records,
      metadata: this.#metadata,
      errors: this.#errors,
      metrics: m,
    });
  }

  toJSON() {
    return {
      id: this.#id,
      recordCount: this.#records.length,
      errorCount: this.#errors.length,
      metadata: Object.fromEntries(this.#metadata),
      metrics: Object.fromEntries(this.#metrics),
      createdAt: this.#createdAt.toISOString(),
    };
  }
}

module.exports = PipelineContext;
