// src/pipeline/PipelineStage.js

const { PipelineStageError } = require('../errors/PipelineErrors');

/**
 * Abstract base class for all pipeline stages.
 * Subclasses must implement `_process(context)`.
 */
class PipelineStage {
  /** @type {string} */
  #name;
  /** @type {boolean} */
  #enabled;
  /** @type {object} */
  #options;
  /** @type {number} */
  #executionCount;
  /** @type {number} */
  #totalDurationMs;

  /**
   * @param {string} name - Human-readable stage name
   * @param {object} [options] - Stage-specific configuration
   * @param {boolean} [options.enabled=true]
   * @param {boolean} [options.continueOnError=false]
   * @param {number} [options.timeoutMs=30000]
   * @param {number} [options.retries=0]
   * @param {number} [options.retryDelayMs=1000]
   */
  constructor(name, options = {}) {
    if (new.target === PipelineStage) {
      throw new TypeError('PipelineStage is abstract and cannot be instantiated directly');
    }
    this.#name = name;
    this.#enabled = options.enabled ?? true;
    this.#options = { continueOnError: false, timeoutMs: 30_000, retries: 0, retryDelayMs: 1000, ...options };
    this.#executionCount = 0;
    this.#totalDurationMs = 0;
  }

  get name() { return this.#name; }
  get enabled() { return this.#enabled; }
  get options() { return { ...this.#options }; }
  get stats() {
    return {
      executionCount: this.#executionCount,
      totalDurationMs: this.#totalDurationMs,
      avgDurationMs: this.#executionCount > 0
        ? Math.round(this.#totalDurationMs / this.#executionCount)
        : 0,
    };
  }

  /**
   * Execute the stage with timeout, retry, and error handling.
   * @param {import('./PipelineContext')} context
   * @param {import('../utils/Logger')} logger
   * @returns {Promise<import('./PipelineContext')>}
   */
  async execute(context, logger) {
    if (!this.#enabled) {
      logger.debug(`Stage "${this.#name}" is disabled – skipping`);
      return context;
    }

    const startTime = performance.now();
    let lastError = null;
    const maxAttempts = this.#options.retries + 1;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        logger.info(`Stage "${this.#name}" – attempt ${attempt}/${maxAttempts}, records: ${context.recordCount}`);

        const result = await this.#executeWithTimeout(context, logger);

        const durationMs = Math.round(performance.now() - startTime);
        this.#executionCount++;
        this.#totalDurationMs += durationMs;

        logger.info(`Stage "${this.#name}" completed in ${durationMs}ms, records: ${result.recordCount}`);
        return result.withMetric(`stage.${this.#name}.durationMs`, durationMs);

      } catch (error) {
        lastError = error;
        logger.warn(`Stage "${this.#name}" attempt ${attempt} failed: ${error.message}`);

        if (attempt < maxAttempts) {
          const delay = this.#options.retryDelayMs * Math.pow(2, attempt - 1);
          logger.info(`Retrying in ${delay}ms...`);
          await PipelineStage.#sleep(delay);
        }
      }
    }

    // All attempts exhausted
    const stageError = new PipelineStageError(this.#name, lastError);

    if (this.#options.continueOnError) {
      logger.error(`Stage "${this.#name}" failed but continueOnError=true: ${lastError.message}`);
      return context.withError({
        stage: this.#name,
        message: lastError.message,
        stack: lastError.stack,
      });
    }

    throw stageError;
  }

  /**
   * Wrap `_process` in a timeout.
   * @param {import('./PipelineContext')} context
   * @param {import('../utils/Logger')} logger
   * @returns {Promise<import('./PipelineContext')>}
   */
  async #executeWithTimeout(context, logger) {
    const { timeoutMs } = this.#options;

    if (!timeoutMs || timeoutMs <= 0) {
      return this._process(context, logger);
    }

    return Promise.race([
      this._process(context, logger),
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error(`Stage "${this.#name}" timed out after ${timeoutMs}ms`)), timeoutMs)
      ),
    ]);
  }

  /**
   * Override this in subclasses to implement stage logic.
   * @abstract
   * @param {import('./PipelineContext')} context
   * @param {import('../utils/Logger')} logger
   * @returns {Promise<import('./PipelineContext')>}
   */
  async _process(_context, _logger) {
    throw new Error(`Stage "${this.#name}" must implement _process()`);
  }

  static #sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

module.exports = PipelineStage;
