// src/pipeline/Pipeline.js

const PipelineContext = require('./PipelineContext');
const Logger = require('../utils/Logger');
const Metrics = require('../utils/Metrics');
const { PipelineError, PipelineConfigError } = require('../errors/PipelineErrors');

/**
 * The main analytics pipeline orchestrator.
 *
 * Usage:
 *   const pipeline = new Pipeline('my-pipeline')
 *     .addStage(validatorStage)
 *     .addStage(transformStage)
 *     .addStage(aggregatorStage);
 *
 *   const result = await pipeline.run(jsonData);
 */
class Pipeline {
  /** @type {string} */
  #name;
  /** @type {import('./PipelineStage')[]} */
  #stages;
  /** @type {Logger} */
  #logger;
  /** @type {Metrics} */
  #metrics;
  /** @type {Function[]} */
  #onCompleteHooks;
  /** @type {Function[]} */
  #onErrorHooks;
  /** @type {object} */
  #config;

  /**
   * @param {string} name
   * @param {object} [config]
   * @param {string} [config.logLevel='info']
   * @param {boolean} [config.collectMetrics=true]
   * @param {number} [config.maxRecords=Infinity]
   * @param {boolean} [config.dryRun=false]
   */
  constructor(name, config = {}) {
    if (!name || typeof name !== 'string') {
      throw new PipelineConfigError('Pipeline name must be a non-empty string');
    }
    this.#name = name;
    this.#stages = [];
    this.#logger = new Logger({ prefix: `[Pipeline:${name}]`, level: config.logLevel ?? 'info' });
    this.#metrics = new Metrics();
    this.#onCompleteHooks = [];
    this.#onErrorHooks = [];
    this.#config = {
      collectMetrics: true,
      maxRecords: Infinity,
      dryRun: false,
      ...config,
    };
  }

  get name() { return this.#name; }
  get stageCount() { return this.#stages.length; }
  get stageNames() { return this.#stages.map(s => s.name); }

  /**
   * Append a stage to the pipeline.
   * @param {import('./PipelineStage')} stage
   * @returns {Pipeline} this (for chaining)
   */
  addStage(stage) {
    if (!stage || typeof stage.execute !== 'function') {
      throw new PipelineConfigError('Stage must be an instance of PipelineStage');
    }
    this.#stages.push(stage);
    this.#logger.debug(`Added stage "${stage.name}" (position ${this.#stages.length})`);
    return this;
  }

  /**
   * Insert a stage at a specific position.
   * @param {number} index
   * @param {import('./PipelineStage')} stage
   * @returns {Pipeline}
   */
  insertStage(index, stage) {
    if (index < 0 || index > this.#stages.length) {
      throw new PipelineConfigError(`Invalid stage index: ${index}`);
    }
    this.#stages.splice(index, 0, stage);
    return this;
  }

  /**
   * Register a completion hook.
   * @param {(context: PipelineContext) => void | Promise<void>} hook
   * @returns {Pipeline}
   */
  onComplete(hook) {
    this.#onCompleteHooks.push(hook);
    return this;
  }

  /**
   * Register an error hook.
   * @param {(error: Error, context: PipelineContext|null) => void | Promise<void>} hook
   * @returns {Pipeline}
   */
  onError(hook) {
    this.#onErrorHooks.push(hook);
    return this;
  }

  /**
   * Execute the full pipeline on the given input.
   * @param {any[]|object} input - JSON array or single record
   * @returns {Promise<PipelineResult>}
   */
  async run(input) {
    const runId = `run-${Date.now()}`;
    this.#logger.info(`=== Pipeline "${this.#name}" starting (${runId}) ===`);
    this.#metrics.startTimer('pipeline.totalDuration');

    let context = null;

    try {
      // Normalise input
      const records = this.#normaliseInput(input);
      this.#logger.info(`Input: ${records.length} records`);

      // Enforce max records
      const capped = records.slice(0, this.#config.maxRecords);
      if (capped.length < records.length) {
        this.#logger.warn(`Capped input from ${records.length} to ${this.#config.maxRecords} records`);
      }

      context = new PipelineContext({ records: capped });
      context = context.withMetadata('pipelineName', this.#name);
      context = context.withMetadata('runId', runId);
      context = context.withMetadata('startedAt', new Date().toISOString());

      if (this.#config.dryRun) {
        this.#logger.info('Dry run mode – skipping execution');
        return this.#buildResult(context, 'dry_run');
      }

      // Execute each stage sequentially
      for (const stage of this.#stages) {
        context = await stage.execute(context, this.#logger);
      }

      const duration = this.#metrics.endTimer('pipeline.totalDuration');
      context = context.withMetric('pipeline.totalDurationMs', duration);
      context = context.withMetadata('completedAt', new Date().toISOString());

      this.#logger.info(`=== Pipeline completed in ${duration}ms – ${context.recordCount} records, ${context.errorCount} errors ===`);

      // Fire completion hooks
      await this.#fireHooks(this.#onCompleteHooks, context);

      return this.#buildResult(context, context.hasErrors ? 'completed_with_errors' : 'success');

    } catch (error) {
      const duration = this.#metrics.endTimer('pipeline.totalDuration');
      this.#logger.error(`Pipeline failed after ${duration}ms: ${error.message}`);

      await this.#fireHooks(this.#onErrorHooks, error, context);

      return this.#buildResult(
        context?.withError({ stage: 'pipeline', message: error.message, stack: error.stack }) ?? null,
        'failed',
        error,
      );
    }
  }

  /**
   * Run the pipeline on a stream of JSON objects (async generator).
   * @param {AsyncIterable<object>} source
   * @param {number} [batchSize=100]
   * @returns {AsyncGenerator<PipelineResult>}
   */
  async *runStream(source, batchSize = 100) {
    let batch = [];
    let batchIndex = 0;

    for await (const record of source) {
      batch.push(record);

      if (batch.length >= batchSize) {
        this.#logger.info(`Processing batch ${++batchIndex} (${batch.length} records)`);
        yield await this.run(batch);
        batch = [];
      }
    }

    // Final partial batch
    if (batch.length > 0) {
      this.#logger.info(`Processing final batch ${++batchIndex} (${batch.length} records)`);
      yield await this.run(batch);
    }
  }

  // ── Private Helpers ──────────────────────────────────

  #normaliseInput(input) {
    if (Array.isArray(input)) return input;
    if (typeof input === 'string') {
      try {
        const parsed = JSON.parse(input);
        return Array.isArray(parsed) ? parsed : [parsed];
      } catch {
        throw new PipelineConfigError('Input string is not valid JSON');
      }
    }
    if (input !== null && typeof input === 'object') return [input];
    throw new PipelineConfigError(`Unsupported input type: ${typeof input}`);
  }

  #buildResult(context, status, error = null) {
    return {
      status,
      pipelineName: this.#name,
      records: context?.records ?? [],
      recordCount: context?.recordCount ?? 0,
      errors: context?.errors ?? [],
      errorCount: context?.errorCount ?? 0,
      metadata: context ? Object.fromEntries(context.metadata) : {},
      metrics: context ? Object.fromEntries(context.metrics) : {},
      stageStats: this.#stages.map(s => ({ name: s.name, ...s.stats })),
      error: error ? { message: error.message, stack: error.stack } : null,
    };

