using System;
using System.Collections.Concurrent;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

namespace ChatModeration
{
    // Represents a chat message entering the moderation pipeline
    public record ChatMessage(
        string MessageId,
        string UserId,
        string Username,
        string Content,
        string Channel,
        DateTime Timestamp);

    // Result after moderation processing
    public enum ModerationAction
    {
        Approved,
        Filtered,    // silently removed
        Warned,      // user gets a warning
        Muted,       // user temporarily muted
        Banned       // user banned
    }

    public record ModerationResult(
        ChatMessage Message,
        ModerationAction Action,
        string Reason,
        TimeSpan ProcessingTime);

    // Tracks per-user violation state for escalation
    public class UserViolationTracker
    {
        private readonly ConcurrentDictionary<string, int> _violations = new();
        private readonly int _warnThreshold;
        private readonly int _muteThreshold;
        private readonly int _banThreshold;

        public UserViolationTracker(int warnThreshold = 1, int muteThreshold = 3, int banThreshold = 5)
        {
            _warnThreshold = warnThreshold;
            _muteThreshold = muteThreshold;
            _banThreshold = banThreshold;
        }

        public ModerationAction RecordViolation(string userId)
        {
            int count = _violations.AddOrUpdate(userId, 1, (_, c) => c + 1);
            return count switch
            {
                _ when count >= _banThreshold => ModerationAction.Banned,
                _ when count >= _muteThreshold => ModerationAction.Muted,
                _ when count >= _warnThreshold => ModerationAction.Warned,
                _ => ModerationAction.Filtered
            };
        }

        public int GetViolationCount(string userId) =>
            _violations.GetValueOrDefault(userId, 0);

        public void Reset(string userId) =>
            _violations.TryRemove(userId, out _);
    }

    // Rule-based content checker (easy to extend)
    public class ContentModerator
    {
        private static readonly string[] BannedWords =
            { "spam", "scam", "hack", "cheat", "exploit" };

        private static readonly Regex UrlPattern =
            new(@"https?://\S+", RegexOptions.Compiled | RegexOptions.IgnoreCase);

        private static readonly Regex AllCapsPattern =
            new(@"^[A-Z\s!?.]{15,}$", RegexOptions.Compiled);

        private static readonly Regex RepeatedCharPattern =
            new(@"(.)\1{4,}", RegexOptions.Compiled);

        public (bool flagged, string reason) Check(ChatMessage message)
        {
            string content = message.Content;

            // Rule 1: banned words
            foreach (string word in BannedWords)
            {
                if (content.Contains(word, StringComparison.OrdinalIgnoreCase))
                    return (true, $"Banned word detected: '{word}'");
            }

            // Rule 2: excessive caps (shouting)
            if (content.Length > 10 && AllCapsPattern.IsMatch(content))
                return (true, "Excessive caps / shouting");

            // Rule 3: repeated characters (flood)
            if (RepeatedCharPattern.IsMatch(content))
                return (true, "Character spam / flooding");

            // Rule 4: link spam (more than 2 URLs)
            if (UrlPattern.Matches(content).Count > 2)
                return (true, "Excessive link posting");

            // Rule 5: message too long
            if (content.Length > 500)
                return (true, "Message exceeds length limit");

            return (false, string.Empty);
        }
    }

    // The queue consumer: pulls messages and moderates them
    public class ModerationConsumer : IDisposable
    {
        private readonly BlockingCollection<ChatMessage> _queue;
        private readonly ContentModerator _moderator;
        private readonly UserViolationTracker _tracker;
        private readonly CancellationTokenSource _cts;
        private readonly Task[] _workers;
        private readonly int _workerCount;

        // Stats
        private int _processed;
        private int _flagged;

        public int Processed => _processed;
        public int Flagged => _flagged;

        public event Action<ModerationResult>? OnResult;

        public ModerationConsumer(
            BlockingCollection<ChatMessage> queue,
            int workerCount = 2)
        {
            _queue = queue;
            _moderator = new ContentModerator();
            _tracker = new UserViolationTracker();
            _cts = new CancellationTokenSource();
            _workerCount = workerCount;
            _workers = new Task[_workerCount];
        }

        public void Start()
        {
            for (int i = 0; i < _workerCount; i++)
            {
                int workerId = i;
                _workers[i] = Task.Factory.StartNew(
                    () => ConsumeLoop(workerId),
                    _cts.Token,
                    TaskCreationOptions.LongRunning,
                    TaskScheduler.Default);
            }

            Console.WriteLine($"[Consumer] Started {_workerCount} moderation workers.");
        }

        private void ConsumeLoop(int workerId)
        {
            try
            {
                foreach (ChatMessage msg in _queue.GetConsumingEnumerable(_cts.Token))
                {
                    var sw = System.Diagnostics.Stopwatch.StartNew();

                    var (flagged, reason) = _moderator.Check(msg);
                    ModerationAction action;

                    if (flagged)
                    {
                        action = _tracker.RecordViolation(msg.UserId);
                        int violations = _tracker.GetViolationCount(msg.UserId);
                        reason = $"{reason} (violation #{violations} → {action})";
                        Interlocked.Increment(ref _flagged);
                    }
                    else
                    {
                        action = ModerationAction.Approved;
                    }

                    sw.Stop();
                    Interlocked.Increment(ref _processed);

                    var result = new ModerationResult(msg, action, reason, sw.Elapsed);
                    OnResult?.Invoke(result);
                }
            }
            catch (OperationCanceledException)
            {
                Console.WriteLine($"[Worker-{workerId}] Shutting down.");
            }
        }

        public void Stop()
        {
            _cts.Cancel();
            Task.WaitAll(_workers, TimeSpan.FromSeconds(5));
            Console.WriteLine($"[Consumer] Stopped. Processed={_processed}, Flagged={_flagged}");
        }

        public void Dispose()
        {
            _cts.Dispose();
            GC.SuppressFinalize(this);
        }
    }

    // Demo: simulate a busy chat and watch moderation in action
    class Program
    {
        static void Main()
        {
            // Bounded queue — applies back-pressure if moderation can't keep up
            using var queue = new BlockingCollection<ChatMessage>(boundedCapacity: 100);

            using var consumer = new ModerationConsumer(queue, workerCount: 2);

            // Hook into results
            consumer.OnResult += result =>
            {
                string icon = result.Action switch
                {
                    ModerationAction.Approved => "✅",
                    ModerationAction.Filtered => "🗑️",
                    ModerationAction.Warned   => "⚠️",
                    ModerationAction.Muted    => "🔇",
                    ModerationAction.Banned   => "🚫",
                    _ => "❓"
                };

                Console.WriteLine(
                    $"  {icon} [{result.Action}] " +
                    $"@{result.Message.Username}: \"{Truncate(result.Message.Content, 50)}\" " +
                    $"({result.ProcessingTime.TotalMicroseconds:F0}µs)" +
                    (result.Action != ModerationAction.Approved ? $" — {result.Reason}" : ""));
            };

            consumer.Start();

            // --- Produce test messages ---
            string[] testMessages =
            {
                "Hey everyone, great stream!",
                "Check out this scam link lol",
                "HELLO EVERYONE THIS IS SO EXCITING!!!",
                "Normal message here 🙂",
                "haaaaaaaaack the planet",
                "Visit http://a.com http://b.com http://c.com for free stuff",
                "This is a hack tool, trust me",
                "Another clean message",
                "SCAM SCAM SCAM buy now!!!",
                "gggggggggg",
                "Nice play!",
                "exploit the bug before they patch it",
                "I love this community",
                "cheat codes at my profile",
                "What time is the event?",
            };

            Console.WriteLine("[Producer] Enqueueing messages...\n");

            int msgId = 0;
            foreach (string text in testMessages)
            {
                // Simulate a repeat offender (userId "u-bad") and normal users
                bool isBad = text.Contains("scam", StringComparison.OrdinalIgnoreCase)
                          || text.Contains("hack", StringComparison.OrdinalIgnoreCase)
                          || text.Contains("exploit", StringComparison.OrdinalIgnoreCase)
                          || text.Contains("cheat", StringComparison.OrdinalIgnoreCase);

                var msg = new ChatMessage(
                    MessageId: $"msg-{++msgId}",
                    UserId: isBad ? "u-bad" : $"u-{msgId}",
                    Username: isBad ? "ToxicTroll" : $"User{msgId}",
                    Content: text,
                    Channel: "general",
                    Timestamp: DateTime.UtcNow);

                queue.Add(msg);
                Thread.Sleep(50); // simulate message arrival rate
            }

            // Signal no more messages, let workers drain
            queue.CompleteAdding();
            Thread.Sleep(1000);

            consumer.Stop();

            Console.WriteLine($"\nTotal processed: {consumer.Processed}");
            Console.WriteLine($"Total flagged:   {consumer.Flagged}");
        }

        static string Truncate(string s, int max) =>
            s.Length <= max ? s : s[..max] + "…";
    }
}
