```java
package com.docparser.config;

import com.docparser.retry.BackoffStrategy;

import java.time.Duration;
import java.util.*;

/**
 * Immutable retry policy configuration built via the Builder pattern.
 */
public final class RetryPolicy {

    private final int maxRetries;
    private final Duration initialDelay;
    private final Duration maxDelay;
    private final double backoffMultiplier;
    private final BackoffStrategy backoffStrategy;
    private final Set<Class<? extends Throwable>> retryableExceptions;
    private final Set<Class<? extends Throwable>> nonRetryableExceptions;
    private final boolean retryOnAllExceptions;

    private RetryPolicy(Builder builder) {
        this.maxRetries = builder.maxRetries;
        this.initialDelay = builder.initialDelay;
        this.maxDelay = builder.maxDelay;
        this.backoffMultiplier = builder.backoffMultiplier;
        this.backoffStrategy = builder.backoffStrategy;
        this.retryableExceptions = Collections.unmodifiableSet(builder.retryableExceptions);
        this.nonRetryableExceptions = Collections.unmodifiableSet(builder.nonRetryableExceptions);
        this.retryOnAllExceptions = builder.retryOnAllExceptions;
    }

    public int getMaxRetries() { return maxRetries; }
    public Duration getInitialDelay() { return initialDelay; }
    public Duration getMaxDelay() { return maxDelay; }
    public double getBackoffMultiplier() { return backoffMultiplier; }
    public BackoffStrategy getBackoffStrategy() { return backoffStrategy; }
    public Set<Class<? extends Throwable>> getRetryableExceptions() { return retryableExceptions; }
    public Set<Class<? extends Throwable>> getNonRetryableExceptions() { return nonRetryableExceptions; }

    public boolean shouldRetry(Throwable throwable) {
        if (nonRetryableExceptions.stream().anyMatch(cls -> cls.isInstance(throwable))) {
            return false;
        }
        if (retryOnAllExceptions) {
            return true;
        }
        return retryableExceptions.stream().anyMatch(cls -> cls.isInstance(throwable));
    }

    public static Builder builder() {
        return new Builder();
    }

    public static RetryPolicy defaultPolicy() {
        return builder().build();
    }

    public static final class Builder {
        private int maxRetries = 3;
        private Duration initialDelay = Duration.ofMillis(500);
        private Duration maxDelay = Duration.ofSeconds(30);
        private double backoffMultiplier = 2.0;
        private BackoffStrategy backoffStrategy = BackoffStrategy.EXPONENTIAL_WITH_JITTER;
        private final Set<Class<? extends Throwable>> retryableExceptions = new HashSet<>();
        private final Set<Class<? extends Throwable>> nonRetryableExceptions = new HashSet<>();
        private boolean retryOnAllExceptions = false;

        public Builder maxRetries(int maxRetries) {
            if (maxRetries < 0) throw new IllegalArgumentException("maxRetries must be >= 0");
            this.maxRetries = maxRetries;
            return this;
        }

        public Builder initialDelay(Duration initialDelay) {
            Objects.requireNonNull(initialDelay, "initialDelay must not be null");
            this.initialDelay = initialDelay;
            return this;
        }

        public Builder maxDelay(Duration maxDelay) {
            Objects.requireNonNull(maxDelay, "maxDelay must not be null");
            this.maxDelay = maxDelay;
            return this;
        }

        public Builder backoffMultiplier(double multiplier) {
            if (multiplier < 1.0) throw new IllegalArgumentException("multiplier must be >= 1.0");
            this.backoffMultiplier = multiplier;
            return this;
        }

        public Builder backoffStrategy(BackoffStrategy strategy) {
            this.backoffStrategy = Objects.requireNonNull(strategy);
            return this;
        }

        @SafeVarargs
        public final Builder retryOn(Class<? extends Throwable>... exceptions) {
            retryableExceptions.addAll(Arrays.asList(exceptions));
            return this;
        }

        @SafeVarargs
        public final Builder noRetryOn(Class<? extends Throwable>... exceptions) {
            nonRetryableExceptions.addAll(Arrays.asList(exceptions));
            return this;
        }

        public Builder retryOnAllExceptions(boolean retryAll) {
            this.retryOnAllExceptions = retryAll;
            return this;
        }

        public RetryPolicy build() {
            return new RetryPolicy(this);
        }
    }
}
