### BackoffStrategy

```java
package com.docparser.retry;

import java.time.Duration;
import java.util.concurrent.ThreadLocalRandom;

/**
 * Defines how delays increase between retry attempts.
 */
public enum BackoffStrategy {

    FIXED {
        @Override
        public Duration computeDelay(int attempt, Duration initialDelay,
                                     Duration maxDelay, double multiplier) {
            return capDelay(initialDelay, maxDelay);
        }
    },

    LINEAR {
        @Override
        public Duration computeDelay(int attempt, Duration initialDelay,
                                     Duration maxDelay, double multiplier) {
            long delayMs = initialDelay.toMillis() * (attempt + 1);
            return capDelay(Duration.ofMillis(delayMs), maxDelay);
        }
    },

    EXPONENTIAL {
        @Override
        public Duration computeDelay(int attempt, Duration initialDelay,
                                     Duration maxDelay, double multiplier) {
            long delayMs = (long) (initialDelay.toMillis() * Math.pow(multiplier, attempt));
            return capDelay(Duration.ofMillis(delayMs), maxDelay);
        }
    },

    EXPONENTIAL_WITH_JITTER {
        @Override
        public Duration computeDelay(int attempt, Duration initialDelay,
                                     Duration maxDelay, double multiplier) {
            long baseMs = (long) (initialDelay.toMillis() * Math.pow(multiplier, attempt));
            long cappedMs = Math.min(baseMs, maxDelay.toMillis());
            long jitteredMs = ThreadLocalRandom.current().nextLong(1, Math.max(2, cappedMs));
            return Duration.ofMillis(jitteredMs);
        }
    };

    public abstract Duration computeDelay(int attempt, Duration initialDelay,
                                          Duration maxDelay, double multiplier);

    protected static Duration capDelay(Duration delay, Duration maxDelay) {
        return delay.compareTo(maxDelay) > 0 ? maxDelay : delay;
    }
}
