### RetryListener

```java
package com.docparser.retry;

import java.time.Duration;

/**
 * Hook interface for observing retry events (logging, metrics, alerts).
 */
public interface RetryListener {

    default void onRetryAttempt(int attempt, int maxRetries,
                                Duration delay, Throwable failure) {}

    default void onSuccess(int attempt) {}

    default void onFailure(int totalAttempts, Throwable lastFailure) {}

    /** Composite that fans out to multiple listeners. */
    static RetryListener composite(RetryListener... listeners) {
        return new RetryListener() {
            @Override
            public void onRetryAttempt(int attempt, int maxRetries,
                                       Duration delay, Throwable failure) {
                for (RetryListener l : listeners) l.onRetryAttempt(attempt, maxRetries, delay, failure);
            }
            @Override
            public void onSuccess(int attempt) {
                for (RetryListener l : listeners) l.onSuccess(attempt);
            }
            @Override
            public void onFailure(int totalAttempts, Throwable lastFailure) {
                for (RetryListener l : listeners) l.onFailure(totalAttempts, lastFailure);
            }
        };
    }
}
