### CircuitBreaker

```java
package com.docparser.retry;

import java.time.Duration;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.logging.Logger;

/**
 * Thread-safe circuit breaker that prevents calls to an overwhelmed resource.
 *
 * States:  CLOSED → OPEN → HALF_OPEN → CLOSED / OPEN
 */
public class CircuitBreaker {

    private static final Logger LOG = Logger.getLogger(CircuitBreaker.class.getName());

    public enum State { CLOSED, OPEN, HALF_OPEN }

    private final int failureThreshold;
    private final Duration openDuration;
    private final int halfOpenMaxCalls;

    private final AtomicReference<State> state = new AtomicReference<>(State.CLOSED);
    private final AtomicInteger failureCount = new AtomicInteger(0);
    private final AtomicInteger halfOpenCalls = new AtomicInteger(0);
    private volatile Instant openedAt = Instant.MIN;

    public CircuitBreaker(int failureThreshold, Duration openDuration, int halfOpenMaxCalls) {
        this.failureThreshold = failureThreshold;
        this.openDuration = openDuration;
        this.halfOpenMaxCalls = halfOpenMaxCalls;
    }

    /** Default: 5 failures → open for 60 s → allow 3 probe calls. */
    public CircuitBreaker() {
        this(5, Duration.ofSeconds(60), 3);
    }

    public boolean allowRequest() {
        State current = state.get();
        switch (current) {
            case CLOSED:
                return true;
            case OPEN:
                if (Instant.now().isAfter(openedAt.plus(openDuration))) {
                    if (state.compareAndSet(State.OPEN, State.HALF_OPEN)) {
                        halfOpenCalls.set(0);
                        LOG.info("Circuit breaker transitioning to HALF_OPEN");
                    }
                    return halfOpenCalls.incrementAndGet() <= halfOpenMaxCalls;
                }
                return false;
            case HALF_OPEN:
                return halfOpenCalls.incrementAndGet() <= halfOpenMaxCalls;
            default:
                return false;
        }
    }

    public void recordSuccess() {
        State current = state.get();
        if (current == State.HALF_OPEN) {
            state.set(State.CLOSED);
            failureCount.set(0);
            LOG.info("Circuit breaker CLOSED after successful probe");
        } else {
            failureCount.set(0);
        }
    }

    public void recordFailure() {
        int failures = failureCount.incrementAndGet();
        State current = state.get();
        if (current == State.HALF_OPEN) {
            state.set(State.OPEN);
            openedAt = Instant.now();
            LOG.warning("Circuit breaker re-OPENED from HALF_OPEN");
        } else if (failures >= failureThreshold && state.compareAndSet(State.CLOSED, State.OPEN)) {
            openedAt = Instant.now();
            LOG.warning("Circuit breaker OPENED after " + failures + " consecutive failures");
        }
    }

    public State getState() { return state.get(); }
}
