// metrics/TimerMetric.java
package migration.metrics;

import java.time.Duration;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Tracks elapsed time and accumulates durations.
 * Supports nested timing via start/stop pairs.
 */
public class TimerMetric extends Metric {
    private final AtomicReference<Instant> startTime = new AtomicReference<>();
    private final AtomicLong totalNanos = new AtomicLong(0);
    private final AtomicLong invocationCount = new AtomicLong(0);
    private final AtomicLong minNanos = new AtomicLong(Long.MAX_VALUE);
    private final AtomicLong maxNanos = new AtomicLong(0);

    public TimerMetric(String name, String description) {
        super(name, description);
    }

    /** Start a timing session. Returns the start instant. */
    public Instant start() {
        Instant now = Instant.now();
        startTime.set(now);
        return now;
    }

    /** Stop the current timing session and record the duration. */
    public Duration stop() {
        Instant start = startTime.getAndSet(null);
        if (start == null) {
            throw new IllegalStateException("Timer '" + name + "' was not started");
        }
        Duration elapsed = Duration.between(start, Instant.now());
        record(elapsed);
        return elapsed;
    }

    /** Manually record a duration. */
    public void record(Duration duration) {
        long nanos = duration.toNanos();
        totalNanos.addAndGet(nanos);
        invocationCount.incrementAndGet();
        minNanos.updateAndGet(current -> Math.min(current, nanos));
        maxNanos.updateAndGet(current -> Math.max(current, nanos));
    }

    /** Execute a runnable and time it. */
    public Duration time(Runnable action) {
        start();
        try {
            action.run();
        } finally {
            return stop();
        }
    }

    public Duration getTotalDuration() {
        return Duration.ofNanos(totalNanos.get());
    }

    public Duration getAverageDuration() {
        long count = invocationCount.get();
        return count == 0
            ? Duration.ZERO
            : Duration.ofNanos(totalNanos.get() / count);
    }

    public long getInvocationCount() {
        return invocationCount.get();
    }

    @Override
    public MetricSnapshot snapshot() {
        long count = invocationCount.get();
        return new MetricSnapshot.Builder(name, "timer")
            .description(description)
            .value(totalNanos.get())
            .tag("total_ms", String.valueOf(getTotalDuration().toMillis()))
            .tag("avg_ms", String.valueOf(count > 0 ? totalNanos.get() / count / 1_000_000 : 0))
            .tag("min_ms", String.valueOf(count > 0 ? minNanos.get() / 1_000_000 : 0))
            .tag("max_ms", String.valueOf(count > 0 ? maxNanos.get() / 1_000_000 : 0))
            .tag("invocations", String.valueOf(count))
            .build();
    }

    @Override
    public void reset() {
        startTime.set(null);
        totalNanos.set(0);
        invocationCount.set(0);
        minNanos.set(Long.MAX_VALUE);
        maxNanos.set(0);
    }
}
