// metrics/HistogramMetric.java
package migration.metrics;

import java.util.Arrays;
import java.util.concurrent.locks.ReentrantReadWriteLock;

/**
 * Tracks distribution of values with percentile calculations.
 */
public class HistogramMetric extends Metric {
    private double[] values;
    private int size;
    private boolean sorted;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public HistogramMetric(String name, String description) {
        this(name, description, 10_000);
    }

    public HistogramMetric(String name, String description, int initialCapacity) {
        super(name, description);
        this.values = new double[initialCapacity];
        this.size = 0;
        this.sorted = true;
    }

    public void record(double value) {
        lock.writeLock().lock();
        try {
            if (size >= values.length) {
                values = Arrays.copyOf(values, values.length * 2);
            }
            values[size++] = value;
            sorted = false;
        } finally {
            lock.writeLock().unlock();
        }
    }

    public double getPercentile(double percentile) {
        lock.readLock().lock();
        try {
            if (size == 0) return 0.0;
            ensureSorted();
            int index = (int) Math.ceil(percentile / 100.0 * size) - 1;
            return values[Math.max(0, Math.min(index, size - 1))];
        } finally {
            lock.readLock().unlock();
        }
    }

    public double getMean() {
        lock.readLock().lock();
        try {
            if (size == 0) return 0.0;
            double sum = 0;
            for (int i = 0; i < size; i++) sum += values[i];
            return sum / size;
        } finally {
            lock.readLock().unlock();
        }
    }

    public int getCount() {
        lock.readLock().lock();
        try { return size; }
        finally { lock.readLock().unlock(); }
    }

    private void ensureSorted() {
        if (!sorted) {
            // Upgrade to write lock is needed
            lock.readLock().unlock();
            lock.writeLock().lock();
            try {
                if (!sorted) {
                    Arrays.sort(values, 0, size);
                    sorted = true;
                }
                lock.readLock().lock(); // Downgrade
            } finally {
                lock.writeLock().unlock();
            }
        }
    }

    @Override
    public MetricSnapshot snapshot() {
