            .tag("p99", String.format("%.2f", getPercentile(99)))
            .build();
    }

    @Override
    public void reset() {
        lock.writeLock().lock();
        try {
            size = 0;
            sorted = true;
        } finally {
            lock.writeLock().unlock();
        }
    }
