import java.util.*;
import java.util.concurrent.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.io.*;
import java.nio.file.*;
import java.util.logging.*;

// ==================== FIXED CODE ====================

public class ReportScheduler {

    private static final Logger logger = Logger.getLogger(ReportScheduler.class.getName());

    // FIX 1: volatile ensures visibility across threads
    private volatile boolean isRunning = false;

    // FIX 2: Thread-safe ConcurrentHashMap for tasks + their futures
    private final ConcurrentHashMap<String, ReportTask> scheduledTasks = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, ScheduledFuture<?>> taskFutures = new ConcurrentHashMap<>();

    // FIX 3: Thread pool sized for concurrent report generation
    private final ScheduledExecutorService executor;

    // FIX 4: DateTimeFormatter is thread-safe (replaces SimpleDateFormat)
    private static final DateTimeFormatter DATE_FORMATTER =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    // FIX 5: Use a connection pool (simulated here)
    private final ConnectionPool connectionPool;

    // Lock for critical operations
    private final Object schedulerLock = new Object();

    public ReportScheduler(int threadPoolSize, int maxConnections) {
        // FIX 3: Configurable thread pool with meaningful thread names
        this.executor = Executors.newScheduledThreadPool(threadPoolSize, r -> {
            Thread t = new Thread(r, "ReportScheduler-Worker");
            t.setDaemon(true);  // Won't prevent JVM shutdown
            return t;
        });
        this.connectionPool = new ConnectionPool(maxConnections);
    }

    /**
     * Starts the scheduler and schedules all registered tasks.
     */
    public void startScheduler() {
        synchronized (schedulerLock) {
            if (isRunning) {
                logger.warning("Scheduler is already running!");
                return;
            }
            isRunning = true;
        }

        logger.info("Scheduler started at: " + LocalDateTime.now().format(DATE_FORMATTER));

        for (Map.Entry<String, ReportTask> entry : scheduledTasks.entrySet()) {
            scheduleTask(entry.getValue());
        }
    }

    /**
     * Schedules an individual report task.
     */
    private void scheduleTask(ReportTask task) {
        // FIX 6: scheduleWithFixedDelay prevents task pile-up
        ScheduledFuture<?> future = executor.scheduleWithFixedDelay(
            () -> safeGenerateReport(task),
            task.getInitialDelayMinutes(),
            task.getIntervalMinutes(),
            TimeUnit.MINUTES          // FIX 7: Correct TimeUnit
        );

        // Store future for cancellation support
        taskFutures.put(task.getTaskId(), future);
        logger.info("Scheduled task: " + task.getTaskId() +
                     " every " + task.getIntervalMinutes() + " minutes");
    }

    /**
     * FIX 8: Wrapper with full exception handling so the scheduled thread never dies.
     */
    private void safeGenerateReport(ReportTask task) {
        try {
            generateReport(task);
        } catch (Exception e) {
            // Catch ALL exceptions — an uncaught exception kills the ScheduledFuture
            logger.log(Level.SEVERE,
                "Report generation failed for: " + task.getReportName(), e);
            task.setStatus(TaskStatus.FAILED);
            task.setLastError(e.getMessage());
        }
    }

    /**
     * Core report generation logic — fully fixed.
     */
    public void generateReport(ReportTask task) throws Exception {
        logger.info("Generating report: " + task.getReportName());
        task.setStatus(TaskStatus.RUNNING);

        // FIX 5 & 9: Get connection from pool, auto-close with try-with-resources
        try (DatabaseConnection conn = connectionPool.getConnection()) {

            List<Map<String, Object>> data = conn.executeQuery(task.getQuery());

            // FIX 10: Null and empty check on data
            if (data == null || data.isEmpty()) {
                logger.warning("No data returned for report: " + task.getReportName());
                task.setStatus(TaskStatus.COMPLETED_EMPTY);
                return;
            }

            String report = formatReport(data, task.getReportName());

            // FIX 11 & 12: try-with-resources auto-closes and flushes
            Path outputPath = Paths.get(task.getOutputPath());
            Files.createDirectories(outputPath.getParent());  // Ensure dir exists

            try (BufferedWriter writer = Files.newBufferedWriter(
                    outputPath,
                    java.nio.charset.StandardCharsets.UTF_8)) {
                writer.write(report);
            } // Auto-flush and close here

        } // Connection auto-returned to pool here

        // FIX 13: Thread-safe status update using AtomicReference inside ReportTask
        task.setLastRunSafe(LocalDateTime.now());
        task.setStatus(TaskStatus.COMPLETED);

        logger.info("Report generated successfully: " + task.getReportName());
    }

    /**
     * FIX 14 & 15: Validates task and schedules it if scheduler is already running.
     */
    public void addTask(ReportTask task) {
        // FIX 14: Validate all parameters
        Objects.requireNonNull(task, "Task cannot be null");
        Objects.requireNonNull(task.getTaskId(), "Task ID cannot be null");
        Objects.requireNonNull(task.getQuery(), "Query cannot be null");
        Objects.requireNonNull(task.getOutputPath(), "Output path cannot be null");

        if (task.getIntervalMinutes() <= 0) {
            throw new IllegalArgumentException("Interval must be positive");
        }

        scheduledTasks.put(task.getTaskId(), task);

        // FIX 15: If scheduler is running, schedule the new task immediately
        if (isRunning) {
            scheduleTask(task);
        }

        logger.info("Task added: " + task.getTaskId());
    }

    /**
     * FIX 16 & 17: Safe removal with future cancellation.
     */
    public boolean removeTask(String taskId) {
        // FIX 16: ConcurrentHashMap is thread-safe, no CME risk
        ReportTask removed = scheduledTasks.remove(taskId);

        if (removed == null) {
            logger.warning("Task not found: " + taskId);
            return false;
        }

        // FIX 17: Cancel the scheduled future
        ScheduledFuture<?> future = taskFutures.remove(taskId);
        if (future != null) {
            future.cancel(false);  // false = let current execution finish
        }

        logger.info("Task removed and cancelled: " + taskId);
        return true;
    }

    /**
     * FIX 18, 19, 20: Graceful shutdown with timeout and resource cleanup.
     */
    public void stopScheduler() {
        synchronized (schedulerLock) {
            if (!isRunning) {
                logger.warning("Scheduler is not running!");
                return;
            }
            isRunning = false;
        }

        logger.info("Stopping scheduler...");

        // Cancel all futures
        taskFutures.values().forEach(f -> f.cancel(false));
        taskFutures.clear();

        // FIX 18 & 19: Graceful shutdown with timeout
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                logger.warning("Forcing shutdown — tasks did not finish in 60s");
                executor.shutdownNow();

                if (!executor.awaitTermination(15, TimeUnit.SECONDS)) {
                    logger.severe("Executor did not terminate!");
                }
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();  // Restore interrupt flag
        }

        // FIX 20: Close connection pool
        try {
            connectionPool.shutdown();
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error closing connection pool", e);
        }

        logger.info("Scheduler stopped at: " + LocalDateTime.now().format(DATE_FORMATTER));
    }

    /**
     * FIX 21: Uses StringBuilder for efficient string concatenation.
     */
    private String formatReport(List<Map<String, Object>> data, String name) {
        StringBuilder sb = new StringBuilder(data.size() * 100);  // Pre-size estimate

        sb.append("═══════════════════════════════════════\n");
        sb.append("  Report: ").append(name).append('\n');
        sb.append("  Generated: ")
          .append(LocalDateTime.now().format(DATE_FORMATTER)).append('\n');
        sb.append("  Rows: ").append(data.size()).append('\n');
        sb.append("═══════════════════════════════════════\n\n");

        // Header row
        if (!data.isEmpty()) {
            Map<String, Object> firstRow = data.get(0);
            for (String key : firstRow.keySet()) {
                sb.append(String.format("%-20s", key));
            }
            sb.append('\n');
            sb.append("─".repeat(firstRow.size() * 20)).append('\n');
        }

        // Data rows
        for (Map<String, Object> row : data) {
            for (Object value : row.values()) {
                sb.append(String.format("%-20s", value != null ? value : "NULL"));
            }
            sb.append('\n');
        }

        return sb.toString();
    }

    /**
     * Get status of all tasks.
     */
    public Map<String, TaskStatus> getTaskStatuses() {
        Map<String, TaskStatus> statuses = new LinkedHashMap<>();
        scheduledTasks.forEach((id, task) -> statuses.put(id, task.getStatus()));
        return Collections.unmodifiableMap(statuses);
    }
}
