    // ─── SEARCH HANDLER ─────────────────────────────────────────

    class SearchHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            try {
                // FIX 4: Check HTTP method
                if (!"GET".equalsIgnoreCase(exchange.getRequestMethod())) {
                    sendError(exchange, 405, "Method Not Allowed. Use GET.");
                    return;
                }

                // FIX 9 & 10: Safe query parameter extraction
                String query = exchange.getRequestURI().getQuery();
                String searchTerm = extractQueryParam(query, "q");

                if (searchTerm == null || searchTerm.isBlank()) {
                    sendError(exchange, 400, "Missing required query parameter: 'q'.");
                    return;
                }

                // FIX 11: URL-decode the search term
                searchTerm = URLDecoder.decode(searchTerm, StandardCharsets.UTF_8);

                // FIX 12: Normalize to lowercase (consistent with indexing)
                searchTerm = searchTerm.toLowerCase().trim();

                // FIX 13: Handle null results safely
                Set<String> docIds = invertedIndex.getOrDefault(searchTerm, Collections.emptySet());

                // Build JSON results with document content
                StringBuilder json = new StringBuilder("{\"query\": \"");
                json.append(escapeJson(searchTerm));
                json.append("\", \"count\": ").append(docIds.size());
                json.append(", \"results\": [");

                int i = 0;
                for (String docId : docIds) {
                    if (i++ > 0) json.append(",");
                    String content = documentStore.getOrDefault(docId, "");
                    json.append(String.format(
                        "{\"id\": \"%s\", \"snippet\": \"%s\"}",
                        escapeJson(docId),
                        escapeJson(truncate(content, 200))
                    ));
                }
                json.append("]}");

                sendJsonResponse(exchange, 200, json.toString());

            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Error processing search", e);
                sendError(exchange, 500, "Internal server error.");
            }
        }
    }

    // ─── DELETE HANDLER ─────────────────────────────────────────

    class DeleteHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            try {
                if (!"DELETE".equalsIgnoreCase(exchange.getRequestMethod())
                    && !"POST".equalsIgnoreCase(exchange.getRequestMethod())) {
                    sendError(exchange, 405, "Method Not Allowed. Use DELETE or POST.");
                    return;
                }

                String body = readRequestBody(exchange);
                String docId = extractField(body, "id");

                if (docId == null || docId.isBlank()) {
                    sendError(exchange, 400, "Missing required field: 'id'.");
                    return;
                }

                if (!documentStore.containsKey(docId)) {
                    sendError(exchange, 404, "Document not found: " + docId);
                    return;
                }

                // FIX 14: Remove from BOTH documentStore AND invertedIndex
                String content = documentStore.remove(docId);
                if (content != null) {
                    removeFromIndex(docId, content);
                }

                String response = String.format(
                    "{\"id\": \"%s\", \"status\": \"deleted\"}", escapeJson(docId)
                );
                sendJsonResponse(exchange, 200, response);

            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Error deleting document", e);
                sendError(exchange, 500, "Internal server error.");
            }
        }
    }

    // ─── INDEXING LOGIC ─────────────────────────────────────────

    private void indexDocument(String docId, String content) {
        String[] tokens = tokenize(content);
        for (String token : tokens) {
            if (token.isEmpty()) continue;

            // FIX 15: Normalize to lowercase
            // FIX 17: Use computeIfAbsent to safely create set if missing
            invertedIndex
                .computeIfAbsent(token, k -> ConcurrentHashMap.newKeySet())
                .add(docId);
        }
    }

    // FIX 14: Clean up inverted index on delete
    private void removeFromIndex(String docId, String content) {
        String[] tokens = tokenize(content);
        for (String token : tokens) {
            if (token.isEmpty()) continue;
            Set<String> docIds = invertedIndex.get(token);
            if (docIds != null) {
                docIds.remove(docId);
                // Remove empty entries to prevent memory leaks
                if (docIds.isEmpty()) {
                    invertedIndex.remove(token, Collections.emptySet());
                }
            }
        }
    }

    // FIX 15 & 16: Proper tokenization with normalization
    private String[] tokenize(String content) {
        return TOKENIZER.split(content.toLowerCase().trim());
    }

    // ─── UTILITY METHODS ────────────────────────────────────────

    // FIX 18 & 19: Proper encoding + resource management
    private String readRequestBody(HttpExchange exchange) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(exchange.getRequestBody(), StandardCharsets.UTF_8))) {
            StringBuilder body = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                body.append(line);
            }
            return body.toString();
        }
    }

    // FIX 20: More robust JSON field extraction (still simple but safer)
    private String extractField(String json, String field) {
        if (json == null || field == null) return null;
        String key = "\"" + field + "\"";
        int keyIdx = json.indexOf(key);
        if (keyIdx == -1) return null;

        int colonIdx = json.indexOf(':', keyIdx + key.length());
        if (colonIdx == -1) return null;

        // Skip whitespace and opening quote
        int valueStart = -1;
        for (int i = colonIdx + 1; i < json.length(); i++) {
            if (json.charAt(i) == '"') {
                valueStart = i + 1;
                break;
            }
        }
        if (valueStart == -1) return null;

        // Find closing quote (handling escaped quotes)
        int valueEnd = -1;
        for (int i = valueStart; i < json.length(); i++) {
            if (json.charAt(i) == '"' && json.charAt(i - 1) != '\\') {
                valueEnd = i;
                break;
            }
        }
        if (valueEnd == -1) return null;

        return json.substring(valueStart, valueEnd);
