```

## Configuration File

```ini
# backup.conf

[general]
backup_name = my_project_backup
log_level = INFO
# full, incremental, differential
backup_type = incremental
compression = gzip
# Max parallel file operations
max_workers = 4

[source]
# Comma-separated directories to back up
directories = /home/user/documents, /home/user/projects
# Glob patterns to exclude
exclude_patterns = *.tmp, *.log, __pycache__/*, .git/*
# Follow symbolic links
follow_symlinks = false
# Max file size in MB (0 = unlimited)
max_file_size_mb = 500

[destination]
path = /mnt/backup/incremental
# Keep manifest of backed-up files for incremental tracking
manifest_file = .backup_manifest.json
# Max number of incremental chains before forcing full backup
max_incremental_chain = 7

[schedule]
# cron-style: minute hour day_of_month month day_of_week
cron_expression = 0 2 * * *
# Force full backup on this day (0=Mon, 6=Sun)
full_backup_day = 6

[retention]
# Number of full backup sets to keep
keep_full_backups = 4
# Days to keep incremental backups
keep_incremental_days = 30
# Minimum free space in GB before cleanup
min_free_space_gb = 10

[notifications]
enabled = true
email = admin@example.com
notify_on_success = false
notify_on_failure = true
