"""backup_config.py — Incremental backup configuration parser and manager."""

from __future__ import annotations

import configparser
import gzip
import hashlib
import json
import logging
import os
import shutil
import time
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from enum import Enum
from fnmatch import fnmatch
from pathlib import Path
from typing import IO

logger = logging.getLogger(__name__)


# ─── Enums & Data Classes ────────────────────────────────────────────────────

class BackupType(Enum):
    FULL = "full"
    INCREMENTAL = "incremental"
    DIFFERENTIAL = "differential"


class CompressionType(Enum):
    NONE = "none"
    GZIP = "gzip"
    BZ2 = "bz2"


class FileStatus(Enum):
    NEW = "new"
    MODIFIED = "modified"
    DELETED = "deleted"
    UNCHANGED = "unchanged"


@dataclass
class FileRecord:
    """Tracks a single file's state in the backup manifest."""
    path: str
    size: int
    mtime: float
    checksum: str
    last_backup_time: float
    backup_generation: int  # which backup in the chain holds this file

    def to_dict(self) -> dict:
        return {
            "path": self.path,
            "size": self.size,
            "mtime": self.mtime,
            "checksum": self.checksum,
            "last_backup_time": self.last_backup_time,
            "backup_generation": self.backup_generation,
        }

    @classmethod
    def from_dict(cls, data: dict) -> FileRecord:
        return cls(**data)


@dataclass
class BackupManifest:
    """Full manifest tracking all files across backup generations."""
    backup_name: str
    created_at: float = field(default_factory=time.time)
    last_full_backup: float = 0.0
    current_generation: int = 0
    files: dict[str, FileRecord] = field(default_factory=dict)

    def to_dict(self) -> dict:
        return {
            "backup_name": self.backup_name,
            "created_at": self.created_at,
            "last_full_backup": self.last_full_backup,
            "current_generation": self.current_generation,
            "files": {k: v.to_dict() for k, v in self.files.items()},
        }

    @classmethod
    def from_dict(cls, data: dict) -> BackupManifest:
        manifest = cls(
            backup_name=data["backup_name"],
            created_at=data["created_at"],
            last_full_backup=data["last_full_backup"],
            current_generation=data["current_generation"],
        )
        manifest.files = {
            k: FileRecord.from_dict(v) for k, v in data.get("files", {}).items()
        }
        return manifest


