# ─── Validation Helpers ──────────────────────────────────────────────────────

class ConfigValidationError(Exception):
    """Raised when config values are invalid."""
    def __init__(self, section: str, key: str, message: str) -> None:
        self.section = section
        self.key = key
        super().__init__(f"[{section}].{key}: {message}")


def _parse_list(value: str) -> list[str]:
    """Split comma-separated string into a stripped, non-empty list."""
    return [item.strip() for item in value.split(",") if item.strip()]


def _parse_bool(value: str) -> bool:
    if value.lower() in ("true", "yes", "1", "on"):
        return True
    if value.lower() in ("false", "no", "0", "off"):
        return False
    raise ValueError(f"Cannot interpret {value!r} as boolean")


# ─── Config Parser ───────────────────────────────────────────────────────────

class BackupConfigParser:
    """
    Parses an INI-style config file into a validated BackupConfig.

    Usage:
        parser = BackupConfigParser("backup.conf")
        config = parser.parse()
    """

    # Defaults applied when a key is missing from the file
    DEFAULTS: dict[str, dict[str, str]] = {
        "general": {
            "backup_name": "default_backup",
            "log_level": "INFO",
            "backup_type": "incremental",
            "compression": "gzip",
            "max_workers": "4",
        },
        "source": {
            "directories": ".",
            "exclude_patterns": "",
            "follow_symlinks": "false",
            "max_file_size_mb": "0",
        },
        "destination": {
            "path": "./backups",
            "manifest_file": ".backup_manifest.json",
            "max_incremental_chain": "7",
        },
        "schedule": {
            "cron_expression": "0 2 * * *",
            "full_backup_day": "6",
        },
        "retention": {
            "keep_full_backups": "4",
            "keep_incremental_days": "30",
            "min_free_space_gb": "10",
        },
        "notifications": {
            "enabled": "false",
            "email": "",
            "notify_on_success": "false",
            "notify_on_failure": "true",
        },
    }

    def __init__(self, config_path: str | Path) -> None:
        self.config_path = Path(config_path)
        self._cp = configparser.ConfigParser(
            interpolation=configparser.ExtendedInterpolation(),
        )
        # Preserve key casing
        self._cp.optionxform = str  # type: ignore[assignment]

    # ── public API ────────────────────────────────────────────────────────

    def parse(self) -> BackupConfig:
        """Read, merge defaults, validate, and return a BackupConfig."""
        self._read_file()
        self._apply_defaults()
        return self._build_config()

    # ── internals ─────────────────────────────────────────────────────────

    def _read_file(self) -> None:
        if not self.config_path.exists():
            raise FileNotFoundError(f"Config file not found: {self.config_path}")
        with open(self.config_path) as fh:
            self._cp.read_file(fh)

    def _apply_defaults(self) -> None:
        for section, defaults in self.DEFAULTS.items():
            if not self._cp.has_section(section):
                self._cp.add_section(section)
            for key, value in defaults.items():
                if not self._cp.has_option(section, key):
                    self._cp.set(section, key, value)

    def _get(self, section: str, key: str) -> str:
        return self._cp.get(section, key).strip()

    def _get_int(self, section: str, key: str) -> int:
        raw = self._get(section, key)
        try:
            return int(raw)
        except ValueError:
            raise ConfigValidationError(section, key, f"expected integer, got {raw!r}")

    def _get_float(self, section: str, key: str) -> float:
        raw = self._get(section, key)
        try:
            return float(raw)
        except ValueError:
            raise ConfigValidationError(section, key, f"expected float, got {raw!r}")

    def _get_bool(self, section: str, key: str) -> bool:
        raw = self._get(section, key)
        try:
            return _parse_bool(raw)
        except ValueError:
            raise ConfigValidationError(section, key, f"expected boolean, got {raw!r}")

    def _get_enum(self, section: str, key: str, enum_cls: type[Enum]) -> Enum:
        raw = self._get(section, key).lower()
        try:
            return enum_cls(raw)
        except ValueError:
            valid = ", ".join(e.value for e in enum_cls)
            raise ConfigValidationError(
                section, key, f"{raw!r} not in ({valid})"
            )

    def _build_config(self) -> BackupConfig:
        source = SourceConfig(
            directories=_parse_list(self._get("source", "directories")),
            exclude_patterns=_parse_list(self._get("source", "exclude_patterns")),
            follow_symlinks=self._get_bool("source", "follow_symlinks"),
            max_file_size_bytes=self._get_int("source", "max_file_size_mb") * 1024 * 1024,
        )
        self._validate_source(source)

        destination = DestinationConfig(
            path=self._get("destination", "path"),
            manifest_file=self._get("destination", "manifest_file"),
            max_incremental_chain=self._get_int("destination", "max_incremental_chain"),
        )

        schedule = ScheduleConfig(
            cron_expression=self._get("schedule", "cron_expression"),
            full_backup_day=self._get_int("schedule", "full_backup_day"),
        )
        if not 0 <= schedule.full_backup_day <= 6:
            raise ConfigValidationError(
                "schedule", "full_backup_day", "must be 0-6 (Mon-Sun)"
            )

        retention = RetentionConfig(
            keep_full_backups=self._get_int("retention", "keep_full_backups"),
            keep_incremental_days=self._get_int("retention", "keep_incremental_days"),
            min_free_space_gb=self._get_float("retention", "min_free_space_gb"),
        )

        notifications = NotificationConfig(
            enabled=self._get_bool("notifications", "enabled"),
            email=self._get("notifications", "email"),
            notify_on_success=self._get_bool("notifications", "notify_on_success"),
            notify_on_failure=self._get_bool("notifications", "notify_on_failure"),
        )

        return BackupConfig(
            backup_name=self._get("general", "backup_name"),
            log_level=self._get("general", "log_level").upper(),
            backup_type=self._get_enum("general", "backup_type", BackupType),  # type: ignore[arg-type]
            compression=self._get_enum("general", "compression", CompressionType),  # type: ignore[arg-type]
            max_workers=self._get_int("general", "max_workers"),
            source=source,
            destination=destination,
            schedule=schedule,
            retention=retention,
            notifications=notifications,
        )

    @staticmethod
    def _validate_source(source: SourceConfig) -> None:
        for d in source.directories:
            if not Path(d).is_dir():
                logger.warning("Source directory does not exist yet: %s", d)


# ─── Manifest Manager ────────────────────────────────────────────────────────

class ManifestManager:
    """Loads, saves, and queries the backup manifest (JSON on disk)."""

    def __init__(self, config: BackupConfig) -> None:
        self.config = config
        self.manifest_path = (
            Path(config.destination.path) / config.destination.manifest_file
        )

    def load(self) -> BackupManifest:
        if self.manifest_path.exists():
            with open(self.manifest_path) as fh:
                data = json.load(fh)
            logger.info("Loaded manifest with %d file records", len(data.get("files", {})))
            return BackupManifest.from_dict(data)
        logger.info("No existing manifest — starting fresh")
        return BackupManifest(backup_name=self.config.backup_name)

    def save(self, manifest: BackupManifest) -> None:
        self.manifest_path.parent.mkdir(parents=True, exist_ok=True)
        tmp = self.manifest_path.with_suffix(".tmp")
        with open(tmp, "w") as fh:
            json.dump(manifest.to_dict(), fh, indent=2)
        tmp.replace(self.manifest_path)  # atomic on POSIX
        logger.info("Saved manifest (%d files)", len(manifest.files))


# ─── Change Detector ─────────────────────────────────────────────────────────

class ChangeDetector:
    """
    Walks source directories and compares against the manifest
    to find new, modified, and deleted files.
    """

    CHUNK_SIZE = 8192

    def __init__(self, config: BackupConfig, manifest: BackupManifest) -> None:
        self.config = config
        self.manifest = manifest

    # ── public ────────────────────────────────────────────────────────────

    def detect_changes(self) -> dict[str, FileStatus]:
        """Return {filepath: FileStatus} for every relevant file."""
        current_files = self._scan_sources()
        changes: dict[str, FileStatus] = {}

        for path, (size, mtime) in current_files.items():
            record = self.manifest.files.get(path)
            if record is None:
                changes[path] = FileStatus.NEW
            elif mtime != record.mtime or size != record.size:
                changes[path] = FileStatus.MODIFIED
            else:
                changes[path] = FileStatus.UNCHANGED

        # Detect deletions
        for path in self.manifest.files:
            if path not in current_files:
                changes[path] = FileStatus.DELETED

        return changes

    # ── internals ─────────────────────────────────────────────────────────

    def _scan_sources(self) -> dict[str, tuple[int, float]]:
        """Walk all source dirs, returning {path: (size, mtime)}."""
        result: dict[str, tuple[int, float]] = {}

        for directory in self.config.source.directories:
            dir_path = Path(directory)
            if not dir_path.is_dir():
                continue
            for entry in dir_path.rglob("*"):
                if not entry.is_file(follow_symlinks=self.config.source.follow_symlinks):
                    continue
                rel = str(entry)
                if self._is_excluded(rel):
                    continue
                stat = entry.stat(follow_symlinks=self.config.source.follow_symlinks)
                if (
                    self.config.source.max_file_size_bytes > 0
                    and stat.st_size > self.config.source.max_file_size_bytes
                ):
                    logger.debug("Skipping large file: %s (%d bytes)", rel, stat.st_size)
                    continue
                result[rel] = (stat.st_size, stat.st_mtime)

        return result

