package com.parser.model;

import java.util.List;
import java.util.Map;

public class Document {

    private String title;
    private String author;
    private double version;
    private boolean published;
    private List<String> tags;
    private Map<String, Object> metadata;
    private List<Section> sections;

    // --- Inner class for sections ---
    public static class Section {
        private String heading;
        private String content;

        // Getters & Setters
        public String getHeading()                  { return heading; }
        public void setHeading(String heading)      { this.heading = heading; }
        public String getContent()                  { return content; }
        public void setContent(String content)      { this.content = content; }

        @Override
        public String toString() {
            return String.format("  [%s]: %s", heading, content);
        }
    }

    // --- Getters & Setters ---
    public String getTitle()                        { return title; }
    public void setTitle(String title)              { this.title = title; }

    public String getAuthor()                       { return author; }
    public void setAuthor(String author)            { this.author = author; }

    public double getVersion()                      { return version; }
    public void setVersion(double version)          { this.version = version; }

    public boolean isPublished()                    { return published; }
    public void setPublished(boolean published)     { this.published = published; }

    public List<String> getTags()                   { return tags; }
    public void setTags(List<String> tags)          { this.tags = tags; }

    public Map<String, Object> getMetadata()        { return metadata; }
    public void setMetadata(Map<String, Object> m)  { this.metadata = m; }

    public List<Section> getSections()              { return sections; }
    public void setSections(List<Section> sections) { this.sections = sections; }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("=== Document ===\n");
        sb.append("Title:     ").append(title).append("\n");
        sb.append("Author:    ").append(author).append("\n");
        sb.append("Version:   ").append(version).append("\n");
        sb.append("Published: ").append(published).append("\n");
        sb.append("Tags:      ").append(tags).append("\n");
        sb.append("Metadata:  ").append(metadata).append("\n");
        sb.append("Sections:\n");
        if (sections != null) {
            sections.forEach(s -> sb.append(s).append("\n"));
        }
        return sb.toString();
    }
}
