## JSON Parser (`JsonDocumentParser.java`)
```java
package com.parser;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.parser.model.Document;

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class JsonDocumentParser {

    private final ObjectMapper mapper;

    public JsonDocumentParser() {
        this.mapper = new ObjectMapper();
        this.mapper.enable(SerializationFeature.INDENT_OUTPUT);
    }

    // -------------------------------------------------------
    // 1) Parse JSON file → POJO (typed object)
    // -------------------------------------------------------
    public Document parseFile(String filePath) throws IOException {
        File file = new File(filePath);
        return mapper.readValue(file, Document.class);
    }

    // -------------------------------------------------------
    // 2) Parse JSON string → POJO
    // -------------------------------------------------------
    public Document parseString(String json) throws IOException {
        return mapper.readValue(json, Document.class);
    }

    // -------------------------------------------------------
    // 3) Parse JSON file → generic tree (JsonNode)
    //    Useful when structure is unknown
    // -------------------------------------------------------
    public JsonNode parseToTree(String filePath) throws IOException {
        String content = Files.readString(Path.of(filePath));
        return mapper.readTree(content);
    }

    // -------------------------------------------------------
    // 4) Parse JSON → Map (untyped)
    // -------------------------------------------------------
    @SuppressWarnings("unchecked")
    public Map<String, Object> parseToMap(String json) throws IOException {
        return mapper.readValue(json, Map.class);
    }

    // -------------------------------------------------------
    // 5) Convert POJO back → JSON string
    // -------------------------------------------------------
    public String toJson(Document document) throws IOException {
        return mapper.writeValueAsString(document);
    }

    // -------------------------------------------------------
    // 6) Extract a specific field from JSON tree
    // -------------------------------------------------------
    public Optional<String> extractField(JsonNode root, String fieldName) {
        JsonNode node = root.get(fieldName);
        if (node != null && !node.isNull()) {
            return Optional.of(node.asText());
        }
        return Optional.empty();
    }

    // -------------------------------------------------------
    // 7) Extract nested field using path (e.g. "metadata.department")
    // -------------------------------------------------------
    public Optional<String> extractNestedField(JsonNode root, String path) {
        String[] parts = path.split("\\.");
        JsonNode current = root;

        for (String part : parts) {
            if (current == null) return Optional.empty();
            current = current.get(part);
        }

        return (current != null && !current.isNull())
                ? Optional.of(current.asText())
                : Optional.empty();
    }
}
```

