```java
package com.parser;

import com.fasterxml.jackson.databind.JsonNode;
import com.parser.model.Document;

import java.io.IOException;
import java.util.Map;

public class Main {

    public static void main(String[] args) {

        JsonDocumentParser parser = new JsonDocumentParser();

        // --- Sample JSON string (inline) ---
        String jsonInput = """
            {
              "title": "Project Report",
              "author": "Jane Smith",
              "version": 2.1,
              "published": true,
              "tags": ["java", "parsing", "json"],
              "metadata": {
                "createdDate": "2024-01-15",
                "department": "Engineering",
                "pageCount": 42
              },
              "sections": [
                {
                  "heading": "Introduction",
                  "content": "This document covers JSON parsing in Java."
                },
                {
                  "heading": "Implementation",
                  "content": "We use Jackson library for parsing."
                }
              ]
            }
            """;

        try {
            // ============================
            // 1. Parse JSON → POJO
            // ============================
            System.out.println("========== 1. PARSE TO POJO ==========");
            Document doc = parser.parseString(jsonInput);
            System.out.println(doc);

            // Access individual fields
            System.out.println("Title:  " + doc.getTitle());
            System.out.println("Author: " + doc.getAuthor());
            System.out.println("Tags:   " + doc.getTags());
            System.out.println();

            // ============================
            // 2. Parse JSON → Tree (JsonNode)
            // ============================
            System.out.println("========== 2. PARSE TO TREE ==========");
            JsonNode tree = parser.parseToMap_asTree(jsonInput);
            System.out.println("Root fields: ");
            tree.fieldNames().forEachRemaining(f ->
                System.out.println("  - " + f + " : " + tree.get(f).getNodeType())
            );
            System.out.println();

            // ============================
            // 3. Extract specific fields
            // ============================
            System.out.println("========== 3. EXTRACT FIELDS ==========");
            parser.extractField(tree, "title")
                  .ifPresent(val -> System.out.println("Title: " + val));

            parser.extractNestedField(tree, "metadata.department")
                  .ifPresent(val -> System.out.println("Department: " + val));

            parser.extractNestedField(tree, "metadata.pageCount")
                  .ifPresent(val -> System.out.println("Pages: " + val));
            System.out.println();

            // ============================
            // 4. Parse JSON → Map
            // ============================
            System.out.println("========== 4. PARSE TO MAP ==========");
            Map<String, Object> map = parser.parseToMap(jsonInput);
            map.forEach((key, value) ->
                System.out.println("  " + key + " → " + value)
            );
            System.out.println();

            // ============================
            // 5. Convert POJO → JSON
            // ============================
            System.out.println("========== 5. POJO BACK TO JSON ==========");
            String output = parser.toJson(doc);
            System.out.println(output);

            // ============================
            // 6. Parse from file (if exists)
            // ============================
            System.out.println("========== 6. PARSE FROM FILE ==========");
            try {
                Document fileDoc = parser.parseFile("src/main/resources/sample.json");
                System.out.println("Loaded from file: " + fileDoc.getTitle());
            } catch (IOException e) {
                System.out.println("File not found — skipping file parse demo.");
            }

        } catch (IOException e) {
            System.err.println("Error parsing JSON: " + e.getMessage());
            e.printStackTrace();
        }
    }
}
