## `parser.py` — Core Parsing Module

```python
"""
Simple document parser supporting JSON, CSV, TOML-like config, and plain text.
"""

from __future__ import annotations

import csv
import json
import re
import io
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any


# ──────────────────────────── Data Models ────────────────────────────

@dataclass
class ParsedDocument:
    """Uniform result returned by every parser."""
    source: str                          # filename or "<string>"
    format: str                          # "json", "csv", "config", "text"
    data: Any = None                     # parsed payload
    metadata: dict[str, Any] = field(default_factory=dict)

    @property
    def is_empty(self) -> bool:
        if self.data is None:
            return True
        if isinstance(self.data, (list, dict, str)) and len(self.data) == 0:
            return True
        return False


# ──────────────────────────── Base Class ─────────────────────────────

class BaseParser(ABC):
    """Abstract base for all format-specific parsers."""

    format_name: str = "base"

    @abstractmethod
    def parse_string(self, text: str, source: str = "<string>") -> ParsedDocument:
        ...

    def parse_file(self, path: str | Path) -> ParsedDocument:
        path = Path(path)
        if not path.exists():
            raise FileNotFoundError(f"File not found: {path}")
        text = path.read_text(encoding="utf-8")
        return self.parse_string(text, source=str(path))


# ──────────────────────────── JSON Parser ────────────────────────────

class JSONParser(BaseParser):
    format_name = "json"

    def parse_string(self, text: str, source: str = "<string>") -> ParsedDocument:
        text = text.strip()
        if not text:
            return ParsedDocument(source=source, format=self.format_name, data=None)
        try:
            data = json.loads(text)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid JSON in {source}: {exc}") from exc

        metadata: dict[str, Any] = {"type": type(data).__name__}
        if isinstance(data, list):
            metadata["item_count"] = len(data)
        elif isinstance(data, dict):
            metadata["keys"] = list(data.keys())

        return ParsedDocument(source=source, format=self.format_name,
                              data=data, metadata=metadata)


# ──────────────────────────── CSV Parser ─────────────────────────────

class CSVParser(BaseParser):
    format_name = "csv"

    def __init__(self, delimiter: str = ",", has_header: bool = True) -> None:
        self.delimiter = delimiter
        self.has_header = has_header

    def parse_string(self, text: str, source: str = "<string>") -> ParsedDocument:
        text = text.strip()
        if not text:
            return ParsedDocument(source=source, format=self.format_name, data=[])

        reader = csv.reader(io.StringIO(text), delimiter=self.delimiter)
        rows = list(reader)

        if self.has_header and rows:
            headers = [h.strip() for h in rows[0]]
            data = [dict(zip(headers, row)) for row in rows[1:]]
            metadata = {"headers": headers, "row_count": len(data)}
        else:
            data = rows
            metadata = {"row_count": len(data)}

        return ParsedDocument(source=source, format=self.format_name,
                              data=data, metadata=metadata)


# ──────────────────────── Key-Value Config ───────────────────────────

class ConfigParser(BaseParser):
    """Parses simple `key = value` config files (with optional [sections])."""

    format_name = "config"

    _SECTION_RE = re.compile(r"^\[(?P<section>[^\]]+)\]$")
    _KV_RE = re.compile(r"^(?P<key>[^=]+?)=(?P<value>.*)$")  # fixed: removed \s* around =

    def parse_string(self, text: str, source: str = "<string>") -> ParsedDocument:
        data: dict[str, Any] = {}
        current_section: str | None = None

        for lineno, raw_line in enumerate(text.splitlines(), start=1):
            line = raw_line.strip()
            if not line or line.startswith("#") or line.startswith(";"):
                continue

            section_match = self._SECTION_RE.match(line)
            if section_match:
                current_section = section_match.group("section").strip()
                data.setdefault(current_section, {})
                continue

            kv_match = self._KV_RE.match(line)
            if kv_match:
                key = kv_match.group("key").strip()
                value = self._cast_value(kv_match.group("value").strip())
                if current_section:
                    data[current_section][key] = value
                else:
                    data[key] = value
                continue

            raise ValueError(f"Syntax error at {source}:{lineno} → {raw_line!r}")

        sections = [k for k, v in data.items() if isinstance(v, dict)]
        metadata = {"sections": sections}

        return ParsedDocument(source=source, format=self.format_name,
                              data=data, metadata=metadata)

    @staticmethod
    def _cast_value(raw: str) -> str | int | float | bool | None:
        if raw.lower() in ("true", "yes"):
            return True
        if raw.lower() in ("false", "no"):
            return False
        if raw.lower() in ("null", "none", ""):
            return None
        try:
            return int(raw)
        except ValueError:
            pass
        try:
            return float(raw)
        except ValueError:
            pass
        # Strip surrounding quotes
        if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in ('"', "'"):
            return raw[1:-1]
        return raw


# ──────────────────────── Plain-Text Parser ──────────────────────────

class TextParser(BaseParser):
    format_name = "text"

    def parse_string(self, text: str, source: str = "<string>") -> ParsedDocument:
        lines = text.splitlines()
        words = text.split()
        metadata = {
            "line_count": len(lines),
            "word_count": len(words),
            "char_count": len(text),
        }
        return ParsedDocument(source=source, format=self.format_name,
                              data=text, metadata=metadata)


# ──────────────────────── Factory / Registry ─────────────────────────

_EXTENSION_MAP: dict[str, type[BaseParser]] = {
    ".json": JSONParser,
    ".csv":  CSVParser,
    ".tsv":  CSVParser,   # handled via delimiter below
    ".cfg":  ConfigParser,
    ".conf": ConfigParser,
    ".ini":  ConfigParser,
    ".txt":  TextParser,
    ".md":   TextParser,
}


def get_parser(filename: str) -> BaseParser:
    """Return the right parser based on file extension."""
    ext = Path(filename).suffix.lower()
    parser_cls = _EXTENSION_MAP.get(ext)
    if parser_cls is None:
        raise ValueError(f"No parser registered for extension '{ext}'")
    if ext == ".tsv":
        return CSVParser(delimiter="\t")
    return parser_cls()


def parse_file(path: str | Path) -> ParsedDocument:
    """One-liner convenience: detect format → parse → return."""
    path = Path(path)
    parser = get_parser(path.name)
    return parser.parse_file(path)
```

