// src/retry/strategies.js

/**
 * Backoff strategies for retry policies
 */
export const BackoffStrategy = Object.freeze({
  FIXED: 'fixed',
  LINEAR: 'linear',
  EXPONENTIAL: 'exponential',
  EXPONENTIAL_WITH_JITTER: 'exponential_with_jitter',
  DECORRELATED_JITTER: 'decorrelated_jitter',
});

/**
 * Calculate delay based on strategy
 * @param {string} strategy - Backoff strategy name
 * @param {number} attempt - Current attempt number (0-indexed)
 * @param {object} options - Strategy options
 * @returns {number} Delay in milliseconds
 */
export function calculateDelay(strategy, attempt, options = {}) {
  const {
    baseDelay = 1000,
    maxDelay = 30000,
    multiplier = 2,
    jitterFactor = 0.5,
  } = options;

  let delay;

  switch (strategy) {
    case BackoffStrategy.FIXED:
      delay = baseDelay;
      break;

    case BackoffStrategy.LINEAR:
      delay = baseDelay * (attempt + 1);
      break;

    case BackoffStrategy.EXPONENTIAL:
      delay = baseDelay * Math.pow(multiplier, attempt);
      break;

    case BackoffStrategy.EXPONENTIAL_WITH_JITTER: {
      const exponentialDelay = baseDelay * Math.pow(multiplier, attempt);
      const jitter = exponentialDelay * jitterFactor * Math.random();
      delay = exponentialDelay + jitter;
      break;
    }

    case BackoffStrategy.DECORRELATED_JITTER: {
      // AWS-style decorrelated jitter
      const prevDelay = attempt === 0
        ? baseDelay
        : baseDelay * Math.pow(multiplier, attempt - 1);
      delay = Math.min(maxDelay, random(baseDelay, prevDelay * 3));
      break;
    }

    default:
      delay = baseDelay;
  }

  return Math.min(delay, maxDelay);
}

function random(min, max) {
  return min + Math.random() * (max - min);
}

/**
 * Predefined error classifiers
 */
export const ErrorClassifier = {
  isRetryable(error) {
    // Network errors
    if (error.code === 'ECONNRESET' || error.code === 'ECONNREFUSED') return true;
    if (error.code === 'ETIMEDOUT' || error.code === 'EPIPE') return true;

    // HTTP status codes
    if (error.statusCode) {
      return [408, 429, 500, 502, 503, 504].includes(error.statusCode);
    }

    // Specific error types
    if (error.name === 'TimeoutError') return true;
    if (error.name === 'ThrottlingError') return true;

    return false;
  },

  isThrottled(error) {
    return error.statusCode === 429 || error.name === 'ThrottlingError';
  },

  isFatal(error) {
    if (error.statusCode) {
      return [400, 401, 403, 404, 422].includes(error.statusCode);
    }
    if (error.name === 'ValidationError') return true;
    if (error.name === 'AuthenticationError') return true;
    return false;
  },
};
