// src/retry/RetryPolicy.js

import { calculateDelay, BackoffStrategy, ErrorClassifier } from './strategies.js';
import { Logger } from '../utils/Logger.js';
import { Metrics } from '../utils/Metrics.js';

/**
 * Production-grade retry policy with configurable strategies,
 * circuit breaking integration, and observability
 */
export class RetryPolicy {
  #config;
  #logger;
  #metrics;

  /**
   * @param {object} config
   * @param {number} config.maxRetries - Maximum retry attempts
   * @param {string} config.strategy - Backoff strategy
   * @param {number} config.baseDelay - Base delay in ms
   * @param {number} config.maxDelay - Maximum delay in ms
   * @param {number} config.timeout - Per-attempt timeout in ms
   * @param {Function} config.retryIf - Custom retry predicate
   * @param {Function} config.onRetry - Retry callback hook
   * @param {Function} config.onExhausted - Called when retries exhausted
   * @param {AbortSignal} config.signal - Abort signal for cancellation
   */
  constructor(config = {}) {
    this.#config = {
      maxRetries: 3,
      strategy: BackoffStrategy.EXPONENTIAL_WITH_JITTER,
      baseDelay: 1000,
      maxDelay: 30000,
      multiplier: 2,
      jitterFactor: 0.5,
      timeout: 30000,
      retryIf: ErrorClassifier.isRetryable,
      onRetry: null,
      onExhausted: null,
      signal: null,
      ...config,
    };

    this.#logger = Logger.create('RetryPolicy');
    this.#metrics = Metrics.instance();
  }

  /**
   * Execute an operation with retry logic
   * @param {Function} operation - Async function to execute
   * @param {object} context - Context metadata for logging/metrics
   * @returns {Promise<*>} Operation result
   */
  async execute(operation, context = {}) {
    const operationId = context.operationId || crypto.randomUUID();
    let lastError;

    for (let attempt = 0; attempt <= this.#config.maxRetries; attempt++) {
      // Check for abort signal
      if (this.#config.signal?.aborted) {
        throw new RetryAbortedError('Operation aborted', { cause: this.#config.signal.reason });
      }

      try {
        const result = await this.#executeWithTimeout(operation, attempt, context);

        // Record success metrics
        if (attempt > 0) {
          this.#metrics.increment('retry.success_after_retry', {
            attempt,
            operation: context.operation || 'unknown',
          });
        }

        return result;
      } catch (error) {
        lastError = error;

        const shouldRetry = attempt < this.#config.maxRetries
          && this.#config.retryIf(error)
          && !this.#config.signal?.aborted;

        this.#logger.warn('Operation failed', {
          operationId,
          attempt: attempt + 1,
          maxRetries: this.#config.maxRetries,
          willRetry: shouldRetry,
          error: error.message,
          errorCode: error.code || error.statusCode,
          ...context,
        });

        this.#metrics.increment('retry.attempt', {
          attempt,
          retryable: shouldRetry,
          errorType: error.name,
          operation: context.operation || 'unknown',
        });

        if (!shouldRetry) break;

        // Calculate and apply delay
        const delay = this.#getDelay(attempt, error);

        this.#logger.debug('Waiting before retry', {
          operationId,
          delayMs: delay,
          nextAttempt: attempt + 2,
        });

        // Invoke retry hook
        if (this.#config.onRetry) {
          await this.#config.onRetry({ attempt, error, delay, context });
        }

        await this.#sleep(delay);
      }
    }

    // All retries exhausted
    this.#metrics.increment('retry.exhausted', {
      operation: context.operation || 'unknown',
      errorType: lastError.name,
    });

    if (this.#config.onExhausted) {
      await this.#config.onExhausted({ error: lastError, context });
    }

    throw new RetryExhaustedError(
      `All ${this.#config.maxRetries} retries exhausted`,
      { cause: lastError, attempts: this.#config.maxRetries + 1, context }
    );
  }

  /**
   * Execute with per-attempt timeout
   */
  async #executeWithTimeout(operation, attempt, context) {
    if (!this.#config.timeout) {
      return operation(attempt, context);
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.#config.timeout);

    try {
      return await operation(attempt, { ...context, signal: controller.signal });
    } finally {
      clearTimeout(timeoutId);
    }
  }

  /**
   * Calculate delay, with special handling for throttled responses
   */
  #getDelay(attempt, error) {
    // Respect Retry-After header
    if (error.retryAfter) {
      const retryAfterMs = typeof error.retryAfter === 'number'
        ? error.retryAfter * 1000
        : Date.parse(error.retryAfter) - Date.now();
      if (retryAfterMs > 0) {
        return Math.min(retryAfterMs, this.#config.maxDelay);
      }
    }

    // Increase base delay for throttled errors
    const options = { ...this.#config };
    if (ErrorClassifier.isThrottled(error)) {
      options.baseDelay = options.baseDelay * 2;
    }

    return calculateDelay(this.#config.strategy, attempt, options);
  }

  /**
   * Abortable sleep
   */
  #sleep(ms) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, ms);

      this.#config.signal?.addEventListener('abort', () => {
        clearTimeout(timer);
        reject(new RetryAbortedError('Retry aborted during backoff'));
      }, { once: true });
    });
  }

  /**
   * Create a wrapped version of a function with retry
   */
  wrap(fn) {
    const policy = this;
    return function retryableWrapper(...args) {
      return policy.execute(() => fn.apply(this, args), {
        operation: fn.name || 'anonymous',
      });
    };
  }
}

// Custom error classes
export class RetryExhaustedError extends Error {
  constructor(message, { cause, attempts, context } = {}) {
    super(message, { cause });
    this.name = 'RetryExhaustedError';
    this.attempts = attempts;
    this.context = context;
  }
}

export class RetryAbortedError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'RetryAbortedError';
  }
}
