## Circuit Breaker

```javascript
// src/retry/CircuitBreaker.js

import { Logger } from '../utils/Logger.js';
import { Metrics } from '../utils/Metrics.js';
import { EventBus } from '../utils/EventBus.js';

/**
 * Circuit breaker states
 */
const State = Object.freeze({
  CLOSED: 'closed',       // Normal operation
  OPEN: 'open',           // Failing, reject fast
  HALF_OPEN: 'half_open', // Testing recovery
});

/**
 * Circuit breaker to prevent cascading failures.
 * Uses a sliding window for failure rate tracking.
 */
export class CircuitBreaker {
  #name;
  #config;
  #state;
  #failureWindow;
  #successCount;
  #failureCount;
  #lastFailureTime;
  #halfOpenAttempts;
  #logger;
  #metrics;
  #eventBus;

  constructor(name, config = {}) {
    this.#name = name;
    this.#config = {
      failureThreshold: 5,           // Failures to trip
      failureRateThreshold: 0.5,     // 50% failure rate to trip
      windowSize: 10,                // Sliding window size
      resetTimeout: 30000,           // ms before trying half-open
      halfOpenMaxAttempts: 3,        // Test requests in half-open
      monitorInterval: 5000,         // Health check interval
      ...config,
    };

    this.#state = State.CLOSED;
    this.#failureWindow = [];
    this.#successCount = 0;
    this.#failureCount = 0;
    this.#lastFailureTime = 0;
    this.#halfOpenAttempts = 0;
    this.#logger = Logger.create(`CircuitBreaker:${name}`);
    this.#metrics = Metrics.instance();
    this.#eventBus = EventBus.instance();
  }

  get state() {
    // Auto-transition from OPEN to HALF_OPEN
    if (
      this.#state === State.OPEN
      && Date.now() - this.#lastFailureTime >= this.#config.resetTimeout
    ) {
      this.#transitionTo(State.HALF_OPEN);
    }
    return this.#state;
  }

  get isAvailable() {
    return this.state !== State.OPEN;
  }

  get stats() {
    const total = this.#successCount + this.#failureCount;
    return {
      state: this.state,
      successCount: this.#successCount,
      failureCount: this.#failureCount,
      failureRate: total > 0 ? this.#failureCount / total : 0,
      windowFailures: this.#failureWindow.filter(Boolean).length,
      windowSize: this.#failureWindow.length,
    };
  }

  /**
   * Execute an operation through the circuit breaker
   */
  async execute(operation) {
    if (!this.isAvailable) {
      this.#metrics.increment('circuit_breaker.rejected', { name: this.#name });
      throw new CircuitOpenError(
        `Circuit breaker "${this.#name}" is OPEN`,
        { resetTimeout: this.#config.resetTimeout, stats: this.stats }
      );
    }

    try {
      const result = await operation();
      this.#recordSuccess();
      return result;
    } catch (error) {
      this.#recordFailure(error);
      throw error;
    }
  }

  /**
   * Wrap a function with circuit breaker protection
   */
  protect(fn) {
    const breaker = this;
    return function protectedWrapper(...args) {
      return breaker.execute(() => fn.apply(this, args));
    };
  }

  #recordSuccess() {
    this.#successCount++;
    this.#failureWindow.push(false);
    this.#trimWindow();

    this.#metrics.gauge('circuit_breaker.success_total', this.#successCount, {
      name: this.#name,
    });

    if (this.#state === State.HALF_OPEN) {
      this.#halfOpenAttempts++;
      if (this.#halfOpenAttempts >= this.#config.halfOpenMaxAttempts) {
        this.#transitionTo(State.CLOSED);
      }
    }
  }

  #recordFailure(error) {
    this.#failureCount++;
    this.#lastFailureTime = Date.now();
    this.#failureWindow.push(true);
    this.#trimWindow();

    this.#metrics.gauge('circuit_breaker.failure_total', this.#failureCount, {
      name: this.#name,
      errorType: error.name,
    });

    if (this.#state === State.HALF_OPEN) {
      this.#transitionTo(State.OPEN);
      return;
    }

    if (this.#shouldTrip()) {
      this.#transitionTo(State.OPEN);
    }
  }

  #shouldTrip() {
    if (this.#failureWindow.length < this.#config.windowSize) return false;

    const recentFailures = this.#failureWindow.filter(Boolean).length;
    const failureRate = recentFailures / this.#failureWindow.length;

    return (
      recentFailures >= this.#config.failureThreshold
      || failureRate >= this.#config.failureRateThreshold
    );
  }

  #trimWindow() {
    while (this.#failureWindow.length > this.#config.windowSize) {
      this.#failureWindow.shift();
    }
  }

  #transitionTo(newState) {
    const prevState = this.#state;
    this.#state = newState;

    if (newState === State.HALF_OPEN) {
      this.#halfOpenAttempts = 0;
    }

    if (newState === State.CLOSED) {
      this.#failureWindow = [];
    }

    this.#logger.info('State transition', {
      from: prevState,
      to: newState,
      stats: this.stats,
    });

    this.#metrics.gauge('circuit_breaker.state', stateToNumber(newState), {
      name: this.#name,
    });

    this.#eventBus.emit('circuit_breaker.transition', {
      name: this.#name,
      from: prevState,
      to: newState,
      stats: this.stats,
    });
  }

  reset() {
    this.#transitionTo(State.CLOSED);
    this.#successCount = 0;
    this.#failureCount = 0;
    this.#failureWindow = [];
  }
}

function stateToNumber(state) {
  return { [State.CLOSED]: 0, [State.HALF_OPEN]: 0.5, [State.OPEN]: 1 }[state];
}

export class CircuitOpenError extends Error {
  constructor(message, { resetTimeout, stats } = {}) {
    super(message);
    this.name = 'CircuitOpenError';
    this.resetTimeout = resetTimeout;
    this.stats = stats;
  }
}
