```javascript
import { EventEmitter } from 'events';
import logger from '../utils/logger.js';

/**
 * Categorizes errors to determine retry strategy.
 */
const ErrorCategory = Object.freeze({
  TRANSIENT: 'transient',       // Network blips, timeouts — always retry
  THROTTLE: 'throttle',         // Rate limits — retry with longer backoff
  PERMANENT: 'permanent',       // Bad data, auth failures — never retry
});

export { ErrorCategory };

/**
 * Production retry policy with exponential backoff, jitter,
 * per-error-category strategies, and full observability hooks.
 */
export default class RetryPolicy extends EventEmitter {
  #config;
  #retryableErrors;

  /**
   * @param {object} config
   * @param {number} config.maxAttempts
   * @param {number} config.baseDelayMs
   * @param {number} config.maxDelayMs
   * @param {number} config.backoffMultiplier
   * @param {number} config.jitterFactor
   * @param {string[]} config.retryableErrors
   */
  constructor(config) {
    super();
    this.#config = Object.freeze({ ...config });
    this.#retryableErrors = new Set(config.retryableErrors ?? []);
  }

  // ── public API ──────────────────────────────────────────

  /**
   * Execute `fn` with the configured retry policy.
   *
   * @template T
   * @param {() => Promise<T>} fn              – async work to execute
   * @param {object}           [ctx={}]        – arbitrary context for logging
   * @returns {Promise<{ result: T, attempts: number, totalDelayMs: number }>}
   */
  async execute(fn, ctx = {}) {
    const executionId = crypto.randomUUID();
    let lastError = null;
    let totalDelayMs = 0;

    for (let attempt = 1; attempt <= this.#config.maxAttempts; attempt++) {
      try {
        this.emit('attempt', { executionId, attempt, ctx });

        const result = await fn();

        this.emit('success', { executionId, attempt, totalDelayMs, ctx });
        return { result, attempts: attempt, totalDelayMs };
      } catch (error) {
        lastError = error;
        const category = this.#categorizeError(error);

        this.emit('error', {
          executionId,
          attempt,
          error,
          category,
          ctx,
        });

        // Permanent errors are never retried
        if (category === ErrorCategory.PERMANENT) {
          this.emit('permanent_failure', { executionId, error, attempt, ctx });
          throw new RetryExhaustedError(error, attempt, totalDelayMs);
        }

        // If we've used all attempts, bail out
        if (attempt === this.#config.maxAttempts) break;

        // Compute & apply delay
        const delayMs = this.#computeDelay(attempt, category);
        totalDelayMs += delayMs;

        this.emit('retry', {
          executionId,
          attempt,
          nextAttempt: attempt + 1,
          delayMs,
          category,
          ctx,
        });

        logger.warn({
          msg: 'Retrying operation',
          executionId,
          attempt,
          nextAttempt: attempt + 1,
          delayMs,
          category,
          errorMessage: error.message,
          errorCode: error.code,
          ...ctx,
        });

        await RetryPolicy.sleep(delayMs);
      }
    }

    this.emit('exhausted', {
      executionId,
      attempts: this.#config.maxAttempts,
      totalDelayMs,
      error: lastError,
      ctx,
    });

    throw new RetryExhaustedError(
      lastError,
      this.#config.maxAttempts,
      totalDelayMs,
    );
  }

  // ── internals ───────────────────────────────────────────

  /**
   * Map an error to a retry category.
   */
  #categorizeError(error) {
    if (error.permanent || error.statusCode === 400 || error.statusCode === 401) {
      return ErrorCategory.PERMANENT;
    }
    if (error.code === 'RATE_LIMITED' || error.statusCode === 429) {
      return ErrorCategory.THROTTLE;
    }
    if (this.#retryableErrors.has(error.code)) {
      return ErrorCategory.TRANSIENT;
    }
    if (error.statusCode >= 500) {
      return ErrorCategory.TRANSIENT;
    }
    // Default: treat unknown errors as permanent to avoid silent loops
    return ErrorCategory.PERMANENT;
  }

  /**
   * Exponential backoff with decorrelated jitter.
   * Throttle errors get a longer base delay.
   */
  #computeDelay(attempt, category) {
    const base =
      category === ErrorCategory.THROTTLE
        ? this.#config.baseDelayMs * 5
        : this.#config.baseDelayMs;

    const exponential = base * this.#config.backoffMultiplier ** (attempt - 1);
    const capped = Math.min(exponential, this.#config.maxDelayMs);

    // ±jitter
    const jitter = capped * this.#config.jitterFactor;
    const min = capped - jitter;
    const max = capped + jitter;
    return Math.round(min + Math.random() * (max - min));
  }

  /**
   * Awaitable delay — extracted as a static so tests can stub it.
   */
  static sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

/**
 * Thrown when all retry attempts are exhausted or a permanent error is hit.
 */
export class RetryExhaustedError extends Error {
  /**
   * @param {Error}  cause
   * @param {number} attempts
   * @param {number} totalDelayMs
   */
  constructor(cause, attempts, totalDelayMs) {
    super(
      `Retry exhausted after ${attempts} attempt(s) ` +
        `(${totalDelayMs}ms total delay): ${cause.message}`,
    );
    this.name = 'RetryExhaustedError';
    this.cause = cause;
    this.attempts = attempts;
    this.totalDelayMs = totalDelayMs;
  }
}
