import { EventEmitter } from 'events';
import logger from '../utils/logger.js';

const State = Object.freeze({
  CLOSED: 'CLOSED',
  OPEN: 'OPEN',
  HALF_OPEN: 'HALF_OPEN',
});

export { State };

/**
 * Circuit breaker that wraps an async function.
 *
 * CLOSED   → normal operation; failures are counted.
 * OPEN     → all calls rejected immediately (fail fast).
 * HALF_OPEN → limited probe traffic to test recovery.
 */
export default class CircuitBreaker extends EventEmitter {
  #name;
  #config;
  #state;
  #failureCount;
  #successCount;
  #halfOpenAttempts;
  #lastFailureTime;
  #resetTimer;

  constructor(name, config) {
    super();
    this.#name = name;
    this.#config = Object.freeze({ ...config });
    this.#state = State.CLOSED;
    this.#failureCount = 0;
    this.#successCount = 0;
    this.#halfOpenAttempts = 0;
    this.#lastFailureTime = null;
    this.#resetTimer = null;
  }

  get state() {
    return this.#state;
  }

  get stats() {
    return {
      name: this.#name,
      state: this.#state,
      failureCount: this.#failureCount,
      successCount: this.#successCount,
      lastFailureTime: this.#lastFailureTime,
    };
  }

  // ── public API ──────────────────────────────────────────

  /**
   * @template T
   * @param {() => Promise<T>} fn
   * @returns {Promise<T>}
   */
  async execute(fn) {
    // Fast-fail in OPEN state (unless reset timeout elapsed)
    if (this.#state === State.OPEN) {
      if (this.#shouldAttemptReset()) {
        this.#transitionTo(State.HALF_OPEN);
      } else {
        throw new CircuitOpenError(this.#name, this.#config.resetTimeoutMs);
      }
    }

    // Gate probe traffic in HALF_OPEN
    if (this.#state === State.HALF_OPEN) {
      if (this.#halfOpenAttempts >= this.#config.halfOpenMaxAttempts) {
        throw new CircuitOpenError(this.#name, this.#config.resetTimeoutMs);
      }
      this.#halfOpenAttempts++;
    }

    try {
      const result = await fn();
      this.#onSuccess();
      return result;
    } catch (error) {
      this.#onFailure(error);
      throw error;
    }
  }

  reset() {
    this.#transitionTo(State.CLOSED);
    this.#failureCount = 0;
    this.#successCount = 0;
    this.#halfOpenAttempts = 0;
    this.#lastFailureTime = null;
    clearTimeout(this.#resetTimer);
    this.#resetTimer = null;
  }

  destroy() {
    clearTimeout(this.#resetTimer);
    this.removeAllListeners();
  }

  // ── internals ───────────────────────────────────────────

  #onSuccess() {
    this.#successCount++;

    if (this.#state === State.HALF_OPEN) {
      // All probes passed → close the circuit
      logger.info({
        msg: 'Circuit breaker recovered',
        breaker: this.#name,
      });
      this.reset();
    }

    this.#failureCount = 0;
  }

  #onFailure(error) {
    this.#failureCount++;
    this.#lastFailureTime = Date.now();

    if (this.#state === State.HALF_OPEN) {
      // Probe failed → reopen
      this.#transitionTo(State.OPEN);
      this.#scheduleReset();
      return;
    }

    if (this.#failureCount >= this.#config.failureThreshold) {
      this.#transitionTo(State.OPEN);
      this.#scheduleReset();

      logger.error({
        msg: 'Circuit breaker opened',
        breaker: this.#name,
        failureCount: this.#failureCount,
        errorMessage: error.message,
      });
    }
  }

  #shouldAttemptReset() {
    return (
      this.#lastFailureTime &&
      Date.now() - this.#lastFailureTime >= this.#config.resetTimeoutMs
    );
  }

  #scheduleReset() {
    clearTimeout(this.#resetTimer);
    this.#resetTimer = setTimeout(() => {
      this.#transitionTo(State.HALF_OPEN);
      this.#halfOpenAttempts = 0;
    }, this.#config.resetTimeoutMs);

    // Allow process to exit even if timer is pending
    this.#resetTimer.unref?.();
  }

  #transitionTo(newState) {
    const prev = this.#state;
    this.#state = newState;
    this.emit('stateChange', { name: this.#name, from: prev, to: newState });
  }
}

export class CircuitOpenError extends Error {
  constructor(name, resetTimeoutMs) {
    super(
      `Circuit breaker "${name}" is OPEN — ` +
        `retry after ${resetTimeoutMs}ms`,
    );
    this.name = 'CircuitOpenError';
    this.breakerName = name;
    this.resetTimeoutMs = resetTimeoutMs;
  }
}
