import { EventEmitter } from 'events';
import logger from '../utils/logger.js';

/**
 * In-memory DLQ with optional Redis persistence.
 * Failed events land here for later inspection or replay.
 */
export default class DeadLetterQueue extends EventEmitter {
  #items;
  #maxSize;
  #redis;
  #redisKey;

  /**
   * @param {object}  config
   * @param {number}  config.maxSize
   * @param {object} [redis]           – ioredis instance (optional)
   * @param {string} [redisKey]
   */
  constructor(config, redis = null, redisKey = 'analytics:dlq') {
    super();
    this.#items = [];
    this.#maxSize = config.maxSize;
    this.#redis = redis;
    this.#redisKey = redisKey;
  }

  get size() {
    return this.#items.length;
  }

  /**
   * Enqueue a failed event with full diagnostic context.
   */
  async enqueue(event, error, context = {}) {
    const entry = {
      id: crypto.randomUUID(),
      event,
      error: {
        message: error.message,
        code: error.code,
        stack: error.stack,
      },
      context,
      enqueuedAt: new Date().toISOString(),
      retryCount: context.retryCount ?? 0,
    };

    // Evict oldest if at capacity
    if (this.#items.length >= this.#maxSize) {
      const evicted = this.#items.shift();
      this.emit('evicted', evicted);
      logger.warn({
        msg: 'DLQ at capacity — evicting oldest entry',
        evictedId: evicted.id,
      });
    }

    this.#items.push(entry);
    this.emit('enqueued', entry);

    // Optional persistence
    if (this.#redis) {
      try {
        await this.#redis.lpush(this.#redisKey, JSON.stringify(entry));
        await this.#redis.ltrim(this.#redisKey, 0, this.#maxSize - 1);
      } catch (err) {
        logger.error({
          msg: 'Failed to persist DLQ entry to Redis',
          error: err.message,
        });
      }
    }

    logger.error({
      msg: 'Event sent to dead-letter queue',
      dlqEntryId: entry.id,
      originalError: error.message,
      retryCount: entry.retryCount,
    });

    return entry;
  }

  /**
   * Drain all entries (e.g. for replay).
   */
  drain() {
    const entries = [...this.#items];
    this.#items.length = 0;
    return entries;
  }

  /**
   * Peek without removing.
   */
  peek(count = 10) {
    return this.#items.slice(0, count);
  }

  /**
   * Remove a specific entry by id.
   */
  remove(id) {
    const idx = this.#items.findIndex((e) => e.id === id);
    if (idx !== -1) {
      return this.#items.splice(idx, 1)[0];
    }
    return null;
  }

  async loadFromRedis() {
    if (!this.#redis) return;
    try {
      const raw = await this.#redis.lrange(this.#redisKey, 0, -1);
      this.#items = raw.map((r) => JSON.parse(r));
      logger.info({ msg: 'DLQ loaded from Redis', count: this.#items.length });
    } catch (err) {
      logger.error({ msg: 'Failed to load DLQ from Redis', error: err.message });
    }
  }
}
