import com.anthropic.AnthropicClient;
import com.anthropic.models.messages.*;

import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Duration;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;

public class FileSyncWithRetries {

    // --- Configuration ---
    record SyncConfig(
        int maxRetries,
        long initialBackoffMs,
        long maxBackoffMs,
        double backoffMultiplier,
        int maxConcurrentSyncs,
        long syncIntervalSeconds,
        Set<String> ignoredPatterns
    ) {
        static SyncConfig defaults() {
            return new SyncConfig(
                5,
                1000,
                30000,
                2.0,
                4,
                30,
                Set.of(".git", ".DS_Store", "thumbs.db", "*.tmp", "*.swp")
            );
        }
    }

    // --- File Metadata ---
    record FileMetadata(
        String relativePath,
        long size,
        long lastModified,
        String checksum
    ) {}

    // --- Sync Result ---
    enum SyncStatus { SUCCESS, FAILED, SKIPPED, CONFLICT }

    record SyncResult(
        String filePath,
        SyncStatus status,
        int attemptsUsed,
        String errorMessage,
        Duration duration
    ) {}

    record SyncReport(
        List<SyncResult> results,
        int totalFiles,
        int successCount,
        int failedCount,
        int skippedCount,
        int conflictCount,
        Duration totalDuration
    ) {
        String summary() {
            return String.format(
                "Sync Report: %d total | %d success | %d failed | %d skipped | %d conflicts | %s elapsed",
                totalFiles, successCount, failedCount, skippedCount, conflictCount, totalDuration
            );
        }
    }

    // --- Retry Strategy ---
    static class RetryStrategy {
        private final SyncConfig config;

        RetryStrategy(SyncConfig config) {
            this.config = config;
        }

        long calculateBackoff(int attempt) {
            long backoff = (long) (config.initialBackoffMs() * Math.pow(config.backoffMultiplier(), attempt));
            // Add jitter (±25%)
            long jitter = (long) (backoff * 0.25 * (ThreadLocalRandom.current().nextDouble() * 2 - 1));
            return Math.min(backoff + jitter, config.maxBackoffMs());
        }

        boolean shouldRetry(int attempt, Exception e) {
            if (attempt >= config.maxRetries()) return false;
            // Retry on IO errors but not on security or permission errors
            return e instanceof IOException && !(e instanceof java.nio.file.AccessDeniedException);
        }

        <T> T executeWithRetry(String operationName, Callable<T> operation) throws Exception {
            int attempt = 0;
            Exception lastException = null;

            while (true) {
                try {
                    return operation.call();
                } catch (Exception e) {
                    lastException = e;
                    if (!shouldRetry(attempt, e)) {
                        throw e;
                    }
                    long backoff = calculateBackoff(attempt);
                    System.out.printf("[RETRY] %s - attempt %d/%d, waiting %dms: %s%n",
                        operationName, attempt + 1, config.maxRetries(), backoff, e.getMessage());
                    Thread.sleep(backoff);
                    attempt++;
                }
            }
        }
    }

    // --- File Checksum Calculator ---
    static class ChecksumCalculator {
        static String computeSHA256(Path file) throws IOException, NoSuchAlgorithmException {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            try (InputStream is = new BufferedInputStream(Files.newInputStream(file))) {
                byte[] buffer = new byte[8192];
                int bytesRead;
                while ((bytesRead = is.read(buffer)) != -1) {
                    digest.update(buffer, 0, bytesRead);
                }
            }
            byte[] hash = digest.digest();
            StringBuilder hex = new StringBuilder();
            for (byte b : hash) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        }
    }

    // --- Conflict Resolver ---
    enum ConflictStrategy { SOURCE_WINS, DEST_WINS, NEWER_WINS, RENAME_BOTH }

    static class ConflictResolver {
        private final ConflictStrategy strategy;

        ConflictResolver(ConflictStrategy strategy) {
            this.strategy = strategy;
        }

        Path resolve(Path source, Path dest) throws IOException {
            return switch (strategy) {
                case SOURCE_WINS -> source;
                case DEST_WINS -> dest;
                case NEWER_WINS -> {
                    long srcMod = Files.getLastModifiedTime(source).toMillis();
                    long dstMod = Files.getLastModifiedTime(dest).toMillis();
                    yield srcMod >= dstMod ? source : dest;
                }
                case RENAME_BOTH -> {
                    String timestamp = String.valueOf(System.currentTimeMillis());
                    Path conflictCopy = dest.resolveSibling(
                        dest.getFileName() + ".conflict-" + timestamp
                    );
                    Files.copy(dest, conflictCopy, StandardCopyOption.REPLACE_EXISTING);
                    yield source;
                }
            };
        }
    }

    // --- File Synchronizer ---
    static class FileSynchronizer {
        private final Path sourceDir;
        private final Path destDir;
        private final SyncConfig config;
        private final RetryStrategy retryStrategy;
        private final ConflictResolver conflictResolver;
        private final ExecutorService executor;
        private final AtomicInteger activeCount = new AtomicInteger(0);

        FileSynchronizer(Path sourceDir, Path destDir, SyncConfig config, ConflictStrategy conflictStrategy) {
            this.sourceDir = sourceDir;
            this.destDir = destDir;
            this.config = config;
            this.retryStrategy = new RetryStrategy(config);
            this.conflictResolver = new ConflictResolver(conflictStrategy);
            this.executor = Executors.newFixedThreadPool(config.maxConcurrentSyncs());
        }

        boolean shouldIgnore(Path path) {
            String fileName = path.getFileName().toString();
            for (String pattern : config.ignoredPatterns()) {
                if (pattern.startsWith("*.")) {
                    String ext = pattern.substring(1);
                    if (fileName.endsWith(ext)) return true;
                } else if (fileName.equals(pattern)) {
                    return true;
                }
            }
            return false;
        }

        Map<String, FileMetadata> scanDirectory(Path dir) throws IOException {
            Map<String, FileMetadata> files = new ConcurrentHashMap<>();
            if (!Files.exists(dir)) return files;

            Files.walk(dir)
                .filter(Files::isRegularFile)
                .filter(p -> !shouldIgnore(p))
                .forEach(path -> {
                    try {
                        String relativePath = dir.relativize(path).toString();
                        String checksum = ChecksumCalculator.computeSHA256(path);
                        files.put(relativePath, new FileMetadata(
                            relativePath,
                            Files.size(path),
                            Files.getLastModifiedTime(path).toMillis(),
                            checksum
                        ));
                    } catch (Exception e) {
                        System.err.println("Error scanning file " + path + ": " + e.getMessage());
                    }
                });
            return files;
        }

        SyncResult syncFile(String relativePath, FileMetadata sourceMeta, FileMetadata destMeta) {
            Instant start = Instant.now();
            AtomicInteger attempts = new AtomicInteger(0);

            try {
                return retryStrategy.executeWithRetry("sync:" + relativePath, () -> {
                    attempts.incrementAndGet();
                    activeCount.incrementAndGet();
                    try {
                        Path srcFile = sourceDir.resolve(relativePath);
                        Path dstFile = destDir.resolve(relativePath);

                        // Check if file needs syncing
                        if (destMeta != null && sourceMeta.checksum().equals(destMeta.checksum())) {
                            return new SyncResult(relativePath, SyncStatus.SKIPPED, attempts.get(),
                                null, Duration.between(start, Instant.now()));
                        }

                        // Handle conflicts
                        if (destMeta != null && !sourceMeta.checksum().equals(destMeta.checksum())) {
                            Path winner = conflictResolver.resolve(srcFile, dstFile);
                            if (winner.equals(dstFile)) {
                                return new SyncResult(relativePath, SyncStatus.CONFLICT, attempts.get(),
                                    "Destination wins - kept destination version",
                                    Duration.between(start, Instant.now()));
                            }
                        }

                        // Ensure parent directories exist
                        Files.createDirectories(dstFile.getParent());

                        // Atomic copy using temp file
                        Path tempFile = dstFile.resolveSibling(
                            "." + dstFile.getFileName() + ".sync-tmp"
                        );
                        try {
                            Files.copy(srcFile, tempFile, StandardCopyOption.REPLACE_EXISTING,
                                StandardCopyOption.COPY_ATTRIBUTES);

                            // Verify integrity
                            String srcChecksum = ChecksumCalculator.computeSHA256(srcFile);
                            String tmpChecksum = ChecksumCalculator.computeSHA256(tempFile);
                            if (!srcChecksum.equals(tmpChecksum)) {
                                Files.deleteIfExists(tempFile);
                                throw new IOException("Checksum mismatch after copy for " + relativePath);
                            }

                            // Atomic move
                            Files.move(tempFile, dstFile,
                                StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);

                        } catch (Exception e) {
                            Files.deleteIfExists(tempFile);
                            throw e;
                        }

                        return new SyncResult(relativePath, SyncStatus.SUCCESS, attempts.get(),
                            null, Duration.between(start, Instant.now()));

                    } finally {
                        activeCount.decrementAndGet();
                    }
                });
            } catch (Exception e) {
                return new SyncResult(relativePath, SyncStatus.FAILED, attempts.get(),
                    e.getMessage(), Duration.between(start, Instant.now()));
            }
        }

        SyncReport synchronize() throws IOException, InterruptedException {
            Instant start = Instant.now();
            System.out.println("Starting file synchronization...");
            System.out.printf("Source: %s%nDestination: %s%n", sourceDir, destDir);

            // Scan both directories
            Map<String, FileMetadata> sourceFiles = scanDirectory(sourceDir);
            Map<String, FileMetadata> destFiles = scanDirectory(destDir);

            System.out.printf("Found %d source files, %d destination files%n",
                sourceFiles.size(), destFiles.size());

            // Determine files to sync
            Set<String> allFiles = new HashSet<>(sourceFiles.keySet());
            allFiles.addAll(destFiles.keySet());

            // Submit sync tasks
            List<Future<SyncResult>> futures = new ArrayList<>();
            for (String relativePath : allFiles) {
                FileMetadata srcMeta = sourceFiles.get(relativePath);
                FileMetadata dstMeta = destFiles.get(relativePath);

                if (srcMeta == null) {
                    // File only in destination - skip (or could delete)
                    continue;
                }

                futures.add(executor.submit(() -> syncFile(relativePath, srcMeta, dstMeta)));
            }

            // Collect results
            List<SyncResult> results = new ArrayList<>();
            for (Future<SyncResult> future : futures) {
                try {
                    results.add(future.get(60, TimeUnit.SECONDS));
                } catch (ExecutionException | TimeoutException e) {
                    results.add(new SyncResult("unknown", SyncStatus.FAILED, 0,
                        e.getMessage(), Duration.ZERO));
                }
            }

            Duration totalDuration = Duration.between(start, Instant.now());

            int successCount = (int) results.stream().filter(r -> r.status() == SyncStatus.SUCCESS).count();
            int failedCount = (int) results.stream().filter(r -> r.status() == SyncStatus.FAILED).count();
            int skippedCount = (int) results.stream().filter(r -> r.status() == SyncStatus.SKIPPED).count();
            int conflictCount = (int) results.stream().filter(r -> r.status() == SyncStatus.CONFLICT).count();

            return new SyncReport(results, results.size(), successCount, failedCount,
                skippedCount, conflictCount, totalDuration);
        }

        void shutdown() {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(30, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }

