## Architecture

```
Priority: struct defaults → JSON file → environment variables (highest)

Struct Tags:
  env:"VAR"          → environment variable name
  default:"value"    → fallback value  
  required:"true"    → fail if still zero after loading
  json:"key"         → JSON file key
```

## `config.go`

```go
// Package config loads structured configuration from defaults, JSON files,
// and environment variables with validation support.
//
// Values are loaded in the following priority order (highest wins):
//
//  1. Struct tag defaults
//  2. JSON configuration file
//  3. Environment variables
//
// Supported struct tags:
//
//	env:"NAME"         – environment variable to read
//	default:"value"    – fallback when no other source provides a value
//	required:"true"    – fail validation if the field is still zero
//	json:"key"         – standard JSON tag for file loading
//
// Supported field types: string, bool, int/int8–64, uint/uint8–64,
// float32/float64, time.Duration, []string, []int.
package config

import (
	"encoding/json"
	"fmt"
	"os"
	"reflect"
	"strconv"
	"strings"
	"time"
)

// ---------------------------------------------------------------------------
// Error types
// ---------------------------------------------------------------------------

// ErrorKind classifies configuration errors.
type ErrorKind int

const (
	ErrInvalidInput ErrorKind = iota // bad target argument
	ErrFileLoad                      // cannot read / parse file
	ErrParse                         // cannot convert string to field type
	ErrValidation                    // required or custom validation failed
)

func (k ErrorKind) String() string {
	return [...]string{"invalid_input", "file_load", "parse", "validation"}[k]
}

// Error is a structured configuration error.
type Error struct {
	Kind    ErrorKind
	Field   string // dotted path, e.g. "Server.Port"
	Message string
	Err     error // underlying error, if any
}

func (e *Error) Error() string {
	prefix := "config"
	if e.Field != "" {
		prefix += "[" + e.Field + "]"
	}
	return prefix + ": " + e.Message
}

func (e *Error) Unwrap() error { return e.Err }

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

// Validator is an optional interface config structs may implement for
// custom validation that runs after all values are loaded.
type Validator interface {
	Validate() error
}

// Option customises the loader.
type Option func(*loader)

// WithFile sets the path to a JSON configuration file.
func WithFile(path string) Option {
	return func(l *loader) { l.filePath = path }
}

// WithEnvPrefix prepends prefix_ to every environment variable lookup.
// WithEnvPrefix("APP") causes a field tagged env:"PORT" to read APP_PORT.
func WithEnvPrefix(prefix string) Option {
	return func(l *loader) { l.prefix = strings.TrimRight(prefix, "_") }
}

type loader struct {
	filePath string
	prefix   string
}

// Load fills target (must be a non-nil *struct) from defaults, an optional
// JSON file, and environment variables, then validates the result.
func Load(target any, opts ...Option) error {
	rv := reflect.ValueOf(target)
	if rv.Kind() != reflect.Ptr || rv.IsNil() || rv.Elem().Kind() != reflect.Struct {
		return &Error{Kind: ErrInvalidInput, Message: "target must be a non-nil pointer to a struct"}
	}

	l := new(loader)
	for _, o := range opts {
		o(l)
	}

	// Phase 1 – struct tag defaults (lowest priority).
	if err := applyDefaults(rv.Elem(), ""); err != nil {
		return err
	}

	// Phase 2 – JSON file (overwrites only keys present in file).
	if l.filePath != "" {
		if err := loadJSON(l.filePath, target); err != nil {
			return err
		}
	}

	// Phase 3 – environment variables (highest priority).
	if err := applyEnv(rv.Elem(), l.prefix, ""); err != nil {
		return err
	}

	// Phase 4 – required-field check.
	if err := checkRequired(rv.Elem(), ""); err != nil {
		return err
	}

	// Phase 5 – custom validation.
	if v, ok := target.(Validator); ok {
		if err := v.Validate(); err != nil {
			return &Error{Kind: ErrValidation, Message: err.Error(), Err: err}
		}
	}

	return nil
}

// MustLoad calls Load and panics on any error.
func MustLoad(target any, opts ...Option) {
	if err := Load(target, opts...); err != nil {
		panic("config: " + err.Error())
	}
}

// ---------------------------------------------------------------------------
// Phase 1 – defaults
// ---------------------------------------------------------------------------

var (
	durationType = reflect.TypeOf(time.Duration(0))
	timeType     = reflect.TypeOf(time.Time{})
)

func applyDefaults(v reflect.Value, path string) error {
	t := v.Type()
	for i := 0; i < t.NumField(); i++ {
		fv, ft := v.Field(i), t.Field(i)
		if !fv.CanSet() {
			continue
		}
		name := fieldPath(path, ft.Name)

		// Recurse into nested structs (but not time.Time).
		if fv.Kind() == reflect.Struct && fv.Type() != timeType {
			if err := applyDefaults(fv, name); err != nil {
				return err
			}
			continue
		}

		raw, ok := ft.Tag.Lookup("default")
		if !ok || !fv.IsZero() {
			continue
		}
		if err := setValue(fv, raw, name); err != nil {
			return err
		}
	}
	return nil
}

// ---------------------------------------------------------------------------
// Phase 2 – JSON file
// ---------------------------------------------------------------------------

func loadJSON(path string, target any) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return &Error{Kind: ErrFileLoad, Message: "read " + path + ": " + err.Error(), Err: err}
	}
	if err := json.Unmarshal(data, target); err != nil {
		return &Error{Kind: ErrFileLoad, Message: "parse " + path + ": " + err.Error(), Err: err}
	}
	return nil
}

// ---------------------------------------------------------------------------
// Phase 3 – environment variables
// ---------------------------------------------------------------------------

func applyEnv(v reflect.Value, prefix, path string) error {
	t := v.Type()
	for i := 0; i < t.NumField(); i++ {
		fv, ft := v.Field(i), t.Field(i)
		if !fv.CanSet() {
			continue
		}
		name := fieldPath(path, ft.Name)

		if fv.Kind() == reflect.Struct && fv.Type() != timeType {
			if err := applyEnv(fv, prefix, name); err != nil {
				return err
			}
			continue
		}

		key, ok := ft.Tag.Lookup("env")
		if !ok {
			continue
		}
		if prefix != "" {
			key = prefix + "_" + key
		}
		raw, found := os.LookupEnv(key)
		if !found {
			continue
		}
		if err := setValue(fv, raw, name); err != nil {
			return err
		}
	}
	return nil
}

// ---------------------------------------------------------------------------
// Phase 4 – required validation
// ---------------------------------------------------------------------------

func checkRequired(v reflect.Value, path string) error {
	t := v.Type()
	for i := 0; i < t.NumField(); i++ {
		fv, ft := v.Field(i), t.Field(i)
		if !fv.CanSet() {
			continue
		}
		name := fieldPath(path, ft.Name)

		if fv.Kind() == reflect.Struct && fv.Type() != timeType {
			if err := checkRequired(fv, name); err != nil {
				return err
			}
			continue
		}
		if ft.Tag.Get("required") == "true" && fv.IsZero() {
			return &Error{Kind: ErrValidation, Field: name, Message: "required but not set"}
		}
	}
	return nil
}

// ---------------------------------------------------------------------------
// Type-aware field setter
// ---------------------------------------------------------------------------

func setValue(fv reflect.Value, raw, name string) error {
	// time.Duration is int64 under the hood; check type before kind.
	if fv.Type() == durationType {
		d, err := time.ParseDuration(raw)
		if err != nil {
			return parseErr(name, raw, "duration", err)
		}
		fv.SetInt(int64(d))
		return nil
	}

	switch fv.Kind() {
	case reflect.String:
		fv.SetString(raw)

	case reflect.Bool:
		b, err := strconv.ParseBool(raw)
		if err != nil {
			return parseErr(name, raw, "bool", err)
		}
		fv.SetBool(b)

	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		n, err := strconv.ParseInt(raw, 10, fv.Type().Bits())
		if err != nil {
			return parseErr(name, raw, "int", err)
		}
		fv.SetInt(n)

	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		n, err := strconv.ParseUint(raw, 10, fv.Type().Bits())
		if err != nil {
			return parseErr(name, raw, "uint", err)
		}
		fv.SetUint(n)

	case reflect.Float32, reflect.Float64:
		n, err := strconv.ParseFloat(raw, fv.Type().Bits())
		if err != nil {
			return parseErr(name, raw, "float", err)
		}
		fv.SetFloat(n)

	case reflect.Slice:
		return setSlice(fv, raw, name)

	default:
		return &Error{Kind: ErrParse, Field: name,
			Message: "unsupported type " + fv.Type().String()}
	}
	return nil
}

func setSlice(fv reflect.Value, raw, name string) error {
	parts := splitTrim(raw, ",")

	switch fv.Type().Elem().Kind() {
	case reflect.String:
		fv.Set(reflect.ValueOf(parts))

	case reflect.Int:
		ints := make([]int, len(parts))
		for i, p := range parts {
			n, err := strconv.Atoi(p)
			if err != nil {
				return parseErr(name, p, "int (slice element)", err)
			}
			ints[i] = n
		}
		fv.Set(reflect.ValueOf(ints))

	default:
		return &Error{Kind: ErrParse, Field: name,
			Message: "unsupported slice element type " + fv.Type().Elem().String()}
	}
	return nil
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

func parseErr(field, raw, want string, err error) *Error {
	return &Error{
		Kind:    ErrParse,
		Field:   field,
		Message: fmt.Sprintf("cannot parse %q as %s", raw, want),
		Err:     err,
	}
}

func fieldPath(prefix, name string) string {
	if prefix == "" {
		return name
	}
	return prefix + "." + name
}

func splitTrim(s, sep string) []string {
	parts := strings.Split(s, sep)
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}
