// src/store.ts

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";
import { randomUUID } from "node:crypto";
import type { Task, ExecRecord, StoreData, Schedule } from "./types.js";

const DATA_DIR = join(homedir(), ".taskctl");
const DATA_FILE = join(DATA_DIR, "data.json");

// ── Internal I/O ─────────────────────────────────────────────

function ensureDir(): void {
  if (!existsSync(DATA_DIR)) mkdirSync(DATA_DIR, { recursive: true });
}

function read(): StoreData {
  ensureDir();
  if (!existsSync(DATA_FILE)) return { tasks: [], history: [] };
  try {
    return JSON.parse(readFileSync(DATA_FILE, "utf-8"));
  } catch {
    return { tasks: [], history: [] };
  }
}

function write(data: StoreData): void {
  ensureDir();
  writeFileSync(DATA_FILE, JSON.stringify(data, null, 2), "utf-8");
}

function shortId(): string {
  return randomUUID().replace(/-/g, "").slice(0, 8);
}

// ── Public API ───────────────────────────────────────────────

/** Find by exact id, id prefix, or exact name. */
export function resolveTask(query: string): Task | undefined {
  const { tasks } = read();
  return (
    tasks.find((t) => t.id === query) ??
    tasks.find((t) => t.id.startsWith(query)) ??
    tasks.find((t) => t.name === query)
  );
}

export function getAllTasks(): Task[] {
  return read().tasks;
}

export function addTask(
  name: string,
  command: string,
  schedule: Schedule,
  opts: { tags?: string[]; timeout?: number } = {},
): Task {
  const data = read();
  if (data.tasks.some((t) => t.name === name)) {
    throw new Error(`Task "${name}" already exists`);
  }

  const task: Task = {
    id: shortId(),
    name,
    command,
    schedule,
    enabled: true,
    createdAt: new Date().toISOString(),
    lastRun: null,
    runCount: 0,
    tags: opts.tags ?? [],
    timeout: opts.timeout ?? 0,
  };

  data.tasks.push(task);
  write(data);
  return task;
}

export function removeTask(query: string): Task | null {
  const data = read();
  const idx = data.tasks.findIndex(
    (t) => t.id === query || t.id.startsWith(query) || t.name === query,
  );
  if (idx === -1) return null;

  const [removed] = data.tasks.splice(idx, 1);
  data.history = data.history.filter((h) => h.taskId !== removed.id);
  write(data);
  return removed;
}

export function updateTask(
  query: string,
  patch: Partial<Pick<Task, "enabled" | "command" | "schedule" | "tags" | "timeout">>,
): Task | null {
  const data = read();
  const task = data.tasks.find(
    (t) => t.id === query || t.id.startsWith(query) || t.name === query,
  );
  if (!task) return null;

  Object.assign(task, patch);
  write(data);
  return task;
}

export function recordRun(record: ExecRecord): void {
  const data = read();
  data.history.push(record);

  // Cap history at 1 000 entries
  if (data.history.length > 1000) data.history = data.history.slice(-1000);

  // Bump task stats
  const task = data.tasks.find((t) => t.id === record.taskId);
  if (task) {
    task.lastRun = record.startedAt;
    task.runCount += 1;
  }

  write(data);
}

export function getHistory(taskId?: string, limit = 20): ExecRecord[] {
  const { history } = read();
  const filtered = taskId ? history.filter((h) => h.taskId === taskId) : history;
  return filtered.slice(-limit).reverse(); // newest first
}

export function clearHistory(taskId?: string): number {
  const data = read();
  const before = data.history.length;
  data.history = taskId ? data.history.filter((h) => h.taskId !== taskId) : [];
  write(data);
  return before - data.history.length;
}
