// src/executor.ts

import { exec } from "node:child_process";
import { randomUUID } from "node:crypto";
import type { Task, ExecRecord } from "./types.js";

/**
 * Spawns a shell, runs the command, and captures everything.
 * Never rejects — errors are encoded in the returned record.
 */
export function executeTask(task: Task): Promise<ExecRecord> {
  const id = randomUUID().replace(/-/g, "").slice(0, 8);
  const startedAt = new Date();

  return new Promise((resolve) => {
    const child = exec(task.command, {
      timeout: task.timeout || undefined,
      maxBuffer: 1024 * 1024,
      env: {
        ...process.env,
        TASKCTL_ID: task.id,
        TASKCTL_NAME: task.name,
      },
    });

    let stdout = "";
    let stderr = "";

    child.stdout?.on("data", (chunk: string) => { stdout += chunk; });
    child.stderr?.on("data", (chunk: string) => { stderr += chunk; });

    child.on("close", (exitCode) => {
      const completedAt = new Date();
      resolve({
        id,
        taskId: task.id,
        taskName: task.name,
        startedAt: startedAt.toISOString(),
        completedAt: completedAt.toISOString(),
        durationMs: completedAt.getTime() - startedAt.getTime(),
        exitCode,
        stdout: stdout.slice(0, 10_000).trim(),
        stderr: stderr.slice(0, 10_000).trim(),
        success: exitCode === 0,
      });
    });

    child.on("error", (err) => {
      const completedAt = new Date();
      resolve({
        id,
        taskId: task.id,
        taskName: task.name,
        startedAt: startedAt.toISOString(),
        completedAt: completedAt.toISOString(),
        durationMs: completedAt.getTime() - startedAt.getTime(),
        exitCode: null,
        stdout: "",
        stderr: err.message,
        success: false,
      });
    });
  });
}
