// src/format.ts
// Parsing helpers + terminal output formatting.

import cron from "node-cron";
import type { Task, ExecRecord, Schedule } from "./types.js";

// ── Duration / Interval Parsing ──────────────────────────────

const UNITS: Record<string, { ms: number; name: string }> = {
  s: { ms: 1_000, name: "second" },
  m: { ms: 60_000, name: "minute" },
  h: { ms: 3_600_000, name: "hour" },
  d: { ms: 86_400_000, name: "day" },
};

export function parseDuration(input: string): number {
  const match = input.match(/^(\d+)(s|m|h|d)$/i);
  if (!match) throw new Error(`Bad duration "${input}". Examples: 30s, 5m, 2h, 1d`);
  return parseInt(match[1], 10) * UNITS[match[2].toLowerCase()].ms;
}

// ── Schedule Flag Parsing ────────────────────────────────────

export function parseScheduleFlags(flags: {
  cron?: string;
  every?: string;
  at?: string;
}): Schedule {
  const set = [flags.cron, flags.every, flags.at].filter(Boolean);
  if (set.length === 0) throw new Error("Provide --cron, --every, or --at");
  if (set.length > 1) throw new Error("Use only one of --cron, --every, --at");

  if (flags.cron) {
    if (!cron.validate(flags.cron)) throw new Error(`Bad cron: "${flags.cron}"`);
    return { type: "cron", expression: flags.cron };
  }

  if (flags.every) {
    const match = flags.every.match(/^(\d+)(s|m|h|d)$/i);
    if (!match) throw new Error(`Bad interval "${flags.every}"`);
    const n = parseInt(match[1], 10);
    const u = match[2].toLowerCase();
    return { type: "interval", ms: n * UNITS[u].ms, label: `every ${n}${u}` };
  }

  // --at
  const date = new Date(flags.at!);
  if (isNaN(date.getTime())) throw new Error(`Bad date: "${flags.at}"`);
  return { type: "once", date: date.toISOString() };
}

