#!/usr/bin/env python3
"""idx - CLI search indexing tool with BM25 ranking."""

import argparse
import json
import math
import os
import re
import sqlite3
import sys
import time
from collections import defaultdict
from pathlib import Path

# ─── Tokenization & Stemming ────────────────────────────────────────────────

STOP_WORDS = frozenset({
    "a", "an", "and", "are", "as", "at", "be", "by", "for", "from", "has",
    "he", "in", "is", "it", "its", "of", "on", "or", "she", "that", "the",
    "to", "was", "were", "will", "with", "this", "but", "they", "have", "had",
    "what", "when", "where", "who", "which", "not", "no", "do", "does", "did",
    "can", "could", "would", "should", "if", "then", "than", "so", "just",
    "about", "into", "through", "during", "before", "after", "between", "out",
    "up", "down", "over", "under", "again", "further", "once", "all", "been",
})

SUFFIXES = (
    "ingly", "tion", "sion", "ment", "ness", "able", "ible",
    "ing", "ies", "ous", "ive", "ful", "less", "ers", "est",
    "ely", "ed", "er", "ly", "es", "al", "s",
)


def stem(word: str) -> str:
    """Minimal suffix-stripping stemmer (good enough for search)."""
    for suffix in SUFFIXES:
        if word.endswith(suffix) and len(word) - len(suffix) >= 3:
            return word[: -len(suffix)]
    return word


def tokenize(text: str) -> list[str]:
    """Split text into stemmed, filtered tokens."""
    raw = re.findall(r"[a-zA-Z0-9]+", text.lower())
    return [stem(t) for t in raw if t not in STOP_WORDS and len(t) > 1]


def tokenize_raw(text: str) -> list[str]:
    """Tokens without stemming (for snippet matching)."""
    return [t for t in re.findall(r"[a-zA-Z0-9]+", text.lower())
            if t not in STOP_WORDS and len(t) > 1]


