CREATE TABLE IF NOT EXISTS terms (
    term_id INTEGER PRIMARY KEY AUTOINCREMENT,
    term    TEXT UNIQUE NOT NULL
);
CREATE TABLE IF NOT EXISTS postings (
    term_id   INTEGER NOT NULL,
    doc_id    INTEGER NOT NULL,
    frequency INTEGER NOT NULL,
    positions TEXT NOT NULL,
    PRIMARY KEY (term_id, doc_id)
);
CREATE INDEX IF NOT EXISTS idx_postings_doc ON postings(doc_id);
"""


class IndexStore:
    """Persistent inverted index stored in SQLite."""

    def __init__(self, db_path: str):
        self.db_path = db_path
        self.conn = sqlite3.connect(db_path)
        self.conn.execute("PRAGMA journal_mode=WAL")
        self.conn.execute("PRAGMA synchronous=NORMAL")
        self.conn.executescript(SCHEMA)
        self._term_cache: dict[str, int] = {}

    # ── Documents ──

    def upsert_document(self, path: str, size: int, modified: float,
                        token_count: int, title: str) -> int:
        cur = self.conn.execute(
            "INSERT OR REPLACE INTO documents "
            "(path, size, modified, indexed_at, token_count, title) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (path, size, modified, time.time(), token_count, title),
        )
        return cur.lastrowid

    def get_document(self, path: str) -> dict | None:
        row = self.conn.execute(
            "SELECT doc_id, modified FROM documents WHERE path = ?", (path,)
        ).fetchone()
        return {"doc_id": row[0], "modified": row[1]} if row else None

    def remove_document(self, path: str) -> bool:
        row = self.conn.execute(
            "SELECT doc_id FROM documents WHERE path = ?", (path,)
        ).fetchone()
        if not row:
            return False
        doc_id = row[0]
        self.conn.execute("DELETE FROM postings WHERE doc_id = ?", (doc_id,))
        self.conn.execute("DELETE FROM documents WHERE doc_id = ?", (doc_id,))
        self.conn.commit()
        return True

    # ── Terms & Postings ──

    def get_or_create_term(self, term: str) -> int:
        if term in self._term_cache:
            return self._term_cache[term]
        row = self.conn.execute(
            "SELECT term_id FROM terms WHERE term = ?", (term,)
        ).fetchone()
        if row:
            self._term_cache[term] = row[0]
            return row[0]
        cur = self.conn.execute("INSERT INTO terms (term) VALUES (?)", (term,))
        self._term_cache[term] = cur.lastrowid
        return cur.lastrowid

    def add_postings_batch(self, postings: list[tuple[int, int, int, str]]):
        self.conn.executemany(
            "INSERT OR REPLACE INTO postings "
            "(term_id, doc_id, frequency, positions) VALUES (?, ?, ?, ?)",
            postings,
        )

    def delete_postings_for_doc(self, doc_id: int):
        self.conn.execute("DELETE FROM postings WHERE doc_id = ?", (doc_id,))

    # ── Search ──

    def search_terms(self, terms: list[str]) -> dict[str, list[tuple[int, int]]]:
        """Returns {term: [(doc_id, frequency), ...]}."""
        results: dict[str, list[tuple[int, int]]] = {}
        for term in terms:
            rows = self.conn.execute(
                "SELECT p.doc_id, p.frequency FROM postings p "
                "JOIN terms t ON t.term_id = p.term_id WHERE t.term = ?",
                (term,),
            ).fetchall()
            if rows:
                results[term] = rows
        return results

    def get_docs_info(self, doc_ids: set[int]) -> dict[int, dict]:
        if not doc_ids:
            return {}
        ph = ",".join("?" * len(doc_ids))
        rows = self.conn.execute(
            f"SELECT doc_id, path, token_count, title FROM documents "
            f"WHERE doc_id IN ({ph})",
            list(doc_ids),
        ).fetchall()
        return {
            r[0]: {"path": r[1], "token_count": r[2], "title": r[3]}
            for r in rows
        }

    # ── Aggregate ──

    def total_docs(self) -> int:
        return self.conn.execute("SELECT COUNT(*) FROM documents").fetchone()[0]

    def avg_doc_length(self) -> float:
        r = self.conn.execute(
            "SELECT COALESCE(AVG(token_count), 0) FROM documents"
        ).fetchone()[0]
        return float(r)

    def stats(self) -> dict:
        d = self.conn.execute("SELECT COUNT(*) FROM documents").fetchone()[0]
        t = self.conn.execute("SELECT COUNT(*) FROM terms").fetchone()[0]
        p = self.conn.execute("SELECT COUNT(*) FROM postings").fetchone()[0]
        s = self.conn.execute(
            "SELECT COALESCE(SUM(size), 0) FROM documents"
        ).fetchone()[0]
        a = self.conn.execute(
            "SELECT COALESCE(AVG(token_count), 0) FROM documents"
        ).fetchone()[0]
        idx_size = os.path.getsize(self.db_path) if os.path.exists(self.db_path) else 0
        return {
            "documents": d, "terms": t, "postings": p,
            "total_bytes": s, "avg_tokens": a, "index_bytes": idx_size,
        }

    def list_documents(self, limit: int = 50, offset: int = 0) -> list[dict]:
        rows = self.conn.execute(
            "SELECT path, size, token_count, indexed_at FROM documents "
            "ORDER BY indexed_at DESC LIMIT ? OFFSET ?",
            (limit, offset),
        ).fetchall()
        return [
            {"path": r[0], "size": r[1], "tokens": r[2], "indexed_at": r[3]}
            for r in rows
        ]

    def clear(self):
        self.conn.executescript(
            "DELETE FROM postings; DELETE FROM terms; DELETE FROM documents; VACUUM;"
        )
        self._term_cache.clear()

    def commit(self):
        self.conn.commit()

    def close(self):
        self.conn.close()


# ─── File Reading ────────────────────────────────────────────────────────────

TEXT_EXTENSIONS = {
    ".txt", ".md", ".rst", ".org",
    ".py", ".js", ".ts", ".jsx", ".tsx", ".go", ".rs", ".rb", ".java",
    ".c", ".cpp", ".h", ".hpp", ".cs", ".swift", ".kt",
    ".sh", ".bash", ".zsh", ".fish",
    ".html", ".css", ".scss", ".less",
    ".json", ".yml", ".yaml", ".toml", ".xml", ".csv",
    ".ini", ".cfg", ".conf", ".env",
    ".sql", ".graphql", ".proto",
    ".dockerfile", ".makefile",
    ".log", ".tex", ".r", ".lua", ".vim",
}

SKIP_DIRS = frozenset({
    ".git", ".svn", ".hg", "node_modules", "__pycache__",
    "venv", ".venv", "env", ".env", ".tox",
    "dist", "build", ".next", ".cache", "target",
    ".idea", ".vscode", "vendor", "coverage",
})


def read_file(path: str) -> str | None:
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            return f.read(10 * 1024 * 1024)  # cap at 10 MB
    except (OSError, PermissionError):
        return None


def extract_title(path: str, content: str) -> str:
    name = os.path.basename(path)
    if path.endswith(".md"):
        for line in content.split("\n", 10):
            if line.startswith("# "):
                return line[2:].strip()
    if path.endswith((".py", ".sh", ".bash")):
        for line in content.split("\n", 5):
            stripped = line.strip().lstrip("#").strip().strip('"""').strip("'''")
            if stripped and not stripped.startswith("!"):
                return stripped[:100]
    return name


def should_index(path: str, extensions: set[str]) -> bool:
    p = Path(path)
    if any(part.startswith(".") and part != "." for part in p.parts):
        return False
    if any(part in SKIP_DIRS for part in p.parts):
        return False
    return p.suffix.lower() in extensions


# ─── Indexer ─────────────────────────────────────────────────────────────────

class Indexer:
    def __init__(self, store: IndexStore):
        self.store = store

    def index_file(self, filepath: str) -> bool:
        """Index one file. Returns True if content was (re)indexed."""
        abspath = os.path.abspath(filepath)
        try:
            stat = os.stat(abspath)
        except OSError:
            return False

        existing = self.store.get_document(abspath)
        if existing and existing["modified"] >= stat.st_mtime:
            return False

        content = read_file(abspath)
        if content is None:
            return False

        tokens = tokenize(content)
        if not tokens:
            return False

        title = extract_title(abspath, content)

        # clear old data if re-indexing
        if existing:
            self.store.delete_postings_for_doc(existing["doc_id"])

        doc_id = self.store.upsert_document(
            abspath, stat.st_size, stat.st_mtime, len(tokens), title,
        )

        # build position map
        term_positions: dict[str, list[int]] = defaultdict(list)
        for pos, tok in enumerate(tokens):
            term_positions[tok].append(pos)

        batch = []
        for term, positions in term_positions.items():
            term_id = self.store.get_or_create_term(term)
            batch.append((term_id, doc_id, len(positions), json.dumps(positions)))

        self.store.add_postings_batch(batch)
        return True

    def index_path(self, path: str, extensions: set[str],
                   verbose: bool = False) -> tuple[int, int]:
        """Index a file or directory tree. Returns (indexed, skipped)."""
        abspath = os.path.abspath(path)

        if os.path.isfile(abspath):
            ok = self.index_file(abspath)
            self.store.commit()
            if verbose:
                tag = "indexed" if ok else "skipped"
                print(f"  {tag}: {abspath}")
            return (1, 0) if ok else (0, 1)

        indexed = skipped = 0
        for root, dirs, files in os.walk(abspath):
            dirs[:] = sorted(d for d in dirs if d not in SKIP_DIRS and not d.startswith("."))

            for fname in sorted(files):
                fpath = os.path.join(root, fname)
                if not should_index(fpath, extensions):
                    skipped += 1
                    continue
                if self.index_file(fpath):
                    indexed += 1
                    if verbose:
                        print(f"  + {os.path.relpath(fpath, abspath)}")
                else:
                    skipped += 1

            # commit in batches per directory
            self.store.commit()

        return indexed, skipped


# ─── BM25 Search ─────────────────────────────────────────────────────────────

class Searcher:
    def __init__(self, store: IndexStore, k1: float = 1.5, b: float = 0.75):
        self.store = store
        self.k1 = k1
        self.b = b

    def search(self, query: str, limit: int = 10) -> list[dict]:
        terms = list(set(tokenize(query)))
        if not terms:
            return []

        n = self.store.total_docs()
        if n == 0:
            return []
        avgdl = self.store.avg_doc_length()

        postings = self.store.search_terms(terms)
        if not postings:
            return []

        # score every matching document
        scores: dict[int, float] = defaultdict(float)
        doc_ids_needed: set[int] = set()

        for term, posting_list in postings.items():
            df = len(posting_list)
            idf = math.log((n - df + 0.5) / (df + 0.5) + 1.0)
            for doc_id, freq in posting_list:
                doc_ids_needed.add(doc_id)
                scores[doc_id] += idf * freq  # partial — needs doc length

        # fetch doc lengths in one batch
        docs_info = self.store.get_docs_info(doc_ids_needed)

        # recalculate with proper BM25
        final_scores: dict[int, float] = defaultdict(float)
        for term, posting_list in postings.items():
            df = len(posting_list)
            idf = math.log((n - df + 0.5) / (df + 0.5) + 1.0)
            for doc_id, freq in posting_list:
                info = docs_info.get(doc_id)
                if not info:
                    continue
                dl = info["token_count"]
                denom = freq + self.k1 * (1.0 - self.b + self.b * dl / max(avgdl, 1.0))
                final_scores[doc_id] += idf * (freq * (self.k1 + 1.0)) / denom

        ranked = sorted(final_scores.items(), key=lambda x: x[1], reverse=True)[:limit]

        raw_query_tokens = tokenize_raw(query)
        results = []
        for doc_id, score in ranked:
            info = docs_info[doc_id]
            snippet = self._snippet(info["path"], raw_query_tokens)
            results.append({
                "path": info["path"],
                "title": info["title"],
                "score": round(score, 4),
                "snippet": snippet,
            })
        return results

    @staticmethod
    def _snippet(path: str, query_tokens: list[str], ctx: int = 100) -> str:
        content = read_file(path)
        if not content:
            return ""
        lower = content.lower()

        # find best window containing query terms
        best = -1
        for tok in query_tokens:
            pos = lower.find(tok)
            if pos != -1:
                best = pos
                break

        if best == -1:
            text = content[:ctx * 2]
        else:
            start = max(0, best - ctx)
            end = min(len(content), best + ctx)
            text = ("..." if start > 0 else "") + content[start:end]
            if end < len(content):
                text += "..."

        return re.sub(r"\s+", " ", text).strip()


