```rust
use std::collections::HashSet;

const STOP_WORDS: &[&str] = &[
    "a", "an", "the", "and", "or", "but", "in", "on", "at", "to", "for", "of",
    "with", "by", "from", "is", "it", "this", "that", "are", "was", "were", "be",
    "been", "being", "have", "has", "had", "do", "does", "did", "will", "would",
    "could", "should", "may", "might", "can", "shall", "not", "no", "if", "so",
    "as", "its", "you", "your", "we", "our", "they", "their", "he", "she", "my",
    "me", "up", "out", "about", "into", "than", "then", "each", "which", "there",
];

pub struct Tokenizer {
    stop_words: HashSet<&'static str>,
}

impl Tokenizer {
    pub fn new() -> Self {
        Self {
            stop_words: STOP_WORDS.iter().copied().collect(),
        }
    }

    /// Tokenize text into (lowercase_term, position) pairs.
    /// Skips stop words and tokens shorter than 2 chars.
    pub fn tokenize(&self, text: &str) -> Vec<(String, u32)> {
        let mut tokens = Vec::new();
        let mut pos = 0u32;

        for word in text.split(|c: char| !c.is_alphanumeric() && c != '_') {
            if word.is_empty() {
                continue;
            }
            let lower = word.to_lowercase();
            if lower.len() >= 2 && !self.stop_words.contains(lower.as_str()) {
                tokens.push((lower, pos));
            }
            pos += 1;
        }

        tokens
    }

    /// Extract unique query terms from user input words.
    pub fn tokenize_query(&self, words: &[String]) -> Vec<String> {
        let mut seen = HashSet::new();
        let mut terms = Vec::new();

        for word in words {
            for (term, _) in self.tokenize(word) {
                if seen.insert(term.clone()) {
                    terms.push(term);
                }
            }
        }
        terms
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic_tokenization() {
        let t = Tokenizer::new();
        let tokens = t.tokenize("Hello, world! This is a Rust test_case.");
        let terms: Vec<&str> = tokens.iter().map(|(t, _)| t.as_str()).collect();
        assert!(terms.contains(&"hello"));
        assert!(terms.contains(&"world"));
        assert!(terms.contains(&"rust"));
        assert!(terms.contains(&"test_case"));
        assert!(!terms.contains(&"this")); // stop word
        assert!(!terms.contains(&"is"));   // stop word
        assert!(!terms.contains(&"a"));    // stop word
    }

    #[test]
    fn positions_are_sequential() {
        let t = Tokenizer::new();
        let tokens = t.tokenize("fn main() { println }");
        // "fn" at 0, "main" at 1, "println" at 3
        assert_eq!(tokens[0], ("fn".into(), 0));
        assert_eq!(tokens[1], ("main".into(), 1));
        assert_eq!(tokens[2], ("println".into(), 3));
    }

    #[test]
    fn query_deduplication() {
        let t = Tokenizer::new();
        let terms = t.tokenize_query(&["error".into(), "error".into(), "handling".into()]);
        assert_eq!(terms, vec!["error", "handling"]);
    }
}
