## `src/index.rs`

```rust
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::path::Path;
use std::time::{SystemTime, UNIX_EPOCH};

use crate::tokenizer::Tokenizer;

// ── Stored types ────────────────────────────────────────────

#[derive(Serialize, Deserialize, Default)]
pub struct SearchIndex {
    /// term → list of postings (one per document containing the term)
    postings: HashMap<String, Vec<Posting>>,
    /// doc_id → metadata
    documents: HashMap<u64, DocMeta>,
    /// canonical_path → doc_id (dedup & lookup)
    path_to_id: HashMap<String, u64>,
    next_id: u64,
}

#[derive(Serialize, Deserialize, Clone)]
struct Posting {
    doc_id: u64,
    tf: u32,         // raw term frequency in this doc
    positions: Vec<u32>,
}

#[derive(Serialize, Deserialize, Clone)]
pub struct DocMeta {
    pub path: String,
    pub size: u64,
    pub num_terms: u32,
    pub indexed_at: u64,
}

// ── Public result types ─────────────────────────────────────

pub struct Hit {
    pub path: String,
    pub score: f64,
    pub matched_terms: Vec<String>,
}

pub struct Snippet {
    pub line_num: usize,
    pub text: String,
}

// ── Core implementation ─────────────────────────────────────

impl SearchIndex {
    pub fn load_or_create(path: &Path) -> Self {
        if path.exists() {
            let data = fs::read_to_string(path).unwrap_or_default();
            serde_json::from_str(&data).unwrap_or_default()
        } else {
            Self::default()
        }
    }

    pub fn save(&self, path: &Path) -> std::io::Result<()> {
        if let Some(dir) = path.parent() {
            fs::create_dir_all(dir)?;
        }
        let json = serde_json::to_string(self)?;
        fs::write(path, json)
    }

    /// Index a single file. Returns Ok(true) if successfully indexed.
    pub fn index_file(&mut self, file_path: &Path, tokenizer: &Tokenizer) -> std::io::Result<bool> {
        let canonical = fs::canonicalize(file_path)?;
        let key = canonical.to_string_lossy().into_owned();

        let content = match fs::read_to_string(&canonical) {
            Ok(c) => c,
            Err(_) => return Ok(false), // skip binary / unreadable
        };

        let tokens = tokenizer.tokenize(&content);
        if tokens.is_empty() {
            return Ok(false);
        }

        // Remove stale entry when re-indexing the same path
        if let Some(&old_id) = self.path_to_id.get(&key) {
            self.purge_doc(old_id);
        }

        let doc_id = self.next_id;
        self.next_id += 1;

        // Aggregate per-term data
        let mut term_info: HashMap<&str, (u32, Vec<u32>)> = HashMap::new();
        for (term, pos) in &tokens {
            let entry = term_info.entry(term.as_str()).or_default();
            entry.0 += 1;
            entry.1.push(*pos);
        }

        let num_terms = tokens.len() as u32;

        for (term, (tf, positions)) in term_info {
            self.postings
                .entry(term.to_owned())
                .or_default()
                .push(Posting { doc_id, tf, positions });
        }

        let meta = DocMeta {
            path: key.clone(),
            size: fs::metadata(&canonical)?.len(),
            num_terms,
            indexed_at: now_unix(),
        };
        self.documents.insert(doc_id, meta);
        self.path_to_id.insert(key, doc_id);

        Ok(true)
    }

    /// Remove a document by its canonical path string.
    pub fn remove_by_path(&mut self, canonical: &str) -> bool {
        if let Some(&doc_id) = self.path_to_id.get(canonical) {
            self.purge_doc(doc_id);
            self.path_to_id.remove(canonical);
            true
        } else {
            false
        }
    }

    /// Try to find an indexed path matching the given input (exact or suffix).
    pub fn resolve_path(&self, input: &str) -> Option<String> {
        if self.path_to_id.contains_key(input) {
            return Some(input.to_owned());
        }
        // Fall back to suffix match (useful for relative paths / deleted files)
        self.path_to_id
            .keys()
            .find(|k| k.ends_with(input))
            .cloned()
    }

    pub fn clear(&mut self) {
        *self = Self::default();
    }

    // ── Search ──────────────────────────────────────────────

    /// Search the index. Returns hits ranked by TF-IDF score.
    pub fn search(&self, terms: &[String], require_all: bool, limit: usize) -> Vec<Hit> {
        if terms.is_empty() || self.documents.is_empty() {
            return vec![];
        }

        let n = self.documents.len() as f64;
        let mut scores: HashMap<u64, (f64, Vec<String>)> = HashMap::new();

        for term in terms {
            if let Some(postings) = self.postings.get(term) {
                // IDF with smoothing to avoid division by zero
                let idf = ((n + 1.0) / (postings.len() as f64 + 1.0)).ln() + 1.0;

                for p in postings {
                    if let Some(doc) = self.documents.get(&p.doc_id) {
                        let tf = p.tf as f64 / doc.num_terms as f64;
                        let entry = scores.entry(p.doc_id).or_insert_with(|| (0.0, vec![]));
                        entry.0 += tf * idf;
                        if !entry.1.contains(term) {
                            entry.1.push(term.clone());
                        }
                    }
                }
            }
        }

        // AND mode: require every query term to appear
        if require_all {
            let required = terms.len();
            scores.retain(|_, (_, matched)| matched.len() == required);
        }

        let mut ranked: Vec<_> = scores.into_iter().collect();
        ranked.sort_by(|a, b| b.1 .0.partial_cmp(&a.1 .0).unwrap());
        ranked.truncate(limit);

        ranked
            .into_iter()
            .filter_map(|(id, (score, matched_terms))| {
                let doc = self.documents.get(&id)?;
                Some(Hit {
                    path: doc.path.clone(),
                    score,
                    matched_terms,
                })
            })
            .collect()
    }

    // ── Stats ───────────────────────────────────────────────

    pub fn doc_count(&self) -> usize {
        self.documents.len()
    }

    pub fn term_count(&self) -> usize {
        self.postings.len()
    }

    pub fn total_bytes(&self) -> u64 {
        self.documents.values().map(|d| d.size).sum()
    }

    pub fn all_docs(&self) -> Vec<&DocMeta> {
        let mut docs: Vec<_> = self.documents.values().collect();
        docs.sort_by_key(|d| &d.path);
        docs
    }

    // ── Internal ────────────────────────────────────────────

    fn purge_doc(&mut self, doc_id: u64) {
        self.documents.remove(&doc_id);
        for postings in self.postings.values_mut() {
            postings.retain(|p| p.doc_id != doc_id);
        }
        self.postings.retain(|_, v| !v.is_empty());
    }
}

// ── Snippet extraction (re-reads file on demand) ────────────

pub fn extract_snippets(path: &str, terms: &[String], max: usize) -> Vec<Snippet> {
    let Ok(content) = fs::read_to_string(path) else {
        return vec![];
    };

    let mut snippets = Vec::new();
    for (i, line) in content.lines().enumerate() {
        let lower = line.to_lowercase();
        if terms.iter().any(|t| lower.contains(t.as_str())) {
            let text = if line.len() > 120 {
                format!("{}…", &line[..line.floor_char_boundary(117)])
            } else {
                line.to_string()
            };
            snippets.push(Snippet {
                line_num: i + 1,
                text,
            });
            if snippets.len() >= max {
                break;
            }
        }
    }
    snippets
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
