type Record struct {
	Task     string `json:"task"`
	Time     string `json:"time"`
	Duration string `json:"duration"`
	Exit     int    `json:"exit"`
	Output   string `json:"output,omitempty"`
	Error    string `json:"error,omitempty"`
}

// ── Persistence ──────────────────────────────────────────────

var storageMu sync.Mutex

func ensureDir() { os.MkdirAll(dataDir, 0755) }

func loadTasks() ([]Task, error) {
	storageMu.Lock()
	defer storageMu.Unlock()

	data, err := os.ReadFile(tasksPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	var tasks []Task
	return tasks, json.Unmarshal(data, &tasks)
}

func saveTasks(tasks []Task) error {
	storageMu.Lock()
	defer storageMu.Unlock()
	ensureDir()

	b, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(tasksPath, b, 0644)
}

func loadHistory() []Record {
	storageMu.Lock()
	defer storageMu.Unlock()

	data, err := os.ReadFile(historyPath)
	if err != nil {
		return nil
	}
	var r []Record
	json.Unmarshal(data, &r)
	return r
}

func saveRecord(rec Record) {
	storageMu.Lock()
	defer storageMu.Unlock()
	ensureDir()

	var recs []Record
	if data, err := os.ReadFile(historyPath); err == nil {
		json.Unmarshal(data, &recs)
	}

	recs = append(recs, rec)
	if len(recs) > 1000 { // cap history
		recs = recs[len(recs)-1000:]
	}

	b, _ := json.MarshalIndent(recs, "", "  ")
	os.WriteFile(historyPath, b, 0644)
