// ── Cron Expression Parser ───────────────────────────────────
//
// Supports standard 5-field cron: minute hour day month weekday
//   *        any value
//   5        specific value
//   1,3,5    list
//   1-5      range
//   */10     step
//   1-5/2    range with step

type cronExpr struct {
	min     [60]bool
	hour    [24]bool
	day     [32]bool // index 1-31
	month   [13]bool // index 1-12
	weekday [7]bool  // index 0-6, 0=Sunday
}

func parseCron(s string) (*cronExpr, error) {
	fields := strings.Fields(s)
	if len(fields) != 5 {
		return nil, fmt.Errorf("need 5 fields, got %d", len(fields))
	}

	c := &cronExpr{}
	if err := setCronBits(fields[0], c.min[:], 0, 59); err != nil {
		return nil, fmt.Errorf("minute: %w", err)
	}
	if err := setCronBits(fields[1], c.hour[:], 0, 23); err != nil {
		return nil, fmt.Errorf("hour: %w", err)
	}
	if err := setCronBits(fields[2], c.day[:], 1, 31); err != nil {
		return nil, fmt.Errorf("day: %w", err)
	}
	if err := setCronBits(fields[3], c.month[:], 1, 12); err != nil {
		return nil, fmt.Errorf("month: %w", err)
	}
	if err := setCronBits(fields[4], c.weekday[:], 0, 6); err != nil {
		return nil, fmt.Errorf("weekday: %w", err)
	}
	return c, nil
}

func setCronBits(field string, bits []bool, min, max int) error {
	for _, part := range strings.Split(field, ",") {
		if err := setCronPart(part, bits, min, max); err != nil {
			return err
		}
	}
	return nil
}

func setCronPart(part string, bits []bool, min, max int) error {
	switch {
	case part == "*":
		for i := min; i <= max; i++ {
			bits[i] = true
		}

	case strings.HasPrefix(part, "*/"):
		step, err := strconv.Atoi(part[2:])
		if err != nil || step <= 0 {
			return fmt.Errorf("invalid step %q", part)
		}
		for i := min; i <= max; i += step {
			bits[i] = true
		}

	case strings.Contains(part, "-"):
		stepStr := strings.SplitN(part, "/", 2)
		bounds := strings.SplitN(stepStr[0], "-", 2)

		lo, err := strconv.Atoi(bounds[0])
		if err != nil {
			return fmt.Errorf("invalid range %q", part)
		}
		hi, err := strconv.Atoi(bounds[1])
		if err != nil {
			return fmt.Errorf("invalid range %q", part)
		}
		if lo < min || hi > max || lo > hi {
			return fmt.Errorf("range out of bounds %q (%d-%d)", part, min, max)
		}

		step := 1
		if len(stepStr) > 1 {
			step, err = strconv.Atoi(stepStr[1])
			if err != nil || step <= 0 {
				return fmt.Errorf("invalid step in %q", part)
			}
		}
		for i := lo; i <= hi; i += step {
			bits[i] = true
		}

	default:
		v, err := strconv.Atoi(part)
		if err != nil || v < min || v > max {
			return fmt.Errorf("value %q out of range %d-%d", part, min, max)
		}
		bits[v] = true
	}
	return nil
}

