// ─── ConfigValue ─────────────────────────────────────────────────

ConfigValue::ConfigValue(std::string value, std::string section, std::string key)
    : value_(std::move(value))
    , section_(std::move(section))
    , key_(std::move(key))
{}

std::string ConfigValue::as_string() const {
    return value_;
}

int ConfigValue::as_int() const {
    try {
        std::size_t pos = 0;
        int result = std::stoi(value_, &pos);
        // Ensure entire string was consumed
        if (pos != value_.size()) {
            throw std::invalid_argument("trailing characters");
        }
        return result;
    } catch (const std::exception&) {
        throw ConfigTypeError(section_, key_, "int", value_);
    }
}

long long ConfigValue::as_long() const {
    try {
        std::size_t pos = 0;
        long long result = std::stoll(value_, &pos);
        if (pos != value_.size()) {
            throw std::invalid_argument("trailing characters");
        }
        return result;
    } catch (const std::exception&) {
        throw ConfigTypeError(section_, key_, "long long", value_);
    }
}

double ConfigValue::as_double() const {
    try {
        std::size_t pos = 0;
        double result = std::stod(value_, &pos);
        if (pos != value_.size()) {
            throw std::invalid_argument("trailing characters");
        }
        return result;
    } catch (const std::exception&) {
        throw ConfigTypeError(section_, key_, "double", value_);
    }
}

bool ConfigValue::as_bool() const {
    // Normalize to lowercase for comparison
    std::string lower = value_;
    std::transform(lower.begin(), lower.end(), lower.begin(),
                   [](unsigned char c) { return std::tolower(c); });

    if (lower == "true"  || lower == "yes" || lower == "on"  || lower == "1")
        return true;
    if (lower == "false" || lower == "no"  || lower == "off" || lower == "0")
        return false;

    throw ConfigTypeError(section_, key_, "bool", value_);
}

std::vector<std::string> ConfigValue::as_list(char delimiter) const {
    std::vector<std::string> result;
    std::istringstream stream(value_);
    std::string item;

    while (std::getline(stream, item, delimiter)) {
        // Trim each item
        auto start = item.find_first_not_of(" \t");
        auto end   = item.find_last_not_of(" \t");
        if (start != std::string::npos) {
            result.push_back(item.substr(start, end - start + 1));
        }
    }
    return result;
}

// ─── ConfigParser: Loading ───────────────────────────────────────

void ConfigParser::load_file(const std::string& filepath) {
    // Check file exists
    if (!std::filesystem::exists(filepath)) {
        throw ConfigException("Config file not found: " + filepath);
    }

    std::ifstream file(filepath);
    if (!file.is_open()) {
        throw ConfigException("Cannot open config file: " + filepath);
    }

    // Read entire file
    std::ostringstream ss;
    ss << file.rdbuf();

    if (file.bad()) {
        throw ConfigException("Error reading config file: " + filepath);
    }

    parse(ss.str(), filepath);
}

void ConfigParser::load_string(const std::string& content,
                                const std::string& source_name) {
    parse(content, source_name);
}

// ─── ConfigParser: Parsing Core ──────────────────────────────────

void ConfigParser::parse(const std::string& content,
                          const std::string& source) {
    std::istringstream stream(content);
    std::string line;
    std::string current_section;
    int line_num = 0;

    while (std::getline(stream, line)) {
        ++line_num;

        // Remove inline comments (but not inside quoted values)
        auto comment_pos = std::string::npos;
        bool in_quotes = false;
        for (std::size_t i = 0; i < line.size(); ++i) {
            if (line[i] == '"' || line[i] == '\'') {
                in_quotes = !in_quotes;
            } else if (!in_quotes && (line[i] == '#' || line[i] == ';')) {
                comment_pos = i;
                break;
            }
        }
        if (comment_pos != std::string::npos) {
            line = line.substr(0, comment_pos);
        }

        std::string trimmed = trim(line);

        // Skip blank lines
        if (trimmed.empty()) {
            continue;
        }

        // Section header: [section_name]
        if (is_section_header(trimmed)) {
            current_section = extract_section_name(trimmed, source, line_num);

            // Track section order (only first occurrence)
            if (data_.find(current_section) == data_.end()) {
                section_order_.push_back(current_section);
                data_[current_section] = Section{};
            }
            continue;
        }

        // Key = Value pair
        if (trimmed.find('=') != std::string::npos) {
            if (current_section.empty()) {
                throw ConfigParseError(source, line_num, line,
                    "key-value pair found outside of any section");
            }

            auto [key, value] = extract_key_value(trimmed, source, line_num);

            // Check for duplicate keys (warn, last one wins)
            if (data_[current_section].count(key)) {
                std::cerr << source << ":" << line_num
                          << ": warning: duplicate key '" << key
                          << "' in [" << current_section << "]\n";
            }

            data_[current_section][key] = value;
            continue;
        }

        // If we reach here, it's an unrecognized line
        throw ConfigParseError(source, line_num, line,
            "unrecognized syntax (expected [section], key=value, or comment)");
    }

    if (data_.empty()) {
        throw ConfigParseError(source, 0, "",
            "config file is empty or contains no valid entries");
    }
}

// ─── ConfigParser: Value Access ──────────────────────────────────

ConfigValue ConfigParser::get(const std::string& section,
                               const std::string& key) const {
    auto sec_it = data_.find(section);
    if (sec_it == data_.end()) {
        throw ConfigKeyError(section, key);
    }

    auto key_it = sec_it->second.find(key);
    if (key_it == sec_it->second.end()) {
        throw ConfigKeyError(section, key);
    }

    return ConfigValue(key_it->second, section, key);
}

std::string ConfigParser::get_or(const std::string& section,
                                  const std::string& key,
                                  const std::string& default_val) const {
    auto sec_it = data_.find(section);
    if (sec_it == data_.end()) return default_val;

    auto key_it = sec_it->second.find(key);
    if (key_it == sec_it->second.end()) return default_val;

    return key_it->second;
}

std::optional<ConfigValue> ConfigParser::try_get(
    const std::string& section, const std::string& key) const {
    auto sec_it = data_.find(section);
    if (sec_it == data_.end()) return std::nullopt;

    auto key_it = sec_it->second.find(key);
    if (key_it == sec_it->second.end()) return std::nullopt;

    return ConfigValue(key_it->second, section, key);
}

// ─── ConfigParser: Query ─────────────────────────────────────────

bool ConfigParser::has_section(const std::string& section) const {
    return data_.count(section) > 0;
}

bool ConfigParser::has_key(const std::string& section,
                            const std::string& key) const {
    auto it = data_.find(section);
    if (it == data_.end()) return false;
    return it->second.count(key) > 0;
}

std::vector<std::string> ConfigParser::sections() const {
    return section_order_;
}

std::vector<std::string> ConfigParser::keys(const std::string& section) const {
    auto it = data_.find(section);
    if (it == data_.end()) return {};

    std::vector<std::string> result;
    result.reserve(it->second.size());
    for (const auto& [k, v] : it->second) {
        result.push_back(k);
    }
    return result;
}

// ─── ConfigParser: Modification ──────────────────────────────────

void ConfigParser::set(const std::string& section,
                        const std::string& key,
                        const std::string& value) {
    if (data_.find(section) == data_.end()) {
        section_order_.push_back(section);
    }
    data_[section][key] = value;
}

void ConfigParser::remove_key(const std::string& section,
                               const std::string& key) {
    auto it = data_.find(section);
    if (it != data_.end()) {
        it->second.erase(key);
    }
}

void ConfigParser::remove_section(const std::string& section) {
    data_.erase(section);
    section_order_.erase(
        std::remove(section_order_.begin(), section_order_.end(), section),
        section_order_.end());
}

// ─── ConfigParser: Serialization ─────────────────────────────────

std::string ConfigParser::to_string() const {
    std::ostringstream ss;
    for (const auto& sec_name : section_order_) {
        ss << "[" << sec_name << "]\n";
        auto it = data_.find(sec_name);
        if (it != data_.end()) {
            for (const auto& [key, val] : it->second) {
                ss << key << " = " << val << "\n";
            }
        }
        ss << "\n";
    }
    return ss.str();
}

void ConfigParser::save_file(const std::string& filepath) const {
    std::ofstream file(filepath);
    if (!file.is_open()) {
        throw ConfigException("Cannot write to file: " + filepath);
    }
    file << to_string();
}

void ConfigParser::dump(std::ostream& os) const {
    os << "=== Config Dump ===\n";
    for (const auto& sec_name : section_order_) {
        os << "[" << sec_name << "]\n";
        auto it = data_.find(sec_name);
        if (it != data_.end()) {
            for (const auto& [key, val] : it->second) {
                os << "  " << key << " = \"" << val << "\"\n";
            }
        }
    }
    os << "===================\n";
}

// ─── ConfigParser: String Helpers ────────────────────────────────

std::string ConfigParser::trim(const std::string& s) {
    auto start = s.find_first_not_of(" \t\r\n");
    if (start == std::string::npos) return "";
    auto end = s.find_last_not_of(" \t\r\n");
    return s.substr(start, end - start + 1);

