## Core CSV Reader

```kotlin
// CsvReader.kt
import java.io.BufferedReader
import java.io.InputStream
import java.io.InputStreamReader
import java.nio.file.Files
import java.nio.file.Path

/**
 * Represents a single parsed CSV row with column access by name or index.
 */
class CsvRow(
    val index: Int,
    val headers: List<String>,
    private val values: List<String>
) {
    /** Access field by column name (case-insensitive). */
    operator fun get(column: String): String? {
        val colIndex = headers.indexOfFirst { it.equals(column, ignoreCase = true) }
        return if (colIndex in values.indices) values[colIndex] else null
    }

    /** Access field by column index. */
    operator fun get(colIndex: Int): String? =
        if (colIndex in values.indices) values[colIndex] else null

    /** Return non-null value or throw with a clear message. */
    fun require(column: String): String =
        get(column) ?: throw MigrationException("Row $index: missing required column '$column'")

    fun toMap(): Map<String, String> =
        headers.zip(values).toMap()

    override fun toString(): String = "Row#$index${toMap()}"
}

/**
 * Streaming CSV reader that handles:
 *  - Custom delimiters
 *  - Quoted fields (with escaped quotes)
 *  - Blank line skipping
 *  - BOM stripping
 */
class CsvReader(
    private val delimiter: Char = ',',
    private val quote: Char = '"',
    private val skipBlankLines: Boolean = true,
    private val trimFields: Boolean = true
) {

    /** Read from a file path. */
    fun read(path: Path): CsvData {
        val reader = Files.newBufferedReader(path, Charsets.UTF_8)
        return parse(reader)
    }

    /** Read from an InputStream (useful for classpath resources or tests). */
    fun read(input: InputStream): CsvData {
        val reader = BufferedReader(InputStreamReader(input, Charsets.UTF_8))
        return parse(reader)
    }

    /** Read from a raw string. */
    fun readString(csv: String): CsvData =
        parse(csv.reader().buffered())

    // ── Parsing ────────────────────────────────────────────────

    private fun parse(reader: BufferedReader): CsvData = reader.use { br ->
        val lines = br.lineSequence()
            .map { it.stripBom() }
            .let { seq -> if (skipBlankLines) seq.filter { it.isNotBlank() } else seq }
            .toList()

        if (lines.isEmpty()) return CsvData(emptyList(), emptyList())

        val headers = parseLine(lines.first())
        val rows = lines.drop(1).mapIndexed { idx, line ->
            val values = parseLine(line)
            CsvRow(index = idx + 1, headers = headers, values = values)
        }

        CsvData(headers, rows)
    }

    /**
     * RFC-4180-aware line parser that respects quoted fields
     * containing delimiters, newlines, and escaped quotes ("").
     */
    internal fun parseLine(line: String): List<String> {
        val fields = mutableListOf<String>()
        val current = StringBuilder()
        var inQuotes = false
        var i = 0

        while (i < line.length) {
            val ch = line[i]
            when {
                // Start or end of a quoted section
                ch == quote && !inQuotes -> {
                    inQuotes = true
                }
                // Escaped quote inside a quoted field
                ch == quote && inQuotes && i + 1 < line.length && line[i + 1] == quote -> {
                    current.append(quote)
                    i++ // skip next quote
                }
                // End of quoted section
                ch == quote && inQuotes -> {
                    inQuotes = false
                }
                // Delimiter outside quotes → field boundary
                ch == delimiter && !inQuotes -> {
                    fields.add(finishField(current))
                    current.clear()
                }
                else -> current.append(ch)
            }
            i++
        }
        fields.add(finishField(current))
        return fields
    }

    private fun finishField(sb: StringBuilder): String =
        if (trimFields) sb.toString().trim() else sb.toString()

    private fun String.stripBom(): String =
        if (startsWith("\uFEFF")) substring(1) else this
}

/** Wrapper holding parsed headers and rows. */
data class CsvData(
    val headers: List<String>,
    val rows: List<CsvRow>
) {
    val size: Int get() = rows.size
    fun isEmpty(): Boolean = rows.isEmpty()
}

/** Typed exception for migration problems. */
class MigrationException(message: String, cause: Throwable? = null) :
    RuntimeException(message, cause)
