## Field Mapper / Transformer DSL

```kotlin
// FieldMapper.kt

/**
 * Describes how to transform a source CSV row into a target record (Map).
 * Built with a small DSL so mappings are declarative.
 *
 * Usage:
 *   val mapper = FieldMapper {
 *       map("first_name")  to "firstName"
 *       map("last_name")   to "lastName"  transform { it.uppercase() }
 *       map("email")       to "email"     validate { it.contains("@") }
 *       constant("source") value "legacy-crm"
 *       computed("fullName") { row -> "${row.require("first_name")} ${row.require("last_name")}" }
 *   }
 */
class FieldMapper(block: FieldMapperDsl.() -> Unit) {

    private val mappings: List<FieldMapping>

    init {
        val dsl = FieldMapperDsl()
        dsl.block()
        mappings = dsl.build()
    }

    /** Apply all mappings to a single row. Returns the target record. */
    fun apply(row: CsvRow): MappingResult {
        val target = mutableMapOf<String, String>()
        val errors = mutableListOf<String>()

        for (mapping in mappings) {
            try {
                val value = mapping.resolve(row)

                // Run validation if present
                mapping.validator?.let { validator ->
                    if (!validator(value)) {
                        errors.add("Row ${row.index}: validation failed for '${mapping.targetName}' (value='$value')")
                        return@let
                    }
                }

                target[mapping.targetName] = value
            } catch (e: Exception) {
                errors.add("Row ${row.index}: ${e.message}")
            }
        }

        return MappingResult(row.index, target, errors)
    }
}

data class MappingResult(
    val rowIndex: Int,
    val record: Map<String, String>,
    val errors: List<String>
) {
    val isValid: Boolean get() = errors.isEmpty()
}

// ── DSL internals ───────────────────────────────────────────

class FieldMapperDsl {
    private val mappings = mutableListOf<FieldMapping>()

    /** Map a source column. Chain with `to`, `transform`, `validate`. */
    fun map(sourceColumn: String) = ColumnMappingBuilder(sourceColumn).also { mappings.add(it) }

    /** Add a constant value to every target record. */
    fun constant(targetName: String) = ConstantBuilder(targetName).also { mappings.add(it) }

    /** Compute a target field from the entire row. */
    fun computed(targetName: String, computation: (CsvRow) -> String) {
        mappings.add(ComputedMapping(targetName, computation))
    }

    fun build(): List<FieldMapping> = mappings.toList()
}

/** Shared interface for every kind of field mapping. */
sealed interface FieldMapping {
    val targetName: String
    val validator: ((String) -> Boolean)?
    fun resolve(row: CsvRow): String
}

class ColumnMappingBuilder(
    private val sourceColumn: String
) : FieldMapping {

    override var targetName: String = sourceColumn    // default: same name
        private set
    private var transformer: ((String) -> String)? = null
    override var validator: ((String) -> Boolean)? = null
        private set

    infix fun to(target: String): ColumnMappingBuilder {
        targetName = target; return this
    }

    infix fun transform(fn: (String) -> String): ColumnMappingBuilder {
        transformer = fn; return this
    }

    infix fun validate(fn: (String) -> Boolean): ColumnMappingBuilder {
        validator = fn; return this
    }

    override fun resolve(row: CsvRow): String {
        val raw = row.require(sourceColumn)
        return transformer?.invoke(raw) ?: raw
    }
}

class ConstantBuilder(override val targetName: String) : FieldMapping {
    private var constantValue: String = ""
    override var validator: ((String) -> Boolean)? = null
        private set

    infix fun value(v: String): ConstantBuilder {
        constantValue = v; return this
    }

    override fun resolve(row: CsvRow): String = constantValue
}

class ComputedMapping(
    override val targetName: String,
    private val computation: (CsvRow) -> String
) : FieldMapping {
    override val validator: ((String) -> Boolean)? = null
    override fun resolve(row: CsvRow): String = computation(row)
}
```

## Migration Engine

```kotlin
// MigrationEngine.kt
import java.nio.file.Path

/**
 * Orchestrates the full migration pipeline:
 *   read → filter → map → collect results → report
 */
class MigrationEngine(
    private val reader: CsvReader = CsvReader(),
    private val mapper: FieldMapper,
    private val rowFilter: ((CsvRow) -> Boolean)? = null,
    private val batchSize: Int = 500
) {

    /** Run against a file path. */
    fun migrate(source: Path, sink: (List<Map<String, String>>) -> Unit): MigrationReport =
        migrate(reader.read(source), sink)

    /** Run against a CSV string (handy for testing). */
    fun migrateString(csv: String, sink: (List<Map<String, String>>) -> Unit): MigrationReport =
        migrate(reader.readString(csv), sink)

    private fun migrate(
        data: CsvData,
        sink: (List<Map<String, String>>) -> Unit
    ): MigrationReport {
        val report = MigrationReport(totalSourceRows = data.size)

        val filtered = if (rowFilter != null) {
            data.rows.filter(rowFilter).also {
                report.skippedByFilter = data.size - it.size
            }
        } else data.rows

        // Process in batches
        filtered.chunked(batchSize).forEach { batch ->
            val batchRecords = mutableListOf<Map<String, String>>()

            for (row in batch) {
                val result = mapper.apply(row)
                if (result.isValid) {
                    batchRecords.add(result.record)
                    report.successCount++
                } else {
                    report.errors.addAll(result.errors)
                    report.failureCount++
                }
            }

            // Hand valid records to the consumer (DB insert, API call, file write…)
            if (batchRecords.isNotEmpty()) {
                try {
                    sink(batchRecords)
                } catch (e: Exception) {
                    report.errors.add("Batch write failed: ${e.message}")
                    report.failureCount += batchRecords.size
                    report.successCount -= batchRecords.size
                }
            }
        }

        return report
    }
}
