```kotlin
// Main.kt
import java.nio.file.Paths

fun main() {
    // ── 1. Define the field mapping ────────────────────────────
    val mapper = FieldMapper {
        map("first_name") to "firstName" transform { it.trim().replaceFirstChar(Char::uppercase) }
        map("last_name")  to "lastName"  transform { it.trim().uppercase() }
        map("email")      to "email"     validate  { "@" in it && "." in it }
        map("age")        to "age"       validate  { it.toIntOrNull() != null && it.toInt() in 0..150 }
        constant("source")               value     "legacy-csv"
        computed("displayName") { row ->
            "${row.require("first_name").trim()} ${row.require("last_name").trim()}"
        }
    }

    // ── 2. Build the engine ────────────────────────────────────
    val engine = MigrationEngine(
        reader    = CsvReader(delimiter = ',', trimFields = true),
        mapper    = mapper,
        rowFilter = { row -> row["email"]?.isNotBlank() == true },  // skip empty emails
        batchSize = 100
    )

    // ── 3. Sample CSV (in practice, use a file path) ──────────
    val sampleCsv = """
        first_name,last_name,email,age
        alice,smith,alice@example.com,30
        bob,jones,bob@example.com,25
        charlie,brown,,40
        dana,white,dana@example.com,invalid
        "eve, the great",black,eve@example.com,28
    """.trimIndent()

    // ── 4. Run migration ──────────────────────────────────────
    val report = engine.migrateString(sampleCsv) { batch ->
        // This lambda is your "sink": write to a DB, call an API, etc.
        println("  Writing batch of ${batch.size} records:")
        batch.forEach { record ->
            println("    → $record")
        }
    }

    // ── 5. Print report ───────────────────────────────────────
    println()
    report.printSummary()

    // ── Bonus: read from file ─────────────────────────────────
