    private val documents = ConcurrentHashMap<String, Document>()

    // FIX 2: ConcurrentHashMap + CopyOnWriteArrayList for thread safety
    private val invertedIndex = ConcurrentHashMap<String, CopyOnWriteArrayList<String>>()

    /**
     * Tokenizes text: lowercases, splits on non-alphanumeric, removes blanks.
     */
    private fun tokenize(text: String): List<String> {
        // FIX 3: Normalize to lowercase + proper splitting
        return text
            .lowercase()
            .split(Regex("[^a-z0-9]+"))
            .filter { it.isNotBlank() }
    }

    fun indexDocument(doc: Document) {
        logger.info("Indexing document: ${doc.id}")
        documents[doc.id] = doc

        val tokens = tokenize(doc.title) + tokenize(doc.body) +
                     doc.tags.flatMap { tokenize(it) }

        val uniqueTokens = tokens.toSet()               // avoid duplicate postings

        for (token in uniqueTokens) {
            // FIX 4: Safe getOrPut — never throws NPE
            invertedIndex
                .getOrPut(token) { CopyOnWriteArrayList() }
                .add(doc.id)
        }
    }

    fun search(query: String): SearchResult {
        val startTime = System.nanoTime()

        // FIX 5: Lowercase the query tokens to match index
        val tokens = tokenize(query)

        if (tokens.isEmpty()) {
            return SearchResult(emptyList(), 0, 0)
        }

        val matchingIds = mutableSetOf<String>()

        for (token in tokens) {
            // FIX 6: Safe-call + orEmpty → no NPE
            val ids = invertedIndex[token].orEmpty()
            matchingIds.addAll(ids)
        }

        // FIX 7: Use mapNotNull to skip deleted/missing docs
        val results = matchingIds.mapNotNull { id -> documents[id] }

        val queryTimeMs = (System.nanoTime() - startTime) / 1_000_000

        return SearchResult(
            documents = results,
            totalHits = results.size,                   // FIX 8: accurate count
            queryTimeMs = queryTimeMs
        )
    }

    fun deleteDocument(id: String): Boolean {
        val removed = documents.remove(id)

        // FIX 9: Also remove from inverted index
        if (removed != null) {
            logger.info("Deleting document: $id")
            invertedIndex.values.forEach { postingList ->
                postingList.remove(id)
            }
            return true
        }
        return false
    }

    fun getDocument(id: String): Document? = documents[id]

    fun documentCount(): Int = documents.size
}

// ───── API Server (FIXED) ─────
fun main() {
    val index = SearchIndex()
    val logger = LoggerFactory.getLogger("SearchAPI")

    embeddedServer(Netty, port = 8080) {

        // FIX 10: Install ContentNegotiation with JSON
        install(ContentNegotiation) {
            json(Json {
                prettyPrint = true
                isLenient = false
                ignoreUnknownKeys = true
            })
        }

        // FIX 11: Global error handler via StatusPages
        install(StatusPages) {
            exception<ContentTransformationException> { call, cause ->
                logger.warn("Bad request: ${cause.message}")
                call.respond(
                    HttpStatusCode.BadRequest,
                    ApiError("Invalid JSON: ${cause.message}", 400)
                )
            }
            exception<Throwable> { call, cause ->
                logger.error("Internal error", cause)
                call.respond(
                    HttpStatusCode.InternalServerError,
                    ApiError("Internal server error", 500)
                )
            }
        }

        routing {

            // ── Health check ──
            get("/health") {
                call.respond(mapOf(
                    "status" to "ok",
                    "documents" to index.documentCount()
                ))
            }

            // ── Index a document ──
            post("/index") {
                val doc = call.receive<Document>()

                // FIX 12: Validate input
                when (val result = doc.validate()) {
                    is ValidationResult.Valid -> {
                        index.indexDocument(doc)
                        // FIX 13: Return 201 Created
                        call.respond(HttpStatusCode.Created, doc)
                    }
                    is ValidationResult.Invalid -> {
                        call.respond(
                            HttpStatusCode.BadRequest,
                            ApiError(result.reason, 400)
                        )
                    }
                }
            }

            // ── Bulk index ──
            post("/index/bulk") {
                val docs = call.receive<List<Document>>()
                val errors = mutableListOf<String>()
                var indexed = 0

                docs.forEach { doc ->
                    when (val v = doc.validate()) {
                        is ValidationResult.Valid   -> {
                            index.indexDocument(doc); indexed++
                        }
                        is ValidationResult.Invalid ->
                            errors.add("${doc.id}: ${v.reason}")
                    }
                }

                call.respond(HttpStatusCode.OK, mapOf(
                    "indexed" to indexed,
                    "errors"  to errors
                ))
            }

            // ── Search ──
            get("/search") {
                // FIX 14: Null/empty check on query param
                val query = call.request.queryParameters["q"]

                if (query.isNullOrBlank()) {
                    call.respond(
                        HttpStatusCode.BadRequest,
                        ApiError("Query parameter 'q' is required", 400)
                    )
                    return@get
                }

                val results = index.search(query)
                // FIX 15: ContentNegotiation auto-serializes to JSON
                call.respond(HttpStatusCode.OK, results)
            }

            // ── Get document by ID ──
            get("/documents/{id}") {
                val id = call.parameters["id"]
                    ?: return@get call.respond(
                        HttpStatusCode.BadRequest,
                        ApiError("Missing document ID", 400)
                    )

                val doc = index.getDocument(id)

                // FIX 16: Return 404 when not found
                if (doc != null) {
                    call.respond(HttpStatusCode.OK, doc)
                } else {
                    call.respond(
                        HttpStatusCode.NotFound,
                        ApiError("Document '$id' not found", 404)
                    )
                }
            }

            // ── Delete document ──
            delete("/documents/{id}") {
                val id = call.parameters["id"]
                    ?: return@delete call.respond(
                        HttpStatusCode.BadRequest,
                        ApiError("Missing document ID", 400)
                    )

                // FIX 17: Distinguish "deleted" from "not found"
                if (index.deleteDocument(id)) {
                    call.respond(HttpStatusCode.NoContent)        // 204
                } else {
                    call.respond(
                        HttpStatusCode.NotFound,
                        ApiError("Document '$id' not found", 404)
                    )
                }
            }
        }
    }.start(wait = true)
}
