# Background Worker with Rate Limiting in Kotlin

Here's a comprehensive example using Kotlin coroutines with a **Token Bucket** rate limiter pattern:

## Rate Limiter Implementation

```kotlin
import kotlinx.coroutines.*
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import java.time.Instant
import java.util.concurrent.atomic.AtomicBoolean
import kotlin.math.min

// ---------- Token Bucket Rate Limiter ----------

class TokenBucketRateLimiter(
    private val maxTokens: Int,          // bucket capacity
    private val refillRate: Double,      // tokens added per second
) {
    private var availableTokens: Double = maxTokens.toDouble()
    private var lastRefillTime: Long = System.nanoTime()
    private val mutex = Mutex()

    /** Attempts to acquire a token without waiting. */
    suspend fun tryAcquire(): Boolean = mutex.withLock {
        refill()
        if (availableTokens >= 1.0) {
            availableTokens -= 1.0
            true
        } else {
            false
        }
    }

    /** Blocks (suspends) until a token is available. */
    suspend fun acquire() {
        while (true) {
            val waitMs = mutex.withLock {
                refill()
                if (availableTokens >= 1.0) {
                    availableTokens -= 1.0
                    return  // token acquired
                }
                // Calculate wait time for the next token
                ((1.0 - availableTokens) / refillRate * 1000).toLong().coerceAtLeast(1)
            }
            delay(waitMs)
        }
    }

    /** Returns current token count (for monitoring). */
    suspend fun available(): Double = mutex.withLock {
        refill()
        availableTokens
    }

    private fun refill() {
        val now = System.nanoTime()
        val elapsed = (now - lastRefillTime) / 1_000_000_000.0
        availableTokens = min(maxTokens.toDouble(), availableTokens + elapsed * refillRate)
        lastRefillTime = now
    }
}
```

