## Background Worker

```kotlin
// ---------- Background Worker ----------

class RateLimitedWorker(
    private val rateLimiter: TokenBucketRateLimiter,
    private val maxRetries: Int = 3,
    private val concurrency: Int = 4,
    private val queueCapacity: Int = 100,
    private val scope: CoroutineScope = CoroutineScope(Dispatchers.Default + SupervisorJob()),
) {
    private val taskChannel = Channel<Task>(capacity = queueCapacity)
    private val resultChannel = Channel<TaskResult>(capacity = Channel.UNLIMITED)
    private val running = AtomicBoolean(false)

    // Callback for results (optional observer pattern)
    var onResult: (suspend (TaskResult) -> Unit)? = null

    /** Start the worker pool. */
    fun start() {
        if (!running.compareAndSet(false, true)) {
            println("⚠️  Worker already running")
            return
        }

        println("🚀 Starting worker with $concurrency consumers, rate=${rateLimiter})")

        // Launch N consumer coroutines
        repeat(concurrency) { workerId ->
            scope.launch { consumeLoop(workerId) }
        }

        // Launch a result dispatcher
        scope.launch { dispatchResults() }
    }

    /** Enqueue a task for processing. Suspends if the queue is full. */
    suspend fun submit(task: Task) {
        taskChannel.send(task)
        println("📥 Task ${task.id} queued")
    }

    /** Try to enqueue without suspending. Returns false if queue is full. */
    fun trySubmit(task: Task): Boolean {
        val result = taskChannel.trySend(task)
        if (result.isSuccess) println("📥 Task ${task.id} queued")
        return result.isSuccess
    }

    /** Graceful shutdown: finish queued work, then stop. */
    suspend fun shutdown() {
        println("🛑 Shutting down worker...")
        taskChannel.close()                // no more new tasks
        scope.coroutineContext[Job]?.children?.forEach { it.join() }
        resultChannel.close()
        running.set(false)
        println("✅ Worker stopped")
    }

    // ---- internal ----

    private suspend fun consumeLoop(workerId: Int) {
        for (task in taskChannel) {        // suspends until a task arrives; exits when channel closes
            processWithRetry(workerId, task)
        }
        println("   Worker-$workerId finished")
    }

    private suspend fun processWithRetry(workerId: Int, task: Task) {
        var attempt = 0
        var lastError: String? = null

        while (attempt <= maxRetries) {
            // ⏳ Wait for rate limiter before each attempt
            rateLimiter.acquire()

            attempt++
            println("   ⚙️ Worker-$workerId processing ${task.id} (attempt $attempt)")

            when (val result = executeTask(task)) {
                is TaskResult.Success -> {
                    resultChannel.send(result)
                    return
                }
                is TaskResult.Failure -> {
                    lastError = result.error
                    if (!result.retryable || attempt > maxRetries) {
                        resultChannel.send(result)
                        return
                    }
                    // Exponential back-off before retry
                    val backoff = (1000L * attempt).coerceAtMost(8000L)
                    println("   🔄 Retrying ${task.id} in ${backoff}ms (${result.error})")
                    delay(backoff)
                }
            }
        }

        resultChannel.send(
            TaskResult.Failure(task.id, "Exhausted retries: $lastError", retryable = false)
        )
    }

    /**
     * Simulates actual work (e.g., an HTTP API call).
     * Replace this with real logic.
     */
    private suspend fun executeTask(task: Task): TaskResult {
        delay(100) // simulate I/O

        return when {
            task.payload.contains("fail-permanent") ->
                TaskResult.Failure(task.id, "Permanent error", retryable = false)

            task.payload.contains("fail-transient") && Math.random() < 0.6 ->
                TaskResult.Failure(task.id, "Transient error (429 / timeout)", retryable = true)

            else ->
                TaskResult.Success(task.id, "Processed '${task.payload}' at ${Instant.now()}")
        }
    }

    private suspend fun dispatchResults() {
        for (result in resultChannel) {
            when (result) {
                is TaskResult.Success ->
                    println("   ✅ ${result.taskId}: ${result.response}")
                is TaskResult.Failure ->
                    println("   ❌ ${result.taskId}: ${result.error}")
            }
            onResult?.invoke(result)
        }
    }
}
```

