using namespace std;
using Clock = chrono::steady_clock;
using TimePoint = chrono::time_point<Clock>;

// ─── Report Task ────────────────────────────────────────────
struct ReportTask {
    int id;
    string name;
    TimePoint scheduledTime;
    int priority;               // lower = higher priority
    function<string()> generator;
    bool recurring;
    chrono::seconds interval;

    // BUG 1: Wrong comparison operator — causes priority inversion
    bool operator>(const ReportTask& other) const {
        return priority > other.priority;   // ← inverted for min-heap?
    }
};

// ─── Report Result ──────────────────────────────────────────
struct ReportResult {
    int taskId;
    string content;
    TimePoint generatedAt;
    bool success;
};

// ─── Report Scheduler ──────────────────────────────────────
class ReportScheduler {
public:
    ReportScheduler(int maxWorkers)
        // BUG 2: member not initialized — running_ is indeterminate
        : maxWorkers_(maxWorkers), nextId_(0)
    {}

    ~ReportScheduler() {
        // BUG 3: no graceful shutdown — threads may be joinable
    }

    int scheduleReport(const string& name,
                       function<string()> generator,
                       int priority,
                       chrono::seconds delay,
                       bool recurring = false,
                       chrono::seconds interval = chrono::seconds(0))
    {
        // BUG 4: no lock — race condition on shared taskQueue_
        int id = nextId_++;
        ReportTask task{
            id, name,
            Clock::now() + delay,
            priority,
            generator,          // BUG 5: should std::move
            recurring,
            interval
        };
        taskQueue_.push(task);
        cv_.notify_one();
        return id;
    }

    void start() {
        running_ = true;
        for (int i = 0; i < maxWorkers_; ++i) {
            // BUG 6: capturing loop variable i by reference
            workers_.emplace_back([&, i]() { workerLoop(); });
        }
        schedulerThread_ = thread(&ReportScheduler::schedulerLoop, this);
    }

    void stop() {
        running_ = false;
        cv_.notify_all();
        // BUG 7: not joining worker threads — undefined behaviour
        if (schedulerThread_.joinable())
            schedulerThread_.join();
    }

    vector<ReportResult> getResults() {
        // BUG 8: no lock — data race on results_
        return results_;
    }

    void printResults() {
        auto res = getResults();
        for (auto& r : res) {           // BUG 9: could be empty check
            cout << "Task " << r.taskId
                 << (r.success ? " [OK] " : " [FAIL] ")
                 << r.content << "\n";
        }
    }

private:
    void schedulerLoop() {
        while (running_) {
            unique_lock<mutex> lock(mtx_);
            // BUG 10: spurious wake-up not handled correctly
            cv_.wait(lock);

            while (!taskQueue_.empty()) {
                auto& task = taskQueue_.top();

                if (Clock::now() < task.scheduledTime) {
                    // Not yet time — but we break without re-waiting
                    break;
                }

                ReportTask t = task;
                taskQueue_.pop();
                lock.unlock();

                executeTask(t);

                lock.lock();              // re-acquire for next iteration
            }
        }
    }

    void workerLoop() {
        // placeholder — work is done inline in schedulerLoop (design issue)
    }

    void executeTask(ReportTask task) {
        ReportResult result;
        result.taskId = task.id;
        result.generatedAt = Clock::now();

        try {
            result.content = task.generator();
            result.success = true;
        } catch (...) {
            result.content = "Generation failed";
            result.success = false;
        }

        results_.push_back(result);       // no lock — data race

        if (task.recurring) {
            // Re-schedule but no lock acquired
            task.scheduledTime = Clock::now() + task.interval;
            taskQueue_.push(task);
        }
    }

    int maxWorkers_;
    atomic<int> nextId_;
    atomic<bool> running_;                // BUG 2 continued
    mutex mtx_;
    condition_variable cv_;

    // BUG 1 continued: comparator mismatch with std::greater
    priority_queue<ReportTask, vector<ReportTask>, greater<ReportTask>> taskQueue_;

    vector<ReportResult> results_;
    vector<thread> workers_;
    thread schedulerThread_;
};

