    ReportScheduler scheduler(4);

    scheduler.scheduleReport("Daily Sales",
        []() { return "Sales: $12,340"; }, 1, chrono::seconds(2), true, chrono::seconds(5));

    scheduler.scheduleReport("Inventory",
        []() { return "Items: 1,204"; }, 2, chrono::seconds(1));

    scheduler.scheduleReport("Faulty Report",
        []() -> string { throw runtime_error("DB down"); }, 1, chrono::seconds(3));

    scheduler.start();
    this_thread::sleep_for(chrono::seconds(10));
    scheduler.stop();
    scheduler.printResults();
}
