                       function<string()> generator,
                       int priority,
                       chrono::seconds delay,
                       bool recurring        = false,
                       chrono::seconds interval = chrono::seconds(0))
    {
        // FIX 4: lock before touching taskQueue_
        lock_guard<mutex> lock(mtx_);

        int id = nextId_++;
        ReportTask task {
            id,
            name,
            Clock::now() + delay,
            priority,
            std::move(generator),       // FIX 5: move the callable
            recurring,
            interval
        };

        taskQueue_.push(std::move(task));
        cv_.notify_one();
        return id;
    }

    void start() {
        if (running_.exchange(true))     // already running
            return;

        // Launch worker threads
        for (int i = 0; i < maxWorkers_; ++i) {
            workers_.emplace_back([this, i]() { workerLoop(i); });
        }

        // Launch scheduler (dispatcher) thread
        schedulerThread_ = thread(&ReportScheduler::schedulerLoop, this);
    }

    void stop() {
        if (!running_.exchange(false))   // already stopped
            return;

        cv_.notify_all();
        workerCv_.notify_all();

        // FIX 6 & 7: join ALL threads
        if (schedulerThread_.joinable())
            schedulerThread_.join();

        for (auto& w : workers_) {
            if (w.joinable())
                w.join();
        }
        workers_.clear();
    }

    // FIX 8: thread-safe accessor
    vector<ReportResult> getResults() {
        lock_guard<mutex> lock(resultMtx_);
        return results_;
    }

    void printResults() {
        auto res = getResults();
        if (res.empty()) {
            cout << "(no reports generated yet)\n";
            return;
        }
        cout << "\n===== Generated Reports =====\n";
        for (const auto& r : res) {
            cout << "  Task #" << r.taskId
                 << " [" << r.taskName << "] "
                 << (r.success ? "OK" : "FAIL")
                 << " → " << r.content << "\n";
        }
        cout << "=============================\n";
    }

private:
    // ── Scheduler thread: moves ready tasks into the work queue ──
    void schedulerLoop() {
        while (running_) {
            unique_lock<mutex> lock(mtx_);

            // FIX 9: wait_for with predicate — handles spurious wake-ups
            //         and re-checks every 500ms for timed tasks
            cv_.wait_for(lock, chrono::milliseconds(500), [this]() {
                return !running_ || (!taskQueue_.empty()
                       && taskQueue_.top().scheduledTime <= Clock::now());
            });

            if (!running_) break;

            // Dispatch all tasks whose time has come
            while (!taskQueue_.empty()
                   && taskQueue_.top().scheduledTime <= Clock::now())
            {
                ReportTask task = taskQueue_.top();
                taskQueue_.pop();

                {
                    lock_guard<mutex> wLock(workMtx_);
                    workQueue_.push(std::move(task));
                }
                workerCv_.notify_one();
            }
        }
    }

    // ── Worker thread: picks tasks from workQueue_ ──────────────
    void workerLoop(int workerId) {
        while (running_) {
            ReportTask task;
            {
                unique_lock<mutex> lock(workMtx_);
                workerCv_.wait_for(lock, chrono::milliseconds(200), [this]() {
                    return !running_ || !workQueue_.empty();
                });

                if (!running_ && workQueue_.empty()) break;
                if (workQueue_.empty()) continue;

                task = std::move(workQueue_.front());
                workQueue_.pop();
            }

            executeTask(task, workerId);
        }
    }

    // ── Execute & store result ──────────────────────────────────
    void executeTask(ReportTask& task, int workerId) {
        ReportResult result;
        result.taskId      = task.id;
        result.taskName    = task.name;
        result.generatedAt = Clock::now();

        try {
            result.content = task.generator();
            result.success = true;
        } catch (const exception& e) {
            result.content = string("Error: ") + e.what();
            result.success = false;
        } catch (...) {
            result.content = "Unknown error";
            result.success = false;
        }

        cout << "[Worker " << workerId << "] "
             << (result.success ? "Generated" : "Failed")
             << ": " << task.name << "\n";

        // FIX 10: lock before mutating shared containers
        {
            lock_guard<mutex> lock(resultMtx_);
            results_.push_back(std::move(result));
        }

        // Re-schedule recurring tasks safely
        if (task.recurring && running_) {
            task.scheduledTime = Clock::now() + task.interval;
            {
                lock_guard<mutex> lock(mtx_);
                taskQueue_.push(std::move(task));
            }
            cv_.notify_one();
        }
    }

    // ── Data members ────────────────────────────────────────────
    int              maxWorkers_;
    atomic<int>      nextId_;
    atomic<bool>     running_;

    // Scheduler's priority queue (guarded by mtx_)
    mutex                         mtx_;
    condition_variable            cv_;
    priority_queue<ReportTask,
                   vector<ReportTask>,
                   greater<ReportTask>>  taskQueue_;

    // Worker dispatch queue (guarded by workMtx_)
    mutex                         workMtx_;
    condition_variable            workerCv_;
    queue<ReportTask>             workQueue_;

    // Results (guarded by resultMtx_)
    mutex                         resultMtx_;
    vector<ReportResult>          results_;

    // Threads
    vector<thread>                workers_;
    thread                        schedulerThread_;
};

// ─── main ───────────────────────────────────────────────────
int main() {
    ReportScheduler scheduler(4);

    scheduler.scheduleReport(
        "Daily Sales",
        []() {
            this_thread::sleep_for(chrono::milliseconds(300));  // simulate work
            return string("Sales: $12,340");
        },
        1, chrono::seconds(2),
        true, chrono::seconds(4)         // recurring every 4 s
    );

    scheduler.scheduleReport(
        "Inventory Check",
        []() {
            this_thread::sleep_for(chrono::milliseconds(200));
            return string("Items in stock: 1,204");
        },
        2, chrono::seconds(1)
    );

    scheduler.scheduleReport(
        "Faulty Report",
        []() -> string {
            throw runtime_error("Database connection lost");
        },
        1, chrono::seconds(3)
    );

    scheduler.scheduleReport(
        "Weekly Summary",
        []() {
            this_thread::sleep_for(chrono::milliseconds(500));
            return string("Revenue: $86,100 | Expenses: $41,200");
        },
        3, chrono::seconds(1)
    );

    cout << "Starting scheduler...\n\n";
    scheduler.start();

    this_thread::sleep_for(chrono::seconds(12));

    cout << "\nStopping scheduler...\n";
    scheduler.stop();

    scheduler.printResults();

    return 0;
}
