# Debugging a Swift Task Scheduler

## Buggy Code

```swift
import Foundation

// MARK: - Task Model
enum TaskPriority: Int, Comparable {
    case low = 0
    case medium = 1
    case high = 2

    static func < (lhs: TaskPriority, rhs: TaskPriority) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

struct ScheduledTask {
    let id: String
    let priority: TaskPriority
    let executeAt: Date
    let action: () -> Void
}

// MARK: - Buggy Scheduler
class TaskScheduler {
    var tasks: [ScheduledTask] = []              // BUG 1: No thread safety
    var timer: Timer?
    var isRunning = false
    var completedTaskIDs: [String] = []          // BUG 2: Unbounded growth

    func schedule(task: ScheduledTask) {
        tasks.append(task)
        // BUG 3: Tasks not sorted after insertion
    }

    func start() {
        isRunning = true
        // BUG 4: Timer retains self → memory leak
        timer = Timer.scheduledTimer(
            timeInterval: 1.0,
            target: self,
            selector: #selector(tick),
            userInfo: nil,
            repeats: true
        )
    }

    @objc func tick() {
        let now = Date()
        // BUG 5: Mutating array while iterating
        for (index, task) in tasks.enumerated() {
            if task.executeAt <= now {
                task.action()
                completedTaskIDs.append(task.id)
                tasks.remove(at: index)          // Crash: index out of range
            }
        }
    }

    func cancel(taskID: String) {
        // BUG 6: Only removes first match, ignores return value
        tasks.remove(at: tasks.firstIndex(where: { $0.id == taskID })!)
        // Force unwrap crashes if ID not found
    }

    func stop() {
        isRunning = false
        // BUG 7: Timer never invalidated
    }

    // BUG 8: No deinit cleanup

    func getNextTask() -> ScheduledTask? {
        // BUG 9: Returns first task, not highest priority
        return tasks.first
    }
}
```

## All Bugs Identified

| # | Bug | Type | Impact |
|---|-----|------|--------|
| 1 | No thread-safe access to `tasks` | Race condition | Data corruption/crash |
| 2 | `completedTaskIDs` grows forever | Memory leak | OOM over time |
| 3 | Tasks not sorted by priority/time | Logic error | Wrong execution order |
| 4 | `Timer` + `target: self` | Retain cycle | Memory leak |
| 5 | Mutating array while iterating | Runtime crash | Index out of range |
| 6 | Force-unwrap in `cancel()` | Force unwrap | Crash if ID missing |
| 7 | Timer never invalidated in `stop()` | Resource leak | Keeps firing |
| 8 | No `deinit` cleanup | Resource leak | Timer persists |
| 9 | `getNextTask()` ignores priority | Logic error | Wrong task returned |

## Fixed Code

```swift
import Foundation

// MARK: - Task Model
enum TaskPriority: Int, Comparable {
    case low = 0
    case medium = 1
    case high = 2

    static func < (lhs: TaskPriority, rhs: TaskPriority) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

struct ScheduledTask {
    let id: String
    let priority: TaskPriority
    let executeAt: Date
    let action: () -> Void
}

// MARK: - Fixed Scheduler
class TaskScheduler {

    // FIX 1: Thread-safe access via a serial dispatch queue
    private let queue = DispatchQueue(label: "com.scheduler.serialQueue")
    private var tasks: [ScheduledTask] = []
    private var timer: DispatchSourceTimer?          // FIX 4: Use GCD timer (no retain cycle)
    private(set) var isRunning = false

    // FIX 2: Bounded completed-task history
    private var completedTaskIDs: [String] = []
    private let maxCompletedHistory = 1000

    // MARK: - Schedule a Task
    func schedule(task: ScheduledTask) {
        queue.sync {
            tasks.append(task)
            // FIX 3: Sort by priority (desc), then by time (asc)
            tasks.sort { lhs, rhs in
                if lhs.priority != rhs.priority {
                    return lhs.priority > rhs.priority
                }
                return lhs.executeAt < rhs.executeAt
            }
        }
    }

    // MARK: - Start Scheduler
    func start() {
        queue.sync {
            guard !isRunning else { return }
            isRunning = true

            // FIX 4: GCD timer avoids retain cycles with [weak self]
            let newTimer = DispatchSource.makeTimerSource(queue: queue)
            newTimer.schedule(deadline: .now(), repeating: 1.0)
            newTimer.setEventHandler { [weak self] in
                self?.tick()
            }
            newTimer.resume()
            timer = newTimer
        }
    }

    // MARK: - Tick (process due tasks)
    private func tick() {
        // Already on `queue` — called from the timer's event handler
        let now = Date()

        // FIX 5: Collect indices to remove, then remove in reverse order
        var indicesToRemove: [Int] = []

        for (index, task) in tasks.enumerated() {
            if task.executeAt <= now {
                // Execute on a background queue so we don't block the scheduler
                DispatchQueue.global(qos: .userInitiated).async {
                    task.action()
                }
                trackCompleted(taskID: task.id)
                indicesToRemove.append(index)
            }
        }

        // Remove from highest index first to preserve lower indices
        for index in indicesToRemove.reversed() {
            tasks.remove(at: index)
        }
    }

    // MARK: - Cancel a Task
    func cancel(taskID: String) {
        queue.sync {
            // FIX 6: Safe optional handling instead of force-unwrap
            if let index = tasks.firstIndex(where: { $0.id == taskID }) {
                tasks.remove(at: index)
            } else {
                print("⚠️ Task \(taskID) not found — may have already executed.")
            }
        }
    }

    // MARK: - Stop Scheduler
    func stop() {
        queue.sync {
            isRunning = false
            // FIX 7: Invalidate (cancel) the timer
            timer?.cancel()
            timer = nil
        }
    }

    // MARK: - Cleanup
    // FIX 8: Ensure timer is released on deallocation
    deinit {
        timer?.cancel()
        timer = nil
        print("🗑️ TaskScheduler deallocated — all resources cleaned up.")
    }

    // MARK: - Get Next Task
    func getNextTask() -> ScheduledTask? {
        return queue.sync {
            // FIX 9: Tasks are pre-sorted — first element is highest priority + earliest
            return tasks.first
        }
    }

    // MARK: - Helpers
    private func trackCompleted(taskID: String) {
        completedTaskIDs.append(taskID)
        // FIX 2: Trim history when it exceeds the cap
        if completedTaskIDs.count > maxCompletedHistory {
            completedTaskIDs.removeFirst(completedTaskIDs.count - maxCompletedHistory)
        }
    }

    /// Thread-safe read of pending task count
    var pendingCount: Int {
        return queue.sync { tasks.count }
    }
}
```

