## Core CSV Parser

```swift
// CSVParser.swift
import Foundation

/// Errors that can occur during CSV parsing.
enum CSVParseError: Error, CustomStringConvertible {
    case unclosedQuote(line: Int)
    case inconsistentColumnCount(line: Int, expected: Int, got: Int)
    case emptyInput

    var description: String {
        switch self {
        case .unclosedQuote(let line):
            return "Unclosed quote on line \(line)"
        case .inconsistentColumnCount(let line, let expected, let got):
            return "Line \(line): expected \(expected) columns, got \(got)"
        case .emptyInput:
            return "Input is empty"
        }
    }
}

/// Configuration for the CSV parser.
struct CSVParserConfig {
    var delimiter: Character = ","
    var quoteCharacter: Character = "\""
    var trimWhitespace: Bool = true
    var hasHeader: Bool = true
    var strictColumnCount: Bool = true // reject rows with wrong column count
}

/// Low-level CSV parser that handles RFC 4180 rules:
/// - Quoted fields (embedded delimiters, newlines, escaped quotes)
/// - Configurable delimiter and quote character
struct CSVParser {
    let config: CSVParserConfig

    init(config: CSVParserConfig = CSVParserConfig()) {
        self.config = config
    }

    /// Parses raw CSV text into a 2D array of strings.
    func parse(_ input: String) throws -> [[String]] {
        guard !input.isEmpty else { throw CSVParseError.emptyInput }

        var rows: [[String]] = []
        var currentField = ""
        var currentRow: [String] = []
        var insideQuotes = false
        var lineNumber = 1
        var expectedColumns: Int?

        let chars = Array(input)
        var i = 0

        while i < chars.count {
            let ch = chars[i]

            if insideQuotes {
                if ch == config.quoteCharacter {
                    // Look ahead: doubled quote = escaped quote
                    if i + 1 < chars.count && chars[i + 1] == config.quoteCharacter {
                        currentField.append(ch)
                        i += 2
                        continue
                    } else {
                        // End of quoted field
                        insideQuotes = false
                        i += 1
                        continue
                    }
                } else {
                    // Track newlines inside quotes for error reporting
                    if ch == "\n" { lineNumber += 1 }
                    currentField.append(ch)
                    i += 1
                    continue
                }
            }

            // Not inside quotes
            switch ch {
            case config.quoteCharacter:
                insideQuotes = true
                i += 1

            case config.delimiter:
                currentRow.append(finishField(currentField))
                currentField = ""
                i += 1

            case "\r":
                // Handle \r\n and bare \r
                currentRow.append(finishField(currentField))
                currentField = ""
                try validateAndAppend(row: &currentRow, to: &rows,
                                      lineNumber: lineNumber,
                                      expectedColumns: &expectedColumns)
                lineNumber += 1
                i += (i + 1 < chars.count && chars[i + 1] == "\n") ? 2 : 1

            case "\n":
                currentRow.append(finishField(currentField))
                currentField = ""
                try validateAndAppend(row: &currentRow, to: &rows,
                                      lineNumber: lineNumber,
                                      expectedColumns: &expectedColumns)
                lineNumber += 1
                i += 1

            default:
                currentField.append(ch)
                i += 1
            }
        }

        // Check for unclosed quotes
        if insideQuotes {
            throw CSVParseError.unclosedQuote(line: lineNumber)
        }

        // Flush the last row (files often don't end with a newline)
        if !currentField.isEmpty || !currentRow.isEmpty {
            currentRow.append(finishField(currentField))
            try validateAndAppend(row: &currentRow, to: &rows,
                                  lineNumber: lineNumber,
                                  expectedColumns: &expectedColumns)
        }

        return rows
    }

    // MARK: - Private Helpers

    private func finishField(_ field: String) -> String {
        config.trimWhitespace ? field.trimmingCharacters(in: .whitespaces) : field
    }

    private func validateAndAppend(
        row: inout [String],
        to rows: inout [[String]],
        lineNumber: Int,
        expectedColumns: inout Int?
    ) throws {
        // Skip fully empty rows
        if row.allSatisfy({ $0.isEmpty }) && row.count <= 1 {
            row = []
            return
        }

        if config.strictColumnCount {
            if let expected = expectedColumns {
                guard row.count == expected else {
                    throw CSVParseError.inconsistentColumnCount(
                        line: lineNumber, expected: expected, got: row.count)
                }
            } else {
                expectedColumns = row.count
            }
        }

        rows.append(row)
        row = []
    }
}
```

## High-Level CSV Reader

```swift
// CSVReader.swift
import Foundation

/// A parsed CSV document with typed access by column name.
struct CSVDocument {
    let headers: [String]
    let rows: [CSVRow]

    var rowCount: Int { rows.count }
    var columnCount: Int { headers.count }

    /// Look up column index by name (case-insensitive).
    func columnIndex(for name: String) -> Int? {
        headers.firstIndex(where: { $0.lowercased() == name.lowercased() })
    }
}

/// A single row with dictionary-style and index-based access.
struct CSVRow {
    let lineNumber: Int
    let fields: [String]
    private let headerMap: [String: Int] // lowercased header -> index

    init(lineNumber: Int, fields: [String], headers: [String]) {
        self.lineNumber = lineNumber
        self.fields = fields

        var map: [String: Int] = [:]
        for (idx, header) in headers.enumerated() {
            map[header.lowercased()] = idx
        }
        self.headerMap = map
    }

    /// Access by column name (case-insensitive). Returns nil if missing.
    subscript(column: String) -> String? {
        guard let idx = headerMap[column.lowercased()],
              idx < fields.count else { return nil }
        return fields[idx]
    }

    /// Access by column index.
    subscript(index: Int) -> String? {
        guard index >= 0 && index < fields.count else { return nil }
        return fields[index]
    }

    /// Typed getters with optional conversion.
    func integer(_ column: String) -> Int? {
        self[column].flatMap(Int.init)
    }

    func double(_ column: String) -> Double? {
        self[column].flatMap(Double.init)
    }

    func bool(_ column: String) -> Bool? {
        guard let val = self[column]?.lowercased() else { return nil }
        switch val {
        case "true", "yes", "1":  return true
        case "false", "no", "0":  return false
        default:                   return nil
        }
    }

    func date(_ column: String, format: String = "yyyy-MM-dd") -> Date? {
        guard let val = self[column] else { return nil }
        let formatter = DateFormatter()
        formatter.dateFormat = format
        formatter.locale = Locale(identifier: "en_US_POSIX")
        return formatter.date(from: val)
    }
}

/// Reads CSV from strings, files, or Data and produces a CSVDocument.
struct CSVReader {
    let parser: CSVParser

    init(config: CSVParserConfig = CSVParserConfig()) {
        self.parser = CSVParser(config: config)
    }

    /// Read from a raw string.
    func read(string: String) throws -> CSVDocument {
        let raw = try parser.parse(string)
        return try buildDocument(from: raw)
    }

    /// Read from a file URL.
    func read(fileURL: URL, encoding: String.Encoding = .utf8) throws -> CSVDocument {
        let content = try String(contentsOf: fileURL, encoding: encoding)
        return try read(string: content)
    }

    /// Read from Data.
    func read(data: Data, encoding: String.Encoding = .utf8) throws -> CSVDocument {
        guard let content = String(data: data, encoding: encoding) else {
            throw CSVParseError.emptyInput
        }
        return try read(string: content)
    }

    private func buildDocument(from raw: [[String]]) throws -> CSVDocument {
        guard let headerRow = raw.first else {
            throw CSVParseError.emptyInput
        }

        let dataRows = raw.dropFirst()
        let rows = dataRows.enumerated().map { (offset, fields) in
            CSVRow(lineNumber: offset + 2, // +2: 1-indexed, skip header
                   fields: fields,
                   headers: headerRow)
        }

        return CSVDocument(headers: headerRow, rows: rows)
    }
}
