## Migration Plan (Column Mapping + Validation)

```swift
// MigrationPlan.swift
import Foundation

/// Describes how to map a source CSV column to a destination field.
struct ColumnMapping {
    let sourceColumn: String
    let destinationKey: String
    let required: Bool
    let transform: ((String) -> String?)?   // nil = pass through
    let validate: ((String) -> Bool)?        // nil = always valid

    init(
        from source: String,
        to destination: String? = nil,
        required: Bool = true,
        transform: ((String) -> String?)? = nil,
        validate: ((String) -> Bool)? = nil
    ) {
        self.sourceColumn = source
        self.destinationKey = destination ?? source
        self.required = required
        self.transform = transform
        self.validate = validate
    }
}

/// Outcome for a single row migration attempt.
enum RowResult {
    case success([String: String])
    case skipped(line: Int, reason: String)
    case failed(line: Int, errors: [String])
}

/// Full report from a migration run.
struct MigrationReport {
    let succeeded: [[String: String]]
    let skipped: [(line: Int, reason: String)]
    let failed: [(line: Int, errors: [String])]
    let totalProcessed: Int

    var summary: String {
        """
        Migration Report
        ────────────────
        Total rows processed: \(totalProcessed)
        Succeeded:            \(succeeded.count)
        Skipped:              \(skipped.count)
        Failed:               \(failed.count)
        """
    }
}

/// A plan defines column mappings plus optional row-level filters.
struct MigrationPlan {
    var mappings: [ColumnMapping] = []
    var rowFilter: ((CSVRow) -> Bool)?     // return false to skip a row
    var deduplicateOn: String?              // column name to deduplicate

    /// DSL-style builder to add a mapping.
    @discardableResult
    mutating func map(
        from source: String,
        to destination: String? = nil,
        required: Bool = true,
        transform: ((String) -> String?)? = nil,
        validate: ((String) -> Bool)? = nil
    ) -> Self {
        mappings.append(ColumnMapping(
            from: source, to: destination,
            required: required,
            transform: transform, validate: validate
        ))
        return self
    }
}
