```swift
// MigrationEngine.swift
import Foundation

/// Orchestrates reading a CSV and applying a MigrationPlan.
struct MigrationEngine {
    let reader: CSVReader

    init(readerConfig: CSVParserConfig = CSVParserConfig()) {
        self.reader = CSVReader(config: readerConfig)
    }

    /// Run a migration plan against a CSV string.
    func migrate(csvString: String, plan: MigrationPlan) throws -> MigrationReport {
        let document = try reader.read(string: csvString)
        return execute(document: document, plan: plan)
    }

    /// Run a migration plan against a file.
    func migrate(fileURL: URL, plan: MigrationPlan) throws -> MigrationReport {
        let document = try reader.read(fileURL: fileURL)
        return execute(document: document, plan: plan)
    }

    private func execute(document: CSVDocument, plan: MigrationPlan) -> MigrationReport {
        var succeeded: [[String: String]] = []
        var skipped: [(Int, String)] = []
        var failed: [(Int, [String])] = []
        var seenKeys: Set<String> = []

        // Validate that all required source columns exist
        let missingColumns = plan.mappings
            .filter { $0.required }
            .filter { document.columnIndex(for: $0.sourceColumn) == nil }
            .map { $0.sourceColumn }

        if !missingColumns.isEmpty {
            // All rows fail if required columns are missing from the header
            let err = "Missing required columns: \(missingColumns.joined(separator: ", "))"
            for row in document.rows {
                failed.append((row.lineNumber, [err]))
            }
            return MigrationReport(
                succeeded: succeeded, skipped: skipped,
                failed: failed, totalProcessed: document.rowCount)
        }

        for row in document.rows {
            let result = processRow(row, plan: plan, seenKeys: &seenKeys)
            switch result {
            case .success(let record):
                succeeded.append(record)
            case .skipped(let line, let reason):
                skipped.append((line, reason))
            case .failed(let line, let errors):
                failed.append((line, errors))
            }
        }

        return MigrationReport(
            succeeded: succeeded, skipped: skipped,
            failed: failed, totalProcessed: document.rowCount)
    }

    private func processRow(
        _ row: CSVRow,
        plan: MigrationPlan,
        seenKeys: inout Set<String>
    ) -> RowResult {

        // Row-level filter
        if let filter = plan.rowFilter, !filter(row) {
            return .skipped(line: row.lineNumber, reason: "Excluded by row filter")
        }

        var record: [String: String] = [:]
        var errors: [String] = []

        for mapping in plan.mappings {
            let rawValue = row[mapping.sourceColumn]

            // Check required
            if mapping.required && (rawValue == nil || rawValue!.isEmpty) {
                errors.append("'\(mapping.sourceColumn)' is required but empty")
                continue
            }

            guard let value = rawValue, !value.isEmpty else {
                // Optional and missing – skip this field
                continue
            }

            // Validate
            if let validate = mapping.validate, !validate(value) {
                errors.append("'\(mapping.sourceColumn)' failed validation: \"\(value)\"")
                continue
            }

            // Transform
            if let transform = mapping.transform {
                if let transformed = transform(value) {
                    record[mapping.destinationKey] = transformed
                } else {
                    errors.append("'\(mapping.sourceColumn)' transform returned nil for: \"\(value)\"")
                }
            } else {
                record[mapping.destinationKey] = value
            }
        }

        if !errors.isEmpty {
            return .failed(line: row.lineNumber, errors: errors)
        }

        // Deduplication
        if let dedupCol = plan.deduplicateOn, let key = record[dedupCol] {
            if seenKeys.contains(key) {
                return .skipped(line: row.lineNumber,
                                reason: "Duplicate \(dedupCol): \(key)")
            }
            seenKeys.insert(key)
        }

        return .success(record)
    }
}
