## Debugged Code (After Fix)

```php
<?php

/**
 * Debugged PHP Task Scheduler
 * 
 * Fixes applied:
 *  1. Proper constructor initialization & log directory creation
 *  2. Input validation on addTask()
 *  3. Correct next_run initialization
 *  4. Fixed priority sorting (descending)
 *  5. Concurrency guard with is_running flag
 *  6. Iterate by reference so mutations persist
 *  7. Full try/catch error handling
 *  8. Mutate the original array element, not a copy
 *  9. Rich log entries with timestamps and results
 * 10. Append mode + directory safety for log file
 * 11. Filter only pending tasks in getPendingTasks()
 * 12. Re-index array after unset in removeTask()
 * 13. Reference iteration + existence check in rescheduleTask()
 * 14. Correct "time until next run" calculation
 */
class TaskScheduler
{
    /** @var array<int, array> */
    private array  $tasks         = [];
    /** @var string[] */
    private array  $executedTasks = [];
    private string $logFile;
    private string $lockDir;

    // ── FIX 1: Validate & prepare log infrastructure ──────────────
    public function __construct(string $logFile, ?string $lockDir = null)
    {
        $logDirectory = dirname($logFile);

        if (!is_dir($logDirectory)) {
            if (!mkdir($logDirectory, 0755, true)) {
                throw new RuntimeException(
                    "Cannot create log directory: {$logDirectory}"
                );
            }
        }

        if (!is_writable($logDirectory)) {
            throw new RuntimeException(
                "Log directory is not writable: {$logDirectory}"
            );
        }

        $this->logFile = $logFile;
        $this->lockDir = $lockDir ?? sys_get_temp_dir() . '/scheduler_locks';

        if (!is_dir($this->lockDir)) {
            mkdir($this->lockDir, 0755, true);
        }
    }

    // ── FIX 2 & 3: Validate inputs, set correct initial next_run ─
    public function addTask(
        string   $name,
        int      $interval,
        callable $callback,
        int      $priority = 0
    ): bool {
        // FIX 2: Validate every parameter
        if (empty($name)) {
            $this->log("ERROR: Task name cannot be empty", 'error');
            return false;
        }

        if ($interval <= 0) {
            $this->log("ERROR: Interval must be positive for task '{$name}'", 'error');
            return false;
        }

        if (!is_callable($callback)) {
            $this->log("ERROR: Invalid callback for task '{$name}'", 'error');
            return false;
        }

        // Check for duplicate task names
        foreach ($this->tasks as $existing) {
            if ($existing['name'] === $name) {
                $this->log("WARNING: Task '{$name}' already exists — skipped", 'warning');
                return false;
            }
        }

        $this->tasks[] = [
            'name'       => $name,
            'interval'   => $interval,
            'callback'   => $callback,
            'priority'   => $priority,
            'last_run'   => null,
            'next_run'   => time(),        // FIX 3: runs immediately the first time
            'is_running' => false,
            'run_count'  => 0,
            'error_count'=> 0,
        ];

        $this->log("Task added: '{$name}' (interval: {$interval}s, priority: {$priority})");
        return true;
    }

    // ── FIX 4: Higher priority value → runs first (descending) ───
    private function sortByPriority(): void
    {
        usort($this->tasks, function (array $a, array $b): int {
            // If same priority, prefer the one due soonest
            if ($b['priority'] === $a['priority']) {
                return $a['next_run'] <=> $b['next_run'];
            }
            return $b['priority'] <=> $a['priority'];   // descending
        });
    }

    // ── FIX 5 & 6: Guard against re-entry; iterate by reference ──
    public function run(): array
    {
        $this->sortByPriority();
        $now     = time();
        $results = [];

        // FIX 6: & reference so changes to $task persist in $this->tasks
        foreach ($this->tasks as &$task) {

            // FIX 5: Skip tasks already running (concurrency guard)
            if ($task['is_running']) {
                $this->log("SKIP: Task '{$task['name']}' is still running", 'warning');
                continue;
            }

            if ($task['next_run'] <= $now) {
                $results[$task['name']] = $this->executeTask($task);
            }
        }
        unset($task);   // break the reference

        return $results;
    }

    // ── FIX 7, 8, 9: Error handling, reference mutation, rich logs ─
    private function executeTask(array &$task): array
    {
        $startTime = microtime(true);
        $result    = [
            'task'    => $task['name'],
            'success' => false,
            'output'  => null,
            'error'   => null,
            'duration'=> 0,
        ];

        // FIX 8: Use the reference — changes are reflected in $this->tasks
        $task['is_running'] = true;

        // Acquire a simple file lock (prevents cron overlap)
        $lockFile = $this->lockDir . '/' . md5($task['name']) . '.lock';
        $lockFp   = fopen($lockFile, 'w');

        if ($lockFp && !flock($lockFp, LOCK_EX | LOCK_NB)) {
            $this->log("LOCK: Task '{$task['name']}' is locked by another process", 'warning');
            $task['is_running'] = false;
            fclose($lockFp);
            return $result;
        }

        // FIX 7: Wrap execution in try/catch
        try {
            $output = call_user_func($task['callback']);

            $task['last_run'] = time();
            $task['next_run'] = time() + $task['interval'];
            $task['run_count']++;

            $result['success']  = true;
            $result['output']   = $output;

            // FIX 9: Log with timestamp, duration, and result
            $duration            = round(microtime(true) - $startTime, 4);
            $result['duration']  = $duration;

            $this->log(
                "SUCCESS: Task '{$task['name']}' completed in {$duration}s "
                . "(run #{$task['run_count']})"
            );

        } catch (\Throwable $e) {
            $task['error_count']++;
            $task['next_run'] = time() + $task['interval'];   // still reschedule

            $result['error'] = $e->getMessage();

            $this->log(
                "ERROR: Task '{$task['name']}' failed — {$e->getMessage()} "
                . "in {$e->getFile()}:{$e->getLine()}",
                'error'
            );
        } finally {
            $task['is_running'] = false;

            // Release the lock
            if ($lockFp) {
                flock($lockFp, LOCK_UN);
                fclose($lockFp);
                @unlink($lockFile);
            }
        }

        $this->executedTasks[] = $task['name'];

        return $result;
    }

    // ── FIX 10: Append mode, timestamps, severity level ──────────
    private function log(string $message, string $level = 'info'): void
    {
        $timestamp  = date('Y-m-d H:i:s');
        $levelUpper = strtoupper($level);
        $logLine    = "[{$timestamp}] [{$levelUpper}] {$message}" . PHP_EOL;

        // Append (FILE_APPEND) instead of overwriting
        $written = file_put_contents(
            $this->logFile,
            $logLine,
            FILE_APPEND | LOCK_EX
        );

        if ($written === false) {
            error_log("TaskScheduler: could not write to {$this->logFile}");
        }
    }

    // ── FIX 11: Return only tasks whose next_run is in the past ──
    public function getPendingTasks(): array
    {
        $now = time();

        return array_filter($this->tasks, function (array $task) use ($now): bool {
            return !$task['is_running'] && $task['next_run'] <= $now;
        });
    }

    // ── FIX 12: Re-index the array after removing a task ─────────
    public function removeTask(string $name): bool
    {
        foreach ($this->tasks as $key => $task) {
            if ($task['name'] === $name) {
                unset($this->tasks[$key]);
                $this->tasks = array_values($this->tasks);  // re-index
                $this->log("Task removed: '{$name}'");
                return true;                                  // break out
            }
        }

        $this->log("WARNING: Task '{$name}' not found for removal", 'warning');
        return false;
    }

    // ── FIX 13: Iterate by reference + existence check ───────────
    public function rescheduleTask(string $name, int $newInterval): bool
    {
        if ($newInterval <= 0) {
            $this->log("ERROR: Interval must be positive", 'error');
            return false;
        }

        foreach ($this->tasks as &$task) {           // & reference
            if ($task['name'] === $name) {
                $task['interval'] = $newInterval;
                $task['next_run'] = time() + $newInterval;
                $this->log("Task rescheduled: '{$name}' → every {$newInterval}s");
                unset($task);
                return true;
            }
        }
        unset($task);

        $this->log("WARNING: Task '{$name}' not found for rescheduling", 'warning');
        return false;
    }

    // ── FIX 14: Correct "time until next run" + not-found guard ──
    public function getTaskStatus(string $name): ?array
    {
        $now = time();

        foreach ($this->tasks as $task) {
            if ($task['name'] === $name) {
                return [
                    'name'            => $task['name'],
                    'is_running'      => $task['is_running'],
                    'last_run'        => $task['last_run'],
                    'next_run'        => $task['next_run'],
                    // FIX 14: calculate from NOW, not from last_run
                    'time_until_next' => max(0, $task['next_run'] - $now),
                    'run_count'       => $task['run_count'],
                    'error_count'     => $task['error_count'],
                ];
            }
        }

        return null;   // task not found
    }

    // ── Utility helpers ──────────────────────────────────────────
    public function getExecutedTasks(): array
    {
        return $this->executedTasks;
    }

    public function getAllTasks(): array
    {
        return $this->tasks;
    }
}
