### `LogEntry.java`

```java
package com.logingestion.model;

import com.fasterxml.jackson.annotation.JsonAlias;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.JsonNode;

import java.time.Instant;
import java.util.Collections;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;

/**
 * Immutable log entry representing a single ingested log record.
 * Supports flexible JSON field mapping with aliases.
 */
@JsonIgnoreProperties(ignoreUnknown = true)
public final class LogEntry {

    private final String id;

    @JsonProperty("timestamp")
    @JsonAlias({"@timestamp", "time", "ts", "datetime"})
    private final Instant timestamp;

    @JsonProperty("level")
    @JsonAlias({"severity", "log_level", "loglevel"})
    private final LogLevel level;

    @JsonProperty("message")
    @JsonAlias({"msg", "log", "text", "body"})
    private final String message;

    @JsonProperty("service")
    @JsonAlias({"service_name", "application", "app"})
    private final String service;

    @JsonProperty("host")
    @JsonAlias({"hostname", "server", "node"})
    private final String host;

    @JsonProperty("thread")
    @JsonAlias({"thread_name", "threadName"})
    private final String thread;

    @JsonProperty("logger")
    @JsonAlias({"logger_name", "loggerName", "class"})
    private final String logger;

    @JsonProperty("traceId")
    @JsonAlias({"trace_id", "x-trace-id"})
    private final String traceId;

    @JsonProperty("spanId")
    @JsonAlias({"span_id", "x-span-id"})
    private final String spanId;

    @JsonProperty("metadata")
    @JsonAlias({"extra", "fields", "tags", "labels"})
    private final Map<String, JsonNode> metadata;

    @JsonProperty("stackTrace")
    @JsonAlias({"stack_trace", "exception", "error_trace"})
    private final String stackTrace;

    // Jackson deserialization constructor
    public LogEntry(
            @JsonProperty("id") String id,
            @JsonProperty("timestamp") Instant timestamp,
            @JsonProperty("level") LogLevel level,
            @JsonProperty("message") String message,
            @JsonProperty("service") String service,
            @JsonProperty("host") String host,
            @JsonProperty("thread") String thread,
            @JsonProperty("logger") String logger,
            @JsonProperty("traceId") String traceId,
            @JsonProperty("spanId") String spanId,
            @JsonProperty("metadata") Map<String, JsonNode> metadata,
            @JsonProperty("stackTrace") String stackTrace) {
        this.id = (id != null) ? id : UUID.randomUUID().toString();
        this.timestamp = (timestamp != null) ? timestamp : Instant.now();
        this.level = (level != null) ? level : LogLevel.INFO;
        this.message = message;
        this.service = service;
        this.host = host;
        this.thread = thread;
        this.logger = logger;
        this.traceId = traceId;
        this.spanId = spanId;
        this.metadata = (metadata != null)
                ? Collections.unmodifiableMap(metadata)
                : Collections.emptyMap();
        this.stackTrace = stackTrace;
    }

    // --- Builder Pattern ---
    public static Builder builder() {
        return new Builder();
