# Background Worker with Cancellation in C++

## Core Design

The pattern uses `std::atomic<bool>` as a cancellation flag, checked periodically by the worker thread.

## Implementation

```cpp
#pragma once
// background_worker.h

#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <stdexcept>
#include <optional>
#include <string>
#include <iostream>

// ─── Cancellation Token ──────────────────────────────────────
// Shared between the worker and the caller to signal cancellation
class CancellationToken {
public:
    void cancel() noexcept {
        cancelled_.store(true, std::memory_order_release);
    }

    [[nodiscard]] bool is_cancelled() const noexcept {
        return cancelled_.load(std::memory_order_acquire);
    }

    // Call inside the work function to throw if cancelled
    void throw_if_cancelled() const {
        if (is_cancelled()) {
            throw std::runtime_error("Operation was cancelled");
        }
    }

private:
    std::atomic<bool> cancelled_{false};
};

// ─── Worker Status ───────────────────────────────────────────
enum class WorkerState {
    Idle,
    Running,
    Completed,
    Cancelled,
    Faulted
};

inline const char* to_string(WorkerState s) {
    switch (s) {
        case WorkerState::Idle:      return "Idle";
        case WorkerState::Running:   return "Running";
        case WorkerState::Completed: return "Completed";
        case WorkerState::Cancelled: return "Cancelled";
        case WorkerState::Faulted:   return "Faulted";
    }
    return "Unknown";
}

// ─── Background Worker ──────────────────────────────────────
//
//   WorkFn signature:   void(CancellationToken&, int& progress)
//     - Check the token periodically and stop early if cancelled
//     - Write to `progress` (0-100) to report progress
//
class BackgroundWorker {
public:
    // Callback types
    using WorkFn       = std::function<void(CancellationToken&, int& progress)>;
    using ProgressFn   = std::function<void(int percent)>;
    using CompleteFn   = std::function<void(WorkerState state, const std::string& error)>;

    BackgroundWorker() = default;

    ~BackgroundWorker() {
        cancel();       // signal stop
        wait();         // join thread
    }

    // Non-copyable, movable
    BackgroundWorker(const BackgroundWorker&) = delete;
    BackgroundWorker& operator=(const BackgroundWorker&) = delete;

    // ── Configuration (set before calling run()) ─────────
    void on_progress(ProgressFn fn) { progress_cb_ = std::move(fn); }
    void on_complete(CompleteFn fn) { complete_cb_ = std::move(fn); }

    // ── Control ──────────────────────────────────────────
    void run(WorkFn work) {
        if (state() == WorkerState::Running) {
            throw std::logic_error("Worker is already running");
        }

        // Reset state for reuse
        token_   = CancellationToken{};
        state_   = WorkerState::Running;
        error_.clear();

        thread_ = std::thread([this, work = std::move(work)]() mutable {
            int progress = 0;
            int last_reported = -1;

            try {
                // Launch the user's work, passing the token + progress ref
                work(token_, progress);

                // Work finished — was it cancelled during the final stretch?
                if (token_.is_cancelled()) {
                    finish(WorkerState::Cancelled);
                } else {
                    report_progress(100, last_reported);
                    finish(WorkerState::Completed);
                }
            } catch (const std::runtime_error& e) {
                // Cancellation throws std::runtime_error by convention
                if (token_.is_cancelled()) {
                    finish(WorkerState::Cancelled);
                } else {
                    error_ = e.what();
                    finish(WorkerState::Faulted);
                }
            } catch (const std::exception& e) {
                error_ = e.what();
                finish(WorkerState::Faulted);
            } catch (...) {
                error_ = "Unknown exception";
                finish(WorkerState::Faulted);
            }
        });

        // Spin up a lightweight progress‑polling thread
        if (progress_cb_) {
            progress_thread_ = std::thread([this, &progress = std::as_const(state_)]() {
                // We read `progress` from the atomic state and
                // the user‑written `progress` int via the main thread.
                // For simplicity, poll until not Running.
                poll_progress();
            });
        }
    }

    void cancel() noexcept {
        token_.cancel();
    }

    // Block until the worker finishes
    void wait() {
        if (thread_.joinable())          thread_.join();
        if (progress_thread_.joinable()) progress_thread_.join();
    }

    [[nodiscard]] WorkerState state() const noexcept {
        return state_.load(std::memory_order_acquire);
    }

    [[nodiscard]] bool is_running() const noexcept {
        return state() == WorkerState::Running;
    }

    [[nodiscard]] const std::string& error() const noexcept {
        return error_;
    }

    // Block until work completes or timeout expires
    // Returns true if finished, false on timeout
    bool wait_for(std::chrono::milliseconds timeout) {
        std::unique_lock lock(mtx_);
        return cv_.wait_for(lock, timeout, [this] {
            return state() != WorkerState::Running;
        });
    }

private:
    // ── Internal helpers ─────────────────────────────────
    void finish(WorkerState final_state) {
        state_.store(final_state, std::memory_order_release);

        // Wake anyone blocked in wait_for()
        {
            std::lock_guard lock(mtx_);
            cv_.notify_all();
        }

        if (complete_cb_) {
            complete_cb_(final_state, error_);
        }
    }

    // Simple polling loop for progress (runs on its own thread)
    void poll_progress() {
        while (state() == WorkerState::Running) {
            if (progress_cb_) {
                progress_cb_(progress_.load(std::memory_order_relaxed));
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    void report_progress(int value, int& last) {
        if (value != last) {
            progress_.store(value, std::memory_order_relaxed);
            last = value;
        }
    }

    // ── Members ──────────────────────────────────────────
    std::thread            thread_;
    std::thread            progress_thread_;
    CancellationToken      token_;
    std::atomic<WorkerState> state_{WorkerState::Idle};
    std::atomic<int>       progress_{0};
    std::string            error_;

    ProgressFn             progress_cb_;
    CompleteFn             complete_cb_;

    std::mutex             mtx_;
    std::condition_variable cv_;
};
```

## Usage Example

```cpp
// main.cpp
#include "background_worker.h"
#include <chrono>
#include <iostream>

// Simulates a long computation that respects cancellation
void heavy_computation(CancellationToken& token, int& progress) {
    const int total_steps = 50;

    for (int i = 0; i <= total_steps; ++i) {
        // ★ Check cancellation at each iteration
        token.throw_if_cancelled();

        // Simulate work
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        // Report progress
        progress = (i * 100) / total_steps;
    }
}

int main() {
    BackgroundWorker worker;

    // ── Attach callbacks ──────────────────────────────────
    worker.on_progress([](int pct) {
        std::cout << "\r  Progress: " << pct << "%" << std::flush;
    });

    worker.on_complete([](WorkerState state, const std::string& err) {
        std::cout << "\n  Finished: " << to_string(state);
        if (!err.empty()) std::cout << " (" << err << ")";
        std::cout << std::endl;
    });

    // ── Run and cancel after 2 seconds ────────────────────
    std::cout << "=== Run 1: cancel after 2 s ===" << std::endl;
    worker.run(heavy_computation);

    std::this_thread::sleep_for(std::chrono::seconds(2));
    worker.cancel();               // <— non-blocking signal
    worker.wait();                 // <— block until thread exits
    std::cout << "  State: " << to_string(worker.state()) << "\n\n";

    // ── Run again to completion (worker is reusable) ──────
    std::cout << "=== Run 2: run to completion ===" << std::endl;
    worker.run(heavy_computation);
    worker.wait();
    std::cout << "  State: " << to_string(worker.state()) << std::endl;

    return 0;
}
```

## Build & Run

```bash
g++ -std=c++17 -pthread -O2 -o worker main.cpp
./worker
```

**Expected output:**
```
=== Run 1: cancel after 2 s ===
  Progress: 38%
  Finished: Cancelled
  State: Cancelled

=== Run 2: run to completion ===
  Progress: 100%
  Finished: Completed
  State: Completed
