## How the Cancellation Flow Works

```
 Caller thread              Worker thread
 ─────────────              ─────────────
 worker.run(fn)  ────────►  loop:
      │                        token.throw_if_cancelled() ◄── checks atomic bool
      │                        ... do work ...
      │                        update progress
 worker.cancel() ─┐
      │            │
      │        sets atomic ──► throw_if_cancelled() sees true
      │            bool           │
      │                           └──► throws runtime_error
      │                                   │
      │                           catch ──┘
      │                           state ← Cancelled
      │                           on_complete callback fires
 worker.wait()   ◄───────── thread exits
```

## Key Design Points

| Concern | Solution |
|---|---|
| **Cancellation signal** | `std::atomic<bool>` in `CancellationToken` — lock-free, safe to read from any thread |
| **Cooperative cancellation** | Worker calls `throw_if_cancelled()` at safe points — no forced thread termination |
| **Progress reporting** | `std::atomic<int>` polled by a lightweight progress thread |
| **Error propagation** | Exceptions caught inside the thread, stored in `error_` string |
| **Reusability** | After `wait()`, call `run()` again — token and state are reset |
| **RAII cleanup** | Destructor calls `cancel()` + `wait()` so the thread never outlives the object |

> **Important:** Never forcibly kill a thread (`TerminateThread`, `pthread_cancel`). Always use cooperative cancellation — the worker checks a flag and exits cleanly, giving it a chance to release resources.

# C++ Config Parser with Cache Invalidation

This example implements a config parser supporting **INI-style** files with multiple cache invalidation strategies (TTL, file-change detection, version-based, and manual).

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <unordered_map>
#include <optional>
#include <chrono>
#include <filesystem>
#include <mutex>
#include <functional>
#include <variant>
#include <vector>
#include <algorithm>
#include <stdexcept>
#include <memory>
#include <atomic>

namespace fs = std::filesystem;
using Clock = std::chrono::steady_clock;
using TimePoint = Clock::time_point;
using SysClock = std::chrono::system_clock;

// ─────────────────────────────────────────────
// Forward declarations
// ─────────────────────────────────────────────
class ConfigCache;

// ─────────────────────────────────────────────
// Config value: typed access to parsed values
// ─────────────────────────────────────────────
using ConfigVariant = std::variant<std::string, int, double, bool>;

struct ConfigValue {
    std::string raw;          // original string from file
    ConfigVariant typed;      // parsed typed value
    std::string section;      // [section] it belongs to
    std::string key;
    size_t line_number = 0;

    // Convenience accessors with type checking
    template <typename T>
    T as() const {
        if (auto* val = std::get_if<T>(&typed)) {
            return *val;
        }
        throw std::bad_variant_access();
    }

    const std::string& as_string() const { return std::get<std::string>(typed); }
    int                as_int()    const { return std::get<int>(typed); }
    double             as_double() const { return std::get<double>(typed); }
    bool               as_bool()   const { return std::get<bool>(typed); }
};

// ─────────────────────────────────────────────
// Cache entry: wraps a value with metadata
// ─────────────────────────────────────────────
struct CacheEntry {
    ConfigValue   value;
    TimePoint     cached_at;        // when this entry was cached
    uint64_t      version = 0;      // incremented on each reload
    size_t        hit_count = 0;    // access counter for diagnostics

    bool is_expired(std::chrono::milliseconds ttl) const {
        if (ttl.count() <= 0) return false;   // 0 = never expires by TTL
        return (Clock::now() - cached_at) > ttl;
    }
};

// ─────────────────────────────────────────────
// Invalidation strategy interface
// ─────────────────────────────────────────────
class InvalidationStrategy {
public:
    virtual ~InvalidationStrategy() = default;

    // Returns true when the entire cache should be invalidated
    virtual bool should_invalidate(const ConfigCache& cache) const = 0;

    // Human-readable name for logging
    virtual std::string name() const = 0;
};

// ─────────────────────────────────────────────
// Strategy 1 — TTL-based invalidation
// ─────────────────────────────────────────────
class TtlStrategy : public InvalidationStrategy {
public:
    explicit TtlStrategy(std::chrono::milliseconds ttl) : ttl_(ttl) {}

    bool should_invalidate(const ConfigCache& cache) const override;
    std::string name() const override { return "TTL(" + std::to_string(ttl_.count()) + "ms)"; }

private:
    std::chrono::milliseconds ttl_;
};

// ─────────────────────────────────────────────
// Strategy 2 — File modification time
// ─────────────────────────────────────────────
class FileChangeStrategy : public InvalidationStrategy {
public:
    explicit FileChangeStrategy(fs::path path)
        : path_(std::move(path))
        , last_write_(get_write_time()) {}

    bool should_invalidate(const ConfigCache& cache) const override {
        (void)cache;
        auto current = get_write_time();
        if (current != last_write_) {
            last_write_ = current;
            return true;
        }
        return false;
    }

    std::string name() const override { return "FileChange(" + path_.string() + ")"; }

private:
    fs::file_time_type get_write_time() const {
        std::error_code ec;
        auto t = fs::last_write_time(path_, ec);
        return ec ? fs::file_time_type{} : t;
    }

    fs::path                       path_;
    mutable fs::file_time_type     last_write_;
};

// ─────────────────────────────────────────────
// Strategy 3 — Manual / version-based
// ─────────────────────────────────────────────
class ManualStrategy : public InvalidationStrategy {
public:
    void invalidate() { flag_.store(true, std::memory_order_release); }

    bool should_invalidate(const ConfigCache& /*cache*/) const override {
        return flag_.exchange(false, std::memory_order_acq_rel);
    }

    std::string name() const override { return "Manual"; }

private:
    mutable std::atomic<bool> flag_{false};
};

// ─────────────────────────────────────────────
// Strategy 4 — Composite (any-of / all-of)
// ─────────────────────────────────────────────
class CompositeStrategy : public InvalidationStrategy {
public:
    enum class Mode { AnyOf, AllOf };

    explicit CompositeStrategy(Mode mode = Mode::AnyOf) : mode_(mode) {}

    void add(std::shared_ptr<InvalidationStrategy> s) {
        children_.push_back(std::move(s));
    }

    bool should_invalidate(const ConfigCache& cache) const override {
        if (mode_ == Mode::AnyOf) {
            return std::any_of(children_.begin(), children_.end(),
                [&](auto& s) { return s->should_invalidate(cache); });
        }
        return std::all_of(children_.begin(), children_.end(),
            [&](auto& s) { return s->should_invalidate(cache); });
    }

    std::string name() const override {
        std::string n = (mode_ == Mode::AnyOf) ? "AnyOf(" : "AllOf(";
        for (size_t i = 0; i < children_.size(); ++i) {
            if (i) n += ", ";
            n += children_[i]->name();
        }
        return n + ")";
    }

private:
    Mode mode_;
    std::vector<std::shared_ptr<InvalidationStrategy>> children_;
};

// ─────────────────────────────────────────────
// Config cache
// ─────────────────────────────────────────────
class ConfigCache {
public:
    using Key = std::string;   // "section.key"

    void put(const Key& key, ConfigValue value, uint64_t version) {
        entries_[key] = CacheEntry{
            .value     = std::move(value),
            .cached_at = Clock::now(),
            .version   = version,
            .hit_count = 0
        };
    }

    std::optional<CacheEntry*> get(const Key& key) {
        auto it = entries_.find(key);
        if (it == entries_.end()) return std::nullopt;
        ++it->second.hit_count;
        return &it->second;
    }

    void clear() { entries_.clear(); }

    bool empty() const { return entries_.empty(); }

    size_t size() const { return entries_.size(); }

    TimePoint oldest_entry_time() const {
        auto oldest = TimePoint::max();
        for (auto& [k, e] : entries_) {
            if (e.cached_at < oldest) oldest = e.cached_at;
        }
        return oldest;
    }

    // Evict a single key
    bool evict(const Key& key) { return entries_.erase(key) > 0; }

    // Evict everything in a section
    size_t evict_section(const std::string& section) {
        size_t count = 0;
        for (auto it = entries_.begin(); it != entries_.end(); ) {
            if (it->second.value.section == section) {
                it = entries_.erase(it);
                ++count;
            } else {
                ++it;
            }
        }
        return count;
    }

    void dump(std::ostream& os) const {
        for (auto& [k, e] : entries_) {
            auto age_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                Clock::now() - e.cached_at).count();
            os << "  [" << k << "] = \"" << e.value.raw
               << "\"  (v" << e.version
               << ", age=" << age_ms << "ms"
               << ", hits=" << e.hit_count << ")\n";
        }
    }

private:
    std::unordered_map<Key, CacheEntry> entries_;
};

// ── TtlStrategy needs cache access ──────────
inline bool TtlStrategy::should_invalidate(const ConfigCache& cache) const {
    if (cache.empty()) return false;
    auto age = Clock::now() - cache.oldest_entry_time();
    return age > ttl_;
}

