// INI parser: handles the actual file parsing
// ─────────────────────────────────────────────
class IniParser {
public:
    struct ParseError {
        size_t      line;
        std::string message;
    };

    struct ParseResult {
        // section -> (key -> ConfigValue)
        std::unordered_map<std::string,
            std::unordered_map<std::string, ConfigValue>> sections;
        std::vector<ParseError> errors;
        bool ok() const { return errors.empty(); }
    };

    static ParseResult parse(std::istream& stream) {
        ParseResult result;
        std::string current_section = "global";
        std::string line;
        size_t line_num = 0;

        while (std::getline(stream, line)) {
            ++line_num;
            line = trim(line);

            // Skip empty lines and comments
            if (line.empty() || line[0] == '#' || line[0] == ';') continue;

            // Section header: [section]
            if (line.front() == '[' && line.back() == ']') {
                current_section = trim(line.substr(1, line.size() - 2));
                if (current_section.empty()) {
                    result.errors.push_back({line_num, "Empty section name"});
                }
                continue;
            }

            // Key = Value
            auto eq = line.find('=');
            if (eq == std::string::npos) {
                result.errors.push_back({line_num, "Missing '=' in: " + line});
                continue;
            }

            std::string key = trim(line.substr(0, eq));
            std::string val = trim(line.substr(eq + 1));

            // Strip surrounding quotes
            if (val.size() >= 2 &&
                ((val.front() == '"'  && val.back() == '"') ||
                 (val.front() == '\'' && val.back() == '\''))) {
                val = val.substr(1, val.size() - 2);
            }

            ConfigValue cv;
            cv.raw          = val;
            cv.typed        = infer_type(val);
            cv.section      = current_section;
            cv.key          = key;
            cv.line_number  = line_num;

            result.sections[current_section][key] = std::move(cv);
        }

        return result;
    }

    static ParseResult parse_file(const fs::path& path) {
        std::ifstream file(path);
        if (!file.is_open()) {
            return ParseResult{{}, {{0, "Cannot open file: " + path.string()}}};
        }
        return parse(file);
    }

private:
    static std::string trim(const std::string& s) {
        auto start = s.find_first_not_of(" \t\r\n");
        if (start == std::string::npos) return {};
        auto end = s.find_last_not_of(" \t\r\n");
        return s.substr(start, end - start + 1);
    }

    static ConfigVariant infer_type(const std::string& val) {
        // Boolean
        std::string lower = val;
        std::transform(lower.begin(), lower.end(), lower.begin(), ::tolower);
        if (lower == "true" || lower == "yes" || lower == "on")  return true;
        if (lower == "false" || lower == "no" || lower == "off") return false;

        // Integer
        try {
            size_t pos;
            int i = std::stoi(val, &pos);
            if (pos == val.size()) return i;
        } catch (...) {}

        // Double
        try {
            size_t pos;
            double d = std::stod(val, &pos);
            if (pos == val.size()) return d;
        } catch (...) {}

        // Fallback: string
        return val;
    }
};

// ─────────────────────────────────────────────
// ConfigParser: ties parsing + caching together
// ─────────────────────────────────────────────
class ConfigParser {
public:
    using ChangeCallback = std::function<void(const std::string& key,
                                              const std::string& old_val,
                                              const std::string& new_val)>;

    struct Options {
        std::chrono::milliseconds   ttl          = std::chrono::seconds(30);
        bool                        watch_file   = true;
        bool                        auto_reload  = true;   // reload on invalidation
        bool                        log_activity = false;
    };

    // ── Construction ────────────────────────
    explicit ConfigParser(fs::path path, Options opts = {})
        : path_(std::move(path))
        , options_(opts)
        , version_(0)
    {
        build_strategies();
        load();   // initial parse
    }

    // ── Primary API ─────────────────────────

    // Get a value by "section.key" (e.g. "database.host") or just "key" for [global]
    std::optional<ConfigValue> get(const std::string& qualified_key) {
        std::lock_guard lock(mutex_);
        maybe_invalidate();

        // Check cache first
        if (auto entry = cache_.get(qualified_key)) {
            if (options_.log_activity)
                std::cout << "[cache hit] " << qualified_key << "\n";
            return (*entry)->value;
        }

        // Cache miss — look in parsed data
        auto [section, key] = split_key(qualified_key);
        auto sit = parsed_.sections.find(section);
        if (sit == parsed_.sections.end()) return std::nullopt;

        auto kit = sit->second.find(key);
        if (kit == sit->second.end()) return std::nullopt;

        // Populate cache
        cache_.put(qualified_key, kit->second, version_);
        if (options_.log_activity)
            std::cout << "[cache miss → stored] " << qualified_key << "\n";

        return kit->second;
    }

    // Typed convenience wrappers
    std::string get_string(const std::string& key, const std::string& def = {}) {
        auto v = get(key);
        return v ? v->raw : def;
    }

    int get_int(const std::string& key, int def = 0) {
        auto v = get(key);
        if (!v) return def;
        try { return v->as_int(); } catch (...) { return def; }
    }

    double get_double(const std::string& key, double def = 0.0) {
        auto v = get(key);
        if (!v) return def;
        try { return v->as_double(); } catch (...) { return def; }
    }

    bool get_bool(const std::string& key, bool def = false) {
        auto v = get(key);
        if (!v) return def;
        try { return v->as_bool(); } catch (...) { return def; }
    }

    // ── Cache control ───────────────────────

    void invalidate() {
        std::lock_guard lock(mutex_);
        if (options_.log_activity)
            std::cout << "[invalidate] full cache cleared (v" << version_ << ")\n";
        cache_.clear();
        if (options_.auto_reload) load_locked();
    }

    void invalidate_key(const std::string& key) {
        std::lock_guard lock(mutex_);
        cache_.evict(key);
    }

    void invalidate_section(const std::string& section) {
        std::lock_guard lock(mutex_);
        auto n = cache_.evict_section(section);
        if (options_.log_activity)
            std::cout << "[invalidate section] " << section << " (" << n << " evicted)\n";
    }

    // Force a full reload from disk
    void reload() {
        std::lock_guard lock(mutex_);
        cache_.clear();
        load_locked();
    }

    // ── Observability ───────────────────────

    void on_change(ChangeCallback cb) {
        std::lock_guard lock(mutex_);
        change_callbacks_.push_back(std::move(cb));
    }

    void dump_cache(std::ostream& os = std::cout) const {
        std::lock_guard lock(mutex_);
        os << "ConfigParser cache (v" << version_
           << ", " << cache_.size() << " entries):\n";
        cache_.dump(os);
    }

    uint64_t version() const { return version_; }

    // Access the manual strategy to trigger invalidation externally
    std::shared_ptr<ManualStrategy> manual_strategy() const {
        return manual_;
    }

private:
    // ── Internal helpers ────────────────────

    void build_strategies() {
        auto composite = std::make_shared<CompositeStrategy>(CompositeStrategy::Mode::AnyOf);

        if (options_.ttl.count() > 0) {
            composite->add(std::make_shared<TtlStrategy>(options_.ttl));
        }

