    std::string function_name;
    std::vector<std::string> arguments;
    bool has_timestamp;
    bool has_user_context;
    bool has_action;
    bool has_resource_id;
};

struct FunctionInfo {
    std::string name;
    int start_line;
    int end_line;
    bool modifies_sensitive_data;
    std::vector<AuditLogCall> audit_calls;
};

// ─── Configuration ──────────────────────────────────────────────────

struct AuditLintConfig {
    std::vector<std::string> sensitive_functions;
    std::vector<std::string> audit_log_functions;
    std::vector<std::regex> sensitive_data_patterns;
    std::vector<std::string> required_audit_fields;
    bool require_pre_action_log;
    bool require_post_action_log;
    int max_log_message_length;
};

// ═══════════════════════════════════════════════════════════════════
//  BUGGY LINTER IMPLEMENTATION (with bug markers)
// ═══════════════════════════════════════════════════════════════════

class AuditLogLinter {
public:
    AuditLogLinter(const AuditLintConfig& config)    // BUG 1: missing explicit
        : config_(config) {}

    std::vector<LintViolation> lint_file(const std::string& filepath) {
        violations_.clear();  // BUG 2: stale state from previous run not fully reset
        // BUG 2 (cont): current_file_ never set → violations report empty filename

        std::ifstream file(filepath);
        if (!file.is_open()) {
            return violations_;  // BUG 3: silent failure, no error reported
        }

        std::string source;
        std::string line;
        while (std::getline(file, line)) {
            source += line + "\n";
        }

        auto functions = parse_functions(source);
        for (auto& func : functions) {                // BUG 4: should be const auto&
            check_audit_coverage(func);
            check_audit_completeness(func);
            check_sensitive_data_leaks(func, source);
            check_log_ordering(func);
        }

        return violations_;
    }

private:
    AuditLintConfig config_;
    std::vector<LintViolation> violations_;
    std::string current_file_;
    std::unordered_map<std::string, std::vector<FunctionInfo>> file_cache_;

    // ── Function parser (simplified AST-like extraction) ─────────

    std::vector<FunctionInfo> parse_functions(const std::string& source) {
        std::vector<FunctionInfo> functions;
        std::regex func_regex(
            R"((\w+)\s+(\w+)\s*\([^)]*\)\s*\{)"
        );

        std::sregex_iterator it(source.begin(), source.end(), func_regex);
        std::sregex_iterator end;

        while (it != end) {
            FunctionInfo info;
            info.name = (*it)[2].str();
            info.start_line = count_lines(source, it->position());

            // BUG 5: brace matching doesn't handle braces inside strings/comments
            int brace_count = 1;
            size_t pos = it->position() + it->length();
            while (brace_count > 0 && pos < source.length()) { // BUG 6: off-by-one → should be source.size()
                if (source[pos] == '{') brace_count++;
                if (source[pos] == '}') brace_count--;          // BUG 7: else-if needed
                pos++;
            }
            info.end_line = count_lines(source, pos);

            // Check if function modifies sensitive data
            info.modifies_sensitive_data = is_sensitive_function(info.name);

            // Extract audit log calls within this function
            std::string func_body = source.substr(
                it->position(),
                pos - it->position()
            );
            info.audit_calls = extract_audit_calls(func_body, info.start_line);

            functions.push_back(info);
            ++it;
        }

        return functions;
    }

    int count_lines(const std::string& source, size_t position) {
        int lines = 1;
        for (size_t i = 0; i <= position; i++) {    // BUG 8: <= causes read past valid range
            if (source[i] == '\n') lines++;          //   when position == source.size()
        }
        return lines;
    }

    bool is_sensitive_function(const std::string& name) {
        for (const auto& pattern : config_.sensitive_functions) {
            if (name.find(pattern) != std::string::npos) {
                return true;
            }
            // BUG 9: falls through without returning false per-iteration
        }
        return false;  // Only correct return is here — logic itself is fine,
                        // but see BUG 10 below for case sensitivity
    }

    // ── Audit call extraction ────────────────────────────────────

    std::vector<AuditLogCall> extract_audit_calls(
        const std::string& func_body, int base_line
    ) {
        std::vector<AuditLogCall> calls;

        for (const auto& log_func : config_.audit_log_functions) {
            size_t search_pos = 0;
            while (true) {
                size_t pos = func_body.find(log_func, search_pos);
                if (pos == std::string::npos) break;

                AuditLogCall call;
                call.function_name = log_func;
                call.line = base_line + count_lines(func_body.substr(0, pos), 0);
                // BUG 11: ^^^ count_lines on pos=0 always returns 1
                //         should be count_lines(func_body, pos) - 1

                // Extract arguments
                size_t paren_start = func_body.find('(', pos);
                size_t paren_end = func_body.find(')', paren_start);
                // BUG 12: doesn't handle nested parentheses
                // BUG 13: no check if paren_start == npos before using it

                if (paren_end != std::string::npos) {
                    std::string args_str = func_body.substr(
                        paren_start + 1,
                        paren_end - paren_start - 1
                    );
                    call.arguments = split_arguments(args_str);
                    classify_audit_fields(call);
                }

                calls.push_back(call);
                search_pos = pos + 1;   // BUG 14: should advance past the call
                                        //         to avoid overlapping matches
            }
        }

        return calls;
    }

    std::vector<std::string> split_arguments(const std::string& args) {
        std::vector<std::string> result;
        std::stringstream ss(args);
        std::string arg;
        int depth = 0;
        std::string current;

        for (char c : args) {
            if (c == '(' || c == '<') depth++;
            if (c == ')' || c == '>') depth--;
            if (c == ',' && depth == 0) {
                result.push_back(current);
                current.clear();              // BUG 15: doesn't trim whitespace
            } else {
                current += c;
            }
        }
        // BUG 16: last argument never pushed
        return result;
    }

    void classify_audit_fields(AuditLogCall& call) {
        for (const auto& arg : call.arguments) {
            // BUG 10/17: case-sensitive matching misses "Timestamp", "TIME_STAMP" etc.
            if (arg.find("timestamp") != std::string::npos ||
                arg.find("time") != std::string::npos) {
                call.has_timestamp = true;
            }
            if (arg.find("user") != std::string::npos ||
                arg.find("principal") != std::string::npos) {
                call.has_user_context = true;
            }
            if (arg.find("action") != std::string::npos ||
                arg.find("operation") != std::string::npos) {
                call.has_action = true;
            }
            if (arg.find("resource") != std::string::npos ||
                arg.find("entity") != std::string::npos) {
                call.has_resource_id = true;
            }
        }
    }

    // ── Rule checks ─────────────────────────────────────────────

    void check_audit_coverage(const FunctionInfo& func) {
        if (!func.modifies_sensitive_data) return;

        if (func.audit_calls.empty()) {
            LintViolation v;
            v.file = current_file_;
            v.line = func.start_line;
            v.column = 0;
            v.rule_id = "AUDIT_001";
            v.message = "Function '" + func.name +
                        "' modifies sensitive data but has no audit logging";
            v.severity = Severity::ERROR;
            violations_.push_back(v);
        }
    }

    void check_audit_completeness(const FunctionInfo& func) {
        for (const auto& call : func.audit_calls) {
            // BUG 18: fields initialized to garbage — struct members
            //         has_timestamp etc. never initialized to false
            if (!call.has_timestamp) {
                add_violation(call.line, "AUDIT_002",
                    "Audit log call missing timestamp field",
                    Severity::ERROR);
            }
            if (!call.has_user_context) {
                add_violation(call.line, "AUDIT_003",
                    "Audit log call missing user context",
                    Severity::ERROR);
            }
            if (!call.has_action) {
                add_violation(call.line, "AUDIT_004",
                    "Audit log call missing action descriptor",
                    Severity::WARNING);
            }
            if (!call.has_resource_id) {
                add_violation(call.line, "AUDIT_005",
                    "Audit log call missing resource identifier",
                    Severity::WARNING);
            }
        }
    }

    void check_sensitive_data_leaks(
        const FunctionInfo& func, const std::string& source
    ) {
        for (const auto& call : func.audit_calls) {
            for (const auto& arg : call.arguments) {
                for (const auto& pattern : config_.sensitive_data_patterns) {
                    // BUG 19: regex_search can throw; not wrapped in try-catch
                    if (std::regex_search(arg, pattern)) {
                        add_violation(call.line, "AUDIT_006",
                            "Potential sensitive data leak in audit log: " + arg,
                            Severity::ERROR);
                        break;  // BUG 20: only breaks inner loop, keeps
                                //         checking other patterns pointlessly
                    }
                }
            }
        }
    }

    void check_log_ordering(const FunctionInfo& func) {
        if (!func.modifies_sensitive_data) return;
        if (func.audit_calls.size() < 2 &&             // BUG 21: should check
            (config_.require_pre_action_log &&          //   both flags, not &&
             config_.require_post_action_log)) {
            add_violation(func.start_line, "AUDIT_007",
                "Function '" + func.name +
                "' requires both pre- and post-action audit logs",
                Severity::WARNING);
        }
    }

    void add_violation(int line, const std::string& rule_id,
                       const std::string& message, Severity severity) {
        violations_.push_back({current_file_, line, 0, rule_id,
                               message, severity});
    }
};
