 * throttle_seconds = 300
 * enabled = true
 *
 * [rule:deploy_notify]
 * event_type = DEPLOYMENT
 * min_severity = LOW
 * action = webhook
 * target = https://hooks.slack.com/services/xxx
 * throttle_seconds = 0
 * enabled = false
 * ```
 */
data class AppConfig(
    val settings: GlobalSettings,
    val rules: List<EventRule>
)

data class GlobalSettings(
    val appName: String = "EventProcessor",
    val maxRetries: Int = 3,
    val logLevel: String = "INFO"
)

/** Defines how a specific event type/severity combo should be handled */
data class EventRule(
    val name: String,
    val eventType: String,
    val minSeverity: Severity,
    val action: ActionType,
    val target: String,
    val throttleSeconds: Long = 0,
    val enabled: Boolean = true
)

enum class ActionType { LOG, ALERT, WEBHOOK, DROP }
