## Config Parser

```kotlin
// parser/ConfigParser.kt
package parser

import model.*
import java.io.File
import java.io.Reader

/**
 * Parses an INI-style config file into an [AppConfig].
 *
 * Supports:
 *  - [settings] section for global options
 *  - [rule:<name>] sections for event rules
 *  - # line comments
 *  - blank line skipping
 *  - type coercion for Int, Long, Boolean, enums
 */
class ConfigParser {

    // ── Public API ──────────────────────────────────────────────────

    fun parseFile(path: String): AppConfig =
        File(path).bufferedReader().use { parse(it) }

    fun parseString(content: String): AppConfig =
        content.reader().use { parse(it) }

    fun parse(reader: Reader): AppConfig {
        val sections = splitIntoSections(reader.readLines())
        val settings = parseSettings(sections["settings"])
        val rules = sections
            .filterKeys { it.startsWith("rule:") }
            .map { (header, pairs) ->
                val ruleName = header.removePrefix("rule:")
                parseRule(ruleName, pairs)
            }
        return AppConfig(settings, rules)
    }

    // ── Section splitting ───────────────────────────────────────────

    /**
     * Groups lines into named sections.
     * Returns map of "sectionName" → list of "key = value" strings.
     */
    private fun splitIntoSections(
        lines: List<String>
    ): Map<String, List<String>> {
        val sections = mutableMapOf<String, MutableList<String>>()
        var current: String? = null

        for ((lineNum, rawLine) in lines.withIndex()) {
            val line = rawLine.trim()

            // Skip blanks and comments
            if (line.isEmpty() || line.startsWith("#")) continue

            // Section header: [name]
            if (line.startsWith("[") && line.endsWith("]")) {
                current = line
                    .removeSurrounding("[", "]")
                    .trim()
                    .lowercase()
                sections.putIfAbsent(current, mutableListOf())
                continue
            }

            // Key-value pair
            if (current == null) {
                throw ConfigParseException(
                    lineNum + 1,
                    "Key-value pair found outside any section: $line"
                )
            }

            if (!line.contains('=')) {
                throw ConfigParseException(
                    lineNum + 1,
                    "Expected 'key = value', got: $line"
                )
            }

            sections[current]!!.add(line)
        }

        return sections
    }

    // ── Settings parsing ────────────────────────────────────────────

    private fun parseSettings(lines: List<String>?): GlobalSettings {
        if (lines == null) return GlobalSettings()

        val map = toMap(lines)
        return GlobalSettings(
            appName = map["app_name"] ?: "EventProcessor",
            maxRetries = map["max_retries"]?.toIntOrNull() ?: 3,
            logLevel = (map["log_level"] ?: "INFO").uppercase()
        )
    }

    // ── Rule parsing ────────────────────────────────────────────────

    private fun parseRule(name: String, lines: List<String>): EventRule {
        val map = toMap(lines)

        val eventType = map.require("event_type", name)
        val minSeverity = map.requireEnum<Severity>("min_severity", name)
        val action = map.requireEnum<ActionType>("action", name)
        val target = map.require("target", name)

        return EventRule(
            name = name,
            eventType = eventType.uppercase(),
            minSeverity = minSeverity,
            action = action,
            target = target,
            throttleSeconds = map["throttle_seconds"]?.toLongOrNull() ?: 0,
            enabled = map["enabled"]?.toBooleanStrictOrNull() ?: true
        )
    }

    // ── Helpers ─────────────────────────────────────────────────────

    /** Converts "key = value" lines into a map (lowercase keys). */
    private fun toMap(lines: List<String>): Map<String, String> =
        lines.associate { line ->
            val (k, v) = line.split('=', limit = 2)
            k.trim().lowercase() to v.trim()
        }

    /** Extracts a required string value or throws. */
    private fun Map<String, String>.require(
        key: String,
        ruleName: String
    ): String =
        this[key]
            ?: throw ConfigParseException(
                message = "Missing required key '$key' in rule '$ruleName'"
            )

    /** Extracts a required enum value or throws with valid options. */
    private inline fun <reified E : Enum<E>> Map<String, String>.requireEnum(
        key: String,
        ruleName: String
    ): E {
        val raw = require(key, ruleName).uppercase()
        return try {
            enumValueOf<E>(raw)
        } catch (_: IllegalArgumentException) {
            val valid = enumValues<E>().joinToString()
            throw ConfigParseException(
                message = "Invalid value '$raw' for '$key' in rule " +
                        "'$ruleName'. Valid: $valid"
            )
        }
    }
}

/** Thrown when config content is malformed. */
class ConfigParseException(
    line: Int? = null,
    message: String
) : RuntimeException(
    if (line != null) "Line $line: $message" else message
)
