    override fun handle(event: Event, rule: EventRule) {
        val msg = "[${Instant.now()}] ${rule.name} | " +
                "${event.type} from ${event.source} " +
                "(${event.severity}): ${event.payload}"
        println("  📝 LOG → ${rule.target}: $msg")

        // In production: append to the file at rule.target
        // File(rule.target).appendText(msg + "\n")
    }
}

class AlertHandler : EventHandler {
    override fun handle(event: Event, rule: EventRule) {
        println(
            "  🚨 ALERT → ${rule.target}: " +
                    "[${event.severity}] ${event.type} from ${event.source}"
        )
        // In production: send email / PagerDuty / SMS to rule.target
    }
}

class WebhookHandler : EventHandler {
    override fun handle(event: Event, rule: EventRule) {
        val body = """
            {
              "rule": "${rule.name}",
              "event_type": "${event.type}",
              "source": "${event.source}",
              "severity": "${event.severity}",
              "payload": ${event.payload}
            }
        """.trimIndent()

        println("  🌐 WEBHOOK → POST ${rule.target}")
        println("     Body: ${body.take(120)}...")

        // In production: actually POST
        // postJson(rule.target, body)
    }

    @Suppress("unused")
    private fun postJson(url: String, json: String) {
        val conn = URI(url).toURL()
            .openConnection() as HttpURLConnection
        conn.requestMethod = "POST"
        conn.setRequestProperty("Content-Type", "application/json")
        conn.doOutput = true
        conn.outputStream.bufferedWriter().use { it.write(json) }
        println("     Response: ${conn.responseCode}")
        conn.disconnect()
    }
}

class DropHandler : EventHandler {
    override fun handle(event: Event, rule: EventRule) {
        println("  🗑️ DROP: ${event.type} from ${event.source}")
    }
}
