## Event Processor

```kotlin
// processor/EventProcessor.kt
package processor

import model.*
import processor.handlers.*
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap

/**
 * Core engine: matches incoming events against config rules
 * and dispatches to the appropriate handler.
 *
 * Features:
 *  - Rule matching by event type + minimum severity
 *  - Per-rule throttling
 *  - Retry with configurable max attempts
 *  - Listener hooks for monitoring
 */
class EventProcessor(private val config: AppConfig) {

    // ── Handler registry (one per action type) ──────────────────────

    private val handlers: Map<ActionType, EventHandler> = mapOf(
        ActionType.LOG to LogHandler(),
        ActionType.ALERT to AlertHandler(),
        ActionType.WEBHOOK to WebhookHandler(),
        ActionType.DROP to DropHandler()
    )

    // ── Throttle tracking: ruleName → last fire Instant ─────────────

    private val lastFired = ConcurrentHashMap<String, Instant>()

    // ── Listener for external monitoring ────────────────────────────

    fun interface ProcessingListener {
        fun onResult(event: Event, rule: EventRule?, success: Boolean)
    }

    private var listener: ProcessingListener? = null
    fun setListener(l: ProcessingListener) { listener = l }

    // ── Stats ───────────────────────────────────────────────────────

    data class Stats(
        var processed: Int = 0,
        var matched: Int = 0,
        var throttled: Int = 0,
        var errors: Int = 0
    )

    val stats = Stats()

    // ── Main entry point ────────────────────────────────────────────

    fun process(event: Event) {
        stats.processed++
        println("\n⚡ Processing: ${event.type} from ${event.source} [${event.severity}]")

        // Find all enabled rules whose type + severity match
        val matching = config.rules.filter { rule ->
            rule.enabled
                    && rule.eventType == event.type
                    && event.severity.ordinal >= rule.minSeverity.ordinal
        }

        if (matching.isEmpty()) {
            println("  ⏭️ No matching rules — skipping")
            listener?.onResult(event, null, true)
            return
        }

        // Dispatch to each matching rule
        for (rule in matching) {
            if (isThrottled(rule)) {
                stats.throttled++
                println("  ⏳ Throttled: rule '${rule.name}'")
                continue
            }

            dispatch(event, rule)
        }
    }

    /** Process a batch of events in order. */
    fun processAll(events: List<Event>) {
        events.forEach(::process)
    }

    // ── Internals ───────────────────────────────────────────────────

    private fun dispatch(event: Event, rule: EventRule) {
        val handler = handlers[rule.action]
            ?: error("No handler registered for action ${rule.action}")

        var attempt = 0
        val maxRetries = config.settings.maxRetries

        while (attempt <= maxRetries) {
            try {
                handler.handle(event, rule)
                stats.matched++
                lastFired[rule.name] = Instant.now()
                listener?.onResult(event, rule, true)
                return                          // success → done
            } catch (ex: Exception) {
                attempt++
                if (attempt > maxRetries) {
                    stats.errors++
                    println("  ❌ Failed after $maxRetries retries: ${ex.message}")
                    listener?.onResult(event, rule, false)
                } else {
                    println("  🔄 Retry $attempt/$maxRetries...")
                }
            }
        }
    }

    private fun isThrottled(rule: EventRule): Boolean {
        if (rule.throttleSeconds <= 0) return false
        val last = lastFired[rule.name] ?: return false
        return Instant.now().epochSecond - last.epochSecond < rule.throttleSeconds
    }
}
