'use strict';

const LOG_LEVELS = Object.freeze({
  ERROR: 0,
  WARN: 1,
  INFO: 2,
  DEBUG: 3,
});

class Logger {
  #level;
  #context;
  #output;

  /**
   * @param {object} options
   * @param {'ERROR'|'WARN'|'INFO'|'DEBUG'} [options.level='INFO']
   * @param {string} [options.context='Pipeline']
   * @param {Function} [options.output] - Custom output fn(level, message, meta)
   */
  constructor({ level = 'INFO', context = 'Pipeline', output } = {}) {
    this.#level = LOG_LEVELS[level] ?? LOG_LEVELS.INFO;
    this.#context = context;
    this.#output = output || null;
  }

  #log(level, message, meta = {}) {
    if (LOG_LEVELS[level] > this.#level) return;

    const entry = {
      timestamp: new Date().toISOString(),
      level,
      context: this.#context,
      message,
      ...meta,
    };

    if (this.#output) {
      this.#output(level, message, entry);
      return;
    }

    const fn = level === 'ERROR' ? console.error
      : level === 'WARN' ? console.warn
      : console.log;

    fn(JSON.stringify(entry));
  }

  error(message, meta) { this.#log('ERROR', message, meta); }
  warn(message, meta)  { this.#log('WARN', message, meta); }
  info(message, meta)  { this.#log('INFO', message, meta); }
  debug(message, meta) { this.#log('DEBUG', message, meta); }

  child(context) {
    return new Logger({
      level: Object.keys(LOG_LEVELS).find(k => LOG_LEVELS[k] === this.#level),
      context: `${this.#context}:${context}`,
      output: this.#output,
    });
  }
}

module.exports = { Logger, LOG_LEVELS };
