### src/utils/CircuitBreaker.js

```js
'use strict';

const STATES = Object.freeze({
  CLOSED: 'CLOSED',
  OPEN: 'OPEN',
  HALF_OPEN: 'HALF_OPEN',
});

class CircuitBreaker {
  #state;
  #failureCount;
  #successCount;
  #lastFailureTime;
  #options;

  /**
   * @param {object} options
   * @param {number} [options.failureThreshold=5]
   * @param {number} [options.resetTimeoutMs=30000]
   * @param {number} [options.halfOpenMaxAttempts=3]
   * @param {Function} [options.onStateChange]
   */
  constructor(options = {}) {
    this.#options = {
      failureThreshold: options.failureThreshold ?? 5,
      resetTimeoutMs: options.resetTimeoutMs ?? 30_000,
      halfOpenMaxAttempts: options.halfOpenMaxAttempts ?? 3,
      onStateChange: options.onStateChange ?? null,
    };
    this.#state = STATES.CLOSED;
    this.#failureCount = 0;
    this.#successCount = 0;
    this.#lastFailureTime = null;
  }

  get state() { return this.#state; }
  get failureCount() { return this.#failureCount; }

  #setState(newState) {
    const prev = this.#state;
    if (prev === newState) return;
    this.#state = newState;
    this.#options.onStateChange?.(prev, newState);
  }

  /**
   * Executes `fn` if the circuit allows it.
   * @param {Function} fn - Async function to execute
   * @returns {Promise<*>}
   */
  async execute(fn) {
    if (this.#state === STATES.OPEN) {
      if (Date.now() - this.#lastFailureTime >= this.#options.resetTimeoutMs) {
        this.#setState(STATES.HALF_OPEN);
        this.#successCount = 0;
      } else {
        throw new CircuitBreakerOpenError(
          `Circuit is OPEN. Retry after ${this.#options.resetTimeoutMs}ms`
        );
      }
    }

    try {
      const result = await fn();
      this.#onSuccess();
      return result;
    } catch (err) {
      this.#onFailure();
      throw err;
    }
  }

  #onSuccess() {
    if (this.#state === STATES.HALF_OPEN) {
      this.#successCount++;
      if (this.#successCount >= this.#options.halfOpenMaxAttempts) {
        this.#failureCount = 0;
        this.#setState(STATES.CLOSED);
      }
    } else {
      this.#failureCount = 0;
    }
  }

  #onFailure() {
    this.#failureCount++;
    this.#lastFailureTime = Date.now();

    if (this.#state === STATES.HALF_OPEN) {
      this.#setState(STATES.OPEN);
    } else if (this.#failureCount >= this.#options.failureThreshold) {
      this.#setState(STATES.OPEN);
    }
  }

  reset() {
    this.#failureCount = 0;
    this.#successCount = 0;
    this.#lastFailureTime = null;
    this.#setState(STATES.CLOSED);
  }
}

class CircuitBreakerOpenError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CircuitBreakerOpenError';
  }
}

module.exports = { CircuitBreaker, CircuitBreakerOpenError, STATES };
