'use strict';

/**
 * Token-bucket rate limiter.
 */
class RateLimiter {
  #tokens;
  #maxTokens;
  #refillRate; // tokens per ms
  #lastRefill;

  /**
   * @param {object} options
   * @param {number} options.maxPerSecond - Maximum events per second
   * @param {number} [options.burstSize] - Burst capacity (defaults to maxPerSecond)
   */
  constructor({ maxPerSecond, burstSize }) {
    if (!maxPerSecond || maxPerSecond <= 0) {
      throw new RangeError('maxPerSecond must be a positive number');
    }
    this.#maxTokens = burstSize ?? maxPerSecond;
    this.#tokens = this.#maxTokens;
    this.#refillRate = maxPerSecond / 1000;
    this.#lastRefill = Date.now();
  }

  get availableTokens() {
    this.#refill();
    return Math.floor(this.#tokens);
  }

  #refill() {
    const now = Date.now();
    const elapsed = now - this.#lastRefill;
    this.#tokens = Math.min(this.#maxTokens, this.#tokens + elapsed * this.#refillRate);
    this.#lastRefill = now;
  }

  /**
   * Attempt to consume one token.
   * @param {number} [count=1]
   * @returns {boolean}
   */
  tryConsume(count = 1) {
    this.#refill();
    if (this.#tokens >= count) {
      this.#tokens -= count;
      return true;
    }
    return false;
  }

  /**
   * Wait until a token is available then consume.
   * @param {number} [count=1]
   * @param {number} [timeoutMs=5000]
   * @returns {Promise<boolean>}
   */
  async waitForToken(count = 1, timeoutMs = 5000) {
    const deadline = Date.now() + timeoutMs;

    while (Date.now() < deadline) {
      if (this.tryConsume(count)) return true;
      const waitMs = Math.min(
        Math.ceil(count / this.#refillRate),
        deadline - Date.now()
      );
      if (waitMs <= 0) break;
      await new Promise(resolve => setTimeout(resolve, waitMs));
    }

    return false;
  }
}

module.exports = { RateLimiter };
