const { EventEmitter } = require('events');

/**
 * Manages backpressure by monitoring queue depth and pausing/resuming ingestion.
 */
class BackpressureManager extends EventEmitter {
  #highWaterMark;
  #lowWaterMark;
  #currentDepth;
  #isPaused;

  /**
   * @param {object} options
   * @param {number} [options.highWaterMark=10000]
   * @param {number} [options.lowWaterMark=2000]
   */
  constructor({ highWaterMark = 10_000, lowWaterMark = 2_000 } = {}) {
    super();
    if (lowWaterMark >= highWaterMark) {
      throw new RangeError('lowWaterMark must be less than highWaterMark');
    }
    this.#highWaterMark = highWaterMark;
    this.#lowWaterMark = lowWaterMark;
    this.#currentDepth = 0;
    this.#isPaused = false;
  }

  get isPaused() { return this.#isPaused; }
  get currentDepth() { return this.#currentDepth; }

  increment(count = 1) {
    this.#currentDepth += count;
    if (!this.#isPaused && this.#currentDepth >= this.#highWaterMark) {
      this.#isPaused = true;
      this.emit('pause', this.#currentDepth);
    }
  }

  decrement(count = 1) {
    this.#currentDepth = Math.max(0, this.#currentDepth - count);
    if (this.#isPaused && this.#currentDepth <= this.#lowWaterMark) {
      this.#isPaused = false;
      this.emit('resume', this.#currentDepth);
    }
  }

  reset() {
    this.#currentDepth = 0;
    this.#isPaused = false;
  }
}

module.exports = { BackpressureManager };
