}

/**
 * Schema-based event validator with support for required fields,
 * type checking, and custom validators.
 */
class EventValidator {
  #schemas;

  constructor() {
    this.#schemas = new Map();
  }

  /**
   * Register a schema for an event type.
   *
   * @param {string} eventType
   * @param {object} schema
   * @param {object} schema.fields - { fieldName: { type, required?, validator? } }
   * @param {boolean} [schema.allowExtra=false]
   */
  registerSchema(eventType, schema) {
    if (!eventType || typeof eventType !== 'string') {
      throw new TypeError('eventType must be a non-empty string');
    }
    this.#schemas.set(eventType, {
      fields: schema.fields || {},
      allowExtra: schema.allowExtra ?? false,
    });
    return this;
  }

  /**
   * Validate an event against its registered schema.
   * @param {object} event
   * @returns {{ valid: boolean, violations: string[] }}
   */
  validate(event) {
    const violations = [];

    // Base structure checks
    if (!event || typeof event !== 'object') {
      return { valid: false, violations: ['Event must be a non-null object'] };
    }

    if (!event.type || typeof event.type !== 'string') {
      violations.push('Event must have a string "type" field');
    }

    if (!event.timestamp) {
      violations.push('Event must have a "timestamp" field');
    } else if (isNaN(new Date(event.timestamp).getTime())) {
      violations.push('"timestamp" must be a valid date');
    }

    // Schema-specific validation
    const schema = this.#schemas.get(event.type);
    if (schema) {
      const payloadKeys = new Set(Object.keys(event.data || {}));

      for (const [field, rules] of Object.entries(schema.fields)) {
        const value = event.data?.[field];

        if (rules.required && (value === undefined || value === null)) {
          violations.push(`Field "${field}" is required`);
          continue;
        }

        if (value !== undefined && value !== null) {
          if (rules.type && typeof value !== rules.type) {
            violations.push(`Field "${field}" must be of type ${rules.type}, got ${typeof value}`);
          }

          if (rules.enum && !rules.enum.includes(value)) {
            violations.push(`Field "${field}" must be one of: ${rules.enum.join(', ')}`);
          }

          if (rules.min !== undefined && value < rules.min) {
            violations.push(`Field "${field}" must be >= ${rules.min}`);
          }

          if (rules.max !== undefined && value > rules.max) {
            violations.push(`Field "${field}" must be <= ${rules.max}`);
          }

          if (rules.pattern && typeof value === 'string' && !rules.pattern.test(value)) {
            violations.push(`Field "${field}" must match pattern ${rules.pattern}`);
          }

          if (rules.validator && typeof rules.validator === 'function') {
            const result = rules.validator(value);
            if (result !== true) {
              violations.push(`Field "${field}": ${result || 'custom validation failed'}`);
            }
          }
        }

        payloadKeys.delete(field);
      }

      if (!schema.allowExtra && payloadKeys.size > 0) {
        violations.push(`Unknown fields: ${[...payloadKeys].join(', ')}`);
      }
    }

    return { valid: violations.length === 0, violations };
  }

  /**
   * Validate and throw if invalid.
   * @param {object} event
   * @throws {ValidationError}
   */
  assertValid(event) {
    const { valid, violations } = this.validate(event);
    if (!valid) {
      throw new ValidationError('Event validation failed', violations);
    }
  }

  hasSchema(eventType) {
    return this.#schemas.has(eventType);
  }
}

module.exports = { EventValidator, ValidationError };
