```swift
import Foundation

// MARK: - Token Bucket Rate Limiter (Thread-safe via Actor)

actor TokenBucketRateLimiter {
    private let capacity: Int
    private let refillRate: Double          // tokens per second
    private var tokens: Double
    private var lastRefillTime: ContinuousClock.Instant

    init(capacity: Int, tokensPerSecond: Double) {
        self.capacity = capacity
        self.refillRate = tokensPerSecond
        self.tokens = Double(capacity)
        self.lastRefillTime = .now
    }

    /// Attempts to consume a token. Returns true if allowed.
    func tryConsume(count: Int = 1) -> Bool {
        refill()
        let needed = Double(count)
        guard tokens >= needed else { return false }
        tokens -= needed
        return true
    }

    /// Returns seconds to wait before a token is available.
    func timeUntilAvailable(count: Int = 1) -> Duration {
        refill()
        let needed = Double(count)
        if tokens >= needed { return .zero }
        let deficit = needed - tokens
        let seconds = deficit / refillRate
        return .seconds(seconds)
    }

    /// Waits until a token is available, then consumes it.
    func waitAndConsume(count: Int = 1) async throws {
        while true {
            if tryConsume(count: count) { return }
            let wait = timeUntilAvailable(count: count)
            try await Task.sleep(for: wait + .milliseconds(10)) // small buffer
        }
    }

    var availableTokens: Double {
        refill()
        return tokens
    }

    private func refill() {
        let now = ContinuousClock.Instant.now
        let elapsed = Double((now - lastRefillTime).components.seconds)
                    + Double((now - lastRefillTime).components.attoseconds) * 1e-18
        let newTokens = elapsed * refillRate
        tokens = min(Double(capacity), tokens + newTokens)
        lastRefillTime = now
    }
}

// MARK: - Job Definition

struct Job<Input: Sendable, Output: Sendable>: Sendable {
    let id: String
    let input: Input
    let work: @Sendable (Input) async throws -> Output
    let priority: TaskPriority

    init(
        id: String = UUID().uuidString,
        input: Input,
        priority: TaskPriority = .medium,
        work: @escaping @Sendable (Input) async throws -> Output
    ) {
        self.id = id
        self.input = input
        self.priority = priority
        self.work = work
    }
}

// MARK: - Job Result

enum JobResult<Output: Sendable>: Sendable {
    case success(jobId: String, output: Output)
    case failure(jobId: String, error: Error)
}

// MARK: - Worker Configuration

struct WorkerConfig {
    let maxConcurrency: Int
    let maxRetries: Int
    let baseRetryDelay: Duration
    let maxRetryDelay: Duration
    let rateLimiter: TokenBucketRateLimiter

    init(
        maxConcurrency: Int = 4,
        maxRetries: Int = 3,
        baseRetryDelay: Duration = .seconds(1),
        maxRetryDelay: Duration = .seconds(30),
        rateLimiter: TokenBucketRateLimiter
    ) {
        self.maxConcurrency = maxConcurrency
        self.maxRetries = maxRetries
        self.baseRetryDelay = baseRetryDelay
        self.maxRetryDelay = maxRetryDelay
        self.rateLimiter = rateLimiter
    }
}

// MARK: - Background Worker

actor BackgroundWorker<Input: Sendable, Output: Sendable> {
    private let config: WorkerConfig
    private var pendingJobs: [Job<Input, Output>] = []
    private var activeJobCount = 0
    private var isRunning = false
    private var processingTask: Task<Void, Never>?

    // Streams results back to the caller
    private var resultContinuation: AsyncStream<JobResult<Output>>.Continuation?
    let results: AsyncStream<JobResult<Output>>

    // Stats
    private(set) var totalProcessed = 0
    private(set) var totalFailed = 0
    private(set) var totalRetries = 0

    init(config: WorkerConfig) {
        self.config = config
        var continuation: AsyncStream<JobResult<Output>>.Continuation!
        self.results = AsyncStream { continuation = $0 }
        self.resultContinuation = continuation
    }

    // MARK: - Public API

    func enqueue(_ job: Job<Input, Output>) {
        pendingJobs.append(job)
        log("📥 Enqueued job \(job.id) (queue size: \(pendingJobs.count))")
        startProcessingIfNeeded()
    }

    func enqueue(_ jobs: [Job<Input, Output>]) {
        pendingJobs.append(contentsOf: jobs)
        log("📥 Enqueued \(jobs.count) jobs (queue size: \(pendingJobs.count))")
        startProcessingIfNeeded()
    }

    var queueDepth: Int { pendingJobs.count }
    var activeJobs: Int { activeJobCount }

    func shutdown() {
        isRunning = false
        processingTask?.cancel()
        processingTask = nil
        resultContinuation?.finish()
        log("🛑 Worker shut down. Processed: \(totalProcessed), Failed: \(totalFailed)")
    }

    // MARK: - Processing Loop

    private func startProcessingIfNeeded() {
        guard !isRunning else { return }
        isRunning = true

        processingTask = Task { [weak self] in
            guard let self else { return }
            await self.processLoop()
        }
    }

    private func processLoop() async {
        while isRunning {
            // Wait if at max concurrency
            if activeJobCount >= config.maxConcurrency {
                try? await Task.sleep(for: .milliseconds(50))
                continue
            }

            // Grab next job
            guard let job = dequeueNext() else {
                // No more work — stop the loop
                isRunning = false
                break
            }

            activeJobCount += 1

            // Spawn a detached task so jobs run concurrently
            Task(priority: job.priority) { [weak self] in
                guard let self else { return }
                await self.executeWithRetry(job: job, attempt: 1)
                await self.jobFinished()
            }
        }
    }

    private func dequeueNext() -> Job<Input, Output>? {
        guard !pendingJobs.isEmpty else { return nil }
        // Sort by priority descending on dequeue (simple priority queue)
        pendingJobs.sort { $0.priority > $1.priority }
        return pendingJobs.removeFirst()
    }

    private func jobFinished() {
        activeJobCount -= 1
        // Restart loop if there's pending work
        if !pendingJobs.isEmpty {
            startProcessingIfNeeded()
        }
    }

    // MARK: - Retry with Exponential Backoff

    private func executeWithRetry(job: Job<Input, Output>, attempt: Int) async {
        do {
            // ⏳ Wait for rate limiter before executing
            try await config.rateLimiter.waitAndConsume()

            log("🔄 Running job \(job.id) (attempt \(attempt))")
            let output = try await job.work(job.input)

            totalProcessed += 1
            resultContinuation?.yield(.success(jobId: job.id, output: output))
            log("✅ Job \(job.id) completed")

        } catch is CancellationError {
            log("⚠️  Job \(job.id) cancelled")
            resultContinuation?.yield(.failure(jobId: job.id, error: CancellationError()))

        } catch {
            if attempt < config.maxRetries {
                totalRetries += 1
                let delay = retryDelay(attempt: attempt)
                log("⏳ Job \(job.id) failed (attempt \(attempt)), retrying in \(delay)…")
                try? await Task.sleep(for: delay)

                guard !Task.isCancelled else { return }
                await executeWithRetry(job: job, attempt: attempt + 1)
            } else {
                totalFailed += 1
                resultContinuation?.yield(.failure(jobId: job.id, error: error))
                log("❌ Job \(job.id) failed after \(attempt) attempts: \(error)")
            }
        }
    }

    /// Exponential backoff with jitter
    private func retryDelay(attempt: Int) -> Duration {
        let base = Double(config.baseRetryDelay.components.seconds)
        let maxDelay = Double(config.maxRetryDelay.components.seconds)
        let exponential = base * pow(2.0, Double(attempt - 1))
        let jitter = Double.random(in: 0...0.5)
        let total = min(exponential + jitter, maxDelay)
        return .seconds(total)
    }

    private func log(_ message: String) {
        print("[Worker \(Date().formatted(.iso8601))] \(message)")
    }
}

// MARK: - TaskPriority + Comparable (for sorting)

extension TaskPriority: @retroactive Comparable {
    public static func < (lhs: TaskPriority, rhs: TaskPriority) -> Bool {
        lhs.rawValue < rhs.rawValue
    }
}

