template <typename T>
class ThreadSafeQueue {
public:
    void push(T item) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            queue_.push(std::move(item));
        }
        cv_.notify_one();
    }

    bool try_pop(T& item, std::chrono::milliseconds timeout) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (!cv_.wait_for(lock, timeout, [this] { return !queue_.empty() || shutdown_; })) {
            return false;
        }
        if (shutdown_ && queue_.empty()) return false;
        item = std::move(queue_.front());
        queue_.pop();
        return true;
    }

    void shutdown() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            shutdown_ = true;
        }
        cv_.notify_all();
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.size();
    }

private:
    std::queue<T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
    bool shutdown_ = false;
};

// ─── Rate Limiter (per-user message tracking) ────────────────

class RateLimiter {
public:
    RateLimiter(int max_messages, std::chrono::seconds window)
        : max_messages_(max_messages), window_(window) {}

    bool is_rate_limited(const std::string& user_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto now = std::chrono::steady_clock::now();
        auto& timestamps = user_messages_[user_id];

        // Evict old entries
        while (!timestamps.empty() && (now - timestamps.front()) > window_) {
            timestamps.pop_front();
        }
        timestamps.push_back(now);
        return static_cast<int>(timestamps.size()) > max_messages_;
    }

private:
    int max_messages_;
    std::chrono::seconds window_;
    std::mutex mutex_;
    std::unordered_map<std::string, std::deque<std::chrono::steady_clock::time_point>> user_messages_;
};

