        check_message_length(msg.content, result);

        determine_action(result);
        return result;
    }

private:
    std::unordered_set<std::string> banned_words_;
    std::vector<std::string> slur_patterns_;
    std::regex url_pattern_;
    double caps_threshold_;
    int max_repeated_chars_;

    static std::string to_lower(const std::string& s) {
        std::string result = s;
        std::transform(result.begin(), result.end(), result.begin(),
                       [](unsigned char c) { return std::tolower(c); });
        return result;
    }

    void check_banned_words(const std::string& lower, ModerationResult& result) {
        std::istringstream stream(lower);
        std::string word;
        while (stream >> word) {
            // Strip basic punctuation from word edges
            while (!word.empty() && std::ispunct(static_cast<unsigned char>(word.back())))
                word.pop_back();
            while (!word.empty() && std::ispunct(static_cast<unsigned char>(word.front())))
                word.erase(word.begin());

            if (banned_words_.count(word)) {
                result.reasons.push_back("Banned word: " + word);
                elevate_severity(result, Severity::MEDIUM);
            }
        }
    }

    void check_slurs(const std::string& lower, ModerationResult& result) {
        for (const auto& pattern : slur_patterns_) {
            if (lower.find(pattern) != std::string::npos) {
                result.reasons.push_back("Slur detected");
                elevate_severity(result, Severity::CRITICAL);
            }
        }
    }

    void check_spam_patterns(const std::string& content, ModerationResult& result) {
        // Excessive caps
        if (content.size() > 10) {
            long caps = std::count_if(content.begin(), content.end(),
                                      [](unsigned char c) { return std::isupper(c); });
            long alpha = std::count_if(content.begin(), content.end(),
                                       [](unsigned char c) { return std::isalpha(c); });
            if (alpha > 0 && static_cast<double>(caps) / alpha > caps_threshold_) {
                result.reasons.push_back("Excessive caps (" +
                    std::to_string(static_cast<int>(100.0 * caps / alpha)) + "%)");
                elevate_severity(result, Severity::LOW);
            }
        }

        // Repeated characters (e.g., "aaaaaaa")
        int repeat_count = 1;
        for (size_t i = 1; i < content.size(); ++i) {
            if (content[i] == content[i - 1]) {
                repeat_count++;
                if (repeat_count > max_repeated_chars_) {
                    result.reasons.push_back("Repeated characters");
                    elevate_severity(result, Severity::LOW);
                    break;
                }
            } else {
                repeat_count = 1;
            }
        }
    }

    void check_urls(const std::string& content, ModerationResult& result) {
        std::smatch match;
        if (std::regex_search(content, match, url_pattern_)) {
            result.reasons.push_back("Contains URL: " + match[0].str());
            elevate_severity(result, Severity::LOW);
        }
    }

    void check_message_length(const std::string& content, ModerationResult& result) {
        if (content.size() > 500) {
            result.reasons.push_back("Message too long (" +
                std::to_string(content.size()) + " chars)");
            elevate_severity(result, Severity::LOW);
        }
    }

    static void elevate_severity(ModerationResult& result, Severity new_sev) {
        if (new_sev > result.severity) {
            result.severity = new_sev;
        }
    }

    static void determine_action(ModerationResult& result) {
        switch (result.severity) {
            case Severity::CLEAN:    result.action = ActionType::ALLOW;  break;
            case Severity::LOW:      result.action = ActionType::WARN;   break;
            case Severity::MEDIUM:   result.action = ActionType::DELETE; break;
            case Severity::HIGH:     result.action = ActionType::MUTE;   break;
            case Severity::CRITICAL: result.action = ActionType::BAN;    break;
        }
    }
};

// ─── Moderation Consumer ─────────────────────────────────────

class ModerationConsumer {
public:
    ModerationConsumer(ThreadSafeQueue<ChatMessage>& inbox,
                       ThreadSafeQueue<ModerationResult>& outbox,
                       int num_workers = 2)
        : inbox_(inbox)
        , outbox_(outbox)
        , rate_limiter_(10, std::chrono::seconds(30))  // 10 msgs per 30s
    {
        for (int i = 0; i < num_workers; ++i) {
            workers_.emplace_back(&ModerationConsumer::worker_loop, this, i);
        }
        std::cout << "[Consumer] Started " << num_workers << " worker threads\n";
    }

    ~ModerationConsumer() { stop(); }

    void stop() {
        running_ = false;
        for (auto& w : workers_) {
            if (w.joinable()) w.join();
        }
        workers_.clear();
    }

    uint64_t processed_count() const { return processed_.load(); }

private:
    ThreadSafeQueue<ChatMessage>& inbox_;
    ThreadSafeQueue<ModerationResult>& outbox_;
    ContentFilter filter_;
    RateLimiter rate_limiter_;
    std::vector<std::thread> workers_;
    std::atomic<bool> running_{true};
    std::atomic<uint64_t> processed_{0};

    void worker_loop(int worker_id) {
        std::cout << "[Worker " << worker_id << "] Online\n";

        while (running_) {
            ChatMessage msg;
            if (!inbox_.try_pop(msg, std::chrono::milliseconds(200))) {
                continue;
            }

            // Run content filter
            ModerationResult result = filter_.analyze(msg);

            // Check rate limiting (can escalate)
            if (rate_limiter_.is_rate_limited(msg.user_id)) {
                result.reasons.push_back("Rate limited (flood)");
                if (result.severity < Severity::MEDIUM) {
                    result.severity = Severity::MEDIUM;
                    result.action = ActionType::DELETE;
                }
            }

            outbox_.push(std::move(result));
            processed_++;
        }

        std::cout << "[Worker " << worker_id << "] Shutting down\n";
    }
};

// ─── Logger / Result Processor ───────────────────────────────

class ModerationLogger {
public:
    explicit ModerationLogger(ThreadSafeQueue<ModerationResult>& results)
        : results_(results)
        , thread_(&ModerationLogger::run, this)
    {}

    ~ModerationLogger() { stop(); }

    void stop() {
        running_ = false;
        if (thread_.joinable()) thread_.join();
    }

private:
    ThreadSafeQueue<ModerationResult>& results_;
    std::thread thread_;
    std::atomic<bool> running_{true};

    static const char* severity_str(Severity s) {
        switch (s) {
            case Severity::CLEAN:    return "CLEAN";
            case Severity::LOW:      return "LOW";
            case Severity::MEDIUM:   return "MEDIUM";
            case Severity::HIGH:     return "HIGH";
            case Severity::CRITICAL: return "CRITICAL";
        }
        return "UNKNOWN";
    }

    static const char* action_str(ActionType a) {
        switch (a) {
            case ActionType::ALLOW:  return "ALLOW";
            case ActionType::WARN:   return "WARN";
            case ActionType::MUTE:   return "MUTE";
            case ActionType::DELETE: return "DELETE";
            case ActionType::BAN:    return "BAN";
        }
        return "UNKNOWN";
    }

    void run() {
        while (running_) {
            ModerationResult result;
            if (!results_.try_pop(result, std::chrono::milliseconds(200))) {
                continue;
            }

            // In production: write to DB, call APIs, emit webhooks
            std::ostringstream out;
            out << "[Mod] msg#" << result.message_id
                << " @" << result.username
                << " | " << severity_str(result.severity)
                << " → " << action_str(result.action);

            if (!result.reasons.empty()) {
                out << " | Reasons: ";
                for (size_t i = 0; i < result.reasons.size(); ++i) {
                    if (i) out << "; ";
                    out << result.reasons[i];
                }
            }

            out << "\n     Content: \"" << result.original_content << "\"\n";
            std::cout << out.str();
        }
    }
};

// ─── Demo / Main ─────────────────────────────────────────────

int main() {
    ThreadSafeQueue<ChatMessage> inbox;
    ThreadSafeQueue<ModerationResult> results;

    // Start consumer workers and logger
    ModerationConsumer consumer(inbox, results, 3);
    ModerationLogger logger(results);

    // Simulate incoming chat messages
    struct TestMsg { std::string uid; std::string name; std::string channel; std::string text; };
    std::vector<TestMsg> test_messages = {
        {"u1", "alice",   "#general",  "Hey everyone, how's it going?"},
        {"u2", "bob",     "#general",  "Check out this scam site http://evil.example.com"},
        {"u3", "charlie", "#gaming",   "ANYONE WANT TO PLAY SOME GAMES??? LETS GOOOOO"},
        {"u4", "dave",    "#help",     "I need help with my account please"},
        {"u5", "eve",     "#general",  "hahahahahaaaaaaaaaa this is so funny"},
        {"u2", "bob",     "#general",  "Free hack tools at http://malware.example.com"},
        {"u6", "frank",   "#trading",  "I'll cheat the system, easy exploit"},
        {"u1", "alice",   "#general",  "That sunset was beautiful!"},
        {"u7", "grace",   "#general",  "Normal message here, nothing wrong."},
        {"u3", "charlie", "#gaming",   "gg wp, that was a great match"},
    };

    // Flood test: bob sends many messages quickly
    for (int i = 0; i < 12; ++i) {
        test_messages.push_back({"u2", "bob", "#general",
            "spam message #" + std::to_string(i)});
    }

    uint64_t msg_id = 1;
    for (auto& tm : test_messages) {
        ChatMessage msg;
        msg.id = msg_id++;
        msg.user_id = tm.uid;
        msg.username = tm.name;
        msg.channel = tm.channel;
        msg.content = tm.text;
        msg.timestamp = std::chrono::steady_clock::now();
        inbox.push(std::move(msg));

        // Small delay to simulate real traffic
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
    }

    // Wait for processing to finish
    while (inbox.size() > 0 || results.size() > 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(500));

    // Shutdown
    inbox.shutdown();
    results.shutdown();
    consumer.stop();
    logger.stop();

    std::cout << "\n[Done] Processed " << consumer.processed_count() << " messages\n";
    return 0;
}
```

## What this does

**Architecture** — three decoupled stages connected by thread-safe queues:

```
Producers → [inbox queue] → ModerationConsumer (N workers) → [results queue] → Logger
```

**Key components:**

| Component | Role |
|---|---|
| `ThreadSafeQueue<T>` | Bounded MPMC queue with `condition_variable` wait and graceful shutdown |
| `ContentFilter` | Checks banned words, slurs, excessive caps, repeated chars, URLs, message length |
| `RateLimiter` | Sliding-window per-user flood detection (10 msgs / 30s) |
| `ModerationConsumer` | Spawns N worker threads that pull from inbox, run the filter + rate limiter, push results |
| `ModerationLogger` | Drains the results queue and logs actions (swap this for DB writes / API calls) |

**Severity escalation** — each check can raise but never lower the severity. Final action maps directly:

```
CLEAN → ALLOW
LOW → WARN
MEDIUM → DELETE
HIGH → MUTE
CRITICAL → BAN
```

**Production considerations** you'd add on top:
- Persistent queue (Redis Streams, Kafka, RabbitMQ) instead of in-memory
- Database-backed word lists with hot reload
- User reputation scores that affect thresholds
- Appeal/review queue for high-severity actions
- Metrics export (Prometheus counters for each action type)

