use clap::{Parser, Subcommand};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

// ─── CLI ────────────────────────────────────────────────────────

#[derive(Parser)]
#[command(name = "taskr", version, about = "A practical CLI task scheduler")]
struct Cli {
    #[command(subcommand)]
    command: Cmd,
}

