    List,
    /// Remove a task by ID prefix or name
    #[command(alias = "rm")]
    Remove { id: String },
    /// Start the scheduler loop
    Run {
        /// Poll interval in seconds
        #[arg(short, long, default_value = "1")]
        poll: u64,
    },
    /// Show execution history
    #[command(alias = "log")]
    History {
        /// Max entries to display
        #[arg(short, long, default_value = "20")]
        count: usize,
    },
    /// Enable a paused task
    Enable { id: String },
    /// Disable (pause) a task
    Disable { id: String },
}

// ─── Data Model ─────────────────────────────────────────────────

#[derive(Serialize, Deserialize, Clone, Debug)]
struct Task {
    id: String,
    name: String,
    command: String,
    schedule: Schedule,
    enabled: bool,
    created_at: DateTime<Local>,
    last_run: Option<DateTime<Local>>,
    run_count: u64,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(tag = "type")]
enum Schedule {
    Interval { seconds: u64 },
    Daily { hour: u32, minute: u32 },
    Once,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
struct LogEntry {
    task_id: String,
    task_name: String,
    ran_at: DateTime<Local>,
    duration_ms: u64,
    success: bool,
    exit_code: Option<i32>,
    output: String,
}

#[derive(Serialize, Deserialize, Default)]
struct Store {
    tasks: Vec<Task>,
    history: Vec<LogEntry>,
}

// ─── Storage (~/.taskr/data.json) ───────────────────────────────

fn data_path() -> Result<PathBuf> {
    let dir = dirs::home_dir()
        .context("Cannot determine home directory")?
        .join(".taskr");
    fs::create_dir_all(&dir)?;
    Ok(dir.join("data.json"))
}

fn load() -> Result<Store> {
    let path = data_path()?;
    if !path.exists() {
        return Ok(Store::default());
    }
    let json = fs::read_to_string(&path)?;
    serde_json::from_str(&json).context("Corrupted data file — check ~/.taskr/data.json")
}

fn save(store: &Store) -> Result<()> {
    let json = serde_json::to_string_pretty(store)?;
    fs::write(data_path()?, json)?;
    Ok(())
}

// ─── Schedule Parsing ───────────────────────────────────────────

fn parse_schedule(input: &str) -> Result<Schedule> {
    let s = input.trim().to_lowercase();

    if s == "once" {
        return Ok(Schedule::Once);
    }

    if let Some(dur) = s.strip_prefix("every ") {
        let dur = dur.trim();
        if dur.len() < 2 {
            bail!("Invalid interval '{dur}'. Examples: 30s, 5m, 2h, 1d");
        }
        let (digits, unit) = dur.split_at(dur.len() - 1);
        let n: u64 = digits.parse().context("Invalid number in interval")?;
        let secs = match unit {
            "s" => n,
            "m" => n * 60,
            "h" => n * 3600,
            "d" => n * 86400,
            _ => bail!("Unknown unit '{unit}'. Use s, m, h, or d"),
        };
        if secs == 0 {
            bail!("Interval must be > 0");
        }
        return Ok(Schedule::Interval { seconds: secs });
    }

    if let Some(time_str) = s.strip_prefix("daily ") {
        let parts: Vec<&str> = time_str.trim().split(':').collect();
        if parts.len() != 2 {
            bail!("Use HH:MM format for daily schedule");
        }
        let hour: u32 = parts[0].parse().context("Invalid hour")?;
        let minute: u32 = parts[1].parse().context("Invalid minute")?;
        if hour > 23 || minute > 59 {
            bail!("Hour must be 0–23, minute 0–59");
        }
        return Ok(Schedule::Daily { hour, minute });
    }

    bail!(
        "Invalid schedule: '{input}'\n\
         Examples: every 30s | every 5m | every 2h | daily 14:30 | once"
    )
}

// ─── Schedule Display & Due Check ───────────────────────────────

fn display_schedule(s: &Schedule) -> String {
    match s {
        Schedule::Interval { seconds } => {
            let v = *seconds;
            if v % 86400 == 0 {
                format!("every {}d", v / 86400)
            } else if v % 3600 == 0 {
                format!("every {}h", v / 3600)
            } else if v % 60 == 0 {
                format!("every {}m", v / 60)
            } else {
                format!("every {v}s")
            }
        }
        Schedule::Daily { hour, minute } => format!("daily {hour:02}:{minute:02}"),
        Schedule::Once => "once".into(),
    }
}

fn is_due(task: &Task) -> bool {
    if !task.enabled {
        return false;
    }

    let now = Local::now();

    match &task.schedule {
        Schedule::Interval { seconds } => match task.last_run {
            None => true,
            Some(last) => (now - last).num_seconds() >= *seconds as i64,
        },
        Schedule::Daily { hour, minute } => {
            let target =
                NaiveTime::from_hms_opt(*hour, *minute, 0).expect("validated during add");
            let now_time = now.time();
            match task.last_run {
                None => now_time >= target,
                Some(last) => last.date_naive() < now.date_naive() && now_time >= target,
            }
        }
        Schedule::Once => task.run_count == 0,
    }
}

// ─── Helpers ────────────────────────────────────────────────────

fn short_id(id: &str) -> &str {
    &id[..8.min(id.len())]
}

fn find_task(tasks: &[Task], query: &str) -> Result<usize> {
    let hits: Vec<usize> = tasks
        .iter()
        .enumerate()
        .filter(|(_, t)| t.id.starts_with(query) || t.name == query)
        .map(|(i, _)| i)
        .collect();

    match hits.len() {
        0 => bail!("No task matches '{query}'"),
        1 => Ok(hits[0]),
        _ => bail!("'{query}' is ambiguous — use a longer ID prefix"),
    }
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        let t: String = s.chars().take(max - 1).collect();
        format!("{t}…")
    }
}

fn fmt_duration(ms: u64) -> String {
    if ms < 1_000 {
        format!("{ms}ms")
    } else if ms < 60_000 {
        format!("{:.1}s", ms as f64 / 1_000.0)
    } else {
        format!("{:.1}m", ms as f64 / 60_000.0)
    }
}

// ─── Task Execution ─────────────────────────────────────────────

fn execute(task: &Task) -> LogEntry {
    let start = Instant::now();
    let ran_at = Local::now();

    let result = if cfg!(target_os = "windows") {
        ShellCmd::new("cmd").args(["/C", &task.command]).output()
    } else {
        ShellCmd::new("sh").args(["-c", &task.command]).output()
    };

    let duration_ms = start.elapsed().as_millis() as u64;

    match result {
        Ok(output) => {
            let mut text = String::from_utf8_lossy(&output.stdout).into_owned();
            let stderr = String::from_utf8_lossy(&output.stderr);
            if !stderr.is_empty() {
                if !text.is_empty() {
                    text.push('\n');
                }
                text.push_str(&stderr);
            }
            text.truncate(2_000); // cap stored output

            LogEntry {
                task_id: task.id.clone(),
                task_name: task.name.clone(),
                ran_at,
                duration_ms,
                success: output.status.success(),
                exit_code: output.status.code(),
                output: text,
            }
        }
        Err(e) => LogEntry {
            task_id: task.id.clone(),
            task_name: task.name.clone(),
            ran_at,
            duration_ms,
            success: false,
            exit_code: None,
            output: format!("exec error: {e}"),
        },
    }
}

// ─── Command Handlers ───────────────────────────────────────────

fn cmd_add(name: String, cmd: String, schedule_str: String) -> Result<()> {
    let schedule = parse_schedule(&schedule_str)?;
    let mut store = load()?;

    if store.tasks.iter().any(|t| t.name == name) {
        bail!("Task '{name}' already exists");
    }

    let id = Uuid::new_v4().to_string();
    let label = display_schedule(&schedule);

    store.tasks.push(Task {
        id: id.clone(),
        name: name.clone(),
        command: cmd.clone(),
        schedule,
        enabled: true,
        created_at: Local::now(),
        last_run: None,
        run_count: 0,
    });
    save(&store)?;

    println!("✓ Added: {name} [{}]", short_id(&id));
    println!("  Schedule: {label}");
    println!("  Command:  {cmd}");
    Ok(())
}

