# Basic File Watcher for Search Indexing (Linux/inotify)

## file_watcher.cpp

```cpp
#include <sys/inotify.h>
#include <unistd.h>
#include <dirent.h>
#include <climits>
#include <cerrno>
#include <cstring>

#include <string>
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <fstream>
#include <sstream>
#include <iostream>
#include <algorithm>
#include <functional>
#include <filesystem>

namespace fs = std::filesystem;

// ─── Event types ───────────────────────────────────────────────

enum class EventType { Created, Modified, Deleted };

struct FileEvent {
    EventType   type;
    std::string path;
};

// ─── Inverted search index ─────────────────────────────────────

class SearchIndex {
public:
    void addFile(const std::string& path) {
        removeFile(path);  // clear stale tokens first

        std::ifstream file(path);
        if (!file.is_open()) return;

        std::string word;
        std::unordered_set<std::string> tokens;

        // simple whitespace tokenizer, lowercased
        while (file >> word) {
            std::transform(word.begin(), word.end(), word.begin(), ::tolower);
            // strip non-alphanumeric edges
            while (!word.empty() && !std::isalnum(word.front())) word.erase(word.begin());
            while (!word.empty() && !std::isalnum(word.back()))  word.pop_back();
            if (!word.empty()) tokens.insert(word);
        }

        for (const auto& tok : tokens)
            index_[tok].insert(path);

        doc_tokens_[path] = std::move(tokens);
        std::cout << "  [index] added: " << path
                  << " (" << doc_tokens_[path].size() << " unique tokens)\n";
    }

    void removeFile(const std::string& path) {
        auto it = doc_tokens_.find(path);
        if (it == doc_tokens_.end()) return;

        for (const auto& tok : it->second) {
            auto idx_it = index_.find(tok);
            if (idx_it != index_.end()) {
                idx_it->second.erase(path);
                if (idx_it->second.empty()) index_.erase(idx_it);
            }
        }
        doc_tokens_.erase(it);
        std::cout << "  [index] removed: " << path << "\n";
    }

    std::vector<std::string> search(const std::string& query) const {
        std::string q = query;
        std::transform(q.begin(), q.end(), q.begin(), ::tolower);

        auto it = index_.find(q);
        if (it == index_.end()) return {};
        return {it->second.begin(), it->second.end()};
    }

    size_t docCount()  const { return doc_tokens_.size(); }
    size_t tokenCount() const { return index_.size(); }

private:
    // token -> set of file paths containing it
    std::unordered_map<std::string, std::unordered_set<std::string>> index_;
    // file path -> set of tokens (for fast removal)
    std::unordered_map<std::string, std::unordered_set<std::string>> doc_tokens_;
};

// ─── inotify file watcher ──────────────────────────────────────

class FileWatcher {
public:
    using Callback = std::function<void(const FileEvent&)>;

    explicit FileWatcher(const std::string& dir, Callback cb)
        : root_(dir), callback_(std::move(cb))
    {
        fd_ = inotify_init();
        if (fd_ < 0) {
            perror("inotify_init");
            return;
        }

        addWatchRecursive(root_);
    }

    ~FileWatcher() {
        for (auto& [wd, _] : wd_to_path_)
            inotify_rm_watch(fd_, wd);
        if (fd_ >= 0) close(fd_);
    }

    // blocks and dispatches events until stop() is called
    void poll() {
        constexpr size_t BUF_SIZE = 4096;
        alignas(inotify_event) char buf[BUF_SIZE];

        while (running_) {
            ssize_t len = read(fd_, buf, BUF_SIZE);
            if (len <= 0) {
                if (errno == EINTR) continue;
                perror("read");
                break;
            }

            for (char* ptr = buf; ptr < buf + len; ) {
                auto* ev = reinterpret_cast<inotify_event*>(ptr);
                handleEvent(ev);
                ptr += sizeof(inotify_event) + ev->len;
            }
        }
    }

    void stop() { running_ = false; }

private:
    void addWatchRecursive(const std::string& dir) {
        uint32_t mask = IN_CREATE | IN_MODIFY | IN_DELETE |
                        IN_MOVED_FROM | IN_MOVED_TO;

        int wd = inotify_add_watch(fd_, dir.c_str(), mask);
        if (wd < 0) {
            perror(("watch " + dir).c_str());
            return;
        }
        wd_to_path_[wd] = dir;

        // recurse into subdirectories
        for (auto& entry : fs::directory_iterator(dir)) {
            if (entry.is_directory())
                addWatchRecursive(entry.path().string());
        }
    }

    void handleEvent(const inotify_event* ev) {
        if (ev->len == 0) return;

        std::string dir  = wd_to_path_[ev->wd];
        std::string path = dir + "/" + ev->name;

        // skip hidden files
        if (ev->name[0] == '.') return;

        if (ev->mask & (IN_CREATE | IN_MOVED_TO)) {
            // if a new directory appears, start watching it
            if (ev->mask & IN_ISDIR) {
                addWatchRecursive(path);
            } else {
                callback_({EventType::Created, path});
            }
        }

        if (ev->mask & IN_MODIFY) {
            if (!(ev->mask & IN_ISDIR))
                callback_({EventType::Modified, path});
        }

        if (ev->mask & (IN_DELETE | IN_MOVED_FROM)) {
            if (!(ev->mask & IN_ISDIR))
                callback_({EventType::Deleted, path});
        }
    }

    int  fd_ = -1;
    bool running_ = true;
    std::string root_;
    Callback callback_;
    std::unordered_map<int, std::string> wd_to_path_;
};

// ─── Initial directory scan ────────────────────────────────────

static void indexExisting(const std::string& dir, SearchIndex& idx) {
    for (auto& entry : fs::recursive_directory_iterator(dir)) {
        if (entry.is_regular_file() && entry.path().filename().string()[0] != '.')
            idx.addFile(entry.path().string());
    }
}

// ─── Main ──────────────────────────────────────────────────────

int main(int argc, char* argv[]) {
    std::string watchDir = (argc > 1) ? argv[1] : ".";

    if (!fs::is_directory(watchDir)) {
        std::cerr << "Not a directory: " << watchDir << "\n";
        return 1;
    }

    std::cout << "=== File Watcher / Search Index ===\n";
    std::cout << "Watching: " << fs::canonical(watchDir) << "\n\n";

    SearchIndex index;

    // 1. index everything already on disk
    std::cout << "-- initial scan --\n";
    indexExisting(watchDir, index);
    std::cout << "-- scan done: " << index.docCount() << " docs, "
              << index.tokenCount() << " unique tokens --\n\n";

    // 2. handle live filesystem events
    auto onEvent = [&](const FileEvent& ev) {
        const char* tag = "";
        switch (ev.type) {
            case EventType::Created:  tag = "CREATE"; break;
            case EventType::Modified: tag = "MODIFY"; break;
            case EventType::Deleted:  tag = "DELETE"; break;
        }
        std::cout << "[" << tag << "] " << ev.path << "\n";

        switch (ev.type) {
            case EventType::Created:
            case EventType::Modified:
                index.addFile(ev.path);
                break;
            case EventType::Deleted:
                index.removeFile(ev.path);
                break;
        }

        std::cout << "  (index: " << index.docCount() << " docs, "
                  << index.tokenCount() << " tokens)\n";
    };

    FileWatcher watcher(watchDir, onEvent);

    std::cout << "Listening for changes (Ctrl-C to quit) ...\n\n";
    watcher.poll();

    return 0;
}
```

## Build & Run

```bash
