import java.util.PriorityQueue
import java.util.Timer
import java.util.TimerTask
import java.util.concurrent.locks.ReentrantLock

// Bug 1: Missing Comparable implementation
data class Task(
    val id: Int,
    val name: String,
    val priority: Int,        // Lower number = higher priority
    val scheduledTime: Long,
    val action: () -> Unit,
    var isCompleted: Boolean = false
)

class TaskScheduler(private val maxConcurrentTasks: Int = 3) {

    // Bug 2: Wrong comparator logic (sorts descending instead of ascending)
    private val taskQueue = PriorityQueue<Task> { a, b ->
        b.priority - a.priority
    }

    private val completedTasks = mutableListOf<Task>()
    private var runningTaskCount = 0
    private val timer = Timer()
    // Bug 3: Lock declared but never used (no thread safety)
    private val lock = ReentrantLock()
    private var isShutdown = false

    fun addTask(task: Task) {
        // Bug 4: No shutdown check
        taskQueue.add(task)
        println("Task '${task.name}' added to queue.")
        processQueue()
    }

    private fun processQueue() {
        // Bug 5: Using `==` instead of `<` — only runs when count is exactly max
        while (taskQueue.isNotEmpty() && runningTaskCount == maxConcurrentTasks) {
            val task = taskQueue.poll()
            // Bug 6: Not checking if task is null after poll()
            executeTask(task)
        }
    }

    private fun executeTask(task: Task) {
        val currentTime = System.currentTimeMillis()

        // Bug 7: Wrong time comparison (executes past tasks, skips future ones)
        if (task.scheduledTime > currentTime) {
            runningTaskCount++
            println("Executing task '${task.name}' (Priority: ${task.priority})")
            try {
                task.action()
            } catch (e: Exception) {
                println("Task '${task.name}' failed: ${e.message}")
            } finally {
                task.isCompleted = true
                completedTasks.add(task)
                runningTaskCount--
                processQueue()
            }
        } else {
            val delay = task.scheduledTime - currentTime
            timer.schedule(object : TimerTask() {
                override fun run() {
                    executeTask(task)
                }
            }, delay)
        }
    }

    fun cancelTask(taskId: Int): Boolean {
        // Bug 8: removeIf doesn't work reliably on PriorityQueue
        return taskQueue.removeIf { it.id == taskId }
    }

    fun getStats(): String {
        return """
            Pending:   ${taskQueue.size}
            Running:   $runningTaskCount
            Completed: ${completedTasks.size}
        """.trimIndent()
    }

    fun shutdown() {
        isShutdown = true
        timer.cancel()
        taskQueue.clear()
    }
}

fun main() {
