    scheduler.addTask(Task(1, "Low Priority", 10, System.currentTimeMillis()) {
        Thread.sleep(100)
        println("  -> Task 1 done")
    })
    scheduler.addTask(Task(2, "High Priority", 1, System.currentTimeMillis()) {
