## All 8 Bugs Explained & Fixed

```
Bug  | Line Area         | Problem                           | Fix
-----|-------------------|-----------------------------------|---------------------------
 1   | Task class        | Not Comparable; PQ needs ordering  | Implement Comparable<Task>
 2   | PriorityQueue     | Reversed comparator (b - a)        | Change to (a - b)
 3   | processQueue()    | Lock never used → race conditions  | Wrap critical sections
 4   | addTask()         | No shutdown guard                  | Check isShutdown flag
 5   | processQueue()    | == instead of < (logic inverted)   | Use < comparison
 6   | processQueue()    | Null-unsafe poll()                 | Null-safe check
 7   | executeTask()     | Inverted time check (> vs <=)      | Flip the condition
 8   | cancelTask()      | removeIf unreliable on PQ          | Rebuild queue after remove
```

## Fixed Code

```kotlin
import java.util.PriorityQueue
import java.util.Timer
import java.util.TimerTask
import java.util.concurrent.locks.ReentrantLock
import kotlin.concurrent.withLock

// ✅ Fix 1: Implement Comparable for reliable PriorityQueue ordering
data class Task(
    val id: Int,
    val name: String,
    val priority: Int,              // Lower number = higher priority
    val scheduledTime: Long,
    val action: () -> Unit,
    var isCompleted: Boolean = false
) : Comparable<Task> {
    override fun compareTo(other: Task): Int {
        // Primary sort: priority (ascending — lower = more urgent)
        val priorityCompare = this.priority.compareTo(other.priority)
        if (priorityCompare != 0) return priorityCompare
        // Secondary sort: earlier scheduled time first
        return this.scheduledTime.compareTo(other.scheduledTime)
    }
}

class TaskScheduler(private val maxConcurrentTasks: Int = 3) {

    // ✅ Fix 2: Correct ascending comparator (a - b), or rely on Comparable
    private val taskQueue = PriorityQueue<Task>()   // Uses Task.compareTo

    private val completedTasks = mutableListOf<Task>()
    private var runningTaskCount = 0
    private val timer = Timer(true)                  // Daemon timer
    // ✅ Fix 3: Actually USE the lock for thread safety
    private val lock = ReentrantLock()
    @Volatile
    private var isShutdown = false

    fun addTask(task: Task) {
        lock.withLock {
            // ✅ Fix 4: Guard against use after shutdown
            if (isShutdown) {
                println("⚠ Scheduler is shut down. Rejecting '${task.name}'.")
                return
            }
            taskQueue.add(task)
            println("➕ Task '${task.name}' added (Priority: ${task.priority})")
            processQueue()
        }
    }

    private fun processQueue() {
        // ✅ Fix 5: Use `<` so tasks run while count is BELOW max
        while (taskQueue.isNotEmpty() && runningTaskCount < maxConcurrentTasks) {
            // ✅ Fix 6: Null-safe handling after poll()
            val task = taskQueue.poll() ?: break
            executeTask(task)
        }
    }

    private fun executeTask(task: Task) {
        val currentTime = System.currentTimeMillis()

        // ✅ Fix 7: Execute if scheduled time has passed (<=), delay if in future
        if (task.scheduledTime <= currentTime) {
            runningTaskCount++
            println("▶ Executing '${task.name}' (Priority: ${task.priority})")

            // Run on a separate thread to avoid blocking the scheduler
            Thread {
                try {
                    task.action()
                } catch (e: Exception) {
                    println("❌ Task '${task.name}' failed: ${e.message}")
                } finally {
                    lock.withLock {
                        task.isCompleted = true
                        completedTasks.add(task)
                        runningTaskCount--
                        println("✅ Completed '${task.name}'")
                        processQueue()          // Pick up next queued task
                    }
                }
            }.start()
        } else {
            // Task is scheduled for the future — re-schedule after delay
            val delay = task.scheduledTime - currentTime
            println("⏳ Deferring '${task.name}' by ${delay}ms")
            runningTaskCount++                      // Reserve a slot

            timer.schedule(object : TimerTask() {
                override fun run() {
                    lock.withLock {
                        runningTaskCount--          // Release reserved slot
                        taskQueue.add(task)         // Re-add so processQueue picks it up
                        processQueue()
                    }
                }
            }, delay)
        }
    }

    // ✅ Fix 8: Rebuild queue for reliable removal
    fun cancelTask(taskId: Int): Boolean {
        lock.withLock {
            val original = taskQueue.toList()
            val target = original.find { it.id == taskId } ?: return false

            taskQueue.clear()
            original.filter { it.id != taskId }.forEach { taskQueue.add(it) }

            println("🚫 Cancelled task '${target.name}'")
            return true
        }
    }

    fun getStats(): String {
        lock.withLock {
            return """
                ┌─── Scheduler Stats ───┐
                │ Pending:   ${taskQueue.size.toString().padStart(10)} │
                │ Running:   ${runningTaskCount.toString().padStart(10)} │
                │ Completed: ${completedTasks.size.toString().padStart(10)} │
                └───────────────────────┘
            """.trimIndent()
        }
    }

    fun shutdown() {
        lock.withLock {
            isShutdown = true
            timer.cancel()
            taskQueue.clear()
            println("🛑 Scheduler shut down.")
        }
    }
}

// ─── Demo ────────────────────────────────────────────────────────────
fun main() {
    val scheduler = TaskScheduler(maxConcurrentTasks = 2)

    // Immediate tasks (different priorities)
    scheduler.addTask(Task(1, "Low-Priority Job", 10, System.currentTimeMillis()) {
        Thread.sleep(500)
        println("   → Task 1 work done")
    })
    scheduler.addTask(Task(2, "High-Priority Job", 1, System.currentTimeMillis()) {
        Thread.sleep(300)
        println("   → Task 2 work done")
    })
    scheduler.addTask(Task(3, "Medium-Priority Job", 5, System.currentTimeMillis()) {
        Thread.sleep(200)
        println("   → Task 3 work done")
    })

    // Delayed task
    scheduler.addTask(Task(4, "Delayed Job", 3, System.currentTimeMillis() + 2000) {
        println("   → Task 4 (delayed) work done")
    })

    // Cancel a pending task
    scheduler.cancelTask(3)

    // Wait for everything to finish
    Thread.sleep(5000)
    println(scheduler.getStats())
    scheduler.shutdown()
}
```

## Expected Output

```
➕ Task 'Low-Priority Job' added (Priority: 10)
▶ Executing 'Low-Priority Job' (Priority: 10)
➕ Task 'High-Priority Job' added (Priority: 1)
▶ Executing 'High-Priority Job' (Priority: 1)
➕ Task 'Medium-Priority Job' added (Priority: 5)
➕ Task 'Delayed Job' added (Priority: 3)
⏳ Deferring 'Delayed Job' by ~2000ms
🚫 Cancelled task 'Medium-Priority Job'
   → Task 2 work done
✅ Completed 'High-Priority Job'
   → Task 1 work done
✅ Completed 'Low-Priority Job'
   → Task 4 (delayed) work done
✅ Completed 'Delayed Job'
┌─── Scheduler Stats ───┐
│ Pending:            0 │
│ Running:            0 │
│ Completed:          3 │
└───────────────────────┘
🛑 Scheduler shut down.
```

## Key Debugging Takeaways

| Category | Lesson |
|---|---|
| **Comparator logic** | `a - b` = ascending (min-heap), `b - a` = descending (max-heap) |
| **Thread safety** | Always guard shared state (`runningTaskCount`, queue) with a lock |
| **Null safety** | `PriorityQueue.poll()` returns `null` on empty — always check |
| **Time comparison** | "Ready to run" means `scheduledTime <= now`, **not** `>` |
| **PriorityQueue** | `removeIf` may break heap invariant — rebuild after removal |
| **Resource cleanup** | Use daemon `Timer`, guard with `isShutdown`, release in `finally` |

