// ─── Metric Types ──────────────────────────────────────────────────────────────

enum class MetricType { Counter, Gauge, Histogram };

std::string metric_type_to_string(MetricType t) {
    switch (t) {
        case MetricType::Counter:   return "Counter";
        case MetricType::Gauge:     return "Gauge";
        case MetricType::Histogram: return "Histogram";
    }
    return "Unknown";
}

// Holds a single metric's identity and tags
struct MetricKey {
    std::string name;
    MetricType  type;
    std::unordered_map<std::string, std::string> tags;

    bool operator==(const MetricKey& other) const {
        return name == other.name && type == other.type && tags == other.tags;
    }
};

// Hash for MetricKey so it can be used in unordered containers
struct MetricKeyHash {
    size_t operator()(const MetricKey& k) const {
        size_t h = std::hash<std::string>{}(k.name);
        h ^= std::hash<int>{}(static_cast<int>(k.type)) << 1;
        for (auto& [tag_k, tag_v] : k.tags) {
            h ^= std::hash<std::string>{}(tag_k) * 31;
            h ^= std::hash<std::string>{}(tag_v) * 37;
        }
        return h;
    }
};

// Aggregated statistics for a single metric
struct AggregatedStats {
    double   sum          = 0.0;
    double   min_val      = std::numeric_limits<double>::max();
    double   max_val      = std::numeric_limits<double>::lowest();
    double   last_val     = 0.0;
    uint64_t sample_count = 0;
    std::vector<double> samples;  // kept for histogram percentile calc

    void record(double value) {
        sum += value;
        min_val = std::min(min_val, value);
        max_val = std::max(max_val, value);
        last_val = value;
        ++sample_count;
        samples.push_back(value);
    }

    double mean() const {
        return sample_count > 0 ? sum / sample_count : 0.0;
    }

    // Returns the p-th percentile (p in [0,100])
    double percentile(double p) const {
        if (samples.empty()) return 0.0;
        auto sorted = samples;
        std::sort(sorted.begin(), sorted.end());
        double rank = (p / 100.0) * static_cast<double>(sorted.size() - 1);
        size_t lo = static_cast<size_t>(std::floor(rank));
        size_t hi = static_cast<size_t>(std::ceil(rank));
        if (lo == hi) return sorted[lo];
        double frac = rank - static_cast<double>(lo);
        return sorted[lo] * (1.0 - frac) + sorted[hi] * frac;
    }
};

// ─── Abstract Metrics Backend ──────────────────────────────────────────────────

class IMetricsBackend {
public:
    virtual ~IMetricsBackend() = default;
    virtual std::string backend_name() const = 0;
    virtual void emit(const MetricKey& key, double value) = 0;
    virtual void flush() = 0;
    virtual std::unordered_map<MetricKey, AggregatedStats, MetricKeyHash>
        snapshot() const = 0;
};

// ─── Legacy Backend (simulates old system) ─────────────────────────────────────

class LegacyMetricsBackend : public IMetricsBackend {
    mutable std::mutex mu_;
    std::unordered_map<MetricKey, AggregatedStats, MetricKeyHash> store_;
public:
    std::string backend_name() const override { return "LegacyBackend"; }

    void emit(const MetricKey& key, double value) override {
        std::lock_guard lock(mu_);
        store_[key].record(value);
    }

    void flush() override {
        std::lock_guard lock(mu_);
        // Legacy system: pretend we push to a flat file
    }

    std::unordered_map<MetricKey, AggregatedStats, MetricKeyHash>
    snapshot() const override {
        std::lock_guard lock(mu_);
        return store_;
    }
};

// ─── New Backend (simulates new system) ────────────────────────────────────────

class NewMetricsBackend : public IMetricsBackend {
    mutable std::mutex mu_;
    std::unordered_map<MetricKey, AggregatedStats, MetricKeyHash> store_;
public:
    std::string backend_name() const override { return "NewBackend"; }

    void emit(const MetricKey& key, double value) override {
        std::lock_guard lock(mu_);
        store_[key].record(value);
    }

    void flush() override {
        std::lock_guard lock(mu_);
        // New system: pretend we push to a time-series database
    }

    std::unordered_map<MetricKey, AggregatedStats, MetricKeyHash>
    snapshot() const override {
        std::lock_guard lock(mu_);
        return store_;
    }
};

// ─── Migration Phase ───────────────────────────────────────────────────────────

enum class MigrationPhase {
    LegacyOnly,   // All traffic → legacy
    DualWrite,     // Write to both; read from legacy (shadow new)
    DualRead,      // Write to both; compare reads (canary)
    NewOnly        // All traffic → new
};

std::string phase_to_string(MigrationPhase p) {
    switch (p) {
        case MigrationPhase::LegacyOnly: return "LegacyOnly";
        case MigrationPhase::DualWrite:  return "DualWrite";
        case MigrationPhase::DualRead:   return "DualRead";
        case MigrationPhase::NewOnly:    return "NewOnly";
    }
    return "Unknown";
}

// ─── Comparison / Drift Report ─────────────────────────────────────────────────

struct DriftEntry {
    MetricKey key;
    double    legacy_mean;
    double    new_mean;
    double    drift_pct;        // |legacy - new| / legacy * 100
    uint64_t  legacy_samples;
    uint64_t  new_samples;
};

struct MigrationReport {
    MigrationPhase                phase;
    size_t                        total_metrics;
    size_t                        drifted_metrics;   // above threshold
    double                        drift_threshold_pct;
    std::vector<DriftEntry>       entries;

    void print(std::ostream& os) const {
        os << "\n╔══════════════════════════════════════════════════════════════╗\n";
        os << "║            MIGRATION DRIFT REPORT                           ║\n";
        os << "╠══════════════════════════════════════════════════════════════╣\n";
        os << "  Phase            : " << phase_to_string(phase) << "\n";
        os << "  Total metrics    : " << total_metrics << "\n";
        os << "  Drifted (>"
           << drift_threshold_pct << "%) : " << drifted_metrics << "\n";
        os << "╠══════════════════════════════════════════════════════════════╣\n";
        os << std::left
           << std::setw(24) << "  Metric"
           << std::setw(10) << "Type"
           << std::setw(14) << "Legacy Mean"
           << std::setw(14) << "New Mean"
           << std::setw(10) << "Drift%"
           << "\n";
        os << "  " << std::string(58, '-') << "\n";
        for (auto& e : entries) {
            os << "  " << std::left
               << std::setw(24) << e.key.name
               << std::setw(10) << metric_type_to_string(e.key.type)
               << std::setw(14) << std::fixed << std::setprecision(4) << e.legacy_mean
               << std::setw(14) << e.new_mean
               << std::setw(10) << e.drift_pct
               << (e.drift_pct > drift_threshold_pct ? " *** DRIFT ***" : "")
               << "\n";
        }
        os << "╚══════════════════════════════════════════════════════════════╝\n";
    }
};

// ─── Metric Name Transformer ───────────────────────────────────────────────────
// Allows renaming / re-tagging metrics during migration

struct MetricTransformRule {
    std::string                                old_prefix;
    std::string                                new_prefix;
    std::unordered_map<std::string,std::string> add_tags;
    std::unordered_map<std::string,std::string> rename_tags;
};

class MetricTransformer {
    std::vector<MetricTransformRule> rules_;
public:
    void add_rule(MetricTransformRule rule) {
        rules_.push_back(std::move(rule));
    }

    MetricKey transform(const MetricKey& original) const {
        MetricKey result = original;
        for (auto& rule : rules_) {
            // Prefix replacement
            if (result.name.rfind(rule.old_prefix, 0) == 0) {
                result.name = rule.new_prefix
                            + result.name.substr(rule.old_prefix.size());
            }
            // Add tags
            for (auto& [k, v] : rule.add_tags) {
                result.tags[k] = v;
            }
            // Rename tags
            for (auto& [old_tag, new_tag] : rule.rename_tags) {
                if (auto it = result.tags.find(old_tag); it != result.tags.end()) {
                    result.tags[new_tag] = it->second;
                    result.tags.erase(it);
                }
            }
        }
        return result;
    }
};

// ─── Migration Helper (core class) ────────────────────────────────────────────

class MetricsMigrationHelper {
public:
    using PhaseChangeCallback = std::function<void(MigrationPhase, MigrationPhase)>;

    MetricsMigrationHelper(
        std::shared_ptr<IMetricsBackend> legacy,
        std::shared_ptr<IMetricsBackend> new_backend,
        double drift_threshold_pct = 5.0
    )
        : legacy_(std::move(legacy))
        , new_(std::move(new_backend))
        , phase_(MigrationPhase::LegacyOnly)
        , drift_threshold_(drift_threshold_pct)
    {}

    // ── Phase control ──────────────────────────────────

    MigrationPhase current_phase() const {
        std::lock_guard lock(mu_);
        return phase_;
    }

    void advance_phase() {
        std::lock_guard lock(mu_);
        auto old = phase_;
        switch (phase_) {
            case MigrationPhase::LegacyOnly:
                phase_ = MigrationPhase::DualWrite; break;
            case MigrationPhase::DualWrite:
                phase_ = MigrationPhase::DualRead;  break;
            case MigrationPhase::DualRead:
                phase_ = MigrationPhase::NewOnly;    break;
            case MigrationPhase::NewOnly:
                break; // already final
        }
        if (old != phase_ && on_phase_change_) {
            on_phase_change_(old, phase_);
        }
    }

    void set_phase(MigrationPhase p) {
        std::lock_guard lock(mu_);
        auto old = phase_;
        phase_ = p;
        if (old != phase_ && on_phase_change_) {
            on_phase_change_(old, phase_);
        }
    }

    void on_phase_change(PhaseChangeCallback cb) {
        std::lock_guard lock(mu_);
        on_phase_change_ = std::move(cb);
    }

    // ── Transformer ────────────────────────────────────

    MetricTransformer& transformer() { return transformer_; }

    // ── Core emit (called by application code) ────────

    void emit(const MetricKey& key, double value) {
        std::lock_guard lock(mu_);

        switch (phase_) {
            case MigrationPhase::LegacyOnly:
                legacy_->emit(key, value);
                break;

            case MigrationPhase::DualWrite:
            case MigrationPhase::DualRead: {
                legacy_->emit(key, value);
                // Transform the key for the new backend
                auto transformed = transformer_.transform(key);
                new_->emit(transformed, value);
                break;
            }

            case MigrationPhase::NewOnly: {
                auto transformed = transformer_.transform(key);
                new_->emit(transformed, value);
                break;
            }
        }
    }

    // ── Flush both backends ────────────────────────────

    void flush() {
        std::lock_guard lock(mu_);
        legacy_->flush();
        new_->flush();
    }

    // ── Drift comparison ───────────────────────────────

    MigrationReport generate_report() const {
        std::lock_guard lock(mu_);

        auto legacy_snap = legacy_->snapshot();
        auto new_snap    = new_->snapshot();

        MigrationReport report;
        report.phase              = phase_;
        report.drift_threshold_pct = drift_threshold_;
        report.drifted_metrics    = 0;

        // Build entries for every metric in legacy
        for (auto& [key, lstats] : legacy_snap) {
            DriftEntry entry;
            entry.key            = key;
            entry.legacy_mean    = lstats.mean();
            entry.legacy_samples = lstats.sample_count;

            // Find matching metric in new (after transform)
            auto tkey = transformer_.transform(key);
            if (auto it = new_snap.find(tkey); it != new_snap.end()) {
                entry.new_mean    = it->second.mean();
                entry.new_samples = it->second.sample_count;
            } else {
                entry.new_mean    = 0.0;
                entry.new_samples = 0;
            }

            // Drift calculation
            if (entry.legacy_mean != 0.0) {
                entry.drift_pct = std::abs(entry.legacy_mean - entry.new_mean)
                                / std::abs(entry.legacy_mean) * 100.0;
            } else {
                entry.drift_pct = entry.new_mean == 0.0 ? 0.0 : 100.0;
            }

            if (entry.drift_pct > drift_threshold_) {
                ++report.drifted_metrics;
            }

            report.entries.push_back(std::move(entry));
        }

        report.total_metrics = report.entries.size();

        // Sort worst drift first
        std::sort(report.entries.begin(), report.entries.end(),
                  [](auto& a, auto& b){ return a.drift_pct > b.drift_pct; });

        return report;
    }

    // ── Convenience: is safe to fully cut over? ───────

    bool is_migration_safe() const {
        auto report = generate_report();
        return report.drifted_metrics == 0;
    }

private:
    std::shared_ptr<IMetricsBackend> legacy_;
    std::shared_ptr<IMetricsBackend> new_;
    MigrationPhase                   phase_;
    double                           drift_threshold_;
    MetricTransformer                transformer_;
    PhaseChangeCallback              on_phase_change_;
    mutable std::mutex               mu_;
};

