import { ParseError as ParseErrorInfo, DocumentType } from './types';

export class DocumentParseError extends Error {
  public readonly code: string;
  public readonly line?: number;
  public readonly column?: number;
  public readonly documentType?: DocumentType;

  constructor(
    message: string,
    code: string,
    options?: {
      line?: number;
      column?: number;
      documentType?: DocumentType;
      cause?: Error;
    }
  ) {
    super(message);
    this.name = 'DocumentParseError';
    this.code = code;
    this.line = options?.line;
    this.column = options?.column;
    this.documentType = options?.documentType;
    if (options?.cause) {
      this.cause = options.cause;
    }
    Object.setPrototypeOf(this, DocumentParseError.prototype);
  }

  toErrorInfo(): ParseErrorInfo {
    return {
      code: this.code,
      message: this.message,
      line: this.line,
      column: this.column,
      cause: this.cause instanceof Error ? this.cause : undefined,
    };
  }
}

export class InputTooLargeError extends DocumentParseError {
  constructor(actualSize: number, maxSize: number) {
    super(
      `Input size ${actualSize} bytes exceeds maximum ${maxSize} bytes`,
      'INPUT_TOO_LARGE'
    );
    this.name = 'InputTooLargeError';
    Object.setPrototypeOf(this, InputTooLargeError.prototype);
  }
}

export class UnsupportedDocumentTypeError extends DocumentParseError {
  constructor(documentType: string) {
    super(
      `Unsupported document type: ${documentType}`,
      'UNSUPPORTED_DOCUMENT_TYPE'
    );
    this.name = 'UnsupportedDocumentTypeError';
    Object.setPrototypeOf(this, UnsupportedDocumentTypeError.prototype);
  }
}

