### `src/parsers/base.ts`

```typescript
import {
  BaseParserOptions,
  DocumentType,
  IDocumentParser,
  ParseDiagnostic,
  ParseMetadata,
  ParseResult,
  ParseSuccess,
  ParseFailure,
  Severity,
} from '../types';
import { DocumentParseError, InputTooLargeError, ErrorCodes } from '../errors';

const DEFAULT_MAX_SIZE = 10 * 1024 * 1024; // 10 MB

export abstract class BaseParser<T, O extends BaseParserOptions = BaseParserOptions>
  implements IDocumentParser<T, O>
{
  abstract readonly documentType: DocumentType;

  parse(input: string, options?: O): ParseResult<T> {
    const startTime = performance.now();
    const diagnostics: ParseDiagnostic[] = [];
    const opts = this.mergeDefaults(options);

    try {
      // Pre-validation
      this.validateInput(input, opts);

      // Core parse
      const data = this.doParse(input, opts, diagnostics);

      const metadata = this.buildMetadata(input, startTime);
      return this.success(data, metadata, diagnostics);
    } catch (err) {
      const metadata: Partial<ParseMetadata> = {
        documentType: this.documentType,
        parseTimeMs: performance.now() - startTime,
        sizeBytes: Buffer.byteLength(input, 'utf-8'),
      };

      if (err instanceof DocumentParseError) {
        return this.failure(err.toErrorInfo(), metadata, diagnostics);
      }

      const parseError = {
        code: 'UNKNOWN_ERROR',
        message: err instanceof Error ? err.message : String(err),
        cause: err instanceof Error ? err : undefined,
      };
      return this.failure(parseError, metadata, diagnostics);
    }
  }

  validate(input: string, options?: O): readonly ParseDiagnostic[] {
    const result = this.parse(input, options);
    const diagnostics = [...result.diagnostics];
    if (!result.success) {
      diagnostics.push({
        severity: Severity.Error,
        message: result.error.message,
        line: result.error.line,
        column: result.error.column,
      });
    }
    return diagnostics;
  }

  // Subclasses implement this
  protected abstract doParse(
    input: string,
    options: O,
    diagnostics: ParseDiagnostic[]
  ): T;

  protected abstract getDefaultOptions(): O;

  protected mergeDefaults(options?: O): O {
    return { ...this.getDefaultOptions(), ...options };
  }

  protected validateInput(input: string, options: O): void {
    if (!input || input.trim().length === 0) {
      throw new DocumentParseError('Input is empty', ErrorCodes.INPUT_EMPTY, {
        documentType: this.documentType,
      });
    }

    const maxSize = options.maxSizeBytes ?? DEFAULT_MAX_SIZE;
    const actualSize = Buffer.byteLength(input, 'utf-8');
    if (actualSize > maxSize) {
      throw new InputTooLargeError(actualSize, maxSize);
    }
  }

  protected buildMetadata(input: string, startTime: number): ParseMetadata {
    return {
      documentType: this.documentType,
      parseTimeMs: Math.round((performance.now() - startTime) * 1000) / 1000,
      sizeBytes: Buffer.byteLength(input, 'utf-8'),
      lineCount: input.split('\n').length,
    };
  }

  protected success(
    data: T,
    metadata: ParseMetadata,
    diagnostics: ParseDiagnostic[]
  ): ParseSuccess<T> {
    return { success: true, data, metadata, diagnostics };
  }

  protected failure(
    error: { code: string; message: string; line?: number; column?: number; cause?: Error },
    metadata: Partial<ParseMetadata>,
    diagnostics: ParseDiagnostic[]
  ): ParseFailure {
    return { success: false, error, metadata, diagnostics };
  }

  protected addDiagnostic(
    diagnostics: ParseDiagnostic[],
    severity: Severity,
    message: string,
    line?: number,
    column?: number
  ): void {
    diagnostics.push({ severity, message, line, column });
  }

  protected countLine(input: string, position: number): number {
    let line = 1;
    for (let i = 0; i < position && i < input.length; i++) {
      if (input[i] === '\n') line++;
    }
    return line;
  }

  protected countColumn(input: string, position: number): number {
    let col = 1;
    for (let i = position - 1; i >= 0; i--) {
      if (input[i] === '\n') break;
      col++;
    }
    return col;
  }
}
