```typescript
import { BaseParser } from './base';
import {
  DocumentType,
  JSONParserOptions,
  ParseDiagnostic,
  Severity,
} from '../types';
import { DocumentParseError, ErrorCodes } from '../errors';

export class JSONParser extends BaseParser<unknown, JSONParserOptions> {
  readonly documentType = DocumentType.JSON;

  protected getDefaultOptions(): JSONParserOptions {
    return {
      strict: true,
      allowComments: false,
      allowTrailingCommas: false,
      maxDepth: 100,
    };
  }

  protected doParse(
    input: string,
    options: JSONParserOptions,
    diagnostics: ParseDiagnostic[]
  ): unknown {
    let processed = input;

    // Strip comments if allowed
    if (options.allowComments) {
      processed = this.stripComments(processed);
      this.addDiagnostic(
        diagnostics,
        Severity.Info,
        'Comments were stripped from JSON input'
      );
    }

    // Strip trailing commas if allowed
    if (options.allowTrailingCommas) {
      processed = this.stripTrailingCommas(processed);
      this.addDiagnostic(
        diagnostics,
        Severity.Info,
        'Trailing commas were stripped from JSON input'
      );
    }

    try {
      const parsed = JSON.parse(processed);

      // Depth check
      if (options.maxDepth !== undefined) {
        const depth = this.measureDepth(parsed);
        if (depth > options.maxDepth) {
          throw new DocumentParseError(
            `JSON depth ${depth} exceeds maximum ${options.maxDepth}`,
            ErrorCodes.MAX_DEPTH_EXCEEDED,
            { documentType: DocumentType.JSON }
          );
        }
      }

      // Warnings for non-strict
      if (!options.strict) {
        if (typeof parsed !== 'object' || parsed === null) {
          this.addDiagnostic(
            diagnostics,
            Severity.Warning,
            'Root value is not an object or array'
          );
        }
      }

      return parsed;
    } catch (err) {
      if (err instanceof DocumentParseError) throw err;

      const nativeError = err as SyntaxError;
      const position = this.extractPosition(nativeError.message);

      throw new DocumentParseError(
        `Invalid JSON: ${nativeError.message}`,
        ErrorCodes.INVALID_JSON,
        {
          documentType: DocumentType.JSON,
          line: position ? this.countLine(input, position) : undefined,
          column: position ? this.countColumn(input, position) : undefined,
          cause: nativeError,
        }
      );
    }
  }

# Background Worker with Cancellation in PHP

This uses `pcntl_fork` to run tasks in child processes and maps OS signals (SIGTERM) to a **CancellationToken** for cooperative cancellation.

## Core Classes

### CancellationToken

```php
<?php
declare(strict_types=1);

class CancelledException extends RuntimeException
{
    public function __construct(string $message = 'The operation was cancelled.')
    {
        parent::__construct($message);
    }
}

class CancellationToken
{
    private bool $cancelled = false;
    /** @var callable[] */
    private array $listeners = [];

    /**
     * Request cancellation and fire all registered callbacks.
     */
    public function cancel(): void
    {
        if ($this->cancelled) {
            return;
        }

        $this->cancelled = true;

        foreach ($this->listeners as $listener) {
            $listener();
        }

        $this->listeners = [];
    }

    /**
     * Check cancellation state.
     * Also dispatches pending signals so handlers can fire first.
     */
    public function isCancelled(): bool
    {
        if (!$this->cancelled) {
            pcntl_signal_dispatch();  // let queued signals update state
        }
        return $this->cancelled;
    }

    /**
     * Throw immediately if cancellation was already requested.
     */
    public function throwIfCancelled(): void
    {
        if ($this->isCancelled()) {
            throw new CancelledException();
        }
    }

    /**
     * Register a cleanup callback. Fires immediately if already cancelled.
     */
    public function onCancel(callable $listener): void
    {
        if ($this->cancelled) {
            $listener();
            return;
        }
        $this->listeners[] = $listener;
    }

    /**
     * Sleep in small increments so cancellation is detected quickly.
     */
    public function sleepWithCancel(int $milliseconds): void
    {
        $remaining = $milliseconds;
        $step = 100; // check every 100ms

        while ($remaining > 0 && !$this->isCancelled()) {
            usleep(min($step, $remaining) * 1000);
            $remaining -= $step;
        }
    }
}
