### BackgroundWorker

```php
class BackgroundWorker
{
    private ?int $childPid = null;
    private int  $exitCode = -1;
    private bool $running  = false;

    public function __construct(
        private readonly string $label = 'worker'
    ) {}

    // ── Lifecycle ──────────────────────────────────────────

    /**
     * Fork a child process and execute $task.
     * The task receives a CancellationToken wired to SIGTERM/SIGINT.
     *
     * @param callable(CancellationToken): void $task
     */
    public function start(callable $task): void
    {
        if ($this->running) {
            throw new RuntimeException("Worker '{$this->label}' already running.");
        }

        $pid = pcntl_fork();

        if ($pid === -1) {
            throw new RuntimeException('pcntl_fork() failed.');
        }

        if ($pid === 0) {
            // ── Child process ──
            $this->executeInChild($task);
        }

        // ── Parent process ──
        $this->childPid = $pid;
        $this->running  = true;
    }

    /**
     * Runs inside the forked child — never returns.
     */
    private function executeInChild(callable $task): never
    {
        $token = new CancellationToken();

        // Wire OS signals → token cancellation
        $signalHandler = static fn() => $token->cancel();
        pcntl_signal(SIGTERM, $signalHandler);
        pcntl_signal(SIGINT,  $signalHandler);

        try {
            $task($token);
            exit(0);                       // success
        } catch (CancelledException) {
            exit(1);                       // graceful cancellation
        } catch (\Throwable $e) {
            fwrite(STDERR, "[{$this->label}] Fatal: {$e->getMessage()}\n");
            exit(2);                       // error
        }
    }

    // ── Cancellation ──────────────────────────────────────

    /**
     * Send SIGTERM — asks the child to cancel gracefully.
     */
    public function cancel(): bool
    {
        if (!$this->running || $this->childPid === null) {
            return false;
        }
        return posix_kill($this->childPid, SIGTERM);
    }

    /**
     * Send SIGKILL — force-kill with no cleanup.
     */
    public function kill(): bool
    {
        if (!$this->running || $this->childPid === null) {
            return false;
        }
        return posix_kill($this->childPid, SIGKILL);
    }

    /**
     * Cancel gracefully, then force-kill if the timeout expires.
     */
    public function cancelAndWait(int $timeoutSeconds = 5): int
    {
        $this->cancel();
        $deadline = time() + $timeoutSeconds;

        while ($this->isRunning() && time() < $deadline) {
            usleep(50_000); // poll every 50 ms
        }

        if ($this->isRunning()) {
            fwrite(STDERR, "[{$this->label}] Timeout — sending SIGKILL.\n");
            $this->kill();
        }

        return $this->wait();
    }

    // ── Waiting / Status ──────────────────────────────────

    /**
     * Block until the child exits. Returns exit code.
     */
    public function wait(): int
    {
        if ($this->childPid === null) {
            return $this->exitCode;
        }

        pcntl_waitpid($this->childPid, $status);
        $this->running = false;
        $this->exitCode = $this->extractExitCode($status);

        return $this->exitCode;
    }

    /**
     * Non-blocking: is the child still alive?
     */
    public function isRunning(): bool
    {
        if (!$this->running || $this->childPid === null) {
            return false;
        }

        $result = pcntl_waitpid($this->childPid, $status, WNOHANG);

        if ($result === $this->childPid) {
            $this->running  = false;
            $this->exitCode = $this->extractExitCode($status);
            return false;
        }

        return $result === 0;
    }

    private function extractExitCode(int $status): int
    {
        if (pcntl_wifexited($status)) {
            return pcntl_wexitstatus($status);
        }
        if (pcntl_wifsignaled($status)) {
            return 128 + pcntl_wtermsig($status);
        }
        return -1;
    }

    // ── Accessors ─────────────────────────────────────────

    public function getExitCode(): int   { return $this->exitCode; }
    public function getPid(): ?int       { return $this->childPid; }
    public function getLabel(): string   { return $this->label; }
}
