### WorkerPool

```php
class WorkerPool
{
    /** @var BackgroundWorker[] */
    private array $workers = [];

    public function start(BackgroundWorker $worker, callable $task): void
    {
        $worker->start($task);
        $this->workers[] = $worker;
    }

    /**
     * Cancel every running worker, wait up to $timeout seconds total.
     */
    public function cancelAll(int $timeout = 5): array
    {
        // Phase 1: send SIGTERM to all
        foreach ($this->workers as $w) {
            if ($w->isRunning()) {
                $w->cancel();
            }
        }

        // Phase 2: wait with shared deadline
        $deadline = time() + $timeout;
        $results  = [];

        foreach ($this->workers as $w) {
            $remaining = max(1, $deadline - time());

            if ($w->isRunning()) {
                $start = time();
                while ($w->isRunning() && (time() - $start) < $remaining) {
                    usleep(50_000);
                }
                if ($w->isRunning()) {
                    $w->kill();
                }
            }

            $results[$w->getLabel()] = $w->wait();
        }

        return $results;
    }

    public function waitAll(): array
    {
        $results = [];
        foreach ($this->workers as $w) {
            $results[$w->getLabel()] = $w->wait();
        }
        return $results;
    }
}
