## Example Usage

```php
<?php
require_once __DIR__ . '/BackgroundWorker.php'; // or autoload

// ── Task A: iterative work (throw-style cancellation) ────────

$batchProcessor = function (CancellationToken $token): void {
    for ($i = 1; $i <= 50; $i++) {
        $token->throwIfCancelled();          // ← checkpoint

        echo "[batch] Processing item {$i}/50\n";
        usleep(200_000);                     // simulate work
    }
    echo "[batch] All items done.\n";
};

// ── Task B: long-running loop (flag-style cancellation) ──────

$heartbeat = function (CancellationToken $token): void {
    // Register a cleanup callback
    $token->onCancel(function () {
        echo "[heartbeat] Cleaning up resources...\n";
    });

    while (!$token->isCancelled()) {         // ← poll flag
        echo "[heartbeat] Ping " . date('H:i:s') . "\n";
        $token->sleepWithCancel(1000);       // 1 s, but exits early on cancel
    }

    echo "[heartbeat] Shut down gracefully.\n";
};

// ── Run everything ───────────────────────────────────────────

$pool = new WorkerPool();

$w1 = new BackgroundWorker('batch');
$w2 = new BackgroundWorker('heartbeat');

$pool->start($w1, $batchProcessor);
$pool->start($w2, $heartbeat);

echo "Started workers — PIDs: {$w1->getPid()}, {$w2->getPid()}\n";
echo "Running for 3 seconds...\n\n";

sleep(3);

echo "\n--- Cancelling all workers (5 s timeout) ---\n\n";
$results = $pool->cancelAll(timeout: 5);

echo "\n--- Exit codes ---\n";
foreach ($results as $label => $code) {
    $status = match ($code) {
        0 => 'completed',
        1 => 'cancelled',
        default => "error ({$code})",
    };
    echo "  {$label}: {$status}\n";
}
