```go
package main

import (
	"os"
	"strings"
	"sync"
	"unicode"
)

// SearchIndex is a basic inverted index mapping tokens to file paths.
type SearchIndex struct {
	mu    sync.RWMutex
	index map[string]map[string]bool // token -> set of file paths
}

func NewSearchIndex() *SearchIndex {
	return &SearchIndex{
		index: make(map[string]map[string]bool),
	}
}

// tokenize splits text into lowercase alphanumeric tokens.
func tokenize(text string) []string {
	words := strings.FieldsFunc(text, func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsDigit(r)
	})
	tokens := make([]string, 0, len(words))
	for _, w := range words {
		t := strings.ToLower(w)
		if len(t) > 1 { // skip single-char tokens
			tokens = append(tokens, t)
		}
	}
	return tokens
}

// AddFile reads a file and indexes its contents.
func (si *SearchIndex) AddFile(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	tokens := tokenize(string(data))

	si.mu.Lock()
	defer si.mu.Unlock()

	// Remove old entries for this file first (handles updates)
	si.removeFileLocked(path)

	for _, token := range tokens {
		if si.index[token] == nil {
			si.index[token] = make(map[string]bool)
		}
		si.index[token][path] = true
	}
	return nil
}

// RemoveFile removes all index entries for a file.
func (si *SearchIndex) RemoveFile(path string) {
	si.mu.Lock()
	defer si.mu.Unlock()
	si.removeFileLocked(path)
}

func (si *SearchIndex) removeFileLocked(path string) {
	for token, files := range si.index {
		delete(files, path)
		if len(files) == 0 {
			delete(si.index, token)
		}
	}
}

// Search returns file paths containing ALL query terms.
func (si *SearchIndex) Search(query string) []string {
	terms := tokenize(query)
	if len(terms) == 0 {
		return nil
	}

	si.mu.RLock()
	defer si.mu.RUnlock()

	// Start with files matching the first term
	result := make(map[string]bool)
	if files, ok := si.index[terms[0]]; ok {
		for f := range files {
			result[f] = true
		}
	} else {
		return nil
	}

	// Intersect with remaining terms
	for _, term := range terms[1:] {
		files, ok := si.index[term]
		if !ok {
			return nil
		}
		for f := range result {
			if !files[f] {
				delete(result, f)
			}
		}
	}

	paths := make([]string, 0, len(result))
	for f := range result {
		paths = append(paths, f)
	}
	return paths
}

// Stats returns token count and indexed file count.
func (si *SearchIndex) Stats() (tokens int, files int) {
	si.mu.RLock()
	defer si.mu.RUnlock()

	fileSet := make(map[string]bool)
	for _, paths := range si.index {
		for f := range paths {
			fileSet[f] = true
		}
	}
	return len(si.index), len(fileSet)
}
