```go
package main

import (
	"log"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/fsnotify/fsnotify"
)

// Watcher monitors directories and updates the search index.
type Watcher struct {
	fsw        *fsnotify.Watcher
	index      *SearchIndex
	extensions map[string]bool // file extensions to index (e.g. ".txt", ".go")
	debounce   map[string]*time.Timer
}

func NewWatcher(index *SearchIndex, extensions []string) (*Watcher, error) {
	fsw, err := fsnotify.NewWatcher()
	if err != nil {
		return nil, err
	}

	extMap := make(map[string]bool)
	for _, ext := range extensions {
		if !strings.HasPrefix(ext, ".") {
			ext = "." + ext
		}
		extMap[ext] = true
	}

	return &Watcher{
		fsw:        fsw,
		index:      index,
		extensions: extMap,
		debounce:   make(map[string]*time.Timer),
	}, nil
}

func (w *Watcher) shouldIndex(path string) bool {
	if len(w.extensions) == 0 {
		return true
	}
	return w.extensions[filepath.Ext(path)]
}

// WatchDir adds a directory (and its subdirectories) to the watcher
// and indexes existing files.
func (w *Watcher) WatchDir(root string) error {
	return filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		// Skip hidden directories
		if info.IsDir() && strings.HasPrefix(info.Name(), ".") && path != root {
			return filepath.SkipDir
		}

		if info.IsDir() {
			log.Printf("[watch] %s", path)
			return w.fsw.Add(path)
		}

		// Index existing files
		if w.shouldIndex(path) {
			if err := w.index.AddFile(path); err != nil {
				log.Printf("[index error] %s: %v", path, err)
			} else {
				log.Printf("[indexed] %s", path)
			}
		}
		return nil
	})
}

// Start begins listening for file system events. Blocks until done is closed.
func (w *Watcher) Start(done <-chan struct{}) {
	const debounceDelay = 200 * time.Millisecond

	for {
		select {
		case <-done:
			w.fsw.Close()
			return

		case event, ok := <-w.fsw.Events:
			if !ok {
				return
			}
			w.handleEvent(event, debounceDelay)

		case err, ok := <-w.fsw.Errors:
			if !ok {
				return
			}
			log.Printf("[watcher error] %v", err)
		}
	}
}

func (w *Watcher) handleEvent(event fsnotify.Event, delay time.Duration) {
	path := event.Name

	// If a new directory is created, watch it too
	if event.Op&fsnotify.Create != 0 {
		if info, err := os.Stat(path); err == nil && info.IsDir() {
			log.Printf("[new dir] %s", path)
			w.WatchDir(path)
			return
		}
	}

	if !w.shouldIndex(path) {
		return
	}

	// Debounce rapid writes to the same file
	if timer, exists := w.debounce[path]; exists {
		timer.Stop()
	}

	w.debounce[path] = time.AfterFunc(delay, func() {
		delete(w.debounce, path)

		switch {
		case event.Op&fsnotify.Remove != 0 || event.Op&fsnotify.Rename != 0:
			log.Printf("[removed] %s", path)
			w.index.RemoveFile(path)

		case event.Op&fsnotify.Create != 0 || event.Op&fsnotify.Write != 0:
			if err := w.index.AddFile(path); err != nil {
				log.Printf("[index error] %s: %v", path, err)
			} else {
				log.Printf("[reindexed] %s", path)
			}
		}
	})
}
