## main.go — CLI Entrypoint

```go
package main

import (
	"bufio"
	"fmt"
	"log"
	"os"
	"strings"
)

func main() {
	// Defaults
	watchDir := "."
	extensions := []string{".txt", ".md", ".go", ".py", ".js", ".html", ".css", ".json"}

	if len(os.Args) > 1 {
		watchDir = os.Args[1]
	}

	// Verify directory exists
	info, err := os.Stat(watchDir)
	if err != nil || !info.IsDir() {
		log.Fatalf("Invalid directory: %s", watchDir)
	}

	index := NewSearchIndex()
	watcher, err := NewWatcher(index, extensions)
	if err != nil {
		log.Fatalf("Failed to create watcher: %v", err)
	}

	// Index existing files and start watching
	if err := watcher.WatchDir(watchDir); err != nil {
		log.Fatalf("Failed to watch directory: %v", err)
	}

	tokens, files := index.Stats()
	log.Printf("Initial index: %d tokens across %d files", tokens, files)

	done := make(chan struct{})
	go watcher.Start(done)

	// Interactive search REPL
	fmt.Println("\n--- File Search (type a query, or 'quit' to exit) ---")
	scanner := bufio.NewScanner(os.Stdin)

	for {
		fmt.Print("search> ")
		if !scanner.Scan() {
			break
		}
		query := strings.TrimSpace(scanner.Text())

		switch query {
		case "":
			continue
		case "quit", "exit":
			close(done)
			fmt.Println("Bye.")
			return
		case ":stats":
			t, f := index.Stats()
			fmt.Printf("  %d tokens, %d files\n", t, f)
			continue
		}

		results := index.Search(query)
		if len(results) == 0 {
			fmt.Println("  No results.")
		} else {
			for _, r := range results {
				fmt.Printf("  %s\n", r)
			}
		}
	}

	close(done)
}
