// Models/Event.swift

import Foundation

/// Severity levels for events
enum EventSeverity: String, Codable, Comparable {
    case debug
    case info
    case warning
    case error
    case critical

    private var rank: Int {
        switch self {
        case .debug:    return 0
        case .info:     return 1
        case .warning:  return 2
        case .error:    return 3
        case .critical: return 4
        }
    }

    static func < (lhs: EventSeverity, rhs: EventSeverity) -> Bool {
        lhs.rank < rhs.rank
    }
}

/// A single event to be processed
struct Event {
    let id: String
    let source: String
    let type: String
    let severity: EventSeverity
    let payload: [String: Any]
    let timestamp: Date

    init(
        id: String = UUID().uuidString,
        source: String,
        type: String,
        severity: EventSeverity,
        payload: [String: Any] = [:],
        timestamp: Date = Date()
    ) {
        self.id = id
        self.source = source
        self.type = type
        self.severity = severity
        self.payload = payload
        self.timestamp = timestamp
    }
}

extension Event: CustomStringConvertible {
    var description: String {
        "Event(\(id.prefix(8))… | \(source).\(type) | \(severity.rawValue))"
    }
}
