// Models/Config.swift

import Foundation

/// Top-level configuration model
struct EventProcessorConfig: Codable {
    let version: String
    let pipeline: PipelineConfig
    let sources: [SourceConfig]
    let filters: [FilterConfig]
    let routes: [RouteConfig]
    let handlers: [HandlerConfig]
    let settings: SettingsConfig

    enum CodingKeys: String, CodingKey {
        case version, pipeline, sources, filters, routes, handlers, settings
    }
}

struct PipelineConfig: Codable {
    let name: String
    let maxConcurrency: Int
    let bufferSize: Int
    let retryPolicy: RetryPolicy

    enum CodingKeys: String, CodingKey {
        case name
        case maxConcurrency = "max_concurrency"
        case bufferSize = "buffer_size"
        case retryPolicy = "retry_policy"
    }
}

struct RetryPolicy: Codable {
    let maxAttempts: Int
    let backoffSeconds: Double
    let exponential: Bool

    enum CodingKeys: String, CodingKey {
        case maxAttempts = "max_attempts"
        case backoffSeconds = "backoff_seconds"
        case exponential
    }
}

struct SourceConfig: Codable {
    let id: String
    let type: String
    let enabled: Bool
    let properties: [String: PropertyValue]
}

struct FilterConfig: Codable {
    let id: String
    let type: FilterType
    let condition: FilterCondition
}

enum FilterType: String, Codable {
    case severity
    case source
    case eventType = "event_type"
    case payload
    case composite
}

struct FilterCondition: Codable {
    let field: String?
    let op: FilterOperator
    let value: PropertyValue?
    let children: [FilterCondition]?

    enum CodingKeys: String, CodingKey {
        case field, op, value, children
    }
}

enum FilterOperator: String, Codable {
    case eq, neq, gt, gte, lt, lte
    case contains, startsWith = "starts_with"
    case `in`
    case and, or, not
}

struct RouteConfig: Codable {
    let id: String
    let filterIds: [String]
    let handlerIds: [String]
    let priority: Int

    enum CodingKeys: String, CodingKey {
        case id
        case filterIds = "filter_ids"
        case handlerIds = "handler_ids"
        case priority
    }
}

struct HandlerConfig: Codable {
    let id: String
    let type: HandlerType
    let properties: [String: PropertyValue]
}

enum HandlerType: String, Codable {
    case console
    case file
    case webhook
    case aggregate
}

struct SettingsConfig: Codable {
    let logLevel: String
    let metricsEnabled: Bool
    let healthCheckIntervalSeconds: Int

    enum CodingKeys: String, CodingKey {
        case logLevel = "log_level"
        case metricsEnabled = "metrics_enabled"
        case healthCheckIntervalSeconds = "health_check_interval_seconds"
    }
}

/// A flexible value type for config properties
enum PropertyValue: Codable, Equatable {
    case string(String)
    case int(Int)
    case double(Double)
    case bool(Bool)
    case array([PropertyValue])

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let v = try? container.decode(Bool.self)   { self = .bool(v); return }
        if let v = try? container.decode(Int.self)    { self = .int(v); return }
        if let v = try? container.decode(Double.self) { self = .double(v); return }
        if let v = try? container.decode(String.self) { self = .string(v); return }
        if let v = try? container.decode([PropertyValue].self) { self = .array(v); return }
        throw DecodingError.typeMismatch(
            PropertyValue.self,
            .init(codingPath: decoder.codingPath, debugDescription: "Unsupported type")
        )
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .string(let v): try container.encode(v)
        case .int(let v):    try container.encode(v)
        case .double(let v): try container.encode(v)
        case .bool(let v):   try container.encode(v)
        case .array(let v):  try container.encode(v)
        }
    }

    var stringValue: String? {
        if case .string(let v) = self { return v }
        return nil
    }

    var intValue: Int? {
        if case .int(let v) = self { return v }
        return nil
    }
}
