```swift
// Parsing/ConfigParser.swift

import Foundation

enum ConfigError: Error, CustomStringConvertible {
    case fileNotFound(String)
    case readError(String, underlying: Error)
    case parseError(String, underlying: Error)
    case validationError([String])
    case unsupportedFormat(String)

    var description: String {
        switch self {
        case .fileNotFound(let path):
            return "Config file not found: \(path)"
        case .readError(let path, let err):
            return "Failed to read \(path): \(err.localizedDescription)"
        case .parseError(let detail, let err):
            return "Parse error – \(detail): \(err.localizedDescription)"
        case .validationError(let issues):
            return "Validation errors:\n" + issues.map { "  • \($0)" }.joined(separator: "\n")
        case .unsupportedFormat(let ext):
            return "Unsupported config format: \(ext)"
        }
    }
}

/// Parses JSON config into a strongly-typed model
final class ConfigParser {

    private let validator = ConfigValidator()

    /// Parse from a file path
    func parse(filePath: String) throws -> EventProcessorConfig {
        let url = URL(fileURLWithPath: filePath)

        guard FileManager.default.fileExists(atPath: filePath) else {
            throw ConfigError.fileNotFound(filePath)
        }

        guard url.pathExtension == "json" else {
            throw ConfigError.unsupportedFormat(url.pathExtension)
        }

        let data: Data
        do {
            data = try Data(contentsOf: url)
        } catch {
            throw ConfigError.readError(filePath, underlying: error)
        }

        return try parse(data: data)
    }

    /// Parse from raw JSON data
    func parse(data: Data) throws -> EventProcessorConfig {
        let decoder = JSONDecoder()

        let config: EventProcessorConfig
        do {
            config = try decoder.decode(EventProcessorConfig.self, from: data)
        } catch {
            throw ConfigError.parseError("Invalid JSON structure", underlying: error)
        }

        let issues = validator.validate(config)
        guard issues.isEmpty else {
            throw ConfigError.validationError(issues)
        }

        return config
    }

    /// Parse from a JSON string
    func parse(jsonString: String) throws -> EventProcessorConfig {
        guard let data = jsonString.data(using: .utf8) else {
            throw ConfigError.parseError(
                "Invalid UTF-8",
                underlying: NSError(domain: "ConfigParser", code: 1)
            )
        }
        return try parse(data: data)
    }
}
