```swift
// Parsing/ConfigValidator.swift

import Foundation

/// Validates a parsed config for logical correctness
struct ConfigValidator {

    func validate(_ config: EventProcessorConfig) -> [String] {
        var issues: [String] = []

        validatePipeline(config.pipeline, issues: &issues)
        validateSources(config.sources, issues: &issues)
        validateFilters(config.filters, issues: &issues)
        validateHandlers(config.handlers, issues: &issues)
        validateRoutes(config.routes, config: config, issues: &issues)

        return issues
    }

    // MARK: – Section validators

    private func validatePipeline(_ p: PipelineConfig, issues: inout [String]) {
        if p.name.isEmpty {
            issues.append("Pipeline name must not be empty")
        }
        if p.maxConcurrency < 1 {
            issues.append("max_concurrency must be >= 1, got \(p.maxConcurrency)")
        }
        if p.bufferSize < 1 {
            issues.append("buffer_size must be >= 1, got \(p.bufferSize)")
        }
        if p.retryPolicy.maxAttempts < 0 {
            issues.append("retry max_attempts must be >= 0")
        }
        if p.retryPolicy.backoffSeconds < 0 {
            issues.append("retry backoff_seconds must be >= 0")
        }
    }

    private func validateSources(_ sources: [SourceConfig], issues: inout [String]) {
        let ids = sources.map(\.id)
        checkDuplicates(ids, label: "Source", issues: &issues)

        for src in sources where src.id.isEmpty {
            issues.append("Source id must not be empty")
        }
    }

    private func validateFilters(_ filters: [FilterConfig], issues: inout [String]) {
        let ids = filters.map(\.id)
        checkDuplicates(ids, label: "Filter", issues: &issues)
    }

    private func validateHandlers(_ handlers: [HandlerConfig], issues: inout [String]) {
        let ids = handlers.map(\.id)
        checkDuplicates(ids, label: "Handler", issues: &issues)

        for handler in handlers {
            switch handler.type {
            case .file:
                if handler.properties["path"]?.stringValue == nil {
                    issues.append("File handler '\(handler.id)' requires a 'path' property")
                }
            case .webhook:
                if handler.properties["url"]?.stringValue == nil {
                    issues.append("Webhook handler '\(handler.id)' requires a 'url' property")
                }
            default:
                break
            }
        }
    }

    private func validateRoutes(
        _ routes: [RouteConfig],
        config: EventProcessorConfig,
        issues: inout [String]
    ) {
        let filterIds = Set(config.filters.map(\.id))
        let handlerIds = Set(config.handlers.map(\.id))

        for route in routes {
            for fid in route.filterIds where !filterIds.contains(fid) {
                issues.append("Route '\(route.id)' references unknown filter '\(fid)'")
            }
            for hid in route.handlerIds where !handlerIds.contains(hid) {
                issues.append("Route '\(route.id)' references unknown handler '\(hid)'")
            }
        }
    }

    // MARK: – Helpers

    private func checkDuplicates(_ ids: [String], label: String, issues: inout [String]) {
        var seen = Set<String>()
        for id in ids {
            if !seen.insert(id).inserted {
                issues.append("\(label) id '\(id)' is duplicated")
            }
        }
    }
}
