// Processing/EventFilter.swift

import Foundation

/// Protocol every filter must conform to
protocol EventFiltering {
    var id: String { get }
    func matches(_ event: Event) -> Bool
}

/// Builds concrete filters from config
struct EventFilterFactory {

    static func build(from config: FilterConfig) -> EventFiltering {
        switch config.type {
        case .severity:
            return SeverityFilter(id: config.id, condition: config.condition)
        case .source:
            return FieldFilter(id: config.id, condition: config.condition, keyPath: \.source)
        case .eventType:
            return FieldFilter(id: config.id, condition: config.condition, keyPath: \.type)
        case .payload:
            return PayloadFilter(id: config.id, condition: config.condition)
        case .composite:
            return CompositeFilter(id: config.id, condition: config.condition)
        }
    }
}

// MARK: – Concrete Filters

struct SeverityFilter: EventFiltering {
    let id: String
    let condition: FilterCondition

    func matches(_ event: Event) -> Bool {
        guard let thresholdStr = condition.value?.stringValue,
              let threshold = EventSeverity(rawValue: thresholdStr) else {
            return true
        }

        switch condition.op {
        case .gte: return event.severity >= threshold
        case .gt:  return event.severity >  threshold
        case .lte: return event.severity <= threshold
        case .lt:  return event.severity <  threshold
        case .eq:  return event.severity == threshold
        case .neq: return event.severity != threshold
        default:   return true
        }
    }
}

struct FieldFilter: EventFiltering {
    let id: String
    let condition: FilterCondition
    let keyPath: KeyPath<Event, String>

    func matches(_ event: Event) -> Bool {
        let fieldValue = event[keyPath: keyPath]
        guard let target = condition.value?.stringValue else { return true }

        switch condition.op {
        case .eq:         return fieldValue == target
        case .neq:        return fieldValue != target
        case .contains:   return fieldValue.contains(target)
        case .startsWith: return fieldValue.hasPrefix(target)
        case .in:
            if case .array(let arr) = condition.value {
                return arr.compactMap(\.stringValue).contains(fieldValue)
            }
            return false
        default: return true
        }
    }
}

struct PayloadFilter: EventFiltering {
    let id: String
    let condition: FilterCondition

    func matches(_ event: Event) -> Bool {
        guard let field = condition.field,
              let actual = event.payload[field] else {
            return false
        }

        if let target = condition.value?.stringValue,
           let actualStr = actual as? String {
            switch condition.op {
            case .eq:       return actualStr == target
            case .neq:      return actualStr != target
            case .contains: return actualStr.contains(target)
