// MARK: - SyncError.swift

import Foundation

/// All errors that can occur during file synchronization.
public enum SyncError: Error, CustomStringConvertible {
    case fileNotFound(path: String)
    case permissionDenied(path: String)
    case checksumMismatch(expected: String, actual: String)
    case networkUnavailable
    case timeout(operation: String, duration: TimeInterval)
    case conflict(local: FileMetadata, remote: FileMetadata)
    case storageInsufficient(required: UInt64, available: UInt64)
    case transferFailed(underlying: Error)
    case maxRetriesExceeded(operation: String, attempts: Int, lastError: Error)
    case cancelled
    case corruptManifest(reason: String)
    case rateLimited(retryAfter: TimeInterval)
    case serverError(statusCode: Int, message: String)

    public var description: String {
        switch self {
        case .fileNotFound(let path):
            return "File not found: \(path)"
        case .permissionDenied(let path):
            return "Permission denied: \(path)"
        case .checksumMismatch(let expected, let actual):
            return "Checksum mismatch — expected: \(expected), got: \(actual)"
        case .networkUnavailable:
            return "Network unavailable"
        case .timeout(let op, let dur):
            return "Timeout after \(dur)s during: \(op)"
        case .conflict(let local, let remote):
            return "Conflict — local: \(local.path), remote: \(remote.path)"
        case .storageInsufficient(let req, let avail):
            return "Insufficient storage — need: \(req), available: \(avail)"
        case .transferFailed(let err):
            return "Transfer failed: \(err.localizedDescription)"
        case .maxRetriesExceeded(let op, let attempts, let err):
            return "Max retries (\(attempts)) exceeded for \(op): \(err.localizedDescription)"
        case .cancelled:
            return "Operation cancelled"
        case .corruptManifest(let reason):
            return "Corrupt manifest: \(reason)"
        case .rateLimited(let retryAfter):
            return "Rate limited — retry after \(retryAfter)s"
        case .serverError(let code, let msg):
            return "Server error [\(code)]: \(msg)"
        }
    }

    /// Whether this error is transient and the operation may succeed on retry.
    public var isRetryable: Bool {
        switch self {
        case .networkUnavailable, .timeout, .transferFailed,
             .rateLimited, .serverError:
            return true
        case .fileNotFound, .permissionDenied, .checksumMismatch,
             .conflict, .storageInsufficient, .maxRetriesExceeded,
             .cancelled, .corruptManifest:
            return false
        }
    }
}
