// MARK: - FileMetadata.swift

import Foundation
import CryptoKit

/// Immutable snapshot of a file's metadata used for sync comparison.
public struct FileMetadata: Codable, Sendable, Equatable {
    public let path: String
    public let relativePath: String
    public let size: UInt64
    public let modifiedDate: Date
    public let checksum: String
    public let isDirectory: Bool

    public init(
        path: String,
        relativePath: String,
        size: UInt64,
        modifiedDate: Date,
        checksum: String,
        isDirectory: Bool
    ) {
        self.path = path
        self.relativePath = relativePath
        self.size = size
        self.modifiedDate = modifiedDate
        self.checksum = checksum
        self.isDirectory = isDirectory
    }

    /// Builds metadata by reading the file at `url` relative to `baseURL`.
    public static func from(
        url: URL,
        relativeTo baseURL: URL
    ) throws -> FileMetadata {
        let attrs = try FileManager.default
            .attributesOfItem(atPath: url.path)

        let size = attrs[.size] as? UInt64 ?? 0
        let modified = attrs[.modificationDate] as? Date ?? .distantPast
        let isDir = (attrs[.type] as? FileAttributeType) == .typeDirectory
        let checksum = isDir ? "" : try Self.sha256(of: url)

        let relative = url.path.replacingOccurrences(
            of: baseURL.path,
            with: ""
        ).trimmingCharacters(in: CharacterSet(charactersIn: "/"))

        return FileMetadata(
            path: url.path,
            relativePath: relative,
            size: size,
            modifiedDate: modified,
            checksum: checksum,
            isDirectory: isDir
        )
    }

    /// SHA-256 hex digest, streamed in 64 KB chunks.
    public static func sha256(of url: URL) throws -> String {
        let handle = try FileHandle(forReadingFrom: url)
        defer { handle.closeFile() }

        var hasher = SHA256()
        let bufferSize = 65_536

        while autoreleasepool(invoking: {
            let data = handle.readData(ofLength: bufferSize)
            guard !data.isEmpty else { return false }
            hasher.update(data: data)
            return true
        }) {}

        return hasher.finalize()
            .map { String(format: "%02x", $0) }
            .joined()
    }
}
