        case normal = 1
        case high = 2
        case critical = 3

        public static func < (lhs: Priority, rhs: Priority) -> Bool {
            lhs.rawValue < rhs.rawValue
        }
    }

    public init(
        type: OperationType,
        source: FileMetadata,
        destination: String,
        priority: Priority = .normal
    ) {
        self.id = UUID()
        self.type = type
        self.source = source
        self.destination = destination
        self.priority = priority
        self.attemptCount = 0
        self.lastError = nil
    }

    /// Returns a copy with the attempt counter incremented.
    public mutating func recordAttempt(error: Error? = nil) {
        attemptCount += 1
        lastError = error
    }
