import Foundation

/// Observable state emitted by the sync manager.
public struct SyncState: Sendable {
    public let phase: Phase
    public let totalOperations: Int
    public let completedOperations: Int
    public let failedOperations: Int
    public let bytesTransferred: UInt64
    public let totalBytes: UInt64
    public let currentFile: String?
    public let startTime: Date
    public let errors: [SyncError]

    public enum Phase: String, Sendable {
        case idle
        case scanning
        case comparing
        case syncing
        case retrying
        case completed
        case failed
        case cancelled
    }

    public var progress: Double {
        guard totalOperations > 0 else { return 0 }
        return Double(completedOperations) / Double(totalOperations)
    }

    public var elapsedTime: TimeInterval {
        Date().timeIntervalSince(startTime)
    }

    public static var idle: SyncState {
        SyncState(
            phase: .idle,
            totalOperations: 0,
            completedOperations: 0,
            failedOperations: 0,
            bytesTransferred: 0,
            totalBytes: 0,
            currentFile: nil,
            startTime: .now,
            errors: []
        )
    }
