// MARK: - RetryPolicy.swift

import Foundation

/// Configurable retry strategy with exponential backoff and jitter.
public struct RetryPolicy: Sendable {
    public let maxAttempts: Int
    public let baseDelay: TimeInterval
    public let maxDelay: TimeInterval
    public let backoffMultiplier: Double
    public let jitterRange: ClosedRange<Double>
    public let retryableCheck: @Sendable (Error) -> Bool

    public init(
        maxAttempts: Int = 5,
        baseDelay: TimeInterval = 1.0,
        maxDelay: TimeInterval = 60.0,
        backoffMultiplier: Double = 2.0,
        jitterRange: ClosedRange<Double> = 0.8...1.2,
        retryableCheck: @escaping @Sendable (Error) -> Bool = { error in
            (error as? SyncError)?.isRetryable ?? true
        }
    ) {
        self.maxAttempts = maxAttempts
        self.baseDelay = baseDelay
        self.maxDelay = maxDelay
        self.backoffMultiplier = backoffMultiplier
        self.jitterRange = jitterRange
        self.retryableCheck = retryableCheck
    }

    /// Computes the delay before a given attempt number (0-indexed).
    public func delay(forAttempt attempt: Int) -> TimeInterval {
        let exponential = baseDelay * pow(backoffMultiplier, Double(attempt))
        let capped = min(exponential, maxDelay)
        let jitter = Double.random(in: jitterRange)
        return capped * jitter
    }

    /// Whether the error should trigger a retry.
    public func shouldRetry(error: Error, attempt: Int) -> Bool {
        attempt < maxAttempts && retryableCheck(error)
    }

    public static let `default` = RetryPolicy()

    public static let aggressive = RetryPolicy(
        maxAttempts: 10,
        baseDelay: 0.5,
        maxDelay: 120.0,
        backoffMultiplier: 1.5
    )

    public static let conservative = RetryPolicy(
        maxAttempts: 3,
        baseDelay: 2.0,
        maxDelay: 30.0,
        backoffMultiplier: 3.0
    )
}
