import Foundation

/// Persisted record of successfully synced files, enabling incremental sync.
public actor SyncManifest {
    private var entries: [String: Entry]
    private let storageURL: URL

    public struct Entry: Codable, Sendable {
        let relativePath: String
        let checksum: String
        let size: UInt64
        let syncedDate: Date
        let sourceModified: Date
    }

    public init(storageURL: URL) {
        self.storageURL = storageURL
        self.entries = [:]
    }

    // MARK: - CRUD

    public func entry(for relativePath: String) -> Entry? {
        entries[relativePath]
    }

    public func update(_ entry: Entry) {
        entries[entry.relativePath] = entry
    }

    public func remove(relativePath: String) {
        entries.removeValue(forKey: relativePath)
    }

    public func allEntries() -> [String: Entry] {
        entries
    }

    // MARK: - Persistence

    public func load() throws {
        let url = storageURL.appendingPathComponent(".syncmanifest.json")
        guard FileManager.default.fileExists(atPath: url.path) else { return }

        let data = try Data(contentsOf: url)
        entries = try JSONDecoder().decode([String: Entry].self, from: data)
    }

    public func save() throws {
        let url = storageURL.appendingPathComponent(".syncmanifest.json")
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        let data = try encoder.encode(entries)
        try data.write(to: url, options: .atomic)
    }
}
