/// Abstraction over actual I/O so the sync engine remains testable.
public protocol FileTransportProtocol: Sendable {
    /// Copy file with chunked streaming and progress callbacks.
    func transferFile(
        from source: URL,
        to destination: URL,
        chunkSize: Int,
        progress: @Sendable (UInt64) -> Void
    ) async throws

    func deleteFile(at url: URL) async throws
    func createDirectory(at url: URL) async throws
    func fileExists(at url: URL) async -> Bool
    func availableSpace(at url: URL) async throws -> UInt64
}

/// Default local-filesystem transport.
public struct LocalFileTransport: FileTransportProtocol {
    private let fileManager = FileManager.default

    public init() {}

