// csv_reader.cpp
#include "csv_reader.h"
#include <algorithm>
#include <iostream>

// ─── CSVRecord ───────────────────────────────────────────────

CSVRecord::CSVRecord(const std::vector<std::string>& values,
                     const std::shared_ptr<FieldMap>& header_map,
                     size_t line_number)
    : values_(values), header_map_(header_map), line_number_(line_number) {}

const std::string& CSVRecord::operator[](const std::string& column) const {
    auto it = header_map_->find(column);
    if (it == header_map_->end()) {
        throw std::out_of_range("Column not found: " + column);
    }
    if (it->second >= values_.size()) {
        throw std::out_of_range(
            "Column index " + std::to_string(it->second) +
            " out of range at line " + std::to_string(line_number_));
    }
    return values_[it->second];
}

const std::string& CSVRecord::operator[](size_t index) const {
    if (index >= values_.size()) {
        throw std::out_of_range(
            "Index " + std::to_string(index) +
            " out of range at line " + std::to_string(line_number_));
    }
    return values_[index];
}

std::optional<std::string> CSVRecord::get(const std::string& column) const {
    auto it = header_map_->find(column);
    if (it == header_map_->end() || it->second >= values_.size()) {
        return std::nullopt;
    }
    return values_[it->second];
}

int CSVRecord::get_int(const std::string& column) const {
    return std::stoi((*this)[column]);
}

double CSVRecord::get_double(const std::string& column) const {
    return std::stod((*this)[column]);
}

long long CSVRecord::get_long(const std::string& column) const {
    return std::stoll((*this)[column]);
}

bool CSVRecord::get_bool(const std::string& column) const {
    std::string val = (*this)[column];
    std::transform(val.begin(), val.end(), val.begin(), ::tolower);
    return val == "true" || val == "1" || val == "yes";
}

bool CSVRecord::has(const std::string& column) const {
    return header_map_->find(column) != header_map_->end();
}

bool CSVRecord::empty(const std::string& column) const {
    auto val = get(column);
    return !val.has_value() || val->empty();
}


