bool CSVReader::load(std::istream& stream) {
    std::string content(
        (std::istreambuf_iterator<char>(stream)),
         std::istreambuf_iterator<char>());
    return parse(content);
}

bool CSVReader::parse(const std::string& content) {
    error_.clear();
    headers_.clear();
    records_.clear();
    header_map_->clear();

    if (content.empty()) {
        error_ = "Empty input";
        return false;
    }

    // Split into lines, respecting quoted fields that span multiple lines
    std::vector<std::string> lines;
    std::string current_line;
    bool in_quotes = false;

    for (size_t i = 0; i < content.size(); ++i) {
        char c = content[i];

        if (c == config_.quote_char) {
            // Check for escaped quote ("")
            if (in_quotes && i + 1 < content.size()
                && content[i + 1] == config_.quote_char) {
                current_line += c;
                current_line += content[++i];
                continue;
            }
            in_quotes = !in_quotes;
        }

        if (!in_quotes && (c == '\n' || c == '\r')) {
            // Handle \r\n
            if (c == '\r' && i + 1 < content.size() && content[i + 1] == '\n') {
                ++i;
            }
            if (!current_line.empty() || !config_.skip_empty_rows) {
                lines.push_back(current_line);
            }
            current_line.clear();
        } else {
            current_line += c;
        }
    }

    // Last line (no trailing newline)
    if (!current_line.empty()) {
        lines.push_back(current_line);
    }

    return process_rows(lines);
}

bool CSVReader::process_rows(const std::vector<std::string>& lines) {
    if (lines.empty()) {
        error_ = "No data rows found";
        return false;
    }

    size_t data_start = 0;

    // Parse header row
    if (config_.has_header) {
        headers_ = parse_line(lines[0]);
        for (size_t i = 0; i < headers_.size(); ++i) {
            (*header_map_)[headers_[i]] = i;
        }
        data_start = 1;
    } else {
        // Generate numeric column names
        auto first = parse_line(lines[0]);
        for (size_t i = 0; i < first.size(); ++i) {
            std::string name = "col_" + std::to_string(i);
            headers_.push_back(name);
            (*header_map_)[name] = i;
        }
    }

    // Parse data rows
    for (size_t i = data_start; i < lines.size(); ++i) {
        auto values = parse_line(lines[i]);

        if (config_.skip_empty_rows && values.empty()) {
            continue;
        }

        // Pad short rows with empty strings
        while (values.size() < headers_.size()) {
            values.emplace_back("");
        }

        // Line number is 1-based (accounting for header)
        records_.emplace_back(values, header_map_, i + 1);
    }

    return true;
}

std::vector<std::string> CSVReader::parse_line(const std::string& line) {
    std::vector<std::string> fields;
    std::string current_field;
    bool in_quotes = false;

    for (size_t i = 0; i < line.size(); ++i) {
        char c = line[i];

        if (in_quotes) {
            if (c == config_.quote_char) {
                // Escaped quote ""
                if (i + 1 < line.size() && line[i + 1] == config_.quote_char) {
                    current_field += config_.quote_char;
                    ++i;
                } else {
                    in_quotes = false;
                }
            } else {
                current_field += c;
            }
        } else {
            if (c == config_.quote_char) {
                in_quotes = true;
            } else if (c == config_.delimiter) {
                fields.push_back(
                    config_.trim_whitespace ? trim(current_field) : current_field);
                current_field.clear();
            } else {
                current_field += c;
            }
        }
    }

    // Last field
    fields.push_back(
        config_.trim_whitespace ? trim(current_field) : current_field);

    return fields;
}

std::string CSVReader::trim(const std::string& s) const {
    auto start = s.find_first_not_of(" \t");
    if (start == std::string::npos) return "";
    auto end = s.find_last_not_of(" \t");
    return s.substr(start, end - start + 1);
}
