<?php
// src/Config/ConfigToken.php

declare(strict_types=1);

namespace App\Config;

/**
 * Represents a parsed token from the configuration file.
 */
final class ConfigToken
{
    public const TYPE_SECTION   = 'section';
    public const TYPE_KEY_VALUE = 'key_value';
    public const TYPE_COMMENT   = 'comment';
    public const TYPE_BLANK     = 'blank';

    public function __construct(
        public readonly string $type,
        public readonly int    $line,
        public readonly string $rawContent,
        public readonly ?string $section = null,
        public readonly ?string $key = null,
        public readonly mixed   $value = null,
    ) {}

    public function __toString(): string
    {
        return match ($this->type) {
            self::TYPE_SECTION   => "[Section: {$this->section}]",
            self::TYPE_KEY_VALUE => "{$this->key} = " . var_export($this->value, true),
            self::TYPE_COMMENT   => "# comment",
            self::TYPE_BLANK     => "(blank)",
        };
    }
}
