// src/Config/ConfigException.php

declare(strict_types=1);

namespace App\Config;

class ConfigException extends \RuntimeException
{
    public static function fileNotFound(string $path): self
    {
        return new self("Configuration file not found: {$path}");
    }

    public static function parseFailed(int $line, string $content, string $reason): self
    {
        return new self(
            "Parse error on line {$line}: {$reason}\n  Content: \"{$content}\""
        );
    }

    public static function missingKey(string $section, string $key): self
    {
        return new self("Missing required key '{$key}' in section [{$section}]");
    }

    public static function invalidValue(string $key, string $expected, mixed $actual): self
    {
        $actualStr = var_export($actual, true);
        return new self("Invalid value for '{$key}': expected {$expected}, got {$actualStr}");
    }
