### ConfigParser

```php
<?php
// src/Config/ConfigParser.php

declare(strict_types=1);

namespace App\Config;

/**
 * Parses INI-style configuration files with support for:
 *  - Sections and nested sections (dot notation)
 *  - Typed values (bool, int, float, string, arrays)
 *  - Comments and blank lines
 *  - Event-specific section prefixes like [event:name]
 *  - Metadata sub-keys via dot notation in keys
 */
class ConfigParser
{
    /** @var ConfigToken[] */
    private array $tokens = [];

    /** @var array<string, mixed> Flat section→key→value store */
    private array $sections = [];

    /** @var array<string, array<string, mixed>> Parsed event definitions */
    private array $events = [];

    /** Regex patterns */
    private const PATTERN_SECTION   = '/^\[([a-zA-Z0-9_.:]+)\]\s*$/';
    private const PATTERN_KEY_VALUE = '/^([a-zA-Z0-9_.]+)\s*=\s*(.+)$/';
    private const PATTERN_COMMENT   = '/^\s*[#;]/';
    private const PATTERN_BLANK     = '/^\s*$/';

    // ─── Public API ──────────────────────────────────────

    /**
     * Parse a configuration file and return structured data.
     *
     * @throws ConfigException
     */
    public function parseFile(string $filePath): self
    {
        if (!file_exists($filePath) || !is_readable($filePath)) {
            throw ConfigException::fileNotFound($filePath);
        }

        $lines = file($filePath, FILE_IGNORE_NEW_LINES);
        if ($lines === false) {
            throw ConfigException::fileNotFound($filePath);
        }

        $this->tokens   = [];
        $this->sections = [];
        $this->events   = [];

        $this->tokenize($lines);
        $this->buildSections();
        $this->extractEvents();

        return $this;
    }

    /**
     * Parse a config string directly (useful for testing).
     */
    public function parseString(string $content): self
    {
        $lines = explode("\n", $content);

        $this->tokens   = [];
        $this->sections = [];
        $this->events   = [];

        $this->tokenize($lines);
        $this->buildSections();
        $this->extractEvents();

        return $this;
    }

    /**
     * Get a value using dot notation: "app.name", "logging.level", etc.
     */
    public function get(string $path, mixed $default = null): mixed
    {
        $parts   = explode('.', $path, 2);
        $section = $parts[0];
        $key     = $parts[1] ?? null;

        if ($key === null) {
            return $this->sections[$section] ?? $default;
        }

        return $this->sections[$section][$key] ?? $default;
    }

    /**
     * Get a typed boolean value.
     *
     * @throws ConfigException
     */
    public function getBool(string $path, ?bool $default = null): bool
    {
        $value = $this->get($path, $default);

        if (is_bool($value)) {
            return $value;
        }

        if ($default !== null) {
            return $default;
        }

        throw ConfigException::invalidValue($path, 'boolean', $value);
    }

    /**
     * Get a typed integer value.
     *
     * @throws ConfigException
     */
    public function getInt(string $path, ?int $default = null): int
    {
        $value = $this->get($path, $default);

        if (is_int($value)) {
            return $value;
        }

        if ($default !== null) {
            return $default;
        }

        throw ConfigException::invalidValue($path, 'integer', $value);
    }

    /**
     * Get a typed string value.
     */
    public function getString(string $path, ?string $default = null): string
    {
        $value = $this->get($path, $default);
        return is_string($value) ? $value : ($default ?? (string) $value);
    }

    /**
     * Get all parsed event definitions.
     *
     * @return array<string, array<string, mixed>>
     */
    public function getEvents(): array
    {
        return $this->events;
    }

    /**
     * Get a specific event definition.
     */
    public function getEvent(string $eventName): ?array
    {
        return $this->events[$eventName] ?? null;
    }

    /**
     * Get only enabled events, sorted by priority descending.
     *
     * @return array<string, array<string, mixed>>
     */
    public function getEnabledEvents(): array
    {
        $enabled = array_filter(
            $this->events,
            fn(array $def) => ($def['enabled'] ?? false) === true
        );

        uasort($enabled, fn(array $a, array $b) =>
            ($b['priority'] ?? 0) <=> ($a['priority'] ?? 0)
        );

        return $enabled;
    }

    /**
     * Get all parsed sections.
     *
     * @return array<string, mixed>
     */
    public function getAllSections(): array
    {
        return $this->sections;
    }

    /**
     * @return ConfigToken[]
     */
    public function getTokens(): array
    {
        return $this->tokens;
    }

    // ─── Tokenizer ───────────────────────────────────────

    /**
     * Convert raw lines into ConfigToken objects.
     *
     * @param string[] $lines
     * @throws ConfigException
     */
    private function tokenize(array $lines): void
    {
        foreach ($lines as $index => $rawLine) {
            $lineNum = $index + 1;
            $line    = trim($rawLine);

            // Blank line
            if (preg_match(self::PATTERN_BLANK, $line)) {
                $this->tokens[] = new ConfigToken(
                    type: ConfigToken::TYPE_BLANK,
                    line: $lineNum,
                    rawContent: $rawLine,
                );
                continue;
            }

            // Comment
            if (preg_match(self::PATTERN_COMMENT, $line)) {
                $this->tokens[] = new ConfigToken(
                    type: ConfigToken::TYPE_COMMENT,
                    line: $lineNum,
                    rawContent: $rawLine,
                );
                continue;
            }

            // Section header: [section] or [event:user.login]
            if (preg_match(self::PATTERN_SECTION, $line, $matches)) {
                $this->tokens[] = new ConfigToken(
                    type: ConfigToken::TYPE_SECTION,
                    line: $lineNum,
                    rawContent: $rawLine,
                    section: $matches[1],
                );
                continue;
            }

            // Key = Value
            if (preg_match(self::PATTERN_KEY_VALUE, $line, $matches)) {
                $key      = trim($matches[1]);
                $rawValue = $this->stripInlineComment(trim($matches[2]));
                $value    = $this->castValue($rawValue);

                $this->tokens[] = new ConfigToken(
                    type: ConfigToken::TYPE_KEY_VALUE,
                    line: $lineNum,
                    rawContent: $rawLine,
                    key: $key,
                    value: $value,
                );
                continue;
            }

            // Unrecognized line
            throw ConfigException::parseFailed(
                $lineNum,
                $line,
                'Unrecognized syntax'
            );
        }
    }

    // ─── Section Builder ─────────────────────────────────

    /**
     * Organize tokens into section→key→value structure.
     */
    private function buildSections(): void
    {
        $currentSection = '_global';

        foreach ($this->tokens as $token) {
            if ($token->type === ConfigToken::TYPE_SECTION) {
                $currentSection = $token->section;

                if (!isset($this->sections[$currentSection])) {
                    $this->sections[$currentSection] = [];
                }
                continue;
            }

            if ($token->type === ConfigToken::TYPE_KEY_VALUE) {
                // Support dot-notation keys → nested arrays
                $this->setNestedValue(
                    $this->sections[$currentSection],
                    $token->key,
                    $token->value
                );
            }
        }
    }

    // ─── Event Extractor ─────────────────────────────────

    /**
     * Pull out sections prefixed with "event:" into structured event definitions.
     */
    private function extractEvents(): void
    {
        foreach ($this->sections as $sectionName => $values) {
            if (!str_starts_with($sectionName, 'event:')) {
                continue;
            }

            $eventName = substr($sectionName, 6); // strip "event:"

            $this->events[$eventName] = [
                'name'             => $eventName,
                'enabled'          => $values['enabled'] ?? false,
                'handlers'         => $this->parseList($values['handlers'] ?? ''),
                'priority'         => (int) ($values['priority'] ?? 0),
                'throttle_seconds' => (int) ($values['throttle_seconds'] ?? 0),
                'metadata'         => $values['metadata'] ?? [],
            ];
        }
    }

    // ─── Value Helpers ───────────────────────────────────

    /**
     * Strip inline comments from a value string.
     * e.g., '"hello" # this is a comment' → '"hello"'
     */
    private function stripInlineComment(string $raw): string
    {
        // Don't strip # inside quoted strings
        if (preg_match('/^".*"$/', $raw) || preg_match("/^'.*'$/", $raw)) {
            return $raw;
        }

        // Find # or ; that's not inside quotes
        $inQuote = false;
        $quoteChar = '';

        for ($i = 0; $i < strlen($raw); $i++) {
            $char = $raw[$i];

            if (!$inQuote && ($char === '"' || $char === "'")) {
                $inQuote = true;
                $quoteChar = $char;
                continue;
            }

            if ($inQuote && $char === $quoteChar) {
                $inQuote = false;
                continue;
            }

            if (!$inQuote && ($char === '#' || $char === ';')) {
                return trim(substr($raw, 0, $i));
            }
        }

        return $raw;
    }

    /**
     * Cast a raw string value to an appropriate PHP type.
     */
    private function castValue(string $raw): mixed
    {
        // Quoted string → strip quotes
