## `src/store.js` — Persistence Layer

```js
'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');

const DATA_DIR = path.join(os.homedir(), '.taskr');
const TASKS_FILE = path.join(DATA_DIR, 'tasks.json');
const LOGS_DIR = path.join(DATA_DIR, 'logs');
const PID_FILE = path.join(DATA_DIR, 'scheduler.pid');

class Store {
  constructor() {
    fs.mkdirSync(DATA_DIR, { recursive: true });
    fs.mkdirSync(LOGS_DIR, { recursive: true });
  }

  // ── Tasks ──────────────────────────────

  getTasks() {
    try {
      return JSON.parse(fs.readFileSync(TASKS_FILE, 'utf8'));
    } catch {
      return [];
    }
  }

  _save(tasks) {
    // atomic write: write tmp then rename
    const tmp = TASKS_FILE + '~';
    fs.writeFileSync(tmp, JSON.stringify(tasks, null, 2));
    fs.renameSync(tmp, TASKS_FILE);
  }

  addTask({ name, command, schedule, workingDir, timeout }) {
    const tasks = this.getTasks();

    if (tasks.some((t) => t.name === name)) {
      throw new Error(`Task "${name}" already exists`);
    }

    const task = {
      id: crypto.randomBytes(4).toString('hex'),
      name,
      command,
      schedule,
      workingDir: path.resolve(workingDir || '.'),
      timeout: timeout || 0,
      enabled: true,
      createdAt: new Date().toISOString(),
      lastRun: null,
      lastStatus: null,
      runCount: 0,
    };

    tasks.push(task);
    this._save(tasks);
    return task;
  }

  findTask(ref) {
    return (
      this.getTasks().find(
        (t) => t.id === ref || t.id.startsWith(ref) || t.name === ref
      ) || null
    );
  }

  updateTask(id, updates) {
    const tasks = this.getTasks();
    const i = tasks.findIndex((t) => t.id === id);
    if (i < 0) throw new Error(`Task not found: ${id}`);
    Object.assign(tasks[i], updates);
    this._save(tasks);
    return tasks[i];
  }

  removeTask(ref) {
    const task = this.findTask(ref);
    if (!task) throw new Error(`Task not found: ${ref}`);
    this._save(this.getTasks().filter((t) => t.id !== task.id));
    try {
      fs.unlinkSync(path.join(LOGS_DIR, `${task.id}.jsonl`));
    } catch {}
    return task;
  }

  // ── Execution Logs ─────────────────────

  appendLog(taskId, entry) {
    const file = path.join(LOGS_DIR, `${taskId}.jsonl`);
    fs.appendFileSync(file, JSON.stringify(entry) + '\n');
  }

  getLogs(taskId, limit = 20) {
    try {
      const file = path.join(LOGS_DIR, `${taskId}.jsonl`);
      const lines = fs.readFileSync(file, 'utf8').trim().split('\n').filter(Boolean);
      return lines.slice(-limit).map(JSON.parse).reverse();
    } catch {
      return [];
    }
  }

  // ── Scheduler PID ──────────────────────

  getSchedulerPid() {
    try {
      const pid = parseInt(fs.readFileSync(PID_FILE, 'utf8'), 10);
      process.kill(pid, 0); // throws if process is dead
      return pid;
    } catch {
      try { fs.unlinkSync(PID_FILE); } catch {}
      return null;
    }
  }

  writeSchedulerPid() {
    fs.writeFileSync(PID_FILE, String(process.pid));
  }

  clearSchedulerPid() {
    try { fs.unlinkSync(PID_FILE); } catch {}
  }
}

module.exports = { Store, DATA_DIR };
```

## `src/scheduler.js` — Scheduling Engine

```js
'use strict';

const cron = require('node-cron');
const { exec } = require('child_process');
const { Store } = require('./store');

class Scheduler {
  constructor(hooks = {}) {
    this.store = new Store();
    this.jobs = new Map();    // taskId → cron job
    this.running = new Set(); // taskIds currently executing
    this.hooks = hooks;
    this._timer = null;
  }

  start() {
    const tasks = this.store.getTasks().filter((t) => t.enabled);

    for (const task of tasks) {
      this._schedule(task);
    }

    this.store.writeSchedulerPid();

    // re-sync every 10s so CLI changes (add/remove/enable) take effect
    this._timer = setInterval(() => this._sync(), 10_000);

    return tasks.length;
  }

  stop() {
    for (const job of this.jobs.values()) job.stop();
    this.jobs.clear();
    clearInterval(this._timer);
    this.store.clearSchedulerPid();
  }

  _schedule(task) {
    if (this.jobs.has(task.id)) return;
    const job = cron.schedule(task.schedule, () => this._execute(task.id));
    this.jobs.set(task.id, job);
  }

  _execute(taskId) {
    // re-read for freshest data
    const task = this.store.findTask(taskId);
    if (!task || !task.enabled) return;

    // skip if previous run hasn't finished
    if (this.running.has(taskId)) return;

    this.running.add(taskId);
    const t0 = Date.now();

    if (this.hooks.onStart) this.hooks.onStart(task);

    exec(
      task.command,
      {
        cwd: task.workingDir,
        timeout: task.timeout ? task.timeout * 1000 : undefined,
        maxBuffer: 5 * 1024 * 1024,
      },
      (err, stdout, stderr) => {
        this.running.delete(taskId);

        const duration = Date.now() - t0;
        const status = err ? 'failed' : 'success';

        const entry = {
          timestamp: new Date().toISOString(),
          status,
          duration,
          exitCode: err ? (typeof err.code === 'number' ? err.code : 1) : 0,
          stdout: (stdout || '').slice(-5000),
          stderr: (stderr || '').slice(-5000),
          error: err ? err.message : null,
        };

        this.store.appendLog(taskId, entry);

        try {
          const fresh = this.store.findTask(taskId);
          this.store.updateTask(taskId, {
            lastRun: entry.timestamp,
            lastStatus: status,
            runCount: (fresh?.runCount || 0) + 1,
          });
        } catch {}

        if (this.hooks.onEnd) this.hooks.onEnd(task, entry);
      }
    );
  }

  // pick up tasks added/removed/toggled via the CLI while scheduler runs
  _sync() {
    const tasks = this.store.getTasks();
    const byId = new Map(tasks.map((t) => [t.id, t]));

    for (const [id, job] of this.jobs) {
      if (!byId.has(id) || !byId.get(id).enabled) {
        job.stop();
        this.jobs.delete(id);
      }
    }

    for (const t of tasks) {
      if (t.enabled && !this.jobs.has(t.id)) {
        this._schedule(t);
      }
    }
  }
}

module.exports = { Scheduler };
```

