```kotlin
package filesync.config

import java.nio.file.Path
import java.time.Duration

/**
 * Immutable configuration for file synchronization.
 */
data class SyncConfig(
    val sourcePath: Path,
    val destinationPath: Path,
    val retryPolicy: RetryPolicy = RetryPolicy(),
    val deleteOrphaned: Boolean = false,
    val dryRun: Boolean = false,
    val parallelism: Int = Runtime.getRuntime().availableProcessors().coerceIn(1, 8),
    val bufferSize: Int = 8192,
    val checksumAlgorithm: String = "SHA-256",
    val excludePatterns: List<Regex> = emptyList(),
    val includeHidden: Boolean = false,
    val maxFileSizeBytes: Long = Long.MAX_VALUE
) {
    init {
        require(parallelism > 0) { "Parallelism must be positive" }
        require(bufferSize > 0) { "Buffer size must be positive" }
        require(maxFileSizeBytes > 0) { "Max file size must be positive" }
    }
}

/**
 * Retry policy with exponential backoff and jitter.
 */
data class RetryPolicy(
    val maxAttempts: Int = 3,
    val initialDelay: Duration = Duration.ofMillis(500),
    val maxDelay: Duration = Duration.ofSeconds(30),
    val backoffMultiplier: Double = 2.0,
    val jitterFactor: Double = 0.1,
    val retryableExceptions: Set<Class<out Throwable>> = setOf(
        java.io.IOException::class.java,
        java.nio.file.FileSystemException::class.java,
        java.net.SocketException::class.java
    )
) {
    init {
        require(maxAttempts >= 1) { "Max attempts must be at least 1" }
        require(backoffMultiplier > 0) { "Backoff multiplier must be positive" }
        require(jitterFactor in 0.0..1.0) { "Jitter factor must be between 0 and 1" }
    }

    fun isRetryable(throwable: Throwable): Boolean =
        retryableExceptions.any { it.isInstance(throwable) }

    fun delayForAttempt(attempt: Int): Duration {
        val baseDelay = initialDelay.toMillis() * Math.pow(backoffMultiplier, (attempt - 1).toDouble())
        val clampedDelay = baseDelay.toLong().coerceAtMost(maxDelay.toMillis())
        val jitter = (clampedDelay * jitterFactor * (Math.random() * 2 - 1)).toLong()
        return Duration.ofMillis((clampedDelay + jitter).coerceAtLeast(0))
    }
}
