package filesync.model

import java.time.Duration
import java.time.Instant

/**
 * Aggregated result of a complete sync run.
 */
data class SyncResult(
    val startedAt: Instant,
    val completedAt: Instant,
    val outcomes: List<OperationOutcome>,
    val dryRun: Boolean
) {
    val duration: Duration get() = Duration.between(startedAt, completedAt)

    val succeeded: List<OperationOutcome>
        get() = outcomes.filter { it.status == OperationOutcome.Status.SUCCESS }

    val failed: List<OperationOutcome>
        get() = outcomes.filter { it.status == OperationOutcome.Status.FAILED }

    val skipped: List<OperationOutcome>
        get() = outcomes.filter { it.status == OperationOutcome.Status.SKIPPED }

    val totalBytesSynced: Long
        get() = succeeded.sumOf { it.operation.sizeBytes }

    val isFullySuccessful: Boolean
        get() = failed.isEmpty()

    fun summary(): String = buildString {
        appendLine("=== Sync Summary ===")
        if (dryRun) appendLine("[DRY RUN]")
        appendLine("Duration       : ${duration.toMillis()} ms")
        appendLine("Total ops      : ${outcomes.size}")
        appendLine("Succeeded      : ${succeeded.size}")
        appendLine("Failed         : ${failed.size}")
        appendLine("Skipped        : ${skipped.size}")
        appendLine("Bytes synced   : $totalBytesSynced")
        if (failed.isNotEmpty()) {
            appendLine("--- Failures ---")
            failed.forEach { outcome ->
                appendLine("  ${outcome.operation.relativePath}: ${outcome.error?.message}")
            }
        }
    }
}
