## checksum/ChecksumCalculator.kt

```kotlin
package filesync.checksum

import java.io.InputStream
import java.nio.file.Files
import java.nio.file.Path
import java.security.MessageDigest

/**
 * Thread-safe checksum calculator using configurable algorithms.
 */
class ChecksumCalculator(
    private val algorithm: String = "SHA-256",
    private val bufferSize: Int = 8192
) {
    /**
     * Computes the hex-encoded checksum of a file.
     * Uses streaming to handle large files without loading them fully into memory.
     */
    fun compute(path: Path): String {
        val digest = MessageDigest.getInstance(algorithm)
        val buffer = ByteArray(bufferSize)

        Files.newInputStream(path).buffered(bufferSize).use { input: InputStream ->
            var bytesRead: Int
            while (input.read(buffer).also { bytesRead = it } != -1) {
                digest.update(buffer, 0, bytesRead)
            }
        }

        return digest.digest().joinToString("") { "%02x".format(it) }
    }

    /**
     * Returns true if two files have identical checksums.
     */
    fun areEqual(file1: Path, file2: Path): Boolean =
        compute(file1) == compute(file2)
}
