## engine/FileComparator.kt

```kotlin
package filesync.engine

import filesync.checksum.ChecksumCalculator
import filesync.config.SyncConfig
import filesync.model.FileMetadata
import filesync.model.SyncOperation
import filesync.model.SyncOperation.CopyReason
import java.nio.file.Files
import java.nio.file.Path
import java.time.Instant
import kotlin.io.path.*

/**
 * Compares source and destination trees to determine required sync operations.
 */
class FileComparator(
    private val config: SyncConfig,
    private val checksumCalculator: ChecksumCalculator
) {
    /**
     * Scans both trees and returns the list of operations needed to synchronize.
     */
    fun computeOperations(): List<SyncOperation> {
        val sourceFiles = scanTree(config.sourcePath)
        val destFiles = scanTree(config.destinationPath)

        val sourceMap = sourceFiles.associateBy { it.relativePath }
        val destMap = destFiles.associateBy { it.relativePath }

        val operations = mutableListOf<SyncOperation>()

        // --- Directories that must be created first ---
        sourceMap.values
            .filter { it.isDirectory }
            .filterNot { destMap.containsKey(it.relativePath) }
            .sortedBy { it.relativePath.nameCount } // parent dirs first
            .forEach { operations += SyncOperation.CreateDirectory(it.relativePath) }

        // --- Files to copy (new or changed) ---
        sourceMap.values
            .filterNot { it.isDirectory }
            .forEach { srcMeta ->
                val destMeta = destMap[srcMeta.relativePath]
                val reason = determineCopyReason(srcMeta, destMeta)
                if (reason != null) {
                    operations += SyncOperation.Copy(
                        relativePath = srcMeta.relativePath,
                        sizeBytes = srcMeta.sizeBytes,
                        reason = reason
                    )
                }
            }

        // --- Orphaned files to delete ---
        if (config.deleteOrphaned) {
            destMap.values
                .filterNot { sourceMap.containsKey(it.relativePath) }
                .sortedByDescending { it.relativePath.nameCount } // deepest first
                .forEach { operations += SyncOperation.Delete(it.relativePath, it.sizeBytes) }
        }

        return operations
    }

    private fun determineCopyReason(
        source: FileMetadata,
        dest: FileMetadata?
    ): CopyReason? {
        if (dest == null) return CopyReason.NEW_FILE
        if (source.sizeBytes != dest.sizeBytes) return CopyReason.SIZE_CHANGED
        if (source.lastModified.isAfter(dest.lastModified)) {
            // Confirm with checksum to avoid unnecessary copies
            val srcPath = config.sourcePath.resolve(source.relativePath)
            val dstPath = config.destinationPath.resolve(source.relativePath)
            return if (!checksumCalculator.areEqual(srcPath, dstPath)) {
                CopyReason.CHECKSUM_MISMATCH
            } else {
                null // timestamps differ but content is the same
            }
        }
        return null
    }

    private fun scanTree(root: Path): List<FileMetadata> {
        if (!root.exists()) return emptyList()

        return Files.walk(root).use { stream ->
            stream
                .filter { it != root }
                .filter { config.includeHidden || !it.isHidden() }
                .filter { path ->
                    val rel = root.relativize(path).toString()
                    config.excludePatterns.none { it.containsMatchIn(rel) }
                }
                .filter { Files.size(it) <= config.maxFileSizeBytes || it.isDirectory() }
                .map { path ->
                    FileMetadata(
                        relativePath = root.relativize(path),
                        sizeBytes = if (path.isDirectory()) 0L else Files.size(path),
                        lastModified = Files.getLastModifiedTime(path).toInstant(),
                        isDirectory = path.isDirectory()
                    )
                }
                .toList()
        }
    }

    private fun Path.isHidden(): Boolean =
        fileName?.toString()?.startsWith(".") == true
}
