## retry/RetryExecutor.kt

```kotlin
package filesync.retry

import filesync.config.RetryPolicy
import filesync.logging.SyncLogger
import kotlinx.coroutines.delay

/**
 * Executes a suspending block with retry logic, exponential backoff, and jitter.
 */
class RetryExecutor(
    private val policy: RetryPolicy,
    private val logger: SyncLogger
) {
    /**
     * Executes [block] up to [RetryPolicy.maxAttempts] times.
     *
     * @param operationName human-readable label for log messages
     * @param block the suspending action to retry
     * @return [RetryOutcome.Success] or [RetryOutcome.Failure]
     */
    suspend fun <T> execute(
        operationName: String,
        block: suspend (attempt: Int) -> T
    ): RetryOutcome<T> {
        var lastException: Throwable? = null

        for (attempt in 1..policy.maxAttempts) {
            try {
                val result = block(attempt)
                if (attempt > 1) {
                    logger.info("$operationName succeeded on attempt $attempt")
                }
                return RetryOutcome.Success(result, attempt)
            } catch (e: Throwable) {
                lastException = e

                if (!policy.isRetryable(e)) {
                    logger.error("$operationName failed with non-retryable error: ${e.message}")
                    return RetryOutcome.Failure(e, attempt)
                }

                if (attempt < policy.maxAttempts) {
                    val delayDuration = policy.delayForAttempt(attempt)
                    logger.warn(
                        "$operationName failed attempt $attempt/${policy.maxAttempts}: " +
                                "${e.message}. Retrying in ${delayDuration.toMillis()} ms..."
                    )
                    delay(delayDuration.toMillis())
                } else {
                    logger.error(
                        "$operationName exhausted all ${policy.maxAttempts} attempts. " +
                                "Last error: ${e.message}"
                    )
                }
            }
        }

        return RetryOutcome.Failure(
            lastException ?: IllegalStateException("Retry loop exited unexpectedly"),
            policy.maxAttempts
        )
    }
}

/**
 * Outcome of a retried operation.
 */
sealed class RetryOutcome<out T> {
    abstract val attempts: Int

    data class Success<T>(val value: T, override val attempts: Int) : RetryOutcome<T>()
    data class Failure(val error: Throwable, override val attempts: Int) : RetryOutcome<Nothing>()

    val isSuccess: Boolean get() = this is Success
}
