package filesync.logging

import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

/**
 * Structured logger that supports pluggable output.
 * Replace the default implementation with SLF4J / Logback in production.
 */
interface SyncLogger {
    fun debug(message: String)
    fun info(message: String)
    fun warn(message: String)
    fun error(message: String, throwable: Throwable? = null)
}

class ConsoleSyncLogger(
    private val minLevel: Level = Level.INFO
) : SyncLogger {

    enum class Level { DEBUG, INFO, WARN, ERROR }

    private val formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSS")

    override fun debug(message: String) = log(Level.DEBUG, message)
    override fun info(message: String) = log(Level.INFO, message)
    override fun warn(message: String) = log(Level.WARN, message)
    override fun error(message: String, throwable: Throwable?) {
        log(Level.ERROR, message)
        throwable?.printStackTrace(System.err)
    }

    private fun log(level: Level, message: String) {
        if (level.ordinal >= minLevel.ordinal) {
            val timestamp = LocalDateTime.now().format(formatter)
            val thread = Thread.currentThread().name
            println("$timestamp [$thread] ${level.name.padEnd(5)} - $message")
        }
    }
}
