package reportgen

// ── Core data model ──────────────────────────────────────────────
data class Record(val fields: Map<String, String>) {
    fun str(key: String): String = fields[key] ?: ""
    fun num(key: String): Double = fields[key]?.toDoubleOrNull() ?: 0.0
}

data class DataSet(
    val headers: List<String>,
    val records: List<Record>
)

// ── Report configuration ─────────────────────────────────────────
data class ReportConfig(
    val input: String,
    val output: String?          = null,
    val title: String?           = null,
    val reportType: ReportType   = ReportType.DETAIL,
    val outputFormat: OutputFormat = OutputFormat.TABLE,
    val columns: List<String>?   = null,
    val filters: List<Filter>    = emptyList(),
    val groupBy: String?         = null,
    val aggregations: List<Aggregation> = emptyList(),
    val sortBy: String?          = null,
    val sortDesc: Boolean        = false,
    val limit: Int?              = null,
)

enum class ReportType  { DETAIL, SUMMARY, GROUPED }
enum class OutputFormat { TABLE, CSV, HTML, JSON, MARKDOWN }

// ── Filtering ────────────────────────────────────────────────────
sealed interface Filter {
    val field: String
    fun matches(record: Record): Boolean

    data class Eq(override val field: String, val value: String) : Filter {
        override fun matches(record: Record) = record.str(field).equals(value, ignoreCase = true)
    }
    data class Neq(override val field: String, val value: String) : Filter {
        override fun matches(record: Record) = !record.str(field).equals(value, ignoreCase = true)
    }
    data class Gt(override val field: String, val threshold: Double) : Filter {
        override fun matches(record: Record) = record.num(field) > threshold
    }
    data class Lt(override val field: String, val threshold: Double) : Filter {
        override fun matches(record: Record) = record.num(field) < threshold
    }
    data class Gte(override val field: String, val threshold: Double) : Filter {
        override fun matches(record: Record) = record.num(field) >= threshold
    }
    data class Lte(override val field: String, val threshold: Double) : Filter {
        override fun matches(record: Record) = record.num(field) <= threshold
    }
    data class Contains(override val field: String, val substring: String) : Filter {
        override fun matches(record: Record) = record.str(field).contains(substring, ignoreCase = true)
    }
}

// ── Aggregation ──────────────────────────────────────────────────
enum class AggFunc { SUM, AVG, MIN, MAX, COUNT }

data class Aggregation(val field: String, val func: AggFunc) {
    fun compute(records: List<Record>): Double = when (func) {
        AggFunc.SUM   -> records.sumOf { it.num(field) }
        AggFunc.AVG   -> records.map { it.num(field) }.average().takeIf { !it.isNaN() } ?: 0.0
        AggFunc.MIN   -> records.minOfOrNull { it.num(field) } ?: 0.0
        AggFunc.MAX   -> records.maxOfOrNull { it.num(field) } ?: 0.0
        AggFunc.COUNT -> records.size.toDouble()
    }

    val label: String get() = "${func.name.lowercase()}($field)"
}

// ── Report output models ─────────────────────────────────────────
data class ReportResult(
    val title: String,
    val generated: String,         // ISO timestamp
    val headers: List<String>,
    val rows: List<List<String>>,
    val summary: Map<String, String> = emptyMap()
)
