// src/main/kotlin/reportgen/CliParser.kt
package reportgen

class CliParser(private val args: Array<String>) {

    fun parse(): ReportConfig {
        if (args.isEmpty() || hasFlag("-h", "--help")) {
            printUsage()
            throw SystemExitException(0)
        }

        val input = requireArg("-i", "--input") { "Input file is required (--input <file>)" }

        return ReportConfig(
            input        = input,
            output       = optArg("-o", "--output"),
            title        = optArg("--title"),
            reportType   = optArg("-t", "--type")?.let { parseEnum<ReportType>(it) } ?: ReportType.DETAIL,
            outputFormat = optArg("-f", "--format")?.let { parseEnum<OutputFormat>(it) } ?: OutputFormat.TABLE,
            columns      = optArg("-c", "--columns")?.split(",")?.map(String::trim),
            filters      = optAll("--filter").map(::parseFilter),
            groupBy      = optArg("-g", "--group-by"),
            aggregations = optAll("--agg").flatMap(::parseAggregations),
            sortBy       = optArg("-s", "--sort"),
            sortDesc     = hasFlag("--desc"),
            limit        = optArg("-l", "--limit")?.toIntOrNull(),
        )
    }

    // ── Argument helpers ─────────────────────────────────────────

    private fun hasFlag(vararg names: String): Boolean =
        names.any { it in args }

    private fun optArg(vararg names: String): String? {
        for (name in names) {
            val idx = args.indexOf(name)
            if (idx >= 0 && idx + 1 < args.size) return args[idx + 1]
        }
        return null
    }

    private fun requireArg(vararg names: String, errorMsg: () -> String): String =
        optArg(*names) ?: error(errorMsg())

    /** Collect all values for a repeated flag: --filter "x>1" --filter "y=foo" */
    private fun optAll(vararg names: String): List<String> = buildList {
        for (name in names) {
            var idx = args.indexOf(name)
            while (idx >= 0 && idx + 1 < args.size) {
                add(args[idx + 1])
                idx = args.indexOf(name, idx + 2) // kotlin extension not built in, manual
            }
        }
    }

    // manual indexOf from startIndex
    private fun Array<String>.indexOf(element: String, startIndex: Int): Int {
        for (i in startIndex until size) if (this[i] == element) return i
        return -1
    }

    // ── Expression parsers ───────────────────────────────────────

    private fun parseFilter(expr: String): Filter {
        val operators = listOf(">=", "<=", "!=", ">", "<", "~", "=")
        for (op in operators) {
            val parts = expr.split(op, limit = 2)
            if (parts.size == 2) {
                val (field, value) = parts.map(String::trim)
                return when (op) {
                    "="  -> Filter.Eq(field, value)
                    "!=" -> Filter.Neq(field, value)
                    ">"  -> Filter.Gt(field, value.toDouble())
                    "<"  -> Filter.Lt(field, value.toDouble())
                    ">=" -> Filter.Gte(field, value.toDouble())
                    "<=" -> Filter.Lte(field, value.toDouble())
                    "~"  -> Filter.Contains(field, value)
                    else -> error("Unknown operator in filter: $expr")
                }
            }
        }
        error("Invalid filter expression: $expr  (expected: field>value, field=value, field~substr)")
    }

    private fun parseAggregations(expr: String): List<Aggregation> =
        expr.split(",").map { token ->
            val (field, funcStr) = token.trim().split(":", limit = 2)
            Aggregation(field.trim(), parseEnum<AggFunc>(funcStr.trim()))
        }

    private inline fun <reified T : Enum<T>> parseEnum(value: String): T =
        enumValues<T>().find { it.name.equals(value, ignoreCase = true) }
            ?: error("Invalid value '$value'. Expected: ${enumValues<T>().joinToString { it.name.lowercase() }}")

    // ── Help ─────────────────────────────────────────────────────

    private fun printUsage() {
        println("""
            |reportgen — CSV Report Generator
            |
            |USAGE:
            |  reportgen --input <file> [options]
            |
            |OPTIONS:
            |  -i, --input <file>        Input CSV file (required)
            |  -o, --output <file>       Output file (default: stdout)
            |  -t, --type <type>         Report type: detail, summary, grouped
            |  -f, --format <fmt>        Output format: table, csv, html, json, markdown
            |  -c, --columns <cols>      Columns to include (comma-separated)
            |  -g, --group-by <col>      Group by column
            |  -s, --sort <col>          Sort by column
            |      --desc                Sort descending
            |  -l, --limit <n>           Limit output rows
            |      --filter <expr>       Filter: "amount>1000", "region=West", "name~corp"
            |                            Operators: =, !=, >, <, >=, <=, ~ (contains)
            |                            Repeat --filter for multiple conditions (AND logic)
            |      --agg <expr>          Aggregations: "amount:sum,quantity:avg"
            |                            Functions: sum, avg, min, max, count
            |      --title <text>        Report title
            |  -h, --help               Show this help
            |
            |EXAMPLES:
            |  reportgen -i sales.csv -t detail -s amount --desc -l 20
            |  reportgen -i sales.csv -t grouped -g region --agg "revenue:sum,deals:count" -f html -o report.html
            |  reportgen -i sales.csv --filter "amount>5000" --filter "region=West" -f json
        """.trimMargin())
    }
}

