```kotlin
// src/main/kotlin/reportgen/DataLoader.kt
package reportgen

import java.io.File

object DataLoader {

    fun loadCsv(path: String): DataSet {
        val file = File(path)
        require(file.exists()) { "File not found: $path" }
        require(file.extension.equals("csv", ignoreCase = true)) { "Expected .csv file, got: ${file.extension}" }

        val lines = file.readLines().filter { it.isNotBlank() }
        require(lines.size >= 2) { "CSV file must have a header row and at least one data row" }

        val headers = parseCsvLine(lines.first())

        val records = lines.drop(1).mapIndexed { lineNum, line ->
            val values = parseCsvLine(line)
            if (values.size != headers.size) {
                System.err.println("WARN: Line ${lineNum + 2} has ${values.size} fields (expected ${headers.size}), padding/trimming")
            }
            Record(
                headers.mapIndexed { i, h -> h to values.getOrElse(i) { "" } }.toMap()
            )
        }

        return DataSet(headers, records)
    }

    /**
     * Handles quoted fields with commas and escaped quotes.
     * "John ""JD"" Doe",Sales,1500  →  [John "JD" Doe, Sales, 1500]
     */
    private fun parseCsvLine(line: String): List<String> {
        val fields = mutableListOf<String>()
        val current = StringBuilder()
        var inQuotes = false
        var i = 0

        while (i < line.length) {
            val ch = line[i]
            when {
                ch == '"' && !inQuotes -> inQuotes = true
                ch == '"' && inQuotes -> {
                    // Check for escaped quote ""
                    if (i + 1 < line.length && line[i + 1] == '"') {
                        current.append('"')
                        i++ // skip next quote
                    } else {
                        inQuotes = false
                    }
                }
                ch == ',' && !inQuotes -> {
                    fields.add(current.toString().trim())
                    current.clear()
                }
                else -> current.append(ch)
            }
            i++
        }
        fields.add(current.toString().trim())
        return fields
    }
}
