// src/main/kotlin/reportgen/ReportEngine.kt
package reportgen

import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

class ReportEngine(private val config: ReportConfig) {

    fun generate(dataSet: DataSet): ReportResult = when (config.reportType) {
        ReportType.DETAIL  -> detailReport(dataSet)
        ReportType.SUMMARY -> summaryReport(dataSet)
        ReportType.GROUPED -> groupedReport(dataSet)
    }

    // ── Detail report: filtered/sorted list ──────────────────────

    private fun detailReport(dataSet: DataSet): ReportResult {
        val columns = resolveColumns(dataSet.headers)
        val rows = dataSet.records
            .let(::applyFilters)
            .let(::applySort)
            .let(::applyLimit)
            .map { rec -> columns.map { rec.str(it) } }

        return buildResult(
            title   = config.title ?: "Detail Report",
            headers = columns,
            rows    = rows,
            summary = mapOf("Total rows" to rows.size.toString())
        )
    }

    // ── Summary report: aggregate stats across all data ──────────

    private fun summaryReport(dataSet: DataSet): ReportResult {
        val filtered = applyFilters(dataSet.records)
        val numericCols = dataSet.headers.filter { col ->
            filtered.any { it.num(col) != 0.0 || it.str(col) == "0" }
        }

        // Use explicit aggregations or default to sum/avg/min/max for numeric columns
        val aggs = config.aggregations.ifEmpty {
            numericCols.flatMap { col ->
                listOf(AggFunc.SUM, AggFunc.AVG, AggFunc.MIN, AggFunc.MAX).map { Aggregation(col, it) }
            }
        }

        val headers = listOf("Metric", "Value")
        val rows = buildList {
            add(listOf("Record count", filtered.size.toString()))
            for (agg in aggs) {
                add(listOf(agg.label, formatNumber(agg.compute(filtered))))
            }
        }

        return buildResult(
            title   = config.title ?: "Summary Report",
            headers = headers,
            rows    = rows,
        )
    }

    // ── Grouped report: group-by with aggregations ───────────────

    private fun groupedReport(dataSet: DataSet): ReportResult {
        val groupCol = config.groupBy ?: error("--group-by is required for grouped reports")
        require(groupCol in dataSet.headers) { "Group column '$groupCol' not found. Available: ${dataSet.headers}" }

        val aggs = config.aggregations.ifEmpty {
            // Default: count per group
            listOf(Aggregation(groupCol, AggFunc.COUNT))
        }

        val filtered = applyFilters(dataSet.records)
        val groups = filtered.groupBy { it.str(groupCol) }.toSortedMap()

        val headers = listOf(groupCol) + aggs.map { it.label } + listOf("% of total")
        val totalCount = filtered.size.toDouble()

        var rows = groups.map { (key, records) ->
            val values = aggs.map { formatNumber(it.compute(records)) }
            val pct = if (totalCount > 0) "%.1f%%".format(records.size / totalCount * 100) else "0%"
            listOf(key.ifBlank { "(empty)" }) + values + listOf(pct)
