namespace ConfigLib.Exceptions;

/// <summary>Base exception for all configuration errors.</summary>
public class ConfigurationException : Exception
{
    public string? SourceName { get; }

    public ConfigurationException(string message)
        : base(message) { }

    public ConfigurationException(string message, string sourceName)
        : base(message) => SourceName = sourceName;

    public ConfigurationException(string message, Exception inner)
        : base(message, inner) { }

    public ConfigurationException(string message, string sourceName, Exception inner)
        : base(message, inner) => SourceName = sourceName;
}

/// <summary>Thrown when configuration validation fails.</summary>
public sealed class ConfigurationValidationException : ConfigurationException
{
    public IReadOnlyList<ValidationError> Errors { get; }

    public ConfigurationValidationException(IEnumerable<ValidationError> errors)
        : base(FormatMessage(errors))
    {
        Errors = errors.ToList().AsReadOnly();
    }

    private static string FormatMessage(IEnumerable<ValidationError> errors) =>
        "Configuration validation failed:\n" +
        string.Join("\n", errors.Select(e => $"  - {e.PropertyPath}: {e.Message}"));
}

/// <summary>Thrown when binding flat config to a typed object fails.</summary>
public sealed class ConfigurationBindException : ConfigurationException
{
    public string Key { get; }
    public Type TargetType { get; }

    public ConfigurationBindException(string key, Type targetType, Exception inner)
        : base($"Failed to bind key '{key}' to type '{targetType.Name}'.", inner)
    {
        Key = key;
        TargetType = targetType;
    }
}

