namespace ConfigLib;

/// <summary>Represents a single validation error.</summary>
public sealed class ValidationError
{
    public string PropertyPath { get; }
    public string Message { get; }
    public object? AttemptedValue { get; }

    public ValidationError(string propertyPath, string message, object? attemptedValue = null)
    {
        PropertyPath = propertyPath ?? throw new ArgumentNullException(nameof(propertyPath));
        Message = message ?? throw new ArgumentNullException(nameof(message));
        AttemptedValue = attemptedValue;
    }

    public override string ToString() => $"{PropertyPath}: {Message}";
}

/// <summary>Aggregates validation errors for a configuration object.</summary>
public sealed class ValidationResult
{
    private readonly List<ValidationError> _errors = new();

    public bool IsValid => _errors.Count == 0;
    public IReadOnlyList<ValidationError> Errors => _errors.AsReadOnly();

    public void AddError(string path, string message, object? value = null)
        => _errors.Add(new ValidationError(path, message, value));

    public void Merge(ValidationResult other) => _errors.AddRange(other._errors);

    public void ThrowIfInvalid()
    {
        if (!IsValid)
            throw new ConfigurationValidationException(_errors);
    }
}

