/// <summary>Marks a configuration property as required (non-null/non-empty).</summary>
[AttributeUsage(AttributeTargets.Property)]
public sealed class ConfigRequiredAttribute : Attribute { }

/// <summary>Specifies an inclusive numeric range for a configuration property.</summary>
[AttributeUsage(AttributeTargets.Property)]
public sealed class ConfigRangeAttribute : Attribute
{
    public double Minimum { get; }
    public double Maximum { get; }

    public ConfigRangeAttribute(double minimum, double maximum)
    {
        if (minimum > maximum)
            throw new ArgumentException("Minimum must be <= maximum.");
        Minimum = minimum;
        Maximum = maximum;
    }
}

