namespace ConfigLib;

using System.Reflection;

/// <summary>
/// Validates a typed configuration object using <see cref="ConfigRequiredAttribute"/>
/// and <see cref="ConfigRangeAttribute"/> on its properties.
/// </summary>
public sealed class AttributeValidator<T> : IConfigurationValidator<T>
{
    public ValidationResult Validate(T configuration)
    {
        ArgumentNullException.ThrowIfNull(configuration);
        var result = new ValidationResult();
        ValidateObject(configuration, typeof(T).Name, result);
        return result;
    }

    private static void ValidateObject(object obj, string path, ValidationResult result)
    {
        foreach (var prop in obj.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance))
        {
            var propPath = $"{path}.{prop.Name}";
            var value = prop.GetValue(obj);

            // [ConfigRequired]
            if (prop.GetCustomAttribute<ConfigRequiredAttribute>() is not null)
            {
                if (value is null || (value is string s && string.IsNullOrWhiteSpace(s)))
                {
                    result.AddError(propPath, "Value is required.", value);
                    continue;
                }
            }

            // [ConfigRange]
            if (prop.GetCustomAttribute<ConfigRangeAttribute>() is { } range && value is not null)
            {
                var numeric = Convert.ToDouble(value);
                if (numeric < range.Minimum || numeric > range.Maximum)
                {
                    result.AddError(propPath,
                        $"Value {numeric} is outside allowed range [{range.Minimum}, {range.Maximum}].",
                        value);
                }
            }

            // Recurse into nested complex objects (not primitives, strings, or collections)
            if (value is not null && !IsTerminalType(prop.PropertyType))
            {
                ValidateObject(value, propPath, result);
            }
        }
    }

    private static bool IsTerminalType(Type t)
    {
        t = Nullable.GetUnderlyingType(t) ?? t;
        return t.IsPrimitive || t == typeof(string) || t == typeof(decimal)
            || t == typeof(DateTime) || t == typeof(TimeSpan) || t == typeof(Guid)
            || t.IsEnum || typeof(IEnumerable).IsAssignableFrom(t);
    }
}

