namespace ConfigLib.Sources;

using System.Text.Json;
using ConfigLib.Exceptions;

/// <summary>Loads configuration from a JSON file, flattening nested keys with ':' separators.</summary>
public sealed class JsonFileSource : IConfigurationSource
{
    private readonly string _filePath;

    public string Name => $"JsonFile({_filePath})";
    public int Priority { get; }
    public bool Optional { get; }

    public JsonFileSource(string filePath, int priority = 0, bool optional = false)
    {
        _filePath = Path.GetFullPath(filePath ?? throw new ArgumentNullException(nameof(filePath)));
        Priority = priority;
        Optional = optional;
    }

    internal string FilePath => _filePath;

    public IDictionary<string, string?> Load()
    {
        if (!File.Exists(_filePath))
        {
            if (Optional)
                return new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
            throw new ConfigurationException(
                $"Required configuration file not found: {_filePath}", Name);
        }

        try
        {
            var json = File.ReadAllText(_filePath);
            using var doc = JsonDocument.Parse(json, new JsonDocumentOptions
            {
                CommentHandling = JsonCommentHandling.Skip,
                AllowTrailingCommas = true
            });

            var result = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
            Flatten(doc.RootElement, prefix: "", result);
            return result;
        }
        catch (JsonException ex)
        {
            throw new ConfigurationException(
                $"Invalid JSON in configuration file: {_filePath}", Name, ex);
        }
    }

    private static void Flatten(JsonElement element, string prefix, Dictionary<string, string?> output)
    {
        switch (element.ValueKind)
        {
            case JsonValueKind.Object:
                foreach (var prop in element.EnumerateObject())
                {
                    var key = string.IsNullOrEmpty(prefix) ? prop.Name : $"{prefix}:{prop.Name}";
                    Flatten(prop.Value, key, output);
                }
                break;

            case JsonValueKind.Array:
                var idx = 0;
                foreach (var item in element.EnumerateArray())
                {
                    Flatten(item, $"{prefix}:{idx++}", output);
                }
                break;

            case JsonValueKind.Null:
                output[prefix] = null;
                break;

            default:
                output[prefix] = element.ToString();
                break;
        }
    }
}

