namespace ConfigLib.Sources;

using System.Collections;

/// <summary>
/// Loads configuration from environment variables.
/// Filters by <paramref name="prefix"/> and replaces <paramref name="separator"/> with ':'.
/// </summary>
public sealed class EnvironmentVariableSource : IConfigurationSource
{
    private readonly string _prefix;
    private readonly string _separator;

    public string Name => $"Env({_prefix}*)";
    public int Priority { get; }

    public EnvironmentVariableSource(string prefix = "", int priority = 100, string separator = "__")
    {
        _prefix = prefix ?? "";
        _separator = separator ?? "__";
        Priority = priority;
    }

    public IDictionary<string, string?> Load()
    {
        var result = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

        foreach (DictionaryEntry entry in Environment.GetEnvironmentVariables())
        {
            if (entry.Key is not string rawKey) continue;

            if (_prefix.Length > 0)
            {
                if (!rawKey.StartsWith(_prefix, StringComparison.OrdinalIgnoreCase))
                    continue;
                rawKey = rawKey[_prefix.Length..];
            }

            var normalizedKey = rawKey.Replace(_separator, ":");
            result[normalizedKey] = entry.Value?.ToString();
        }

        return result;
    }
}

