namespace ConfigLib.Sources;

/// <summary>
/// Parses command-line arguments into configuration key-value pairs.
/// Supports: --key=value, --key value, and --flag (boolean true).
/// </summary>
public sealed class CommandLineSource : IConfigurationSource
{
    private readonly string[] _args;

    public string Name => "CommandLine";
    public int Priority { get; }

    public CommandLineSource(string[] args, int priority = 200)
    {
        _args = args ?? throw new ArgumentNullException(nameof(args));
        Priority = priority;
    }

    public IDictionary<string, string?> Load()
    {
        var result = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

        for (var i = 0; i < _args.Length; i++)
        {
            var arg = _args[i];
            if (!arg.StartsWith("--")) continue;

            var body = arg[2..];
            var eqIdx = body.IndexOf('=');

            if (eqIdx >= 0)
            {
                // --key=value
                var key = NormalizeKey(body[..eqIdx]);
                result[key] = body[(eqIdx + 1)..];
            }
            else if (i + 1 < _args.Length && !_args[i + 1].StartsWith("--"))
            {
                // --key value
                result[NormalizeKey(body)] = _args[++i];
            }
            else
            {
                // --flag (boolean)
                result[NormalizeKey(body)] = "true";
            }
        }

        return result;
    }

    private static string NormalizeKey(string key) => key.Replace('-', ':');
}

