```csharp
// IO/DataReader.cs
using System.Globalization;
using System.Text;
using System.Text.Json;
using ReportGen.Models;

namespace ReportGen.IO;

public static class DataReader
{
    public static ReportData Read(string path)
    {
        if (!File.Exists(path))
            throw new FileNotFoundException($"Input file not found: {path}");

        return Path.GetExtension(path).ToLowerInvariant() switch
        {
            ".csv"  => ReadCsv(path),
            ".tsv"  => ReadCsv(path, '\t'),
            ".json" => ReadJson(path),
            var ext => throw new NotSupportedException($"Unsupported format: {ext}")
        };
    }

    // ── CSV ────────────────────────────────────────────────
    private static ReportData ReadCsv(string path, char delimiter = ',')
    {
        var data  = new ReportData();
        var lines = File.ReadAllLines(path);

        if (lines.Length == 0) return data;

        var headers = ParseCsvLine(lines[0], delimiter);
        data.Columns.AddRange(headers);

        for (int i = 1; i < lines.Length; i++)
        {
            var line = lines[i];
            if (string.IsNullOrWhiteSpace(line)) continue;

            var fields = ParseCsvLine(line, delimiter);
            var row    = new Dictionary<string, object?>();

            for (int j = 0; j < headers.Count; j++)
                row[headers[j]] = j < fields.Count ? InferType(fields[j]) : null;

            data.Rows.Add(row);
        }

        return data;
    }

    private static List<string> ParseCsvLine(string line, char delimiter)
    {
        var fields   = new List<string>();
        var current  = new StringBuilder();
        bool inQuote = false;

        for (int i = 0; i < line.Length; i++)
        {
            char c = line[i];

            if (c == '"')
            {
                if (inQuote && i + 1 < line.Length && line[i + 1] == '"')
                {
                    current.Append('"');
                    i++;
                }
                else inQuote = !inQuote;
            }
            else if (c == delimiter && !inQuote)
            {
                fields.Add(current.ToString().Trim());
                current.Clear();
            }
            else current.Append(c);
        }

        fields.Add(current.ToString().Trim());
        return fields;
    }

    // ── JSON ───────────────────────────────────────────────
    private static ReportData ReadJson(string path)
    {
        var data = new ReportData();
        using var doc = JsonDocument.Parse(File.ReadAllText(path));

        if (doc.RootElement.ValueKind != JsonValueKind.Array)
            throw new FormatException("JSON input must be an array of objects.");

        var seenColumns = new HashSet<string>();

        foreach (var element in doc.RootElement.EnumerateArray())
        {
            if (element.ValueKind != JsonValueKind.Object) continue;
            var row = new Dictionary<string, object?>();

            foreach (var prop in element.EnumerateObject())
            {
                if (seenColumns.Add(prop.Name))
                    data.Columns.Add(prop.Name);

                row[prop.Name] = prop.Value.ValueKind switch
                {
                    JsonValueKind.Number when prop.Value.TryGetInt64(out long l)
                        && l is >= int.MinValue and <= int.MaxValue => (int)l,
                    JsonValueKind.Number   => prop.Value.GetDouble(),
                    JsonValueKind.True     => true,
                    JsonValueKind.False    => false,
                    JsonValueKind.Null     => null,
                    _                      => prop.Value.GetString()
                };
            }

            data.Rows.Add(row);
        }

        return data;
    }

    // ── Type inference ─────────────────────────────────────
    private static object? InferType(string value)
    {
        if (string.IsNullOrWhiteSpace(value)) return null;
        if (int.TryParse(value, NumberStyles.Any, CultureInfo.InvariantCulture, out int i))    return i;
        if (double.TryParse(value, NumberStyles.Any, CultureInfo.InvariantCulture, out double d)) return d;
        if (DateTime.TryParse(value, CultureInfo.InvariantCulture, DateTimeStyles.None, out var dt)) return dt;
        if (bool.TryParse(value, out bool b)) return b;
        return value;
    }
}
