## Report Engine (filter, group, aggregate, sort)

```csharp
// Engine/ReportEngine.cs
using System.Globalization;
using ReportGen.Models;

namespace ReportGen.Engine;

public static class ReportEngine
{
    public static ReportData Process(ReportData input, ReportConfig config)
    {
        var data = input;

        if (config.Where.Length > 0)
            data = ApplyFilters(data, config.Where);

        if (config.GroupBy.Length > 0 || config.Aggregate.Length > 0)
            data = ApplyGrouping(data, config.GroupBy, config.Aggregate);

        if (config.Select.Length > 0)
            data = ApplySelect(data, config.Select);

        if (config.Sort is not null)
            data = ApplySort(data, config.Sort);

        if (config.Limit.HasValue)
        {
            var limited = Clone(data);
            limited.Rows.Clear();
            limited.Rows.AddRange(data.Rows.Take(config.Limit.Value));
            data = limited;
        }

        data.Title = config.Title;
        data.GeneratedAt = DateTime.Now;

        // Record what was applied
        if (config.Where.Length > 0)
            data.Metadata["Filters"] = string.Join(" AND ", config.Where);
        if (config.GroupBy.Length > 0)
            data.Metadata["Grouped By"] = string.Join(", ", config.GroupBy);
        if (config.Sort is not null)
            data.Metadata["Sorted By"] = config.Sort;

        return data;
    }

    // ── Filtering ──────────────────────────────────────────
    private static ReportData ApplyFilters(ReportData data, string[] filters)
    {
        var conditions = filters.Select(ParseFilter).ToList();
        var result = Clone(data);
        result.Rows.Clear();

        foreach (var row in data.Rows)
        {
            if (conditions.All(c => Evaluate(c, row)))
                result.Rows.Add(new Dictionary<string, object?>(row));
        }

        return result;
    }

    private static FilterCondition ParseFilter(string expr)
    {
        // Supported: >=  <=  !=  =  >  <  contains  starts-with  ends-with
        string[] ops = [">=", "<=", "!=", "=", ">", "<", "contains", "starts-with", "ends-with"];

        foreach (var op in ops)
        {
            int idx = expr.IndexOf($" {op} ", StringComparison.OrdinalIgnoreCase);
            if (idx < 0) continue;

            string field = expr[..idx].Trim();
            string value = expr[(idx + op.Length + 2)..].Trim().Trim('"', '\'');
            return new FilterCondition(field, op.ToLowerInvariant(), value);
        }

        throw new FormatException(
            $"Cannot parse filter: '{expr}'. Expected format: 'Column operator Value'");
    }

    private static bool Evaluate(FilterCondition cond, Dictionary<string, object?> row)
    {
        if (!row.TryGetValue(cond.Field, out var cell) || cell is null) return false;

        string cellStr = cell.ToString()!;

        return cond.Op switch
        {
            "="  or "==" => Compare(cell, cond.Value) == 0,
            "!="         => Compare(cell, cond.Value) != 0,
            ">"          => Compare(cell, cond.Value) > 0,
            "<"          => Compare(cell, cond.Value) < 0,
            ">="         => Compare(cell, cond.Value) >= 0,
            "<="         => Compare(cell, cond.Value) <= 0,
            "contains"   => cellStr.Contains(cond.Value, StringComparison.OrdinalIgnoreCase),
            "starts-with"=> cellStr.StartsWith(cond.Value, StringComparison.OrdinalIgnoreCase),
            "ends-with"  => cellStr.EndsWith(cond.Value, StringComparison.OrdinalIgnoreCase),
            _            => throw new InvalidOperationException($"Unknown operator: {cond.Op}")
        };
    }

    private static int Compare(object cell, string filterVal)
    {
        if (cell is int i    && int.TryParse(filterVal, NumberStyles.Any, CultureInfo.InvariantCulture, out int fi))
            return i.CompareTo(fi);
        if (cell is double d && double.TryParse(filterVal, NumberStyles.Any, CultureInfo.InvariantCulture, out double fd))
            return d.CompareTo(fd);
        if (cell is DateTime dt && DateTime.TryParse(filterVal, CultureInfo.InvariantCulture, DateTimeStyles.None, out var fdt))
            return dt.CompareTo(fdt);
        return string.Compare(cell.ToString(), filterVal, StringComparison.OrdinalIgnoreCase);
    }

    // ── Grouping / Aggregation ─────────────────────────────
    private static ReportData ApplyGrouping(ReportData data, string[] groupBy, string[] aggregates)
    {
        var aggOps = aggregates.Select(ParseAggregate).ToList();

        // No group-by → aggregate over entire dataset
        if (groupBy.Length == 0)
        {
            var result = new ReportData();
            var summaryRow = new Dictionary<string, object?>();

            foreach (var op in aggOps)
            {
                string colName = op.Field == "*" ? op.Function : $"{op.Function}_{op.Field}";
                result.Columns.Add(colName);
                summaryRow[colName] = ComputeAggregate(op, data.Rows);
            }

            result.Rows.Add(summaryRow);
            return result;
        }

        // Group rows by key columns
        var groups = data.Rows
            .GroupBy(row => string.Join("|||",
                groupBy.Select(g => row.GetValueOrDefault(g)?.ToString() ?? "")))
            .ToList();

        var output = new ReportData();
        output.Columns.AddRange(groupBy);
        foreach (var op in aggOps)
        {
            string colName = op.Field == "*" ? op.Function : $"{op.Function}_{op.Field}";
            output.Columns.Add(colName);
        }

        foreach (var group in groups)
        {
            var rows    = group.ToList();
            var first   = rows[0];
            var outRow  = new Dictionary<string, object?>();

            foreach (string col in groupBy)
                outRow[col] = first.GetValueOrDefault(col);

            foreach (var op in aggOps)
            {
                string colName = op.Field == "*" ? op.Function : $"{op.Function}_{op.Field}";
                outRow[colName] = ComputeAggregate(op, rows);
            }

            output.Rows.Add(outRow);
        }

        return output;
    }

    private static AggregateOp ParseAggregate(string expr)
    {
        // Format: function:field  e.g. sum:Revenue, count:*, avg:Price
        int colon = expr.IndexOf(':');
        if (colon < 0)
            throw new FormatException($"Invalid aggregate: '{expr}'. Expected 'func:field'.");

        return new AggregateOp(
            expr[..colon].Trim().ToLowerInvariant(),
            expr[(colon + 1)..].Trim());
    }

    private static object? ComputeAggregate(AggregateOp op, List<Dictionary<string, object?>> rows)
    {
        if (op.Function == "count")
            return op.Field == "*" ? rows.Count : rows.Count(r => r.GetValueOrDefault(op.Field) is not null);

        var values = rows
            .Select(r => ToDouble(r.GetValueOrDefault(op.Field)))
            .Where(v => v.HasValue)
            .Select(v => v!.Value)
            .ToList();

        if (values.Count == 0) return null;

        return op.Function switch
        {
            "sum" => Math.Round(values.Sum(), 2),
            "avg" => Math.Round(values.Average(), 2),
            "min" => values.Min(),
            "max" => values.Max(),
            _     => throw new InvalidOperationException($"Unknown aggregate: {op.Function}")
        };
    }

    // ── Select ─────────────────────────────────────────────
    private static ReportData ApplySelect(ReportData data, string[] columns)
    {
        var valid  = columns.Where(c => data.Columns.Contains(c)).ToList();
        var result = new ReportData();
        result.Columns.AddRange(valid);

        foreach (var row in data.Rows)
        {
            var newRow = new Dictionary<string, object?>();
            foreach (string col in valid)
                newRow[col] = row.GetValueOrDefault(col);
            result.Rows.Add(newRow);
        }

        return result;
    }

    // ── Sort ───────────────────────────────────────────────
    private static ReportData ApplySort(ReportData data, string sortExpr)
    {
        bool descending = sortExpr.StartsWith('-');
        string column   = descending ? sortExpr[1..] : sortExpr.TrimStart('+');

        if (!data.Columns.Contains(column))
            throw new ArgumentException($"Sort column not found: {column}");

        var result = Clone(data);
        result.Rows.Sort((a, b) =>
        {
            var va = a.GetValueOrDefault(column);
            var vb = b.GetValueOrDefault(column);
            int cmp = CompareObjects(va, vb);
            return descending ? -cmp : cmp;
        });

        return result;
    }

    private static int CompareObjects(object? a, object? b)
    {
        if (a is null && b is null) return 0;
        if (a is null) return -1;
        if (b is null) return 1;
        if (a is IComparable ca) return ca.CompareTo(b);
        return string.Compare(a.ToString(), b.ToString(), StringComparison.Ordinal);
    }

    // ── Helpers ────────────────────────────────────────────
    private static double? ToDouble(object? val) => val switch
    {
        int i    => i,
        long l   => l,
        float f  => f,
        double d => d,
        decimal m=> (double)m,
        string s when double.TryParse(s, NumberStyles.Any, CultureInfo.InvariantCulture, out var d) => d,
        _        => null
    };

    private static ReportData Clone(ReportData src)
    {
        var copy = new ReportData { Title = src.Title, GeneratedAt = src.GeneratedAt };
        copy.Columns.AddRange(src.Columns);
        copy.Rows.AddRange(src.Rows.Select(r => new Dictionary<string, object?>(r)));
        foreach (var kv in src.Metadata) copy.Metadata[kv.Key] = kv.Value;
        return copy;
    }
}
